function weirdAlgorithm(n) {
    let result = n;
    // continue the process until result becomes 1
    while (result !== 1) {
        // if result is even, divide it by 2
        if (result % 2 === 0) {
            result = result / 2;
        } 
        // if result is odd, multiply it by 3 and add 1
        else {
            result = result * 3 + 1;
        }
    }
    return result;
}

function missingNumber(nums) {
    let n = nums.length;
    let expectedSum = ((n + 1) * (n + 2)) / 2; // calculate the sum of numbers from 0 to n
    let actualSum = 0;
    for (let i = 0; i < n; i++) {
        actualSum += nums[i]; // sum up the numbers in the array
    }
    return expectedSum - actualSum; // return the difference between expected and actual sum
}

function numberSpiral(y, x) {
    if (y > x) {
        let ans = (y - 1) * (y - 1);
        return y % 2 !== 0 ? ans + x : ans + 2 * y - x;
    } else {
        let ans = (x - 1) * (x - 1);
        return x % 2 === 0 ? ans + y : ans + 2 * x - y;
    }
}

function josephusOrder(n) {
    const people = [];
    for (let i = 1; i <= n; i++) people.push(i);
    const order = [];
    let idx = 0;
    while (people.length > 0) {
        idx = (idx + 1) % people.length;
        order.push(people[idx]);
        people.splice(idx, 1);
        if (idx === people.length) idx = 0;
    }
    return order;
}

function findDistinctNumbers(nums) {
    // sort the array to group duplicate numbers together
    nums.sort((a, b) => a - b);
    let distinctCount = 0;
    // iterate through the sorted array and count distinct numbers
    for (let i = 0; i < nums.length; i++) {
        if (i === 0 || nums[i] !== nums[i - 1]) {
            distinctCount++;
        }
    }
    return distinctCount;
}

function apartments(k, a, b) {
    a.sort((x, y) => x - y);
    b.sort((x, y) => x - y);
    let i = 0, j = 0, count = 0;
    while (i < a.length && j < b.length) {
        if (Math.abs(a[i] - b[j]) <= k) {
            i++; j++; count++;
        } else if (a[i] < b[j]) {
            i++;
        } else {
            j++;
        }
    }
    return count;
}

function ferrisWheel(people, limit) {
    people.sort((a, b) => a - b); // sort people by weight in ascending order
    let left = 0, right = people.length - 1; // initialize two pointers
    let count = 0; // count the number of boats
    while (left <= right) { // loop until all people are on a boat
        if (people[left] + people[right] <= limit) { // check if the heaviest and lightest person can be on the same boat
            left++; // move the lightest person to the next boat
        }
        right--; // move the heaviest person to the current boat
        count++; // increment the boat count
    }
    return count; // return the minimum number of boats needed
}

function concertTickets(prices, payments) {
    const sorted = [...prices].sort((a, b) => a - b);
    const result = [];
    for (const pay of payments) {
        // binary search for the rightmost price <= pay
        let lo = 0, hi = sorted.length - 1, idx = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (sorted[mid] <= pay) { idx = mid; lo = mid + 1; }
            else hi = mid - 1;
        }
        if (idx === -1) {
            result.push(-1);
        } else {
            result.push(sorted[idx]);
            sorted.splice(idx, 1);
        }
    }
    return result;
}

function restaurantCustomers(arrivals, departures) {
    arrivals.sort((a, b) => a - b); // sort the arrival times
    departures.sort((a, b) => a - b); // sort the departure times
    let i = 0, j = 0, currentCustomers = 0, maxCustomers = 0; 
    while (i < arrivals.length && j < departures.length) { 
        // if the next arrival is before the next departure, increment the current customers
        if (arrivals[i] <= departures[j]) {
            currentCustomers++;
            i++;
        } 
        // if the next departure is before the next arrival, decrement the current customers
        else {
            currentCustomers--;
            j++;
        }
        // update the maximum customers
        maxCustomers = Math.max(maxCustomers, currentCustomers);
    }
    return maxCustomers;
}

function diceCombinations(dice, target) {
    // number of ways to reach each sum using any number of throws (1..dice per throw)
    let dp = new Array(target + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= target; i++) {
        for (let j = 1; j <= Math.min(i, dice); j++) {
            dp[i] = (dp[i] + dp[i - j]) % 1000000007;
        }
    }
    return dp[target];
}

function minimizingCoins(coins, amount) {
    let dp = new Array(amount + 1).fill(Infinity);
    dp[0] = 0; 
    for (let coin of coins) // iterate over each coin denomination
        for (let i = coin; i <= amount; i++) // for each amount from coin to target amount
            dp[i] = Math.min(dp[i], dp[i - coin] + 1); // update dp array with minimum coins needed
    return dp[amount] !== Infinity ? dp[amount] : -1; // return minimum coins needed or -1 if not possible
}

function coinChange(coins, amount) {
    let dp = new Array(amount + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= amount; i++) {
        for (const coin of coins) {
            if (coin <= i) {
                dp[i] = (dp[i] + dp[i - coin]) % 1000000007;
            }
        }
    }
    return dp[amount];
}

function coinChange(amount, coins) {
    let combinations = new Array(amount + 1).fill(0);
    combinations[0] = 1; // base case: there is one way to make 0 amount
    for (let coin of coins) {
        for (let i = coin; i <= amount; i++) {
            // update combinations by adding the number of ways to make the remaining amount
            combinations[i] = (combinations[i] + combinations[i - coin]) % 1000000007;
        }
    }
    return combinations[amount];
}

function removingDigits(n) {
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        let temp = i;
        while (temp > 0) {
            const d = temp % 10;
            if (d > 0) dp[i] = Math.min(dp[i], dp[i - d] + 1);
            temp = Math.floor(temp / 10);
        }
    }
    return dp[n];
}

function bookShop(prices, pages, budget) {
    let n = prices.length;
    let dp = new Array(n + 1).fill(0).map(() => new Array(budget + 1).fill(0));
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= budget; j++) {
            // if current book's price exceeds the current budget, skip it
            if (prices[i - 1] > j) {
                dp[i][j] = dp[i - 1][j];
            } else {
                // choose the maximum between including and excluding the current book
                dp[i][j] = Math.max(dp[i - 1][j], dp[i - 1][j - prices[i - 1]] + pages[i - 1]);
            }
        }
    }
    return dp[n][budget];
}

function countRooms(grid) {
    let rooms = 0;
    let visited = new Array(grid.length).fill(0).map(() => new Array(grid[0].length).fill(false));
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            if (!visited[i][j] && grid[i][j] === 0) {
                // perform DFS to mark all connected cells as visited
                dfs(grid, visited, i, j);
                rooms++;
            }
        }
    }
    return rooms;
}

function dfs(grid, visited, i, j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i][j] || grid[i][j] === 1) {
        return;
    }
    visited[i][j] = true;
    // recursively visit all neighboring cells
    dfs(grid, visited, i - 1, j);
    dfs(grid, visited, i + 1, j);
    dfs(grid, visited, i, j - 1);
    dfs(grid, visited, i, j + 1);
}

function buildingRoads(n, connections) {
    let parent = new Array(n).fill(0).map((val, index) => index);
    let rank = new Array(n).fill(0);

    function find(x) {
        // if the current node is not the parent, recursively find its parent
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }

    function union(x, y) {
        // find the parents of x and y
        let rootX = find(x);
        let rootY = find(y);

        // if they are already in the same set, do nothing
        if (rootX === rootY) return;

        // otherwise, merge the sets by making one parent the other
        if (rank[rootX] > rank[rootY]) parent[rootY] = rootX;
        else if (rank[rootX] < rank[rootY]) parent[rootX] = rootY;
        else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    for (let i = 0; i < connections.length; i++) {
        let cityA = connections[i][0];
        let cityB = connections[i][1];
        if (find(cityA) !== find(cityB)) {
            union(cityA, cityB);
        }
    }
    let roots = new Set();
    for (let i = 0; i < n; i++) roots.add(find(i));
    return roots.size - 1;   // new roads needed = (components - 1), not the count of useful given edges
}

