function messageRoute(graph, start, end) {
    let visited = new Set();
    let queue = [[start]];
    // while there are still paths to explore in the queue
    while (queue.length > 0) {
        let path = queue.shift();
        let node = path[path.length - 1];
        // if we've reached the end node, return the path
        if (node === end) return path;
        // if we haven't visited this node before, mark it as visited and add its neighbors to the queue
        if (!visited.has(node)) {
            visited.add(node);
            // for each neighbor of the current node
            for (let neighbor of graph[node]) {
                // create a new path by appending the neighbor to the current path
                let newPath = [...path, neighbor];
                queue.push(newPath);
            }
        }
    }
    // if we've explored all paths and haven't found the end node, return null
    return null;
}

function buildTeams(n, edges) {
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }
    const team = new Array(n).fill(0);
    for (let start = 0; start < n; start++) {
        if (team[start] !== 0) continue;
        team[start] = 1;
        const queue = [start];
        while (queue.length) {
            const node = queue.shift();
            for (const nb of graph[node]) {
                if (team[nb] === 0) {
                    team[nb] = team[node] === 1 ? 2 : 1;
                    queue.push(nb);
                } else if (team[nb] === team[node]) {
                    return null; // IMPOSSIBLE
                }
            }
        }
    }
    return team;
}

function investigation(n, edges) {
    const MOD = 1000000007;
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b, c] of edges) graph[a].push([b, c]);
    const dist = new Array(n).fill(Infinity);
    const ways = new Array(n).fill(0);
    const minF = new Array(n).fill(Infinity);
    const maxF = new Array(n).fill(-Infinity);
    dist[0] = 0; ways[0] = 1; minF[0] = 0; maxF[0] = 0;
    const pq = [[0, 0]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (d > dist[u]) continue;
        for (const [v, w] of graph[u]) {
            const nd = dist[u] + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                ways[v] = ways[u];
                minF[v] = minF[u] + 1;
                maxF[v] = maxF[u] + 1;
                pq.push([nd, v]);
            } else if (nd === dist[v]) {
                ways[v] = (ways[v] + ways[u]) % MOD;
                minF[v] = Math.min(minF[v], minF[u] + 1);
                maxF[v] = Math.max(maxF[v], maxF[u] + 1);
            }
        }
    }
    return [dist[n-1], ways[n-1], minF[n-1], maxF[n-1]];
}

function shortestRoutes(graph, start) {
    const distances = new Array(graph.length).fill(Infinity);
    distances[start] = 0;
    const queue = [start];
    while (queue.length > 0) {
        const currentNode = queue.shift();
        // iterate over all neighbors of the current node and update their distances if a shorter path is found
        for (let i = 0; i < graph.length; i++) {
            if (graph[currentNode][i] !== 0 && distances[currentNode] + graph[currentNode][i] < distances[i]) {
                distances[i] = distances[currentNode] + graph[currentNode][i];
                queue.push(i);
            }
        }
    }
    return distances;
}

function shortestRoutes(n, edges, src, dest) {
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
        graph[v].push([u, w]); // assuming undirected graph
    }
    const distance = Array(n).fill(Infinity);
    distance[src] = 0;
    const pq = [[src, 0]];
    while (pq.length) {
        const [currentNode, currentDistance] = pq.shift();
        // if current distance is greater than already found distance, skip this node
        if (currentDistance > distance[currentNode]) continue;
        for (const [neighbor, weight] of graph[currentNode]) {
            // calculate new distance and update if it's shorter
            const newDistance = currentDistance + weight;
            if (newDistance < distance[neighbor]) {
                distance[neighbor] = newDistance;
                pq.push([neighbor, newDistance]);
                // sort pq to maintain heap property
                pq.sort((a, b) => a[1] - b[1]);
            }
        }
    }
    return distance[dest] === Infinity ? -1 : distance[dest];
}

function treeMatching(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
    const order = [];
    const parent = new Array(n).fill(-1);
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const node = stack.pop();
        order.push(node);
        for (const nb of adj[node]) {
            if (!visited[nb]) {
                visited[nb] = true;
                parent[nb] = node;
                stack.push(nb);
            }
        }
    }
    const matched = new Array(n).fill(false);
    let count = 0;
    for (let i = order.length - 1; i >= 0; i--) {
        const node = order[i];
        const p = parent[node];
        if (p !== -1 && !matched[node] && !matched[p]) {
            matched[node] = true;
            matched[p] = true;
            count++;
        }
    }
    return count;
}

function treeDistances(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
    function bfs(src) {
        const dist = new Array(n).fill(-1);
        dist[src] = 0;
        const queue = [src];
        let qi = 0;
        while (qi < queue.length) {
            const node = queue[qi++];
            for (const nb of adj[node]) {
                if (dist[nb] === -1) {
                    dist[nb] = dist[node] + 1;
                    queue.push(nb);
                }
            }
        }
        return dist;
    }
    const d0 = bfs(0);
    let a = 0;
    for (let i = 0; i < n; i++) if (d0[i] > d0[a]) a = i;
    const dA = bfs(a);
    let b = 0;
    for (let i = 0; i < n; i++) if (dA[i] > dA[b]) b = i;
    const dB = bfs(b);
    const result = new Array(n);
    for (let i = 0; i < n; i++) result[i] = Math.max(dA[i], dB[i]);
    return result;
}

function wordCombinations(s, words) {
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    for (let i = 1; i <= n; i++) {
        for (const w of words) {
            const L = w.length;
            if (L <= i && s.slice(i - L, i) === w) {
                dp[i] = (dp[i] + dp[i - L]) % 1000000007;
            }
        }
    }
    return dp[n];
}

function stringMatching(text, pattern) {
    let patternLength = pattern.length;
    let textLength = text.length;
    let matchCount = 0;
    // Loop through the text to find all occurrences of the pattern
    for (let i = 0; i <= textLength - patternLength; i++) {
        let match = true;
        // Check each character of the pattern against the corresponding character in the text
        for (let j = 0; j < patternLength; j++) {
            if (text[i + j] !== pattern[j]) {
                match = false;
                break;
            }
        }
        // If the pattern matches, increment the match count
        if (match) {
            matchCount++;
        }
    }
    return matchCount;
}

function findBorders(s) {
    let borders = new Array(s.length).fill(0);
    let maxLength = 0;
    // iterate over the string to fill the borders array
    for (let i = 1; i < s.length; i++) {
        let j = maxLength;
        // adjust the maxLength until we find a match or reach the start of the string
        while (j > 0 && s[i] !== s[j]) j = borders[j - 1];
        // if we found a match, update maxLength
        if (s[i] === s[j]) maxLength = j + 1;
        borders[i] = maxLength;
    }
    return borders;
}

function twoSum(nums, target) {
  var numToIndex = {};
  for (var i = 0; i < nums.length; i++) {
    // calculate the complement of the current number with respect to the target
    var complement = target - nums[i];
    // check if the complement is already in the hash table
    if (complement in numToIndex) {
      // if it is, return the indices of the current number and its complement
      return [numToIndex[complement], i];
    }
    // if not, add the current number and its index to the hash table
    numToIndex[nums[i]] = i;
  }
}

function addTwoNumbers(l1, l2) {
    let dummyHead = new ListNode(0);
    let current = dummyHead;
    let carry = 0;
    // Traverse both linked lists and add corresponding nodes
    while (l1 !== null || l2 !== null) {
        let x = (l1 !== null) ? l1.val : 0;
        let y = (l2 !== null) ? l2.val : 0;
        let sum = carry + x + y;
        // Update carry for next iteration
        carry = Math.floor(sum / 10);
        current.next = new ListNode(sum % 10);
        current = current.next;
        if (l1 !== null) l1 = l1.next;
        if (l2 !== null) l2 = l2.next;
    }
    // Handle remaining carry
    if (carry > 0) {
        current.next = new ListNode(carry);
    }
    return dummyHead.next;
}

