function lengthOfLongestSubstring(s) {
    let maxLength = 0;
    let left = 0;
    let charIndexMap = {};
    for (let right = 0; right < s.length; right++) {
        // if the character is already in the map, move the left pointer to the right of the previous occurrence
        if (s[right] in charIndexMap && charIndexMap[s[right]] >= left) {
            left = charIndexMap[s[right]] + 1;
        }
        // update the character index in the map
        charIndexMap[s[right]] = right;
        // update the maximum length
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

function findMedianSortedArrays(nums1, nums2) {
    // ensure that nums1 is the smaller array to simplify the logic
    if (nums1.length > nums2.length) return findMedianSortedArrays(nums2, nums1);
    let x = nums1.length, y = nums2.length;
    let start = 0, end = x;
    while (start <= end) {
        // calculate the partition point for nums1
        let partitionX = Math.floor((start + end) / 2);
        // calculate the partition point for nums2
        let partitionY = Math.floor((x + y + 1) / 2) - partitionX;
        // calculate the values at the partition points
        let maxLeftX = partitionX === 0 ? -Infinity : nums1[partitionX - 1];
        let minRightX = partitionX === x ? Infinity : nums1[partitionX];
        let maxLeftY = partitionY === 0 ? -Infinity : nums2[partitionY - 1];
        let minRightY = partitionY === y ? Infinity : nums2[partitionY];
        // check if the partition is correct
        if (maxLeftX <= minRightY && maxLeftY <= minRightX) {
            // calculate the median
            if ((x + y) % 2 === 0) return (Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY)) / 2;
            else return Math.max(maxLeftX, maxLeftY);
        } 
        // adjust the partition point
        else if (maxLeftX > minRightY) end = partitionX - 1;
        else start = partitionX + 1;
    }
}

