function longestPalindromicSubstring(s) {
    function expandAroundCenter(left, right) {
        while (left >= 0 && right < s.length && s[left] === s[right]) {
            // expand the window as long as the characters match
            left--;
            right++;
        }
        return s.slice(left + 1, right);
    }

    let longestPalindrome = '';
    for (let i = 0; i < s.length; i++) {
        // consider odd-length palindromes
        let palindrome = expandAroundCenter(i, i);
        if (palindrome.length > longestPalindrome.length) {
            longestPalindrome = palindrome;
        }
        // consider even-length palindromes
        palindrome = expandAroundCenter(i, i + 1);
        if (palindrome.length > longestPalindrome.length) {
            longestPalindrome = palindrome;
        }
    }
    return longestPalindrome;
}

function convert(s, numRows) {
    if (numRows === 1) return s;
    let result = '';
    let rows = new Array(numRows).fill('');
    let index = 0;
    let step = 1;
    // iterate over the string and fill the rows array
    for (let i = 0; i < s.length; i++) {
        rows[index] += s[i];
        // if we are at the first or last row, change the direction
        if (index === 0) step = 1;
        if (index === numRows - 1) step = -1;
        index += step;
    }
    // concatenate all the rows to form the result
    for (let row of rows) result += row;
    return result;
}

function reverse(x) {
  let isNegative = x < 0;
  x = Math.abs(x);
  let reversed = 0;
  // continuously take the last digit of x and append it to reversed
  while (x > 0) {
    let digit = x % 10;
    x = Math.floor(x / 10);
    // check for potential overflow before appending the new digit
    if (reversed > (Math.pow(2, 31) - 1 - digit) / 10) return 0;
    reversed = reversed * 10 + digit;
  }
  // restore the original sign
  return isNegative ? -reversed : reversed;
}

function myAtoi(s) {
    let result = 0, sign = 1, index = 0;
    // check for leading whitespace and move index forward
    while (index < s.length && s[index] === ' ') index++;
    // check for sign and update sign variable
    if (index < s.length && (s[index] === '-' || s[index] === '+')) {
        sign = s[index] === '-' ? -1 : 1;
        index++;
    }
    // iterate over the string and update result
    while (index < s.length && s[index] >= '0' && s[index] <= '9') {
        result = result * 10 + (s.charCodeAt(index) - 48);
        index++;
    }
    // apply sign and check for overflow
    result *= sign;
    // check for 32-bit signed integer overflow
    if (result > 2**31 - 1) return 2**31 - 1;
    else if (result < -(2**31)) return -(2**31);
    return result;
}

function isPalindrome(x) {
    // convert the integer to a string to easily reverse it
    var str = x.toString();
    // initialize two pointers, one at the start and one at the end of the string
    var left = 0;
    var right = str.length - 1;
    // compare characters from the start and end, moving towards the center
    while (left < right) {
        // if the characters at the current positions do not match, return false
        if (str[left] !== str[right]) return false;
        left++;
        right--;
    }
    // if the loop completes without finding any mismatches, return true
    return true;
}

// TIME: O(log(n)) SPACE: O(log(n))

function isMatch(s, p) {
    let dp = Array(s.length + 1).fill(false).map(() => Array(p.length + 1).fill(false));
    dp[s.length][p.length] = true;
    // fill the dp table in a bottom-up manner, starting from the end of both strings
    for (let i = s.length; i >= 0; i--) {
        for (let j = p.length - 1; j >= 0; j--) {
            // if the current character in p is '*', then we have two possibilities: 
            // 1) we ignore the '*' and move to the next character in p, 
            // 2) we use the '*' to match the current character in s, and move to the next character in s
            if (p[j] === '*') {
                dp[i][j] = dp[i][j + 1] || (i < s.length && (p[j - 1] === s[i] || p[j - 1] === '.') && dp[i + 1][j]);
            } 
            // if the current character in p is not '*', then we simply check if the current characters in s and p match
            else {
                dp[i][j] = i < s.length && (p[j] === s[i] || p[j] === '.') && dp[i + 1][j + 1];
            }
        }
    }
    return dp[0][0];
}

function maxArea(height) {
  let maxWater = 0;
  let left = 0;
  let right = height.length - 1;
  // calculate area at each step and update maxWater if necessary
  while (left < right) {
    let water = Math.min(height[left], height[right]) * (right - left);
    maxWater = Math.max(maxWater, water);
    // move the pointer of the shorter line towards the other end
    if (height[left] < height[right]) {
      left++;
    } else {
      right--;
    }
  }
  return maxWater;
}

function intToRoman(num) {
    // define a hash table to store the mapping of decimal values to Roman numerals
    var romanMap = [
        [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
        [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
        [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
    ];
    var result = '';
    // iterate over the hash table and append the corresponding Roman numerals to the result
    for (var i = 0; i < romanMap.length; i++) {
        // calculate the number of times the current decimal value fits into the number
        while (num >= romanMap[i][0]) {
            // append the corresponding Roman numeral to the result
            result += romanMap[i][1];
            // subtract the decimal value from the number
            num -= romanMap[i][0];
        }
    }
    return result;
}

function romanToInt(s) {
    const romanMap = { 'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000 };
    let total = 0;
    for (let i = 0; i < s.length; i++) // iterate through the string and calculate the total
        total += (i + 1 < s.length && romanMap[s[i]] < romanMap[s[i + 1]]) ? -romanMap[s[i]] : romanMap[s[i]];
    return total;
}

function longestCommonPrefix(strs) {
    if (!strs.length) return "";
    let shortestStr = strs.reduce((a, b) => a.length < b.length ? a : b);
    for (let i = 0; i < shortestStr.length; i++) // compare characters at each position
        for (let str of strs) 
            if (str[i] !== shortestStr[i]) // if any string has a different character, return the prefix up to this point
                return shortestStr.slice(0, i);
    return shortestStr; // if all strings match up to the length of the shortest string, return the shortest string
}

function threeSumClosest(nums, target) {
    nums.sort((a, b) => a - b); // sort the array to apply two-pointer technique
    let closestSum = Infinity; // initialize the closest sum
    for (let i = 0; i < nums.length - 2; i++) { // iterate over the array
        let left = i + 1; // initialize the left pointer
        let right = nums.length - 1; // initialize the right pointer
        while (left < right) { // apply two-pointer technique
            let currentSum = nums[i] + nums[left] + nums[right]; // calculate the current sum
            if (Math.abs(currentSum - target) < Math.abs(closestSum - target)) { // update the closest sum if needed
                closestSum = currentSum;
            }
            if (currentSum < target) { // move the left pointer to increase the sum
                left++;
            } else { // move the right pointer to decrease the sum
                right--;
            }
        }
    }
    return closestSum;
}

function threeSum(nums) {
    // Sort the array to apply the two-pointer technique
    nums.sort((a, b) => a - b);
    var result = [];
    for (var i = 0; i < nums.length - 2; i++) {
        // Skip the same result
        if (i > 0 && nums[i] === nums[i - 1]) continue;
        var left = i + 1, right = nums.length - 1;
        while (left < right) {
            // Calculate the sum of the three numbers
            var sum = nums[i] + nums[left] + nums[right];
            if (sum < 0) left++;
            else if (sum > 0) right--;
            else {
                // Add the triplet to the result and move the pointers
                result.push([nums[i], nums[left], nums[right]]);
                // Skip the same result
                while (left < right && nums[left] === nums[left + 1]) left++;
                // Skip the same result
                while (left < right && nums[right] === nums[right - 1]) right--;
                left++; right--;
            }
        }
    }
    return result;
}

function letterCombinations(digits) {
    const phoneMap = {
        '2': 'abc',
        '3': 'def',
        '4': 'ghi',
        '5': 'jkl',
        '6': 'mno',
        '7': 'pqrs',
        '8': 'tuv',
        '9': 'wxyz'
    };
    const result = [];

    function backtrack(combination, nextDigits) {
        // base case: if there are no more digits to process, add the current combination to the result
        if (nextDigits.length === 0) {
            if (combination.length > 0) result.push(combination);
            return;
        }
        // get the letters corresponding to the next available digit
        const letters = phoneMap[nextDigits[0]];
        // for each letter, recursively call backtrack with the updated combination and remaining digits
        for (let i = 0; i < letters.length; i++) {
            // add the current letter to the combination and remove the first digit from nextDigits
            backtrack(combination + letters[i], nextDigits.slice(1));
        }
    }

    // start the backtracking process with an empty combination and the input digits
    backtrack('', digits);
    return result;
}

function removeNthFromEnd(head, n) {
    let length = 0;
    let temp = head;
    // calculate the length of the linked list
    while (temp !== null) {
        length++;
        temp = temp.next;
    }
    // calculate the position of the node to be removed from the start
    let pos = length - n;
    // if the node to be removed is the head
    if (pos === 0) {
        return head.next;
    }
    temp = head;
    // traverse to the node before the node to be removed
    for (let i = 0; i < pos - 1; i++) {
        temp = temp.next;
    }
    // remove the nth node from the end
    temp.next = temp.next.next;
    return head;
}

function isValid(s) {
    var stack = [];
    // push opening brackets into the stack
    for (var i = 0; i < s.length; i++) {
        if (s[i] === '(' || s[i] === '{' || s[i] === '[') {
            stack.push(s[i]);
        } else {
            // check if stack is empty before popping to avoid error
            if (stack.length === 0) return false;
            // check if the top of the stack matches the current closing bracket
            if ((s[i] === ')' && stack[stack.length - 1] !== '(') || 
                (s[i] === '}' && stack[stack.length - 1] !== '{') || 
                (s[i] === ']' && stack[stack.length - 1] !== '[')) {
                return false;
            }
            // if matches, pop the opening bracket from the stack
            stack.pop();
        }
    }
    // if stack is empty after iterating through the string, it's valid
    return stack.length === 0;
}

function mergeTwoLists(list1, list2) {
    // if list1 is empty, return list2 as it's already sorted
    if (!list1) return list2;
    // if list2 is empty, return list1 as it's already sorted
    if (!list2) return list1;
    // if list1's value is smaller, set list1 as the head and recursively merge the rest of list1 and list2
    if (list1.val < list2.val) {
        list1.next = mergeTwoLists(list1.next, list2);
        return list1;
    } 
    // if list2's value is smaller, set list2 as the head and recursively merge the rest of list1 and list2
    else {
        list2.next = mergeTwoLists(list1, list2.next);
        return list2;
    }
}

function swapPairs(head) {
    // if the list is empty or only has one node, return the head as it is
    if (!head || !head.next) return head;
    // store the next node to be swapped
    let nextNode = head.next;
    // swap the current node with the next node
    head.next = swapPairs(nextNode.next);
    // swap the next node with the current node
    nextNode.next = head;
    // return the new head which is the next node
    return nextNode;
}

function generateParenthesis(n) {
    let result = [];
    function backtrack(open, close, current) {
        // if the length of the current combination is equal to 2n, it's a well-formed combination
        if (current.length === 2 * n) {
            result.push(current);
            return;
        }
        // if the number of open parentheses is less than n, we can add an open parenthesis
        if (open < n) {
            backtrack(open + 1, close, current + '(');
        }
        // if the number of close parentheses is less than the number of open parentheses, we can add a close parenthesis
        if (close < open) {
            backtrack(open, close + 1, current + ')');
        }
    }
    backtrack(0, 0, '');
    return result;
}

