function mergeKLists(lists) {
    // Create a min-heap to store the current smallest node from each list
    let minHeap = [];
    for (let i = 0; i < lists.length; i++) {
        if (lists[i]) {
            // Store the node value, list index, and node itself in the heap
            minHeap.push([lists[i].val, i, lists[i]]);
        }
    }
    // Create a dummy node to serve as the head of the merged list
    let dummy = new ListNode(0);
    let current = dummy;
    // While the heap is not empty
    while (minHeap.length > 0) {
        // Extract the smallest node from the heap
        minHeap.sort((a, b) => a[0] - b[0]);
        let [val, listIndex, node] = minHeap.shift();
        // Add the extracted node to the merged list
        current.next = node;
        current = current.next;
        // If the extracted node has a next node, add it to the heap
        if (node.next) {
            minHeap.push([node.next.val, listIndex, node.next]);
        }
    }
    // Return the merged list
    return dummy.next;
}

function removeDuplicates(nums) {
    if (nums.length === 0) return 0;
