        if (nums[i] !== nums[i - 1]) nums[uniqueIndex++] = nums[i];
    }
    return uniqueIndex;
}

function reverseKGroup(head, k) {
    let dummy = new ListNode(0);
    dummy.next = head;
    let groupPrev = dummy;
    while (true) {
        let kth = groupPrev;
        for (let i = 0; i < k && kth; i++) kth = kth.next;
        if (!kth) break;
        let groupNext = kth.next;
        let prev = groupNext, curr = groupPrev.next;
        while (curr !== groupNext) {
            let tmp = curr.next;
            curr.next = prev;
            prev = curr;
            curr = tmp;
        }
        let tmp = groupPrev.next;
        groupPrev.next = kth;
        groupPrev = tmp;
    }
    return dummy.next;
}

function removeElement(nums, val) {
    // initialize two pointers, one at the beginning and one at the end of the array
    let left = 0;
    // iterate through the array with the right pointer
    for (let right = 0; right < nums.length; right++) {
        // if the current element is not equal to the target value, swap it with the left pointer element and move the left pointer forward
        if (nums[right] !== val) {
            nums[left] = nums[right];
            left++;
        }
    }
    // return the number of elements that are not equal to the target value
    return left;
}

function strStr(haystack, needle) {
  // loop through the haystack string with a sliding window of needle's length
  for (let i = 0; i <= haystack.length - needle.length; i++) {
    // check if the substring of haystack matches the needle
    if (haystack.substring(i, i + needle.length) === needle) {
      // return the index if a match is found
      return i;
    }
  }
  // return -1 if no match is found
  return -1;
}

function divide(dividend, divisor) {
    // Determine the sign of the result
    let sign = (dividend < 0) ^ (divisor < 0) ? -1 : 1;
    // Convert both numbers to positive
    let a = Math.abs(dividend), b = Math.abs(divisor);
    let quotient = 0;
    // Loop until dividend is less than divisor
    while (a >= b) {
        // Calculate the number of left shifts
        let shift = 0;
        // Keep shifting the divisor to the left until it's larger than the dividend
        while ((b << shift) <= a) {
            // Increment the shift count
            shift++;
        }
        // Subtract the shifted divisor from the dividend
        a -= (b << (shift - 1));
        // Add the shifted 1 to the quotient
        quotient += (1 << (shift - 1));
    }
    // Apply the sign to the quotient
    quotient *= sign;
    // Clamp the quotient to the 32-bit signed integer range
    return Math.max(-Math.pow(2, 31), Math.min(quotient, Math.pow(2, 31) - 1));
}

function findSubstring(s, words) {
    let result = [];
    let wordCount = words.length;
    let wordLength = words[0].length;
    let totalLength = wordCount * wordLength;
    let wordMap = {};
    // Create a hash map to store the frequency of each word
    for (let word of words) {
        if (wordMap[word]) {
            wordMap[word]++;
        } else {
            wordMap[word] = 1;
        }
    }
    // Iterate over the string with a sliding window of size totalLength
    for (let i = 0; i <= s.length - totalLength; i++) {
        let seen = {};
        // Initialize a seen map to keep track of the words in the current window
        for (let j = 0; j < wordCount; j++) {
            let word = s.substring(i + j * wordLength, i + (j + 1) * wordLength);
            // If the word is not in the wordMap, break the loop
            if (!wordMap[word]) {
                break;
            }
            // If the word is in the seen map, increment its count
            if (seen[word]) {
                seen[word]++;
            } else {
                seen[word] = 1;
            }
            // If the count of the word in the seen map exceeds the count in the wordMap, break the loop
            if (seen[word] > wordMap[word]) {
                break;
            }
            // If we have checked all the words in the window, add the start index to the result
            if (j === wordCount - 1) {
                result.push(i);
            }
        }
    }
    return result;
}

function nextPermutation(nums) {
  let i = nums.length - 2;
  // find the first decreasing element from the end
  while (i >= 0 && nums[i] >= nums[i + 1]) {
    i--;
  }
  if (i >= 0) {
    let j = nums.length - 1;
    // find the smallest element greater than nums[i] from the end
    while (j > i && nums[j] <= nums[i]) {
      j--;
    }
    // swap nums[i] and nums[j]
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  // reverse the elements after i
  let left = i + 1, right = nums.length - 1;
  while (left < right) {
    // swap nums[left] and nums[right]
    [nums[left], nums[right]] = [nums[right], nums[left]];
    left++;
    right--;
  }
}

function longestValidParentheses(s) {
    let maxLength = 0;
    let stack = [-1]; // initialize stack with -1 to handle edge cases
    for (let i = 0; i < s.length; i++) {
        // if we encounter an opening parenthesis, push its index to the stack
        if (s[i] === '(') {
            stack.push(i);
        } else {
            // if we encounter a closing parenthesis, pop the top of the stack
            stack.pop();
            // if the stack is empty, push the current index to the stack
            if (stack.length === 0) {
                stack.push(i);
            } else {
                // update maxLength if the current valid substring is longer
                maxLength = Math.max(maxLength, i - stack[stack.length - 1]);
            }
        }
    }
    return maxLength;
}

function search(nums, target) {
    let left = 0;
    let right = nums.length - 1;
    // Determine which half is sorted and decide which half to continue searching in
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        // If target is found, return the index
        if (nums[mid] === target) return mid;
        // Check if left half is sorted
        if (nums[left] <= nums[mid]) {
            // If target is in the sorted left half, continue searching in the left half
            if (nums[left] <= target && target < nums[mid]) {
                right = mid - 1;
            } else {
                // Otherwise, continue searching in the right half
                left = mid + 1;
            }
        } else {
            // If left half is not sorted, then right half must be sorted
            // If target is in the sorted right half, continue searching in the right half
            if (nums[mid] < target && target <= nums[right]) {
                left = mid + 1;
            } else {
                // Otherwise, continue searching in the left half
                right = mid - 1;
            }
        }
    }
    // If target is not found, return -1
    return -1;
}

function searchRange(nums, target) {
    // find the first occurrence of the target using binary search
    let firstPosition = findFirstPosition(nums, target);
    // if the target is not found, return [-1, -1]
    if (firstPosition === -1) return [-1, -1];
    // find the last occurrence of the target using binary search
    let lastPosition = findLastPosition(nums, target);
    return [firstPosition, lastPosition];
}

function findFirstPosition(nums, target) {
    let left = 0, right = nums.length - 1;
    let firstPosition = -1;
    while (left <= right) {
        // calculate the middle index and check if it's the first occurrence of the target
        let mid = Math.floor((left + right) / 2);
        if (nums[mid] === target) {
            firstPosition = mid;
            // continue searching on the left half to find the first occurrence
            right = mid - 1;
        } else if (nums[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return firstPosition;
}

function findLastPosition(nums, target) {
    let left = 0, right = nums.length - 1;
    let lastPosition = -1;
    while (left <= right) {
        // calculate the middle index and check if it's the last occurrence of the target
        let mid = Math.floor((left + right) / 2);
        if (nums[mid] === target) {
            lastPosition = mid;
            // continue searching on the right half to find the last occurrence
            left = mid + 1;
        } else if (nums[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return lastPosition;
}

function searchInsert(nums, target) {
    let left = 0;
    let right = nums.length - 1;
    // continue the loop until the left pointer is less than or equal to the right pointer
    while (left <= right) {
        // calculate the middle index
        let mid = Math.floor((left + right) / 2);
        // if the target is found, return the index
        if (nums[mid] === target) return mid;
        // if the target is less than the middle element, move the right pointer
        else if (nums[mid] > target) right = mid - 1;
        // if the target is greater than the middle element, move the left pointer
        else left = mid + 1;
    }
    // if the target is not found, return the index where it should be inserted
    return left;
}

function isValidSudoku(board) {
    let rows = new Array(9).fill(0).map(() => new Set());
    let cols = new Array(9).fill(0).map(() => new Set());
    let boxes = new Array(9).fill(0).map(() => new Set());
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            // Check if current cell is not empty
            if (board[i][j] !== '.') {
                let num = board[i][j];
                let boxIndex = Math.floor(i / 3) * 3 + Math.floor(j / 3);
                // Check if current number already exists in the row, column or box
                if (rows[i].has(num) || cols[j].has(num) || boxes[boxIndex].has(num)) {
                    return false;
                }
                rows[i].add(num);
                cols[j].add(num);
                boxes[boxIndex].add(num);
            }
        }
    }
    return true;
}

function countAndSay(n) {
    let result = '1';
    // generate the next sequence by iterating over the current sequence
    for (let i = 1; i < n; i++) {
        let nextSequence = '';
        let count = 1;
        // iterate over the current sequence to generate the next sequence
        for (let j = 1; j <= result.length; j++) {
            // if the current character is the same as the next one, increment the count
            if (j < result.length && result[j] === result[j - 1]) {
                count++;
            } else {
                // otherwise, append the count and character to the next sequence
                nextSequence += count + result[j - 1];
                count = 1;
            }
        }
        result = nextSequence;
    }
    return result;
}

function solveSudoku(board) {
    // Check if the current board is a valid solution
    if (isBoardFull(board)) return true;

    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            // Check if the current cell is empty
            if (board[i][j] === '.') {
                // Try numbers from 1 to 9
                for (let num = 1; num <= 9; num++) {
                    // Convert the number to a string
                    let numStr = num.toString();
                    // Check if the current number is valid in the current cell
                    if (isValid(board, i, j, numStr)) {
                        // Place the current number in the current cell
                        board[i][j] = numStr;
                        // Recursively try to fill the rest of the board
                        if (solveSudoku(board)) return true;
                        // If the recursive call returns false, reset the current cell
                        board[i][j] = '.';
                    }
                }
                // If no number is valid in the current cell, return false
                return false;
            }
        }
    }
}

// Helper function to check if the board is full
function isBoardFull(board) {
    for (let i = 0; i < 9; i++) {
        for (let j = 0; j < 9; j++) {
            if (board[i][j] === '.') return false;
        }
    }
    return true;
}

// Helper function to check if a number is valid in a cell
function isValid(board, row, col, num) {
    // Check the row
    for (let i = 0; i < 9; i++) {
        if (board[row][i] === num) return false;
    }
    // Check the column
    for (let i = 0; i < 9; i++) {
        if (board[i][col] === num) return false;
    }
    // Check the 3x3 box
    let boxRow = Math.floor(row / 3) * 3;
    let boxCol = Math.floor(col / 3) * 3;
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            if (board[boxRow + i][boxCol + j] === num) return false;
        }
    }
    return true;
}

// TIME: O(9^(n*n)) SPACE: O(n*n)

function combinationSum(candidates, target) {
    const result = [];
    function backtrack(remain, comb, start) {
        // if the remaining sum is 0, it means we have found a valid combination
        if (remain === 0) result.push([...comb]);
        // iterate over the candidates array starting from the start index
        for (let i = start; i < candidates.length; i++) {
            // if the current candidate is greater than the remaining sum, break the loop
            if (candidates[i] > remain) break;
            // add the current candidate to the current combination
            comb.push(candidates[i]);
            // recursively call the backtrack function with the updated remaining sum and combination
            backtrack(remain - candidates[i], comb, i);
            // remove the last added candidate from the current combination for backtracking
            comb.pop();
        }
    }
    backtrack(target, [], 0);
    return result;
}

