function combinationSum2(candidates, target) {
    // sort the candidates array to handle duplicates
    candidates.sort((a, b) => a - b);
    var result = [];
    function backtrack(remain, comb, start) {
        // if the remaining target is 0, it means we have found a valid combination
        if (remain === 0) {
            result.push([...comb]);
            return;
        }
        // iterate over the candidates array
        for (var i = start; i < candidates.length; i++) {
            // skip duplicates to avoid duplicate combinations
            if (i > start && candidates[i] === candidates[i - 1]) continue;
            // if the current candidate is greater than the remaining target, break the loop
            if (candidates[i] > remain) break;
            // add the current candidate to the current combination
            comb.push(candidates[i]);
            // recursively call the backtrack function with the updated remaining target and combination
            backtrack(remain - candidates[i], comb, i + 1);
            // remove the last added candidate from the current combination for backtracking
            comb.pop();
        }
    }
    backtrack(target, [], 0);
    return result;
}

function firstMissingPositive(nums) {
    // separate positive numbers to the left side of the array
    let j = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] > 0) {
            // swap nums[i] and nums[j]
            let temp = nums[i];
            nums[i] = nums[j];
            nums[j] = temp;
            j++;
        }
    }
    // mark the presence of an element x by using the sign of the value at the index x
    for (let i = 0; i < j; i++) {
        // get the absolute value of nums[i] to handle the case where nums[i] has been marked
        let num = Math.abs(nums[i]);
        if (num - 1 < j) {
            // mark the presence of num
            nums[num - 1] = -Math.abs(nums[num - 1]);
        }
    }
    // find the first index which has a positive value
    for (let i = 0; i < j; i++) {
        if (nums[i] > 0) {
            return i + 1;
        }
    }
    // if all numbers from 1 to j are present, return j + 1
    return j + 1;
}

function trap(height) {
  let left = 0, right = height.length - 1;
  let maxLeft = 0, maxRight = 0;
  let result = 0;
  while (left <= right) {
    // if height of left bar is less than height of right bar, we calculate the trapped water for the left bar
    if (height[left] < height[right]) {
      // if height of current left bar is greater than maxLeft, update maxLeft
      if (height[left] > maxLeft) {
        maxLeft = height[left];
      } else {
        // calculate the trapped water for the current left bar
        result += maxLeft - height[left];
      }
      left++;
    } else {
      // if height of current right bar is greater than maxRight, update maxRight
      if (height[right] > maxRight) {
        maxRight = height[right];
      } else {
        // calculate the trapped water for the current right bar
        result += maxRight - height[right];
      }
      right--;
    }
  }
  return result;
}

function multiply(num1, num2) {
    let result = new Array(num1.length + num2.length).fill(0);
    // iterate over each digit in num1 and num2, multiplying them and adding to the result
    for (let i = num1.length - 1; i >= 0; i--) {
        for (let j = num2.length - 1; j >= 0; j--) {
            let mul = (num1.charCodeAt(i) - '0'.charCodeAt(0)) * (num2.charCodeAt(j) - '0'.charCodeAt(0));
            let p1 = i + j, p2 = i + j + 1;
            let sum = mul + result[p2];
            result[p1] += Math.floor(sum / 10);
            result[p2] = sum % 10;
        }
    }
    // remove leading zeros from the result
    let start = 0;
    while (start < result.length - 1 && result[start] === 0) start++;
    let res = '';
    for (let i = start; i < result.length; i++) res += result[i];
    return res || '0';
}

function isMatch(s, p) {
  let sIndex = 0, pIndex = 0, starIndex = -1, matchIndex = 0;
  while (sIndex < s.length) {
    // if current pattern character is '*' then store its index and move to next character in pattern
    if (pIndex < p.length && p[pIndex] === '*') {
      starIndex = pIndex;
      matchIndex = sIndex;
      pIndex++;
    } 
    // if current pattern character is '?' or matches current string character then move to next characters in both string and pattern
    else if (pIndex < p.length && (p[pIndex] === '?' || p[pIndex] === s[sIndex])) {
      pIndex++;
      sIndex++;
    } 
    // if current pattern character does not match current string character and '*' has been encountered before then move to next character in string and reset pattern index to next character of last '*'
    else if (starIndex !== -1) {
      pIndex = starIndex + 1;
      matchIndex++;
      sIndex = matchIndex;
    } 
    // if none of the above conditions are met then return false as current pattern does not match current string
    else {
      return false;
    }
  }
  // if all characters in string have been matched then move to next characters in pattern until '*' is encountered or all characters in pattern have been matched
  while (pIndex < p.length && p[pIndex] === '*') {
    pIndex++;
  }
  // return true if all characters in both string and pattern have been matched, false otherwise
  return pIndex === p.length;
}

function jump(nums) {
    let jumps = 0;
    let currentEnd = 0;
    let farthest = 0;
    // iterate through the array and update the farthest reachable position
    for (let i = 0; i < nums.length - 1; i++) {
        // update the farthest reachable position
        farthest = Math.max(farthest, i + nums[i]);
        // if we have reached the end of the current jump, update the current end and increment the jump count
        if (i === currentEnd) {
            jumps++;
            currentEnd = farthest;
        }
    }
    return jumps;
}

function rotate(matrix) {
    // transpose the matrix by swapping elements across the diagonal
    for (let i = 0; i < matrix.length; i++) {
        for (let j = i; j < matrix.length; j++) {
            let temp = matrix[i][j];
            matrix[i][j] = matrix[j][i];
            matrix[j][i] = temp;
        }
    }
    // reverse each row to complete the rotation
    for (let i = 0; i < matrix.length; i++) {
        let left = 0;
        let right = matrix.length - 1;
        while (left < right) {
            let temp = matrix[i][left];
            matrix[i][left] = matrix[i][right];
            matrix[i][right] = temp;
            left++;
            right--;
        }
    }
}

function permute(nums) {
  const result = [];
  function backtrack(current, remaining) {
    // if there are no more numbers to choose from, add the current permutation to the result
    if (remaining.length === 0) result.push([...current]);
    else {
      // for each number in the remaining array
      for (let i = 0; i < remaining.length; i++) {
        // add the number to the current permutation
        current.push(remaining[i]);
        // remove the number from the remaining array
        const newRemaining = remaining.slice(0, i).concat(remaining.slice(i + 1));
        // recursively call the backtrack function with the updated current and remaining arrays
        backtrack(current, newRemaining);
        // remove the last added number from the current permutation (backtracking)
        current.pop();
      }
    }
  }
  backtrack([], nums);
  return result;
}

function permuteUnique(nums) {
    // sort the array to handle duplicates
    nums.sort((a, b) => a - b);
    const result = [];
    const visited = new Array(nums.length).fill(false);
    function backtrack(current) {
        // if the current permutation is complete, add it to the result
        if (current.length === nums.length) {
            result.push([...current]);
            return;
        }
        for (let i = 0; i < nums.length; i++) {
            // skip the current number if it's already visited or if it's a duplicate
            if (visited[i] || (i > 0 && nums[i] === nums[i - 1] && !visited[i - 1])) {
                continue;
            }
            // mark the current number as visited and add it to the current permutation
            visited[i] = true;
            current.push(nums[i]);
            // recursively generate all permutations
            backtrack(current);
            // backtrack by removing the current number from the current permutation and marking it as unvisited
            current.pop();
            visited[i] = false;
        }
    }
    backtrack([]);
    return result;
}

function groupAnagrams(strs) {
    var anagramMap = {};
    for (var i = 0; i < strs.length; i++) {
        var sortedStr = strs[i].split('').sort().join(''); // sorting the string to create a unique key for anagrams
        if (!anagramMap[sortedStr]) anagramMap[sortedStr] = [];
        anagramMap[sortedStr].push(strs[i]); // grouping anagrams together
    }
    return Object.values(anagramMap); // returning the grouped anagrams
}

// TIME: O(n*m*log(m)) SPACE: O(n*m)

function myPow(x, n) {
    // handle negative exponent by converting to positive and taking reciprocal at the end
    if (n < 0) {
        x = 1 / x;
        n = -n;
    }
    // initialize result to 1
    var result = 1;
    // repeatedly multiply x to result for n times
    while (n > 0) {
        // if n is odd, multiply x to result
        if (n % 2 === 1) result *= x;
        // square x and divide n by 2 for next iteration
        x *= x;
        n = Math.floor(n / 2);
    }
    return result;
}

function solveNQueens(n) {
    const result = [];
    const board = Array(n).fill('.').map(() => Array(n).fill('.'));
    function isValid(row, col) {
        // check the column
        for (let i = 0; i < row; i++) {
            if (board[i][col] === 'Q') return false;
        }
        // check the main diagonal
        for (let i = row - 1, j = col - 1; i >= 0 && j >= 0; i--, j--) {
            if (board[i][j] === 'Q') return false;
        }
        // check the other diagonal
        for (let i = row - 1, j = col + 1; i >= 0 && j < n; i--, j++) {
            if (board[i][j] === 'Q') return false;
        }
        return true;
    }
    function backtrack(row) {
        // if we have placed all queens, add the board to the result
        if (row === n) {
            const boardCopy = board.map(row => row.join(''));
            result.push(boardCopy);
            return;
        }
        // try to place a queen in each column
        for (let col = 0; col < n; col++) {
            // check if it's safe to place a queen here
            if (isValid(row, col)) {
                // place a queen
                board[row][col] = 'Q';
                // move to the next row
                backtrack(row + 1);
                // remove the queen
                board[row][col] = '.';
            }
        }
    }
    backtrack(0);
    return result;
}

function maxSubArray(nums) {
    let maxSum = nums[0]; // initialize maxSum with the first element
    let currentSum = nums[0]; // initialize currentSum with the first element
    for (let i = 1; i < nums.length; i++) { 
        // update currentSum to be the maximum of the current number and the sum of current number and previous currentSum
        currentSum = Math.max(nums[i], currentSum + nums[i]); 
        // update maxSum to be the maximum of maxSum and currentSum
        maxSum = Math.max(maxSum, currentSum); 
    }
    return maxSum;
}

function spiralOrder(matrix) {
    const result = [];
    if (!matrix.length) return result; // handle empty matrix
    let top = 0, bottom = matrix.length - 1, left = 0, right = matrix[0].length - 1;
    while (top <= bottom && left <= right) {
        // traverse from left to right
        for (let i = left; i <= right; i++) result.push(matrix[top][i]);
        top++;
        // traverse from top to bottom
        for (let i = top; i <= bottom; i++) result.push(matrix[i][right]);
        right--;
        // traverse from right to left
        if (top <= bottom) for (let i = right; i >= left; i--) result.push(matrix[bottom][i]);
        bottom--;
        // traverse from bottom to top
        if (left <= right) for (let i = bottom; i >= top; i--) result.push(matrix[i][left]);
        left++;
    }
    return result;
}

function totalNQueens(n) {
    function isSafe(board, row, col) {
        // check this column on left side
        for (let i = 0; i < row; i++) {
            if (board[i] === col || 
                board[i] - i === col - row || 
                board[i] + i === col + row) {
                return false;
            }
        }
        return true;
    }

    function placeQueens(board, row) {
        if (row === n) {
            // found a solution
            return 1;
        }
        let count = 0;
        for (let col = 0; col < n; col++) {
            // check if the queen can be placed on board[row][col]
            if (isSafe(board, row, col)) {
                // place this queen in board[row][col]
                board[row] = col;
                // recur to place rest of the queens
                count += placeQueens(board, row + 1);
            }
        }
        return count;
    }

    let board = new Array(n).fill(-1);
    return placeQueens(board, 0);
}

function canJump(nums) {
  let lastPosition = nums.length - 1;
  // iterate through the array in reverse to find the last position that can reach the end
  for (let i = nums.length - 1; i >= 0; i--) {
    // if we can reach the last position from the current position, update the last position
    if (i + nums[i] >= lastPosition) {
      lastPosition = i;
    }
  }
  // return true if we can reach the end from the start, false otherwise
  return lastPosition === 0;
}

function mergeIntervals(intervals) {
  // Sort the intervals based on their start time
  intervals.sort((a, b) => a[0] - b[0]);
  const merged = [intervals[0]];
  for (let i = 1; i < intervals.length; i++) {
    // Check if the current interval overlaps with the last merged interval
    if (intervals[i][0] <= merged[merged.length - 1][1]) {
      // Merge the current interval with the last merged interval
      merged[merged.length - 1][1] = Math.max(merged[merged.length - 1][1], intervals[i][1]);
    } else {
      // Add the current interval to the list of merged intervals
      merged.push(intervals[i]);
    }
  }
  return merged;
}

function insert(intervals, newInterval) {
    let result = [];
    let i = 0;
    // add all intervals that come before the 'newInterval'
    while (i < intervals.length && intervals[i][1] < newInterval[0]) {
        result.push(intervals[i]);
        i++;
    }
    // merge all overlapping intervals to the 'newInterval'
    while (i < intervals.length && intervals[i][0] <= newInterval[1]) {
        newInterval[0] = Math.min(newInterval[0], intervals[i][0]);
        newInterval[1] = Math.max(newInterval[1], intervals[i][1]);
        i++;
    }
    // add the 'newInterval'
    result.push(newInterval);
    // add all remaining intervals to the output
    while (i < intervals.length) {
        result.push(intervals[i]);
        i++;
    }
    return result;
}

function lengthOfLastWord(s) {
    // remove trailing spaces to ensure we're checking the actual last word
    s = s.trim();
    // find the last space in the string, which separates the last word from the rest
    let lastSpaceIndex = s.lastIndexOf(' ');
    // if no space is found, the entire string is the last word
    if (lastSpaceIndex === -1) return s.length;
    // otherwise, return the length of the substring after the last space
    return s.length - lastSpaceIndex - 1;
}

function getPermutation(n, k) {
    let numbers = [];
    for (let i = 1; i <= n; i++) {
        numbers.push(i);
    }
    k--; // adjust k to 0-based index
    let result = '';
    while (n > 0) {
        // calculate the factorial of n-1
        let factorial = 1;
        for (let i = 1; i < n; i++) {
            factorial *= i;
        }
        // find the index of the current number
        let index = Math.floor(k / factorial);
        // append the current number to the result
        result += numbers[index];
        // remove the current number from the list
        numbers.splice(index, 1);
        // update k
        k %= factorial;
        n--;
    }
    return result;
}

function generateMatrix(n) {
    let matrix = new Array(n).fill(0).map(() => new Array(n).fill(0));
    let rowStart = 0, rowEnd = n - 1;
    let colStart = 0, colEnd = n - 1;
    let count = 1;
    // fill the matrix in spiral order
    while (rowStart <= rowEnd && colStart <= colEnd) {
        // fill the first row
        for (let i = colStart; i <= colEnd; i++) {
            matrix[rowStart][i] = count++;
        }
        rowStart++;
        // fill the last column
        for (let i = rowStart; i <= rowEnd; i++) {
            matrix[i][colEnd] = count++;
        }
        colEnd--;
        // fill the last row
        if (rowStart <= rowEnd) {
            for (let i = colEnd; i >= colStart; i--) {
                matrix[rowEnd][i] = count++;
            }
        }
        rowEnd--;
        // fill the first column
        if (colStart <= colEnd) {
            for (let i = rowEnd; i >= rowStart; i--) {
                matrix[i][colStart] = count++;
            }
        }
        colStart++;
    }
    return matrix;
}

function rotateList(head, k) {
    if (!head || !head.next || k === 0) return head; 
    // calculate the length of the linked list
    let length = 1;
    let tail = head;
    while (tail.next) {
        length++;
        tail = tail.next;
    }
    // connect the tail to the head to form a circular linked list
    tail.next = head;
    // calculate the new tail position
    let newTailPosition = length - k % length - 1;
    // find the new tail
    let newTail = head;
    for (let i = 0; i < newTailPosition; i++) {
        newTail = newTail.next;
    }
    // find the new head
    let newHead = newTail.next;
    // disconnect the new tail and new head
    newTail.next = null;
    return newHead;
}

function uniquePaths(m, n) {
    let dp = Array(m).fill().map(() => Array(n).fill(1)); 
    // calculate the number of unique paths for each cell
    for (let i = 1; i < m; i++) {
        for (let j = 1; j < n; j++) {
            // the number of unique paths to a cell is the sum of the number of unique paths to the cell above it and the cell to its left
            dp[i][j] = dp[i-1][j] + dp[i][j-1];
        }
    }
    return dp[m-1][n-1];
}

function uniquePathsWithObstacles(obstacleGrid) {
    let rows = obstacleGrid.length;
    let cols = obstacleGrid[0].length;
    let dp = new Array(rows).fill(0).map(() => new Array(cols).fill(0));
    // initialize the first cell as 1 if it's not an obstacle
    dp[0][0] = obstacleGrid[0][0] === 0 ? 1 : 0;
    // fill the first row
    for (let i = 1; i < cols; i++) {
        // if the current cell is not an obstacle and the previous cell is reachable
        dp[0][i] = obstacleGrid[0][i] === 0 ? dp[0][i - 1] : 0;
    }
    // fill the first column
    for (let i = 1; i < rows; i++) {
        // if the current cell is not an obstacle and the cell above it is reachable
        dp[i][0] = obstacleGrid[i][0] === 0 ? dp[i - 1][0] : 0;
    }
    // fill the rest of the grid
    for (let i = 1; i < rows; i++) {
        for (let j = 1; j < cols; j++) {
            // if the current cell is not an obstacle, the number of ways to reach it is the sum of the ways to reach the cell above it and the cell to its left
            dp[i][j] = obstacleGrid[i][j] === 0 ? dp[i - 1][j] + dp[i][j - 1] : 0;
        }
    }
    return dp[rows - 1][cols - 1];
}

function minPathSum(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  // initialize the first cell with its own value
  for (let i = 1; i < rows; i++) {
    // for each cell in the first column, add the value of the cell above it
    grid[i][0] += grid[i-1][0];
  }
  for (let j = 1; j < cols; j++) {
    // for each cell in the first row, add the value of the cell to its left
    grid[0][j] += grid[0][j-1];
  }
  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < cols; j++) {
      // for each cell, add the minimum of the cell above it and the cell to its left
      grid[i][j] += Math.min(grid[i-1][j], grid[i][j-1]);
    }
  }
  // the minimum path sum is stored in the bottom right cell
  return grid[rows-1][cols-1];
}

function isNumber(s) {
    let seenE = false, seenDot = false, seenDigit = false;
    for (let i = 0; i < s.length; i++) {
        // check if the current character is a digit
        if (!isNaN(s[i])) {
            seenDigit = true;
        } 
        // check if the current character is a sign
        else if (s[i] === '-' || s[i] === '+') {
            // a sign can only appear at the start or after 'e' or 'E'
            if (i !== 0 && s[i-1].toLowerCase() !== 'e') return false;
        } 
        // check if the current character is 'e' or 'E'
        else if (s[i].toLowerCase() === 'e') {
            // 'e' or 'E' can only appear once and after a digit
            if (seenE || !seenDigit) return false;
            seenE = true;
            seenDigit = false; // reset seenDigit for the exponent part
        } 
        // check if the current character is a dot
        else if (s[i] === '.') {
            // a dot can only appear once and not after 'e' or 'E'
            if (seenDot || seenE) return false;
            seenDot = true;
        } 
        // if the current character is none of the above, return false
        else {
            return false;
        }
    }
    // return true if we have seen at least one digit
    return seenDigit;
}

function plusOne(digits) {
  for (let i = digits.length - 1; i >= 0; i--) { 
    // if the current digit is not 9, we can simply increment it and return the array
    if (digits[i] !== 9) {
      digits[i]++;
      return digits;
    }
    // if the current digit is 9, we set it to 0 and continue to the next most significant digit
    digits[i] = 0;
  }
  // if all digits are 9, we need to add a new most significant digit (1) to the array
  digits.unshift(1);
  return digits;
}

function addBinary(a, b) {
    let result = ''
    let carry = 0
    let i = a.length - 1
    let j = b.length - 1
    // iterate through both binary strings from the end and calculate the sum
    while (i >= 0 || j >= 0 || carry) {
        let sum = carry
        if (i >= 0) sum += parseInt(a[i--])
        if (j >= 0) sum += parseInt(b[j--])
        // update the result and the carry
        result = (sum % 2) + result
        carry = Math.floor(sum / 2)
    }
    return result
}

// TIME: O(max(m, n)) SPACE: O(max(m, n))

function fullJustify(words, maxWidth) {
    let result = [];
    let currentLine = [];
    let currentWidth = 0;
    for (let i = 0; i < words.length; i++) {
        if (currentWidth + currentLine.length + words[i].length > maxWidth) {
            let spaces = maxWidth - currentWidth;
            let gaps = currentLine.length - 1;
            let line = '';
            if (gaps === 0) {
                line = currentLine[0] + ' '.repeat(spaces);
            } else {
                let extraSpaces = Math.floor(spaces / gaps);
                let remainingSpaces = spaces % gaps;
                for (let j = 0; j < currentLine.length; j++) {
                    line += currentLine[j];
                    if (j < currentLine.length - 1) {
                        line += ' '.repeat(extraSpaces + (j < remainingSpaces ? 1 : 0));
                    }
                }
            }
            result.push(line);
            currentLine = [words[i]];
            currentWidth = words[i].length;
        } else {
            currentLine.push(words[i]);
            currentWidth += words[i].length;
        }
    }
    let lastLine = currentLine.join(' ');
    lastLine += ' '.repeat(maxWidth - lastLine.length);
    result.push(lastLine);
    return result;
}

function climbStairs(n) {
  let ways = new Array(n + 1);
  ways[0] = 1; 
  ways[1] = 1; 
  // for each step, calculate the number of ways to reach it by summing the ways to reach the previous two steps
  for (let i = 2; i <= n; i++) {
    ways[i] = ways[i - 1] + ways[i - 2];
  }
  return ways[n];
}

function simplifyPath(path) {
    let stack = [];
    let components = path.split('/');
    // iterate through each component in the path
    for (let component of components) {
        // ignore empty strings and the current directory
        if (component === '' || component === '.') {
            continue;
        } 
        // move up one directory level
        else if (component === '..') {
            // if the stack is not empty, pop the last directory
            if (stack.length > 0) {
                stack.pop();
            }
        } 
        // add the directory to the stack
        else {
            stack.push(component);
        }
    }
    // join the directories in the stack with '/' and add a leading '/'
    return '/' + stack.join('/');
}

function minDistance(word1, word2) {
  const m = word1.length, n = word2.length;
  const dp = Array(m + 1).fill().map(() => Array(n + 1).fill(0));
  // initialize base cases for the first row and column
  for (let i = 0; i <= m; i++) dp[i][0] = i;
  for (let j = 0; j <= n; j++) dp[0][j] = j;
  // fill in the rest of the table using the recurrence relation
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      // if the current characters match, there's no operation needed
      if (word1[i - 1] === word2[j - 1]) dp[i][j] = dp[i - 1][j - 1];
      // otherwise, consider all possible operations and take the minimum
