    if (!root) return [];
    let result = [];
    let queue = [root];
    let isLeftToRight = true;
    // perform BFS and alternate the direction of traversal at each level
    while (queue.length > 0) {
        let levelSize = queue.length;
        let levelValues = [];
        for (let i = 0; i < levelSize; i++) {
            let currentNode = queue.shift();
            // add node value to levelValues array
            if (isLeftToRight) levelValues.push(currentNode.val);
            else levelValues.unshift(currentNode.val);
            if (currentNode.left) queue.push(currentNode.left);
            if (currentNode.right) queue.push(currentNode.right);
        }
        result.push(levelValues);
        // alternate the direction of traversal at each level
        isLeftToRight = !isLeftToRight;
    }
    return result;
}

function buildTree(preorder, inorder) {
    if (preorder.length === 0) return null;
    // Create the root node with the first element of preorder
    let root = { val: preorder[0], left: null, right: null };
    // Find the index of the root in inorder to divide the tree
    let index = inorder.indexOf(preorder[0]);
    // Recursively construct the left subtree
    root.left = buildTree(preorder.slice(1, index + 1), inorder.slice(0, index));
    // Recursively construct the right subtree
    root.right = buildTree(preorder.slice(index + 1), inorder.slice(index + 1));
    return root;
}

function levelOrderBottom(root) {
    if (!root) return [];
    let result = [];
    let queue = [root];
    // perform BFS traversal
    while (queue.length > 0) {
        let levelSize = queue.length;
        let levelNodes = [];
        // process each node at the current level
        for (let i = 0; i < levelSize; i++) {
            let currentNode = queue.shift();
            levelNodes.push(currentNode.val);
            if (currentNode.left) queue.push(currentNode.left);
            if (currentNode.right) queue.push(currentNode.right);
        }
        // add the current level to the result
        result.unshift(levelNodes);
    }
    return result;
}

function buildTree(inorder, postorder) {
    if (inorder.length === 0) return null;
    // create root node with the last element of postorder
    let root = new TreeNode(postorder[postorder.length - 1]);
    // find the index of the root in inorder
    let index = inorder.indexOf(postorder[postorder.length - 1]);
    // recursively build left and right subtrees
    root.left = buildTree(inorder.slice(0, index), postorder.slice(0, index));
    root.right = buildTree(inorder.slice(index + 1), postorder.slice(index, postorder.length - 1));
    return root;
}

function sortedArrayToBST(nums) {
  function helper(left, right) {
    // base case: if left pointer exceeds right pointer, return null
    if (left > right) return null;
    // find the middle index to ensure the tree is height-balanced
    let mid = Math.floor((left + right) / 2);
    // create a new node with the middle element as its value
    let node = { val: nums[mid], left: null, right: null };
    // recursively construct the left and right subtrees
    node.left = helper(left, mid - 1);
    node.right = helper(mid + 1, right);
    return node;
  }
  return helper(0, nums.length - 1);
}

function sortedListToBST(head) {
    // if the list is empty, return null
    if (!head) return null;

    // find the length of the linked list
    let length = 0;
    let temp = head;
    while (temp) {
        length++;
        temp = temp.next;
    }

    // create a new array to store the values of the linked list
    let values = new Array(length);
    let index = 0;
    temp = head;
    while (temp) {
        values[index++] = temp.val;
        temp = temp.next;
    }

    // recursively construct the BST
    function buildBST(left, right) {
        // if the left index is greater than the right index, return null
        if (left > right) return null;

        // find the middle index
        let mid = Math.floor((left + right) / 2);

        // create a new node with the middle value
        let node = { val: values[mid], left: null, right: null };

        // recursively construct the left and right subtrees
        node.left = buildBST(left, mid - 1);
        node.right = buildBST(mid + 1, right);

        // return the node
        return node;
    }

    // return the root of the BST
    return buildBST(0, length - 1);
}

function isBalanced(root) {
    function checkBalance(node) {
        // if the node is null, consider it balanced with height -1
        if (node === null) return [-1, true];

        // recursively check the left and right subtrees
        let [leftHeight, leftBalanced] = checkBalance(node.left);
        let [rightHeight, rightBalanced] = checkBalance(node.right);

        // the current node is balanced if both subtrees are balanced and their heights differ by at most 1
        let balanced = leftBalanced && rightBalanced && Math.abs(leftHeight - rightHeight) <= 1;

        // the height of the current node is the maximum height of its subtrees plus 1
        let height = Math.max(leftHeight, rightHeight) + 1;

        return [height, balanced];
    }

    // return whether the root node is balanced
    return checkBalance(root)[1];
}

function hasPathSum(root, targetSum) {
    // base case: if the tree is empty, return false
    if (!root) return false;
    // if the current node is a leaf and its value equals the target sum, return true
    if (!root.left && !root.right) return root.val === targetSum;
    // recursively check the left and right subtrees with the updated target sum
    targetSum -= root.val;
    return hasPathSum(root.left, targetSum) || hasPathSum(root.right, targetSum);
}

function connect(root) {
    if (!root) return null;
    // perform level order traversal to populate next pointers
    let queue = [root];
    while (queue.length > 0) {
        let size = queue.length;
        for (let i = 0; i < size; i++) {
            // set next pointer for each node to the next node in the queue
            if (i < size - 1) queue[i].next = queue[i + 1];
            else queue[i].next = null;
            // add children to the queue for the next level
            if (queue[i].left) queue.push(queue[i].left);
            if (queue[i].right) queue.push(queue[i].right);
        }
        // move to the next level
        queue = queue.slice(size);
    }
    return root;
}

function connect(root) {
    if (!root) return null;
    // perform level order traversal to connect nodes at each level
    let queue = [root];
    while (queue.length > 0) {
        let size = queue.length;
        // connect nodes at the current level
        for (let i = 0; i < size; i++) {
            let node = queue.shift();
            // connect the current node to the next node at the same level
            if (i < size - 1) node.next = queue[0];
            // add children of the current node to the queue
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
    }
    return root;
}

function flatten(root) {
    if (!root) return;
    // recursively flatten the left and right subtrees
    flatten(root.left);
    flatten(root.right);
    // if the left subtree is not empty, move it to the right of the current node
    if (root.left) {
        // find the rightmost node in the left subtree
        let rightmost = root.left;
        while (rightmost.right) rightmost = rightmost.right;
        // reassign the right child of the rightmost node to the current right child
        rightmost.right = root.right;
        // reassign the right child of the current node to the left child
        root.right = root.left;
        // set the left child of the current node to null
        root.left = null;
    }
}

function pathSum(root, targetSum) {
    let result = [];
    function dfs(node, currentPath, currentSum) {
        // if the current node is null, return immediately
        if (!node) return;
        // add the current node's value to the current path and sum
        currentPath.push(node.val);
        currentSum += node.val;
        // if the current node is a leaf and the current sum equals the target sum, add the current path to the result
        if (!node.left && !node.right && currentSum === targetSum) result.push([...currentPath]);
        // recursively explore the left and right subtrees
        dfs(node.left, currentPath, currentSum);
        dfs(node.right, currentPath, currentSum);
        // remove the current node from the current path to backtrack
        currentPath.pop();
    }
    dfs(root, [], 0);
    return result;
}

function numDistinct(s, t) {
    let sLength = s.length;
    let tLength = t.length;
    let dp = Array(tLength + 1).fill(0).map(() => Array(sLength + 1).fill(0));
    // initialize base case where t is empty, there's one way to match it
    for (let j = 0; j <= sLength; j++) {
        dp[0][j] = 1;
    }
    // fill up dp table in a bottom-up manner
    for (let i = 1; i <= tLength; i++) {
        for (let j = 1; j <= sLength; j++) {
            // if current characters in s and t match, consider two cases: include or exclude current character in s
            if (t[i - 1] === s[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1];
            } 
            // if current characters don't match, we can only exclude current character in s
            else {
                dp[i][j] = dp[i][j - 1];
            }
        }
    }
    // the answer is stored in the bottom-right corner of the dp table
    return dp[tLength][sLength];
}

function fourSum(nums, target) {
    nums.sort((a, b) => a - b); // sort the array to apply two-pointer technique
    let result = [];
    for (let i = 0; i < nums.length - 3; i++) { // iterate over the array with four pointers
        if (i > 0 && nums[i] === nums[i - 1]) continue; // skip duplicates for the first pointer
        for (let j = i + 1; j < nums.length - 2; j++) { // iterate over the remaining array
            if (j > i + 1 && nums[j] === nums[j - 1]) continue; // skip duplicates for the second pointer
            let left = j + 1, right = nums.length - 1; // initialize two pointers
            while (left < right) { // apply two-pointer technique
                let sum = nums[i] + nums[j] + nums[left] + nums[right]; // calculate the sum of four elements
                if (sum < target) left++; // move the left pointer to increase the sum
                else if (sum > target) right--; // move the right pointer to decrease the sum
                else { // if the sum equals the target, add the quadruplet to the result
                    result.push([nums[i], nums[j], nums[left], nums[right]]);
                    while (left < right && nums[left] === nums[left + 1]) left++; // skip duplicates for the third pointer
                    while (left < right && nums[right] === nums[right - 1]) right--; // skip duplicates for the fourth pointer
                    left++; right--; // move both pointers
                }
            }
        }
    }
    return result;
}

function maxProfit(prices) {
