  return maxProfit;
}

function generatePascalTriangle(numRows) {
    let pascalTriangle = [[1]];
    // generate each row based on the previous row
    for (let i = 1; i < numRows; i++) {
        let currentRow = [1];
        // calculate the middle elements of the current row
        for (let j = 1; j < i; j++) {
            currentRow.push(pascalTriangle[i - 1][j - 1] + pascalTriangle[i - 1][j]);
        }
        currentRow.push(1);
        pascalTriangle.push(currentRow);
    }
    return pascalTriangle;
}

function getRow(rowIndex) {
