}

function minimumTotal(triangle) {
    let n = triangle.length;
    let dp = new Array(n);
    for (let i = 0; i < n; i++) {
        dp[i] = new Array(triangle[i].length).fill(0);
    }
    dp[0][0] = triangle[0][0]; // initialize the first row
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < triangle[i].length; j++) {
            // for each element, calculate the minimum sum by considering the two possible paths from the previous row
            if (j === 0) {
                dp[i][j] = dp[i-1][j] + triangle[i][j];
            } else if (j === triangle[i].length - 1) {
                dp[i][j] = dp[i-1][j-1] + triangle[i][j];
            } else {
                dp[i][j] = Math.min(dp[i-1][j-1], dp[i-1][j]) + triangle[i][j];
            }
        }
    }
    // find the minimum sum in the last row
    let minSum = dp[n-1][0];
    for (let i = 1; i < triangle[n-1].length; i++) {
        minSum = Math.min(minSum, dp[n-1][i]);
    }
    return minSum;
}

function maxProfit(prices) {
