    function dfs(node) {
        if (node === null) return 0;
        let leftSum = Math.max(dfs(node.left), 0);
        let rightSum = Math.max(dfs(node.right), 0);
        maxSum = Math.max(maxSum, node.val + leftSum + rightSum);
        return node.val + Math.max(leftSum, rightSum);
    }
    dfs(root);
    return maxSum;
}

function isPalindrome(s) {
    let left = 0, right = s.length - 1;
    while (left < right) { 
        // if left character is not alphanumeric, move to the next one
        if (!isAlphanumeric(s[left])) left++;
        // if right character is not alphanumeric, move to the previous one
        else if (!isAlphanumeric(s[right])) right--;
        // if characters at left and right are not equal, return false
        else if (s[left].toLowerCase() !== s[right].toLowerCase()) return false;
        // if characters match, move both pointers
        else left++, right--;
    }
    return true;
}

function isAlphanumeric(char) {
    return (char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || (char >= '0' && char <= '9');
}

function longestConsecutive(nums) {
    let numSet = new Set(nums);
    let longestStreak = 0;
    for (let num of numSet) {
        // check if it's the start of a sequence
        if (!numSet.has(num - 1)) {
            let currentNum = num;
            let currentStreak = 1;
            // check numbers that are consecutive to currentNum
            while (numSet.has(currentNum + 1)) {
                currentNum += 1;
                currentStreak += 1;
            }
            longestStreak = Math.max(longestStreak, currentStreak);
        }
    }
    return longestStreak;
}

function sumNumbers(root) {
    function dfs(node, currentNumber) {
