        if (node === null) return 0;
        // append the current node's value to the current number
        currentNumber = currentNumber * 10 + node.val;
        // if the node is a leaf node, return the current number
        if (node.left === null && node.right === null) return currentNumber;
        // recursively traverse the left and right subtrees
        return dfs(node.left, currentNumber) + dfs(node.right, currentNumber);
    }
    // start the depth-first search from the root node
    return dfs(root, 0);
}

function ladderLength(beginWord, endWord, wordList) {
    let wordSet = new Set(wordList); // convert wordList to a set for faster lookup
    let queue = [[beginWord, 1]]; // initialize queue with beginWord and length 1
    while (queue.length > 0) { 
        // dequeue the first word and its length
        let [word, length] = queue.shift();
        // if the word is the endWord, return its length
        if (word === endWord) return length;
        // generate all possible words by changing one character
        for (let i = 0; i < word.length; i++) { 
            // for each character in the word
            for (let j = 0; j < 26; j++) { 
                // for each possible character
                let nextWord = word.slice(0, i) + String.fromCharCode(97 + j) + word.slice(i + 1);
                // if the next word is in the wordSet
                if (wordSet.has(nextWord)) { 
                    // add it to the queue and remove it from the wordSet
                    queue.push([nextWord, length + 1]);
                    wordSet.delete(nextWord);
                }
            }
        }
    }
    // if no transformation sequence is found, return 0
    return 0;
}

function findLadders(beginWord, endWord, wordList) {
    let wordSet = new Set(wordList);
    if (!wordSet.has(endWord)) return [];
    let queue = [[beginWord]];
    let visited = new Set([beginWord]);
    let shortestPathLength = Infinity;
    let result = [];
    while (queue.length > 0) {
        let path = queue.shift();
        let currentWord = path[path.length - 1];
        // generate all possible words by changing one character at a time
        for (let i = 0; i < currentWord.length; i++) {
            for (let j = 0; j < 26; j++) {
                let nextWord = currentWord.slice(0, i) + String.fromCharCode(97 + j) + currentWord.slice(i + 1);
                if (wordSet.has(nextWord) && !visited.has(nextWord)) {
                    // if we found the endWord, update the result if the path is shorter
                    if (nextWord === endWord) {
                        if (path.length + 1 < shortestPathLength) {
                            shortestPathLength = path.length + 1;
                            result = [path.concat([nextWord])];
                        } else if (path.length + 1 === shortestPathLength) {
                            result.push(path.concat([nextWord]));
                        }
                    } else {
                        queue.push(path.concat([nextWord]));
                        visited.add(nextWord);
                    }
                }
            }
        }
    }
    return result;
}

function solve(board) {
    if (!board || board.length === 0) return;

    const rows = board.length;
    const cols = board[0].length;

    // Mark all 'O' regions connected to the border as 'N' (not captured)
    for (let i = 0; i < rows; i++) {
        // Check the first and last column for 'O' regions
        if (board[i][0] === 'O') dfs(board, i, 0);
        if (board[i][cols - 1] === 'O') dfs(board, i, cols - 1);
    }
    for (let j = 0; j < cols; j++) {
        // Check the first and last row for 'O' regions
        if (board[0][j] === 'O') dfs(board, 0, j);
        if (board[rows - 1][j] === 'O') dfs(board, rows - 1, j);
    }

    // Capture all 'O' regions and convert 'N' regions back to 'O'
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // If the region is 'O', it's surrounded, so capture it
            if (board[i][j] === 'O') board[i][j] = 'X';
            // If the region is 'N', it's not captured, so convert it back to 'O'
            else if (board[i][j] === 'N') board[i][j] = 'O';
        }
    }
}

// Helper function to perform DFS
function dfs(board, i, j) {
    const rows = board.length;
    const cols = board[0].length;

    // Check if the current position is within the board and is an 'O' region
    if (i < 0 || i >= rows || j < 0 || j >= cols || board[i][j] !== 'O') return;

    // Mark the current 'O' region as 'N' (not captured)
    board[i][j] = 'N';

    // Perform DFS on the neighboring 'O' regions
    dfs(board, i - 1, j); // Up
    dfs(board, i + 1, j); // Down
    dfs(board, i, j - 1); // Left
    dfs(board, i, j + 1); // Right
}

function partition(s) {
    var result = [];
    function isPalindrome(str) {
        return str === str.split('').reverse().join('');
    }
    function backtrack(start, path) {
        // if we have processed the entire string, add the current partition to the result
        if (start === s.length) result.push([...path]);
        for (var i = start; i < s.length; i++) {
            // get the current substring
            var substring = s.substring(start, i + 1);
            // if the substring is a palindrome, add it to the current partition
            if (isPalindrome(substring)) {
                // add the current substring to the current partition
                path.push(substring);
                // recursively process the remaining part of the string
                backtrack(i + 1, path);
                // remove the last substring from the current partition for backtracking
                path.pop();
            }
        }
    }
    backtrack(0, []);
    return result;
}

function cloneGraph(node) {
    if (!node) return null;
    const visited = new Map();
    function dfs(node) {
        // Create a new node if it's not visited before
        if (!visited.has(node)) {
            const newNode = { val: node.val, neighbors: [] };
            visited.set(node, newNode);
            // Recursively clone all neighbors
            for (let neighbor of node.neighbors) {
                // If the neighbor is not visited, clone it first
                if (!visited.has(neighbor)) dfs(neighbor);
                // Add the cloned neighbor to the new node's neighbors
                newNode.neighbors.push(visited.get(neighbor));
            }
        }
        // Return the cloned node
        return visited.get(node);
    }
    return dfs(node);
}

function canCompleteCircuit(gas, cost) {
    let totalGas = 0, totalCost = 0, tank = 0, start = 0;
    for (let i = 0; i < gas.length; i++) {
        // calculate the total gas and cost to check if it's possible to complete the circuit
        totalGas += gas[i];
        totalCost += cost[i];
        tank += gas[i] - cost[i];
        // if the tank is empty, reset the start point
        if (tank < 0) {
            start = i + 1;
            tank = 0;
        }
    }
    // if the total gas is less than the total cost, it's impossible to complete the circuit
    if (totalGas < totalCost) return -1;
    return start;
}

function minCut(s) {
    const n = s.length;
    const isPalindrome = Array(n).fill(0).map(() => Array(n).fill(false));
    const dp = Array(n).fill(0);

    // initialize isPalindrome array by checking all substrings
    for (let i = n - 1; i >= 0; i--) {
        for (let j = i; j < n; j++) {
            // a substring is a palindrome if it has one character, or its first and last characters are the same and the substring in between is a palindrome
            isPalindrome[i][j] = s[i] === s[j] && (j - i < 2 || isPalindrome[i + 1][j - 1]);
        }
    }

    // initialize dp array with the maximum possible cuts for each substring
    for (let i = 0; i < n; i++) {
        dp[i] = i; // the maximum possible cuts for a substring of length i + 1 is i
    }

    // update dp array by checking all substrings
    for (let i = 0; i < n; i++) {
        // if the substring from the start to the current index is a palindrome, we don't need any cuts
        if (isPalindrome[0][i]) {
            dp[i] = 0;
        } else {
            // otherwise, we try to find the minimum cuts by checking all possible partitions
            for (let j = 0; j < i; j++) {
                // if the substring from the start to the current index j is a palindrome, we update dp[i] with the minimum cuts
                if (isPalindrome[j + 1][i]) {
                    dp[i] = Math.min(dp[i], dp[j] + 1);
                }
            }
        }
    }

    // return the minimum cuts for the entire string
    return dp[n - 1];
}

function candy(ratings) {
  let n = ratings.length;
  let candies = new Array(n).fill(1); // initialize each child with 1 candy
  // iterate through the ratings from left to right to ensure each child gets more candies than the previous one if they have a higher rating
  for (let i = 1; i < n; i++) {
    if (ratings[i] > ratings[i - 1]) candies[i] = candies[i - 1] + 1;
  }
  // iterate through the ratings from right to left to ensure each child gets more candies than the next one if they have a higher rating
  for (let i = n - 2; i >= 0; i--) {
    if (ratings[i] > ratings[i + 1]) candies[i] = Math.max(candies[i], candies[i + 1] + 1);
  }
  // calculate the total number of candies
