            // calculate the slope of the line passing through the current two points
            let slope = calculateSlope(points[i], points[j]);
            // if the two points are the same, increment the samePoint counter
            if (slope === 'inf' && points[i][0] === points[j][0] && points[i][1] === points[j][1]) {
                samePoint++;
            } else {
