function calculateMinimumHP(dungeon) {
    var rows = dungeon.length;
    var cols = dungeon[0].length;
    var dp = new Array(rows).fill(0).map(() => new Array(cols).fill(0));
    // initialize the last cell with the maximum of 1 and the value in the last cell plus 1
    dp[rows - 1][cols - 1] = Math.max(1, 1 - dungeon[rows - 1][cols - 1]);
    // fill the last row from right to left
    for (var j = cols - 2; j >= 0; j--) {
        // for each cell, calculate the minimum health required to reach the next cell
        dp[rows - 1][j] = Math.max(1, dp[rows - 1][j + 1] - dungeon[rows - 1][j]);
    }
    // fill the last column from bottom to top
    for (var i = rows - 2; i >= 0; i--) {
        // for each cell, calculate the minimum health required to reach the cell below
        dp[i][cols - 1] = Math.max(1, dp[i + 1][cols - 1] - dungeon[i][cols - 1]);
    }
    // fill the rest of the cells
    for (var i = rows - 2; i >= 0; i--) {
        for (var j = cols - 2; j >= 0; j--) {
            // for each cell, calculate the minimum health required to reach the cell below or to the right
            dp[i][j] = Math.max(1, Math.min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j]);
        }
    }
    // return the minimum health required to reach the princess
    return dp[0][0];
}

