function maxProfit(k, prices) {
  const n = prices.length;
  if (k >= n/2) {
    let maxProfit = 0;
    for (let i = 1; i < n; i++) {
      if (prices[i] > prices[i-1]) maxProfit += prices[i] - prices[i-1];
    }
    return maxProfit;
  }
  const dp = Array.from({length: n}, () => Array(2*k+1).fill(0));
  for (let i = 1; i < n; i++) {
    for (let j = 1; j <= k; j++) {
      let max = dp[i-1][2*j-1];
      for (let l = 0; l < i; l++) {
        max = Math.max(max, dp[l][2*j-2] + prices[i] - prices[l]);
      }
      dp[i][2*j-1] = max;

      dp[i][2*j] = Math.max(dp[i-1][2*j], dp[i][2*j-1]);
    }
  }
  return dp[n-1][2*k-1];
}

