        if (nums[mid] > nums[mid + 1]) { // if middle element is greater than next, peak must be on the left side
            right = mid;
        } else { // if middle element is not greater than next, peak must be on the right side
            left = mid + 1;
        }
    }
    return left;
}

function convertToTitle(columnNumber) {
    let result = '';
    // while loop to continuously divide columnNumber by 26 and append the corresponding character to result
    while (columnNumber > 0) {
        // subtract 1 from columnNumber because Excel column titles are 1-indexed, but our calculation is 0-indexed
        let remainder = (columnNumber - 1) % 26;
        // convert remainder to corresponding character and prepend to result
        result = String.fromCharCode(65 + remainder) + result;
        // update columnNumber for next iteration
        columnNumber = Math.floor((columnNumber - 1) / 26);
    }
    return result;
}

