    return result;
}

function fractionToDecimal(numerator, denominator) {
    if (numerator === 0) return '0';
    let result = '';
    // check if the result is negative
    if ((numerator > 0) !== (denominator > 0)) result += '-';
    // convert both numbers to positive
    numerator = Math.abs(numerator);
    denominator = Math.abs(denominator);
    // calculate the integer part
    result += Math.floor(numerator / denominator);
    // if there's no fractional part, return the result
    let remainder = numerator % denominator;
    if (remainder === 0) return result;
    result += '.';
    // use a hash map to store the remainders and their corresponding indices
    let map = {};
    let fractionalPart = '';
    // calculate the fractional part
    while (remainder !== 0) {
        // if the remainder is already in the map, it means we've found a repeating part
        if (map[remainder] !== undefined) {
            // insert the parentheses at the correct position
            fractionalPart = fractionalPart.substring(0, map[remainder]) + '(' + fractionalPart.substring(map[remainder]) + ')';
            break;
        }
        // store the remainder and its index
        map[remainder] = fractionalPart.length;
        // calculate the next digit of the fractional part
        remainder *= 10;
        fractionalPart += Math.floor(remainder / denominator);
        remainder %= denominator;
    }
    // add the fractional part to the result
    result += fractionalPart;
    return result;
}

