function rangeBitwiseAnd(left, right) {
    let shift = 0;
    // find the common prefix of left and right by shifting right until they are equal
    while (left < right) {
        // shift right and left to the right by one bit
        left >>= 1;
        right >>= 1;
        shift++;
    }
    // restore the common prefix to its original position
    return left << shift;
}

function rightSideView(root) {
    // Initialize an empty array to store the result
    let result = [];
    // Initialize a helper function for depth-first search
    function dfs(node, depth) {
        // If the node is null, return immediately
        if (!node) return;
        // If the current depth is equal to the length of the result array, 
        // it means we've reached a new level, so add the node's value to the result
        if (depth === result.length) result.push(node.val);
        // Recursively call the dfs function on the right child and then the left child
        dfs(node.right, depth + 1); // right child first to get the rightmost node
        dfs(node.left, depth + 1);
    }
    // Call the dfs function on the root node with depth 0
    dfs(root, 0);
    // Return the result array
    return result;
}

function isHappy(n) {
  let seen = {};
  while (n !== 1 && !seen[n]) {
    // store the current number to detect cycles
    seen[n] = true;
    let sum = 0;
    // calculate the sum of the squares of the digits
    while (n) {
      let digit = n % 10;
      sum += digit * digit;
      n = Math.floor(n / 10);
    }
    n = sum;
  }
  // return true if the number is happy, false otherwise
  return n === 1;
}

function numIslands(grid) {
    let islandCount = 0;
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            // if we find a land cell, increment the island count and mark all connected land cells as visited
            if (grid[i][j] === '1') {
                islandCount++;
                dfs(grid, i, j);
            }
        }
    }
    return islandCount;
}

function dfs(grid, i, j) {
    // check if the current cell is within the grid boundaries and is a land cell
    if (i < 0 || j < 0 || i >= grid.length || j >= grid[0].length || grid[i][j] !== '1') {
        return;
    }
    // mark the current cell as visited by setting it to '0'
    grid[i][j] = '0';
    // recursively visit all adjacent land cells
    dfs(grid, i - 1, j); // up
    dfs(grid, i + 1, j); // down
    dfs(grid, i, j - 1); // left
    dfs(grid, i, j + 1); // right
}

function rob(nums) {
  if (nums.length === 0) return 0;
  if (nums.length === 1) return nums[0];
  let maxAmounts = new Array(nums.length);
  maxAmounts[0] = nums[0];
  maxAmounts[1] = Math.max(nums[0], nums[1]);
  // calculate the maximum amount that can be robbed up to each house
  for (let i = 2; i < nums.length; i++) {
    // choose the maximum between including the current house and excluding it
    maxAmounts[i] = Math.max(maxAmounts[i-1], maxAmounts[i-2] + nums[i]);
  }
  return maxAmounts[maxAmounts.length - 1];
}

function removeElements(head, val) {
  // if head is null, return null as there are no nodes to process
  if (head === null) return null;
  // recursively remove elements from the rest of the list
  head.next = removeElements(head.next, val);
  // if current node's value matches val, return the next node
  if (head.val === val) return head.next;
  // otherwise, return the current node
  return head;
}

function reverseList(head) {
  let previousNode = null;
  let currentNode = head;
  // Traverse the list and reverse the 'next' pointer of each node
  while (currentNode !== null) {
    let nextNode = currentNode.next;
    currentNode.next = previousNode;
    // Move to the next node
    previousNode = currentNode;
    currentNode = nextNode;
  }
  // At the end, 'previousNode' will be the new head of the reversed list
  return previousNode;
}

function canFinish(numCourses, prerequisites) {
    // Create a graph where each course is a node and prerequisites are directed edges
    const graph = Array.from({ length: numCourses }, () => []);
    for (const [course, prerequisite] of prerequisites) {
        graph[course].push(prerequisite);
    }

    // Initialize a visited array to keep track of visited courses
    const visited = Array(numCourses).fill(0);

    // Define a helper function to perform DFS
    function dfs(course) {
        // If the course is already marked as visiting, it means there's a cycle
        if (visited[course] === -1) return false;
        // If the course is already visited, return true
        if (visited[course] === 1) return true;

        // Mark the course as visiting
        visited[course] = -1;
        // Perform DFS on all prerequisites of the course
        for (const prerequisite of graph[course]) {
            // If any prerequisite has a cycle, return false
            if (!dfs(prerequisite)) return false;
        }
        // Mark the course as visited
        visited[course] = 1;
        return true;
    }

    // Perform DFS on all courses
    for (let i = 0; i < numCourses; i++) {
        // If any course has a cycle, return false
        if (!dfs(i)) return false;
    }
    return true;
}

function countPrimes(n) {
    if (n <= 2) return 0; // base case: numbers less than 2 are not prime
    let primes = new Array(n).fill(true); // assume all numbers are prime initially
    primes[0] = primes[1] = false; // 0 and 1 are not prime
    for (let i = 2; i * i < n; i++) { // only need to check up to sqrt(n)
        if (primes[i]) { // if i is prime
            for (let j = i * i; j < n; j += i) { // mark all multiples of i as not prime
                primes[j] = false;
            }
        }
    }
    let count = 0; // count the number of prime numbers
    for (let i = 0; i < n; i++) {
        if (primes[i]) count++;
    }
    return count;
}

function isIsomorphic(s, t) {
  if (s.length !== t.length) return false;
  var sToTMap = {};
  var tToSMap = {};
  for (var i = 0; i < s.length; i++) {
    // check if character in s is already mapped to a character in t
    if (sToTMap[s[i]] !== undefined && sToTMap[s[i]] !== t[i]) return false;
    // check if character in t is already mapped to a character in s
    if (tToSMap[t[i]] !== undefined && tToSMap[t[i]] !== s[i]) return false;
    sToTMap[s[i]] = t[i];
    tToSMap[t[i]] = s[i];
  }
  return true;
}

