function minSubArrayLen(target, nums) {
    let left = 0, minLen = Infinity, currentSum = 0;
    for (let right = 0; right < nums.length; right++) {
        currentSum += nums[right]; // add elements to the current window
        while (currentSum >= target) {
            minLen = Math.min(minLen, right - left + 1); // update minimum length
            currentSum -= nums[left]; // shrink the window from the left
            left++;
        }
    }
    return minLen === Infinity ? 0 : minLen; // return 0 if no such subarray exists
}

function shortestPalindrome(s) {
    let reversedS = s.split('').reverse().join(''); // create the reversed string
    for (let i = 0; i <= s.length; i++) { 
        // check if the substring of the reversed string is a prefix of the original string
        if (s.startsWith(reversedS.slice(i))) {
            return reversedS.slice(0, i) + s; // return the shortest palindrome
        }
    }
}

function findOrder(numCourses, prerequisites) {
    // Create a graph to store the prerequisites
    let graph = Array.from({ length: numCourses }, () => []);
    let visited = Array.from({ length: numCourses }, () => 0);
    let result = [];

    // Populate the graph with the prerequisites
    for (let [course, prerequisite] of prerequisites) {
        graph[prerequisite].push(course);
    }

    // Perform DFS on each unvisited course
    for (let i = 0; i < numCourses; i++) {
        // If the course is not visited, perform DFS
        if (visited[i] === 0) {
            if (!dfs(graph, visited, result, i)) {
                return [];
            }
        }
    }

    // Return the result in reverse order
    return result.reverse();
}

// Helper function to perform DFS
function dfs(graph, visited, result, course) {
    // Mark the course as visiting
    visited[course] = 1;

    // Visit all the neighboring courses
    for (let neighbor of graph[course]) {
        // If the neighboring course is visiting, it means there's a cycle
        if (visited[neighbor] === 1) {
            return false;
        }
        // If the neighboring course is not visited, perform DFS
        if (visited[neighbor] === 0) {
            if (!dfs(graph, visited, result, neighbor)) {
                return false;
            }
        }
    }

    // Mark the course as visited and add it to the result
    visited[course] = 2;
    result.push(course);
    return true;
}

function rob(nums) {
    // handle edge cases
    if (nums.length === 1) return nums[0];
    if (nums.length === 2) return Math.max(nums[0], nums[1]);

    // define a helper function to calculate the maximum amount of money that can be robbed
    function helper(nums) {
        let dp = new Array(nums.length).fill(0);
        dp[0] = nums[0];
        dp[1] = Math.max(nums[0], nums[1]);
        // calculate the maximum amount of money that can be robbed for each house
        for (let i = 2; i < nums.length; i++) {
            dp[i] = Math.max(dp[i-1], dp[i-2] + nums[i]);
        }
        return dp[nums.length - 1];
    }

    // calculate the maximum amount of money that can be robbed for two cases: 
    // 1. the first house is robbed and the last house is not robbed
    // 2. the first house is not robbed and the last house is robbed
    return Math.max(helper(nums.slice(0, nums.length - 1)), helper(nums.slice(1)));
}

function findKthLargest(nums, k) {
  function quickSelect(left, right, k) {
    // Select a pivot and partition the array around it
    let pivotIndex = partition(left, right);
    // If the pivot is at the kth position, return the pivot
    if (k === pivotIndex) return nums[k];
    // If the kth position is on the left side of the pivot, recurse on the left side
    else if (k < pivotIndex) return quickSelect(left, pivotIndex - 1, k);
    // If the kth position is on the right side of the pivot, recurse on the right side
    else return quickSelect(pivotIndex + 1, right, k);
  }

  function partition(left, right) {
    // Choose the middle element as the pivot
    let pivot = nums[Math.floor((left + right) / 2)];
    // Move all elements smaller than the pivot to the left and all elements larger to the right
    let i = left, j = right;
    while (i <= j) {
      // Find an element on the left that is larger than the pivot
      while (nums[i] < pivot) i++;
      // Find an element on the right that is smaller than the pivot
      while (nums[j] > pivot) j--;
      // Swap the two elements
      if (i <= j) {
        let temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
        i++;
        j--;
      }
    }
    // Return the final index of the pivot
    return i - 1;
  }

  // Call the quickSelect function with the initial range and k
  return quickSelect(0, nums.length - 1, nums.length - k);
}

