WordDictionary.prototype.searchHelper = function(node, word, index) {
    // if we've reached the end of the word and the current node is marked as the end of a word, return true
    if (index === word.length) return node.end === true;
    let char = word[index];
    // if the current character is a dot, recursively search all possible branches
    if (char === '.') {
        for (let key in node) {
            // skip the 'end' property
            if (key === 'end') continue;
            // if any branch returns true, return true
            if (this.searchHelper(node[key], word, index + 1)) return true;
        }
        // if no branch returns true, return false
        return false;
    } else {
        // if the current character is not a dot, recursively search the corresponding branch
        if (!node[char]) return false;
        return this.searchHelper(node[char], word, index + 1);
    }
}

function findWords(board, words) {
    const result = [];
    const trie = {};
    for (const word of words) {
        let node = trie;
        for (const char of word) {
            if (!node[char]) node[char] = {};
            node = node[char];
        }
        node.end = word;
    }
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    function backtrack(i, j, node) {
        // check if current character matches any character in the trie
        if (!node[board[i][j]]) return;
        node = node[board[i][j]];
        // if we've reached the end of a word, add it to the result
        if (node.end) {
            result.push(node.end);
            node.end = null; // avoid duplicates
        }
        // mark current cell as visited
        const temp = board[i][j];
        board[i][j] = '#';
        // explore all possible directions
        for (const [dx, dy] of directions) {
            const x = i + dx, y = j + dy;
            if (x >= 0 && x < board.length && y >= 0 && y < board[0].length) {
                backtrack(x, y, node);
            }
        }
        // backtrack and unmark current cell
        board[i][j] = temp;
    }
    for (let i = 0; i < board.length; i++) {
        for (let j = 0; j < board[0].length; j++) {
            backtrack(i, j, trie);
        }
    }
    return result;
}

