function containsNearbyAlmostDuplicate(nums, indexDiff, valueDiff) {
    // Create a bucket for each possible value range
    let buckets = {};
    for (let i = 0; i < nums.length; i++) {
        // Calculate the bucket id for the current number
        let bucketId = Math.floor(nums[i] / (valueDiff + 1));
        // Check if the current bucket or the adjacent buckets contain a number that satisfies the conditions
        if (buckets[bucketId] !== undefined || 
            (buckets[bucketId - 1] !== undefined && Math.abs(nums[i] - buckets[bucketId - 1]) <= valueDiff) || 
            (buckets[bucketId + 1] !== undefined && Math.abs(nums[i] - buckets[bucketId + 1]) <= valueDiff)) {
            return true;
        }
        // Add the current number to the bucket
        buckets[bucketId] = nums[i];
        // Remove the number that is out of the index range
        if (i >= indexDiff) {
            let oldBucketId = Math.floor(nums[i - indexDiff] / (valueDiff + 1));
            delete buckets[oldBucketId];
        }
    }
    return false;
}

