function backtrack(start, remainingSum, remainingCount, currentCombination, result) {
    // If we've found a valid combination, add it to the result
    if (remainingCount === 0 && remainingSum === 0) {
        result.push([...currentCombination]);
    } else {
        // Try numbers from start to 9 (since we're looking for combinations of single-digit numbers)
        for (let i = start; i <= 9; i++) {
            // If the current number exceeds the remaining sum, stop exploring this branch
            if (i > remainingSum) {
                break;
            }
            // Add the current number to the current combination
            currentCombination.push(i);
            // Recursively explore the next number
            backtrack(i + 1, remainingSum - i, remainingCount - 1, currentCombination, result);
            // Remove the current number from the current combination (backtrack)
            currentCombination.pop();
        }
    }
}

function maximalSquare(matrix) {
    if (!matrix || !matrix[0]) return 0;
    let rows = matrix.length, cols = matrix[0].length;
    let dp = Array(rows).fill().map(() => Array(cols).fill(0));
    let maxSide = 0;
    // initialize the first row and column of dp array
    for (let i = 0; i < rows; i++) {
        dp[i][0] = matrix[i][0] === '1' ? 1 : 0;
        maxSide = Math.max(maxSide, dp[i][0]);
    }
    for (let j = 0; j < cols; j++) {
        dp[0][j] = matrix[0][j] === '1' ? 1 : 0;
        maxSide = Math.max(maxSide, dp[0][j]);
    }
    // fill up the rest of the dp array
    for (let i = 1; i < rows; i++) {
        for (let j = 1; j < cols; j++) {
            // if current cell is '1', then the side of the square is the minimum of the top, left, and top-left cells plus one
            if (matrix[i][j] === '1') {
                dp[i][j] = Math.min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1;
                maxSide = Math.max(maxSide, dp[i][j]);
            }
        }
    }
    // return the area of the largest square
    return maxSide * maxSide;
}

