    points.sort((a, b) => a[0] === b[0] ? a[1] - b[1] : a[0] - b[0]);
    let result = [];
    let maxHeap = [0];
    let prevHeight = 0;
    for (let point of points) {
        if (point[1] > 0) {
            maxHeap.splice(maxHeap.indexOf(point[1]), 1);
        } else {
