    }
    // compare the nodes from the start and end of the array, moving towards the center
    let left = 0, right = nodes.length - 1;
    while (left < right) {
        if (nodes[left] !== nodes[right]) return false;
        left++; right--;
    }
    return true;
}

function lowestCommonAncestor(root, p, q) {
    // if both p and q are less than the current node, move to the left subtree
    if (p.val < root.val && q.val < root.val) return lowestCommonAncestor(root.left, p, q);
    // if both p and q are greater than the current node, move to the right subtree
    if (p.val > root.val && q.val > root.val) return lowestCommonAncestor(root.right, p, q);
    // if p and q are on different sides of the current node, or one of them is the current node, return the current node
    return root;
}

function deleteNode(node) {
