function lowestCommonAncestor(root, p, q) {
  // if the root is null, return null
  if (root === null) return null;
  // if the root is either p or q, return the root
  if (root === p || root === q) return root;
  // recursively find the LCA in the left and right subtrees
  let left = lowestCommonAncestor(root.left, p, q);
  let right = lowestCommonAncestor(root.right, p, q);
  // if both left and right are not null, return the root
  if (left !== null && right !== null) return root;
  // if only left is not null, return the left
  if (left !== null) return left;
  // if only right is not null, return the right
  if (right !== null) return right;
  // if both left and right are null, return null
  return null;
}

function productExceptSelf(nums) {
  const length = nums.length;
  const answer = new Array(length).fill(1);
  // calculate prefix product for each element
  for (let i = 1; i < length; i++) {
    answer[i] = answer[i - 1] * nums[i - 1];
  }
  let suffixProduct = 1;
  // calculate suffix product and multiply with prefix product
  for (let i = length - 1; i >= 0; i--) {
    answer[i] *= suffixProduct;
    suffixProduct *= nums[i];
  }
  return answer;
}

function maxSlidingWindow(nums, k) {
    let result = []; // store the max values for each window
    let deque = []; // store the indices of the elements in the current window
    for (let i = 0; i < nums.length; i++) {
        // remove the indices of the elements that are out of the current window
        while (deque.length > 0 && deque[0] < i - k + 1) deque.shift();
        // remove the indices of the elements that are smaller than the current element
        while (deque.length > 0 && nums[deque[deque.length - 1]] < nums[i]) deque.pop();
        // add the index of the current element to the deque
        deque.push(i);
        // add the max value of the current window to the result
        if (i >= k - 1) result.push(nums[deque[0]]); // get the max value from the front of the deque
    }
    return result;
}

function searchMatrix(matrix, target) {
  for (let row = 0; row < matrix.length; row++) {
    // start searching from the top-right corner of the current row
    let left = 0, right = matrix[row].length - 1;
    while (left <= right) {
      // calculate the middle index
      let mid = Math.floor((left + right) / 2);
      // compare the middle element with the target
      if (matrix[row][mid] === target) return true;
      // if the middle element is greater than the target, move to the left half
      else if (matrix[row][mid] > target) right = mid - 1;
      // if the middle element is less than the target, move to the right half
      else left = mid + 1;
    }
  }
  return false;
}

function diffWaysToCompute(expression) {
    let memo = {};
    function compute(expression) {
        // if expression is already computed, return the result
        if (expression in memo) return memo[expression];
        let results = [];
        // if expression is a number, return it
        if (!isNaN(expression)) {
            results.push(parseInt(expression));
        } else {
            // iterate over the expression to find operators
            for (let i = 0; i < expression.length; i++) {
                // if the character is an operator
                if (expression[i] === '-' || expression[i] === '+' || expression[i] === '*') {
                    // recursively compute the left and right parts
                    let left = compute(expression.substring(0, i));
                    let right = compute(expression.substring(i + 1));
                    // combine the results based on the operator
                    for (let l of left) {
                        for (let r of right) {
                            if (expression[i] === '+') results.push(l + r);
                            else if (expression[i] === '-') results.push(l - r);
                            else if (expression[i] === '*') results.push(l * r);
                        }
                    }
                }
            }
        }
        // store the result in memo
        memo[expression] = results;
        return results;
    }
    return compute(expression);
}

function isAnagram(s, t) {
    // If the two strings have different lengths, they cannot be anagrams
    if (s.length !== t.length) return false;
    // Create a hash table to store the frequency of each character in the first string
    let charFrequency = {};
    // Populate the hash table with the characters from the first string
    for (let char of s) {
        // If the character is already in the hash table, increment its count; otherwise, add it with a count of 1
        charFrequency[char] = (charFrequency[char] || 0) + 1;
    }
    // Iterate over the second string and decrement the count of each character in the hash table
    for (let char of t) {
        // If the character is not in the hash table or its count is 0, the strings are not anagrams
        if (!charFrequency[char] || charFrequency[char] === 0) return false;
        // Decrement the count of the character in the hash table
        charFrequency[char]--;
    }
    // If we have iterated over both strings without returning false, they are anagrams
    return true;
}

