function singleNumber(nums) {
    // calculate the XOR of all numbers to get the XOR of the two single numbers
    let xorResult = 0;
    for (let num of nums) {
        xorResult ^= num;
    }

    // find the rightmost set bit in the XOR result
    let rightmostSetBit = xorResult & -xorResult;

    // divide the numbers into two groups based on the rightmost set bit
    let singleNumber1 = 0, singleNumber2 = 0;
    for (let num of nums) {
        // if the rightmost set bit is set, put the number in the first group
        if (num & rightmostSetBit) {
            singleNumber1 ^= num;
        } 
        // otherwise, put the number in the second group
        else {
            singleNumber2 ^= num;
        }
    }

    return [singleNumber1, singleNumber2];
}

function nthUglyNumber(n) {
  let uglyNumbers = [1];
  let i2 = 0, i3 = 0, i5 = 0;
  // generate next ugly number by multiplying the smallest ugly number with 2, 3, or 5
  while (uglyNumbers.length < n) {
    let nextUgly = Math.min(uglyNumbers[i2] * 2, uglyNumbers[i3] * 3, uglyNumbers[i5] * 5);
    uglyNumbers.push(nextUgly);
    // move the pointer of the smallest ugly number that generates the next ugly number
    if (nextUgly === uglyNumbers[i2] * 2) i2++;
    if (nextUgly === uglyNumbers[i3] * 3) i3++;
    if (nextUgly === uglyNumbers[i5] * 5) i5++;
  }
  return uglyNumbers[n - 1];
}

