function hIndex(citations) {
    let left = 0, right = citations.length - 1;
    // calculate the possible h-index for the middle element
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        // if the number of papers is greater than or equal to the citations, move to the right half
        if (citations.length - mid <= citations[mid]) {
            right = mid - 1;
        } 
        // if the number of papers is less than the citations, move to the left half
        else {
            left = mid + 1;
        }
    }
