function numSquares(n) {
    let dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        let j = 1; 
        // generate all perfect squares less than or equal to i
        while (j * j <= i) {
            // update dp[i] with the minimum of its current value and 1 plus the number of perfect squares that sum to i - j * j
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
            j++;
        }
    }
    return dp[n];
}

