function addOperators(num, target) {
    let result = [];
    function backtrack(index, path, value, prev) {
        // if we've processed the entire string and the current value equals the target, add the path to the result
        if (index === num.length && value === target) {
            result.push(path);
            return;
        }
        // if we've processed the entire string but the current value doesn't equal the target, return
        if (index === num.length) return;
        // try to add a number to the current path
        for (let i = index; i < num.length; i++) {
            // if the current number starts with 0 and has more than one digit, skip it
            if (i !== index && num[index] === '0') break;
            let currNum = parseInt(num.substring(index, i + 1));
            // if this is the first number in the path, add it directly
            if (path === '') {
                backtrack(i + 1, path + currNum, currNum, currNum);
            } else {
                // try to add the current number to the path with '+', '-', and '*'
                backtrack(i + 1, path + '+' + currNum, value + currNum, currNum);
                backtrack(i + 1, path + '-' + currNum, value - currNum, -currNum);
                backtrack(i + 1, path + '*' + currNum, value - prev + prev * currNum, prev * currNum);
            }
        }
    }
    backtrack(0, '', 0, 0);
    return result;
}

