        if (!(pattern[i] in patternToWord)) patternToWord[pattern[i]] = words[i];
        // if wordToPattern does not have the current word, add it to the hash table
        if (!(words[i] in wordToPattern)) wordToPattern[words[i]] = pattern[i];
