// Native binary heap (no external dependency -- see fresh_implementation note)
function Heap(compare) {
    this.data = [];
    this.compare = compare;
}
Heap.prototype.size = function(){ return this.data.length; };
Heap.prototype.top = function(){ return this.data[0]; };
Heap.prototype.push = function(val) {
    this.data.push(val);
    let i = this.data.length - 1;
    while (i > 0) {
        let p = (i - 1) >> 1;
        if (this.compare(this.data[i], this.data[p]) < 0) { [this.data[i], this.data[p]] = [this.data[p], this.data[i]]; i = p; }
        else break;
    }
};
Heap.prototype.pop = function() {
    const top = this.data[0];
    const last = this.data.pop();
    if (this.data.length > 0) {
        this.data[0] = last;
        let i = 0;
        while (true) {
            let l = 2 * i + 1, r = 2 * i + 2, smallest = i;
            if (l < this.data.length && this.compare(this.data[l], this.data[smallest]) < 0) smallest = l;
            if (r < this.data.length && this.compare(this.data[r], this.data[smallest]) < 0) smallest = r;
            if (smallest === i) break;
            [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]]; i = smallest;
        }
    }
    return top;
};

function MedianFinder() {
