    else this.minHeap.push(num);
    if (this.maxHeap.size() > this.minHeap.size() + 1) this.minHeap.push(this.maxHeap.pop());
    else if (this.minHeap.size() > this.maxHeap.size()) this.maxHeap.push(this.minHeap.pop());
};
MedianFinder.prototype.findMedian = function() {
    if (this.maxHeap.size() === this.minHeap.size()) return (this.maxHeap.top() + this.minHeap.top()) / 2;
    return this.maxHeap.top();
};

function serialize(root) {
    if (!root) return 'X,';
    return root.val + ',' + serialize(root.left) + serialize(root.right);
}

function deserialize(data) {
    let nodes = data.split(',');
    let index = 0;
    function buildTree() {
        // if the current node is null, return null
        if (nodes[index] === 'X') {
            index++;
            return null;
        }
        // create a new node with the current value
        let node = new TreeNode(parseInt(nodes[index]));
        index++;
        // recursively build the left and right subtrees
        node.left = buildTree();
        node.right = buildTree();
        return node;
    }
    return buildTree();
}

function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

function getHint(secret, guess) {
    let bulls = 0;
    let cows = 0;
    let secretCount = {};
    let guessCount = {};
    // create frequency maps for secret and guess
    for (let i = 0; i < secret.length; i++) {
        if (secret[i] === guess[i]) {
            // if digits match at the same position, increment bulls
            bulls++;
        } else {
            // count the occurrences of each digit in secret and guess
            secretCount[secret[i]] = (secretCount[secret[i]] || 0) + 1;
            guessCount[guess[i]] = (guessCount[guess[i]] || 0) + 1;
        }
    }
    // calculate cows by finding the minimum count of each digit in secret and guess
    for (let key in secretCount) {
        if (key in guessCount) {
            cows += Math.min(secretCount[key], guessCount[key]);
        }
    }
    // return the hint in the required format
    return bulls + "A" + cows + "B";
}

function lengthOfLIS(nums) {
    if (nums.length === 0) return 0;
    let dp = new Array(nums.length).fill(1);
    for (let i = 1; i < nums.length; i++) {
        for (let j = 0; j < i; j++) 
            // if current element is greater than previous, update dp[i] if necessary
            if (nums[i] > nums[j]) dp[i] = Math.max(dp[i], dp[j] + 1);
    }
    // return the maximum length found in dp array
    return Math.max(...dp);
}

function removeInvalidParentheses(s) {
    let level = { [s]: 1 };
    while (true) {
        let valid = Object.keys(level).filter(str => isValid(str));
        if (valid.length > 0) return valid;
        let nextLevel = {};
        for (let str in level) {
            // generate all possible strings by removing one parenthesis
            for (let i = 0; i < str.length; i++) {
                if (str[i] === '(' || str[i] === ')') {
                    let newStr = str.substring(0, i) + str.substring(i + 1);
                    if (!nextLevel[newStr]) nextLevel[newStr] = 1;
                }
            }
        }
        level = nextLevel;
    }
}

function isValid(s) {
    let count = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') count++;
        else if (s[i] === ')') {
            if (count === 0) return false;
            count--;
        }
    }
    return count === 0;
}

function NumArray(nums) {
