function NumMatrix(matrix) {
    this.matrix = matrix;
    this.prefixSum = [];
    for (let i = 0; i < matrix.length; i++) {
        this.prefixSum[i] = [];
        for (let j = 0; j < matrix[0].length; j++) {
            // calculate prefix sum for each cell by adding the current cell value to the sum of the cell above it and the cell to its left, then subtract the cell diagonally up and to the left to avoid double counting
            let sum = (i > 0 ? this.prefixSum[i - 1][j] : 0) + (j > 0 ? this.prefixSum[i][j - 1] : 0) - (i > 0 && j > 0 ? this.prefixSum[i - 1][j - 1] : 0) + matrix[i][j];
            this.prefixSum[i][j] = sum;
        }
    }
}

NumMatrix.prototype.sumRegion = function(row1, col1, row2, col2) {
    // calculate the sum of the region by taking the prefix sum of the bottom right cell, then subtract the prefix sum of the cell above the region and the cell to the left of the region, and finally add back the prefix sum of the cell diagonally up and to the left of the region to avoid double subtraction
    let sum = this.prefixSum[row2][col2] - (row1 > 0 ? this.prefixSum[row1 - 1][col2] : 0) - (col1 > 0 ? this.prefixSum[row2][col1 - 1] : 0) + (row1 > 0 && col1 > 0 ? this.prefixSum[row1 - 1][col1 - 1] : 0);
    return sum;
};

function isAdditiveNumber(num) {
    function isValid(num) {
        return !(num.length > 1 && num[0] === '0');
    }

    function backtrack(start, path) {
        // if we've reached the end of the string and have at least 3 numbers in the path, return true
        if (start === num.length && path.length >= 3) return true;

        for (let i = start; i < num.length; i++) {
            let currNum = num.substring(start, i + 1);
            // if the current number is not valid, skip it
            if (!isValid(currNum)) continue;

            // if the path has less than 2 numbers, add the current number to the path
            if (path.length < 2) {
                if (backtrack(i + 1, path.concat([currNum]))) return true;
            } 
            // if the path has at least 2 numbers, check if the current number is the sum of the last two numbers
            else if (BigInt(path[path.length - 1]) + BigInt(path[path.length - 2]) === BigInt(currNum)) {
                if (backtrack(i + 1, path.concat([currNum]))) return true;
            }
        }
        return false;
    }

    return backtrack(0, []);
}

function NumArray(nums) {
