    }
}

NumArray.prototype.update = function(index, val) {
    let diff = val - this.nums[index]; // calculate difference
    this.nums[index] = val;
    for (let i = index + 1; i < this.prefixSum.length; i++) {
        this.prefixSum[i] += diff; // update prefix sum
    }
}

