}

function maxProfit(prices) {
    let buy = -Infinity, sell = 0, cooldown = 0;
    for (let price of prices) {
        // update buy to be the maximum of current buy and cooldown - price (to buy the stock)
        let newBuy = Math.max(buy, cooldown - price);
        // update cooldown to be the maximum of current cooldown and sell (to cooldown after selling)
        let newCooldown = Math.max(cooldown, sell);
        // update sell to be the maximum of current sell and buy + price (to sell the stock)
        let newSell = Math.max(sell, buy + price);
        buy = newBuy;
        sell = newSell;
        cooldown = newCooldown;
    }
    // return the maximum of sell and cooldown (the maximum profit after all transactions)
    return Math.max(sell, cooldown);
}

function findMinHeightTrees(n, edges) {
    if (n === 1) return [0];
    let graph = new Array(n).fill(0).map(() => new Array());
    let degree = new Array(n).fill(0);
    for (let edge of edges) {
        graph[edge[0]].push(edge[1]);
        graph[edge[1]].push(edge[0]);
        degree[edge[0]]++;
        degree[edge[1]]++;
    }
    let queue = [];
    for (let i = 0; i < n; i++) {
        if (degree[i] === 1) queue.push(i); // add all leaf nodes to the queue
    }
    while (n > 2) {
        let size = queue.length;
        n -= size;
        for (let i = 0; i < size; i++) {
            let node = queue.shift();
            for (let neighbor of graph[node]) {
                degree[neighbor]--;
                if (degree[neighbor] === 1) queue.push(neighbor); // add new leaf nodes to the queue
            }
        }
    }
    return queue; // return the remaining nodes as the roots of MHTs
}

function removeDuplicateLetters(s) {
    let lastOccurrence = {};
    for (let i = 0; i < s.length; i++) {
        lastOccurrence[s[i]] = i;
    }
    let stack = [];
    let seen = {};
    for (let i = 0; i < s.length; i++) {
        // if the character is already in the stack, skip it
        if (seen[s[i]]) continue;
        // while the stack is not empty and the top of the stack is greater than the current character and it appears later
        while (stack.length > 0 && stack[stack.length - 1] > s[i] && lastOccurrence[stack[stack.length - 1]] > i) {
            // remove the top of the stack and mark it as unseen
            seen[stack.pop()] = false;
        }
        // push the current character to the stack and mark it as seen
        stack.push(s[i]);
        seen[s[i]] = true;
    }
    // join the stack into a string and return it
    return stack.join('');
}

function countSmallerNumbersAfterSelf(nums) {
    const n = nums.length;
    const indices = Array.from({ length: n }, (_, i) => i);
    const temp = new Array(n);
    const count = new Array(n).fill(0);
    function mergeSort(start, end) {
        if (start >= end) return;
        const mid = Math.floor((start + end) / 2);
        mergeSort(start, mid);
        mergeSort(mid + 1, end);
        let left = start, right = mid + 1, idx = start;
        while (left <= mid && right <= end) {
            if (nums[indices[left]] <= nums[indices[right]]) {
                count[indices[left]] += right - (mid + 1);
                temp[idx++] = indices[left++];
            } else {
                temp[idx++] = indices[right++];
            }
        }
        while (left <= mid) {
            count[indices[left]] += right - (mid + 1);
            temp[idx++] = indices[left++];
        }
        while (right <= end) temp[idx++] = indices[right++];
        for (let i = start; i <= end; i++) indices[i] = temp[i];
    }
    mergeSort(0, n - 1);
    return count;
}

function nthSuperUglyNumber(n, primes) {
  let uglyNumbers = [1];
  let indices = new Array(primes.length).fill(0);
  // generate the next super ugly number by multiplying the current ugly number with the smallest prime factor
  while (uglyNumbers.length < n) {
    let nextUgly = Infinity;
    for (let i = 0; i < primes.length; i++) {
      // calculate the next possible super ugly number for each prime factor
      nextUgly = Math.min(nextUgly, uglyNumbers[indices[i]] * primes[i]);
    }
    uglyNumbers.push(nextUgly);
    // update the indices for the prime factors that generated the next super ugly number
    for (let i = 0; i < primes.length; i++) {
      if (uglyNumbers[indices[i]] * primes[i] === nextUgly) {
        indices[i]++;
      }
    }
  }
  return uglyNumbers[uglyNumbers.length - 1];
}

function bulbSwitch(n) {
    let bulbs = new Array(n).fill(false); // initially all bulbs are off
    for (let i = 1; i <= n; i++) { 
        // toggle every i bulb
        for (let j = i - 1; j < n; j += i) {
            bulbs[j] = !bulbs[j]; // toggle the bulb
        }
    }
    let count = 0; 
    // count the number of bulbs that are on
    for (let i = 0; i < n; i++) {
        if (bulbs[i]) count++;
    }
    return count;
}

function coinChange(coins, amount) {
    let dp = new Array(amount + 1).fill(Infinity);
    dp[0] = 0; // base case: 0 coins needed to make 0 amount
    for (let i = 1; i <= amount; i++) {
        for (let coin of coins) {
            if (i - coin >= 0) { // check if we can use this coin
                dp[i] = Math.min(dp[i], dp[i - coin] + 1); // update dp array with the minimum number of coins
            }
        }
    }
    return dp[amount] === Infinity ? -1 : dp[amount]; // return -1 if amount cannot be made up
}

function wiggleSortII(nums) {
  const n = nums.length;
  const sorted = nums.slice().sort((a, b) => a - b);
  const mid = Math.floor((n - 1) / 2);
  const result = new Array(n);
  let j = mid, k = n - 1;
  for (let i = 0; i < n; i++) {
    if (i % 2 === 0) result[i] = sorted[j--];
    else result[i] = sorted[k--];
  }
  for (let i = 0; i < n; i++) nums[i] = result[i];
}

function isPowerOfThree(n) {
    // if n is less than or equal to 0, it cannot be a power of three
    if (n <= 0) return false;
    // recursively divide n by 3 until it is no longer divisible
    if (n % 3 === 0) return isPowerOfThree(n / 3);
    // if n is 1, it is a power of three (3^0 = 1)
    return n === 1;
}

