function countRangeSum(nums, lower, upper) {
    let count = 0;
    let sum = 0;
    let prefixSums = [0];
    // Create prefix sums array to store cumulative sum of elements
    for (let num of nums) {
        sum += num;
        prefixSums.push(sum);
    }
    // Initialize count and merge sort the prefix sums array
    return mergeSort(prefixSums, lower, upper, 0, prefixSums.length - 1);
}

function mergeSort(prefixSums, lower, upper, start, end) {
    let count = 0;
    if (start < end) {
        let mid = Math.floor((start + end) / 2);
        // Recursively sort the left and right halves
        count += mergeSort(prefixSums, lower, upper, start, mid);
        count += mergeSort(prefixSums, lower, upper, mid + 1, end);
        // Merge the sorted halves and count range sums
        count += merge(prefixSums, lower, upper, start, mid, end);
    }
    return count;
}

function merge(prefixSums, lower, upper, start, mid, end) {
    let count = 0;
    let left = start;
    let right = mid + 1;
    let temp = [];
    // Merge the sorted halves and count range sums
    while (left <= mid && right <= end) {
        if (prefixSums[right] - prefixSums[left] < lower) {
            left++;
        } else if (prefixSums[right] - prefixSums[left] > upper) {
            right++;
        } else {
            // Count the range sums that lie in [lower, upper]
            count++;
            left++;
            right++;
        }
    }
    return count;
}

function oddEvenList(head) {
    if (!head) return head;
    let odd = head, even = head.next, evenHead = even;
    // separate the linked list into two parts: odd and even
    while (even && even.next) {
        odd.next = even.next;
        odd = odd.next;
        even.next = odd.next;
        even = even.next;
    }
    // connect the odd list with the even list
    odd.next = evenHead;
    return head;
}

function longestIncreasingPath(matrix) {
    if (!matrix.length) return 0;
    const rows = matrix.length;
    const cols = matrix[0].length;
    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    const memo = Array(rows).fill().map(() => Array(cols).fill(0));

    function dfs(row, col) {
        // if we've already computed the longest path from this cell, return it
        if (memo[row][col] !== 0) return memo[row][col];
        let longestPath = 1;
        // explore all possible directions from the current cell
        for (const [dr, dc] of directions) {
            const nr = row + dr;
            const nc = col + dc;
            // if the new cell is within bounds and has a greater value, explore it
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && matrix[nr][nc] > matrix[row][col]) {
                // recursively find the longest path from the new cell and update our current longest path
                longestPath = Math.max(longestPath, 1 + dfs(nr, nc));
            }
        }
        // store the longest path from this cell in our memoization table
        memo[row][col] = longestPath;
        return longestPath;
    }

    let maxLength = 0;
    // start a depth-first search from each cell in the matrix
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // update our maximum length if we find a longer path
            maxLength = Math.max(maxLength, dfs(i, j));
        }
    }
    return maxLength;
}

function minPatches(nums, n) {
    let patchCount = 0, i = 0, miss = 1;
    // we start from 1 because we want to cover the range [1, n]
    while (miss <= n) {
        // if the current number in the array is less than or equal to the current miss
        if (i < nums.length && nums[i] <= miss) {
            // we can cover the range [miss, miss + nums[i]] by including the current number
            miss += nums[i];
            // move to the next number in the array
            i++;
        } else {
            // if the current number in the array is greater than the current miss
            // we need to patch the current miss to cover the range [miss, miss * 2]
            miss *= 2;
            // increment the patch count
            patchCount++;
        }
    }
    return patchCount;
}

function isValidSerialization(preorder) {
    let nodes = preorder.split(','); // split the string into an array of nodes
    let diff = 1; // initialize the difference between the number of nodes and the number of '#'
    for (let node of nodes) { // iterate over each node in the array
        // if the difference is 0, it means we have more '#' than nodes, so return false
        if (--diff < 0) return false; 
        if (node !== '#') diff += 2; // if the node is not '#', increase the difference by 2
    }
    // if the difference is 1, it means we have the correct number of '#' and nodes, so return true
    return diff === 0; 
}

function findItinerary(tickets) {
    // Create a graph from the tickets
    const graph = {};
    for (let i = 0; i < tickets.length; i++) {
        const [from, to] = tickets[i];
        if (!graph[from]) graph[from] = [];
        graph[from].push(to);
    }
    // Sort the destinations for each airport
    for (const airport in graph) {
        graph[airport].sort();
    }
    // Initialize the result and the current path
    const result = [];
    const path = ['JFK'];
    // Perform a depth-first search to find the itinerary
    function dfs() {
        // If we have used all the tickets, return true
        if (path.length - 1 === tickets.length) return true;
        // Get the current airport
        const currentAirport = path[path.length - 1];
        // If the current airport has no more destinations, return false
        if (!graph[currentAirport] || graph[currentAirport].length === 0) return false;
        // Try each destination
        for (let i = 0; i < graph[currentAirport].length; i++) {
            // Get the next destination
            const nextDestination = graph[currentAirport].shift();
            // Add the next destination to the path
            path.push(nextDestination);
            // If we can find a valid itinerary, return true
            if (dfs()) return true;
            // If not, backtrack
            path.pop();
            // Add the next destination back to the graph
            graph[currentAirport].unshift(nextDestination);
        }
        // If we cannot find a valid itinerary, return false
        return false;
    }
    // Perform the depth-first search
    dfs();
    // Return the result
    return path;
}

function increasingTripletSubsequence(nums) {
