    if (num <= firstMin) firstMin = num; 
    // update secondMin if we find a number larger than firstMin
    else if (num <= secondMin) secondMin = num; 
    // if we find a number larger than secondMin, we have a triplet
    else return true; 
  }
  return false; 
}

function isSelfCrossing(distance) {
    if (distance.length < 4) return false; // if less than 4 moves, no crossing is possible
    for (let i = 3; i < distance.length; i++) {
        // check if current line crosses the line 3 moves ago
        if (distance[i] >= distance[i-2] && distance[i-1] <= distance[i-3]) return true;
        // check if current line crosses the line 4 moves ago
        if (i >= 4 && distance[i-1] == distance[i-3] && distance[i] + distance[i-4] >= distance[i-2]) return true;
        // check if current line crosses the line 5 moves ago
        if (i >= 5 && distance[i-2] >= distance[i-4] && distance[i] + distance[i-4] >= distance[i-2] && distance[i-1] <= distance[i-3] && distance[i-1] + distance[i-5] >= distance[i-3]) return true;
    }
    return false;
}

function maxCoins(nums) {
    const n = nums.length;
    const balloons = [1, ...nums, 1];
    const dp = Array.from({ length: n + 2 }, () => new Array(n + 2).fill(0));
    for (let gap = 2; gap <= n + 1; gap++) {
        for (let left = 0; left + gap <= n + 1; left++) {
            const right = left + gap;
            for (let i = left + 1; i < right; i++) {
                dp[left][right] = Math.max(dp[left][right], balloons[left] * balloons[i] * balloons[right] + dp[left][i] + dp[i][right]);
            }
        }
    }
    return dp[0][n + 1];
}

function palindromePairs(words) {
    const indexMap = new Map();
    for (let i = 0; i < words.length; i++) indexMap.set(words[i], i);

    const isPalindrome = (s, l, r) => {
        while (l < r) { if (s[l] !== s[r]) return false; l++; r--; }
        return true;
    };

    const result = [];
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        const n = w.length;
        for (let cut = 0; cut <= n; cut++) {
            if (isPalindrome(w, cut, n - 1)) {
                const leftRev = w.substring(0, cut).split('').reverse().join('');
                if (indexMap.has(leftRev) && indexMap.get(leftRev) !== i) {
                    result.push([i, indexMap.get(leftRev)]);
                }
            }
            if (cut > 0 && isPalindrome(w, 0, cut - 1)) {
                const rightRev = w.substring(cut).split('').reverse().join('');
                if (indexMap.has(rightRev) && indexMap.get(rightRev) !== i) {
                    result.push([indexMap.get(rightRev), i]);
                }
            }
        }
    }
    return result;
}

function rob(root) {
    function dfs(node) {
        // base case: if the node is null, return [0, 0] representing the maximum amount of money that can be robbed with and without the current node
        if (!node) return [0, 0];

        // recursively calculate the maximum amount of money that can be robbed for the left and right subtrees
        const left = dfs(node.left);
        const right = dfs(node.right);

        // calculate the maximum amount of money that can be robbed with the current node
        const withCurrent = node.val + left[1] + right[1];

        // calculate the maximum amount of money that can be robbed without the current node
        const withoutCurrent = Math.max(left[0], left[1]) + Math.max(right[0], right[1]);

        // return the maximum amount of money that can be robbed with and without the current node
        return [withCurrent, withoutCurrent];
    }

    // call the dfs function and return the maximum amount of money that can be robbed
    return Math.max(...dfs(root));
}

class NestedIterator {
  constructor(nestedList) {
    function flatten(list) {
      let result = [];
      for (let element of list) {
        if (Array.isArray(element)) result = result.concat(flatten(element));
        else result.push(element);
      }
      return result;
    }
    this.flatList = flatten(nestedList);
    this.index = 0;
  }
  hasNext() { return this.index < this.flatList.length; }
  next() { return this.flatList[this.index++]; }
}

function isPowerOfFour(n) {
    if (n <= 0) return false; // check for invalid input
    while (n % 4 === 0) n /= 4; // keep dividing by 4 as long as it's divisible
    return n === 1; // if we're left with 1, then it's a power of four
}

function integerBreak(n) {
    if (n === 2) return 1; // base case: when n is 2, the maximum product is 1
    if (n === 3) return 2; // base case: when n is 3, the maximum product is 2
    let result = 1; 
    while (n > 4) { // keep breaking down n into 3s
        result *= 3;
        n -= 3;
    }
    result *= n; // multiply the remaining value of n
    return result;
}

function reverseString(s) {
  let leftPointer = 0; 
  let rightPointer = s.length - 1; 
  // Swap characters from the start and end of the string, moving towards the center
