}

function canMeasureWater(x, y, target) {
    // Create a queue for BFS, storing the current state of the jugs
    let queue = [[0, 0]];
    // Create a set to store visited states
    let visited = new Set(['0,0']);
    // Perform BFS
    while (queue.length > 0) {
        // Dequeue the current state
        let [currX, currY] = queue.shift();
        // If the current state matches the target, return true
        if (currX + currY === target) return true;
        // Generate next states by filling, emptying, or pouring water between jugs
        let nextStates = [
            [x, currY], // Fill the first jug
            [currX, y], // Fill the second jug
            [0, currY], // Empty the first jug
            [currX, 0], // Empty the second jug
            [Math.max(0, currX - (y - currY)), Math.min(y, currY + currX)], // Pour from the first jug to the second jug
            [Math.min(x, currX + currY), Math.max(0, currY - (x - currX))] // Pour from the second jug to the first jug
        ];
        // Add next states to the queue if they have not been visited
        for (let nextState of nextStates) {
            let nextStateStr = nextState.join(',');
            if (!visited.has(nextStateStr)) {
                queue.push(nextState);
                visited.add(nextStateStr);
            }
        }
    }
    // If no state matches the target, return false
    return false;
}

