    let mid = Math.floor((left + right) / 2);
    let square = mid * mid;
    // if the square is equal to num, return true
    if (square === num) return true;
    // if the square is less than num, move the left pointer
    else if (square < num) left = mid + 1;
    // if the square is greater than num, move the right pointer
    else right = mid - 1;
  }
  // if no perfect square is found, return false
  return false;
}

function largestDivisibleSubset(nums) {
    if (nums.length === 0) return [];
    nums.sort((a, b) => a - b);
    let dp = new Array(nums.length).fill(1);
    let prev = new Array(nums.length).fill(-1);
    let maxIndex = 0;
    // Initialize dp and prev arrays to store lengths and previous indices of subsets
    for (let i = 1; i < nums.length; i++) {
        for (let j = 0; j < i; j++) {
            // Check if current number is divisible by previous number and update dp and prev arrays
            if (nums[i] % nums[j] === 0 && dp[i] < dp[j] + 1) {
                dp[i] = dp[j] + 1;
                prev[i] = j;
            }
        }
        // Update maxIndex if current subset is larger
        if (dp[i] > dp[maxIndex]) maxIndex = i;
    }
    let result = [];
