// MinHeap implementation
function MinHeap() {
    this.heap = [];
}

MinHeap.prototype.insert = function(val) {
    this.heap.push(val);
    this.heapifyUp(this.heap.length - 1);
};

MinHeap.prototype.extractMin = function() {
    if (this.heap.length === 0) {
        return null;
    }
    if (this.heap.length === 1) {
        return this.heap.pop();
    }
    const min = this.heap[0];
    this.heap[0] = this.heap.pop();
    this.heapifyDown(0);
    return min;
};

MinHeap.prototype.size = function() {
    return this.heap.length;
};

MinHeap.prototype.heapifyUp = function(index) {
    while (index > 0) {
        const parentIndex = Math.floor((index - 1) / 2);
        if (this.heap[parentIndex][0] + this.heap[parentIndex][1] <= this.heap[index][0] + this.heap[index][1]) {
            break;
        }
        this.swap(parentIndex, index);
        index = parentIndex;
    }
};

MinHeap.prototype.heapifyDown = function(index) {
    while (true) {
        let smallest = index;
        const left = 2 * index + 1;
        const right = 2 * index + 2;
        if (left < this.heap.length && this.heap[left][0] + this.heap[left][1] < this.heap[smallest][0] + this.heap[smallest][1]) {
            smallest = left;
        }
        if (right < this.heap.length && this.heap[right][0] + this.heap[right][1] < this.heap[smallest][0] + this.heap[smallest][1]) {
            smallest = right;
        }
        if (smallest === index) {
            break;
        }
        this.swap(smallest, index);
        index = smallest;
    }
};

MinHeap.prototype.swap = function(i, j) {
    const temp = this.heap[i];
    this.heap[i] = this.heap[j];
    this.heap[j] = temp;
};

