            if (currNum !== '') { stack[stack.length - 1].push(parseInt(currNum)); currNum = ''; }
        } else if (c === '[') {
            stack.push([]);
        } else if (c === ']') {
            if (currNum !== '') { stack[stack.length - 1].push(parseInt(currNum)); currNum = ''; }
