    }
    // Compare the two hash tables to find the character that appears more times in t
    for (let char in tCount) {
        if (!(char in sCount) || tCount[char] > sCount[char]) {
            return char;
        }
    }
}

function lastRemaining(n) {
  let left = true; // direction of elimination
  let remaining = n;
  let step = 1;
  let head = 1;
  // while there are more than one numbers remaining, continue the elimination process
  while (remaining > 1) {
    // if we are eliminating from the left or if the number of remaining numbers is odd
    if (left || remaining % 2 === 1) {
      // update the head of the remaining numbers
      head = head + step;
    }
    // update the step size for the next round of elimination
    step = step * 2;
    // update the number of remaining numbers
    remaining = remaining / 2;
    // switch the direction of elimination
    left = !left;
  }
  // return the last remaining number
  return head;
}

function isRectangleCover(rectangles) {
    let area = 0;
    let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
    let corners = {};
    // iterate through each rectangle to calculate total area and find the bounds of the overall rectangle
    for (let rectangle of rectangles) {
        let [x, y, a, b] = rectangle;
        area += (a - x) * (b - y);
        minX = Math.min(minX, x);
        minY = Math.min(minY, y);
        maxX = Math.max(maxX, a);
        maxY = Math.max(maxY, b);
        // mark the corners of each rectangle
        let points = [[x, y], [x, b], [a, y], [a, b]];
        for (let point of points) {
            let key = point.join(',');
            // if a corner is already marked and it's not a corner of the overall rectangle, return false
            if (corners[key] === 1) {
                delete corners[key];
            } else {
                corners[key] = 1;
            }
        }
    }
    // check if the total area of all rectangles equals the area of the overall rectangle
    if (area !== (maxX - minX) * (maxY - minY)) {
        return false;
    }
    // check if only the four corners of the overall rectangle are left
    if (Object.keys(corners).length !== 4 || !corners[[minX, minY].join(',')] || !corners[[minX, maxY].join(',')] || !corners[[maxX, minY].join(',')] || !corners[[maxX, maxY].join(',')]) {
        return false;
    }
    return true;
}

function longestSubstring(s, k) {
    if (s.length < k) return 0;
    for (let uniqueChar of new Set(s)) // check each unique character in the string
        if (s.split(uniqueChar).length - 1 < k) 
            return Math.max(...s.split(uniqueChar).map(sub => longestSubstring(sub, k)));
    return s.length;
}

function pickIndex(nums, target) {
    let indices = []; // store indices of target in nums
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === target) indices.push(i); // store index if it matches target
    }
    let randomIndex = Math.floor(Math.random() * indices.length); // generate random index
    return indices[randomIndex]; // return random index of target
}

function integerReplacement(n) {
    let operations = 0;
    // if n is even, divide it by 2, if n is odd, either add 1 or subtract 1 to make it even
    while (n !== 1) {
        // if n is even, divide it by 2
        if (n % 2 === 0) {
            n = n / 2;
        } 
        // if n is odd and n + 1 is a power of 2, add 1
        else if (n % 4 === 1 || n === 3) {
            n = n - 1;
        } 
        // if n is odd and n - 1 is a power of 2, subtract 1
        else {
            n = n + 1;
        }
        // increment operations count
        operations++;
    }
    return operations;
}

function rotateFunction(nums) {
    let n = nums.length;
    let maxVal = -Infinity;
    let totalSum = 0;
    let initialSum = 0;
    for (let i = 0; i < n; i++) {
        totalSum += nums[i]; // calculate total sum of the array
        initialSum += i * nums[i]; // calculate initial rotation sum
    }
    maxVal = initialSum;
    for (let k = 1; k < n; k++) {
        initialSum = initialSum + totalSum - n * nums[n - k]; // update rotation sum for each k
        maxVal = Math.max(maxVal, initialSum); // update maxVal if current rotation sum is larger
    }
    return maxVal;
}

function decodeString(s) {
    let stack = [];
    let currentString = '';
    let currentNumber = 0;
    // iterate over the string to separate numbers and strings
    for (let i = 0; i < s.length; i++) {
        // if the character is a digit, update the current number
        if (!isNaN(s[i])) {
            currentNumber = currentNumber * 10 + parseInt(s[i]);
        } 
        // if the character is a letter, add it to the current string
        else if (s[i] >= 'a' && s[i] <= 'z') {
            currentString += s[i];
        } 
        // if the character is an opening bracket, push the current string and number to the stack
        else if (s[i] === '[') {
            stack.push(currentString);
            stack.push(currentNumber);
            currentString = '';
            currentNumber = 0;
        } 
        // if the character is a closing bracket, pop the number and previous string from the stack and update the current string
        else if (s[i] === ']') {
            let number = stack.pop();
            let previousString = stack.pop();
            // repeat the current string 'number' times and add it to the previous string
            currentString = previousString + currentString.repeat(number);
        }
    }
    return currentString;
}

function calcEquation(equations, values, queries) {
    // Create a graph where each variable is a node and the edges represent the division relationships
    const graph = {};
    for (let i = 0; i < equations.length; i++) {
        const [a, b] = equations[i];
        if (!graph[a]) graph[a] = [];
        if (!graph[b]) graph[b] = [];
        graph[a].push([b, values[i]]);
        graph[b].push([a, 1 / values[i]]);
    }

    // Perform DFS to find the division result for each query
    function dfs(a, b, visited) {
        // If a and b are the same variable, return 1
        if (a === b) return 1;
        visited.add(a);
        for (const [neighbor, value] of graph[a]) {
            // If the neighbor is the target variable and it has not been visited, return the product of the current value and the value of the edge
            if (neighbor === b && !visited.has(neighbor)) return value;
            // If the neighbor has not been visited, recursively call dfs on the neighbor
            if (!visited.has(neighbor)) {
                const result = dfs(neighbor, b, visited);
                // If the result is not -1, return the product of the current value and the result
                if (result !== -1) return value * result;
            }
        }
        // If the target variable is not reachable from the current variable, return -1
        return -1;
    }

    // Calculate the division result for each query
    const result = [];
    for (const [a, b] of queries) {
        // If a or b is not in the graph, the result is -1
        if (!graph[a] || !graph[b]) result.push(-1);
        else {
            // Perform DFS to find the division result
            result.push(dfs(a, b, new Set()));
        }
    }
    return result;
}

function findNthDigit(n) {
    let length = 1, count = 9, start = 1;
    // calculate the length of the numbers that the nth digit falls into
    while (n > length * count) {
        n -= length * count;
        length += 1;
        count *= 10;
        start *= 10;
    }
    // calculate the actual number that the nth digit falls into
    start += Math.floor((n - 1) / length);
    // return the nth digit of the calculated number
    return parseInt(start.toString()[(n - 1) % length]);

}

