function canCross(stones) {
    let n = stones.length;
    let stoneSet = new Set(stones);
    let memo = new Map();
    function dfs(stone, k) {
        // create a unique key for memoization
        let key = stone + ',' + k;
        if (memo.has(key)) return memo.get(key);
        // base case: if we've reached the last stone, return true
        if (stone === stones[n - 1]) return true;
        // try all possible jumps
        for (let jump = k - 1; jump <= k + 1; jump++) {
            // skip invalid jumps
            if (jump <= 0) continue;
            // check if the next stone exists
            if (stoneSet.has(stone + jump)) {
                // recursively try to cross the river from the next stone
                if (dfs(stone + jump, jump)) {
                    memo.set(key, true);
                    return true;
                }
            }
        }
        // if no jump works, return false
        memo.set(key, false);
        return false;
    }
    // start from the first stone with a jump of 1
    return dfs(stones[0], 1);
}

function sumOfLeftLeaves(root) {
  function dfs(node, isLeft) {
    // if the node is null, return 0 as there are no leaves to sum
    if (node === null) return 0;
    // if the node is a leaf and is the left child, return its value
    if (node.left === null && node.right === null && isLeft) return node.val;
    // recursively call dfs on the left and right children, passing the correct isLeft value
    return dfs(node.left, true) + dfs(node.right, false);
  }
  // call dfs on the root node, which is not the left child of any node
  return dfs(root, false);
}

function toHex(num) {
    if (num === 0) return '0'; // handle zero case
    let result = ''; 
    let isNegative = num < 0; 
    if (isNegative) num = num + Math.pow(2, 32); // apply two's complement for negative numbers
    while (num > 0) {
        let remainder = num % 16; // get the remainder
        if (remainder < 10) result = String.fromCharCode(48 + remainder) + result; // convert to char for digits
        else result = String.fromCharCode(87 + remainder) + result; // convert to char for letters
        num = Math.floor(num / 16); // integer division
    }
    return result;
}

function removeKDigits(num, k) {
    let stack = [];
    // iterate through the number and push digits to the stack if it's empty or the top of the stack is smaller than the current digit
    for (let i = 0; i < num.length; i++) {
        // while the stack is not empty, the top of the stack is greater than the current digit, and we still have removals left, pop the stack
        while (stack.length > 0 && stack[stack.length - 1] > num[i] && k > 0) {
            stack.pop();
            k--;
        }
        stack.push(num[i]);
    }
    // if we still have removals left, remove the remaining digits from the end of the stack
    while (k > 0) {
        stack.pop();
        k--;
    }
    // join the stack into a string and remove leading zeroes
    let result = stack.join('').replace(/^0+/, '') || '0';
    return result;
}

function readBinaryWatch(turnedOn) {
    let result = [];
    // generate all possible times and check if the number of turned on LEDs matches
    for (let hour = 0; hour < 12; hour++) {
        for (let minute = 0; minute < 60; minute++) {
            // calculate the number of turned on LEDs for the current time
            let hourBits = countBits(hour);
            let minuteBits = countBits(minute);
            if (hourBits + minuteBits === turnedOn) {
                // format the time as a string and add it to the result
                result.push(`${hour}:${minute.toString().padStart(2, '0')}`);
            }
        }
    }
    return result;
}

function countBits(n) {
    let count = 0;
    // count the number of bits set in the binary representation of n
    while (n) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

function reconstructQueue(people) {
