        queue.splice(person[1], 0, person);
    }
    return queue;
}

function longestPalindrome(s) {
    var charCount = {};
    for (var i = 0; i < s.length; i++) {
        // count occurrences of each character
        if (charCount[s[i]]) charCount[s[i]]++;
        else charCount[s[i]] = 1;
    }
    var length = 0;
    var oddFound = false;
    for (var char in charCount) {
        // add the largest even number less than or equal to the count to the length
        length += charCount[char] - (charCount[char] % 2);
        // if a character has an odd count, we can add one more character to the middle of the palindrome
        if (charCount[char] % 2 !== 0) oddFound = true;
    }
    // if we found any characters with odd counts, we can add one more character to the length
    if (oddFound) length++;
    return length;
}

function trapRainWater(heightMap) {
    let m = heightMap.length;
    let n = heightMap[0].length;
    let visited = new Array(m).fill(0).map(() => new Array(n).fill(false));
    let pq = [];
    let volume = 0;
    // add all the boundary cells to the priority queue
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (i === 0 || j === 0 || i === m - 1 || j === n - 1) {
                visited[i][j] = true;
                pq.push([heightMap[i][j], i, j]);
            }
        }
    }
    // sort the priority queue in ascending order
    pq.sort((a, b) => a[0] - b[0]);
    let directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (pq.length > 0) {
        let [height, x, y] = pq.shift();
        // explore all the neighboring cells
        for (let [dx, dy] of directions) {
            let nx = x + dx;
            let ny = y + dy;
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && !visited[nx][ny]) {
                // calculate the trapped water
                volume += Math.max(0, height - heightMap[nx][ny]);
                // update the height of the neighboring cell
                heightMap[nx][ny] = Math.max(heightMap[nx][ny], height);
                visited[nx][ny] = true;
                // add the neighboring cell to the priority queue
                pq.push([heightMap[nx][ny], nx, ny]);
                // sort the priority queue in ascending order
                pq.sort((a, b) => a[0] - b[0]);
            }
        }
    }
    return volume;
}

