}

function thirdMax(nums) {
    // Remove duplicates by converting the array to a set
    let uniqueNums = [...new Set(nums)];
    // Sort the unique numbers in descending order
    uniqueNums.sort((a, b) => b - a);
    // If there are at least three unique numbers, return the third one
    if (uniqueNums.length >= 3) return uniqueNums[2];
    // Otherwise, return the maximum number
    return uniqueNums[0];
}

function numberOfArithmeticSlices(nums) {
    let count = 0;
    for (let i = 0; i < nums.length - 2; i++) {
        let diff = nums[i + 1] - nums[i]; // calculate the initial difference
        for (let j = i + 2; j < nums.length; j++) {
            if (nums[j] - nums[j - 1] === diff) { // check if the difference is the same
                count++; // increment count if it's an arithmetic slice
            } else {
                break; // break the inner loop if the difference changes
            }
        }
    }
    return count;
}

function addStrings(num1, num2) {
    let result = '';
    let carry = 0;
    let i = num1.length - 1;
    let j = num2.length - 1;
    // iterate through the strings from right to left, adding corresponding digits and handling carry
    while (i >= 0 || j >= 0 || carry) {
        let sum = carry;
        if (i >= 0) sum += num1.charCodeAt(i--) - '0'.charCodeAt(0);
        if (j >= 0) sum += num2.charCodeAt(j--) - '0'.charCodeAt(0);
        // append the last digit of the sum to the result and update the carry
        result = (sum % 10) + result;
        carry = Math.floor(sum / 10);
    }
    return result;
}

