function splitArray(nums, k) {
    let left = Math.max(...nums); // the minimum possible sum
    let right = nums.reduce((a, b) => a + b, 0); // the maximum possible sum
    while (left < right) {
        let mid = Math.floor((left + right) / 2); // calculate the middle sum
        let count = 1, sum = 0; // initialize the count of subarrays and the current sum
        for (let num of nums) { // iterate over the array
            sum += num; // add the current number to the sum
            if (sum > mid) { // if the sum exceeds the middle sum
                count++; // increment the count of subarrays
                sum = num; // reset the sum to the current number
            }
        }
        if (count > k) { // if the count of subarrays exceeds k
            left = mid + 1; // update the left boundary
        } else { // otherwise
            right = mid; // update the right boundary
        }
    }
    return left; // return the minimum largest sum
}

function canPartition(nums) {
  let totalSum = 0;
  for (let num of nums) {
    totalSum += num;
  }
  // If the total sum is odd, it's impossible to partition the array into two subsets with equal sum
  if (totalSum % 2 !== 0) {
    return false;
  }
  let targetSum = totalSum / 2;
  let dp = new Array(targetSum + 1).fill(false);
  dp[0] = true;
  for (let num of nums) {
    // Iterate over the dp array in reverse order to avoid overwriting previously computed values
    for (let i = targetSum; i >= num; i--) {
      dp[i] = dp[i] || dp[i - num];
    }
  }
  return dp[targetSum];
}

function strongPasswordChecker(password) {
    let missingTypes = 3;
    let one = false, upper = false, digit = false;
    let totalLength = password.length;
    let changes = 0;

    // Check for missing character types
    for (let i = 0; i < totalLength; i++) {
        if (password[i] >= 'a' && password[i] <= 'z') one = true;
        else if (password[i] >= 'A' && password[i] <= 'Z') upper = true;
        else if (password[i] >= '0' && password[i] <= '9') digit = true;
    }
    if (one) missingTypes--;
    if (upper) missingTypes--;
    if (digit) missingTypes--;

    // Calculate changes needed for length
    if (totalLength < 6) {
        // If password is too short, we need to add characters
        changes += 6 - totalLength;
    } else if (totalLength > 20) {
        // If password is too long, we need to remove characters
        changes += totalLength - 20;
    }

    // Calculate changes needed for sequences
    let i = 2;
    while (i < totalLength) {
        // Check for sequences of 3 or more identical characters
        if (password[i] === password[i-1] && password[i] === password[i-2]) {
            let length = 2;
            while (i + 1 < totalLength && password[i] === password[i+1]) {
                i++;
                length++;
            }
            // Calculate changes needed to break sequence
            changes += Math.floor(length / 3);
        }
        i++;
    }

    // Return total changes needed
    return Math.max(missingTypes, changes);
}

function pacificAtlantic(heights) {
    const m = heights.length;
    const n = heights[0].length;
    const pacific = Array(m).fill().map(() => Array(n).fill(false));
    const atlantic = Array(m).fill().map(() => Array(n).fill(false));

    function dfs(row, col, visited) {
        visited[row][col] = true;
        // check all four directions (up, down, left, right) and perform DFS if the height is greater or equal
        const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
        for (const [dr, dc] of directions) {
            const nr = row + dr;
            const nc = col + dc;
            if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && heights[nr][nc] >= heights[row][col]) {
                dfs(nr, nc, visited);
            }
        }
    }

    // perform DFS from the Pacific Ocean
    for (let i = 0; i < m; i++) {
        dfs(i, 0, pacific); // left edge
    }
    for (let j = 0; j < n; j++) {
        dfs(0, j, pacific); // top edge
    }

    // perform DFS from the Atlantic Ocean
    for (let i = 0; i < m; i++) {
        dfs(i, n - 1, atlantic); // right edge
    }
    for (let j = 0; j < n; j++) {
        dfs(m - 1, j, atlantic); // bottom edge
    }

    const result = [];
    // find the cells that can flow to both the Pacific and Atlantic oceans
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (pacific[i][j] && atlantic[i][j]) {
                result.push([i, j]);
            }
        }
    }
    return result;
}

function findMaximumXOR(nums) {
  let maximumXOR = 0;
  let root = {};
  // Create a Trie and insert all numbers into it
  for (let num of nums) {
    let node = root;
    for (let i = 31; i >= 0; i--) {
      let bit = (num >> i) & 1;
      if (!node[bit]) node[bit] = {};
      node = node[bit];
    }
  }
  // For each number in the array, find the maximum XOR in the Trie
  for (let num of nums) {
    let node = root;
    let currentXOR = 0;
    for (let i = 31; i >= 0; i--) {
      let bit = (num >> i) & 1;
      // Try to find the opposite bit to maximize the XOR
      if (node[1 - bit]) {
        currentXOR |= (1 << i);
        node = node[1 - bit];
      } else {
        node = node[bit];
      }
    }
    // Update the maximum XOR
    maximumXOR = Math.max(maximumXOR, currentXOR);
  }
  return maximumXOR;
}

function characterReplacement(s, k) {
    let maxLength = 0;
    let windowStart = 0;
    let frequencyMap = {};
    let maxFrequency = 0;
    for (let windowEnd = 0; windowEnd < s.length; windowEnd++) {
        let rightChar = s[windowEnd];
        // update frequency map
        if (!(rightChar in frequencyMap)) {
            frequencyMap[rightChar] = 0;
        }
        frequencyMap[rightChar]++;
        // update max frequency
        maxFrequency = Math.max(maxFrequency, frequencyMap[rightChar]);
        // shrink the window if we have more than 'k' characters to replace
        if ((windowEnd - windowStart + 1) - maxFrequency > k) {
            let leftChar = s[windowStart];
            frequencyMap[leftChar]--;
            windowStart++;
        }
        // update max length
        maxLength = Math.max(maxLength, windowEnd - windowStart + 1);
    }
    return maxLength;
}

function originalDigits(s) {
    let count = new Array(26).fill(0);
    // count the frequency of each character in the string
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i) - 'a'.charCodeAt(0)]++;
    }
    let result = new Array(10).fill(0);
    // calculate the count of '0' using 'z'
    result[0] = count['z'.charCodeAt(0) - 'a'.charCodeAt(0)];
    // calculate the count of '2' using 'w'
    result[2] = count['w'.charCodeAt(0) - 'a'.charCodeAt(0)];
    // calculate the count of '4' using 'u'
    result[4] = count['u'.charCodeAt(0) - 'a'.charCodeAt(0)];
    // calculate the count of '6' using 'x'
    result[6] = count['x'.charCodeAt(0) - 'a'.charCodeAt(0)];
    // calculate the count of '8' using 'g'
    result[8] = count['g'.charCodeAt(0) - 'a'.charCodeAt(0)];
    // calculate the count of '1' using 'o' and subtracting '0', '2', '4'
    result[1] = count['o'.charCodeAt(0) - 'a'.charCodeAt(0)] - result[0] - result[2] - result[4];
    // calculate the count of '3' using 'h' and subtracting '8'
    result[3] = count['h'.charCodeAt(0) - 'a'.charCodeAt(0)] - result[8];
    // calculate the count of '5' using 'f' and subtracting '4'
    result[5] = count['f'.charCodeAt(0) - 'a'.charCodeAt(0)] - result[4];
    // calculate the count of '7' using 's' and subtracting '6'
    result[7] = count['s'.charCodeAt(0) - 'a'.charCodeAt(0)] - result[6];
    // calculate the count of '9' using 'i' and subtracting '5', '6', '8'
    result[9] = count['i'.charCodeAt(0) - 'a'.charCodeAt(0)] - result[5] - result[6] - result[8];
    let res = '';
    // construct the result string
    for (let i = 0; i < 10; i++) {
        res += i.toString().repeat(result[i]);
    }
    return res;
}

function construct(grid) {
    function constructQuadTree(x, y, n) {
        // Check if all cells in the current grid are the same
        let isLeaf = true;
        let val = grid[x][y];
        for (let i = x; i < x + n; i++) {
            for (let j = y; j < y + n; j++) {
                if (grid[i][j] !== val) {
                    isLeaf = false;
                    break;
                }
            }
            if (!isLeaf) break;
        }
        // If all cells are the same, return a leaf node
        if (isLeaf) return [1, val];
        // Otherwise, divide the grid into four sub-grids and recursively construct the quad tree
        let node = [0, 0];
        let half = Math.floor(n / 2);
        node.push(constructQuadTree(x, y, half));
        node.push(constructQuadTree(x, y + half, half));
        node.push(constructQuadTree(x + half, y, half));
        node.push(constructQuadTree(x + half, y + half, half));
        return node;
    }
    return constructQuadTree(0, 0, grid.length);
}

function levelOrder(root) {
    if (!root) return [];
    var result = [];
    var queue = [root];
    // while loop to traverse each level of the tree
    while (queue.length > 0) {
        var levelSize = queue.length;
        var currentLevel = [];
        // for loop to process each node at the current level
        for (var i = 0; i < levelSize; i++) {
            var currentNode = queue.shift();
            currentLevel.push(currentNode.val);
            // add all children of the current node to the queue
            if (currentNode.children) {
                for (var j = 0; j < currentNode.children.length; j++) {
                    queue.push(currentNode.children[j]);
                }
            }
        }
        // add the current level to the result
        result.push(currentLevel);
    }
    return result;
}

function countBattleships(board) {
