    for (let i = 0; i < board.length; i++) {
        for (let j = 0; j < board[i].length; j++) {
            // if current cell is 'X' and it's not part of a previously counted battleship
            if (board[i][j] === 'X' && (i === 0 || board[i-1][j] !== 'X') && (j === 0 || board[i][j-1] !== 'X')) {
                count++; // increment the count of battleships
            }
        }
    }
    return count;
}

function flatten(head) {
    if (!head) return head;
    const stack = [head];
    let prev = null;
    while (stack.length) {
        const cur = stack.pop();
        if (prev) {
            prev.next = cur;
            cur.prev = prev;
        }
        if (cur.next) stack.push(cur.next);
        if (cur.child) {
            stack.push(cur.child);
            cur.child = null;
        }
        prev = cur;
    }
    return head;
}

class Node {
    constructor(val, prev = null, next = null, child = null) {
        this.val = val;
        this.prev = prev;
        this.next = next;
        this.child = child;
    }
}

function toList(head) {
    const res = [];
    while (head) {
        res.push(head.val);
        head = head.next;
    }
    return res;
}

function link(...nodes) {
    for (let i = 0; i < nodes.length - 1; i++) {
        nodes[i].next = nodes[i + 1];
        nodes[i + 1].prev = nodes[i];
    }
    return nodes[0];
}

