function minMutation(startGene, endGene, bank) {
    let bankSet = new Set(bank);
    let queue = [[startGene, 0]];
    let visited = new Set([startGene]);
    while (queue.length > 0) {
        let [currentGene, steps] = queue.shift();
        // if the current gene is the target gene, return the number of steps
        if (currentGene === endGene) return steps;
        // generate all possible mutations of the current gene
        for (let i = 0; i < 8; i++) {
            for (let char of ['A', 'C', 'G', 'T']) {
                let nextGene = currentGene.substring(0, i) + char + currentGene.substring(i + 1);
                // if the next gene is in the bank and has not been visited, add it to the queue
                if (bankSet.has(nextGene) && !visited.has(nextGene)) {
                    queue.push([nextGene, steps + 1]);
                    visited.add(nextGene);
                }
            }
        }
    }
    // if there is no possible mutation, return -1
    return -1;
}

function countSegments(s) {
  let segmentCount = 0;
  let inSegment = false;
  // iterate through the string and count segments by tracking when we enter and exit a segment
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== ' ' && !inSegment) {
      segmentCount++;
      inSegment = true;
    } else if (s[i] === ' ' && inSegment) {
      inSegment = false;
    }
  }
  return segmentCount;
}

function AllOne() {
    this.keyCountMap = new Map(); // stores the count of each key
    this.countKeyMap = new Map(); // stores the keys for each count
    this.minCount = Infinity; // minimum count
    this.maxCount = -Infinity; // maximum count
}

AllOne.prototype.inc = function(key) {
    // get the current count of the key
    let count = this.keyCountMap.get(key) || 0;
    // remove the key from the current count
    if (count > 0) this.countKeyMap.get(count).delete(key);
    // if the current count is the minimum count and the set is empty, update the minimum count
    if (count === this.minCount && this.countKeyMap.get(count).size === 0) this.minCount = count + 1;
    // a brand new key always has count 1, which is always <= any existing minCount
    if (count === 0) this.minCount = 1;
    // update the count of the key
    this.keyCountMap.set(key, count + 1);
    // add the key to the new count
    if (!this.countKeyMap.has(count + 1)) this.countKeyMap.set(count + 1, new Set());
    this.countKeyMap.get(count + 1).add(key);
    // update the maximum count
    this.maxCount = Math.max(this.maxCount, count + 1);
};

AllOne.prototype.dec = function(key) {
    // get the current count of the key
    let count = this.keyCountMap.get(key);
    // remove the key from the current count
    this.countKeyMap.get(count).delete(key);
    // if the current count is the maximum count and the set is empty, update the maximum count
    if (count === this.maxCount && this.countKeyMap.get(count).size === 0) this.maxCount = count - 1;
    // update the count of the key
    if (count > 1) {
        this.keyCountMap.set(key, count - 1);
        // add the key to the new count
        if (!this.countKeyMap.has(count - 1)) this.countKeyMap.set(count - 1, new Set());
        this.countKeyMap.get(count - 1).add(key);
        // update the minimum count (a real bucket now exists at count-1)
        this.minCount = Math.min(this.minCount, count - 1);
    } else {
        this.keyCountMap.delete(key);
        // key fully removed; if it emptied the min bucket, recompute the min from scratch
        if (count === this.minCount && this.countKeyMap.get(count).size === 0) {
            if (this.keyCountMap.size === 0) {
                this.minCount = Infinity;
                this.maxCount = -Infinity;
            } else {
                let m = Infinity;
                for (const [c, s] of this.countKeyMap) {
                    if (s.size > 0 && c < m) m = c;
                }
                this.minCount = m;
            }
        }
    }
};

AllOne.prototype.getMinKey = function() {
    if (!this.countKeyMap.has(this.minCount)) return "";
    // return the first key in the set of the minimum count
    return this.countKeyMap.get(this.minCount).values().next().value || "";
};

AllOne.prototype.getMaxKey = function() {
    if (!this.countKeyMap.has(this.maxCount)) return "";
    // return the first key in the set of the maximum count
    return this.countKeyMap.get(this.maxCount).values().next().value || "";
};

function findRightInterval(intervals) {
    let result = new Array(intervals.length);
    let intervalIndices = [];
    for (let i = 0; i < intervals.length; i++) {
        intervalIndices.push([intervals[i][0], i]);
    }
    intervalIndices.sort((a, b) => a[0] - b[0]); // sort intervals by start time
    for (let i = 0; i < intervals.length; i++) {
        let target = intervals[i][1]; // find the right interval for the current interval
        let left = 0, right = intervals.length - 1;
        while (left <= right) {
            let mid = Math.floor((left + right) / 2);
            if (intervalIndices[mid][0] >= target) {
                right = mid - 1; // continue searching in the left half
            } else {
                left = mid + 1; // continue searching in the right half
            }
        }
        result[i] = left < intervals.length ? intervalIndices[left][1] : -1; // assign the index of the right interval
    }
    return result;
}

function pathSum(root, targetSum) {
    let count = 0;
    function dfs(node, currentSum) {
        if (!node) return;
        // check if currentSum plus node value equals targetSum
        currentSum += node.val;
        if (currentSum === targetSum) count++;
        // recursively call dfs for left and right subtrees
        dfs(node.left, currentSum);
        dfs(node.right, currentSum);
    }
    function traverse(node) {
        if (!node) return;
        dfs(node, 0);
        // traverse left and right subtrees
        traverse(node.left);
        traverse(node.right);
    }
    traverse(root);
    return count;
}

function findAnagrams(s, p) {
    const result = [];
    const pCount = {};
    const sCount = {};

    // Create a count map for string p
    for (let char of p) {
        if (!pCount[char]) pCount[char] = 0;
        pCount[char]++;
    }

    // Initialize the window boundaries
    let left = 0;
    let right = 0;

    // Expand the window to the right and update the count map for string s
    while (right < s.length) {
        // Add the character at the right boundary to the count map
        if (!sCount[s[right]]) sCount[s[right]] = 0;
        sCount[s[right]]++;

        // If the window size is equal to the length of string p, check if it's an anagram
        if (right - left + 1 === p.length) {
            // Check if the count maps are equal, which means it's an anagram
            let isAnagram = true;
            for (let char in pCount) {
                if (pCount[char] !== sCount[char]) {
                    isAnagram = false;
                    break;
                }
            }
            if (isAnagram) {
                // If it's an anagram, add the start index to the result
                result.push(left);
            }

            // Remove the character at the left boundary from the count map
            sCount[s[left]]--;
            if (sCount[s[left]] === 0) delete sCount[s[left]];
            left++;
        }
        right++;
    }

    return result;
}

function findKthNumber(n, k) {
  let cur = 1;
  k--;
  while (k > 0) {
    // calculate the number of nodes in the current subtree
    let step = 0;
    let first = cur;
    let last = cur + 1;
    while (first <= n) {
      // update step and boundaries for the next level
      step += Math.min(n + 1, last) - first;
      first *= 10;
      last *= 10;
    }
    // if k is still greater than step, move to the next sibling
    if (k >= step) {
      k -= step;
      cur++;
    } 
    // if k is less than step, move down to the next level
    else {
      k--;
      cur *= 10;
    }
  }
  return cur;
}

