function arrangeCoins(n) {
    let left = 1, right = n;
    // we use binary search to find the maximum number of complete rows
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        let sum = Math.floor(mid * (mid + 1) / 2);
        // if the total coins are enough to build mid rows, we try to build more rows
        if (sum <= n) {
            left = mid + 1;
        } 
        // if the total coins are not enough to build mid rows, we try to build fewer rows
        else {
            right = mid - 1;
        }
    }
    // the maximum number of complete rows is the right pointer
    return right;
}

function compress(chars) {
    let writeIndex = 0; 
    let count = 1;
    for (let readIndex = 1; readIndex < chars.length; readIndex++) {
        // if the current character is the same as the previous one, increment the count
        if (chars[readIndex] === chars[readIndex - 1]) {
            count++;
        } else {
            // write the character and its count to the array
            chars[writeIndex++] = chars[readIndex - 1];
            // convert the count to a string and write it to the array
            let countStr = count.toString();
            for (let i = 0; i < countStr.length; i++) {
                chars[writeIndex++] = countStr[i];
            }
            count = 1;
        }
    }
    // handle the last group of characters
    chars[writeIndex++] = chars[chars.length - 1];
    let countStr = count.toString();
    for (let i = 0; i < countStr.length; i++) {
        chars[writeIndex++] = countStr[i];
    }
    return writeIndex;
}

function eraseOverlapIntervals(intervals) {
    if (intervals.length === 0) return 0;
    intervals.sort((a, b) => a[1] - b[1]); // sort intervals by end time
    let end = intervals[0][1], count = 0; // initialize end time and count of non-overlapping intervals
    for (let i = 1; i < intervals.length; i++) { // iterate through intervals
        if (intervals[i][0] < end) count++; // if current interval overlaps with previous, increment count
        else end = intervals[i][1]; // if not, update end time
    }
    return count; // return count of overlapping intervals
}

function findDuplicates(nums) {
  var result = [];
  for (var i = 0; i < nums.length; i++) {
    // use the absolute value of the current number as an index to mark it as visited
    var index = Math.abs(nums[i]) - 1;
    // if the number at the marked index is negative, it means we've seen this number before
    if (nums[index] < 0) {
      result.push(Math.abs(nums[i]));
    }
    // mark the number as visited by making it negative
    nums[index] = -nums[index];
  }
  return result;
}

function numberOfArithmeticSlices(nums) {
    let count = 0;
    let n = nums.length;
    let dp = new Array(n);
    for (let i = 0; i < n; i++) {
        dp[i] = {};
    }
    // iterate over each pair of numbers to find the difference
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            let diff = nums[i] - nums[j];
            // update the count of arithmetic subsequences ending at i with difference diff
            count += dp[j][diff] || 0;
            // update the count of arithmetic subsequences ending at i with difference diff
            dp[i][diff] = (dp[i][diff] || 0) + (dp[j][diff] || 0) + 1;
        }
    }
    return count;
}

function numberOfBoomerangs(points) {
    let count = 0;
    for (let i = 0; i < points.length; i++) {
        let map = {};
        for (let j = 0; j < points.length; j++) {
            if (i === j) continue;
            // calculate the distance between points i and j
            let distance = Math.pow(points[i][0] - points[j][0], 2) + Math.pow(points[i][1] - points[j][1], 2);
            if (map[distance]) {
                // if the distance is already in the map, increment the count by the number of times it appears
                map[distance]++;
            } else {
                map[distance] = 1;
            }
        }
        // for each distance in the map, add the number of permutations to the count
        for (let key in map) {
            // calculate the number of permutations: n*(n-1) where n is the number of points with the same distance
            count += map[key] * (map[key] - 1);
        }
    }
    return count;
}

