}

function addTwoNumbers(l1, l2) {
    // reverse the first linked list
    let reversedL1 = reverseList(l1);
    // reverse the second linked list
    let reversedL2 = reverseList(l2);
    // initialize a dummy node for the result linked list
    let dummy = new ListNode(0);
    let current = dummy;
    let carry = 0;
    // iterate through the reversed linked lists
    while (reversedL1 || reversedL2 || carry) {
        // calculate the sum of the current nodes and the carry
        let sum = (reversedL1 ? reversedL1.val : 0) + (reversedL2 ? reversedL2.val : 0) + carry;
        // update the carry
        carry = Math.floor(sum / 10);
        // create a new node with the digit value of the sum
        current.next = new ListNode(sum % 10);
        // move to the next node
        current = current.next;
        // move to the next nodes in the reversed linked lists
        reversedL1 = reversedL1 ? reversedL1.next : null;
        reversedL2 = reversedL2 ? reversedL2.next : null;
    }
    // reverse the result linked list
    return reverseList(dummy.next);
}

function reverseList(head) {
    let prev = null;
    let current = head;
    while (current) {
        let next = current.next;
        current.next = prev;
        prev = current;
        current = next;
    }
    return prev;
}

