function deleteNode(root, key) {
    // base case: if tree is empty, return null
    if (root === null) return null;

    // if key is less than current node's value, recurse on left subtree
    if (key < root.val) root.left = deleteNode(root.left, key);
    // if key is greater than current node's value, recurse on right subtree
    else if (key > root.val) root.right = deleteNode(root.right, key);
    // if key matches current node's value, handle deletion
    else {
        // case 1: no children, simply return null
        if (root.left === null && root.right === null) return null;
        // case 2: one child, return that child
        if (root.left === null) return root.right;
        if (root.right === null) return root.left;
        // case 3: two children, find in-order successor and replace node's value
        let successor = root.right;
        while (successor.left !== null) successor = successor.left;
        root.val = successor.val;
        // delete in-order successor
        root.right = deleteNode(root.right, successor.val);
    }
    return root;
}

function frequencySort(s) {
    var frequencyMap = {};
    // count the frequency of each character
    for (var i = 0; i < s.length; i++) {
        if (!frequencyMap[s[i]]) frequencyMap[s[i]] = 0;
        frequencyMap[s[i]]++;
    }
    var sortedChars = Object.keys(frequencyMap).sort(function(a, b) {
        // sort characters by frequency in descending order
        return frequencyMap[b] - frequencyMap[a];
    });
    var result = '';
    // build the result string
    for (var i = 0; i < sortedChars.length; i++) {
        // append each character to the result string as many times as its frequency
        for (var j = 0; j < frequencyMap[sortedChars[i]]; j++) {
            result += sortedChars[i];
        }
    }
    return result;
}

function minMoves(nums) {
  // find the minimum element in the array as the target value
  var minVal = Math.min.apply(Math, nums);
  var moves = 0;
  // calculate the total difference between each element and the target value
  for (var i = 0; i < nums.length; i++) {
    // add the difference to the total moves
    moves += nums[i] - minVal;
  }
  return moves;
}

function findMinArrowShots(points) {
    if (points.length === 0) return 0;
    points.sort((a, b) => a[1] - b[1]); // sort by end point
    let arrows = 1; 
    let currentEnd = points[0][1]; 
    for (let i = 1; i < points.length; i++) // iterate through each balloon
        if (points[i][0] > currentEnd) { // if current balloon is not burst by previous arrow
            arrows++; 
            currentEnd = points[i][1]; 
        }
    return arrows;
}

function find132pattern(nums) {
  let stack = [];
  let s3 = Number.MIN_SAFE_INTEGER;
  // iterate through the array from right to left to find the first element that can be part of the 132 pattern
  for (let i = nums.length - 1; i >= 0; i--) {
    // if the current element is less than s3, it means we have found a 132 pattern
    if (nums[i] < s3) return true;
    // while the stack is not empty and the top of the stack is greater than the current element, update s3
    while (stack.length > 0 && stack[stack.length - 1] < nums[i]) {
      // update s3 to be the top of the stack
      s3 = stack.pop();
    }
    // push the current element onto the stack
    stack.push(nums[i]);
  }
  // if we have iterated through the entire array and not found a 132 pattern, return false
  return false;
}

function serialize(root) {
    if (!root) return 'X,';
    // recursively serialize left and right subtrees and concatenate with current node's value
    return root.val + ',' + serialize(root.left) + serialize(root.right);
}

function deserialize(data) {
    if (!data) return null;
    let nodes = data.split(',');
    let index = 0;
    function buildTree() {
        if (index >= nodes.length || nodes[index] === 'X') {
            index++;
            return null;
        }
        // create a new node with the current value and recursively build left and right subtrees
        let node = new TreeNode(parseInt(nodes[index++]));
        node.left = buildTree();
        node.right = buildTree();
        return node;
    }
    return buildTree();
}

function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

function findContentChildren(g, s) {
    // Sort both arrays to easily find matching pairs
    g.sort((a, b) => a - b);
    s.sort((a, b) => a - b);
    let childIndex = 0, cookieIndex = 0;
    // Iterate through both arrays and assign cookies to children
    while (childIndex < g.length && cookieIndex < s.length) {
        // If the current cookie can satisfy the current child, move to the next child
        if (s[cookieIndex] >= g[childIndex]) childIndex++;
        // Move to the next cookie
        cookieIndex++;
    }
    // The number of satisfied children is the index of the last satisfied child plus one
    return childIndex;
}

function poorPigs(buckets, minutesToDie, minutesToTest) {
    let states = minutesToTest / minutesToDie + 1; // calculate the number of possible states for each pig
    let pigs = Math.ceil(Math.log(buckets) / Math.log(states)); // calculate the minimum number of pigs needed using logarithm
    return pigs;
}

function circularArrayLoop(nums) {
    for (let i = 0; i < nums.length; i++) {
        let slow = i, fast = i;
        let direction = nums[i] > 0;
        let isLoop = false;
        do {
            slow = findNextIndex(nums, slow, direction);
            if (slow === -1) break;
            fast = findNextIndex(nums, fast, direction);
            if (fast === -1) break;
            fast = findNextIndex(nums, fast, direction);
            if (fast === -1) break;
            if (slow === fast) {
                // self-loop (single-element cycle) doesn't count - stop searching from this start
                if (slow === findNextIndex(nums, slow, direction)) {
                    break;
                } else {
                    isLoop = true;
                }
            }
        } while (!isLoop);
        if (isLoop) return true;
    }
    return false;
}
function findNextIndex(nums, currentIndex, direction) {
    let nextIndex = (currentIndex + nums[currentIndex]) % nums.length;
    if (nextIndex < 0) nextIndex += nums.length;
    if (nums[nextIndex] > 0 !== direction) return -1;
    return nextIndex;
}

function fourSumCount(nums1, nums2, nums3, nums4) {
    let count = 0;
    let map = {};
    // Create a hashmap to store the sum of elements from nums1 and nums2
    for (let i = 0; i < nums1.length; i++) {
        for (let j = 0; j < nums2.length; j++) {
            let sum = nums1[i] + nums2[j];
            // If the sum is already in the hashmap, increment its count
            if (map[sum] === undefined) {
                map[sum] = 1;
            } else {
                map[sum]++;
            }
        }
    }
    // Iterate over nums3 and nums4 to find the sum that equals to the negative of the sum in the hashmap
    for (let i = 0; i < nums3.length; i++) {
        for (let j = 0; j < nums4.length; j++) {
            let sum = nums3[i] + nums4[j];
            // If the negative of the sum is in the hashmap, increment the count by the value in the hashmap
            if (map[-sum] !== undefined) {
                count += map[-sum];
            }
        }
    }
    return count;
}

function repeatedSubstringPattern(s) {
  // check all possible substring lengths that can evenly divide the string length
  for (var length = 1; length <= s.length / 2; length++) {
    // only consider lengths that can divide the string length without remainder
    if (s.length % length === 0) {
      var substring = s.substring(0, length);
      var repeated = '';
      // repeat the substring to match the string length
      for (var i = 0; i < s.length / length; i++) {
        repeated += substring;
      }
      // check if the repeated substring matches the original string
      if (repeated === s) {
        return true;
      }
    }
  }
  return false;
}

function hammingDistance(x, y) {
  let distance = 0;
  let xorResult = x ^ y; // perform XOR operation to find bits that are different
  while (xorResult > 0) {
    distance += xorResult & 1; // count the least significant bit
    xorResult >>= 1; // shift right to move to the next bit
  }
  return distance;
}

