function LFUCache(capacity) {
    this.capacity = capacity;
    this.keyMap = new Map();
    this.freqMap = new Map();
    this.minFreq = 1;
}

LFUCache.prototype.get = function(key) {
    // if key is not in cache, return -1
    if (!this.keyMap.has(key)) return -1;
    let node = this.keyMap.get(key);
    this.freqMap.get(node.freq).delete(key);
    // if frequency list is empty after deletion, update min frequency
    if (this.freqMap.get(node.freq).size === 0 && this.minFreq === node.freq) this.minFreq++;
    node.freq++;
    // add key to new frequency list
    if (!this.freqMap.has(node.freq)) this.freqMap.set(node.freq, new Map());
    this.freqMap.get(node.freq).set(key, node);
    return node.val;
}

LFUCache.prototype.put = function(key, value) {
    // if cache is full and key is not in cache, remove least frequently used key
    if (this.capacity === 0) return;
    if (this.keyMap.has(key)) {
        this.keyMap.get(key).val = value;
        this.get(key); // increment frequency
        return;
    }
    if (this.keyMap.size === this.capacity) {
        // find least frequently used key
        let lfuKey = this.freqMap.get(this.minFreq).keys().next().value;
        this.keyMap.delete(lfuKey);
        this.freqMap.get(this.minFreq).delete(lfuKey);
    }
    // add new key to cache
    let newNode = {key, val: value, freq: 1};
    this.keyMap.set(key, newNode);
    if (!this.freqMap.has(1)) this.freqMap.set(1, new Map());
    this.freqMap.get(1).set(key, newNode);
    this.minFreq = 1;
}

function minMoves2(nums) {
