function islandPerimeter(grid) {
    let perimeter = 0;
    // iterate over each cell in the grid to check for land cells
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[i].length; j++) {
            // if the current cell is a land cell
            if (grid[i][j] === 1) {
                // check the top edge of the cell
                if (i === 0 || grid[i - 1][j] === 0) {
                    perimeter++;
                }
                // check the bottom edge of the cell
                if (i === grid.length - 1 || grid[i + 1][j] === 0) {
                    perimeter++;
                }
                // check the left edge of the cell
                if (j === 0 || grid[i][j - 1] === 0) {
                    perimeter++;
                }
                // check the right edge of the cell
                if (j === grid[i].length - 1 || grid[i][j + 1] === 0) {
                    perimeter++;
                }
            }
        }
    }
    return perimeter;
}

function getMaxRepetitions(s1, n1, s2, n2) {
    let dp = new Array(s2.length + 1).fill(0);
    for (let i = 1; i <= s2.length; i++) {
        let count = 0;
        let j = 0;
        for (let k = 0; k < s1.length * n1; k++) {
            // if current character in s1 matches the current character in s2, move to the next character in s2
            if (s1[k % s1.length] === s2[j]) j++;
            // if we have matched all characters in s2, increment the count and reset j
            if (j === i) { count++; j = 0; }
        }
        dp[i] = count;
    }
    // calculate the maximum number of times s2 can be repeated in s1
    return Math.floor(dp[s2.length] / n2);
}

function validIPAddress(queryIP) {
    if (queryIP.includes('.')) {
        // Split the IP into parts and check if each part is a valid IPv4 segment
        let parts = queryIP.split('.');
        if (parts.length !== 4) return 'Neither';
        for (let part of parts) {
            // Check if the part is a valid IPv4 segment (between 0 and 255, no leading zeros)
            if (isNaN(part) || part.length > 1 && part[0] === '0' || parseInt(part) < 0 || parseInt(part) > 255) return 'Neither';
        }
        return 'IPv4';
    } else if (queryIP.includes(':')) {
        // Split the IP into parts and check if each part is a valid IPv6 segment
        let parts = queryIP.split(':');
        if (parts.length !== 8) return 'Neither';
        for (let part of parts) {
            // Check if the part is a valid IPv6 segment (between 0 and FFFF, no more than 4 characters)
            if (part.length > 4 || !/^[0-9a-fA-F]+$/.test(part)) return 'Neither';
        }
        return 'IPv6';
    } else {
        return 'Neither';
    }
}

function findSubstringInWraproundString(s) {
    let count = 0; // count of unique substrings
    let maxLength = new Array(26).fill(0); // max length of substring ending at each character
    let maxLengthSoFar = 0; // max length of substring ending at current character

    for (let i = 0; i < s.length; i++) {
        // if current character is next in sequence or wraparound, increase length of substring
        if (i > 0 && (s.charCodeAt(i) - s.charCodeAt(i - 1) === 1 || s.charCodeAt(i) - s.charCodeAt(i - 1) === -25)) {
            maxLengthSoFar++;
        } else {
            maxLengthSoFar = 1;
        }

        // update max length of substring ending at current character
        let charIndex = s.charCodeAt(i) - 'a'.charCodeAt(0);
        if (maxLengthSoFar > maxLength[charIndex]) {
            // update count of unique substrings
            count += maxLengthSoFar - maxLength[charIndex];
            maxLength[charIndex] = maxLengthSoFar;
        }
    }

    return count;
}

