function canBeConcatenated(word, wordSet, start, piecesUsed) {
    if (start === word.length) {
        return piecesUsed >= 2;
    }
    for (let end = start + 1; end <= word.length; end++) {
        if (wordSet.has(word.substring(start, end)) && canBeConcatenated(word, wordSet, end, piecesUsed + 1)) {
