function findComplement(num) {
    // calculate the number of bits in the given number
    let numberOfBits = Math.floor(Math.log2(num)) + 1;
    // create a mask with all bits set to 1, with the same number of bits as the input number
    let mask = (1 << numberOfBits) - 1;
    // flip all the bits in the input number using the mask
    return num ^ mask;
}

function randPoint(radius, x_center, y_center) {
