function totalHammingDistance(nums) {
  let totalDistance = 0;
  // for each bit position, calculate the number of pairs where the bits are different
  for (let i = 0; i < 30; i++) {
    let ones = 0;
    // count the number of ones at the current bit position
    for (let num of nums) {
      if ((num >> i) & 1) ones++;
    }
    // the number of zeros at the current bit position is the total count minus the number of ones
    let zeros = nums.length - ones;
    // the number of pairs where the bits are different is the product of the number of ones and zeros
    totalDistance += ones * zeros;
  }
  return totalDistance;
}

function medianSlidingWindow(nums, k) {
    let result = [];
    for (let i = 0; i <= nums.length - k; i++) {
        // Create a window of size k and sort it to find the median
        let window = nums.slice(i, i + k).sort((a, b) => a - b);
        // If the window size is even, the median is the average of the two middle numbers
        if (k % 2 === 0) {
            // Calculate the median as the average of the two middle numbers
            result.push((window[k / 2 - 1] + window[k / 2]) / 2);
        } else {
            // If the window size is odd, the median is the middle number
            result.push(window[Math.floor(k / 2)]);
        }
    }
    return result;
}

