function largestPalindromeProduct(n) {
    let max = Math.pow(10, n) - 1;
    let min = Math.pow(10, n - 1);
    let largestPalindrome = 0;
    for (let i = max; i >= min; i--) {
        // generate all possible products of two n-digit numbers in descending order
        for (let j = i; j >= min; j--) {
            let product = i * j;
            // check if the product is a palindrome and larger than the current largest palindrome
            if (isPalindrome(product) && product > largestPalindrome) {
                largestPalindrome = product;
            }
        }
    }
    // calculate the result modulo 1337
    return largestPalindrome % 1337;
}

function isPalindrome(num) {
