    // Calculate the length of the first group
    var firstGroupLength = sNoDashes.length % k;
    // If the first group is not empty, add it to the result
    var result = (firstGroupLength > 0) ? sNoDashes.substring(0, firstGroupLength) : '';
    // Add the rest of the groups to the result
    for (var i = firstGroupLength; i < sNoDashes.length; i += k) {
        // Add a dash before each group except the first one
        if (i > 0) result += '-';
