function smallestGoodBase(n) {
    const num = BigInt(n);
    const maxLen = Math.floor(Math.log(Number(num)) / Math.log(2)) + 1;
    for (let len = maxLen; len >= 2; len--) {
        let left = 2n, right = num - 1n;
        while (left <= right) {
            const mid = (left + right) / 2n;
            let sum = 0n;
            for (let i = 0; i < len; i++) {
                sum = sum * mid + 1n;
            }
            if (sum === num) {
                return mid.toString();
            } else if (sum < num) {
                left = mid + 1n;
            } else {
                right = mid - 1n;
            }
        }
    }
    return (num - 1n).toString();
}

function findRadius(houses, heaters) {
