    for (let house of houses) { 
        // find the closest heater to the current house
        while (heaterIndex < heaters.length - 1 && Math.abs(heaters[heaterIndex + 1] - house) <= Math.abs(heaters[heaterIndex] - house)) 
            heaterIndex++;
        // update the result with the maximum distance between a house and its closest heater
