    }
    return result;
}

function PredictTheWinner(nums) {
    let n = nums.length;
    let dp = new Array(n).fill(0).map(() => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        dp[i][i] = nums[i]; // initialize the diagonal with the numbers themselves
    }
    for (let d = 1; d < n; d++) {
        for (let i = 0; i < n - d; i++) {
            let j = i + d;
            dp[i][j] = Math.max(nums[i] - dp[i + 1][j], nums[j] - dp[i][j - 1]); // choose the maximum difference
        }
    }
    return dp[0][n - 1] >= 0; // return true if player 1's score is greater than or equal to player 2's score
}

function findMaxConsecutiveOnes(nums) {
