    if (nums[i] === 1) currentConsecutiveOnes++;
    // if current element is not 1, reset the current consecutive ones count and update max if needed
    else { 
      maxConsecutiveOnes = Math.max(maxConsecutiveOnes, currentConsecutiveOnes); 
      currentConsecutiveOnes = 0; 
    }
  }
  // update max one last time after the loop ends
  maxConsecutiveOnes = Math.max(maxConsecutiveOnes, currentConsecutiveOnes);
  return maxConsecutiveOnes;
}

function findMinStep(board, hand) {
    let memo = new Map();
    function dfs(board, hand) {
        let key = board + ',' + hand;
        if (memo.has(key)) return memo.get(key);
        if (board.length === 0) return 0;
        let res = Infinity;
        for (let i = 0; i < hand.length; i++) {
            let newHand = hand.slice(0, i) + hand.slice(i + 1);
            for (let j = 0; j <= board.length; j++) {
                let newBoard = board.slice(0, j) + hand[i] + board.slice(j);
                newBoard = removeConsecutive(newBoard);
                if (newBoard.length === 0) return 1;
                if (newHand.length > 0) {
                    let temp = dfs(newBoard, newHand);
                    if (temp !== -1) res = Math.min(res, 1 + temp);
                }
            }
        }
        if (res === Infinity) res = -1;
        memo.set(key, res);
        return res;
    }
    function removeConsecutive(board) {
        let changed = true;
        while (changed) {
            changed = false;
            let i = 0;
            while (i < board.length) {
                let j = i;
                while (j < board.length && board[j] === board[i]) j++;
                if (j - i >= 3) {
                    board = board.slice(0, i) + board.slice(j);
                    changed = true;
                    break;
                }
                i = j;
            }
        }
        return board;
    }
    return dfs(board, hand);
}

function constructRectangle(area) {
  let width = Math.floor(Math.sqrt(area)); // start from the square root of the area
  while (area % width !== 0) { // if the area is not divisible by the current width
    width--; // decrement the width
  }
  let length = area / width; // calculate the length
  return [length, width]; // return the length and width
}

