function findSubsequences(nums) {
  const result = new Set();
  function backtrack(start, current) {
    // if current subsequence has at least two elements, add it to the result
    if (current.length >= 2) result.add(JSON.stringify(current));
    for (let i = start; i < nums.length; i++) {
      // if current subsequence is empty or the current number is not less than the last number in the subsequence
      if (current.length === 0 || nums[i] >= current[current.length - 1]) {
        // add the current number to the subsequence and continue the backtracking
        current.push(nums[i]);
        backtrack(i + 1, current);
        // remove the last number from the subsequence for backtracking
        current.pop();
      }
    }
  }
  backtrack(0, []);
  return Array.from(result).map(JSON.parse);
}

function findTargetSumWays(nums, target) {
    let count = 0;
    function backtrack(index, sum) {
        // if we've reached the end of the array, check if the sum equals the target
        if (index === nums.length) {
            if (sum === target) count++;
            return;
        }
        // recursively try adding and subtracting the current number
        backtrack(index + 1, sum + nums[index]);
        backtrack(index + 1, sum - nums[index]);
    }
    backtrack(0, 0);
    return count;
}

function reversePairs(nums) {
    let count = 0;
    function mergeSort(arr) {
        if (arr.length <= 1) return arr;
        const mid = Math.floor(arr.length / 2);
        const left = mergeSort(arr.slice(0, mid));
        const right = mergeSort(arr.slice(mid));
        // count pairs first, using a separate two-pointer pass over the two
        // already-sorted halves (the doubled-value comparison is unrelated to merge order)
        let j = 0;
        for (let i = 0; i < left.length; i++) {
            while (j < right.length && left[i] > 2 * right[j]) j++;
            count += j;
        }
        return merge(left, right);
    }
    function merge(left, right) {
        const result = [];
        let i = 0, j = 0;
        while (i < left.length && j < right.length) {
            if (left[i] <= right[j]) {
                result.push(left[i]);
                i++;
            } else {
                result.push(right[j]);
                j++;
            }
        }
        return result.concat(left.slice(i)).concat(right.slice(j));
    }
    mergeSort(nums);
    return count;
}

function nextGreaterElement(nums1, nums2) {
    let result = new Array(nums1.length).fill(-1);
    let stack = [];
    let map = {};
    // create a map to store the next greater element for each element in nums2
    for (let i = 0; i < nums2.length; i++) {
        // while the stack is not empty and the current element is greater than the top of the stack
        while (stack.length > 0 && nums2[i] > stack[stack.length - 1]) {
            // update the map with the next greater element
            map[stack.pop()] = nums2[i];
        }
        // push the current element to the stack
        stack.push(nums2[i]);
    }
    // for each element in nums1, find its next greater element in the map
    for (let i = 0; i < nums1.length; i++) {
        // if the element is in the map, update the result
        if (nums1[i] in map) {
            result[i] = map[nums1[i]];
        }
    }
    return result;
}

function Solution(rects) {
    this.rects = rects;
    this.weights = [];
    this.totalWeight = 0;
    for (let rect of rects) {
        let weight = (rect[2] - rect[0] + 1) * (rect[3] - rect[1] + 1);
        this.weights.push(weight);
        this.totalWeight += weight;
    }
}

Solution.prototype.pick = function() {
    let rand = Math.floor(Math.random() * this.totalWeight);
    let cumulativeWeight = 0;
    for (let i = 0; i < this.rects.length; i++) {
        cumulativeWeight += this.weights[i];
        if (rand < cumulativeWeight) {
            let rect = this.rects[i];
            // calculate the number of points in the current rectangle that are less than or equal to the random number
            let pointsInRect = rand - (cumulativeWeight - this.weights[i]);
            let x = rect[0] + Math.floor(pointsInRect % (rect[2] - rect[0] + 1));
            let y = rect[1] + Math.floor(pointsInRect / (rect[2] - rect[0] + 1));
            return [x, y];
        }
    }
}

function findDiagonalOrder(mat) {
    const rows = mat.length;
    const cols = mat[0].length;
    const result = new Array(rows * cols);
    let index = 0;
    // iterate over all possible diagonals in the matrix
    for (let k = 0; k < rows + cols - 1; k++) {
        // if the diagonal is going from top-left to bottom-right
        if (k % 2 === 0) {
            // start from the top row and move down
            let i = Math.min(k, rows - 1);
            let j = k - i;
            // traverse the diagonal
            while (i >= 0 && j < cols) {
                result[index++] = mat[i--][j++];
            }
        } 
        // if the diagonal is going from top-right to bottom-left
        else {
            // start from the leftmost column and move right
            let i = Math.max(0, k - cols + 1);
            let j = k - i;
            // traverse the diagonal
            while (i < rows && j >= 0) {
                result[index++] = mat[i++][j--];
            }
        }
    }
    return result;
}

function findWords(words) {
    const rows = ["qwertyuiop", "asdfghjkl", "zxcvbnm"];
    const result = [];
    for (let word of words) {
        // Check if all characters in the word are in the same row
        for (let row of rows) {
            if (word.toLowerCase().split('').every(char => row.includes(char))) {
                result.push(word);
                break;
            }
        }
    }
    return result;
}

function findMode(root) {
    let maxCount = 0;
    let modes = [];
    let countMap = {};
    function dfs(node) {
        // traverse the tree and count occurrences of each value
        if (node) {
            countMap[node.val] = (countMap[node.val] || 0) + 1;
            dfs(node.left);
            dfs(node.right);
        }
    }
    dfs(root);
    // find the maximum count
    for (let key in countMap) {
        // update maxCount if a higher count is found
        if (countMap[key] > maxCount) {
            maxCount = countMap[key];
            modes = [parseInt(key)];
        } else if (countMap[key] === maxCount) {
            // add to modes if the count is equal to maxCount
            modes.push(parseInt(key));
        }
    }
    return modes;
}

function findMaximizedCapital(k, w, profits, capital) {
    let projects = [];
    for (let i = 0; i < profits.length; i++) {
        projects.push([profits[i], capital[i]]);
    }
    projects.sort((a, b) => a[1] - b[1]);
    let availableProjects = [];
    let i = 0;
    while (k > 0) {
        // add available projects to the priority queue
        while (i < projects.length && projects[i][1] <= w) {
            availableProjects.push(projects[i][0]);
            i++;
        }
        if (availableProjects.length === 0) break;
        // select the project with the highest profit
        availableProjects.sort((a, b) => b - a);
        w += availableProjects[0];
        availableProjects.shift();
        k--;
    }
    return w;
}

function nextGreaterElements(nums) {
  const result = new Array(nums.length).fill(-1);
  const stack = [];
  // iterate through the array twice to handle circular case
  for (let i = 0; i < nums.length * 2; i++) {
    const current = nums[i % nums.length];
    // pop elements from stack if current element is greater
    while (stack.length > 0 && nums[stack[stack.length - 1]] < current) {
      // update result array with next greater element
      result[stack.pop()] = current;
    }
    // push current index to stack
    stack.push(i % nums.length);
  }
  return result;
}

function convertToBase7(num) {
    if (num === 0) return '0'; // handle special case where num is 0
    let isNegative = num < 0; // check if the number is negative
    num = Math.abs(num); // convert to positive for calculation
    let result = ''; // initialize result string
    while (num > 0) { // loop until num becomes 0
        result = num % 7 + result; // prepend the remainder to the result
        num = Math.floor(num / 7); // update num for the next iteration
    }
    return isNegative ? '-' + result : result; // add negative sign if needed
}

