    var sortedScore = score.slice().sort(function(a, b) { return b - a; });
    var result = [];
    for (var i = 0; i < score.length; i++) {
        // find the index of the current score in the sorted array to determine its rank
        var rank = sortedScore.indexOf(score[i]) + 1;
        // assign the corresponding rank or medal to the result array
        if (rank === 1) result.push("Gold Medal");
        else if (rank === 2) result.push("Silver Medal");
