function checkPerfectNumber(num) {
  let sumOfDivisors = 0;
  // loop through all numbers up to num to check for divisors
  for (let i = 1; i < num; i++) {
    // check if i is a divisor of num
    if (num % i === 0) {
      sumOfDivisors += i;
    }
  }
  // check if sum of divisors equals num
  return sumOfDivisors === num;
}

function findFrequentTreeSum(root) {
    let sumFrequency = {};
    let maxFrequency = 0;
    let result = [];

    function dfs(node) {
        // calculate the sum of the subtree rooted at the current node
        if (node === null) return 0;
        let sum = node.val + dfs(node.left) + dfs(node.right);

        // update the frequency of the subtree sum
        sumFrequency[sum] = (sumFrequency[sum] || 0) + 1;

        // update the max frequency if necessary
        if (sumFrequency[sum] > maxFrequency) {
            maxFrequency = sumFrequency[sum];
            result = [sum];
        } 
        // if the frequency of the current sum is equal to the max frequency, add it to the result
        else if (sumFrequency[sum] === maxFrequency) {
            result.push(sum);
        }

        return sum;
    }

    dfs(root);
    return result;
}

function findPoisonedDuration(timeSeries, duration) {
    let totalDuration = 0;
    for (let i = 0; i < timeSeries.length; i++) {
        // calculate the duration of the current attack, considering the next attack
        totalDuration += Math.min(duration, (i < timeSeries.length - 1 ? timeSeries[i + 1] : timeSeries[i] + duration) - timeSeries[i]);
    }
    return totalDuration;
}

function findBottomLeftValue(root) {
    let result = root.val;
    let maxDepth = 0;
    function dfs(node, depth) {
        // update result if current node is at a greater depth or at the same depth but more to the left
        if (depth > maxDepth) {
            maxDepth = depth;
            result = node.val;
        }
        // recursively traverse the tree
        if (node.left) dfs(node.left, depth + 1);
        if (node.right) dfs(node.right, depth + 1);
    }
    dfs(root, 0);
    return result;
}

function largestValues(root) {
    if (!root) return [];
    let result = [];
    let queue = [root];
    // perform BFS to traverse the tree level by level
    while (queue.length > 0) {
        let levelSize = queue.length;
        let maxVal = -Infinity;
        // find the max value in the current level
        for (let i = 0; i < levelSize; i++) {
            let node = queue.shift();
            maxVal = Math.max(maxVal, node.val);
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        result.push(maxVal);
    }
    return result;
}

function findRotateSteps(ring, key) {
    let n = ring.length, m = key.length;
    let dp = Array(m).fill(0).map(() => Array(n).fill(Infinity));
    // initialize the dp array for the first character of the key
    for (let j = 0; j < n; j++) {
        if (ring[j] === key[0]) {
            dp[0][j] = Math.min(dp[0][j], Math.min(j, n - j) + 1);
        }
    }
    // fill up the dp array for the rest of the characters in the key
    for (let i = 1; i < m; i++) {
        for (let j = 0; j < n; j++) {
            // check all possible previous positions of the ring
            for (let k = 0; k < n; k++) {
                if (ring[k] === key[i - 1]) {
                    // calculate the minimum steps to reach the current position from the previous position
                    dp[i][j] = Math.min(dp[i][j], dp[i - 1][k] + Math.min(Math.abs(j - k), n - Math.abs(j - k)) + 1);
                }
            }
        }
    }
    // find the minimum steps to spell all characters in the key
    let minSteps = Infinity;
    for (let j = 0; j < n; j++) {
        if (ring[j] === key[m - 1]) {
            minSteps = Math.min(minSteps, dp[m - 1][j]);
        }
    }
    return minSteps;
}

function findMinMoves(machines) {
    var totalDresses = machines.reduce(function(a, b) { return a + b; });
    var n = machines.length;
    if (totalDresses % n !== 0) return -1;
    var averageDressesPerMachine = Math.floor(totalDresses / n);
    var maxMoves = 0;
    var currentImbalance = 0;
    for (var i = 0; i < n; i++) {
        // calculate the imbalance of dresses at the current machine
        currentImbalance += machines[i] - averageDressesPerMachine;
        // update maxMoves with the maximum of the current maxMoves and the absolute value of the current imbalance
        maxMoves = Math.max(maxMoves, Math.abs(currentImbalance));
        // update maxMoves with the maximum of the current maxMoves and the difference between the current machine's dresses and the average dresses per machine
        maxMoves = Math.max(maxMoves, machines[i] - averageDressesPerMachine);
    }
    return maxMoves;
}

function change(amount, coins) {
  let dp = new Array(amount + 1).fill(0);
  dp[0] = 1; // base case: one way to make up amount 0 (using no coins)
  for (let coin of coins) {
    for (let i = coin; i <= amount; i++) {
      // update dp[i] by adding the number of combinations that can make up the remaining amount (i - coin)
      dp[i] += dp[i - coin];
    }
  }
  return dp[amount];
}

