  return false;
}

function createRandomFlipMatrix(m, n) {
    let total = m * n;
    let availableIndices = new Set();
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            availableIndices.add(i * n + j);
        }
    }

    function flip() {
        // generate a random index from the available indices
        let randomIndex = Math.floor(Math.random() * availableIndices.size);
        let index = Array.from(availableIndices)[randomIndex];
        availableIndices.delete(index);
        return [Math.floor(index / n), index % n];
    }

    function reset() {
        availableIndices = new Set();
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                availableIndices.add(i * n + j);
            }
        }
    }

    return { flip, reset };
}

function checkSubarraySum(nums, k) {
    let prefixSum = 0;
    let sumMap = new Map();
    sumMap.set(0, -1);
    for (let i = 0; i < nums.length; i++) {
        prefixSum += nums[i];
        // calculate the remainder of the prefix sum when divided by k
        let remainder = prefixSum % k;
        // if the remainder is already in the map, it means we have found a good subarray
        if (sumMap.has(remainder)) {
            // if the difference between the current index and the index stored in the map is greater than 1, return true
            if (i - sumMap.get(remainder) > 1) return true;
        } else {
            // if the remainder is not in the map, add it to the map with the current index
            sumMap.set(remainder, i);
        }
    }
    return false;
}

function findLUSlength(strs) {
    // count occurrences of each string
    let count = {};
    for (let str of strs) {
        if (count[str]) count[str]++;
        else count[str] = 1;
    }

    // filter out strings that appear more than once
    let uniqueStrs = Object.keys(count).filter(str => count[str] === 1);

    // if no unique strings, return -1
    if (uniqueStrs.length === 0) return -1;

    // sort unique strings by length in descending order
    uniqueStrs.sort((a, b) => b.length - a.length);

    // check if the longest unique string is a subsequence of any other string
    for (let i = 0; i < uniqueStrs.length; i++) {
        let isSubsequence = false;
        for (let j = 0; j < strs.length; j++) {
            // if the string is a subsequence of another string, skip it
            if (uniqueStrs[i] === strs[j]) continue;
            // check if the string is a subsequence of the current string
            if (isSubsequenceOf(uniqueStrs[i], strs[j])) {
                isSubsequence = true;
                break;
            }
        }
        // if the string is not a subsequence of any other string, return its length
        if (!isSubsequence) return uniqueStrs[i].length;
    }

    // if no uncommon subsequence is found, return -1
    return -1;
}

function isSubsequenceOf(s1, s2) {
    let i = 0, j = 0;
    while (i < s1.length && j < s2.length) {
        if (s1[i] === s2[j]) i++;
        j++;
    }
    return i === s1.length;
}

function longestPalindromicSubsequence(s) {
    let n = s.length;
    let dp = new Array(n).fill(0).map(() => new Array(n).fill(0));
    // initialize all substrings with one character as palindromes
    for (let i = 0; i < n; i++) {
        dp[i][i] = 1;
    }
    // check for substrings of length 2
    for (let i = 0; i < n - 1; i++) {
        if (s[i] === s[i + 1]) {
            dp[i][i + 1] = 2;
        } else {
            dp[i][i + 1] = 1;
        }
    }
    // check for lengths greater than 2
    for (let length = 3; length <= n; length++) {
        for (let i = 0; i < n - length + 1; i++) {
            let j = i + length - 1;
            // if the first and last characters are the same, add 2 to the length of the subsequence in between
            if (s[i] === s[j]) {
                dp[i][j] = dp[i + 1][j - 1] + 2;
            } else {
                // otherwise, take the maximum length of the subsequences without the first or last character
                dp[i][j] = Math.max(dp[i + 1][j], dp[i][j - 1]);
            }
        }
    }
    // the length of the longest palindromic subsequence is stored in dp[0][n - 1]
    return dp[0][n - 1];
}

function findMaxLength(nums) {
    let maxLength = 0;
    let count = 0;
    let countMap = {};
    countMap[0] = -1; // base case for when count is 0
    for (let i = 0; i < nums.length; i++) {
        // update count based on current element (1 for 1, -1 for 0)
        count += nums[i] === 1 ? 1 : -1;
        // if count is already in map, update maxLength
        if (count in countMap) {
            maxLength = Math.max(maxLength, i - countMap[count]);
        } else {
            // otherwise, add count to map with current index
            countMap[count] = i;
        }
    }
    return maxLength;
}

function findLongestWord(s, dictionary) {
    function isSubsequence(word) {
        let sIndex = 0, wordIndex = 0;
        // iterate through the string and word, checking if characters match in order
        while (sIndex < s.length && wordIndex < word.length) {
            if (s[sIndex] === word[wordIndex]) wordIndex++;
            sIndex++;
        }
        // return true if all characters in the word were found in the string
        return wordIndex === word.length;
    }

    let longestWord = '';
    // iterate through each word in the dictionary
    for (let word of dictionary) {
        // check if the word is a subsequence of the string
        if (isSubsequence(word)) {
            // if the word is longer than the current longest word, or if it's the same length but lexicographically smaller, update the longest word
            if (word.length > longestWord.length || (word.length === longestWord.length && word < longestWord)) longestWord = word;
        }
    }
    return longestWord;
}

function countArrangement(n) {
    let count = 0;
    let visited = new Array(n + 1).fill(false);
    function backtrack(index) {
        // if we have filled all positions, increment the count
        if (index === n + 1) count++;
        else {
            for (let i = 1; i <= n; i++) {
                // check if the current number is not visited and it satisfies the condition
                if (!visited[i] && (i % index === 0 || index % i === 0)) {
                    visited[i] = true;
                    // recursively call the backtrack function for the next position
                    backtrack(index + 1);
                    // reset the visited status for the current number
                    visited[i] = false;
                }
            }
        }
    }
    backtrack(1);
    return count;
}

function findLUSlength(a, b) {
    // if a and b are equal, there's no uncommon subsequence, so return -1
    if (a === b) return -1;
    // otherwise, the longest uncommon subsequence is the longer of the two strings
    return Math.max(a.length, b.length);
}

function pickIndex(w) {
    // calculate the total sum of weights
    let totalSum = 0;
    for (let i = 0; i < w.length; i++) {
        totalSum += w[i];
    }

    // generate a random number between 0 and totalSum
    let randomNum = Math.random() * totalSum;

    // find the index where the cumulative sum exceeds the random number
    let cumulativeSum = 0;
    for (let i = 0; i < w.length; i++) {
        cumulativeSum += w[i];
        // if the cumulative sum exceeds the random number, return the current index
        if (cumulativeSum >= randomNum) {
            return i;
        }
    }
}

function getMinimumDifference(root) {
    let minDiff = Infinity;
    let prevVal = null;
    function inorder(node) {
        if (node) {
            inorder(node.left); // traverse left subtree
            if (prevVal !== null) {
                minDiff = Math.min(minDiff, Math.abs(node.val - prevVal)); // update minDiff
            }
            prevVal = node.val; // update prevVal
            inorder(node.right); // traverse right subtree
        }
    }
    inorder(root);
    return minDiff;
}

function updateBoard(board, click) {
    let rows = board.length;
    let cols = board[0].length;
    let row = click[0];
    let col = click[1];
    if (board[row][col] === 'M') {
        board[row][col] = 'X';
    } else {
        dfs(board, row, col);
    }
    return board;
}

function dfs(board, row, col) {
    let rows = board.length;
    let cols = board[0].length;
    if (row < 0 || row >= rows || col < 0 || col >= cols || board[row][col] !== 'E') {
        return;
    }
    let count = 0;
    for (let i = -1; i <= 1; i++) {
        for (let j = -1; j <= 1; j++) {
            let newRow = row + i;
            let newCol = col + j;
            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && board[newRow][newCol] === 'M') {
                count++;
            }
        }
    }
    if (count === 0) {
        board[row][col] = 'B';
        dfs(board, row - 1, col);
        dfs(board, row + 1, col);
        dfs(board, row, col - 1);
        dfs(board, row, col + 1);
        dfs(board, row - 1, col - 1);
        dfs(board, row - 1, col + 1);
        dfs(board, row + 1, col - 1);
        dfs(board, row + 1, col + 1);
    } else {
        board[row][col] = count.toString();
    }
}

function findPairs(nums, k) {
    if (k < 0) return 0;
    let freq = new Map();
    for (let num of nums) freq.set(num, (freq.get(num) || 0) + 1);
    let count = 0;
    if (k === 0) {
        for (let [num, c] of freq) if (c >= 2) count++;
    } else {
        for (let num of freq.keys()) if (freq.has(num + k)) count++;
    }
    return count;
}

