function complexNumberMultiply(num1, num2) {
    // extract real and imaginary parts from num1
    let num1Real = parseInt(num1.substring(0, num1.indexOf('+')));
    let num1Imaginary = parseInt(num1.substring(num1.indexOf('+') + 1, num1.length - 1));

    // extract real and imaginary parts from num2
    let num2Real = parseInt(num2.substring(0, num2.indexOf('+')));
    let num2Imaginary = parseInt(num2.substring(num2.indexOf('+') + 1, num2.length - 1));

    // calculate real part of the result
    let resultReal = num1Real * num2Real - num1Imaginary * num2Imaginary;

    // calculate imaginary part of the result
    let resultImaginary = num1Real * num2Imaginary + num1Imaginary * num2Real;

    // construct the result string
    return resultReal + '+' + resultImaginary + 'i';
}

function convertBST(root) {
    let sum = 0;
    function reverseInorder(node) {
        if (node === null) return;
        // traverse the right subtree first to get the sum of all greater nodes
        reverseInorder(node.right);
        // update the node's value by adding the sum of all greater nodes
        node.val += sum;
        // update the sum for the next nodes
        sum = node.val;
        // traverse the left subtree
        reverseInorder(node.left);
    }
    reverseInorder(root);
    return root;
}

function singleNonDuplicate(nums) {
    let low = 0, high = nums.length - 1;
    while (low < high) {
        // calculate mid and consider the pair index
        let mid = Math.floor(low + (high - low) / 2);
        // if mid is even and mid + 1 is the same or mid is odd and mid - 1 is the same, then the single element is on the right half
        if ((mid % 2 === 0 && nums[mid] === nums[mid + 1]) || (mid % 2 === 1 && nums[mid] === nums[mid - 1])) {
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return nums[low];
}

function reverseStrII(s, k) {
  let result = '';
  for (let i = 0; i < s.length; i += 2 * k) {
    // reverse the first k characters of the current 2k block
    let reversed = s.substring(i, Math.min(i + k, s.length)).split('').reverse().join('');
    // append the reversed substring and the remaining characters in the block
    result += reversed + s.substring(Math.min(i + k, s.length), Math.min(i + 2 * k, s.length));
  }
  return result;
}

function updateMatrix(mat) {
    var rows = mat.length;
    var cols = mat[0].length;
    var directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    var queue = [];
    var result = new Array(rows).fill(0).map(() => new Array(cols).fill(Infinity));

    // initialize queue with all zeros and update result matrix
    for (var i = 0; i < rows; i++) {
        for (var j = 0; j < cols; j++) {
            if (mat[i][j] === 0) {
                queue.push([i, j]);
                result[i][j] = 0;
            }
        }
    }

    // perform BFS
    while (queue.length > 0) {
        var current = queue.shift();
        var x = current[0];
        var y = current[1];
        // explore all neighbors and update distance if necessary
        for (var i = 0; i < directions.length; i++) {
            var newX = x + directions[i][0];
            var newY = y + directions[i][1];
            if (newX >= 0 && newX < rows && newY >= 0 && newY < cols && result[newX][newY] > result[x][y] + 1) {
                result[newX][newY] = result[x][y] + 1;
                queue.push([newX, newY]);
            }
        }
    }
    return result;
}

function diameterOfBinaryTree(root) {
    let maxDiameter = 0;
    function depthFirstSearch(node) {
        // calculate the depth of the left and right subtrees
        if (node === null) return 0;
        let leftDepth = depthFirstSearch(node.left);
        let rightDepth = depthFirstSearch(node.right);
        // update the max diameter if the current path is longer
        maxDiameter = Math.max(maxDiameter, leftDepth + rightDepth);
        // return the depth of the current node
        return Math.max(leftDepth, rightDepth) + 1;
    }
    depthFirstSearch(root);
    return maxDiameter;
}

function findMinDifference(timePoints) {
    let minutes = [];
    // Convert each time point to minutes and store in the minutes array
    for (let time of timePoints) {
        let [hour, minute] = time.split(':').map(Number);
        minutes.push(hour * 60 + minute);
    }
    // Sort the minutes array in ascending order
    minutes.sort((a, b) => a - b);
    let minDiff = Infinity;
    // Calculate the minimum time difference between two adjacent time points
    for (let i = 0; i < minutes.length - 1; i++) {
        minDiff = Math.min(minDiff, minutes[i + 1] - minutes[i]);
    }
    // Calculate the time difference between the first and last time points
    minDiff = Math.min(minDiff, 24 * 60 - minutes[minutes.length - 1] + minutes[0]);
    return minDiff;
}

function removeBoxes(boxes) {
    let n = boxes.length;
    let memo = new Map();

    function dp(left, right, k) {
        if (left > right) return 0;
        let key = left + ',' + right + ',' + k;
        if (memo.has(key)) return memo.get(key);
        let max = (k + 1) * (k + 1) + dp(left, right - 1, 0);
        for (let i = right - 1; i >= left; i--) {
            if (boxes[i] === boxes[right])
                max = Math.max(max, dp(left, i, k + 1) + dp(i + 1, right - 1, 0));
        }
        memo.set(key, max);
        return max;
    }

    return dp(0, n - 1, 0);
}

function findCircleNum(isConnected) {
