    if (s[i] === 'A') absenceCount++;
    // check if the current character is 'L' to count consecutive lates
    if (s[i] === 'L') lateCount++;
    // if the current character is not 'L', reset the late count
    else lateCount = 0;
    // if the student has 2 or more absences or 3 or more consecutive lates, return false
    if (absenceCount >= 2 || lateCount >= 3) return false;
  }
  // if the function hasn't returned false, the student is eligible for the award
  return true;
}

function optimalDivision(nums) {
    let n = nums.length;
    if (n === 1) return nums[0].toString();
    if (n === 2) return nums[0] + '/' + nums[1];
    let result = nums[0] + '/(';
    // iterate through the rest of the numbers and append them to the result string with '/' in between
    for (let i = 1; i < n - 1; i++) {
        result += nums[i] + '/';
    }
    // append the last number and close the parenthesis
    result += nums[n - 1] + ')';
