function checkRecord(n) {
    const MOD = 1000000007;
    // dp[i][a][l]: number of valid records of length i with a absences so far
    // and l trailing consecutive lates
    let dp = new Array(n + 1);
    for (let i = 0; i <= n; i++) {
        dp[i] = new Array(2).fill(0).map(() => new Array(3).fill(0));
    }
    dp[0][0][0] = 1;
    for (let i = 1; i <= n; i++) {
        for (let a = 0; a < 2; a++) {
            for (let l = 0; l < 3; l++) {
                const prev = dp[i - 1][a][l];
                if (prev === 0) continue;
                // add 'P'
                dp[i][a][0] = (dp[i][a][0] + prev) % MOD;
                // add 'L' (only if not already at 2 trailing L's)
                if (l < 2) dp[i][a][l + 1] = (dp[i][a][l + 1] + prev) % MOD;
                // add 'A' (only if no absence yet)
                if (a === 0) dp[i][1][0] = (dp[i][1][0] + prev) % MOD;
            }
        }
    }
    let res = 0;
    for (let i = 0; i < 2; i++) {
        for (let j = 0; j < 3; j++) {
            res = (res + dp[n][i][j]) % MOD;
        }
    }
    return res;
}

function leastBricks(wall) {
    let edgeCount = {};
    for (let row of wall) {
        let edgePosition = 0;
        // calculate the edge positions for each brick in the row and count the edges
        for (let i = 0; i < row.length - 1; i++) {
            edgePosition += row[i];
            edgeCount[edgePosition] = (edgeCount[edgePosition] || 0) + 1;
        }
    }
    let maxEdges = 0;
    // find the maximum count of edges at the same position
    for (let count in edgeCount) {
        // this is the key logic: the more edges at a position, the fewer bricks will be crossed
        maxEdges = Math.max(maxEdges, edgeCount[count]);
    }
    // the minimum number of bricks crossed is the total number of rows minus the maximum count of edges
    return wall.length - maxEdges;
}

function reverseWords(s) {
    let words = s.split(' ');
