        words[i] = words[i].split('').reverse().join(''); // reverse the characters in the word
    return words.join(' ');
}

function nextGreaterElement(n) {
    let numStr = n.toString();
    let i = numStr.length - 2;
    // find the first decreasing digit from right to left
    while (i >= 0 && numStr[i] >= numStr[i + 1]) {
        i--;
    }
    if (i < 0) return -1;
    let j = numStr.length - 1;
    // find the smallest digit greater than numStr[i] from right to left
    while (j > i && numStr[j] <= numStr[i]) {
        j--;
    }
    let numArr = numStr.split('');
    // swap numStr[i] and numStr[j]
    [numArr[i], numArr[j]] = [numArr[j], numArr[i]];
    // sort the digits after i in ascending order
    let right = numArr.slice(i + 1).sort((a, b) => a - b);
    // combine the left part and the sorted right part
    numArr = numArr.slice(0, i + 1).concat(right);
    let result = parseInt(numArr.join(''));
    // check if the result is within the 32-bit integer range
    return result > 2147483647 ? -1 : result;
}

function maxDepth(root) {
    if (!root) return 0; // base case: if root is null, depth is 0
    let maxChildDepth = 0; 
    for (let child of root.children) // iterate over each child of the root
        maxChildDepth = Math.max(maxChildDepth, maxDepth(child)); // recursively calculate the depth of each child
    return 1 + maxChildDepth; // add 1 to the maximum child depth to get the depth of the current node
}

function buildTree(flat) {
    if (!flat || flat.length === 0) return null;
    const root = { isLeaf: flat[0][0], val: flat[0][1], children: null };
    const q = [root];
    let i = 1;
    const n = flat.length;
    while (q.length && i < n) {
        const node = q.shift();
        if (node.isLeaf) continue;
        const children = [];
        for (let k = 0; k < 4; k++) {
            if (i < n && flat[i] !== null) {
                const c = { isLeaf: flat[i][0], val: flat[i][1], children: null };
                children.push(c);
                q.push(c);
                i++;
            } else if (i < n && flat[i] === null) {
                i++;
            } else break;
        }
        node.children = children;
    }
    return root;
}

function serialize(root) {
    if (root === null) return [];
    const out = [[root.isLeaf, root.val]];
    const q = [root];
    while (q.length) {
        const node = q.shift();
        if (node.isLeaf || !node.children || node.children.length === 0) {
            for (let k = 0; k < 4; k++) out.push(null);
        } else {
            for (const c of node.children) {
                out.push([c.isLeaf, c.val]);
                q.push(c);
            }
        }
    }
    while (out.length && out[out.length - 1] === null) out.pop();
    return out;
}

function intersectTrees(t1, t2) {
    if (t1.isLeaf && t2.isLeaf) return { isLeaf: 1, val: t1.val | t2.val, children: null };
    if (t1.isLeaf) return t1.val === 1 ? t1 : t2;
    if (t2.isLeaf) return t2.val === 1 ? t2 : t1;
    const children = t1.children.map((c1, idx) => intersectTrees(c1, t2.children[idx]));
    const allLeaves = children.every(c => c.isLeaf);
    if (allLeaves) {
        const vals = new Set(children.map(c => c.val));
        if (vals.size === 1) return { isLeaf: 1, val: children[0].val, children: null };
    }
    return { isLeaf: 0, val: 0, children: children };
}

function intersect(flat1, flat2) {
    const t1 = buildTree(flat1);
    const t2 = buildTree(flat2);
    const result = intersectTrees(t1, t2);
    return serialize(result);
}

function matrixReshape(mat, r, c) {
    let originalRows = mat.length;
    let originalColumns = mat[0].length;
    // Check if the total number of elements in the original matrix is equal to the total number of elements in the reshaped matrix
    if (originalRows * originalColumns !== r * c) return mat;
    let reshapedMatrix = new Array(r);
    let index = 0;
    // Iterate over the rows of the reshaped matrix
    for (let i = 0; i < r; i++) {
        reshapedMatrix[i] = new Array(c);
        // Fill the current row of the reshaped matrix with elements from the original matrix
        for (let j = 0; j < c; j++) {
            let originalRow = Math.floor(index / originalColumns);
            let originalColumn = index % originalColumns;
            reshapedMatrix[i][j] = mat[originalRow][originalColumn];
            index++;
        }
    }
    return reshapedMatrix;
}

function arrayNesting(nums) {
  let maxLength = 0;
  let visited = new Array(nums.length).fill(false);
  for (let i = 0; i < nums.length; i++) {
    if (!visited[i]) {
      let currentLength = 0;
      let currentIndex = i;
      // start a depth-first search from the current index
      while (!visited[currentIndex]) {
        visited[currentIndex] = true;
        currentLength++;
        currentIndex = nums[currentIndex];
      }
      maxLength = Math.max(maxLength, currentLength);
    }
  }
  return maxLength;
}

function checkInclusion(s1, s2) {
    if (s1.length > s2.length) return false;
    let s1Count = {};
    let s2Count = {};
    // Initialize the count of characters in s1
    for (let i = 0; i < s1.length; i++) {
        s1Count[s1[i]] = (s1Count[s1[i]] || 0) + 1;
        s2Count[s2[i]] = (s2Count[s2[i]] || 0) + 1;
    }
    // Check if the first window of s2 is a permutation of s1
    let matches = 0;
    for (let key in s1Count) {
        if (s1Count[key] === s2Count[key]) matches++;
    }
    let left = 0;
    // Slide the window to the right and check for permutations
    for (let right = s1.length; right < s2.length; right++) {
        // Remove the leftmost character from the window
        s2Count[s2[left]]--;
        if (s2Count[s2[left]] === s1Count[s2[left]]) matches++;
        else if (s2Count[s2[left]] === s1Count[s2[left]] - 1) matches--;
        // Add the new character to the window
        s2Count[s2[right]] = (s2Count[s2[right]] || 0) + 1;
        if (s2Count[s2[right]] === s1Count[s2[right]]) matches++;
        else if (s2Count[s2[right]] === s1Count[s2[right]] + 1) matches--;
        // Check if the current window is a permutation of s1
        if (matches === Object.keys(s1Count).length) return true;
        left++;
    }
    // Check the last window
    return matches === Object.keys(s1Count).length;
}

function isSubtree(root, subRoot) {
    // define a helper function to check if two trees are identical
    function isIdentical(t1, t2) {
        // if both trees are null, they are identical
        if (t1 === null && t2 === null) return true;
        // if one tree is null and the other is not, they are not identical
        if (t1 === null || t2 === null) return false;
        // if the values of the nodes are different, the trees are not identical
        if (t1.val !== t2.val) return false;
        // recursively check the left and right subtrees
        return isIdentical(t1.left, t2.left) && isIdentical(t1.right, t2.right);
    }

    // define a helper function to traverse the main tree and check for the subtree
    function traverse(t1) {
        // if the current tree is null, return false
        if (t1 === null) return false;
        // if the current tree is identical to the subtree, return true
        if (isIdentical(t1, subRoot)) return true;
        // recursively traverse the left and right subtrees
        return traverse(t1.left) || traverse(t1.right);
    }

    // start traversing the main tree from the root
    return traverse(root);
}

function distributeCandies(candyType) {
  let uniqueCandies = new Set(candyType); // create a set to store unique candy types
  let maxCandiesToEat = candyType.length / 2; // calculate the maximum number of candies Alice can eat
  return Math.min(uniqueCandies.size, maxCandiesToEat); // return the minimum between the number of unique candies and the maximum number of candies Alice can eat

}

function findPaths(m, n, maxMove, startRow, startColumn) {
    const MOD = 1e9 + 7;
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const memo = new Map();
    function dfs(row, col, moves) {
        // if we are out of moves or out of the grid, return 1 if out of grid, 0 if out of moves
        if (row < 0 || row >= m || col < 0 || col >= n) return 1;
        if (moves <= 0) return 0;
        const key = row + ',' + col + ',' + moves;
        // if we have computed this subproblem before, return the result
        if (memo.has(key)) return memo.get(key);
        let paths = 0;
        // try all four directions
        for (const [dr, dc] of directions) {
            // recursively call dfs for the new position and decrement the moves
            paths = (paths + dfs(row + dr, col + dc, moves - 1)) % MOD;
        }
        // store the result in the memo
        memo.set(key, paths);
        return paths;
    }
    // call the dfs function with the initial position and maxMove
    return dfs(startRow, startColumn, maxMove);
}

function findUnsortedSubarray(nums) {
  let sortedNums = nums.slice().sort((a, b) => a - b);
  let start = nums.length, end = 0;
  // find the first and last indices where the original array differs from the sorted array
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] !== sortedNums[i]) {
      start = Math.min(start, i);
      end = Math.max(end, i);
    }
  }
  // return the length of the unsorted subarray, or 0 if the array is already sorted
  return start < end ? end - start + 1 : 0;
}

function minDistance(word1, word2) {
    let m = word1.length, n = word2.length;
    let dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));
    // Initialize the base case for the first string being empty
    for (let i = 0; i <= m; i++) dp[i][0] = i;
    // Initialize the base case for the second string being empty
    for (let j = 0; j <= n; j++) dp[0][j] = j;
    // Fill up the dp table in a bottom-up manner
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            // If the current characters match, there's no operation needed
            if (word1[i - 1] === word2[j - 1]) dp[i][j] = dp[i - 1][j - 1];
            // Otherwise, try all possible operations and take the one with the minimum cost
            else dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1]);
        }
    }
    return dp[m][n];
}

function outerTrees(trees) {
    const n = trees.length;
    if (n < 4) return trees;
    trees = trees.slice().sort((a,b) => a[0]-b[0] || a[1]-b[1]);
    function cross(o,a,b){ return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0]); }
    const lower = [];
    for (const p of trees) {
        while (lower.length>=2 && cross(lower[lower.length-2], lower[lower.length-1], p) < 0) lower.pop();
        lower.push(p);
    }
    const upper = [];
    for (let i=n-1;i>=0;i--) {
        const p = trees[i];
        while (upper.length>=2 && cross(upper[upper.length-2], upper[upper.length-1], p) < 0) upper.pop();
        upper.push(p);
    }
    const seen = new Set();
    const result = [];
    for (const p of [...lower, ...upper]) {
        const key = p[0]+','+p[1];
        if (!seen.has(key)) { seen.add(key); result.push(p); }
    }
    return result;
}

function preorder(root) {
    let result = [];
    if (!root) return result;
    let stack = [root];
    // push the root node into the stack and start the traversal
    while (stack.length > 0) {
        let node = stack.pop();
        result.push(node.val);
        // add children to the stack in reverse order to maintain the preorder traversal
        for (let i = node.children.length - 1; i >= 0; i--) {
            stack.push(node.children[i]);
        }
    }
    return result;
}

function postorder(root) {
    let result = [];
    // if the tree is empty, return an empty array
    if (!root) return result;

    let stack = [root];
    // iterate through the stack until it's empty
    while (stack.length > 0) {
        let node = stack.pop();
        // add the current node's value to the result array
        result.push(node.val);

        // add the children of the current node to the stack in reverse order
        if (node.children) {
            for (let i = 0; i < node.children.length; i++) {
                stack.push(node.children[i]);
            }
        }
    }

    // return the result array in reverse order
    return result.reverse();
}

function isValid(code) {
    let stack = [];
    let insideCdata = false;
    for (let i = 0; i < code.length; i++) {
        // check if we are entering a cdata section
        if (code.substring(i, i + 9) === "<![CDATA[") {
            insideCdata = true;
            i += 8; // skip the cdata start tag
        }
        // check if we are exiting a cdata section
        else if (insideCdata && code.substring(i, i + 3) === "]]>") {
            insideCdata = false;
            i += 2; // skip the cdata end tag
        }
        // check if we are entering a tag
        else if (code[i] === "<" && !insideCdata) {
            // check if this is a closing tag
            if (code[i + 1] === "/") {
                let j = i + 2;
                let tagName = "";
                // extract the tag name
                while (j < code.length && code[j] !== ">") {
                    tagName += code[j];
                    j++;
                }
                // check if the tag name is valid and the stack is not empty
                if (tagName.length > 0 && tagName.length <= 9 && stack.length > 0 && stack[stack.length - 1] === tagName) {
                    stack.pop();
                } else {
                    return false;
                }
                i = j; // move to the end of the tag
            }
            // check if this is an opening tag
            else {
                let j = i + 1;
                let tagName = "";
                // extract the tag name
                while (j < code.length && code[j] !== ">") {
                    tagName += code[j];
                    j++;
                }
                // check if the tag name is valid
                if (tagName.length > 0 && tagName.length <= 9) {
                    stack.push(tagName);
                } else {
                    return false;
                }
                i = j; // move to the end of the tag
            }
        }
    }
    // check if we are still inside a cdata section or if there are unmatched opening tags
    return !insideCdata && stack.length === 0;
}

function fractionAddition(expression) {
    let numerator = 0, denominator = 1; // initialize numerator and denominator
    let i = 0; 
    while (i < expression.length) { 
        // check if the current character is a negative sign
        let sign = 1; 
        if (expression[i] === '-') {
            sign = -1;
            i++;
        } else if (expression[i] === '+') {
            i++;
        }
        // extract the numerator of the current fraction
        let num = 0;
        while (i < expression.length && expression[i] !== '/') {
            num = num * 10 + parseInt(expression[i]);
            i++;
        }
        i++; // skip the '/'
        // extract the denominator of the current fraction
        let den = 0;
        while (i < expression.length && expression[i] !== '+' && expression[i] !== '-') {
            den = den * 10 + parseInt(expression[i]);
            i++;
        }
        // update the numerator and denominator
        numerator = numerator * den + sign * num * denominator;
        denominator *= den;
        // find the greatest common divisor to simplify the fraction
        let gcd = function(a, b) {
            if (b === 0) return a;
            return gcd(b, a % b);
        };
        let g = gcd(Math.abs(numerator), denominator);
        numerator /= g;
        denominator /= g;
    }
    // return the result as a string
    return numerator + '/' + denominator;
}

function validSquare(p1, p2, p3, p4) {
    // calculate all possible distances between points
    let distances = [distance(p1, p2), distance(p1, p3), distance(p1, p4), 
                      distance(p2, p3), distance(p2, p4), distance(p3, p4)];
    // sort the distances to easily compare the sides and diagonals
    distances.sort((a, b) => a - b);
    // check if the four sides have equal length and the two diagonals have equal length
    return distances[0] === distances[1] && distances[1] === distances[2] && distances[2] === distances[3] 
           && distances[4] === distances[5] && distances[0] < distances[4];
}

function distance(p1, p2) {
    return Math.pow(p1[0] - p2[0], 2) + Math.pow(p1[1] - p2[1], 2);
}

function findLHS(nums) {
    let countMap = {};
    for (let num of nums) {
        countMap[num] = (countMap[num] || 0) + 1;
    }
    let longestLength = 0;
    for (let num in countMap) {
        const n = parseInt(num);
        if (countMap[n + 1]) {
            longestLength = Math.max(longestLength, countMap[n] + countMap[n + 1]);
        }
    }
    return longestLength;
}

function maxCount(m, n, ops) {
  let minRow = m;
  let minCol = n;
  // finding the minimum row and column that covers all operations
  for (let i = 0; i < ops.length; i++) {
    // updating minimum row and column if current operation has smaller row or column
    minRow = Math.min(minRow, ops[i][0]);
    minCol = Math.min(minCol, ops[i][1]);
  }
  // calculating the maximum count by multiplying the minimum row and column
  return minRow * minCol;
}

function findRestaurant(list1, list2) {
    let minIndexSum = Infinity;
    let result = [];
    // Create a hash table to store the index of each restaurant in list1
    let indexMap = {};
    for (let i = 0; i < list1.length; i++) {
        indexMap[list1[i]] = i;
    }
    // Iterate through list2 and find the common strings with the least index sum
    for (let j = 0; j < list2.length; j++) {
        if (indexMap[list2[j]] !== undefined) {
            let indexSum = indexMap[list2[j]] + j;
            // If the index sum is less than the current minimum, update the result
            if (indexSum < minIndexSum) {
                minIndexSum = indexSum;
                result = [list2[j]];
            } 
            // If the index sum is equal to the current minimum, add the string to the result
            else if (indexSum === minIndexSum) {
                result.push(list2[j]);
            }
        }
    }
    return result;
}

function findIntegers(n) {
  let dp = [1, 2];
  // calculate the number of valid integers for each bit length
  for (let i = 2; i <= 30; i++) {
    // the number of valid integers for the current bit length is the sum of the number of valid integers for the previous two bit lengths
    dp.push(dp[i - 1] + dp[i - 2]);
  }
  let result = 0;
  let bitLength = 0;
  // iterate over the bits of n from left to right
  while (n > 0) {
    // if the current bit is 1
    if (n % 2 === 1) {
      // add the number of valid integers for the remaining bit length to the result
      result += dp[bitLength];
      // if the previous bit is also 1, we need to break the loop
      if (n >= 2 && Math.floor(n / 2) % 2 === 1) break;
    }
    // move to the next bit
    n = Math.floor(n / 2);
    bitLength++;
  }
  // add 1 to the result because n itself is a valid integer
  return result + 1;
}

function canPlaceFlowers(flowerbed, n) {
    let count = 0;
    // check each plot to see if we can plant a flower
    for (let i = 0; i < flowerbed.length; i++) {
        // check if the current plot is empty and its neighbors are also empty
        if (flowerbed[i] === 0 && (i === 0 || flowerbed[i - 1] === 0) && (i === flowerbed.length - 1 || flowerbed[i + 1] === 0)) {
            // plant a flower in the current plot
            flowerbed[i] = 1;
            // increment the count of planted flowers
            count++;
            // if we have planted n flowers, we can stop
            if (count === n) break;
        }
    }
    // return true if we have planted n flowers, false otherwise
    return count === n;
}

function tree2str(root) {
    if (!root) return '';
    let result = root.val + '';
    // recursively traverse left subtree and append to result if it's not empty
    if (root.left) result += '(' + tree2str(root.left) + ')';
    // if right subtree exists but left subtree doesn't, we still need to append '()' to indicate the absence of a left child
    if (root.right) {
        // if left subtree doesn't exist, we need to append '()' to indicate its absence
        if (!root.left) result += '()';
        result += '(' + tree2str(root.right) + ')';
    }
    return result;
}

function findDuplicate(paths) {
    let contentMap = {};
    for (let path of paths) {
        // split the path into directory and files
        let [directory, ...files] = path.split(' ');
        for (let file of files) {
            // extract the filename and content from the file string
            let filename = file.substring(0, file.indexOf('('));
            let content = file.substring(file.indexOf('(') + 1, file.indexOf(')'));
            // add the file path to the content map
            if (!contentMap[content]) contentMap[content] = [];
            contentMap[content].push(directory + '/' + filename);
        }
    }
    // filter out the contents that only have one file
    let result = Object.values(contentMap).filter(files => files.length > 1);
    return result;
}

function triangleNumber(nums) {
    nums.sort((a, b) => a - b);
    let count = 0;
    // iterate over all possible triplets and check if they can form a triangle
    for (let i = 0; i < nums.length - 2; i++) {
        // for each i, find the maximum j such that nums[i] + nums[i+1] > nums[j]
        for (let j = i + 1; j < nums.length - 1; j++) {
            // for each j, find the maximum k such that nums[i] + nums[j] > nums[k]
            for (let k = j + 1; k < nums.length; k++) {
                // check if the current triplet can form a triangle
                if (nums[i] + nums[j] > nums[k] && nums[i] + nums[k] > nums[j] && nums[j] + nums[k] > nums[i]) {
                    count++;
                }
            }
        }
    }
    return count;
}

function mergeTrees(root1, root2) {
    // if both trees are empty, return null
    if (!root1 && !root2) return null;
    // if one tree is empty, return the other tree
    if (!root1) return root2;
    if (!root2) return root1;
    // merge the values of the current nodes
    root1.val += root2.val;
    // recursively merge the left and right subtrees
    root1.left = mergeTrees(root1.left, root2.left);
    root1.right = mergeTrees(root1.right, root2.right);
    return root1;
}

function leastInterval(tasks, n) {
    // Create a frequency map of tasks
    let frequencyMap = {};
    for (let task of tasks) {
        if (!frequencyMap[task]) {
            frequencyMap[task] = 0;
        }
        frequencyMap[task]++;
    }

    // Find the maximum frequency and its count
    let maxFrequency = 0;
    let maxFrequencyCount = 0;
    for (let task in frequencyMap) {
        if (frequencyMap[task] > maxFrequency) {
            maxFrequency = frequencyMap[task];
            maxFrequencyCount = 1;
        } else if (frequencyMap[task] === maxFrequency) {
            maxFrequencyCount++;
        }
    }

    // Calculate the minimum number of intervals required
    let intervals = (maxFrequency - 1) * (n + 1) + maxFrequencyCount;
    return Math.max(tasks.length, intervals);
}

function MyCircularQueue(k) {
    this.capacity = k;
    this.queue = new Array(k);
    this.head = 0;
    this.tail = -1;
    this.size = 0;
}

MyCircularQueue.prototype.enQueue = function(value) {
    if (this.isFull()) return false;
    this.tail = (this.tail + 1) % this.capacity;
    this.queue[this.tail] = value;
    this.size++;
    return true;
    // increment tail and use modulus to wrap around to the start of the queue if necessary
}

MyCircularQueue.prototype.deQueue = function() {
    if (this.isEmpty()) return false;
    this.head = (this.head + 1) % this.capacity;
    this.size--;
    return true;
    // increment head and use modulus to wrap around to the start of the queue if necessary
}

MyCircularQueue.prototype.Front = function() {
    if (this.isEmpty()) return -1;
    return this.queue[this.head];
    // return the element at the head of the queue
}

MyCircularQueue.prototype.Rear = function() {
    if (this.isEmpty()) return -1;
    return this.queue[this.tail];
    // return the element at the tail of the queue
}

MyCircularQueue.prototype.isEmpty = function() {
    return this.size === 0;
    // check if the queue is empty
}

MyCircularQueue.prototype.isFull = function() {
    return this.size === this.capacity;
    // check if the queue is full
}

function addOneRow(root, val, depth) {
    if (depth === 1) {
        // create a new node with the given value and make the current root its child
        return { val: val, left: root, right: null };
    }
    function traverse(node, currentDepth) {
        if (node === null) return null;
        if (currentDepth === depth - 1) {
            // add a new node with the given value as the left and right child of the current node
            node.left = { val: val, left: node.left, right: null };
            node.right = { val: val, left: null, right: node.right };
        } else {
            // recursively traverse the left and right subtrees
            traverse(node.left, currentDepth + 1);
            traverse(node.right, currentDepth + 1);
        }
    }
    traverse(root, 1);
    return root;
}

function maxDistance(arrays) {
    let min = Infinity, max = -Infinity;
    // find the minimum and maximum values across all arrays
    for (let array of arrays) {
        min = Math.min(min, array[0]);
        max = Math.max(max, array[array.length - 1]);
    }
    // the maximum distance will be between the minimum and maximum values
    return Math.abs(max - min);
}

function maximumProduct(nums) {
  // sort the array to easily find the largest and smallest numbers
  nums.sort((a, b) => a - b);
  // calculate the product of the three largest numbers
  let maxProduct1 = nums[nums.length - 1] * nums[nums.length - 2] * nums[nums.length - 3];
  // calculate the product of the two smallest (most negative) numbers and the largest number
  let maxProduct2 = nums[0] * nums[1] * nums[nums.length - 1];
  // return the maximum of the two products
  return Math.max(maxProduct1, maxProduct2);
}

function kInversePairs(n, k) {
    const MOD = 1e9 + 7;
    const dp = Array(n + 1).fill(0).map(() => Array(k + 1).fill(0));
    for (let i = 0; i <= n; i++) {
        dp[i][0] = 1; // base case: no inverse pairs
    }
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= k; j++) {
            // calculate the number of arrays with exactly j inverse pairs by considering the last element
            let sum = 0;
            for (let p = 0; p <= i - 1 && p <= j; p++) {
                sum = (sum + dp[i - 1][j - p]) % MOD; // accumulate the number of arrays with j - p inverse pairs
            }
            dp[i][j] = sum;
        }
    }
    return dp[n][k];
}

function scheduleCourse(courses) {
    // Sort the courses by their last day
    courses.sort((a, b) => a[1] - b[1]);
    let pq = [], time = 0;
    for (let course of courses) {
        // Add the course to the priority queue and update the time
        time += course[0];
        pq.push(-course[0]);
        pq.sort((a, b) => a - b);
        // If the time exceeds the last day of the course, remove the longest course from the priority queue
        if (time > course[1]) {
            time += pq.shift();
        }
    }
    // Return the number of courses in the priority queue
    return pq.length;
}

function smallestRange(nums) {
    // Create a min-heap to store the current smallest element from each list along with its list index and element index
    let minHeap = [];
    for (let i = 0; i < nums.length; i++) {
        // Push the first element of each list into the min-heap
        minHeap.push([nums[i][0], i, 0]);
    }
    minHeap.sort((a, b) => a[0] - b[0]);

    // Initialize the smallest range and the maximum value in the current range
    let smallestRange = [-Infinity, Infinity];
    let maxVal = Math.max(...minHeap.map(x => x[0]));

    // Continue the process until the min-heap is empty
    while (minHeap.length === nums.length) {
        // Get the smallest element from the min-heap
        let [minVal, listIdx, elemIdx] = minHeap.shift();

        // Update the smallest range if the current range is smaller
        if (maxVal - minVal < smallestRange[1] - smallestRange[0]) {
            smallestRange = [minVal, maxVal];
        }

        // If there are more elements in the current list, push the next element into the min-heap
        if (elemIdx + 1 < nums[listIdx].length) {
            let nextVal = nums[listIdx][elemIdx + 1];
            minHeap.push([nextVal, listIdx, elemIdx + 1]);
            minHeap.sort((a, b) => a[0] - b[0]);
            // Update the maximum value in the current range
            maxVal = Math.max(maxVal, nextVal);
        } else {
            // If there are no more elements in the current list, break the loop
            break;
        }
    }

    return smallestRange;
}

function judgeSquareSum(c) {
  for (var a = 0; a * a <= c; a++) 
    // check if the remaining value is a perfect square
    if (isPerfectSquare(c - a * a)) return true;
  return false;
}

function isPerfectSquare(x) {
  var left = 0, right = Math.floor(Math.sqrt(x)) + 1;
  while (left < right) {
    // perform binary search to find the square root
    var mid = Math.floor((left + right) / 2);
    if (mid * mid === x) return true;
    if (mid * mid < x) left = mid + 1;
    else right = mid;
  }
  return false;
}

