function findExclusiveTimes(n, logs) {
    let stack = [];
    let exclusiveTimes = new Array(n).fill(0);
    let prevTime = 0;
    for (let log of logs) {
        let [functionId, eventType, timestamp] = log.split(":");
        functionId = parseInt(functionId);
        timestamp = parseInt(timestamp);
        // calculate the time difference between the current log and the previous log
        if (eventType === "start") {
            if (stack.length > 0) {
                exclusiveTimes[stack[stack.length - 1]] += timestamp - prevTime;
            }
            stack.push(functionId);
            prevTime = timestamp;
        } else {
            // if the event type is "end", calculate the time difference and add it to the exclusive time
            exclusiveTimes[stack.pop()] += timestamp - prevTime + 1;
            prevTime = timestamp + 1;
        }
    }
    return exclusiveTimes;
}

function averageOfLevels(root) {
    let result = [];
    let queue = [root];
    // perform BFS to traverse the tree level by level
    while (queue.length > 0) {
        let levelSize = queue.length;
        let sum = 0;
        // calculate the sum of all nodes at the current level
        for (let i = 0; i < levelSize; i++) {
            let node = queue.shift();
            sum += node.val;
            // add child nodes to the queue for the next level
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        // calculate the average of the current level
        result.push(sum / levelSize);
    }
    return result;
}

function shoppingOffers(price, special, needs) {
    let memo = {};
    function dfs(needs) {
        // Create a key for memoization
        let key = needs.join(',');
        if (key in memo) return memo[key];

        let res = 0;
        // Calculate the cost without using any special offers
        for (let i = 0; i < needs.length; i++) {
            // Update the result with the cost of the current item
            res += needs[i] * price[i];
        }

        // Iterate over each special offer
        for (let spec of special) {
            let clone = needs.slice();
            let valid = true;
            // Check if the special offer can be applied
            for (let i = 0; i < needs.length; i++) {
                // If the special offer requires more items than we have, it's not valid
                clone[i] -= spec[i];
                if (clone[i] < 0) {
                    valid = false;
                    break;
                }
            }
            // If the special offer is valid, calculate the cost with the special offer
            if (valid) {
                // Recursively call dfs with the updated needs
                res = Math.min(res, spec[spec.length - 1] + dfs(clone));
            }
        }

        // Store the result in the memo dictionary
        memo[key] = res;
        return res;
    }

    // Call the dfs function with the initial needs
    return dfs(needs);
}

function numDecodings(s) {
    const MOD = 10**9 + 7;
    const n = s.length;
    let dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    // calculate the number of ways to decode the string up to the current position
    for (let i = 1; i <= n; i++) {
        // if the current character is not '*', it can be decoded in one way
        if (s[i - 1] !== '*') {
            if (s[i - 1] !== '0') {
                // if the current character is not '0', it can be decoded
                dp[i] += dp[i - 1];
            }
            // if the current character and the previous character can be decoded together
            if (i >= 2 && (s[i - 2] === '1' || (s[i - 2] === '2' && s[i - 1] <= '6'))) {
                dp[i] += dp[i - 2];
            }
        } else {
            // if the current character is '*', it can be decoded in 9 ways
            dp[i] += dp[i - 1] * 9;
            // if the current character and the previous character can be decoded together
            if (i >= 2) {
                if (s[i - 2] === '1') {
                    dp[i] += dp[i - 2] * 9;
                } else if (s[i - 2] === '2') {
                    dp[i] += dp[i - 2] * 6;
                }
            }
        }
        // take the modulus to avoid overflow
        dp[i] %= MOD;
    }
    return dp[n];
}

function solveEquation(equation) {
    let leftX = 0, leftVal = 0, rightX = 0, rightVal = 0;
    let left = true;
    let num = 0, sign = 1;
    for (let i = 0; i < equation.length; i++) {
        // check if the current character is a digit
        if (!isNaN(equation[i])) {
            num = num * 10 + parseInt(equation[i]);
        } else if (equation[i] === 'x') {
            // if 'x' is found, update the coefficient of 'x'
            if (num === 0) num = 1;
            if (left) leftX += sign * num; else rightX += sign * num;
            num = 0;
        } else if (equation[i] === '+' || equation[i] === '-') {
            // update the sign for the next number
            if (num !== 0) {
                if (left) leftVal += sign * num; else rightVal += sign * num;
                num = 0;
            }
            sign = equation[i] === '+' ? 1 : -1;
        } else if (equation[i] === '=') {
            // switch to the right side of the equation
            left = false;
            sign = 1;
        }
    }
    // update the last number
    if (num !== 0) {
        if (left) leftVal += sign * num; else rightVal += sign * num;
    }
    // calculate the value of 'x'
    let newX = leftX - rightX;
    let newVal = rightVal - leftVal;
    if (newX === 0 && newVal === 0) return "Infinite solutions";
    if (newX === 0) return "No solution";
    return "x=" + newVal / newX;
}

function MyCircularDeque(k) {
    let capacity = k;
    let size = 0;
    let head = 0;
    let tail = 0;
    let data = new Array(k).fill(null);

    function addFront(value) {
        // if deque is full, return false
        if (size === capacity) return false;
        head = (head - 1 + capacity) % capacity;
        data[head] = value;
        size++;
        return true;
    }

    function addRear(value) {
        // if deque is full, return false
        if (size === capacity) return false;
        data[tail] = value;
        tail = (tail + 1) % capacity;
        size++;
        return true;
    }

    function deleteFront() {
        // if deque is empty, return false
        if (size === 0) return false;
        head = (head + 1) % capacity;
        size--;
        return true;
    }

    function deleteRear() {
        // if deque is empty, return false
        if (size === 0) return false;
        tail = (tail - 1 + capacity) % capacity;
        size--;
        return true;
    }

    function getFront() {
        // if deque is empty, return -1
        if (size === 0) return -1;
        return data[head];
    }

    function getRear() {
        // if deque is empty, return -1
        if (size === 0) return -1;
        return data[(tail - 1 + capacity) % capacity];
    }

    function isEmpty() {
        return size === 0;
    }

    function isFull() {
        return size === capacity;
    }

    return {
        addFront,
        addRear,
        deleteFront,
        deleteRear,
        getFront,
        getRear,
        isEmpty,
        isFull
    };
}

function findMaxAverage(nums, k) {
  let maxSum = -Infinity;
  let currentSum = 0;
  // calculate the sum of the first window
  for (let i = 0; i < k; i++) {
    currentSum += nums[i];
  }
  maxSum = currentSum;
  // slide the window and update the sum
  for (let i = k; i < nums.length; i++) {
    // subtract the leftmost element and add the new element
    currentSum = currentSum - nums[i - k] + nums[i];
    // update the max sum
    maxSum = Math.max(maxSum, currentSum);
  }
  // return the max average
  return maxSum / k;
}

function findErrorNums(nums) {
    let duplicate = -1, missing = -1;
    let count = new Array(nums.length + 1).fill(0);
    // Create a frequency count array to track occurrences of each number
    for (let i = 0; i < nums.length; i++) {
        count[nums[i]]++;
    }
    // Iterate through the count array to find the duplicate and missing numbers
    for (let i = 1; i <= nums.length; i++) {
        if (count[i] === 0) {
            missing = i;
        } else if (count[i] > 1) {
            duplicate = i;
        }
    }
    return [duplicate, missing];
}

function findLongestChain(pairs) {
  // sort the pairs based on the right value of each pair
  pairs.sort((a, b) => a[1] - b[1]);
  let count = 1;
  let prevRight = pairs[0][1];
  for (let i = 1; i < pairs.length; i++) {
    // if the current pair's left value is greater than the previous pair's right value, it can be added to the chain
    if (pairs[i][0] > prevRight) {
      count++;
      prevRight = pairs[i][1];
    }
  }
  return count;
}

function countSubstrings(s) {
  let count = 0;
  // iterate over the string to consider each character as a potential center of a palindrome
  for (let i = 0; i < s.length; i++) {
    // consider odd-length palindromes
    count += countPalindromes(s, i, i);
    // consider even-length palindromes
    count += countPalindromes(s, i, i + 1);
  }
  return count;
}

function countPalindromes(s, left, right) {
  let count = 0;
  // expand the palindrome as long as the characters match
  while (left >= 0 && right < s.length && s[left] === s[right]) {
    count++;
    left--;
    right++;
  }
  return count;
}

function replaceWords(dictionary, sentence) {
    // create a Trie and insert all roots into it
    var trie = {};
    for (var word of dictionary) {
        var node = trie;
        for (var ch of word) {
            if (!node[ch]) node[ch] = {};
            node = node[ch];
        }
        node['$'] = word; // mark the end of a word
    }

    // split the sentence into words
    var words = sentence.split(' ');
    for (var i = 0; i < words.length; i++) {
        // check if the word can be replaced by a root in the Trie
        var node = trie;
        var replaced = false;
        for (var j = 0; j < words[i].length; j++) {
            if (!node[words[i][j]]) break;
            node = node[words[i][j]];
            if (node['$']) { // if we've found a root, replace the word
                words[i] = node['$'];
                replaced = true;
                break;
            }
        }
    }

    // join the words back into a sentence
    return words.join(' ');
}

function predictPartyVictory(senate) {
    let radiantQueue = [], direQueue = [];
    for (let i = 0; i < senate.length; i++) {
        // Store the index of each senator in the corresponding queue
        if (senate[i] === 'R') radiantQueue.push(i);
        else direQueue.push(i);
    }
    while (radiantQueue.length > 0 && direQueue.length > 0) {
        // Compare the index of the first senator in each queue
        if (radiantQueue[0] < direQueue[0]) {
            // If the Radiant senator has a smaller index, they ban the next Dire senator
            radiantQueue.push(radiantQueue[0] + senate.length);
            radiantQueue.shift();
            direQueue.shift();
        } else {
            // If the Dire senator has a smaller index, they ban the next Radiant senator
            direQueue.push(direQueue[0] + senate.length);
            direQueue.shift();
            radiantQueue.shift();
        }
    }
    // Return the party of the remaining senators
    return radiantQueue.length > 0 ? "Radiant" : "Dire";
}

function minSteps(n) {
  let currentSteps = 0;
  let currentChars = 1;
  let buffer = 0;
  while (currentChars < n) {
    // if n is divisible by currentChars, we can copy and paste to reduce steps
    if (n % currentChars === 0) {
      buffer = currentChars;
      currentChars *= 2;
      currentSteps += 2;
    } else {
      // otherwise, just paste the buffer
      currentChars += buffer;
      currentSteps += 1;
    }
  }
  return currentSteps;
}

function findDuplicateSubtrees(root) {
    let result = [];
    let subtreeMap = new Map();
    function traverse(node) {
        // if the node is null, return a special string to avoid null pointer exception
        if (!node) return '#';
        // serialize the subtree rooted at the current node
        let subtree = node.val + ',' + traverse(node.left) + ',' + traverse(node.right);
        // increment the count of the subtree in the map
        subtreeMap.set(subtree, (subtreeMap.get(subtree) || 0) + 1);
        // if the count of the subtree is 2, it's a duplicate, so add it to the result
        if (subtreeMap.get(subtree) === 2) result.push(node);
        // return the serialized subtree
        return subtree;
    }
    // start the traversal from the root
    traverse(root);
    return result;
}

function findTarget(root, k) {
    let values = [];
    // traverse the tree and store all node values in an array
    function traverse(node) {
        if (node) {
            traverse(node.left);
            values.push(node.val);
            traverse(node.right);
        }
    }
    traverse(root);
    // sort the array to apply two-pointer technique
    values.sort((a, b) => a - b);
    let left = 0, right = values.length - 1;
    // use two pointers to find a pair of values that sum up to k
    while (left < right) {
        let sum = values[left] + values[right];
        if (sum === k) return true;
        else if (sum < k) left++;
        else right--;
    }
    return false;
}

function constructMaximumBinaryTree(nums) {
    // base case: if the array is empty, return null
    if (nums.length === 0) return null;

    // find the index of the maximum value in the array
    let maxIndex = 0;
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] > nums[maxIndex]) maxIndex = i;
    }

    // create a new node with the maximum value
    let node = { val: nums[maxIndex], left: null, right: null };

    // recursively construct the left and right subtrees
    node.left = constructMaximumBinaryTree(nums.slice(0, maxIndex));
    node.right = constructMaximumBinaryTree(nums.slice(maxIndex + 1));

    return node;
}

function printTree(root) {
    function getHeight(node) {
        // calculate the height of the tree to determine the matrix size
        if (!node) return 0;
        return 1 + Math.max(getHeight(node.left), getHeight(node.right));
    }

    function printNode(node, row, left, right) {
        // recursively print each node in the tree
        if (!node) return;
        const mid = left + Math.floor((right - left) / 2);
        res[row][mid] = node.val.toString();
        printNode(node.left, row + 1, left, mid);
        printNode(node.right, row + 1, mid + 1, right);
    }

    const height = getHeight(root);
    const width = 2 ** height - 1;
    const res = Array(height).fill().map(() => Array(width).fill(""));
    printNode(root, 0, 0, width);
    return res;
}

function judgeCircle(moves) {
  let x = 0, y = 0; 
  // iterate over each move and update the coordinates accordingly
  for (let move of moves) {
    // update the x or y coordinate based on the move
    if (move === 'R') x++; 
    else if (move === 'L') x--; 
    else if (move === 'U') y++; 
    else if (move === 'D') y--; 
  }
  // return true if the robot ends up at the origin, false otherwise
  return x === 0 && y === 0;
}

function findKClosestElements(arr, k, x) {
  // calculate the absolute difference between each element and x
  let diffArr = arr.map(num => ({ num, diff: Math.abs(num - x) }));
  // sort the array based on the difference and the value itself
  diffArr.sort((a, b) => a.diff - b.diff || a.num - b.num);
  // get the k closest elements and sort them in ascending order
  let result = diffArr.slice(0, k).map(obj => obj.num).sort((a, b) => a - b);
  return result;
}

function isPossible(nums) {
    const freq = new Map();
    const need = new Map();
    for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
    for (const n of nums) {
        if (!freq.get(n)) continue;
        freq.set(n, freq.get(n) - 1);
        if ((need.get(n - 1) || 0) > 0) {
            need.set(n - 1, need.get(n - 1) - 1);
            need.set(n, (need.get(n) || 0) + 1);
        } else if ((freq.get(n + 1) || 0) > 0 && (freq.get(n + 2) || 0) > 0) {
            freq.set(n + 1, freq.get(n + 1) - 1);
            freq.set(n + 2, freq.get(n + 2) - 1);
            need.set(n + 2, (need.get(n + 2) || 0) + 1);
        } else {
            return false;
        }
    }
    return true;
}

function imageSmoother(img) {
    const m = img.length;
    const n = img[0].length;
    const result = new Array(m).fill(0).map(() => new Array(n).fill(0));
    // Calculate the sum of neighboring cells for each cell
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            let sum = 0;
            let count = 0;
            // Check all neighboring cells
            for (let x = -1; x <= 1; x++) {
                for (let y = -1; y <= 1; y++) {
                    const ni = i + x;
                    const nj = j + y;
                    // Check if the neighboring cell is within the image boundaries
                    if (ni >= 0 && ni < m && nj >= 0 && nj < n) {
                        sum += img[ni][nj];
                        count++;
                    }
                }
            }
            // Calculate the average and round down
            result[i][j] = Math.floor(sum / count);
        }
    }
    return result;
}

function widthOfBinaryTree(root) {
    let maxWidth = 0;
    let queue = [[root, 0]];
    while (queue.length > 0) {
        let size = queue.length;
        let leftmost = queue[0][1];
        let rightmost = queue[size - 1][1];
        maxWidth = Math.max(maxWidth, rightmost - leftmost + 1);
        for (let i = 0; i < size; i++) {
            let [node, index] = queue.shift();
            if (node.left) queue.push([node.left, 2 * index]);
            if (node.right) queue.push([node.right, 2 * index + 1]);
        }
    }
    return maxWidth;
}

function strangePrinter(s) {
  const n = s.length;
  if (n === 0) return 0;
  const dp = Array.from({length: n}, () => new Array(n).fill(0));
  for (let i = n - 1; i >= 0; i--) {
    dp[i][i] = 1;
    for (let j = i + 1; j < n; j++) {
      if (s[i] === s[j]) {
        dp[i][j] = dp[i][j - 1];
      } else {
        let best = Infinity;
        for (let k = i; k < j; k++) best = Math.min(best, dp[i][k] + dp[k + 1][j]);
        dp[i][j] = best;
      }
    }
  }
  return dp[0][n - 1];
}

function checkPossibility(nums) {
  let count = 0;
  // Check each element to see if it's greater than the next one
  for (let i = 0; i < nums.length - 1; i++) {
    if (nums[i] > nums[i + 1]) {
      count++;
      // If we've already found one issue, check if changing this or the next element would fix it
      if (count > 1) return false;
      // Check if changing the current element to the next one would fix the issue
      if (i > 0 && nums[i - 1] > nums[i + 1] && i < nums.length - 2 && nums[i] > nums[i + 2]) return false;
    }
  }
  return true;
}

function constructArray(n, k) {
    const result = [];
    for (let i = 1; i <= n - k - 1; i++) result.push(i);
    let low = n - k, high = n;
    for (let i = 0; i <= k; i++) {
        if (i % 2 === 0) { result.push(low); low++; }
        else { result.push(high); high--; }
    }
    return result;
}

function maximumSwap(num) {
    let numStr = num.toString();
    let numArr = numStr.split('');
    let lastSeen = new Array(10).fill(0);
    for (let i = 0; i < numArr.length; i++) {
        // store the last seen index of each digit
        lastSeen[numArr[i]] = i;
    }
    for (let i = 0; i < numArr.length; i++) {
        // check if we can swap the current digit with a larger one that appears later
        for (let j = 9; j > numArr[i]; j--) {
            if (lastSeen[j] > i) {
                // swap the current digit with the larger one
                let temp = numArr[i];
                numArr[i] = numArr[lastSeen[j]];
                numArr[lastSeen[j]] = temp;
                return parseInt(numArr.join(''));
            }
        }
    }
    return num;
}

function subarraySum(nums, k) {
  let count = 0; 
  let prefixSumCount = {0: 1}; 
  let currentSum = 0; 
  for (let i = 0; i < nums.length; i++) {
    currentSum += nums[i]; 
    // calculate the difference between current sum and target sum k
    let diff = currentSum - k; 
    // if the difference exists in the prefix sum count, increment the count
    if (diff in prefixSumCount) count += prefixSumCount[diff]; 
    // update the prefix sum count
    if (!(currentSum in prefixSumCount)) prefixSumCount[currentSum] = 0; 
    prefixSumCount[currentSum]++; 
  }
  return count; 
}

function countBits(n) {
  var result = new Array(n + 1);
  result[0] = 0; 
  // initialize the first element to 0 since there are no bits set in the number 0
  for (var i = 1; i <= n; i++) 
    // for each number from 1 to n, calculate the number of bits set
    result[i] = result[i >> 1] + (i & 1); 
    // use bit manipulation to calculate the number of bits set in the current number
  return result;
}

function isSubsequence(s, t) {
  let sPointer = 0; 
  let tPointer = 0; 
  // iterate through t until we find all characters in s in the correct order
  while (sPointer < s.length && tPointer < t.length) {
    // if the current characters match, move to the next character in s
    if (s[sPointer] === t[tPointer]) sPointer++; 
    // move to the next character in t regardless of a match
    tPointer++; 
  }
  // if we've found all characters in s, s is a subsequence of t
  return sPointer === s.length; 
}

function arrayPairSum(nums) {
    // sort the array in ascending order to easily find the pairs with the maximum sum of min values
    nums.sort((a, b) => a - b);
    let sum = 0;
    // iterate over the sorted array with a step of 2 to consider each pair
    for (let i = 0; i < nums.length; i += 2) {
        // add the smaller value of each pair to the sum
        sum += nums[i];
    }
    return sum;
}

function findLengthOfLCIS(nums) {
  let maxLength = 0;
  let currentLength = 1;
  // iterate through the array and compare each element with its previous one to check for increasing subsequence
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) {
      // if the current element is greater than the previous one, increase the current length
      currentLength++;
    } else {
      // if the current element is not greater than the previous one, update the max length and reset the current length
      maxLength = Math.max(maxLength, currentLength);
      currentLength = 1;
    }
  }
  // update the max length one last time after the loop ends
  maxLength = Math.max(maxLength, currentLength);
  return maxLength;
}

function checkValidString(s) {
    let left = 0, right = 0;
    for (let i = 0; i < s.length; i++) // count open and wildcard characters
        if (s[i] === '(' || s[i] === '*') left++;
        else right++;
        if (left < right) return false; // if more close than open or wildcard, return false
    left = right = 0;
    for (let i = s.length - 1; i >= 0; i--) // count close and wildcard characters from the end
        if (s[i] === ')' || s[i] === '*') right++;
        else left++;
        if (left > right) return false; // if more open than close or wildcard, return false
    return true; // if pass both checks, return true
}

function maxProduct(words) {
    let maxProduct = 0;
    // Create a bitmask for each word to efficiently check for common letters
    let bitmasks = words.map(word => {
        let bitmask = 0;
        for (let char of word) {
            // Set the bit corresponding to the character in the bitmask
            bitmask |= 1 << (char.charCodeAt(0) - 'a'.charCodeAt(0));
        }
        return bitmask;
    });
    // Iterate over all pairs of words
    for (let i = 0; i < words.length; i++) {
        for (let j = i + 1; j < words.length; j++) {
            // Check if the two words do not share common letters by checking if their bitmasks have no bits in common
            if ((bitmasks[i] & bitmasks[j]) === 0) {
                // Update the maximum product if the product of the lengths of the two words is greater
                maxProduct = Math.max(maxProduct, words[i].length * words[j].length);
            }
        }
    }
    return maxProduct;
}

function MapSum() {
    this.map = {};
    this.trie = {};
}

MapSum.prototype.insert = function(key, val) {
    // update the value in the map
    this.map[key] = val;
    let node = this.trie;
    // iterate through each character in the key and update the trie
    for (let char of key) {
        if (!node[char]) node[char] = {};
        node = node[char];
    }
    node.end = true;
    node.key = key; // remember which key ends here so sum() can look up its current value
}

MapSum.prototype.sum = function(prefix) {
    let node = this.trie;
    // traverse the trie to the node corresponding to the prefix
    for (let char of prefix) {
        if (!node[char]) return 0;
        node = node[char];
    }
    // perform a depth-first search to sum up all words with the given prefix
    return dfs.call(this, node);
    function dfs(node) {
        let sum = 0;
        // if the node is the end of a word, add ITS OWN key's value to the sum (not the search prefix's)
        if (node.end) sum += this.map[node.key];
        // recursively traverse all child nodes
        for (let child in node) {
            if (child !== 'end' && child !== 'key') sum += dfs.call(this, node[child]);
        }
        return sum;
    }
}

function cutOffTree(forest) {
    let m = forest.length, n = forest[0].length;
    let trees = [];
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (forest[i][j] > 1) {
                trees.push([forest[i][j], i, j]);
            }
        }
    }
    trees.sort((a, b) => a[0] - b[0]);
    let start = [0, 0];
    let totalSteps = 0;
    for (let tree of trees) {
        let steps = bfs(forest, start, tree);
        if (steps === -1) return -1; // cannot reach the tree
        totalSteps += steps;
        start = [tree[1], tree[2]];
    }
    return totalSteps;
}

function bfs(forest, start, end) {
    let m = forest.length, n = forest[0].length;
    let queue = [[start[0], start[1], 0]];
    let visited = new Array(m).fill(0).map(() => new Array(n).fill(false));
    visited[start[0]][start[1]] = true;
    let directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    while (queue.length > 0) {
        let [x, y, steps] = queue.shift();
        if (x === end[1] && y === end[2]) return steps; // reached the tree
        for (let [dx, dy] of directions) {
            let nx = x + dx, ny = y + dy;
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && forest[nx][ny] !== 0 && !visited[nx][ny]) {
                queue.push([nx, ny, steps + 1]);
                visited[nx][ny] = true;
            }
        }
    }
    return -1; // cannot reach the tree
}

// TIME: O(m*n*log(m*n)) SPACE: O(m*n)

function findNumberOfLIS(nums) {
    let n = nums.length;
    let lengths = new Array(n).fill(1);
    let counts = new Array(n).fill(1);
    // Initialize variables to store the maximum length and count of longest increasing subsequences
    let maxLength = 1;
    let maxCount = 1;
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            // Check if current element can extend the increasing subsequence ending at j
            if (nums[i] > nums[j]) {
                // If the length of the new subsequence is greater than the current length, update the length and count
                if (lengths[j] + 1 > lengths[i]) {
                    lengths[i] = lengths[j] + 1;
                    counts[i] = counts[j];
                } 
                // If the length of the new subsequence is equal to the current length, update the count
                else if (lengths[j] + 1 === lengths[i]) {
                    counts[i] += counts[j];
                }
            }
        }
        // Update the maximum length and count
        if (lengths[i] > maxLength) {
            maxLength = lengths[i];
            maxCount = counts[i];
        } 
        // If the length of the current subsequence is equal to the maximum length, update the count
        else if (lengths[i] === maxLength) {
            maxCount += counts[i];
        }
    }
    return maxCount;
}

function magicDictionary(wordList) {
    let wordSet = new Set(wordList);
    return function(searchWord) {
        for (let i = 0; i < searchWord.length; i++) {
            // generate all possible words by changing one character at a time
            for (let j = 0; j < 26; j++) {
                let word = searchWord.slice(0, i) + String.fromCharCode(97 + j) + searchWord.slice(i + 1);
                // check if the generated word is in the word set and not the same as the search word
                if (wordSet.has(word) && word !== searchWord) return true;
            }
        }
        // if no match is found after checking all possible words, return false
        return false;
    }
}

function validUtf8(data) {
    let bytesLeft = 0;
    // iterate over each byte in the data
    for (let i = 0; i < data.length; i++) {
        // convert the byte to binary and remove the '0b' prefix
        let binary = data[i].toString(2).padStart(8, '0');
        // if we are not in the middle of a multi-byte character
        if (bytesLeft === 0) {
            // check if the byte is a 1-byte character
            if (binary[0] === '0') {
                continue;
            }
            // check if the byte is a 2-byte character
            else if (binary.substring(0, 3) === '110') {
                bytesLeft = 1;
            }
            // check if the byte is a 3-byte character
            else if (binary.substring(0, 4) === '1110') {
                bytesLeft = 2;
            }
            // check if the byte is a 4-byte character
            else if (binary.substring(0, 5) === '11110') {
                bytesLeft = 3;
            }
            // if the byte does not match any of the above, return false
            else {
                return false;
            }
        }
        // if we are in the middle of a multi-byte character
        else {
            // check if the byte is a continuation byte
            if (binary.substring(0, 2) !== '10') {
                return false;
            }
            // decrement the bytes left counter
            bytesLeft--;
        }
    }
    // if we have finished all bytes and there are no bytes left, return true
    return bytesLeft === 0;
}

function maxNumber(nums1, nums2, k) {
    let result = [];
    for (let i = Math.max(0, k - nums2.length); i <= Math.min(k, nums1.length); i++) {
        // generate the maximum subsequence of length i from nums1
        let subsequence1 = maxSubsequence(nums1, i);
        // generate the maximum subsequence of length k - i from nums2
        let subsequence2 = maxSubsequence(nums2, k - i);
        // merge the two subsequences to get the maximum number
        let merged = merge(subsequence1, subsequence2);
        // update the result if the merged number is larger
        if (greater(merged, result)) {
            result = merged;
        }
    }
    return result;
}

function maxSubsequence(nums, k) {
    let result = [];
    for (let i = 0; i < nums.length; i++) {
        // remove elements from the back of the result that are smaller than the current number
        while (result.length > 0 && result.length + nums.length - i > k && result[result.length - 1] < nums[i]) {
            result.pop();
        }
        // add the current number to the result
        result.push(nums[i]);
    }
    // return the first k elements of the result
    return result.slice(0, k);
}

function merge(nums1, nums2) {
    let result = [];
    while (nums1.length > 0 || nums2.length > 0) {
        // compare the remaining elements of nums1 and nums2 and add the larger one to the result
        if (greater(nums1, nums2)) {
            result.push(nums1.shift());
        } else {
            result.push(nums2.shift());
        }
    }
    return result;
}

function greater(nums1, nums2) {
    for (let i = 0; i < Math.min(nums1.length, nums2.length); i++) {
        // compare the elements of nums1 and nums2 from left to right
        if (nums1[i] > nums2[i]) {
            return true;
        } else if (nums1[i] < nums2[i]) {
            return false;
        }
    }
    // if all elements are equal, the longer number is larger
    return nums1.length > nums2.length;
}

