function shortestPathLength(graph) {
    const n = graph.length;
    const queue = [];
    const visited = Array(n).fill(0).map(() => Array(1 << n).fill(Infinity));
    for (let i = 0; i < n; i++) {
        queue.push([i, 1 << i, 0]);
        visited[i][1 << i] = 0;
    }
    const allVisited = (1 << n) - 1;
    while (queue.length > 0) {
        const [node, state, pathLength] = queue.shift();
        // if all nodes have been visited, return the path length
        if (state === allVisited) return pathLength;
        // for each neighbor of the current node
        for (const neighbor of graph[node]) {
            const newState = state | (1 << neighbor);
            // if visiting the neighbor results in a shorter path, update the visited state and add to queue
            if (visited[neighbor][newState] > pathLength + 1) {
                visited[neighbor][newState] = pathLength + 1;
                queue.push([neighbor, newState, pathLength + 1]);
            }
        }
    }
    return -1;
}

function isNStraightHand(hand, groupSize) {
    if (hand.length % groupSize !== 0) return false;
    let countMap = {};
    for (let num of hand) {
        // count the occurrence of each number
        countMap[num] = (countMap[num] || 0) + 1;
    }
    let keys = Object.keys(countMap).sort((a, b) => a - b);
    for (let key of keys) {
        // if the current number has a count greater than 0, try to form a group
        if (countMap[key] > 0) {
            let count = countMap[key];
            // try to form a group of consecutive numbers
            for (let i = 0; i < groupSize; i++) {
                let nextNum = parseInt(key) + i;
                // if any number in the group is missing, return false
                if (!countMap[nextNum] || countMap[nextNum] < count) return false;
                // decrease the count of each number in the group
                countMap[nextNum] -= count;
            }
        }
    }
    return true;
}

function scoreOfParentheses(s) {
    let stack = [], currentScore = 0;
    for (let i = 0; i < s.length; i++) {
        // if we encounter an opening parenthesis, push the current score into the stack and reset it
        if (s[i] === '(') {
            stack.push(currentScore);
            currentScore = 0;
        } 
        // if we encounter a closing parenthesis, pop the last score from the stack, add the maximum of 2 * current score and 1 to it, and update the current score
        else {
            currentScore = stack.pop() + Math.max(2 * currentScore, 1);
        }
    }
    return currentScore;
}

function possibleBipartition(n, dislikes) {
    let graph = Array.from({ length: n + 1 }, () => []);
    for (let [a, b] of dislikes) {
        graph[a].push(b);
        graph[b].push(a);
    }
    let colors = Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        if (colors[i] === 0) {
            let queue = [i];
            colors[i] = 1;
            while (queue.length) {
                let node = queue.shift();
                for (let neighbor of graph[node]) {
                    // if neighbor is not colored, color it with the opposite color and add to queue
                    if (colors[neighbor] === 0) {
                        colors[neighbor] = -colors[node];
                        queue.push(neighbor);
                    } 
                    // if neighbor is colored with the same color, return false
                    else if (colors[neighbor] === colors[node]) {
                        return false;
                    }
                }
            }
        }
    }
    return true;
}

function kSimilarity(s1, s2) {
    let queue = [s1];
    let visited = new Set([s1]);
    let step = 0;
    // generate all possible next strings by swapping two characters
    while (true) {
        let nextQueue = [];
        for (let s of queue) {
            if (s === s2) return step;
            // find the first character that is different from s2
            for (let i = 0; i < s.length; i++) {
                if (s[i] !== s2[i]) {
                    // try to swap this character with all other characters
                    for (let j = i + 1; j < s.length; j++) {
                        if (s[j] === s2[i]) {
                            let nextS = s.slice(0, i) + s[j] + s.slice(i + 1, j) + s[i] + s.slice(j + 1);
                            if (!visited.has(nextS)) {
                                nextQueue.push(nextS);
                                visited.add(nextS);
                            }
                        }
                    }
                    break;
                }
            }
        }
        // if we cannot find a next string, it means we need to try more swaps
        queue = nextQueue;
        step++;
    }
}

function shortestPathAllKeys(grid) {
  const m = grid.length;
  const n = grid[0].length;
  const allKeys = new Set();
  let start = null;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === '@') start = [i, j];
      if (grid[i][j] >= 'a' && grid[i][j] <= 'f') allKeys.add(grid[i][j]);
    }
  }
  const allKeysSize = allKeys.size;
  const queue = [[start, new Set()]];
  const visited = new Set();
  const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
  let steps = 0;
  // main logic: using BFS to explore all possible paths and keep track of the keys collected
  while (queue.length > 0) {
    const size = queue.length;
    for (let i = 0; i < size; i++) {
      const [position, keys] = queue.shift();
      const [x, y] = position;
      // check if we have collected all keys
      if (keys.size === allKeysSize) return steps;
      for (const [dx, dy] of directions) {
        const nx = x + dx;
        const ny = y + dy;
        if (nx >= 0 && nx < m && ny >= 0 && ny < n && grid[nx][ny] !== '#') {
          const newKeys = new Set(keys);
          if (grid[nx][ny] >= 'a' && grid[nx][ny] <= 'f') newKeys.add(grid[nx][ny]);
          if (grid[nx][ny] >= 'A' && grid[nx][ny] <= 'F' && !keys.has(grid[nx][ny].toLowerCase())) continue;
          const newState = `${nx},${ny},${Array.from(newKeys).sort().join('')}`;
          if (!visited.has(newState)) {
            queue.push([[nx, ny], newKeys]);
            visited.add(newState);
          }
        }
      }
    }
    steps++;
  }
  return -1;
}

function ExamRoom(n) {
    this.n = n;
    this.seats = [];
}

ExamRoom.prototype.seat = function() {
    // if the room is empty, the student sits at seat 0
    if (this.seats.length === 0) {
        this.seats.push(0);
        return 0;
    }
    // calculate the distance for the first seat
    let maxDistance = this.seats[0];
    let result = 0;
    // check the distance for each gap between students
    for (let i = 0; i < this.seats.length - 1; i++) {
        // calculate the distance to the closest person in the gap
        let distance = Math.floor((this.seats[i + 1] - this.seats[i]) / 2);
        // if the distance in the current gap is greater than the max distance, update the result
        if (distance > maxDistance) {
            maxDistance = distance;
            result = this.seats[i] + distance;
        }
    }
    // check the distance for the last seat
    let distance = this.n - 1 - this.seats[this.seats.length - 1];
    // if the distance to the last seat is greater than the max distance, update the result
    if (distance > maxDistance) {
        maxDistance = distance;
        result = this.n - 1;
    }
    // add the result to the seats array and return it
    this.seats.push(result);
    this.seats.sort((a, b) => a - b);
    return result;
}

