function mincostToHireWorkers(quality, wage, k) {
    let workers = [];
    for (let i = 0; i < quality.length; i++) {
        workers.push([quality[i], wage[i]]);
    }
    workers.sort((a, b) => (a[1] / a[0]) - (b[1] / b[0]));
    let minCost = Infinity, totalQuality = 0, maxHeap = [];
    for (let i = 0; i < workers.length; i++) {
        totalQuality += workers[i][0];
        maxHeap.push(-workers[i][0]);
        if (maxHeap.length > k) {
            // most-negative entry represents the largest original quality - evict that one
            const worst = Math.min(...maxHeap);
            totalQuality += worst;
            maxHeap.splice(maxHeap.indexOf(worst), 1);
        }
        if (maxHeap.length === k) {
            minCost = Math.min(minCost, totalQuality * (workers[i][1] / workers[i][0]));
        }
    }
    return minCost;
}

