RLEIterator.prototype.next = function(num) {
    while (this.index < this.encoding.length) {
        // if count is 0, we need to get the next count and value from encoding
        if (this.count === 0) {
            this.count = this.encoding[this.index];
            this.value = this.encoding[this.index + 1];
            this.index += 2;
        }
        // if num is less than or equal to the current count, return the current value
        if (num <= this.count) {
            this.count -= num;
            return this.value;
        }
        // if num is greater than the current count, subtract the current count from num and reset count
        else {
            num -= this.count;
            this.count = 0;
