function dieSimulator(n, rollMax) {
    const MOD = 1e9 + 7;
    const memo = new Map();
    function dp(roll, last, count) {
        // Create a key for memoization
        const key = `${roll},${last},${count}`;
        if (roll === n) return 1;
        if (memo.has(key)) return memo.get(key);
        let res = 0;
        // Try all possible outcomes for the next roll
        for (let i = 1; i <= 6; i++) {
            // Check if the current outcome can be rolled consecutively
            if (i === last && count === rollMax[i - 1]) continue;
            // Recursively call dp for the next roll
            res = (res + dp(roll + 1, i, i === last ? count + 1 : 1)) % MOD;
        }
        memo.set(key, res);
        return res;
    }
    return dp(0, 0, 0);
}

