function threeEqualParts(arr) {
    const n = arr.length;
    const ones = arr.reduce((a, b) => a + b, 0);
    if (ones === 0) return [0, n - 1];
    if (ones % 3 !== 0) return [-1, -1];
    const k = ones / 3;
    let i1 = -1, i2 = -1, i3 = -1, count = 0;
    for (let i = 0; i < n; i++) {
        if (arr[i] === 1) {
            count++;
            if (count === 1) i1 = i;
            else if (count === k + 1) i2 = i;
            else if (count === 2 * k + 1) i3 = i;
        }
    }
    const len = n - i3;
    if (i1 + len > i2 || i2 + len > i3) return [-1, -1];
    for (let i = 0; i < len; i++) {
        if (arr[i1 + i] !== arr[i2 + i] || arr[i2 + i] !== arr[i3 + i]) return [-1, -1];
    }
    return [i1 + len - 1, i2 + len];
}

function maxEqualFreq(nums) {
  let countMap = {};
  let freqMap = {};
  let maxLen = 0;

  for (let i = 0; i < nums.length; i++) {
    let num = nums[i];
    let oldFreq = countMap[num] || 0;
    if (oldFreq > 0) {
      freqMap[oldFreq]--;
      if (freqMap[oldFreq] === 0) delete freqMap[oldFreq];
    }
    countMap[num] = oldFreq + 1;
    let freq = countMap[num];
    freqMap[freq] = (freqMap[freq] || 0) + 1;
    if (canMakeEqualFreq(freqMap)) {
      maxLen = i + 1;
    }
  }
  return maxLen;
}

function canMakeEqualFreq(freqMap) {
  let freqs = Object.keys(freqMap).map(Number);
  if (freqs.length === 1) {
    const f = freqs[0];
    return f === 1 || freqMap[f] === 1;
  }
  if (freqs.length === 2) {
    freqs.sort((a, b) => a - b);
    let [f1, f2] = freqs;
    if (f1 === 1 && freqMap[f1] === 1) return true;
    if (f2 === f1 + 1 && freqMap[f2] === 1) return true;
  }
  return false;
}

