            factors.push(i); // add i to the factors list
        }
    }
    // check if n has at least k factors
    if (k > factors.length) {
        return -1; // return -1 if n has less than k factors
    }
    // return the kth factor
    return factors[k - 1];
}

function longestSubarray(nums) {
    let maxLength = 0;
    let left = 0;
    let zeros = 0;
    // iterate through the array and maintain a sliding window with at most one zero
    for (let right = 0; right < nums.length; right++) {
        // if the current element is zero, increment the zeros count
        if (nums[right] === 0) {
            zeros++;
        }
        // while there are more than one zeros in the window, shrink the window from the left
        while (zeros > 1) {
            if (nums[left] === 0) {
                zeros--;
            }
            left++;
        }
        // update the maximum length if the current window has more ones
        if (right - left + 1 > maxLength && zeros === 1) {
            maxLength = right - left + 1 - 1; // subtract one because we can delete one element
        } else if (right - left + 1 > maxLength && zeros === 0) {
            maxLength = right - left + 1 - 1; // subtract one because we can delete one element
        }
    }
    // return the maximum length found
    return maxLength;
}

function minimumInteger(num, k) {
    let digits = num.split(''); // convert string to array for easier manipulation
    for (let i = 0; i < digits.length; i++) { 
        // find the smallest digit in the next k positions and swap it with the current digit
        let minIndex = i;
        for (let j = i + 1; j <= i + k && j < digits.length; j++) {
            if (digits[j] < digits[minIndex]) {
                minIndex = j;
            }
        }
        // swap the current digit with the smallest digit found
        for (let j = minIndex; j > i; j--) {
            [digits[j], digits[j - 1]] = [digits[j - 1], digits[j]];
            k--; // decrement k after each swap
            if (k === 0) break; // stop swapping if k becomes 0
        }
        if (k === 0) break; // stop the outer loop if k becomes 0
    }
    return digits.join(''); // convert array back to string
}

function popcount(x) { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; }
function minNumberOfSemesters(n, relations, k) {
    const prereq = new Array(n + 1).fill(0);
    for (const [a, b] of relations) prereq[b] |= (1 << (a - 1));
    const full = (1 << n) - 1;
    const dp = new Array(1 << n).fill(Infinity);
    dp[0] = 0;
    for (let mask = 0; mask <= full; mask++) {
        if (dp[mask] === Infinity) continue;
        let avail = 0;
        for (let c = 1; c <= n; c++) {
            if (!(mask & (1 << (c - 1))) && (mask & prereq[c]) === prereq[c]) {
                avail |= (1 << (c - 1));
            }
        }
        let sub = avail;
        while (sub > 0) {
            if (popcount(sub) <= k) {
                dp[mask | sub] = Math.min(dp[mask | sub], dp[mask] + 1);
            }
            sub = (sub - 1) & avail;
        }
    }
    return dp[full];
}

function numSubmat(mat) {
    const m = mat.length, n = mat[0].length;
