}
function helper(A) {
    const n = A.length;
    const sum = new Array(n).fill(0);
    const stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && A[stack[stack.length - 1]] >= A[i]) stack.pop();
        if (stack.length) {
            const preIndex = stack[stack.length - 1];
            sum[i] = sum[preIndex] + A[i] * (i - preIndex);
        } else {
            sum[i] = A[i] * (i + 1);
        }
        stack.push(i);
    }
    return sum.reduce((a, b) => a + b, 0);
}

