function maxProbability(n, edges, succProb, start, end) {
    // Create an adjacency list representation of the graph
    const graph = Array.from({ length: n }, () => []);
    for (let i = 0; i < edges.length; i++) {
        const [a, b] = edges[i];
        graph[a].push([b, succProb[i]]);
        graph[b].push([a, succProb[i]]);
    }

    // Initialize the probability of reaching each node to 0, except for the start node which is 1
    const prob = Array(n).fill(0);
    prob[start] = 1;

    // Use Dijkstra's algorithm with a priority queue to find the node with the maximum probability
    const pq = [[start, 1]];
    while (pq.length) {
        // Extract the node with the maximum probability from the priority queue
        const [node, currProb] = pq.shift();
        // If the current node is the end node, return its probability
        if (node === end) return currProb;
        // If the current probability is less than the already known probability, skip this node
        if (currProb < prob[node]) continue;
        // Update the probabilities of the neighbors
        for (const [neighbor, edgeProb] of graph[node]) {
            // Calculate the new probability of reaching the neighbor through the current node
            const newProb = currProb * edgeProb;
            // If the new probability is greater than the already known probability, update it and push the neighbor to the priority queue
            if (newProb > prob[neighbor]) {
                prob[neighbor] = newProb;
                pq.push([neighbor, newProb]);
                // Sort the priority queue in descending order of probabilities
                pq.sort((a, b) => b[1] - a[1]);
            }
        }
    }
    // If there is no path from the start node to the end node, return 0
    return 0;
}

function check(nums) {
