      count++;
    }
  }
  // check if the last element is greater than the first element
  if (nums[nums.length - 1] > nums[0]) {
    count++;
  }
  // if the number of rotations is more than 1, return false
  if (count > 1) {
    return false;
  }
  // check if the array is sorted in ascending order after rotation
  for (let i = 0; i < nums.length - 1; i++) {
