    }

    let left = 1;
    let right = Math.max(...nums);
    while (left < right) {
        // find the middle value and check if it's possible to achieve this maxBalls
        let mid = Math.floor((left + right) / 2);
        if (canDivide(mid)) {
            // if possible, try to decrease maxBalls
            right = mid;
        } else {
