            left = mid + 1;
        }
    }
    return left;
}

function maximumScore(a, b, c) {
    let score = 0;
    // keep removing stones from the two largest piles until one of them becomes empty
    while (a > 0 && b > 0 || a > 0 && c > 0 || b > 0 && c > 0) {
        // sort the piles in descending order to easily find the two largest piles
        let max = Math.max(a, b, c);
        let min = Math.min(a, b, c);
        let mid = a + b + c - max - min;
        // remove one stone from each of the two largest piles
        if (max === a) {
            if (mid === b) {
                a--;
                b--;
            } else {
                a--;
                c--;
            }
        } else if (max === b) {
            if (mid === a) {
