}

function maximumScore(nums, multipliers) {
  const n = nums.length, m = multipliers.length;
  const dp = Array.from({length: m+1}, () => new Array(m+1).fill(0));
  for (let i = m-1; i>=0; i--){
    for (let left=0; left<=i; left++){
      const right = n-1-(i-left);
      const pickLeft = multipliers[i]*nums[left] + dp[i+1][left+1];
      const pickRight = multipliers[i]*nums[right] + dp[i+1][left];
      dp[i][left] = Math.max(pickLeft, pickRight);
    }
  }
  return dp[0][0];
}

function mergeStrings(word1, word2) {
