function countPairs(n, edges, queries) {
    // Create an adjacency list to represent the graph
    let graph = new Array(n + 1).fill(0).map(() => new Array());
    for (let edge of edges) {
        // Add edges to the adjacency list
        graph[edge[0]].push(edge[1]);
        graph[edge[1]].push(edge[0]);
    }

    // Initialize an array to store the degree of each node
    let degrees = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        // Calculate the degree of each node
        degrees[i] = graph[i].length;
    }

    // Initialize an array to store the answers to the queries
    let answers = new Array(queries.length).fill(0);
    for (let i = 0; i < queries.length; i++) {
        let query = queries[i];
        let count = 0;
        // Iterate over all pairs of nodes
        for (let a = 1; a <= n; a++) {
            for (let b = a + 1; b <= n; b++) {
                // Calculate the incident(a, b) value
                let incident = degrees[a] + degrees[b];
                // Check if there is an edge between a and b
                if (graph[a].includes(b)) {
                    // Subtract 1 from the incident(a, b) value because the edge between a and b is counted twice
                    incident -= 1;
                }
                // Check if the incident(a, b) value is greater than the query
                if (incident > query) {
                    // Increment the count of pairs that satisfy the condition
                    count++;
                }
            }
        }
        // Store the answer to the query
        answers[i] = count;
    }
    return answers;
}

function AuthenticationManager(timeToLive) {
