    this.tokens[tokenId] = currentTime + this.timeToLive; // update token's expiration time
}

AuthenticationManager.prototype.countUnexpiredTokens = function(currentTime) {
    let count = 0; 
    for (let tokenId in this.tokens) {
        if (this.tokens[tokenId] > currentTime) count++; // count unexpired tokens
    }
    return count;
}

