function minTrioDegree(n, edges) {
    // Create an adjacency list to represent the graph
    let graph = Array.from({length: n + 1}, () => []);
    for (let [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    let minDegree = Infinity;
    // Iterate over all possible trios
    for (let i = 1; i <= n; i++) {
        for (let j = i + 1; j <= n; j++) {
            for (let k = j + 1; k <= n; k++) {
                // Check if the trio is connected
                if (graph[i].includes(j) && graph[j].includes(k) && graph[k].includes(i)) {
                    // Calculate the degree of the trio
                    let degree = 0;
                    // Count edges from each node in the trio to nodes outside the trio
                    for (let node of [i, j, k]) {
                        for (let neighbor of graph[node]) {
                            if (![i, j, k].includes(neighbor)) {
                                degree++;
                            }
                        }
                    }
                    // Update the minimum degree
                    minDegree = Math.min(minDegree, degree);
                }
            }
        }
    }
    // Return the minimum degree or -1 if no connected trios are found
    return minDegree === Infinity ? -1 : minDegree;
}

function repeatedStringMatch(a, b) {
    let count = Math.ceil(b.length / a.length);
    let repeated = a.repeat(count);
    if (repeated.includes(b)) return count;
    repeated += a;
    count++;
    if (repeated.includes(b)) return count;
    return -1;
}

function findRedundantConnection(edges) {
    let parent = Array(edges.length + 1).fill(0).map((val, index) => index);
    // iterate over each edge to check if it forms a cycle
    for (let edge of edges) {
        // if the two nodes are already connected, return this edge
        if (!union(parent, edge[0], edge[1])) {
            return edge;
        }
    }
}

function find(parent, i) {
    // if the parent of i is not i, then i is not the root
    if (parent[i] !== i) {
        // path compression: set the parent of i to the root of i
        parent[i] = find(parent, parent[i]);
    }
    return parent[i];
}

function union(parent, i, j) {
    // find the roots of i and j
    let rootI = find(parent, i);
    let rootJ = find(parent, j);
    // if the roots are the same, then i and j are already connected
    if (rootI === rootJ) {
        return false;
    }
    // union the two sets by setting the parent of one root to the other
    parent[rootI] = rootJ;
    return true;
}

