function findRedundantDirectedConnection(edges) {
    let n = edges.length;
    let parent = new Array(n + 1).fill(0);
    let first = null, second = null;
    // find the node that has two parents
    for (let i = 0; i < n; i++) {
        let [u, v] = edges[i];
        if (parent[v] !== 0) {
            first = [parent[v], v];
            second = [u, v];
            edges[i] = null;
            break;
        }
        parent[v] = u;
    }
    // if no node has two parents, then the last edge is the redundant one
    if (first === null) {
        let uf = new UnionFind(n + 1);
        for (let i = 0; i < n; i++) {
            if (edges[i] !== null) {
                let [u, v] = edges[i];
                if (!uf.union(u, v)) {
                    return edges[i];
                }
            }
        }
    } else {
        // if a node has two parents, then we need to check if removing the first or the second edge will make the graph a tree
        let uf = new UnionFind(n + 1);
        for (let i = 0; i < n; i++) {
            if (edges[i] !== null && edges[i] !== second) {
                let [u, v] = edges[i];
                if (!uf.union(u, v)) {
                    return first;
                }
            }
        }
        return second;
    }
}

function UnionFind(n) {
    this.parent = new Array(n).fill(0).map((_, i) => i);
    this.rank = new Array(n).fill(0);
}

UnionFind.prototype.find = function(x) {
    if (this.parent[x] !== x) {
        this.parent[x] = this.find(this.parent[x]);
    }
    return this.parent[x];
}

UnionFind.prototype.union = function(x, y) {
    let rootX = this.find(x);
    let rootY = this.find(y);
    if (rootX === rootY) {
        return false;
    }
    if (this.rank[rootX] < this.rank[rootY]) {
        this.parent[rootX] = rootY;
    } else if (this.rank[rootX] > this.rank[rootY]) {
        this.parent[rootY] = rootX;
    } else {
        this.parent[rootY] = rootX;
        this.rank[rootX]++;
    }
    return true;
}

function longestUnivaluePath(root) {
    let maxLength = 0;
    function dfs(node) {
        if (!node) return 0;
        let leftLen = dfs(node.left);
        let rightLen = dfs(node.right);
        let leftPath = (node.left && node.left.val === node.val) ? leftLen + 1 : 0;
        let rightPath = (node.right && node.right.val === node.val) ? rightLen + 1 : 0;
        maxLength = Math.max(maxLength, leftPath + rightPath);
        return Math.max(leftPath, rightPath);
    }
    dfs(root);
    return maxLength;
}

function knightProbability(n, k, row, column) {
  const directions = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]];
  const memo = new Map();

  function dfs(r, c, k) {
    // if we've made k moves, return 1 (we're still on the board) or 0 (we're off the board)
    if (k === 0) return r >= 0 && r < n && c >= 0 && c < n ? 1 : 0;

    // if we've already computed this subproblem, return the result
    const key = `${r},${c},${k}`;
    if (memo.has(key)) return memo.get(key);

    // recursively try all possible moves and sum the probabilities
    let prob = 0;
    for (const [dr, dc] of directions) {
      const nr = r + dr, nc = c + dc;
      // if the new position is on the board, recursively call dfs with k-1 moves
      if (nr >= 0 && nr < n && nc >= 0 && nc < n) prob += dfs(nr, nc, k-1);
    }

    // divide the sum of probabilities by 8 (since there are 8 possible moves)
    prob /= 8;
    memo.set(key, prob);
    return prob;
  }

  return dfs(row, column, k);
}

function maxSumOfThreeSubarrays(nums, k) {
    const n = nums.length;
    const sum = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        sum[i + 1] = sum[i] + nums[i];
    }
    const sums = new Array(n - k + 1).fill(0);
    for (let i = 0; i <= n - k; i++) {
        // calculate sum of subarray from i to i+k-1
        sums[i] = sum[i + k] - sum[i];
    }
    let maxSum = -Infinity;
    let result = [];
    for (let i = 0; i <= n - k; i++) {
        for (let j = i + k; j <= n - k; j++) {
            for (let m = j + k; m <= n - k; m++) {
                // calculate total sum of three subarrays
                const totalSum = sums[i] + sums[j] + sums[m];
                if (totalSum > maxSum) {
                    maxSum = totalSum;
                    result = [i, j, m];
                } else if (totalSum === maxSum) {
                    // compare lexicographically
                    if (i < result[0] || (i === result[0] && j < result[1]) || (i === result[0] && j === result[1] && m < result[2])) {
                        result = [i, j, m];
                    }
                }
            }
        }
    }
    return result;
}

function getImportance(employees, id) {
    // create a hash table to store employee information for efficient lookup
    let employeeMap = new Map();
    for (let employee of employees) {
        employeeMap.set(employee[0], employee);
    }

    function dfs(currentId) {
        // get the current employee's information from the hash table
        let currentEmployee = employeeMap.get(currentId);
        // calculate the total importance value by adding the current employee's importance value and the total importance value of their subordinates
        let totalImportance = currentEmployee[1];
        for (let subordinateId of currentEmployee[2]) {
            // recursively calculate the total importance value of each subordinate
            totalImportance += dfs(subordinateId);
        }
        return totalImportance;
    }

    // start the depth-first search from the given employee ID
    return dfs(id);
}

function topKFrequent(words, k) {
    // Create a hash map to store the frequency of each word
    let frequencyMap = {};
    for (let word of words) {
        // Increment the frequency of the current word
        frequencyMap[word] = (frequencyMap[word] || 0) + 1;
    }

    // Create an array of words and their frequencies
    let wordFrequencies = [];
    for (let word in frequencyMap) {
        // Store the word and its frequency as an array
        wordFrequencies.push([word, frequencyMap[word]]);
    }

    // Sort the words based on their frequency and lexicographical order
    wordFrequencies.sort((a, b) => {
        // If the frequencies are different, sort by frequency in descending order
        if (a[1] !== b[1]) {
            return b[1] - a[1];
        } else {
            // If the frequencies are the same, sort by lexicographical order
            return a[0].localeCompare(b[0]);
        }
    });

    // Return the top k words
    let result = [];
    for (let i = 0; i < k; i++) {
        // Add the word to the result array
        result.push(wordFrequencies[i][0]);
    }
    return result;
}

