function minStickers(stickers, target) {
    let dp = new Map();
    dp.set(0, 0);
    for (let i = 1; i <= (1 << target.length); i++) {
        dp.set(i, Infinity);
    }
    // iterate over all possible subsets of the target string
    for (let mask = 0; mask < (1 << target.length); mask++) {
        // if the current subset is not in the dp map, skip it
        if (dp.get(mask) === Infinity) continue;
        // iterate over all stickers
        for (let sticker of stickers) {
            let newMask = mask;
            // iterate over all characters in the sticker
            for (let char of sticker) {
                // find the first occurrence of the character in the target string
                for (let i = 0; i < target.length; i++) {
                    // if the character is found and it is not already in the subset
                    if (target[i] === char && ((newMask >> i) & 1) === 0) {
                        // add the character to the subset
                        newMask |= (1 << i);
                        break;
                    }
                }
            }
            // if the new subset is not in the dp map or the current subset is smaller
            if (!dp.has(newMask) || dp.get(newMask) > dp.get(mask) + 1) {
                // update the dp map with the new subset
                dp.set(newMask, dp.get(mask) + 1);
            }
        }
    }
    // if the full target string is not in the dp map, return -1
    if (dp.get((1 << target.length) - 1) === Infinity) return -1;
    // return the minimum number of stickers needed to spell out the target string
    return dp.get((1 << target.length) - 1);
}

function hasAlternatingBits(n) {
    let previousBit = n & 1; // get the least significant bit
    n >>= 1; // shift the bits to the right
    while (n > 0) {
        let currentBit = n & 1; // get the least significant bit
        if (currentBit === previousBit) // if two adjacent bits are the same
            return false; 
        previousBit = currentBit; // update the previous bit
        n >>= 1; // shift the bits to the right
    }
    return true; // if all bits are alternating
}

function maxAreaOfIsland(grid) {
    let maxArea = 0;
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            // if we find a land cell, calculate the area of the island it belongs to
            if (grid[i][j] === 1) {
                let area = 0;
                // use a helper function to calculate the area using DFS
                function dfs(row, col) {
                    // if the cell is out of bounds or is water, return
                    if (row < 0 || row >= grid.length || col < 0 || col >= grid[0].length || grid[row][col] === 0) {
                        return;
                    }
                    // mark the cell as visited by setting it to 0
                    grid[row][col] = 0;
                    // increment the area
                    area++;
                    // recursively visit all neighboring cells
                    dfs(row - 1, col); // up
                    dfs(row + 1, col); // down
                    dfs(row, col - 1); // left
                    dfs(row, col + 1); // right
                }
                dfs(i, j);
                // update the max area
                maxArea = Math.max(maxArea, area);
            }
        }
    }
    return maxArea;
}

function countBinarySubstrings(s) {
    let count = 0;
    let prev = 0;
    let curr = 1;
    // Iterate over the string and count consecutive occurrences of the same character
    for (let i = 1; i < s.length; i++) {
        // If the current character is different from the previous one, update the counts
        if (s[i] !== s[i - 1]) {
            count += Math.min(prev, curr);
            prev = curr;
            curr = 1;
        } else {
            // If the current character is the same as the previous one, increment the current count
            curr++;
        }
    }
    // Update the count one last time after the loop ends
    count += Math.min(prev, curr);
    return count;
}

function findShortestSubArray(nums) {
    let count = {}, first = {}, last = {};
    for (let i = 0; i < nums.length; i++) {
        // count the frequency of each number
        count[nums[i]] = (count[nums[i]] || 0) + 1;
        // store the first occurrence of each number
        if (!(nums[i] in first)) first[nums[i]] = i;
        // update the last occurrence of each number
        last[nums[i]] = i;
    }
    let degree = Math.max(...Object.values(count));
    let minLen = Infinity;
    for (let num in count) {
        // check if the number has the maximum frequency
        if (count[num] === degree) {
            // calculate the length of the subarray for this number
            minLen = Math.min(minLen, last[num] - first[num] + 1);
        }
    }
    return minLen;
}

function canPartitionKSubsets(nums, k) {
    let totalSum = 0;
    for (let num of nums) {
        totalSum += num;
    }
    if (totalSum % k !== 0) return false;
    let targetSum = totalSum / k;
    let visited = new Array(nums.length).fill(false);
    function backtrack(index, count, currentSum) {
        // if we have formed k subsets with equal sums, return true
        if (count === k) return true;
        // if the current sum exceeds the target sum, return false
        if (currentSum > targetSum) return false;
        // if we have formed a subset with the target sum, recursively call backtrack
        if (currentSum === targetSum) return backtrack(0, count + 1, 0);
        for (let i = index; i < nums.length; i++) {
            // skip the current number if it is already visited
            if (visited[i]) continue;
            visited[i] = true;
            // recursively call backtrack with the updated current sum and index
            if (backtrack(i + 1, count, currentSum + nums[i])) return true;
            visited[i] = false;
        }
        return false;
    }
    return backtrack(0, 0, 0);
}

function fallingSquares(positions) {
    let heights = new Array(positions.length).fill(0);
    let maxHeight = 0;
    let ans = [];
    for (let i = 0; i < positions.length; i++) {
        let left = positions[i][0];
        let sideLength = positions[i][1];
        let right = left + sideLength;
        let currHeight = 0;
        for (let j = 0; j < i; j++) {
            // check if the current square overlaps with the previous square
            if (positions[j][0] < right && left < positions[j][0] + positions[j][1]) {
                // update the current height if it overlaps
                currHeight = Math.max(currHeight, heights[j]);
            }
        }
        // update the height of the current square
        heights[i] = currHeight + sideLength;
        // update the maximum height
        maxHeight = Math.max(maxHeight, heights[i]);
        // add the maximum height to the answer array
        ans.push(maxHeight);
    }
    return ans;
}

function searchBST(root, val) {
    // if the tree is empty, return null
    if (!root) return null;
    // if the current node's value matches the target value, return the current node
    if (root.val === val) return root;
    // if the target value is less than the current node's value, search in the left subtree
    if (val < root.val) return searchBST(root.left, val);
    // if the target value is greater than the current node's value, search in the right subtree
    return searchBST(root.right, val);
}

function insertIntoBST(root, val) {
    if (!root) return new TreeNode(val); // base case: if tree is empty, create a new node
    if (val < root.val) root.left = insertIntoBST(root.left, val); // if val is less than current node, insert into left subtree
    else if (val > root.val) root.right = insertIntoBST(root.right, val); // if val is greater than current node, insert into right subtree
    return root; // return the modified tree
}

function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

function KthLargest(k, nums) {
    this.k = k;
    this.nums = nums;
    this.heap = [];
    for (let num of nums) {
        this.add(num);
    }
}

KthLargest.prototype.add = function(val) {
    // add the new score to the heap
    this.heap.push(val);
    this.heap.sort((a, b) => b - a);
    // maintain the heap size to be k
    if (this.heap.length > this.k) {
        this.heap.pop();
    }
    // return the kth largest element
    return this.heap[this.heap.length - 1];
}

function search(nums, target) {
  let left = 0;
  let right = nums.length - 1;
  // continue searching while the search space is not empty
  while (left <= right) {
    // calculate the middle index of the current search space
    let mid = Math.floor((left + right) / 2);
    // if the target is found at the middle index, return it
    if (nums[mid] === target) return mid;
    // if the target is less than the middle element, search in the left half
    else if (nums[mid] > target) right = mid - 1;
    // if the target is greater than the middle element, search in the right half
    else left = mid + 1;
  }
  // if the target is not found after searching the entire array, return -1
  return -1;
}

function MyHashSet() {
    let size = 1000;
    let buckets = new Array(size);
    // Create an empty bucket for each index in the array
    for (let i = 0; i < size; i++) {
        buckets[i] = [];
    }

    function _hash(key) {
        // Calculate the index using the hash function
        return key % size;
    }

    function add(key) {
        // Calculate the index and add the key to the corresponding bucket if it doesn't exist
        let index = _hash(key);
        if (!buckets[index].includes(key)) {
            buckets[index].push(key);
        }
    }

    function remove(key) {
        // Calculate the index and remove the key from the corresponding bucket if it exists
        let index = _hash(key);
        let pos = buckets[index].indexOf(key);
        if (pos !== -1) {
            buckets[index].splice(pos, 1);
        }
    }

    function contains(key) {
        // Calculate the index and check if the key exists in the corresponding bucket
        let index = _hash(key);
        return buckets[index].includes(key);
    }

    return { add, remove, contains };
}

function MyHashMap() {
    // Initialize an empty array to store key-value pairs
    this.map = new Array(1000).fill(null).map(() => []);
}

MyHashMap.prototype.put = function(key, value) {
    // Calculate the index using the modulo operator to handle collisions
    let index = key % 1000;
    // Find the key in the bucket and update its value if it exists
    for (let i = 0; i < this.map[index].length; i++) {
        if (this.map[index][i][0] === key) {
            // Update the value if the key already exists
            this.map[index][i][1] = value;
            return;
        }
    }
    // If the key does not exist, add a new key-value pair to the bucket
    this.map[index].push([key, value]);
}

MyHashMap.prototype.get = function(key) {
    // Calculate the index using the modulo operator to handle collisions
    let index = key % 1000;
    // Find the key in the bucket and return its value if it exists
    for (let i = 0; i < this.map[index].length; i++) {
        if (this.map[index][i][0] === key) {
            // Return the value if the key exists
            return this.map[index][i][1];
        }
    }
    // Return -1 if the key does not exist
    return -1;
}

MyHashMap.prototype.remove = function(key) {
    // Calculate the index using the modulo operator to handle collisions
    let index = key % 1000;
    // Find the key in the bucket and remove it if it exists
    for (let i = 0; i < this.map[index].length; i++) {
        if (this.map[index][i][0] === key) {
            // Remove the key-value pair from the bucket
            this.map[index].splice(i, 1);
            return;
        }
    }
}

function MyLinkedList() {
    // Initialize the head and tail of the linked list
    this.head = null;
    this.tail = null;
    this.size = 0;
}

MyLinkedList.prototype.get = function(index) {
    // Check if the index is within the bounds of the linked list
    if (index < 0 || index >= this.size) return -1;
    let current = this.head;
    // Traverse the linked list to find the node at the given index
    for (let i = 0; i < index; i++) current = current.next;
    return current.val;
}

MyLinkedList.prototype.addAtHead = function(val) {
    // Create a new node with the given value
    let newNode = { val: val, next: null };
    // If the linked list is empty, set the new node as the head and tail
    if (!this.head) this.head = this.tail = newNode;
    else {
        // Otherwise, set the new node's next pointer to the current head
        newNode.next = this.head;
        // Update the head of the linked list
        this.head = newNode;
    }
    // Increment the size of the linked list
    this.size++;
}

MyLinkedList.prototype.addAtTail = function(val) {
    // Create a new node with the given value
    let newNode = { val: val, next: null };
    // If the linked list is empty, set the new node as the head and tail
    if (!this.tail) this.head = this.tail = newNode;
    else {
        // Otherwise, set the current tail's next pointer to the new node
        this.tail.next = newNode;
        // Update the tail of the linked list
        this.tail = newNode;
    }
    // Increment the size of the linked list
    this.size++;
}

MyLinkedList.prototype.addAtIndex = function(index, val) {
    // Check if the index is within the bounds of the linked list
    if (index < 0 || index > this.size) return;
    // If the index is 0, add the new node at the head
    if (index === 0) return this.addAtHead(val);
    // If the index is equal to the size, add the new node at the tail
    if (index === this.size) return this.addAtTail(val);
    let newNode = { val: val, next: null };
    let current = this.head;
    // Traverse the linked list to find the node before the given index
    for (let i = 0; i < index - 1; i++) current = current.next;
    // Insert the new node at the given index
    newNode.next = current.next;
    current.next = newNode;
    // Increment the size of the linked list
    this.size++;
}

MyLinkedList.prototype.deleteAtIndex = function(index) {
    // Check if the index is within the bounds of the linked list
    if (index < 0 || index >= this.size) return;
    // If the index is 0, remove the head node
    if (index === 0) {
        // Update the head of the linked list
        this.head = this.head.next;
        // If the linked list becomes empty, update the tail
        if (!this.head) this.tail = null;
    } else {
        let current = this.head;
        // Traverse the linked list to find the node before the given index
        for (let i = 0; i < index - 1; i++) current = current.next;
        // Remove the node at the given index
        current.next = current.next.next;
        // If the removed node was the tail, update the tail
        if (!current.next) this.tail = current;
    }
    // Decrement the size of the linked list
    this.size--;
}

function toLowerCase(s) {
  let result = ''; 
  // iterate over each character in the string and convert to lower case if it's an uppercase letter
  for (let i = 0; i < s.length; i++) {
    let charCode = s.charCodeAt(i); 
    // check if the character is an uppercase letter
    if (charCode >= 65 && charCode <= 90) {
      // convert the character to lower case
      result += String.fromCharCode(charCode + 32); 
    } else {
      result += s[i]; 
    }
  }
  return result;
}

function pickRandom(n, blacklist) {
    let availableNumbers = n - blacklist.length;
    let mapping = {};
    let j = 0;
    // Create a mapping of blacklisted numbers to their corresponding available numbers
    for (let i = 0; i < n; i++) {
        if (blacklist.includes(i)) {
            continue;
        }
        if (j < blacklist.length && i > blacklist[j]) {
            mapping[blacklist[j]] = i;
            j++;
        }
    }
    // Generate a random number and return the corresponding available number
    let randomIndex = Math.floor(Math.random() * availableNumbers);
    for (let i = 0; i < n; i++) {
        if (!blacklist.includes(i)) {
            if (randomIndex === 0) {
                return i;
            }
            randomIndex--;
        }
    }
}

function minimumDeleteSum(s1, s2) {
    let m = s1.length, n = s2.length;
    let dp = Array(m + 1).fill(0).map(() => Array(n + 1).fill(0));
    for (let i = 1; i <= m; i++) // initialize the first row
        dp[i][0] = dp[i - 1][0] + s1.charCodeAt(i - 1);
    for (let j = 1; j <= n; j++) // initialize the first column
        dp[0][j] = dp[0][j - 1] + s2.charCodeAt(j - 1);
    for (let i = 1; i <= m; i++) 
        for (let j = 1; j <= n; j++) 
            // if the current characters are the same, no need to delete
            dp[i][j] = s1[i - 1] === s2[j - 1] ? dp[i - 1][j - 1] : Math.min(dp[i - 1][j] + s1.charCodeAt(i - 1), dp[i][j - 1] + s2.charCodeAt(j - 1));
    return dp[m][n];
}

function numSubarrayProductLessThanK(nums, k) {
  if (k <= 1) return 0; // if k is less than or equal to 1, no subarray product will be less than k
  let left = 0, product = 1, count = 0;
  for (let right = 0; right < nums.length; right++) {
    product *= nums[right]; // keep track of the current subarray product
    while (product >= k && left <= right) { // if product is greater than or equal to k, shrink the window from the left
      product /= nums[left];
      left++;
    }
    count += right - left + 1; // count the number of subarrays ending at the current right pointer
  }
  return count;
}

function maxProfit(prices, fee) {
  let buy = -prices[0]; // initialize buy state with the first price
  let sell = 0; // initialize sell state with 0 profit
  for (let i = 1; i < prices.length; i++) {
    // update buy state by choosing the maximum between the current buy state and the previous sell state minus the current price
    buy = Math.max(buy, sell - prices[i]);
    // update sell state by choosing the maximum between the current sell state and the previous buy state plus the current price minus the transaction fee
    sell = Math.max(sell, buy + prices[i] - fee);
  }
  return sell; // return the maximum profit
}

function RangeModule() {
    let ranges = [];
    return {
        addRange: function(left, right) {
        // merge overlapping ranges
        let i = 0;
        while (i < ranges.length && ranges[i][1] < left) i++;
        let start = i; // preserve the original prefix boundary -- the loop below mutates i
        let j = i;
        while (j < ranges.length && ranges[j][0] <= right) j++;
        let merged = [left, right];
        while (i < j) {
            merged[0] = Math.min(merged[0], ranges[i][0]);
            merged[1] = Math.max(merged[1], ranges[i][1]);
            i++;
        }
        ranges = ranges.slice(0, start).concat([merged]).concat(ranges.slice(j));
    },
    queryRange: function(left, right) {
        // find the range that contains the query range
        let i = 0;
        while (i < ranges.length && ranges[i][1] < left) i++;
        return i < ranges.length && ranges[i][0] <= left && right <= ranges[i][1];
    },
    removeRange: function(left, right) {
        // split the range that overlaps with the remove range
        let i = 0;
        while (i < ranges.length && ranges[i][1] < left) i++;
        let j = i;
        while (j < ranges.length && ranges[j][0] < right) j++;
        let newRanges = ranges.slice(0, i);
        if (i < j) {
            if (ranges[i][0] < left) newRanges.push([ranges[i][0], left]);
            if (ranges[i][1] > right) newRanges.push([right, ranges[i][1]]);
            i++;
        }
        while (i < j) {
            if (ranges[i][1] > right) newRanges.push([right, ranges[i][1]]);
            i++;
        }
        ranges = newRanges.concat(ranges.slice(j));
    }
    };
}

function isOneBitCharacter(bits) {
  let index = 0;
  // loop through the array and move the index based on the current bit
  while (index < bits.length - 1) {
    // if the current bit is 1, it must be a two-bit character, so move the index by 2
    if (bits[index] === 1) {
      index += 2;
    } 
    // if the current bit is 0, it must be a one-bit character, so move the index by 1
    else {
      index += 1;
    }
  }
  // if the index is at the second last position, the last character must be a one-bit character
  return index === bits.length - 1;
}

function findLength(nums1, nums2) {
    let maxLength = 0;
    // Create a 2D array to store the lengths of common subarrays
    let dp = Array(nums1.length + 1).fill(0).map(() => Array(nums2.length + 1).fill(0));
    // Iterate over both arrays to find common subarrays
    for (let i = 1; i <= nums1.length; i++) {
        for (let j = 1; j <= nums2.length; j++) {
            // If the current elements are equal, update the length of the common subarray
            if (nums1[i - 1] === nums2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
                // Update the maximum length found so far
                maxLength = Math.max(maxLength, dp[i][j]);
            }
        }
    }
    return maxLength;
}

function kthSmallestPairDistance(nums, k) {
    let distances = [];
    for (let i = 0; i < nums.length; i++) {
        for (let j = i + 1; j < nums.length; j++) {
            // calculate all possible pair distances and store them in an array
            distances.push(Math.abs(nums[i] - nums[j]));
        }
    }
    distances.sort((a, b) => a - b);
    // return the kth smallest distance after sorting the array
    return distances[k - 1];
}

function longestWord(words) {
    words.sort(); // sort the words lexicographically
    let wordSet = new Set(words); // create a set for O(1) lookup
    let longestWord = ''; // initialize the longest word
    for (let word of words) {
        let isBuildable = true; // assume the word is buildable
        for (let i = 1; i < word.length; i++) { // check if each prefix is in the set
            // if any prefix is not in the set, the word is not buildable
            if (!wordSet.has(word.substring(0, i))) {
                isBuildable = false;
                break;
            }
        }
        // if the word is buildable and it's longer than the current longest word, update the longest word
        if (isBuildable && word.length > longestWord.length) {
            longestWord = word;
        }
    }
    return longestWord;
}

function removeComments(source) {
    let result = [];
    let blockComment = false;
    let currentLine = '';
    for (let line of source) {
        let i = 0;
        while (i < line.length) {
            // check if we are in a block comment
            if (blockComment) {
                // check if block comment ends
                if (line.substring(i, i + 2) === '*/') {
                    i += 2;
                    blockComment = false;
                } else {
                    i++;
                }
            } else {
                // check if line comment starts
                if (line.substring(i, i + 2) === '//') {
                    break;
                }
                // check if block comment starts
                else if (line.substring(i, i + 2) === '/*') {
                    i += 2;
                    blockComment = true;
                } else {
                    currentLine += line[i];
                    i++;
                }
            }
        }
        // add current line to result if it is not empty
        if (currentLine !== '' && !blockComment) {
            result.push(currentLine);
            currentLine = '';
        }
    }
    return result;
}

function accountsMerge(accounts) {
    // Create a parent map to store the parent of each email
    let parent = {};
    // Create an email map to store the emails of each person
    let emailMap = {};

    // Initialize the parent map and email map
    for (let i = 0; i < accounts.length; i++) {
        for (let j = 1; j < accounts[i].length; j++) {
            // Initialize the parent of each email to itself
            parent[accounts[i][j]] = accounts[i][j];
            // Store the emails of each person
            emailMap[accounts[i][j]] = accounts[i][0];
        }
    }

    // Create a union function to union two emails
    function union(email1, email2) {
        // Find the parent of email1 and email2
        let parent1 = find(email1);
        let parent2 = find(email2);
        // If the parents are different, union them
        if (parent1 !== parent2) {
            parent[parent1] = parent2;
        }
    }

    // Create a find function to find the parent of an email
    function find(email) {
        // If the email is not its own parent, find its parent
        if (parent[email] !== email) {
            parent[email] = find(parent[email]);
        }
        return parent[email];
    }

    // Union emails that belong to the same person
    for (let i = 0; i < accounts.length; i++) {
        for (let j = 2; j < accounts[i].length; j++) {
            // Union the current email with the previous email
            union(accounts[i][j], accounts[i][j - 1]);
        }
    }

    // Create a result map to store the merged emails of each person
    let result = {};
    // Store the merged emails of each person
    for (let email in parent) {
        // Find the parent of the email
        let parentEmail = find(email);
        // If the parent email is not in the result map, add it
        if (!(parentEmail in result)) {
            result[parentEmail] = [];
        }
        // Add the email to the result map
        result[parentEmail].push(email);
    }

    // Create the final result
    let finalResult = [];
    // For each person, add their merged emails to the final result
    for (let email in result) {
        // Sort the emails of the person
        let emails = result[email].sort();
        // Add the name and emails of the person to the final result
        finalResult.push([emailMap[email]].concat(emails));
    }

    return finalResult;
}

