function pivotIndex(nums) {
    let totalSum = 0; // calculate total sum of the array
    for (let i = 0; i < nums.length; i++) {
        totalSum += nums[i];
    }
    let leftSum = 0; // initialize left sum
    for (let i = 0; i < nums.length; i++) {
        // if left sum equals total sum minus left sum and current element, return index
        if (leftSum === totalSum - leftSum - nums[i]) {
            return i;
        }
        leftSum += nums[i]; // update left sum
    }
    return -1; // if no pivot index is found, return -1
}

function splitListToParts(head, k) {
    let length = 0;
    let temp = head;
    // calculate the length of the linked list
    while (temp !== null) {
        length++;
        temp = temp.next;
    }
    let result = new Array(k);
    let size = Math.floor(length / k);
    let remainder = length % k;
    let start = head;
    // split the linked list into k parts
    for (let i = 0; i < k; i++) {
        result[i] = start;
        let partSize = size + (i < remainder ? 1 : 0);
        // move to the end of the current part
        for (let j = 0; j < partSize - 1; j++) {
            if (start !== null) {
                start = start.next;
            }
        }
        // split the linked list at the end of the current part
        if (start !== null) {
            let next = start.next;
            start.next = null;
            start = next;
        }
    }
    return result;
}

function countOfAtoms(formula) {
    let stack = [{ }];
    for (let i = 0; i < formula.length; i++) {
        // parse the current character and decide what to do
        if (formula[i] === '(') {
            stack.push({ });
        } else if (formula[i] === ')') {
            let current = stack.pop();
            let multiplier = 0;
            i++;
            // parse the multiplier after the closing parenthesis
            while (i < formula.length && !isNaN(formula[i])) {
                multiplier = multiplier * 10 + parseInt(formula[i]);
                i++;
            }
            if (multiplier === 0) multiplier = 1;
            i--;
            for (let name in current) {
                stack[stack.length - 1][name] = (stack[stack.length - 1][name] || 0) + current[name] * multiplier;
            }
        } else {
            let name = formula[i++];
            // parse the rest of the name
            while (i < formula.length && formula[i] >= 'a' && formula[i] <= 'z') {
                name += formula[i++];
            }
            i--;
            let multiplier = 0;
            // parse the multiplier after the name
            while (i + 1 < formula.length && !isNaN(formula[i + 1])) {
                multiplier = multiplier * 10 + parseInt(formula[++i]);
            }
            if (multiplier === 0) multiplier = 1;
            stack[stack.length - 1][name] = (stack[stack.length - 1][name] || 0) + multiplier;
        }
    }
    let result = [];
    for (let name in stack[0]) {
        result.push(name + (stack[0][name] > 1 ? stack[0][name] : ''));
    }
    return result.sort().join('');
}

function selfDividingNumbers(left, right) {
  function isSelfDividing(num) {
    // check if num is divisible by every digit it contains
    for (let digit of num.toString()) {
      if (digit === '0' || num % parseInt(digit) !== 0) {
        return false;
      }
    }
    return true;
  }

  let result = [];
  for (let i = left; i <= right; i++) {
    // check each number in the range to see if it's self-dividing
    if (isSelfDividing(i)) {
      result.push(i);
    }
  }
  return result;
}

function MyCalendar() {
