}

function countPalindromicSubsequences(s) {
    const MOD = 1e9 + 7;
    const n = s.length;
    const dp = Array.from({length: n}, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) dp[i][i] = 1;
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i <= n - len; i++) {
            const j = i + len - 1;
            if (s[i] === s[j]) {
                let lo = i + 1, hi = j - 1;
                while (lo <= hi && s[lo] !== s[i]) lo++;
                while (lo <= hi && s[hi] !== s[i]) hi--;
                if (lo > hi) {
                    dp[i][j] = (2 * dp[i + 1][j - 1] + 2) % MOD;
                } else if (lo === hi) {
                    dp[i][j] = (2 * dp[i + 1][j - 1] + 1) % MOD;
                } else {
                    dp[i][j] = (2 * dp[i + 1][j - 1] - dp[lo + 1][hi - 1] + MOD) % MOD;
                }
            } else {
                dp[i][j] = (dp[i + 1][j] + dp[i][j - 1] - dp[i + 1][j - 1] + MOD) % MOD;
            }
        }
    }
    return dp[0][n - 1];
}

function book(start, end, events) {
    // Check for single and double bookings
    for (let i = 0; i < events.length; i++) {
        // If the new event overlaps with an existing event
        if (start < events[i][1] && end > events[i][0]) {
            for (let j = 0; j < events.length; j++) {
                // If the overlap of the new event and an existing event overlaps with another existing event
                if (i !== j && Math.max(start, events[i][0]) < Math.min(end, events[i][1]) && Math.max(start, events[j][0]) < Math.min(end, events[j][1]) && Math.max(events[i][0], events[j][0]) < Math.min(events[i][1], events[j][1])) {
                    return false;
                }
            }
        }
    }
    // Add the new event if no triple booking is found
    events.push([start, end]);
    return true;
}

function MyCalendarThree() {
