function floodFill(image, sr, sc, color) {
    // get the target color from the image at the start position
    var targetColor = image[sr][sc];
    // if the target color is the same as the new color, no changes are needed
    if (targetColor === color) return image;
    // define the possible directions for DFS (up, down, left, right)
    var directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    // perform DFS from the start position
    function dfs(row, col) {
        // if the current position is out of bounds or the color is not the target color, return
        if (row < 0 || row >= image.length || col < 0 || col >= image[0].length || image[row][col] !== targetColor) return;
        // change the color of the current position to the new color
        image[row][col] = color;
        // perform DFS on the neighboring positions
        for (var i = 0; i < directions.length; i++) {
            // calculate the new position
            var newRow = row + directions[i][0];
            var newCol = col + directions[i][1];
            // perform DFS from the new position
            dfs(newRow, newCol);
        }
    }
    // start the DFS from the start position
    dfs(sr, sc);
    // return the modified image
    return image;
}

function asteroidCollision(asteroids) {
    let stack = [];
    for (let asteroid of asteroids) {
        let alive = true;
        while (alive && asteroid < 0 && stack.length > 0 && stack[stack.length - 1] > 0) {
            if (stack[stack.length - 1] < -asteroid) {
                stack.pop();
            } else if (stack[stack.length - 1] === -asteroid) {
                stack.pop();
                alive = false;
            } else {
                alive = false;
            }
        }
        if (alive) stack.push(asteroid);
    }
    return stack;
}

function evaluate(expression) {
    function tokenize(s) {
        const tokens = [];
        let depth = 0, start = 0;
        for (let i = 0; i < s.length; i++) {
            if (s[i] === '(') depth++;
            else if (s[i] === ')') depth--;
            else if (s[i] === ' ' && depth === 0) {
                tokens.push(s.slice(start, i));
                start = i + 1;
            }
        }
        tokens.push(s.slice(start));
        return tokens;
    }
    function helper(expr, scope) {
        if (expr[0] !== '(') {
            if (!isNaN(parseInt(expr[0])) || expr[0] === '-') return parseInt(expr);
            for (let i = scope.length - 1; i >= 0; i--) {
                if (scope[i].has(expr)) return scope[i].get(expr);
            }
        }
        const inner = expr.slice(1, -1);
        const tokens = tokenize(inner);
        if (tokens[0] === 'let') {
            const newScope = new Map();
            scope.push(newScope);
            let i = 1;
            while (i < tokens.length - 1) {
                newScope.set(tokens[i], helper(tokens[i + 1], scope));
                i += 2;
            }
            const result = helper(tokens[tokens.length - 1], scope);
            scope.pop();
            return result;
        } else if (tokens[0] === 'add') {
            return helper(tokens[1], scope) + helper(tokens[2], scope);
        } else {
            return helper(tokens[1], scope) * helper(tokens[2], scope);
        }
    }
    return helper(expression, []);
}

function monotoneIncreasingDigits(n) {
  let numStr = n.toString();
  let result = -1;
  for (let i = numStr.length - 1; i >= 0; i--) {
    // if current digit is greater than the next one, decrease current digit and set all following digits to 9
    if (i < numStr.length - 1 && numStr[i] > numStr[i + 1]) {
      numStr = numStr.substring(0, i) + (parseInt(numStr[i]) - 1).toString() + new Array(numStr.length - i - 1).fill('9').join('');
      // since we've decreased the current digit, we need to break the loop and start from the beginning to check for other potential decreases
      break;
    }
  }
  // if we've made any changes to the number, we need to check again from the beginning
  if (numStr !== n.toString()) {
    result = monotoneIncreasingDigits(parseInt(numStr));
  } else {
    result = n;
  }
  return result;
}

function dailyTemperatures(temperatures) {
  const result = new Array(temperatures.length).fill(0);
  const stack = [];
  for (let i = 0; i < temperatures.length; i++) {
    // while the stack is not empty and the current temperature is greater than the temperature at the top of the stack
    while (stack.length > 0 && temperatures[i] > temperatures[stack[stack.length - 1]]) {
      // calculate the difference between the current index and the index at the top of the stack
      const index = stack.pop();
      result[index] = i - index;
    }
    // push the current index to the stack
    stack.push(i);
  }
  return result;
}

function deleteAndEarn(nums) {
  let maxVal = 0;
  for (let num of nums) {
    maxVal = Math.max(maxVal, num);
  }
  let count = new Array(maxVal + 1).fill(0);
  for (let num of nums) {
    // Count occurrences of each number to calculate points
    count[num]++;
  }
  let dp = new Array(maxVal + 1).fill(0);
  dp[1] = count[1];
  for (let i = 2; i <= maxVal; i++) {
    // For each number, choose the maximum points between including and excluding it
    dp[i] = Math.max(dp[i-1], dp[i-2] + count[i] * i);
  }
  return dp[maxVal];
}

function cherryPickup(grid) {
  const n = grid.length;
  const memo = new Map();
  function dp(r1, c1, r2) {
    const c2 = r1 + c1 - r2;
    if (r1 >= n || c1 >= n || r2 >= n || c2 >= n || c2 < 0 || grid[r1][c1] === -1 || grid[r2][c2] === -1) return -Infinity;
    if (r1 === n - 1 && c1 === n - 1) return grid[r1][c1];
    const key = r1 + ',' + c1 + ',' + r2;
    if (memo.has(key)) return memo.get(key);
    let cherries = grid[r1][c1];
    if (r1 !== r2) cherries += grid[r2][c2];
    let best = Math.max(dp(r1 + 1, c1, r2 + 1), dp(r1 + 1, c1, r2), dp(r1, c1 + 1, r2 + 1), dp(r1, c1 + 1, r2));
    cherries += best;
    memo.set(key, cherries);
    return cherries;
  }
  return Math.max(dp(0, 0, 0), 0);
}

function nextGreatestLetter(letters, target) {
  let left = 0, right = letters.length - 1;
  // perform binary search to find the smallest character greater than target
  while (left <= right) {
    let mid = Math.floor((left + right) / 2);
    // if the middle character is greater than target, update right pointer
    if (letters[mid] > target) {
      right = mid - 1;
    } 
    // if the middle character is not greater than target, update left pointer
    else {
      left = mid + 1;
    }
  }
  // if no character is greater than target, return the first character
  return letters[left % letters.length];
}

function networkDelayTime(times, n, k) {
    // Create an adjacency list representation of the graph
    const graph = Array.from({ length: n + 1 }, () => []);
    for (const [u, v, w] of times) {
        graph[u].push([v, w]);
    }

    // Initialize the distance array with infinity for all nodes except the source node
    const distance = Array.from({ length: n + 1 }, () => Infinity);
    distance[k] = 0;

    // Create a priority queue to store nodes to be processed
    const pq = [[k, 0]];

    // Process nodes in the priority queue
    while (pq.length) {
        const [node, dist] = pq.shift();
        // If the current distance is greater than the already known distance, skip this node
        if (dist > distance[node]) continue;

        // Update distances for neighbors of the current node
        for (const [neighbor, weight] of graph[node]) {
            const newDist = dist + weight;
            if (newDist < distance[neighbor]) {
                distance[neighbor] = newDist;
                pq.push([neighbor, newDist]);
                // Sort the priority queue to ensure the node with the smallest distance is processed next
                pq.sort((a, b) => a[1] - b[1]);
            }
        }
    }

    // Find the maximum distance in the distance array
    const maxDist = Math.max(...distance.slice(1));

    // If the maximum distance is infinity, return -1; otherwise, return the maximum distance
    return maxDist === Infinity ? -1 : maxDist;
}

function WordFilter(words) {
    this.trie = {};
    for (let weight = 0; weight < words.length; weight++) {
        let word = words[weight];
        for (let i = 0; i < word.length; i++) {
            // create all possible prefixes of the word
            let prefix = word.substring(0, i + 1);
            for (let j = 0; j < word.length; j++) {
                // create all possible suffixes of the word
                let suffix = word.substring(j);
                // store the word and its weight in the trie with the prefix and suffix as the key
                this.trie[prefix + '#' + suffix] = weight;
            }
        }
    }
}

function f(word, prefix, suffix) {
    // check if the word starts with the prefix and ends with the suffix
    return word.startsWith(prefix) && word.endsWith(suffix);
}

function WordFilterSearch(wordFilter, prefix, suffix) {
