    return key in this.trie ? this.trie[key] : -1;
};

function dominantIndex(nums) {
  let maxIndex = 0, max = nums[0], secondMax = -Infinity;
  // iterate through the array to find the max and second max values
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > max) {
      secondMax = max;
      max = nums[i];
      maxIndex = i;
    } else if (nums[i] > secondMax) {
      secondMax = nums[i];
    }
  }
  // check if the max value is at least twice as much as the second max value
  return max >= 2 * secondMax ? maxIndex : -1;
}

function minCostClimbingStairs(cost) {
    let n = cost.length;
    let dp = new Array(n);
    dp[0] = cost[0]; // base case for starting at index 0
    dp[1] = cost[1]; // base case for starting at index 1
    // calculate minimum cost for each step
    for (let i = 2; i < n; i++) {
        // choose the minimum cost between the previous step and the step before that
        dp[i] = Math.min(dp[i-1], dp[i-2]) + cost[i];
    }
    // return the minimum cost to reach the top
    return Math.min(dp[n-1], dp[n-2]);
}

function openLock(deadends, target) {
    let dead = new Set(deadends);
    if (dead.has('0000')) return -1;
    let queue = [['0000', 0]];
    let visited = new Set(['0000']);
    while (queue.length > 0) {
        let [lock, turns] = queue.shift();
        // generate all possible next states by turning each wheel one slot
        for (let i = 0; i < 4; i++) {
            for (let j = -1; j <= 1; j += 2) {
                let nextLock = lock.substring(0, i) + ((lock.charCodeAt(i) - '0'.charCodeAt(0) + j + 10) % 10) + lock.substring(i + 1);
                // if the next state is the target, return the number of turns
                if (nextLock === target) return turns + 1;
                // if the next state is not a dead end and has not been visited, add it to the queue
                if (!dead.has(nextLock) && !visited.has(nextLock)) {
                    queue.push([nextLock, turns + 1]);
                    visited.add(nextLock);
                }
            }
        }
    }
    // if the target cannot be reached, return -1
    return -1;
}

function crackSafe(n, k) {
    const visited = new Set();
    const result = [];
    const start = '0'.repeat(n - 1);
    function dfs(node) {
        for (let x = 0; x < k; x++) {
            const next = node + x;
            if (!visited.has(next)) {
                visited.add(next);
                dfs(next.slice(1));
                result.push(x.toString());
            }
        }
    }
    dfs(start);
    return result.join('') + start;
}

function containVirus(isInfected) {
    const m = isInfected.length;
    const n = isInfected[0].length;
    let wallsUsed = 0;
    while (true) {
        const regions = [];
        const visited = Array.from({ length: m }, () => Array(n).fill(false));
        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (isInfected[i][j] === 1 && !visited[i][j]) {
                    const region = [];
                    const frontierSet = new Set();
                    let frontierEdges = 0;
                    const dfs = (x, y) => {
                        visited[x][y] = true;
                        region.push([x, y]);
                        for (const [dx, dy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
                            const nx = x + dx;
                            const ny = y + dy;
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n) {
                                if (isInfected[nx][ny] === 1 && !visited[nx][ny]) {
                                    dfs(nx, ny);
                                } else if (isInfected[nx][ny] === 0) {
                                    frontierSet.add(nx + ',' + ny);
                                    frontierEdges++;
                                }
                            }
                        }
                    };
                    dfs(i, j);
                    regions.push({ region, frontierSet, frontierEdges });
                }
            }
        }
        if (regions.length === 0) break;
        let maxThreat = 0, maxRegionIndex = -1;
        for (let i = 0; i < regions.length; i++) {
            if (regions[i].frontierSet.size > maxThreat) {
                maxThreat = regions[i].frontierSet.size;
                maxRegionIndex = i;
            }
        }
        wallsUsed += regions[maxRegionIndex].frontierEdges;
        for (const [x, y] of regions[maxRegionIndex].region) {
            isInfected[x][y] = -1;
        }
        for (let i = 0; i < regions.length; i++) {
            if (i !== maxRegionIndex) {
                for (const key of regions[i].frontierSet) {
                    const [x, y] = key.split(',').map(Number);
                    isInfected[x][y] = 1;
                }
            }
        }
    }
    return wallsUsed;
}

function validPalindrome(s) {
  let left = 0;
  let right = s.length - 1;
  // check if the string is already a palindrome or can be made one by removing one character
  while (left < right) {
    if (s[left] !== s[right]) {
      // check if removing the character at the left or right pointer makes the string a palindrome
      return isPalindrome(s, left + 1, right) || isPalindrome(s, left, right - 1);
    }
    left++;
    right--;
  }
  return true;
}

function isPalindrome(s, left, right) {
  while (left < right) {
    if (s[left] !== s[right]) {
      return false;
    }
    left++;
    right--;
  }
  return true;
}

function trimBST(root, low, high) {
    // if the tree is empty, return null
    if (!root) return null;
    // if the current node's value is less than low, trim the left subtree and return the trimmed right subtree
    if (root.val < low) return trimBST(root.right, low, high);
    // if the current node's value is greater than high, trim the right subtree and return the trimmed left subtree
    if (root.val > high) return trimBST(root.left, low, high);
    // if the current node's value is within the range, recursively trim the left and right subtrees
    root.left = trimBST(root.left, low, high);
    root.right = trimBST(root.right, low, high);
    return root;
}

function findTilt(root) {
    let totalTilt = 0;
    function dfs(node) {
        // calculate the sum of the left and right subtrees and update the total tilt
        if (!node) return 0;
        let leftSum = dfs(node.left);
        let rightSum = dfs(node.right);
        totalTilt += Math.abs(leftSum - rightSum);
        // return the sum of the current node and its subtrees
        return node.val + leftSum + rightSum;
    }
    dfs(root);
    return totalTilt;
}

function findSecondMinimumValue(root) {
    let min = root.val;
    let secondMin = Infinity;
    function dfs(node) {
        // traverse the tree and update secondMin if a smaller value is found
        if (node.val > min && node.val < secondMin) secondMin = node.val;
        if (node.left) dfs(node.left);
        if (node.right) dfs(node.right);
    }
    dfs(root);
    // return -1 if no second minimum value exists, otherwise return the second minimum value
    return secondMin === Infinity ? -1 : secondMin;
}

function calPoints(operations) {
    let scores = [];
    for (let operation of operations) {
        // Check if the operation is a number
        if (!isNaN(operation)) {
            scores.push(parseInt(operation));
        } 
        // Check if the operation is 'C' to invalidate and remove the previous score
        else if (operation === 'C') {
            scores.pop();
        } 
        // Check if the operation is 'D' to add double the previous score
        else if (operation === 'D') {
            scores.push(2 * scores[scores.length - 1]);
        } 
        // Check if the operation is '+' to add the sum of the last two scores
        else if (operation === '+') {
            scores.push(scores[scores.length - 1] + scores[scores.length - 2]);
        }
    }
    // Calculate the sum of all scores
    return scores.reduce((a, b) => a + b, 0);
}

function flipLights(n, presses) {
    n = Math.min(n, 3);
    function popcount(x) { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; }
    function applyButton(lights, b) {
        for (let i = 0; i < lights.length; i++) {
            if (b === 0) lights[i] ^= 1;
            else if (b === 1 && i % 2 === 0) lights[i] ^= 1;
            else if (b === 2 && i % 2 === 1) lights[i] ^= 1;
            else if (b === 3 && i % 3 === 0) lights[i] ^= 1;
        }
    }
    const seen = new Set();
    for (let mask = 0; mask < 16; mask++) {
        const cnt = popcount(mask);
        if (cnt > presses) continue;
        if ((presses - cnt) % 2 !== 0) continue;
        const lights = new Array(n).fill(1);
        for (let b = 0; b < 4; b++) {
            if (mask & (1 << b)) applyButton(lights, b);
        }
        seen.add(lights.join(''));
    }
    return seen.size;
}

function findKthNumber(m, n, k) {
    let left = 1;
    let right = m * n;
    while (left < right) {
        // calculate the middle value and count how many numbers are less than or equal to it
        let mid = Math.floor((left + right) / 2);
        let count = 0;
        let j = n;
        for (let i = 1; i <= m; i++) {
            // while the product of i and j is greater than mid, decrement j
            while (j > 0 && i * j > mid) {
                j--;
            }
            // add the count of numbers less than or equal to mid for the current i
            count += j;
        }
        // if the count is less than k, move the left pointer to mid + 1
        if (count < k) {
            left = mid + 1;
        } 
        // if the count is greater than or equal to k, move the right pointer to mid
        else {
            right = mid;
        }
    }
    return left;
}

