function judgePoint24(cards) {
    function calculate(a, b, op) {
        if (op === '+') return a + b;
        if (op === '-') return a - b;
        if (op === '*') return a * b;
        if (op === '/') return a / b;
    }

    function dfs(nums) {
        if (nums.length === 1) return Math.abs(nums[0] - 24) < 0.001; // check if the result is close to 24
        for (let i = 0; i < nums.length; i++) {
            for (let j = i + 1; j < nums.length; j++) {
                for (let op of ['+', '-', '*', '/']) {
                    let a = nums[i], b = nums[j];
                    let next = [calculate(a, b, op)];
                    for (let k = 0; k < nums.length; k++) {
                        if (k !== i && k !== j) next.push(nums[k]);
                    }
                    if (dfs(next)) return true; // recursively check all possible combinations
                }
            }
        }
        return false;
    }
    return dfs(cards);
}

function reachNumber(target) {
    target = Math.abs(target);
    let step = 0;
    let sum = 0;
    // keep moving until we reach or exceed the target
    while (sum < target) {
        step++;
        sum += step;
    }
    // adjust the steps if the sum exceeds the target and is odd
    while ((sum - target) % 2 !== 0) {
        step++;
        sum += step;
    }
    return step;
}

