function findClosestPalindrome(n) {
    const num = parseInt(n);
    const len = n.length;
    const candidates = new Set();
    candidates.add(String(Math.pow(10, len - 1) - 1)); // e.g. 99
    candidates.add(String(Math.pow(10, len) + 1)); // e.g. 1001

    const prefix = parseInt(n.substring(0, Math.ceil(len / 2)));
    for (const p of [prefix - 1, prefix, prefix + 1]) {
        const prefixStr = String(p);
        let palin;
        if (len % 2 === 0) {
            palin = prefixStr + prefixStr.split('').reverse().join('');
        } else {
            palin = prefixStr + prefixStr.split('').reverse().join('').substring(1);
        }
        candidates.add(palin);
    }
    candidates.delete(String(num));

    let closest = null;
    let minDiff = Infinity;
    for (const cStr of candidates) {
        const c = parseInt(cStr);
        const diff = Math.abs(c - num);
        if (diff < minDiff || (diff === minDiff && c < closest)) {
            minDiff = diff;
            closest = c;
        }
    }
    return String(closest);
}

function shortestCompletingWord(licensePlate, words) {
    // Create a frequency map of the letters in the license plate, ignoring numbers and spaces, and treating letters as case insensitive
    let licensePlateMap = {};
    for (let char of licensePlate.toLowerCase()) {
        if (char >= 'a' && char <= 'z') {
            if (licensePlateMap[char]) {
                licensePlateMap[char]++;
            } else {
                licensePlateMap[char] = 1;
            }
        }
    }

    // Initialize the shortest completing word and its length
    let shortestWord = '';
    let shortestLength = Infinity;

    // Iterate over each word in the list of words
    for (let word of words) {
        // Create a frequency map of the letters in the current word
        let wordMap = {};
        for (let char of word.toLowerCase()) {
            if (wordMap[char]) {
                wordMap[char]++;
            } else {
                wordMap[char] = 1;
            }
        }

        // Check if the current word is a completing word
        let isCompletingWord = true;
        for (let char in licensePlateMap) {
            // If the current word does not contain a letter in the license plate, or does not contain it enough times, it is not a completing word
            if (!wordMap[char] || wordMap[char] < licensePlateMap[char]) {
                isCompletingWord = false;
                break;
            }
        }

        // If the current word is a completing word and is shorter than the current shortest word, update the shortest word
        if (isCompletingWord && word.length < shortestLength) {
            shortestWord = word;
            shortestLength = word.length;
        }
    }

    return shortestWord;
}

function countPrimeSetBits(left, right) {
  function isPrime(n) {
    if (n <= 1) return false;
    if (n <= 3) return true;
    if (n % 2 === 0 || n % 3 === 0) return false;
    let i = 5;
    while (i * i <= n) {
      if (n % i === 0 || n % (i + 2) === 0) return false;
      i += 6;
    }
    return true;
  }
  let count = 0;
  for (let i = left; i <= right; i++) {
    // count the number of set bits in the binary representation of i
    let setBits = i.toString(2).split('1').length - 1;
    // check if the number of set bits is prime
    if (isPrime(setBits)) count++;
  }
  return count;
}

