function intersectionSize(intervals) {
    intervals.sort((a, b) => a[1] - b[1] || b[0] - a[0]);
    const result = [];
    for (const [start, end] of intervals) {
        const len = result.length;
        if (len >= 2 && result[len - 2] >= start && result[len - 1] <= end) continue;
        if (len >= 1 && result[len - 1] >= start) {
            result.push(end);
        } else {
            result.push(end - 1);
            result.push(end);
        }
    }
    return result.length;
}

function isToeplitzMatrix(matrix) {
    let rows = matrix.length;
    let cols = matrix[0].length;
    // Check each diagonal from top-left to bottom-right
    for (let i = 0; i < rows - 1; i++) {
        for (let j = 0; j < cols - 1; j++) {
            // If the current element is not equal to the element diagonally below it, return false
            if (matrix[i][j] !== matrix[i + 1][j + 1]) {
                return false;
            }
        }
    }
    return true;
}

function partitionLabels(s) {
    // create a hash table to store the last index of each character
    let lastIndex = {};
    for (let i = 0; i < s.length; i++) {
        lastIndex[s[i]] = i;
    }
    let result = [];
    let start = 0, end = 0;
    for (let i = 0; i < s.length; i++) {
        // update the end index if the current character's last index is greater than the current end index
        end = Math.max(end, lastIndex[s[i]]);
        // if the current index is equal to the end index, it means we have found a valid partition
        if (i === end) {
            result.push(end - start + 1);
            start = end + 1;
        }
    }
    return result;
}

function minSwapsCouples(row) {
    let n = row.length;
    let count = 0;
    for (let i = 0; i < n; i += 2) {
        // if the couple is not sitting side by side, we need to find the partner and swap them
        if (row[i] % 2 === 0 && row[i + 1] !== row[i] + 1) {
            for (let j = i + 1; j < n; j++) {
                // find the partner of the current person
                if (row[j] === row[i] + 1) {
                    // swap the partner with the person sitting next to the current person
                    [row[i + 1], row[j]] = [row[j], row[i + 1]];
                    count++;
                    break;
                }
            }
        } else if (row[i] % 2 === 1 && row[i + 1] !== row[i] - 1) {
            for (let j = i + 1; j < n; j++) {
                // find the partner of the current person
                if (row[j] === row[i] - 1) {
                    // swap the partner with the person sitting next to the current person
                    [row[i + 1], row[j]] = [row[j], row[i + 1]];
                    count++;
                    break;
                }
            }
        }
    }
    return count;
}

function orderOfLargestPlusSign(n, mines) {
    let grid = new Array(n).fill(0).map(() => new Array(n).fill(1));
    for (let mine of mines) {
        grid[mine[0]][mine[1]] = 0;
    }
    let maxOrder = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                let order = 1;
                // check arms of the plus sign
                while (i - order >= 0 && i + order < n && j - order >= 0 && j + order < n && 
                       grid[i - order][j] === 1 && grid[i + order][j] === 1 && 
                       grid[i][j - order] === 1 && grid[i][j + order] === 1) {
                    order++;
                }
                maxOrder = Math.max(maxOrder, order);
            }
        }
    }
    return maxOrder;
}

function makeLargestSpecial(s) {
    let count = 0, i = 0;
    let result = [];
    // iterate through the string and find all special binary substrings
    for (let j = 0; j < s.length; j++) {
        // if the character is '1', increment the count
        if (s[j] === '1') count++;
        // if the character is '0', decrement the count
        else count--;
        // if the count is zero, it means we have found a special binary substring
        if (count === 0) {
            // recursively call the function on the substring
            result.push('1' + makeLargestSpecial(s.substring(i + 1, j)) + '0');
            // update the index and reset the count
            i = j + 1;
        }
    }
    // sort the result array in descending order
    result.sort((a, b) => b.localeCompare(a));
    // join the result array into a string
    return result.join('');
}

function reorganizeString(s) {
    // Create a frequency map of characters in the string
    let frequencyMap = {};
    for (let char of s) {
        if (!frequencyMap[char]) frequencyMap[char] = 0;
        frequencyMap[char]++;
    }

    // Create a max heap to store characters and their frequencies
    let maxHeap = [];
    for (let char in frequencyMap) {
        // Push character and its frequency into the max heap
        maxHeap.push([char, frequencyMap[char]]);
    }
    maxHeap.sort((a, b) => b[1] - a[1]);

    // Initialize the result string
    let result = '';

    // While the max heap is not empty
    while (maxHeap.length > 0) {
        // If the result string is not empty and the last character of the result string is the same as the character at the top of the max heap
        if (result.length > 0 && result[result.length - 1] === maxHeap[0][0]) {
            // If the max heap has only one character left, it's not possible to rearrange the string
            if (maxHeap.length === 1) return "";
            // Otherwise, pop the second character from the max heap and append it to the result string
            let secondChar = maxHeap[1];
            result += secondChar[0];
            // Decrement the frequency of the second character
            secondChar[1]--;
            // If the frequency of the second character becomes zero, remove it from the max heap
            if (secondChar[1] === 0) maxHeap.splice(1, 1);
            // Push the first character back into the max heap
            maxHeap.push(maxHeap.shift());
        } else {
            // Pop the character at the top of the max heap and append it to the result string
            let topChar = maxHeap.shift();
            result += topChar[0];
            // Decrement the frequency of the top character
            topChar[1]--;
            // If the frequency of the top character becomes zero, do not push it back into the max heap
            if (topChar[1] > 0) maxHeap.push(topChar);
        }
        // Sort the max heap to maintain the max heap property
        maxHeap.sort((a, b) => b[1] - a[1]);
    }
    return result;
}

function pyramidTransition(bottom, allowed) {
    let allowedMap = {};
    for (let pattern of allowed) {
        let key = pattern.substring(0, 2);
        if (!allowedMap[key]) allowedMap[key] = [];
        allowedMap[key].push(pattern[2]);
    }
    let memo = {};
    function dfs(bottom) {
        let key = bottom;
        if (key.length === 1) return true; // base case: if only one block left
        if (memo[key] !== undefined) return memo[key]; // 
        let next = [];
        for (let i = 0; i < bottom.length - 1; i++) {
            let pair = bottom.substring(i, i + 2);
            if (!allowedMap[pair]) return memo[key] = false; // no allowed pattern for this pair
            if (!next.length) next = allowedMap[pair]; // initialize next level
            else {
                let temp = [];
                for (let n of next) {
                    for (let a of allowedMap[pair]) {
                        temp.push(n + a);
                    }
                }
                next = temp;
            }
        }
        for (let n of next) {
            if (dfs(n)) return memo[key] = true; // 
        }
        return memo[key] = false;
    }
    return dfs(bottom);
}

