    for (let i = 0; i < arr.length; i++) {
        maxValue = Math.max(maxValue, arr[i]);
        // if the maximum value is equal to the current index, it means we can form a chunk
        if (maxValue === i) {
            chunkCount++;
        }
    }
    return chunkCount;
}

function maxChunksToSorted(arr) {
    var sortedArr = arr.slice().sort(function(a, b) { return a - b; });
    var max = 0;
    var sum = 0;
    var sortedSum = 0;
    // iterate through both arrays and compare cumulative sums to determine chunk boundaries
    for (var i = 0; i < arr.length; i++) {
        sum += arr[i];
        sortedSum += sortedArr[i];
        // if cumulative sums are equal, it means we've found a chunk boundary
        if (sum === sortedSum) {
            max++;
        }
    }
    return max;
}

function numJewelsInStones(jewels, stones) {
