  // Iterate over each stone and check if it's a jewel
  for (let stone of stones) {
    // If the stone is in the jewel set, increment the count
    if (jewelSet.has(stone)) count++;
  }
  return count;
}

function kthGrammar(n, k) {
    let row = '0';
    for (let i = 1; i < n; i++) {
        let nextRow = '';
        for (let j = 0; j < row.length; j++) {
            if (row[j] === '0') nextRow += '01';
            else nextRow += '10';
        }
        row = nextRow;
    }
    return parseInt(row[k - 1]);
}

function basicCalculatorIV(expression, evalvars, evalints) {
  const varMap = new Map();
  for (let i = 0; i < evalvars.length; i++) varMap.set(evalvars[i], evalints[i]);

  function makeTerm(coeff, vars) {
    return new Map([[vars.join('*'), { coeff, vars }]]);
  }
  function addPoly(a, b) {
    const result = new Map(a);
    for (const [key, term] of b) {
      if (result.has(key)) {
        const existing = result.get(key);
        result.set(key, { coeff: existing.coeff + term.coeff, vars: term.vars });
      } else {
        result.set(key, term);
      }
    }
    return result;
  }
  function subPoly(a, b) {
    const negB = new Map();
    for (const [key, term] of b) negB.set(key, { coeff: -term.coeff, vars: term.vars });
    return addPoly(a, negB);
  }
  function mulPoly(a, b) {
    const result = new Map();
    for (const [, ta] of a) {
      for (const [, tb] of b) {
        let vars = [...ta.vars, ...tb.vars].filter(v => v !== '1').sort();
        if (vars.length === 0) vars = ['1'];
        const key = vars.join('*');
        const coeff = ta.coeff * tb.coeff;
        if (result.has(key)) result.get(key).coeff += coeff;
        else result.set(key, { coeff, vars });
      }
    }
    return result;
  }

  const tokens = expression.match(/[a-zA-Z]+|\d+|[()+\-*]/g);
  let pos = 0;
  function parseExpr() {
    let node = parseTerm();
    while (pos < tokens.length && (tokens[pos] === '+' || tokens[pos] === '-')) {
      const op = tokens[pos++];
      const rhs = parseTerm();
      node = op === '+' ? addPoly(node, rhs) : subPoly(node, rhs);
    }
    return node;
  }
  function parseTerm() {
    let node = parseFactor();
    while (pos < tokens.length && tokens[pos] === '*') {
      pos++;
      const rhs = parseFactor();
      node = mulPoly(node, rhs);
    }
    return node;
  }
  function parseFactor() {
    if (tokens[pos] === '(') {
      pos++;
      const node = parseExpr();
      pos++;
      return node;
    }
    const tok = tokens[pos++];
    if (/^\d+$/.test(tok)) return makeTerm(parseInt(tok), ['1']);
    if (varMap.has(tok)) return makeTerm(varMap.get(tok), ['1']);
    return makeTerm(1, [tok]);
  }

  const poly = parseExpr();
  const terms = [...poly.values()].filter(t => t.coeff !== 0);
  terms.sort((a, b) => {
    const aIsConst = a.vars[0] === '1', bIsConst = b.vars[0] === '1';
    if (aIsConst && bIsConst) return 0;
    if (aIsConst) return 1;
    if (bIsConst) return -1;
    const degDiff = b.vars.length - a.vars.length;
    if (degDiff !== 0) return degDiff;
    for (let i = 0; i < a.vars.length; i++) {
      if (a.vars[i] !== b.vars[i]) return a.vars[i] < b.vars[i] ? -1 : 1;
    }
    return 0;
  });
  return terms.map(t => t.vars[0] === '1' ? t.coeff.toString() : t.coeff + '*' + t.vars.join('*'));
}

function reachingPoints(sx, sy, tx, ty) {
    while (tx > sx && ty > sy) // continue reducing tx and ty while both are greater than sx and sy
        if (tx > ty) tx -= ty; 
        else ty -= tx;
    return (tx === sx && ty >= sy && (ty - sy) % sx === 0) || (ty === sy && tx >= sx && (tx - sx) % sy === 0);
}

