function swimInWater(grid) {
    var n = grid.length;
    var directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    var pq = [[grid[0][0], 0, 0]];
    var visited = new Array(n).fill(0).map(() => new Array(n).fill(false));
    visited[0][0] = true;
    var maxElevation = 0;
    while (pq.length > 0) {
        pq.sort((a, b) => a[0] - b[0]);
        var [currElevation, currX, currY] = pq.shift();
        maxElevation = Math.max(maxElevation, currElevation);
        if (currX === n - 1 && currY === n - 1) return maxElevation;
        for (var i = 0; i < 4; i++) {
            var newX = currX + directions[i][0];
            var newY = currY + directions[i][1];
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY]) {
                pq.push([grid[newX][newY], newX, newY]);
                visited[newX][newY] = true;
            }
        }
    }
}

function canTransform(start, result) {
    let startPointer = 0, resultPointer = 0;
    while (startPointer < start.length && resultPointer < result.length) {
        // move pointers forward until we find 'L' or 'R' in both strings
        while (startPointer < start.length && start[startPointer] === 'X') startPointer++;
        while (resultPointer < result.length && result[resultPointer] === 'X') resultPointer++;
        if (startPointer === start.length && resultPointer === result.length) return true; // both strings have been fully traversed
        if (startPointer === start.length || resultPointer === result.length) return false; // one string has been fully traversed, but not the other
        if (start[startPointer] !== result[resultPointer]) return false; // 'L' or 'R' characters do not match
        if ((start[startPointer] === 'L' && startPointer < resultPointer) || (start[startPointer] === 'R' && startPointer > resultPointer)) return false; // 'L' cannot move right, 'R' cannot move left
        startPointer++; resultPointer++;
    }
    return true;
}

function isIdealPermutation(nums) {
    var n = nums.length;
    var globalInversions = 0;
    var localInversions = 0;
    // iterate through the array to count local inversions
    for (var i = 0; i < n - 1; i++) {
        if (nums[i] > nums[i + 1]) {
            localInversions++;
        }
    }
    // iterate through the array to count global inversions
    for (var i = 0; i < n; i++) {
        // compare each element with the elements after it
        for (var j = i + 1; j < n; j++) {
            // if the current element is greater than the compared element, it's a global inversion
            if (nums[i] > nums[j]) {
                globalInversions++;
            }
        }
    }
    // return true if the number of global inversions is equal to the number of local inversions
    return globalInversions === localInversions;
}

function slidingPuzzle(board) {
    const target = [[1,2,3],[4,5,0]];
    const directions = [[1,3], [0,2,4], [1,5], [0,4], [1,3,5], [2,4]];
    const queue = [[board, 0]];
    const visited = new Set();
    visited.add(JSON.stringify(board));

    while (queue.length > 0) {
        const [state, moves] = queue.shift();
        // Check if the current state is the target state
        if (JSON.stringify(state) === JSON.stringify(target)) return moves;

        // Find the position of the empty square
        let zeroIndex = -1;
        for (let i = 0; i < 2; i++) {
            for (let j = 0; j < 3; j++) {
                if (state[i][j] === 0) {
                    zeroIndex = i * 3 + j;
                    break;
                }
            }
            if (zeroIndex !== -1) break;
        }

        // Generate all possible next states
        for (let i = 0; i < directions[zeroIndex].length; i++) {
            const nextState = JSON.parse(JSON.stringify(state));
            // Swap the empty square with the adjacent number
            [nextState[Math.floor(zeroIndex / 3)][zeroIndex % 3], nextState[Math.floor(directions[zeroIndex][i] / 3)][directions[zeroIndex][i] % 3]] = 
            [nextState[Math.floor(directions[zeroIndex][i] / 3)][directions[zeroIndex][i] % 3], nextState[Math.floor(zeroIndex / 3)][zeroIndex % 3]];

            // Check if the next state has been visited
            const nextStateStr = JSON.stringify(nextState);
            if (!visited.has(nextStateStr)) {
                queue.push([nextState, moves + 1]);
                visited.add(nextStateStr);
            }
        }
    }

    // If no solution is found, return -1
    return -1;
}

function minDiffInBST(root) {
    let minDiff = Infinity;
    let prevVal = null;
    function inorder(node) {
        if (node === null) return;
        inorder(node.left); // recursively traverse left subtree
        if (prevVal !== null) minDiff = Math.min(minDiff, Math.abs(node.val - prevVal)); // update minDiff if current node's value is closer to prevVal
        prevVal = node.val;
        inorder(node.right); // recursively traverse right subtree
    }
    inorder(root);
    return minDiff;
}

function numRabbits(answers) {
    let count = 0;
    let map = {};
    for (let answer of answers) {
        // if the answer is not in the map or the count of the answer is 0, we need to add the answer + 1 rabbits to the total count
        if (!map[answer] || map[answer] === 0) {
            count += answer + 1;
            // reset the count of the answer to the answer
            map[answer] = answer;
        } else {
            // if the answer is in the map and the count of the answer is not 0, we just decrement the count of the answer
            map[answer]--;
        }
    }
    return count;
}

function movesToMakeBoard(board) {
    const n = board.length;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if ((board[0][0] ^ board[i][0] ^ board[0][j] ^ board[i][j]) !== 0) return -1;
        }
    }
    let rowSum = 0, colSum = 0, rowSwap = 0, colSwap = 0;
    for (let i = 0; i < n; i++) {
        rowSum += board[0][i];
        colSum += board[i][0];
        if (board[i][0] === (i % 2)) rowSwap++;
        if (board[0][i] === (i % 2)) colSwap++;
    }
    if (rowSum !== Math.floor(n / 2) && rowSum !== Math.ceil(n / 2)) return -1;
    if (colSum !== Math.floor(n / 2) && colSum !== Math.ceil(n / 2)) return -1;
    if (n % 2 === 1) {
        if (rowSwap % 2 === 1) rowSwap = n - rowSwap;
        if (colSwap % 2 === 1) colSwap = n - colSwap;
    } else {
        rowSwap = Math.min(rowSwap, n - rowSwap);
        colSwap = Math.min(colSwap, n - colSwap);
    }
    return (rowSwap + colSwap) / 2;
}

function letterCasePermutation(s) {
    let result = [];
    function backtrack(current, index) {
        // if we've processed the entire string, add it to the result
        if (index === s.length) result.push(current);
        else {
            // if the current character is a letter, try both cases
            if (s[index].match(/[a-zA-Z]/)) {
                backtrack(current + s[index].toLowerCase(), index + 1);
                backtrack(current + s[index].toUpperCase(), index + 1);
            } 
            // if the current character is not a letter, just append it
            else backtrack(current + s[index], index + 1);
        }
    }
    backtrack('', 0);
    return result;
}

function isBipartite(graph) {
    const n = graph.length;
    const color = new Array(n).fill(-1);
    for (let i = 0; i < n; i++) {
        if (color[i] === -1) {
            const stack = [i];
            color[i] = 0; // assign color 0 to the current node
            while (stack.length > 0) {
                const node = stack.pop();
                for (const neighbor of graph[node]) {
                    // if the neighbor has the same color as the current node, return false
                    if (color[neighbor] === color[node]) return false;
                    if (color[neighbor] === -1) {
                        color[neighbor] = 1 - color[node]; // assign the opposite color to the neighbor
                        stack.push(neighbor);
                    }
                }
            }
        }
    }
    return true; // if we have not returned false, the graph is bipartite
}

function rotateString(s, goal) {
  // check if the length of s and goal are equal, if not return false
  if (s.length !== goal.length) return false;
  // concatenate s with itself to simulate all possible shifts
  let doubleS = s + s;
  // check if goal is a substring of the concatenated string
  return doubleS.indexOf(goal) !== -1;
}

function customSortString(order, s) {
    let frequency = {};
    // Create a frequency map of characters in string s
    for (let char of s) {
        if (!frequency[char]) frequency[char] = 0;
        frequency[char]++;
    }
    let result = '';
    // Append characters from order to the result string
    for (let char of order) {
        if (frequency[char]) {
            result += char.repeat(frequency[char]);
            frequency[char] = 0;
        }
    }
    // Append remaining characters to the result string
    for (let char in frequency) {
        if (frequency[char] > 0) {
            result += char.repeat(frequency[char]);
        }
    }
    return result;
}

function kthSmallestPrimeFraction(arr, k) {
    let n = arr.length;
    let pq = [];
    for (let j = 1; j < n; j++) pq.push([arr[0], arr[j], 0, j]);
    let res = [];
    for (let i = 0; i < k; i++) {
        pq.sort((a, b) => a[0] * b[1] - a[1] * b[0]);
        let [num, den, idx, j] = pq.shift();
        res = [num, den];
        if (idx + 1 < j) {
            pq.push([arr[idx + 1], den, idx + 1, j]);
        }
    }
    return res;
}

function escapeGhosts(ghosts, target) {
    // calculate the distance from the player to the target
    const playerDistance = Math.abs(target[0]) + Math.abs(target[1]);
    // iterate over each ghost to calculate its distance to the target
    for (let i = 0; i < ghosts.length; i++) {
        // calculate the distance from the current ghost to the target
        const ghostDistance = Math.abs(ghosts[i][0] - target[0]) + Math.abs(ghosts[i][1] - target[1]);
        // if the ghost's distance is less than or equal to the player's distance, return false
        if (ghostDistance <= playerDistance) return false;
    }
    // if no ghost can catch up, return true
    return true;
}

function numSubarrayBoundedMax(nums, left, right) {
    function countAtMost(bound) {
        let count = 0, cur = 0;
        for (const num of nums) {
            cur = num <= bound ? cur + 1 : 0;
            count += cur;
        }
        return count;
    }
    return countAtMost(right) - countAtMost(left - 1);
}

function numMatchingSubseq(s, words) {
    let count = 0;
    // iterate over each word in the words array
    for (let word of words) {
        let i = 0, j = 0;
        // use two pointers to check if the word is a subsequence of s
        while (i < s.length && j < word.length) {
            // if the current characters in s and word match, move to the next character in both strings
            if (s[i] === word[j]) j++;
            // move to the next character in s
            i++;
        }
        // if we've checked all characters in the word, it's a subsequence of s
        if (j === word.length) count++;
    }
    return count;
}

function numTilings(n) {
    const MOD = 1000000007;
    // base cases for n = 0, 1, 2, 3
    if (n === 0) return 0;
    if (n === 1) return 1;
    if (n === 2) return 2;
    if (n === 3) return 5;
    // initialize dp array with base cases
    let dp = new Array(n + 1).fill(0);
    dp[0] = 0;
    dp[1] = 1;
    dp[2] = 2;
    dp[3] = 5;
    // calculate the number of ways to tile the board for n > 3
    for (let i = 4; i <= n; i++) {
        // for each cell, consider the number of ways to tile the previous cells
        dp[i] = (2 * dp[i - 1] + dp[i - 3]) % MOD; // calculate the number of ways to tile the current cell
    }
    return dp[n];
}

function preimageSizeFZF(k) {
    function findTrailingZeroes(x) {
        let count = 0;
        let i = 5;
        while (Math.floor(x / i) >= 1) {
            count += Math.floor(x / i);
            i *= 5;
        }
        return count;
    }
    let left = 0, right = 5 * k + 5;
    while (left < right) {
        let mid = Math.floor((left + right) / 2);
        if (findTrailingZeroes(mid) < k) left = mid + 1;
        else right = mid;
    }
    if (findTrailingZeroes(left) !== k) return 0;
    let count = 1;
    let i = 1;
    while (findTrailingZeroes(left + i) === k) { count++; i++; }
    i = 1;
    while (left - i >= 0 && findTrailingZeroes(left - i) === k) { count++; i++; }
    return count;
}

function validTicTacToe(board) {
    let xCount = 0, oCount = 0;
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            if (board[i][j] === 'X') xCount++;
            else if (board[i][j] === 'O') oCount++;
        }
    }
    // Check if the number of 'X's and 'O's is valid
    if (xCount < oCount || xCount > oCount + 1) return false;
    // Check if there is a winner
    let xWin = checkWin(board, 'X');
    let oWin = checkWin(board, 'O');
    // If 'X' wins, 'X' should have one more move than 'O'
    if (xWin && xCount !== oCount + 1) return false;
    // If 'O' wins, 'X' and 'O' should have the same number of moves
    if (oWin && xCount !== oCount) return false;
    // If both 'X' and 'O' win, it's not a valid state
    if (xWin && oWin) return false;
    return true;
}

function checkWin(board, player) {
    // Check rows and columns for a win
    for (let i = 0; i < 3; i++) {
        if (board[i][0] === player && board[i][1] === player && board[i][2] === player) return true;
        if (board[0][i] === player && board[1][i] === player && board[2][i] === player) return true;
    }
    // Check diagonals for a win
    if ((board[0][0] === player && board[1][1] === player && board[2][2] === player) ||
        (board[0][2] === player && board[1][1] === player && board[2][0] === player)) return true;
    return false;
}

function rotatedDigits(n) {
    let count = 0;
    for (let i = 1; i <= n; i++) {
        // Check if the rotated number is valid and different from the original number
        let rotated = rotateNumber(i);
        if (rotated !== -1 && rotated !== i) {
            count++;
        }
    }
    return count;
}

function rotateNumber(num) {
    let rotated = '';
    let isValid = true;
    while (num > 0) {
        let digit = num % 10;
        // Rotate the digit by 180 degrees
        let rotatedDigit = getRotatedDigit(digit);
        if (rotatedDigit === -1) {
            isValid = false;
            break;
        }
        rotated = rotatedDigit + rotated;
        num = Math.floor(num / 10);
    }
    return isValid ? parseInt(rotated) : -1;
}

function getRotatedDigit(digit) {
    // Define the mapping of digits after rotation
    let mapping = {
        '0': '0',
        '1': '1',
        '8': '8',
        '2': '5',
        '5': '2',
        '6': '9',
        '9': '6'
    };
    return mapping[digit] ? mapping[digit] : -1;
}

function findCheapestPrice(n, flights, src, dst, k) {
    const graph = {};
    for (let i = 0; i < n; i++) {
        graph[i] = [];
    }
    for (const [from, to, price] of flights) {
        graph[from].push([to, price]);
    }
    const queue = [[src, 0, k + 1]]; // city, price, stops
    const prices = new Array(n).fill(Infinity);
    prices[src] = 0;
    while (queue.length) {
        const [city, price, stops] = queue.shift(); // current city, current price, remaining stops
        // if we've reached the destination, update the price if it's cheaper
        if (city === dst) {
            prices[dst] = Math.min(prices[dst], price);
        }
        // if we have no more stops, skip this city
        if (stops === 0) {
            continue;
        }
        // explore all neighboring cities
        for (const [neighbor, neighborPrice] of graph[city]) {
            // if the new price is cheaper, update the price and add it to the queue
            if (price + neighborPrice < prices[neighbor]) {
                prices[neighbor] = price + neighborPrice;
                queue.push([neighbor, price + neighborPrice, stops - 1]);
            }
        }
    }
    // if we've reached the destination, return the price; otherwise, return -1
    return prices[dst] === Infinity ? -1 : prices[dst];
}

function allPathsSourceTarget(graph) {
    const result = [];
    function dfs(currentNode, path) {
        // add current node to the path
        path.push(currentNode);
        // if current node is the last node, add path to result
        if (currentNode === graph.length - 1) result.push([...path]);
        else {
            // for each neighbor of the current node, continue dfs
            for (const neighbor of graph[currentNode]) dfs(neighbor, path);
        }
        // backtrack by removing the current node from the path
        path.pop();
    }
    dfs(0, []);
    return result;
}

function bestRotation(nums) {
    let n = nums.length;
    let maxScore = 0;
    let result = 0;
    for (let k = 0; k < n; k++) {
        let score = 0;
        // calculate score for each rotation
        for (let i = 0; i < n; i++) {
            if (nums[(i + k) % n] <= i) score++;
        }
        // update max score and result if current score is higher
        if (score > maxScore) {
            maxScore = score;
            result = k;
        } else if (score === maxScore) {
            // if scores are equal, choose the smaller k
            result = Math.min(result, k);
        }
    }
    return result;
}

function uniqueMorseRepresentations(words) {
    const morseCode = [".-","-...","-.-.","-..",".","..-.","--.","....","..",".---","-.-",".-..","--","-.","---",".--.","--.-",".-.","...","-","..-","...-",".--","-..-","-.--","--.."];
    const transformations = new Set();
    for (let word of words) {
        let transformation = ''; // initialize an empty string to store the morse code transformation of the current word
        for (let char of word) {
            transformation += morseCode[char.charCodeAt(0) - 97]; // convert each character to its morse code equivalent
        }
        transformations.add(transformation); // add the transformation to the set
    }
    return transformations.size; // return the number of unique transformations
}

function champagneTower(poured, query_row, query_glass) {
    let champagne = new Array(query_row + 1).fill(0).map(() => new Array(query_row + 1).fill(0));
    champagne[0][0] = poured; // initialize the top glass with the poured champagne
    for (let i = 0; i < query_row; i++) { 
        // for each row, calculate the excess champagne and distribute it to the next row
        for (let j = 0; j <= i; j++) { 
            if (champagne[i][j] > 1) { 
                // if the current glass has more than 1 cup of champagne, calculate the excess
                let excess = (champagne[i][j] - 1) / 2; 
                champagne[i + 1][j] += excess; // distribute the excess to the left glass in the next row
                champagne[i + 1][j + 1] += excess; // distribute the excess to the right glass in the next row
                champagne[i][j] = 1; // reset the current glass to 1 cup
            }
        }
    }
    return Math.min(1, champagne[query_row][query_glass]); // return the amount of champagne in the query glass, capped at 1 cup
}

function numberOfLines(widths, s) {
    let lines = 1;
    let width = 0;
    for (let i = 0; i < s.length; i++) {
        let charWidth = widths[s.charCodeAt(i) - 97]; // get the width of the current character
        if (width + charWidth > 100) { // if adding the current character exceeds 100 pixels
            lines++; // start a new line
            width = 0; // reset the width
        }
        width += charWidth; // add the width of the current character
    }
    return [lines, width];
}

function maxIncreaseKeepingSkyline(grid) {
    var n = grid.length;
    var rowMax = new Array(n).fill(0);
    var colMax = new Array(n).fill(0);
    for (var i = 0; i < n; i++) {
        for (var j = 0; j < n; j++) {
            rowMax[i] = Math.max(rowMax[i], grid[i][j]); // find max height in each row
            colMax[j] = Math.max(colMax[j], grid[i][j]); // find max height in each column
        }
    }
    var increase = 0;
    for (var i = 0; i < n; i++) {
        for (var j = 0; j < n; j++) {
            increase += Math.min(rowMax[i], colMax[j]) - grid[i][j]; // calculate increase for each building
        }
    }
    return increase;
}

function xorGame(nums) {
    let xor = 0;
    // calculate the initial XOR of all elements in the array
    for (let num of nums) {
        xor ^= num;
    }
    // if the initial XOR is 0, Alice wins
    if (xor === 0) return true;
    // if the length of the array is even, Alice wins
    // because no matter what Alice does, Bob will always be the one to make the XOR 0
    if (nums.length % 2 === 0) return true;
    // if the length of the array is odd, Alice loses
    // because Alice will always be the one to make the XOR 0
    return false;
}

function splitArraySameAverage(nums) {
    let sum = 0;
    for (let num of nums) sum += num; // calculate the total sum of the array
    let n = nums.length;
    for (let i = 1; i <= n / 2; i++) { // try all possible sizes for the first subset
        if (sum * i % n !== 0) continue; // if the sum of the first subset is not an integer, skip
        let target = sum * i / n; // calculate the target sum for the first subset
        let dp = new Array(target + 1).fill(0); // initialize a dynamic programming array
        dp[0] = 1; // the sum 0 can be achieved with an empty subset
        for (let num of nums) { // try to add each number to the subset
            for (let j = target; j >= num; j--) { // update the dynamic programming array
                dp[j] = dp[j] || dp[j - num];
            }
        }
        if (dp[target] && i !== n - i) return true; // if the target sum can be achieved and the subset is not empty and not the whole array, return true
    }
    return false;
}

function minSwap(nums1, nums2) {
  const n = nums1.length;
  let swap = 1, notSwap = 0;
  for (let i = 1; i < n; i++) {
    let newSwap = Infinity, newNotSwap = Infinity;
    if (nums1[i] > nums1[i-1] && nums2[i] > nums2[i-1]) {
      newNotSwap = Math.min(newNotSwap, notSwap);
      newSwap = Math.min(newSwap, swap + 1);
    }
    if (nums1[i] > nums2[i-1] && nums2[i] > nums1[i-1]) {
      newSwap = Math.min(newSwap, notSwap + 1);
      newNotSwap = Math.min(newNotSwap, swap);
    }
    swap = newSwap;
    notSwap = newNotSwap;
  }
  return Math.min(swap, notSwap);
}

function eventualSafeNodes(graph) {
    const n = graph.length;
    const color = new Array(n).fill(0); // 0 - not visited, 1 - visiting, 2 - safe
    const result = [];

    function dfs(node) {
        // if we've already determined this node is safe or not safe, return immediately
        if (color[node] > 0) return color[node] === 2;

        // mark this node as visiting
        color[node] = 1;

        // if we find a cycle, this node is not safe
        for (const neighbor of graph[node]) {
            // if the neighbor is visiting and we're still visiting this node, we have a cycle
            if (!dfs(neighbor)) return false;
        }

        // if we've visited all neighbors and haven't found a cycle, this node is safe
        color[node] = 2;
        return true;
    }

    // perform dfs on all nodes
    for (let i = 0; i < n; i++) {
        // if this node is safe, add it to the result
        if (dfs(i)) result.push(i);
    }

    return result;
}

function hitBricks(grid, hits) {
  const R = grid.length, C = grid[0].length;
  const gridCopy = grid.map(row => row.slice());
  for (const [r, c] of hits) gridCopy[r][c] = 0;

  const size = R * C + 1;
  const parent = Array.from({length: size}, (_, i) => i);
  const rank = new Array(size).fill(0);
  const sz = new Array(size).fill(1);
  function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
  function union(a, b) {
    const ra = find(a), rb = find(b);
    if (ra === rb) return;
    if (rank[ra] < rank[rb]) { parent[ra] = rb; sz[rb] += sz[ra]; }
    else if (rank[ra] > rank[rb]) { parent[rb] = ra; sz[ra] += sz[rb]; }
    else { parent[rb] = ra; sz[ra] += sz[rb]; rank[ra]++; }
  }
  const roof = R * C;
  const idx = (r, c) => r * C + c;
  for (let c = 0; c < C; c++) if (gridCopy[0][c] === 1) union(idx(0, c), roof);
  for (let r = 0; r < R; r++) {
    for (let c = 0; c < C; c++) {
      if (gridCopy[r][c] === 1) {
        if (r > 0 && gridCopy[r - 1][c] === 1) union(idx(r, c), idx(r - 1, c));
        if (c > 0 && gridCopy[r][c - 1] === 1) union(idx(r, c), idx(r, c - 1));
      }
    }
  }
  const result = new Array(hits.length).fill(0);
  for (let i = hits.length - 1; i >= 0; i--) {
    const [r, c] = hits[i];
    if (grid[r][c] === 0) continue;
    const before = sz[find(roof)];
    gridCopy[r][c] = 1;
    if (r === 0) union(idx(r, c), roof);
    if (r > 0 && gridCopy[r - 1][c] === 1) union(idx(r, c), idx(r - 1, c));
    if (r < R - 1 && gridCopy[r + 1][c] === 1) union(idx(r, c), idx(r + 1, c));
    if (c > 0 && gridCopy[r][c - 1] === 1) union(idx(r, c), idx(r, c - 1));
    if (c < C - 1 && gridCopy[r][c + 1] === 1) union(idx(r, c), idx(r, c + 1));
    const after = sz[find(roof)];
    result[i] = Math.max(0, after - before - 1);
  }
  return result;
}

function soupServings(n) {
    n = Math.ceil(n / 25); // 
    if (n >= 179) return 1; // 
    let memo = new Map(); // 
    function dfs(a, b) {
        if (memo.has(`${a},${b}`)) return memo.get(`${a},${b}`); // 
        if (a <= 0 && b > 0) return 1; // 
        if (a <= 0 && b <= 0) return 0.5; // 
        if (a > 0 && b <= 0) return 0; // 
        let res = 0.25 * (dfs(a - 4, b) + dfs(a - 3, b - 1) + dfs(a - 2, b - 2) + dfs(a - 1, b - 3)); // 
        memo.set(`${a},${b}`, res); // 
        return res;
    }
    return dfs(n, n); // 
}

function subdomainVisits(cpdomains) {
    let domainCount = {};
    let result = [];

    // Iterate over each count-paired domain
    for (let i = 0; i < cpdomains.length; i++) {
        let [count, domain] = cpdomains[i].split(' ');
        let subdomains = domain.split('.');

        // Count visits for each subdomain
        for (let j = 0; j < subdomains.length; j++) {
            let subdomain = subdomains.slice(j).join('.');
            // Update count for the subdomain in the hash table
            domainCount[subdomain] = (domainCount[subdomain] || 0) + parseInt(count);
        }
    }

    // Create the result array from the hash table
    for (let domain in domainCount) {
        // Construct the count-paired domain string
        result.push(domainCount[domain] + ' ' + domain);
    }

    return result;
}

function expressiveWords(s, words) {
    let count = 0;
    for (let word of words) {
        let i = 0, j = 0;
        while (i < s.length && j < word.length) {
            // if current characters do not match, the word is not stretchy
            if (s[i] !== word[j]) break;
            // count consecutive occurrences of the current character in s and word
            let countS = 0, countWord = 0;
            let charS = s[i], charWord = word[j];
            while (i < s.length && s[i] === charS) { countS++; i++; }
            while (j < word.length && word[j] === charWord) { countWord++; j++; }
            // if the count of the character in word is more than in s, or 
            // if the count of the character in s is less than 3 and not equal to the count in word, 
            // the word is not stretchy
            if (countWord > countS || (countS < 3 && countS !== countWord)) break;
        }
        // if we have processed all characters in both s and word, the word is stretchy
        if (i === s.length && j === word.length) count++;
    }
    return count;
}

function largestTriangleArea(points) {
    let maxArea = 0;
    // calculate area for all possible combinations of three points
    for (let i = 0; i < points.length; i++) {
        for (let j = i + 1; j < points.length; j++) {
            for (let k = j + 1; k < points.length; k++) {
                // calculate area using the Shoelace formula
                let area = Math.abs((points[i][0] * (points[j][1] - points[k][1]) + 
                                    points[j][0] * (points[k][1] - points[i][1]) + 
                                    points[k][0] * (points[i][1] - points[j][1])) / 2);
                maxArea = Math.max(maxArea, area);
            }
        }
    }
    return maxArea;
}

function pruneTree(root) {
    // if the tree is empty, return null
    if (!root) return null;

    // recursively prune the left and right subtrees
    root.left = pruneTree(root.left);
    root.right = pruneTree(root.right);

    // if the current node's value is 0 and it has no children, return null to prune it
    if (root.val === 0 && !root.left && !root.right) return null;

    // otherwise, return the current node
    return root;
}

function numComponents(head, nums) {
    let numSet = new Set(nums); // create a set for O(1) lookup
    let count = 0; // count of connected components
    let inComponent = false; // flag to track if we are in a connected component
    while (head) { 
        // if current node's value is in the set and we are not in a component, increment count and set flag
        if (numSet.has(head.val) && !inComponent) {
            count++;
            inComponent = true;
        }
        // if current node's value is not in the set, reset flag
        if (!numSet.has(head.val)) {
            inComponent = false;
        }
        head = head.next; // move to the next node
    }
    return count;
}

function mostCommonWord(paragraph, banned) {
    // convert paragraph to lowercase and replace non-alphanumeric characters with spaces
    let words = paragraph.toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/);
    // create a hash table to store the frequency of each word
    let wordCount = {};
    for (let word of words) {
        // skip empty strings
        if (word) {
            // increment the count of the current word
            wordCount[word] = (wordCount[word] || 0) + 1;
        }
    }
    // create a set of banned words for efficient lookup
    let bannedSet = new Set(banned.map(word => word.toLowerCase()));
    // find the most frequent word that is not banned
    let maxCount = 0, result = '';
    for (let word in wordCount) {
        // check if the word is not banned and has a higher count than the current max
        if (!bannedSet.has(word) && wordCount[word] > maxCount) {
            // update the max count and the result
            maxCount = wordCount[word];
            result = word;
        }
    }
    return result;
}

function numBusesToDestination(routes, source, target) {
    if (source === target) return 0;
    const busStops = {};
    for (let i = 0; i < routes.length; i++) {
        for (let stop of routes[i]) {
            if (!busStops[stop]) busStops[stop] = [];
            busStops[stop].push(i);
        }
    }
    const queue = [[source, 0]];
    const visitedStops = new Set([source]);
    const visitedBuses = new Set();
    while (queue.length) {
        const [stop, busCount] = queue.shift();
        // If the current stop is the target, return the bus count
        if (stop === target) return busCount;
        for (let bus of busStops[stop] || []) {
            // If we've already visited this bus, skip it to avoid infinite loops
            if (visitedBuses.has(bus)) continue;
            visitedBuses.add(bus);
            for (let nextStop of routes[bus]) {
                // If we've already visited this stop, skip it to avoid infinite loops
                if (visitedStops.has(nextStop)) continue;
                visitedStops.add(nextStop);
                queue.push([nextStop, busCount + 1]);
            }
        }
    }
    // If we've reached this point, it's not possible to reach the target
    return -1;
}

function ambiguousCoordinates(s) {
    s = s.substring(1, s.length - 1);
    let result = [];
    for (let i = 1; i < s.length; i++) {
        let left = s.substring(0, i);
        let right = s.substring(i);
        for (let leftNum of generateNumbers(left)) {
            for (let rightNum of generateNumbers(right)) {
                result.push("(" + leftNum + ", " + rightNum + ")");
            }
        }
    }
    return result;
}

function generateNumbers(s) {
    let result = [];
    if (s.length === 1) {
        result.push(s);
    } else if (s[0] !== '0') {
        // no leading zero: whole integer is valid
        result.push(s);
        for (let i = 1; i < s.length; i++) {
            // decimal part must not end in '0'
            if (s[s.length - 1] !== '0') {
                result.push(s.substring(0, i) + '.' + s.substring(i));
            }
        }
    } else {
        // s[0] === '0' and length > 1: whole integer form is invalid (leading zero).
        // Only "0.xxx" can be valid, and only if xxx doesn't end in '0'.
        if (s[s.length - 1] !== '0') {
            result.push('0.' + s.substring(1));
        }
    }
    return result;
}

function largestSumOfAverages(nums, k) {
    const n = nums.length;
    const prefixSum = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }
    const dp = new Array(n).fill(0).map(() => new Array(k + 1).fill(0));
    for (let i = 0; i < n; i++) {
        dp[i][1] = (prefixSum[i + 1] / (i + 1)); // calculate the average for the first partition
    }
    for (let j = 2; j <= k; j++) {
        for (let i = j - 1; i < n; i++) {
            for (let x = j - 2; x < i; x++) {
                dp[i][j] = Math.max(dp[i][j], dp[x][j - 1] + (prefixSum[i + 1] - prefixSum[x + 1]) / (i - x)); // try all possible partitions
            }
        }
    }
    return dp[n - 1][k];
}

function racecar(target) {
    let queue = [[0, 1, 0]]; // position, speed, steps
    let visited = new Set();
    while (queue.length > 0) {
        let [position, speed, steps] = queue.shift();
        // if we have reached the target, return the steps
        if (position === target) return steps;
        // mark the current state as visited
        let state = position + ',' + speed;
        if (visited.has(state)) continue;
        visited.add(state);
        // accelerate
        queue.push([position + speed, speed * 2, steps + 1]);
        // reverse
        queue.push([position, -1, steps + 1]);
    }
}

function flipgame(fronts, backs) {
    let same = new Set(); // store numbers that are the same on both sides
    for (let i = 0; i < fronts.length; i++) {
        // if the number on the front is the same as the number on the back, add it to the set
        if (fronts[i] === backs[i]) same.add(fronts[i]);
    }
    let result = Infinity; // initialize result to positive infinity
    for (let i = 0; i < fronts.length; i++) {
        // if the number on the front is not in the set of same numbers, update the result
        if (!same.has(fronts[i])) result = Math.min(result, fronts[i]);
        // if the number on the back is not in the set of same numbers, update the result
        if (!same.has(backs[i])) result = Math.min(result, backs[i]);
    }
    // if the result is still infinity, return 0, otherwise return the result
    return result === Infinity ? 0 : result;
}

function minimumLengthEncoding(words) {
    let good = new Set(words);
    for (let word of words) {
        // remove all suffixes of the current word from the set
        for (let k = 1; k < word.length; k++) {
            good.delete(word.slice(k));
        }
    }
    let length = 0;
    // calculate the total length of the remaining words plus the '#' character
    for (let word of good) {
        length += word.length + 1;
    }
    return length;
}

function toGoatLatin(sentence) {
    let words = sentence.split(' ');
    for (let i = 0; i < words.length; i++) {
        // check if the word starts with a vowel
        if ('aeiouAEIOU'.includes(words[i][0])) {
            words[i] += 'ma';
        } else {
            // move the first consonant to the end and add 'ma'
            words[i] = words[i].slice(1) + words[i][0] + 'ma';
        }
        // add 'a's to the end of the word based on its position
        words[i] += 'a'.repeat(i + 1);
    }
    return words.join(' ');
}

function numFactoredBinaryTrees(arr) {
    const MOD = 1e9 + 7;
    arr.sort((a, b) => a - b);
    const dp = new Map();
    for (let i = 0; i < arr.length; i++) {
        dp.set(arr[i], 1); // base case: single node tree
    }
    for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < i; j++) {
            // check if arr[i] can be factored into arr[j] and another number
            if (arr[i] % arr[j] === 0) {
                const otherFactor = arr[i] / arr[j];
                if (dp.has(otherFactor)) {
                    // update dp[arr[i]] with the number of possible trees
                    dp.set(arr[i], (dp.get(arr[i]) + dp.get(arr[j]) * dp.get(otherFactor)) % MOD);
                }
            }
        }
    }
    let totalTrees = 0;
    for (let count of dp.values()) {
        totalTrees = (totalTrees + count) % MOD;
    }
    return totalTrees;
}

function numFriendRequests(ages) {
  let count = 0;
  for (let i = 0; i < ages.length; i++) {
    for (let j = 0; j < ages.length; j++) {
      if (i === j) continue;
      const a = ages[i], b = ages[j];
      if (b <= 0.5 * a + 7) continue;
      if (b > a) continue;
      if (b > 100 && a < 100) continue;
      count++;
    }
  }
  return count;
}

function shortestToChar(s, c) {
    var result = new Array(s.length);
    var indices = [];
    // find all indices of character c in string s
    for (var i = 0; i < s.length; i++) {
        if (s[i] === c) {
            indices.push(i);
        }
    }
    // calculate the distance from each index to the closest occurrence of character c
    for (var i = 0; i < s.length; i++) {
        var minDistance = Infinity;
        // find the minimum distance to the closest occurrence of character c
        for (var j = 0; j < indices.length; j++) {
            var distance = Math.abs(i - indices[j]);
            if (distance < minDistance) {
                minDistance = distance;
            }
        }
        result[i] = minDistance;
    }
    return result;
}

function maxProfitAssignment(difficulty, profit, worker) {
    let jobDifficultyAndProfit = difficulty.map((diff, index) => [diff, profit[index]]);
    jobDifficultyAndProfit.sort((a, b) => a[0] - b[0]);
    let maxProfitSoFar = new Array(jobDifficultyAndProfit.length);
    maxProfitSoFar[0] = jobDifficultyAndProfit[0][1];
    for (let i = 1; i < jobDifficultyAndProfit.length; i++) {
        // update maxProfitSoFar array to keep track of the maximum profit that can be achieved for each job
        maxProfitSoFar[i] = Math.max(maxProfitSoFar[i - 1], jobDifficultyAndProfit[i][1]);
    }
    let totalMaxProfit = 0;
    for (let i = 0; i < worker.length; i++) {
        // use binary search to find the most profitable job that the current worker can do
        let left = 0, right = jobDifficultyAndProfit.length - 1;
        while (left <= right) {
            let mid = Math.floor((left + right) / 2);
            if (jobDifficultyAndProfit[mid][0] <= worker[i]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        // if the worker can do at least one job, add the maximum profit that can be achieved to the totalMaxProfit
        if (right >= 0) {
            totalMaxProfit += maxProfitSoFar[right];
        }
    }
    return totalMaxProfit;
}

function countUniqueChars(s) {
  let result = 0;
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      const substring = s.slice(i, j);
      const freq = {};
      for (const c of substring) freq[c] = (freq[c] || 0) + 1;
      let uniqueCount = 0;
      for (const c in freq) if (freq[c] === 1) uniqueCount++;
      result += uniqueCount;
    }
  }
  return result;
}

function consecutiveNumbersSum(n) {
  let count = 0;
  for (let start = 1; start <= n; start++) {
    // calculate the sum of consecutive numbers starting from 'start'
    let sum = 0;
    for (let end = start; end <= n; end++) {
      sum += end;
      // check if the sum equals 'n' and increment the count if true
      if (sum === n) count++;
      // break the inner loop if the sum exceeds 'n'
      if (sum > n) break;
    }
  }
  return count;
}

function flipAndInvertImage(image) {
    for (let i = 0; i < image.length; i++) {
        // Reverse each row in the image
        image[i] = image[i].reverse();
        // Invert the image by changing 0s to 1s and 1s to 0s
        for (let j = 0; j < image[i].length; j++) {
            image[i][j] = 1 - image[i][j];
        }
    }
    return image;
}

function largestIsland(grid) {
    const n = grid.length;
    const directions = [[0, 1], [0, -1], [1, 0], [-1, 0]];
    let maxArea = 0;
    let index = 2;
    const area = {};
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                area[index] = dfs(grid, i, j, index, directions);
                maxArea = Math.max(maxArea, area[index]);
                index++;
            }
        }
    }
    if (index === 2) return 1;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 0) {
                let currentArea = 1;
                const seen = new Set();
                for (const direction of directions) {
                    const x = i + direction[0];
                    const y = j + direction[1];
                    if (x >= 0 && x < n && y >= 0 && y < n && grid[x][y] > 1 && !seen.has(grid[x][y])) {
                        seen.add(grid[x][y]);
                        currentArea += area[grid[x][y]];
                    }
                }
                maxArea = Math.max(maxArea, currentArea);
            }
        }
    }
    return maxArea;
}
function dfs(grid, i, j, index, directions) {
    const n = grid.length;
    if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] !== 1) return 0;
    grid[i][j] = index;
    let area = 1;
    for (const direction of directions) {
        area += dfs(grid, i + direction[0], j + direction[1], index, directions);
    }
    return area;
}

function largeGroupPositions(s) {
    var result = [];
    var groupSize = 1;
    // iterate over string to track consecutive groups of the same character
    for (var i = 1; i < s.length; i++) {
        if (s[i] === s[i - 1]) {
            groupSize++;
        } else {
            // check if previous group is large and add its interval to result
            if (groupSize >= 3) {
                result.push([i - groupSize, i - 1]);
            }
            groupSize = 1;
        }
    }
    // check the last group
    if (groupSize >= 3) {
        result.push([s.length - groupSize, s.length - 1]);
    }
    return result;
}

function findAndReplace(s, indices, sources, targets) {
    let result = s.split('');
    const order = indices.map((_, i) => i).sort((a, b) => indices[b] - indices[a]);
    for (const i of order) {
        if (s.substring(indices[i], indices[i] + sources[i].length) === sources[i]) {
            result.splice(indices[i], sources[i].length, ...targets[i].split(''));
        }
    }
    return result.join('');
}

function maskPII(s) {
    // Check if the string contains '@' to determine if it's an email or a phone number
    if (s.indexOf('@') !== -1) {
        // Split the email into local and domain parts
        var parts = s.split('@');
        // Convert the local and domain parts to lowercase
        var local = parts[0].toLowerCase();
        var domain = parts[1].toLowerCase();
        // Mask the local part by replacing the middle with 5 asterisks
        var maskedLocal = local[0] + '*****' + local[local.length - 1];
        // Return the masked email
        return maskedLocal + '@' + domain;
    } else {
        // Remove all non-digit characters from the phone number
        var digits = s.replace(/[^0-9]/g, '');
        // Mask the phone number by replacing all but the last 4 digits with '***-***-'
        var maskedDigits = '***-***-' + digits.slice(-4);
        // Return the masked phone number
        return maskedDigits;
    }
}

function isRectangleOverlap(rec1, rec2) {
    // check if the x-coordinate of the top-right corner of rec1 is greater than the x-coordinate of the bottom-left corner of rec2
    // and the x-coordinate of the top-right corner of rec2 is greater than the x-coordinate of the bottom-left corner of rec1
    var xOverlap = rec1[2] > rec2[0] && rec2[2] > rec1[0];
    // check if the y-coordinate of the top-right corner of rec1 is greater than the y-coordinate of the bottom-left corner of rec2
    // and the y-coordinate of the top-right corner of rec2 is greater than the y-coordinate of the bottom-left corner of rec1
    var yOverlap = rec1[3] > rec2[1] && rec2[3] > rec1[1];
    // return true if both x and y overlaps are true, otherwise return false
    return xOverlap && yOverlap;
}

function pushDominoes(dominoes) {
    let n = dominoes.length;
    let forces = new Array(n).fill(0);
    let force = 0;
    // calculate forces from left to right
    for (let i = 0; i < n; i++) {
        if (dominoes[i] === 'R') force = n;
        else if (dominoes[i] === 'L') force = 0;
        else force = Math.max(force - 1, 0);
        forces[i] += force;
    }
    force = 0;
    // calculate forces from right to left
    for (let i = n - 1; i >= 0; i--) {
        if (dominoes[i] === 'L') force = n;
        else if (dominoes[i] === 'R') force = 0;
        else force = Math.max(force - 1, 0);
        forces[i] -= force;
    }
    let result = '';
    // construct the final state based on the forces
    for (let i = 0; i < n; i++) {
        if (forces[i] > 0) result += 'R';
        else if (forces[i] < 0) result += 'L';
        else result += '.';
    }
    return result;
}

function new21Game(n, k, maxPts) {
  if (k === 0 || n >= k + maxPts - 1) return 1.0;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;
  let wSum = 1, result = 0;
  for (let i = 1; i <= n; i++) {
    dp[i] = wSum / maxPts;
    if (i < k) wSum += dp[i]; else result += dp[i];
    if (i - maxPts >= 0) wSum -= dp[i - maxPts];
  }
  return result;
}

function sumOfDistancesInTree(n, edges) {
    let graph = Array.from({length: n}, () => []);
    for (let [u, v] of edges) { graph[u].push(v); graph[v].push(u); }
    let count = Array(n).fill(1);
    let res = Array(n).fill(0);
    function dfs(node, parent, depth) {
        res[0] += depth;
        for (let child of graph[node]) {
            if (child !== parent) {
                dfs(child, node, depth + 1);
                count[node] += count[child];
            }
        }
    }
    function dfs2(node, parent) {
        for (let child of graph[node]) {
            if (child !== parent) {
                res[child] = res[node] + n - 2 * count[child];
                dfs2(child, node);
            }
        }
    }
    dfs(0, -1, 0);
    dfs2(0, -1);
    return res;
}

function largestOverlap(img1, img2) {
    var n = img1.length;
    var maxOverlap = 0;
    // iterate over all possible translations
    for (var dx = -n + 1; dx < n; dx++) {
        for (var dy = -n + 1; dy < n; dy++) {
            var overlap = 0;
            // count the overlap for the current translation
            for (var x = 0; x < n; x++) {
                for (var y = 0; y < n; y++) {
                    if (x + dx >= 0 && x + dx < n && y + dy >= 0 && y + dy < n) {
                        overlap += img1[x][y] & img2[x + dx][y + dy];
                    }
                }
            }
            // update the maximum overlap
            maxOverlap = Math.max(maxOverlap, overlap);
        }
    }
    return maxOverlap;
}

function numSimilarGroups(strs) {
    const parent = {};
    for (let i = 0; i < strs.length; i++) {
        parent[strs[i]] = strs[i];
    }

    function find(x) {
        // if x is not the parent of itself, find its parent and update x's parent
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    function union(x, y) {
        const rootX = find(x);
        const rootY = find(y);
        // if x and y are not in the same group, merge them
        if (rootX !== rootY) {
            parent[rootX] = rootY;
        }
    }

    function isSimilar(x, y) {
        let diff = 0;
        for (let i = 0; i < x.length; i++) {
            // count the number of different characters at the same position
            if (x[i] !== y[i]) {
                diff++;
            }
            // if there are more than 2 different characters, x and y are not similar
            if (diff > 2) {
                return false;
            }
        }
        // if there are 0 or 2 different characters, x and y are similar
        return diff === 0 || diff === 2;
    }

    for (let i = 0; i < strs.length; i++) {
        for (let j = i + 1; j < strs.length; j++) {
            // if two strings are similar, merge them into the same group
            if (isSimilar(strs[i], strs[j])) {
                union(strs[i], strs[j]);
            }
        }
    }

    const groups = new Set();
    for (let i = 0; i < strs.length; i++) {
        // add the parent of each string to the set of groups
        groups.add(find(strs[i]));
    }
    return groups.size;
}

function numMagicSquaresInside(grid) {
    let count = 0;
    // check all possible 3x3 subgrids
    for (let i = 0; i <= grid.length - 3; i++) {
        for (let j = 0; j <= grid[0].length - 3; j++) {
            let subgrid = [];
            for (let k = 0; k < 3; k++) {
                subgrid.push(grid[i + k].slice(j, j + 3));
            }
            // check if the subgrid is a magic square
            if (isMagicSquare(subgrid)) {
                count++;
            }
        }
    }
    return count;
}

function isMagicSquare(grid) {
    let expectedSum = grid[0][0] + grid[0][1] + grid[0][2];
    // check rows
    for (let i = 0; i < 3; i++) {
        let sum = 0;
        for (let j = 0; j < 3; j++) {
            sum += grid[i][j];
        }
        if (sum !== expectedSum) {
            return false;
        }
    }
    // check columns
    for (let i = 0; i < 3; i++) {
        let sum = 0;
        for (let j = 0; j < 3; j++) {
            sum += grid[j][i];
        }
        if (sum !== expectedSum) {
            return false;
        }
    }
    // check diagonals
    let diagonal1 = grid[0][0] + grid[1][1] + grid[2][2];
    let diagonal2 = grid[0][2] + grid[1][1] + grid[2][0];
    if (diagonal1 !== expectedSum || diagonal2 !== expectedSum) {
        return false;
    }
    // check if all numbers are distinct and between 1 and 9
    let numbers = [];
    for (let i = 0; i < 3; i++) {
        for (let j = 0; j < 3; j++) {
            numbers.push(grid[i][j]);
        }
    }
    numbers.sort((a, b) => a - b);
    for (let i = 0; i < 9; i++) {
        if (numbers[i] !== i + 1) {
            return false;
        }
    }
    return true;
}

function canVisitAllRooms(rooms) {
    let visited = new Set();
    visited.add(0);
    let keys = new Set(rooms[0]);
    while (keys.size > 0) {
        // get all new rooms that can be visited with the current keys
        let newKeys = new Set();
        for (let key of keys) {
            if (!visited.has(key)) {
                visited.add(key);
                // add all new keys found in the newly visited room
                for (let newKey of rooms[key]) {
                    newKeys.add(newKey);
                }
            }
        }
        // if no new rooms were visited, break the loop
        if (newKeys.size === 0) break;
        keys = newKeys;
    }
    // return true if all rooms were visited, false otherwise
    return visited.size === rooms.length;
}

function splitIntoFibonacci(num) {
    var result = [];
    function backtrack(start, path) {
        // if we have processed the entire string and there are at least 3 numbers in the path, return true
        if (start === num.length && path.length >= 3) return true;
        for (var i = 1; i <= num.length - start; i++) {
            var substr = num.substring(start, start + i);
            // if the substring starts with 0 and has more than one digit, skip it
            if (substr.length > 1 && substr[0] === '0') continue;
            var currNum = parseInt(substr);
            // if the path is empty or has less than 2 numbers, add the current number to the path
            if (path.length < 2) {
                path.push(currNum);
                // recursively call backtrack with the updated start index and path
                if (backtrack(start + i, path)) {
                    result = path.slice();
                    return true;
                }
                path.pop();
            } else {
                // if the current number is equal to the sum of the last two numbers in the path, add it to the path
                if (currNum === path[path.length - 1] + path[path.length - 2]) {
                    path.push(currNum);
                    // recursively call backtrack with the updated start index and path
                    if (backtrack(start + i, path)) {
                        result = path.slice();
                        return true;
                    }
                    path.pop();
                }
            }
        }
        return false;
    }
    backtrack(0, []);
    return result;
}

function findPeakElement(arr) {
    let left = 0;
    let right = arr.length - 1;
    while (left < right) { 
        // calculate mid index and compare middle elements to determine which half to discard
        let mid = Math.floor((left + right) / 2);
        if (arr[mid] < arr[mid + 1]) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

// TIME: O(log(n)) SPACE: O(1)

function shiftingLetters(s, shifts) {
    const n = s.length;
    const arr = s.split('');
    let suffix = 0;
    for (let i = n - 1; i >= 0; i--) {
        suffix = (suffix + shifts[i]) % 26;
        const code = ((arr[i].charCodeAt(0) - 97 + suffix) % 26) + 97;
        arr[i] = String.fromCharCode(code);
    }
    return arr.join('');
}

function longestMountain(arr) {
    let maxLength = 0;
    for (let i = 1; i < arr.length - 1; i++) {
        // check if current element is a peak
        if (arr[i - 1] < arr[i] && arr[i] > arr[i + 1]) {
            let left = i - 1;
            let right = i + 1;
            // expand to the left
            while (left >= 0 && arr[left] < arr[left + 1]) {
                left--;
            }
            // expand to the right
            while (right < arr.length && arr[right] < arr[right - 1]) {
                right++;
            }
            // update max length
            maxLength = Math.max(maxLength, right - left - 1);
        }
    }
    return maxLength;
}

function loudAndRich(richer, quiet) {
    var n = quiet.length;
    var graph = new Array(n).fill(0).map(() => new Array());
    var indegree = new Array(n).fill(0);
    for (var i = 0; i < richer.length; i++) {
        var u = richer[i][0], v = richer[i][1];
        graph[u].push(v);
        indegree[v]++;
    }
    var answer = new Array(n).fill(0).map((_, i) => i);
    var queue = [];
    for (var i = 0; i < n; i++) {
        if (indegree[i] === 0) queue.push(i);
    }
    while (queue.length > 0) {
        var u = queue.shift();
        // update answer for all neighbors of u if u is quieter
        for (var v of graph[u]) {
            if (quiet[answer[u]] < quiet[answer[v]]) answer[v] = answer[u];
            indegree[v]--;
            // add v to queue if all its incoming edges have been processed
            if (indegree[v] === 0) queue.push(v);
        }
    }
    return answer;
}

function backspaceCompare(s, t) {
    function processString(str) {
        let result = [];
        for (let char of str) {
            // if the character is a backspace and the result array is not empty, remove the last character from the result array
            if (char === '#' && result.length > 0) result.pop();
            // if the character is not a backspace, add it to the result array
            else if (char !== '#') result.push(char);
        }
        return result.join('');
    }
    // compare the processed strings
    return processString(s) === processString(t);
}

function rectangleArea(rectangles) {
  const MOD = 1000000007n;
  const xs = new Set();
  for (const [x1, , x2] of rectangles) { xs.add(x1); xs.add(x2); }
  const sortedXs = [...xs].sort((a, b) => a - b);
  let area = 0n;
  for (let i = 0; i < sortedXs.length - 1; i++) {
    const x1 = sortedXs[i], x2 = sortedXs[i + 1];
    const width = x2 - x1;
    if (width <= 0) continue;
    const intervals = [];
    for (const [rx1, ry1, rx2, ry2] of rectangles) {
      if (rx1 <= x1 && rx2 >= x2) intervals.push([ry1, ry2]);
    }
    intervals.sort((a, b) => a[0] - b[0]);
    let totalHeight = 0n;
    let curStart = null, curEnd = null;
    for (const [y1, y2] of intervals) {
      if (curEnd === null || y1 > curEnd) {
        if (curEnd !== null) totalHeight += BigInt(curEnd - curStart);
        curStart = y1; curEnd = y2;
      } else {
        curEnd = Math.max(curEnd, y2);
      }
    }
    if (curEnd !== null) totalHeight += BigInt(curEnd - curStart);
    area = (area + BigInt(width) * totalHeight) % MOD;
  }
  return Number(area);
}

function findSecretWord(wordlist, master, allowedGuesses) {
    // Create a copy of the wordlist to avoid modifying the original list
    let possibleWords = wordlist.slice();

    // Loop until we've made the maximum number of allowed guesses
    for (let i = 0; i < allowedGuesses; i++) {
        // Choose a random word from the possible words
        let guess = possibleWords[Math.floor(Math.random() * possibleWords.length)];

        // Get the number of matching characters
        let matches = master.guess(guess);

        // If we've found the secret word, return
        if (matches === 6) return;

        // Filter the possible words based on the number of matches
        possibleWords = possibleWords.filter(word => {
            // Count the number of matching characters between the guess and the word
            let matchCount = 0;
            for (let j = 0; j < 6; j++) {
                if (word[j] === guess[j]) matchCount++;
            }
            // If the number of matches is equal to the number of matches for the guess, keep the word
            return matchCount === matches;
        });
    }
}

function mirrorReflection(p, q) {
    function gcd(a, b) { return b === 0 ? a : gcd(b, a % b); }
    let g = gcd(p, q);
    p /= g; q /= g;
    if (p % 2 === 0) return 2;
    if (q % 2 === 0) return 0;
    return 1;
}

function primePalindrome(n) {
    // check if a number is a palindrome
    function isPalindrome(num) {
        return num.toString() === num.toString().split('').reverse().join('');
    }
    // check if a number is prime
    function isPrime(num) {
        // a prime number must be greater than 1
        if (num <= 1) return false;
        // check from 2 to sqrt(num)
        for (let i = 2, sqrt = Math.sqrt(num); i <= sqrt; i++) {
            // if num is divisible by any number between 2 and sqrt(num), it's not prime
            if (num % i === 0) return false;
        }
        return true;
    }
    // start checking from n
    while (true) {
        // check if the current number is a palindrome and prime
        if (isPalindrome(n) && isPrime(n)) return n;
        // if not, move to the next number
        n++;
    }
}

// TIME: O(n*sqrt(n)) SPACE: O(1)

function advantageCount(nums1, nums2) {
    nums1.sort((a, b) => a - b); // sort nums1 in ascending order
    var result = new Array(nums1.length); // initialize result array
    var left = 0, right = nums1.length - 1; // initialize two pointers
    for (var i = 0; i < nums2.length; i++) { // iterate through nums2
        var maxIndex = nums2.indexOf(Math.max(...nums2)); // find the index of the maximum element in nums2
        if (nums1[right] > nums2[maxIndex]) { // if the largest element in nums1 is greater than the current max in nums2
            result[maxIndex] = nums1[right--]; // assign it to the result array and decrement the right pointer
        } else { // otherwise
            result[maxIndex] = nums1[left++]; // assign the smallest element in nums1 to the result array and increment the left pointer
        }
        nums2[maxIndex] = -1; // mark the current max in nums2 as visited
    }
    return result;
}

function leafSimilar(root1, root2) {
    function dfs(node) {
        if (!node) return []; // base case: empty tree
        if (!node.left && !node.right) return [node.val]; // leaf node
        return dfs(node.left).concat(dfs(node.right)); // recursively traverse left and right subtrees
    }
    return dfs(root1).join(',') === dfs(root2).join(','); // compare leaf value sequences
}

function reorderedPowerOf2(n) {
  // convert the number to a string to easily access and count each digit
  let count = {};
  for (let char of n.toString()) {
    // count the occurrences of each digit in the number
    count[char] = (count[char] || 0) + 1;
  }

  // generate all powers of 2 from 0 to 31
  for (let i = 0; i <= 31; i++) {
    // convert the power of 2 to a string to compare with the original number
    let powerOf2 = Math.pow(2, i).toString();
    let powerOf2Count = {};
    for (let char of powerOf2) {
      // count the occurrences of each digit in the power of 2
      powerOf2Count[char] = (powerOf2Count[char] || 0) + 1;
    }
    // compare the counts of digits in the original number and the power of 2
    if (JSON.stringify(count) === JSON.stringify(powerOf2Count)) {
      // if the counts are equal, return true
      return true;
    }
  }
  // if no match is found, return false
  return false;
}

function subtreeWithAllDeepest(root) {
    let maxDepth = 0;
    let deepestNodes = [];
    let result = null;

    function dfs(node, depth) {
        // update maxDepth and deepestNodes if current node is deeper
        if (depth > maxDepth) {
            maxDepth = depth;
            deepestNodes = [node];
        } else if (depth === maxDepth) {
            deepestNodes.push(node);
        }

        // recursively traverse left and right subtrees
        if (node.left) dfs(node.left, depth + 1);
        if (node.right) dfs(node.right, depth + 1);
    }

    dfs(root, 0);

    function findLCA(node, depth) {
        // base case: if node is null, return null
        if (!node) return null;

        // if node is one of the deepest nodes, return the node
        if (deepestNodes.includes(node)) return node;

        // recursively traverse left and right subtrees
        let left = findLCA(node.left, depth + 1);
        let right = findLCA(node.right, depth + 1);

        // if both left and right subtrees contain deepest nodes, return the current node
        if (left && right) return node;

        // if only one subtree contains deepest nodes, return that subtree
        return left || right;
    }

    result = findLCA(root, 0);

    return result;
}

function binaryGap(n) {
    let binaryString = n.toString(2); // convert n to binary string
    let maxDistance = 0; 
    let lastOneIndex = -1; 
    for (let i = 0; i < binaryString.length; i++) { 
        // if current character is '1', update maxDistance if necessary
        if (binaryString[i] === '1') {
            if (lastOneIndex !== -1) maxDistance = Math.max(maxDistance, i - lastOneIndex);
            lastOneIndex = i;
        }
    }
    return maxDistance;
}

function lenLongestFibSubseq(arr) {
    let maxLength = 0;
    let numSet = new Set(arr);
    // iterate through all pairs of numbers in the array to find potential Fibonacci subsequences
    for (let i = 0; i < arr.length; i++) {
        for (let j = i + 1; j < arr.length; j++) {
            let a = arr[i], b = arr[j];
            let length = 2;
            // generate the Fibonacci sequence starting with a and b, and check if it exists in the array
            while (numSet.has(a + b)) {
                let temp = a;
                a = b;
                b = temp + b;
                length++;
            }
            // update the maximum length found
            maxLength = Math.max(maxLength, length);
        }
    }
    // return the maximum length found, or 0 if no Fibonacci subsequence exists
    return maxLength > 2 ? maxLength : 0;
}

function shortestSubarray(nums, k) {
  const n = nums.length;
  const prefixSum = new Array(n + 1).fill(0);
  for (let i = 0; i < n; i++) prefixSum[i + 1] = prefixSum[i] + nums[i];
  let result = n + 1;
  const deque = [];
  for (let i = 0; i <= n; i++) {
    while (deque.length > 0 && prefixSum[i] - prefixSum[deque[0]] >= k) {
      result = Math.min(result, i - deque.shift());
    }
    while (deque.length > 0 && prefixSum[i] <= prefixSum[deque[deque.length - 1]]) {
      deque.pop();
    }
    deque.push(i);
  }
  return result <= n ? result : -1;
}

function buddyStrings(s, goal) {
  if (s.length !== goal.length) return false;
  let diff = [];
  // iterate through the strings and find the different characters
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== goal[i]) diff.push(i);
  }
  // if there are no differences or more than 2 differences, return false
  if (diff.length === 0) {
    // if there are no differences, check if there are duplicate characters in s
    let charCount = {};
    for (let i = 0; i < s.length; i++) {
      if (charCount[s[i]]) charCount[s[i]]++;
      else charCount[s[i]] = 1;
    }
    for (let key in charCount) {
      if (charCount[key] > 1) return true;
    }
    return false;
  } else if (diff.length > 2) return false;
  // if there are exactly 2 differences, check if swapping them makes the strings equal
  else if (diff.length === 2) {
    // swap the characters at the different indices
    let sArr = s.split('');
    let temp = sArr[diff[0]];
    sArr[diff[0]] = sArr[diff[1]];
    sArr[diff[1]] = temp;
    // check if the strings are now equal
    return sArr.join('') === goal;
  }
}

function transpose(matrix) {
  const rows = matrix.length;
  const cols = matrix[0].length;
  const result = new Array(cols);
  // Initialize each row in the result array
  for (let i = 0; i < cols; i++) {
    result[i] = new Array(rows);
  }
  // Swap row and column indices to transpose the matrix
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      result[j][i] = matrix[i][j];
    }
  }
  return result;
}

function distanceK(root, target, k) {
    // Create a hash map to store the parent of each node
    const parentMap = {};
    function buildParentMap(node, parent) {
        if (node) {
            parentMap[node.val] = parent;
            buildParentMap(node.left, node);
            buildParentMap(node.right, node);
        }
    }
    buildParentMap(root, null);

    // Create a set to store the visited nodes
    const visited = new Set();
    const result = [];
    function dfs(node, distance) {
        // If the node is null or visited, return
        if (!node || visited.has(node.val)) return;
        // Mark the node as visited
        visited.add(node.val);
        // If the distance is equal to k, add the node's value to the result
        if (distance === k) result.push(node.val);
        // If the distance is less than k, continue the DFS
        if (distance < k) {
            dfs(node.left, distance + 1);
            dfs(node.right, distance + 1);
            dfs(parentMap[node.val], distance + 1);
        }
    }
    // Start the DFS from the target node
    dfs(target, 0);
    return result;
}

function maxDistToClosest(seats) {
    let maxDistance = 0;
    let left = -1;
    for (let i = 0; i < seats.length; i++) {
        if (seats[i] === 1) {
            if (left === -1) {
                // if this is the first person we've seen, the distance is the current index
                maxDistance = Math.max(maxDistance, i);
            } else {
                // if we've seen people before, the distance is the average of the distance to the left and right people
                maxDistance = Math.max(maxDistance, Math.floor((i - left) / 2));
            }
            left = i;
        }
    }
    // if the last seat is empty, the distance is the distance from the last person to the end
    maxDistance = Math.max(maxDistance, seats.length - 1 - left);
    return maxDistance;
}

function minRefuelStops(target, startFuel, stations) {
    let currentFuel = startFuel;
    let stops = 0;
    let previousStation = 0;
    let pq = [];
    for (let i = 0; i <= stations.length; i++) {
        let distance = i < stations.length ? stations[i][0] - previousStation : target - previousStation;
        // if the car can't reach the next station, try to refuel at the previous stations
        while (pq.length > 0 && currentFuel < distance) {
            currentFuel += -pq.shift();
            stops++;
        }
        // if the car still can't reach the next station, return -1
        if (currentFuel < distance) return -1;
        // add the current station's fuel to the priority queue
        if (i < stations.length) {
            pq.push(-stations[i][1]);
            pq.sort((a, b) => a - b);
            previousStation = stations[i][0];
        }
        currentFuel -= distance;
    }
    return stops;
}

function matrixScore(grid) {
    let rows = grid.length;
    let cols = grid[0].length;
    // flip rows to ensure the first column has the most ones
    for (let i = 0; i < rows; i++) {
        if (grid[i][0] === 0) {
            // flip the row
            for (let j = 0; j < cols; j++) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }
    // flip columns to maximize the number of ones
    for (let j = 1; j < cols; j++) {
        let ones = 0;
        let zeros = 0;
        for (let i = 0; i < rows; i++) {
            if (grid[i][j] === 1) {
                ones++;
            } else {
                zeros++;
            }
        }
        // flip the column if it has more zeros than ones
        if (zeros > ones) {
            for (let i = 0; i < rows; i++) {
                grid[i][j] = 1 - grid[i][j];
            }
        }
    }
    // calculate the score
    let score = 0;
    for (let i = 0; i < rows; i++) {
        let rowScore = 0;
        for (let j = 0; j < cols; j++) {
            rowScore += grid[i][j] * (1 << (cols - 1 - j));
        }
        score += rowScore;
    }
    return score;
}

function lemonadeChange(bills) {
    let fiveDollarBills = 0, tenDollarBills = 0;
    for (let i = 0; i < bills.length; i++) {
        if (bills[i] === 5) // if customer pays with $5, just collect it
            fiveDollarBills++;
        else if (bills[i] === 10) { // if customer pays with $10, give back a $5
            if (fiveDollarBills === 0) 
                return false;
            fiveDollarBills--;
            tenDollarBills++;
        } else { // if customer pays with $20
            if (tenDollarBills > 0 && fiveDollarBills > 0) { // give back a $10 and a $5
                tenDollarBills--;
                fiveDollarBills--;
            } else if (fiveDollarBills >= 3) { // give back three $5s
                fiveDollarBills -= 3;
            } else 
                return false;
        }
    }
    return true;
}

function carFleet(target, position, speed) {
    let n = position.length;
    let cars = [];
    for (let i = 0; i < n; i++) {
        // calculate the time it takes for each car to reach the target
        let time = (target - position[i]) / speed[i];
        cars.push([position[i], time]);
    }
    // sort the cars based on their position in descending order
    cars.sort((a, b) => b[0] - a[0]);
    let fleets = 1;
    let maxTime = cars[0][1];
    for (let i = 1; i < n; i++) {
        // if the current car's time is greater than the max time, it will form a new fleet
        if (cars[i][1] > maxTime) {
            fleets++;
            maxTime = cars[i][1];
        }
    }
    return fleets;
}

function robotSim(commands, obstacles) {
    let maxDistance = 0;
    let directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // north, east, south, west
    let currentDirection = 0;
    let currentPosition = [0, 0];
    let obstacleSet = new Set();
    for (let obstacle of obstacles) {
        obstacleSet.add(obstacle.join(','));
    }
    for (let command of commands) {
        // if command is negative, change direction
        if (command < 0) {
            // turn right if command is -1, turn left if command is -2
            currentDirection = (currentDirection + (command === -1 ? 1 : -1) + 4) % 4;
        } else {
            // move forward
            for (let i = 0; i < command; i++) {
                let nextPosition = [currentPosition[0] + directions[currentDirection][0], currentPosition[1] + directions[currentDirection][1]];
                if (obstacleSet.has(nextPosition.join(','))) {
                    break;
                }
                currentPosition = nextPosition;
                // calculate the squared Euclidean distance
                let distance = currentPosition[0] * currentPosition[0] + currentPosition[1] * currentPosition[1];
                maxDistance = Math.max(maxDistance, distance);
            }
        }
    }
    return maxDistance;
}

function middleNode(head) {
  let slowPointer = head;
  let fastPointer = head;
  // move the fast pointer twice as fast as the slow pointer to find the middle
  while (fastPointer !== null && fastPointer.next !== null) {
    slowPointer = slowPointer.next;
    fastPointer = fastPointer.next.next;
  }
  return slowPointer;
}

function uncommonFromSentences(s1, s2) {
  let wordCount = {};
  let words = s1.split(' ').concat(s2.split(' '));
  // Count the frequency of each word
  for (let word of words) {
    if (wordCount[word]) {
      wordCount[word]++;
    } else {
      wordCount[word] = 1;
    }
  }
  let result = [];
  // Filter out words that appear more than once or in both sentences
  for (let word in wordCount) {
    if (wordCount[word] === 1) {
      result.push(word);
    }
  }
  return result;
}

function stoneGame(piles) {
    let n = piles.length;
    let dp = new Array(n).fill(0).map(() => new Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        dp[i][i] = piles[i]; // base case: one pile
    }
    for (let d = 1; d < n; d++) {
        for (let i = 0; i < n - d; i++) {
            let j = i + d;
            dp[i][j] = Math.max(piles[i] - dp[i + 1][j], piles[j] - dp[i][j - 1]); // choose the move that maximizes the score
        }
    }
    return dp[0][n - 1] > 0; // Alice wins if her score is positive
}

function numRescueBoats(people, limit) {
    people.sort((a, b) => a - b); // sort the people array in ascending order
    let left = 0, right = people.length - 1; // initialize two pointers, one at the start and one at the end
    let boats = 0; // initialize the number of boats
    while (left <= right) { // loop until the two pointers meet
        // if the sum of the weights of the people at the two pointers is within the limit, put them in the same boat
        if (people[left] + people[right] <= limit) left++; 
        right--; // move the right pointer to the left
        boats++; // increment the number of boats
    }
    return boats;
}

function fairCandySwap(aliceSizes, bobSizes) {
    let aliceTotal = 0, bobTotal = 0;
    for (const a of aliceSizes) aliceTotal += a;
    for (const b of bobSizes) bobTotal += b;
    let target = (aliceTotal + bobTotal) / 2;
    let aliceSet = new Set(aliceSizes);
    for (let bobSize of bobSizes) {
        let aliceSize = aliceTotal + bobSize - target;
        if (aliceSet.has(aliceSize)) return [aliceSize, bobSize];
    }
}

function nthMagicalNumber(n, a, b) {
    const MOD = 1e9 + 7;
    let left = Math.min(a, b), right = n * Math.min(a, b);
    // calculate the count of magical numbers less than or equal to mid
    while (left < right) {
        let mid = Math.floor((left + right) / 2);
        // calculate the count of magical numbers less than or equal to mid
        let count = Math.floor(mid / a) + Math.floor(mid / b) - Math.floor(mid / lcm(a, b));
        if (count < n) left = mid + 1;
        else right = mid;
    }
    return left % MOD;
}

function gcd(a, b) {
    if (b === 0) return a;
    return gcd(b, a % b);
}

function lcm(a, b) {
    return Math.floor(a * b / gcd(a, b));
}

