function projectionArea(grid) {
    let xyArea = 0, yzArea = 0, zxArea = 0;
    let maxRow = new Array(grid.length).fill(0), maxCol = new Array(grid[0].length).fill(0);
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            // calculate xy projection area by counting non-zero cells
            if (grid[i][j] > 0) xyArea++;
            // update max height for each row and column
            maxRow[i] = Math.max(maxRow[i], grid[i][j]);
            maxCol[j] = Math.max(maxCol[j], grid[i][j]);
        }
    }
    // calculate yz and zx projection areas by summing max heights of rows and columns
    yzArea = maxRow.reduce((a, b) => a + b, 0);
    zxArea = maxCol.reduce((a, b) => a + b, 0);
    return xyArea + yzArea + zxArea;
}

function decodeAtIndex(s, k) {
    let size = 0;
    for (const c of s) {
        if (/\d/.test(c)) size *= Number(c);
        else size++;
    }
    for (let i = s.length - 1; i >= 0; i--) {
        k %= size;
        if (k === 0 && /[a-z]/.test(s[i])) return s[i];
        if (/\d/.test(s[i])) size /= Number(s[i]);
        else size--;
    }
}

function superEggDrop(k, n) {
  let dp = new Array(k + 1).fill(0).map(() => new Array(n + 1).fill(0));
  let m = 0;
  // calculate the minimum number of moves for each number of eggs and floors
  while (dp[k][m] < n) {
    m++;
    for (let i = 1; i <= k; i++) {
      // for each egg, calculate the maximum number of floors that can be checked
      dp[i][m] = dp[i - 1][m - 1] + dp[i][m - 1] + 1;
    }
  }
  return m;
}

function minEatingSpeed(piles, h) {
    let left = 1, right = Math.max(...piles);
    while (left < right) {
        // calculate the middle speed and check if it's possible to eat all bananas within h hours
        let mid = Math.floor((left + right) / 2);
        let hoursNeeded = 0;
        for (let pile of piles) {
            // calculate the hours needed to eat the current pile with the current speed
            hoursNeeded += Math.ceil(pile / mid);
        }
        if (hoursNeeded > h) {
            // if the hours needed is more than h, we need to increase the speed
            left = mid + 1;
        } else {
            // if the hours needed is less than or equal to h, we can try to decrease the speed
            right = mid;
        }
    }
    return left;
}

function profitableSchemes(n, minProfit, group, profit) {
  const MOD = 1e9 + 7;
  const dp = Array.from({length: n + 1}, () => new Array(minProfit + 1).fill(0));
  dp[0][0] = 1;
  for (let i = 0; i < group.length; i++) {
    const g = group[i], p = profit[i];
    for (let j = n; j >= g; j--) {
      for (let k = minProfit; k >= 0; k--) {
        const newK = Math.min(minProfit, k + p);
        dp[j][newK] = (dp[j][newK] + dp[j - g][k]) % MOD;
      }
    }
  }
  let result = 0;
  for (let j = 0; j <= n; j++) result = (result + dp[j][minProfit]) % MOD;
  return result;
}

function reachableNodes(edges, maxMoves, n) {
  const graph = new Map();
  for (let i = 0; i < n; i++) graph.set(i, new Map());
  for (const [u, v, cnt] of edges) {
    graph.get(u).set(v, cnt);
    graph.get(v).set(u, cnt);
  }
  const dist = new Array(n).fill(Infinity);
  dist[0] = 0;
  const pq = [[0, 0]];
  const visited = new Set();
  while (pq.length) {
    pq.sort((a, b) => a[0] - b[0]);
    const [d, u] = pq.shift();
    if (visited.has(u)) continue;
    visited.add(u);
    for (const [v, cnt] of graph.get(u)) {
      const nd = d + cnt + 1;
      if (nd < dist[v]) { dist[v] = nd; pq.push([nd, v]); }
    }
  }
  let result = 0;
  for (let i = 0; i < n; i++) if (dist[i] <= maxMoves) result++;
  for (const [u, v, cnt] of edges) {
    const a = dist[u] < maxMoves ? Math.min(cnt, maxMoves - dist[u]) : 0;
    const b = dist[v] < maxMoves ? Math.min(cnt, maxMoves - dist[v]) : 0;
    result += Math.min(cnt, a + b);
  }
  return result;
}

function spiralMatrixIII(rows, cols, rStart, cStart) {
    let result = [];
    let directions = [[0, 1], [1, 0], [0, -1], [-1, 0]]; // right, down, left, up
    let directionIndex = 0;
    let steps = 1;
    let stepsCount = 0;
    let row = rStart;
    let col = cStart;
    // add the starting position to the result
    result.push([row, col]);
    while (result.length < rows * cols) {
        // move in the current direction
        let newRow = row + directions[directionIndex][0];
        let newCol = col + directions[directionIndex][1];
        // check if the new position is within the grid
        if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols) {
            // add the new position to the result
            result.push([newRow, newCol]);
        }
        // move to the new position
        row = newRow;
        col = newCol;
        // increment the steps count
        stepsCount++;
        // if we have taken the required number of steps in the current direction, change the direction
        if (stepsCount === steps) {
            // reset the steps count
            stepsCount = 0;
            // change the direction
            directionIndex = (directionIndex + 1) % 4;
            // increase the number of steps for the next two directions
            if (directionIndex % 2 === 0) {
                steps++;
            }
        }
    }
    return result;
}

function constructFromPrePost(preorder, postorder) {
    function buildTree(preStart, preEnd, postStart, postEnd) {
        // base case: if the start index is greater than the end index, return null
        if (preStart > preEnd) return null;

        // create the root node with the first element in the preorder array
        let root = new TreeNode(preorder[preStart]);

        // if the length of the current subtree is 1, return the root node
        if (preStart == preEnd) return root;

        // find the index of the left child in the preorder array
        let leftChildIndex = preStart + 1;

        // find the index of the left child in the postorder array
        let leftChildPostIndex = postStart;
        while (postorder[leftChildPostIndex] != preorder[leftChildIndex]) leftChildPostIndex++;

        // calculate the length of the left subtree
        let leftTreeLength = leftChildPostIndex - postStart + 1;

        // recursively build the left subtree
        root.left = buildTree(leftChildIndex, leftChildIndex + leftTreeLength - 1, postStart, leftChildPostIndex);

        // recursively build the right subtree
        root.right = buildTree(leftChildIndex + leftTreeLength, preEnd, leftChildPostIndex + 1, postEnd - 1);

        return root;
    }

    return buildTree(0, preorder.length - 1, 0, postorder.length - 1);
}

function isMonotonic(nums) {
  let increasing = true;
  let decreasing = true;
  // Check for increasing and decreasing conditions in a single pass
  for (let i = 0; i < nums.length - 1; i++) {
    if (nums[i] > nums[i + 1]) increasing = false;
    if (nums[i] < nums[i + 1]) decreasing = false;
  }
  // Return true if the array is either increasing or decreasing
  return increasing || decreasing;
}

function sortArrayByParity(nums) {
  let left = 0; 
  let right = 0;
  // iterate through the array and swap elements if they are in the wrong order
  while (right < nums.length) {
    // if the current element is even, swap it with the leftmost element
    if (nums[right] % 2 === 0) {
      let temp = nums[left];
      nums[left] = nums[right];
      nums[right] = temp;
      // move the left pointer to the next position
      left++;
    }
    // move the right pointer to the next position
    right++;
  }
  return nums;
}

function totalFruit(fruits) {
    let maxFruits = 0;
    let left = 0;
    let fruitCount = {};
    // iterate over the fruits array and expand the window to the right
    for (let right = 0; right < fruits.length; right++) {
        // add the current fruit to the fruitCount object
        fruitCount[fruits[right]] = (fruitCount[fruits[right]] || 0) + 1;
        // while there are more than 2 types of fruits in the window, shrink the window from the left
        while (Object.keys(fruitCount).length > 2) {
            // remove the fruit at the left of the window from the fruitCount object
            fruitCount[fruits[left]]--;
            // if the count of the fruit at the left is 0, remove it from the fruitCount object
            if (fruitCount[fruits[left]] === 0) {
                delete fruitCount[fruits[left]];
            }
            // move the left pointer to the right
            left++;
        }
        // update the maxFruits with the current window size
        maxFruits = Math.max(maxFruits, right - left + 1);
    }
    return maxFruits;
}

function numSpecialEquivGroups(words) {
    let groups = new Set();
    for (let word of words) {
        let evenChars = '', oddChars = '';
        for (let i = 0; i < word.length; i++) {
            // separate characters at even and odd indices
            if (i % 2 === 0) evenChars += word[i];
            else oddChars += word[i];
        }
        // sort characters at even and odd indices separately
        let sortedWord = evenChars.split('').sort().join('') + oddChars.split('').sort().join('');
        groups.add(sortedWord);
    }
    return groups.size;
}

