function numPermsDISequence(s) {
  const n = s.length;
  const MOD = 1e9 + 7;
  let prev = [1];
  for (let i = 1; i <= n; i++) {
    const cur = new Array(i + 1).fill(0);
    if (s[i - 1] === 'I') {
      let prefix = 0;
      for (let j = 0; j <= i; j++) {
        cur[j] = prefix % MOD;
        if (j < prev.length) prefix += prev[j];
      }
    } else {
      let suffix = 0;
      for (let j = i; j >= 0; j--) {
        if (j < prev.length) suffix += prev[j];
        cur[j] = suffix % MOD;
      }
    }
    prev = cur;
  }
  let res = 0;
  for (const v of prev) res = (res + v) % MOD;
  return res;
}

function findAndReplacePattern(words, pattern) {
    function isMatch(word, pattern) {
        // Create two hash tables to store the mapping from pattern to word and word to pattern
        let patternToWord = {};
        let wordToPattern = {};

        // Iterate over the characters in the pattern and the word
        for (let i = 0; i < pattern.length; i++) {
            // If the pattern character is not in the patternToWord hash table, add it
            if (!(pattern[i] in patternToWord)) {
                patternToWord[pattern[i]] = word[i];
            }
            // If the word character is not in the wordToPattern hash table, add it
            if (!(word[i] in wordToPattern)) {
                wordToPattern[word[i]] = pattern[i];
            }
            // If the mapping is not consistent, return false
            if (patternToWord[pattern[i]] !== word[i] || wordToPattern[word[i]] !== pattern[i]) {
                return false;
            }
        }
        // If the function has not returned false, the word matches the pattern
        return true;
    }

    // Filter the words array to include only the words that match the pattern
    return words.filter(word => isMatch(word, pattern));
}

function StockSpanner() {
    this.stack = [];
}

StockSpanner.prototype.next = function(price) {
    let span = 1; 
    // keep popping elements from the stack as long as the price at the top of the stack is less than or equal to the current price
    while (this.stack.length > 0 && this.stack[this.stack.length - 1][0] <= price) {
        // add the span of the popped element to the current span
        span += this.stack.pop()[1];
    }
    // push the current price and its span onto the stack
    this.stack.push([price, span]);
    return span;
}

function allPossibleFBT(n) {
    if (n % 2 === 0) return []; // if n is even, it's not possible to form a full binary tree
    if (n === 1) return [new TreeNode(0)]; // base case: tree with one node
    let result = []; // store all possible full binary trees
    for (let i = 1; i < n; i += 2) { // try all possible left subtree sizes
        let leftTrees = allPossibleFBT(i); // get all possible left subtrees
        let rightTrees = allPossibleFBT(n - i - 1); // get all possible right subtrees
        for (let left of leftTrees) { // combine left and right subtrees
            for (let right of rightTrees) {
                let root = new TreeNode(0); // create a new root node
                root.left = left; // set left child
                root.right = right; // set right child
                result.push(root); // add the new tree to the result
            }
        }
    }
    return result; // return all possible full binary trees
}

function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

function FreqStack() {
    let frequencyMap = {};
    let frequencyToElements = {};
    let maxFrequency = 0;
    return {
        push: function(x) {
            // increment frequency of the element in frequency map
            frequencyMap[x] = (frequencyMap[x] || 0) + 1;
            let frequency = frequencyMap[x];
            // update max frequency if needed
            maxFrequency = Math.max(maxFrequency, frequency);
            // add element to the corresponding frequency list
            if (!frequencyToElements[frequency]) frequencyToElements[frequency] = [];
            frequencyToElements[frequency].push(x);
        },
        pop: function() {
            // remove the most frequent element from the stack
            let mostFrequentElements = frequencyToElements[maxFrequency];
            let removedElement = mostFrequentElements.pop();
            // update frequency map and max frequency if needed
            frequencyMap[removedElement]--;
            if (mostFrequentElements.length === 0) maxFrequency--;
            return removedElement;
        }
    }
}

function sumSubseqWidths(nums) {
    const MOD = 1e9 + 7;
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const powersOf2 = new Array(n).fill(1);
    for (let i = 1; i < n; i++) powersOf2[i] = (powersOf2[i - 1] * 2) % MOD;
    let sum = 0;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            sum = (sum + (nums[j] - nums[i]) * powersOf2[j - i - 1]) % MOD;
        }
    }
    return sum;
}

function superpalindromesInRange(left, right) {
    function isPalindrome(num) {
        let str = num.toString();
        let i = 0, j = str.length - 1;
        while (i < j) {
            if (str[i] !== str[j]) return false;
            i++; j--;
        }
        return true;
    }

    let count = 0;
    // generate all possible palindrome numbers and check if their squares are within the range
    for (let i = 1; i <= 10000; i++) {
        if (isPalindrome(i)) {
            let square = i * i;
            // check if the square is within the range and is a palindrome
            if (square >= parseInt(left) && square <= parseInt(right) && isPalindrome(square)) {
                count++;
            }
        }
    }
    return count;
}

function surfaceArea(grid) {
    let n = grid.length;
    let result = 0;
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            // calculate the surface area of the top and bottom faces
            if (grid[i][j] > 0) result += 2;
            // calculate the surface area of the sides
            if (grid[i][j] > 0) {
                // check the cell to the left
                if (j === 0 || grid[i][j] > grid[i][j - 1]) result += grid[i][j] - (j > 0 ? grid[i][j - 1] : 0);
                // check the cell to the right
                if (j === n - 1 || grid[i][j] > grid[i][j + 1]) result += grid[i][j] - (j < n - 1 ? grid[i][j + 1] : 0);
                // check the cell above
                if (i === 0 || grid[i][j] > grid[i - 1][j]) result += grid[i][j] - (i > 0 ? grid[i - 1][j] : 0);
                // check the cell below
                if (i === n - 1 || grid[i][j] > grid[i + 1][j]) result += grid[i][j] - (i < n - 1 ? grid[i + 1][j] : 0);
            }
        }
    }
    return result;
}

function atMostNGivenDigitSet(digits, n) {
  const s = n.toString();
  const k = s.length;
  const D = digits.length;
  let result = 0;
  for (let len = 1; len < k; len++) result += Math.pow(D, len);
  for (let i = 0; i < k; i++) {
    let hasSame = false;
    for (const d of digits) {
      if (d < s[i]) result += Math.pow(D, k - i - 1);
      else if (d === s[i]) { hasSame = true; break; }
    }
    if (!hasSame) return result;
  }
  return result + 1;
}

function sumSubarrayMins(arr) {
    const MOD = 1e9 + 7;
    const n = arr.length;
    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    const stack = [];
    // find the first smaller element to the left
    for (let i = 0; i < n; i++) {
        while (stack.length > 0 && arr[stack[stack.length - 1]] >= arr[i]) {
            stack.pop();
        }
        if (stack.length > 0) {
            left[i] = stack[stack.length - 1];
        }
        stack.push(i);
    }
    stack.length = 0;
    // find the first smaller element to the right
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length > 0 && arr[stack[stack.length - 1]] > arr[i]) {
            stack.pop();
        }
        if (stack.length > 0) {
            right[i] = stack[stack.length - 1];
        }
        stack.push(i);
    }
    let sum = 0;
    // calculate the sum of min(b) for each subarray
    for (let i = 0; i < n; i++) {
        const count = (i - left[i]) * (right[i] - i);
        sum = (sum + count * arr[i]) % MOD;
    }
    return sum;
}

function smallestRangeI(nums, k) {
  let smallest = Math.min(...nums); // find the smallest number in the array
  let largest = Math.max(...nums); // find the largest number in the array
  return Math.max(largest - smallest - 2 * k, 0); // calculate the smallest possible range after applying k operations
}

function partitionDisjoint(nums) {
  let maxLeft = nums[0], maxSoFar = nums[0], partitionIndex = 0;
  for (let i = 1; i < nums.length; i++) {
    // update maxSoFar to track the max value seen so far
    maxSoFar = Math.max(maxSoFar, nums[i]);
    // if current element is smaller than maxLeft, update partitionIndex and maxLeft
    if (nums[i] < maxLeft) {
      partitionIndex = i;
      maxLeft = maxSoFar;
    }
  }
  // return the partitionIndex which represents the length of the left subarray
  return partitionIndex + 1;
}

function reverseOnlyLetters(s) {
  let left = 0;
  let right = s.length - 1;
  let result = s.split('');
  // Swap characters from left and right pointers if they are letters
  while (left < right) {
    if (!isLetter(s[left])) {
      left++;
    } else if (!isLetter(s[right])) {
      right--;
    } else {
      // Swap characters
      let temp = result[left];
      result[left] = result[right];
      result[right] = temp;
      left++;
      right--;
    }
  }
  return result.join('');
}

function isLetter(char) {
  return char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z';
}

function snakesAndLadders(board) {
    const n = board.length;
    const cells = new Array(n * n);
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            const idx = i % 2 === 0 ? i * n + j : i * n + n - j - 1;
            cells[idx] = board[n - i - 1][j];
        }
    }
    const queue = [[0, 0]];
    const visited = new Set([0]);
    while (queue.length > 0) {
        const [curr, rolls] = queue.shift();
        if (curr === n * n - 1) return rolls;
        for (let i = 1; i <= 6; i++) {
            let next = curr + i;
            if (next >= n * n) continue;
            if (cells[next] !== -1) next = cells[next] - 1;
            if (!visited.has(next)) {
                queue.push([next, rolls + 1]);
                visited.add(next);
            }
        }
    }
    return -1;
}

function smallestRangeII(nums, k) {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  let result = nums[n - 1] - nums[0];
  for (let i = 0; i < n - 1; i++) {
    const high = Math.max(nums[n - 1] - k, nums[i] + k);
    const low = Math.min(nums[0] + k, nums[i + 1] - k);
    result = Math.min(result, high - low);
  }
  return result;
}

function hasGroupsSizeX(deck) {
  // Create a hash map to store the frequency of each card number
  var countMap = {};
  for (var i = 0; i < deck.length; i++) {
    if (countMap[deck[i]]) {
      countMap[deck[i]]++;
    } else {
      countMap[deck[i]] = 1;
    }
  }
  // Find the greatest common divisor of all the frequencies
  var gcd = -1;
  for (var key in countMap) {
    if (gcd === -1) {
      gcd = countMap[key];
    } else {
      gcd = findGCD(gcd, countMap[key]); // Find GCD of current GCD and the current frequency
    }
  }
  // If the GCD is greater than 1, return true; otherwise, return false
  return gcd > 1;
}

function findGCD(a, b) {
  if (b === 0) {
    return a;
  } else {
    return findGCD(b, a % b);
  }
}

function sortArray(nums) {
  // divide the array into two halves until we have subarrays of size 1
  if (nums.length <= 1) return nums;
  const mid = Math.floor(nums.length / 2);
  const left = sortArray(nums.slice(0, mid));
  const right = sortArray(nums.slice(mid));
  // merge the sorted subarrays
  return merge(left, right);
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  // compare elements from the two subarrays and add the smaller one to the result
  while (i < left.length && j < right.length) {
    if (left[i] < right[j]) result.push(left[i++]);
    else result.push(right[j++]);
  }
  // add any remaining elements from the subarrays
  return result.concat(left.slice(i)).concat(right.slice(j));
}

