function wordSubsets(words1, words2) {
    let maxFreq = {};
    for (let word of words2) {
        let freq = {};
        for (let char of word) freq[char] = (freq[char] || 0) + 1;
        for (let char in freq) maxFreq[char] = Math.max(maxFreq[char] || 0, freq[char]);
    }
    let result = [];
    for (let word of words1) {
        let freq = {};
        for (let char of word) freq[char] = (freq[char] || 0) + 1;
        let isUniversal = true;
        for (let char in maxFreq) {
            if ((freq[char] || 0) < maxFreq[char]) {
                isUniversal = false;
                break;
            }
        }
        if (isUniversal) result.push(word);
    }
    return result;
}

function topVotedCandidate(persons, times, queries) {
    let voteCount = {};
    let leader = 0;
    let result = [];
    let leaderAtTime = {};

    for (let i = 0; i < persons.length; i++) {
        if (!voteCount[persons[i]]) voteCount[persons[i]] = 0;
        voteCount[persons[i]]++;

        if (voteCount[persons[i]] >= voteCount[leader] || (voteCount[persons[i]] === voteCount[leader] && i > leader)) {
            leader = persons[i];
        }

        leaderAtTime[times[i]] = leader;
    }

    for (let i = 0; i < queries.length; i++) {
        let queryTime = queries[i];
        // FIXED: the buggy version first searched forward for the smallest recorded
        // time >= queryTime, which uses a FUTURE vote to answer a query about an
        // earlier time. The correct answer is the leader at the LARGEST recorded
        // time <= queryTime, found here via backward scan.
        let leaderAtQueryTime = null;
        for (let j = times.length - 1; j >= 0; j--) {
            if (times[j] <= queryTime) {
                leaderAtQueryTime = leaderAtTime[times[j]];
                break;
            }
        }
        result.push(leaderAtQueryTime);
    }

    return result;
}

function catMouseGame(graph) {
  const n = graph.length;
  const DRAW = 0, MOUSE_WIN = 1, CAT_WIN = 2;
  const MOUSE_TURN = 0, CAT_TURN = 1;

  const color = Array.from({length: n}, () => Array.from({length: n}, () => new Array(2).fill(DRAW)));
  const degree = Array.from({length: n}, () => Array.from({length: n}, () => new Array(2).fill(0)));
  for (let mouse = 0; mouse < n; mouse++) {
    for (let cat = 0; cat < n; cat++) {
      degree[mouse][cat][MOUSE_TURN] = graph[mouse].length;
      degree[mouse][cat][CAT_TURN] = graph[cat].length - (graph[cat].includes(0) ? 1 : 0);
    }
  }

  const queue = [];
  for (let cat = 1; cat < n; cat++) {
    for (let turn = 0; turn < 2; turn++) {
      if (color[0][cat][turn] === DRAW) { color[0][cat][turn] = MOUSE_WIN; queue.push([0, cat, turn]); }
      if (color[cat][cat][turn] === DRAW) { color[cat][cat][turn] = CAT_WIN; queue.push([cat, cat, turn]); }
    }
  }

  function parents(mouse, cat, turn) {
    const result = [];
    if (turn === CAT_TURN) {
      for (const m of graph[mouse]) result.push([m, cat, MOUSE_TURN]);
    } else {
      for (const c of graph[cat]) {
        if (c !== 0) result.push([mouse, c, CAT_TURN]);
      }
    }
    return result;
  }

  let qi = 0;
  while (qi < queue.length) {
    const [mouse, cat, turn] = queue[qi++];
    const result = color[mouse][cat][turn];
    for (const [pMouse, pCat, pTurn] of parents(mouse, cat, turn)) {
      if (color[pMouse][pCat][pTurn] !== DRAW) continue;
      let win;
      if (pTurn === MOUSE_TURN) win = (result === MOUSE_WIN);
      else win = (result === CAT_WIN);
      if (win) {
        color[pMouse][pCat][pTurn] = result;
        queue.push([pMouse, pCat, pTurn]);
      } else {
        degree[pMouse][pCat][pTurn]--;
        if (degree[pMouse][pCat][pTurn] === 0) {
          color[pMouse][pCat][pTurn] = (pTurn === MOUSE_TURN) ? CAT_WIN : MOUSE_WIN;
          queue.push([pMouse, pCat, pTurn]);
        }
      }
    }
  }

  return color[1][2][MOUSE_TURN];
}

function minAddToMakeValid(s) {
  let count = 0;
  let balance = 0;
  // iterate through string and balance open and close parentheses
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '(') balance++;
    else balance--;
    // if balance is negative, increment count and reset balance
    if (balance < 0) { count++; balance = 0; }
  }
  // add remaining balance to count
  return count + balance;
}

function maxSubarraySumCircular(nums) {
    let totalSum = 0;
    let maxKadaneSum = -Infinity;
    let minKadaneSum = Infinity;
    let currentMaxSum = 0;
    let currentMinSum = 0;

    for (let i = 0; i < nums.length; i++) {
        totalSum += nums[i];
        // update current max sum using Kadane's algorithm
        currentMaxSum = Math.max(nums[i], currentMaxSum + nums[i]);
        maxKadaneSum = Math.max(maxKadaneSum, currentMaxSum);
        // update current min sum using Kadane's algorithm
        currentMinSum = Math.min(nums[i], currentMinSum + nums[i]);
        minKadaneSum = Math.min(minKadaneSum, currentMinSum);
    }

    // if total sum is equal to minKadaneSum, it means all numbers are negative
    if (totalSum === minKadaneSum) {
        return maxKadaneSum;
    } else {
        // return the maximum of maxKadaneSum and totalSum - minKadaneSum
        return Math.max(maxKadaneSum, totalSum - minKadaneSum);
    }
}

function numMusicPlaylists(n, goal, k) {
    const MOD = 1e9 + 7;
    const dp = Array.from({length: goal + 1}, () => Array(n + 1).fill(0));
    dp[0][0] = 1;
    for (let i = 1; i <= goal; i++) {
        for (let j = 1; j <= n; j++) {
            dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (n - j + 1)) % MOD;
            if (j > k) dp[i][j] = (dp[i][j] + dp[i - 1][j] * (j - k)) % MOD;
        }
    }
    return dp[goal][n];
}

function TreeNode(val, left, right) {
    this.val = (val === undefined ? 0 : val);
    this.left = (left === undefined ? null : left);
    this.right = (right === undefined ? null : right);
}

function CBTInserter(root) {
    this.root = root;
    this.queue = []; // holds nodes that are missing at least one child, in level order
    let q = [root];
    while (q.length) {
        let node = q.shift();
        if (!node.left || !node.right) this.queue.push(node);
        if (node.left) q.push(node.left);
        if (node.right) q.push(node.right);
    }
}

CBTInserter.prototype.insert = function(val) {
    const node = new TreeNode(val);
    const parent = this.queue[0];
    if (!parent.left) parent.left = node;
    else { parent.right = node; this.queue.shift(); }
    this.queue.push(node);
    return parent.val;
};

CBTInserter.prototype.get_root = function() {
    return this.root;
};

function sortArrayByParityII(nums) {
  let evenIndex = 0, oddIndex = 1;
  // iterate through the array and swap elements if they are in the wrong position
  while (evenIndex < nums.length && oddIndex < nums.length) {
    // if the current even index has an odd number, swap it with the next odd index
    if (nums[evenIndex] % 2 === 1) {
      // find the next odd index with an even number
      while (nums[oddIndex] % 2 === 1) oddIndex += 2;
      // swap the elements
      let temp = nums[evenIndex];
      nums[evenIndex] = nums[oddIndex];
      nums[oddIndex] = temp;
    }
    // if the current odd index has an even number, swap it with the next even index
    if (nums[oddIndex] % 2 === 0) {
      // find the next even index with an odd number
      while (nums[evenIndex] % 2 === 0) evenIndex += 2;
      // swap the elements
      let temp = nums[oddIndex];
      nums[oddIndex] = nums[evenIndex];
      nums[evenIndex] = temp;
    }
    // move to the next indices
    evenIndex += 2;
    oddIndex += 2;
  }
  return nums;
}

function threeSumMulti(arr, target) {
  const MOD = 1e9 + 7;
  const count = new Array(101).fill(0);
  for (const x of arr) count[x]++;
  let result = 0;
  for (let i = 0; i <= 100; i++) {
    for (let j = i; j <= 100; j++) {
      const k = target - i - j;
      if (k < j || k > 100) continue;
      if (i === j && j === k) {
        result += count[i] * (count[i] - 1) * (count[i] - 2) / 6;
      } else if (i === j) {
        result += count[i] * (count[i] - 1) / 2 * count[k];
      } else if (j === k) {
        result += count[i] * (count[j] * (count[j] - 1) / 2);
      } else {
        result += count[i] * count[j] * count[k];
      }
      result %= MOD;
    }
  }
  return result;
}

function minFlipsMonoIncr(s) {
    let ones = 0, flips = 0;
    for (let i = 0; i < s.length; i++) {
        // if we encounter a 1, we can either flip all previous 0s to 1s or flip this 1 to 0
        if (s[i] === '1') ones++;
        else // if we encounter a 0 after some 1s, we can either flip this 0 to 1 or flip all previous 1s to 0s
            flips = Math.min(flips + 1, ones);
    }
    return flips;
}

function numSubarraysWithSum(nums, goal) {
    let count = 0;
    let prefixSumCount = {0: 1}; // initialize with 0 sum having a count of 1
    let currentSum = 0;
    for (let i = 0; i < nums.length; i++) {
        currentSum += nums[i]; // calculate the prefix sum
        let diff = currentSum - goal; 
        if (diff in prefixSumCount) // if the difference is in the hash map
            count += prefixSumCount[diff]; // add the count to the result
        if (!(currentSum in prefixSumCount)) // if the current sum is not in the hash map
            prefixSumCount[currentSum] = 0; // initialize it with a count of 0
        prefixSumCount[currentSum]++; // increment the count of the current sum
    }
    return count;
}

function isLongPressedName(name, typed) {
