}

function numUniqueEmails(emails) {
  let uniqueEmails = new Set();
  for (let email of emails) {
    // split the email into local and domain parts
    let [local, domain] = email.split('@');
    // remove everything after the first '+' in the local part
    local = local.split('+')[0];
    // remove all '.' in the local part
    local = local.replace(/\./g, '');
    // combine the modified local and domain parts back into an email
    uniqueEmails.add(local + '@' + domain);
  }
  // return the number of unique emails
  return uniqueEmails.size;
}

function beautifulArray(n) {
    const memo = {};
    function helper(n) {
        if (memo[n]) return memo[n];
        if (n === 1) return [1];
        const odds = helper(Math.ceil(n / 2)).map(x => 2 * x - 1);
        const evens = helper(Math.floor(n / 2)).map(x => 2 * x);
        const res = odds.concat(evens);
        memo[n] = res;
        return res;
    }
    return helper(n);
}

function minFallingPathSum(matrix) {
    let n = matrix.length;
    let dp = Array(n).fill().map(() => Array(n).fill(0));
    // initialize the first row of dp with the values from the first row of matrix
    for (let i = 0; i < n; i++) {
        dp[0][i] = matrix[0][i];
    }
    // for each row starting from the second row
    for (let i = 1; i < n; i++) {
        // for each column
        for (let j = 0; j < n; j++) {
            // if it's the first column, consider the cell above and the cell above-right
            if (j === 0) {
                dp[i][j] = matrix[i][j] + Math.min(dp[i-1][j], dp[i-1][j+1]);
            }
            // if it's the last column, consider the cell above and the cell above-left
            else if (j === n-1) {
                dp[i][j] = matrix[i][j] + Math.min(dp[i-1][j-1], dp[i-1][j]);
            }
            // for other columns, consider the cell above, the cell above-left, and the cell above-right
            else {
                dp[i][j] = matrix[i][j] + Math.min(dp[i-1][j-1], dp[i-1][j], dp[i-1][j+1]);
            }
        }
    }
    // find the minimum value in the last row of dp
    let minSum = Infinity;
    for (let i = 0; i < n; i++) {
        minSum = Math.min(minSum, dp[n-1][i]);
    }
    return minSum;
}

function minMalwareSpread(graph, initial) {
    let n = graph.length;
    let parent = new Array(n).fill(0).map((_, i) => i);
    let size = new Array(n).fill(1);

    function find(x) {
        if (parent[x] !== x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    function union(x, y) {
        let rootX = find(x);
        let rootY = find(y);
        if (rootX !== rootY) {
            if (size[rootX] < size[rootY]) {
                parent[rootX] = rootY;
                size[rootY] += size[rootX];
            } else {
                parent[rootY] = rootX;
                size[rootX] += size[rootY];
            }
        }
    }

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (graph[i][j] === 1) {
                union(i, j);
            }
        }
    }

    let infected = new Array(n).fill(0);
    for (let node of initial) {
        infected[find(node)]++;
    }

    let res = -1;
    let maxSave = 0;
    for (let node of initial) {
        let root = find(node);
        if (infected[root] === 1 && size[root] > maxSave) {
            maxSave = size[root];
            res = node;
        } else if (infected[root] === 1 && size[root] === maxSave) {
            res = Math.min(res, node);
        }
    }

    if (res === -1) {
        res = Math.min(...initial);
    }

    return res;
}

function minMalwareSpread(graph, initial) {
  const n = graph.length;
  const parent = Array.from({length: n}, (_, i) => i);
  function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
  function union(x, y) { const rx = find(x), ry = find(y); if (rx !== ry) parent[rx] = ry; }
  const initialSet = new Set(initial);
  for (let i = 0; i < n; i++) {
    if (initialSet.has(i)) continue;
    for (let j = i + 1; j < n; j++) {
      if (initialSet.has(j)) continue;
      if (graph[i][j] === 1) union(i, j);
    }
  }
  const count = new Map();
  for (const node of initial) {
    for (let j = 0; j < n; j++) {
      if (!initialSet.has(j) && graph[node][j] === 1) {
        const root = find(j);
        if (!count.has(root)) count.set(root, new Set());
        count.get(root).add(node);
      }
    }
  }
  const size = new Map();
  for (let i = 0; i < n; i++) {
    if (!initialSet.has(i)) {
      const root = find(i);
      size.set(root, (size.get(root) || 0) + 1);
    }
  }
  const contribution = new Map();
  for (const [root, sources] of count) {
    if (sources.size === 1) {
      const node = [...sources][0];
      contribution.set(node, (contribution.get(node) || 0) + size.get(root));
    }
  }
  let best = Math.min(...initial);
  let bestVal = contribution.get(best) || 0;
  for (const node of initial) {
    const val = contribution.get(node) || 0;
    if (val > bestVal || (val === bestVal && node < best)) {
      bestVal = val;
      best = node;
    }
  }
  return best;
}

function knightDialer(n) {
    const MOD = 1e9 + 7;
    const moves = {
        1: [6, 8],
        2: [7, 9],
        3: [4, 8],
        4: [0, 3, 9],
        5: [],
        6: [0, 1, 7],
        7: [2, 6],
        8: [1, 3],
        9: [2, 4],
        0: [4, 6]
    };
    const dp = new Array(10).fill(1);
    // for each jump, update dp array with the number of ways to reach each cell
    for (let i = 1; i < n; i++) {
        const temp = new Array(10).fill(0);
        // for each cell, calculate the number of ways to reach it
        for (let j = 0; j < 10; j++) {
            // for each possible move from the current cell
            for (let move of moves[j]) {
                temp[j] = (temp[j] + dp[move]) % MOD;
            }
        }
        dp.splice(0, dp.length, ...temp);
    }
    // calculate the total number of distinct phone numbers
    let total = 0;
    for (let count of dp) {
        total = (total + count) % MOD;
    }
    return total;
}

function shortestBridge(grid) {
    let n = grid.length;
    let directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let queue = [];
    function dfs(i, j) {
        if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] !== 1) return;
        grid[i][j] = -1;
        queue.push([i, j]);
        for (let dir of directions) dfs(i + dir[0], j + dir[1]);
    }
    outer: for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) { dfs(i, j); break outer; }
        }
    }
    let distance = 0;
    while (queue.length > 0) {
        let size = queue.length;
        for (let i = 0; i < size; i++) {
            let [x, y] = queue.shift();
            for (let dir of directions) {
                let nx = x + dir[0], ny = y + dir[1];
                if (nx >= 0 && nx < n && ny >= 0 && ny < n) {
                    if (grid[nx][ny] === 1) return distance;
                    if (grid[nx][ny] === 0) {
                        grid[nx][ny] = -1;
                        queue.push([nx, ny]);
                    }
                }
            }
        }
        distance++;
    }
}

function reorderLogFiles(logs) {
    let letterLogs = [];
    let digitLogs = [];
    // Separate logs into letter and digit logs
    for (let log of logs) {
        if (isNaN(log.split(' ')[1])) {
            letterLogs.push(log);
        } else {
            digitLogs.push(log);
        }
    }
    // Sort letter logs based on their content
    letterLogs.sort((a, b) => {
        let contentA = a.substring(a.indexOf(' ') + 1);
        let contentB = b.substring(b.indexOf(' ') + 1);
        if (contentA < contentB) return -1;
        if (contentA > contentB) return 1;
        // If content is the same, sort by identifier
        return a.localeCompare(b);
    });
    // Combine sorted letter logs and original digit logs
    return letterLogs.concat(digitLogs);
}

