function movesToStamp(stamp, target) {
  const M = stamp.length, N = target.length;
  const result = [];
  const s = target.split('');
  const stamped = new Array(N).fill(false);
  let stampedCount = 0;
  function canStampAt(i) {
    let changed = false;
    for (let j = 0; j < M; j++) {
      if (s[i + j] === '?') continue;
      if (s[i + j] !== stamp[j]) return null;
      changed = true;
    }
    return changed;
  }
  let madeProgress = true;
  while (stampedCount < N && madeProgress) {
    madeProgress = false;
    for (let i = 0; i <= N - M; i++) {
      if (stamped[i]) continue;
      const canApply = canStampAt(i);
      if (canApply) {
        for (let j = 0; j < M; j++) {
          if (s[i + j] !== '?') { s[i + j] = '?'; stampedCount++; }
        }
        stamped[i] = true;
        result.push(i);
        madeProgress = true;
      }
    }
  }
  if (stampedCount < N) return [];
  return result.reverse();
}

function rangeSumBST(root, low, high) {
    function dfs(node) {
        if (!node) return 0; // base case: if node is null, return 0
        let sum = 0; 
        // recursively traverse the left and right subtrees
        sum += dfs(node.left) + dfs(node.right); 
        // if the current node's value is within the range, add it to the sum
        if (node.val >= low && node.val <= high) sum += node.val; 
        return sum;
    }
    return dfs(root);
}

function minAreaRect(points) {
