    }
    return minArea === Infinity ? 0 : minArea;
}

function validMountainArray(arr) {
    let left = 0, right = arr.length - 1;
    // find the first element from the left that is smaller than the previous one
    while (left < arr.length - 1 && arr[left] < arr[left + 1]) left++;
    // find the first element from the right that is smaller than the previous one
    while (right > 0 && arr[right] < arr[right - 1]) right--;
    // if the two pointers meet at the same point and it's not at the start or end, it's a mountain array
    return left > 0 && left < arr.length - 1 && left === right;
