}

function distinctSubseqII(s) {
    const MOD = 1e9 + 7;
    const n = s.length;
    let dp = new Array(n + 1).fill(0);
    let last = new Array(26).fill(-1);
    dp[0] = 1;
    for (let i = 1; i <= n; i++) {
        // calculate the total number of subsequences without the current character
        dp[i] = dp[i - 1] * 2 % MOD;
        // if the current character has appeared before, subtract the number of subsequences that end with the same character
        if (last[s[i - 1].charCodeAt(0) - 'a'.charCodeAt(0)] !== -1) {
            dp[i] = (dp[i] - dp[last[s[i - 1].charCodeAt(0) - 'a'.charCodeAt(0)]] + MOD) % MOD;
        }
        // update the last occurrence of the current character
        last[s[i - 1].charCodeAt(0) - 'a'.charCodeAt(0)] = i - 1;
    }
    // return the total number of distinct non-empty subsequences
    return (dp[n] - 1 + MOD) % MOD;
}

function minIncrementForUnique(nums) {
