      moves += nums[i - 1] - nums[i] + 1; // calculate the moves needed to make the current number unique
      nums[i] = nums[i - 1] + 1; // update the current number to be unique
    }
  }
  return moves;
}

function validateStackSequences(pushed, popped) {
  let stack = [];
  let popIndex = 0;
  // iterate through the pushed array and simulate the stack operations
  for (let i = 0; i < pushed.length; i++) {
    stack.push(pushed[i]);
    // try to pop elements from the stack as long as the top element matches the next expected popped element
    while (stack.length > 0 && stack[stack.length - 1] === popped[popIndex]) {
      stack.pop();
      popIndex++;
    }
  }
  // if the stack is empty, it means we were able to simulate the entire popped sequence
  return stack.length === 0;
}

function shortestSuperstring(words) {
    const n = words.length;
    const overlap = Array(n).fill(0).map(() => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            for (let k = Math.min(words[i].length, words[j].length); k > 0; k--) {
                if (words[i].endsWith(words[j].slice(0, k))) {
                    overlap[i][j] = k;
                    break;
                }
            }
        }
    }
    const dp = Array(1 << n).fill(0).map(() => Array(n).fill(null));
    for (let i = 0; i < n; i++) {
        dp[1 << i][i] = words[i];
    }
    for (let mask = 1; mask < (1 << n); mask++) {
        for (let i = 0; i < n; i++) {
            if (((mask >> i) & 1) === 0) continue;
            const subMask = mask ^ (1 << i);
            for (let j = 0; j < n; j++) {
                if (subMask === 0 || dp[subMask][j] === null) continue;
                if (dp[mask][i] === null || dp[mask][i].length > dp[subMask][j].length + words[i].length - overlap[j][i]) {
                    dp[mask][i] = dp[subMask][j] + words[i].slice(overlap[j][i]);
                }
            }
        }
    }
    let minLen = Infinity;
    let result = null;
    for (let i = 0; i < n; i++) {
        if (dp[(1 << n) - 1][i] !== null && dp[(1 << n) - 1][i].length < minLen) {
            minLen = dp[(1 << n) - 1][i].length;
            result = dp[(1 << n) - 1][i];
        }
    }
    return result;
}

function minDeletionSize(strs) {
