            if (strs[row].charAt(col) < strs[row - 1].charAt(col)) {
                isSorted = false;
                break;
            }
        }
        // if the column is not sorted, increment the deletion count
        if (!isSorted) {
            deletionCount++;
        }
    }
    return deletionCount;
}

function bagOfTokensScore(tokens, power) {
    tokens.sort((a, b) => a - b); // sort tokens in ascending order to consider playing the smallest tokens first
    let score = 0, maxScore = 0;
    let left = 0, right = tokens.length - 1;
    while (left <= right) { // use two pointers to consider playing tokens face-up and face-down
        if (power >= tokens[left]) {
            power -= tokens[left]; // play token face-up
            score++;
            left++;
            maxScore = Math.max(maxScore, score); // update max score
        } else if (score > 0) {
            power += tokens[right]; // play token face-down
            score--;
            right--;
        } else {
            break; // cannot play any more tokens
        }
    }
    return maxScore;
}

