    if (queue.length > 0) queue.push(queue.shift());
  }
  return result;
}

function largestTimeFromDigits(arr) {
    let maxTime = -1;
    // Generate all permutations of the input array
    function permute(arr, start, end) {
        if (start === end) {
            // Convert the current permutation to a time string
            let time = `${arr[0]}${arr[1]}:${arr[2]}${arr[3]}`;
            // Check if the time is valid
            if (isValidTime(time)) {
                // Update the max time if the current time is larger
                maxTime = Math.max(maxTime, parseInt(time.replace(":", "")));
            }
        } else {
            for (let i = start; i <= end; i++) {
                // Swap the current element with the start element
                [arr[start], arr[i]] = [arr[i], arr[start]];
                // Recursively generate permutations for the remaining elements
                permute(arr, start + 1, end);
                // Backtrack by swapping the elements back
                [arr[start], arr[i]] = [arr[i], arr[start]];
            }
        }
    }
    // Check if a time string is valid
    function isValidTime(time) {
        let [hours, minutes] = time.split(":");
        // Check if the hours and minutes are within valid ranges
        return parseInt(hours) >= 0 && parseInt(hours) <= 23 && parseInt(minutes) >= 0 && parseInt(minutes) <= 59;
    }
    // Generate all permutations of the input array
    permute(arr, 0, arr.length - 1);
    // Return the max time in "HH:MM" format if it's valid, otherwise return an empty string
    if (maxTime === -1) return "";
    let hours = Math.floor(maxTime / 100).toString().padStart(2, "0");
    let minutes = (maxTime % 100).toString().padStart(2, "0");
    return `${hours}:${minutes}`;
}

function removeStones(stones) {
    let parent = {};
    let rank = {};

    function find(x) {
        // if the stone is not in the parent dictionary, add it
        if (!(x in parent)) {
            parent[x] = x;
            rank[x] = 0;
        }
        // if the stone is the parent of itself, return it
        if (parent[x] === x) return x;
        // otherwise, recursively find the parent and update the parent of the current stone
        return parent[x] = find(parent[x]);
    }

    function union(x, y) {
        // find the parents of the two stones
        let rootX = find(x);
        let rootY = find(y);
        // if the two stones are already in the same group, return
        if (rootX === rootY) return;
        // otherwise, merge the two groups
        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    // iterate over the stones and union the stones that share the same row or column
    for (let i = 0; i < stones.length; i++) {
        for (let j = i + 1; j < stones.length; j++) {
            // if two stones share the same row or column, union them
            if (stones[i][0] === stones[j][0] || stones[i][1] === stones[j][1]) {
                union(stones[i].join(','), stones[j].join(','));
            }
        }
    }

    // count the number of groups
    let groups = new Set();
    for (let stone of stones) {
        groups.add(find(stone.join(',')));
    }

    // the number of stones that can be removed is the total number of stones minus the number of groups
    return stones.length - groups.size;
}

