function flipEquiv(root1, root2) {
    // if both trees are empty, they are flip equivalent
    if (!root1 && !root2) return true;
    // if one tree is empty and the other is not, they are not flip equivalent
    if (!root1 || !root2) return false;
    // if the values at the current nodes are different, the trees are not flip equivalent
    if (root1.val !== root2.val) return false;
    // check if the trees are flip equivalent without flipping
    let noFlip = flipEquiv(root1.left, root2.left) && flipEquiv(root1.right, root2.right);
    // check if the trees are flip equivalent with flipping
    let flip = flipEquiv(root1.left, root2.right) && flipEquiv(root1.right, root2.left);
    // return true if the trees are flip equivalent with or without flipping
    return noFlip || flip;
}

function isAlienSorted(words, order) {
    // Create a hash table to store the order of the alien alphabet
    let alienOrder = {};
    for (let i = 0; i < order.length; i++) {
        alienOrder[order[i]] = i;
    }

    // Compare each pair of adjacent words in the list
    for (let i = 0; i < words.length - 1; i++) {
        let word1 = words[i];
        let word2 = words[i + 1];
        // Compare characters at the same position in the two words
        for (let j = 0; j < Math.min(word1.length, word2.length); j++) {
            // If the characters are different, check their order in the alien alphabet
            if (word1[j] !== word2[j]) {
                // If the character in the first word comes after the character in the second word, return false
                if (alienOrder[word1[j]] > alienOrder[word2[j]]) {
                    return false;
                }
                // If the character in the first word comes before the character in the second word, break the loop
                break;
            }
        }
        // If the first word is longer than the second word and all characters are the same, return false
        if (word1.length > word2.length && word1.substring(0, word2.length) === word2) {
            return false;
        }
    }
    // If all pairs of words are sorted, return true
    return true;
}

function largestComponentSize(nums) {
    // Create a map to store the prime factors of each number
    let primeFactors = new Map();
    for (let num of nums) {
        let factors = getPrimeFactors(num);
        primeFactors.set(num, factors);
    }

    // Initialize a union-find data structure
    let parent = new Map();
    for (let num of nums) {
        parent.set(num, num);
    }

    // Union the numbers that share a common prime factor
    for (let num1 of nums) {
        for (let num2 of nums) {
            if (num1 !== num2) {
                let commonFactor = getCommonFactor(primeFactors.get(num1), primeFactors.get(num2));
                if (commonFactor !== -1) {
                    union(parent, num1, num2);
                }
            }
        }
    }

    // Find the size of the largest connected component
    let componentSizes = new Map();
    for (let num of nums) {
        let root = find(parent, num);
        if (!componentSizes.has(root)) {
            componentSizes.set(root, 0);
        }
        componentSizes.set(root, componentSizes.get(root) + 1);
    }

    // Return the size of the largest connected component
    let maxSize = 0;
    for (let size of componentSizes.values()) {
        maxSize = Math.max(maxSize, size);
    }
    return maxSize;
}

// Helper function to get the prime factors of a number
function getPrimeFactors(num) {
    let factors = new Set();
    for (let i = 2; i * i <= num; i++) {
        while (num % i === 0) {
            factors.add(i);
            num /= i;
        }
    }
    if (num > 1) {
        factors.add(num);
    }
    return factors;
}

// Helper function to get the common prime factor between two sets of factors
function getCommonFactor(factors1, factors2) {
    for (let factor of factors1) {
        if (factors2.has(factor)) {
            return factor;
        }
    }
    return -1;
}

// Helper function for the union-find data structure
function find(parent, num) {
    if (parent.get(num) !== num) {
        parent.set(num, find(parent, parent.get(num)));
    }
    return parent.get(num);
}

// Helper function for the union-find data structure
function union(parent, num1, num2) {
    let root1 = find(parent, num1);
    let root2 = find(parent, num2);
    if (root1 !== root2) {
        parent.set(root1, root2);
    }
}

