        let needDelete = false;
        for (let row = 0; row < n - 1; row++) {
            if (!sorted[row] && strs[row][col] > strs[row + 1][col]) { needDelete = true; break; }
        }
        if (needDelete) { count++; continue; }
        for (let row = 0; row < n - 1; row++) {
            if (strs[row][col] < strs[row + 1][col]) sorted[row] = true;
        }
    }
    return count;
}

function tallestBillboard(rods) {
    let dp = {0: 0};
    for (let rod of rods) {
        let newDp = Object.assign({}, dp);
        for (let diffKey in dp) {
            const diff = Number(diffKey);
            let sum = dp[diffKey] + rod;
            newDp[diff + rod] = Math.max(newDp[diff + rod] || 0, sum);
            newDp[Math.abs(rod - diff)] = Math.max(newDp[Math.abs(rod - diff)] || 0, sum - rod);
        }
        dp = newDp;
    }
    return dp[0];
}

function canReorderDoubled(arr) {
    let countMap = {};
    for (let num of arr) {
        // count occurrences of each number
        countMap[num] = (countMap[num] || 0) + 1;
    }
    let keys = Object.keys(countMap).sort((a, b) => Math.abs(a) - Math.abs(b));
    for (let key of keys) {
        // try to match each number with its double
        let count = countMap[key];
        if (count > 0) {
            let doubleCount = countMap[key * 2] || 0;
            if (count > doubleCount) {
                return false;
            }
            // remove matched pairs from count map
            countMap[key * 2] = doubleCount - count;
        }
    }
    return true;
}

function prisonAfterNDays(cells, n) {
    let state = cells.join('');
    let map = {};
    let days = 0;
    // while loop to simulate the days
    while (days < n) {
        // store the current state in the map
        if (map[state]) {
            // if the state is already in the map, we've found a cycle
            let cycleLength = days - map[state];
            // calculate the remaining days
            let remainingDays = (n - days) % cycleLength;
            // simulate the remaining days
            for (let i = 0; i < remainingDays; i++) {
                // update the state
                state = getNextState(state);
            }
            // break the loop
            break;
        }
        // store the current state in the map
        map[state] = days;
        // update the state
        state = getNextState(state);
        // increment the days
        days++;
    }
    // convert the state back to an array
    return state.split('').map(Number);
}

// helper function to get the next state
function getNextState(state) {
    let nextState = '';
    // iterate over the cells
    for (let i = 0; i < state.length; i++) {
        // if the cell is the first or the last, it only has one neighbor
        if (i === 0 || i === state.length - 1) {
            // if the cell is occupied and its neighbor is vacant, or vice versa, it becomes vacant
            nextState += '0';
        } else {
            // if the cell's neighbors are the same, it becomes occupied
            if (state[i - 1] === state[i + 1]) {
                nextState += '1';
            } else {
                // if the cell's neighbors are different, it becomes vacant
                nextState += '0';
            }
        }
    }
    return nextState;
}

function repeatedNTimes(nums) {
