function isCompleteTree(root) {
    if (!root) return true;
    let queue = [root];
    let hasNull = false;
    while (queue.length > 0) {
        // check if we've encountered a null node before, if so, all subsequent nodes must be null
        let node = queue.shift();
        if (node === null) {
            hasNull = true;
        } else {
            // if we've encountered a null node before and now we're seeing a non-null node, return false
            if (hasNull) return false;
            queue.push(node.left);
            queue.push(node.right);
        }
    }
    return true;
}

function maxWidthRamp(nums) {
  let indices = []; // store indices of elements in non-increasing order
  for (let i = 0; i < nums.length; i++) {
    // if the current element is less than or equal to the last element in the indices array, add it
    if (indices.length === 0 || nums[i] <= nums[indices[indices.length - 1]]) {
      indices.push(i);
    }
  }
  let maxWidth = 0;
  for (let j = nums.length - 1; j >= 0; j--) {
    // for each element from the end, find the largest index i such that nums[i] <= nums[j]
    while (indices.length > 0 && nums[indices[indices.length - 1]] <= nums[j]) {
      // update the maximum width if the current pair has a larger width
      maxWidth = Math.max(maxWidth, j - indices.pop());
    }
  }
  return maxWidth;
}

function leastOperators(x, target) {
  const memo = new Map();
  function solve(t) {
    if (t === 0) return 0;
    if (t < x) return Math.min(2 * t - 1, 2 * (x - t));
    if (memo.has(t)) return memo.get(t);
    let k = Math.floor(Math.log(t) / Math.log(x));
    let p = Math.pow(x, k);
    // guard against floating point log/pow drift
    while (p * x <= t) { p *= x; k++; }
    while (p > t) { p /= x; k--; }
    let ans;
    if (t === p) {
      ans = k - 1;
    } else {
      ans = solve(t - p) + k;
      const left = p * x - t;
      if (left < t) ans = Math.min(ans, solve(left) + k + 1);
    }
    memo.set(t, ans);
    return ans;
  }
  return solve(target);
}

function minDeletionSize(strs) {
    const m = strs[0].length;
    const dp = new Array(m).fill(1);
    for (let j = 1; j < m; j++) {
        for (let i = 0; i < j; i++) {
            let valid = true;
            for (const s of strs) {
                if (s[i] > s[j]) { valid = false; break; }
            }
            if (valid) dp[j] = Math.max(dp[j], dp[i] + 1);
        }
    }
    const maxKeep = Math.max(...dp);
    return m - maxKeep;
}

function minAreaFreeRect(points) {
  const n = points.length;
  const groups = new Map();
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const [x1, y1] = points[i], [x2, y2] = points[j];
      const cx = (x1 + x2) / 2, cy = (y1 + y2) / 2;
      const dist2 = (x1 - x2) ** 2 + (y1 - y2) ** 2;
      const key = cx + ',' + cy + ',' + dist2;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push([i, j]);
    }
  }
  let minArea = Infinity;
  for (const pairs of groups.values()) {
    for (let a = 0; a < pairs.length; a++) {
      for (let b = a + 1; b < pairs.length; b++) {
        const [i1, j1] = pairs[a], [i2, j2] = pairs[b];
        const p1 = points[i1], p2 = points[i2], p3 = points[j2];
        const dx1 = p2[0] - p1[0], dy1 = p2[1] - p1[1];
        const dx2 = p3[0] - p1[0], dy2 = p3[1] - p1[1];
        const area = Math.sqrt(dx1 * dx1 + dy1 * dy1) * Math.sqrt(dx2 * dx2 + dy2 * dy2);
        minArea = Math.min(minArea, area);
      }
    }
  }
  return minArea === Infinity ? 0 : minArea;
}

function regionsBySlashes(grid) {
