}

function dfs(grid, i, j) {
    let n = grid.length;
    if (i < 0 || i >= n || j < 0 || j >= n || grid[i][j] === 1) {
        return;
    }
    // mark the cell as visited
    grid[i][j] = 1;
    dfs(grid, i - 1, j);
    dfs(grid, i + 1, j);
    dfs(grid, i, j - 1);
    dfs(grid, i, j + 1);
}

function isUnivalTree(root) {
    // check if the current node's value is the same as the root's value
    if (!root) return true;
    if (root.val !== root.left?.val && root.left) return false;
    if (root.val !== root.right?.val && root.right) return false;
    // recursively check the left and right subtrees
    return isUnivalTree(root.left) && isUnivalTree(root.right);
}

function spellchecker(wordlist, queries) {
    let originalWords = new Set(wordlist);
    let lowerCaseWords = {};
    let ignoreVowelWords = {};

    for (let word of wordlist) {
        let lowerCaseWord = word.toLowerCase();
        if (!(lowerCaseWord in lowerCaseWords)) {
            lowerCaseWords[lowerCaseWord] = word;
        }
        let ignoreVowelWord = lowerCaseWord.replace(/[aeiou]/g, '*');
        if (!(ignoreVowelWord in ignoreVowelWords)) {
            ignoreVowelWords[ignoreVowelWord] = word;
        }
    }

    let result = [];
    for (let query of queries) {
        if (originalWords.has(query)) {
            result.push(query);
        } else {
            let lowerCaseQuery = query.toLowerCase();
            if (lowerCaseQuery in lowerCaseWords) {
                result.push(lowerCaseWords[lowerCaseQuery]);
            } else {
                let ignoreVowelQuery = lowerCaseQuery.replace(/[aeiou]/g, '*');
                if (ignoreVowelQuery in ignoreVowelWords) {
                    result.push(ignoreVowelWords[ignoreVowelQuery]);
                } else {
                    result.push('');
                }
            }
        }
    }
    return result;
}

function numsSameConsecDiff(n, k) {
