}

function dfs(result, current, length, k, firstDigit) {
  if (length === 0) {
    // if the number is complete, add it to the result
    result.push(current);
    return;
  }
  let lastDigit = current % 10;
  if (lastDigit - k >= 0) {
    // try adding the next digit with the difference k
    dfs(result, current * 10 + lastDigit - k, length - 1, k, firstDigit);
  }
  if (k !== 0 && lastDigit + k <= 9) {
    // try adding the next digit with the negative difference k
    dfs(result, current * 10 + lastDigit + k, length - 1, k, firstDigit);
  }
}

function minCameraCover(root) {
    let result = 0;
    function dfs(node) {
        // if node is null, return 0 (no camera needed)
        if (!node) return 0;
        let left = dfs(node.left), right = dfs(node.right);
        // if any child node is not covered, install a camera
        if (left === -1 || right === -1) {
            result++;
            return 1;
        }
        // if any child node has a camera, this node is covered
        if (left === 1 || right === 1) return 0;
        // if this node is not covered and no child node has a camera, return -1
        return -1;
    }
    // if root node is not covered, install a camera
    if (dfs(root) === -1) result++;
    return result;
}

function flipMatchVoyage(root, voyage) {
    let index = 0;
    let result = [];
    function dfs(node) {
        if (!node) return true;
        // Check if current node's value matches the expected value in voyage
        if (node.val !== voyage[index++]) return false;
        // If the left child exists and its value does not match the next expected value, flip the node
        if (node.left && node.left.val !== voyage[index]) {
            result.push(node.val);
            // Swap left and right subtrees
            [node.left, node.right] = [node.right, node.left];
        }
        // Recursively traverse the left and right subtrees
        return dfs(node.left) && dfs(node.right);
    }
    return dfs(root) ? result : [-1];
}

function powerfulIntegers(x, y, bound) {
    let result = [];
    let i = 0;
    // calculate all possible values of xi
    while (Math.pow(x, i) <= bound) {
        let j = 0;
        // calculate all possible values of yj and check if xi + yj is within the bound
        while (Math.pow(x, i) + Math.pow(y, j) <= bound) {
            let value = Math.pow(x, i) + Math.pow(y, j);
            // add the value to the result if it's not already there
            if (!result.includes(value)) {
                result.push(value);
            }
            // if y is 1, then yj will always be 1, so we can break the loop
            if (y === 1) {
                break;
            }
            j++;
        }
        // if x is 1, then xi will always be 1, so we can break the loop
        if (x === 1) {
            break;
        }
        i++;
    }
    return result;
}

