function pancakeSort(arr) {
    var result = [];
    var n = arr.length;
    // iterate through the array from the end to the beginning
    for (var i = n - 1; i > 0; i--) {
        var maxIndex = 0;
        // find the index of the maximum element in the unsorted part of the array
        for (var j = 1; j <= i; j++) {
            if (arr[j] > arr[maxIndex]) {
                maxIndex = j;
            }
        }
        // if the maximum element is not at the end of the unsorted part, flip it to the end
        if (maxIndex !== i) {
            // if the maximum element is not at the beginning, flip it to the beginning
            if (maxIndex !== 0) {
                result.push(maxIndex + 1);
                // flip the sub-array from the beginning to the maximum element
                flip(arr, maxIndex);
            }
            result.push(i + 1);
            // flip the sub-array from the beginning to the end of the unsorted part
            flip(arr, i);
        }
    }
    return result;
}

// helper function to flip a sub-array
function flip(arr, k) {
    var left = 0;
    var right = k;
    // swap elements from the left and right ends of the sub-array
    while (left < right) {
        var temp = arr[left];
        arr[left] = arr[right];
        arr[right] = temp;
        left++;
        right--;
    }
}

function kClosest(points, k) {
    // calculate the Euclidean distance for each point and store it along with the point
    let pointsWithDistance = points.map(point => ({ point, distance: Math.sqrt(point[0] * point[0] + point[1] * point[1]) }));
    // sort the points based on their distance from the origin
    pointsWithDistance.sort((a, b) => a.distance - b.distance);
    // return the k closest points
    return pointsWithDistance.slice(0, k).map(point => point.point);
}

function largestPerimeter(nums) {
    nums.sort((a, b) => b - a); // sort the array in descending order to consider the largest possible perimeters first
    for (let i = 0; i < nums.length - 2; i++) { 
        // check if the current three sides can form a triangle with a non-zero area
        if (nums[i] < nums[i + 1] + nums[i + 2]) { 
            return nums[i] + nums[i + 1] + nums[i + 2]; // return the largest possible perimeter
        }
    }
    return 0; // if no triangle can be formed, return 0
}

function sortedSquares(nums) {
  const result = new Array(nums.length);
  let left = 0, right = nums.length - 1;
  // iterate from the end of the result array to fill it with the largest squares first
  for (let i = nums.length - 1; i >= 0; i--) {
    // compare the absolute values of the numbers at the left and right pointers to determine which square is larger
    if (Math.abs(nums[left]) > Math.abs(nums[right])) {
      result[i] = nums[left] * nums[left];
      left++;
    } else {
      result[i] = nums[right] * nums[right];
      right--;
    }
  }
  return result;
}

function maxTurbulenceSize(arr) {
    let maxLength = 1;
    let increasing = 1;
    let decreasing = 1;
    for (let i = 1; i < arr.length; i++) {
        // if current element is greater than previous, update increasing subarray length
        if (arr[i] > arr[i - 1]) {
            increasing = decreasing + 1;
            decreasing = 1;
        } 
        // if current element is less than previous, update decreasing subarray length
        else if (arr[i] < arr[i - 1]) {
            decreasing = increasing + 1;
            increasing = 1;
        } 
        // if current element is equal to previous, reset both subarray lengths
        else {
            increasing = 1;
            decreasing = 1;
        }
        // update maximum length
        maxLength = Math.max(maxLength, Math.max(increasing, decreasing));
    }
    return maxLength;
}

function subarraysDivByK(nums, k) {
    let count = 0;
    let prefixSum = 0;
    let sumCount = new Map();
    sumCount.set(0, 1); // initialize with 0 sum and count 1
    for (let i = 0; i < nums.length; i++) {
        prefixSum += nums[i]; // calculate prefix sum
        let remainder = prefixSum % k; // calculate remainder
        if (sumCount.has(remainder)) // if remainder is already in map
            count += sumCount.get(remainder); // increment count
        sumCount.set(remainder, (sumCount.get(remainder) || 0) + 1); // update remainder count
    }
    return count;
}

function isRationalEqual(s, t) {
  function toFraction(str) {
    let repPart = '';
    const parenIdx = str.indexOf('(');
    let mainPart = parenIdx === -1 ? str : str.slice(0, parenIdx);
    if (parenIdx !== -1) repPart = str.slice(parenIdx + 1, str.indexOf(')'));
    const dotIdx = mainPart.indexOf('.');
    let intPart, decPart;
    if (dotIdx === -1) { intPart = mainPart; decPart = ''; }
    else { intPart = mainPart.slice(0, dotIdx); decPart = mainPart.slice(dotIdx + 1); }
    const d = decPart.length;
    const A = parseInt((intPart + decPart) || '0', 10);
    if (repPart.length === 0) {
      return [A, Math.pow(10, d)];
    }
    const r = repPart.length;
    const B = parseInt(repPart, 10);
    const numerator = A * (Math.pow(10, r) - 1) + B;
    const denominator = Math.pow(10, d) * (Math.pow(10, r) - 1);
    return [numerator, denominator];
  }
  const [n1, d1] = toFraction(s);
  const [n2, d2] = toFraction(t);
  return n1 * d2 === n2 * d1;
}

function oddEvenJumps(arr) {
    const n = arr.length;
    function makeJumps(indicesSorted) {
        const result = new Array(n).fill(-1);
        const stack = [];
        for (const i of indicesSorted) {
            while (stack.length > 0 && stack[stack.length - 1] < i) {
                result[stack.pop()] = i;
            }
            stack.push(i);
        }
        return result;
    }
    const idx = arr.map((v, i) => i);
    const ascIndices = idx.slice().sort((a, b) => arr[a] - arr[b] || a - b);
    const descIndices = idx.slice().sort((a, b) => arr[b] - arr[a] || a - b);
    const nextHigher = makeJumps(ascIndices);
    const nextLower = makeJumps(descIndices);
    const higher = new Array(n).fill(false);
    const lower = new Array(n).fill(false);
    higher[n - 1] = true;
    lower[n - 1] = true;
    let count = 1;
    for (let i = n - 2; i >= 0; i--) {
        if (nextHigher[i] !== -1) higher[i] = lower[nextHigher[i]];
        if (nextLower[i] !== -1) lower[i] = higher[nextLower[i]];
        if (higher[i]) count++;
    }
    return count;
}

function distributeCoins(root) {
    let moves = 0;
    function dfs(node) {
        // recursively calculate the number of coins that need to be moved for each node
        if (!node) return 0;
        let left = dfs(node.left);
        let right = dfs(node.right);
        moves += Math.abs(left) + Math.abs(right);
        // calculate the number of coins that need to be moved from the current node to its children
        return node.val + left + right - 1;
    }
    dfs(root);
    return moves;
}

function TimeMap() {
