}

TimeMap.prototype.get = function(key, timestamp) {
    // FIXED: must return "" (empty string), not -1, when nothing is found -
    // the problem spec requires a string return type, and "" !== -1 breaks equality checks.
    if (!this.map[key]) return "";
    if (this.map[key][timestamp]) return this.map[key][timestamp];
