}

function uniquePathsIII(grid) {
    let m = grid.length, n = grid[0].length, nonObstacles = 0, startX = 0, startY = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 0) nonObstacles++;
            else if (grid[i][j] === 1) { startX = i; startY = j; }
        }
    }
    let count = 0;
    function backtrack(x, y, steps) {
        if (x < 0 || x >= m || y < 0 || y >= n || grid[x][y] === -1 || grid[x][y] === 'v') return;
        if (grid[x][y] === 2) {
            if (steps === nonObstacles + 1) count++;
            return;
        }
        let temp = grid[x][y];
        grid[x][y] = 'v';
        backtrack(x + 1, y, steps + 1);
        backtrack(x - 1, y, steps + 1);
        backtrack(x, y + 1, steps + 1);
        backtrack(x, y - 1, steps + 1);
        grid[x][y] = temp;
    }
    backtrack(startX, startY, 0);
    return count;
}

function countAndTriples(nums) {
