function mincostTickets(days, costs) {
    let lastDay = days[days.length - 1];
    let dp = new Array(lastDay + 1).fill(0);
    let travelDays = new Set(days);
    for (let day = 1; day <= lastDay; day++) {
        if (!travelDays.has(day)) {
            dp[day] = dp[day - 1]; // if not a travel day, cost is the same as the previous day
        } else {
            dp[day] = Math.min(
                dp[Math.max(0, day - 1)] + costs[0], // 1-day pass
                dp[Math.max(0, day - 7)] + costs[1], // 7-day pass
                dp[Math.max(0, day - 30)] + costs[2] // 30-day pass
            );
        }
    }
    return dp[lastDay];
}

function intervalIntersection(firstList, secondList) {
    let result = [];
    let i = 0, j = 0;
    // Loop through both lists until one of them is exhausted
    while (i < firstList.length && j < secondList.length) {
        // Calculate the intersection of the current intervals
        let start = Math.max(firstList[i][0], secondList[j][0]);
        let end = Math.min(firstList[i][1], secondList[j][1]);
        // If the intersection is valid, add it to the result
        if (start <= end) result.push([start, end]);
        // Move to the next interval in the list with the smaller end value
        if (firstList[i][1] < secondList[j][1]) i++;
        else j++;
    }
    return result;
}

function brokenCalc(startValue, target) {
