        if (target % 2 === 1) {
            target++;
            operations++;
        }
        // divide target by 2 to reduce the difference between target and startValue
        target = Math.floor(target / 2);
        operations++;
    }
    // add the difference between startValue and target to operations
    operations += startValue - target;
    return operations;
}

