function subarraysWithKDistinct(nums, k) {
  function atMostK(k) {
    let count = 0;
    let left = 0;
    let map = {};
    for (let right = 0; right < nums.length; right++) {
      map[nums[right]] = (map[nums[right]] || 0) + 1;
      // while there are more than k distinct integers in the window, shrink the window
      while (Object.keys(map).length > k) {
        map[nums[left]]--;
        if (map[nums[left]] === 0) {
          delete map[nums[left]];
        }
        left++;
      }
      // the number of subarrays ending at the current right pointer is right - left + 1
      count += right - left + 1;
    }
    return count;
  }
  // the number of subarrays with exactly k distinct integers is the number of subarrays with at most k distinct integers minus the number of subarrays with at most k-1 distinct integers
  return atMostK(k) - atMostK(k - 1);
}

