        return dfs(node.left, node.val, depth + 1, target) || dfs(node.right, node.val, depth + 1, target);
    }
    // find parents and depths of x and y
    let [xParent, xDepth] = dfs(root, null, 0, x);
    let [yParent, yDepth] = dfs(root, null, 0, y);
