function verticalTraversal(root) {
    if (!root) return [];
    const columnTable = {};
    const queue = [[root, 0, 0]]; // node, column, row
    let minColumn = 0, maxColumn = 0;
    while (queue.length) {
        const [node, column, row] = queue.shift();
        if (node) {
            if (!columnTable[column]) columnTable[column] = [];
            columnTable[column].push([row, node.val]);
            minColumn = Math.min(minColumn, column);
            maxColumn = Math.max(maxColumn, column);
            queue.push([node.left, column - 1, row + 1]);
            queue.push([node.right, column + 1, row + 1]);
        }
    }
    const result = [];
    for (let i = minColumn; i <= maxColumn; i++) {
        if (columnTable[i]) {
            columnTable[i].sort((a, b) => a[0] - b[0] || a[1] - b[1]);
            result.push(columnTable[i].map(x => x[1]));
        }
    }
    return result;
}

