    for (let equation of equations) {
        // Check if the equation is an equality equation
        if (equation[1] === '=') {
            // Find the parents of the two variables
            let x = equation[0].charCodeAt(0) - 'a'.charCodeAt(0);
            let y = equation[3].charCodeAt(0) - 'a'.charCodeAt(0);
            // Union the two variables
            parent[find(parent, x)] = find(parent, y);
        }
    }

    // Then, process all the inequality equations
    for (let equation of equations) {
        // Check if the equation is an inequality equation
        if (equation[1] === '!') {
            // Find the parents of the two variables
            let x = equation[0].charCodeAt(0) - 'a'.charCodeAt(0);
            let y = equation[3].charCodeAt(0) - 'a'.charCodeAt(0);
            // If the two variables are in the same group, return false
            if (find(parent, x) === find(parent, y)) {
                return false;
            }
        }
    }

    // If we have not returned false, then it is possible to assign integers to variable names
    return true;
}

// Helper function to find the parent of a variable
function find(parent, x) {
    // If the parent of x is not x, then find the parent of the parent of x
    if (parent[x] !== x) {
        parent[x] = find(parent, parent[x]);
    }
    return parent[x];
}

// TIME: O(n * alpha(n)) SPACE: O(1)

function minKBitFlips(nums, k) {
    let flips = 0;
    let queue = [];
    for (let i = 0; i < nums.length; i++) {
        // if there are flips in the queue and we are at a position where a flip would end, remove it from the queue
        if (queue.length > 0 && queue[0] + k === i) queue.shift();
        // if the current bit is 0 and the queue length is even, or if the current bit is 1 and the queue length is odd, we need to flip
        if ((nums[i] === 0 && queue.length % 2 === 0) || (nums[i] === 1 && queue.length % 2 === 1)) {
            // if we can't flip (not enough bits left), return -1
            if (i + k > nums.length) return -1;
            // add the current flip to the queue
            queue.push(i);
            // increment the number of flips
            flips++;
        }
    }
    return flips;
}

function numSquarefulPerms(nums) {
    function isPerfectSquare(num) {
        const sqrt = Math.sqrt(num);
        return sqrt === Math.floor(sqrt);
    }
    nums.sort((a, b) => a - b);
    const n = nums.length;
    const used = new Array(n).fill(false);
    let count = 0;
    function backtrack(path) {
        if (path.length === n) { count++; return; }
        for (let i = 0; i < n; i++) {
            if (used[i]) continue;
            if (i > 0 && nums[i] === nums[i - 1] && !used[i - 1]) continue;
            if (path.length > 0 && !isPerfectSquare(path[path.length - 1] + nums[i])) continue;
            used[i] = true;
            path.push(nums[i]);
            backtrack(path);
            path.pop();
            used[i] = false;
        }
    }
    backtrack([]);
    return count;
}

function findJudge(n, trust) {
    let trustCount = new Array(n + 1).fill(0);
    // for each trust relationship, decrement the trust count of the person who trusts and increment the trust count of the person being trusted
    for (let i = 0; i < trust.length; i++) {
        trustCount[trust[i][0]]--;
        trustCount[trust[i][1]]++;
    }
    // find the person with a trust count of n - 1, which means they are trusted by everyone else
    for (let i = 1; i <= n; i++) {
        if (trustCount[i] === n - 1) {
            return i;
        }
    }
    // if no such person is found, return -1
    return -1;
}

function insertIntoMaxTree(root, val) {
    // if the tree is empty, create a new node with the given value
    if (!root) return { val: val, left: null, right: null };

    // if the value is greater than the root's value, create a new root with the given value
    if (val > root.val) {
        // the original root becomes the left child of the new root
        return { val: val, left: root, right: null };
    }

    // if the value is less than the root's value, recursively insert it into the right subtree
    // if the right subtree is empty, create a new node with the given value
    if (!root.right) return { val: root.val, left: root.left, right: { val: val, left: null, right: null } };

    // recursively insert the value into the right subtree
    root.right = insertIntoMaxTree(root.right, val);
    // return the updated root
    return root;
}

function numRookCaptures(board) {
    let rookRow, rookCol;
    // find the position of the rook
    for (let i = 0; i < 8; i++) {
        for (let j = 0; j < 8; j++) {
            if (board[i][j] === 'R') {
                rookRow = i;
                rookCol = j;
                break;
            }
        }
    }
    let count = 0;
    // check up
    for (let i = rookRow - 1; i >= 0; i--) {
        // if we encounter a pawn, increment count and break
        if (board[i][rookCol] === 'p') {
            count++;
            break;
        }
        // if we encounter a bishop or another piece, break
        if (board[i][rookCol] !== '.') {
            break;
        }
    }
    // check down
    for (let i = rookRow + 1; i < 8; i++) {
        // if we encounter a pawn, increment count and break
        if (board[i][rookCol] === 'p') {
            count++;
            break;
        }
        // if we encounter a bishop or another piece, break
        if (board[i][rookCol] !== '.') {
            break;
        }
    }
    // check left
    for (let i = rookCol - 1; i >= 0; i--) {
        // if we encounter a pawn, increment count and break
        if (board[rookRow][i] === 'p') {
            count++;
            break;
        }
        // if we encounter a bishop or another piece, break
        if (board[rookRow][i] !== '.') {
            break;
        }
    }
    // check right
    for (let i = rookCol + 1; i < 8; i++) {
        // if we encounter a pawn, increment count and break
        if (board[rookRow][i] === 'p') {
            count++;
            break;
        }
        // if we encounter a bishop or another piece, break
        if (board[rookRow][i] !== '.') {
            break;
        }
    }
