}

function orangesRotting(grid) {
    let rows = grid.length;
    let cols = grid[0].length;
    let queue = [];
    let freshCount = 0;
    let minutes = 0;

    // initialize queue with rotten oranges and count fresh oranges
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (grid[i][j] === 2) {
                queue.push([i, j]);
            } else if (grid[i][j] === 1) {
                freshCount++;
            }
        }
    }

    // define possible directions for BFS
    let directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // perform BFS
    while (queue.length > 0 && freshCount > 0) {
        let size = queue.length;
        for (let i = 0; i < size; i++) {
            let [x, y] = queue.shift();
            // explore neighbors and rot fresh oranges
            for (let direction of directions) {
                let nx = x + direction[0];
                let ny = y + direction[1];
                if (nx >= 0 && nx < rows && ny >= 0 && ny < cols && grid[nx][ny] === 1) {
                    grid[nx][ny] = 2;
                    queue.push([nx, ny]);
                    freshCount--;
                }
            }
        }
        // increment minutes after each level of BFS
        minutes++;
    }

    // return minutes if all fresh oranges are rotten, otherwise return -1
    return freshCount === 0 ? minutes : -1;
}

function isValid(s) {
  let stack = [];
  for (let i = 0; i < s.length; i++) {
    // if we encounter 'c', check if the top two elements of the stack are 'a' and 'b'
    if (s[i] === 'c' && stack.length >= 2 && stack[stack.length - 1] === 'b' && stack[stack.length - 2] === 'a') {
      stack.pop();
      stack.pop();
    } else {
      stack.push(s[i]);
    }
  }
  // if the stack is empty, it means we were able to transform the string into an empty string
  return stack.length === 0;
}

function findCommonCharacters(words) {
    // Create a hash map to store the frequency of each character in the first word
    let commonChars = {};
    for (let char of words[0]) {
        if (!commonChars[char]) commonChars[char] = 0;
        commonChars[char]++;
    }
    // Iterate over the rest of the words and update the hash map
    for (let i = 1; i < words.length; i++) {
        let currentWord = {};
        for (let char of words[i]) {
            if (!currentWord[char]) currentWord[char] = 0;
            currentWord[char]++;
        }
        // Update the commonChars hash map with the minimum frequency of each character
        for (let char in commonChars) {
            if (currentWord[char]) commonChars[char] = Math.min(commonChars[char], currentWord[char]);
            else delete commonChars[char];
        }
    }
    // Create the result array with the common characters
    let result = [];
    for (let char in commonChars) {
        // Add the character to the result array the number of times it appears in all words
        for (let i = 0; i < commonChars[char]; i++) result.push(char);
    }
    return result;
}

function mergeStones(stones, k) {
    const n = stones.length;
    if ((n - 1) % (k - 1) !== 0) return -1;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + stones[i];
    const dp = Array.from({length: n}, () => new Array(n).fill(0));
    for (let len = k; len <= n; len++) {
        for (let i = 0; i + len - 1 < n; i++) {
            const j = i + len - 1;
            dp[i][j] = Infinity;
            for (let mid = i; mid < j; mid += k - 1) {
                dp[i][j] = Math.min(dp[i][j], dp[i][mid] + dp[mid + 1][j]);
            }
            if ((len - 1) % (k - 1) === 0) {
                dp[i][j] += prefix[j + 1] - prefix[i];
            }
        }
    }
    return dp[0][n - 1];
}

function gridIllumination(n, lamps, queries) {
    let lampSet = new Set();
    for (let lamp of lamps) {
        lampSet.add(lamp.join(','));
    }
    let rowCounts = new Array(n).fill(0);
    let colCounts = new Array(n).fill(0);
    let diagonal1Counts = new Array(2 * n - 1).fill(0);
    let diagonal2Counts = new Array(2 * n - 1).fill(0);
    for (let lamp of lamps) {
        let row = lamp[0];
        let col = lamp[1];
        rowCounts[row]++;
        colCounts[col]++;
        diagonal1Counts[row + col]++;
        diagonal2Counts[row - col + n - 1]++;
    }
    let result = new Array(queries.length);
    for (let i = 0; i < queries.length; i++) {
        let row = queries[i][0];
        let col = queries[i][1];
        // check if the cell is illuminated
        result[i] = rowCounts[row] > 0 || colCounts[col] > 0 || diagonal1Counts[row + col] > 0 || diagonal2Counts[row - col + n - 1] > 0 ? 1 : 0;
        // turn off the lamp at the query cell and its adjacent lamps
        for (let r = Math.max(0, row - 1); r <= Math.min(n - 1, row + 1); r++) {
            for (let c = Math.max(0, col - 1); c <= Math.min(n - 1, col + 1); c++) {
                let lampKey = [r, c].join(',');
                if (lampSet.has(lampKey)) {
                    lampSet.delete(lampKey);
                    rowCounts[r]--;
                    colCounts[c]--;
                    diagonal1Counts[r + c]--;
                    diagonal2Counts[r - c + n - 1]--;
                }
            }
        }
    }
    return result;
}

function longestOnes(nums, k) {
  let left = 0, maxLen = 0, zeros = 0;
  // maintain a sliding window where the number of zeros is less than or equal to k
  for (let right = 0; right < nums.length; right++) {
    // if a zero is encountered, increment the zeros count
    if (nums[right] === 0) zeros++;
    // while the number of zeros exceeds k, shrink the window from the left
    while (zeros > k) {
      // if the leftmost element is a zero, decrement the zeros count
      if (nums[left] === 0) zeros--;
      // move the window to the right
      left++;
    }
    // update the maximum length of the window
    maxLen = Math.max(maxLen, right - left + 1);
  }
  return maxLen;
}

function largestSumAfterKNegations(nums, k) {
  // Sort the array in ascending order to prioritize negating smaller numbers
  nums.sort((a, b) => a - b);
  for (let i = 0; i < k; i++) {
    // Negate the smallest number in the array
    nums[0] = -nums[0];
    // Re-sort the array to maintain the smallest number at the front
    nums.sort((a, b) => a - b);
  }
  // Calculate the sum of the modified array
  return nums.reduce((a, b) => a + b, 0);
}

function clumsy(n) {
    let stack = [n];
    n--;
    let operations = ['*', '/', '+', '-'];
    let opIndex = 0;
    // loop through all numbers from n-1 down to 1
    while (n > 0) {
        // determine the current operation
        let operation = operations[opIndex % 4];
        // apply the operation to the top of the stack and the current number
        if (operation === '*') {
            // multiply the top of the stack with the current number
            let top = stack.pop();
            stack.push(top * n);
        } else if (operation === '/') {
            // divide the top of the stack by the current number
            let top = stack.pop();
            stack.push(Math.floor(top / n));
        } else {
            // add or subtract the current number from the top of the stack
            stack.push(operation);
            stack.push(n);
        }
        // move to the next operation and number
        opIndex++;
        n--;
    }
    // evaluate the expression in the stack
    let result = stack[0];
    for (let i = 1; i < stack.length; i += 2) {
        // get the operation and the next number
        let operation = stack[i];
        let num = stack[i + 1];
        // apply the operation
        if (operation === '+') {
            result += num;
        } else {
            result -= num;
        }
    }
    return result;
}

function minDominoRotations(tops, bottoms) {
    // Check if either the first element of tops or the first element of bottoms can be the target value
    for (let target of [tops[0], bottoms[0]]) {
        // Initialize the number of rotations needed for the current target value
        let rotationsA = 0, rotationsB = 0;
        // Check if the target value can be achieved by rotating the dominoes
        for (let i = 0; i < tops.length; i++) {
            // If the target value is not present in either the top or the bottom of the current domino, return -1
            if (tops[i] !== target && bottoms[i] !== target) return -1;
            // If the target value is present in the bottom of the current domino but not in the top, increment the number of rotations needed for tops
            if (tops[i] !== target) rotationsA++;
            // If the target value is present in the top of the current domino but not in the bottom, increment the number of rotations needed for bottoms
            if (bottoms[i] !== target) rotationsB++;
        }
        // If the target value can be achieved, return the minimum number of rotations needed
        if (rotationsA <= tops.length && rotationsB <= tops.length) return Math.min(rotationsA, rotationsB);
    }
    // If neither the first element of tops nor the first element of bottoms can be the target value, return -1
    return -1;
}

function numDupDigitsAtMostN(n) {
  let count = 0;
  for (let i = 1; i <= n; i++) {
    // check if the current number has any repeated digits
    let numStr = i.toString();
    let seen = new Set();
    let hasRepeat = false;
    for (let j = 0; j < numStr.length; j++) {
      // if the digit is already in the set, it's a repeat
      if (seen.has(numStr[j])) {
        hasRepeat = true;
        break;
      }
      seen.add(numStr[j]);
    }
    if (hasRepeat) {
      // if the number has a repeat, increment the count
      count++;
    }
  }
  return count;
}

function findComplement(n) {
    // calculate the number of bits in n
    let numBits = Math.floor(Math.log2(n)) + 1;
    // create a mask with all bits set to 1, with the same number of bits as n
    let mask = (1 << numBits) - 1;
    // flip all the bits in n using the mask
    return n ^ mask;
}

function canThreePartsEqualSum(arr) {
  let totalSum = 0;
  for (let i = 0; i < arr.length; i++) {
    totalSum += arr[i];
  }
  // If the total sum is not divisible by 3, we cannot partition the array into three parts with equal sums
  if (totalSum % 3 !== 0) {
    return false;
  }
  let targetSum = totalSum / 3;
  let currentSum = 0;
  let count = 0;
  for (let i = 0; i < arr.length; i++) {
    currentSum += arr[i];
    // If the current sum equals the target sum, increment the count and reset the current sum
    if (currentSum === targetSum) {
      count++;
      currentSum = 0;
    }
  }
  // We need to find at least three parts with equal sums
  return count >= 3;
}

function numPairsDivisibleBy60(time) {
  let count = 0;
  let frequency = new Array(60).fill(0);
  // iterate over each song duration and calculate its remainder when divided by 60
  for (let i = 0; i < time.length; i++) {
    let remainder = time[i] % 60;
    // for each song, find the number of songs that when added to it, the total duration is divisible by 60
    count += frequency[(60 - remainder) % 60];
    // increment the frequency of the current song's remainder
    frequency[remainder]++;
  }
  return count;
}

function shipWithinDays(weights, days) {
    let left = Math.max(...weights), right = weights.reduce((a, b) => a + b);
    while (left < right) {
        // calculate the middle capacity and check if it's possible to ship all packages within days
        let mid = Math.floor((left + right) / 2);
        let need = 1, cur = 0;
        for (let weight of weights) {
            // if current weight exceeds the capacity, start a new day
            if (cur + weight > mid) {
                need++;
                cur = 0;
            }
            cur += weight;
        }
        // if we need more days than allowed, increase the capacity
        if (need > days) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

function bstFromPreorder(preorder) {
    if (preorder.length === 0) return null;
    let root = new TreeNode(preorder[0]);
    let stack = [root];
    for (let i = 1; i < preorder.length; i++) {
        let val = preorder[i]; // create a new node with the current preorder value
        if (val < stack[stack.length - 1].val) { // if the current value is less than the top of the stack, it's a left child
            stack[stack.length - 1].left = new TreeNode(val);
            stack.push(stack[stack.length - 1].left);
        } else { // otherwise, it's a right child of a node in the stack
            let last = null;
            while (stack.length > 0 && stack[stack.length - 1].val < val) { // find the correct parent node
                last = stack.pop();
            }
            last.right = new TreeNode(val); // assign the current value as the right child of the parent node
            stack.push(last.right);
        }
    }
    return root;
}

function queryString(s, n) {
    for (let i = 1; i <= n; i++) // loop through all numbers from 1 to n
        if (s.indexOf(i.toString(2)) === -1) // check if binary representation of current number is a substring of s
            return false;
    return true;
}

function smallestRepunitDivisibleByK(k) {
    let remainder = 0;
    for (let length = 1; length <= k; length++) {
        // calculate the remainder of the current repunit when divided by k
        remainder = (remainder * 10 + 1) % k;
        if (remainder == 0) {
            // if the remainder is 0, return the current length
            return length;
        }
    }
    // if no such repunit is found, return -1
    return -1;
}

function prefixesDivBy5(nums) {
  var result = [];
  var binaryNumber = 0;
  for (var i = 0; i < nums.length; i++) {
    // update binaryNumber by shifting current bits to the left and adding new bit
    binaryNumber = (binaryNumber << 1) | nums[i];
    // check if binaryNumber is divisible by 5
    result.push(binaryNumber % 5 === 0);
  }
  return result;
}

function baseNeg2(n) {
    let result = '';
    while (n !== 0) {
        let remainder = ((n % 2) + 2) % 2;
        n = (n - remainder) / -2;
        result = remainder + result;
    }
    return result === '' ? '0' : result;
}

function maxScoreSightseeingPair(values) {
  let maxScore = 0;
  let maxValPlusIndex = values[0] + 0; // initialize max value plus index
  for (let j = 1; j < values.length; j++) {
    // update max score if current pair has higher score
    maxScore = Math.max(maxScore, maxValPlusIndex + values[j] - j);
    // update max value plus index for next iteration
    maxValPlusIndex = Math.max(maxValPlusIndex, values[j] + j);
  }
  return maxScore;
}

function nextLargerNodes(head) {
    let values = [];
    let currentNode = head;
    // Traverse the linked list to store node values
    while (currentNode) {
        values.push(currentNode.val);
        currentNode = currentNode.next;
    }
    let result = new Array(values.length).fill(0);
    let stack = [];
    for (let i = 0; i < values.length; i++) {
        // Pop all elements from the stack that are smaller than the current value
        while (stack.length > 0 && values[stack[stack.length - 1]] < values[i]) {
            result[stack.pop()] = values[i];
        }
        stack.push(i);
    }
    return result;
}

function numEnclaves(grid) {
    // define the directions for DFS
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    // get the number of rows and columns in the grid
    const rows = grid.length, cols = grid[0].length;
    // function to perform DFS from a given cell
    function dfs(row, col) {
        // if the cell is out of bounds or is a sea cell, return
        if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] === 0) return;
        // mark the current cell as visited by setting it to 0
        grid[row][col] = 0;
        // perform DFS on all adjacent land cells
        for (const [dr, dc] of directions) dfs(row + dr, col + dc);
    }
    // perform DFS from all land cells on the boundary
    for (let i = 0; i < rows; i++) {
        // if the cell is a land cell, perform DFS
        dfs(i, 0);
        dfs(i, cols - 1);
    }
    for (let j = 0; j < cols; j++) {
        // if the cell is a land cell, perform DFS
        dfs(0, j);
        dfs(rows - 1, j);
    }
    // count the number of remaining land cells
    let count = 0;
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // if the cell is a land cell, increment the count
            count += grid[i][j];
        }
    }
    return count;
}

function removeOuterParentheses(s) {
    let result = '';
    let stack = [];
    let temp = '';
    // iterate through the string to find the primitive decomposition
    for (let i = 0; i < s.length; i++) {
        // add the current character to the temporary string
        temp += s[i];
        // if the character is an opening parenthesis, push it to the stack
        if (s[i] === '(') {
            stack.push(s[i]);
        } 
        // if the character is a closing parenthesis, pop the opening parenthesis from the stack
        else if (s[i] === ')') {
            stack.pop();
            // if the stack is empty, it means we have found a primitive string
            if (stack.length === 0) {
                // remove the outermost parentheses and add the string to the result
                result += temp.slice(1, temp.length - 1);
                // reset the temporary string
                temp = '';
            }
        }
    }
    return result;
}

function videoStitching(clips, time) {
    clips.sort((a, b) => a[0] - b[0]);
    let count = 0, end = 0, far = 0;
    for (let i = 0; i < clips.length && end < time; i++) {
        // if current clip starts after the end of the current segment, return -1
        if (clips[i][0] > end) return -1;
        // update the farthest end of the current segment
        if (clips[i][1] > far) far = clips[i][1];
        // if we have reached the end of the current segment, update the end and increment the count
        if (i + 1 === clips.length || clips[i + 1][0] > end) {
            end = far;
            count++;
        }
    }
    // if we still haven't reached the end of the event, return -1
    return end < time ? -1 : count;
}

function divisorGame(n) {
    // create a dynamic programming table to store the results of subproblems
    let dp = new Array(n + 1).fill(false);
    dp[1] = false;
    for (let i = 2; i <= n; i++) {
        // check all possible moves for the current player
        for (let j = 1; j * j <= i; j++) {
            // if the current number is divisible by j, check if the opponent loses
            if (i % j === 0) {
                // if the opponent loses in the next state, the current player wins
                if (!dp[i - j]) {
                    dp[i] = true;
                    break;
                }
            }
        }
    }
    return dp[n];
}

// TIME: O(n*sqrt(n)) SPACE: O(n)

function sumRootToLeaf(root) {
    function dfs(node, currentNumber) {
        // if the node is null, return 0 as there's no path to consider
        if (node === null) return 0;
        // update the current number by shifting the bits to the left and adding the node's value
        currentNumber = (currentNumber << 1) | node.val;
        // if the node is a leaf, return the current number
        if (node.left === null && node.right === null) return currentNumber;
        // recursively explore the left and right subtrees
        return dfs(node.left, currentNumber) + dfs(node.right, currentNumber);
    }
    return dfs(root, 0);
}

function maxAncestorDiff(root) {
    let maxDiff = 0;
    function dfs(node, minVal, maxVal) {
        // update maxDiff if current node's value is the new minimum or maximum
        maxDiff = Math.max(maxDiff, Math.abs(maxVal - node.val), Math.abs(node.val - minVal));
        // update minVal and maxVal for the current node
        minVal = Math.min(minVal, node.val);
        maxVal = Math.max(maxVal, node.val);
        // recursively traverse the left and right subtrees
        if (node.left) dfs(node.left, minVal, maxVal);
        if (node.right) dfs(node.right, minVal, maxVal);
    }
    dfs(root, root.val, root.val);
    return maxDiff;
}

function camelMatch(queries, pattern) {
    const result = [];
    for (let query of queries) {
        let patternIndex = 0; // keep track of the current position in the pattern
        let match = true;
        for (let i = 0; i < query.length; i++) {
            // if the current character in the query matches the current character in the pattern, move to the next character in the pattern
            if (patternIndex < pattern.length && query[i] === pattern[patternIndex]) {
                patternIndex++;
            } 
            // if the current character in the query is uppercase and it does not match the current character in the pattern, the query does not match the pattern
            else if (query[i] >= 'A' && query[i] <= 'Z') {
                match = false;
                break;
            }
        }
        // if we have not matched all characters in the pattern, the query does not match the pattern
        if (patternIndex < pattern.length) {
            match = false;
        }
        result.push(match);
    }
    return result;
}

function longestArithmeticSubsequence(nums) {
  let maxLength = 0;
  let numMap = new Map();
  for (let i = 0; i < nums.length; i++) {
    numMap.set(nums[i], i);
  }
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      let diff = nums[j] - nums[i];
      let currentLength = 2;
      let lastNum = nums[j];
      // Check for the existence of the next number in the sequence
      while (numMap.has(lastNum + diff)) {
        lastNum += diff;
        currentLength++;
      }
      maxLength = Math.max(maxLength, currentLength);
    }
  }
  return maxLength;
}

function recoverFromPreorder(traversal) {
    let index = 0;
    function dfs(depth) {
        // parse the current node's value and update the index
        let value = 0;
        while (index < traversal.length && traversal[index] !== '-') {
            value = value * 10 + (traversal[index++] - '0');
        }
        let node = new TreeNode(value);

        // parse the current node's children
        while (index < traversal.length) {
            let childDepth = 0;
            while (index < traversal.length && traversal[index] === '-') {
                childDepth++;
                index++;
            }
            // if the child's depth is greater than the current node's depth, it's a child
            if (childDepth === depth + 1) {
                // recursively construct the child subtree
                if (!node.left) node.left = dfs(childDepth);
                else node.right = dfs(childDepth);
            } else {
                // if the child's depth is not greater, it's a sibling or ancestor, so we're done
                break;
            }
        }
        return node;
    }
    return dfs(0);
}

function twoCitySchedCost(costs) {
    // calculate the difference in cost between city a and city b for each person
    let differences = costs.map(([a, b]) => b - a);
    // sort the costs array based on the differences
    costs.sort((a, b) => (b[1] - b[0]) - (a[1] - a[0]));
    // initialize the total cost
    let totalCost = 0;
    // send the first n people to city a and the rest to city b
    for (let i = 0; i < costs.length; i++) {
        // if it's the first n people, send them to city a
        if (i < costs.length / 2) {
            totalCost += costs[i][0];
        } 
        // otherwise, send them to city b
        else {
            totalCost += costs[i][1];
        }
    }
    return totalCost;
}

function allCellsDistOrder(rows, cols, rCenter, cCenter) {
    let result = [];
    // generate all cell coordinates and calculate their distance from the center
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            result.push([i, j, Math.abs(i - rCenter) + Math.abs(j - cCenter)]);
        }
    }
    // sort the cells by their distance from the center
    result.sort((a, b) => a[2] - b[2]);
    // remove the distance from the result
    return result.map(cell => cell.slice(0, 2));
}

