function numMovesStones(a, b, c) {
    const s = [a, b, c].sort((x, y) => x - y);
    const [x, y, z] = s;
    if (z - x === 2) return [0, 0];
    if (y - x <= 2 || z - y <= 2) return [1, z - x - 2];
    return [2, z - x - 2];
}

function maxSumTwoNoOverlapSubarrays(nums, firstLen, secondLen) {
    let maxSum = 0;
    // calculate prefix sum to efficiently calculate subarray sums
    let prefixSum = [0];
    for (let i = 0; i < nums.length; i++) {
        prefixSum.push(prefixSum[i] + nums[i]);
    }
    // calculate sum of firstLen subarray and secondLen subarray for all possible positions
    for (let i = 0; i < nums.length - firstLen + 1; i++) {
        for (let j = 0; j < nums.length - secondLen + 1; j++) {
            // check if subarrays do not overlap
            if (i + firstLen <= j || j + secondLen <= i) {
                // calculate sum of current subarrays
                let sum1 = prefixSum[i + firstLen] - prefixSum[i];
                let sum2 = prefixSum[j + secondLen] - prefixSum[j];
                // update maxSum if current sum is larger
                maxSum = Math.max(maxSum, sum1 + sum2);
            }
        }
    }
    return maxSum;
}

function StreamChecker(words) {
    this.trie = {};
    for (let word of words) {
        let node = this.trie;
        for (let i = word.length - 1; i >= 0; i--) {
            // Build a trie with words in reverse order to efficiently check suffixes
            if (!node[word[i]]) node[word[i]] = {};
            node = node[word[i]];
        }
        node.end = true;
    }
    this.stream = '';
}

StreamChecker.prototype.query = function(letter) {
    this.stream += letter;
    let node = this.trie;
    for (let i = this.stream.length - 1; i >= 0; i--) {
        // Traverse the trie from the end of the stream to check for a matching suffix
        if (!node[this.stream[i]]) return false;
        node = node[this.stream[i]];
        if (node.end) return true;
    }
    return false;
}

function colorBorder(grid, row, col, color) {
    // get the color of the connected component that contains the square grid[row][col]
    const componentColor = grid[row][col];

    // directions to explore adjacent squares
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];

    // set to keep track of visited squares
    const visited = new Set();

    // set to keep track of squares on the border
    const border = new Set();

    // function to perform DFS
    function dfs(r, c) {
        // mark the current square as visited
        visited.add(`${r},${c}`);

        // check if the current square is on the border
        if (r === 0 || r === grid.length - 1 || c === 0 || c === grid[0].length - 1 || 
            // check if any adjacent square has a different color
            directions.some(([dr, dc]) => {
                const nr = r + dr;
                const nc = c + dc;
                return nr < 0 || nr >= grid.length || nc < 0 || nc >= grid[0].length || grid[nr][nc] !== componentColor;
            })) {
            // add the current square to the border set
            border.add(`${r},${c}`);
        }

        // explore adjacent squares
        for (const [dr, dc] of directions) {
            const nr = r + dr;
            const nc = c + dc;
            if (nr >= 0 && nr < grid.length && nc >= 0 && nc < grid[0].length && grid[nr][nc] === componentColor && !visited.has(`${nr},${nc}`)) {
                dfs(nr, nc);
            }
        }
    }

    // start DFS from the given square
    dfs(row, col);

    // color the border squares with the given color
    for (const coord of border) {
        const [r, c] = coord.split(',').map(Number);
        grid[r][c] = color;
    }

    return grid;
}

function maxUncrossedLines(nums1, nums2) {
    let memo = new Map();
    function dp(i, j) {
        // create a unique key for memoization
        let key = i + ',' + j;
        if (memo.has(key)) return memo.get(key);
        // base case: if we've reached the end of either array
        if (i === nums1.length || j === nums2.length) return 0;
        // if the current numbers match, draw a line and move to the next numbers
        if (nums1[i] === nums2[j]) {
            // store the result in memo and return it
            memo.set(key, 1 + dp(i + 1, j + 1));
            return memo.get(key);
        }
        // if the numbers don't match, try not drawing a line and move to the next number in either array
        // store the result in memo and return it
        memo.set(key, Math.max(dp(i + 1, j), dp(i, j + 1)));
        return memo.get(key);
    }
    return dp(0, 0);
}

function convertBST(root) {
    let sum = 0;
    function reverseInorder(node) {
        if (node === null) return;
        // traverse the right subtree first to get the sum of greater nodes
        reverseInorder(node.right);
        // update the node's value by adding the sum of greater nodes
        sum += node.val;
        node.val = sum;
        // traverse the left subtree
        reverseInorder(node.left);
    }
    reverseInorder(root);
    return root;
}

function isBoomerang(points) {
  // calculate the slopes between the first point and the other two points
  let slope1 = (points[1][1] - points[0][1]) * (points[2][0] - points[1][0]);
  let slope2 = (points[2][1] - points[1][1]) * (points[1][0] - points[0][0]);
  // if the slopes are not equal, the points are not in a straight line
  return slope1 !== slope2;
}

function minScoreTriangulation(values) {
    let n = values.length;
    let dp = new Array(n).fill(0).map(() => new Array(n).fill(0));
    for (let length = 2; length < n; length++) {
        for (let i = 0; i < n - length; i++) {
            let j = i + length;
            dp[i][j] = Infinity;
            // calculate the minimum score for the current sub-polygon
            for (let k = i + 1; k < j; k++) {
                // calculate the score for the current triangle and add it to the scores of the remaining sub-polygons
                dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + values[i] * values[k] * values[j]);
            }
        }
    }
    return dp[0][n - 1];
}

function numMovesStonesII(stones) {
    stones.sort((a, b) => a - b);
    const n = stones.length;
    const maxMoves = Math.max(stones[n-1]-stones[1]-(n-2), stones[n-2]-stones[0]-(n-2));
    let minMoves = n;
    let i = 0;
    for (let j = 0; j < n; j++) {
        while (stones[j] - stones[i] + 1 > n) i++;
        const count = j - i + 1;
        if (count === n - 1 && stones[j] - stones[i] + 1 === n - 1) {
            minMoves = Math.min(minMoves, 2);
        } else {
            minMoves = Math.min(minMoves, n - count);
        }
    }
    return [minMoves, maxMoves];
}

function isEscapePossible(blocked, source, target) {
  const BOUND = 20000;
  const blockedSet = new Set(blocked.map(([x, y]) => x + ',' + y));
  function bfs(start, end) {
    const visited = new Set([start.join(',')]);
    const queue = [start];
    let qi = 0;
    while (qi < queue.length) {
      const [x, y] = queue[qi++];
      if (x === end[0] && y === end[1]) return true;
      if (visited.size > BOUND) return true;
      for (const [dx, dy] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
        const nx = x + dx, ny = y + dy;
        const key = nx + ',' + ny;
        if (nx >= 0 && nx < 1000000 && ny >= 0 && ny < 1000000 && !blockedSet.has(key) && !visited.has(key)) {
          visited.add(key);
          queue.push([nx, ny]);
        }
      }
    }
    return false;
  }
  return bfs(source, target) && bfs(target, source);
}

function gardenNoAdj(n, paths) {
    // Create an adjacency list to represent the graph
    let graph = Array.from({length: n}, () => []);
    for (let [x, y] of paths) {
        graph[x - 1].push(y - 1);
        graph[y - 1].push(x - 1);
    }

    // Initialize the result array with zeros
    let result = new Array(n).fill(0);

    // Iterate over each garden
    for (let i = 0; i < n; i++) {
        // Initialize a set to store the flower types used by adjacent gardens
        let used = new Set();
        for (let j of graph[i]) {
            // Add the flower type used by each adjacent garden to the set
            used.add(result[j]);
        }
        // Choose the first available flower type
        for (let j = 1; j <= 4; j++) {
            if (!used.has(j)) {
                // Assign the chosen flower type to the current garden
                result[i] = j;
                break;
            }
        }
    }

    return result;
}

function isRobotBounded(instructions) {
    let x = 0, y = 0, direction = 0; // 0: north, 1: east, 2: south, 3: west
    for (let i = 0; i < instructions.length; i++) {
        // check each instruction and update the position and direction accordingly
        if (instructions[i] === 'G') {
            if (direction === 0) y++; // move north
            else if (direction === 1) x++; // move east
            else if (direction === 2) y--; // move south
            else if (direction === 3) x--; // move west
        } else if (instructions[i] === 'L') {
            direction = (direction + 3) % 4; // turn left
        } else if (instructions[i] === 'R') {
            direction = (direction + 1) % 4; // turn right
        }
    }
    // if the robot ends up back at the origin or is not facing north, it is bounded
    return x === 0 && y === 0 || direction !== 0;
}

function maxSumAfterPartitioning(arr, k) {
  let n = arr.length;
  let dp = new Array(n + 1).fill(0);
  for (let i = 1; i <= n; i++) {
    let maxVal = 0;
    for (let j = 1; j <= Math.min(i, k); j++) {
      // calculate the maximum value in the current subarray
      maxVal = Math.max(maxVal, arr[i - j]);
      // update dp[i] with the maximum sum
      dp[i] = Math.max(dp[i], dp[i - j] + maxVal * j);
    }
  }
  return dp[n];
}

function lastStoneWeight(stones) {
    while (stones.length > 1) {
        // sort the array in descending order to get the heaviest two stones
        stones.sort((a, b) => b - a);
        // smash the heaviest two stones together
        let x = stones.shift(), y = stones.shift();
        // if the weights are not equal, add the difference back to the array
        if (x !== y) stones.push(Math.abs(x - y));
    }
    // return the weight of the last stone, or 0 if there are no stones left
    return stones.length === 0 ? 0 : stones[0];
}

function removeDuplicates(s) {
  var stack = [];
  // iterate over each character in the string and push it to the stack if it's not equal to the top of the stack
  for (var i = 0; i < s.length; i++) {
    // if the stack is not empty and the top of the stack is equal to the current character, pop the top of the stack
    if (stack.length > 0 && stack[stack.length - 1] === s[i]) {
      stack.pop();
    } else {
      stack.push(s[i]);
    }
  }
  // join all characters in the stack to form the final string
  return stack.join('');
}

function lastStoneWeightII(stones) {
    let totalWeight = 0;
    for (let i = 0; i < stones.length; i++) {
        totalWeight += stones[i];
    }
    let halfWeight = Math.floor(totalWeight / 2);
    let dp = new Array(halfWeight + 1).fill(0);
    // iterate over each stone and update dp array to store maximum weight that can be achieved
    for (let i = 0; i < stones.length; i++) {
        for (let j = halfWeight; j >= stones[i]; j--) {
            // update dp array to store maximum weight that can be achieved
            dp[j] = Math.max(dp[j], dp[j - stones[i]] + stones[i]);
        }
    }
    // return the difference between total weight and twice the maximum weight that can be achieved
    return totalWeight - 2 * dp[halfWeight];
}

function longestStrChain(words) {
    // sort the words by length to ensure we're always checking shorter words first
    words.sort((a, b) => a.length - b.length);

    let dp = {};
    let maxLength = 1;

    // initialize dp with all words having a length of 1
    for (let word of words) {
        dp[word] = 1;
    }

    // for each word, check all possible predecessors
    for (let word of words) {
        for (let i = 0; i < word.length; i++) {
            // create a predecessor by removing one character
            let predecessor = word.slice(0, i) + word.slice(i + 1);
            // if the predecessor exists and the current word's length is greater than the predecessor's length plus one
            if (dp[predecessor] !== undefined) {
                // update the current word's length in the dp table
                dp[word] = Math.max(dp[word], dp[predecessor] + 1);
                // update the maximum length found so far
                maxLength = Math.max(maxLength, dp[word]);
            }
        }
    }

    return maxLength;
}

function longestDupSubstring(s) {
    let left = 1, right = s.length;
    let longest = "";
    // Perform binary search to find the maximum length of the duplicate substring
    while (left <= right) {
        let mid = Math.floor((left + right) / 2);
        let set = new Set();
        let found = false;
        // Generate all substrings of length mid and check for duplicates
        for (let i = 0; i <= s.length - mid; i++) {
            let substr = s.substring(i, i + mid);
            // If the substring is already in the set, it's a duplicate
            if (set.has(substr)) {
                longest = substr;
                found = true;
                break;
            }
            set.add(substr);
        }
        // If a duplicate substring of length mid is found, try to find a longer one
        if (found) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return longest;
}

function prevPermOpt1(arr) {
    let n = arr.length;
    // find the first pair of elements from the right that are in descending order
    for (let i = n - 2; i >= 0; i--) {
        if (arr[i] > arr[i + 1]) {
            // find the largest element to the right of i that is smaller than arr[i]
            let maxIndex = i + 1;
            for (let j = i + 2; j < n; j++) {
                // if a larger element is found, update maxIndex
                if (arr[j] < arr[i] && arr[j] > arr[maxIndex]) {
                    maxIndex = j;
                }
            }
            // swap arr[i] and arr[maxIndex]
            [arr[i], arr[maxIndex]] = [arr[maxIndex], arr[i]];
            return arr;
        }
    }
    // if no such pair is found, return the original array
    return arr;
}

function maxSatisfied(customers, grumpy, minutes) {
    let totalSatisfied = 0;
    let currentGrumpy = 0;
    let maxGrumpy = 0;
    let windowStart = 0;
    // calculate the initial total satisfied and the initial current grumpy
    for (let windowEnd = 0; windowEnd < customers.length; windowEnd++) {
        if (grumpy[windowEnd] === 0) {
            totalSatisfied += customers[windowEnd];
        } else {
            currentGrumpy += customers[windowEnd];
        }
        // when the window size is larger than minutes, shrink the window
        if (windowEnd >= minutes - 1) {
            maxGrumpy = Math.max(maxGrumpy, currentGrumpy);
            if (grumpy[windowStart] === 1) {
                currentGrumpy -= customers[windowStart];
            }
            windowStart++;
        }
    }
    // return the total satisfied plus the max grumpy
    return totalSatisfied + maxGrumpy;
}

function rearrangeBarcodes(barcodes) {
    // Create a frequency map to store the frequency of each barcode
    let frequencyMap = {};
    for (let barcode of barcodes) {
        // Count the frequency of each barcode
        frequencyMap[barcode] = (frequencyMap[barcode] || 0) + 1;
    }

    // Create a max heap to store the barcodes and their frequencies
    let maxHeap = [];
    for (let barcode in frequencyMap) {
        // Push the barcode and its frequency into the max heap
        maxHeap.push([parseInt(barcode), frequencyMap[barcode]]);
    }
    maxHeap.sort((a, b) => b[1] - a[1]);

    // Initialize the result array
    let result = new Array(barcodes.length);
    let index = 0;

    // While the max heap is not empty
    while (maxHeap.length > 0) {
        // Get the barcode with the highest frequency
        let [barcode1, frequency1] = maxHeap.shift();
        // If the max heap is not empty, get the next barcode with the highest frequency
        if (maxHeap.length > 0) {
            let [barcode2, frequency2] = maxHeap.shift();
            // Place the two barcodes in the result array
            result[index++] = barcode1;
            result[index++] = barcode2;
            // If the frequencies of the two barcodes are greater than 1, decrement their frequencies and push them back into the max heap
            if (frequency1 > 1) maxHeap.push([barcode1, frequency1 - 1]);
            if (frequency2 > 1) maxHeap.push([barcode2, frequency2 - 1]);
            // Sort the max heap to maintain the order
            maxHeap.sort((a, b) => b[1] - a[1]);
        } else {
            // If the max heap only contains one barcode, place it in the result array
            result[index++] = barcode1;
        }
    }
    return result;
}

function smallestEquivalentString(s1, s2, baseStr) {
    let parent = {};
    // initialize the parent map with each character as its own parent
    for (let i = 0; i < 26; i++) {
        let char = String.fromCharCode('a'.charCodeAt(0) + i);
        parent[char] = char;
    }

    // union the characters in s1 and s2
    for (let i = 0; i < s1.length; i++) {
        let char1 = s1[i];
        let char2 = s2[i];
        union(parent, char1, char2);
    }

    // find the lexicographically smallest equivalent string of baseStr
    let result = '';
    for (let i = 0; i < baseStr.length; i++) {
        let char = baseStr[i];
        // find the smallest character in the same group as char
        result += find(parent, char);
    }

    return result;
}

function find(parent, char) {
    // if char is not its own parent, find its parent
    if (parent[char] !== char) {
        // path compression
        parent[char] = find(parent, parent[char]);
    }
    return parent[char];
}

function union(parent, char1, char2) {
    // find the parents of char1 and char2
    let parent1 = find(parent, char1);
    let parent2 = find(parent, char2);
    // make the smaller character the parent
    if (parent1 < parent2) {
        parent[parent2] = parent1;
    } else {
        parent[parent1] = parent2;
    }
}

function gcdOfStrings(str1, str2) {
    // check if the concatenation of str1 and str2 is equal to the concatenation of str2 and str1
    if (str1 + str2 !== str2 + str1) return "";

    // calculate the greatest common divisor of the lengths of str1 and str2
    function gcd(a, b) {
        if (b === 0) return a;
        return gcd(b, a % b);
    }

    // calculate the greatest common divisor of the lengths of str1 and str2
    let gcdLength = gcd(str1.length, str2.length);

    // return the substring of str1 with the length of the greatest common divisor
    return str1.substring(0, gcdLength);
}

function maxEqualRowsAfterFlips(matrix) {
    let countMap = {};
    let maxCount = 0;
    // Create a normalized version of each row by flipping all bits if the first bit is 1
    for (let row of matrix) {
        // Flip the row if the first element is 1 to normalize it
        let normalizedRow = row[0] === 1 ? row.map(x => 1 - x) : row;
        // Convert the row to a string to use as a key in the map
        let rowKey = normalizedRow.join('');
        // Increment the count for this row in the map
        countMap[rowKey] = (countMap[rowKey] || 0) + 1;
        // Update the max count if this row's count is higher
        maxCount = Math.max(maxCount, countMap[rowKey]);
    }
    return maxCount;
}

function addNegabinary(arr1, arr2) {
    let carry = 0, result = [];
    let i = arr1.length - 1, j = arr2.length - 1;
    while (i >= 0 || j >= 0 || carry !== 0) {
        let sum = carry + (i >= 0 ? arr1[i] : 0) + (j >= 0 ? arr2[j] : 0);
        const digit = ((sum % 2) + 2) % 2;
        result.push(digit);
        carry = (sum - digit) / -2;
        i--; j--;
    }
    while (result.length > 1 && result[result.length - 1] === 0) result.pop();
    return result.reverse();
}

function sufficientSubset(root, limit) {
    if (!root) return null;
    if (!root.left && !root.right) {
        return root.val < limit ? null : root;
    }
    if (root.left) root.left = sufficientSubset(root.left, limit - root.val);
    if (root.right) root.right = sufficientSubset(root.right, limit - root.val);
    if (!root.left && !root.right) return null;
    return root;
}

function numberOfSubmatricesThatSumToTarget(matrix, target) {
    let count = 0;
    let rows = matrix.length;
    let cols = matrix[0].length;
    // generate prefix sum for each row
    for (let i = 0; i < rows; i++) {
        for (let j = 1; j < cols; j++) {
            matrix[i][j] += matrix[i][j - 1];
        }
    }
    // calculate sum for each possible submatrix
    for (let left = 0; left < cols; left++) {
        for (let right = left; right < cols; right++) {
            let sumMap = new Map();
            sumMap.set(0, 1);
            let currentSum = 0;
            for (let i = 0; i < rows; i++) {
                // calculate sum of current submatrix
                currentSum += matrix[i][right] - (left > 0 ? matrix[i][left - 1] : 0);
                // check if there is a sum that equals to currentSum - target
                count += sumMap.get(currentSum - target) || 0;
                // update sumMap
                sumMap.set(currentSum, (sumMap.get(currentSum) || 0) + 1);
            }
        }
    }
    return count;
}

function numTilePossibilities(tiles) {
    let count = 0;
    let tileCounts = {};
    for (let tile of tiles) {
        if (tileCounts[tile]) tileCounts[tile]++;
        else tileCounts[tile] = 1;
    }
    function backtrack() {
        // iterate over each unique tile and recursively generate all possible sequences
        for (let tile in tileCounts) {
            if (tileCounts[tile] > 0) {
                count++;
                tileCounts[tile]--;
                backtrack();
                tileCounts[tile]++;
            }
        }
    }
    backtrack();
    return count;
}

function smallestSubsequence(s) {
    let lastOccurrence = {};
    for (let i = 0; i < s.length; i++) {
        lastOccurrence[s[i]] = i;
    }
    let stack = [];
    let seen = {};
    for (let i = 0; i < s.length; i++) {
        // if the character is already in the stack, skip it
        if (seen[s[i]]) continue;
        // while the stack is not empty and the top of the stack is greater than the current character and the top of the stack appears later in the string
        while (stack.length > 0 && stack[stack.length - 1] > s[i] && lastOccurrence[stack[stack.length - 1]] > i) {
            // remove the top of the stack and mark it as unseen
            seen[stack.pop()] = false;
        }
        // add the current character to the stack and mark it as seen
        stack.push(s[i]);
        seen[s[i]] = true;
    }
    return stack.join('');
}

function largestValuesFromLabels(values, labels, numWanted, useLimit) {
    // Create a list of items with their values and labels
    let items = values.map((value, index) => ({ value, label: labels[index] }));

    // Sort the items in descending order of their values
    items.sort((a, b) => b.value - a.value);

    let labelCount = {};
    let sum = 0;

    // Iterate over the sorted items and add them to the sum if their label count is less than the use limit
    for (let item of items) {
        // Check if the item's label count is less than the use limit
        if (!labelCount[item.label] || labelCount[item.label] < useLimit) {
            sum += item.value;
            // Increment the label count
            labelCount[item.label] = (labelCount[item.label] || 0) + 1;
            // Decrement the number of items wanted
            numWanted--;
            // If we have found the required number of items, break the loop
            if (numWanted === 0) break;
        }
    }

    return sum;
}

function duplicateZeros(arr) {
