function parseBoolExpr(expression) {
    // base case: if the expression is a single character, return its boolean value
    if (expression.length === 1) return expression === 't';

    // get the operator and the operands
    let operator = expression[0];
    let operands = [];
    let count = 0;
    let temp = '';
    for (let i = 2; i < expression.length - 1; i++) {
        // if we encounter an opening parenthesis, increment the count
        if (expression[i] === '(') count++;
        // if we encounter a comma and the count is 0, it means we've reached the end of an operand
        else if (expression[i] === ',' && count === 0) {
            operands.push(temp);
            temp = '';
        }
        // if we encounter a closing parenthesis, decrement the count
        else if (expression[i] === ')') count--;
        // if we encounter a character that is not a parenthesis or a comma, add it to the current operand
        else if (expression[i] !== ',') temp += expression[i];
    }
    // add the last operand to the list
    operands.push(temp);

    // evaluate the expression based on the operator
    if (operator === '!') return !parseBoolExpr(operands[0]);
    else if (operator === '&') {
        // evaluate the expression as an AND operation
        for (let operand of operands) {
            // if any of the operands is false, return false
            if (!parseBoolExpr(operand)) return false;
        }
        return true;
    } else if (operator === '|') {
        // evaluate the expression as an OR operation
        for (let operand of operands) {
            // if any of the operands is true, return true
            if (parseBoolExpr(operand)) return true;
        }
        return false;
    }
}

function delNodes(root, to_delete) {
    let result = [];
    let set = new Set(to_delete);
    function dfs(node) {
        // if the node is null, return null
        if (!node) return null;
        // if the node's value is in the set, delete the node and return the children
        if (set.has(node.val)) {
            // recursively call dfs on the left and right children
            let left = dfs(node.left);
            let right = dfs(node.right);
            // if the left child is not null, add it to the result
            if (left) result.push(left);
            // if the right child is not null, add it to the result
            if (right) result.push(right);
            // return null to indicate the node is deleted
            return null;
        } else {
            // if the node's value is not in the set, recursively call dfs on the children
            node.left = dfs(node.left);
            node.right = dfs(node.right);
            // return the node
            return node;
        }
    }
    // call dfs on the root
    let newRoot = dfs(root);
    // if the new root is not null, add it to the result
    if (newRoot) result.push(newRoot);
    return result;
}

