function relativeSortArray(arr1, arr2) {
    // Create a hash map to store the frequency of elements in arr1
    let frequencyMap = {};
    for (let num of arr1) {
        // Increment the frequency of each element in the map
        frequencyMap[num] = (frequencyMap[num] || 0) + 1;
    }

    let result = [];
    // Iterate over arr2 and append elements to the result array based on their frequency in arr1
    for (let num of arr2) {
        // Append the element to the result array as many times as its frequency in arr1
        while (frequencyMap[num] > 0) {
            result.push(num);
            frequencyMap[num]--;
        }
    }

    // Append the remaining elements in arr1 to the result array in ascending order
    for (let num in frequencyMap) {
        // Check if the frequency of the element is greater than 0
        if (frequencyMap[num] > 0) {
            // Append the element to the result array as many times as its frequency in arr1
            while (frequencyMap[num] > 0) {
                result.push(parseInt(num));
                frequencyMap[num]--;
            }
        }
    }

    return result;
}

function lcaDeepestLeaves(root) {
    let maxDepth = -1;
    let lca = null;
    function dfs(node, depth) {
        if (!node.left && !node.right && depth > maxDepth) {
            maxDepth = depth;
            lca = node;
        }
        if (node.left) dfs(node.left, depth + 1);
        if (node.right) dfs(node.right, depth + 1);
        if (node.left && node.right && depth + 1 === maxDepth) {
            lca = node;
        }
    }
    dfs(root, 0);
    return lca;
}

function longestWPI(hours) {
