    for (let i = 0; i < hours.length; i++) {
        score += hours[i] > 8 ? 1 : -1;
        if (score > 0) {
            maxLength = i + 1;
        } else if ((score - 1) in seen) {
            maxLength = Math.max(maxLength, i - seen[score - 1]);
        }
        if (!(score in seen)) seen[score] = i;
    }
    return maxLength;
}

function smallestSufficientTeam(req_skills, people) {
    let n = req_skills.length;
    let m = people.length;
    let skillToIndex = {};
    for (let i = 0; i < n; i++) {
        skillToIndex[req_skills[i]] = i;
    }
    let dp = new Array(1 << n).fill(null).map(() => new Array(m + 1).fill(null));
    for (let i = 0; i < m; i++) {
        let skillSet = 0;
        for (let skill of people[i]) {
            skillSet |= (1 << skillToIndex[skill]);
        }
        dp[skillSet][i] = [i];
    }
    for (let mask = 0; mask < (1 << n); mask++) {
        for (let i = 0; i < m; i++) {
            if (dp[mask][i] === null) continue;
            for (let j = i + 1; j < m; j++) {
                let newMask = mask | getSkillSet(people[j], skillToIndex);
                if (dp[newMask][j + 1] === null || dp[newMask][j + 1].length > dp[mask][i].length + 1) {
                    dp[newMask][j + 1] = dp[mask][i].concat([j]);
                }
            }
        }
    }
    let minSize = Infinity;
    let result = null;
    for (let i = 0; i <= m; i++) {
        if (dp[(1 << n) - 1][i] !== null && dp[(1 << n) - 1][i].length < minSize) {
            minSize = dp[(1 << n) - 1][i].length;
            result = dp[(1 << n) - 1][i];
        }
    }
    return result;
}

function getSkillSet(person, skillToIndex) {
    let skillSet = 0;
    for (let skill of person) {
        skillSet |= (1 << skillToIndex[skill]);
    }
    return skillSet;
}

function maxAbsValExpr(arr1, arr2) {
    let maxVal = 0;
    // iterate over all pairs of indices to calculate the expression
    for (let i = 0; i < arr1.length; i++) {
        for (let j = 0; j < arr1.length; j++) {
            // calculate the absolute value expression
            let val = Math.abs(arr1[i] - arr1[j]) + Math.abs(arr2[i] - arr2[j]) + Math.abs(i - j);
            // update maxVal if the current value is larger
            maxVal = Math.max(maxVal, val);
        }
    }
    return maxVal;
}

function numEquivDominoPairs(dominoes) {
    let count = 0;
    let dominoMap = {};
    // Create a map to store the frequency of each domino
    for (let i = 0; i < dominoes.length; i++) {
        let a = dominoes[i][0];
        let b = dominoes[i][1];
        let key = Math.min(a, b) + ',' + Math.max(a, b);
        // Use a consistent key for each domino, regardless of order
        if (key in dominoMap) {
            dominoMap[key]++;
        } else {
            dominoMap[key] = 1;
        }
    }
    // Calculate the number of pairs for each domino
    for (let key in dominoMap) {
        let freq = dominoMap[key];
        // Use the formula n*(n-1)/2 to calculate the number of pairs
        count += freq * (freq - 1) / 2;
    }
    return count;
}

function mctFromLeafValues(arr) {
    let result = 0;
    let stack = [Infinity];
    // iterate through the array and calculate the minimum cost tree
    for (let num of arr) {
        // while the current number is smaller than the top of the stack, pop the stack and calculate the cost
        while (stack[stack.length - 1] <= num) {
            let mid = stack.pop();
            // calculate the cost by multiplying the minimum of the top two elements in the stack with the popped element
            result += mid * Math.min(stack[stack.length - 1], num);
        }
        // push the current number into the stack
        stack.push(num);
    }
    // calculate the cost for the remaining elements in the stack
    for (let i = 1; i < stack.length - 1; i++) {
        // calculate the cost by multiplying the current element with the next element in the stack
        result += stack[i] * stack[i + 1];
    }
    return result;
}

function shortestAlternatingPaths(n, redEdges, blueEdges) {
    // Create adjacency list for red and blue edges
    let redGraph = Array.from({ length: n }, () => []), blueGraph = Array.from({ length: n }, () => []);
    for (let [u, v] of redEdges) redGraph[u].push(v);
    for (let [u, v] of blueEdges) blueGraph[u].push(v);

    // Initialize result array and queue for BFS
    let result = Array(n).fill(-1), queue = [[0, 0, true], [0, 0, false]];
    result[0] = 0;

    // Perform BFS
    while (queue.length) {
        let [node, len, isRed] = queue.shift();
        // Explore neighbors of the current node with the opposite color
        if (isRed) {
            for (let neighbor of blueGraph[node]) {
                if (result[neighbor] === -1) {
                    result[neighbor] = len + 1;
                    queue.push([neighbor, len + 1, false]);
                }
            }
        } else {
            for (let neighbor of redGraph[node]) {
                if (result[neighbor] === -1) {
                    result[neighbor] = len + 1;
                    queue.push([neighbor, len + 1, true]);
                }
            }
        }
    }
    return result;
}

function tribonacci(n) {
    if (n === 0) return 0;
    if (n === 1 || n === 2) return 1;
    // initialize an array to store the Tribonacci sequence
    let tribonacciSequence = [0, 1, 1];
    // calculate the Tribonacci sequence up to the nth number
    for (let i = 3; i <= n; i++) 
        // calculate the next number as the sum of the previous three numbers
        tribonacciSequence.push(tribonacciSequence[i-1] + tribonacciSequence[i-2] + tribonacciSequence[i-3]);
    // return the nth Tribonacci number
    return tribonacciSequence[n];
}

function alphabetBoardPath(target) {
    const board = ["abcde", "fghij", "klmno", "pqrst", "uvwxy", "z"];
    const positionMap = {};
    for (let i = 0; i < board.length; i++) {
        for (let j = 0; j < board[i].length; j++) {
            positionMap[board[i][j]] = [i, j];
        }
    }
    let result = "";
    let currX = 0, currY = 0;
    for (let i = 0; i < target.length; i++) {
        const char = target[i];
        const [nextX, nextY] = positionMap[char];
        // move Up/Left before Down/Right - required so we never step onto an
        // invalid column while passing through row 5 (which only has 'z' at col 0)
        if (nextX < currX) result += 'U'.repeat(currX - nextX);
        if (nextY < currY) result += 'L'.repeat(currY - nextY);
        if (nextX > currX) result += 'D'.repeat(nextX - currX);
        if (nextY > currY) result += 'R'.repeat(nextY - currY);
        result += '!';
        currX = nextX;
        currY = nextY;
    }
    return result;
}

function stoneGameII(piles) {
  let n = piles.length;
  let suffixSum = new Array(n + 1).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    suffixSum[i] = suffixSum[i + 1] + piles[i];
  }
  let memo = new Array(n).fill(0).map(() => new Array(n + 1).fill(-1));
  function dp(i, m) {
    if (i + 2 * m >= n) return suffixSum[i];
    if (memo[i][m] !== -1) return memo[i][m];
    // the current player wants to MAXIMIZE their own take, not minimize it
    let best = -Infinity;
    for (let x = 1; x <= 2 * m; x++) {
      let score = suffixSum[i] - dp(i + x, Math.max(m, x));
      best = Math.max(best, score);
    }
    memo[i][m] = best;
    return best;
  }
  // dp(0,1) already IS Alice's best total, not suffixSum[0] minus it
  return dp(0, 1);
}

function movesToMakeZigzag(nums) {
    const n = nums.length;
    function cost(parity) {
        // decrease every index with i % 2 === parity so it's strictly less than both neighbors
        let total = 0;
        for (let i = 0; i < n; i++) {
            if (i % 2 !== parity) continue;
            let neighborMin = Infinity;
            if (i > 0) neighborMin = Math.min(neighborMin, nums[i - 1]);
            if (i < n - 1) neighborMin = Math.min(neighborMin, nums[i + 1]);
            if (neighborMin === Infinity) continue;
            total += Math.max(0, nums[i] - neighborMin + 1);
        }
        return total;
    }
    return Math.min(cost(0), cost(1));
}

function longestCommonSubsequence(text1, text2) {
    let dp = Array(text1.length + 1).fill(0).map(() => Array(text2.length + 1).fill(0));
    // iterate over both strings and update dp table when characters match
    for (let i = 1; i <= text1.length; i++) {
        for (let j = 1; j <= text2.length; j++) {
            // if current characters in both strings are the same, update dp table
            if (text1[i - 1] === text2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1] + 1;
            } else {
                // otherwise, take the maximum value from the previous cells
                dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
            }
        }
    }
    // the length of the longest common subsequence is stored in the last cell of the dp table
    return dp[text1.length][text2.length];
}

function longestDecomposition(text) {
  const n = text.length;
  if (n === 0) return 0;
  for (let len = 1; len <= Math.floor(n / 2); len++) {
    if (text.slice(0, len) === text.slice(n - len)) {
      return 2 + longestDecomposition(text.slice(len, n - len));
    }
  }
  return 1;
}

function btreeGameWinningMove(root, n, x) {
    let targetNode = null;
    function findTarget(node) {
        if (!node) return;
        if (node.val === x) { targetNode = node; return; }
        findTarget(node.left);
        findTarget(node.right);
    }
    findTarget(root);
    function countSize(node) {
        if (!node) return 0;
        return 1 + countSize(node.left) + countSize(node.right);
    }
    const leftCount = countSize(targetNode.left);
    const rightCount = countSize(targetNode.right);
    const parentCount = n - leftCount - rightCount - 1;
    const half = n / 2;
    return leftCount > half || rightCount > half || parentCount > half;
}

function SnapshotArray(length) {
    // Initialize the current snapshot id and the map to store snapshots
    let currentId = 0;
    let snapshots = new Map();
    for (let i = 0; i < length; i++) {
        snapshots.set(i, []);
    }

    return {
        set: function(index, val) {
            // Update the value at the given index for the current snapshot id
            snapshots.get(index).push([currentId, val]);
        },
        snap: function() {
            // Increment the current snapshot id
            currentId++;
            return currentId - 1;
        },
        get: function(index, snap_id) {
            // Find the most recent value at the given index that is less than or equal to the given snapshot id
            let values = snapshots.get(index);
            let left = 0, right = values.length - 1;
            while (left <= right) {
                // Perform binary search to find the most recent value
                let mid = Math.floor((left + right) / 2);
                if (values[mid][0] <= snap_id) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }
            // Return the value at the found index, or 0 if no such value exists
            return right >= 0 ? values[right][1] : 0;
        }
    };
}

// TIME: O(1) for set and snap, O(log n) for get where n is the number of updates for a given index 
// SPACE: O(n) where n is the total number of updates across all indices

function numRollsToTarget(n, k, target) {
    const MOD = 1000000007;
    const dp = Array(n + 1).fill(0).map(() => Array(target + 1).fill(0));
    dp[0][0] = 1; // base case: one way to get a sum of 0 with 0 dice
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= target; j++) {
            // for each possible face value of the current die, add the number of ways to get the remaining sum with the remaining dice
            for (let face = 1; face <= k && j - face >= 0; face++) {
                dp[i][j] = (dp[i][j] + dp[i - 1][j - face]) % MOD; // accumulate the number of ways and apply modulo
            }
        }
    }
    return dp[n][target];
}

function maxRepOpt1(text) {
    const n = text.length;
    const counts = {};
    for (const c of text) counts[c] = (counts[c] || 0) + 1;
    const groups = [];
    let i = 0;
    while (i < n) {
        let j = i + 1;
        while (j < n && text[j] === text[i]) j++;
        groups.push([text[i], j - i]);
        i = j;
    }
    let maxLen = 0;
    for (let idx = 0; idx < groups.length; idx++) {
        const [ch, len] = groups[idx];
        // extend this run by 1 if there's a spare same char elsewhere to swap in
        let cand = len + (counts[ch] > len ? 1 : 0);
        maxLen = Math.max(maxLen, Math.min(cand, counts[ch]));
        // merge two same-char runs separated by exactly one different char
        if (idx + 2 < groups.length && groups[idx + 1][1] === 1 && groups[idx][0] === groups[idx + 2][0]) {
            let merged = groups[idx][1] + groups[idx + 2][1];
            merged += (counts[ch] > merged) ? 1 : 0;
            maxLen = Math.max(maxLen, Math.min(merged, counts[ch]));
        }
    }
    return maxLen;
}

function MajorityChecker(arr, threshold) {
    function query(left, right) {
        // count occurrences of each element in the subarray
        let counts = {};
        for (let i = left; i <= right; i++) {
            counts[arr[i]] = (counts[arr[i]] || 0) + 1;
        }
        // find the majority element
        for (let num in counts) {
            // check if the count of the current element meets the threshold
            if (counts[num] >= threshold) {
                return parseInt(num);
            }
        }
        // if no majority element is found, return -1
        return -1;
    }
    return query;
}

function countCharacters(words, chars) {
  let totalLength = 0;
  let charsCount = {};
  for (let char of chars) {
    if (!charsCount[char]) charsCount[char] = 0;
    charsCount[char]++;
  }

  for (let word of words) {
    let wordCount = {};
    let canBeFormed = true;
    for (let char of word) {
      if (!wordCount[char]) wordCount[char] = 0;
      wordCount[char]++;
      // must default missing chars to 0, not undefined (undefined comparisons are always false in JS)
      if (wordCount[char] > (charsCount[char] || 0)) {
        canBeFormed = false;
        break;
      }
    }
    if (canBeFormed) totalLength += word.length;
  }
  return totalLength;
}

function lastSubstring(s) {
  let maxLength = 0;
  let maxSubstring = '';
  for (let i = 0; i < s.length; i++) {
    for (let j = i + 1; j <= s.length; j++) {
      let currentSubstring = s.substring(i, j);
      // if current substring is lexicographically larger than max substring, update max substring
      if (currentSubstring > maxSubstring) {
        maxSubstring = currentSubstring;
      }
    }
  }
  return maxSubstring;
}

function largest1BorderedSquare(grid) {
    let rows = grid.length;
    let cols = grid[0].length;
    let maxSideLength = Math.min(rows, cols);
    let maxArea = 0;

    for (let sideLength = 1; sideLength <= maxSideLength; sideLength++) {
        // check all possible subgrids of the given side length
        for (let i = 0; i <= rows - sideLength; i++) {
            for (let j = 0; j <= cols - sideLength; j++) {
                // check if the current subgrid has all 1s on its border
                if (hasAllOnesOnBorder(grid, i, j, sideLength)) {
                    // update the maximum area if the current subgrid is larger
                    maxArea = Math.max(maxArea, sideLength * sideLength);
                }
            }
        }
    }

    return maxArea;
}

function hasAllOnesOnBorder(grid, row, col, sideLength) {
    // check the top and bottom borders
    for (let i = col; i < col + sideLength; i++) {
        // check if the top or bottom border has a 0
        if (grid[row][i] === 0 || grid[row + sideLength - 1][i] === 0) {
            return false;
        }
    }

    // check the left and right borders
    for (let i = row; i < row + sideLength; i++) {
        // check if the left or right border has a 0
        if (grid[i][col] === 0 || grid[i][col + sideLength - 1] === 0) {
            return false;
        }
    }

    return true;
}

function maxLevelSum(root) {
    if (!root) return 0;
    let maxSum = -Infinity, maxLevel = 0, level = 0;
    let queue = [root];
    while (queue.length) {
        level++; // increment the level
        let sum = 0, size = queue.length;
        for (let i = 0; i < size; i++) {
            let node = queue.shift(); // remove the node from the queue
            sum += node.val; // add the node value to the sum
            if (node.left) queue.push(node.left); // add the left child to the queue
            if (node.right) queue.push(node.right); // add the right child to the queue
        }
        if (sum > maxSum) { // update the max sum and level if current sum is greater
            maxSum = sum;
            maxLevel = level;
        }
    }
    return maxLevel;
}

function dayOfYear(date) {
    var year = parseInt(date.substring(0, 4));
    var month = parseInt(date.substring(5, 7));
    var day = parseInt(date.substring(8, 10));
    // calculate the total days of the previous months
    var daysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    if (isLeapYear(year)) daysInMonth[1] = 29;
    var totalDays = 0;
    for (var i = 0; i < month - 1; i++) {
        totalDays += daysInMonth[i];
    }
    // add the current day to get the day of the year
    return totalDays + day;
}

function isLeapYear(year) {
    return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
}

function numSmallerByFrequency(queries, words) {
    function f(s) {
        // find the lexicographically smallest character and its frequency
        let minChar = 'z';
        let minCount = 0;
        for (let i = 0; i < s.length; i++) {
            if (s[i] < minChar) {
                minChar = s[i];
                minCount = 1;
            } else if (s[i] === minChar) {
                minCount++;
            }
        }
        return minCount;
    }

    let result = [];
    for (let query of queries) {
        let count = 0;
        // count the number of words where f(query) is smaller than f(word)
        for (let word of words) {
            if (f(query) < f(word)) {
                count++;
            }
        }
        result.push(count);
    }
    return result;
}

function invalidTransactions(transactions) {
    let result = [];
    let transactionMap = {};
    // Create a map to store transactions for each person
    for (let i = 0; i < transactions.length; i++) {
        let [name, time, amount, city] = transactions[i].split(",");
        if (!transactionMap[name]) transactionMap[name] = [];
        transactionMap[name].push([time, amount, city, i]);
    }
    // Check each transaction for possible invalidity
    for (let name in transactionMap) {
        for (let i = 0; i < transactionMap[name].length; i++) {
            let [time, amount, city, index] = transactionMap[name][i];
            // Check if the transaction amount is greater than 1000
            if (amount > 1000) result.push(transactions[index]);
            // Check if there are transactions within 60 minutes in a different city
            for (let j = 0; j < transactionMap[name].length; j++) {
                if (i !== j) {
                    let [time2, amount2, city2, index2] = transactionMap[name][j];
                    if (Math.abs(time - time2) <= 60 && city !== city2) {
                        if (!result.includes(transactions[index])) result.push(transactions[index]);
                        if (!result.includes(transactions[index2])) result.push(transactions[index2]);
                    }
                }
            }
        }
    }
    return result;
}

function maxDistance(grid) {
    const n = grid.length;
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let queue = [];
    let hasWater = false;

    // initialize queue with all land cells
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                queue.push([i, j, 0]);
            } else {
                hasWater = true;
            }
        }
    }

    // if no land or water exists, return -1
    if (queue.length === 0 || !hasWater) {
        return -1;
    }

    let maxDistance = 0;

    // perform BFS
    while (queue.length > 0) {
        const [x, y, distance] = queue.shift();
        maxDistance = Math.max(maxDistance, distance);
        // explore all neighboring cells
        for (const [dx, dy] of directions) {
            const nx = x + dx;
            const ny = y + dy;
            // if neighboring cell is within bounds and is water, mark it as visited and add it to the queue
            if (nx >= 0 && nx < n && ny >= 0 && ny < n && grid[nx][ny] === 0) {
                grid[nx][ny] = -1; // mark as visited
                queue.push([nx, ny, distance + 1]);
            }
        }
    }

    return maxDistance;
}

function canMakePali(s, queries) {
    function isPaliPossible(substring, k) {
        let charCount = {};
        for (let char of substring) {
            if (!charCount[char]) charCount[char] = 0;
            charCount[char]++;
        }
        let oddCount = 0;
        for (let count in charCount) {
            if (charCount[count] % 2 !== 0) oddCount++;
        }
        // minimum replacements needed = floor(oddCount / 2)
        return Math.floor(oddCount / 2) <= k;
    }

    let result = [];
    for (let query of queries) {
        let substring = s.slice(query[0], query[1] + 1);
        let k = query[2];
        result.push(isPaliPossible(substring, k));
    }
    return result;
}

function removeZeroSumSublists(head) {
    let dummy = { next: head };
    let prefix = 0;
    let seen = { 0: dummy };
    // iterate through the list to calculate prefix sum and store nodes in hash map
    while (head) {
        prefix += head.val;
        // if prefix sum is found in hash map, it means we have a zero sum sublist
        if (prefix in seen) {
            let node = seen[prefix];
            let tmp = node.next;
            let tmpPrefix = prefix + tmp.val;
            // remove nodes from hash map that are part of the zero sum sublist
            while (tmp !== head) {
                delete seen[tmpPrefix];
                tmp = tmp.next;
                tmpPrefix += tmp.val;
            }
            // remove the zero sum sublist from the linked list
            node.next = head.next;
        } else {
            // if prefix sum is not found in hash map, add it
            seen[prefix] = head;
        }
        head = head.next;
    }
    return dummy.next;
}

function numPrimeArrangements(n) {
    // create a helper function to check if a number is prime
    function isPrime(num) {
        if (num <= 1) return false;
        for (let i = 2; i * i <= num; i++) {
            if (num % i === 0) return false;
        }
        return true;
    }

    // count the number of prime numbers from 1 to n
    let primeCount = 0;
    for (let i = 1; i <= n; i++) {
        if (isPrime(i)) primeCount++;
    }

    // calculate the number of permutations for prime and non-prime numbers separately
    let primePermutations = 1;
    let nonPrimePermutations = 1;
    for (let i = 1; i <= primeCount; i++) {
        primePermutations = (primePermutations * i) % (1e9 + 7);
    }
    for (let i = 1; i <= n - primeCount; i++) {
        nonPrimePermutations = (nonPrimePermutations * i) % (1e9 + 7);
    }

    // return the total number of permutations
    return (primePermutations * nonPrimePermutations) % (1e9 + 7);
}

// TIME: O(n*sqrt(n)) SPACE: O(1)

function findNumOfValidWords(words, puzzles) {
    let result = new Array(puzzles.length).fill(0);
    let wordMap = {};
    // Create a hashmap to store the words with their corresponding bitmask
    for (let word of words) {
        let bitmask = 0;
        for (let char of word) {
            // Calculate the bitmask for the word
            bitmask |= 1 << (char.charCodeAt(0) - 'a'.charCodeAt(0));
        }
        if (!wordMap[bitmask]) wordMap[bitmask] = 0;
        wordMap[bitmask]++;
    }
    // Iterate over each puzzle
    for (let i = 0; i < puzzles.length; i++) {
        let puzzleBitmask = 0;
        for (let char of puzzles[i]) {
            // Calculate the bitmask for the puzzle
            puzzleBitmask |= 1 << (char.charCodeAt(0) - 'a'.charCodeAt(0));
        }
        let submask = puzzleBitmask;
        // Generate all possible submasks of the puzzle bitmask
        while (submask > 0) {
            // Check if the submask is present in the wordMap and the first letter of the puzzle is in the submask
            if (wordMap[submask] && (submask & (1 << (puzzles[i][0].charCodeAt(0) - 'a'.charCodeAt(0)))) !== 0) {
                result[i] += wordMap[submask];
            }
            // Generate the next submask
            submask = (submask - 1) & puzzleBitmask;
        }
    }
    return result;
}

function distanceBetweenBusStops(distance, start, destination) {
    if (start > destination) {
        // Swap start and destination to ensure start is less than destination
        [start, destination] = [destination, start];
    }
    let clockwiseDistance = 0;
    // Calculate the distance between start and destination in the clockwise direction
    for (let i = start; i < destination; i++) {
        clockwiseDistance += distance[i];
    }
    let totalDistance = 0;
    // Calculate the total distance of the circle
    for (let i = 0; i < distance.length; i++) {
        totalDistance += distance[i];
    }
    // Calculate the distance between start and destination in the counterclockwise direction
    let counterclockwiseDistance = totalDistance - clockwiseDistance;
    // Return the minimum distance between the clockwise and counterclockwise directions
    return Math.min(clockwiseDistance, counterclockwiseDistance);
}

function DinnerPlates(capacity) {
    let stacks = [];
    let available = []; // min-heap of candidate indices (lazy deletion of stale/full entries)

    function heapPush(heap, val) {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function heapPop(heap) {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0, n = heap.length;
            while (true) {
                let l = 2 * i + 1, r = 2 * i + 2, smallest = i;
                if (l < n && heap[l] < heap[smallest]) smallest = l;
                if (r < n && heap[r] < heap[smallest]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    }

    function push(val) {
        while (available.length && (available[0] >= stacks.length || stacks[available[0]].length >= capacity)) {
            heapPop(available);
        }
        if (available.length === 0) {
            stacks.push([val]);
            if (capacity > 1) heapPush(available, stacks.length - 1);
        } else {
            const idx = available[0];
            stacks[idx].push(val);
            if (stacks[idx].length >= capacity) heapPop(available);
        }
    }

    function pop() {
        while (stacks.length && stacks[stacks.length - 1].length === 0) stacks.pop();
        if (!stacks.length) return -1;
        return popAtStack(stacks.length - 1);
    }

    function popAtStack(index) {
        if (index >= stacks.length || stacks[index].length === 0) return -1;
        const wasFull = stacks[index].length === capacity;
        const val = stacks[index].pop();
        if (wasFull) heapPush(available, index);
        while (stacks.length && stacks[stacks.length - 1].length === 0) stacks.pop();
        return val;
    }

    return { push, pop, popAtStack };
}

function dayOfTheWeek(day, month, year) {
    // calculate the day of the week using Zeller's Congruence formula
    let t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4];
    year -= (month < 3) ? 1 : 0;
    let dayOfWeek = (year + Math.floor(year/4) - Math.floor(year/100) + Math.floor(year/400) + t[month-1] + day) % 7;
    // map the calculated day of the week to the corresponding day name
    let days = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
    return days[dayOfWeek];
}

function maxNumberOfBalloons(text) {
    let charCount = {};
    for (let char of text) {
        charCount[char] = (charCount[char] || 0) + 1;
    }
    let balloonCount = Infinity;
    let balloonChars = 'balloon';
    for (let char of balloonChars) {
        // default to 0 for chars missing from text entirely - undefined/2 is NaN and
        // Math.min(x, NaN) is always NaN, silently corrupting the whole result
        let avail = charCount[char] || 0;
        if (char === 'l' || char === 'o') avail = Math.floor(avail / 2);
        balloonCount = Math.min(balloonCount, avail);
    }
    return balloonCount;
}

function reverseParentheses(s) {
    // start with a base level so the outermost text always has somewhere to accumulate into
    let stack = [''];
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '(') {
            stack.push('');
        } else if (s[i] === ')') {
            let reversed = stack.pop().split('').reverse().join('');
            stack[stack.length - 1] += reversed;
        } else {
            stack[stack.length - 1] += s[i];
        }
    }
    return stack[0];
}

function maximumSum(arr) {
    let n = arr.length;
    let forward = new Array(n).fill(0);
    let backward = new Array(n).fill(0);
    let maxSum = arr[0];
    // calculate maximum subarray sum from left to right
    forward[0] = arr[0];
    for (let i = 1; i < n; i++) {
        forward[i] = Math.max(arr[i], forward[i-1] + arr[i]);
        maxSum = Math.max(maxSum, forward[i]);
    }
    // calculate maximum subarray sum from right to left
    backward[n-1] = arr[n-1];
    for (let i = n - 2; i >= 0; i--) {
        backward[i] = Math.max(arr[i], backward[i+1] + arr[i]);
        maxSum = Math.max(maxSum, backward[i]);
    }
    // calculate maximum subarray sum with one deletion
    for (let i = 1; i < n - 1; i++) {
        maxSum = Math.max(maxSum, forward[i-1] + backward[i+1]);
    }
    return maxSum;
}

function kConcatenationMaxSum(arr, k) {
    const MOD = 1e9 + 7;
    function kadaneNonNeg(a) {
        let cur = 0, best = 0;
        for (const x of a) {
            cur = Math.max(x, cur + x);
            best = Math.max(best, cur);
        }
        return best;
    }
    let total = 0;
    for (const x of arr) total += x;
    const best1 = kadaneNonNeg(arr);
    if (k === 1) return best1 % MOD;
    const best2 = kadaneNonNeg(arr.concat(arr));
    // beyond 2 copies, extra whole-array repeats only help if the array's total sum is positive
    let ans = total > 0 ? best2 + (k - 2) * total : best2;
    return ans % MOD;
}

function makeArrayIncreasing(arr1, arr2) {
    const sorted2 = Array.from(new Set(arr2)).sort((a, b) => a - b);
    function nextGreater(v) {
        // smallest value in sorted2 strictly greater than v
        let lo = 0, hi = sorted2.length;
        while (lo < hi) { let mid = (lo + hi) >> 1; if (sorted2[mid] > v) hi = mid; else lo = mid + 1; }
        return lo < sorted2.length ? sorted2[lo] : undefined;
    }
    // dp: map from "value the sequence currently ends on" -> min operations used so far
    let dp = new Map();
    dp.set(arr1[0], 0);
    if (sorted2.length > 0) dp.set(sorted2[0], Math.min(dp.get(sorted2[0]) ?? Infinity, 1));
    for (let i = 1; i < arr1.length; i++) {
        const newDp = new Map();
        for (const [prevVal, prevOps] of dp) {
            if (arr1[i] > prevVal) {
                const cur = newDp.get(arr1[i]) ?? Infinity;
                newDp.set(arr1[i], Math.min(cur, prevOps));
            }
            const ng = nextGreater(prevVal);
            if (ng !== undefined) {
                const cur = newDp.get(ng) ?? Infinity;
                newDp.set(ng, Math.min(cur, prevOps + 1));
            }
        }
        dp = newDp;
        if (dp.size === 0) return -1;
    }
    return Math.min(...dp.values());
}

function criticalConnections(n, connections) {
    // Create an adjacency list representation of the graph
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v] of connections) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const visited = Array(n).fill(false);
    const low = Array(n).fill(Infinity);
    const disc = Array(n).fill(Infinity);
    const parent = Array(n).fill(-1);
    const critical = [];
    let time = 0;

    function dfs(u) {
        // Mark the current node as visited and initialize its discovery time and low value
        visited[u] = true;
        disc[u] = time;
        low[u] = time;
        time++;

        for (const v of graph[u]) {
            if (!visited[v]) {
                // If the adjacent node is not visited, recursively call dfs on it
                parent[v] = u;
                dfs(v);
                // Update the low value of the current node based on the low value of its child
                low[u] = Math.min(low[u], low[v]);
                // If the low value of the child is greater than the discovery time of the current node, it's a critical connection
                if (low[v] > disc[u]) {
                    // Add the critical connection to the result
                    critical.push([u, v]);
                }
            } else if (v !== parent[u]) {
                // If the adjacent node is already visited and it's not the parent of the current node, update the low value of the current node
                low[u] = Math.min(low[u], disc[v]);
            }
        }
    }

    dfs(0);
    return critical;
}

function minimumAbsDifference(arr) {
    // Sort the array to easily find adjacent pairs with minimum absolute difference
    arr.sort((a, b) => a - b);
    let minDiff = Infinity;
    let result = [];
    // Iterate through the sorted array to find the minimum absolute difference
    for (let i = 0; i < arr.length - 1; i++) {
        let diff = arr[i + 1] - arr[i];
        // Update the minimum difference if a smaller difference is found
        if (diff < minDiff) {
            minDiff = diff;
            result = [[arr[i], arr[i + 1]]];
        } 
        // Add pairs with the minimum absolute difference to the result
        else if (diff === minDiff) {
            result.push([arr[i], arr[i + 1]]);
        }
    }
    return result;
}

function uniqueOccurrences(arr) {
    var frequencyMap = {};
    for (var i = 0; i < arr.length; i++) {
        // count the frequency of each number in the array
        frequencyMap[arr[i]] = (frequencyMap[arr[i]] || 0) + 1;
    }
    var frequencySet = new Set();
    for (var key in frequencyMap) {
        // check if the frequency of each number is unique
        if (frequencySet.has(frequencyMap[key])) return false;
        frequencySet.add(frequencyMap[key]);
    }
    return true;
}

function equalSubstring(s, t, maxCost) {
    let maxLength = 0;
    let left = 0;
    let currentCost = 0;
    // Calculate the cost of changing the substring from s to t and update the maximum length
    for (let right = 0; right < s.length; right++) {
        currentCost += Math.abs(s.charCodeAt(right) - t.charCodeAt(right));
        // Shrink the window from the left if the cost exceeds maxCost
        while (currentCost > maxCost) {
            currentCost -= Math.abs(s.charCodeAt(left) - t.charCodeAt(left));
            left++;
        }
        // Update the maximum length
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

function nthUglyNumber(n, a, b, c) {
    function gcd(x, y) { while (y) { [x, y] = [y, x % y]; } return x; }
    function lcm(x, y) { return x / gcd(x, y) * y; }
    const ab = lcm(a, b), bc = lcm(b, c), ac = lcm(a, c);
    const abc = lcm(ab, c);
    let left = 1, right = 2 * n * Math.max(a, b, c);
    while (left < right) {
        let mid = Math.floor((left + right) / 2);
        let count = Math.floor(mid / a) + Math.floor(mid / b) + Math.floor(mid / c)
            - Math.floor(mid / ab) - Math.floor(mid / bc) - Math.floor(mid / ac)
            + Math.floor(mid / abc);
        if (count < n) left = mid + 1;
        else right = mid;
    }
    return left;
}

function removeDuplicates(s, k) {
    let stack = [];
    // iterate over each character in the string and its index
    for (let i = 0; i < s.length; i++) {
        let char = s[i];
        // if the stack is not empty and the top of the stack has the same character as the current one
        if (stack.length > 0 && stack[stack.length - 1][0] === char) {
            // increment the count of the top of the stack
            stack[stack.length - 1][1]++;
            // if the count of the top of the stack equals k, pop it from the stack
            if (stack[stack.length - 1][1] === k) {
                stack.pop();
            }
        } else {
            // if the stack is empty or the top of the stack has a different character, push the current character and its count to the stack
            stack.push([char, 1]);
        }
    }
    // initialize an empty string to store the result
    let result = '';
    // iterate over each character and its count in the stack
    for (let i = 0; i < stack.length; i++) {
        // append the character repeated by its count to the result
        result += stack[i][0].repeat(stack[i][1]);
    }
    return result;
}

function smallestStringWithSwaps(s, pairs) {
    let parent = Array(s.length).fill(0).map((_, i) => i);
    let rank = Array(s.length).fill(0);

    function find(x) {
        // if x is not the parent of itself, find its parent
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }

    function union(x, y) {
        // find the parents of x and y
        let rootX = find(x), rootY = find(y);
        // if they are not in the same group, merge them
        if (rootX !== rootY) {
            // merge the smaller group into the larger one
            if (rank[rootX] < rank[rootY]) parent[rootX] = rootY;
            else if (rank[rootX] > rank[rootY]) parent[rootY] = rootX;
            else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    // group the indices by their connections
    for (let [x, y] of pairs) union(x, y);

    // create a map to store the characters in each group
    let map = {};
    for (let i = 0; i < s.length; i++) {
        let group = find(i);
        if (!map[group]) map[group] = [];
        map[group].push(s[i]);
    }

    // sort the characters in each group
    for (let group in map) {
        // sort the characters in ascending order
        map[group].sort();
    }

    // rebuild the string with the sorted characters
    let result = Array(s.length);
    for (let i = 0; i < s.length; i++) {
        let group = find(i);
        // get the next smallest character from the group
        result[i] = map[group].shift();
    }

    return result.join('');
}

// TIME: O(n + m * alpha(n)) SPACE: O(n)

function Skiplist() {
    this.levels = 16;
    this.maxValue = 1 << 15;
    this.head = new Node(this.maxValue, this.levels);
}

function Node(val, level) {
    this.val = val;
    this.next = new Array(level).fill(null);
}

Skiplist.prototype.search = function(target) {
    let curr = this.head;
    for (let i = this.levels - 1; i >= 0; i--) {
        while (curr.next[i] && curr.next[i].val < target) {
            curr = curr.next[i];
        }
    }
    return curr.next[0] && curr.next[0].val === target;
}

Skiplist.prototype.add = function(num) {
    let update = new Array(this.levels).fill(this.head);
    let curr = this.head;
    for (let i = this.levels - 1; i >= 0; i--) {
        while (curr.next[i] && curr.next[i].val < num) {
            curr = curr.next[i];
        }
        update[i] = curr;
    }
    let newNode = new Node(num, getRandomLevel());
    for (let i = 0; i < newNode.next.length; i++) {
        newNode.next[i] = update[i].next[i];
        update[i].next[i] = newNode;
    }
}

Skiplist.prototype.erase = function(num) {
    let update = new Array(this.levels).fill(this.head);
    let curr = this.head;
    for (let i = this.levels - 1; i >= 0; i--) {
        while (curr.next[i] && curr.next[i].val < num) {
            curr = curr.next[i];
        }
        update[i] = curr;
    }
    // FIXED: the original function never returned anything (always undefined),
    // but the spec requires erase() to return true/false depending on whether the value existed.
    if (curr.next[0] && curr.next[0].val === num) {
        for (let i = 0; i < this.levels; i++) {
            if (update[i].next[i] && update[i].next[i].val === num) {
                update[i].next[i] = update[i].next[i].next[i];
            } else {
                break;
            }
        }
        return true;
    }
    return false;
}

function getRandomLevel() {
    let level = 1;
    while (Math.random() < 0.5 && level < 16) {
        level++;
    }
    return level;
}

function sortItems(n, m, group, beforeItems) {
    group = group.slice();
    let nextGroupId = m;
    for (let i = 0; i < n; i++) {
        if (group[i] === -1) group[i] = nextGroupId++;
    }
    const totalGroups = nextGroupId;

    const itemAdj = Array.from({length: n}, () => []);
    const itemIndeg = new Array(n).fill(0);
    const groupAdj = Array.from({length: totalGroups}, () => []);
    const groupIndeg = new Array(totalGroups).fill(0);

    for (let i = 0; i < n; i++) {
        for (const b of beforeItems[i]) {
            itemAdj[b].push(i);
            itemIndeg[i]++;
            if (group[b] !== group[i]) {
                groupAdj[group[b]].push(group[i]);
                groupIndeg[group[i]]++;
            }
        }
    }

    function topo(adj, indeg, count) {
        const deg = indeg.slice();
        const queue = [];
        for (let i = 0; i < count; i++) if (deg[i] === 0) queue.push(i);
        const order = [];
        let head = 0;
        while (head < queue.length) {
            const u = queue[head++];
            order.push(u);
            for (const v of adj[u]) {
                deg[v]--;
                if (deg[v] === 0) queue.push(v);
            }
        }
        return order.length === count ? order : null;
    }

    const itemOrder = topo(itemAdj, itemIndeg, n);
    if (itemOrder === null) return [];
    const groupOrder = topo(groupAdj, groupIndeg, totalGroups);
    if (groupOrder === null) return [];

    const itemsByGroup = new Map();
    for (let g = 0; g < totalGroups; g++) itemsByGroup.set(g, []);
    for (const item of itemOrder) itemsByGroup.get(group[item]).push(item);

    const result = [];
    for (const g of groupOrder) {
        for (const item of itemsByGroup.get(g)) result.push(item);
    }
    return result;
}

function isValid(n, group, beforeItems, order) {
    if (order.length !== n) return false;
    const pos = new Array(n);
    order.forEach((v, i) => pos[v] = i);
    for (let i = 0; i < n; i++) {
        for (const b of beforeItems[i]) {
            if (pos[b] > pos[i]) return false;
        }
    }
    const seen = new Map();
    order.forEach((item, idx) => {
        const g = group[item];
        if (g === -1) return;
        if (!seen.has(g)) seen.set(g, [idx, idx]);
        else seen.get(g)[1] = idx;
    });
    for (const [g, [lo, hi]] of seen) {
        for (let idx = lo; idx <= hi; idx++) {
            if (group[order[idx]] !== g) return false;
        }
    }
    return true;
}

