function minimumMoves(grid) {
    const n = grid.length;
    const visited = Array.from({length: n}, () => Array.from({length: n}, () => [false, false]));
    const queue = [[0, 0, 0, 0]]; // r, c, orientation (0=horizontal,1=vertical), steps
    visited[0][0][0] = true;
    while (queue.length) {
        const [r, c, ori, steps] = queue.shift();
        if (ori === 0 && r === n - 1 && c === n - 2) return steps;
        if (ori === 0) {
            if (c + 2 < n && grid[r][c + 2] === 0 && !visited[r][c + 1][0]) {
                visited[r][c + 1][0] = true;
                queue.push([r, c + 1, 0, steps + 1]);
            }
            if (r + 1 < n && grid[r + 1][c] === 0 && grid[r + 1][c + 1] === 0) {
                if (!visited[r + 1][c][0]) { visited[r + 1][c][0] = true; queue.push([r + 1, c, 0, steps + 1]); }
                if (!visited[r][c][1]) { visited[r][c][1] = true; queue.push([r, c, 1, steps + 1]); }
            }
        } else {
            if (r + 2 < n && grid[r + 2][c] === 0 && !visited[r + 1][c][1]) {
                visited[r + 1][c][1] = true;
                queue.push([r + 1, c, 1, steps + 1]);
            }
            if (c + 1 < n && grid[r][c + 1] === 0 && grid[r + 1][c + 1] === 0) {
                if (!visited[r][c + 1][1]) { visited[r][c + 1][1] = true; queue.push([r, c + 1, 1, steps + 1]); }
                if (!visited[r][c][0]) { visited[r][c][0] = true; queue.push([r, c, 0, steps + 1]); }
            }
        }
    }
    return -1;
}

function minCostToMoveChips(position) {
    let evenCount = 0;
    let oddCount = 0;
    // Count the number of chips at even and odd positions
    for (let i = 0; i < position.length; i++) {
        if (position[i] % 2 === 0) {
            evenCount++;
        } else {
            oddCount++;
        }
    }
    // The minimum cost is the smaller of the counts of even and odd positions
    return Math.min(evenCount, oddCount);
}

function balancedStringSplit(s) {
    let count = 0, balance = 0; 
    // iterate through the string and update the balance based on 'L' or 'R'
    for (let i = 0; i < s.length; i++) {
        // if 'L' is encountered, increment balance, if 'R' is encountered, decrement balance
        balance += s[i] === 'L' ? 1 : -1; 
        // if balance is zero, it means we have found a balanced substring, so increment count
        if (balance === 0) count++; 
    }
    return count;
}

function longestSubsequence(arr, difference) {
  let maxLength = 0;
  let sequenceLengths = {};
  for (let i = 0; i < arr.length; i++) {
    // Check if the current element can be part of an existing sequence
    let previousElement = arr[i] - difference;
    let currentLength = (sequenceLengths[previousElement] || 0) + 1;
    sequenceLengths[arr[i]] = currentLength;
    // Update the maximum length found so far
    maxLength = Math.max(maxLength, currentLength);
  }
  return maxLength;
}

function countVowelPermutation(n) {
    const MOD = 1000000007;
    const vowels = ['a', 'e', 'i', 'o', 'u'];
    const dp = Array.from({length: 5}, () => Array(n).fill(0));
    // initialize the base case where n = 1
    for (let i = 0; i < 5; i++) {
        dp[i][0] = 1;
    }
    // fill up the dp table based on the rules
    for (let i = 1; i < n; i++) {
        // 'a' can be appended after 'e', 'i', 'u'
        dp[0][i] = (dp[1][i-1] + dp[2][i-1] + dp[4][i-1]) % MOD;
        // 'e' can be appended after 'a', 'i'
        dp[1][i] = (dp[0][i-1] + dp[2][i-1]) % MOD;
        // 'i' can be appended after 'e', 'o'
        dp[2][i] = (dp[1][i-1] + dp[3][i-1]) % MOD;
        // 'o' can be appended after 'i'
        dp[3][i] = dp[2][i-1] % MOD;
        // 'u' can be appended after 'i', 'o'
        dp[4][i] = (dp[2][i-1] + dp[3][i-1]) % MOD;
    }
    // calculate the total number of strings
    let total = 0;
    for (let i = 0; i < 5; i++) {
        total = (total + dp[i][n-1]) % MOD;
    }
    return total;
}

function getMaximumGold(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    let maxGold = 0;

    function backtrack(row, col, currentGold, visited) {
        // update maxGold if currentGold is greater
        maxGold = Math.max(maxGold, currentGold);

        // explore all possible directions
        for (let i = 0; i < 4; i++) {
            const newRow = row + directions[i][0];
            const newCol = col + directions[i][1];

            // check if new position is within grid and not visited before
            if (newRow >= 0 && newRow < m && newCol >= 0 && newCol < n && grid[newRow][newCol] !== 0 && !visited.has(newRow + ',' + newCol)) {
                // mark new position as visited and recursively explore
                visited.add(newRow + ',' + newCol);
                backtrack(newRow, newCol, currentGold + grid[newRow][newCol], visited);
                // backtrack by removing new position from visited set
                visited.delete(newRow + ',' + newCol);
            }
        }
    }

    // start backtracking from each non-empty cell
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] !== 0) {
                backtrack(i, j, grid[i][j], new Set([i + ',' + j]));
            }
        }
    }

    return maxGold;
}

function checkStraightLine(coordinates) {
    // calculate the slope of the line formed by the first two points
    let x0 = coordinates[0][0], y0 = coordinates[0][1];
    let x1 = coordinates[1][0], y1 = coordinates[1][1];
    let slope = x1 - x0 === 0 ? Infinity : (y1 - y0) / (x1 - x0);
    // check if the slope of the line formed by the first point and each of the remaining points is the same
    for (let i = 2; i < coordinates.length; i++) {
        let x = coordinates[i][0], y = coordinates[i][1];
        let newSlope = x - x0 === 0 ? Infinity : (y - y0) / (x - x0);
        if (newSlope !== slope) return false;
    }
    return true;
}

function circularPermutation(n, start) {
    const result = [];
    const size = 1 << n;
    for (let i = 0; i < size; i++) {
        // reflected Gray code, rotated so it starts at `start`
        result.push((i ^ (i >> 1)) ^ start);
    }
    return result;
}

function findSolution(function_id, z) {
    let result = [];
    // Loop through all possible values of x from 1 to z
    for (let x = 1; x <= z; x++) {
        // For each x, find the corresponding y that makes f(x, y) equal to z
        for (let y = 1; y <= z; y++) {
            // Check if f(x, y) equals z
            if (f(x, y, function_id) === z) {
                // If it does, add the pair (x, y) to the result
                result.push([x, y]);
            }
        }
    }
    return result;
}

// Helper function to calculate f(x, y) based on the given function_id
function f(x, y, function_id) {
    if (function_id === 1) {
        return x + y;
    } else if (function_id === 2) {
        return x * y;
    }
}

function maxLength(arr) {
    let maxLen = 0;
    function backtrack(start, path) {
        // check if the current path has unique characters
        if (isUnique(path)) {
            maxLen = Math.max(maxLen, path.length);
        }
        // try to add each string in the array to the current path
        for (let i = start; i < arr.length; i++) {
            // skip if adding the current string would result in duplicate characters
            if (hasDuplicate(path + arr[i])) continue;
            backtrack(i + 1, path + arr[i]);
        }
    }
    function isUnique(str) {
        let set = new Set();
        for (let char of str) {
            if (set.has(char)) return false;
            set.add(char);
        }
        return true;
    }
    function hasDuplicate(str) {
        let set = new Set();
        for (let char of str) {
            if (set.has(char)) return true;
            set.add(char);
        }
        return false;
    }
    backtrack(0, '');
    return maxLen;
}

function numberOfSubarrays(nums, k) {
    let count = 0;
    // Initialize a hashmap to store the prefix sum of odd numbers and their frequencies
    let prefixSumCount = {0: 1};
    let currentSum = 0;
