        if (charCount[idx] === 0) distinct++;
        charCount[idx]++;
    }

    // slide the window across the whole string
    for (let start = 0; start + minSize <= s.length; start++) {
        // MAIN LOGIC: if the window respects the maxLetters constraint,
        // count the current substring
        if (distinct <= maxLetters) {
            const sub = s.substring(start, start + minSize);
            const newCount = (freqMap.get(sub) || 0) + 1;
            freqMap.set(sub, newCount);
            if (newCount > best) best = newCount;
        }

        // move window one step to the right (unless we are at the last position)
        if (start + minSize < s.length) {
            const leftIdx = s.charCodeAt(start) - 97;
            const rightIdx = s.charCodeAt(start + minSize) - 97;

            // remove left character
            charCount[leftIdx]--;
            if (charCount[leftIdx] === 0) distinct--;

            // add right character
            if (charCount[rightIdx] === 0) distinct++;
            charCount[rightIdx]++;
        }
    }

    return best;
}

function sumOfMutatedArrayClosestTarget(arr, target) {
    if (!arr.length) return 0;
    arr = [...arr].sort((a,b) => a-b);
    const n = arr.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) prefix[i] = prefix[i-1] + arr[i-1];

    function bisectRight(x) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= x) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
    function mutatedSum(x) {
        const idx = bisectRight(x);
        return prefix[idx] + x * (n - idx);
    }
    const originalSum = prefix[n];
    if (target >= originalSum) return arr[n-1];

    let low = 0, high = arr[n-1];
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (mutatedSum(mid) < target) low = mid + 1; else high = mid;
    }
    let bestX = low;
    let bestDiff = Math.abs(mutatedSum(bestX) - target);
    if (bestX > 0) {
        const cand = bestX - 1;
        const diff = Math.abs(mutatedSum(cand) - target);
        if (diff < bestDiff || (diff === bestDiff && cand < bestX)) {
            bestX = cand;
        }
    }
    return bestX;
}

function replaceElements(arr) {
    let maxSoFar = -1;                     // start with -1 for the last element
    for (let i = arr.length - 1; i >= 0; i--) {
        const current = arr[i];
        arr[i] = maxSoFar;                 // replace with greatest element to the right
        if (current > maxSoFar) {
            maxSoFar = current;            // update the running maximum
        }
    }
    return arr;
}

function pathsWithMaxScore(board) {
    const MOD = 1000000007;
    const n = board.length;
    const dpSum = Array.from({length:n+1}, () => new Array(n+1).fill(-1));
    const dpCnt = Array.from({length:n+1}, () => new Array(n+1).fill(0));
    dpSum[n-1][n-1] = 0;
    dpCnt[n-1][n-1] = 1;
    const dirs = [[0,1],[1,0],[1,1]]; // from (r,c) coming from (r+dr,c+dc) reversed: we compute backward from S to E meaning iterate r,c from n-1 down to 0, value at (r,c) = max over (r+1,c),(r,c+1),(r+1,c+1)
    for (let r = n-1; r >= 0; r--) {
        for (let c = n-1; c >= 0; c--) {
            if (r === n-1 && c === n-1) continue;
            if (board[r][c] === 'X') continue;
            let best = -1, cnt = 0;
            for (const [dr,dc] of [[1,0],[0,1],[1,1]]) {
                const nr = r+dr, nc = c+dc;
                if (nr >= n || nc >= n) continue;
                if (dpSum[nr][nc] === -1) continue;
                const val = dpSum[nr][nc];
                if (val > best) { best = val; cnt = dpCnt[nr][nc]; }
                else if (val === best) { cnt = (cnt + dpCnt[nr][nc]) % MOD; }
            }
            if (best === -1) continue;
            const add = board[r][c] === 'E' || board[r][c] === 'S' ? 0 : Number(board[r][c]);
            dpSum[r][c] = best + add;
            dpCnt[r][c] = cnt;
        }
    }
    if (dpSum[0][0] === -1) return [0,0];
    return [dpSum[0][0], dpCnt[0][0]];
}

function deepestLeavesSum(root) {
    if (!root) return 0;

    let queue = [root];
    let deepestSum = 0;

    while (queue.length) {
        const levelSize = queue.length;
        let levelSum = 0;                     // reset sum for this level

        for (let i = 0; i < levelSize; i++) {
            const node = queue.shift();       // pop front node
            levelSum += node.val;              // add its value

            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }

        deepestSum = levelSum;                 // after loop, this is the sum of the latest level
    }

    return deepestSum;
}

function maxCandies(status, candies, keys, containedBoxes, initialBoxes) {
    const n = status.length;
    const haveBox = new Array(n).fill(false);
    const haveKey = new Array(n).fill(false);
    const opened = new Array(n).fill(false);
    const queue = [];
    for (const b of initialBoxes) haveBox[b] = true;
    for (let i = 0; i < n; i++) if (status[i] === 1) haveKey[i] = true;
    for (const b of initialBoxes) if (haveKey[b]) queue.push(b);
    let total = 0;
    while (queue.length) {
        const b = queue.shift();
        if (opened[b]) continue;
        opened[b] = true;
        total += candies[b];
        for (const k of keys[b]) {
            if (!haveKey[k]) { haveKey[k] = true; if (haveBox[k] && !opened[k]) queue.push(k); }
        }
        for (const nb of containedBoxes[b]) {
            haveBox[nb] = true;
            if (haveKey[nb] && !opened[nb]) queue.push(nb);
        }
    }
    return total;
}

function getAllElements(root1, root2) {
    // collect values from a BST in sorted order
    function inorder(node, result) {
        if (!node) return;
        inorder(node.left, result);
        result.push(node.val);
        inorder(node.right, result);
    }

    const list1 = [];
    const list2 = [];
    inorder(root1, list1);
    inorder(root2, list2);

    // merge the two sorted lists
    const merged = [];
    let i = 0, j = 0;
    while (i < list1.length && j < list2.length) {
        if (list1[i] <= list2[j]) {
            merged.push(list1[i++]);
        } else {
            merged.push(list2[j++]);
        }
    }
    while (i < list1.length) merged.push(list1[i++]);
    while (j < list2.length) merged.push(list2[j++]);

    return merged;
}

function decryptString(s) {
    const decoded = [];
    let i = s.length - 1;
    while (i >= 0) {
        let num;
        if (s[i] === '#') {               // two‑digit code
            num = (s.charCodeAt(i - 2) - 48) * 10 + (s.charCodeAt(i - 1) - 48);
            i -= 3;
        } else {                          // single‑digit code
            num = s.charCodeAt(i) - 48;
            i -= 1;
        }
        const letter = String.fromCharCode(97 + num - 1);
        decoded.push(letter);
    }
    decoded.reverse();
    return decoded.join('');
}

function canReach(arr, start) {
    const n = arr.length;
    const visited = new Array(n).fill(false);
    const queue = [];

    queue.push(start);
    visited[start] = true;

    while (queue.length) { // explore reachable indices breadth‑first
        const idx = queue.shift();

        if (arr[idx] === 0) return true; // found a zero

        const jump = arr[idx];
        const forward = idx + jump;
        const backward = idx - jump;

        if (forward < n && !visited[forward]) {
            visited[forward] = true;
            queue.push(forward);
        }
        if (backward >= 0 && !visited[backward]) {
            visited[backward] = true;
            queue.push(backward);
        }
    }

    return false;
}

function findZeroSumArray(n) {
    const result = [];
    if (n % 2 === 0) {
        for (let i = 1; i <= n / 2; i++) {
            result.push(i);
            result.push(-i);
        }
    } else {
        if (n === 1) {
            result.push(0);
        } else if (n === 3) {
            result.push(-1, 0, 1);
        } else {
            result.push(-1, 1);
            let sumPos = 0;
            for (let i = 3; i <= n - 1; i++) {
                result.push(i);
                sumPos += i;
            }
            result.push(-sumPos);
        }
    }
    result.sort((a, b) => a - b);
    return result;
}

function isSolvable(words, result) {
    const lettersSet = new Set();
    const leading = new Set();
    for (const w of words) {
        for (const c of w) lettersSet.add(c);
        if (w.length > 1) leading.add(w[0]);
    }
    for (const c of result) lettersSet.add(c);
    if (result.length > 1) leading.add(result[0]);
    const letters = [...lettersSet];

    const assign = new Map();
    const used = new Set();

    const maxLen = Math.max(Math.max(...words.map(w=>w.length)), result.length);
    const cols = [];
    for (let pos = 0; pos < maxLen; pos++) {
        const addLetters = [];
        for (const w of words) if (w.length > pos) addLetters.push(w[w.length-1-pos]);
        const resLetter = result.length > pos ? result[result.length-1-pos] : null;
        cols.push([addLetters, resLetter]);
    }

    function checkPartial() {
        let carry = 0;
        for (const [addLetters, resLetter] of cols) {
            let sumVal = carry;
            for (const ch of addLetters) {
                if (!assign.has(ch)) return true;
                sumVal += assign.get(ch);
            }
            const expectedDigit = sumVal % 10;
            carry = Math.floor(sumVal/10);
            if (resLetter === null) {
                if (expectedDigit !== 0) return false;
                continue;
            }
            if (!assign.has(resLetter)) {
                if (used.has(expectedDigit)) return false;
                continue;
            }
            if (assign.get(resLetter) !== expectedDigit) return false;
        }
        return true;
    }

    function backtrack(idx) {
        if (idx === letters.length) {
            let total = 0;
            for (const w of words) {
                let num = 0;
                for (const ch of w) num = num*10 + assign.get(ch);
                total += num;
            }
            let resNum = 0;
            for (const ch of result) resNum = resNum*10 + assign.get(ch);
            return total === resNum;
        }
        const ch = letters[idx];
        for (let d = 0; d <= 9; d++) {
            if (used.has(d)) continue;
            if (d === 0 && leading.has(ch)) continue;
            assign.set(ch, d);
            used.add(d);
            if (checkPartial() && backtrack(idx+1)) return true;
            used.delete(d);
            assign.delete(ch);
        }
        return false;
    }
    return backtrack(0);
}

function xorQueries(arr, queries) {
    // build prefix xor: prefix[i] = xor of first i elements (0‑based)
    const prefix = new Array(arr.length + 1);
    prefix[0] = 0;
    for (let i = 0; i < arr.length; i++) {
        prefix[i + 1] = prefix[i] ^ arr[i];
    }

    const answers = new Array(queries.length);
    for (let i = 0; i < queries.length; i++) {
        const [left, right] = queries[i];
        // xor of subarray [left, right] = prefix[right+1] ^ prefix[left]
        answers[i] = prefix[right + 1] ^ prefix[left];
    }
    return answers;
}

function decompressRLElist(nums) {
    const result = [];

    for (let i = 0; i < nums.length; i += 2) {
        const freq = nums[i];
        const val = nums[i + 1];

        // repeat val freq times and append to result
        for (let j = 0; j < freq; j++) {
            result.push(val);
        }
    }

    return result;
}


// where m = Σ freq (total number of elements in the decompressed list)

function getWatchedVideosByFriends(watchedVideos, friends, id, level) {
    const n = watchedVideos.length;
    const visited = new Array(n).fill(false);
    const queue = [];

    visited[id] = true;
    queue.push(id);
    let currentLevel = 0;

    // BFS to reach the exact level
    while (queue.length && currentLevel < level) {
        const size = queue.length;
        for (let i = 0; i < size; i++) {
            const person = queue.shift();
            for (const nb of friends[person]) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.push(nb);
                }
            }
        }
        currentLevel++;
    }

    // Count frequencies of videos watched by people at the target level
    const freq = {};
    for (const person of queue) {
        for (const video of watchedVideos[person]) {
            freq[video] = (freq[video] || 0) + 1;
        }
    }

    // Sort by frequency (ascending) then alphabetically
    const result = Object.keys(freq).sort((a, b) => {
        if (freq[a] !== freq[b]) return freq[a] - freq[b];
        return a.localeCompare(b);
    });

    return result;
}

function minInsertions(s) {
    const n = s.length;
    if (n === 0) return 0;

    const rev = s.split('').reverse().join('');

    // dpPrev holds results for i‑1, dpCurr for i
    let dpPrev = new Array(n + 1).fill(0);
    let dpCurr = new Array(n + 1).fill(0);

    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= n; j++) {
            if (s[i - 1] === rev[j - 1]) {
                dpCurr[j] = dpPrev[j - 1] + 1;          // match → extend LCS
            } else {
                dpCurr[j] = Math.max(dpPrev[j], dpCurr[j - 1]); // take best of skipping a char
            }
        }
        // swap rows for the next i
        const tmp = dpPrev;
        dpPrev = dpCurr;
        dpCurr = tmp;
    }

    const lpsLength = dpPrev[n];
    return n - lpsLength;
}

function sumEvenGrandparent(root) {
    let total = 0;

    function dfs(node, parentVal, grandparentVal) {
        if (!node) return;

        // add node value when its grandparent exists and is even
        if (grandparentVal !== null && grandparentVal % 2 === 0) {
            total += node.val;
        }

        // recurse left and right, shifting parent → grandparent
        dfs(node.left, node.val, parentVal);
        dfs(node.right, node.val, parentVal);
    }

    dfs(root, null, null);
    return total;
}

function distinctEchoSubstrings(text) {
    const n = text.length;
    const base = 91138233n;
    const mod1 = 1000000007n;
    const mod2 = 1000000009n;

    const pref1 = new Array(n + 1).fill(0n);
    const pref2 = new Array(n + 1).fill(0n);
    const pow1 = new Array(n + 1).fill(1n);
    const pow2 = new Array(n + 1).fill(1n);

    for (let i = 0; i < n; i++) {
        const code = BigInt(text.charCodeAt(i));
        pref1[i + 1] = (pref1[i] * base + code) % mod1;
        pref2[i + 1] = (pref2[i] * base + code) % mod2;
        pow1[i + 1] = (pow1[i] * base) % mod1;
        pow2[i + 1] = (pow2[i] * base) % mod2;
    }

    function getHash(l, r) {
        const h1 = (pref1[r] - (pref1[l] * pow1[r - l]) % mod1 + mod1) % mod1;
        const h2 = (pref2[r] - (pref2[l] * pow2[r - l]) % mod2 + mod2) % mod2;
        return { h1, h2 };
    }

    const seen = new Set();

    for (let len = 2; len <= n; len += 2) {
        const half = len >> 1;
        for (let i = 0; i + len <= n; i++) {
            const left = getHash(i, i + half);
            const right = getHash(i + half, i + len);
            if (left.h1 === right.h1 && left.h2 === right.h2) {
                const whole = getHash(i, i + len);
                seen.add(whole.h1 + "#" + whole.h2);
            }
        }
    }

    return seen.size;
}

function matrixBlockSum(mat, k) {
    const rows = mat.length;
    const cols = mat[0].length;

    // build prefix sum matrix (rows+1 x cols+1)
    const prefix = Array.from({ length: rows + 1 }, () => new Array(cols + 1).fill(0));
    for (let i = 0; i < rows; i++) {
        let rowSum = 0;
        for (let j = 0; j < cols; j++) {
            rowSum += mat[i][j];
            prefix[i + 1][j + 1] = prefix[i][j + 1] + rowSum;
        }
    }

    const answer = Array.from({ length: rows }, () => new Array(cols).fill(0));

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // clamp the block boundaries to matrix edges
            const r1 = Math.max(0, i - k);
            const c1 = Math.max(0, j - k);
            const r2 = Math.min(rows - 1, i + k);
            const c2 = Math.min(cols - 1, j + k);

            // use prefix sums to get block sum in O(1)
            answer[i][j] =
                prefix[r2 + 1][c2 + 1] -
                prefix[r1][c2 + 1] -
                prefix[r2 + 1][c1] +
                prefix[r1][c1];
        }
    }

    return answer;
}

function minFlips(a, b, c) {
    let flips = 0;
    // iterate until all bits of a, b and c are processed
    while (a > 0 || b > 0 || c > 0) {
        const bitA = a & 1;
        const bitB = b & 1;
        const bitC = c & 1;

        if (bitC === 0) {
            // c's bit is 0 → both a and b must be 0
            flips += bitA + bitB;
        } else {
            // c's bit is 1 → at least one of a or b must be 1
            if (bitA === 0 && bitB === 0) flips += 1;
        }

        a >>= 1;
        b >>= 1;
        c >>= 1;
    }
    return flips;
}

// TIME: O(log max(a,b,c)) SPACE: O(1)

function sumNoZeroIntegers(n) {
    // helper: check if a number contains digit 0
    function isNoZero(x) {
        while (x > 0) {
            if (x % 10 === 0) return false;
            x = Math.floor(x / 10);
        }
        return true;
    }

    let a = 1;
    // try successive a until both a and n‑a have no zero digits
    while (true) {
        const b = n - a;
        if (isNoZero(a) && isNoZero(b)) return [a, b];
        a++;
    }
}

// TIME: O(k·d) where k is the number of tries until a solution (usually very small) and d is the number of digits of the numbers
// SPACE: O(1)

function minimumDistance(word) {
    function dist(a, b) {
        if (a === -1 || b === -1) return 0;
        const ra = Math.floor(a/6), ca = a%6;
        const rb = Math.floor(b/6), cb = b%6;
        return Math.abs(ra-rb) + Math.abs(ca-cb);
    }
    if (!word.length) return 0;
    const n = word.length;
    if (n === 1) return 0;
    let prev = word.charCodeAt(0) - 65;
    let dp = new Map();
    dp.set(prev+','+(-1), 0);
    dp.set((-1)+','+prev, 0);

    for (let i = 1; i < n; i++) {
        const cur = word.charCodeAt(i) - 65;
        const newDp = new Map();
        for (const [key, val] of dp) {
            const [p1, p2] = key.split(',').map(Number);
            let state1, cost1, state2, cost2;
            if (p1 === prev) {
                state1 = cur+','+p2;
                cost1 = val + dist(prev, cur);
                state2 = p1+','+cur;
                cost2 = val + dist(p2, cur);
            } else {
                state1 = p1+','+cur;
                cost1 = val + dist(prev, cur);
                state2 = cur+','+p2;
                cost2 = val + dist(p1, cur);
            }
            for (const [st, cost] of [[state1,cost1],[state2,cost2]]) {
                if (!newDp.has(st) || cost < newDp.get(st)) newDp.set(st, cost);
            }
        }
        dp = newDp;
        prev = cur;
    }
    return Math.min(...dp.values());
}

function makeConnected(n, connections) {
    // Not enough cables to ever connect all computers
    if (connections.length < n - 1) return -1;

    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        const ra = find(a);
        const rb = find(b);
        if (ra === rb) return false; // already in same set
        if (rank[ra] < rank[rb]) {
            parent[ra] = rb;
        } else if (rank[ra] > rank[rb]) {
            parent[rb] = ra;
        } else {
            parent[rb] = ra;
            rank[ra]++;
        }
        return true;
    }

    let components = n;                     // start with n isolated computers
    for (const [a, b] of connections) {
        if (union(a, b)) components--;      // each successful union reduces component count
    }

    // To connect k components we need k‑1 operations
    return components - 1;
}


// TIME: O(n + m α(n))  SPACE: O(n)

function maximum69Number(num) {
    // Convert number to mutable array of characters
    const digits = num.toString().split('');

    // Change the first '6' to '9' to maximize the number
    for (let i = 0; i < digits.length; i++) {
        if (digits[i] === '6') {
            digits[i] = '9';
            break;
        }
    }

    // Reassemble and return as integer
    return parseInt(digits.join(''), 10);
}

function printVertically(s) {
    // split the sentence into words, ignoring possible extra spaces
    const words = s.split(' ').filter(Boolean);
    // longest word determines the number of columns
    let maxLen = 0;
    for (const w of words) {
        if (w.length > maxLen) maxLen = w.length;
    }

    const result = [];

    // MAIN LOGIC: build each column string
    for (let col = 0; col < maxLen; col++) {
        let columnStr = '';
        for (const w of words) {
            columnStr += (w.length > col) ? w[col] : ' ';
        }
        // remove trailing spaces (they are not allowed)
        columnStr = columnStr.replace(/\s+$/g, '');
        result.push(columnStr);
    }

    return result;
}

function maxValueAfterReverse(nums) {
    const n = nums.length;
    let res = 0, min2 = Infinity, max2 = -Infinity;
    for (let i = 0; i < n - 1; ++i) {
        res += Math.abs(nums[i] - nums[i + 1]);
        min2 = Math.min(min2, Math.max(nums[i], nums[i + 1]));
        max2 = Math.max(max2, Math.min(nums[i], nums[i + 1]));
    }
    let res2 = res;
    for (let i = 1; i < n - 1; ++i) {
        // reversal touching the left end (prefix) or right end (suffix) - only one edge changes
        res2 = Math.max(res2, res + Math.abs(nums[0] - nums[i + 1]) - Math.abs(nums[i] - nums[i + 1]));
        res2 = Math.max(res2, res + Math.abs(nums[n - 1] - nums[i - 1]) - Math.abs(nums[i] - nums[i - 1]));
    }
    // fully-interior reversal - both endpoints interior, two edges change; this closed form
    // captures the best achievable gain across all sign cases of the two changed edges
    return Math.max(res2, res + Math.max(0, (max2 - min2) * 2));
}

function deleteLeaves(root, target) {
    function dfs(node) {
        if (!node) return null;
        node.left = dfs(node.left);   // process left subtree
        node.right = dfs(node.right); // process right subtree
        // delete node if it became a leaf with the target value
        if (!node.left && !node.right && node.val === target) {
            return null;
        }
        return node;
    }
    return dfs(root);
}

function minTaps(n, ranges) {
    if (n === 0) return 0;                     // no garden length

    // maxRight[l] = farthest right end of any tap that can start covering from l
    const maxRight = new Array(n + 1).fill(0);
    for (let i = 0; i <= n; i++) {
        const left = Math.max(0, i - ranges[i]);
        const right = Math.min(n, i + ranges[i]);
        if (right > maxRight[left]) maxRight[left] = right;
    }

    let taps = 0;           // number of opened taps
    let currentEnd = 0;     // rightmost point already covered
    let farthest = 0;       // farthest point we can reach in this step
    let pos = 0;            // iterator over positions up to currentEnd

    // Greedy expansion of coverage
    while (currentEnd < n) {
        // explore all intervals that start at or before currentEnd
        while (pos <= currentEnd) {
            if (maxRight[pos] > farthest) farthest = maxRight[pos];
            pos++;
        }
        if (farthest <= currentEnd) return -1; // cannot extend coverage
        taps++;
        currentEnd = farthest;                  // extend covered range
    }
    return taps;
}

function breakPalindrome(palindrome) {
    const n = palindrome.length;
    if (n === 1) return "";               // single character cannot be broken

    const chars = palindrome.split('');

    // replace the first non-'a' character in the left half with 'a'
    for (let i = 0; i < Math.floor(n / 2); i++) {
        if (chars[i] !== 'a') {
            chars[i] = 'a';
            return chars.join('');
        }
    }

    // all left half characters are 'a' → change the last character to 'b'
    chars[n - 1] = 'b';
    return chars.join('');
}

function diagonalSort(mat) {
    const rows = mat.length;
    const cols = mat[0].length;

    // sort one diagonal that starts at (r, c)
    function sortDiagonal(r, c) {
        let i = r, j = c;
        const elems = [];

        // collect elements of the diagonal
        while (i < rows && j < cols) {
            elems.push(mat[i][j]);
            i++; j++;
        }

        elems.sort((a, b) => a - b); // sort the collected values

        // write the sorted values back
        i = r; j = c; let idx = 0;
        while (i < rows && j < cols) {
            mat[i][j] = elems[idx++];
            i++; j++;
        }
    }

    // process diagonals that start in the first row
    for (let col = 0; col < cols; col++) {
        sortDiagonal(0, col);
    }

    // process diagonals that start in the first column (skip the top‑left corner)
    for (let row = 1; row < rows; row++) {
        sortDiagonal(row, 0);
    }

    return mat;
}
// TIME: O(m * n * log(min(m, n))) SPACE: O(min(m, n))

function removePalindromeSubsequences(s) {
    // empty string needs no steps
    if (s.length === 0) return 0;

    // check if s is a palindrome
    let left = 0, right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) {
            // not a palindrome → answer is 2
            return 2;
        }
        left++;
        right--;
    }

    // palindrome → answer is 1
    return 1;
}

function filterRestaurants(restaurants, veganFriendly, maxPrice, maxDistance) {
    // keep only restaurants that satisfy all three filters
    const eligible = restaurants.filter(r => {
        const [id, rating, vegan, price, distance] = r;
        if (veganFriendly === 1 && vegan !== 1) return false;
        if (price > maxPrice) return false;
        if (distance > maxDistance) return false;
        return true;
    });

    // sort by rating descending, then by id descending
    eligible.sort((a, b) => {
        if (b[1] !== a[1]) return b[1] - a[1]; // rating comparison
        return b[0] - a[0];                    // id comparison
    });

    // return only the restaurant ids in the sorted order
    return eligible.map(r => r[0]);
}

function findTheCity(n, edges, distanceThreshold) {
  const INF = Infinity;
  const dist = Array.from({length:n}, () => Array(n).fill(INF));
  for (let i = 0; i < n; i++) dist[i][i] = 0;
  for (const [u,v,w] of edges) { dist[u][v] = Math.min(dist[u][v], w); dist[v][u] = Math.min(dist[v][u], w); }
  for (let k = 0; k < n; k++)
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++)
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
  let best = -1, bestCount = Infinity;
  for (let i = 0; i < n; i++) {
    let cnt = 0;
    for (let j = 0; j < n; j++) if (i !== j && dist[i][j] <= distanceThreshold) cnt++;
    if (cnt <= bestCount) { bestCount = cnt; best = i; }
  }
  return best;
}

function minDifficulty(jobDifficulty, d) {
    const n = jobDifficulty.length;
    if (d > n) return -1;                     // impossible

    // dp[i] = min difficulty for first i jobs with the processed days
    let prev = new Array(n + 1).fill(Infinity);
    prev[0] = 0;                              // zero jobs, zero difficulty

    // iterate over each day
    for (let day = 1; day <= d; day++) {
        const cur = new Array(n + 1).fill(Infinity);
        // i = number of jobs considered so far (must be at least day)
        for (let i = day; i <= n; i++) {
            let dayMax = 0;
            // try all possible starting points j for this day
            for (let j = i - 1; j >= day - 1; j--) {
                dayMax = Math.max(dayMax, jobDifficulty[j]); // max in [j, i-1]
                // transition: previous days + difficulty of current day
                cur[i] = Math.min(cur[i], prev[j] + dayMax);
            }
        }
        prev = cur;                            // move to next day
    }

    return prev[n] === Infinity ? -1 : prev[n];
}

function rankTransform(arr) {
  // sort unique values to determine ranks
  const sortedUnique = [...new Set(arr)].sort((a, b) => a - b);

  // map each value to its rank (1‑based)
  const rankMap = new Map();
  for (let i = 0; i < sortedUnique.length; i++) {
    rankMap.set(sortedUnique[i], i + 1);
  }

  // replace original elements with their ranks
  return arr.map(v => rankMap.get(v));
}

function kWeakestRows(mat, k) {
    // count soldiers in a row using binary search (1's are left‑most)
    function countSoldiers(row) {
        let left = 0, right = row.length;
        while (left < right) {
            const mid = (left + right) >> 1;
            if (row[mid] === 1) left = mid + 1;
            else right = mid;
        }
        return left; // number of 1's
    }

    const rows = [];
    for (let i = 0; i < mat.length; i++) {
        rows.push([countSoldiers(mat[i]), i]); // [soldierCount, rowIndex]
    }

    // sort by soldier count, then by row index
    rows.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

    const answer = [];
    for (let i = 0; i < k; i++) answer.push(rows[i][1]);
    return answer;
}

function maxProduct(root) {
    const MOD = 1000000007n;          // modulo as BigInt
    const subtreeSums = [];           // store every subtree sum

    // first DFS: compute sum of each subtree and collect it
    function dfs(node) {
        if (!node) return 0n;
        const left = dfs(node.left);
        const right = dfs(node.right);
        const cur = BigInt(node.val) + left + right;
        subtreeSums.push(cur);         // remember this subtree sum
        return cur;
    }

    const total = dfs(root);           // total sum of the whole tree

    let best = 0n;
    // evaluate product for every possible cut (every subtree except the whole tree)
    for (const s of subtreeSums) {
        const product = s * (total - s);
        if (product > best) best = product;
    }

    return Number(best % MOD);         // result fits into 32‑bit integer
}

function minSetSize(arr) {
    // count frequency of each integer
    const freqMap = {};
    for (const num of arr) {
        freqMap[num] = (freqMap[num] || 0) + 1;
    }

    // sort frequencies from largest to smallest
    const frequencies = Object.values(freqMap);
    frequencies.sort((a, b) => b - a); // descending

    const half = Math.ceil(arr.length / 2);
    let removed = 0;
    let setSize = 0;

    // pick numbers with highest frequencies until at least half are removed
    for (const freq of frequencies) {
        removed += freq;
        setSize++;
        if (removed >= half) break;
    }
    return setSize;
}

function maxJumps(arr, d) {
    const n = arr.length;
    const order = [...Array(n).keys()].sort((a,b) => arr[a]-arr[b]);
    const memo = new Array(n).fill(1);
    for (const i of order) {
        for (let dir = -1; dir <= 1; dir += 2) {
            for (let step = 1; step <= d; step++) {
                const j = i + dir*step;
                if (j < 0 || j >= n) break;
                if (arr[j] >= arr[i]) break;
                memo[i] = Math.max(memo[i], memo[j] + 1);
            }
        }
    }
    return Math.max(...memo);
}

function numOfSubarrays(arr, k, threshold) {
    const requiredSum = k * threshold;          // target sum for each window
    let windowSum = 0;
    let count = 0;

    for (let i = 0; i < arr.length; i++) {
        windowSum += arr[i];                     // add new element to the window

        if (i >= k) {
            windowSum -= arr[i - k];             // remove element that slides out
        }

        if (i >= k - 1 && windowSum >= requiredSum) {
            count++;                              // current window meets the condition
        }
    }

    return count;
}

function checkIfExist(arr) {
    const seen = new Set();          // store numbers we have processed
    let zeroCount = 0;               // count zeros to handle the special case

    for (const x of arr) {
        if (x === 0) {
            zeroCount++;             // another zero found
            if (zeroCount >= 2) return true; // 0 and 0 satisfy the condition
        } else {
            // if we have already seen its double or its half, condition is met
            if (seen.has(x * 2) || (x % 2 === 0 && seen.has(x / 2))) {
                return true;
            }
        }
        seen.add(x);                 // remember current number for future checks
    }
    return false;
}

function minJumps(arr) {
    const n = arr.length;
    if (n <= 1) return 0;

    // map each value to all indices that contain it
    const valueIndices = new Map();
    for (let i = 0; i < n; i++) {
        if (!valueIndices.has(arr[i])) valueIndices.set(arr[i], []);
        valueIndices.get(arr[i]).push(i);
    }

    const visited = new Array(n).fill(false);
    const queue = [0];
    visited[0] = true;
    let steps = 0;

    while (queue.length) {
        const size = queue.length;               // process one BFS layer
        for (let s = 0; s < size; s++) {
            const idx = queue.shift();
            if (idx === n - 1) return steps;      // reached the end

            const next = [];

            if (idx - 1 >= 0) next.push(idx - 1);
            if (idx + 1 < n)  next.push(idx + 1);

            const sameVal = valueIndices.get(arr[idx]) || [];
            for (const j of sameVal) next.push(j);
            valueIndices.set(arr[idx], []);        // avoid revisiting same‑value jumps

            for (const nb of next) {
                if (!visited[nb]) {
                    visited[nb] = true;
                    queue.push(nb);
                }
            }
        }
        steps++;
    }
    return -1; // should never happen for valid input
}

function numberOfSteps(num) {
    let steps = 0;
    while (num > 0) {
        // if num is even divide by 2, else subtract 1
        if (num % 2 === 0) {
            num = num / 2;
        } else {
            num = num - 1;
        }
        steps++;
    }
    return steps;
}

function minSteps(s, t) {
    // 1. frequency map for s
    const cntS = {};
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        cntS[ch] = (cntS[ch] || 0) + 1;
    }

    // 2. frequency map for t
    const cntT = {};
    for (let i = 0; i < t.length; i++) {
        const ch = t[i];
        cntT[ch] = (cntT[ch] || 0) + 1;
    }

    // 3. sum of surplus characters in t
    let steps = 0;
    for (const ch in cntT) {
        const surplus = cntT[ch] - (cntS[ch] || 0);
        if (surplus > 0) steps += surplus;   // each surplus needs one replacement
    }

    return steps;
}

function TweetCounts() {
    const data = new Map();

    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    function upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    return {
        recordTweet: function (tweetName, time) {
            if (!data.has(tweetName)) data.set(tweetName, []);
            const arr = data.get(tweetName);
            const idx = lowerBound(arr, time);
            arr.splice(idx, 0, time);
        },

        getTweetCountsPerFrequency: function (freq, tweetName, startTime, endTime) {
            const bucketSize = freq === 'minute' ? 60 :
                               freq === 'hour'   ? 3600 :
                               86400;

            const bucketCount = Math.floor((endTime - startTime) / bucketSize) + 1;
            const counts = new Array(bucketCount).fill(0);

            const arr = data.get(tweetName);
            if (!arr) return counts;

            const left = lowerBound(arr, startTime);
            const right = upperBound(arr, endTime);

            for (let i = left; i < right; ++i) {
                const bucket = Math.floor((arr[i] - startTime) / bucketSize);
                counts[bucket]++;
            }
            return counts;
        }
    };
}

function maxStudents(seats) {
    const m = seats.length, n = seats[0].length;
    const rowMask = new Array(m).fill(0);
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) if (seats[i][j] === '.') rowMask[i] |= (1 << j);
    const full = 1 << n;
    const validMasks = [];
    for (let mask = 0; mask < full; mask++) if ((mask & (mask << 1)) === 0) validMasks.push(mask);
    let dp = new Map([[0, 0]]);
    for (let i = 0; i < m; i++) {
        const ndp = new Map();
        for (const mask of validMasks) {
            if ((mask & ~rowMask[i]) !== 0) continue;
            let cnt = 0, mm = mask; while (mm) { cnt += mm & 1; mm >>= 1; }
            for (const [pmask, pval] of dp) {
                if ((mask & (pmask << 1)) || (mask & (pmask >> 1))) continue;
                const val = pval + cnt;
                if (!ndp.has(mask) || ndp.get(mask) < val) ndp.set(mask, val);
            }
        }
        dp = ndp;
    }
    let best = 0;
    for (const v of dp.values()) best = Math.max(best, v);
    return best;
}

function createProductOfNumbers() {
    const prefix = [1];                 // prefix[i] = product of first i numbers (excluding zeros)

    return {
        add: function(num) {
            if (num === 0) {
                // reset on zero: discard all previous products
                prefix.length = 1;
            } else {
                // store cumulative product
                prefix.push(prefix[prefix.length - 1] * num);
            }
        },
        getProduct: function(k) {
            // if k exceeds stored length, a zero occurred within the last k numbers
            if (k >= prefix.length) return 0;
            // product of last k = total product / product before those k numbers
            return prefix[prefix.length - 1] / prefix[prefix.length - 1 - k];
        }
    };
}

var isPossible = function(target) {
    if (target.length === 1) return target[0] === 1;
    let total = 0;
    const arr = target.slice();
    for (const v of arr) total += v;
    while (true) {
        arr.sort((a,b) => b-a);
        const mx = arr.shift();
        const rest = total - mx;
        if (mx === 1 || rest === 1) return true;
        if (rest === 0 || mx < rest) return false;
        let prev = mx % rest;
        if (prev === 0) prev = rest;
        if (prev < 1) return false;
        total = rest + prev;
        arr.push(prev);
    }
};

function countNegatives(grid) {
    const rows = grid.length;
    if (rows === 0) return 0;
    const cols = grid[0].length;

    let r = rows - 1;   // start from bottom‑left corner
    let c = 0;
    let count = 0;

    while (r >= 0 && c < cols) {
        if (grid[r][c] < 0) {
            // current element is negative → all elements to the right are also negative
            count += cols - c;
            r--;               // move up to the previous row
        } else {
            c++;               // move right to find first negative in this row
        }
    }
    return count;
}

function maxEvents(events) {
    // sort by start day
    events.sort((a, b) => a[0] - b[0]);

    // ----- min‑heap for end days -----
    const heap = [];
    const push = (val) => {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        if (heap.length === 0) return undefined;
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1,
                    r = i * 2 + 2,
                    smallest = i;
                if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
                if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    };
    const peek = () => (heap.length ? heap[0] : undefined);
    // ----------------------------------

    let i = 0;               // index in sorted events
    let day = 0;             // current day
    let attended = 0;
    const n = events.length;

    while (i < n || heap.length) {
        // jump to next start day if nothing is available now
        if (heap.length === 0) day = events[i][0];

        // add all events that start today or earlier
        while (i < n && events[i][0] <= day) {
            push(events[i][1]);
            i++;
        }

        // discard events that already ended
        while (heap.length && peek() < day) pop();

        // attend the event that ends earliest
        if (heap.length) {
            pop();
            attended++;
            day++;               // move to next day
        } else {
            // no event can be attended today, will jump in next loop
            day++;
        }
    }
    return attended;
}

function sortByBits(arr) {
    const bitCount = new Map();

    // count set bits using Kernighan's algorithm
    function countBits(x) {
        let cnt = 0;
        while (x) {
            x &= x - 1;
            cnt++;
        }
        return cnt;
    }

    // pre‑compute bit counts for all numbers
    for (let i = 0; i < arr.length; i++) {
        bitCount.set(arr[i], countBits(arr[i]));
    }

    // sort by bit count, then by numeric value
    arr.sort((a, b) => {
        const ca = bitCount.get(a);
        const cb = bitCount.get(b);
        if (ca !== cb) return ca - cb;
        return a - b;
    });

    return arr;
}

function Cashier(n, discount, products, prices) {
    // map each product id to its price for O(1) look‑ups
    const priceMap = new Map();
    for (let i = 0; i < products.length; i++) {
        priceMap.set(products[i], prices[i]);
    }

    let orderCount = 0;               // how many customers have been processed

    return {
        getBill: function(product, amount) {
            orderCount++;               // count this order

            let total = 0;
            for (let i = 0; i < product.length; i++) {
                total += amount[i] * priceMap.get(product[i]); // compute subtotal
            }

            // apply discount on every nth order
            if (orderCount % n === 0) {
                total = total * (100 - discount) / 100;
            }
            return total;
        }
    };
}

function countOrders(n) {
    const MOD = 1000000007n;          // use BigInt for exact modular arithmetic
    let fact = 1n;
    // compute (2n)! modulo MOD
    for (let i = 2n; i <= 2n * BigInt(n); i++) {
        fact = (fact * i) % MOD;
    }
    // compute 2^n modulo MOD
    let pow2 = 1n, base = 2n, exp = BigInt(n);
    while (exp > 0) {                  // fast exponentiation
        if (exp & 1n) pow2 = (pow2 * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1n;
    }
    // modular inverse of 2^n : (2^n)^(MOD-2) mod MOD
    let inv = 1n, b = pow2, e = MOD - 2n;
    while (e > 0) {
        if (e & 1n) inv = (inv * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1n;
    }
    return Number((fact * inv) % MOD);
}

function numberOfSubstrings(s) {
    const cnt = { a: 0, b: 0, c: 0 };
    let left = 0;
    let ans = 0;

    for (let right = 0; right < s.length; right++) {
        cnt[s[right]]++;                     // add new char to the window

        // shrink window while it still contains a, b and c
        while (cnt.a > 0 && cnt.b > 0 && cnt.c > 0) {
            cnt[s[left]]--;                  // remove leftmost char
            left++;                          // move left border
        }

        // 'left' is now one position past the minimal valid start,
        // so exactly 'left' substrings ending at 'right' are valid
        ans += left;
    }

    return ans;
}

function validateBinaryTreeNodes(n, leftChild, rightChild) {
    // compute indegree for each node
    const indegree = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        const l = leftChild[i];
        const r = rightChild[i];
        if (l !== -1) indegree[l]++;          // left edge
        if (r !== -1) indegree[r]++;          // right edge
    }

    // find the unique root (indegree 0)
    let root = -1;
    for (let i = 0; i < n; i++) {
        if (indegree[i] === 0) {
            if (root !== -1) return false;   // more than one root
            root = i;
        }
    }
    if (root === -1) return false;            // no root

    // traverse the tree from the root, checking for cycles / disconnected nodes
    const visited = new Array(n).fill(false);
    const stack = [root];
    while (stack.length) {
        const node = stack.pop();
        if (visited[node]) return false;      // cycle detected
        visited[node] = true;
        const l = leftChild[node];
        const r = rightChild[node];
        if (l !== -1) stack.push(l);
        if (r !== -1) stack.push(r);
    }

    // all nodes must be visited exactly once
    for (let i = 0; i < n; i++) {
        if (!visited[i]) return false;
    }
    return true;
}

function daysBetween(date1, date2) {
    // parse the first date
    const [y1, m1, d1] = date1.split('-').map(Number);
    // parse the second date
    const [y2, m2, d2] = date2.split('-').map(Number);

    // create UTC timestamps (months are zero‑based)
    const t1 = Date.UTC(y1, m1 - 1, d1);
    const t2 = Date.UTC(y2, m2 - 1, d2);

    // absolute difference in days
    const diffMs = Math.abs(t1 - t2);
    return diffMs / (1000 * 60 * 60 * 24);
}

function closestDivisors(num) {
    let bestDiff = Infinity;
    let bestPair = [];

    // examine num+1 and num+2
    for (let product of [num + 1, num + 2]) {
        const limit = Math.floor(Math.sqrt(product));

        // MAIN LOGIC: search downward from sqrt(product) for the first divisor
        for (let i = limit; i >= 1; i--) {
