function minCost(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = 1e9;
    const dist = Array.from({ length: m }, () => Array(n).fill(INF));

    // ----- binary min‑heap helpers -----
    const heap = [];
    const push = (c, i, j) => {
        heap.push([c, i, j]);
        let idx = heap.length - 1;
        while (idx > 0) {
            const p = (idx - 1) >> 1;
            if (heap[p][0] <= heap[idx][0]) break;
            [heap[p], heap[idx]] = [heap[idx], heap[p]];
            idx = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let idx = 0;
            while (true) {
                let l = idx * 2 + 1,
                    r = idx * 2 + 2,
                    smallest = idx;
                if (l < heap.length && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.length && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest === idx) break;
                [heap[smallest], heap[idx]] = [heap[idx], heap[smallest]];
                idx = smallest;
            }
        }
        return top;
    };
    // ----------------------------------

    dist[0][0] = 0;
    push(0, 0, 0);

    // directions: right, left, down, up with their sign numbers
    const dirs = [
        [0, 1, 1],
        [0, -1, 2],
        [1, 0, 3],
        [-1, 0, 4],
    ];

    // Dijkstra / 0‑1 BFS main loop
    while (heap.length) {
        const [cost, i, j] = pop();
        if (cost !== dist[i][j]) continue; // stale entry
        if (i === m - 1 && j === n - 1) return cost; // reached target

        for (const [dx, dy, dir] of dirs) {
            const ni = i + dx,
                nj = j + dy;
            if (ni < 0 || nj < 0 || ni >= m || nj >= n) continue;

            // no extra cost if we follow the current sign, otherwise +1
            const newCost = cost + (grid[i][j] === dir ? 0 : 1);
            if (newCost < dist[ni][nj]) {
                dist[ni][nj] = newCost;
                push(newCost, ni, nj);
            }
        }
    }
    return dist[m - 1][n - 1];
}

