function rankTeams(votes) {
    const n = votes[0].length;                     // number of positions / teams
    const counts = {};                             // team → array of position counts

    // initialise count arrays for each team
    for (const ch of votes[0]) {
        counts[ch] = new Array(n).fill(0);
    }

    // fill the counts
    for (const vote of votes) {
        for (let i = 0; i < n; i++) {
            const team = vote[i];
            counts[team][i]++;                     // count a vote for this team at position i
        }
    }

    const teams = Object.keys(counts);

    // sort according to the ranking rules
    teams.sort((a, b) => {
        for (let i = 0; i < n; i++) {
            if (counts[a][i] !== counts[b][i]) {
