function frogPosition(n, edges, t, target) {
    // build adjacency list
    const graph = Array.from({ length: n + 1 }, () => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }

    const visited = new Array(n + 1).fill(false);
    let result = 0;

    function dfs(node, time, prob) {
        visited[node] = true;

        // if we reached the required time
        if (time === t) {
            if (node === target) result += prob;
            visited[node] = false;
            return;
        }

        // count unvisited neighbours
        const unvisitedNeighbors = graph[node].filter(v => !visited[v]);

        // if no where to go, frog stays forever
        if (unvisitedNeighbors.length === 0) {
            if (node === target) result += prob;
            visited[node] = false;
            return;
        }

        // distribute probability equally among all possible moves
        const nextProb = prob / unvisitedNeighbors.length;
        for (const next of unvisitedNeighbors) {
