function maxPerformance(n, speed, efficiency, k) {
    const MOD = 1_000_000_007;

    // Pair each engineer's efficiency with its speed
    const engineers = [];
    for (let i = 0; i < n; i++) {
        engineers.push([efficiency[i], speed[i]]);
    }

    // Sort by efficiency descending so the current engineer is the minimum efficiency of the team
    engineers.sort((a, b) => b[0] - a[0]);

    // Min‑heap to keep the k largest speeds (store speeds)
    const heap = [];
    const heapPush = (val) => {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (heap[parent] <= heap[idx]) break;
            [heap[parent], heap[idx]] = [heap[idx], heap[parent]];
            idx = parent;
        }
    };
    const heapPop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length === 0) return top;
