function hasValidPath(grid) {
    const m = grid.length, n = grid[0].length;
    const dr = [-1, 1, 0, 0]; // up, down, left, right
    const dc = [0, 0, -1, 1];
    const opposite = [1, 0, 3, 2];

    // corrected street-type -> allowed-directions table (see explanation)
    const allowed = {
        1: [2, 3], // left, right
        2: [0, 1], // up, down
        3: [2, 1], // left, down
        4: [3, 1], // right, down
        5: [2, 0], // left, up
        6: [3, 0]  // right, up
