    const visited = Array.from({ length: m }, () => Array(n).fill(false));
    const queue = [[0, 0]];
    visited[0][0] = true;

    while (queue.length) {
        const [r, c] = queue.shift();
        if (r === m - 1 && c === n - 1) return true;

        for (const dir of allowed[grid[r][c]]) {
            const nr = r + dr[dir];
            const nc = c + dc[dir];
            if (
                nr >= 0 && nr < m && nc >= 0 && nc < n &&
                !visited[nr][nc] &&
                allowed[grid[nr][nc]].includes(opposite[dir])
