        while (j > 0 && s[i] !== s[j]) {
            j = pi[j - 1];             // fall back to shorter border
        }
        if (s[i] === s[j]) {
            j++;                       // extend border by one character
        }
        pi[i] = j;                     // store longest border for prefix ending at i
