function UndergroundSystem() {
    const active = new Map();
    const stats = new Map();

    return {
        checkIn(id, stationName, t) {
            active.set(id, { station: stationName, time: t });
        },

        checkOut(id, stationName, t) {
            const info = active.get(id);
            const travelTime = t - info.time;
            const routeKey = info.station + '|' + stationName;

            const cur = stats.get(routeKey);
            if (cur) {
                cur.totalTime += travelTime;
                cur.trips += 1;
            } else {
                stats.set(routeKey, { totalTime: travelTime, trips: 1 });
            }

            active.delete(id);
        },

        getAverageTime(startStation, endStation) {
            const key = startStation + '|' + endStation;
            const data = stats.get(key);
            return data.totalTime / data.trips;
