function findGoodStrings(n, s1, s2, evil) {
    const MOD = 1000000007;
    const m = evil.length;
    const pi = new Array(m).fill(0);
    for (let i = 1; i < m; i++) {
        let j = pi[i-1];
        while (j > 0 && evil[i] !== evil[j]) j = pi[j-1];
        if (evil[i] === evil[j]) j++;
        pi[i] = j;
    }
    const nxt = Array.from({length:m}, () => new Array(26).fill(0));
    for (let k = 0; k < m; k++) {
        for (let c = 0; c < 26; c++) {
            const ch = String.fromCharCode(97+c);
            let j = k;
            while (j > 0 && ch !== evil[j]) j = pi[j-1];
            if (ch === evil[j]) j++;
            nxt[k][c] = j;
        }
    }
    let dp = [[new Array(m).fill(0), new Array(m).fill(0)], [new Array(m).fill(0), new Array(m).fill(0)]];
    dp[1][1][0] = 1;
    for (let pos = 0; pos < n; pos++) {
        const ndp = [[new Array(m).fill(0), new Array(m).fill(0)], [new Array(m).fill(0), new Array(m).fill(0)]];
        const s1c = s1.charCodeAt(pos), s2c = s2.charCodeAt(pos);
        for (let lower = 0; lower <= 1; lower++) {
            for (let upper = 0; upper <= 1; upper++) {
                const lowChar = lower ? s1c : 97;
                const highChar = upper ? s2c : 122;
                if (lowChar > highChar) continue;
                for (let matched = 0; matched < m; matched++) {
                    const cur = dp[lower][upper][matched];
                    if (!cur) continue;
                    for (let code = lowChar; code <= highChar; code++) {
                        const newLower = lower && (code===s1c) ? 1 : 0;
                        const newUpper = upper && (code===s2c) ? 1 : 0;
                        const newMatched = nxt[matched][code-97];
                        if (newMatched === m) continue;
                        ndp[newLower][newUpper][newMatched] = (ndp[newLower][newUpper][newMatched] + cur) % MOD;
                    }
                }
            }
        }
        dp = ndp;
    }
    let ans = 0;
    for (let lower = 0; lower <= 1; lower++)
        for (let upper = 0; upper <= 1; upper++)
            for (let matched = 0; matched < m; matched++)
                ans = (ans + dp[lower][upper][matched]) % MOD;
    return ans;
}

function findLucky(arr) {
    // Count frequencies of each number
    const freq = {};
    for (let i = 0; i < arr.length; i++) {
        const num = arr[i];
        freq[num] = (freq[num] || 0) + 1;
    }

    // Find the largest lucky integer
    let largestLucky = -1;
    for (const key in freq) {
        const value = Number(key);
        if (freq[key] === value && value > largestLucky) {
            largestLucky = value;
        }
    }
    return largestLucky;
}

function canConstruct(s, k) {
    // count character frequencies
    const freq = {};
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        freq[ch] = (freq[ch] || 0) + 1;
    }

    // count how many characters appear an odd number of times
    let oddCount = 0;
    for (const ch in freq) {
        if (freq[ch] % 2 === 1) oddCount++;
    }

    // main logic: need oddCount ≤ k ≤ s.length
    return oddCount <= k && k <= s.length;
}

function maxSatisfaction(satisfaction) {
    // sort descending so that larger satisfactions are tried first
    satisfaction.sort((a, b) => b - a);

    let curSum = 0;   // sum of satisfactions of dishes kept so far
    let best = 0;     // best total like‑time coefficient found

    for (let i = 0; i < satisfaction.length; i++) {
        curSum += satisfaction[i];          // include current dish
        if (curSum > 0) {
            best += curSum;                  // its addition improves the answer
        } else {
            break;                           // further dishes cannot help
        }
    }
    return best;
}

function countLargestGroup(n) {
    // map digit‑sum → how many numbers have this sum
    const freq = new Map();

    // helper: sum of decimal digits
    function digitSum(x) {
        let s = 0;
        while (x > 0) {
            s += x % 10;
            x = Math.floor(x / 10);
        }
        return s;
    }

    // MAIN LOGIC: count frequencies of each digit sum
    for (let i = 1; i <= n; i++) {
        const sum = digitSum(i);
        freq.set(sum, (freq.get(sum) || 0) + 1);
    }

    // find the largest group size
    let maxSize = 0;
    for (const cnt of freq.values()) {
        if (cnt > maxSize) maxSize = cnt;
    }

    // count how many groups have that size
    let answer = 0;
    for (const cnt of freq.values()) {
        if (cnt === maxSize) answer++;
    }
    return answer;
}

function checkOverlap(radius, xCenter, yCenter, x1, y1, x2, y2) {
    // Find the closest point on the rectangle to the circle's center
    const closestX = Math.max(x1, Math.min(xCenter, x2));
    const closestY = Math.max(y1, Math.min(yCenter, y2));

    const dx = xCenter - closestX;
    const dy = yCenter - closestY;

    // If the distance from the center to this point is within the radius, they overlap
    return dx * dx + dy * dy <= radius * radius;
}

function minSubsequence(nums) {
    // sort numbers in non‑increasing order
    nums.sort((a, b) => b - a);

    const totalSum = nums.reduce((s, v) => s + v, 0);
    const result = [];
    let chosenSum = 0;

    // keep taking the largest elements until their sum exceeds the rest
    for (let i = 0; i < nums.length; i++) {
        chosenSum += nums[i];
        result.push(nums[i]);
        if (chosenSum > totalSum - chosenSum) break;
    }
    return result;
}

function stoneGameIII(stoneValue) {
    const n = stoneValue.length;
    const dp = new Array(n + 1).fill(0);   // dp[i] = best (current - opponent) from i

    for (let i = n - 1; i >= 0; i--) {
        let take = 0;
        let best = -Infinity;
        // try taking 1, 2, or 3 stones starting at i
        for (let k = 1; k <= 3 && i + k <= n; k++) {
            take += stoneValue[i + k - 1];
            const net = take - dp[i + k];   // net score if we take k stones
            if (net > best) best = net;
        }
        dp[i] = best;                       // optimal net difference from position i
    }

    const diff = dp[0];
    if (diff > 0) return "Alice";
    if (diff < 0) return "Bob";
    return "Tie";
}

function stringMatching(words) {
    const result = new Set();
    const n = words.length;

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            // if words[i] contains words[j] as a substring, keep words[j]
            if (words[i].includes(words[j])) {
                result.add(words[j]);
            }
        }
    }
    return Array.from(result);
}

function processQueries(queries, m) {
    const P = Array.from({length:m}, (_,i)=>i+1);
    const result = [];
    for (const x of queries) {
        const idx = P.indexOf(x);
        result.push(idx);
        P.splice(idx,1);
        P.unshift(x);
    }
    return result;
}

function numberOfSteps(s) {
    // Edge case: already 1
    if (s === "1") return 0;

    let steps = 0;      // total operations
    let carry = 0;      // 0 or 1, result of previous odd‑add operations

    // Process bits from least significant to the second most significant
    for (let i = s.length - 1; i > 0; i--) {
        const bit = s.charCodeAt(i) - 48;   // 0 or 1
        const sum = bit + carry;            // current effective bit

        if (sum === 0) {
            // even → just divide by 2
            steps += 1;
        } else if (sum === 1) {
            // odd → add 1 (makes it even) then divide by 2
            steps += 2;
            carry = 1;                       // addition creates a carry
        } else { // sum === 2
            // effective bit is 0 with a carry already present
            // just divide by 2, carry stays 1
            steps += 1;
        }
    }

    // After processing all but the most‑significant bit,
    // if a carry remains we need one extra division to reach 1
    steps += carry;
    return steps;
}

function longestDiverseString(a, b, c) {
  const items = [['a', a], ['b', b], ['c', c]];
  let result = '';
  while (true) {
    items.sort((x, y) => y[1] - x[1]);
    let placed = false;
    for (const item of items) {
      const [ch, cnt] = item;
      if (cnt <= 0) continue;
      const len = result.length;
      if (len >= 2 && result[len-1] === ch && result[len-2] === ch) continue;
      result += ch;
      item[1]--;
      placed = true;
      break;
    }
    if (!placed) break;
  }
  return result;
}

function entityParser(text) {
    const entityMap = {
        '&quot;': '"',
        '&apos;': "'",
        '&amp;': '&',
        '&gt;': '>',
        '&lt;': '<',
        '&frasl;': '/'
    };

    let result = '';
    let i = 0;
    while (i < text.length) {
        if (text[i] === '&') {                 // start of a possible entity
            let matched = false;
            for (const [entity, ch] of Object.entries(entityMap)) {
                if (text.startsWith(entity, i)) {
                    result += ch;              // replace entity with its character
                    i += entity.length;
                    matched = true;
                    break;
                }
            }
            if (!matched) {                    // not a known entity, keep '&'
                result += '&';
                i++;
            }
        } else {
            result += text[i];                  // regular character
            i++;
        }
    }
    return result;
}

function findMinFibonacciNumbers(k) {
    // build Fibonacci numbers up to k
    const fib = [1, 1];
    while (fib[fib.length - 1] < k) {
        fib.push(fib[fib.length - 1] + fib[fib.length - 2]);
    }

    let count = 0;
    let remaining = k;

    // MAIN LOGIC: repeatedly subtract the largest Fibonacci number not exceeding the remaining sum
    while (remaining > 0) {
        // binary search for the largest fib <= remaining
        let left = 0, right = fib.length - 1;
        while (left < right) {
            const mid = Math.floor((left + right + 1) / 2);
            if (fib[mid] <= remaining) left = mid;
            else right = mid - 1;
        }
        remaining -= fib[left];
        count++;
    }

    return count;
}

function restoreArray(s, k) {
    const MOD = 1000000007;
    const n = s.length;
    const maxLen = k.toString().length;          // longest possible number
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;

    for (let i = 1; i <= n; i++) {
        // MAIN LOGIC: try every possible length of the last number
        for (let len = 1; len <= maxLen; len++) {
            if (i - len < 0) break;               // substring would start before string
            if (s[i - len] === '0') continue;     // leading zero not allowed
            const sub = s.slice(i - len, i);
            const val = Number(sub);
            if (val > k) break;                    // larger lengths will only increase the value
            dp[i] = (dp[i] + dp[i - len]) % MOD;
        }
    }
    return dp[n];
}

function numOfWays(n) {
    const MOD = 1_000_000_007;

    // base case for one row
    let same = 6; // patterns ABA
    let diff = 6; // patterns ABC

    for (let i = 2; i <= n; i++) {
        // transition from previous row to current row
        const newSame = (same * 3 + diff * 2) % MOD;
        const newDiff = (same * 2 + diff * 2) % MOD;
        same = newSame;
        diff = newDiff;
    }

    return (same + diff) % MOD;
}

function getHappyString(n, k) {
    const total = 3 * (1 << (n - 1));
    if (k > total) return "";
    const letters = ['a','b','c'];
    let result = "";
    let remaining = k;
    let blockSize = total / 3;
    for (let pos = 0; pos < n; pos++) {
        const idx = Math.floor((remaining - 1) / blockSize);
        let choice;
        if (pos === 0) {
            choice = letters[idx];
        } else {
            const prev = result[pos-1];
            const options = letters.filter(l => l !== prev);
            choice = options[idx];
        }
        result += choice;
        remaining -= idx * blockSize;
        if (pos < n - 1) blockSize /= 2;
    }
    return result;
}

function minStartValue(nums) {
    let sum = 0;
    let minPrefix = 0;               // track the smallest prefix sum

    for (let num of nums) {
        sum += num;
        if (sum < minPrefix) {
            minPrefix = sum;          // update when a new lower sum appears
        }
    }

    // we need startValue + minPrefix >= 1  →  startValue >= 1 - minPrefix
    return Math.max(1, 1 - minPrefix);
}

function reformatString(s) {
    // 1. Separate letters and digits
    const letters = [];
    const digits = [];
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch >= '0' && ch <= '9') {
            digits.push(ch);
        } else {
            letters.push(ch);
        }
    }

    // 2. If the counts differ by more than 1, impossible
    if (Math.abs(letters.length - digits.length) > 1) {
        return "";
    }

    // 3. Decide which type starts the result
    const startWithLetter = letters.length >= digits.length;
    const first = startWithLetter ? letters : digits;
    const second = startWithLetter ? digits : letters;

    // 4. Interleave characters from the two groups
    const result = [];
    const n = Math.max(first.length, second.length);
    for (let i = 0; i < n; i++) {
        if (i < first.length) result.push(first[i]);
        if (i < second.length) result.push(second[i]);
    }

    return result.join('');
}

var displayTable = function(orders) {
    const foods = new Set();
    const tableCounts = new Map();
    for (const [, tableStr, food] of orders) {
        const table = parseInt(tableStr, 10);
        foods.add(food);
        if (!tableCounts.has(table)) tableCounts.set(table, new Map());
        const m = tableCounts.get(table);
        m.set(food, (m.get(food)||0)+1);
    }
    const sortedFoods = Array.from(foods).sort();
    const result = [];
    result.push(["Table", ...sortedFoods]);
    const tables = Array.from(tableCounts.keys()).sort((a,b)=>a-b);
    for (const table of tables) {
        const row = [String(table)];
        const counts = tableCounts.get(table);
        for (const food of sortedFoods) row.push(String(counts.get(food) || 0));
        result.push(row);
    }
    return result;
};

var minNumberOfFrogs = function(croakOfFrogs) {
    const mapping = {c:0,r:1,o:2,a:3,k:4};
    const cnt = [0,0,0,0,0];
    let frogs = 0, maxFrogs = 0;
    for (const ch of croakOfFrogs) {
        if (!(ch in mapping)) return -1;
        const idx = mapping[ch];
        cnt[idx]++;
        if (idx > 0) {
            cnt[idx-1]--;
            if (cnt[idx-1] < 0) return -1;
        }
        if (ch === 'c') {
            frogs++;
            if (frogs > maxFrogs) maxFrogs = frogs;
        } else if (ch === 'k') {
            frogs--;
        }
    }
    return frogs === 0 ? maxFrogs : -1;
};

function numOfArrays(n, m, k) {
    const MOD = 1000000007n;
    if (k === 0) return 0;
    let dp = Array.from({length:m+1}, () => new Array(k+1).fill(0n));
    for (let j = 1; j <= m; j++) dp[j][1] = 1n;
    for (let i = 2; i <= n; i++) {
        const ndp = Array.from({length:m+1}, () => new Array(k+1).fill(0n));
        for (let j = 1; j <= m; j++) {
            for (let c = 1; c <= k; c++) {
                if (dp[j][c] === 0n) continue;
                ndp[j][c] = (ndp[j][c] + dp[j][c] * BigInt(j)) % MOD;
                if (c+1 <= k) {
                    for (let v = j+1; v <= m; v++) ndp[v][c+1] = (ndp[v][c+1] + dp[j][c]) % MOD;
                }
            }
        }
        dp = ndp;
    }
    let ans = 0n;
    for (let j = 1; j <= m; j++) ans = (ans + dp[j][k]) % MOD;
    return Number(ans);
}

function maxScore(s) {
    const n = s.length;
    let totalOnes = 0;
    for (let i = 0; i < n; i++) {
        if (s[i] === '1') totalOnes++;
    }

    let zerosLeft = 0;
    let onesSeen = 0;
    let maxScore = 0;

    // evaluate every split that leaves a non‑empty right part
    for (let i = 0; i < n - 1; i++) {
        if (s[i] === '0') zerosLeft++; else onesSeen++;
        const score = zerosLeft + (totalOnes - onesSeen); // score for split after i
        if (score > maxScore) maxScore = score;
    }
    return maxScore;
}

function findDiagonalOrder(nums) {
    // 1️⃣ bucket elements by their diagonal index (i + j)
    const buckets = [];                     // array of arrays
    for (let i = 0; i < nums.length; i++) {
        const row = nums[i];
        for (let j = 0; j < row.length; j++) {
            const d = i + j;
            if (!buckets[d]) buckets[d] = [];
            buckets[d].push(row[j]);        // keep original order (increasing i)
        }
    }

    // 2️⃣ build the result by reading each bucket backwards
    const result = [];
    for (let d = 0; d < buckets.length; d++) {
        const diag = buckets[d];
        if (!diag) continue;
        for (let k = diag.length - 1; k >= 0; k--) {
            result.push(diag[k]);            // reverse to get larger i first
        }
    }
    return result;
}

function constrainedSubsequenceSum(nums, k) {
    const n = nums.length;
    const dp = new Array(n);
    const deque = [];               // stores indices with decreasing dp values
    dp[0] = nums[0];
    let answer = dp[0];
    deque.push(0);

    for (let i = 1; i < n; i++) {
        // discard indices that are farther than k from i
        while (deque.length && deque[0] < i - k) deque.shift();

        // best previous sum within window (or 0 to start new subsequence)
        const bestPrev = dp[deque[0]] > 0 ? dp[deque[0]] : 0;
        dp[i] = nums[i] + bestPrev;
        if (dp[i] > answer) answer = dp[i];

        // maintain decreasing order of dp values in deque
        while (deque.length && dp[deque[deque.length - 1]] <= dp[i]) deque.pop();
        deque.push(i);
    }
    return answer;
}

function maxScore(cardPoints, k) {
    const n = cardPoints.length;
    let total = 0;
    for (let v of cardPoints) total += v;          // total sum of all cards

    const windowSize = n - k;                      // length of the subarray we will NOT take
    if (windowSize === 0) return total;           // take all cards

    // initial sum of the first window
    let windowSum = 0;
    for (let i = 0; i < windowSize; i++) windowSum += cardPoints[i];
    let minWindowSum = windowSum;                  // track minimum window sum

    // slide the window across the array
    for (let i = windowSize; i < n; i++) {
        windowSum += cardPoints[i] - cardPoints[i - windowSize];
        if (windowSum < minWindowSum) minWindowSum = windowSum; // update minimum
    }

    return total - minWindowSum;                   // max score = total - min excluded sum
}

function kidsWithGreatestCandies(candies, extraCandies) {
    // find the current maximum number of candies
    let maxCandies = 0;
    for (let i = 0; i < candies.length; i++) {
        if (candies[i] > maxCandies) maxCandies = candies[i];
    }

    // determine for each kid if they can reach or exceed the maximum
    const result = new Array(candies.length);
    for (let i = 0; i < candies.length; i++) {
        result[i] = candies[i] + extraCandies >= maxCandies;
    }
    return result;
}

function canBreak(s1, s2) {
    // sort both strings to get the smallest possible permutations
    const a = s1.split('').sort();
    const b = s2.split('').sort();

    // check if a[i] >= b[i] for every position
    let aBreaksB = true;
    for (let i = 0; i < a.length; i++) {
        if (a[i] < b[i]) { aBreaksB = false; break; }
    }

    // check if b[i] >= a[i] for every position
    let bBreaksA = true;
    for (let i = 0; i < b.length; i++) {
        if (b[i] < a[i]) { bBreaksA = false; break; }
    }

    return aBreaksB || bBreaksA;
}

function maxDiff(num) {
    const s = String(num);
    let a = s, b = s;
    for (let i = 0; i < s.length; i++) {
        if (s[i] !== '9') { a = s.split('').map(c => c === s[i] ? '9' : c).join(''); break; }
    }
    if (s[0] !== '1') {
        b = s.split('').map(c => c === s[0] ? '1' : c).join('');
    } else {
        for (let i = 1; i < s.length; i++) {
            if (s[i] !== '0' && s[i] !== s[0]) {
                b = s.split('').map(c => c === s[i] ? '0' : c).join('');
                break;
            }
        }
    }
    return parseInt(a) - parseInt(b);
}

function numberWays(hats) {
    const MOD = 1000000007;
    const n = hats.length;
    const totalMask = 1 << n;

    // people who like each hat (1‑based index)
    const peopleForHat = Array.from({ length: 41 }, () => []);
    for (let person = 0; person < n; person++) {
        for (const h of hats[person]) {
            peopleForHat[h].push(person);
        }
    }

    const dp = new Array(totalMask).fill(0);
    dp[0] = 1; // empty assignment

    // iterate over all hat types
    for (let hat = 1; hat <= 40; hat++) {
        const candidates = peopleForHat[hat];
        if (candidates.length === 0) continue;

        // update masks in decreasing order to avoid re‑using the same hat
        for (let mask = totalMask - 1; mask >= 0; mask--) {
            const curWays = dp[mask];
            if (curWays === 0) continue; // skip unreachable states

            // try giving this hat to each still‑free person who likes it
            for (const p of candidates) {
                if ((mask & (1 << p)) === 0) {
                    const newMask = mask | (1 << p);
                    dp[newMask] = (dp[newMask] + curWays) % MOD;
                }
            }
        }
    }

    return dp[totalMask - 1];
}

function kthSmallestSum(mat, k) {
    // ---------- min‑heap implementation ----------
    class MinHeap {
        constructor() { this.heap = []; }
        size() { return this.heap.length; }
        push(node) {
            const h = this.heap;
            h.push(node);
            let i = h.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (h[p][0] <= h[i][0]) break;
                [h[p], h[i]] = [h[i], h[p]];
                i = p;
            }
        }
        pop() {
            const h = this.heap;
            if (h.length === 0) return null;
            const top = h[0];
            const last = h.pop();
            if (h.length) {
                h[0] = last;
                let i = 0;
                while (true) {
                    let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                    if (l < h.length && h[l][0] < h[smallest][0]) smallest = l;
                    if (r < h.length && h[r][0] < h[smallest][0]) smallest = r;
                    if (smallest === i) break;
                    [h[i], h[smallest]] = [h[smallest], h[i]];
                    i = smallest;
                }
            }
            return top;
        }
    }
    // ---------- main logic ----------
    // start with the first row as the initial list of sums
    let sums = mat[0].slice();               // already sorted
    for (let rowIdx = 1; rowIdx < mat.length; rowIdx++) {
        const row = mat[rowIdx];
        const heap = new MinHeap();
        const limit = Math.min(k, sums.length);
        // push the smallest candidate for each partial sum
        for (let i = 0; i < limit; i++) {
            heap.push([sums[i] + row[0], i, 0]); // [total, indexInSums, indexInRow]
        }
        const newSums = [];
        // extract up to k smallest combined sums
        while (newSums.length < k && heap.size() > 0) {
            const [total, i, j] = heap.pop();
            newSums.push(total);
            if (j + 1 < row.length) {
                heap.push([sums[i] + row[j + 1], i, j + 1]);
            }
        }
        sums = newSums;                       // keep only the k smallest so far
    }
    return sums[k - 1];                       // kth smallest overall sum
}

function destCity(paths) {
    const startCities = new Set();               // collect all cities that have outgoing paths
    for (const [src, dst] of paths) {
        startCities.add(src);
    }

    for (const [, dst] of paths) {               // the city that never appears as a source is the destination
        if (!startCities.has(dst)) {
            return dst;
        }
    }
}

function areAllOnesKPlacesAway(nums, k) {
    let lastOneIdx = -1;                     // store index of previous 1
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 1) {
            // if a previous 1 exists and the gap is smaller than k, fail
            if (lastOneIdx !== -1 && i - lastOneIdx - 1 < k) {
                return false;
            }
            lastOneIdx = i;                  // update last seen 1
        }
    }
    return true;
}

function longestSubarray(nums, limit) {
    const maxDeque = []; // stores indices of candidates for max, decreasing values
    const minDeque = []; // stores indices of candidates for min, increasing values
    let left = 0;
    let best = 0;

    for (let right = 0; right < nums.length; right++) {
        // maintain decreasing maxDeque
        while (maxDeque.length && nums[right] > nums[maxDeque[maxDeque.length - 1]]) {
            maxDeque.pop();
        }
        maxDeque.push(right);

        // maintain increasing minDeque
        while (minDeque.length && nums[right] < nums[minDeque[minDeque.length - 1]]) {
            minDeque.pop();
        }
        minDeque.push(right);

        // shrink window while diff exceeds limit
        while (nums[maxDeque[0]] - nums[minDeque[0]] > limit) {
            if (maxDeque[0] === left) maxDeque.shift();
            if (minDeque[0] === left) minDeque.shift();
            left++;
        }

        // update answer
        best = Math.max(best, right - left + 1);
    }

    return best;
}

function countTriplets(arr) {
    const n = arr.length;
    let pref = 0;
    const xorMap = new Map();
    xorMap.set(0, [1, 0]);
    let ans = 0;
    for (let idx = 1; idx <= n; idx++) {
        pref ^= arr[idx - 1];
        const [cnt, posSum] = xorMap.get(pref) || [0, 0];
        ans += cnt * (idx - 1) - posSum;
        xorMap.set(pref, [cnt + 1, posSum + idx]);
    }
    return ans;
}

function minTime(n, edges, hasApple) {
    // build adjacency list
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }

    // depth‑first search returning time needed for subtree and back to node
    function dfs(node, parent) {
        let timeNeeded = 0;
        for (const neigh of graph[node]) {
            if (neigh === parent) continue;               // avoid revisiting parent
            const childTime = dfs(neigh, node);           // time for child's subtree
            // if child subtree has an apple (or the child itself), we must go there and back
            if (childTime > 0 || hasApple[neigh]) {
                timeNeeded += childTime + 2;              // travel edge twice
            }
        }
        return timeNeeded;
    }

    return dfs(0, -1);
}

function ways(pizza, k) {
    const MOD = 1000000007;
    const n = pizza.length, m = pizza[0].length;
    const apples = Array.from({length:n+1}, () => new Array(m+1).fill(0));
    for (let i = n-1; i >= 0; i--) {
        for (let j = m-1; j >= 0; j--) {
            apples[i][j] = (pizza[i][j]==='A'?1:0) + apples[i+1][j] + apples[i][j+1] - apples[i+1][j+1];
        }
    }
    const memo = new Map();
    function dfs(i, j, pieces) {
        if (apples[i][j] === 0) return 0;
        if (pieces === 1) return 1;
        const key = i+','+j+','+pieces;
        if (memo.has(key)) return memo.get(key);
        let ans = 0;
        for (let r = i+1; r < n; r++) {
            if (apples[i][j] - apples[r][j] > 0) ans = (ans + dfs(r,j,pieces-1)) % MOD;
        }
        for (let c = j+1; c < m; c++) {
            if (apples[i][j] - apples[i][c] > 0) ans = (ans + dfs(i,c,pieces-1)) % MOD;
        }
        memo.set(key, ans);
        return ans;
    }
    return dfs(0,0,k) % MOD;
}

function buildArray(target, n) {
    const ops = [];          // operations to return
    let idx = 0;             // next index in target

    for (let i = 1; i <= n; i++) {
        if (idx === target.length) break;   // target already built

        if (i === target[idx]) {            // needed number
            ops.push("Push");               // keep it
            idx++;
        } else {                             // not needed
            ops.push("Push");
            ops.push("Pop");                // discard it
        }
    }
    return ops;
}

function busyStudent(startTime, endTime, queryTime) {
    let count = 0;
    // count students whose interval includes queryTime
    for (let i = 0; i < startTime.length; i++) {
        if (startTime[i] <= queryTime && queryTime <= endTime[i]) {
            count++;
        }
