}

function rearrangeWords(text) {
    // 1. split the sentence
    const originalWords = text.split(' ');
    // 2. lower‑case all words
    const lowerWords = originalWords.map(w => w.toLowerCase());

    // 3. stable sort by length
    const indexed = lowerWords.map((w, i) => ({ word: w, idx: i }));
    indexed.sort((a, b) => {
        if (a.word.length !== b.word.length) {
            return a.word.length - b.word.length;   // main logic: compare lengths
        }
        return a.idx - b.idx;                       // keep original order for ties
    });
    const sorted = indexed.map(obj => obj.word);

    // 4. capitalize the first word
    if (sorted.length > 0) {
        sorted[0] = sorted[0][0].toUpperCase() + sorted[0].slice(1);
    }

    // 5. join and return
    return sorted.join(' ');
}

function maxPower(s) {
    let maxLen = 0;               // track the longest run found
    let curLen = 0;               // length of the current run
    let prevChar = '';            // previous character in the scan

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch === prevChar) {    // same as previous → extend run
            curLen++;
        } else {                  // new character → start new run
            curLen = 1;
            prevChar = ch;
        }
        if (curLen > maxLen) {    // update maximum if needed
            maxLen = curLen;
        }
    }
    return maxLen;
}

function simplifiedFractions(n) {
    const fractions = [];

    for (let denominator = 2; denominator <= n; denominator++) {
        for (let numerator = 1; numerator < denominator; numerator++) {
            // keep only fractions that are already in lowest terms
            if (gcd(numerator, denominator) === 1) {
                fractions.push(numerator + '/' + denominator);
            }
        }
    }
    return fractions;
}

// Euclidean algorithm for greatest common divisor
function gcd(a, b) {
    while (b !== 0) {
        const temp = a % b;
        a = b;
        b = temp;
    }
    return a;
}

function countGoodNodes(root) {
    // helper returns count of good nodes in subtree, given the max value seen so far
    function dfs(node, maxSoFar) {
        if (!node) return 0;
        // a node is good if its value is at least the maximum on the path to it
        const isGood = node.val >= maxSoFar ? 1 : 0;
        const newMax = Math.max(maxSoFar, node.val);
        // explore left and right subtrees
        const leftCount = dfs(node.left, newMax);
        const rightCount = dfs(node.right, newMax);
        return isGood + leftCount + rightCount;
    }
    return dfs(root, -Infinity);
}

function largestNumber(cost, target) {
    // dpLen[i] = maximum number of digits we can paint with total cost i
    const dpLen = new Array(target + 1).fill(-1);
    dpLen[0] = 0;

    // fill dpLen
    for (let i = 1; i <= target; i++) {
        for (let d = 1; d <= 9; d++) {
            const c = cost[d - 1];
            if (i >= c && dpLen[i - c] !== -1) {
                dpLen[i] = Math.max(dpLen[i], dpLen[i - c] + 1);
            }
        }
    }

    if (dpLen[target] === -1) return "0";

    // reconstruct the largest number greedily from 9 down to 1
    let remaining = target;
    let length = dpLen[target];
    let result = "";

    for (let d = 9; d >= 1; d--) {
        const c = cost[d - 1];
        // try to place digit d as many times as possible
        while (remaining >= c && dpLen[remaining - c] === length - 1) {
            result += d;          // add digit d
            remaining -= c;       // reduce remaining cost
            length--;             // one digit placed
        }
    }

    return result;
}

function maxVowels(s, k) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    let currentCount = 0;
    let maxCount = 0;

    // Initialize the first window
    for (let i = 0; i < k && i < s.length; i++) {
        if (vowels.has(s[i])) currentCount++;
    }
    maxCount = currentCount;

    // Slide the window through the rest of the string
    for (let i = k; i < s.length; i++) {
        if (vowels.has(s[i])) currentCount++;               // add new char
        if (vowels.has(s[i - k])) currentCount--;           // remove leftmost char
        if (currentCount > maxCount) maxCount = currentCount; // update answer
    }

    return maxCount;
}

function peopleIndexes(favoriteCompanies) {
    const n = favoriteCompanies.length;
    const sets = new Array(n);
    for (let i = 0; i < n; i++) {
        sets[i] = new Set(favoriteCompanies[i]);   // build a set for fast lookup
    }

    const result = [];
    for (let i = 0; i < n; i++) {
        let isSubset = false;
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            if (favoriteCompanies[j].length < favoriteCompanies[i].length) continue; // j cannot be a superset
            // check whether list i is contained in list j
            let allPresent = true;
            for (const company of favoriteCompanies[i]) {
                if (!sets[j].has(company)) {
                    allPresent = false;
                    break;
                }
            }
            if (allPresent) {
                isSubset = true;
                break; // no need to look at other j's
            }
        }
        if (!isSubset) result.push(i);
    }
    return result;
}

function maxDarts(darts, r) {
    const n = darts.length;
    if (n === 0) return 0;
    const TWO_PI = Math.PI * 2;
    const EPS = 1e-9;
    let best = 1; // at least one dart can be covered (the centre can be on it)

    for (let i = 0; i < n; ++i) {
        const events = [];

        // build angular intervals for all other darts
        for (let j = 0; j < n; ++j) {
            if (i === j) continue;
            const dx = darts[j][0] - darts[i][0];
            const dy = darts[j][1] - darts[i][1];
            const d = Math.hypot(dx, dy);
            if (d > 2 * r + EPS) continue;               // cannot be together

            const theta = Math.atan2(dy, dx);
            const delta = Math.acos(d / (2 * r));

            let start = theta - delta;
            let end   = theta + delta;

            // normalize to [0, 2π)
            if (start < 0) start += TWO_PI;
            if (end   < 0) end   += TWO_PI;
            if (start >= TWO_PI) start -= TWO_PI;
            if (end   >= TWO_PI) end   -= TWO_PI;

            if (start > end) {
                // interval wraps around 0 → split into two
                events.push([start, 1]);
                events.push([TWO_PI, -1]);
                events.push([0, 1]);
                events.push([end, -1]);
            } else {
                events.push([start, 1]);
                events.push([end, -1]);
            }
        }

        // MAIN LOGIC: sweep the angular events to find maximal overlap
        events.sort((a, b) => {
            if (Math.abs(a[0] - b[0]) > EPS) return a[0] - b[0];
            return b[1] - a[1]; // start (+1) before end (-1) when angles equal
        });

        let cur = 0;
        for (const [, delta] of events) {
            cur += delta;
            if (cur + 1 > best) best = cur + 1; // +1 for dart i itself
        }
    }

    return best;
}

function findPrefixWord(sentence, searchWord) {
    const words = sentence.split(' ');
    for (let i = 0; i < words.length; i++) {
        // if the current word has searchWord as its prefix
        if (words[i].startsWith(searchWord)) {
            return i + 1;               // 1‑indexed position
        }
    }
    return -1;
}

function makeTwoArraysEqual(target, arr) {
    // If lengths differ, they can never be equal
    if (target.length !== arr.length) return false;

    const freq = new Map();               // count elements in target

    for (let i = 0; i < target.length; i++) {
        const val = target[i];
        freq.set(val, (freq.get(val) || 0) + 1);
    }

    // decrease counts using arr; any mismatch means impossible
    for (let i = 0; i < arr.length; i++) {
        const val = arr[i];
        if (!freq.has(val)) return false; // value not present in target
        const newCount = freq.get(val) - 1;
        if (newCount === 0) freq.delete(val);
        else freq.set(val, newCount);
    }

    // all counts matched if map is empty
    return freq.size === 0;
}

function pseudoPalindromicPaths(root) {
    let result = 0;

    function dfs(node, mask) {
        if (!node) return;
        // toggle the bit for the current node's value (1‑9)
        mask ^= 1 << node.val;

        // leaf node: check if mask has at most one bit set
        if (!node.left && !node.right) {
            if ((mask & (mask - 1)) === 0) result++;
            return;
        }

        dfs(node.left, mask);
        dfs(node.right, mask);
    }

    dfs(root, 0);
    return result;
}

function checkIfPrerequisite(numCourses, prerequisites, queries) {
    // reach[i][j] === true  ⇔  there is a path i → j
    const reach = Array.from({ length: numCourses }, () => Array(numCourses).fill(false));

    // direct edges
    for (const [a, b] of prerequisites) {
        reach[a][b] = true;
    }

    // Floyd‑Warshall: propagate reachability through intermediate vertices
    for (let k = 0; k < numCourses; k++) {
        for (let i = 0; i < numCourses; i++) {
            if (reach[i][k]) {                 // only continue if i can reach k
                for (let j = 0; j < numCourses; j++) {
                    if (reach[k][j]) {
                        reach[i][j] = true;   // i can reach j via k
                    }
                }
            }
        }
    }

    const answer = [];
    for (const [u, v] of queries) {
        answer.push(reach[u][v]);
    }
    return answer;
}

function maxDotProduct(nums1, nums2) {
    const m = nums1.length;
    const n = nums2.length;

    // dp[i][j] = max dot product using first i elements of nums1 and first j elements of nums2
    const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(-Infinity));

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            const prod = nums1[i - 1] * nums2[j - 1];
            // either pair these two elements (starting new or extending), or skip one of them
            dp[i][j] = Math.max(
                dp[i - 1][j - 1] + prod, // extend previous subsequence
                prod,                    // start a new subsequence with this pair
                dp[i - 1][j],            // skip nums1[i-1]
                dp[i][j - 1]             // skip nums2[j-1]
            );
        }
    }
    return dp[m][n];
}

function maxArea(h, w, horizontalCuts, verticalCuts) {
    const MOD = 1_000_000_007;

    horizontalCuts.sort((a, b) => a - b);
    verticalCuts.sort((a, b) => a - b);

    let maxHeight = Math.max(horizontalCuts[0], h - horizontalCuts[horizontalCuts.length - 1]);
    for (let i = 1; i < horizontalCuts.length; i++) {
        const gap = horizontalCuts[i] - horizontalCuts[i - 1];
        if (gap > maxHeight) maxHeight = gap;
    }

    let maxWidth = Math.max(verticalCuts[0], w - verticalCuts[verticalCuts.length - 1]);
    for (let i = 1; i < verticalCuts.length; i++) {
        const gap = verticalCuts[i] - verticalCuts[i - 1];
        if (gap > maxWidth) maxWidth = gap;
    }

    // convert back to Number - a BigInt return value isn't JSON-serializable
    // and doesn't match the expected numeric return type
    return Number((BigInt(maxHeight) * BigInt(maxWidth)) % BigInt(MOD));
}

function cherryPickup(grid) {
    const rows = grid.length, cols = grid[0].length;
    const NEG = -Infinity;
    let dp = Array.from({length: cols}, () => new Array(cols).fill(NEG));
    dp[0][cols-1] = grid[0][0] + (cols-1 === 0 ? 0 : grid[0][cols-1]);
    for (let r = 1; r < rows; r++) {
        const ndp = Array.from({length: cols}, () => new Array(cols).fill(NEG));
        for (let c1 = 0; c1 < cols; c1++) {
            for (let c2 = 0; c2 < cols; c2++) {
                if (dp[c1][c2] === NEG) continue;
                for (let d1 = -1; d1 <= 1; d1++) {
                    for (let d2 = -1; d2 <= 1; d2++) {
                        const nc1 = c1+d1, nc2 = c2+d2;
                        if (nc1 < 0 || nc1 >= cols || nc2 < 0 || nc2 >= cols) continue;
                        let val = dp[c1][c2] + grid[r][nc1];
                        if (nc1 !== nc2) val += grid[r][nc2];
                        if (val > ndp[nc1][nc2]) ndp[nc1][nc2] = val;
                    }
                }
            }
        }
        dp = ndp;
    }
    let best = 0;
    for (let c1 = 0; c1 < cols; c1++) for (let c2 = 0; c2 < cols; c2++) best = Math.max(best, dp[c1][c2]);
    return best;
}

function comb(n, k) {
    if (k < 0 || k > n) return 0;
    let res = 1;
    for (let i = 0; i < k; i++) res = res * (n-i) / (i+1);
    return Math.round(res);
}
function getProbability(balls) {
    const k = balls.length;
    const total = balls.reduce((a,b)=>a+b,0);
    const n = Math.floor(total/2);
    let dp = Array.from({length:n+1}, () => Array.from({length:k+1}, () => new Array(k+1).fill(0)));
    dp[0][0][0] = 1;
    for (const c of balls) {
        const newdp = Array.from({length:n+1}, () => Array.from({length:k+1}, () => new Array(k+1).fill(0)));
        for (let sel = 0; sel <= n; sel++) {
            for (let d1 = 0; d1 <= k; d1++) {
                for (let d2 = 0; d2 <= k; d2++) {
                    const cur = dp[sel][d1][d2];
                    if (!cur) continue;
                    for (let x = 0; x <= c; x++) {
                        const ns = sel + x;
                        if (ns > n) continue;
                        const nd1 = d1 + (x>0?1:0);
                        const nd2 = d2 + ((c-x)>0?1:0);
                        newdp[ns][nd1][nd2] += cur * comb(c,x);
                    }
                }
            }
        }
        dp = newdp;
    }
    let numerator = 0;
    for (let d = 0; d <= k; d++) numerator += dp[n][d][d];
    const denominator = comb(total, n);
    return Math.round((numerator/denominator) * 100000) / 100000;
}

function hasAllCodes(s, k) {
    if (s.length < k) return false;                 // quick reject

    const totalCodes = 1 << k;                      // 2^k possible codes
    const seen = new Set();
    const mask = totalCodes - 1;                     // keep only k bits
    let hash = 0;

    for (let i = 0; i < s.length; i++) {
        // slide window: shift left, add new bit, drop bits beyond k
        hash = ((hash << 1) & mask) | (s.charCodeAt(i) - 48);
        if (i >= k - 1) {                            // window is full
            seen.add(hash);
            if (seen.size === totalCodes) return true; // all codes found early
        }
    }
    return seen.size === totalCodes;
}

function maxProduct(nums) {
    let firstMax = -Infinity;
    let secondMax = -Infinity;

    for (let i = 0; i < nums.length; i++) {
        const val = nums[i];
        // keep track of the two largest numbers
        if (val > firstMax) {
            secondMax = firstMax;
            firstMax = val;
        } else if (val > secondMax) {
            secondMax = val;
        }
    }

    return (firstMax - 1) * (secondMax - 1);
}

function minReorder(n, connections) {
    // store original directed edges for quick lookup
    const directed = new Set();
    for (const [a, b] of connections) {
        directed.add(`${a}->${b}`);
    }

    // build undirected adjacency list
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of connections) {
        adj[a].push(b);
        adj[b].push(a);
    }

    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    let reversals = 0;

    while (stack.length) {
        const u = stack.pop();
        for (const v of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                // count edges that originally go away from the root
                if (directed.has(`${u}->${v}`)) {
                    reversals++;
                }
                stack.push(v);
            }
        }
    }

    return reversals;
}



// TIME: O(n) SPACE: O(n)

function BrowserHistory(homepage) {
    this.history = [homepage];   // store visited pages
    this.current = 0;            // index of the current page
}

// visit a new url, discarding any forward history
BrowserHistory.prototype.visit = function (url) {
    this.history.length = this.current + 1; // truncate forward part
    this.history.push(url);
    this.current++;                         // move to the new page
};

// move back up to 'steps' pages and return the current url
BrowserHistory.prototype.back = function (steps) {
    this.current = Math.max(0, this.current - steps);
    return this.history[this.current];
};

// move forward up to 'steps' pages and return the current url
BrowserHistory.prototype.forward = function (steps) {
    this.current = Math.min(this.history.length - 1, this.current + steps);
    return this.history[this.current];
};

// TIME: O(1) per operation SPACE: O(N) where N is the number of visited pages.

function minCost(houses, cost, m, n, target) {
    const INF = 1e15;

    // dp[t][c] = min cost up to current house with t neighborhoods and current color c (1‑based)
    let dp = Array.from({ length: target + 1 }, () => Array(n + 1).fill(INF));

    // initialize for the first house
    if (houses[0] !== 0) {
        dp[1][houses[0]] = 0;
    } else {
        for (let c = 1; c <= n; c++) dp[1][c] = cost[0][c - 1];
    }

    // process remaining houses
    for (let i = 1; i < m; i++) {
        const newDp = Array.from({ length: target + 1 }, () => Array(n + 1).fill(INF));
        const possibleColors = houses[i] !== 0 ? [houses[i]] : Array.from({ length: n }, (_, idx) => idx + 1);

        for (let prevT = 1; prevT <= target; prevT++) {
            for (let prevC = 1; prevC <= n; prevC++) {
                const prevCost = dp[prevT][prevC];
                if (prevCost === INF) continue;               // skip impossible states

                for (const curC of possibleColors) {
                    const addCost = houses[i] === 0 ? cost[i][curC - 1] : 0;
                    const curT = (curC === prevC) ? prevT : prevT + 1;
                    if (curT > target) continue;               // exceed target neighborhoods
                    const total = prevCost + addCost;
                    if (total < newDp[curT][curC]) newDp[curT][curC] = total; // update best
                }
            }
        }
        dp = newDp;
    }

    // answer is the minimum cost with exactly target neighborhoods
    let answer = INF;
    for (let c = 1; c <= n; c++) answer = Math.min(answer, dp[target][c]);
    return answer === INF ? -1 : answer;
}

function shuffle(nums, n) {
    const shuffled = [];                     // result array
    for (let i = 0; i < n; i++) {
        shuffled.push(nums[i]);              // add xi
        shuffled.push(nums[i + n]);          // add yi
    }
    return shuffled;
}

function finalPrices(prices) {
    const n = prices.length;
    const result = prices.slice();          // copy original prices
    const stack = [];                       // indices waiting for a smaller-or-equal price

    for (let i = 0; i < n; i++) {
        // current price is a discount for all previous items that are >= it
        while (stack.length && prices[i] <= prices[stack[stack.length - 1]]) {
            const idx = stack.pop();
            result[idx] = prices[idx] - prices[i];
        }
        stack.push(i);                      // current item may get a discount later
    }
    return result;                          // items left in stack keep original price
}

function SubrectangleQueries(rectangle) {
    // store the initial matrix
    this.rect = rectangle;
}

/* update all cells inside the given sub‑rectangle to newValue */
SubrectangleQueries.prototype.updateSubrectangle = function(row1, col1, row2, col2, newValue) {
    for (let r = row1; r <= row2; r++) {               // iterate rows in range
        for (let c = col1; c <= col2; c++) {           // iterate cols in range
            this.rect[r][c] = newValue;                // assign new value
        }
    }
};

/* return the value at the specified cell */
SubrectangleQueries.prototype.getValue = function(row, col) {
