};

// TIME: O((row2‑row1+1)*(col2‑col1+1)) for update, O(1) for getValue  SPACE: O(1) extra (besides the stored matrix)

function strongestValues(arr, k) {
    // sort a copy of the array to work with ordered values
    const sorted = arr.slice().sort((a, b) => a - b);
    const n = sorted.length;
    const centre = sorted[Math.floor((n - 1) / 2)]; // centre element

    let left = 0;
    let right = n - 1;
    const result = [];

    while (result.length < k) {
        const leftDiff = Math.abs(sorted[left] - centre);
        const rightDiff = Math.abs(sorted[right] - centre);

        // pick the stronger side (right side wins ties on value)
        if (rightDiff > leftDiff || (rightDiff === leftDiff && sorted[right] > sorted[left])) {
            result.push(sorted[right]);
            right--;
        } else {
            result.push(sorted[left]);
            left++;
        }
    }

    return result;
}

function findLeastNumOfUniqueInts(arr, k) {
    const freq = new Map();
    for (const x of arr) freq.set(x, (freq.get(x)||0)+1);
    const counts = [...freq.values()].sort((a,b)=>a-b);
    let distinct = counts.length;
    for (const c of counts) {
        if (k >= c) { k -= c; distinct--; }
        else break;
    }
    return distinct;
}

function minSumOfLengths(arr, target) {
  const n = arr.length;
  const best = new Array(n).fill(Infinity); // best[i] = min length of a target-sum subarray ending at or before i
  const prefixIndex = new Map();
  prefixIndex.set(0, -1);
  let prefixSum = 0;
  let ans = Infinity;
  let bestSoFar = Infinity;
  for (let i = 0; i < n; i++) {
    prefixSum += arr[i];
    if (prefixIndex.has(prefixSum - target)) {
      const startIdx = prefixIndex.get(prefixSum - target);
      const len = i - startIdx;
      if (startIdx >= 0 && bestSoFar !== Infinity) {
        ans = Math.min(ans, bestSoFar + len);
      }
      if (len < best[i]) best[i] = len;
    }
    best[i] = Math.min(best[i], i > 0 ? best[i-1] : Infinity);
    bestSoFar = best[i];
    prefixIndex.set(prefixSum, i);
  }
  return ans === Infinity ? -1 : ans;
}

function allocateMailboxes(houses, k) {
    houses.sort((a, b) => a - b);
    const n = houses.length;
    if (k >= n) return 0;

    // prefix sums for fast range sum queries
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + houses[i];

    // cost[i][j] = minimal total distance for houses i..j with one mailbox
    const cost = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = i; j < n; j++) {
            const mid = Math.floor((i + j) / 2);
            const left = houses[mid] * (mid - i) - (prefix[mid] - prefix[i]);
            const right = (prefix[j + 1] - prefix[mid + 1]) - houses[mid] * (j - mid);
            cost[i][j] = left + right;
        }
    }

    // dp[m][i] = minimal distance for first i+1 houses using m mailboxes
    const dp = Array.from({ length: k + 1 }, () => Array(n).fill(Infinity));
    for (let i = 0; i < n; i++) dp[1][i] = cost[0][i]; // one mailbox

    for (let m = 2; m <= k; m++) {
        for (let i = m - 1; i < n; i++) {
            let best = Infinity;
            // try placing the last mailbox covering houses p+1..i
            for (let p = m - 2; p < i; p++) {
                const cur = dp[m - 1][p] + cost[p + 1][i];
                if (cur < best) best = cur;
            }
            dp[m][i] = best;
        }
    }
    return dp[k][n - 1];
}

function runningSum(nums) {
    // accumulate each element with the sum of all previous elements
    for (let i = 1; i < nums.length; i++) {
        nums[i] += nums[i - 1];
    }
    return nums;
}

function xorOperation(n, start) {
    let xor = 0;
    // iterate through the generated array and accumulate XOR
    for (let i = 0; i < n; i++) {
        xor ^= start + 2 * i;
    }
    return xor;
}

function getFolderNames(names) {
    const nextSuffix = {};          // maps a name to the smallest k to try next
    const result = [];

    for (let i = 0; i < names.length; i++) {
        const original = names[i];

        if (!(original in nextSuffix)) {          // name not used before
            result.push(original);
            nextSuffix[original] = 1;             // next k for this base name
        } else {
            let k = nextSuffix[original];
            let candidate = original + '(' + k + ')';

            // find the first unused candidate
            while (candidate in nextSuffix) {
                k++;
                candidate = original + '(' + k + ')';
            }

            result.push(candidate);
            nextSuffix[original] = k + 1;         // update next k for the base name
            nextSuffix[candidate] = 1;            // reserve the new name
        }
    }

    return result;
}

function minDays(bloomDay, m, k) {
    // impossible if not enough flowers
    if (m * k > bloomDay.length) return -1;

    // search range: earliest and latest bloom day
    let low = Math.min(...bloomDay);
    let high = Math.max(...bloomDay);

    // helper: can we make m bouquets by day 'day'?
    function canMake(day) {
        let bouquets = 0, consecutive = 0;
        for (let i = 0; i < bloomDay.length; i++) {
            if (bloomDay[i] <= day) {
                consecutive++;                     // flower is ready
                if (consecutive === k) {           // enough adjacent flowers
                    bouquets++;
                    consecutive = 0;               // start next bouquet
                    if (bouquets >= m) return true;
                }
            } else {
                consecutive = 0;                   // break the streak
            }
        }
        return false;
    }

    // binary search for the minimal feasible day
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (canMake(mid)) {
            high = mid;               // try earlier days
        } else {
            low = mid + 1;            // need more days
        }
    }
    return low;
}

function isPathCrossing(path) {
    let x = 0, y = 0;                     // current position
    const visited = new Set();            // stores visited coordinates
    visited.add('0,0');                    // origin is visited first

    for (let i = 0; i < path.length; i++) {
        const dir = path[i];
        // move one step according to direction
        if (dir === 'N') y++;
        else if (dir === 'S') y--;
        else if (dir === 'E') x++;
        else if (dir === 'W') x--;

        const key = x + ',' + y;          // encode position as string
        // if we have been here before, the path crosses itself
        if (visited.has(key)) return true;
        visited.add(key);
    }
    return false;
}

/**
 * Returns the k-th ancestor of a node in a rooted tree.
 *
 * @param {number[]} parent  - parent[i] is the parent of node i (parent[0] = -1)
 * @param {number} node      - the starting node
 * @param {number} k         - how many steps up the tree
 * @return {number}          - the k-th ancestor or -1 if it does not exist
 */
function kthAncestor(parent, node, k) {
    const n = parent.length;

    let maxPower = 0;
    while ((1 << maxPower) <= n) maxPower++;

    const up = Array.from({ length: maxPower }, () => new Array(n).fill(-1));

    for (let v = 0; v < n; v++) up[0][v] = parent[v];

    for (let p = 1; p < maxPower; p++) {
        for (let v = 0; v < n; v++) {
            const mid = up[p - 1][v];
            up[p][v] = mid === -1 ? -1 : up[p - 1][mid];
        }
    }

    let cur = node;
    let bit = 0;
    while (k > 0 && cur !== -1) {
        if (k & 1) cur = up[bit][cur];
        k >>= 1;
        bit++;
    }
    return cur;
}

function numSubseq(nums, target) {
    const MOD = 1000000007;
    const n = nums.length;
    if (n === 0) return 0;

    // sort to enable two‑pointer scan
    nums.sort((a, b) => a - b);

    // pre‑compute powers of 2 modulo MOD
    const pow2 = new Array(n);
    pow2[0] = 1;
    for (let i = 1; i < n; i++) {
        pow2[i] = (pow2[i - 1] * 2) % MOD;
    }

    let left = 0,
        right = n - 1,
        ans = 0;

    // main logic: move pointers to count valid subsequences
    while (left <= right) {
        if (nums[left] + nums[right] <= target) {
            // all subsets of the elements between left and right can be chosen
            ans = (ans + pow2[right - left]) % MOD;
            left++;
        } else {
            right--;
        }
    }
    return ans;
}

function avoidFlood(rains) {
    const n = rains.length;
    const ans = new Array(n).fill(1);
    const fullLakes = new Map();
    const dryDays = [];
    for (let i = 0; i < n; i++) {
        const lake = rains[i];
        if (lake === 0) { dryDays.push(i); continue; }
        ans[i] = -1;
        if (fullLakes.has(lake)) {
            const prev = fullLakes.get(lake);
            let found = -1;
            for (let d = 0; d < dryDays.length; d++) {
                if (dryDays[d] > prev) { found = d; break; }
            }
            if (found === -1) return [];
            ans[dryDays[found]] = lake;
            dryDays.splice(found, 1);
        }
        fullLakes.set(lake, i);
    }
    return ans;
}

function findCriticalAndPseudoCriticalEdges(n, edges) {
    const indexedEdges = edges.map(([u,v,w], i) => [u,v,w,i]);
    class DSU {
        constructor(size) { this.parent = Array.from({length:size},(_,i)=>i); this.rank = new Array(size).fill(0); }
        find(x) { while (this.parent[x]!==x) { this.parent[x]=this.parent[this.parent[x]]; x=this.parent[x]; } return x; }
        union(a,b) {
            let ra=this.find(a), rb=this.find(b);
            if (ra===rb) return false;
            if (this.rank[ra]<this.rank[rb]) [ra,rb]=[rb,ra];
            this.parent[rb]=ra;
            if (this.rank[ra]===this.rank[rb]) this.rank[ra]++;
            return true;
        }
    }
    const sortedEdges = [...indexedEdges].sort((a,b)=>a[2]-b[2]);
    const INF = 1e15;
    function mstWeight(skip=-1, force=-1) {
        const dsu = new DSU(n);
        let total = 0, used = 0;
        if (force !== -1) {
            const [u,v,w] = indexedEdges[force];
            if (dsu.union(u,v)) { total += w; used++; }
        }
        for (const [u,v,w,idx] of sortedEdges) {
            if (idx === skip) continue;
            if (dsu.union(u,v)) {
                total += w; used++;
                if (used === n-1) break;
            }
        }
        return used === n-1 ? total : INF;
    }
    const originalWeight = mstWeight();
    const critical = [], pseudo = [];
    for (const [,,,idx] of indexedEdges) {
        if (mstWeight(idx,-1) > originalWeight) critical.push(idx);
        else {
            if (mstWeight(-1,idx) === originalWeight) pseudo.push(idx);
        }
    }
    return [critical, pseudo];
}

function reformatDate(date) {
    const monthMap = {
        Jan: "01", Feb: "02", Mar: "03", Apr: "04",
        May: "05", Jun: "06", Jul: "07", Aug: "08",
        Sep: "09", Oct: "10", Nov: "11", Dec: "12"
    };

    const parts = date.split(' ');          // ["20th", "Oct", "2052"]
    const day = parts[0].slice(0, -2).padStart(2, '0'); // remove suffix, pad
    const month = monthMap[parts[1]];       // convert month abbreviation
    const year = parts[2];                  // keep year as is

    return `${year}-${month}-${day}`;
}

function canPair(arr, k) {
    // count how many numbers give each remainder modulo k
    const remainderCount = {};
    for (let i = 0; i < arr.length; i++) {
        const r = ((arr[i] % k) + k) % k; // normalize to [0, k-1]
        remainderCount[r] = (remainderCount[r] || 0) + 1;
    }

    // check the pairing conditions for each possible remainder
    for (let r in remainderCount) {
        r = Number(r);
        const cnt = remainderCount[r];

        if (r === 0) {                     // remainder 0 pairs with itself
            if (cnt % 2 !== 0) return false;
        } else if (k % 2 === 0 && r === k / 2) { // when k is even, remainder k/2 pairs with itself
            if (cnt % 2 !== 0) return false;
        } else {
            const complement = (k - r) % k;
            if (cnt !== (remainderCount[complement] || 0)) return false;
        }
    }
    return true;
}

function maxValueOfEquation(points, k) {
    const n = points.length;
    let best = -Infinity;                 // answer
    const dq = [];                        // stores indices, decreasing (yi - xi)

    for (let j = 0; j < n; j++) {
        const [xj, yj] = points[j];

        // remove indices that are farther than k from current xj
        while (dq.length && xj - points[dq[0]][0] > k) dq.shift();

        // use the best (yi - xi) from the front of the deque
        if (dq.length) {
            const i = dq[0];
            const candidate = (points[i][1] - points[i][0]) + yj + xj;
            if (candidate > best) best = candidate;
        }

        // maintain decreasing order of (yi - xi)
        const curVal = yj - xj;
        while (dq.length && (points[dq[dq.length - 1]][1] - points[dq[dq.length - 1]][0]) <= curVal) {
            dq.pop();
        }
        dq.push(j);
    }
    return best;
}

function stoneGameIV(n) {
    // generate all square numbers up to n
    const squares = [];
    for (let i = 1; i * i <= n; i++) {
        squares.push(i * i);
    }

    const win = new Array(n + 1).fill(false); // win[i] = true if current player can force a win with i stones

    // dp recurrence: win[i] is true if there exists a square s <= i such that win[i - s] is false
    for (let i = 1; i <= n; i++) {
        for (const s of squares) {
            if (s > i) break;
            if (!win[i - s]) { // opponent loses from i - s
                win[i] = true;
                break;
            }
        }
    }
    return win[n];
}

function minDifference(nums) {
    const n = nums.length;
    if (n <= 4) return 0;                     // we can change all but one element

    nums.sort((a, b) => a - b);               // sort to access extremes easily

    let best = Infinity;
    // try removing i smallest and (3-i) largest elements
    for (let i = 0; i <= 3; i++) {
        const lowIdx = i;                      // first kept element
        const highIdx = n - 1 - (3 - i);       // last kept element
        const diff = nums[highIdx] - nums[lowIdx];
        if (diff < best) best = diff;          // keep the minimal difference
    }
    return best;
}

var rangeSum = function(nums, n, left, right) {
    const MOD = 1000000007;
    const allSums = [];
    for (let i=0;i<n;i++) {
        let cur = 0;
        for (let j=i;j<n;j++) {
            cur += nums[j];
            allSums.push(cur);
        }
    }
    allSums.sort((a,b)=>a-b);
    let sum = 0;
    for (let k=left-1;k<right;k++) sum += allSums[k];
    return sum % MOD;
};

function maxWaterBottles(numBottles, numExchange) {
    let totalDrunk = numBottles;          // initial full bottles are drunk
    let emptyBottles = numBottles;        // they become empty after drinking

    // repeatedly exchange empty bottles for new full ones
    while (emptyBottles >= numExchange) {
        const newFull = Math.floor(emptyBottles / numExchange);
        totalDrunk += newFull;
        emptyBottles = (emptyBottles % numExchange) + newFull;
    }

    return totalDrunk;
}

function countOdds(low, high) {
    // first odd number >= low
    var first = (low % 2 === 1) ? low : low + 1;
    // last odd number <= high
    var last = (high % 2 === 1) ? high : high - 1;
    if (first > last) return 0;               // no odds in range
    // count = ((last - first) / 2) + 1
    return ((last - first) >> 1) + 1;
}

function countSubTrees(n, edges, labels) {
    // build adjacency list
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const answer = new Array(n).fill(0);

    // depth‑first search returning label frequencies of the subtree
    function dfs(node, parent) {
        const freq = new Array(26).fill(0);          // 26 letters

        for (const nxt of graph[node]) {
            if (nxt === parent) continue;            // avoid going back
            const childFreq = dfs(nxt, node);        // recurse
            for (let i = 0; i < 26; i++) {           // merge child frequencies
                freq[i] += childFreq[i];
            }
        }

        const idx = labels.charCodeAt(node) - 97;    // label of current node
        freq[idx]++;                                 // count itself
        answer[node] = freq[idx];                    // result for this node
        return freq;
    }

    dfs(0, -1);   // root is node 0
    return answer;
}

function bestPositionSum(positions) {
    const n = positions.length;
    if (n === 0) return 0;

    // start at the arithmetic mean of all points
    let cx = 0, cy = 0;
    for (let i = 0; i < n; ++i) {
        cx += positions[i][0];
        cy += positions[i][1];
    }
    cx /= n;
    cy /= n;

    const EPS = 1e-7;          // convergence tolerance
    while (true) {
        let numX = 0, numY = 0, denom = 0;
        let moved = false;

        for (let i = 0; i < n; ++i) {
            const dx = cx - positions[i][0];
            const dy = cy - positions[i][1];
            const dist = Math.hypot(dx, dy);

            // if current centre coincides with a data point → optimal
            if (dist === 0) {
                cx = positions[i][0];
                cy = positions[i][1];
                moved = false;
                break;
            }

            const w = 1 / dist;          // weight = 1 / distance
            numX += positions[i][0] * w;
            numY += positions[i][1] * w;
            denom += w;
        }

        const nextX = numX / denom;
        const nextY = numY / denom;

        // stop when the centre moves less than EPS
        if (Math.hypot(nextX - cx, nextY - cy) < EPS) break;

        cx = nextX;
        cy = nextY;
    }

    // compute the minimal sum of distances
    let total = 0;
    for (let i = 0; i < n; ++i) {
        total += Math.hypot(cx - positions[i][0], cy - positions[i][1]);
    }
    return total;
}

function maxNumOfSubstrings(s) {
    const n = s.length;
    const left = new Array(26).fill(-1);   // first index of each letter
    const right = new Array(26).fill(-1);  // last index of each letter

    // record first and last positions
    for (let i = 0; i < n; ++i) {
        const idx = s.charCodeAt(i) - 97;
        if (left[idx] === -1) left[idx] = i;
        right[idx] = i;
    }

    const intervals = [];

    // build minimal valid intervals, only from first occurrence of a letter
    for (let i = 0; i < n; ++i) {
        const idx = s.charCodeAt(i) - 97;
        if (i !== left[idx]) continue;          // start only at first occurrence

        let start = i;
        let end = right[idx];
        let j = start;
        let ok = true;

        // expand until the interval stabilises
        while (j <= end) {
            const curIdx = s.charCodeAt(j) - 97;
            if (left[curIdx] < start) {         // a character starts before our left border
                ok = false;
                break;
            }
            end = Math.max(end, right[curIdx]); // need to include its last occurrence
            ++j;
        }

        if (ok) intervals.push([start, end]);   // store a minimal valid interval
    }

    // sort by right end so that greedy selection gives the maximum count
    intervals.sort((a, b) => a[1] - b[1]);

    const result = [];
    let lastEnd = -1;

    // greedy pick non‑overlapping intervals
    for (const [l, r] of intervals) {
        if (l > lastEnd) {
            result.push(s.slice(l, r + 1));
            lastEnd = r;
        }
    }
    return result;
}

function numberOfSubarrays(arr) {
    const MOD = 1000000007;
    let evenCount = 1;   // empty prefix has even sum
    let oddCount = 0;
    let prefixParity = 0; // 0 = even, 1 = odd
    let result = 0;

    for (let i = 0; i < arr.length; i++) {
        // update parity of current prefix sum
        prefixParity ^= (arr[i] & 1);

        if (prefixParity === 1) {
            // odd prefix → subarrays ending here with odd sum = previous even prefixes
            result = (result + evenCount) % MOD;
            oddCount++;               // this prefix itself is odd
        } else {
            // even prefix → subarrays ending here with odd sum = previous odd prefixes
            result = (result + oddCount) % MOD;
            evenCount++;              // this prefix itself is even
        }
    }
    return result;
}

function restoreString(s, indices) {
    const n = s.length;
    const shuffled = new Array(n);
    for (let i = 0; i < n; i++) {
        // place character s[i] at its target position indices[i]
        shuffled[indices[i]] = s[i];
    }
    return shuffled.join('');
}

function numberOfGoodSplits(s) {
    const n = s.length;
    const prefix = new Array(n);
    const suffix = new Array(n);
    const seenLeft = new Array(26).fill(false);
    let distinctLeft = 0;

    // build prefix distinct counts
    for (let i = 0; i < n; i++) {
        const idx = s.charCodeAt(i) - 97;
        if (!seenLeft[idx]) {
            seenLeft[idx] = true;
            distinctLeft++;
        }
        prefix[i] = distinctLeft;
    }

    const seenRight = new Array(26).fill(false);
    let distinctRight = 0;

    // build suffix distinct counts
    for (let i = n - 1; i >= 0; i--) {
        const idx = s.charCodeAt(i) - 97;
        if (!seenRight[idx]) {
            seenRight[idx] = true;
            distinctRight++;
        }
        suffix[i] = distinctRight;
    }

    let goodSplits = 0;
    // compare prefix and suffix counts for each possible split
    for (let i = 1; i < n; i++) {
        if (prefix[i - 1] === suffix[i]) goodSplits++;
    }
    return goodSplits;
}

function minSuffixFlips(target) {
    let flips = 0;          // number of operations performed
    let parity = 0;         // 0 = even flips (bits are 0), 1 = odd flips (bits are 1)

    for (let i = 0; i < target.length; i++) {
        const bit = target.charCodeAt(i) - 48; // convert '0'/'1' to 0/1
        if (bit !== parity) {                  // if current bit differs from effective bit, flip suffix
            flips++;
            parity ^= 1;                        // toggle parity
        }
    }
    return flips;
}

function minNumberOperations(target) {
    if (!target || target.length === 0) return 0;
    let operations = target[0];
    for (let i = 1; i < target.length; i++) {
        const diff = target[i] - target[i - 1];
        if (diff > 0) operations += diff; // add only positive increase
    }
    return operations;
}

function minSwaps(grid) {
    const n = grid.length;
    const rightOne = new Array(n);
    // compute rightmost 1 for each row
    for (let i = 0; i < n; i++) {
        let pos = -1;
        for (let j = n - 1; j >= 0; j--) {
            if (grid[i][j] === 1) { pos = j; break; }
        }
        rightOne[i] = pos;
    }

    let steps = 0;
    // place rows one by one from top to bottom
    for (let i = 0; i < n; i++) {
        // if current row already satisfies the condition, continue
        if (rightOne[i] <= i) continue;

        // find the nearest row below that can be moved up
        let j = i + 1;
        while (j < n && rightOne[j] > i) j++;

        if (j === n) return -1; // no suitable row found

        // bring row j up to position i by swapping adjacent rows
        while (j > i) {
            // swap rightOne[j] with rightOne[j-1]
            const temp = rightOne[j];
            rightOne[j] = rightOne[j - 1];
            rightOne[j - 1] = temp;
            steps++;
            j--;
        }
    }
    return steps;
}

function countPairs(root, distance) {
    let goodPairs = 0;

    function dfs(node) {
        if (!node) return [];

        // leaf node: distance 1 to its parent
        if (!node.left && !node.right) return [1];

        const leftDist = dfs(node.left);
        const rightDist = dfs(node.right);

        // count good pairs formed by leaves from left and right subtrees
        for (let l of leftDist) {
            for (let r of rightDist) {
                if (l + r <= distance) goodPairs++;
            }
        }

        // propagate distances upward, discarding those that exceed the limit
        const up = [];
        for (let d of leftDist) {
            if (d + 1 <= distance) up.push(d + 1);
        }
        for (let d of rightDist) {
            if (d + 1 <= distance) up.push(d + 1);
        }
        return up;
    }

    dfs(root);
    return goodPairs;
}

function getLengthOfOptimalCompression(s, k) {
    const n = s.length;
    function getLen(cnt) {
        if (cnt === 1) return 1;
        return 1 + String(cnt).length;
    }
    const memo = new Map();
    function dp(i, rem) {
        if (rem >= n - i) return 0;
        if (i === n) return 0;
        const key = i+','+rem;
        if (memo.has(key)) return memo.get(key);
        let best = rem > 0 ? dp(i+1, rem-1) : Infinity;
        let cnt = 0, delNeeded = 0;
        for (let j = i; j < n; j++) {
            if (s[j] === s[i]) cnt++;
            else delNeeded++;
            if (delNeeded > rem) continue;
            const cost = getLen(cnt) + dp(j+1, rem-delNeeded);
            if (cost < best) best = cost;
        }
        memo.set(key, best);
        return best;
    }
    return dp(0, k);
}

function countGoodTriplets(arr, a, b, c) {
    let n = arr.length;
    let good = 0;

    // enumerate all triples i < j < k
    for (let i = 0; i < n - 2; i++) {
        for (let j = i + 1; j < n - 1; j++) {
            // first condition
            if (Math.abs(arr[i] - arr[j]) > a) continue;
            for (let k = j + 1; k < n; k++) {
                // second and third conditions
                if (Math.abs(arr[j] - arr[k]) <= b &&
                    Math.abs(arr[i] - arr[k]) <= c) {
                    good++;
                }
            }
        }
    }
    return good;
}

function canConvertStringInKMoves(s, t, k) {
    // count how many times each shift amount (1..25) is needed
    const need = new Array(26).fill(0); // index = diff

    for (let i = 0; i < s.length; i++) {
        const a = s.charCodeAt(i) - 97; // 'a' -> 0
        const b = t.charCodeAt(i) - 97;
        if (a === b) continue;                     // no shift required
        const diff = (b - a + 26) % 26;             // 1..25
        need[diff]++;                               // record requirement
    }

    // verify each required diff can be satisfied with distinct moves ≤ k
    for (let diff = 1; diff < 26; diff++) {
        const cnt = need[diff];
        if (cnt === 0) continue;                    // nothing needed for this diff
        if (diff > k) return false;                 // smallest possible move already too large
        const maxMoves = Math.floor((k - diff) / 26) + 1; // how many moves give this diff
        if (cnt > maxMoves) return false;           // not enough moves
    }

    return true;
}

function findWinner(arr, k) {
    // If k is large enough the maximum element will win for sure
    if (k >= arr.length - 1) {
        let max = arr[0];
        for (let i = 1; i < arr.length; i++) if (arr[i] > max) max = arr[i];
        return max;
    }

    // use the array itself as a queue
    let queue = arr.slice();          // copy to avoid mutating input
    let cur = queue.shift();          // current champion
    let win = 0;                      // consecutive wins of cur

    while (win < k) {
        let next = queue.shift();     // challenger

        if (cur > next) {             // cur wins this round
            win++;                    // increase streak
            queue.push(next);         // loser goes to the back
        } else {                      // next becomes new champion
            queue.push(cur);          // old champion goes to the back
            cur = next;               // new champion
            win = 1;                  // it just won this round
        }
    }
    return cur;
}

function minInsertions(s) {
    let insertions = 0;      // total characters we need to add
    let need = 0;            // how many ')' are required right now

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];

        if (ch === '(') {
            // if we currently need an odd number of ')', insert one to make it even
            if (need % 2 === 1) {
                insertions++;
                need--;          // the inserted ')' satisfies one needed ')'
            }
            need += 2;          // each '(' expects two ')'
        } else { // ch === ')'
            need--;              // consume one required ')'
            if (need < 0) {      // we have a surplus ')'
                insertions++;    // insert a '(' before it
                need = 1;        // after inserting '(', we still need one more ')'
            }
        }
    }

    insertions += need;        // any remaining ')' needed are inserted at the end
    return insertions;
}

function maxScore(nums1, nums2) {
    const MOD = 1000000007;
    let i = 0, j = 0;
    let sum1 = 0, sum2 = 0;
    let answer = 0;

    while (i < nums1.length && j < nums2.length) {
        if (nums1[i] < nums2[j]) {
            sum1 += nums1[i];
            i++;
        } else if (nums1[i] > nums2[j]) {
            sum2 += nums2[j];
            j++;
        } else {
            // at a common element: pick the better accumulated sum and add the common value
            answer = (answer + Math.max(sum1, sum2) + nums1[i]) % MOD;
            sum1 = 0;
            sum2 = 0;
            i++;
            j++;
        }
    }

    while (i < nums1.length) {
        sum1 += nums1[i];
        i++;
    }
    while (j < nums2.length) {
        sum2 += nums2[j];
        j++;
    }

    answer = (answer + Math.max(sum1, sum2)) % MOD;
    return answer;
}

function findKthMissing(arr, k) {
    // helper: how many positive numbers are missing up to index i
    function missingCount(i) {
        return arr[i] - (i + 1);
    }

    let left = 0;
    let right = arr.length - 1;

    // binary search for the first index where missingCount >= k
    while (left <= right) {
        const mid = Math.floor((left + right) / 2);
        if (missingCount(mid) < k) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    // left is the insertion point; compute answer from the previous element
    const prevMissing = left > 0 ? missingCount(left - 1) : 0;
    const prevValue   = left > 0 ? arr[left - 1] : 0;
    return prevValue + (k - prevMissing);
}

function makeGood(s) {
    const stack = [];
    for (const ch of s) {
        // if top of stack and current char are same letter with opposite case, remove the pair
        if (stack.length && Math.abs(stack[stack.length - 1].charCodeAt(0) - ch.charCodeAt(0)) === 32) {
            stack.pop();
        } else {
            stack.push(ch);
        }
    }
    return stack.join('');
}

function longestAwesome(s) {
    const INF = 1e9;
    const first = new Array(1 << 10).fill(INF);
    first[0] = -1;                     // empty prefix

    let mask = 0;
    let best = 0;

    for (let i = 0; i < s.length; i++) {
        const digit = s.charCodeAt(i) - 48;   // '0' -> 0
        mask ^= (1 << digit);                  // toggle parity

        // case: all digits even
        best = Math.max(best, i - first[mask]);

        // case: exactly one digit odd
        for (let d = 0; d < 10; d++) {
            const cand = mask ^ (1 << d);
            best = Math.max(best, i - first[cand]);
        }

        // store earliest index for this mask
        if (first[mask] === INF) first[mask] = i;
    }
    return best;
}

function minCost(n, cuts) {
    // sort cuts and add the stick ends (0 and n)
    const pos = [0, ...cuts.sort((a, b) => a - b), n];
    const m = pos.length;
    const dp = Array.from({ length: m }, () => Array(m).fill(0));

    // DP over interval length (distance between i and j)
    for (let len = 2; len < m; ++len) {          // len = j - i
        for (let i = 0; i + len < m; ++i) {
            const j = i + len;
            let best = Infinity;
            // try every possible first cut k inside (i, j)
            for (let k = i + 1; k < j; ++k) {
                const cost = dp[i][k] + dp[k][j] + pos[j] - pos[i];
                if (cost < best) best = cost;
            }
            dp[i][j] = best;
        }
    }
    return dp[0][m - 1];
}

var findKthBit = function(n, k) {
    if (n === 1) return "0";
    const mid = 1 << (n-1);
    if (k === mid) return "1";
    if (k < mid) return findKthBit(n-1, k);
    const mirrored = (1 << n) - k;
    return findKthBit(n-1, mirrored) === "1" ? "0" : "1";
};

function minOperations(n) {
