}

function maxNonOverlappingSubarrays(nums, target) {
    let count = 0;                 // number of subarrays found
    let prefixSum = 0;             // sum of the current segment
    let seen = new Set([0]);       // prefix sums seen in the current segment

    for (let i = 0; i < nums.length; i++) {
        prefixSum += nums[i];
        // if a previous prefix sum makes a subarray sum equal to target
        if (seen.has(prefixSum - target)) {
            count++;                // take this subarray
            // start a new segment after the chosen subarray
            prefixSum = 0;
            seen = new Set([0]);
        } else {
            seen.add(prefixSum);    // record sum for future checks
        }
    }
    return count;
}

function threeConsecutiveOdds(arr) {
    let consecutive = 0;                     // count of current consecutive odds
    for (let i = 0; i < arr.length; i++) {
        if (arr[i] % 2 !== 0) {               // odd number found
            consecutive++;                   // increase streak
            if (consecutive === 3) return true; // three odds in a row
        } else {
            consecutive = 0;                 // reset streak on even
        }
    }
