function minDays(n) {
    const memo = new Map();               // store results for sub‑problems

    function dfs(x) {
        if (x <= 1) return x;             // 0 or 1 orange needs x days
        if (memo.has(x)) return memo.get(x);

        // choose the better of making x divisible by 2 or by 3, then recurse
        const daysVia2 = x % 2 + dfs(Math.floor(x / 2));
        const daysVia3 = x % 3 + dfs(Math.floor(x / 3));
        const result = 1 + Math.min(daysVia2, daysVia3);

        memo.set(x, result);
        return result;
    }

    return dfs(n);
}

function maxDistance36(position, m) {
  position.sort((a, b) => a - b);
  const n = position.length;
  function canPlace(d) {
    let count = 1, last = position[0];
    for (let i = 1; i < n; i++) {
      if (position[i] - last >= d) { count++; last = position[i]; }
    }
    return count >= m;
  }
  let lo = 1, hi = position[n-1] - position[0];
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (canPlace(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}

function minOperations(nums) {
    let ops = 0, maxDoubles = 0;
    for (const v of nums) {
        let x = v, bits = 0, highest = 0;
        while (x > 0) { if (x & 1) bits++; x >>= 1; highest++; }
        ops += bits;
        maxDoubles = Math.max(maxDoubles, highest > 0 ? highest-1 : 0);
    }
    return ops + maxDoubles;
}

function thousandSeparator(n) {
    // Convert number to string and handle sign
    let str = n.toString();
    let sign = "";
    if (str[0] === "-") {
        sign = "-";
        str = str.slice(1);
    }

    const result = [];
    let count = 0;

    // Build the string from right to left, inserting a dot every three digits
    for (let i = str.length - 1; i >= 0; i--) {
        result.push(str[i]);
        count++;
        if (count === 3 && i !== 0) { // insert separator unless at the most‑significant digit
            result.push(".");
            count = 0;
        }
    }

    // Reverse to obtain correct order and add sign back
    return sign + result.reverse().join("");
}

function minimumVertices(n, edges) {
    // indegree[i] counts how many edges point to i
    const indegree = new Array(n).fill(0);
    for (let i = 0; i < edges.length; i++) {
        const to = edges[i][1];
        indegree[to]++;               // count incoming edge
    }

    const result = [];
    for (let v = 0; v < n; v++) {
        if (indegree[v] === 0) {      // vertex with no incoming edges
            result.push(v);
        }
    }
    return result;
}

function maxCoins(piles) {
    // sort ascending; Bob (smallest each round) always ends up with the smallest
    // n piles overall (indices 0..n-1), Alice always takes the current largest,
    // and "you" get every second pile among the remaining top 2n piles
    piles.sort((a, b) => a - b);
    const n = piles.length / 3;
    let total = 0;
    for (let i = n; i < piles.length; i += 2) {
        total += piles[i];
    }
    return total;
}

function stoneGameV(stoneValue) {
    const n = stoneValue.length;
    if (n <= 1) return 0;
    const prefix = new Array(n+1).fill(0);
    for (let i = 0; i < n; i++) prefix[i+1] = prefix[i] + stoneValue[i];
    const dp = Array.from({length:n}, () => new Array(n).fill(0));

    for (let length = 2; length <= n; length++) {
        for (let i = 0; i <= n - length; i++) {
            const j = i + length - 1;
            let low = i, high = j - 1;
            while (low < high) {
                const mid = Math.floor((low + high + 1) / 2);
                const leftSum = prefix[mid+1] - prefix[i];
                const rightSum = prefix[j+1] - prefix[mid+1];
                if (leftSum <= rightSum) low = mid; else high = mid - 1;
            }
            const k = low;
            let best = 0;
            for (const split of [k, k+1]) {
                if (split < i || split >= j) continue;
                const leftSum = prefix[split+1] - prefix[i];
                const rightSum = prefix[j+1] - prefix[split+1];
                if (leftSum < rightSum) {
                    best = Math.max(best, leftSum + dp[i][split]);
                } else if (leftSum > rightSum) {
                    best = Math.max(best, rightSum + dp[split+1][j]);
                } else {
                    best = Math.max(best, leftSum + dp[i][split], rightSum + dp[split+1][j]);
                }
            }
            dp[i][j] = best;
        }
    }
    return dp[0][n-1];
}

function detectCycle(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const visited = Array.from({ length: m }, () => Array(n).fill(false));
    const dirs = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
    ];

    // depth‑first search that returns true as soon as a cycle is found
    function dfs(x, y, px, py, ch) {
        visited[x][y] = true;
        for (const [dx, dy] of dirs) {
            const nx = x + dx;
            const ny = y + dy;
            if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;   // out of bounds
            if (grid[nx][ny] !== ch) continue;                     // different character

            if (!visited[nx][ny]) {
                if (dfs(nx, ny, x, y, ch)) return true;           // continue exploring
            } else if (nx !== px || ny !== py) {
                return true;                                       // visited neighbour not parent → cycle
            }
        }
        return false;
    }

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (!visited[i][j]) {
                if (dfs(i, j, -1, -1, grid[i][j])) return true; // start new component
            }
        }
    }
    return false;
}

function mostVisitedSectors(n, rounds) {
    const start = rounds[0];
    const end = rounds[rounds.length - 1];
    const result = [];

    // main logic: the sectors visited most are those on the final path from start to end
    if (start <= end) {
        for (let i = start; i <= end; i++) {
            result.push(i);
        }
    } else {
        for (let i = 1; i <= end; i++) {
            result.push(i);
        }
        for (let i = start; i <= n; i++) {
            result.push(i);
        }
    }
    return result;
}

function minDays(grid) {
    const m = grid.length, n = grid[0].length;

    // count how many islands exist in the current grid
    function countIslands() {
        const visited = Array.from({ length: m }, () => Array(n).fill(false));
        let islands = 0;

        const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
        const stack = [];

        for (let i = 0; i < m; i++) {
            for (let j = 0; j < n; j++) {
                if (grid[i][j] === 1 && !visited[i][j]) {
                    islands++;
                    stack.push([i, j]);
                    visited[i][j] = true;
                    // flood‑fill this island
                    while (stack.length) {
                        const [x, y] = stack.pop();
                        for (const [dx, dy] of dirs) {
                            const nx = x + dx, ny = y + dy;
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n &&
                                grid[nx][ny] === 1 && !visited[nx][ny]) {
                                visited[nx][ny] = true;
                                stack.push([nx, ny]);
                            }
                        }
                    }
                }
            }
        }
        return islands;
    }

    // MAIN LOGIC: already disconnected?
    if (countIslands() !== 1) return 0;

    // MAIN LOGIC: try removing each land cell once
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                grid[i][j] = 0;                     // delete this cell
                if (countIslands() !== 1) return 1; // became disconnected
                grid[i][j] = 1;                     // restore
            }
        }
    }

    // MAIN LOGIC: need at least two deletions
    return 2;
}


// TIME: O((m·n)²)  SPACE: O(m·n)

function findLatestStep(arr, m) {
    const n = arr.length;
    const left = new Array(n+2).fill(0);
    const right = new Array(n+2).fill(0);
    const count = new Map();
    let answer = -1;

    function inc(k, d) {
        const v = (count.get(k) || 0) + d;
        if (v === 0) count.delete(k); else count.set(k, v);
    }

    for (let step = 1; step <= arr.length; step++) {
        const pos = arr[step-1];
        const lLen = left[pos-1] || 0;
        const rLen = right[pos+1] || 0;
        const newLen = lLen + 1 + rLen;

        if (lLen) inc(lLen, -1);
        if (rLen) inc(rLen, -1);
        inc(newLen, 1);

        left[pos] = right[pos] = newLen;
        left[pos + rLen] = newLen;
        right[pos - lLen] = newLen;

        if (count.has(m)) answer = step;
    }
    return answer;
}

function numberOfWays(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const fact = new Array(n+1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = (fact[i-1] * BigInt(i)) % MOD;
    function modpow(base, exp, mod) {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    }
    const invFact = new Array(n+1).fill(1n);
    invFact[n] = modpow(fact[n], MOD - 2n, MOD);
    for (let i = n; i > 0; i--) invFact[i-1] = (invFact[i] * BigInt(i)) % MOD;

    function comb(a, b) {
        if (b < 0 || b > a) return 0n;
        return fact[a] * invFact[b] % MOD * invFact[a-b] % MOD;
    }

    function dfs(arr) {
        if (arr.length <= 1) return [arr.length, 1n];
        const root = arr[0];
        const left = arr.slice(1).filter(x => x < root);
        const right = arr.slice(1).filter(x => x > root);
        const [lsize, lways] = dfs(left);
        const [rsize, rways] = dfs(right);
        const ways = comb(lsize + rsize, lsize) * lways % MOD * rways % MOD;
        return [lsize + rsize + 1, ways];
    }

    const [, totalWays] = dfs(nums);
    return Number(((totalWays - 1n) % MOD + MOD) % MOD);
}

function hasPattern(arr, m, k) {
    const n = arr.length;
    if (m <= 0 || k <= 0) return false;
    if (m * k > n) return false;
    if (k === 1) return m <= n;               // any subarray of length m satisfies k = 1

    // try each possible start index and count how many consecutive repeats of length‑m we get
    for (let i = 0; i <= n - m * k; i++) {
        let repeats = 1;                       // the first occurrence is always present
        while (repeats < k) {
            let same = true;
            for (let j = 0; j < m; j++) {
                if (arr[i + j] !== arr[i + repeats * m + j]) {
                    same = false;
                    break;
                }
            }
            if (!same) break;                  // pattern breaks, stop extending
            repeats++;
        }
        if (repeats >= k) return true;         // found enough consecutive repetitions
    }
    return false;
}

// TIME: O(n * m * k) in the worst case (each start may compare up to k blocks of length m)
// SPACE: O(1)

function getMaxLen(nums) {
    let maxPos = 0;      // longest positive‑product subarray seen so far
    let posLen = 0;      // length ending at current index with positive product
    let negLen = 0;      // length ending at current index with negative product

    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];

        if (x === 0) {                // zero breaks any subarray
            posLen = 0;
            negLen = 0;
        } else if (x > 0) {           // positive number keeps signs
            posLen = posLen + 1;               // extend positive subarray
            if (negLen > 0) negLen = negLen + 1; // extend negative subarray if it exists
        } else {                      // x < 0, signs are swapped
            const oldPos = posLen;
            const oldNeg = negLen;

            // a former negative becomes positive, a former positive becomes negative
            posLen = (oldNeg > 0) ? oldNeg + 1 : 0;
            negLen = oldPos + 1;
        }

        if (posLen > maxPos) maxPos = posLen;   // update answer
    }

    return maxPos;
}

function countRoutes(locations, start, finish, fuel) {
    const MOD = 1_000_000_007;
    const n = locations.length;
    // memo[i][f] = number of ways from city i with f fuel left
    const memo = Array.from({ length: n }, () => Array(fuel + 1).fill(-1));

    function dfs(city, remaining) {
        if (memo[city][remaining] !== -1) return memo[city][remaining];

        // count current city if it is the destination
        let ways = city === finish ? 1 : 0;

        // try moving to every other city
        for (let next = 0; next < n; next++) {
            if (next === city) continue;
            const cost = Math.abs(locations[city] - locations[next]);
            if (cost <= remaining) {
                ways = (ways + dfs(next, remaining - cost)) % MOD; // transition
            }
        }

        memo[city][remaining] = ways;
        return ways;
    }

    return dfs(start, fuel);
}

function modifyString(s) {
    const n = s.length;
    const result = new Array(n);
    const letters = 'abcdefghijklmnopqrstuvwxyz';

    for (let i = 0; i < n; i++) {
        if (s[i] !== '?') {
            result[i] = s[i];                     // keep original character
        } else {
            const prev = i > 0 ? result[i - 1] : null;
            const next = i + 1 < n && s[i + 1] !== '?' ? s[i + 1] : null;
            // pick the first letter that differs from both neighbours
            for (let j = 0; j < letters.length; j++) {
                const cand = letters[j];
                if (cand !== prev && cand !== next) {
                    result[i] = cand;
                    break;
                }
            }
        }
    }
    return result.join('');
}

function matrixDiagonalSum(mat) {
    const n = mat.length;
    let sum = 0;
    for (let i = 0; i < n; i++) {
        sum += mat[i][i];                         // primary diagonal
        const j = n - 1 - i;                      // column index for secondary diagonal
        if (i !== j) sum += mat[i][j];            // avoid double‑counting the center element
    }
    return sum;
}

function numberOfWays(s) {
    const MOD = 1000000007;
    const n = s.length;
    let totalOnes = 0;
    for (let i = 0; i < n; i++) {
        if (s[i] === '1') totalOnes++;
    }

    if (totalOnes % 3 !== 0) return 0;                     // impossible to balance

    if (totalOnes === 0) {                                 // all zeros
        const ways = ((n - 1) * (n - 2) / 2) % MOD;        // choose any two cuts
        return ways;
    }

    const target = totalOnes / 3;
    let onesSeen = 0;
    let zerosAfterFirst = 0;
    let zerosAfterSecond = 0;
    let i = 0;

    // count zeros that can be placed after the first part
    while (i < n) {
        if (s[i] === '1') onesSeen++;
        if (onesSeen === target) {
            i++;
            while (i < n && s[i] === '0') {
                zerosAfterFirst++;
                i++;
            }
            break;
        }
        i++;
    }

    // count zeros that can be placed after the second part
    while (i < n) {
        if (s[i] === '1') onesSeen++;
        if (onesSeen === 2 * target) {
            i++;
            while (i < n && s[i] === '0') {
                zerosAfterSecond++;
                i++;
            }
            break;
        }
        i++;
    }

    const ways = (BigInt(zerosAfterFirst + 1) * BigInt(zerosAfterSecond + 1)) % BigInt(MOD);
    return Number(ways);
}

function shortestSubarrayToRemove(arr) {
    const n = arr.length;
    // find longest non‑decreasing prefix
    let prefixEnd = 0;
    while (prefixEnd + 1 < n && arr[prefixEnd] <= arr[prefixEnd + 1]) {
        prefixEnd++;
    }
    // already sorted
    if (prefixEnd === n - 1) return 0;

    // find longest non‑decreasing suffix
    let suffixStart = n - 1;
    while (suffixStart - 1 >= 0 && arr[suffixStart - 1] <= arr[suffixStart]) {
        suffixStart--;
    }

    // remove everything after prefix or everything before suffix
    let minRemove = Math.min(n - prefixEnd - 1, suffixStart);

    // try to keep some prefix elements and some suffix elements together
    let i = 0, j = suffixStart;
    while (i <= prefixEnd && j < n) {
        // advance j until suffix element can follow prefix element
        while (j < n && arr[j] < arr[i]) j++;
        if (j < n) {
            // length of removed subarray between i and j
            minRemove = Math.min(minRemove, j - i - 1);
        }
        i++;
    }
    return minRemove;
}

function maxNumEdgesToRemove(n, edges) {
    // simple Union‑Find structure
    function DSU(size) {
        const parent = new Int32Array(size + 1);
        const rank = new Int8Array(size + 1);
        for (let i = 1; i <= size; i++) parent[i] = i;
        this.find = function (x) {
            while (parent[x] !== x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        this.union = function (a, b) {
            let ra = this.find(a), rb = this.find(b);
            if (ra === rb) return false;
            if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
            parent[rb] = ra;
            if (rank[ra] === rank[rb]) rank[ra]++;
            return true;
        };
    }

    const alice = new DSU(n);
    const bob = new DSU(n);
    let used = 0;

    // use type‑3 edges for both Alice and Bob
    for (const [type, u, v] of edges) {
        if (type === 3) {
            const a = alice.union(u, v);
            const b = bob.union(u, v);
            if (a || b) used++;               // edge contributes to at least one DSU
        }
    }

    // use exclusive edges
    for (const [type, u, v] of edges) {
        if (type === 1) {                     // Alice only
            if (alice.union(u, v)) used++;
        } else if (type === 2) {              // Bob only
            if (bob.union(u, v)) used++;
        }
    }

    // verify both graphs are fully connected
    function compCount(ds) {
        let cnt = 0;
        for (let i = 1; i <= n; i++) if (ds.find(i) === i) cnt++;
        return cnt;
    }
    if (compCount(alice) !== 1 || compCount(bob) !== 1) return -1;

    return edges.length - used;               // removable edges
}

