function specialPositions(mat) {
    const rows = mat.length;
    const cols = mat[0].length;
    const rowSum = new Array(rows).fill(0);
    const colSum = new Array(cols).fill(0);

    // count 1's in each row and column
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (mat[i][j] === 1) {
                rowSum[i]++;
                colSum[j]++;
            }
        }
    }

    let specialCount = 0;
    // a position is special if its row and column each contain exactly one 1
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            if (mat[i][j] === 1 && rowSum[i] === 1 && colSum[j] === 1) {
                specialCount++;
            }
        }
    }

    return specialCount;
}

function minCost(colors, neededTime) {
    let totalTime = 0;
    let i = 0;
    while (i < colors.length) {
        // process a contiguous block of identical colors
        let maxInBlock = neededTime[i];
        let sumInBlock = neededTime[i];
        let j = i + 1;
        while (j < colors.length && colors[j] === colors[i]) {
            sumInBlock += neededTime[j];
            if (neededTime[j] > maxInBlock) maxInBlock = neededTime[j];
            j++;
        }
        // keep the most expensive balloon, remove the rest
        totalTime += sumInBlock - maxInBlock;
        i = j; // move to the next distinct color
    }
    return totalTime;
}

function numTriplets(nums1, nums2) {
    function countType(A, B) {
        let count = 0;
        for (const x of A) {
            const target = BigInt(x) * BigInt(x);
            for (let j = 0; j < B.length; j++) {
                for (let k = j+1; k < B.length; k++) {
                    if (BigInt(B[j])*BigInt(B[k]) === target) count++;
                }
            }
        }
        return count;
    }
    return countType(nums1, nums2) + countType(nums2, nums1);
}

function minCostConnectPoints(points) {
    const n = points.length;
    const visited = new Array(n).fill(false);
    const minDist = new Array(n).fill(Infinity);
    minDist[0] = 0;                 // start from point 0
    let totalCost = 0;

    for (let i = 0; i < n; i++) {
        // find the unvisited point with the smallest connection cost
        let u = -1;
        let best = Infinity;
        for (let j = 0; j < n; j++) {
            if (!visited[j] && minDist[j] < best) {
                best = minDist[j];
                u = j;
            }
        }

        visited[u] = true;
        totalCost += best;          // add the cheapest edge to the MST

        // update the cheapest connection cost for the remaining points
        for (let v = 0; v < n; v++) {
            if (!visited[v]) {
                const dist = Math.abs(points[u][0] - points[v][0]) +
                             Math.abs(points[u][1] - points[v][1]);
                if (dist < minDist[v]) {
                    minDist[v] = dist;
                }
            }
        }
    }

    return totalCost;
}

function countUnhappyFriends(n, preferences, pairs) {
    // partner[i] = current partner of i
    const partner = new Array(n);
    for (const [a, b] of pairs) {
        partner[a] = b;
        partner[b] = a;
    }

    // rank[i][j] = position of j in i's preference list (lower = better)
    const rank = Array.from({ length: n }, () => new Array(n));
    for (let i = 0; i < n; i++) {
        const list = preferences[i];
        for (let pos = 0; pos < list.length; pos++) {
            rank[i][list[pos]] = pos;
        }
    }

    const unhappy = new Array(n).fill(false);

    // MAIN LOGIC: determine unhappy friends
    for (let x = 0; x < n; x++) {
        const y = partner[x];
        for (const u of preferences[x]) {
            if (u === y) break;                     // stop when reaching current partner
            const v = partner[u];
            // u prefers x over its own partner v ?
            if (rank[u][x] < rank[u][v]) {
                unhappy[x] = true;
                break;                               // x is already unhappy
            }
        }
    }

    // count unhappy friends
    let ans = 0;
    for (const flag of unhappy) if (flag) ans++;
    return ans;
}

function isTransformable(s, t) {
    const n = s.length;
    const pos = Array.from({ length: 10 }, () => []);
    for (let i = 0; i < n; i++) {
        const d = s.charCodeAt(i) - 48;
        pos[d].push(i);
    }
    for (let i = 0; i < n; i++) {
        const need = t.charCodeAt(i) - 48;
        if (pos[need].length === 0) return false;
        const idx = pos[need].shift();
        for (let d = 0; d < need; d++) {
            if (pos[d].length > 0 && pos[d][0] < idx) {
                return false;
            }
        }
    }
    return true;
}

function sumOddLengthSubarrays(arr) {
    const n = arr.length;
    let total = 0;

    for (let i = 0; i < n; i++) {
        const leftCount = i + 1;
        const rightCount = n - i;

        const leftOdd = Math.ceil(leftCount / 2);
        const leftEven = Math.floor(leftCount / 2);
        const rightOdd = Math.ceil(rightCount / 2);
        const rightEven = Math.floor(rightCount / 2);

        // a subarray's total length (left part + right part, sharing index i)
        // is ODD exactly when the two parts have MATCHING parity (both odd or
        // both even) - not when they differ
        const oddSubarrays = leftOdd * rightOdd + leftEven * rightEven;

        total += arr[i] * oddSubarrays;
    }
    return total;
}

function minSubarray(nums, p) {
  const n = nums.length;
  let total = 0;
  for (const x of nums) total += x;
  const target = total % p;
  if (target === 0) return 0;
  const lastIndex = new Map();
  lastIndex.set(0, -1);
  let prefix = 0;
  let best = n;
  for (let i = 0; i < n; i++) {
    prefix = (prefix + nums[i]) % p;
    const need = ((prefix - target) % p + p) % p;
    if (lastIndex.has(need)) best = Math.min(best, i - lastIndex.get(need));
    lastIndex.set(prefix, i);
  }
  return best === n ? -1 : best;
}

function reorderSpaces(text) {
    // count total spaces in the original string
    let totalSpaces = 0;
    for (let i = 0; i < text.length; i++) {
        if (text[i] === ' ') totalSpaces++;
    }

    // extract all words (sequences of non‑space characters)
    const words = text.trim().split(/\s+/);
    const wordCount = words.length;

    // if there is only one word, all spaces go to the end
    if (wordCount === 1) {
        return words[0] + ' '.repeat(totalSpaces);
    }

    // compute equal spaces between words and remaining extra spaces
    const spacesBetween = Math.floor(totalSpaces / (wordCount - 1));
    const extraSpaces = totalSpaces - spacesBetween * (wordCount - 1);

    // build the result string
    const middle = ' '.repeat(spacesBetween);
    return words.join(middle) + ' '.repeat(extraSpaces);
}

function maxUniqueSplit(s) {
    const used = new Set();          // store substrings already taken
    let best = 0;                    // best count found so far

    function dfs(start, count) {
        if (start === s.length) {    // reached the end of the string
            if (count > best) best = count;
            return;
        }
        // try every possible next substring starting at 'start'
        for (let end = start + 1; end <= s.length; end++) {
            const sub = s.slice(start, end);
            if (!used.has(sub)) {    // keep uniqueness
                used.add(sub);
                dfs(end, count + 1); // continue from the next position
                used.delete(sub);    // backtrack
            }
        }
    }

    dfs(0, 0);
    return best;
}

function isPrintable(targetGrid) {
    const m = targetGrid.length;
    const n = targetGrid[0].length;

    // 1. collect all colors and compute their bounding rectangles
    const rect = new Map(); // color -> [minR, maxR, minC, maxC]
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const col = targetGrid[r][c];
            if (!rect.has(col)) {
                rect.set(col, [r, r, c, c]);
            } else {
                const cur = rect.get(col);
                cur[0] = Math.min(cur[0], r);
                cur[1] = Math.max(cur[1], r);
                cur[2] = Math.min(cur[2], c);
                cur[3] = Math.max(cur[3], c);
            }
        }
    }

    const colors = Array.from(rect.keys());
    const indegree = new Map(); // color -> number of incoming edges
    const graph = new Map();    // color -> Set of colors that must come after it

    // initialise structures
    for (const col of colors) {
        indegree.set(col, 0);
        graph.set(col, new Set());
    }

    // 2. build dependency graph: if a different color appears inside col's rectangle,
    // that other color must be printed after col
    for (const col of colors) {
        const [minR, maxR, minC, maxC] = rect.get(col);
        for (let r = minR; r <= maxR; r++) {
            for (let c = minC; c <= maxC; c++) {
                const inner = targetGrid[r][c];
                if (inner !== col) {
                    if (!graph.get(col).has(inner)) {
                        graph.get(col).add(inner);
                        indegree.set(inner, indegree.get(inner) + 1); // MAIN LOGIC: add edge col -> inner
                    }
                }
            }
        }
    }

    // 3. topological sort (Kahn's algorithm)
    const queue = [];
    for (const col of colors) {
        if (indegree.get(col) === 0) queue.push(col);
    }

    let visited = 0;
    while (queue.length) {
        const cur = queue.shift();
        visited++;
        for (const nxt of graph.get(cur)) {
            indegree.set(nxt, indegree.get(nxt) - 1);
            if (indegree.get(nxt) === 0) queue.push(nxt);
        }
    }

    // if every color could be ordered, printing is possible
    return visited === colors.length;
}

function maxProductPath(grid) {
    const MOD = 1000000007n;
    const rows = grid.length;
    const cols = grid[0].length;
    const maxDP = Array.from({ length: rows }, () => Array(cols).fill(0n));
    const minDP = Array.from({ length: rows }, () => Array(cols).fill(0n));

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const val = BigInt(grid[i][j]);

            if (i === 0 && j === 0) {
                maxDP[i][j] = val;
                minDP[i][j] = val;
                continue;
            }

            const candidates = [];
            if (i > 0) {
                candidates.push(maxDP[i - 1][j] * val);
                candidates.push(minDP[i - 1][j] * val);
            }
            if (j > 0) {
                candidates.push(maxDP[i][j - 1] * val);
                candidates.push(minDP[i][j - 1] * val);
            }

            // main logic: derive the best and worst products reaching (i, j)
            let curMax = candidates[0];
            let curMin = candidates[0];
            for (let k = 1; k < candidates.length; k++) {
                if (candidates[k] > curMax) curMax = candidates[k];
                if (candidates[k] < curMin) curMin = candidates[k];
            }
            maxDP[i][j] = curMax;
            minDP[i][j] = curMin;
        }
    }

    const finalMax = maxDP[rows - 1][cols - 1];
    if (finalMax < 0n) return -1;
    return Number(finalMax % MOD);
}

function maxSumRangeQuery(nums, requests) {
    const MOD = 1_000_000_007n;
    const n = nums.length;
    const diff = new Array(n + 1).fill(0);

    for (const [l, r] of requests) {
        diff[l] += 1;
        if (r + 1 < n) diff[r + 1] -= 1;
    }

    const freq = new Array(n);
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur += diff[i];
        freq[i] = cur;
    }

    nums.sort((a, b) => b - a);
    freq.sort((a, b) => b - a);

    let ans = 0n; // BigInt from the start - mixing Number 0 with a BigInt result throws
    for (let i = 0; i < n; i++) {
        ans = (ans + (BigInt(nums[i]) * BigInt(freq[i])) % MOD) % MOD;
    }
    return Number(ans);
}

function connectTwoGroups(cost) {
    const m = cost.length, n = cost[0].length;
    const minCol = new Array(n).fill(Infinity);
    for (let j = 0; j < n; j++) for (let i = 0; i < m; i++) minCol[j] = Math.min(minCol[j], cost[i][j]);
    const memo = Array.from({length:m+1}, () => new Array(1<<n).fill(-1));
    function dfs(i, mask) {
        if (memo[i][mask] !== -1) return memo[i][mask];
        let res;
        if (i === m) {
            res = 0;
            for (let j = 0; j < n; j++) if (!((mask>>j)&1)) res += minCol[j];
        } else {
            res = Infinity;
            for (let j = 0; j < n; j++) res = Math.min(res, cost[i][j] + dfs(i+1, mask | (1<<j)));
        }
        memo[i][mask] = res;
        return res;
    }
    return dfs(0, 0);
}

function minOperations(logs) {
    let depth = 0;                     // current folder depth

    for (let i = 0; i < logs.length; i++) {
        const op = logs[i];
        if (op === "./") continue;                 // stay in the same folder
        if (op === "../") {                         // go up one level if possible
            if (depth > 0) depth--;
        } else {                                    // go into a subfolder
            depth++;
        }
    }

    return depth;                     // number of steps needed to return to main folder
}

function maximumRequests(n, requests) {
    const m = requests.length;
    let best = 0;

    // Enumerate all subsets of requests
    for (let mask = 0; mask < (1 << m); mask++) {
        const balance = new Array(n).fill(0);
        let used = 0;

        for (let i = 0; i < m; i++) {
            if (mask & (1 << i)) {
                const [from, to] = requests[i];
                balance[from]--;   // employee leaves 'from'
                balance[to]++;     // employee arrives at 'to'
                used++;
            }
        }

        // Verify net balance zero for all buildings
        let ok = true;
        for (let b = 0; b < n; b++) {
            if (balance[b] !== 0) {
                ok = false;
                break;
            }
        }

        if (ok && used > best) best = used;
    }

    return best;
}

