function maxProfit(customers, boardingCost, runningCost) {
    let waiting = 0;          // customers waiting for a seat
    let profit = 0;           // current profit
    let maxProfit = 0;        // best profit seen so far
    let bestRot = -1;         // rotations when best profit occurs
    let rotations = 0;        // total rotations performed

    // continue while there are arrivals left or people still waiting
    for (let i = 0; i < customers.length || waiting > 0; i++) {
        if (i < customers.length) waiting += customers[i];   // new arrivals

        const board = Math.min(4, waiting);  // up to 4 can board this rotation
        waiting -= board;                     // remove boarded customers

        rotations++;                          // one more rotation performed
        profit += board * boardingCost - runningCost; // update profit

        // record the earliest rotation that yields the highest profit
        if (profit > maxProfit) {
            maxProfit = profit;
            bestRot = rotations;
        }
    }

    return maxProfit > 0 ? bestRot : -1;
}

function ThroneInheritance(kingName) {
    // map each person to the list of his/her children in birth order
    const children = new Map();
    children.set(kingName, []);

    // set of dead people
    const dead = new Set();

    // add a new child to the family tree
    function birth(parentName, childName) {
        if (!children.has(parentName)) children.set(parentName, []);
        children.get(parentName).push(childName);
        children.set(childName, []);
    }

    // mark a person as dead
    function death(name) {
        dead.add(name);
    }

    // depth‑first preorder traversal, skipping dead members
    function getInheritanceOrder() {
        const order = [];
        function dfs(person) {
            if (!dead.has(person)) order.push(person);   // add alive person
            for (const child of children.get(person) || []) {
                dfs(child);                               // visit children in birth order
            }
        }
        dfs(kingName);
        return order;
    }

    return { birth, death, getInheritanceOrder };
}

function ParkingSystem(big, medium, small) {
    // store remaining slots for each car type: 0‑big, 1‑medium, 2‑small
    this.slots = [big, medium, small];

    // try to park a car of the given type (1,2,3)
    this.addCar = function (carType) {
        // if a slot is available, occupy it and return true
        if (this.slots[carType - 1] > 0) {
            this.slots[carType - 1]--;
            return true;
        }
        // otherwise no slot left
        return false;
    };
}

class MinHeap2 {
