    const busy = new MinHeap2();
    const cnt = new Array(k).fill(0);
    for (let i = 0; i < n; i++) {
        const t = arrival[i];
        while (busy.size && busy.peek()[0] <= t) {
            const [, sid] = busy.pop();
            insortInto(free, sid);
        }
        if (!free.length) continue;
        const target = i % k;
        let idx = bisectLeft(free, target);
        if (idx === free.length) idx = 0;
