function alertNames(keyName, keyTime) {
    const minutesMap = new Map();               // name → list of minutes

    // collect times per person
    for (let i = 0; i < keyName.length; i++) {
        const name = keyName[i];
        const [h, m] = keyTime[i].split(':');
        const minutes = Number(h) * 60 + Number(m);
        if (!minutesMap.has(name)) minutesMap.set(name, []);
        minutesMap.get(name).push(minutes);
    }

    const alerted = new Set();

    // check each person's sorted times with a sliding window of size 3
    for (const [name, times] of minutesMap) {
        times.sort((a, b) => a - b);            // chronological order
        for (let i = 0; i + 2 < times.length; i++) {
            if (times[i + 2] - times[i] <= 60) { // three uses within one hour
                alerted.add(name);
