function restoreMatrix(rowSum, colSum) {
    const rows = rowSum.length;
    const cols = colSum.length;
    const matrix = Array.from({ length: rows }, () => Array(cols).fill(0));

    let r = 0, c = 0;
    while (r < rows && c < cols) {
        // put the largest possible value that does not exceed the remaining row/column sums
        const take = Math.min(rowSum[r], colSum[c]);
        matrix[r][c] = take;
        rowSum[r] -= take;
        colSum[c] -= take;

        if (rowSum[r] === 0) r++;   // move to next row when its sum is satisfied
        if (colSum[c] === 0) c++;   // move to next column when its sum is satisfied
    }
    return matrix;
}

function specialArray(nums) {
