    nums.sort((a, b) => b - a);

    const n = nums.length;
    for (let i = 0; i < n; i++) {
        const count = i + 1;                     // how many numbers are >= current element
        // check if exactly 'count' numbers are >= 'count'
        if (nums[i] >= count && (i + 1 === n || nums[i + 1] < count)) {
            return count;
