    }
    return -1;
}

function evenOddTree(root) {
    if (!root) return true;                     // empty tree satisfies the conditions

    const queue = [root];
    let level = 0;
    let head = 0;

    while (head < queue.length) {
        const levelSize = queue.length - head;
        let prev = level % 2 === 0 ? -Infinity : Infinity;   // init comparison value

        for (let i = 0; i < levelSize; i++) {
            const node = queue[head++];

            // check parity and monotonic order for the current level
            if (level % 2 === 0) {               // even level: odd values, strictly increasing
                if (node.val % 2 === 0 || node.val <= prev) return false;
            } else {                             // odd level: even values, strictly decreasing
                if (node.val % 2 === 1 || node.val >= prev) return false;
            }
            prev = node.val;

            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        level++;
    }
    return true;
}

function maxVisiblePoints(points, angle, location) {
    const sameLocation = points.reduce((cnt, [x, y]) => {
        return (x === location[0] && y === location[1]) ? cnt + 1 : cnt;
    }, 0);

    const angles = [];
    for (const [x, y] of points) {
        if (x === location[0] && y === location[1]) continue;
        let deg = Math.atan2(y - location[1], x - location[0]) * 180 / Math.PI;
        if (deg < 0) deg += 360;
        angles.push(deg);
    }

    if (angle >= 360) return points.length; // whole circle visible

    angles.sort((a, b) => a - b);
    const extended = angles.concat(angles.map(v => v + 360));

    let maxInWindow = 0;
    let left = 0;
    // sliding window to find largest group within 'angle' degrees
    for (let right = 0; right < extended.length; right++) {
        while (extended[right] - extended[left] > angle) left++;
        const windowSize = right - left + 1;
        if (windowSize > maxInWindow) maxInWindow = windowSize;
    }

    return maxInWindow + sameLocation;
}

function maxNestingDepth(s) {
