function countSubgraphsForEachDiameter(n, edges) {
    const adj = Array.from({length:n}, () => []);
    for (const [uu,vv] of edges) {
        const u = uu-1, v = vv-1;
        adj[u].push(v); adj[v].push(u);
    }
    function bfs(start, mask) {
        const q = [start];
        let visitedMask = 1 << start;
        const dist = new Array(n).fill(-1);
        dist[start] = 0;
        let far = start, maxd = 0;
        let head = 0;
        while (head < q.length) {
            const u = q[head++];
            const du = dist[u];
            if (du > maxd) { maxd = du; far = u; }
            for (const v of adj[u]) {
                if (((mask>>v)&1) && !((visitedMask>>v)&1)) {
                    visitedMask |= (1<<v);
                    dist[v] = du+1;
                    q.push(v);
                }
            }
        }
        return [far, maxd];
    }
    const ans = new Array(n-1).fill(0);
    const totalMasks = 1 << n;
    for (let mask = 1; mask < totalMasks; mask++) {
        if ((mask & (mask-1)) === 0) continue;
        const start = Math.round(Math.log2(mask & (-mask)));
        const stack = [start];
        let visitedMask = 1 << start;
        while (stack.length) {
            const u = stack.pop();
            for (const v of adj[u]) {
                if (((mask>>v)&1) && !((visitedMask>>v)&1)) {
                    visitedMask |= (1<<v);
                    stack.push(v);
                }
            }
        }
        if (visitedMask !== mask) continue;
        const [far] = bfs(start, mask);
        const [, diam] = bfs(far, mask);
        if (diam > 0) ans[diam-1]++;
    }
    return ans;
}

function meanOfArray(arr) {
    const n = arr.length;
