function maximalNetworkRank(n, roads) {
    // degree[i] = number of roads incident to city i
    const degree = new Array(n).fill(0);
    // adjacent[i] = Set of cities directly connected to i
    const adjacent = Array.from({ length: n }, () => new Set());

    // fill degree and adjacency information
    for (const [a, b] of roads) {
        degree[a]++; degree[b]++;
        adjacent[a].add(b);
        adjacent[b].add(a);
    }

    let best = 0;
    // examine every unordered pair of cities
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            let rank = degree[i] + degree[j];
