function bestCoordinate(towers, radius) {
    // Determine search bounds
    let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
    for (const [x, y] of towers) {
        if (x < minX) minX = x;
        if (x > maxX) maxX = x;
        if (y < minY) minY = y;
        if (y > maxY) maxY = y;
    }
    minX -= radius;
    maxX += radius;
    minY -= radius;
    maxY += radius;

    let bestX = 0, bestY = 0, bestQuality = -1;

    // Enumerate every integer point inside the bounding box
    for (let cx = minX; cx <= maxX; cx++) {
        for (let cy = minY; cy <= maxY; cy++) {
            let total = 0;
            // Sum contributions of reachable towers
            for (const [tx, ty, q] of towers) {
                const dx = tx - cx;
                const dy = ty - cy;
                const dist = Math.sqrt(dx * dx + dy * dy);
                if (dist <= radius) {
                    total += Math.floor(q / (1 + dist));
                }
            }
            // Update best coordinate (lexicographically smallest on ties)
            if (total > bestQuality || (total === bestQuality && (cx < bestX || (cx === bestX && cy < bestY)))) {
                bestQuality = total;
                bestX = cx;
                bestY = cy;
            }
        }
    }
    return [bestX, bestY];
}

