function largestSubstringBetweenEqualChars(s) {
    const firstPos = {};   // character -> first index
    const lastPos = {};    // character -> last index

    // scan the string once
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (firstPos[ch] === undefined) {
            firstPos[ch] = i;          // store first occurrence
        }
        lastPos[ch] = i;               // update last occurrence
    }

    let maxLen = -1;

    // evaluate longest distance for each character
    for (const ch in firstPos) {
        if (lastPos[ch] > firstPos[ch]) {          // appears at least twice
            const curLen = lastPos[ch] - firstPos[ch] - 1;
            if (curLen > maxLen) {
                maxLen = curLen;
            }
        }
    }

    return maxLen;
}

function numberOfSets(n, k) {
    const MOD = 1000000007n;
    const maxVal = n + k;
    const fact = new Array(maxVal+1).fill(1n);
    for (let i = 1; i <= maxVal; i++) fact[i] = (fact[i-1]*BigInt(i))%MOD;
    function modpow(base, exp, mod) {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp&1n) result=(result*base)%mod; base=(base*base)%mod; exp>>=1n; }
        return result;
    }
    const invFact = new Array(maxVal+1).fill(1n);
    invFact[maxVal] = modpow(fact[maxVal], MOD-2n, MOD);
    for (let i = maxVal; i > 0; i--) invFact[i-1] = (invFact[i]*BigInt(i))%MOD;
    function comb(N,R) {
        if (R<0||R>N) return 0n;
        return fact[N]*invFact[R]%MOD*invFact[N-R]%MOD;
    }
    return Number(comb(n+k-1, 2*k));
}

function bestTeamScore(scores, ages) {
    const n = scores.length;
    // pair each player with age and score
    const players = new Array(n);
    for (let i = 0; i < n; i++) {
        players[i] = { age: ages[i], score: scores[i] };
    }

    // sort by age, then by score to break ties
    players.sort((p1, p2) => {
        if (p1.age !== p2.age) return p1.age - p2.age;
        return p1.score - p2.score;
    });

    const dp = new Array(n).fill(0);
    let best = 0;

    for (let i = 0; i < n; i++) {
        dp[i] = players[i].score;                 // start with only this player
        // MAIN LOGIC: extend any earlier team whose last score ≤ current score
        for (let j = 0; j < i; j++) {
