function createFancySequence() {
    const MOD = 1000000007n;
    const values = [];
    const mulAt = [];
    const addAt = [];
    let curMul = 1n;
    let curAdd = 0n;

    function modPow(base, exp) {
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1n;
        }
        return result;
    }

    return {
        append: function (val) {
            values.push(BigInt(val));
            mulAt.push(curMul);
            addAt.push(curAdd);
        },
        addAll: function (inc) {
            curAdd = (curAdd + BigInt(inc)) % MOD;
        },
        multAll: function (m) {
            curMul = (curMul * BigInt(m)) % MOD;
            curAdd = (curAdd * BigInt(m)) % MOD;
        },
        getIndex: function (idx) {
            if (idx < 0 || idx >= values.length) return -1;
            const v = values[idx];
            const m0 = mulAt[idx];
            const a0 = addAt[idx];
            const inv = modPow(m0, MOD - 2n);
            const factor = (curMul * inv) % MOD;
            // FIXED: must subtract a0*factor (not a0*inv) - the additive offset a0 was
            // recorded under the OLD multiplier m0, so it must be scaled by the same
            // "factor" (curMul/m0) as the value itself before being removed from curAdd.
            const add = ((curAdd - (a0 * factor) % MOD) % MOD + MOD) % MOD;
            const res = (v * factor + add) % MOD;
            return Number(res);
        }
    };
}

function slowestKey(releaseTimes, keysPressed) {
    // initialize with the first keypress
    let maxDuration = releaseTimes[0];
    let resultKey = keysPressed[0];

    // iterate over remaining keypresses
    for (let i = 1; i < releaseTimes.length; i++) {
        // duration of the current keypress
        const duration = releaseTimes[i] - releaseTimes[i - 1];

        // update if we found a longer duration or same duration with a larger key
        if (duration > maxDuration || (duration === maxDuration && keysPressed[i] > resultKey)) {
            maxDuration = duration;
            resultKey = keysPressed[i];
