function minimumEffortPath(heights) {
    const rows = heights.length, cols = heights[0].length;
    const dist = Array.from({length:rows}, () => new Array(cols).fill(Infinity));
    dist[0][0] = 0;
    // simple Dijkstra with array-based priority (small enough via binary search insert or just use a sorted array queue)
    const visited = Array.from({length:rows}, () => new Array(cols).fill(false));
    const pq = [[0,0,0]]; // [effort, r, c]
    while (pq.length) {
        pq.sort((a,b) => a[0]-b[0]);
        const [d, r, c] = pq.shift();
        if (visited[r][c]) continue;
        visited[r][c] = true;
        if (r === rows-1 && c === cols-1) return d;
        for (const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
            const nr=r+dr, nc=c+dc;
            if (nr<0||nr>=rows||nc<0||nc>=cols||visited[nr][nc]) continue;
            const nd = Math.max(d, Math.abs(heights[nr][nc]-heights[r][c]));
            if (nd < dist[nr][nc]) { dist[nr][nc] = nd; pq.push([nd,nr,nc]); }
        }
    }
    return dist[rows-1][cols-1];
}

function areConnected(n, threshold, queries) {
    const parent = Array.from({length: n+1}, (_,i)=>i);
    function find(x){ while(parent[x]!==x){parent[x]=parent[parent[x]]; x=parent[x];} return x; }
    function union(a,b){ a=find(a); b=find(b); if(a!==b) parent[a]=b; }
    for (let d = threshold+1; d <= n; d++) {
        for (let m = 2*d; m <= n; m += d) union(d, m);
    }
    return queries.map(([a,b]) => find(a)===find(b));
}

function findLexSmallestString(s, a, b) {
    const n = s.length;
    const seen = new Set();
    let best = s;
    const queue = [s];
    seen.add(s);
    function addA(str) {
        return str.split('').map((c,i) => i%2===1 ? String((Number(c)+a)%10) : c).join('');
    }
    function rotate(str) {
        return str.slice(n-b) + str.slice(0, n-b);
    }
    while (queue.length) {
        const cur = queue.shift();
        if (cur < best) best = cur;
        for (const next of [addA(cur), rotate(cur)]) {
            if (!seen.has(next)) { seen.add(next); queue.push(next); }
        }
    }
    return best;
}

function checkArithmeticSubarrays(nums, l, r) {
    const m = l.length;
    const answer = new Array(m);
    for (let i = 0; i < m; i++) {
        const start = l[i];
        const end = r[i];
        const len = end - start + 1;

        // subarrays of length 0 or 1 are trivially arithmetic
        if (len <= 2) {
            answer[i] = true;
            continue;
        }

        let min = nums[start];
        let max = nums[start];

        // find min and max in the subarray
        for (let j = start + 1; j <= end; j++) {
            const v = nums[j];
            if (v < min) min = v;
            if (v > max) max = v;
        }

        // if the range cannot be evenly divided, not arithmetic
        if ((max - min) % (len - 1) !== 0) {
            answer[i] = false;
            continue;
        }

        const diff = (max - min) / (len - 1);
        // all elements equal case
        if (diff === 0) {
            answer[i] = true;
            continue;
        }

        const seen = new Array(len).fill(false);
        let ok = true;

        // verify each element fits the arithmetic progression
        for (let j = start; j <= end && ok; j++) {
            const v = nums[j];
            if ((v - min) % diff !== 0) {
                ok = false;
                break;
            }
            const idx = (v - min) / diff;
            if (idx < 0 || idx >= len || seen[idx]) {
                ok = false;
                break;
            }
            seen[idx] = true;
        }

        answer[i] = ok;
    }
    return answer;
}

function matrixRankTransform(matrix) {
    const m = matrix.length;
    const n = matrix[0].length;

    // collect all cells with their coordinates and values
    const cells = [];
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            cells.push({ val: matrix[i][j], row: i, col: j });
        }
    }

    // sort cells by value (ascending)
    cells.sort((a, b) => a.val - b.val);

    const answer = Array.from({ length: m }, () => Array(n));
    const rank = new Array(m + n).fill(0); // rank for each row and column

    let idx = 0;
    while (idx < cells.length) {
        const sameVal = [];
        const curVal = cells[idx].val;

        // gather all cells with the same value
        while (idx < cells.length && cells[idx].val === curVal) {
            sameVal.push(cells[idx]);
            idx++;
        }

        // temporary DSU for this group (only nodes that appear)
        const parent = {};

        const find = (x) => {
            if (!(x in parent)) parent[x] = x;
            while (parent[x] !== x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };

        const union = (a, b) => {
            const ra = find(a);
            const rb = find(b);
            if (ra !== rb) parent[ra] = rb;
        };

        // union row and column nodes for each cell
        for (const cell of sameVal) {
            union(cell.row, m + cell.col);
        }

        // compute the maximum existing rank for each component
        const compMax = {};
        for (const cell of sameVal) {
            const root = find(cell.row);
            const curMax = Math.max(rank[cell.row], rank[m + cell.col]);
            compMax[root] = Math.max(compMax[root] || 0, curMax);
        }

        // assign new rank to each cell and update row/col ranks
        for (const cell of sameVal) {
            const root = find(cell.row);
            const newRank = compMax[root] + 1;
            answer[cell.row][cell.col] = newRank;
            rank[cell.row] = newRank;
            rank[m + cell.col] = newRank;
        }
    }

    return answer;
}
// TIME: O(m*n log(m*n)) SPACE: O(m*n)

function countVowelStrings(n) {
    // dp[i] = number of strings of the current length that end with the i-th vowel (a,e,i,o,u)
    let dp = Array(5).fill(1);

    for (let len = 2; len <= n; len++) {
        for (let i = 1; i < 5; i++) {
            dp[i] += dp[i - 1];
        }
    }
    // total is the sum across ALL ending vowels, not just dp[4] (strings ending in 'u')
    return dp.reduce((a, b) => a + b, 0);
}

function sortArrayByIncreasingFrequency(nums) {
    // build frequency map
    const freq = {};
    for (const v of nums) {
        freq[v] = (freq[v] || 0) + 1;
    }

    // sort by frequency asc, then value desc
    nums.sort((a, b) => {
        if (freq[a] !== freq[b]) {
            return freq[a] - freq[b];          // lower frequency first
        }
        return b - a;                          // same frequency → larger value first
    });

    return nums;
}

function numWays(words, target) {
    const MOD = 1000000007;
    const m = words[0].length;
    const n = target.length;

    // count[c][pos] = how many words have character c at position pos
    const count = Array.from({ length: 26 }, () => Array(m).fill(0));
    for (const w of words) {
        for (let pos = 0; pos < m; pos++) {
            const idx = w.charCodeAt(pos) - 97;
            count[idx][pos] += 1;
        }
    }

    // dp[i] = ways to form first i characters of target using processed positions
    const dp = Array(n + 1).fill(0);
    dp[0] = 1;

    // iterate over each column (position) of the words
    for (let pos = 0; pos < m; pos++) {
