function kthSmallestPath(destination, k) {
    let [row, col] = destination;
    function binom(n, r) {
        if (r < 0 || r > n) return 0;
        let res = 1;
        for (let i = 0; i < r; i++) res = res * (n - i) / (i + 1);
        return Math.round(res);
    }
    let result = "";
    let h = col, v = row;
    while (h > 0 || v > 0) {
        if (h === 0) { result += 'V'; v--; continue; }
        if (v === 0) { result += 'H'; h--; continue; }
        const countIfH = binom(h - 1 + v, v);
        if (k <= countIfH) {
            result += 'H';
            h--;
        } else {
            k -= countIfH;
            result += 'V';
            v--;
        }
