    return deletions;
}

function furthestBuilding(heights, bricks, ladders) {
    // min‑heap to store the climbs we have taken so far
    const heap = [];

    function heapPush(val) {
        heap.push(val);
        let idx = heap.length - 1;
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (heap[parent] <= heap[idx]) break;
            [heap[parent], heap[idx]] = [heap[idx], heap[parent]];
            idx = parent;
        }
    }

    function heapPop() {
        if (heap.length === 1) return heap.pop();
        const top = heap[0];
        heap[0] = heap.pop();
        let idx = 0;
        while (true) {
            const left = idx * 2 + 1;
            const right = idx * 2 + 2;
            let smallest = idx;
            if (left < heap.length && heap[left] < heap[smallest]) smallest = left;
            if (right < heap.length && heap[right] < heap[smallest]) smallest = right;
            if (smallest === idx) break;
            [heap[smallest], heap[idx]] = [heap[idx], heap[smallest]];
            idx = smallest;
        }
        return top;
    }

    for (let i = 0; i < heights.length - 1; i++) {
        const climb = heights[i + 1] - heights[i];
        if (climb <= 0) continue;                 // no resources needed
        heapPush(climb);                           // assume we use a ladder for this climb
        if (heap.length > ladders) {               // too many ladders, replace smallest with bricks
            const smallestClimb = heapPop();
            bricks -= smallestClimb;
            if (bricks < 0) return i;              // cannot reach building i+1
