function createSortedArray(instructions) {
    const MOD = 1_000_000_007;

    const uniq = Array.from(new Set(instructions)).sort((a, b) => a - b);
    const indexMap = new Map();
    for (let i = 0; i < uniq.length; i++) {
        indexMap.set(uniq[i], i + 1);
    }

    class Fenwick {
        constructor(size) {
            this.n = size;
            this.tree = new Array(size + 1).fill(0);
        }
        add(i, delta) {
            while (i <= this.n) { this.tree[i] += delta; i += i & -i; }
        }
        prefixSum(i) {
            let sum = 0;
            while (i > 0) { sum += this.tree[i]; i -= i & -i; }
            return sum;
        }
    }

    const bit = new Fenwick(uniq.length);
    let total = 0;

    for (let i = 0; i < instructions.length; i++) {
        const idx = indexMap.get(instructions[i]);
        const less = bit.prefixSum(idx - 1);
        const lessOrEqual = bit.prefixSum(idx);
        const greater = i - lessOrEqual;
        total = (total + Math.min(less, greater)) % MOD;
        bit.add(idx, 1);
    }

    return total;
}

