        const nxt = inv[i+1];
        const cnt = i+1;
        const diff = cur-nxt;
        if (diff === 0) { i++; continue; }
        const balls = diff*cnt;
        if (orders >= balls) {
            const total = (cur+nxt+1)*diff/2;
            profit += cnt*total;
            orders -= balls;
            i++;
