function canDistribute(nums, quantity) {
  // count how many times each distinct integer appears
  const freqMap = {};
  for (const v of nums) freqMap[v] = (freqMap[v] || 0) + 1;
  const freqs = Object.values(freqMap);          // array of available counts

  const m = quantity.length;
  const fullMask = (1 << m) - 1;

  // larger orders first – helps pruning
  quantity.sort((a, b) => b - a);

  // pre‑compute total quantity for every subset of customers
  const subsetSum = new Array(1 << m).fill(0);
  for (let mask = 1; mask < 1 << m; mask++) {
    const lsb = mask & -mask;                     // lowest set bit
    const idx = Math.log2(lsb);                   // which customer it is
    subsetSum[mask] = subsetSum[mask ^ lsb] + quantity[idx];
  }

  const memo = new Map();                         // memo key: "mask,i"

  function dfs(mask, i) {
    if (mask === 0) return true;                  // all customers satisfied
    if (i === freqs.length) return false;         // no more numbers left

    const key = mask + ',' + i;
    if (memo.has(key)) return memo.get(key);

    // try skipping the current integer count
    if (dfs(mask, i + 1)) {
      memo.set(key, true);
      return true;
    }

    // try giving this integer to any non‑empty subset of remaining customers
    for (let sub = mask; sub; sub = (sub - 1) & mask) {
      if (subsetSum[sub] <= freqs[i]) {           // enough copies for this subset
        if (dfs(mask ^ sub, i + 1)) {
          memo.set(key, true);
          return true;
        }
      }
    }

    memo.set(key, false);
    return false;
  }

  return dfs(fullMask, 0);
}

function decrypt(code, k) {
    const n = code.length;
    const result = new Array(n).fill(0);
    if (k === 0) return result;                 // all zeros

    const steps = Math.abs(k);
    let window = 0;

    if (k > 0) {
        // initial sum of the next `steps` elements for index 0
        for (let i = 1; i <= steps; i++) {
            window += code[i % n];
        }
        for (let i = 0; i < n; i++) {
            result[i] = window;                  // assign current window sum
            // slide window: remove the element that leaves, add the new entering element
            window -= code[(i + 1) % n];
            window += code[(i + steps + 1) % n];
        }
    } else {
        // initial sum of the previous `steps` elements for index 0
        for (let i = 0; i < steps; i++) {
            window += code[(n - 1 - i + n) % n];
        }
        for (let i = 0; i < n; i++) {
            result[i] = window;                  // assign current window sum
            // slide window: remove the farthest previous element, add the current element
            window -= code[(i - steps + n) % n];
            window += code[i];
        }
    }

    return result;
}

