    for (let v of nums) total += v;          // total sum of array

    const target = total - x;                // sum we need to keep
    if (target < 0) return -1;               // impossible
    if (target === 0) return n;              // must remove everything

    let left = 0, curr = 0, maxLen = -1;     // sliding window variables
    for (let right = 0; right < n; right++) {
