function minimumJumps(forbidden, a, b, x) {
    const forbiddenSet = new Set(forbidden);                     // O(F)
    const maxForbidden = Math.max(0, ...forbidden);
    const limit = Math.max(maxForbidden, x) + a + b;             // search bound

    const visited = new Set();                                    // "pos,prevBack"
    const queue = [];
    queue.push([0, false, 0]);                                   // position, prevBack, steps
    visited.add('0,false');

    while (queue.length) {
        const [pos, prevBack, steps] = queue.shift();
        if (pos === x) return steps;                             // reached home

        // ----- forward jump -----
        const forward = pos + a;
        if (forward <= limit && !forbiddenSet.has(forward)) {
            const key = `${forward},false`;
            if (!visited.has(key)) {
                visited.add(key);
                queue.push([forward, false, steps + 1]);
            }
        }

        // ----- backward jump (only if previous wasn't backward) -----
        if (!prevBack) {
            const backward = pos - b;
            if (backward >= 0 && !forbiddenSet.has(backward)) {
                const key = `${backward},true`;
                if (!visited.has(key)) {
                    visited.add(key);
                    queue.push([backward, true, steps + 1]);
