function areCloseStrings(word1, word2) {
    if (word1.length !== word2.length) return false;          // lengths must match

    const cnt1 = new Array(26).fill(0);
    const cnt2 = new Array(26).fill(0);
    const aCode = 'a'.charCodeAt(0);

    for (let i = 0; i < word1.length; i++) {                 // count letters in word1
        cnt1[word1.charCodeAt(i) - aCode]++;
        cnt2[word2.charCodeAt(i) - aCode]++;                 // count letters in word2
    }

    // both strings must contain the same set of characters
    for (let i = 0; i < 26; i++) {
