    let leftEven = 0, leftOdd = 0;
    let count = 0;
    for (let i = 0; i < n; i++) {
        let rightEven, rightOdd;
        if (i % 2 === 0) { rightEven = totalEven - leftEven - nums[i]; rightOdd = totalOdd - leftOdd; }
        else { rightEven = totalEven - leftEven; rightOdd = totalOdd - leftOdd - nums[i]; }
        const newEvenSum = leftEven + rightOdd;
        const newOddSum = leftOdd + rightEven;
        if (newEvenSum === newOddSum) count++;
        if (i % 2 === 0) leftEven += nums[i]; else leftOdd += nums[i];
    }
    return count;
}

function maxGridHappiness(m, n, introvertsCount, extrovertsCount) {
  const totalCells = m * n;
  const grid = new Array(totalCells).fill(0); // 0 empty, 1 introvert, 2 extrovert
  const base = { 1: 120, 2: 40 };
  const adjDelta = {
    1: { 1: -60, 2: -10 }, // new introvert with neighbor introvert/extrovert
    2: { 1: -10, 2: 40 }   // new extrovert with neighbor introvert/extrovert
  };
  let best = 0;

  function dfs(pos, introLeft, extroLeft, current) {
    if (pos === totalCells) {
      if (current > best) best = current;
      return;
    }
    // If no people left, we can skip remaining cells
    if (introLeft === 0 && extroLeft === 0) {
      if (current > best) best = current;
      return;
    }

    // Option 1: leave empty
    dfs(pos + 1, introLeft, extroLeft, current);

    const row = Math.floor(pos / n);
    const col = pos % n;
    const left = col > 0 ? grid[pos - 1] : 0;
    const up = row > 0 ? grid[pos - n] : 0;

    // Option 2: place introvert
    if (introLeft > 0) {
      let add = base[1];
      if (left) add += adjDelta[1][left];
      if (up) add += adjDelta[1][up];
      grid[pos] = 1;
      dfs(pos + 1, introLeft - 1, extroLeft, current + add);
      grid[pos] = 0;
    }

    // Option 3: place extrovert
    if (extroLeft > 0) {
      let add = base[2];
      if (left) add += adjDelta[2][left];
      if (up) add += adjDelta[2][up];
      grid[pos] = 2;
      dfs(pos + 1, introLeft, extroLeft - 1, current + add);
      grid[pos] = 0;
    }
  }

  dfs(0, introvertsCount, extrovertsCount, 0);
  return best;
}
