function minimumDeviation(nums) {
    // ---------- max‑heap implementation ----------
    class MaxHeap {
        constructor() { this.data = []; }
        peek() { return this.data[0]; }
        push(val) {
            const a = this.data;
            a.push(val);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (a[p] >= a[i]) break;
                [a[p], a[i]] = [a[i], a[p]];
                i = p;
            }
        }
        pop() {
            const a = this.data;
            const top = a[0];
            const last = a.pop();
            if (a.length) {
                a[0] = last;
                let i = 0;
                while (true) {
                    let l = i * 2 + 1,
                        r = i * 2 + 2,
                        largest = i;
                    if (l < a.length && a[l] > a[largest]) largest = l;
                    if (r < a.length && a[r] > a[largest]) largest = r;
                    if (largest === i) break;
                    [a[i], a[largest]] = [a[largest], a[i]];
                    i = largest;
                }
