    // ---------- greedy reduction of the current maximum ----------
    let best = heap.peek() - currentMin;
    while (heap.peek() % 2 === 0) {
        const maxVal = heap.pop();
        const reduced = maxVal / 2;
        heap.push(reduced);
        if (reduced < currentMin) currentMin = reduced;
        const deviation = heap.peek() - currentMin;
        if (deviation < best) best = deviation;
    }

    return best;
