        // Add current number if we haven't reached size k yet
        if (stack.length < k) {
            stack.push(nums[i]);
        }
    }

    return stack;
}

function maxOperations(nums, k) {
    // sort to enable two‑pointer pairing
    nums.sort((a, b) => a - b);

    let left = 0;
    let right = nums.length - 1;
    let operations = 0;

    while (left < right) {
        const sum = nums[left] + nums[right];
        if (sum === k) {          // found a valid pair
            operations++;
            left++;
            right--;
        } else if (sum < k) {
            left++;                // need a larger sum
        } else {
            right--;               // need a smaller sum
        }
    }
    return operations;
}

function concatenatedBinary(n) {
    const MOD = 1000000007n;          // modulus as BigInt
    let result = 0n;                  // accumulated value
    let pow2 = 1n;                    // will hold 2^{bit length}
    for (let i = 1; i <= n; i++) {
        if ((i & (i - 1)) === 0) {    // i is a power of two → bit length grows
            pow2 = (pow2 * 2n) % MOD;
        }
        result = (result * pow2 + BigInt(i)) % MOD; // shift left and append i
    }
    return Number(result);            // final value fits in Number range
}

var minMoves = function(nums, limit) {
    const n = nums.length;
    const pairCnt = Math.floor(n/2);
    const maxSum = 2*limit;
    const diff = new Array(maxSum+2).fill(0);
    const cnt0 = new Array(maxSum+2).fill(0);
    for (let i=0;i<pairCnt;i++) {
        const a = nums[i], b = nums[n-1-i];
        const s = a+b;
        cnt0[s]++;
        const low = Math.min(a,b)+1;
        const high = Math.max(a,b)+limit;
        diff[low]++;
        if (high+1 < diff.length) diff[high+1]--;
    }
    const cnt1 = new Array(maxSum+2).fill(0);
    let cur = 0;
    for (let t=2;t<=maxSum;t++) {
        cur += diff[t];
        cnt1[t] = cur;
    }
    let ans = Infinity;
    for (let t=2;t<=maxSum;t++) {
        const moves = 2*pairCnt - cnt1[t] - cnt0[t];
        if (moves < ans) ans = moves;
    }
    return ans;
};

function interpret(command) {
    let result = '';
    let i = 0;
    while (i < command.length) {
        if (command[i] === 'G') {               // handle single 'G'
            result += 'G';
            i++;
        } else if (command[i] === '(') {
            if (command[i + 1] === ')') {       // handle "()"
                result += 'o';
                i += 2;
            } else {                             // handle "(al)"
                result += 'al';
                i += 4;
            }
        }
    }
    return result;
}

function sumOfAbsoluteDifferences(nums) {
    const n = nums.length;
    const prefix = new Array(n);
    let sum = 0;
    for (let i = 0; i < n; i++) {          // build prefix sums
        sum += nums[i];
        prefix[i] = sum;
    }

    const total = sum;
    const result = new Array(n);
    for (let i = 0; i < n; i++) {
        const leftCount = i;                         // elements left of i
        const rightCount = n - i - 1;                // elements right of i

        const leftSum = leftCount > 0 ? prefix[i - 1] : 0;
        const rightSum = total - prefix[i];

        // left contribution + right contribution
        result[i] = nums[i] * leftCount - leftSum
                    + rightSum - nums[i] * rightCount;
    }
    return result;
}

function stoneGameVI(aliceValues, bobValues) {
    const n = aliceValues.length;
    const stones = new Array(n);
    for (let i = 0; i < n; i++) {
        stones[i] = {
            sum: aliceValues[i] + bobValues[i],
            a: aliceValues[i],
            b: bobValues[i]
        };
    }
    // sort by combined importance (largest first)
    stones.sort((x, y) => y.sum - x.sum);

    let aliceScore = 0, bobScore = 0;
    for (let i = 0; i < n; i++) {
        if (i % 2 === 0) {
            aliceScore += stones[i].a; // Alice's turn
        } else {
            bobScore += stones[i].b;   // Bob's turn
        }
    }

    if (aliceScore > bobScore) return 1;
    if (aliceScore < bobScore) return -1;
    return 0;
}

function boxDelivering(boxes, portsCount, maxBoxes, maxWeight) {
    const n = boxes.length;
    const dp = new Array(n+1).fill(0);
    const prefixWeight = new Array(n+1).fill(0);
    for (let i = 0; i < n; i++) prefixWeight[i+1] = prefixWeight[i] + boxes[i][1];
    const trips = new Array(n+1).fill(0);
    for (let i = 1; i < n; i++) trips[i+1] = trips[i] + (boxes[i][0] !== boxes[i-1][0] ? 1 : 0);
    let left = 0;
    const dq = [0];
    for (let i = 1; i <= n; i++) {
        while (i - left > maxBoxes || prefixWeight[i] - prefixWeight[left] > maxWeight) left++;
        while (dq.length && dq[0] < left) dq.shift();
        dp[i] = dp[dq[0]] + trips[i] - trips[dq[0]+1] + 2;
        while (dq.length && dp[dq[dq.length-1]] - trips[dq[dq.length-1]+1] >= dp[i] - trips[i+1]) dq.pop();
        dq.push(i);
    }
    return dp[n];
}

function minimumIncompatibility(nums, k) {
  const n = nums.length;
  const groupSize = n / k;
  if (groupSize === 1) return 0;
  const full = 1 << n;
  const subsetCost = new Array(full).fill(-1);
  for (let mask = 0; mask < full; mask++) {
    if (popcount(mask) !== groupSize) continue;
    const seen = new Set();
    let valid = true, mn = Infinity, mx = -Infinity;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        if (seen.has(nums[i])) { valid = false; break; }
        seen.add(nums[i]);
        mn = Math.min(mn, nums[i]); mx = Math.max(mx, nums[i]);
      }
    }
    if (valid) subsetCost[mask] = mx - mn;
  }
  function popcount(x) { let c = 0; while (x) { c += x & 1; x >>= 1; } return c; }
  const memo = new Map();
  function dp(mask) {
    if (mask === 0) return 0;
    if (memo.has(mask)) return memo.get(mask);
    let best = Infinity;
    // iterate submasks of mask with size groupSize
    let sub = mask;
    while (sub > 0) {
      if (popcount(sub) === groupSize && subsetCost[sub] !== -1) {
        const rest = dp(mask ^ sub);
        if (rest !== Infinity) best = Math.min(best, subsetCost[sub] + rest);
      }
      sub = (sub - 1) & mask;
    }
    memo.set(mask, best);
    return best;
  }
  const ans = dp(full - 1);
  return ans === Infinity ? -1 : ans;
}

function maxHeight(cuboids) {
    // 1. sort dimensions inside each cuboid so we can rotate freely
    for (let c of cuboids) c.sort((a, b) => a - b);

    // 2. sort cuboids lexicographically (width, length, height)
    cuboids.sort((a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        if (a[1] !== b[1]) return a[1] - b[1];
        return a[2] - b[2];
    });

    const n = cuboids.length;
    const dp = new Array(n).fill(0);
    let best = 0;

    // 3. DP: max height of a stack ending with cuboid i on top
    for (let i = 0; i < n; ++i) {
        const h = cuboids[i][2];          // height of i after normalisation
        dp[i] = h;                        // stack consisting of i alone
        for (let j = 0; j < i; ++j) {
            // check if j can be placed below i
            if (cuboids[j][0] <= cuboids[i][0] &&
                cuboids[j][1] <= cuboids[i][1] &&
                cuboids[j][2] <= cuboids[i][2]) {
                dp[i] = Math.max(dp[i], dp[j] + h);
            }
        }
        best = Math.max(best, dp[i]);
    }
    return best;
}

function countConsistentStrings(allowed, words) {
    // build a set of allowed characters for O(1) look‑ups
    const allowedSet = new Set(allowed.split(''));

    let consistentCount = 0;

    for (const w of words) {
        let isConsistent = true;
        // check each character of the current word
        for (const ch of w) {
            if (!allowedSet.has(ch)) {   // character not allowed
                isConsistent = false;
                break;
            }
        }
        if (isConsistent) consistentCount++;
    }

    return consistentCount;
}

function reformatNumber(number) {
    // Remove spaces and dashes
    let digits = '';
    for (let ch of number) {
        if (ch !== ' ' && ch !== '-') digits += ch;
    }

    let groups = [];
    let i = 0;
    // Form groups of 3 while more than 4 digits remain
    while (digits.length - i > 4) {
        groups.push(digits.substr(i, 3));
        i += 3;
    }

    // Handle the last 2‑4 digits
    let remaining = digits.length - i;
    if (remaining === 4) {
        groups.push(digits.substr(i, 2));
        groups.push(digits.substr(i + 2, 2));
    } else {
        groups.push(digits.substr(i));
    }

    return groups.join('-');
}

function countMatches(n) {
    let total = 0;
    // Simulate each round until only one team remains
    while (n > 1) {
        const roundMatches = Math.floor(n / 2); // matches this round
        total += roundMatches;
        n = Math.ceil(n / 2); // teams advancing to next round
    }
    return total;
}

function minPartitions(n) {
    // Find the largest digit in the string
    let maxDigit = 0;
    for (let i = 0; i < n.length; i++) {
        const digit = n.charCodeAt(i) - 48; // '0' -> 0, '9' -> 9
        if (digit > maxDigit) maxDigit = digit;
    }
    return maxDigit;
}

function stoneGameVII(stones) {
    const n = stones.length;
    if (n === 1) return 0;                     // only one stone → no points

    // prefix sums: prefix[k] = sum of stones[0 … k‑1]
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + stones[i];
    }

    // helper to get sum of stones[l … r] inclusive
    const rangeSum = (l, r) => prefix[r + 1] - prefix[l];

    // dp[i][j] = best difference for sub‑array stones[i … j]
    const dp = Array.from({ length: n }, () => new Array(n).fill(0));

    // consider intervals of increasing length
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i + len - 1 < n; i++) {
            const j = i + len - 1;
            const total = rangeSum(i, j);               // sum of stones[i … j]

            // remove leftmost stone i
            const removeLeft = total - stones[i] - dp[i + 1][j];
            // remove rightmost stone j
            const removeRight = total - stones[j] - dp[i][j - 1];

            dp[i][j] = Math.max(removeLeft, removeRight); // optimal choice
        }
    }

    return dp[0][n - 1];
}

function maxErasureValue(nums) {
    const lastSeen = new Map();          // stores the latest index of each value
    let left = 0;
    let currentSum = 0;
    let best = 0;

    for (let right = 0; right < nums.length; right++) {
        const val = nums[right];
        // if val already in window, move left past its previous occurrence
        if (lastSeen.has(val) && lastSeen.get(val) >= left) {
            while (left <= lastSeen.get(val)) {
                currentSum -= nums[left];
                left++;
            }
        }
        currentSum += val;                // extend window to include right
        lastSeen.set(val, right);
        if (currentSum > best) best = currentSum; // update answer
    }
    return best;
}

function distanceLimitedPathsExist(n, edgeList, queries) {
    // sort edges by distance
    edgeList.sort((a, b) => a[2] - b[2]);

    // keep original index of each query
    const indexedQueries = queries.map((q, i) => [q[0], q[1], q[2], i]);
    // sort queries by limit
    indexedQueries.sort((a, b) => a[2] - b[2]);

    // Union‑Find structure
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    const union = (x, y) => {
        let rx = find(x), ry = find(y);
        if (rx === ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank[rx]++; }
    };

    const answer = new Array(queries.length);
    let e = 0; // pointer in edgeList

    // process queries in increasing limit
    for (const [p, q, limit, idx] of indexedQueries) {
        // add all edges whose distance is strictly smaller than current limit
        while (e < edgeList.length && edgeList[e][2] < limit) {
            union(edgeList[e][0], edgeList[e][1]);
            e++;
        }
        // check connectivity using only allowed edges
        answer[idx] = find(p) === find(q);
    }
    return answer;
}

// TIME: O((E + Q) log (E + Q)) SPACE: O(n + E + Q)

function maximumBinaryString(binary) {
    const n = binary.length;
    const firstZero = binary.indexOf('0');
    if (firstZero === -1) return binary;
    const zeroCount = (binary.match(/0/g) || []).length;
    return '1'.repeat(firstZero + zeroCount - 1) + '0' + '1'.repeat(n - firstZero - zeroCount);
}

function maxResult(nums, k) {
    const n = nums.length;
    const dp = new Array(n);
    const deque = []; // stores indices with decreasing dp values

    dp[0] = nums[0];
    deque.push(0);

    for (let i = 1; i < n; i++) {
        // discard indices that are out of the window [i‑k, i‑1]
        while (deque.length && deque[0] < i - k) deque.shift();

        dp[i] = nums[i] + dp[deque[0]]; // best previous reachable score

        // keep deque monotonic: remove smaller dp values from the back
        while (deque.length && dp[deque[deque.length - 1]] <= dp[i]) deque.pop();

        deque.push(i);
    }

    return dp[n - 1];
}

function averageWaitingTime(customers) {
    let currentTime = 0;          // when the chef becomes free
    let totalWaiting = 0;         // sum of all waiting times

    for (let i = 0; i < customers.length; i++) {
        const [arrival, prep] = customers[i];

        if (currentTime < arrival) currentTime = arrival; // chef waits for next arrival
        const finishTime = currentTime + prep;
        totalWaiting += finishTime - arrival;            // waiting time for this customer
        currentTime = finishTime;                        // update chef's next free time
    }

    return totalWaiting / customers.length;
}

function findBall(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const result = new Array(n);

    for (let start = 0; start < n; start++) {
        let col = start;
        let stuck = false;

        for (let row = 0; row < m; row++) {
            const dir = grid[row][col];          // direction of current board
            const nextCol = col + dir;           // where the ball would move

            // check wall collision or V‑shaped trap
            if (nextCol < 0 || nextCol >= n || grid[row][nextCol] !== dir) {
                stuck = true;
                break;
            }
            col = nextCol;                       // ball moves to next column
        }
        result[start] = stuck ? -1 : col;
    }
    return result;
}

function countStudents(students, sandwiches) {
    // count how many students prefer each type
    let pref0 = 0, pref1 = 0;
    for (let s of students) {
        if (s === 0) pref0++;
        else pref1++;
    }

    for (let sand of sandwiches) {
        // serve the sandwich if any remaining student wants it
        if (sand === 0) {
            if (pref0 > 0) pref0--;
            else break;
        } else {
            if (pref1 > 0) pref1--;
            else break;
        }
    }
    return pref0 + pref1; // students left without a sandwich
}

function minSwaps(nums, k) {
    const ones = [];
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 1) ones.push(i);
    }
    if (k <= 1) return 0;
    const m = ones.length;
    const adjusted = new Array(m);
    for (let i = 0; i < m; i++) {
        adjusted[i] = ones[i] - i;
    }
    const prefix = new Array(m + 1).fill(0);
    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + adjusted[i];
    }
    let best = Number.MAX_SAFE_INTEGER;
    for (let start = 0; start + k - 1 < m; start++) {
        const end = start + k - 1;
        const mid = start + Math.floor(k / 2);
        const median = adjusted[mid];
        const leftCount = mid - start;
        const rightCount = end - mid;
        const leftSum = median * leftCount - (prefix[mid] - prefix[start]);
        const rightSum = (prefix[end + 1] - prefix[mid + 1]) - median * rightCount;
        const cost = leftSum + rightSum;
        if (cost < best) best = cost;
    }
    return best;
}

function halvesAreAlike(s) {
    const vowels = new Set(['a','e','i','o','u','A','E','I','O','U']);
    const half = s.length / 2;
    let countFirst = 0, countSecond = 0;

    // count vowels in each half
    for (let i = 0; i < half; i++) {
        if (vowels.has(s[i])) countFirst++;
        if (vowels.has(s[i + half])) countSecond++;
    }

    return countFirst === countSecond;
}

function maxEatenApples(apples, days) {
    const heap = [];                     // min‑heap of {expire, count}
    const n = apples.length;
    let day = 0;
    let eaten = 0;

    // helper: swap two elements in the heap
    const swap = (i, j) => { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; };

    // helper: move element up to keep heap property
    const siftUp = (idx) => {
        while (idx > 0) {
            const parent = (idx - 1) >> 1;
            if (heap[parent].expire <= heap[idx].expire) break;
            swap(parent, idx);
            idx = parent;
        }
    };

    // helper: move element down to keep heap property
    const siftDown = (idx) => {
        const len = heap.length;
        while (true) {
            let smallest = idx;
            const left = idx * 2 + 1;
            const right = left + 1;
            if (left < len && heap[left].expire < heap[smallest].expire) smallest = left;
            if (right < len && heap[right].expire < heap[smallest].expire) smallest = right;
            if (smallest === idx) break;
            swap(idx, smallest);
            idx = smallest;
        }
    };

    const push = (node) => { heap.push(node); siftUp(heap.length - 1); };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) { heap[0] = last; siftDown(0); }
        return top;
    };

    while (day < n || heap.length) {
        // add apples that appear on this day
        if (day < n && apples[day] > 0) {
            push({ expire: day + days[day], count: apples[day] });
        }

        // discard batches that are already rotten or empty
        while (heap.length && (heap[0].expire <= day || heap[0].count === 0)) {
            pop();
        }

        // eat one apple from the batch that expires soonest
        if (heap.length) {
            heap[0].count--;
            eaten++;
            if (heap[0].count === 0) pop();
        }

        day++;
    }
    return eaten;
}

function maximumXor(nums, queries) {
    nums = [...nums].sort((a,b) => a-b);
    const indexedQueries = queries.map(([xi,mi], idx) => [mi, xi, idx]);
    indexedQueries.sort((a,b) => a[0]-b[0] || a[1]-b[1] || a[2]-b[2]);
    const trie = [[-1,-1]];
    function insert(val) {
        let node = 0;
        for (let bit = 30; bit >= 0; bit--) {
            const b = (val >> bit) & 1;
            let nxt = trie[node][b];
            if (nxt === -1) {
                trie.push([-1,-1]);
                nxt = trie.length - 1;
                trie[node][b] = nxt;
            }
            node = nxt;
        }
    }
    function query(x) {
        let node = 0, res = 0;
        for (let bit = 30; bit >= 0; bit--) {
            const b = (x >> bit) & 1;
            const want = 1 - b;
            if (trie[node][want] !== -1) {
                res |= (1 << bit);
                node = trie[node][want];
            } else {
                node = trie[node][b];
            }
        }
        return res;
    }
    const answers = new Array(queries.length).fill(-1);
    let i = 0;
    for (const [mi, xi, idx] of indexedQueries) {
        while (i < nums.length && nums[i] <= mi) { insert(nums[i]); i++; }
        if (i === 0) answers[idx] = -1;
        else answers[idx] = query(xi);
    }
    return answers;
}

function countGoodMeals(deliciousness) {
    const MOD = 1000000007;
    const freq = new Map();          // counts of values seen so far
    let result = 0;

    // determine the largest power of two we need to consider
    let maxVal = 0;
    for (const v of deliciousness) if (v > maxVal) maxVal = v;
    let limit = 1;
    while (limit <= maxVal * 2) limit <<= 1;   // sum can be at most 2*maxVal

    for (const cur of deliciousness) {
        // check all powers of two for a possible complement
        for (let p = 1; p <= limit; p <<= 1) {
            const need = p - cur;
            if (freq.has(need)) {
                result = (result + freq.get(need)) % MOD;
            }
        }
        // store current value for future pairs
        freq.set(cur, (freq.get(cur) || 0) + 1);
    }
    return result;
}

function waysToSplit(nums) {
    const MOD = 1000000007;
    const n = nums.length;
    if (n < 3) return 0;
    const prefix = new Array(n+1).fill(0);
    for (let i = 0; i < n; i++) prefix[i+1] = prefix[i] + nums[i];
    const total = prefix[n];
    let ans = 0, low = 1, high = 1;
    for (let i = 0; i < n - 2; i++) {
        const leftSum = prefix[i+1];
        if (low < i+1) low = i+1;
        if (high < i+1) high = i+1;
        while (low < n-1 && prefix[low+1] - prefix[i+1] < leftSum) low++;
        while (high < n-1 && prefix[high+1] - prefix[i+1] <= total - prefix[high+1]) high++;
        if (low < n-1) ans = (ans + Math.max(0, high - low)) % MOD;
    }
    return ans;
}

function maximumUnits(boxTypes, truckSize) {
    // sort box types by units per box descending
    boxTypes.sort((a, b) => b[1] - a[1]);

    let totalUnits = 0;
    let remaining = truckSize;

    for (let i = 0; i < boxTypes.length && remaining > 0; i++) {
        const [boxCount, unitsPerBox] = boxTypes[i];
        const take = Math.min(boxCount, remaining);   // choose as many as possible from this type
        totalUnits += take * unitsPerBox;
        remaining -= take;
    }

    return totalUnits;
}

function maximumScore(s, x, y) {
    // decide which substring to delete first (higher score)
    let first = "ab", firstScore = x;
    let second = "ba", secondScore = y;
    if (y > x) {
        first = "ba"; firstScore = y;
        second = "ab"; secondScore = x;
    }

    let stack = [];
    let total = 0;

    // first pass: greedily remove the higher‑value substring
    for (const ch of s) {
        if (stack.length && stack[stack.length - 1] === first[0] && ch === first[1]) {
            stack.pop();               // delete the pair
            total += firstScore;       // add its points
        } else {
            stack.push(ch);
        }
    }

    // second pass: remove the remaining lower‑value substring
    let stack2 = [];
    for (const ch of stack) {
        if (stack2.length && stack2[stack2.length - 1] === second[0] && ch === second[1]) {
            stack2.pop();              // delete the pair
            total += secondScore;      // add its points
