function minOperations(target, arr) {
    // map each target value to its index
    const pos = new Map();
    for (let i = 0; i < target.length; i++) {
        pos.set(target[i], i);
    }

    // collect indices of arr elements that exist in target
    const indices = [];
    for (const v of arr) {
        if (pos.has(v)) indices.push(pos.get(v));
    }

    // longest increasing subsequence (patience sorting)
    const tails = [];                     // tails[i] = smallest possible tail of an LIS of length i+1
    for (const x of indices) {
        // binary search for the first tail >= x
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (tails[mid] < x) lo = mid + 1;
            else hi = mid;
        }
        if (lo === tails.length) tails.push(x); // extend LIS
        else tails[lo] = x;                     // replace to keep tails minimal
