function constructLargestValidSequence(n) {
    const len = 2 * n - 1;
    const res = new Array(len).fill(0);
    const used = new Array(n + 1).fill(false);

    function backtrack(pos) {
        if (pos === len) return true;
        if (res[pos] !== 0) return backtrack(pos + 1);
        for (let num = n; num >= 1; num--) {
            if (used[num]) continue;
            if (num === 1) {
                res[pos] = 1;
                used[1] = true;
                if (backtrack(pos + 1)) return true;
                res[pos] = 0;
                used[1] = false;
            } else {
                const second = pos + num;
                if (second < len && res[second] === 0) {
                    res[pos] = num; res[second] = num; used[num] = true;
                    if (backtrack(pos + 1)) return true;
                    res[pos] = 0; res[second] = 0; used[num] = false;
                }
            }
        }
        return false;
    }
    backtrack(0);
    return res;
}

function minimumHammingDistance(source, target, allowedSwaps) {
    const n = source.length;
    const parent = new Array(n);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        const ra = find(a);
        const rb = find(b);
        if (ra !== rb) parent[ra] = rb;
    }

    // unite indices that can be swapped
    for (const [a, b] of allowedSwaps) union(a, b);

    const groups = new Map();               // root -> list of indices in the component
    for (let i = 0; i < n; i++) {
        const root = find(i);
        if (!groups.has(root)) groups.set(root, []);
        groups.get(root).push(i);
    }

    let mismatches = 0;
    // for each component, match as many values as possible
    for (const indices of groups.values()) {
        const srcCount = new Map();          // value frequency in source within this component
        for (const idx of indices) {
            const val = source[idx];
            srcCount.set(val, (srcCount.get(val) || 0) + 1);
        }
        for (const idx of indices) {
            const val = target[idx];
            if (srcCount.has(val) && srcCount.get(val) > 0) {
                srcCount.set(val, srcCount.get(val) - 1);
            } else {
                mismatches++;
            }
        }
    }

    return mismatches;
}

