function calculateMoney(n) {
    // number of complete weeks and leftover days
    const full = Math.floor(n / 7);
    const rem = n % 7;

    // sum of all complete weeks: 7 * (1+2+...+full) + 21 * full
    const fullWeeksTotal = 7 * (full * (full + 1) / 2) + 21 * full;

    // sum of the remaining days in the next week
    const remTotal = rem * (full + 1) + (rem * (rem - 1)) / 2;

    return fullWeeksTotal + remTotal;
