function numberOfWays(pairs) {
    const adj = new Map();
    for (const [x, y] of pairs) {
        if (!adj.has(x)) adj.set(x, new Set());
        if (!adj.has(y)) adj.set(y, new Set());
        adj.get(x).add(y);
        adj.get(y).add(x);
    }
    const n = adj.size;

    let root = -1;
    for (const [node, neighbors] of adj) {
        if (neighbors.size === n - 1) { root = node; break; }
    }
    if (root === -1) return 0;

    let ans = 1;
    for (const [node, neighbors] of adj) {
        if (node === root) continue;
        let parent = -1, parentSize = Infinity;
        for (const nb of neighbors) {
            const nbSize = adj.get(nb).size;
            // parent candidate's neighbor-set size must be >= this node's - equal size
            // signals a genuine tie (ambiguous parent choice), not a disqualification
            if (nbSize >= neighbors.size && nbSize < parentSize) {
                parent = nb;
                parentSize = nbSize;
            }
        }
        if (parent === -1) return 0;
        if (parentSize === neighbors.size) ans = 2; // tie -> multiple valid trees exist
