    }

    // use two‑pointer technique to locate kth node from the end
    let kthFromEnd = head;
    let fast = kthFromStart;
    while (fast.next) {
        fast = fast.next;
        kthFromEnd = kthFromEnd.next;
    }

    // swap the node values
    const tmp = kthFromStart.val;
    kthFromStart.val = kthFromEnd.val;
    kthFromEnd.val = tmp;

    return head;
}

function minimumTimeRequired(jobs, k) {
    jobs.sort((a,b) => b-a);
    const n = jobs.length;
    const workers = new Array(k).fill(0);

    function backtrack(idx, limit) {
        if (idx === n) return true;
        const seen = new Set();
        for (let i = 0; i < k; i++) {
            if (seen.has(workers[i])) continue;
            if (workers[i] + jobs[idx] <= limit) {
                seen.add(workers[i]);
                workers[i] += jobs[idx];
                if (backtrack(idx + 1, limit)) return true;
                workers[i] -= jobs[idx];
            }
            if (workers[i] === 0) break;
        }
        return false;
    }

    let lo = Math.max(...jobs), hi = jobs.reduce((a,b)=>a+b,0);
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        workers.fill(0);
        if (backtrack(0, mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

function minimumTeachings(n, languages, friendships) {
    // Build a set of languages for each user for O(1) look‑ups
