function decodeXorPermutation(encoded) {
    const n = encoded.length + 1;               // length of original permutation

    // XOR of all numbers 1..n
    let totalXor = 0;
    for (let i = 1; i <= n; i++) totalXor ^= i;

    // XOR of perm[1]..perm[n-1] (all except the first) using encoded at odd indices
    let xorExceptFirst = 0;
    for (let i = 1; i < encoded.length; i += 2) xorExceptFirst ^= encoded[i];

    const perm = new Array(n);
    perm[0] = totalXor ^ xorExceptFirst;        // recover the first element

    // recover the rest using the definition encoded[i] = perm[i] XOR perm[i+1]
    for (let i = 0; i < encoded.length; i++) {
        perm[i + 1] = perm[i] ^ encoded[i];
    }

    return perm;
}

function largestSubmatrix(matrix) {
    if (!matrix || matrix.length === 0) return 0;
    const rows = matrix.length;
    const cols = matrix[0].length;
    const heights = new Array(cols).fill(0);
    let maxArea = 0;

    for (let r = 0; r < rows; r++) {
        // update consecutive 1's height for each column
        for (let c = 0; c < cols; c++) {
            heights[c] = matrix[r][c] === 1 ? heights[c] + 1 : 0;
        }

        // sort heights descending to simulate optimal column reordering
        const sorted = heights.slice().sort((a, b) => b - a);
        // compute best area using sorted heights
        for (let i = 0; i < cols; i++) {
            const area = sorted[i] * (i + 1);
            if (area > maxArea) maxArea = area;
        }
    }

    return maxArea;
}

function catMouseGame(grid, catJump, mouseJump) {
    const rows = grid.length, cols = grid[0].length;
    const total = rows * cols;
    let mouseStart=-1, catStart=-1, food=-1;
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const ch = grid[i][j];
            if (ch==='M') mouseStart = i*cols+j;
            else if (ch==='C') catStart = i*cols+j;
            else if (ch==='F') food = i*cols+j;
        }
    }
    const passable = Array.from({length:rows}, (_,i) => new Array(cols).fill(0).map((_,j)=>grid[i][j]!=='#'));
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    function computeMoves(jump) {
        const moves = Array.from({length:total}, () => []);
        for (let r = 0; r < rows; r++) {
            for (let c = 0; c < cols; c++) {
                if (!passable[r][c]) continue;
                const idx = r*cols+c;
                moves[idx].push(idx);
                for (const [dr,dc] of dirs) {
                    let nr=r, nc=c;
                    for (let k = 0; k < jump; k++) {
                        nr += dr; nc += dc;
                        if (!(nr>=0&&nr<rows&&nc>=0&&nc<cols)) break;
                        if (!passable[nr][nc]) break;
                        moves[idx].push(nr*cols+nc);
                    }
                }
            }
        }
        return moves;
    }
    const mouseMoves = computeMoves(mouseJump);
    const catMoves = computeMoves(catJump);
    const mouseRev = Array.from({length:total}, () => []);
    const catRev = Array.from({length:total}, () => []);
    for (let src = 0; src < total; src++) {
        for (const dst of mouseMoves[src]) mouseRev[dst].push(src);
        for (const dst of catMoves[src]) catRev[dst].push(src);
    }
    const result = new Map();
    const degree = new Map();
    function key(m,c,t) { return m+'_'+c+'_'+t; }
    for (let m = 0; m < total; m++) {
        for (let c = 0; c < total; c++) {
            if (!passable[Math.floor(m/cols)][m%cols] || !passable[Math.floor(c/cols)][c%cols]) continue;
            for (const turn of [0,1]) {
                const k = key(m,c,turn);
                degree.set(k, turn===0 ? mouseMoves[m].length : catMoves[c].length);
                if (m === food) result.set(k, 1);
                else if (c === food || m === c) result.set(k, -1);
            }
        }
    }
    const q = [...result.keys()];
    let head = 0;
    while (head < q.length) {
        const curKey = q[head++];
        const [m,c,turn] = curKey.split('_').map(Number);
        const curRes = result.get(curKey);
        if (turn === 0) {
            for (const pc of catRev[c]) {
                const predKey = key(m,pc,1);
                if (result.has(predKey)) continue;
                if (curRes === -1) { result.set(predKey,-1); q.push(predKey); }
                else {
                    degree.set(predKey, degree.get(predKey)-1);
                    if (degree.get(predKey) === 0) { result.set(predKey,1); q.push(predKey); }
                }
            }
        } else {
            for (const pm of mouseRev[m]) {
                const predKey = key(pm,c,0);
                if (result.has(predKey)) continue;
                if (curRes === 1) { result.set(predKey,1); q.push(predKey); }
                else {
                    degree.set(predKey, degree.get(predKey)-1);
                    if (degree.get(predKey) === 0) { result.set(predKey,-1); q.push(predKey); }
                }
            }
        }
    }
    const finalKey = key(mouseStart, catStart, 0);
    return (result.has(finalKey) ? result.get(finalKey) : -1) === 1;
}

function minCharacters(a, b) {
    const ca = new Array(26).fill(0), cb = new Array(26).fill(0);
    for (const c of a) ca[c.charCodeAt(0)-97]++;
    for (const c of b) cb[c.charCodeAt(0)-97]++;
    const la = a.length, lb = b.length;
    let best = Infinity;
    for (let i = 0; i < 26; i++) best = Math.min(best, la - ca[i] + lb - cb[i]);
    let prefA = 0, prefB = 0;
    for (let i = 0; i < 25; i++) {
        prefA += ca[i]; prefB += cb[i];
        best = Math.min(best, (la - prefA) + prefB);
        best = Math.min(best, (lb - prefB) + prefA);
    }
    return best;
}

function kthLargestXorCoordinate(matrix, k) {
    const m = matrix.length;
    const n = matrix[0].length;
    const pref = Array.from({ length: m }, () => Array(n).fill(0));
    const vals = [];

    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const top = i > 0 ? pref[i - 1][j] : 0;
            const left = j > 0 ? pref[i][j - 1] : 0;
            const diag = i > 0 && j > 0 ? pref[i - 1][j - 1] : 0;
            pref[i][j] = top ^ left ^ diag ^ matrix[i][j]; // compute XOR for (i,j)
            vals.push(pref[i][j]);
        }
    }

    vals.sort((a, b) => b - a); // descending order
    return vals[k - 1];
}



