function minFloorBoxes(n) {
    // Find the largest h such that tetrahedral number T_h = h*(h+1)*(h+2)/6 <= n
    let low = 0;
    let high = 2000000; // sufficiently large upper bound for n up to 1e9
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        const tetra = mid * (mid + 1) * (mid + 2) / 6;
        if (tetra <= n) {
            low = mid;
        } else {
            high = mid - 1;
        }
    }
    const h = low;
    const tetra = h * (h + 1) * (h + 2) / 6;
