function countWays(queries) {
    const MOD = 1000000007n;
    let maxN = 0, maxE = 0;
    function factorExponents(k) {
        const exps = [];
        let d = 2;
        while (d*d <= k) {
            if (k % d === 0) {
                let cnt = 0;
                while (k % d === 0) { k = Math.floor(k/d); cnt++; }
                exps.push(cnt);
            }
            d += (d === 2) ? 1 : 2;
        }
        if (k > 1) exps.push(1);
        return exps;
    }
    for (const [n,k] of queries) {
        if (n > maxN) maxN = n;
        if (k !== 1) for (const e of factorExponents(k)) if (e > maxE) maxE = e;
    }
    const limit = maxN + maxE + 5;
    const fact = new Array(limit+1).fill(1n);
    for (let i = 1; i <= limit; i++) fact[i] = (fact[i-1]*BigInt(i))%MOD;
    function modpow(base, exp, mod) {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp&1n) result=(result*base)%mod; base=(base*base)%mod; exp>>=1n; }
        return result;
    }
    const invFact = new Array(limit+1).fill(1n);
    invFact[limit] = modpow(fact[limit], MOD-2n, MOD);
    for (let i = limit; i > 0; i--) invFact[i-1] = (invFact[i]*BigInt(i))%MOD;
    function comb(n,k) {
        if (k<0||k>n) return 0n;
        return fact[n]*invFact[k]%MOD*invFact[n-k]%MOD;
