    const right = nums.slice(mid);

    // generate all subset sums for a half
    function genSums(arr) {
        const m = arr.length;
        const total = 1 << m;
        const sums = new Array(total);
        for (let mask = 0; mask < total; mask++) {
            let s = 0;
            for (let i = 0; i < m; i++) {
                if (mask & (1 << i)) s += arr[i];
            }
            sums[mask] = s;
        }
        return sums;
    }

    const leftSums = genSums(left);
    const rightSums = genSums(right);
    rightSums.sort((a, b) => a - b); // prepare for binary search

    let best = Infinity;

    // binary search helper: returns index of first element >= target
    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    for (const s1 of leftSums) {
        const need = goal - s1;                     // MAIN LOGIC: target sum from right half
        const idx = lowerBound(rightSums, need);    // MAIN LOGIC: closest position in sorted right sums

        // check candidate at idx
        if (idx < rightSums.length) {
            const cur = Math.abs(s1 + rightSums[idx] - goal);
            if (cur < best) best = cur;
        }
        // check candidate just before idx
        if (idx > 0) {
            const cur = Math.abs(s1 + rightSums[idx - 1] - goal);
            if (cur < best) best = cur;
        }
        // early exit if perfect match found
        if (best === 0) return 0;
    }

    return best;
}

