function closestDessertCost(baseCosts, toppingCosts, target) {
  // generate all possible topping totals (each topping can be used 0, 1, or 2 times)
  const toppingSums = [];
  function dfs(i, cur) {
    if (i === toppingCosts.length) {
      toppingSums.push(cur);
      return;
    }
    // try 0, 1, 2 of the current topping
    for (let cnt = 0; cnt < 3; cnt++) {
      dfs(i + 1, cur + cnt * toppingCosts[i]);
    }
  }
  dfs(0, 0);

  let best = Infinity; // placeholder for the answer

  // evaluate every combination of base + topping sum
  for (const base of baseCosts) {
    for (const top of toppingSums) {
      const total = base + top;
      const diff = Math.abs(total - target);
      const bestDiff = Math.abs(best - target);
      // choose closer total, break ties by smaller total
      if (diff < bestDiff || (diff === bestDiff && total < best)) {
        best = total;
      }
    }
  }
  return best;
}

function carFleetII(cars) {
    const n = cars.length;
    const answer = new Array(n).fill(-1);
    const stack = []; // indices of cars ahead that are potential collision targets

    for (let i = n - 1; i >= 0; i--) {
        const [posI, speedI] = cars[i];

        // Remove cars that i cannot collide with or would collide after they have already collided
        while (stack.length) {
            const j = stack[stack.length - 1];
            const [posJ, speedJ] = cars[j];

            if (speedI <= speedJ) { // i is slower or same speed, never catches j
                stack.pop();
                continue;
            }

            const collideTime = (posJ - posI) / (speedI - speedJ);

            // If j never collides or i catches j before j's own collision, keep j
            if (answer[j] === -1 || collideTime <= answer[j]) break;

            // Otherwise j will have merged before i can catch it
            stack.pop();
        }

        if (stack.length) {
            const j = stack[stack.length - 1];
            const [posJ, speedJ] = cars[j];
            answer[i] = (posJ - posI) / (speedI - speedJ);
        }

        stack.push(i);
    }

    return answer;
}

function minOperations(nums1, nums2) {
    // 1. compute sums
    let sum1 = 0, sum2 = 0;
    for (let v of nums1) sum1 += v;
    for (let v of nums2) sum2 += v;

    if (sum1 === sum2) return 0;                 // already equal

    // 2. make sum1 the smaller one
    if (sum1 > sum2) {
        [nums1, nums2] = [nums2, nums1];
        [sum1, sum2] = [sum2, sum1];
    }

    let diff = sum2 - sum1;                      // positive difference to close

    // 3. count possible gains (0..5, we ignore 0)
    const cnt = new Array(6).fill(0);
    for (let v of nums1) cnt[6 - v]++;           // increase possibilities
    for (let v of nums2) cnt[v - 1]++;           // decrease possibilities

    // 4. greedy use of biggest gains first
    let ops = 0;
    for (let g = 5; g >= 1 && diff > 0; g--) {
        if (cnt[g] === 0) continue;
        const need = Math.ceil(diff / g);        // how many of this gain we would need
        const use = Math.min(cnt[g], need);
        diff -= use * g;
        ops += use;
    }

    return diff > 0 ? -1 : ops;                  // -1 if impossible, else answer
}

function minElements(nums, limit, goal) {
