var countRestrictedPaths = function(n, edges) {
    const MOD = 1000000007;
    const adj = Array.from({length:n+1}, () => []);
    for (const [u,v,w] of edges) {
        adj[u].push([v,w]);
        adj[v].push([u,w]);
    }
    const dist = new Array(n+1).fill(Infinity);
    dist[n] = 0;
    let heap = [[0,n]];
    while (heap.length) {
        heap.sort((a,b)=>a[0]-b[0]);
        const cur = heap.shift();
        const d = cur[0], u = cur[1];
        if (d !== dist[u]) continue;
        for (const [v,w] of adj[u]) {
            const nd = d+w;
            if (nd < dist[v]) {
                dist[v] = nd;
                heap.push([nd,v]);
            }
        }
    }
    const memo = new Map();
    function dfs(u) {
        if (u === n) return 1;
        if (memo.has(u)) return memo.get(u);
        let total = 0;
        for (const pair of adj[u]) {
            const v = pair[0];
            if (dist[v] < dist[u]) total = (total + dfs(v)) % MOD;
        }
        memo.set(u, total);
        return total;
    }
    return dfs(1);
