function minOperationsXorSegments(nums, k) {
    const n = nums.length;
    const L = k; // period must be k (not k+1) - consecutive length-k windows force nums[i]===nums[i+k]
    const groups = Array.from({ length: L }, () => []);
    for (let i = 0; i < n; i++) groups[i % L].push(nums[i]);

    const MAX_XOR = 1 << 10;
    const NEG = -1e9;
    let dpPrev = new Int32Array(MAX_XOR).fill(NEG);
    dpPrev[0] = 0;

    for (let g = 0; g < L; g++) {
        const freq = new Map();
        for (const v of groups[g]) freq.set(v, (freq.get(v) || 0) + 1);

        let maxPrev = NEG;
        for (let x = 0; x < MAX_XOR; x++) if (dpPrev[x] > maxPrev) maxPrev = dpPrev[x];

        // option: discard this whole group's original values, freely pick any xor contribution at cost 0 kept
        const dpNext = new Int32Array(MAX_XOR).fill(maxPrev);
        for (const [v, c] of freq.entries()) {
            for (let xorPrev = 0; xorPrev < MAX_XOR; xorPrev++) {
                const cand = dpPrev[xorPrev] + c;
                const newXor = xorPrev ^ v;
                if (cand > dpNext[newXor]) dpNext[newXor] = cand;
            }
        }
        dpPrev = dpNext;
    }
    const kept = dpPrev[0];
    return n - kept;
