function maxAverageRatio(classes, extraStudents) {
    // ---------- max‑heap implementation ----------
    class MaxHeap {
        constructor() { this.data = []; }
        size() { return this.data.length; }
        // compare by gain (larger first)
        _greater(i, j) { return this.data[i][0] > this.data[j][0]; }
        push(item) {
            const a = this.data;
            a.push(item);
            let idx = a.length - 1;
            while (idx > 0) {
                const parent = (idx - 1) >> 1;
                if (!this._greater(idx, parent)) break;
                [a[idx], a[parent]] = [a[parent], a[idx]];
                idx = parent;
            }
        }
        pop() {
            const a = this.data;
            if (a.length === 0) return null;
            const top = a[0];
            const last = a.pop();
            if (a.length) {
                a[0] = last;
                let idx = 0;
                while (true) {
                    let left = idx * 2 + 1;
                    let right = left + 1;
                    let largest = idx;
                    if (left < a.length && this._greater(left, largest)) largest = left;
                    if (right < a.length && this._greater(right, largest)) largest = right;
                    if (largest === idx) break;
                    [a[idx], a[largest]] = [a[largest], a[idx]];
                    idx = largest;
                }
            }
            return top;
        }
    }

    // ---------- helper to compute gain ----------
    function gain(p, t) {
        return (p + 1) / (t + 1) - p / t;
    }

    const heap = new MaxHeap();

    // initialise heap with each class's current gain
    for (const [p, t] of classes) {
        heap.push([gain(p, t), p, t]);
    }

    // assign each extra student to the class with maximal gain
    while (extraStudents-- > 0) {
        const [_, p, t] = heap.pop();          // pop class with biggest gain
        const newP = p + 1;
        const newT = t + 1;
        heap.push([gain(newP, newT), newP, newT]); // push updated class back
    }

    // compute final average ratio
    let sum = 0;
    while (heap.size()) {
        const [, p, t] = heap.pop();
        sum += p / t;
    }
    return sum / classes.length;
}

function canMakeEqualByOneSwap(s1, s2) {
    // If strings are already equal, no swap is needed
    if (s1 === s2) return true;

    const n = s1.length;
