                amount -= matched;
                sell.amount -= matched;
                if (sell.amount === 0) heapPop(sellHeap, sellCmp);
            }
            if (amount > 0) heapPush(buyHeap, {price, amount}, buyCmp);
        } else {                              // SELL
            while (amount > 0 && heapSize(buyHeap) && heapPeek(buyHeap).price >= price) {
                const buy = heapPeek(buyHeap);
                const matched = Math.min(amount, buy.amount);
                amount -= matched;
                buy.amount -= matched;
                if (buy.amount === 0) heapPop(buyHeap, buyCmp);
            }
            if (amount > 0) heapPush(sellHeap, {price, amount}, sellCmp);
        }
    }

    // ---------- sum remaining orders ----------
    let total = 0;
    for (const node of buyHeap) total = (total + node.amount) % MOD;
    for (const node of sellHeap) total = (total + node.amount) % MOD;
    return total;
}

function maxValue(n, index, maxSum) {
    function sumSide(peak, len) {
        if (len === 0) return 0n;
        const P = BigInt(peak), L = BigInt(len);
        if (peak - 1 >= len) {
            const hi = P-1n, lo = P-L;
            return (hi+lo)*L/2n;
        } else {
            const cnt = P-1n;
            const s = cnt*(cnt+1n)/2n;
            return s + (L - cnt);
        }
    }
    let lo = 1, hi = maxSum, ans = 1;
    while (lo <= hi) {
        const mid = Math.floor((lo+hi)/2);
        const total = BigInt(mid) + sumSide(mid, index) + sumSide(mid, n-index-1);
        if (total <= BigInt(maxSum)) { ans = mid; lo = mid+1; } else hi = mid-1;
    }
    return ans;
}

function maxAscendingSum(nums) {
    if (!nums || nums.length === 0) return 0;   // handle empty input

    let maxSum = nums[0];   // best sum found so far
    let curSum = nums[0];   // sum of the current ascending subarray

    for (let i = 1; i < nums.length; i++) {
        if (nums[i] > nums[i - 1]) {          // continue ascending sequence
            curSum += nums[i];
        } else {                              // start a new subarray
            curSum = nums[i];
        }
        if (curSum > maxSum) maxSum = curSum; // update answer
    }

    return maxSum;
}

function numberOfDifferentIntegers(word) {
    const unique = new Set();          // store normalized integers
    let num = "";                      // current consecutive digits

    for (let i = 0; i < word.length; i++) {
        const ch = word[i];
        if (ch >= '0' && ch <= '9') {  // building a number
            num += ch;
        } else if (num.length) {      // delimiter reached, process the number
            let norm = num.replace(/^0+/, ''); // remove leading zeros
            if (norm === '') norm = '0';        // all zeros case
            unique.add(norm);
            num = "";
        }
    }

    // handle possible trailing number
    if (num.length) {
        let norm = num.replace(/^0+/, '');
        if (norm === '') norm = '0';
        unique.add(norm);
    }

    return unique.size;
}

function countPairs(nums, low, high) {
  let maxVal = Math.max(...nums, high);
  let maxBit = 0;
  while ((1 << maxBit) <= maxVal) maxBit++;
  maxBit--;

  function newNode() { return { cnt: 0, child: [null, null] }; }

  function query(root, num, K) {
    if (K < 0) return 0;
    let node = root;
    let total = 0;
    for (let i = maxBit; i >= 0; i--) {
      if (!node) return total;
      const bitNum = (num >> i) & 1;
      const bitK = (K >> i) & 1;
      if (bitK === 1) {
        if (node.child[bitNum]) total += node.child[bitNum].cnt;
        node = node.child[1 - bitNum];
      } else {
        node = node.child[bitNum];
      }
    }
    // reached the end while exactly tracking K's bits the whole way - those
    // numbers give xor === K exactly, which IS <= K and must be counted too
    if (node) total += node.cnt;
    return total;
  }

  function insert(root, num) {
    let node = root;
    for (let i = maxBit; i >= 0; i--) {
      const bit = (num >> i) & 1;
      if (!node.child[bit]) node.child[bit] = newNode();
      node = node.child[bit];
      node.cnt++;
    }
  }

  function countLessOrEqual(bound) {
    const root = newNode(); // fresh trie for each independent pass
    let ans = 0;
    for (const num of nums) {
      ans += query(root, num, bound);
      insert(root, num);
    }
    return ans;
  }

  return countLessOrEqual(high) - countLessOrEqual(low - 1);
}

function reinitializePermutation(n) {
    let steps = 0;
    let pos = 1;                     // start from index 1 (0 and n‑1 are fixed)

    do {
        // apply one operation to the current index
        if (pos % 2 === 0) {
            pos = pos / 2;
        } else {
            pos = n / 2 + (pos - 1) / 2;
        }
        steps++;
    } while (pos !== 1);            // stop when we are back at the start

    return steps;
}

function maxNiceDivisors(primeFactors) {
    const MOD = 1000000007n;
    function modpow(b, e) {
        b = BigInt(b) % MOD;
        let res = 1n;
        while (e > 0) {
            if (e & 1) res = (res * b) % MOD;
            b = (b * b) % MOD;
            e = Math.floor(e / 2);
        }
        return res;
    }
    if (primeFactors <= 3) return primeFactors;
    const q = Math.floor(primeFactors / 3);
    const r = primeFactors % 3;
    let ans;
    if (r === 0) ans = modpow(3, q);
    else if (r === 1) ans = (modpow(3, q - 1) * 4n) % MOD;
    else ans = (modpow(3, q) * 2n) % MOD;
    return Number(ans);
}

function areSentencesSimilar(sentence1, sentence2) {
    const words1 = sentence1.split(' ');
    const words2 = sentence2.split(' ');
    const n1 = words1.length, n2 = words2.length;
    const minLen = Math.min(n1, n2);

    let left = 0;
    // match common prefix
    while (left < minLen && words1[left] === words2[left]) {
        left++;
    }

    let right = 0;
    // match common suffix
    while (right < minLen && words1[n1 - 1 - right] === words2[n2 - 1 - right]) {
        right++;
    }

    // if the whole shorter sentence is covered by prefix+suffix, insertion works
    return left + right >= minLen;
}

function determineColor(coordinates) {
    // Convert column letter to a number (a -> 1, b -> 2, ..., h -> 8)
    const col = coordinates.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
    // Convert row character to a number (character '1' -> 1, ..., '8' -> 8)
    const row = Number(coordinates[1]);

    // If the sum of column and row is odd the square is white, otherwise black
    return (col + row) % 2 === 1;
}

var maxHappyGroups = function(batchSize, groups) {
    let baseHappy = 0;
    const remainderCounts = new Array(batchSize).fill(0);
    for (const g of groups) {
        const r = g % batchSize;
        if (r === 0) baseHappy++;
        else remainderCounts[r]++;
    }
    const initialState = remainderCounts.slice(1);
    const memo = new Map();
    function dfs(state, curMod) {
        if (state.every(x => x === 0)) return 0;
        const key = state.join(',') + '|' + curMod;
        if (memo.has(key)) return memo.get(key);
        let best = 0;
        for (let r=1;r<batchSize;r++) {
            const idx = r-1;
            if (state[idx] === 0) continue;
            const newState = state.slice();
            newState[idx]--;
            const newMod = (curMod + r) % batchSize;
            const add = curMod === 0 ? 1 : 0;
            const val = add + dfs(newState, newMod);
            if (val > best) best = val;
        }
        memo.set(key, best);
        return best;
    }
    return baseHappy + dfs(initialState, 0);
};

function truncateSentence(s, k) {
    // split the sentence into words, keep only the first k, and join them back
    return s.split(' ').slice(0, k).join(' ');
}

function findingUsersActiveMinutes(logs, k) {
    const userMinutes = new Map();               // map userId → set of unique minutes

    for (const [id, minute] of logs) {           // collect minutes per user
        if (!userMinutes.has(id)) userMinutes.set(id, new Set());
        userMinutes.get(id).add(minute);
    }

    const answer = new Array(k).fill(0);         // answer[UAM‑1] = number of users with that UAM

    for (const minutesSet of userMinutes.values()) { // count users by their UAM
        const uam = minutesSet.size;
        if (uam >= 1 && uam <= k) answer[uam - 1]++; 
    }

    return answer;
}

function evaluateBracketPairs(s, knowledge) {
    // Build a map from key to its value for O(1) look‑ups
    const dict = {};
    for (let i = 0; i < knowledge.length; i++) {
        const [key, val] = knowledge[i];
        dict[key] = val;
    }

    const result = [];
    let i = 0;
    while (i < s.length) {
        if (s[i] === '(') {                     // start of a key
            i++;                                 // skip '('
            let key = '';
            while (i < s.length && s[i] !== ')') {
                key += s[i++];
            }
            i++;                                 // skip ')'
            result.push(dict.hasOwnProperty(key) ? dict[key] : '?');
        } else {
            result.push(s[i++]);                 // normal character
        }
    }
    return result.join('');
}

function minimumAbsoluteSumDifference(nums1, nums2) {
    const MOD = 1_000_000_007;
    const n = nums1.length;

    // sort a copy of nums1 for binary search
    const sortedVals = [...nums1].sort((a, b) => a - b);

    let originalSum = 0;
    let maxGain = 0;

    // binary search: first index with value >= target
    function lowerBound(arr, target) {
        let left = 0, right = arr.length;
        while (left < right) {
            const mid = (left + right) >> 1;
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    for (let i = 0; i < n; ++i) {
        const diff = Math.abs(nums1[i] - nums2[i]);
        originalSum = (originalSum + diff) % MOD;   // accumulate original sum

        const pos = lowerBound(sortedVals, nums2[i]); // find closest candidates

        let best = diff; // keep current diff as baseline
        if (pos < n) {
            const cand = Math.abs(sortedVals[pos] - nums2[i]);
            if (cand < best) best = cand;
        }
        if (pos > 0) {
            const cand = Math.abs(sortedVals[pos - 1] - nums2[i]);
            if (cand < best) best = cand;
        }

        const gain = diff - best;
        if (gain > maxGain) maxGain = gain;
    }

    return (originalSum - maxGain + MOD) % MOD;
}

function countNicePairs(nums) {
    const MOD = 1_000_000_007;
    // helper: reverse digits of a non‑negative integer
    function rev(x) {
        // turn into string, reverse, back to number
        return Number(String(x).split('').reverse().join(''));
    }

    const freq = Object.create(null);   // map diff -> count
    for (let i = 0; i < nums.length; i++) {
        const diff = nums[i] - rev(nums[i]);   // main logic: group by this value
        freq[diff] = (freq[diff] || 0) + 1;
    }

    let ans = 0;
    for (const key in freq) {
        const cnt = freq[key];
        if (cnt > 1) {
            // add combinations cnt choose 2, modulo MOD
            ans = (ans + (cnt * (cnt - 1) / 2) % MOD) % MOD;
        }
    }
    return ans;
}

function minSideJumps(obstacles) {
    const n = obstacles.length - 1;
    const INF = 1e9;
    let dp = [1, 0, 1];

    for (let i = 1; i <= n; i++) {
        const blocked = obstacles[i] - 1;
        const before = dp.slice(); // snapshot before this position's updates - avoids chaining multiple jumps into one step
        const next = before.slice();
        if (blocked >= 0) next[blocked] = INF;

        for (let lane = 0; lane < 3; lane++) {
            if (lane === blocked) continue;
            let bestOther = INF;
            for (let other = 0; other < 3; other++) {
                // the source lane for a jump must ALSO be unblocked at this exact position
                if (other !== lane && other !== blocked && before[other] < bestOther) bestOther = before[other];
            }
            next[lane] = Math.min(next[lane], 1 + bestOther);
        }
        dp = next;
    }
    return Math.min(dp[0], dp[1], dp[2]);
}

function countDifferentSubsequenceGCDs(nums) {
  const maxVal = Math.max(...nums);
  const present = new Array(maxVal + 1).fill(false);
  for (const x of nums) present[x] = true;
  function gcd(a,b){ while(b){[a,b]=[b,a%b];} return a; }
  let count = 0;
  for (let g = 1; g <= maxVal; g++) {
    let cur = 0;
    for (let m = g; m <= maxVal; m += g) {
      if (present[m]) {
        cur = cur === 0 ? m : gcd(cur, m);
        if (cur === g) break;
      }
    }
    if (cur === g) count++;
  }
  return count;
}

function arraySign(nums) {
    let negativeCount = 0;                     // count of negative numbers
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 0) return 0;           // product is zero if any element is zero
        if (nums[i] < 0) negativeCount++;      // track sign changes
    }
    return (negativeCount % 2 === 0) ? 1 : -1; // even negatives → positive, odd → negative
}

function findTheWinner(n, k) {
    // iterative Josephus formula
    let winner = 0;                     // position for i = 1 (0‑based)
    for (let i = 1; i <= n; i++) {
        winner = (winner + k) % i;      // update for current circle size
    }
    return winner + 1;                  // convert to 1‑based indexing
}

function minOperations(nums) {
    let operations = 0;
    let prev = nums[0];                 // keep the last value that is already strictly increasing

    for (let i = 1; i < nums.length; i++) {
        if (nums[i] <= prev) {          // current element breaks the increasing order
            const needed = prev + 1 - nums[i];
            operations += needed;       // add the increments we must perform
            prev = prev + 1;            // update to the new value after increments
        } else {
            prev = nums[i];              // no change needed, move forward
        }
    }
    return operations;
}

function numberOfPointsInsideCircles(points, queries) {
    const result = [];
    for (const [cx, cy, r] of queries) {
        const rSq = r * r;
        let cnt = 0;
        for (const [x, y] of points) {
            const dx = x - cx, dy = y - cy;
            if (dx * dx + dy * dy <= rSq) cnt++;
        }
        result.push(cnt);
    }
    return result;
}

function makeStringSorted(s) {
    const MOD = 1000000007n;
    const n = s.length;
    const fact = new Array(n+1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = (fact[i-1]*BigInt(i))%MOD;
    function modpow(base, exp, mod) {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp&1n) result=(result*base)%mod; base=(base*base)%mod; exp>>=1n; }
        return result;
    }
    const invFact = new Array(n+1).fill(1n);
    invFact[n] = modpow(fact[n], MOD-2n, MOD);
    for (let i = n; i > 0; i--) invFact[i-1] = (invFact[i]*BigInt(i))%MOD;
    const cnt = new Array(26).fill(0);
    for (const ch of s) cnt[ch.charCodeAt(0)-97]++;
    let denominator = 1n;
    for (const c of cnt) denominator = denominator * invFact[c] % MOD;
    let ans = 0n;
    for (let i = 0; i < n; i++) {
        const idx = s.charCodeAt(i)-97;
        const rem = n - i - 1;
        const base = fact[rem] * denominator % MOD;
        let less = 0n;
        for (let j = 0; j < idx; j++) less += BigInt(cnt[j]);
        ans = (ans + less * base) % MOD;
        const curCnt = cnt[idx];
        denominator = denominator * fact[curCnt] % MOD;
        denominator = denominator * invFact[curCnt-1] % MOD;
        cnt[idx]--;
    }
    return Number(ans % MOD);
}

function mkAverage(m, k) {
    const window = [];
    const maxSize = m;
    const kk = k;
    return {
        addElement: function (num) {
            window.push(num);
            if (window.length > maxSize) {
                window.shift();
            }
        },
        calculateMKAverage: function () {
            if (window.length < maxSize) {
                return -1;
            }
            const sorted = [...window].sort((a, b) => a - b);
            const start = kk;
            const end = maxSize - kk;
            let sum = 0;
            for (let i = start; i < end; i++) {
                sum += sorted[i];
            }
            return Math.floor(sum / (maxSize - 2 * kk));
        }
    };
}

function getMaximumXor(nums, maximumBit) {
    const mask = (1 << maximumBit) - 1;
    let totalXor = 0;
    for (const v of nums) totalXor ^= v;
    const n = nums.length;
    const answer = new Array(n);
    for (let i = 0; i < n; i++) {
        answer[i] = mask ^ totalXor;
        totalXor ^= nums[n - 1 - i];
    }
    return answer;
}

function checkPangram(sentence) {
    const uniqueLetters = new Set();               // collect distinct characters
    for (let i = 0; i < sentence.length; i++) {
        uniqueLetters.add(sentence[i]);             // add each letter to the set
        if (uniqueLetters.size === 26) break;      // early exit when all letters seen
    }
    return uniqueLetters.size === 26;
}

function maxIceCream(costs, coins) {
    // find the highest price to size the frequency array
    let maxCost = 0;
    for (let c of costs) {
        if (c > maxCost) maxCost = c;
    }

    // count how many bars have each price
    const freq = new Array(maxCost + 1).fill(0);
    for (let c of costs) {
        freq[c]++;
    }

    let bought = 0;
    let remaining = coins;

    // buy cheapest bars first using the frequency table
    for (let price = 1; price <= maxCost && remaining >= price; price++) {
        if (freq[price] === 0) continue;
        const affordable = Math.floor(remaining / price);
        const take = Math.min(freq[price], affordable);
        bought += take;
        remaining -= take * price;
    }

    return bought;
}

function xorAndSum(arr1, arr2) {
  // compute XOR of all elements in arr1
  let xor1 = 0;
  for (let v of arr1) xor1 ^= v;

  // compute XOR of all elements in arr2
  let xor2 = 0;
  for (let v of arr2) xor2 ^= v;

  // result bit k is 1 iff both xor1 and xor2 have bit k = 1
  return xor1 & xor2;
}

function getOrder(tasks) {
    // attach original indices
    const tasksWithIdx = tasks.map((t, i) => [t[0], t[1], i]);
    // sort by enqueue time
    tasksWithIdx.sort((a, b) => a[0] - b[0]);

    const heap = [];                     // min‑heap by [processingTime, index]
    const compare = (a, b) => {
        if (a[0] !== b[0]) return a[0] - b[0];
        return a[1] - b[1];
    };
    const heapPush = (node) => {
        heap.push(node);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (compare(heap[p], heap[i]) <= 0) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const heapPop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < heap.length && compare(heap[l], heap[smallest]) < 0) smallest = l;
                if (r < heap.length && compare(heap[r], heap[smallest]) < 0) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    };

    const result = [];
    let time = 0, i = 0, n = tasksWithIdx.length;

    while (result.length < n) {
        // enqueue all tasks that have arrived by current time
        while (i < n && tasksWithIdx[i][0] <= time) {
            heapPush([tasksWithIdx[i][1], tasksWithIdx[i][2]]);
            i++;
        }
        if (heap.length) {
            const [proc, idx] = heapPop();   // pick shortest processing time (tie → smallest index)
            time += proc;
            result.push(idx);
        } else {
            // CPU idle, jump to next task's enqueue time
            time = tasksWithIdx[i][0];
        }
    }
    return result;
}

function maxFrequency(nums, k) {
    // sort to bring equalizable numbers together
    nums.sort((a, b) => a - b);

    let left = 0;          // start of sliding window
    let windowSum = 0;     // sum of elements inside the window
    let best = 1;          // best frequency found

    for (let right = 0; right < nums.length; right++) {
        windowSum += nums[right];   // extend window to the right

        // shrink window until we can raise all its elements to nums[right] within k ops
        while (nums[right] * (right - left + 1) - windowSum > k) {
            windowSum -= nums[left];
            left++;
        }

        // update answer with current window size
        best = Math.max(best, right - left + 1);
    }

    return best;
}

function maximumBuildingHeight(n, restrictions) {
    // add the implicit restriction for building 1
    restrictions.push([1, 0]);
    // sort by building index
    restrictions.sort((a, b) => a[0] - b[0]);

    // forward pass: enforce that we cannot jump more than 1 per step
    for (let i = 1; i < restrictions.length; i++) {
        const dist = restrictions[i][0] - restrictions[i - 1][0];
        const allowed = restrictions[i - 1][1] + dist;
        if (restrictions[i][1] > allowed) {
            restrictions[i][1] = allowed;
        }
    }

    // backward pass: same constraint from right to left
    for (let i = restrictions.length - 2; i >= 0; i--) {
        const dist = restrictions[i + 1][0] - restrictions[i][0];
        const allowed = restrictions[i + 1][1] + dist;
        if (restrictions[i][1] > allowed) {
            restrictions[i][1] = allowed;
        }
    }

    let answer = 0;

    // evaluate each interval between consecutive restrictions
    for (let i = 0; i < restrictions.length - 1; i++) {
        const leftIdx = restrictions[i][0];
        const leftH = restrictions[i][1];
        const rightIdx = restrictions[i + 1][0];
        const rightH = restrictions[i + 1][1];
        const d = rightIdx - leftIdx;
        const diff = Math.abs(leftH - rightH);
        // highest possible building inside the interval
        const localMax = Math.max(leftH, rightH) + Math.floor((d - diff) / 2);
        if (localMax > answer) answer = localMax;
    }

    // consider the tail after the last restriction up to building n
    const lastIdx = restrictions[restrictions.length - 1][0];
    const lastH = restrictions[restrictions.length - 1][1];
    const tailMax = lastH + (n - lastIdx);
    if (tailMax > answer) answer = tailMax;

    return answer;
}

function sumDigitsInBaseK(n, k) {
    // handle zero explicitly
    if (n === 0) return 0;

    let sum = 0;
    // repeatedly extract the least‑significant digit in base k
    while (n > 0) {
        sum += n % k;   // add current digit
        n = Math.floor(n / k); // move to next higher digit
    }
    return sum;
}

function longestBeautifulSubstring(word) {
    const vowels = ['a', 'e', 'i', 'o', 'u'];   // order of stages
    let maxLen = 0;        // best length found
    let curLen = 0;        // length of current candidate
    let stage = -1;        // -1 = not started, 0..4 = a..u

    for (let i = 0; i < word.length; i++) {
        const ch = word[i];

        if (stage >= 0 && ch === vowels[stage]) {
            // same vowel as current stage → keep extending
            curLen++;
        } else if (stage + 1 < 5 && ch === vowels[stage + 1]) {
            // next vowel in order → move to next stage and extend
            stage++;
            curLen++;
        } else {
            // order broken – can only restart if we see an 'a'
            if (ch === 'a') {
                stage = 0;
                curLen = 1;
            } else {
