    const qs = queries.map((v, i) => [v, i]);
    qs.sort((a, b) => a[0] - b[0]);

    const res = new Array(queries.length).fill(-1);
    const heap = [];

    // heap helpers (min‑heap by interval size)
    const push = (node) => {
        heap.push(node);
        let cur = heap.length - 1;
        while (cur > 0) {
            const parent = (cur - 1) >> 1;
            if (heap[parent].size <= heap[cur].size) break;
            [heap[parent], heap[cur]] = [heap[cur], heap[parent]];
            cur = parent;
        }
    };
    const pop = () => {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let cur = 0;
            while (true) {
                let left = cur * 2 + 1;
                let right = left + 1;
                if (left >= heap.length) break;
                let smallest = left;
                if (right < heap.length && heap[right].size < heap[left].size) smallest = right;
                if (heap[cur].size <= heap[smallest].size) break;
                [heap[cur], heap[smallest]] = [heap[smallest], heap[cur]];
                cur = smallest;
            }
        }
        return top;
    };
    const peek = () => heap[0];

    let i = 0; // index over intervals

    // process queries in increasing order
    for (const [q, idx] of qs) {
