function maxSumMinProduct(nums) {
    const n = nums.length;
    const MOD = 1000000007n;

    // prefix sums as BigInt
    const prefix = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + BigInt(nums[i]);
    }

    const left = new Array(n);
    const right = new Array(n);
    const stack = [];

    // previous smaller element for each position
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) {
            stack.pop();
        }
        left[i] = stack.length ? stack[stack.length - 1] : -1;
        stack.push(i);
    }

    stack.length = 0; // reuse stack

    // next smaller element for each position
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) {
            stack.pop();
        }
        right[i] = stack.length ? stack[stack.length - 1] : n;
        stack.push(i);
    }

    let maxProd = 0n;

    // evaluate product for each element as the minimum of its maximal subarray
    for (let i = 0; i < n; i++) {
        const l = left[i];
        const r = right[i];
