    // 1️⃣ Let stones fall to the right inside each row
    for (let i = 0; i < m; i++) {
        let emptyPos = n - 1;                     // rightmost free cell
        for (let j = n - 1; j >= 0; j--) {
            const cell = boxGrid[i][j];
            if (cell === '*') {
                emptyPos = j - 1;                 // obstacle blocks further fall
            } else if (cell === '#') {
                if (emptyPos !== j) {              // move stone if needed
                    boxGrid[i][emptyPos] = '#';
                    boxGrid[i][j] = '.';
                }
                emptyPos--;                        // next stone lands left of this one
            }
        }
    }

    // 2️⃣ Rotate the settled box clockwise
    const rotated = Array.from({ length: n }, () => Array(m));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
