function sumOfFlooredPairs(nums) {
    // ---------- build frequency ----------
    let maxVal = 0;
    for (const v of nums) if (v > maxVal) maxVal = v;

    const cnt = new Array(maxVal + 1).fill(0);
    for (const v of nums) cnt[v]++;

