    // determine if an alternating string is possible
    if (Math.abs(zeros - ones) > 1) return -1;
    if (n % 2 === 0 && zeros !== ones) return -1; // even length must be balanced

    // count mismatches for both possible patterns
    let mismatchesStart0 = 0; // pattern: 0,1,0,1,...
    let mismatchesStart1 = 0; // pattern: 1,0,1,0,...

    for (let i = 0; i < n; i++) {
        const expected0 = (i % 2 === 0) ? '0' : '1';
        const expected1 = (i % 2 === 0) ? '1' : '0';
        if (s[i] !== expected0) mismatchesStart0++;
        if (s[i] !== expected1) mismatchesStart1++;
