    if (hour <= n - 1) return -1;

    const MAX_SPEED = 1e7; // guaranteed upper bound

    // binary search for the smallest feasible speed
    let low = 1, high = MAX_SPEED;
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (isFeasible(mid)) {
            high = mid;               // try smaller speeds
        } else {
            low = mid + 1;            // need larger speed
        }
    }
    return isFeasible(low) ? low : -1;

    // checks whether speed v lets us arrive within 'hour'
    function isFeasible(v) {
        let total = 0;
        for (let i = 0; i < n - 1; i++) {
