function getBiggestThree(grid) {
    if (!grid.length || !grid[0].length) return [];
    const m = grid.length, n = grid[0].length;
    const diag1 = Array.from({length:m}, () => new Array(n).fill(0));
    const diag2 = Array.from({length:m}, () => new Array(n).fill(0));
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            diag1[i][j] = grid[i][j] + ((i>0&&j>0) ? diag1[i-1][j-1] : 0);
            diag2[i][j] = grid[i][j] + ((i>0&&j+1<n) ? diag2[i-1][j+1] : 0);
        }
    }
    const sums = new Set();
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const maxK = Math.min(Math.floor((m-1-i)/2), j, n-1-j);
            for (let k = 0; k <= maxK; k++) {
                if (k === 0) { sums.add(grid[i][j]); continue; }
                const e1 = diag1[i+k][j+k] - ((i>0&&j>0) ? diag1[i-1][j-1] : 0);
                let sub = (i+k-1>=0 && j+k+1<n) ? diag2[i+k-1][j+k+1] : 0;
                const e2 = diag2[i+2*k][j] - sub;
                sub = (i+k-1>=0 && j-k-1>=0) ? diag1[i+k-1][j-k-1] : 0;
                const e3 = diag1[i+2*k][j] - sub;
                sub = (i-1>=0 && j+1<n) ? diag2[i-1][j+1] : 0;
                const e4 = diag2[i+k][j-k] - sub;
                const total = e1+e2+e3+e4 - (grid[i][j] + grid[i+k][j+k] + grid[i+2*k][j] + grid[i+k][j-k]);
