        pref[i] = pref[i - 1] + stones[i];
    }
    const dp = new Array(n);
    dp[n - 1] = 0;
    let maxVal = -Infinity;
    for (let i = n - 2; i >= 0; i--) {
        maxVal = Math.max(maxVal, pref[i + 1] - dp[i + 1]);
        dp[i] = maxVal;
    }
    return dp[0];
}

function maxValue(n, x) {
  const neg = n[0] === '-';
  const digits = neg ? n.slice(1) : n;
  let idx = digits.length;
  for (let i = 0; i < digits.length; i++) {
    const d = Number(digits[i]);
    if ((!neg && d < x) || (neg && d > x)) { idx = i; break; }
  }
  const result = digits.slice(0, idx) + String(x) + digits.slice(idx);
  return neg ? '-' + result : result;
}

function minPairSum(nums) {
    // sort the array to enable optimal pairing
    nums.sort((a, b) => a - b);

    let left = 0;                     // start of the array
    let right = nums.length - 1;      // end of the array
    let maxSum = 0;

    // pair smallest with largest, move pointers inward
    while (left < right) {
        const pairSum = nums[left] + nums[right];
        if (pairSum > maxSum) maxSum = pairSum;
        left++;
        right--;
    }

    return maxSum;
}

function assignTasks(servers, tasks) {
    class MinHeap {
        constructor(compare) {
            this.data = [];
            this.compare = compare;
        }
        size() {
            return this.data.length;
        }
        peek() {
            return this.data[0];
        }
        push(item) {
            this.data.push(item);
            this._siftUp(this.data.length - 1);
        }
        pop() {
            if (this.data.length === 0) return undefined;
            const top = this.data[0];
            const last = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = last;
                this._siftDown(0);
            }
            return top;
        }
        _siftUp(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.compare(this.data[i], this.data[p]) < 0) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        _siftDown(i) {
            const n = this.data.length;
            while (true) {
                let l = i * 2 + 1;
                let r = i * 2 + 2;
                let smallest = i;
                if (l < n && this.compare(this.data[l], this.data[smallest]) < 0) smallest = l;
                if (r < n && this.compare(this.data[r], this.data[smallest]) < 0) smallest = r;
                if (smallest !== i) {
                    [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                    i = smallest;
                } else break;
            }
        }
    }

    const n = servers.length;
    const m = tasks.length;
    const ans = new Array(m);

    const freeHeap = new MinHeap((a, b) => {
        if (a.weight !== b.weight) return a.weight - b.weight;
        return a.index - b.index;
    });
    const busyHeap = new MinHeap((a, b) => {
        if (a.freeTime !== b.freeTime) return a.freeTime - b.freeTime;
        if (a.weight !== b.weight) return a.weight - b.weight;
        return a.index - b.index;
    });

    for (let i = 0; i < n; ++i) {
        freeHeap.push({ weight: servers[i], index: i });
    }

    const queue = [];
    let qHead = 0;
    let nextTask = 0;
    let cur = 0;
    let processed = 0;

    while (processed < m) {
        // add all tasks that have arrived by current time
        while (nextTask < m && nextTask <= cur) {
            queue.push(nextTask);
            nextTask++;
        }

        // move servers that have become free by current time to freeHeap
        while (busyHeap.size() && busyHeap.peek().freeTime <= cur) {
            const srv = busyHeap.pop();
            freeHeap.push({ weight: srv.weight, index: srv.index });
        }

        // assign tasks while possible
        while (freeHeap.size() && qHead < queue.length) {
            const taskIdx = queue[qHead++];
            const srv = freeHeap.pop();
            ans[taskIdx] = srv.index;
            processed++;
            busyHeap.push({
                freeTime: cur + tasks[taskIdx],
                weight: srv.weight,
                index: srv.index
            });
        }

        if (qHead >= queue.length) {
            // no waiting tasks
            if (nextTask < m) {
                cur = nextTask; // jump to next arrival time
            } else {
                break;
            }
        } else {
            // tasks waiting but no free server
            cur = busyHeap.peek().freeTime;
        }
    }

    return ans;
}
// TIME: O((n+m) log n) SPACE: O(n+m)

function minSkips(dist, speed, hoursBefore) {
    const n = dist.length;
    const INF = Infinity;
    // dp[skips] = minimal time*speed (integer) after processing some roads, using 'skips' skips
    const EPS = 1e-9;
    let dp = new Array(n+1).fill(INF);
    dp[0] = 0;
    for (let i = 0; i < n; i++) {
        const ndp = new Array(n+1).fill(INF);
        for (let s = 0; s <= i; s++) {
            if (dp[s] === INF) continue;
            // don't skip: round up to next integer
            const notSkip = Math.ceil((dp[s] + dist[i]) / speed - EPS) * speed;
            if (notSkip < ndp[s]) ndp[s] = notSkip;
            // skip
            if (s+1 <= n) {
                const skip = dp[s] + dist[i];
                if (skip < ndp[s+1]) ndp[s+1] = skip;
            }
        }
        dp = ndp;
    }
    for (let s = 0; s <= n; s++) {
        if (dp[s] <= hoursBefore * speed + EPS) return s;
    }
    return -1;
}

function minimumXORSum(nums1, nums2) {
    const n = nums1.length;
    const totalMask = 1 << n;
    const dp = new Array(totalMask).fill(Infinity);
    dp[0] = 0;

    // helper to count set bits
    const popcount = (x) => {
        let cnt = 0;
        while (x) {
            x &= x - 1;
            cnt++;
        }
        return cnt;
    };

    for (let mask = 1; mask < totalMask; mask++) {
        const i = popcount(mask) - 1;               // index in nums1 for this mask
        // try pairing nums1[i] with each chosen element in nums2
        for (let j = 0; j < n; j++) {
            if (mask & (1 << j)) {
                const prev = mask ^ (1 << j);
                const candidate = dp[prev] + (nums1[i] ^ nums2[j]);
                if (candidate < dp[mask]) dp[mask] = candidate;
            }
        }
    }
    return dp[totalMask - 1];
}

