function minWastedSpace(packages, boxes) {
    const MOD = 1_000_000_007;

    // sort packages and build prefix sums
    packages.sort((a, b) => a - b);
    const n = packages.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + packages[i];
    }

    // helper: first index > target (upper bound)
    function upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    let best = Infinity;

    for (const supplier of boxes) {
        // sort box sizes for this supplier
        supplier.sort((a, b) => a - b);
        // if the largest box cannot hold the largest package, this supplier is useless
        if (supplier[supplier.length - 1] < packages[n - 1]) continue;

        let waste = 0;
        let prevIdx = 0; // packages already assigned

        // iterate over box sizes, assigning as many packages as possible to each size
        for (const size of supplier) {
            const idx = upperBound(packages, size); // first package too big for this box
            const cnt = idx - prevIdx;               // how many packages fit in this size
            if (cnt > 0) {
                // total waste contributed by these packages
                waste += size * cnt - (prefix[idx] - prefix[prevIdx]);
            }
            prevIdx = idx;
            if (prevIdx === n) break; // all packages placed
        }

        if (prevIdx === n) {
            best = Math.min(best, waste);
        }
    }

    return best === Infinity ? -1 : best % MOD;
}

function twoEggDrop(n) {
