    }

    // helper: rotate a matrix 90° clockwise
    function rotate(a) {
        const res = Array.from({ length: n }, () => Array(n));
        for (let i = 0; i < n; i++) {
            for (let j = 0; j < n; j++) {
                res[j][n - 1 - i] = a[i][j];
