    let ops = 0;
    let processed = 0;
    let prev = null;
    for (let i = nums.length - 1; i >= 0; i--) {
        if (prev === null) {
            prev = nums[i];
            processed = 1;
        } else if (nums[i] === prev) {
            processed++;
        } else {
            ops += processed;
            prev = nums[i];
            processed++;
        }
    }
    return ops;
}

function isCovered(ranges, left, right) {
    // find the farthest point we need to handle
    let maxCoord = right;
    for (const [s, e] of ranges) {
        if (e > maxCoord) maxCoord = e;
    }

    const diff = new Array(maxCoord + 2).fill(0);
    // mark starts and ends (+1 at start, -1 after end)
    for (const [s, e] of ranges) {
        diff[s] += 1;
        diff[e + 1] -= 1;
    }

    // sweep with prefix sum and check every integer in [left, right]
    let cur = 0;
    for (let i = 0; i <= maxCoord; i++) {
        cur += diff[i];
        if (i >= left && i <= right && cur === 0) {
            return false;
        }
    }
    return true;
}

function findStudent(chalk, k) {
    const n = chalk.length;
    const prefix = new Array(n);
    let total = 0;
    for (let i = 0; i < n; i++) {
        total += chalk[i];
        prefix[i] = total;               // build prefix sums
    }

    k = k % total;                       // reduce k to a single cycle

    // binary search for the first prefix sum greater than k
    let left = 0, right = n - 1;
    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        if (prefix[mid] > k) {
            right = mid;
        } else {
            left = mid + 1;
        }
    }
    return left;                         // index of the student who cannot get chalk
}

function largestMagicSquare(grid) {
    const m = grid.length, n = grid[0].length;
    const rowPrefix = Array.from({length:m}, () => new Array(n+1).fill(0));
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) rowPrefix[i][j+1] = rowPrefix[i][j] + grid[i][j];
    const colPrefix = Array.from({length:m+1}, () => new Array(n).fill(0));
    for (let j = 0; j < n; j++) for (let i = 0; i < m; i++) colPrefix[i+1][j] = colPrefix[i][j] + grid[i][j];

    const maxK = Math.min(m,n);
    for (let k = maxK; k > 0; k--) {
        for (let i = 0; i <= m-k; i++) {
            for (let j = 0; j <= n-k; j++) {
                const target = rowPrefix[i][j+k] - rowPrefix[i][j];
                let ok = true;
                for (let r = i; r < i+k; r++) if (rowPrefix[r][j+k]-rowPrefix[r][j] !== target) { ok=false; break; }
                if (!ok) continue;
                for (let c = j; c < j+k; c++) if (colPrefix[i+k][c]-colPrefix[i][c] !== target) { ok=false; break; }
                if (!ok) continue;
                let diagSum = 0;
                for (let d = 0; d < k; d++) diagSum += grid[i+d][j+d];
                if (diagSum !== target) continue;
                let antiSum = 0;
                for (let d = 0; d < k; d++) antiSum += grid[i+d][j+k-1-d];
                if (antiSum !== target) continue;
                return k;
            }
        }
    }
    return 1;
}

function mergeTriplets(triplets, target) {
    const [x, y, z] = target;
    let haveX = false, haveY = false, haveZ = false;

    for (const [a, b, c] of triplets) {
        // only use triplets that are not larger than the target in any coordinate
        if (a <= x && b <= y && c <= z) {
            if (a === x) haveX = true;   // can provide the required x
            if (b === y) haveY = true;   // can provide the required y
            if (c === z) haveZ = true;   // can provide the required z
        }
    }
    return haveX && haveY && haveZ;
}

function canMakeEqual(words) {
    const n = words.length;
