    // count total characters and frequency of each character
    for (let w of words) {
        totalLength += w.length;
        for (let ch of w) {
            freq[ch] = (freq[ch] || 0) + 1;
        }
    }

    // each string must end up with the same length
    if (totalLength % n !== 0) return false;

    // each character count must be divisible by n
    for (let count of Object.values(freq)) {
        if (count % n !== 0) return false;
    }

    return true;
}

function maximumRemovals(s, p, removable) {
    const n = s.length;

    // helper: can p still be a subsequence after removing first k indices?
    function canRemove(k) {
        const deleted = new Array(n).fill(false);
        for (let i = 0; i < k; i++) {
            deleted[removable[i]] = true;          // mark deletions
        }

        let j = 0;                                 // pointer in p
        for (let i = 0; i < n && j < p.length; i++) {
            if (!deleted[i] && s[i] === p[j]) {    // match current char
                j++;
            }
        }
        return j === p.length;                     // all of p matched?
    }

    let low = 0, high = removable.length, ans = 0;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        if (canRemove(mid)) {                      // main logic: binary search step
            ans = mid;
            low = mid + 1;                         // try to delete more
        } else {
            high = mid - 1;                        // delete fewer characters
        }
    }
    return ans;
}

function minOperationsToFlip(expression) {
  // stack of [cost0, cost1, opCharCode] ; opCharCode 0 means "no operator set yet"
  const stack = [[0, 0, 0]];
  function reduce() {
    const r = stack.pop();
    const l = stack.pop();
    const op = l[2];
    let result;
    if (op === '&'.charCodeAt(0)) {
      const c0 = Math.min(l[0], r[0]);
      const c1 = Math.min(l[1] + r[1], Math.min(l[1], r[1]) + 1);
      result = [c0, c1, 0];
    } else if (op === '|'.charCodeAt(0)) {
      const c0 = Math.min(l[0] + r[0], Math.min(l[0], r[0]) + 1);
      const c1 = Math.min(l[1], r[1]);
      result = [c0, c1, 0];
    } else {
      result = [r[0], r[1], 0];
    }
    stack.push(result);
  }
  for (const ch of expression) {
    if (ch === '(') {
      stack.push([0, 0, 0]);
    } else if (ch === '&' || ch === '|') {
      stack[stack.length - 1][2] = ch.charCodeAt(0);
    } else {
      if (ch === '0' || ch === '1') {
        const cost0 = ch === '1' ? 1 : 0;
        const cost1 = ch === '0' ? 1 : 0;
        stack.push([cost0, cost1, 0]);
      }
      reduce();
    }
  }
  const top = stack[stack.length - 1];
  return Math.max(top[0], top[1]);
}

function largestOddNumberInString(num) {
