function numberOfFullRounds(loginTime, logoutTime) {
    // convert "HH:MM" to minutes since midnight
    function toMinutes(t) {
        const [h, m] = t.split(':').map(Number);
        return h * 60 + m;
    }

    let start = toMinutes(loginTime);
    let end   = toMinutes(logoutTime);

    // handle crossing midnight
    if (end < start) end += 24 * 60;

    // first round that can be fully played
    const roundStart = Math.ceil(start / 15) * 15;   // MAIN LOGIC
    // last round that can be fully played
    const roundEnd   = Math.floor(end / 15) * 15;    // MAIN LOGIC

    if (roundStart >= roundEnd) return 0;            // MAIN LOGIC
    return (roundEnd - roundStart) / 15;            // MAIN LOGIC
}

function minimumAbsoluteDifferenceQueries(nums, queries) {
    const result = new Array(queries.length);
    for (let qi = 0; qi < queries.length; ++qi) {
        const [l, r] = queries[qi];
        const sub = nums.slice(l, r + 1);
        sub.sort((a, b) => a - b);
        let minDiff = Infinity;
        for (let i = 1; i < sub.length; ++i) {
            if (sub[i] === sub[i - 1]) continue; // a duplicate just contributes nothing - it doesn't disqualify the range
            const diff = sub[i] - sub[i - 1];
            if (diff < minDiff) minDiff = diff;
        }
        // -1 only when there is no pair of DIFFERENT values at all (every element identical)
        result[qi] = (minDiff === Infinity) ? -1 : minDiff;
    }
    return result;
}

function earliestAndLatestRound(n, firstPlayer, secondPlayer) {
    let A = Math.min(firstPlayer, secondPlayer);
    let B = Math.max(firstPlayer, secondPlayer);
    const memo = new Map();

    function solve(n, a, b) {
        if (a + b === n + 1) return [1, 1];
        const key = n + ',' + a + ',' + b;
        if (memo.has(key)) return memo.get(key);

        const half = Math.floor(n / 2);
        const hasBye = n % 2 === 1;
        const byePos = hasBye ? (n + 1) / 2 : -1;

        // pairs not involving a or b - either player in each can win, we try all combinations
        const freePairs = [];
        for (let i = 1; i <= half; i++) {
            const j = n + 1 - i;
            if (i === a || i === b || j === a || j === b) continue;
            freePairs.push([i, j]);
        }
        const k = freePairs.length;
        let earliest = Infinity, latest = -Infinity;

        for (let mask = 0; mask < (1 << k); mask++) {
            const survivors = [a, b];
            if (hasBye && byePos !== a && byePos !== b) survivors.push(byePos);
            for (let idx = 0; idx < k; idx++) {
                const [p, q] = freePairs[idx];
                survivors.push((mask & (1 << idx)) ? p : q);
            }
            survivors.sort((x, y) => x - y);
            const newA = survivors.indexOf(a) + 1;
            const newB = survivors.indexOf(b) + 1;
            const [e, l] = solve(survivors.length, newA, newB);
            if (e + 1 < earliest) earliest = e + 1;
            if (l + 1 > latest) latest = l + 1;
        }
        const res = [earliest, latest];
        memo.set(key, res);
        return res;
    }

    return solve(n, A, B);
}

function findPeakGrid(mat) {
    const m = mat.length;
    const n = mat[0].length;
    let left = 0, right = n - 1;

    while (left <= right) {
        const mid = Math.floor((left + right) / 2);          // binary‑search column

        // find the row with the maximum value in column mid
        let maxRow = 0;
        for (let i = 1; i < m; i++) {
            if (mat[i][mid] > mat[maxRow][mid]) maxRow = i;
        }

        const leftVal  = (mid > 0) ? mat[maxRow][mid - 1] : -1;   // neighbour values
        const rightVal = (mid < n - 1) ? mat[maxRow][mid + 1] : -1;

        if (mat[maxRow][mid] > leftVal && mat[maxRow][mid] > rightVal) {
            return [maxRow, mid];                                 // peak found
        }

        // move to the side that has the larger neighbour
        if (leftVal > mat[maxRow][mid]) {
            right = mid - 1;
        } else {
            left = mid + 1;
        }
    }
}

function maxAlternatingSum(nums) {
    // E: best sum for a subsequence with an EVEN chosen-count so far (or empty) - ends on a SUBTRACT (or nothing)
    // O: best sum for a subsequence with an ODD chosen-count so far - ends on an ADD
    let E = 0, O = -Infinity;
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        // extending an even-count subsequence by one element makes it odd-count,
        // and that new element is at an ODD position (1st, 3rd, ...) - it gets ADDED
        const newO = Math.max(O, E + x);
        // extending an odd-count subsequence by one makes it even-count,
        // and that new element is at an EVEN position (2nd, 4th, ...) - it gets SUBTRACTED
        const newE = Math.max(E, O - x);
        O = newO;
        E = newE;
    }
    // the optimal subsequence can end on either parity
    return Math.max(E, O);
}

function countSubIslands(grid1, grid2) {
    const rows = grid1.length;
