    let subIslandCount = 0;

    // explore one island in grid2 and determine if it is a sub‑island
    function dfs(r, c) {
        // out of bounds or water in grid2
        if (r < 0 || r >= rows || c < 0 || c >= cols || grid2[r][c] === 0) return true;

        // mark visited
        grid2[r][c] = 0;

        // if the corresponding cell in grid1 is water, this island cannot be a sub‑island
        let isSub = grid1[r][c] === 1;

        // explore four directions, combine results with logical AND
        const up    = dfs(r - 1, c);
        const down  = dfs(r + 1, c);
        const left  = dfs(r, c - 1);
        const right = dfs(r, c + 1);

        return isSub && up && down && left && right;
    }

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid2[r][c] === 1) {               // start of a new island in grid2
                if (dfs(r, c)) subIslandCount++;   // whole island is a sub‑island
            }
        }
    }

    return subIslandCount;
}

function maxProductDifference(nums) {
    // sort numbers to easily pick the two largest and two smallest values
    nums.sort((a, b) => a - b);

    const n = nums.length;
    const smallestProduct = nums[0] * nums[1];          // product of two smallest
    const largestProduct = nums[n - 1] * nums[n - 2];   // product of two largest

    return largestProduct - smallestProduct;
}

function removeOccurrences(s, part) {
    const stack = [];                     // build result incrementally
    const m = part.length;

    for (let i = 0; i < s.length; i++) {
        stack.push(s[i]);                  // add current character

        // if the tail could match `part`, verify and remove it
        if (stack.length >= m) {
            let match = true;
            for (let j = 0; j < m; j++) {
                if (stack[stack.length - m + j] !== part[j]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                for (let j = 0; j < m; j++) stack.pop(); // delete the substring
            }
        }
    }
    return stack.join('');
}

function canBeIncreasing(nums) {
    let violationIdx = -1;               // index where the first non‑increasing pair appears
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] <= nums[i - 1]) {
            if (violationIdx !== -1) return false; // more than one violation
            violationIdx = i;
        }
    }
    if (violationIdx === -1) return true; // already strictly increasing

    const i = violationIdx;
    // try removing nums[i-1] or nums[i]
    const canRemovePrev = i === 1 || nums[i] > nums[i - 2];
    const canRemoveCurr = i === nums.length - 1 || nums[i + 1] > nums[i - 1];
    return canRemovePrev || canRemoveCurr;
}

function rotateGrid(grid, k) {
    const m = grid.length;
    const n = grid[0].length;
    const layers = Math.min(m, n) / 2;

    for (let layer = 0; layer < layers; layer++) {
        const top = layer,
              bottom = m - 1 - layer,
              left = layer,
              right = n - 1 - layer;

        // collect the current layer in clockwise order
        const elems = [];

        // top row (left → right)
        for (let c = left; c <= right; c++) elems.push(grid[top][c]);

        // right column (top+1 → bottom)
        for (let r = top + 1; r <= bottom; r++) elems.push(grid[r][right]);

        // bottom row (right-1 → left) if bottom > top
        for (let c = right - 1; c >= left; c--) elems.push(grid[bottom][c]);

        // left column (bottom-1 → top+1) if left < right
        for (let r = bottom - 1; r > top; r--) elems.push(grid[r][left]);

        const len = elems.length;
        const rot = k % len;               // effective rotations
        // rotate left by rot positions (counter‑clockwise shift)
        const rotated = elems.slice(rot).concat(elems.slice(0, rot));

        // write the rotated values back in the same order
        let idx = 0;

        for (let c = left; c <= right; c++) grid[top][c] = rotated[idx++];
        for (let r = top + 1; r <= bottom; r++) grid[r][right] = rotated[idx++];
        for (let c = right - 1; c >= left; c--) grid[bottom][c] = rotated[idx++];
        for (let r = bottom - 1; r > top; r--) grid[r][left] = rotated[idx++];
    }

    return grid;
}

function Heap(compare) { this.data = []; this.cmp = compare; }
Heap.prototype.peek = function () { return this.data[0]; };
Heap.prototype.push = function (x) {
    const a = this.data, cmp = this.cmp;
    a.push(x);
    let i = a.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (cmp(a[p], a[i]) <= 0) break;
        [a[p], a[i]] = [a[i], a[p]];
        i = p;
    }
};
Heap.prototype.pop = function () {
    const a = this.data, cmp = this.cmp;
    if (a.length === 0) return undefined;
    const root = a[0];
    const last = a.pop();
    if (a.length) {
        a[0] = last;
        let i = 0;
        while (true) {
            let l = i * 2 + 1, r = l + 1, smallest = i;
            if (l < a.length && cmp(a[l], a[smallest]) < 0) smallest = l;
            if (r < a.length && cmp(a[r], a[smallest]) < 0) smallest = r;
            if (smallest === i) break;
            [a[i], a[smallest]] = [a[smallest], a[i]];
            i = smallest;
        }
    }
    return root;
};

function MovieRentingSystem(n, entries) {
    const priceMap = new Map();
    const available = new Map();
    const compAvail = (a, b) => a.price !== b.price ? a.price - b.price : a.shop - b.shop;
    const compRent = (a, b) => a.price !== b.price ? a.price - b.price : (a.shop !== b.shop ? a.shop - b.shop : a.movie - b.movie);
    const rentedHeap = new Heap(compRent);
    const rentedSet = new Set();

    function key(shop, movie) { return shop + '#' + movie; }

    for (const [shop, movie, price] of entries) {
        const k = key(shop, movie);
        priceMap.set(k, price);
        if (!available.has(movie)) available.set(movie, new Heap(compAvail));
        available.get(movie).push({ price, shop, movie });
    }

    return {
        search(movie) {
            const heap = available.get(movie) || new Heap(compAvail);
            const tmp = [];
            const ans = [];
            while (ans.length < 5 && heap.data.length) {
                const top = heap.peek();
                if (rentedSet.has(key(top.shop, top.movie))) { heap.pop(); continue; }
                ans.push(top.shop);
                heap.pop();
                tmp.push(top);
            }
            for (const e of tmp) heap.push(e);
            return ans;
        },
        rent(shop, movie) {
            const k = key(shop, movie);
            rentedSet.add(k);
            const price = priceMap.get(k);
            rentedHeap.push({ price, shop, movie });
        },
        drop(shop, movie) {
            const k = key(shop, movie);
            rentedSet.delete(k);
            const price = priceMap.get(k);
            if (!available.has(movie)) available.set(movie, new Heap(compAvail));
            available.get(movie).push({ price, shop, movie });
        },
        report() {
            const tmp = [];
            const ans = [];
            while (ans.length < 5 && rentedHeap.data.length) {
                const top = rentedHeap.peek();
                if (!rentedSet.has(key(top.shop, top.movie))) { rentedHeap.pop(); continue; }
                ans.push([top.shop, top.movie]);
                rentedHeap.pop();
                tmp.push(top);
            }
            for (const e of tmp) rentedHeap.push(e);
            return ans;
        }
    };
}

function eliminateMaximum(dist, speed) {
    const n = dist.length;
    // use REAL division, not floor - floor division loses precision and creates
    // false ties between monsters that actually arrive at different real times
    const arrival = dist.map((d, i) => d / speed[i]).sort((a, b) => a - b);
    let time = 0;
    for (let i = 0; i < n; i++) {
        if (arrival[i] <= time) return i;
        time++;
    }
    return n;
}

function waysToBuildRooms(prevRoom) {
    const MOD = 1000000007n;
    const n = prevRoom.length;
    const children = Array.from({length:n}, () => []);
    for (let i = 1; i < n; i++) children[prevRoom[i]].push(i);
    const fact = new Array(n+1).fill(1n);
    for (let i = 1; i <= n; i++) fact[i] = (fact[i-1]*BigInt(i))%MOD;
    function modpow(base,exp,mod) { base%=mod; let r=1n; while(exp>0n){ if(exp&1n) r=(r*base)%mod; base=(base*base)%mod; exp>>=1n;} return r; }
    const invFact = new Array(n+1).fill(1n);
    invFact[n] = modpow(fact[n], MOD-2n, MOD);
    for (let i = n; i > 0; i--) invFact[i-1] = (invFact[i]*BigInt(i))%MOD;
    function dfs(u) {
        let totalSize = 1n, ways = 1n;
        const childSizes = [];
        for (const v of children[u]) {
            const [sz, w] = dfs(v);
            childSizes.push(sz);
            totalSize += sz;
            ways = ways * w % MOD;
        }
        const sumChild = totalSize - 1n;
        let coeff = fact[Number(sumChild)];
        for (const sz of childSizes) coeff = coeff * invFact[Number(sz)] % MOD;
        ways = ways * coeff % MOD;
        return [totalSize, ways];
    }
    return Number(dfs(0)[1] % MOD);
}

function wonderfulSubstrings(word) {
    const MAX_MASK = 1 << 10;          // 1024 possible masks
    const cnt = new Array(MAX_MASK).fill(0);
    cnt[0] = 1;                        // empty prefix

    let mask = 0;
    let answer = 0;

    for (let i = 0; i < word.length; i++) {
        const bit = word.charCodeAt(i) - 97;   // 'a' -> 0, ..., 'j' -> 9
        mask ^= (1 << bit);                    // flip parity of current letter

        answer += cnt[mask];                    // substrings with 0 odd letters
        for (let b = 0; b < 10; b++) {         // substrings with exactly 1 odd letter
            answer += cnt[mask ^ (1 << b)];
        }

        cnt[mask]++;                            // record this prefix mask
    }

    return answer;
}

function buildArray(nums) {
    const n = nums.length;
    const ans = new Array(n);
    for (let i = 0; i < n; i++) {
        // compute ans[i] using the permutation definition
        ans[i] = nums[nums[i]];
    }
    return ans;
}

function longestCommonSubpath(n, paths) {
    const m = paths.length;
    const minLen = Math.min(...paths.map(p=>p.length));
    const MOD = 1000000007n;
    const BASE = BigInt(n + 7);
    function hashesOfLength(arr, L) {
        const set = new Set();
        if (arr.length < L) return set;
        let h = 0n, power = 1n;
        for (let i = 0; i < L; i++) { h = (h*BASE + BigInt(arr[i])) % MOD; if (i>0) power = (power*BASE)%MOD; }
        set.add(h.toString());
        for (let i = L; i < arr.length; i++) {
            h = (h - BigInt(arr[i-L])*power % MOD + MOD*MOD) % MOD;
            h = (h*BASE + BigInt(arr[i])) % MOD;
            set.add(h.toString());
        }
        return set;
    }
    function feasible(L) {
        if (L === 0) return true;
        let common = hashesOfLength(paths[0], L);
        for (let i = 1; i < m; i++) {
            const s = hashesOfLength(paths[i], L);
            const next = new Set();
            for (const h of common) if (s.has(h)) next.add(h);
            common = next;
            if (common.size === 0) return false;
        }
        return common.size > 0;
    }
    let lo = 0, hi = minLen, ans = 0;
    while (lo <= hi) {
        const mid = Math.floor((lo+hi)/2);
        if (feasible(mid)) { ans = mid; lo = mid+1; } else hi = mid-1;
    }
    return ans;
}

function countSquareSumTriples(n) {
    let count = 0;
    for (let c = 1; c <= n; c++) {                     // iterate possible hypotenuse
        const c2 = c * c;
        for (let a = 1; a <= n; a++) {                 // iterate possible leg a
            const a2 = a * a;
            if (a2 >= c2) break;                       // a must be smaller than c
            const b2 = c2 - a2;                        // required b²
            const b = Math.floor(Math.sqrt(b2));       // integer candidate for b
            if (b * b === b2 && b >= 1 && b <= n) {    // check perfect square & bounds
                count++;                               // (a,b,c) is a valid ordered triple
            }
        }
    }
    return count;
}

function sumGame(num) {
    const n = num.length;
    const half = Math.floor(n/2);
    const left = num.slice(0, half);
    const right = num.slice(half);
    let leftSum=0, rightSum=0, leftQ=0, rightQ=0;
    for (const c of left) { if (c==='?') leftQ++; else leftSum += parseInt(c); }
    for (const c of right) { if (c==='?') rightQ++; else rightSum += parseInt(c); }
    const diff = leftSum - rightSum;
    const totalQ = leftQ + rightQ;
    if (totalQ % 2 === 1) return true;
    const needed = 9 * (rightQ - leftQ) / 2;
    return diff !== needed;
}

function countGoodNumbers(n) {
    const MOD = 1000000007n;                     // modulus as BigInt

    // number of even / odd positions (ceil / floor)
    const evenCnt = BigInt(Math.floor((n + 1) / 2));
    const oddCnt  = BigInt(Math.floor(n / 2));

    // fast exponentiation (binary) – returns (base^exp) % MOD
    function powMod(base, exp) {
        if (exp === 0n) return 1n;               // base case
        const half = powMod(base, exp / 2n);     // recursive call
        let res = (half * half) % MOD;           // square
        if (exp % 2n === 1n) {                   // if exponent is odd
            res = (res * base) % MOD;
        }
        return res;
    }

    const pow5 = powMod(5n, evenCnt);            // 5^evenCnt mod MOD
    const pow4 = powMod(4n, oddCnt);             // 4^oddCnt  mod MOD

    const ans = (pow5 * pow4) % MOD;             // combine the two parts
    return Number(ans);                          // safe, < MOD
}

function nearestExit(maze, entrance) {
    const rows = maze.length;
    const cols = maze[0].length;
    const [startRow, startCol] = entrance;

    const visited = Array.from({ length: rows }, () => Array(cols).fill(false));
    const queue = [];
    queue.push([startRow, startCol, 0]);
    visited[startRow][startCol] = true;

    const directions = [
        [-1, 0], // up
        [1, 0],  // down
        [0, -1], // left
        [0, 1]   // right
    ];

    while (queue.length) {
        const [r, c, dist] = queue.shift();

        // If this cell is on the border and not the entrance, we found the nearest exit
        if ((r === 0 || r === rows - 1 || c === 0 || c === cols - 1) && !(r === startRow && c === startCol)) {
            return dist;
        }

        for (const [dr, dc] of directions) {
            const nr = r + dr;
            const nc = c + dc;
            // stay inside the maze, avoid walls and already visited cells
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols &&
                maze[nr][nc] === '.' && !visited[nr][nc]) {
                visited[nr][nc] = true;
                queue.push([nr, nc, dist + 1]);
            }
        }
    }

    return -1; // no reachable exit
}

function getConcatenation(nums) {
    const n = nums.length;
    const ans = new Array(2 * n);
    for (let i = 0; i < n; i++) {
        ans[i] = nums[i];          // copy original element
        ans[i + n] = nums[i];      // copy it again at offset n
    }
    return ans;
}

function mergeBSTs(trees) {
    const rootMap = new Map();
    const leafVals = new Set();
    for (const t of trees) {
        rootMap.set(t.val, t);
        if (t.left) leafVals.add(t.left.val);
        if (t.right) leafVals.add(t.right.val);
    }
    const candidates = [...rootMap.keys()].filter(v => !leafVals.has(v));
    if (candidates.length !== 1) return null;
    let root = rootMap.get(candidates[0]);
    rootMap.delete(candidates[0]);

    function merge(node, low, high) {
        if (!node) return null;
        if (!(low < node.val && node.val < high)) throw new Error('invalid');
        if (node.left === null && node.right === null && rootMap.has(node.val)) {
            node = rootMap.get(node.val);
            rootMap.delete(node.val);
        }
        node.left = merge(node.left, low, node.val);
        node.right = merge(node.right, node.val, high);
        return node;
    }
    try {
        root = merge(root, -Infinity, Infinity);
    } catch (e) {
        return null;
    }
    if (rootMap.size > 0) return null;
    return root;
}

function minCost(maxTime, edges, passingFees) {
    const n = passingFees.length;

    // build adjacency list
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, t] of edges) {
        adj[u].push([v, t]);
        adj[v].push([u, t]);
    }

    const INF = Number.MAX_SAFE_INTEGER;
    // best[city][time] = cheapest cost known for that exact time
    const best = Array.from({ length: n }, () => Array(maxTime + 1).fill(INF));
    best[0][0] = passingFees[0];               // start fee

    // ----- priority queue (min‑heap) -----
    class MinHeap {
        constructor() { this.heap = []; }
        isEmpty() { return this.heap.length === 0; }
        push(item) {
            const h = this.heap;
            h.push(item);
            let i = h.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (h[p][0] <= h[i][0]) break;
                [h[p], h[i]] = [h[i], h[p]];
                i = p;
            }
        }
        pop() {
            const h = this.heap;
            const top = h[0];
            const last = h.pop();
            if (h.length) {
                h[0] = last;
                let i = 0;
                while (true) {
                    let l = i * 2 + 1, r = l + 1, smallest = i;
                    if (l < h.length && h[l][0] < h[smallest][0]) smallest = l;
                    if (r < h.length && h[r][0] < h[smallest][0]) smallest = r;
                    if (smallest === i) break;
                    [h[i], h[smallest]] = [h[smallest], h[i]];
                    i = smallest;
                }
            }
            return top;
        }
    }
    // ------------------------------------

    const heap = new MinHeap();
    heap.push([passingFees[0], 0, 0]); // [cost, city, time]

    while (!heap.isEmpty()) {
        const [cost, city, time] = heap.pop();

        // outdated entry?
        if (cost !== best[city][time]) continue;

        // reached destination with minimal possible cost
        if (city === n - 1) return cost;

        // relax all outgoing roads
        for (const [next, roadTime] of adj[city]) {
            const newTime = time + roadTime;
            if (newTime > maxTime) continue;               // time limit exceeded
            const newCost = cost + passingFees[next];
            if (newCost < best[next][newTime]) {
                best[next][newTime] = newCost;
                heap.push([newCost, next, newTime]);
            }
        }
    }

    // no feasible path – pick the cheapest among all allowed times
    let answer = INF;
    for (let t = 0; t <= maxTime; ++t) answer = Math.min(answer, best[n - 1][t]);
    return answer === INF ? -1 : answer;
}


