    }

    return best;
}

var waysToPartition = function(nums, k) {
    const n = nums.length;
    const pref = new Array(n).fill(0);
    let cur = 0;
    for (let i=0;i<n;i++) { cur += nums[i]; pref[i] = cur; }
    const total = pref[n-1];
    const twoPref = new Array(n-1).fill(0);
    for (let i=0;i<n-1;i++) twoPref[i] = 2*pref[i];
    const rightCounts = new Map();
    for (const val of twoPref) rightCounts.set(val, (rightCounts.get(val)||0)+1);
    const leftCounts = new Map();
    let ans = rightCounts.get(total) || 0;
    for (let j=0;j<n;j++) {
        const delta = k - nums[j];
        const totalPrime = total + delta;
        const leftContrib = leftCounts.get(totalPrime) || 0;
        const targetRight = total - delta;
        const rightContrib = rightCounts.get(targetRight) || 0;
        ans = Math.max(ans, leftContrib + rightContrib);
        if (j <= n-2) {
            const val = twoPref[j];
            const cnt = (rightCounts.get(val)||0) - 1;
            if (cnt) rightCounts.set(val, cnt);
            else rightCounts.delete(val);
            leftCounts.set(val, (leftCounts.get(val)||0)+1);
        }
    }
    return ans;
};

function countPairs(nums, target) {
