function StockPrice() {
    const priceMap = new Map();          // timestamp → latest price
    let latestTimestamp = 0;             // most recent timestamp seen

    const maxHeap = [];                  // stores [price, timestamp] for max query
    const minHeap = [];                  // stores [price, timestamp] for min query

    // ---------- heap helpers ----------
    function heapPush(heap, item, better) {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (better(heap[p], heap[i])) break;   // parent already better
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }

    function heapPop(heap, better) {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            heapifyDown(heap, 0, better);
        }
        return top;
    }

    function heapifyDown(heap, i, better) {
        const n = heap.length;
        while (true) {
            let left = i * 2 + 1,
                right = i * 2 + 2,
                best = i;
            if (left < n && !better(heap[best], heap[left])) best = left;
            if (right < n && !better(heap[best], heap[right])) best = right;
            if (best === i) break;
            [heap[i], heap[best]] = [heap[best], heap[i]];
            i = best;
        }
    }

    // ---------- lazy clean ----------
    function clean(heap, better) {
        while (heap.length) {
            const [price, ts] = heap[0];
            if (priceMap.get(ts) !== price) {   // stale entry
                heapPop(heap, better);
            } else break;
        }
    }

    // ---------- public API ----------
    return {
        update(timestamp, price) {
            priceMap.set(timestamp, price);
            if (timestamp >= latestTimestamp) latestTimestamp = timestamp; // keep newest
            heapPush(maxHeap, [price, timestamp], (a, b) => a[0] > b[0]); // max‑heap
            heapPush(minHeap, [price, timestamp], (a, b) => a[0] < b[0]); // min‑heap
        },

        current() {
            return priceMap.get(latestTimestamp);
        },

        maximum() {
            clean(maxHeap, (a, b) => a[0] > b[0]); // discard outdated tops
            return maxHeap[0][0];
        },

        minimum() {
            clean(minHeap, (a, b) => a[0] < b[0]); // discard outdated tops
            return minHeap[0][0];
        }
    };
}

