function smallestSubsequence(s, k, letter, repetition) {
    const n = s.length;
    const suffix = new Array(n+1).fill(0);
    for (let i = n-1; i >= 0; i--) suffix[i] = suffix[i+1] + (s[i]===letter?1:0);
    const stack = [];
    let usedLetter = 0;
    for (let i = 0; i < n; i++) {
        const c = s[i];
        while (stack.length) {
            const top = stack[stack.length-1];
            if (c < top) {
                const afterUsedLetter = usedLetter - (top===letter?1:0);
                if ((stack.length-1+(n-i) >= k) && (afterUsedLetter+suffix[i] >= repetition)) {
                    stack.pop();
                    usedLetter = afterUsedLetter;
                } else break;
            } else break;
        }
        if (stack.length < k) {
            if (c === letter) { stack.push(c); usedLetter++; }
            else {
                const needed = repetition - usedLetter;
                const slotsLeft = k - (stack.length+1);
                if (slotsLeft >= needed) stack.push(c);
            }
        }
    }
    return stack.join('');
}

