    // sort to obtain the median
    values.sort((a, b) => a - b);
    const median = values[Math.floor(values.length / 2)];

    let ops = 0;
    // check feasibility and accumulate operations
    for (let i = 0; i < grid.length; i++) {
        for (let j = 0; j < grid[0].length; j++) {
            const diff = grid[i][j] - median;
            if (diff % x !== 0) return -1;               // impossible
            ops += Math.abs(diff) / x;                    // operations for this cell
        }
    }
    return ops;
}



