    }

    // earliest finishing month for each course
    const finish = new Array(n);
    const queue = [];

    // initialise sources (no prerequisites)
    for (let i = 0; i < n; i++) {
        if (indeg[i] === 0) {
            finish[i] = time[i];   // can start at month 0
            queue.push(i);
        } else {
            finish[i] = 0;          // will be updated later
        }
    }

    // Kahn's algorithm
    while (queue.length) {
        const u = queue.shift();          // pop a source
        for (const v of adj[u]) {
            // update earliest finish of v using u as a predecessor
            const candidate = finish[u] + time[v];
            if (candidate > finish[v]) finish[v] = candidate;
            if (--indeg[v] === 0) queue.push(v); // v becomes a source
        }
    }

    // answer = maximum finishing month among all courses
    let answer = 0;
    for (let i = 0; i < n; i++) {
        if (finish[i] > answer) answer = finish[i];
    }
    return answer;
}

function countValidWords(sentence) {
    // split by spaces and ignore empty parts caused by multiple spaces
    const tokens = sentence.split(' ').filter(t => t.length > 0);
    let validCount = 0;

    for (const token of tokens) {
        if (isValid(token)) {
            validCount++;
        }
    }
    return validCount;
}

/* MAIN LOGIC: checks a single token against all validity rules */
function isValid(token) {
    let hyphenSeen = false;
    let punctSeen = false;

    for (let i = 0; i < token.length; i++) {
        const ch = token[i];

        // reject digits immediately
        if (ch >= '0' && ch <= '9') return false;

        // hyphen handling
        if (ch === '-') {
            if (hyphenSeen) return false;          // more than one hyphen
            hyphenSeen = true;
            if (i === 0 || i === token.length - 1) return false; // at ends
            if (!isLetter(token[i - 1]) || !isLetter(token[i + 1])) return false; // not surrounded by letters
            continue;
        }

        // punctuation handling
        if (ch === '!' || ch === '.' || ch === ',') {
            if (punctSeen) return false;           // more than one punctuation
            punctSeen = true;
            if (i !== token.length - 1) return false; // must be last character
            continue;
        }

        // any other non‑letter character is invalid
        if (!isLetter(ch)) return false;
    }
    return true;
}

/* helper: true for lowercase letters a‑z */
function isLetter(ch) {
    return ch >= 'a' && ch <= 'z';
}

function platesBetweenCandles(s, queries) {
    const n = s.length;
    const pref = new Array(n + 1).fill(0);          // plates prefix sum
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + (s[i] === '*' ? 1 : 0);
    }

    const leftCandle = new Array(n).fill(-1);       // nearest candle on the left (including self)
    let last = -1;
    for (let i = 0; i < n; i++) {
        if (s[i] === '|') last = i;
        leftCandle[i] = last;
    }

    const rightCandle = new Array(n).fill(-1);      // nearest candle on the right (including self)
    let next = -1;
    for (let i = n - 1; i >= 0; i--) {
        if (s[i] === '|') next = i;
        rightCandle[i] = next;
    }

    const ans = new Array(queries.length);
    for (let q = 0; q < queries.length; q++) {
        const [l, r] = queries[q];
        const left = rightCandle[l];                // first candle >= l
        const right = leftCandle[r];                // last candle <= r
        // if a valid candle pair exists, count plates between them
        ans[q] = (left !== -1 && right !== -1 && left < right)
            ? pref[right] - pref[left + 1]
            : 0;
    }
    return ans;
}

function kthDistinct(arr, k) {
    // Count how many times each string appears
    const freq = new Map();
    for (const s of arr) {
        freq.set(s, (freq.get(s) || 0) + 1);
    }

    // Scan in original order and pick the k‑th string with frequency 1
    let distinctSeen = 0;
    for (const s of arr) {
        if (freq.get(s) === 1) {
            distinctSeen++;
            if (distinctSeen === k) {
                return s;
            }
        }
    }
    return "";
}

function maxTwoEvents(events) {
    if (events.length === 0) return 0;

    // Sort events by their end time so we can use prefix maximums
    events.sort((a, b) => a[1] - b[1]);

    const n = events.length;
    const ends = new Array(n);
    const prefixMax = new Array(n);

    // Build arrays of end times and prefix maximum values
    for (let i = 0; i < n; i++) {
        ends[i] = events[i][1];
        const val = events[i][2];
        prefixMax[i] = i === 0 ? val : Math.max(prefixMax[i - 1], val);
    }

    let best = 0;

    // Iterate each event as the later one in a possible pair
    for (let i = 0; i < n; i++) {
        const [start, end, value] = events[i];
        best = Math.max(best, value); // case of taking only this event

        // Find the last event that ends before this one starts (end < start)
        let lo = 0, hi = i - 1, idx = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (ends[mid] < start) {
                idx = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        // Combine with the best earlier non‑overlapping event, if any
        if (idx !== -1) {
            best = Math.max(best, value + prefixMax[idx]);
        }
    }

    return best;
}

function countValidMoveCombinations(pieces, positions) {
    const n = pieces.length;
    const destLists = pieces.map((type, i) => {
        const r0 = positions[i][0];
        const c0 = positions[i][1];
        const list = [];
        for (let r = 1; r <= 8; r++) {
            for (let c = 1; c <= 8; c++) {
                const dr = r - r0;
                const dc = c - c0;
                const absDr = Math.abs(dr);
                const absDc = Math.abs(dc);
                let ok = false;
                if (type === "rook") {
                    ok = (r === r0 || c === c0);
                } else if (type === "bishop") {
                    ok = (absDr === absDc);
                } else { // queen
                    ok = (r === r0 || c === c0 || absDr === absDc);
                }
                if (ok) list.push([r, c]);
            }
        }
        return list;
    });

    let count = 0;
    const chosen = new Array(n);

    function dfs(idx) {
        if (idx === n) {
            if (isValid(chosen)) count++;
            return;
        }
        for (const dest of destLists[idx]) {
            chosen[idx] = dest;
            dfs(idx + 1);
        }
    }

    function isValid(destinations) {
        const paths = new Array(n);
        let maxLen = 0;
        for (let i = 0; i < n; i++) {
            const startR = positions[i][0];
            const startC = positions[i][1];
            const destR = destinations[i][0];
            const destC = destinations[i][1];
            const dr = Math.sign(destR - startR);
            const dc = Math.sign(destC - startC);
            const path = [];
            let r = startR, c = startC;
            path.push([r, c]);
            while (r !== destR || c !== destC) {
                r += dr;
                c += dc;
                path.push([r, c]);
            }
            paths[i] = path;
            if (path.length > maxLen) maxLen = path.length;
        }
        for (let t = 0; t < maxLen; t++) {
            const seen = new Set();
            for (let i = 0; i < n; i++) {
                const p = paths[i];
                const pos = t < p.length ? p[t] : p[p.length - 1];
                const key = pos[0] * 8 + pos[1];
                if (seen.has(key)) return false;
                seen.add(key);
            }
        }
        return true;
    }

    dfs(0);
    return count;
}

function possiblyEquals(s1, s2) {
    const n1 = s1.length, n2 = s2.length;
    const memo = new Map();
    const isAlpha = c => /[a-zA-Z]/.test(c);
    const isDigit = c => /[0-9]/.test(c);
    function dfs(i, j, diff) {
        if (i === n1 && j === n2) return diff === 0;
        const key = i+','+j+','+diff;
        if (memo.has(key)) return memo.get(key);
        let res = false;
        if (diff > 0) {
            if (j < n2 && isAlpha(s2[j])) res = dfs(i, j+1, diff-1);
            if (!res && j < n2 && isDigit(s2[j])) {
                let num = 0;
                for (let k = j; k < n2; k++) {
                    if (!isDigit(s2[k])) break;
                    num = num*10 + parseInt(s2[k]);
                    if (dfs(i, k+1, diff-num)) { res = true; break; }
                }
            }
        } else if (diff < 0) {
            if (i < n1 && isAlpha(s1[i])) res = dfs(i+1, j, diff+1);
            if (!res && i < n1 && isDigit(s1[i])) {
                let num = 0;
                for (let k = i; k < n1; k++) {
                    if (!isDigit(s1[k])) break;
                    num = num*10 + parseInt(s1[k]);
                    if (dfs(k+1, j, diff+num)) { res = true; break; }
                }
            }
        } else {
            if (i < n1 && j < n2 && isAlpha(s1[i]) && isAlpha(s2[j]) && s1[i]===s2[j]) {
                res = dfs(i+1, j+1, 0);
            }
            if (!res && i < n1 && isDigit(s1[i])) {
                let num = 0;
                for (let k = i; k < n1; k++) {
                    if (!isDigit(s1[k])) break;
                    num = num*10 + parseInt(s1[k]);
                    if (dfs(k+1, j, num)) { res = true; break; }
                }
            }
            if (!res && j < n2 && isDigit(s2[j])) {
                let num = 0;
                for (let k = j; k < n2; k++) {
                    if (!isDigit(s2[k])) break;
                    num = num*10 + parseInt(s2[k]);
                    if (dfs(i, k+1, -num)) { res = true; break; }
                }
            }
        }
        memo.set(key, res);
        return res;
    }
    return dfs(0,0,0);
}

function nodesBetweenCriticalPoints(head) {
    // indices of critical points and distances
    let firstIdx = -1;      // index of the first critical point found
    let prevIdx = -1;       // index of the previous critical point
    let lastIdx = -1;       // index of the last critical point found
    let minDist = Infinity; // smallest distance between two critical points

    let prev = null;
    let curr = head;
    let idx = 0;

    while (curr !== null) {
        const next = curr.next;

        // check if current node is a critical point (needs both neighbors)
        if (prev !== null && next !== null) {
            const isMax = curr.val > prev.val && curr.val > next.val;
            const isMin = curr.val < prev.val && curr.val < next.val;
            if (isMax || isMin) {
                if (firstIdx === -1) {
                    firstIdx = idx;               // first critical point
                } else {
                    minDist = Math.min(minDist, idx - prevIdx); // update min distance
                }
                prevIdx = idx;                    // update previous critical point
                lastIdx = idx;                    // update last critical point
            }
        }

        // advance pointers
        prev = curr;
        curr = next;
        idx++;
    }

    // not enough critical points
    if (firstIdx === -1 || firstIdx === lastIdx) {
        return [-1, -1];
    }

    const maxDist = lastIdx - firstIdx; // distance between first and last critical points
    return [minDist, maxDist];
}

function sumVowelsInAllSubstrings(word) {
    const n = word.length;
    let total = 0;
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);

    for (let i = 0; i < n; i++) {
        // add contribution only when the character is a vowel
        if (vowels.has(word[i])) {
            total += (i + 1) * (n - i);
        }
    }
    return total;
}

function maxPathQuality(values, edges, maxTime) {
    const n = values.length;
    const graph = Array.from({ length: n }, () => []);
    for (const [u, v, t] of edges) {
        graph[u].push([v, t]);
        graph[v].push([u, t]);
    }

    const visited = Array(n).fill(false);
    let best = 0;

    // depth‑first search with backtracking
    function dfs(node, timeLeft, quality) {
        if (node === 0) best = Math.max(best, quality);          // update answer when back at start
        for (const [next, cost] of graph[node]) {
            if (cost > timeLeft) continue;                       // cannot afford this edge
            if (!visited[next]) {                                // first time we visit this node
                visited[next] = true;
                dfs(next, timeLeft - cost, quality + values[next]);
                visited[next] = false;                           // backtrack
            } else {
                dfs(next, timeLeft - cost, quality);            // revisit without extra value
            }
        }
    }

    visited[0] = true;
    dfs(0, maxTime, values[0]);
    return best;
}

function smallestEqualIndex(nums) {
    // Scan indices in order to find the first match
    for (let i = 0; i < nums.length; i++) {
        if (i % 10 === nums[i]) { // check the required condition
            return i;               // smallest index found
        }
    }
    return -1; // no index satisfies the condition
}

function minimumOperations(nums, start, goal) {
    if (start === goal) return 0;
    const LOW = -1000, HIGH = 2000;
    const visited = new Set();
    visited.add(start);
    let queue = [start];
    let steps = 0;
    while (queue.length) {
        steps++;
        const nq = [];
        for (const x of queue) {
            for (const n of nums) {
                for (const val of [x+n, x-n, x^n]) {
                    if (val === goal) return steps;
                    if (val < 0 || val > 1000) continue;
                    if (!visited.has(val)) { visited.add(val); nq.push(val); }
                }
            }
        }
        queue = nq;
        if (queue.length === 0) return -1;
    }
    return -1;
}

function areAlmostEquivalent(word1, word2) {
    const diff = new Array(26).fill(0);          // frequency differences for each letter

    for (let i = 0; i < word1.length; i++) {
        diff[word1.charCodeAt(i) - 97]++;        // count letters from word1
        diff[word2.charCodeAt(i) - 97]--;        // subtract letters from word2
    }

    for (let i = 0; i < 26; i++) {
        if (Math.abs(diff[i]) > 3) return false; // any difference > 3 breaks the rule
    }
    return true;
}

function countVowelSubstrings(word) {
    const vowelSet = new Set(['a', 'e', 'i', 'o', 'u']);
    const n = word.length;
    let total = 0;
    let i = 0;

    // split the string into maximal vowel‑only blocks
    while (i < n) {
        if (!vowelSet.has(word[i])) {          // skip consonants
            i++;
            continue;
        }
        const blockStart = i;
        while (i < n && vowelSet.has(word[i])) i++; // find end of block
        const blockEnd = i;                     // exclusive

        total += countBlock(word, blockStart, blockEnd);
    }
    return total;
}

/* count substrings inside word[ l … r ) that consist only of vowels
   and contain all five different vowels */
function countBlock(s, l, r) {
    const freq = { a: 0, e: 0, i: 0, o: 0, u: 0 };
    let haveAll = 0;          // how many different vowels are present
    let left = l;
    let answer = 0;

    for (let right = l; right < r; right++) {
        const ch = s[right];
        if (freq[ch] === 0) haveAll++;   // first occurrence of this vowel
        freq[ch]++;

        // while the window already has the five vowels,
        // every extension to the right is a valid substring
        while (haveAll === 5) {
            answer += (r - right);        // all endings >= right are valid
            const leftChar = s[left];
            freq[leftChar]--;
            if (freq[leftChar] === 0) haveAll--; // lost a vowel
            left++;
        }
    }
    return answer;
}

function maxTaskAssign(tasks, workers, pills, strength) {
    tasks.sort((a, b) => a - b);
    workers.sort((a, b) => a - b);
    const n = tasks.length;
    const m = workers.length;
    let low = 0, high = Math.min(n, m);
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        if (canAssign(mid)) low = mid; else high = mid - 1;
    }
    return low;

    function canAssign(k) {
        let ptr = m - 1; // scans the top-k strongest workers from strongest downward
        const deque = []; // workers examined so far that are pill-boost-eligible for the current task
        let remainingPills = pills;
        for (let i = k - 1; i >= 0; i--) {
            const task = tasks[i];
            while (ptr >= m - k && workers[ptr] + strength >= task) {
                deque.push(ptr);
                ptr--;
            }
            if (deque.length === 0) return false;
            if (workers[deque[0]] >= task) {
                deque.shift(); // strongest eligible worker handles it without a pill
            } else {
                if (remainingPills === 0) return false;
                remainingPills--;
                deque.pop(); // use the weakest still-eligible worker's pill boost, saving the stronger ones
            }
        }
        return true;
    }
}

function robotSimulation(width, height) {
    // direction order matches a clockwise perimeter walk starting East from (0,0)
    const dx = [1, 0, -1, 0];   // East, North, West, South
    const dy = [0, 1, 0, -1];
    const dirName = ['East', 'North', 'West', 'South'];

    let x = 0, y = 0;
    let dirIdx = 0; // start facing East

    function move(num) {
        for (let i = 0; i < num; i++) {
            let nx = x + dx[dirIdx];
            let ny = y + dy[dirIdx];
            if (nx < 0 || nx >= width || ny < 0 || ny >= height) {
                dirIdx = (dirIdx + 1) % 4; // hit a wall, turn to keep walking the perimeter
                nx = x + dx[dirIdx];
                ny = y + dy[dirIdx];
            }
            x = nx;
            y = ny;
        }
    }

    function getPos() {
        return [x, y];
    }

    function getDir() {
        return dirName[dirIdx];
    }

    return { move, getPos, getDir };
}

function mostBeautifulItem(items, queries) {
    // sort items by price (ascending)
    items.sort((a, b) => a[0] - b[0]);

    const prices = [];
    const prefBeauty = [];
    let maxBeauty = 0;

    // build prefix maximum of beauty
    for (const [price, beauty] of items) {
        if (beauty > maxBeauty) maxBeauty = beauty;   // update running max
        prices.push(price);
        prefBeauty.push(maxBeauty);
    }

    const answers = [];

    // binary search helper: first index with value > target
    function upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // answer each query
    for (const q of queries) {
        const idx = upperBound(prices, q) - 1;   // last price ≤ q
        answers.push(idx >= 0 ? prefBeauty[idx] : 0);
    }

    return answers;
}

function minimizedMaximum(n, quantities) {
    let low = 1;
    let high = Math.max(...quantities); // the largest quantity is an upper bound

    while (low < high) {
        const mid = Math.floor((low + high) / 2);

        // MAIN LOGIC: compute how many stores are needed if the max per store is mid
        let required = 0;
        for (let i = 0; i < quantities.length; i++) {
            required += Math.ceil(quantities[i] / mid);
        }

        if (required <= n) {
            high = mid;          // mid works, try a smaller maximum
        } else {
            low = mid + 1;       // mid too small, need a larger maximum
        }
    }

    return low;
}

function timeRequiredToBuy(tickets, k) {
    const target = tickets[k];                 // tickets needed by person k
    let time = 0;
    for (let i = 0; i < tickets.length; i++) {
        if (i <= k) {
            // people before or at k get a chance each round until k finishes
            time += Math.min(tickets[i], target);
        } else {
            // people after k get one fewer chance because k leaves after its last ticket
            time += Math.min(tickets[i], target - 1);
        }
    }
    return time;
}

function reverseEvenLengthGroups(head) {
    // dummy node simplifies edge handling
    const dummy = { next: head };
    let prevGroupTail = dummy;   // tail of the previous processed group
    let cur = head;              // start of the current group
    let groupSize = 1;           // expected size of the next group

    while (cur) {
        // count actual nodes in this group and remember the last node
        let count = 0;
        let lastNode = null;
        let runner = cur;
        while (count < groupSize && runner) {
            lastNode = runner;
            runner = runner.next;
            count++;
        }
        const nextGroupHead = runner; // first node after the current group

        if (count % 2 === 0) { // even length → reverse this segment
            // reverse nodes between cur (inclusive) and nextGroupHead (exclusive)
            let prev = nextGroupHead;
            let node = cur;
            for (let i = 0; i < count; i++) {
                const nxt = node.next;
                node.next = prev;
                prev = node;
                node = nxt;
            }
            // reconnect reversed segment
            prevGroupTail.next = prev; // prev is new head of the reversed group
            prevGroupTail = cur;       // cur becomes the tail after reversal
        } else { // odd length → keep order, just move the tail pointer
            prevGroupTail = lastNode;
        }

        // advance to the next group
        cur = nextGroupHead;
        groupSize++;
    }

    return dummy.next;
}

function decodeSlantedCipher(encodedText, rows) {
    const n = encodedText.length;
    const cols = n / rows;
    const matrix = new Array(rows);
    let idx = 0;
    for (let i = 0; i < rows; i++) {
        matrix[i] = new Array(cols);
        for (let j = 0; j < cols; j++) {
            matrix[i][j] = encodedText[idx++];
        }
    }
    const result = [];
    // decode by walking a diagonal starting from each column j in row 0,
    // moving down-right (x++, y++) - this matches how the cipher was actually
    // read out to PRODUCE encodedText in the first place
    for (let j = 0; j < cols; j++) {
        let x = 0, y = j;
        while (x < rows && y < cols) {
            result.push(matrix[x][y]);
            x++; y++;
        }
    }
    while (result.length && result[result.length - 1] === ' ') result.pop();
    return result.join('');
}

function wateringPlants(plants, capacity) {
    let steps = 0;
    let position = -1; // start at the river
    let water = capacity;

    for (let i = 0; i < plants.length; i++) {
        if (water < plants[i]) {
            // go back to the river to refill
            steps += position + 1; // distance from current position to -1
            position = -1;
            water = capacity;
        }
        // walk forward to plant i
        steps += i - position;
        position = i;
        water -= plants[i];
    }
    return steps;
}

function processFriendRequests(n, restrictions, requests) {
    // ----- Union‑Find structure -----
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        if (parent[x] !== x) parent[x] = find(parent[x]); // path compression
        return parent[x];
    }

    function union(x, y) {
        const rx = find(x), ry = find(y);
        if (rx === ry) return;
        if (rank[rx] < rank[ry]) parent[rx] = ry;
        else if (rank[rx] > rank[ry]) parent[ry] = rx;
        else { parent[ry] = rx; rank[rx]++; }
    }

    const answer = [];

    // ----- process each request in order -----
    for (const [u, v] of requests) {
        const ru = find(u), rv = find(v);

        // already friends → automatically successful
        if (ru === rv) {
            answer.push(true);
            continue;
        }

        // check every restriction to see if merging ru and rv would break it
        let ok = true;                                   // MAIN LOGIC
        for (const [x, y] of restrictions) {
            const rx = find(x), ry = find(y);
            if ((rx === ru && ry === rv) || (rx === rv && ry === ru)) {
                ok = false;
                break;
            }
        }

        if (ok) {
            union(ru, rv);        // make them friends
            answer.push(true);
        } else {
            answer.push(false);   // request rejected
        }
    }

    return answer;
}


// TIME: O(requests.length * restrictions.length * α(n))  SPACE: O(n + restrictions.length)

function isPalindromeInBase(x, k) {
    const digits = [];
    let n = x;
    while (n > 0) { digits.push(n % k); n = Math.floor(n/k); }
    let i = 0, j = digits.length-1;
    while (i < j) { if (digits[i] !== digits[j]) return false; i++; j--; }
    return true;
}
function sumKMirror(k, n) {
    let count = 0, answer = 0, length = 1;
    while (count < n) {
        const halfLen = Math.floor((length+1)/2);
        const start = Math.pow(10, halfLen-1);
        const end = Math.pow(10, halfLen) - 1;
        let half = start;
        while (half <= end && count < n) {
            const s = String(half);
            let palStr;
            if (length % 2 === 0) palStr = s + [...s].reverse().join('');
            else palStr = s + [...s.slice(0,-1)].reverse().join('');
            const pal = parseInt(palStr);
            if (isPalindromeInBase(pal, k)) { answer += pal; count++; }
            half++;
        }
        length++;
    }
    return answer;
}

function maxDistanceDifferentColors(colors) {
    const n = colors.length;
    if (n === 0) return 0;

    const leftColor = colors[0];
    const rightColor = colors[n - 1];

    // If the two ends already have different colors, the farthest possible distance is n‑1
    if (leftColor !== rightColor) return n - 1;

    let maxDist = 0;

    // Scan from the left to find the first house whose color differs from the rightmost house
    for (let i = 0; i < n; i++) {
        if (colors[i] !== rightColor) {
            maxDist = Math.max(maxDist, n - 1 - i); // distance to the rightmost house
            break; // farther i would only reduce the distance
        }
    }

    // Scan from the right to find the first house whose color differs from the leftmost house
    for (let i = n - 1; i >= 0; i--) {
        if (colors[i] !== leftColor) {
            maxDist = Math.max(maxDist, i); // distance to the leftmost house
            break; // farther i would only reduce the distance
        }
    }

    return maxDist;
}

function RangeFreqQuery(nums) {
    // store sorted indices for each distinct value
    const positions = new Map();
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (!positions.has(v)) positions.set(v, []);
        positions.get(v).push(i);
    }

    // binary search: first index >= target
    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // binary search: first index > target
    function upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    return {
        query: function (left, right, value) {
            const list = positions.get(value);
            if (!list) return 0;                 // value never appears
            const l = lowerBound(list, left);    // first occurrence >= left
            const r = upperBound(list, right);   // first occurrence > right
            return r - l;                        // count inside [left, right]
        }
    };
}

function minimumBuckets(hamsters) {
    const n = hamsters.length;
    const arr = hamsters.split('');
    let count = 0;
    for (let i = 0; i < n; i++) {
        if (arr[i] !== 'H') continue;
        if (i > 0 && arr[i-1] === 'B') continue;
        if (i+1 < n && arr[i+1] === '.') { arr[i+1] = 'B'; count++; continue; }
        if (i > 0 && arr[i-1] === '.') { arr[i-1] = 'B'; count++; continue; }
        return -1;
    }
    return count;
}

function countFertilePyramids(grid) {
    if (!grid.length || !grid[0].length) return 0;
    const m = grid.length, n = grid[0].length;
    const dpUp = Array.from({length:m}, () => new Array(n).fill(0));
    const dpDown = Array.from({length:m}, () => new Array(n).fill(0));

    for (let i = m-1; i >= 0; i--) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                if (i === m-1) dpUp[i][j] = 1;
                else {
                    const left = j > 0 ? dpUp[i+1][j-1] : 0;
                    const mid = dpUp[i+1][j];
                    const right = j+1 < n ? dpUp[i+1][j+1] : 0;
                    dpUp[i][j] = 1 + Math.min(left, mid, right);
                }
            }
        }
    }
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 1) {
                if (i === 0) dpDown[i][j] = 1;
                else {
                    const left = j > 0 ? dpDown[i-1][j-1] : 0;
                    const mid = dpDown[i-1][j];
                    const right = j+1 < n ? dpDown[i-1][j+1] : 0;
                    dpDown[i][j] = 1 + Math.min(left, mid, right);
                }
            }
        }
    }
    let total = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            total += Math.max(0, dpUp[i][j]-1);
            total += Math.max(0, dpDown[i][j]-1);
        }
    }
    return total;
}

function getAverages(nums, k) {
    const n = nums.length;
    const result = new Array(n).fill(-1);
    const windowSize = 2 * k + 1;

    // If the window is larger than the array, every entry stays -1
    if (windowSize > n) return result;

    let sum = 0;
    for (let i = 0; i < n; i++) {
        sum += nums[i];                     // add rightmost element to the window

        if (i >= windowSize) {
            sum -= nums[i - windowSize];    // remove leftmost element when window exceeds size
        }

        if (i >= windowSize - 1) {
            const center = i - k;            // index of the current k‑radius center
            result[center] = Math.trunc(sum / windowSize); // compute integer average
        }
    }
    return result;
}

function countWords(words1, words2) {
    const freq1 = {};
    for (const w of words1) {
        freq1[w] = (freq1[w] || 0) + 1;
    }

    const freq2 = {};
    for (const w of words2) {
        freq2[w] = (freq2[w] || 0) + 1;
    }

    let commonOnce = 0;
    // check each distinct word from the first array
    for (const w in freq1) {
        if (freq1[w] === 1 && freq2[w] === 1) {
            commonOnce++;
        }
    }
    return commonOnce;
}

function targetIndices(nums, target) {
    // sort a copy of the array in non‑decreasing order
    const sorted = [...nums].sort((a, b) => a - b);
    const indices = [];

    // collect all positions where the value equals the target
    for (let i = 0; i < sorted.length; i++) {
        if (sorted[i] === target) {
            indices.push(i);
        }
    }
    return indices;
}

function findEvenNumbers(digits) {
    // build frequency map of available digits
    const freq = {};
    for (const d of digits) freq[d] = (freq[d] || 0) + 1;

    const results = new Set();               // store unique numbers

    // backtrack to build a 3‑digit number
    function backtrack(pos, current) {
        if (pos === 3) {                     // finished a candidate
            const lastDigit = current % 10;
            if (lastDigit % 2 === 0) {       // must be even
                results.add(current);
            }
            return;
        }
        for (const d in freq) {              // try each digit
            const digit = Number(d);
            if (freq[digit] === 0) continue; // none left
            if (pos === 0 && digit === 0) continue; // no leading zero

            freq[digit]--;                    // use digit
            backtrack(pos + 1, current * 10 + digit);
            freq[digit]++;                    // backtrack
        }
    }

    backtrack(0, 0);
    return Array.from(results).sort((a, b) => a - b);
}

function deleteMiddle(head) {
    // If the list is empty or has only one node, remove it
    if (!head || !head.next) return null;

    let slow = head;          // moves one step
    let fast = head;          // moves two steps
    let prev = null;          // node before slow

    // Find middle node using two‑pointer technique
    while (fast && fast.next) {
        fast = fast.next.next;
        prev = slow;
        slow = slow.next;
    }

    // Remove the middle node
    prev.next = slow.next;
    return head;
}

function minimumDeletions(nums) {
    const n = nums.length;
    let minIdx = 0, maxIdx = 0;

    // find positions of minimum and maximum
    for (let i = 1; i < n; i++) {
        if (nums[i] < nums[minIdx]) minIdx = i;
        if (nums[i] > nums[maxIdx]) maxIdx = i;
    }

    // deletions if we only remove from the front
    const frontOnly = Math.max(minIdx, maxIdx) + 1;
    // deletions if we only remove from the back
    const backOnly = Math.max(n - minIdx, n - maxIdx);
    // deletions if we remove front part then back part
    const frontThenBack = Math.min(minIdx, maxIdx) + 1 + (n - Math.max(minIdx, maxIdx));
    // deletions if we remove back part then front part (same as above, kept for clarity)
    const backThenFront = frontThenBack; // identical value, kept for readability

    // minimal deletions among all possibilities
    return Math.min(frontOnly, backOnly, frontThenBack, backThenFront);
}

function minCost(startPos, homePos, rowCosts, colCosts) {
    const [sr, sc] = startPos;
    const [hr, hc] = homePos;
    let total = 0;

    // move vertically towards home, adding the cost of each entered row
    if (sr < hr) {
        for (let r = sr + 1; r <= hr; r++) {
            total += rowCosts[r];
        }
    } else {
        for (let r = sr - 1; r >= hr; r--) {
            total += rowCosts[r];
        }
    }

    // move horizontally towards home, adding the cost of each entered column
    if (sc < hc) {
        for (let c = sc + 1; c <= hc; c++) {
            total += colCosts[c];
        }
    } else {
        for (let c = sc - 1; c >= hc; c--) {
            total += colCosts[c];
        }
    }

    return total;
}

function findAllPeople(n, meetings, firstPerson) {
    const knows = new Array(n).fill(false);
    knows[0] = true;
    knows[firstPerson] = true;

    meetings.sort((a, b) => a[2] - b[2]);               // sort by time

    let i = 0;
    while (i < meetings.length) {
        const curTime = meetings[i][2];
        const group = [];
        const persons = new Set();

        // collect all meetings that happen at the same time
        while (i < meetings.length && meetings[i][2] === curTime) {
            const [x, y] = meetings[i];
            group.push([x, y]);
            persons.add(x);
            persons.add(y);
            i++;
        }

        // build adjacency list for this time slice
        const adj = new Map();
        for (const p of persons) adj.set(p, []);
        for (const [x, y] of group) {
            adj.get(x).push(y);
            adj.get(y).push(x);
        }

        const visited = new Set();

        // explore each connected component within the same time
        for (const start of persons) {
            if (visited.has(start)) continue;

            const stack = [start];
            const component = [];
            let hasSecret = false;
            visited.add(start);

            while (stack.length) {
                const cur = stack.pop();
                component.push(cur);
                if (knows[cur]) hasSecret = true;      // check if secret is already present

                for (const nb of adj.get(cur)) {
                    if (!visited.has(nb)) {
                        visited.add(nb);
                        stack.push(nb);
                    }
                }
            }

            // if any member knows the secret, spread it to the whole component
            if (hasSecret) {
                for (const node of component) knows[node] = true;
            }
        }
    }

    const result = [];
    for (let i = 0; i < n; i++) if (knows[i]) result.push(i);
    return result;
}

function maxSubsequence(nums, k) {
    const n = nums.length;
    const pairs = new Array(n);
    for (let i = 0; i < n; i++) {
        pairs[i] = [nums[i], i];               // value with its original index
    }

    // sort by value descending and take the k largest elements
    pairs.sort((a, b) => b[0] - a[0]);
    const selected = pairs.slice(0, k);

    // restore original order of the chosen elements
    selected.sort((a, b) => a[1] - b[1]);

    const result = new Array(k);
    for (let i = 0; i < k; i++) {
        result[i] = selected[i][0];            // extract the values
    }
    return result;
}

function findGoodDays(security, time) {
    const n = security.length;
    const left = new Array(n).fill(0);   // left[i] = length of non‑increasing run ending at i
    const right = new Array(n).fill(0);  // right[i] = length of non‑decreasing run starting at i

    // build left array
    for (let i = 1; i < n; i++) {
        if (security[i - 1] >= security[i]) left[i] = left[i - 1] + 1;
    }

    // build right array
    for (let i = n - 2; i >= 0; i--) {
        if (security[i] <= security[i + 1]) right[i] = right[i + 1] + 1;
    }

    const result = [];
    // check each possible day
    for (let i = time; i < n - time; i++) {
        if (left[i] >= time && right[i] >= time) result.push(i);
    }
    return result;
}

function getDirections(root, startValue, destValue) {
    let pathToStart = "";
    let pathToDest = "";

    // DFS that records the path from root to the target node
    function dfs(node, target, curPath) {
        if (!node) return false;
        if (node.val === target) {
            return curPath;               // found: return the built path
        }
        // explore left child
        let left = dfs(node.left, target, curPath + "L");
        if (left !== false) return left;
        // explore right child
        let right = dfs(node.right, target, curPath + "R");
        if (right !== false) return right;
        return false;                     // not in this subtree
    }

    pathToStart = dfs(root, startValue, "");
    pathToDest = dfs(root, destValue, "");

    // find first differing index → LCA
    let i = 0;
    while (i < pathToStart.length && i < pathToDest.length && pathToStart[i] === pathToDest[i]) {
        i++;
    }

    // up moves from start to LCA, then down moves from LCA to dest
    const upMoves = "U".repeat(pathToStart.length - i);
    const downMoves = pathToDest.slice(i);
    return upMoves + downMoves;
}

function validArrangement(pairs) {
    if (!pairs.length) return [];
    const adj = new Map();
    const indeg = new Map();
    const outdeg = new Map();
    for (let idx = 0; idx < pairs.length; idx++) {
        const [u,v] = pairs[idx];
        if (!adj.has(u)) adj.set(u, []);
        adj.get(u).push([v, idx]);
        outdeg.set(u, (outdeg.get(u)||0)+1);
        indeg.set(v, (indeg.get(v)||0)+1);
    }
    let start = null;
    const nodes = new Set([...outdeg.keys(), ...indeg.keys()]);
    for (const node of nodes) {
        if ((outdeg.get(node)||0) - (indeg.get(node)||0) === 1) { start = node; break; }
    }
    if (start === null) start = adj.keys().next().value;

    const stack = [start];
    const edgeStack = [];
    const path = [];
    while (stack.length) {
        const v = stack[stack.length-1];
        const lst = adj.get(v);
        if (lst && lst.length) {
            const [nxt, eid] = lst.pop();
            stack.push(nxt);
            edgeStack.push(eid);
        } else {
            stack.pop();
            if (edgeStack.length) path.push(edgeStack.pop());
        }
    }
    path.reverse();
    return path.map(i => pairs[i]);
}

function sumOfSubarrayRanges(nums) {
    const n = nums.length;
    const leftMax = new Array(n).fill(-1);
    const rightMax = new Array(n).fill(n);
    const leftMin = new Array(n).fill(-1);
    const rightMin = new Array(n).fill(n);
    let stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length-1]] <= nums[i]) stack.pop();
        leftMax[i] = stack.length ? stack[stack.length-1] : -1;
        stack.push(i);
    }
    stack = [];
    for (let i = n-1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length-1]] < nums[i]) stack.pop();
        rightMax[i] = stack.length ? stack[stack.length-1] : n;
        stack.push(i);
    }
    stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length-1]] >= nums[i]) stack.pop();
        leftMin[i] = stack.length ? stack[stack.length-1] : -1;
        stack.push(i);
    }
    stack = [];
    for (let i = n-1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length-1]] > nums[i]) stack.pop();
        rightMin[i] = stack.length ? stack[stack.length-1] : n;
        stack.push(i);
    }
    let totalMax = 0, totalMin = 0;
    for (let i = 0; i < n; i++) {
        totalMax += nums[i] * (i - leftMax[i]) * (rightMax[i] - i);
        totalMin += nums[i] * (i - leftMin[i]) * (rightMin[i] - i);
    }
    return totalMax - totalMin;
}

function maxTotalFruits(fruits, startPos, k) {
    const n = fruits.length;
    const prefix = new Array(n+1).fill(0);
    for (let i = 0; i < n; i++) prefix[i+1] = prefix[i] + fruits[i][1];
    function lowerBound(target) {
        let lo = 0, hi = n;
        while (lo < hi) { const mid=(lo+hi)>>1; if (fruits[mid][0] < target) lo=mid+1; else hi=mid; }
        return lo;
    }
    let best = 0;
    for (let turn = 0; turn <= k; turn++) {
        const remain = k - 2*turn;
        if (remain < 0) continue;
        // go left `turn` then right `remain`
        best = Math.max(best, prefix[lowerBound(startPos + remain + 1)] - prefix[lowerBound(startPos - turn)]);
        // go right `turn` then left `remain`
        best = Math.max(best, prefix[lowerBound(startPos + turn + 1)] - prefix[lowerBound(startPos - remain)]);
    }
    return best;
}

/**
 * @param {number[][]} bombs
 * @return {number}
 */
function maximumDetonation(bombs) {
    const n = bombs.length;
    const adj = Array.from({ length: n }, () => []);   // adjacency list

    // build directed edges: i -> j if bomb i can reach bomb j
    for (let i = 0; i < n; i++) {
        const [xi, yi, ri] = bombs[i];
        const ri2 = ri * ri;
        for (let j = 0; j < n; j++) {
            if (i === j) continue;
            const [xj, yj] = bombs[j];
            const dx = xi - xj;
            const dy = yi - yj;
            if (dx * dx + dy * dy <= ri2) {
                adj[i].push(j);
            }
        }
    }

    let best = 0;

    // try every bomb as the initial detonation
    for (let start = 0; start < n; start++) {
        const visited = new Array(n).fill(false);
        const queue = [start];
        visited[start] = true;
        let count = 0;

        // BFS over the directed graph
        while (queue.length) {
            const cur = queue.shift();
            count++;
            for (const nxt of adj[cur]) {
                if (!visited[nxt]) {
                    visited[nxt] = true;
                    queue.push(nxt);
                }
            }
        }
        if (count > best) best = count;
    }

    return best;
}

function SORTracker() {
    this.k = 0;
    // "best" (max-heap-ish): worst of the current top-k sits on top, so pop() gives up the
    // weakest of the retrieved-eligible set when it needs to make room
    this.best = [];
    // "rest": best of the leftovers sits on top (min-heap by "goodness")
    this.rest = [];
}

function better(a, b) {
    if (a.score !== b.score) return a.score > b.score;
    return a.name < b.name;
}

function heapPush(heap, item, topIsWorstAmongBest) {
    heap.push(item);
    let i = heap.length - 1;
    const cmp = topIsWorstAmongBest
        ? (x, y) => !better(x, y)   // smaller-priority(worse) bubbles toward the top for "best"
        : (x, y) => better(x, y);  // larger-priority(better) bubbles toward the top for "rest"
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (cmp(heap[p], heap[i])) break;
        [heap[p], heap[i]] = [heap[i], heap[p]];
        i = p;
    }
}

function heapPop(heap, topIsWorstAmongBest) {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length) {
        heap[0] = last;
        const cmp = topIsWorstAmongBest
            ? (x, y) => !better(x, y)
            : (x, y) => better(x, y);
        let i = 0;
        while (true) {
            let l = i * 2 + 1, r = l + 1, bst = i;
            if (l < heap.length && !cmp(heap[bst], heap[l])) bst = l;
            if (r < heap.length && !cmp(heap[bst], heap[r])) bst = r;
            if (bst === i) break;
            [heap[i], heap[bst]] = [heap[bst], heap[i]];
            i = bst;
        }
    }
    return top;
}

SORTracker.prototype.add = function (name, score) {
    const item = { name, score };
    heapPush(this.best, item, true);
    if (this.best.length > this.k) {
        const moved = heapPop(this.best, true);
        heapPush(this.rest, moved, false);
    }
};

SORTracker.prototype.get = function () {
    this.k++;
    if (this.rest.length > 0) {
        const moved = heapPop(this.rest, false);
        heapPush(this.best, moved, true);
    }
    return this.best[0].name;
};

function countRods(rings) {
    // bitmask for each rod (0-9)
    const masks = new Array(10).fill(0);
    const colorBit = { 'R': 1, 'G': 2, 'B': 4 };

    for (let i = 0; i < rings.length; i += 2) {
        const color = rings[i];
        const rod = rings.charCodeAt(i + 1) - 48; // convert digit char to number
        masks[rod] |= colorBit[color]; // record this color on the rod
    }

    // count rods that have all three colors (mask 1|2|4 == 7)
    let result = 0;
    for (let i = 0; i < 10; i++) {
        if (masks[i] === 7) result++;
    }
    return result;
}

function addSpaces(s, spaces) {
    // Ensure spaces are sorted (they are guaranteed to be, but safe)
    let idx = 0;                     // pointer for spaces array
    const n = s.length;
    const result = [];

    for (let i = 0; i < n; i++) {
        // if current position matches a space index, insert a space first
        if (idx < spaces.length && i === spaces[idx]) {
            result.push(' ');
            idx++;
        }
        result.push(s[i]);            // add the original character
    }

    return result.join('');
}

function waterPlants(plants, capacityA, capacityB) {
    let i = 0;
    let j = plants.length - 1;
    let waterA = capacityA;
    let waterB = capacityB;
    let refills = 0;

    while (i <= j) {
        if (i === j) {                     // same plant
            if (waterA >= waterB) {        // Alice waters it
                if (waterA < plants[i]) { // not enough water
                    refills++;
                    waterA = capacityA;
                }
                waterA -= plants[i];
            } else {                       // Bob waters it
                if (waterB < plants[j]) {
                    refills++;
                    waterB = capacityB;
                }
                waterB -= plants[j];
            }
            break;
        }

        // Alice waters plant i
        if (waterA < plants[i]) {
            refills++;
            waterA = capacityA;
        }
        waterA -= plants[i];

        // Bob waters plant j
        if (waterB < plants[j]) {
            refills++;
            waterB = capacityB;
        }
