function minOperations(arr, k) {
    let operations = 0;

    // Process each of the k independent subsequences
    for (let offset = 0; offset < k; offset++) {
        const subsequence = [];
        for (let i = offset; i < arr.length; i += k) subsequence.push(arr[i]);

        // Find length of longest non‑decreasing subsequence (LNDS)
        const tails = [];                     // tails[i] = smallest possible tail of an LNDS of length i+1
        for (const value of subsequence) {
            // binary search for first element > value (upper bound) to allow equal values
            let left = 0, right = tails.length;
            while (left < right) {
                const mid = (left + right) >> 1;
                if (tails[mid] > value) right = mid;
                else left = mid + 1;
            }
            if (left === tails.length) tails.push(value);
            else tails[left] = value;
        }

        operations += subsequence.length - tails.length; // elements to change in this group
    }

    return operations;
}

