        for (const ing of ingredients[i]) {
            if (!adj.has(ing)) adj.set(ing, []);
            adj.get(ing).push(recipes[i]);   // ingredient -> recipe edge
        }
    }

    const queue = [...supplies];          // start with all available supplies
    const result = [];

    // BFS: each available item may unlock recipes that depend on it
    while (queue.length) {
