function abbreviateProductRange(left, right) {
  const MOD = 10n ** 12n; // keep enough trailing digits
  let twos = 0, fives = 0;
  let sumLog = 0;
  let tail = 1n;

  for (let i = left; i <= right; i++) {
    sumLog += Math.log10(i);
    let x = i;
    while ((x & 1) === 0) { // factor out 2
      twos++;
      x >>= 1;
    }
    while (x % 5 === 0) { // factor out 5
      fives++;
      x = Math.floor(x / 5);
    }
    tail = (tail * BigInt(x)) % MOD;
  }

  const zeroCount = Math.min(twos, fives);
  const diff = twos - fives;

  function powMod(base, exp) {
    let b = BigInt(base) % MOD;
    let e = BigInt(exp);
    let res = 1n;
    while (e > 0n) {
      if (e & 1n) res = (res * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1n;
    }
    return res;
  }

  if (diff > 0) tail = (tail * powMod(2, diff)) % MOD;
  else if (diff < 0) tail = (tail * powMod(5, -diff)) % MOD;

  const totalLog = sumLog - zeroCount;
  const totalDigits = Math.floor(totalLog) + 1;

  if (totalDigits <= 10) {
    // compute exact product using BigInt
    let prod = 1n;
    for (let i = left; i <= right; i++) prod *= BigInt(i);
    prod /= 10n ** BigInt(zeroCount);
    return prod.toString() + 'e' + zeroCount;
  }

  // leading 5 digits
  const frac = totalLog - Math.floor(totalLog);
  let leading = Math.floor(Math.pow(10, frac + 4));
  if (leading >= 100000) leading = Math.floor(leading / 10);
  const leadingStr = leading.toString().padStart(5, '0');

  // trailing 5 digits
  const trailingNum = Number(tail % 100000n);
  const trailingStr = trailingNum.toString().padStart(5, '0');

  return leadingStr + '...' + trailingStr + 'e' + zeroCount;
}

