function sumIntervals(arr) {
    const n = arr.length;
    const answer = new Array(n).fill(0);
    const groups = new Map();

    // collect indices for each distinct value
    for (let i = 0; i < n; i++) {
        const val = arr[i];
        if (!groups.has(val)) groups.set(val, []);
        groups.get(val).push(i);
    }

    // for each group compute sum of distances using prefix sums
    for (const indices of groups.values()) {
        const k = indices.length;
        if (k === 1) continue;               // only one occurrence → sum stays 0

        const prefix = new Array(k);
        prefix[0] = indices[0];
        for (let i = 1; i < k; i++) {
            prefix[i] = prefix[i - 1] + indices[i];
        }
        const total = prefix[k - 1];

        for (let i = 0; i < k; i++) {
            const idx = indices[i];
            const leftCount = i;                     // number of indices left of i
            const rightCount = k - 1 - i;            // number of indices right of i
            const leftSum = i > 0 ? prefix[i - 1] : 0;
            const rightSum = total - prefix[i];
            // distance to left side + distance to right side
            answer[idx] = idx * leftCount - leftSum + rightSum - idx * rightCount;
        }
    }

    return answer;
}

function recoverArray(nums) {
