function maxTwinSum(head) {
    if (!head) return 0;                     // empty list

    // ---- find middle of the list ----
    let slow = head, fast = head;
    while (fast && fast.next) {
        fast = fast.next.next;
        slow = slow.next;
    }

    // ---- reverse second half ----
    let prev = null, curr = slow;
    while (curr) {
        const nxt = curr.next;
        curr.next = prev;
        prev = curr;
        curr = nxt;
    }
    // now `prev` is head of reversed second half

    // ---- compute maximum twin sum ----
    let maxSum = 0;
    let p1 = head, p2 = prev;
    while (p2) {
        const sum = p1.val + p2.val;
        if (sum > maxSum) maxSum = sum;
        p1 = p1.next;
        p2 = p2.next;
    }

    // ---- restore the original list (optional) ----
    curr = prev;
    prev = null;
    while (curr) {
        const nxt = curr.next;
        curr.next = prev;
        prev = curr;
        curr = nxt;
    }
    // reconnect (if needed)
    // (the first half still ends at `slowPrev`, but we don't need it further)

    return maxSum;
}

function capitalizeTitle(title) {
