function maximumInvitations(favorite) {
    const n = favorite.length;
    const indeg = new Array(n).fill(0);
    for (const v of favorite) indeg[v]++;
    const dist = new Array(n).fill(0);
    const q = [];
    for (let i = 0; i < n; i++) if (indeg[i] === 0) q.push(i);
    let head = 0;
    while (head < q.length) {
        const u = q[head++];
        const v = favorite[u];
        dist[v] = Math.max(dist[v], dist[u]+1);
        indeg[v]--;
        if (indeg[v] === 0) q.push(v);
    }
    const visited = new Array(n).fill(false);
    let maxCycle = 0, pairSum = 0;
    for (let i = 0; i < n; i++) {
        if (indeg[i] > 0 && !visited[i]) {
            let cur = i;
            const cycle = [];
            while (!visited[cur]) {
                visited[cur] = true;
                cycle.push(cur);
                cur = favorite[cur];
            }
            const cycLen = cycle.length;
            if (cycLen === 2) {
                const [a,b] = cycle;
                pairSum += 2 + dist[a] + dist[b];
            } else {
