        }
    }

    return totalBeams;
}

function minSwaps(nums) {
    const n = nums.length;
    // count total number of 1's
    let totalOnes = 0;
    for (let i = 0; i < n; i++) totalOnes += nums[i];
    if (totalOnes <= 1) return 0;               // no swaps needed

    // compute number of 1's in the first window of size totalOnes
    let windowOnes = 0;
    for (let i = 0; i < totalOnes; i++) windowOnes += nums[i];
    let minZeros = totalOnes - windowOnes;      // zeros inside current window

    // slide the window around the circular array
    for (let start = 1; start < n; start++) {
        windowOnes -= nums[start - 1];                              // leave
        const enteringIdx = (start + totalOnes - 1) % n;
        windowOnes += nums[enteringIdx];                            // enter
        const zeros = totalOnes - windowOnes;
        if (zeros < minZeros) minZeros = zeros;                     // keep best
    }
    return minZeros;
}

function longestPalindrome(words) {
    // 1. frequency map
    const freq = new Map();
    for (const w of words) {
        freq.set(w, (freq.get(w) || 0) + 1);
    }

    let length = 0;
    let hasCenter = false;

    // 2. build palindrome from pairs
    for (const [word, cnt] of freq.entries()) {
        if (cnt === 0) continue;               // already used up

        const rev = word[1] + word[0];

        if (word === rev) {                     // self‑palindromic word like "gg"
            const pairs = Math.floor(cnt / 2);
            length += pairs * 4;                // each pair adds 4 chars
            if (cnt % 2 === 1) hasCenter = true; // one leftover can be centre
        } else {                                // normal word, look for its reverse
            const revCnt = freq.get(rev) || 0;
            const pairCnt = Math.min(cnt, revCnt);
            length += pairCnt * 4;              // each matched pair adds 4 chars
            // mark used copies so we don't count them again
            freq.set(word, cnt - pairCnt);
            freq.set(rev, revCnt - pairCnt);
        }
    }

    // 3. possibly place a single self‑palindromic word in the centre
    if (hasCenter) length += 2;

    return length;
}

