}

var possibleToStamp = function(grid, stampHeight, stampWidth) {
    const m = grid.length;
    if (m===0) return true;
    const n = grid[0].length;
    const ps = Array.from({length:m+1}, () => new Array(n+1).fill(0));
    for (let i=0;i<m;i++) {
        let rowSum = 0;
        for (let j=0;j<n;j++) {
