            ps[i+1][j+1] = ps[i][j+1] + rowSum;
        }
    }
    const diff = Array.from({length:m+1}, () => new Array(n+1).fill(0));
    const maxI = m - stampHeight;
    const maxJ = n - stampWidth;
    for (let i=0;i<=maxI;i++) {
        for (let j=0;j<=maxJ;j++) {
            const total = ps[i+stampHeight][j+stampWidth] - ps[i][j+stampWidth] - ps[i+stampHeight][j] + ps[i][j];
            if (total === 0) {
                diff[i][j] += 1;
                diff[i+stampHeight][j] -= 1;
                diff[i][j+stampWidth] -= 1;
                diff[i+stampHeight][j+stampWidth] += 1;
            }
        }
    }
    for (let i=0;i<m;i++) {
        for (let j=0;j<n;j++) {
            if (i>0) diff[i][j] += diff[i-1][j];
            if (j>0) diff[i][j] += diff[i][j-1];
            if (i>0 && j>0) diff[i][j] -= diff[i-1][j-1];
            if (grid[i][j]===0 && diff[i][j]===0) return false;
        }
    }
    return true;
};

function isValidMatrix(matrix) {
    const n = matrix.length;

    // check each row contains 1..n exactly once
    for (let row = 0; row < n; row++) {
        const seen = new Set();
        for (let col = 0; col < n; col++) {
            const val = matrix[row][col];
            if (val < 1 || val > n) return false; // out‑of‑range value
            seen.add(val);
        }
        if (seen.size !== n) return false; // missing or duplicate numbers
    }

    // check each column contains 1..n exactly once
    for (let col = 0; col < n; col++) {
        const seen = new Set();
        for (let row = 0; row < n; row++) {
            const val = matrix[row][col];
            if (val < 1 || val > n) return false;
            seen.add(val);
        }
        if (seen.size !== n) return false;
    }

    return true;
}

function divideString(s, k, fill) {
