function maxPoints(questions) {
    const n = questions.length;
    const dp = new Array(n + 1).fill(0);   // dp[i] = best points from i to end

    for (let i = n - 1; i >= 0; i--) {
        const [points, brain] = questions[i];
        // choose to solve i or skip it
        const take = points + (i + brain + 1 <= n ? dp[i + brain + 1] : 0);
        const skip = dp[i + 1];
        dp[i] = Math.max(take, skip);
    }
    return dp[0];
}

function countWords(startWords, targetWords) {
