    for (const t of targetWords) {
        const sortedTarget = t.split('').sort().join('');
        for (let i = 0; i < sortedTarget.length; i++) {
            // avoid checking the same removal when letters are duplicated
            if (i > 0 && sortedTarget[i] === sortedTarget[i - 1]) continue;
            const candidate = sortedTarget.slice(0, i) + sortedTarget.slice(i + 1);
            if (startSet.has(candidate)) {
