    for (let d of differences) {
        pref += d;
        if (pref < minPref) minPref = pref;
        if (pref > maxPref) maxPref = pref;
    }

    // feasible range for the first hidden value
    const low0  = lower - minPref;
    const high0 = upper - maxPref;

    // number of integer choices for hidden[0]
    return high0 >= low0 ? high0 - low0 + 1 : 0;
