function maxRunTime(n, batteries) {
    if (batteries.length < n) return 0;

    const total = batteries.reduce((s, b) => s + b, 0);
    let low = 0;
    let high = Math.floor(total / n); // upper bound

    // binary search for the largest feasible time
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        let possible = 0;
        for (let i = 0; i < batteries.length; i++) {
            possible += Math.min(batteries[i], mid);
        }
        if (possible >= n * mid) {
            low = mid;               // mid is feasible, try higher
        } else {
            high = mid - 1;          // mid is not feasible, go lower
        }
    }
    return low;
}

function numberOfWays(corridor) {
