    const result = new Array(nums.length);
    // Fill result alternately: positive at even indices, negative at odd indices
    for (let i = 0; i < result.length; i++) {
        if (i % 2 === 0) result[i] = positives[i / 2];
        else result[i] = negatives[(i - 1) / 2];
    }

    return result;
}

