        const val = grid[r][c];
        if (low <= val && val <= high) candidates.push([d, val, r, c]);
        for (const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]) {
            const nr = r+dr, nc = c+dc;
            if (nr>=0 && nr<m && nc>=0 && nc<n && !visited[nr][nc] && grid[nr][nc] !== 0) {
                visited[nr][nc] = true;
                q.push([nr,nc,d+1]);
            }
        }
    }
    candidates.sort((a,b) => a[0]-b[0] || a[1]-b[1] || a[2]-b[2] || a[3]-b[3]);
    return candidates.slice(0,k).map(([,,r,c]) => [r,c]);
}

function countElements(nums) {
    // find global minimum and maximum
    let min = nums[0];
    let max = nums[0];
    for (let i = 1; i < nums.length; i++) {
        if (nums[i] < min) min = nums[i];
        if (nums[i] > max) max = nums[i];
    }

    // count elements that are strictly between min and max
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] > min && nums[i] < max) count++;
    }
    return count;
}

function findSubstringWithGivenHash(s, power, modulo, k, hashValue) {
    const n = s.length;
    const p = BigInt(power);
    const mod = BigInt(modulo);
    const target = BigInt(hashValue);
    const charVal = c => BigInt(c.charCodeAt(0) - 96); // 'a' -> 1

    // power^k % mod
    let powerK = 1n;
    for (let i = 0; i < k; i++) {
        powerK = (powerK * p) % mod;
    }

    // hash of the last k characters
    let cur = 0n;
    let pow = 1n;
    for (let i = n - k; i < n; i++) {
        cur = (cur + charVal(s[i]) * pow) % mod;
        pow = (pow * p) % mod;
    }

    let answerIdx = n - k;
    if (cur === target) {
        answerIdx = n - k;
    }

    // slide window to the left
    for (let i = n - k - 1; i >= 0; i--) {
        const outVal = charVal(s[i + k]);
        cur = (charVal(s[i]) + p * cur - outVal * powerK) % mod;
        if (cur < 0) cur += mod;
        if (cur === target) {
            answerIdx = i; // earlier index found
        }
    }

    return s.substring(answerIdx, answerIdx + k);
}

function maximumGood(statements) {
    const n = statements.length;
    let best = 0;

    // enumerate every possible set of good people
    for (let mask = 0; mask < (1 << n); mask++) {
        const goodCount = popCount(mask);
        if (goodCount <= best) continue;               // no need to check smaller sets

        let ok = true;
        // verify that all declared truths of the assumed good people hold
        for (let i = 0; i < n && ok; i++) {
            if ((mask >> i) & 1) {                     // i is assumed good
                for (let j = 0; j < n; j++) {
                    const stmt = statements[i][j];
                    if (stmt === 2) continue;          // no statement
                    const jIsGood = (mask >> j) & 1;
                    if (stmt === 1 && !jIsGood) { ok = false; break; } // said good but j is bad
                    if (stmt === 0 && jIsGood) { ok = false; break; } // said bad but j is good
                }
            }
        }
        if (ok) best = goodCount;
    }
    return best;
}

// helper: count set bits in an integer
function popCount(x) {
    let cnt = 0;
    while (x) {
        x &= x - 1;
        cnt++;
    }
    return cnt;
}

function groupStrings(words) {
    const maskCounts = new Map();
    for (const w of words) {
        let mask = 0;
        for (const ch of w) mask |= 1 << (ch.charCodeAt(0) - 97);
        maskCounts.set(mask, (maskCounts.get(mask)||0) + 1);
    }
    const masks = [...maskCounts.keys()];
    const n = masks.length;
    const idxOfMask = new Map(masks.map((m,i) => [m,i]));
    const parent = Array.from({length:n}, (_,i) => i);
    const rank = new Array(n).fill(0);
    function find(x) {
        while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function union(a, b) {
        const ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else { parent[rb] = ra; rank[ra]++; }
    }
    const bitsSet = [], bitsUnset = [];
    for (const m of masks) {
        const setList = [], unsetList = [];
        for (let i = 0; i < 26; i++) {
            if ((m >> i) & 1) setList.push(i); else unsetList.push(i);
        }
        bitsSet.push(setList);
        bitsUnset.push(unsetList);
    }
    for (let i = 0; i < n; i++) {
        const m = masks[i];
        for (let b = 0; b < 26; b++) {
            const bit = 1 << b;
            const newMask = (m & bit) ? (m ^ bit) : (m | bit);
            const j = idxOfMask.get(newMask);
            if (j !== undefined) union(i, j);
        }
        for (const b of bitsSet[i]) {
            for (const c of bitsUnset[i]) {
                const newMask = (m ^ (1 << b)) | (1 << c);
                const j = idxOfMask.get(newMask);
                if (j !== undefined) union(i, j);
            }
        }
    }
    const compSizes = new Map();
    for (let i = 0; i < n; i++) {
        const root = find(i);
        compSizes.set(root, (compSizes.get(root)||0) + maskCounts.get(masks[i]));
    }
    const numGroups = compSizes.size;
    const maxGroup = compSizes.size ? Math.max(...compSizes.values()) : 0;
    return [numGroups, maxGroup];
}

function keepMultiplying(nums, original) {
    // Build a hash set for O(1) look‑ups
    const valueSet = new Set(nums);
    let current = original;
    // Keep doubling while the current value exists in the set
    while (valueSet.has(current)) {
        current *= 2;
    }
    return current;
}

function maxScoreDivisions(nums) {
    const n = nums.length;
    let totalOnes = 0;
    for (let v of nums) totalOnes += v;          // count all ones

    let zerosLeft = 0;      // zeros in the current left part
    let onesSeen = 0;       // ones already moved to the left part
    let maxScore = -1;
    const result = [];

    for (let i = 0; i <= n; i++) {
        const onesRight = totalOnes - onesSeen; // ones remaining on the right
        const score = zerosLeft + onesRight;    // MAIN LOGIC: division score

        if (score > maxScore) {                  // MAIN LOGIC: update max & reset list
            maxScore = score;
            result.length = 0;
            result.push(i);
        } else if (score === maxScore) {         // MAIN LOGIC: collect equal max
            result.push(i);
        }

        // move element nums[i] from right to left for next iteration
        if (i < n) {
            if (nums[i] === 0) zerosLeft++;
            else onesSeen++;
        }
    }
    return result;
}

function partitionArray(nums, pivot) {
    const less = [];    // elements < pivot, keep order
    const equal = [];   // elements == pivot
    const greater = []; // elements > pivot, keep order

    // MAIN LOGIC: distribute each element into one of the three groups
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        if (v < pivot) {
            less.push(v);
        } else if (v === pivot) {
            equal.push(v);
        } else {
            greater.push(v);
        }
    }

    // combine groups preserving their internal order
    return less.concat(equal, greater);
}

function minCostSetCookingTime(startAt, moveCost, pushCost, targetSeconds) {
    let best = Number.MAX_SAFE_INTEGER;
    for (let minutes = 0; minutes <= 99; minutes++) {
        const seconds = targetSeconds - minutes * 60;
        if (seconds < 0 || seconds > 99) continue;
        const mm = String(minutes).padStart(2, '0');
        const ss = String(seconds).padStart(2, '0');
        const code = mm + ss; // 4‑digit string
        let leadingZeros = 0;
        while (leadingZeros < 4 && code[leadingZeros] === '0') leadingZeros++;
        for (let drop = 0; drop <= leadingZeros; drop++) {
            const typed = code.slice(drop);
            if (typed.length === 0) continue; // must press at least one digit
            let cur = startAt;
            let cost = 0;
            for (let i = 0; i < typed.length; i++) {
                const d = typed.charCodeAt(i) - 48; // digit value
                if (cur !== d) cost += moveCost;
                cost += pushCost;
                cur = d;
            }
            if (cost < best) best = cost;
        }
    }
    return best;
}

function minimumDifference(nums) {
    const total = nums.length, n = total/3;
    const leftMin = new Array(total).fill(0n);
    const rightMax = new Array(total).fill(0n);
    let heap = [], sum = 0n;
    for (let i = 0; i < total; i++) {
        heap.push(nums[i]); sum += BigInt(nums[i]);
        heap.sort((a,b)=>b-a);
        if (heap.length > n) sum -= BigInt(heap.shift());
        if (heap.length === n) leftMin[i] = sum;
    }
    heap = []; sum = 0n;
    for (let i = total-1; i >= 0; i--) {
        heap.push(nums[i]); sum += BigInt(nums[i]);
        heap.sort((a,b)=>a-b);
        if (heap.length > n) sum -= BigInt(heap.shift());
        if (heap.length === n) rightMax[i] = sum;
    }
    let best = null;
    for (let i = n-1; i < 2*n; i++) {
        const diff = leftMin[i] - rightMax[i+1];
        if (best === null || diff < best) best = diff;
    }
    return Number(best);
}

function minSum(num) {
    // 1. extract the four digits
    const digits = [
        Math.floor(num / 1000),          // thousands
        Math.floor((num % 1000) / 100),  // hundreds
        Math.floor((num % 100) / 10),    // tens
        num % 10                         // ones
    ];

    // 2. sort digits ascending
    digits.sort((a, b) => a - b);

    // 3. build the two numbers with smallest possible tens digits
    const new1 = digits[0] * 10 + digits[2];
    const new2 = digits[1] * 10 + digits[3];

    // 4. return their sum
    return new1 + new2;
}

function minimumTime(s) {
    const n = s.length;
    let best = 0, cur = 0;
    for (const ch of s) {
        const val = ch === '1' ? 1 : -1;
        cur = Math.min(val, cur+val);
        best = Math.min(best, cur);
    }
    return n + best;
}

function countOperations(num1, num2) {
    let operations = 0;
    while (num1 > 0 && num2 > 0) {
        if (num1 >= num2) {
            operations += Math.floor(num1 / num2); // how many times we can subtract num2 from num1
            num1 = num1 % num2;                     // remainder after those subtractions
        } else {
            operations += Math.floor(num2 / num1);
            num2 = num2 % num1;
        }
    }
    return operations;
}

// TIME: O(log min(num1, num2)) SPACE: O(1)

function sortEvenOddIndices(nums) {
    const oddVals = [];
    const evenVals = [];

    // separate values by index parity
    for (let i = 0; i < nums.length; i++) {
        if (i % 2 === 0) {
            evenVals.push(nums[i]);
        } else {
            oddVals.push(nums[i]);
        }
    }

    // sort odd-index values descending, even-index values ascending
    oddVals.sort((a, b) => b - a);
    evenVals.sort((a, b) => a - b);

    // rebuild the array using the sorted groups
    const result = new Array(nums.length);
    let oddIdx = 0, evenIdx = 0;
    for (let i = 0; i < nums.length; i++) {
        if (i % 2 === 0) {
            result[i] = evenVals[evenIdx++];
        } else {
            result[i] = oddVals[oddIdx++];
        }
    }
    return result;
}

function smallestRearrangedNumber(num) {
  // handle the trivial zero case
  if (num === 0) return 0;

  const sign = Math.sign(num);                     // keep the original sign
  const digits = Math.abs(num).toString().split(''); // work with absolute digits

  if (sign >= 0) {
    digits.sort((a, b) => a - b);                  // sort ascending for smallest positive
    // ensure the first digit is not zero
    if (digits[0] === '0') {
      const firstNonZero = digits.findIndex(d => d !== '0');
      if (firstNonZero !== -1) {
        [digits[0], digits[firstNonZero]] = [digits[firstNonZero], digits[0]];
      }
    }
    return Number(digits.join(''));
  } else {
    digits.sort((a, b) => b - a);                  // sort descending for largest magnitude
    // leading zero cannot appear after sorting descending unless all digits are zero
    return Number('-' + digits.join(''));
  }
}

function Bitset(size) {
    const bits = new Uint8Array(size);   // stored bits (0/1)
    let flipped = false;                 // lazy flip flag
    let onesCount = 0;                   // number of 1s in the actual bitset

    return {
        fix: function (idx) {
            // if actual bit is 0, set it to 1
            if ((bits[idx] ^ (flipped ? 1 : 0)) === 0) {
                bits[idx] = flipped ? 0 : 1;
                onesCount++;
            }
        },
        unfix: function (idx) {
            // if actual bit is 1, set it to 0
            if ((bits[idx] ^ (flipped ? 1 : 0)) === 1) {
                bits[idx] = flipped ? 1 : 0;
                onesCount--;
            }
        },
        flip: function () {
            flipped = !flipped;                     // toggle lazy flag
            onesCount = size - onesCount;           // update count of 1s
        },
        all: function () {
            return onesCount === size ? 1 : 0;
        },
        one: function () {
            return onesCount > 0 ? 1 : 0;
        },
        count: function () {
            return onesCount;
        },
        toString: function () {
            let result = '';
            for (let i = 0; i < size; i++) {
                result += bits[i] ^ (flipped ? 1 : 0);
            }
            return result;
        }
    };
}

// TIME: O(1) per operation (toString O(n)) SPACE: O(n)

function minimumOperationsAlternating(nums) {
    const n = nums.length;
    function topTwo(indices) {
        const freq = new Map();
        for (const i of indices) freq.set(nums[i], (freq.get(nums[i])||0)+1);
        let first = [null,0], second = [null,0];
        for (const [val,cnt] of freq) {
            if (cnt > first[1]) { second = first; first = [val,cnt]; }
            else if (cnt > second[1]) second = [val,cnt];
        }
        return {first, second, total: indices.length};
    }
    const evenIdx = [], oddIdx = [];
    for (let i = 0; i < n; i++) (i%2===0?evenIdx:oddIdx).push(i);
    const E = topTwo(evenIdx), O = topTwo(oddIdx);
    if (E.first[0] !== O.first[0] || E.first[0] === null) {
        const keepE = E.first[1] || 0, keepO = O.first[1] || 0;
        return (E.total - keepE) + (O.total - keepO);
    } else {
        const opt1 = (E.total - E.first[1]) + (O.total - O.second[1]);
        const opt2 = (E.total - E.second[1]) + (O.total - O.first[1]);
        return Math.min(opt1, opt2);
    }
}

function minimumRemoval(beans) {
    beans.sort((a, b) => a - b);               // sort ascending
    const n = beans.length;
    let total = 0;
    for (let v of beans) total += v;           // total beans

    let maxKept = 0;
    for (let i = 0; i < n; i++) {
        const kept = beans[i] * (n - i);        // keep suffix [i..n-1] at beans[i]
        if (kept > maxKept) maxKept = kept;     // update best kept amount
    }
    return total - maxKept;                     // beans to remove
}

var countEqualAndDivisiblePairs = function(nums, k) {
    let ans = 0;
    const n = nums.length;
    for (let i=0;i<n;i++)
        for (let j=i+1;j<n;j++)
            if (nums[i]===nums[j] && (i*j)%k===0) ans++;
    return ans;
};

function threeConsecutiveSum(num) {
    // If num is not divisible by 3, it cannot be expressed as sum of three consecutive integers
    if (num % 3 !== 0) return [];

    const middle = num / 3;                 // the middle integer of the three
    return [middle - 1, middle, middle + 1]; // the three consecutive integers
}

function maximumANDSum(nums, numSlots) {
    const n = nums.length;
    const totalPos = 2*numSlots;
    const dp = new Array(1 << totalPos).fill(-Infinity);
    dp[0] = 0;
    for (let mask = 0; mask < (1<<totalPos); mask++) {
        if (dp[mask] === -Infinity) continue;
        let k = 0, m = mask;
        while (m) { k += m&1; m>>=1; }
        if (k >= n) continue;
        for (let p = 0; p < totalPos; p++) {
            if ((mask>>p)&1) continue;
            const slot = Math.floor(p/2)+1;
            const newMask = mask | (1<<p);
            const val = dp[mask] + (nums[k] & slot);
            if (val > dp[newMask]) dp[newMask] = val;
        }
    }
    let ans = 0;
    for (let mask = 0; mask < (1<<totalPos); mask++) {
        let k=0,m=mask; while(m){k+=m&1;m>>=1;}
        if (k === n) ans = Math.max(ans, dp[mask]);
    }
    return ans;
}

function maximumSplit(finalSum) {
    if (finalSum % 2 !== 0) return [];
    const result = [];
    let next = 2;
    let remaining = finalSum;
    while (remaining >= next) {
        result.push(next);
        remaining -= next;
        next += 2;
    }
    if (remaining > 0) result[result.length - 1] += remaining;
    return result;
}

function mergeNodes(head) {
    // dummy node to build the result list
    const dummy = { val: 0, next: null };
    let tail = dummy;          // points to last node in result list
    let current = head.next;   // skip the leading zero
    let segmentSum = 0;

    while (current) {
        if (current.val === 0) {          // reached the end of a segment
            // create a node with the accumulated sum and attach it
            tail.next = { val: segmentSum, next: null };
            tail = tail.next;
            segmentSum = 0;                // reset for the next segment
        } else {
            segmentSum += current.val;     // accumulate values inside the segment
        }
        current = current.next;
    }

    return dummy.next;   // head of the merged list (no leading zero)
}

function repeatLimitedString(s, repeatLimit) {
    // count occurrences of each letter
    const cnt = new Array(26).fill(0);
    for (let ch of s) cnt[ch.charCodeAt(0) - 97]++;

    const res = [];
    let lastIdx = -1;      // index of the last placed character
    let lastRun = 0;       // how many times it appears consecutively

    while (true) {
        // find the largest character that is still available
        let i = 25;
        while (i >= 0 && cnt[i] === 0) i--;
        if (i < 0) break; // no characters left

        // if adding this character would exceed the repeat limit, try the next smaller one
        if (i === lastIdx && lastRun === repeatLimit) {
            let j = i - 1;
            while (j >= 0 && cnt[j] === 0) j--;
            if (j < 0) break; // cannot place any more characters
            // place the smaller character to break the streak
            res.push(String.fromCharCode(j + 97));
            cnt[j]--;
            lastIdx = j;
            lastRun = 1;
        } else {
            // place the current largest character
            res.push(String.fromCharCode(i + 97));
            cnt[i]--;
            if (i === lastIdx) {
                lastRun++;
            } else {
                lastIdx = i;
                lastRun = 1;
            }
        }
    }
    return res.join('');
}

function goodTriplets(nums1, nums2) {
    const n = nums1.length;
    const posInNums2 = new Array(Math.max(...nums2) + 1).fill(0);
    for (let idx = 0; idx < nums2.length; idx++) posInNums2[nums2[idx]] = idx;
    const p = nums1.map(val => posInNums2[val]);

    class Fenwick {
        constructor(size) { this.n = size; this.bit = new Array(size+1).fill(0); }
        add(idx, delta=1) {
            let i = idx+1;
            while (i <= this.n) { this.bit[i] += delta; i += i & (-i); }
        }
        sum(idx) {
            if (idx < 0) return 0;
            let i = idx+1, res = 0;
            while (i) { res += this.bit[i]; i -= i & (-i); }
            return res;
        }
    }
    const fenwickLeft = new Fenwick(n);
    const leftCounts = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        const pi = p[i];
        leftCounts[i] = fenwickLeft.sum(pi-1);
        fenwickLeft.add(pi, 1);
    }
    const fenwickRight = new Fenwick(n);
    const rightCounts = new Array(n).fill(0);
    let seen = 0;
    for (let i = n-1; i >= 0; i--) {
        const pi = p[i];
        const lessOrEqual = fenwickRight.sum(pi);
        const greater = seen - lessOrEqual;
        rightCounts[i] = greater;
        fenwickRight.add(pi, 1);
        seen++;
    }
    let ans = 0;
    for (let i = 0; i < n; i++) ans += leftCounts[i] * rightCounts[i];
    return ans;
}

function countEvenDigitSum(num) {
    let count = 0;
    for (let i = 1; i <= num; i++) {
        // compute digit sum of i
        let sum = 0, x = i;
        while (x > 0) {
            sum += x % 10;
            x = Math.floor(x / 10);
        }
        if (sum % 2 === 0) count++;
    }
    return count;
}

// TIME: O(num * log10(num)) SPACE: O(1)

function countPairs(nums, k) {
  // helper to compute greatest common divisor
  function gcd(a, b) {
    while (b !== 0) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  const freq = new Map();   // stores how many times each gcd value has appeared
  let result = 0;

  for (const num of nums) {
    const g = gcd(num, k);   // gcd of current element with k

    // MAIN LOGIC: count previous elements whose gcd with k together make a product divisible by k
    for (const [prevG, cnt] of freq.entries()) {
      if ((g * prevG) % k === 0) {
        result += cnt;
      }
    }

    // update frequency map
    freq.set(g, (freq.get(g) || 0) + 1);
  }

  return result;
}

function countWords(words, pref) {
    let count = 0;                         // initialize result

    for (let i = 0; i < words.length; i++) {   // iterate over all words
        // check if current word starts with the given prefix
        if (words[i].startsWith(pref)) {
            count++;                         // increment when prefix matches
        }
    }

    return count;                           // return total matches
}

function minSteps(s, t) {
    const diff = {};                     // store count(s) - count(t) for each character

    for (const ch of s) {
        diff[ch] = (diff[ch] || 0) + 1;
    }
    for (const ch of t) {
        diff[ch] = (diff[ch] || 0) - 1;
    }

    let steps = 0;
    // sum the absolute differences; each unit represents one needed append
    for (const key in diff) {
        steps += Math.abs(diff[key]);
    }
    return steps;
}

function sortJumbled(mapping, nums) {
  // Build an array that keeps the original number, its mapped value, and original index
  const items = nums.map((num, i) => {
    const mappedStr = String(num)
      .split('')                                   // split into digits
      .map(ch => mapping[Number(ch)])              // replace each digit
      .join('');                                    // re‑assemble
    const mappedVal = Number(mappedStr);           // remove leading zeros
    return { orig: num, mapped: mappedVal, idx: i };
  });

  // Stable sort by mapped value, then by original index to keep relative order
  items.sort((a, b) => {
    if (a.mapped !== b.mapped) return a.mapped - b.mapped;
    return a.idx - b.idx;
  });

  // Extract the sorted original numbers
  return items.map(item => item.orig);
}

function getAncestors(n, edges) {
    // build adjacency list and indegree count
    const adj = Array.from({ length: n }, () => []);
    const indeg = new Array(n).fill(0);
    for (const [from, to] of edges) {
        adj[from].push(to);
        indeg[to]++;
    }

    // each node keeps a Set of its ancestors
    const ancestors = Array.from({ length: n }, () => new Set());

    // Kahn's algorithm for topological order
    const queue = [];
    for (let i = 0; i < n; i++) if (indeg[i] === 0) queue.push(i);

    while (queue.length) {
        const u = queue.shift();

        // propagate ancestors from u to its children
        for (const v of adj[u]) {
            ancestors[v].add(u);               // direct parent
            for (const anc of ancestors[u]) {   // all ancestors of u
                ancestors[v].add(anc);
            }
            indeg[v]--;
            if (indeg[v] === 0) queue.push(v);
        }
    }

    // convert Sets to sorted arrays
    const result = ancestors.map(set => Array.from(set).sort((a, b) => a - b));
    return result;
}

// TIME: O(n + e + totalAncestors) ≈ O(n^2) SPACE: O(n^2)

function minimumTime(time, totalTrips) {
    // lower bound: at least 1 unit of time
    let left = 1;
    // upper bound: fastest bus does all trips alone
    let right = Math.min(...time) * totalTrips;

    while (left < right) {
        const mid = Math.floor((left + right) / 2);
        // count trips possible by time = mid
        let trips = 0;
        for (let i = 0; i < time.length; i++) {
            trips += Math.floor(mid / time[i]);
            if (trips >= totalTrips) break; // early stop
        }
        if (trips >= totalTrips) {
            right = mid;               // enough trips, try smaller time
        } else {
            left = mid + 1;            // not enough, need more time
        }
    }
    return left;
}

function minimumFinishTime(tires, changeTime, numLaps) {
    const INF = Infinity;
    const best = new Array(numLaps+1).fill(INF);
    for (const [f,r] of tires) {
        let lapTime = f, total = 0;
        for (let k = 1; k <= numLaps; k++) {
            total += lapTime;
            if (total < best[k]) best[k] = total;
            lapTime *= r;
            if (lapTime > changeTime + f) break;
        }
    }
    const dp = new Array(numLaps+1).fill(INF);
    dp[0] = 0;
    for (let i = 1; i <= numLaps; i++) {
        for (let k = 1; k <= i; k++) {
            if (best[k] === INF) continue;
            const cand = dp[i-k] + best[k] + (i===k?0:changeTime);
            if (cand < dp[i]) dp[i] = cand;
        }
    }
    return dp[numLaps];
}

function createBinaryTree(descriptions) {
    // map value -> TreeNode instance
    const nodes = new Map();
    // keep track of all child values
    const children = new Set();

    // helper to get or create a node
    function getNode(val) {
        if (!nodes.has(val)) nodes.set(val, { val, left: null, right: null });
        return nodes.get(val);
    }

    for (const [parentVal, childVal, isLeft] of descriptions) {
        const parentNode = getNode(parentVal);
        const childNode = getNode(childVal);
        // attach child to the correct side of the parent
        if (isLeft === 1) parentNode.left = childNode;
        else parentNode.right = childNode;
        children.add(childVal);               // record that this node has a parent
    }

    // the root is the only node that never appears as a child
    for (const [val, node] of nodes) {
        if (!children.has(val)) return node;
    }
    return null; // should never happen with valid input
}

function replaceNonCoprimes(nums) {
    function gcd(a,b){while(b){[a,b]=[b,a%b];}return a;}
    const stack = [];
    for (const num of nums) {
        let cur = num;
        while (stack.length) {
            const g = gcd(stack[stack.length-1], cur);
            if (g > 1) {
                cur = stack.pop() / g * cur;
            } else break;
        }
        stack.push(cur);
    }
    return stack;
}

function mostFrequent(nums, key) {
    const followCount = {};

    // Count each number that appears right after an occurrence of key
    for (let i = 0; i < nums.length - 1; i++) {
        if (nums[i] === key) {
            const target = nums[i + 1];
            followCount[target] = (followCount[target] || 0) + 1;
        }
    }

    // Find the target with the highest count
    let bestTarget = -1;
    let maxCnt = -1;
    for (const t in followCount) {
        const cnt = followCount[t];
        if (cnt > maxCnt) {
            maxCnt = cnt;
            bestTarget = Number(t);
        }
    }
    return bestTarget;
}

function cellsInRange(s) {
    // split the range into start and end cells
    const [start, end] = s.split(':');

    // extract column letters and row numbers
    const startCol = start[0];
    const startRow = parseInt(start.slice(1), 10);
    const endCol = end[0];
    const endRow = parseInt(end.slice(1), 10);

    const result = [];

    // iterate columns from start to end
    for (let colCode = startCol.charCodeAt(0); colCode <= endCol.charCodeAt(0); colCode++) {
        // iterate rows from start to end for each column
        for (let row = startRow; row <= endRow; row++) {
            result.push(String.fromCharCode(colCode) + row);
        }
    }

    return result;
}

function minMovesToMakePalindrome(s) {
    const arr = s.split('');          // mutable copy
    let i = 0,
        j = arr.length - 1,
        moves = 0;

    while (i < j) {
        if (arr[i] === arr[j]) {      // already a matching pair
            i++;
            j--;
            continue;
        }

        // find a partner for arr[i] on the right side
        let k = j;
        while (k > i && arr[k] !== arr[i]) k--;

        if (k === i) {                // left char is the middle one
            // swap it one step towards the centre
            [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
            moves++;
        } else {
            // bring the matching character to position j
            while (k < j) {
                [arr[k], arr[k + 1]] = [arr[k + 1], arr[k]];
                moves++;
                k++;
            }
            i++;
            j--;
        }
    }
    return moves;
}

function minimalAppendSum(nums, k) {
    const present = new Set(nums);          // store existing numbers for O(1) lookup
    let added = 0;
    let sum = 0;
    let candidate = 1;
    while (added < k) {                     // keep adding until k numbers are chosen
        if (!present.has(candidate)) {      // candidate is not in the original array
            sum += candidate;
            added++;
        }
        candidate++;
    }
    return sum;
}

function findKDistantIndices(nums, key, k) {
    const n = nums.length;
    const keyPos = [];

    // collect all positions where nums[j] == key
    for (let i = 0; i < n; i++) {
        if (nums[i] === key) keyPos.push(i);
    }

    const result = [];
    let ptr = 0;                     // pointer to the first key position that could be within distance k

    // iterate over every index i and check if a key lies within [i‑k, i+k]
    for (let i = 0; i < n; i++) {
        // discard key positions that are too far left of i
        while (ptr < keyPos.length && keyPos[ptr] < i - k) {
            ptr++;
        }
        // if the current key position is not farther than i+k, i is k‑distant
        if (ptr < keyPos.length && keyPos[ptr] <= i + k) {
            result.push(i);
        }
    }
    return result;
}

function maximumTop(nums, k) {
    const n = nums.length;
    if (k === 0) return nums[0];
    if (n === 1) return (k % 2 === 1) ? -1 : nums[0];
    let maxVal = -1;
    const limit = Math.min(k-1, n);
    for (let i = 0; i < limit; i++) if (nums[i] > maxVal) maxVal = nums[i];
    if (k < n && nums[k] > maxVal) maxVal = nums[k];
    return maxVal;
}

function countArtifacts(n, artifacts, dig) {
    // store all dug cells
    const dugSet = new Set();
    for (const [r, c] of dig) {
        dugSet.add(r + ',' + c);
    }

    // map each cell to its artifact index (optional for this solution,
    // kept for clarity; not used later)
    const cellToArtifact = new Map();
    for (let i = 0; i < artifacts.length; i++) {
        const [r1, c1, r2, c2] = artifacts[i];
        for (let r = r1; r <= r2; r++) {
            for (let c = c1; c <= c2; c++) {
                cellToArtifact.set(r + ',' + c, i);
            }
        }
    }

    let answer = 0;
    // check every artifact
    for (const [r1, c1, r2, c2] of artifacts) {
        let fullyDug = true;                     // MAIN LOGIC: assume artifact is extractable
        for (let r = r1; r <= r2 && fullyDug; r++) {
            for (let c = c1; c <= c2; c++) {
                if (!dugSet.has(r + ',' + c)) { // MAIN LOGIC: found an undug part
                    fullyDug = false;
                    break;
                }
            }
        }
        if (fullyDug) answer++;                  // MAIN LOGIC: count extractable artifact
    }
    return answer;
}

function minimumWeight(n, edges, src1, src2, dest) {
    const adj = Array.from({length:n}, () => []);
    const rev = Array.from({length:n}, () => []);
    for (const [u,v,w] of edges) { adj[u].push([v,w]); rev[v].push([u,w]); }
    function dijkstra(src, graph) {
        const dist = new Array(n).fill(Infinity);
        dist[src] = 0;
        const visited = new Array(n).fill(false);
        const pq = [[0, src]];
        while (pq.length) {
            pq.sort((a,b)=>a[0]-b[0]);
            const [d, u] = pq.shift();
            if (visited[u]) continue;
            visited[u] = true;
            for (const [v, w] of graph[u]) {
                if (dist[u]+w < dist[v]) { dist[v] = dist[u]+w; pq.push([dist[v], v]); }
            }
        }
        return dist;
    }
    const d1 = dijkstra(src1, adj);
    const d2 = dijkstra(src2, adj);
    const d3 = dijkstra(dest, rev);
    let ans = Infinity;
    for (let v = 0; v < n; v++) {
        if (d1[v] < Infinity && d2[v] < Infinity && d3[v] < Infinity) {
            ans = Math.min(ans, d1[v]+d2[v]+d3[v]);
        }
    }
    return ans === Infinity ? -1 : ans;
}

function minOperations(nums) {
    // compute total sum and target reduction
    let total = 0;
    for (let v of nums) total += v;
    const target = total / 2;

    // max‑heap helpers
    function heapPush(heap, val) {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] >= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function heapPop(heap) {
        const max = heap[0];
        const end = heap.pop();
        if (heap.length) {
            heap[0] = end;
            let i = 0;
            while (true) {
                const l = i * 2 + 1;
                const r = i * 2 + 2;
                let largest = i;
                if (l < heap.length && heap[l] > heap[largest]) largest = l;
                if (r < heap.length && heap[r] > heap[largest]) largest = r;
                if (largest === i) break;
                [heap[i], heap[largest]] = [heap[largest], heap[i]];
                i = largest;
            }
        }
        return max;
    }

    // build heap with initial numbers
    const heap = [];
    for (let v of nums) heapPush(heap, v);

    let saved = 0;   // total reduction achieved so far
    let ops = 0;
    // keep halving the current largest element until we reach the target
    while (saved < target) {
        const cur = heapPop(heap);
        const half = cur / 2;
        saved += half;          // we reduced the sum by half of cur
        heapPush(heap, half);   // the reduced value can be used again
        ops++;
    }
    return ops;
}

function maximumSubsequenceCount(text, pattern) {
    const [a, b] = [pattern[0], pattern[1]];
    let countA = 0, countB = 0;
    let pairs = 0n;
    for (const c of text) {
        if (c === b) { pairs += BigInt(countA); countB++; }
        if (c === a) countA++;
    }
    return Number(pairs + BigInt(Math.max(countA, countB)));
}

function minimumWhiteTiles(floor, numCarpets, carpetLen) {
    const n = floor.length;
    const memo = new Map();
    function dfs(i, j) {
        if (i >= n) return 0;
        if (floor[i] === '0') return dfs(i + 1, j); // '0' is black, contributes nothing
        const key = i + ',' + j;
        if (memo.has(key)) return memo.get(key);
        let best = 1 + dfs(i + 1, j); // leave this white ('1') tile visible
        if (j > 0) best = Math.min(best, dfs(i + carpetLen, j - 1)); // start a new carpet exactly here
        memo.set(key, best);
        return best;
    }
    return dfs(0, numCarpets);
}

function divideArray(nums) {
    const freq = {};                     // frequency map
    for (const x of nums) {              // count each number
        freq[x] = (freq[x] || 0) + 1;
    }
    // verify every count is even
    for (const count of Object.values(freq)) {
        if (count % 2 !== 0) return false;
    }
    return true;
}

function countHillValley(nums) {
    // Build a compressed array without consecutive duplicates
    const compressed = [];
    for (let i = 0; i < nums.length; i++) {
        if (i === 0 || nums[i] !== nums[i - 1]) {
            compressed.push(nums[i]);
        }
    }

    // Count peaks (hills) and troughs (valleys) in the compressed array
    let result = 0;
    for (let i = 1; i < compressed.length - 1; i++) {
        if (compressed[i] > compressed[i - 1] && compressed[i] > compressed[i + 1]) {
            result++;                     // hill
        } else if (compressed[i] < compressed[i - 1] && compressed[i] < compressed[i + 1]) {
            result++;                     // valley
        }
    }
    return result;
}

function maximumBobPoints(numArrows, aliceArrows) {
  let bestScore = -1, bestMask = 0;
  for (let mask = 0; mask < 4096; mask++) {
    let used = 0, score = 0;
    for (let i = 0; i < 12; i++) {
      if (mask & (1 << i)) { used += aliceArrows[i] + 1; score += i; }
    }
    if (used <= numArrows && score > bestScore) { bestScore = score; bestMask = mask; }
  }
  const result = new Array(12).fill(0);
  let used = 0;
  for (let i = 0; i < 12; i++) {
    if (bestMask & (1 << i)) { result[i] = aliceArrows[i] + 1; used += result[i]; }
  }
  result[0] += numArrows - used;
  return result;
}

function countCollisions(directions) {
    const arr = directions.split('');
    const stack = [];
    let collisions = 0;
    for (const d of arr) {
        if (d === 'L') {
            let collided = false;
            while (stack.length && stack[stack.length-1] !== 'L') {
                stack.pop();
                collisions++;
                collided = true;
            }
            stack.push(collided ? 'S' : 'L');
        } else {
            stack.push(d);
        }
    }
    return collisions;
}

function longestRepeating(s, queryCharacters, queryIndices) {
  const arr = s.split('');
  const k = queryCharacters.length;
  const result = [];
  function longestRun(str) {
    let best = 1, cur = 1;
    for (let i = 1; i < str.length; i++) {
      if (str[i] === str[i-1]) { cur++; best = Math.max(best, cur); }
      else cur = 1;
    }
    return str.length === 0 ? 0 : best;
  }
  for (let i = 0; i < k; i++) {
    arr[queryIndices[i]] = queryCharacters[i];
    result.push(longestRun(arr));
  }
  return result;
}

function findDifference(nums1, nums2) {
    // build hash sets for fast lookup
    const set1 = new Set(nums1);
    const set2 = new Set(nums2);

    const onlyInFirst = [];
    const onlyInSecond = [];

    // collect elements that are in nums1 but not in nums2
    for (const val of set1) {
        if (!set2.has(val)) onlyInFirst.push(val);
    }

    // collect elements that are in nums2 but not in nums1
    for (const val of set2) {
        if (!set1.has(val)) onlyInSecond.push(val);
    }

    return [onlyInFirst, onlyInSecond];
}

function minDeletionsToMakeBeautiful(nums) {
    let pairs = 0;
    let waiting = null;
    for (let i = 0; i < nums.length; i++) {
        const cur = nums[i];
        if (waiting === null) {
            waiting = cur;
        } else if (cur > waiting) {
            pairs++;
            waiting = null;
        } else {
            waiting = cur;
        }
    }
    return nums.length - pairs * 2;
}

function maxValueOfCoins(piles, k) {
    // pre‑compute prefix sums for every pile
    const pref = piles.map(p => {
        const pre = [0];
        for (let v of p) pre.push(pre[pre.length - 1] + v);
        return pre;                     // pre[x] = sum of first x coins
    });

    const dp = new Array(k + 1).fill(-Infinity);
    dp[0] = 0;                          // zero coins give zero value

    // process piles one by one
    for (let i = 0; i < piles.length; i++) {
        const curPref = pref[i];
        const sz = curPref.length - 1; // number of coins in this pile
        const next = new Array(k + 1).fill(-Infinity);

        // try all total numbers of taken coins
        for (let taken = 0; taken <= k; taken++) {
            // try taking x coins from the current pile
            const maxX = Math.min(sz, taken);
            for (let x = 0; x <= maxX; x++) {
                if (dp[taken - x] === -Infinity) continue;
                const candidate = dp[taken - x] + curPref[x];
                if (candidate > next[taken]) next[taken] = candidate;
            }
        }
        // move to the next pile
        for (let j = 0; j <= k; j++) dp[j] = next[j];
    }

    return dp[k];
}

function kthPalindrome(queries, intLength) {
    const half = Math.ceil(intLength/2);
    const base = 10n ** BigInt(half-1);
    const result = [];
    for (const q of queries) {
        const idx = BigInt(q) - 1n;
        const prefixNum = base + idx;
        const prefixStr = prefixNum.toString();
        if (prefixStr.length > half) { result.push(-1); continue; }
        let s = prefixStr;
        let rev = prefixStr.split('').reverse().join('');
        if (intLength % 2 === 1) rev = rev.substring(1);
        const full = s + rev;
        if (full.length !== intLength) { result.push(-1); continue; }
        result.push(Number(BigInt(full)));
    }
    return result;
}

function numberOfWays(s) {
    const n = s.length;
    if (n < 3) return 0;

    // total counts of each bit
    let totalZero = 0;
    for (let ch of s) if (ch === '0') totalZero++;
    const totalOne = n - totalZero;

    let prefixZero = 0; // zeros seen before current j
    let prefixOne = 0;  // ones  seen before current j
    let answer = 0;

    for (let j = 0; j < n; ++j) {
        let left, right;
        if (s[j] === '0') {
            left = prefixOne;                         // opposite on the left
            right = totalOne - prefixOne;             // opposite on the right
        } else { // s[j] === '1'
            left = prefixZero;
            right = totalZero - prefixZero;
        }
        answer += left * right; // add triples with this j as middle

        // update prefix counters for next position
        if (s[j] === '0') ++prefixZero;
        else ++prefixOne;
    }
    return answer;
}

function minBitFlips(start, goal) {
    // XOR reveals all positions where bits differ
    let diff = start ^ goal;
    let flips = 0;
    // Count the number of set bits in diff
    while (diff) {
        diff &= diff - 1; // remove the lowest set bit
        flips++;
    }
    return flips;
}

// TIME: O(log max(start,goal)) SPACE: O(1)

function triangularSum(nums) {
    // Reduce the array size step by step
    for (let size = nums.length; size > 1; size--) {
        // Compute the next row of the triangle in‑place
        for (let i = 0; i < size - 1; i++) {
            nums[i] = (nums[i] + nums[i + 1]) % 10;
        }
    }
    return nums[0];
}

function minOperations(current, correct) {
    // convert HH:MM to total minutes
    const cur = parseInt(current.slice(0, 2)) * 60 + parseInt(current.slice(3));
    const cor = parseInt(correct.slice(0, 2)) * 60 + parseInt(correct.slice(3));

    // minutes we need to add (handle wrap‑around)
    let diff = cor - cur;
    if (diff < 0) diff += 24 * 60;

    // greedy use of largest possible increments
    const inc = [60, 15, 5, 1];
    let ops = 0;
    for (const d of inc) {
        ops += Math.floor(diff / d);
        diff %= d;
    }
    return ops;
}

function findWinners(matches) {
    const lossCount = new Map();   // player -> number of losses
    const players = new Set();     // all distinct players

    for (const [winner, loser] of matches) {
        players.add(winner);
        players.add(loser);
        lossCount.set(loser, (lossCount.get(loser) || 0) + 1);
    }

    const zeroLoss = [];
    const oneLoss = [];

    for (const p of players) {
        const cnt = lossCount.get(p) || 0;
        if (cnt === 0) zeroLoss.push(p);   // never lost
        else if (cnt === 1) oneLoss.push(p); // lost exactly once
    }

    zeroLoss.sort((a, b) => a - b);
    oneLoss.sort((a, b) => a - b);

    return [zeroLoss, oneLoss];
}

function maximumCandies(candies, k) {
    // find the largest pile – this is the upper bound for the answer
    let maxPile = 0;
    for (let v of candies) if (v > maxPile) maxPile = v;

    let low = 1, high = maxPile, best = 0;

    // binary search on the answer
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);   // candidate candies per child
        let total = 0;
        for (let v of candies) {
            total += Math.floor(v / mid);            // how many children can receive 'mid' candies from this pile
            if (total >= k) break;                  // early stop – we already have enough
        }
        if (total >= k) {            // 'mid' is feasible
            best = mid;
            low = mid + 1;            // try to increase the amount
        } else {
            high = mid - 1;           // need to decrease the amount
        }
    }
    return best;                     // 0 if no feasible amount (e.g., total candies < k)
}

function sumScores(s) {
    const n = s.length;
    const z = new Array(n).fill(0);
    let left = 0, right = 0;

    // Z‑algorithm: compute longest prefix match for each position
    for (let i = 1; i < n; i++) {
        if (i <= right) {
            z[i] = Math.min(right - i + 1, z[i - left]);
        }
        while (i + z[i] < n && s[z[i]] === s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] - 1 > right) {
            left = i;
            right = i + z[i] - 1;
        }
    }

    let total = n;                 // score of the whole string s_n
    for (let i = 1; i < n; i++) {  // add scores of all other prefixes (suffixes)
        total += z[i];
    }
    return total;
}

function Encrypter(keys, values, dictionary) {
    const encMap = {};
    for (let i = 0; i < keys.length; i++) {
        encMap[keys[i]] = values[i];
    }

    const dictCount = {};
    for (const word of dictionary) {
        let enc = "";
        let possible = true;
        for (const ch of word) {
            const pair = encMap[ch];
            if (pair === undefined) {
                possible = false;
                break;
            }
            enc += pair;
        }
        if (possible) {
            dictCount[enc] = (dictCount[enc] || 0) + 1;
        }
    }

    return {
        encrypt: function (word) {
            let enc = "";
            for (const ch of word) {
                const pair = encMap[ch];
                if (pair === undefined) return "";
                enc += pair;
            }
            return enc;
        },
        decrypt: function (code) {
            return dictCount[code] || 0;
        }
    };
}

function largestNumberAfterParitySwaps(num) {
    // convert the number to a string to work with individual digits
    const s = String(num);
    const odd = [];
    const even = [];

    // collect digits by parity
    for (let ch of s) {
        const d = ch.charCodeAt(0) - 48; // faster than Number(ch)
        if (d % 2) odd.push(d);
        else even.push(d);
    }

    // sort each parity group in descending order so the biggest digits are used first
    odd.sort((a, b) => b - a);
    even.sort((a, b) => b - a);

    let oi = 0, ei = 0;
    const result = [];

    // rebuild the number, picking the largest possible digit of the same parity for each position
    for (let ch of s) {
        const d = ch.charCodeAt(0) - 48;
        if (d % 2) result.push(odd[oi++]);
        else result.push(even[ei++]);
    }

    // join back to a string and convert to a number
    return Number(result.join(''));
}

function maxProductAfterKIncrements(nums, k) {
    const MOD = 1000000007n;
    const heap = [];
    function heapPush(val) {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function heapPop() {
        const min = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1;
                let r = i * 2 + 2;
                let smallest = i;
                if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
                if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return min;
    }
    for (let v of nums) heapPush(v);
    for (let i = 0; i < k; i++) {
        const cur = heapPop() + 1;
        heapPush(cur);
    }
    let prod = 1n;
    while (heap.length) {
        prod = (prod * BigInt(heapPop())) % MOD;
    }
    return Number(prod);
}
// TIME: O((n+k)·log n) SPACE: O(n)

function minimizeResult(expression) {
    const plusIdx = expression.indexOf('+');
    const left = expression.slice(0, plusIdx);
    const right = expression.slice(plusIdx+1);
    let bestVal = null, bestStr = "";
    for (let i = 0; i < left.length; i++) {
        const leftOutStr = left.slice(0,i);
        const insideLeftStr = left.slice(i);
        const leftOut = leftOutStr ? parseInt(leftOutStr) : 1;
        const insideLeft = parseInt(insideLeftStr);
        for (let j = 0; j < right.length; j++) {
            const insideRightStr = right.slice(0,j+1);
            const rightOutStr = right.slice(j+1);
            const rightOut = rightOutStr ? parseInt(rightOutStr) : 1;
            const insideRight = parseInt(insideRightStr);
            const val = leftOut * (insideLeft + insideRight) * rightOut;
            if (bestVal === null || val < bestVal) {
                bestVal = val;
                bestStr = leftOutStr + '(' + insideLeftStr + '+' + insideRightStr + ')' + rightOutStr;
            }
        }
    }
    return bestStr;
}

function boundedBisectLeft(arr, val, lo, hi) {
    while (lo < hi) { const mid=(lo+hi)>>1; if (arr[mid]<val) lo=mid+1; else hi=mid; }
    return lo;
}
function maximumBeauty(flowers, newFlowers, target, full, partial) {
    const n = flowers.length;
    flowers = [...flowers].sort((a,b)=>a-b);
    const pref = [0];
    for (const v of flowers) pref.push(pref[pref.length-1]+v);
    const need = flowers.map(v => Math.max(0, target-v));
    const suff = new Array(n+1).fill(0);
    for (let i = n-1; i >= 0; i--) suff[i] = suff[i+1] + need[i];

    let ans = 0;
    if (suff[0] <= newFlowers) ans = Math.max(ans, full*n);

    for (let k = 0; k <= n; k++) {
        const start = n - k;
        const costFull = suff[start];
        if (costFull > newFlowers) break;
        const remaining = newFlowers - costFull;
        if (k === n) { ans = Math.max(ans, full*n); continue; }

        let lo = flowers[0], hi = target - 1;
        if (lo > hi) lo = hi;
        while (lo < hi) {
            const mid = Math.floor((lo+hi+1)/2);
            const pos = boundedBisectLeft(flowers, mid, 0, start);
            const cost = mid*pos - pref[pos];
            if (cost <= remaining) lo = mid; else hi = mid - 1;
        }
        const minVal = lo;
        ans = Math.max(ans, full*k + partial*minVal);
    }
    return ans;
}

