function findClosestNumber(nums) {
    // Initialize with the first element as the current best
    let best = nums[0];
    let bestAbs = Math.abs(best);

    // Scan the array to find the number with smallest distance to zero
    for (let i = 1; i < nums.length; i++) {
        const cur = nums[i];
        const curAbs = Math.abs(cur);

        if (curAbs < bestAbs) {                 // closer to zero
            best = cur;
            bestAbs = curAbs;
        } else if (curAbs === bestAbs && cur > best) { // same distance, larger value wins
            best = cur;
        }
    }
    return best;
}

function countWays(total, cost1, cost2) {
    let ways = 0;
    // iterate over every possible number of pens
    for (let pens = 0; pens * cost1 <= total; pens++) {
        const remaining = total - pens * cost1;
        const maxPencils = Math.floor(remaining / cost2);
        ways += maxPencils + 1; // add all pencil counts from 0 to maxPencils
    }
    return ways;
}

function createATM() {
    const values = [20, 50, 100, 200, 500];   // denominations
    const stock = new Array(5).fill(0);       // current count of each note

    return {
        // add banknotes to the ATM
        deposit: function(notes) {
            for (let i = 0; i < 5; i++) stock[i] += notes[i];
        },

        // try to withdraw the requested amount
        withdraw: function(amount) {
            const used = new Array(5).fill(0);

            // greedy: take as many of the largest notes as possible
            for (let i = 4; i >= 0; i--) {
                const maxTake = Math.min(Math.floor(amount / values[i]), stock[i]);
                used[i] = maxTake;
                amount -= maxTake * values[i];
            }

            // if we couldn't make the exact amount, signal failure
            if (amount !== 0) return [-1];

            // commit the withdrawal
            for (let i = 0; i < 5; i++) stock[i] -= used[i];
            return used;
        }
    };
}

function maximumScore(scores, edges) {
    const n = scores.length;
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
    const top = [];
    for (let i = 0; i < n; i++) {
        const neighbors = [...adj[i]].sort((a,b) => scores[b]-scores[a]);
        top.push(neighbors.slice(0,3));
    }
    let best = -1;
    for (const [u,v] of edges) {
        const candA = top[u].filter(a => a !== v);
        const candD = top[v].filter(d => d !== u);
        for (const a of candA) {
            for (const d of candD) {
                if (a === d) continue;
                const total = scores[a]+scores[u]+scores[v]+scores[d];
                if (total > best) best = total;
            }
        }
    }
    return best;
}

function minimumRounds(tasks) {
    const freq = {};                     // count occurrences of each difficulty
    for (let i = 0; i < tasks.length; i++) {
        const d = tasks[i];
        freq[d] = (freq[d] || 0) + 1;
    }

    let total = 0;
    for (const key in freq) {
        const cnt = freq[key];
        if (cnt === 1) return -1;        // impossible to finish a single task
        if (cnt % 3 === 0) {
            total += cnt / 3;            // all triples
        } else if (cnt % 3 === 2) {
            total += Math.floor(cnt / 3) + 1; // triples + one pair
        } else { // cnt % 3 === 1
            total += (cnt - 4) / 3 + 2; // replace one triple by two pairs
        }
    }
    return total;
}

function calculateDigitSum(s, k) {
    // repeat rounds while the string is longer than k
    while (s.length > k) {
        const newParts = [];
        // process groups of size k
        for (let i = 0; i < s.length; i += k) {
            let sum = 0;
            // sum digits inside the current group
            for (let j = i; j < i + k && j < s.length; ++j) {
                sum += s.charCodeAt(j) - 48; // digit value
            }
            newParts.push(String(sum));
        }
        s = newParts.join('');
    }
    return s;
}

function maxTrailingZeros(grid) {
    const m = grid.length, n = grid[0].length;
    function factors(v) {
        let t2=0,t5=0;
        while (v%2===0){v/=2;t2++;}
        while (v%5===0){v/=5;t5++;}
        return [t2,t5];
    }
    const f = grid.map(row => row.map(factors));
    const rowP = Array.from({length:m}, () => Array.from({length:n+1}, () => [0,0]));
    const colP = Array.from({length:n}, () => Array.from({length:m+1}, () => [0,0]));
    for (let i=0;i<m;i++) for (let j=0;j<n;j++) rowP[i][j+1] = [rowP[i][j][0]+f[i][j][0], rowP[i][j][1]+f[i][j][1]];
    for (let j=0;j<n;j++) for (let i=0;i<m;i++) colP[j][i+1] = [colP[j][i][0]+f[i][j][0], colP[j][i][1]+f[i][j][1]];
    let best = 0;
    for (let i=0;i<m;i++) for (let j=0;j<n;j++) {
        const left = rowP[i][j+1], right = [rowP[i][n][0]-rowP[i][j][0], rowP[i][n][1]-rowP[i][j][1]];
        const up = colP[j][i+1], down = [colP[j][m][0]-colP[j][i][0], colP[j][m][1]-colP[j][i][1]];
        const cell = f[i][j];
        const combos = [
            [left[0]+up[0]-cell[0], left[1]+up[1]-cell[1]],
            [left[0]+down[0]-cell[0], left[1]+down[1]-cell[1]],
            [right[0]+up[0]-cell[0], right[1]+up[1]-cell[1]],
            [right[0]+down[0]-cell[0], right[1]+down[1]-cell[1]],
        ];
        for (const [t2,t5] of combos) best = Math.max(best, Math.min(t2,t5));
    }
    return best;
}

function intersectionMultiple(nums) {
    const arrayCount = nums.length;
    const freqMap = new Map();

    // Count each unique number per sub‑array and track how many arrays contain it
    for (const arr of nums) {
        const seen = new Set();               // deduplicate numbers inside the current array
        for (const num of arr) {
            if (!seen.has(num)) {
                seen.add(num);
                freqMap.set(num, (freqMap.get(num) || 0) + 1);
            }
        }
    }

    const result = [];
    // Keep only numbers that appear in every array
    for (const [num, cnt] of freqMap.entries()) {
        if (cnt === arrayCount) result.push(num);
    }

    result.sort((a, b) => a - b); // optional: return in ascending order
    return result;
}

function countRectangles(rectangles, points) {
  const byHeight = Array.from({length:101}, () => []);
  for (const [l,h] of rectangles) byHeight[h].push(l);
  for (const arr of byHeight) arr.sort((a,b)=>a-b);
  const result = [];
  for (const [x,y] of points) {
