function longestPath(parent, s) {
    const n = parent.length;
    const graph = Array.from({ length: n }, () => []);
    // build undirected adjacency list
    for (let i = 1; i < n; i++) {
        const p = parent[i];
        graph[p].push(i);
        graph[i].push(p);
    }

    let answer = 1; // at least one node

    function dfs(node, prev) {
        let best1 = 0, best2 = 0; // two longest extendable child chains
        for (const nxt of graph[node]) {
            if (nxt === prev) continue;               // avoid going back
            const childLen = dfs(nxt, node);
            if (s[nxt] === s[node]) continue;         // cannot use this edge
            if (childLen > best1) {
                best2 = best1;
                best1 = childLen;
            } else if (childLen > best2) {
                best2 = childLen;
            }
        }
        // combine the two best child chains with the current node
        answer = Math.max(answer, best1 + best2 + 1);
        // return the longest chain that can be extended upward
        return best1 + 1;
    }

    dfs(0, -1);
    return answer;
}

function countLatticePoints(circles) {
    const visited = new Set();                     // store unique points as "x,y"

    for (let i = 0; i < circles.length; i++) {
        const [cx, cy, r] = circles[i];
        const rSq = r * r;

        // iterate over possible x coordinates within the circle
        for (let x = cx - r; x <= cx + r; x++) {
            const dx = x - cx;
            const dxSq = dx * dx;
            if (dxSq > rSq) continue;               // outside the circle horizontally

            // maximum vertical offset that still stays inside the circle
            const dyMax = Math.floor(Math.sqrt(rSq - dxSq));

            // iterate over all y that satisfy the circle equation
            for (let y = cy - dyMax; y <= cy + dyMax; y++) {
                visited.add(`${x},${y}`);           // add point (x,y) to the set
            }
        }
    }

    return visited.size;
}

function fullBloomFlowers(flowers, people) {
    // separate start and end times
    const starts = [];
    const ends = [];
    for (const f of flowers) {
        starts.push(f[0]);
        ends.push(f[1]);
    }
    // sort for binary search
    starts.sort((a, b) => a - b);
    ends.sort((a, b) => a - b);

    // binary search: first index > target
    function upperBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // binary search: first index >= target
    function lowerBound(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    const result = new Array(people.length);
    for (let i = 0; i < people.length; i++) {
        const t = people[i];
        const started = upperBound(starts, t);      // flowers that have started by time t
        const finished = lowerBound(ends, t);       // flowers that ended before time t
        result[i] = started - finished;             // currently blooming
    }
    return result;
}

function minimumAverageDifference(nums) {
    const n = nums.length;
    let totalSum = 0;
    for (let v of nums) totalSum += v;          // total sum of array

    let bestIdx = 0;
    let minDiff = Number.MAX_SAFE_INTEGER;
    let prefixSum = 0;

    for (let i = 0; i < n; i++) {
        prefixSum += nums[i];                    // sum of first i+1 elements
        const leftAvg = Math.floor(prefixSum / (i + 1));

        const rightCount = n - i - 1;
        const rightAvg = rightCount > 0
            ? Math.floor((totalSum - prefixSum) / rightCount) // sum of remaining elements
            : 0;                                                // no elements on the right

        const diff = Math.abs(leftAvg - rightAvg); // average difference at i

        if (diff < minDiff) {                      // update best index
            minDiff = diff;
            bestIdx = i;
        }
    }

    return bestIdx;
}

function countPrefixes(words, s) {
