function countUnguarded(m, n, guards, walls) {
    // 0 = empty, 1 = guard, 2 = wall, 3 = guarded empty cell
    const grid = Array.from({ length: m }, () => Array(n).fill(0));
    const GUARD = 1, WALL = 2, GUARDED = 3;

    // place guards
    for (const [r, c] of guards) grid[r][c] = GUARD;
    // place walls
    for (const [r, c] of walls) grid[r][c] = WALL;

    const dirs = [
        [-1, 0], // north
        [1, 0],  // south
        [0, -1], // west
        [0, 1]   // east
    ];

    // MAIN LOGIC: let each guard scan in the four directions
    for (const [gr, gc] of guards) {
        for (const [dr, dc] of dirs) {
            let r = gr + dr, c = gc + dc;
            while (r >= 0 && r < m && c >= 0 && c < n && grid[r][c] !== WALL && grid[r][c] !== GUARD) {
                if (grid[r][c] === 0) grid[r][c] = GUARDED; // mark as seen
                r += dr;
                c += dc;
            }
        }
    }

    // count cells that stayed empty (0)
    let unguarded = 0;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (grid[i][j] === 0) unguarded++;
        }
    }
    return unguarded;
}


