function maximumMinutes(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = Infinity;
    const fire = Array.from({length:m}, () => new Array(n).fill(INF));
    let q = [];
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) if (grid[i][j]===1) { fire[i][j]=0; q.push([i,j]); }
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    let head = 0;
    while (head < q.length) {
        const [i,j] = q[head++];
        for (const [di,dj] of dirs) {
            const ni=i+di, nj=j+dj;
            if (ni>=0&&ni<m&&nj>=0&&nj<n&&grid[ni][nj]!==2&&fire[ni][nj]===INF) {
                fire[ni][nj] = fire[i][j]+1;
                q.push([ni,nj]);
            }
        }
    }
    function canReach(wait) {
        if (wait >= fire[0][0]) return false;
        const person = Array.from({length:m}, () => new Array(n).fill(INF));
        person[0][0] = wait;
        const q2 = [[0,0]];
        let h2 = 0;
        while (h2 < q2.length) {
            const [i,j] = q2[h2++];
            for (const [di,dj] of dirs) {
                const ni=i+di, nj=j+dj;
                if (ni>=0&&ni<m&&nj>=0&&nj<n&&grid[ni][nj]!==2&&person[ni][nj]===INF) {
                    const t = person[i][j]+1;
                    if (ni===m-1 && nj===n-1) {
                        if (t <= fire[ni][nj]) { person[ni][nj]=t; q2.push([ni,nj]); }
                    } else {
                        if (t < fire[ni][nj]) { person[ni][nj]=t; q2.push([ni,nj]); }
                    }
                }
            }
        }
        return person[m-1][n-1] !== INF;
    }
    if (fire[m-1][n-1] === INF) return canReach(0) ? 1000000000 : -1;
    if (!canReach(0)) return -1;
    let lo = 0, hi = fire[m-1][n-1], ans = 0;
    while (lo <= hi) {
        const mid = Math.floor((lo+hi)/2);
        if (canReach(mid)) { ans = mid; lo = mid+1; }
        else hi = mid-1;
    }
    return ans;
}

function removeDigit(number, digit) {
    const len = number.length;
    let removeIdx = -1;

    // Find the first occurrence where removing it makes the next digit larger
    for (let i = 0; i < len - 1; i++) {
        if (number[i] === digit && number[i] < number[i + 1]) {
            removeIdx = i;
            break;
        }
    }

    // If no such position, remove the last occurrence of the digit
    if (removeIdx === -1) {
        for (let i = len - 1; i >= 0; i--) {
            if (number[i] === digit) {
                removeIdx = i;
                break;
            }
        }
    }

    // Build the result without the chosen character
    return number.slice(0, removeIdx) + number.slice(removeIdx + 1);
}

function countKDivisibleSubarrays(nums, k, p) {
    const MOD1 = 1000000007;
    const MOD2 = 1000000009;
    const BASE = 100007;               // a constant > any element value
    const n = nums.length;
    const seen = new Set();            // stores "hash1,hash2"

    for (let i = 0; i < n; i++) {
        let divCnt = 0;
        let h1 = 0;
        let h2 = 0;
        for (let j = i; j < n; j++) {
            if (nums[j] % p === 0) divCnt++;   // update divisor count
            if (divCnt > k) break;             // further extensions invalid

            // update rolling hashes
            h1 = (h1 * BASE + nums[j]) % MOD1;
            h2 = (h2 * BASE + nums[j]) % MOD2;

            const key = h1 + ',' + h2;          // combine two hashes
            seen.add(key);
        }
    }
    return seen.size;
}

function totalAppeal(s) {
    const n = s.length;
    const lastPos = new Map();          // stores last index of each character
    let total = 0;

    for (let i = 0; i < n; i++) {
        const ch = s[i];
        const prev = lastPos.has(ch) ? lastPos.get(ch) : -1;
        // each occurrence adds (i‑prev) * (n‑i) to the answer
        total += (i - prev) * (n - i);
        lastPos.set(ch, i);
    }
    return total;
}

function minimumCardPickup(cards) {
    const lastPos = new Map();          // stores most recent index of each card value
    let best = Infinity;                // smallest window length found

    for (let i = 0; i < cards.length; i++) {
        const val = cards[i];
        if (lastPos.has(val)) {
            // main logic: a matching pair is found, update minimal length
            const length = i - lastPos.get(val) + 1;
            if (length < best) best = length;
        }
        lastPos.set(val, i);            // update last seen position
    }

    return best === Infinity ? -1 : best;
}

function largestGoodInteger(num) {
    // keep the best digit found so far; empty means none yet
    let best = "";

    // examine every possible length‑3 window
    for (let i = 0; i + 2 < num.length; i++) {
        // MAIN LOGIC: check if the three characters are identical
        if (num[i] === num[i + 1] && num[i] === num[i + 2]) {
            // update best if this digit is larger than the current best
            if (num[i] > best) best = num[i];
        }
    }

    // if a good integer was found, repeat the digit three times
    return best === "" ? "" : best.repeat(3);
}

function countNodesEqualToAverage(root) {
    let answer = 0;

    // post‑order DFS returns [sum of subtree, number of nodes in subtree]
    function dfs(node) {
        if (!node) return [0, 0];
        const left  = dfs(node.left);
        const right = dfs(node.right);

        const sum   = left[0] + right[0] + node.val;
        const count = left[1] + right[1] + 1;
        const avg   = Math.floor(sum / count);   // average of the subtree

        if (node.val === avg) answer++;           // node matches its subtree average

        return [sum, count];
    }

    dfs(root);
    return answer;
}

function countTexts(pressedKeys) {
    const MOD = 1000000007;
    const n = pressedKeys.length;
    const dp3 = new Array(n+1).fill(0);
    const dp4 = new Array(n+1).fill(0);
    dp3[0] = dp4[0] = 1;
    for (let i = 1; i <= n; i++) {
        dp3[i] = dp3[i-1];
        if (i >= 2) dp3[i] = (dp3[i] + dp3[i-2]) % MOD;
        if (i >= 3) dp3[i] = (dp3[i] + dp3[i-3]) % MOD;
        dp4[i] = dp4[i-1];
        if (i >= 2) dp4[i] = (dp4[i] + dp4[i-2]) % MOD;
        if (i >= 3) dp4[i] = (dp4[i] + dp4[i-3]) % MOD;
        if (i >= 4) dp4[i] = (dp4[i] + dp4[i-4]) % MOD;
    }
    let ans = 1;
    let i = 0;
    while (i < n) {
        let j = i;
        while (j < n && pressedKeys[j] === pressedKeys[i]) j++;
        const length = j - i;
        const digit = pressedKeys[i];
        const ways = (digit === '7' || digit === '9') ? dp4[length] : dp3[length];
        ans = (ans * ways) % MOD;
        i = j;
    }
    return ans;
}

function hasValidPath(grid) {
  const m = grid.length, n = grid[0].length;
  if ((m+n-1) % 2 !== 0) return false;
  if (grid[0][0] === ')' || grid[m-1][n-1] === '(') return false;
  const memo = Array.from({length:m}, () => Array.from({length:n}, () => new Map()));
  function dp(i, j, balance) {
    const delta = grid[i][j] === '(' ? 1 : -1;
    const nb = balance + delta;
    if (nb < 0) return false;
    if (i === m-1 && j === n-1) return nb === 0;
    if (memo[i][j].has(nb)) return memo[i][j].get(nb);
    let res = false;
    if (i+1 < m && dp(i+1, j, nb)) res = true;
    if (!res && j+1 < n && dp(i, j+1, nb)) res = true;
    memo[i][j].set(nb, res);
    return res;
  }
  return dp(0, 0, 0);
}

function kBeauty(num, k) {
    const s = String(num);
    const n = s.length;
    if (k > n) return 0;

    // compute 10^(k-1) for removing the leftmost digit in the window
    let power = 1;
    for (let i = 1; i < k; i++) power *= 10;

    // value of the first window of length k
    let cur = 0;
    for (let i = 0; i < k; i++) cur = cur * 10 + (s.charCodeAt(i) - 48);

    let ans = 0;
    if (cur > 0 && num % cur === 0) ans++;               // first window

    // slide the window across the string
    for (let i = k; i < n; i++) {
        const outDigit = s.charCodeAt(i - k) - 48;       // digit leaving the window
        const inDigit = s.charCodeAt(i) - 48;            // digit entering the window
        cur = (cur - outDigit * power) * 10 + inDigit;   // update window value
        if (cur > 0 && num % cur === 0) ans++;           // check divisor condition
    }

    return ans;
}

function numberOfWays(nums) {
    // total sum of the whole array
    let total = 0;
    for (let v of nums) total += v;

    let count = 0;
    let prefix = 0;
    // iterate up to the second‑last element (splits must leave a non‑empty right part)
    for (let i = 0; i < nums.length - 1; i++) {
        prefix += nums[i];                     // update left part sum
        if (prefix * 2 >= total) count++;      // check the split condition
    }
    return count;
}

function maximumWhiteTiles(tiles, carpetLen) {
    tiles = tiles.slice().sort((a, b) => a[0] - b[0]); // the sliding window requires sorted input
    let left = 0, right = 0;
    let cur = 0;
    let ans = 0;
    while (left < tiles.length) {
        while (right < tiles.length && tiles[right][1] <= tiles[left][0] + carpetLen - 1) {
            cur += tiles[right][1] - tiles[right][0] + 1;
            right++;
        }
        let extra = 0;
        if (right < tiles.length) {
            const carpetEnd = tiles[left][0] + carpetLen - 1;
            extra = Math.max(0, carpetEnd - tiles[right][0] + 1);
        }
        ans = Math.max(ans, cur + extra);
        cur -= tiles[left][1] - tiles[left][0] + 1;
        left++;
    }
    return ans;
}

function findResultantArray(words) {
  // helper: true if a and b are anagrams
  function areAnagrams(a, b) {
    if (a.length !== b.length) return false;
    const sort = s => s.split('').sort().join('');
    return sort(a) === sort(b);
  }

  const result = [];
  for (let i = 0; i < words.length; i++) {
    // MAIN LOGIC: keep the word only if it is NOT an anagram of the previous kept word
    if (result.length && areAnagrams(result[result.length - 1], words[i])) {
      continue;               // delete words[i]
    }
    result.push(words[i]);    // keep words[i]
  }
  return result;
}

function largestVariance(s) {
    const chars = [...new Set(s)];
    let best = 0;
    for (const a of chars) {
        for (const b of chars) {
            if (a === b) continue;
            let countA = 0, countB = 0, hasB = false;
            for (let i = 0; i < s.length; i++) {
                if (s[i] === a) countA++;
                else if (s[i] === b) { countB++; hasB = true; }
                if (hasB) best = Math.max(best, countA - countB);
                if (countA < countB) { countA = 0; countB = 0; hasB = false; }
            }
        }
    }
    return best;
}

function maximumBags(capacity, rocks, additionalRocks) {
    const n = capacity.length;
    const need = new Array(n);
    for (let i = 0; i < n; i++) {
        need[i] = capacity[i] - rocks[i];          // rocks needed to fill each bag
    }

    need.sort((a, b) => a - b);                    // smallest needs first

    let fullBags = 0;
    for (let i = 0; i < n; i++) {
        if (additionalRocks >= need[i]) {
            additionalRocks -= need[i];            // use rocks to fill this bag
            fullBags++;                             // this bag is now full
        } else {
            break;                                  // not enough rocks for any larger need
        }
    }
    return fullBags;
}

function largestCombination(candidates) {
    // count how many numbers have each bit set
    const bitCounts = new Array(32).fill(0);
    for (let i = 0; i < candidates.length; i++) {
        let num = candidates[i];
        for (let b = 0; b < 32; b++) {
            if ((num >> b) & 1) bitCounts[b]++;   // main logic
        }
    }

    // the answer is the largest count among all bits
    let maxSize = 0;
    for (let b = 0; b < 32; b++) {
        if (bitCounts[b] > maxSize) maxSize = bitCounts[b]; // main logic
    }
    return maxSize;
}

function maxConsecutive(bottom, top, special) {
    // sort the special floors
    special.sort((a, b) => a - b);

    let maxGap = 0;

    // gap from bottom to the first special floor
    maxGap = Math.max(maxGap, special[0] - bottom);

    // gaps between consecutive special floors
    for (let i = 1; i < special.length; i++) {
        // number of non‑special floors between special[i‑1] and special[i]
        const gap = special[i] - special[i - 1] - 1;
        if (gap > maxGap) maxGap = gap;
    }

    // gap from the last special floor to top
    maxGap = Math.max(maxGap, top - special[special.length - 1]);

    return maxGap;
}

function CountIntervals() {
    const intervals = [];          // sorted list of disjoint intervals [l, r]
    let total = 0;                 // total number of covered integers

    function add(left, right) {
        // binary search for first interval with start >= left
        let lo = 0, hi = intervals.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (intervals[mid][0] < left) lo = mid + 1;
            else hi = mid;
        }
        let idx = lo;

        // if previous interval touches/overlaps, start merging from it
        if (idx > 0 && intervals[idx - 1][1] + 1 >= left) idx--;

        let newL = left, newR = right;

        // merge every overlapping or adjacent interval
        while (idx < intervals.length && intervals[idx][0] <= right + 1) {
            const [l, r] = intervals[idx];
            newL = Math.min(newL, l);
            newR = Math.max(newR, r);
            total -= (r - l + 1);          // remove its contribution
            intervals.splice(idx, 1);      // delete it
        }

        // insert the merged interval and update total
        intervals.splice(idx, 0, [newL, newR]);
        total += (newR - newL + 1);
    }

    function count() {
        return total;
    }

    return { add, count };
}

function percentageLetter(s, letter) {
    // count how many times `letter` appears in `s`
    let matchCount = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === letter) matchCount++;
    }
    // avoid division by zero for empty string
    if (s.length === 0) return 0;
    // compute floor of the percentage
    return Math.floor((matchCount / s.length) * 100);
}

function totalStrength(strength) {
    const MOD = 1000000007n;
    const n = strength.length;
    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    let stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && strength[stack[stack.length-1]] >= strength[i]) stack.pop();
        left[i] = stack.length ? stack[stack.length-1] : -1;
        stack.push(i);
    }
    stack = [];
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && strength[stack[stack.length-1]] > strength[i]) stack.pop();
        right[i] = stack.length ? stack[stack.length-1] : n;
        stack.push(i);
    }

    // P[k] = sum of strength[0..k-1], P has length n+1
    const P = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) P[i+1] = P[i] + BigInt(strength[i]);
    // S[k] = sum of P[0..k-1], S has length n+2
    const S = new Array(n + 2).fill(0n);
    for (let i = 0; i <= n; i++) S[i+1] = S[i] + P[i];

    let ans = 0n;
    for (let i = 0; i < n; i++) {
        const l = left[i], r = right[i];
        const leftCount = i - l;
        const rightCount = r - i;
        const sumR = ((S[r+1] - S[i+1]) % MOD + MOD) % MOD;
        const sumL = ((S[i+1] - S[l+1]) % MOD + MOD) % MOD;
        let contribution = (BigInt(leftCount) * sumR - BigInt(rightCount) * sumL) % MOD;
        contribution = (contribution % MOD + MOD) % MOD;
        ans = (ans + BigInt(((strength[i] % 1000000007) + 1000000007) % 1000000007) * contribution) % MOD;
    }
    return Number(ans);
}

function checkNumber(num) {
    // count how many times each digit appears
    const freq = new Array(10).fill(0);
    for (let ch of num) {
        freq[ch.charCodeAt(0) - 48]++;   // '0' -> 48
    }

    // verify the condition for each index i present in the string
    for (let i = 0; i < num.length; i++) {
        const required = num.charCodeAt(i) - 48; // numeric value of num[i]
        if (freq[i] !== required) return false;
    }
    return true;
}

function largestWordCount(messages, senders) {
    const countMap = {};                     // map sender → total words

    for (let i = 0; i < messages.length; i++) {
        const sender = senders[i];
        const words = messages[i].split(' ').length; // words in current message
        countMap[sender] = (countMap[sender] || 0) + words;
    }

    let bestSender = '';
    let maxWords = -1;

    for (const sender in countMap) {
        const total = countMap[sender];
        if (total > maxWords || (total === maxWords && sender > bestSender)) {
            maxWords = total;
            bestSender = sender;
        }
    }

    return bestSender;
}

function minLines(stockPrices) {
    if (stockPrices.length < 2) return 0;

    // sort by day (x-coordinate)
    stockPrices.sort((a, b) => a[0] - b[0]);

    let count = 0;
    let prevSlope = null;

    // helper: greatest common divisor
    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    for (let i = 1; i < stockPrices.length; i++) {
        let dy = stockPrices[i][1] - stockPrices[i - 1][1];
        let dx = stockPrices[i][0] - stockPrices[i - 1][0];

        const g = gcd(Math.abs(dy), Math.abs(dx));
        dy /= g;
        dx /= g;

        if (dx < 0) {          // normalize sign so dx is non‑negative
            dy = -dy;
            dx = -dx;
        }

        // start a new line when the slope differs from the previous one
        if (prevSlope === null || dy !== prevSlope[0] || dx !== prevSlope[1]) {
            count++;
            prevSlope = [dy, dx];
        }
    }

    return count;
}

function maximumImportance(n, roads) {
    const degree = new Array(n).fill(0);
    for (const [u, v] of roads) {
        degree[u]++;               // count edge for u
        degree[v]++;               // count edge for v
    }

    // sort degrees so that higher degree nodes get higher values
    const sortedDegrees = degree.slice().sort((a, b) => b - a);

    let currentValue = n;
    let totalImportance = 0;
    for (const deg of sortedDegrees) {
        totalImportance += deg * currentValue; // each node contributes its value to all incident edges
        currentValue--;
    }
    return totalImportance;
}

function minimumObstacles(grid) {
    const m = grid.length, n = grid[0].length;
    const INF = 1e9;
    const dist = Array.from({length:m}, () => new Array(n).fill(INF));
    const dq = [[0,0]];
    dist[0][0] = 0;
    const directions = [[1,0],[-1,0],[0,1],[0,-1]];
    let head = 0;
    while (head < dq.length) {
        const [x,y] = dq[head]; // deque semantics via head/tail with occasional unshift
        head++;
        if (x === m-1 && y === n-1) return dist[x][y];
        const current = dist[x][y];
        for (const [dx,dy] of directions) {
            const nx = x+dx, ny = y+dy;
            if (nx>=0 && nx<m && ny>=0 && ny<n) {
                const nd = current + grid[nx][ny];
                if (nd < dist[nx][ny]) {
                    dist[nx][ny] = nd;
                    if (grid[nx][ny] === 0) { dq.splice(head, 0, [nx,ny]); }
                    else { dq.push([nx,ny]); }
                }
            }
        }
    }
    return dist[m-1][n-1];
}

function maxCopies(s, target) {
    // count letters in s
    const sCount = {};
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        sCount[ch] = (sCount[ch] || 0) + 1;
    }

    // count letters in target
    const tCount = {};
    for (let i = 0; i < target.length; i++) {
        const ch = target[i];
        tCount[ch] = (tCount[ch] || 0) + 1;
    }

    // compute max copies based on character frequencies
    let copies = Infinity;
    for (const ch in tCount) {
        if (!sCount[ch]) return 0;                // missing character
        copies = Math.min(copies, Math.floor(sCount[ch] / tCount[ch]));
    }
    return copies === Infinity ? 0 : copies;
}

function discountPrices(sentence, discount) {
    // split the sentence into words
    const words = sentence.split(' ');
    // process each word
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        // a price word must start with '$' and the rest are digits only
        if (w.length > 1 && w[0] === '$' && /^\d+$/.test(w.slice(1))) {
            const original = Number(w.slice(1));               // numeric value of the price
            const discounted = original * (100 - discount) / 100; // apply discount
            const formatted = discounted.toFixed(2);           // exactly two decimals
            words[i] = '$' + formatted;                        // replace with new price
        }
    }
    // re‑join the words into a sentence
    return words.join(' ');
}

function totalSteps(nums) {
  const n = nums.length;
  const stack = []; // stores [value, stepsToRemove]
  let ans = 0;
  for (let i = n - 1; i >= 0; i--) {
    let maxSteps = 0;
    while (stack.length && stack[stack.length-1][0] < nums[i]) {
      maxSteps = Math.max(maxSteps, stack.pop()[1]);
    }
    const steps = stack.length === 0 ? 0 : maxSteps + 1;
    ans = Math.max(ans, steps);
    stack.push([nums[i], steps]);
  }
  return ans;
}

function BookMyShow(n, m) {
    const rem = new Array(n).fill(m);
    const size = 4 * n;
    const sum = new Array(size).fill(0);
    const mx = new Array(size).fill(0);

    const build = (node, l, r) => {
        if (l === r) {
            sum[node] = m;
            mx[node] = m;
        } else {
            const mid = (l + r) >> 1;
            build(node * 2, l, mid);
            build(node * 2 + 1, mid + 1, r);
            pull(node);
        }
    };

    const pull = (node) => {
        sum[node] = sum[node * 2] + sum[node * 2 + 1];
        mx[node] = Math.max(mx[node * 2], mx[node * 2 + 1]);
    };

    const update = (node, l, r, idx, val) => {
        if (l === r) {
            sum[node] = val;
            mx[node] = val;
        } else {
            const mid = (l + r) >> 1;
            if (idx <= mid) update(node * 2, l, mid, idx, val);
            else update(node * 2 + 1, mid + 1, r, idx, val);
            pull(node);
        }
    };

    const querySum = (node, l, r, ql, qr) => {
        if (ql > r || qr < l) return 0;
        if (ql <= l && r <= qr) return sum[node];
        const mid = (l + r) >> 1;
        return querySum(node * 2, l, mid, ql, qr) + querySum(node * 2 + 1, mid + 1, r, ql, qr);
    };

    const queryMax = (node, l, r, ql, qr) => {
        if (ql > r || qr < l) return -Infinity;
        if (ql <= l && r <= qr) return mx[node];
        const mid = (l + r) >> 1;
        return Math.max(
            queryMax(node * 2, l, mid, ql, qr),
            queryMax(node * 2 + 1, mid + 1, r, ql, qr)
        );
    };

    const findFirst = (node, l, r, qr, need) => {
        if (l > qr || mx[node] < need) return -1;
        if (l === r) return l;
        const mid = (l + r) >> 1;
        const left = findFirst(node * 2, l, mid, qr, need);
        if (left !== -1) return left;
        return findFirst(node * 2 + 1, mid + 1, r, qr, need);
    };

    build(1, 0, n - 1);

    const gather = (k, maxRow) => {
        if (queryMax(1, 0, n - 1, 0, maxRow) < k) return [];
        const row = findFirst(1, 0, n - 1, maxRow, k);
        const start = m - rem[row];
        rem[row] -= k;
        update(1, 0, n - 1, row, rem[row]);
        return [row, start];
    };

    const scatter = (k, maxRow) => {
        if (querySum(1, 0, n - 1, 0, maxRow) < k) return false;
        while (k > 0) {
            const row = findFirst(1, 0, n - 1, maxRow, 1);
            const take = Math.min(rem[row], k);
            rem[row] -= take;
            update(1, 0, n - 1, row, rem[row]);
            k -= take;
        }
        return true;
    };

    return { gather, scatter };
}
// TIME: O(log n) per gather, O(log n + rows touched) per scatter  SPACE: O(n) for segment tree and arrays

function designTextEditor(operations, args) {
    const left = [];   // characters left of cursor
    const right = [];  // characters right of cursor
    const res = [];

    for (let i = 0; i < operations.length; i++) {
        const op = operations[i];

        if (op === "TextEditor") {
            res.push(null);                       // constructor
        } else if (op === "addText") {
            const s = args[i][0];
            for (let ch of s) left.push(ch);      // add characters before cursor
            res.push(null);
        } else if (op === "deleteText") {
            let k = args[i][0];
            let cnt = 0;
            while (cnt < k && left.length) {      // delete up to k chars left of cursor
                left.pop();
                cnt++;
            }
            res.push(cnt);
        } else if (op === "cursorLeft") {
            let k = args[i][0];
            let moved = 0;
            while (moved < k && left.length) {    // move cursor left
                right.push(left.pop());
                moved++;
            }
            const preview = left.slice(-10).join(''); // last up to 10 chars left of cursor
            res.push(preview);
        } else if (op === "cursorRight") {
            let k = args[i][0];
            let moved = 0;
            while (moved < k && right.length) {   // move cursor right
                left.push(right.pop());
                moved++;
            }
            const preview = left.slice(-10).join('');
            res.push(preview);
        }
    }
    return res;
}


// TIME: O(k) per operation (k = number of characters moved/deleted); overall O(total characters processed)  
// SPACE: O(N) where N is the total number of characters stored in the editor.

function minMaxGame(nums) {
    // repeat until one element remains
    while (nums.length > 1) {
        const next = [];
        for (let i = 0; i < nums.length; i += 2) {
            const pairIdx = i / 2;
            if (pairIdx % 2 === 0) {
                next.push(Math.min(nums[i], nums[i + 1]));
            } else {
                next.push(Math.max(nums[i], nums[i + 1]));
            }
        }
        nums = next;
    }
    return nums[0];
}

function minNumberOfSubsequences(nums, k) {
    if (nums.length === 0) return 0;                 // empty array

    const sorted = nums.slice().sort((a, b) => a - b); // sort ascending

    let groups = 0;
    let i = 0;
    while (i < sorted.length) {
        groups++;                                     // start a new subsequence
        const start = sorted[i];                     // its minimum value
        while (i < sorted.length && sorted[i] - start <= k) {
            i++;                                      // add element while within k
        }
    }
    return groups;
}

function replaceElements(nums, operations) {
    // map each value to its current index for O(1) lookup
    const indexMap = new Map();
    for (let i = 0; i < nums.length; i++) {
        indexMap.set(nums[i], i);
    }

    // process each replacement operation
    for (const [oldVal, newVal] of operations) {
        const idx = indexMap.get(oldVal);   // find where the old value is
        nums[idx] = newVal;                 // replace it in the array
        indexMap.delete(oldVal);            // remove old mapping
        indexMap.set(newVal, idx);          // add new mapping
    }

    return nums;
}

function successfulPairs(spells, potions, success) {
    // sort potions so we can binary‑search thresholds
    potions.sort((a, b) => a - b);
    const m = potions.length;
    const result = [];

    // binary search: first index with value >= target
    function lowerBound(arr, target) {
        let left = 0, right = arr.length;
        while (left < right) {
            const mid = left + ((right - left) >> 1);
            if (arr[mid] < target) left = mid + 1;
            else right = mid;
        }
        return left;
    }

    for (let i = 0; i < spells.length; i++) {
        const spell = spells[i];
        // minimum potion strength needed to reach 'success'
        const need = Math.ceil(success / spell);
        const idx = lowerBound(potions, need);
        result.push(m - idx); // potions from idx to end are successful
