function calculateTax(brackets, income) {
    let tax = 0;
    let lower = 0;
    for (let i = 0; i < brackets.length; i++) {
        const [upper, percent] = brackets[i];
        if (income <= lower) break;
        const portion = Math.min(income, upper) - lower;
        tax += portion * percent / 100;
        lower = upper;
    }
