function countSubarrays(nums, k) {
    if (k <= 0) return 0;               // no positive score can be < non‑positive k
    let left = 0;
    let sum = 0;
    let answer = 0;

    for (let right = 0; right < nums.length; right++) {
        sum += nums[right];               // extend window to the right

        // shrink window until (sum * length) < k
        while (left <= right && sum * (right - left + 1) >= k) {
            sum -= nums[left];
            left++;
