        // all subarrays ending at 'right' and starting anywhere from 'left' to 'right' are valid
        answer += right - left + 1;
    }

    return answer;
}

function minPathCost(grid, moveCost) {
    const m = grid.length;
    const n = grid[0].length;

    // cost to reach each cell of the first row = its own value
    let prev = grid[0].slice();

    // process rows 1 .. m-1
    for (let i = 1; i < m; i++) {
        const cur = new Array(n).fill(Infinity);
        // MAIN LOGIC: transition from previous row to current row
        for (let j = 0; j < n; j++) {               // target column in current row
            for (let k = 0; k < n; k++) {           // source column in previous row
                const candidate = prev[k] + moveCost[grid[i - 1][k]][j] + grid[i][j];
                if (candidate < cur[j]) cur[j] = candidate;
