function distributeCookies(cookies, k) {
    // sort descending to fail early on large bags
    cookies.sort((a, b) => b - a);
    const total = cookies.reduce((s, v) => s + v, 0);
    const maxBag = cookies[0];

    // binary search on the answer
    let low = maxBag, high = total;
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (canFit(mid)) high = mid;          // MAIN LOGIC: feasible → try smaller bound
        else low = mid + 1;                    // MAIN LOGIC: not feasible → need larger bound
    }
    return low;

    // check if all bags can be assigned without any child exceeding `limit`
    function canFit(limit) {
        const load = new Array(k).fill(0);

        function dfs(idx) {
            if (idx === cookies.length) return true; // all bags placed
            const cur = cookies[idx];
            for (let i = 0; i < k; i++) {
                if (load[i] + cur <= limit) {
                    load[i] += cur;
                    if (dfs(idx + 1)) return true; // MAIN LOGIC: successful placement
                    load[i] -= cur;
                }
                // symmetry pruning: if this child is still empty, no need to try other empty children
                if (load[i] === 0) break;
