function maxProfit(m, n, prices) {
    // store the best price for each exact shape
    const priceMap = new Map();
    for (const [h, w, p] of prices) {
        const key = h + ',' + w;
        const cur = priceMap.get(key) || 0;
        if (p > cur) priceMap.set(key, p);
    }

    // memo[h][w] will hold the optimal profit for a h×w piece
    const memo = Array.from({ length: m + 1 }, () => Array(n + 1).fill(undefined));

    function dfs(h, w) {
        if (memo[h][w] !== undefined) return memo[h][w];

        // start with the price of selling the piece whole (if allowed)
        let best = priceMap.get(h + ',' + w) || 0;

        // try every possible vertical cut
        for (let cut = 1; cut < w; cut++) {
            const left = dfs(h, cut);
            const right = dfs(h, w - cut);
            const combined = left + right;
            if (combined > best) best = combined;
        }

        // try every possible horizontal cut
        for (let cut = 1; cut < h; cut++) {
            const top = dfs(cut, w);
            const bottom = dfs(h - cut, w);
            const combined = top + bottom;
            if (combined > best) best = combined;
        }

        memo[h][w] = best;
        return best;
    }

    return dfs(m, n);
}
