function distinctNames(ideas) {
    // 1. group suffixes by their first letter
    const groups = Array.from({ length: 26 }, () => new Set());
    for (const w of ideas) {
        const first = w.charCodeAt(0) - 97;          // 0 … 25
        const suffix = w.slice(1);
        groups[first].add(suffix);
