function countUnreachablePairs(n, edges) {
    // initialize Union‑Find
    const parent = new Array(n);
    const size = new Array(n).fill(1);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        // union by size
        if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        size[ra] += size[rb];
    }

    // build components
    for (const [u, v] of edges) union(u, v);

    // collect sizes of distinct components
    const compSize = new Map();
    for (let i = 0; i < n; i++) {
        const root = find(i);
        compSize.set(root, (compSize.get(root) || 0) + 1);
    }

    // count pairs across different components
    let result = 0;
    let remaining = n;
    for (const sz of compSize.values()) {
        remaining -= sz;               // nodes left after removing this component
        result += sz * remaining;      // pairs between this component and the rest
    }
    return result;
}

