function countDistinctRollSequences(n) {
    const MOD = 1000000007n;
    const gcd = (a, b) => { while (b) { [a, b] = [b, a % b]; } return a; };
    if (n === 1) return 6;

    // dp[prev][prevprev] = count of sequences ending with ...prevprev, prev
    // values 1..6, use 0 for "no prevprev" at the start
    let dp = {};
    for (let a = 1; a <= 6; a++) {
        for (let b = 1; b <= 6; b++) {
            if (a === b) continue;
            if (gcd(a, b) !== 1) continue;
            const key = `${b}_${a}`; // prev=b, prevprev=a
            dp[key] = (dp[key] || 0n) + 1n;
        }
    }
    // dp now represents sequences of length 2: prevprev=a, prev=b

    for (let len = 3; len <= n; len++) {
        const ndp = {};
        for (const key in dp) {
            const [prevStr, prevprevStr] = key.split('_');
            const prev = Number(prevStr), prevprev = Number(prevprevStr);
            const cnt = dp[key];
            for (let v = 1; v <= 6; v++) {
                if (v === prev) continue;
                if (v === prevprev) continue;
                if (gcd(v, prev) !== 1) continue;
                const nkey = `${v}_${prev}`;
                ndp[nkey] = ((ndp[nkey] || 0n) + cnt) % MOD;
            }
        }
        dp = ndp;
    }

    let total = 0n;
    for (const key in dp) total = (total + dp[key]) % MOD;
    return Number(total);
}

