function spiralMatrix(m, n, head) {
    // create empty matrix
    const matrix = Array.from({ length: m }, () => Array(n).fill(-1));

    let top = 0,
        bottom = m - 1,
        left = 0,
        right = n - 1;
    let node = head;

    while (top <= bottom && left <= right) {
        // left → right on the current top row
        for (let col = left; col <= right; col++) {
            if (node) {
                matrix[top][col] = node.val;
                node = node.next;
            }
        }
        top++;

        // top → bottom on the current right column
        for (let row = top; row <= bottom; row++) {
            if (node) {
                matrix[row][right] = node.val;
                node = node.next;
            }
        }
        right--;

        // right → left on the current bottom row
        if (top <= bottom) {
            for (let col = right; col >= left; col--) {
                if (node) {
                    matrix[bottom][col] = node.val;
                    node = node.next;
                }
            }
            bottom--;
        }

        // bottom → top on the current left column
        if (left <= right) {
            for (let row = bottom; row >= top; row--) {
                if (node) {
                    matrix[row][left] = node.val;
                    node = node.next;
                }
            }
            left++;
        }
    }

    return matrix;
}

function peopleAwareOfSecret(n, delay, forget) {
    const MOD = 1_000_000_007;
    const dp = new Array(n + 1).fill(0);
    const start = new Array(n + 1).fill(0);
    const end = new Array(n + 1).fill(0);

    dp[1] = 1;                                   // day 1: the first person learns
    if (1 + delay <= n) start[1 + delay] = 1;   // becomes active after `delay`
    if (1 + forget <= n) end[1 + forget] = 1;   // forgets after `forget`

    let active = 0; // people that can share today

    for (let day = 2; day <= n; day++) {
        // update active count with people that start or stop sharing today
        active = (active + start[day]) % MOD;               // MAIN LOGIC
        active = (active - end[day] + MOD) % MOD;           // MAIN LOGIC

        dp[day] = active;                                   // MAIN LOGIC

        // schedule future activation and forgetting for the new learners
        const actDay = day + delay;
        if (actDay <= n) start[actDay] = (start[actDay] + dp[day]) % MOD;
        const finDay = day + forget;
        if (finDay <= n) end[finDay] = (end[finDay] + dp[day]) % MOD;
    }

    // sum people that have not forgotten the secret by day n
    let result = 0;
    for (let i = 1; i <= n; i++) {
        if (i + forget > n) {
            result = (result + dp[i]) % MOD;
        }
    }
    return result;
}

function maximumScore(nums1, nums2) {
    let sum1 = 0, sum2 = 0;
    // compute total sums of both arrays
    for (let i = 0; i < nums1.length; i++) {
        sum1 += nums1[i];
        sum2 += nums2[i];
    }

    let bestDiff = 0, curDiff = 0;      // Kadane for diff = nums2 - nums1
    let bestNeg = 0, curNeg = 0;        // Kadane for -diff = nums1 - nums2

    for (let i = 0; i < nums1.length; i++) {
        const diff = nums2[i] - nums1[i];

        // update Kadane for diff
        curDiff = Math.max(diff, curDiff + diff);
        bestDiff = Math.max(bestDiff, curDiff);

        // update Kadane for -diff
        const neg = -diff;
        curNeg = Math.max(neg, curNeg + neg);
        bestNeg = Math.max(bestNeg, curNeg);
    }

    // choose the better of swapping to improve nums1 or to improve nums2
    return Math.max(sum1 + bestDiff, sum2 + bestNeg);
}

function minimumScore(nums, edges) {
    const n = nums.length;
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }

    const parent = new Array(n).fill(-1);
    const tin = new Array(n).fill(0);
    const tout = new Array(n).fill(0);
    const subXor = new Array(n).fill(0);
    let timer = 0;

    function dfs(u, p) {
        parent[u] = p;
        tin[u] = timer++;
        subXor[u] = nums[u];
        for (const v of adj[u]) {
            if (v !== p) {
                dfs(v, u);
                subXor[u] ^= subXor[v];
            }
        }
        tout[u] = timer++;
    }
    dfs(0, -1);

    function isAncestor(u, v) {
        // is u an ancestor of v?
        return tin[u] <= tin[v] && tout[v] <= tout[u];
    }

    const totalXor = subXor[0];
    let best = Infinity;
    for (let i = 1; i < n; i++) {
        for (let j = i+1; j < n; j++) {
            let a, b, c;
            if (isAncestor(i, j)) {
                a = subXor[j];
                b = subXor[i] ^ subXor[j];
                c = totalXor ^ subXor[i];
            } else if (isAncestor(j, i)) {
                a = subXor[i];
                b = subXor[j] ^ subXor[i];
                c = totalXor ^ subXor[j];
            } else {
                a = subXor[i];
                b = subXor[j];
                c = totalXor ^ subXor[i] ^ subXor[j];
            }
            const mx = Math.max(a,b,c), mn = Math.min(a,b,c);
            best = Math.min(best, mx - mn);
        }
    }
    return best;
}

function decodeMessage(key, message) {
    const cipherToPlain = {};                 // map cipher letter → plain letter
    let nextPlainCode = 97;                   // ASCII code for 'a'

    // build substitution table from key
    for (let i = 0; i < key.length; i++) {
        const ch = key[i];
        if (ch === ' ') continue;             // ignore spaces
        if (!(ch in cipherToPlain)) {
            cipherToPlain[ch] = String.fromCharCode(nextPlainCode);
            nextPlainCode++;
        }
    }

    // decode the message using the table
    let decoded = '';
    for (let i = 0; i < message.length; i++) {
        const ch = message[i];
        decoded += ch === ' ' ? ' ' : cipherToPlain[ch];
    }
