}

function latestTimeCatchTheBus(buses, passengers, capacity) {
    // sort times so we can process chronologically
    buses.sort((a, b) => a - b);
    passengers.sort((a, b) => a - b);

    const passengerSet = new Set(passengers);   // for O(1) existence checks
    let pIdx = 0;                               // pointer in passengers array
    let answer = -1;                            // best feasible time found

    for (let bus of buses) {
        let boarded = 0;                        // how many passengers got on this bus

        // board earliest passengers that can catch this bus
        while (pIdx < passengers.length && passengers[pIdx] <= bus && boarded < capacity) {
            boarded++;
            pIdx++;
        }

        let candidate;
        if (boarded < capacity) {
            // bus still has a free seat → we could arrive exactly at its departure time
            candidate = bus;
        } else {
            // bus is full → we must arrive before the last passenger who boarded
            candidate = passengers[pIdx - 1] - 1;
        }

        // move left while the candidate time is already taken by another passenger
        while (passengerSet.has(candidate)) {
            candidate--;
        }

        // keep the latest feasible moment over all buses
        if (candidate > answer) {
            answer = candidate;
        }
    }

    return answer;
}

var countPaths = function(grid) {
    const MOD = 1000000007;
