    const cells = [];
    for (let i=0;i<m;i++) for (let j=0;j<n;j++) cells.push([grid[i][j], i, j]);
    cells.sort((a,b)=>a[0]-b[0]);
    const dp = Array.from({length:m}, () => new Array(n).fill(1));
    let ans = 0;
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    for (const [val, i, j] of cells) {
