function evaluateTree(root) {
    // leaf node: its value directly represents the boolean
    if (root.left === null && root.right === null) {
        return root.val === 1;
    }

    // evaluate left and right subtrees
    const leftVal = evaluateTree(root.left);
    const rightVal = evaluateTree(root.right);

    // OR node (value 2) or AND node (value 3)
    if (root.val === 2) {
        return leftVal || rightVal;   // OR operation
    } else { // root.val === 3
        return leftVal && rightVal;   // AND operation
    }
