function canChange(start, target) {
    const n = start.length;
    let i = 0, j = 0;

    // iterate through both strings, skipping '_' characters
    while (i < n && j < n) {
        while (i < n && start[i] === '_') i++;
        while (j < n && target[j] === '_') j++;

        // if one string ends before the other, pieces differ
        if ((i < n) !== (j < n)) return false;

        // both reached the end
        if (i === n && j === n) break;

        // pieces must be of the same type
        if (start[i] !== target[j]) return false;

        // 'L' can only move left, so its start index must be >= target index
        if (start[i] === 'L' && i < j) return false;

        // 'R' can only move right, so its start index must be <= target index
        if (start[i] === 'R' && i > j) return false;

        i++;
        j++;
    }

    // any remaining non-'_' characters mean mismatch
    while (i < n) if (start[i++] !== '_') return false;
    while (j < n) if (target[j++] !== '_') return false;

    return true;
