                let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
                if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return min;
    }

    return {
        popSmallest: function () {
            if (heap.length) {
                const val = heapPop();
                inHeap.delete(val);
                return val;
            }
            return next++;
        },

        addBack: function (num) {
            if (num < next && !inHeap.has(num)) {
                heapPush(num);
                inHeap.add(num);
            }
        }
    };
}

function idealArrays(n, maxValue) {
    const MOD = 1000000007n;
    const maxFact = n + maxValue;
    const fact = new Array(maxFact+1).fill(1n);
    for (let i = 1; i <= maxFact; i++) fact[i] = (fact[i-1]*BigInt(i))%MOD;
    function modpow(base,exp,mod) { base%=mod; let r=1n; while(exp>0n){ if(exp&1n) r=(r*base)%mod; base=(base*base)%mod; exp>>=1n;} return r; }
    const invFact = new Array(maxFact+1).fill(1n);
    invFact[maxFact] = modpow(fact[maxFact], MOD-2n, MOD);
    for (let i = maxFact; i > 0; i--) invFact[i-1] = (invFact[i]*BigInt(i))%MOD;
    function comb(a,b) {
        if (b<0||b>a) return 0n;
        return fact[a]*invFact[b]%MOD*invFact[a-b]%MOD;
    }
    const spf = Array.from({length:maxValue+1}, (_,i)=>i);
    const limit = Math.floor(Math.sqrt(maxValue))+1;
    for (let i = 2; i < limit; i++) {
        if (spf[i]===i) {
            for (let j = i*i; j <= maxValue; j += i) if (spf[j]===j) spf[j]=i;
        }
    }
    let ans = 0n;
    for (let v = 1; v <= maxValue; v++) {
        let x = v, ways = 1n;
        while (x > 1) {
            const p = spf[x];
            let e = 0;
            while (x % p === 0) { x = Math.floor(x/p); e++; }
            ways = ways * comb(e+n-1, e) % MOD;
        }
        ans = (ans + ways) % MOD;
    }
    return Number(ans);
}

function validSubarraySize(nums, threshold) {
    const n = nums.length;
    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    const stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && nums[stack[stack.length-1]] >= nums[i]) stack.pop();
        left[i] = stack.length ? stack[stack.length-1] : -1;
        stack.push(i);
    }
    stack.length = 0;
    for (let i = n-1; i >= 0; i--) {
        while (stack.length && nums[stack[stack.length-1]] >= nums[i]) stack.pop();
        right[i] = stack.length ? stack[stack.length-1] : n;
        stack.push(i);
    }
    for (let i = 0; i < n; i++) {
        const width = right[i] - left[i] - 1;
        if (nums[i] > threshold / width) return width;
    }
    return -1;
}

function minSumSquareDiff(nums1, nums2, k1, k2) {
  const n = nums1.length;
  const diff = new Array(n);
  for (let i = 0; i < n; i++) diff[i] = Math.abs(nums1[i] - nums2[i]);
  let budget = k1 + k2;
  function canReduceToAtMost(cap) {
    let need = 0;
    for (const d of diff) if (d > cap) need += d - cap;
    return need <= budget;
  }
  let lo = 0, hi = Math.max(...diff);
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (canReduceToAtMost(mid)) hi = mid; else lo = mid + 1;
  }
  // apply reduction to cap = lo, using remaining leftover budget to reduce some at cap further by 1
  const reduced = diff.map(d => Math.min(d, lo));
  let used = 0;
  for (let i = 0; i < n; i++) used += diff[i] - reduced[i];
  let leftover = budget - used;
  for (let i = 0; i < n && leftover > 0; i++) {
    if (reduced[i] === lo && lo > 0) { reduced[i]--; leftover--; }
  }
  let sum = 0n;
  for (const d of reduced) sum += BigInt(d) * BigInt(d);
  return Number(sum);
}

function smallestTrimmedNumbers(nums, queries) {
    const n = nums.length;
    const answers = new Array(queries.length);

    for (let q = 0; q < queries.length; q++) {
        const [k, trim] = queries[q];

        // build an array of objects {idx, trimmed}
        const items = new Array(n);
        for (let i = 0; i < n; i++) {
            const trimmed = nums[i].slice(-trim);          // keep last `trim` digits
            items[i] = { idx: i, val: parseInt(trimmed, 10) };
        }

        // sort by trimmed value, then by original index
        items.sort((a, b) => {
            if (a.val !== b.val) return a.val - b.val;    // numeric order
            return a.idx - b.idx;                         // tie‑break by index
        });

        answers[q] = items[k - 1].idx;                    // k‑th smallest (1‑based)
    }

    return answers;
}

function minDeletion(nums, numsDivide) {
  // helper to compute gcd of two numbers
  function gcd(a, b) {
    while (b !== 0) {
      const t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  // compute gcd of all elements in numsDivide
  let common = numsDivide[0];
  for (let i = 1; i < numsDivide.length; i++) {
    common = gcd(common, numsDivide[i]);
  }

  // sort nums so we can delete smallest elements first
  nums.sort((a, b) => a - b);

  // find the first element that divides the common gcd
  for (let i = 0; i < nums.length; i++) {
    if (common % nums[i] === 0) return i; // deletions needed
  }

  return -1; // impossible
}

function maxSumPair(nums) {
    // helper to compute sum of digits
    function digitSum(n) {
        let s = 0;
        while (n > 0) {
            s += n % 10;
            n = Math.floor(n / 10);
        }
        return s;
    }

    const top = {};               // digit sum -> [largest, secondLargest]
    let best = -1;

    for (let value of nums) {
        const d = digitSum(value);

        if (!top[d]) {
            // first occurrence of this digit sum
            top[d] = [value, -Infinity];
        } else {
            const [max1, max2] = top[d];

            // use the current value with the largest seen so far
            best = Math.max(best, max1 + value);   // main logic

            // keep the two largest numbers for this digit sum
            if (value > max1) {
                top[d] = [value, max1];
            } else if (value > max2) {
                top[d][1] = value;
            }
        }
    }

    return best;
}

function maxPairs(nums) {
    // count occurrences of each value
    const freq = {};
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        freq[v] = (freq[v] || 0) + 1;
    }

    let pairs = 0;
    // compute pairs from each frequency
    for (const key in freq) {
        pairs += Math.floor(freq[key] / 2);
    }

    const leftover = nums.length - pairs * 2; // elements that cannot be paired
    return [pairs, leftover];
}

function countZeroFilledSubarrays(nums) {
    let total = 0;          // total number of zero-filled subarrays
    let consecutive = 0;    // length of current consecutive zeros

    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 0) {
            consecutive += 1;          // extend the current zero streak
            total += consecutive;      // each new zero creates 'consecutive' subarrays ending here
        } else {
            consecutive = 0;           // reset when a non‑zero appears
        }
    }

    return total;
}

function shortestSequence(rolls, k) {
    const n = rolls.length;
    // nextPos[i][c] = first index >= i where rolls[idx] == c, or -1 if none
    const nextPos = Array.from({ length: n + 1 }, () => Array(k + 1).fill(-1));
    for (let i = n - 1; i >= 0; i--) {
        for (let c = 1; c <= k; c++) {
            nextPos[i][c] = nextPos[i + 1][c];
        }
        const v = rolls[i];
        nextPos[i][v] = i;
    }
    const dp = Array(n + 1).fill(0);
    dp[n] = 1; // after the end, any single value is impossible
    for (let i = n - 1; i >= 0; i--) {
        let best = Infinity;
        for (let c = 1; c <= k; c++) {
            const nxt = nextPos[i][c];
            const cand = nxt === -1 ? 1 : 1 + dp[nxt + 1];
            if (cand < best) best = cand;
        }
        dp[i] = best;
    }
    return dp[0];
}

function NumberContainers() {
    const indexToNum = new Map();
    const numToHeap = new Map();

    class MinHeap {
        constructor() { this.arr = []; }
        peek() { return this.arr[0]; }
        push(val) {
            const a = this.arr;
            a.push(val);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (a[p] <= a[i]) break;
                [a[p], a[i]] = [a[i], a[p]];
                i = p;
            }
        }
        pop() {
            const a = this.arr;
            if (a.length === 0) return undefined;
            const root = a[0];
            const last = a.pop();
            if (a.length) {
                a[0] = last;
                let i = 0;
                while (true) {
                    let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                    if (l < a.length && a[l] < a[smallest]) smallest = l;
                    if (r < a.length && a[r] < a[smallest]) smallest = r;
                    if (smallest === i) break;
                    [a[i], a[smallest]] = [a[smallest], a[i]];
                    i = smallest;
                }
            }
            return root;
        }
        size() { return this.arr.length; }
    }

    return {
        add: function (number, index) {
            // FIXED: original special-cased number===0 as a "delete this index" signal
            // and never actually stored a 0 value - but 0 is a perfectly legal number for
            // this problem, so add(0, index) silently failed to make later query(0) find it.
            indexToNum.set(index, number);
            if (!numToHeap.has(number)) numToHeap.set(number, new MinHeap());
            numToHeap.get(number).push(index);
        },

        query: function (number) {
            const heap = numToHeap.get(number);
            if (!heap) return -1;
            while (heap.size() && indexToNum.get(heap.peek()) !== number) heap.pop();
            return heap.size() ? heap.peek() : -1;
        }
    };
}

function bestPokerHand(ranks, suits) {
    const isFlush = suits.every(s => s === suits[0]);
    if (isFlush) return "Flush";

    const rankCount = {};
    let maxCount = 0;
    for (const r of ranks) {
        rankCount[r] = (rankCount[r] || 0) + 1;
        if (rankCount[r] > maxCount) maxCount = rankCount[r];
    }

    if (maxCount >= 3) return "Three of a Kind";
    if (maxCount === 2) return "Pair";
    return "High Card";
}

function countExcellentPairs(nums, k) {
    const distinct = [...new Set(nums)];
    const bits = distinct.map(v => { let c=0,x=v; while(x){c+=x&1;x>>>=1;} return c; });
    const cnt = new Array(32).fill(0);
    for (const b of bits) cnt[b]++;
    let total = 0n;
    for (let i = 0; i < 32; i++) for (let j = 0; j < 32; j++) {
        if (i+j >= k) total += BigInt(cnt[i])*BigInt(cnt[j]);
    }
    return Number(total);
}

function firstLetterToAppearTwice(s) {
    const seen = new Set();               // track letters we have encountered
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (seen.has(ch)) return ch;      // first letter whose second occurrence appears
        seen.add(ch);
    }
    return ''; // fallback if no letter appears twice
}

function equalPairs(grid) {
    const n = grid.length;
    const rowMap = new Map();

    // store each row as a string and count its occurrences
    for (let i = 0; i < n; i++) {
        const key = grid[i].join(',');
        rowMap.set(key, (rowMap.get(key) || 0) + 1);
    }

    let result = 0;

    // build each column, turn it into a string, and add matching row count
    for (let j = 0; j < n; j++) {
        const col = [];
        for (let i = 0; i < n; i++) col.push(grid[i][j]);
        const key = col.join(',');
        result += rowMap.get(key) || 0;
    }

    return result;
}

function FoodRatings(foods, cuisines, ratings) {
    const foodToCuisine = {};
    const foodToRating = {};
    const cuisineHeap = {};

    function heapCompare(a, b) {
        if (a.rating !== b.rating) return a.rating > b.rating;
        return a.food < b.food;
    }
    function heapPush(heap, node) {
        heap.push(node);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heapCompare(heap[p], heap[i])) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function heapPop(heap) {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let left = i * 2 + 1, right = i * 2 + 2, best = i;
                if (left < heap.length && heapCompare(heap[left], heap[best])) best = left;
                if (right < heap.length && heapCompare(heap[right], heap[best])) best = right;
                if (best === i) break;
                [heap[i], heap[best]] = [heap[best], heap[i]];
                i = best;
            }
        }
        return top;
    }
    function heapPeek(heap) { return heap[0]; }

    for (let i = 0; i < foods.length; i++) {
        const food = foods[i], cuisine = cuisines[i], rating = ratings[i];
        foodToCuisine[food] = cuisine;
        foodToRating[food] = rating;
        if (!cuisineHeap[cuisine]) cuisineHeap[cuisine] = [];
        heapPush(cuisineHeap[cuisine], { food, rating });
    }

    return {
        changeRating(food, newRating) {
            const cuisine = foodToCuisine[food];
            foodToRating[food] = newRating;
            heapPush(cuisineHeap[cuisine], { food, rating: newRating });
        },
        highestRated(cuisine) {
            const heap = cuisineHeap[cuisine];
            while (heap.length) {
                const top = heapPeek(heap);
                if (top.rating === foodToRating[top.food]) return top.food;
                heapPop(heap);
            }
            return "";
        }
    };
}

function makeArrayZero(nums) {
    const distinct = new Set();
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] > 0) {
            distinct.add(nums[i]);   // count distinct positive numbers
        }
    }
    return distinct.size;
}

function closestMeetingNode(edges, node1, node2) {
    const n = edges.length;
    const dist1 = new Array(n).fill(-1);
    const dist2 = new Array(n).fill(-1);

    // traverse from node1 and record distances
    let cur = node1, step = 0;
    while (cur !== -1 && dist1[cur] === -1) {
        dist1[cur] = step++;
        cur = edges[cur];
    }

    // traverse from node2 and record distances
    cur = node2; step = 0;
    while (cur !== -1 && dist2[cur] === -1) {
        dist2[cur] = step++;
        cur = edges[cur];
    }

    let bestNode = -1;
    let bestDist = Infinity;

    // find node reachable from both with minimal maximal distance
    for (let i = 0; i < n; i++) {
        if (dist1[i] !== -1 && dist2[i] !== -1) {
            const curMax = Math.max(dist1[i], dist2[i]);
            if (curMax < bestDist || (curMax === bestDist && i < bestNode)) {
                bestDist = curMax;
                bestNode = i;
            }
        }
    }
    return bestNode;
}

function maxGroups(grades) {
    // the actual grade VALUES don't matter at all - grades can be freely sorted
    // and assigned, so this reduces purely to: what's the max k such that
    // group sizes 1,2,3,...,k (summing to k*(k+1)/2) fit within n students?
    const n = grades.length;
    let k = 0, total = 0;
    while (total + k + 1 <= n) {
        k++;
        total += k;
    }
    return k;
}

function taskSchedulerII(tasks, space) {
    const lastDay = new Map();
    let day = 0;
    for (const t of tasks) {
        const prior = lastDay.get(t);
        // a task type's FIRST occurrence has no cooldown constraint at all - using a
        // default of 0 in its place wrongly forces an artificial wait until day=space+1
        const earliest = prior === undefined ? day + 1 : Math.max(day + 1, prior + space + 1);
        day = earliest;
        lastDay.set(t, day);
    }
    return day;
}

function longestCycle(edges) {
    const n = edges.length;
    const visited = new Array(n).fill(false);
    let maxLen = -1;

    for (let start = 0; start < n; start++) {
        if (visited[start]) continue;

        const stepMap = new Map();
        let cur = start;
        let step = 0;

        while (cur !== -1) {
            if (stepMap.has(cur)) {
                // found a cycle - check this BEFORE the visited check, so a node
                // revisited within the CURRENT walk is correctly detected as a cycle
                const cycleLen = step - stepMap.get(cur);
                if (cycleLen > maxLen) maxLen = cycleLen;
                break;
            }
            if (visited[cur]) break; // reached a node from an earlier, already-finished walk
            stepMap.set(cur, step);
            visited[cur] = true;
            cur = edges[cur];
            step++;
        }
    }
    return maxLen;
}

function minimumReplacement(nums) {
    let operations = 0;
    let limit = nums[nums.length - 1];          // rightmost element stays as is

    for (let i = nums.length - 2; i >= 0; i--) {
        if (nums[i] <= limit) {
            limit = nums[i];                    // no split needed
        } else {
            const parts = Math.ceil(nums[i] / limit); // minimal k
            operations += parts - 1;            // operations for this element
            limit = Math.floor(nums[i] / parts); // new maximal value on the left
        }
    }
    return operations;
}

function validPartition(nums) {
    const n = nums.length;
    const dp = new Array(n + 1).fill(false);
    dp[0] = true;                         // empty prefix is trivially valid

    for (let i = 2; i <= n; i++) {
        // pair of equal numbers
        if (dp[i - 2] && nums[i - 2] === nums[i - 1]) {
            dp[i] = true;
        }
        // three equal numbers
        if (!dp[i] && i >= 3 && dp[i - 3] &&
            nums[i - 3] === nums[i - 2] && nums[i - 2] === nums[i - 1]) {
            dp[i] = true;
        }
        // three consecutive increasing numbers
        if (!dp[i] && i >= 3 && dp[i - 3] &&
            nums[i - 3] + 1 === nums[i - 2] && nums[i - 2] + 1 === nums[i - 1]) {
            dp[i] = true;
        }
    }
    return dp[n];
}

function numberOfArithmeticTriplets(nums, diff) {
    const numSet = new Set(nums);
    let count = 0;
    for (let middle of nums) {
        // count a triplet when both neighbors at distance diff exist
        if (numSet.has(middle - diff) && numSet.has(middle + diff)) {
            count++;
        }
    }
    return count;
}

function countBadPairs(nums) {
    const n = nums.length;
    const totalPairs = n * (n - 1) / 2;   // all possible (i, j)
    let goodPairs = 0;
    const freq = new Map();               // diff → occurrences

    for (let i = 0; i < n; i++) {
        const diff = i - nums[i];
        // each previous occurrence of the same diff forms a good pair with i
        if (freq.has(diff)) {
            goodPairs += freq.get(diff);
            freq.set(diff, freq.get(diff) + 1);
        } else {
            freq.set(diff, 1);
        }
    }
    return totalPairs - goodPairs;
}

function mergeSimilarItems(items1, items2) {
    const weightMap = new Map();                 // accumulate weights by value

    // add weights from the first array
    for (const [value, weight] of items1) {
        weightMap.set(value, (weightMap.get(value) || 0) + weight);
    }

    // add weights from the second array
    for (const [value, weight] of items2) {
        weightMap.set(value, (weightMap.get(value) || 0) + weight);
    }

    // transform map to sorted array of [value, totalWeight]
    const result = Array.from(weightMap.entries())
        .sort((a, b) => a[0] - b[0])               // sort by value ascending
        .map(([value, totalWeight]) => [value, totalWeight]);

    return result;
}

function largestLocal(grid) {
    const n = grid.length;
    const size = n - 2;
    const maxLocal = Array.from({ length: size }, () => Array(size).fill(0));

    for (let i = 0; i < size; i++) {
        for (let j = 0; j < size; j++) {
            let curMax = -Infinity;
            // examine the 3×3 block whose top‑left corner is (i, j)
            for (let r = i; r < i + 3; r++) {
                for (let c = j; c < j + 3; c++) {
                    if (grid[r][c] > curMax) curMax = grid[r][c];
                }
            }
            maxLocal[i][j] = curMax;
        }
    }
    return maxLocal;
}

function reachableNodes(n, edges, restricted) {
    // build adjacency list
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }

    const restrictedSet = new Set(restricted);
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    let reachableCount = 0;

    // DFS from node 0, skipping restricted nodes
    while (stack.length) {
        const node = stack.pop();
        reachableCount++;

        for (const neighbor of graph[node]) {
            if (!visited[neighbor] && !restrictedSet.has(neighbor)) {
                visited[neighbor] = true;
                stack.push(neighbor);
            }
        }
    }

    return reachableCount;
}

function nodeWithHighestEdgeScore(edges) {
    const n = edges.length;
    const scores = new Array(n).fill(0);

    // accumulate edge scores: each node i contributes its label to its target
    for (let i = 0; i < n; i++) {
        scores[edges[i]] += i;
    }

    // find node with maximum score (smallest index on ties)
    let bestNode = 0;
    let maxScore = scores[0];
    for (let i = 1; i < n; i++) {
        if (scores[i] > maxScore) {
            maxScore = scores[i];
            bestNode = i;
        }
    }
    return bestNode;
}

function longestIdealString(s, k) {
  const dp = new Array(26).fill(0);
  let best = 0;
  for (const ch of s) {
    const c = ch.charCodeAt(0) - 97;
    let cur = 1;
    for (let d = Math.max(0, c-k); d <= Math.min(25, c+k); d++) {
      cur = Math.max(cur, dp[d] + 1);
    }
    dp[c] = Math.max(dp[c], cur);
    best = Math.max(best, dp[c]);
  }
  return best;
}

function countSpecialNumbers(n) {
    function perm(m, k) {
        let res = 1;
        for (let i = 0; i < k; i++) res *= (m - i);
        return res;
    }
    const s = String(n);
    const length = s.length;
    let total = 0;
    for (let l = 1; l < length; l++) total += 9 * perm(9, l-1);

    const used = new Set();
    let brokeEarly = false;
    for (let i = 0; i < s.length; i++) {
        const cur = parseInt(s[i]);
        const start = (i === 0) ? 1 : 0;
        for (let d = start; d < cur; d++) {
            if (used.has(d)) continue;
            const remainingPositions = length - i - 1;
            const remainingDigits = 10 - (i + 1);
            total += perm(remainingDigits, remainingPositions);
        }
        if (used.has(cur)) { brokeEarly = true; break; }
        used.add(cur);
    }
    if (!brokeEarly) total += 1;
    return total;
