function shiftingLettersII(s, shifts) {
    const n = s.length;
    const diff = new Array(n + 1).fill(0);          // difference array for range updates

    // apply each shift as a range increment/decrement
    for (let i = 0; i < shifts.length; i++) {
        const [l, r, dir] = shifts[i];
        const delta = dir === 1 ? 1 : -1;           // forward = +1, backward = -1
        diff[l] += delta;
        diff[r + 1] -= delta;
    }

    // compute prefix sums and build the resulting string
    let cur = 0;
    const result = new Array(n);
    for (let i = 0; i < n; i++) {
        cur += diff[i];                              // total shift for position i
        const shift = ((cur % 26) + 26) % 26;        // normalize to [0,25]
        const originalCode = s.charCodeAt(i) - 97;  // 0‑based alphabet index
        const newCode = (originalCode + shift) % 26;
        result[i] = String.fromCharCode(newCode + 97);
    }

    return result.join('');
}

function constructSmallestNumber(pattern) {
    const n = pattern.length;
    const result = [];
    const stack = [];

    for (let i = 0; i <= n; i++) {
        stack.push(i + 1);
        // flush the stack when we see an 'I' or reach the end
        if (i === n || pattern[i] === 'I') {
            while (stack.length) {
                result.push(stack.pop());
            }
        }
    }
    return result.join('');
}

function largestPalindromic(num) {
    const cnt = new Array(10).fill(0);
    for (let ch of num) cnt[ch.charCodeAt(0) - 48]++;

    let left = "";
    for (let d = 9; d >= 0; d--) {
        const pairs = Math.floor(cnt[d] / 2);
        if (pairs > 0) left += String(d).repeat(pairs);
        cnt[d] -= pairs * 2;
    }

    let middle = "";
    for (let d = 9; d >= 0; d--) {
        if (cnt[d] > 0) { middle = String(d); break; }
    }

    // if left is empty OR made up entirely of zeros (any non-zero digit pair would
    // always appear before zero-pairs in "left", since we build descending from 9),
    // a leading zero would result - fall back to just the middle digit (or "0")
    if (left === "" || left[0] === '0') {
        return middle === "0" || middle === "" ? "0" : middle;
    }

    const right = left.split('').reverse().join('');
    return left + middle + right;
}

function minRecolors(blocks, k) {
    const n = blocks.length;
    // count whites in the first window of size k
    let whiteCount = 0;
    for (let i = 0; i < k; i++) {
        if (blocks[i] === 'W') whiteCount++;
    }
    let minWhite = whiteCount;                     // minimal recolors found so far

    // slide the window across the string
    for (let i = k; i < n; i++) {
        // remove the leftmost character of the previous window
        if (blocks[i - k] === 'W') whiteCount--;
        // add the new rightmost character
        if (blocks[i] === 'W') whiteCount++;
        // update answer
        if (whiteCount < minWhite) minWhite = whiteCount;
    }
    return minWhite;
}

function kSum(nums, k) {
    let total = 0;
    const arr = [];
    for (const x of nums) {
        if (x >= 0) total += x;
        arr.push(Math.abs(x));
    }
    arr.sort((a,b) => a-b);
    if (k === 1) return total;
    const n = arr.length;
    const heap = [[arr[0], 0]];
    function push(item) {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i-1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function pop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = 2*i+1, r = 2*i+2, smallest = i;
                if (l < heap.length && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.length && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    }
    let sum = 0;
    for (let i = 1; i < k; i++) {
        const [s, idx] = pop();
        sum = s;
        if (idx + 1 < n) {
            push([s - arr[idx] + arr[idx+1], idx+1]);
            push([s + arr[idx+1], idx+1]);
        }
    }
    return total - sum;
}

function amountOfTime(root, start) {
    const adj = {};

    // Build undirected graph from the binary tree
    function dfs(node, parent) {
        if (!node) return;
        if (!adj[node.val]) adj[node.val] = [];
        if (parent) {
            if (!adj[parent.val]) adj[parent.val] = [];
            adj[node.val].push(parent.val);
            adj[parent.val].push(node.val);
        }
        dfs(node.left, node);
        dfs(node.right, node);
    }
    dfs(root, null);

    // BFS from the start node to find the farthest distance
    const visited = new Set();
    const queue = [start];
    visited.add(start);
    let minutes = -1;               // counts levels; start node is level 0

    while (queue.length) {
        const size = queue.length;
        for (let i = 0; i < size; i++) {
            const cur = queue.shift();
            for (const nb of (adj[cur] || [])) {
                if (!visited.has(nb)) {
                    visited.add(nb);
                    queue.push(nb);
                }
            }
        }
        minutes++;                  // one minute passes after each level
    }
    return minutes;
}

function removeStars(s) {
