    // Iterate through the string, applying the star‑removal rule
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        if (ch === '*') {
            if (stack.length) stack.pop();    // '*' removes the closest previous character
        } else {
            stack.push(ch);                    // keep ordinary characters
        }
    }
    return stack.join('');                     // convert the stack back to a string
}

function longestSubsequenceWithLimitedSum(nums, queries) {
    // sort numbers to pick the smallest ones first
    const sorted = [...nums].sort((a, b) => a - b);

    // build prefix sums of the sorted array
    const prefix = new Array(sorted.length);
    let running = 0;
    for (let i = 0; i < sorted.length; i++) {
        running += sorted[i];
        prefix[i] = running;
    }

    const answers = new Array(queries.length);
    for (let q = 0; q < queries.length; q++) {
        const limit = queries[q];
        // binary search the largest prefix sum ≤ limit
        let lo = 0, hi = sorted.length - 1, best = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (prefix[mid] <= limit) {
                best = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        answers[q] = best + 1; // +1 because indices are 0‑based
    }
    return answers;
}

