var buildMatrix = function(k, rowConditions, colConditions) {
    function topoSort(k, edges) {
        const adj = Array.from({length:k+1}, () => []);
        const indeg = new Array(k+1).fill(0);
        const seen = new Set();
        for (const [u,v] of edges) {
            const key = u+','+v;
            if (seen.has(key)) continue;
            seen.add(key);
            adj[u].push(v);
            indeg[v]++;
        }
        const q = [];
        for (let i=1;i<=k;i++) if (indeg[i]===0) q.push(i);
        let head = 0;
        const order = [];
        while (head < q.length) {
            const node = q[head++];
            order.push(node);
            for (const nb of adj[node]) {
                indeg[nb]--;
                if (indeg[nb]===0) q.push(nb);
            }
        }
        return order.length === k ? order : null;
    }
    const colOrder = topoSort(k, colConditions);
    if (colOrder === null) return [];
    const colPos = {};
    colOrder.forEach((num,idx)=>colPos[num]=idx);

    const adj = Array.from({length:k+1}, () => []);
    const indeg = new Array(k+1).fill(0);
    const seen = new Set();
    for (const [u,v] of rowConditions) {
        const key = u+','+v;
        if (seen.has(key)) continue;
        seen.add(key);
        adj[u].push(v);
        indeg[v]++;
    }
    let heap = [];
    for (let i=1;i<=k;i++) if (indeg[i]===0) heap.push([colPos[i], i]);
    heap.sort((a,b)=>a[0]-b[0]);
    const rowOrder = [];
    while (heap.length) {
        const item = heap.shift();
        const node = item[1];
        rowOrder.push(node);
        for (const nb of adj[node]) {
            indeg[nb]--;
            if (indeg[nb]===0) {
                heap.push([colPos[nb], nb]);
                heap.sort((a,b)=>a[0]-b[0]);
            }
        }
    }
    if (rowOrder.length !== k) return [];
    const rowPos = {};
    rowOrder.forEach((num,idx)=>rowPos[num]=idx);
    const matrix = Array.from({length:k}, () => new Array(k).fill(0));
    for (let num=1; num<=k; num++) {
        const r = rowPos[num], c = colPos[num];
        matrix[r][c] = num;
    }
    return matrix;
};

function findSubarraysWithEqualSum(nums) {
    // If there are fewer than two elements, no subarray of length 2 exists
    if (nums.length < 2) return false;

    const seenSums = new Set();               // store sums of subarrays of length 2

    for (let i = 0; i < nums.length - 1; i++) {
        const sum = nums[i] + nums[i + 1];     // sum of current subarray

        // if this sum was seen before, we have two subarrays with equal sum
        if (seenSums.has(sum)) return true;

        seenSums.add(sum);
    }

    return false;
}

