function maxRowsCovered(matrix, numSelect) {
    const m = matrix.length;
    const n = matrix[0].length;

    // pre‑compute bitmask for each row
    const rowMasks = new Array(m);
    for (let i = 0; i < m; i++) {
        let mask = 0;
        for (let j = 0; j < n; j++) {
            if (matrix[i][j] === 1) mask |= (1 << j);
        }
        rowMasks[i] = mask;
    }

    let best = 0;

    // backtrack over all column subsets of size numSelect
    function dfs(start, chosenMask, chosenCnt) {
        if (chosenCnt === numSelect) {
            // evaluate current subset
            let covered = 0;
            for (let i = 0; i < m; i++) {
                if ((rowMasks[i] & ~chosenMask) === 0) covered++;
            }
            if (covered > best) best = covered;
            return;
        }
        for (let col = start; col < n; col++) {
            dfs(col + 1, chosenMask | (1 << col), chosenCnt + 1);
        }
    }

    dfs(0, 0, 0);
    return best;
}



