function maxRobots(chargeTimes, runningCosts, budget) {
    const n = chargeTimes.length;
    let left = 0;
    let sumRunning = 0;
    let best = 0;
    const maxDeque = []; // stores indices, decreasing chargeTimes

    for (let right = 0; right < n; right++) {
        sumRunning += runningCosts[right];                     // add new running cost

        // keep deque decreasing so front is current max charge
        while (maxDeque.length && chargeTimes[maxDeque[maxDeque.length - 1]] <= chargeTimes[right]) {
            maxDeque.pop();
        }
        maxDeque.push(right);

        // shrink left side while total cost exceeds budget
        while (left <= right) {
            const currentMax = chargeTimes[maxDeque[0]];
            const totalCost = currentMax + (right - left + 1) * sumRunning;
            if (totalCost <= budget) break;

            if (maxDeque[0] === left) maxDeque.shift();      // remove leaving max if needed
            sumRunning -= runningCosts[left];                // remove its running cost
            left++;
        }

        best = Math.max(best, right - left + 1);               // update answer
    }
    return best;
}

function numberOfWays(startPos, endPos, k) {
    const MOD = 1000000007n;
    const delta = endPos - startPos;
    const d = Math.abs(delta);
    if (d > k || (k-d) % 2 !== 0) return 0;
    const r = (k + delta) / 2;
    if (r < 0 || r > k) return 0;
    const fact = new Array(k+1).fill(1n);
    for (let i = 1; i <= k; i++) fact[i] = (fact[i-1]*BigInt(i))%MOD;
    function modpow(base,exp,mod) { base%=mod; let res=1n; while(exp>0n){ if(exp&1n) res=(res*base)%mod; base=(base*base)%mod; exp>>=1n;} return res; }
    const invFact = new Array(k+1).fill(1n);
    invFact[k] = modpow(fact[k], MOD-2n, MOD);
    for (let i = k; i > 0; i--) invFact[i-1] = (invFact[i]*BigInt(i))%MOD;
    return Number(fact[k]*invFact[r]%MOD*invFact[k-r]%MOD);
}

function longestNiceSubarray(nums) {
    let left = 0;          // left border of sliding window
    let mask = 0;          // OR of all bits inside the window
    let best = 0;          // longest length found

    for (let right = 0; right < nums.length; right++) {
        const cur = nums[right];

        // shrink window while current number shares a set bit with the window
        while ((mask & cur) !== 0) {
            mask ^= nums[left]; // remove leftmost element's bits (they are unique)
            left++;
        }

        mask |= cur;                     // add current element to window
        const len = right - left + 1;    // current window size
        if (len > best) best = len;      // update answer
    }

    return best;
}

function mostBooked(n, meetings) {
    // sort meetings by start time
    meetings.sort((a, b) => a[0] - b[0]);

    // ---------- heap helpers ----------
    function pushHeap(heap, node, cmp) {
        heap.push(node);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (cmp(heap[p], node) <= 0) break;
            heap[i] = heap[p];
            i = p;
        }
        heap[i] = node;
    }

    function popHeap(heap, cmp) {
        if (heap.length === 0) return undefined;
        const top = heap[0];
        const last = heap.pop();
        if (heap.length > 0) {
            let i = 0;
            while (true) {
                const left = i * 2 + 1;
                const right = left + 1;
                if (left >= heap.length) break;
                let smallest = left;
                if (right < heap.length && cmp(heap[right], heap[left]) < 0) {
                    smallest = right;
                }
                if (cmp(heap[smallest], last) >= 0) break;
                heap[i] = heap[smallest];
                i = smallest;
            }
            heap[i] = last;
        }
        return top;
    }
    // -----------------------------------

    // min‑heap of free room indices
    const freeRooms = [];
    for (let i = 0; i < n; ++i) pushHeap(freeRooms, i, (a, b) => a - b);

    // min‑heap of busy rooms ordered by (end time, room index)
    const busyRooms = [];

    const count = new Array(n).fill(0);

    for (const [start, end] of meetings) {
        // release rooms that have become free by current start time
        while (busyRooms.length && busyRooms[0].end <= start) {
            const freed = popHeap(busyRooms, (a, b) => a.end - b.end || a.room - b.room);
            pushHeap(freeRooms, freed.room, (a, b) => a - b);
        }

        if (freeRooms.length) {
            // assign to the smallest free room
            const room = popHeap(freeRooms, (a, b) => a - b);
            count[room] += 1;
            pushHeap(busyRooms, { end: end, room }, (a, b) => a.end - b.end || a.room - b.room);
        } else {
            // delay: take the room that becomes free the earliest
            const earliest = popHeap(busyRooms, (a, b) => a.end - b.end || a.room - b.room);
            const duration = end - start;
            const newEnd = earliest.end + duration;
            count[earliest.room] += 1;
            pushHeap(busyRooms, { end: newEnd, room: earliest.room }, (a, b) => a.end - b.end || a.room - b.room);
        }
    }

    // find room with maximum meetings (tie → smallest index)
    let bestRoom = 0;
    for (let i = 1; i < n; ++i) {
        if (count[i] > count[bestRoom]) bestRoom = i;
    }
    return bestRoom;
}

function isGoodArray(nums) {
    function gcd(a, b) {
        // calculate the greatest common divisor of two numbers using Euclidean algorithm
        if (b === 0) return a;
        return gcd(b, a % b);
    }
    let result = nums[0];
    // iterate through the array to calculate the greatest common divisor of all numbers
    for (let i = 1; i < nums.length; i++) {
        result = gcd(result, nums[i]);
    }
    // if the greatest common divisor is 1, the array is good
    return result === 1;
}

function removeSubfolders(folder) {
