}

function minimumSwap(s1, s2) {
    let xy = 0, yx = 0; // xy: positions where s1='x' and s2='y'; yx: the reverse
    for (let i = 0; i < s1.length; i++) {
        if (s1[i] !== s2[i]) {
            if (s1[i] === 'x') xy++; else yx++;
        }
    }
    if ((xy + yx) % 2 === 1) return -1;
    // each matched "xy & xy" pair takes 1 swap, each "yx & yx" pair takes 1 swap;
    // one leftover xy plus one leftover yx (when both counts are odd) takes 2 swaps
    return Math.floor(xy / 2) + Math.floor(yx / 2) + (xy % 2) * 2;
}

function minRemoveToMakeValid(s) {
    let stack = []; // store indices of opening parentheses
    let toRemove = new Set(); // store indices of parentheses to remove
    for (let i = 0; i < s.length; i++) {
        // if opening parenthesis, push index to stack
        if (s[i] === '(') {
            stack.push(i);
        } else if (s[i] === ')') {
            // if stack is empty, it means there's no matching opening parenthesis, so mark this closing parenthesis for removal
            if (stack.length === 0) {
                toRemove.add(i);
            } else {
                // if stack is not empty, pop the index of the matching opening parenthesis
                stack.pop();
            }
        }
    }
    // add any remaining opening parentheses in the stack to the set of indices to remove
    while (stack.length > 0) {
        toRemove.add(stack.pop());
    }
    let result = '';
    for (let i = 0; i < s.length; i++) {
        // only append characters that are not marked for removal
        if (!toRemove.has(i)) {
            result += s[i];
        }
    }
    return result;
}

