function tilingRectangle(n, m) {
    // track a "skyline" of fill-heights per column, always filling the lowest gap
    const heights = new Array(m).fill(0);
    let best = n * m; // trivial upper bound: all 1x1 squares

    function findLowest() {
        let minH = Infinity, idx = -1;
        for (let i = 0; i < m; i++) {
            if (heights[i] < minH) { minH = heights[i]; idx = i; }
        }
        return idx;
    }

    function canPlace(col, size) {
        if (col + size > m) return false;
        const base = heights[col];
        if (base + size > n) return false;
        for (let i = col; i < col + size; i++) if (heights[i] !== base) return false;
        return true;
    }

    function backtrack(count) {
        if (count >= best) return; // pruning
        const col = findLowest();
        if (col === -1 || heights[col] === n) { best = Math.min(best, count); return; }

        const maxSize = Math.min(n - heights[col], m - col);
        for (let size = maxSize; size >= 1; size--) {
            if (!canPlace(col, size)) continue;
            for (let i = col; i < col + size; i++) heights[i] += size;
            backtrack(count + 1);
            for (let i = col; i < col + size; i++) heights[i] -= size;
        }
    }

    backtrack(0);
    return best;
}

function jobScheduling(startTime, endTime, profit) {
    let n = startTime.length;
    let jobs = [];
    for (let i = 0; i < n; i++) {
        jobs.push([startTime[i], endTime[i], profit[i]]);
    }
    // sort jobs based on end time
    jobs.sort((a, b) => a[1] - b[1]);
    let dp = new Array(n).fill(0);
    dp[0] = jobs[0][2];
    for (let i = 1; i < n; i++) {
        let maxProfit = jobs[i][2];
        // find the last non-overlapping job and add its profit
        for (let j = i - 1; j >= 0; j--) {
            if (jobs[j][1] <= jobs[i][0]) {
                maxProfit += dp[j];
                break;
            }
        }
        dp[i] = Math.max(maxProfit, dp[i - 1]);
    }
    return dp[n - 1];
}

function closedIsland(grid) {
