function secondsToRemoveOccurrences(s) {
  let seconds = 0, zeros = 0, prevOnesTime = 0;
  for (const ch of s) {
    if (ch === '0') zeros++;
    else {
      if (zeros > 0) prevOnesTime = Math.max(prevOnesTime + 1, zeros);
      seconds = Math.max(seconds, prevOnesTime);
    }
  }
  return seconds;
}

function sortPeople(names, heights) {
  // Create a 2D array to store names and heights, and sort it based on heights in descending order
  var sortedPeople = names.map((name, index) => [name, heights[index]]).sort((a, b) => b[1] - a[1]);
  // Extract the sorted names from the 2D array
  return sortedPeople.map(person => person[0]);
}

function countCommonFactors(a, b) {
  let count = 0;
  // iterate over all possible factors from 1 to the smaller number
  for (let i = 1; i <= Math.min(a, b); i++) {
    // check if the current number is a factor of both a and b
    if (a % i === 0 && b % i === 0) {
      count++;
    }
  }
  return count;
}

