function LUPrefix(n) {
    let uploadedVideos = new Set();
    let longestPrefix = 0;
    return function upload(video) {
        // Add the uploaded video to the set of uploaded videos
        uploadedVideos.add(video);
        // While the longest prefix plus one is in the set of uploaded videos, increment the longest prefix
        while (uploadedVideos.has(longestPrefix + 1)) longestPrefix++;
        return longestPrefix;
    }
}

function maxSum(grid) {
    let maxSum = -Infinity;
    let rows = grid.length;
    let cols = grid[0].length;
    // iterate over each possible hourglass in the grid
    for (let i = 0; i < rows - 2; i++) {
        for (let j = 0; j < cols - 2; j++) {
            // calculate the sum of the current hourglass
            let sum = grid[i][j] + grid[i][j + 1] + grid[i][j + 2] + grid[i + 1][j + 1] + grid[i + 2][j] + grid[i + 2][j + 1] + grid[i + 2][j + 2];
            // update the maximum sum if the current sum is larger
            maxSum = Math.max(maxSum, sum);
        }
    }
    return maxSum;
}

function countPairs(nums1, nums2, diff) {
    let count = 0;
    // iterate over all pairs of elements in the arrays
    for (let i = 0; i < nums1.length; i++) {
        for (let j = i + 1; j < nums1.length; j++) {
            // check if the pair satisfies the conditions
            if (nums1[i] - nums1[j] <= nums2[j] - nums2[i] + diff) {
                count++;
            }
        }
    }
    return count;
}

function longestSubarray(nums) {
  let maxLength = 0;
  let maxAnd = nums[0];
  // Iterate through all possible subarrays to find the maximum bitwise AND
  for (let i = 0; i < nums.length; i++) {
    let and = nums[i];
    for (let j = i; j < nums.length; j++) {
      and = and & nums[j];
      // Update maxAnd if a larger bitwise AND is found
      if (and > maxAnd) {
        maxAnd = and;
      }
    }
  }
  // Find the longest subarray with the maximum bitwise AND
  for (let i = 0; i < nums.length; i++) {
    let and = nums[i];
    for (let j = i; j < nums.length; j++) {
      and = and & nums[j];
      // Update maxLength if a longer subarray with maxAnd is found
      if (and === maxAnd) {
        maxLength = Math.max(maxLength, j - i + 1);
      }
    }
  }
  return maxLength;
}

function goodIndices(nums, k) {
    let n = nums.length;
    let result = [];
    for (let i = k; i < n - k; i++) {
        // Check if the subarray to the left is non-increasing
        let isNonIncreasing = true;
        for (let j = i - 1; j >= i - k; j--) {
            if (nums[j] < nums[j + 1]) {
                isNonIncreasing = false;
                break;
            }
        }
        // Check if the subarray to the right is non-decreasing
        let isNonDecreasing = true;
        for (let j = i + 1; j <= i + k; j++) {
            if (nums[j] < nums[j - 1]) {
                isNonDecreasing = false;
                break;
            }
        }
        // If both conditions are met, add the index to the result
        if (isNonIncreasing && isNonDecreasing) {
            result.push(i);
        }
    }
    return result;
}

function canEqualFrequency(word) {
    let charCount = {};
    for (let char of word) {
        // count the frequency of each character in the word
        charCount[char] = (charCount[char] || 0) + 1;
    }
    let counts = Object.values(charCount);
    let uniqueCounts = new Set(counts);
    if (uniqueCounts.size === 1) {
        // all letters share the same count c: removing one letter only keeps
        // everything equal if that letter vanishes entirely (c === 1) or it
        // was the only distinct letter to begin with
        const c = [...uniqueCounts][0];
        return c === 1 || Object.keys(charCount).length === 1;
    }
    if (uniqueCounts.size > 2) return false;
    let maxCount = Math.max(...uniqueCounts);
    let minCount = Math.min(...uniqueCounts);
    if (maxCount - minCount === 1 && counts.filter(count => count === maxCount).length === 1) return true;
    if (minCount === 1 && counts.filter(count => count === minCount).length === 1) return true;
    return false;
}

function numberOfGoodPaths(vals, edges) {
    let n = vals.length;
    let graph = new Array(n).fill(0).map(() => []);
    for (let [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }
    let count = 0;
    // perform DFS from each node to find good paths
    for (let i = 0; i < n; i++) {
        let visited = new Array(n).fill(false);
        visited[i] = true;
        count += dfs(graph, vals, i, i, visited);
    }
    // since each path is counted twice, divide the count by 2, then add n
    // for the trivial single-node paths
    return count / 2 + n;
}

function dfs(graph, vals, start, current, visited) {
    let count = 0;
    // explore all neighbors of the current node
    for (let neighbor of graph[current]) {
        // a neighbor may only be crossed if its value does not exceed the
        // START node's value (not the current node's value) - a good path
        // just needs every node on it to be <= the max endpoint value
        if (!visited[neighbor] && vals[neighbor] <= vals[start]) {
            visited[neighbor] = true;
            // only nodes whose value equals the start's value complete a
            // good path with the start node
            if (vals[neighbor] === vals[start]) count++;
            count += dfs(graph, vals, start, neighbor, visited);
        }
    }
    return count;
}

function xorAllPairings(nums1, nums2) {
    let result = 0;
    // Iterate over each element in nums1 and nums2, and calculate the XOR of all pairings
    for (let i = 0; i < nums1.length; i++) {
        for (let j = 0; j < nums2.length; j++) {
            // Calculate the XOR of the current pairing and update the result
            result ^= (nums1[i] ^ nums2[j]);
        }
    }
    return result;
}

function minimizeXOR(num1, num2) {
    // calculate the number of set bits in num2
    let setBitsInNum2 = countSetBits(num2);
    // calculate the number of set bits in num1
    let setBitsInNum1 = countSetBits(num1);
    // if num1 has more set bits than num2, return num1
    if (setBitsInNum1 > setBitsInNum2) return num1;
    // if num1 has fewer set bits than num2, return the smallest number with the same number of set bits as num2
    if (setBitsInNum1 < setBitsInNum2) return smallestNumberWithSetBits(setBitsInNum2);
    // if num1 has the same number of set bits as num2, return num1
    return num1;
}

function countSetBits(n) {
    let count = 0;
    while (n) {
        count += n & 1;
        n >>= 1;
    }
    return count;
}

function smallestNumberWithSetBits(setBits) {
    let result = 0;
    for (let i = 0; i < setBits; i++) {
        result |= 1 << i;
    }
    return result;
}

function maximumDeletions(s) {
    // dp[i] = max operations to fully delete s starting from index i
    const n = s.length;
    const dp = new Array(n + 1).fill(0);
    for (let i = n - 1; i >= 0; i--) {
        // fallback: delete the entire remaining suffix in one operation
        let best = 1;
        for (let L = 1; i + 2 * L <= n; L++) {
            if (s.substring(i, i + L) === s.substring(i + L, i + 2 * L)) {
                best = Math.max(best, 1 + dp[i + L]);
            }
        }
        dp[i] = best;
    }
    return dp[0];
}

function countTime(time) {
    // Hour digits are jointly constrained (a '2' in position 0 limits position
    // 1 to 0-3), so counting them multiplicatively per-digit overcounts when
    // BOTH are unknown. Count valid (h0,h1) pairs directly by checking all 24
    // hours, and likewise all 60 minutes (minute digits have no such coupling,
    // but checking directly keeps both halves consistent and simple).
    const h0 = time[0], h1 = time[1], m0 = time[3], m1 = time[4];
    let hourCount = 0;
    for (let h = 0; h <= 23; h++) {
        const hs = String(h).padStart(2, '0');
        if ((h0 === '?' || h0 === hs[0]) && (h1 === '?' || h1 === hs[1])) hourCount++;
    }
    let minuteCount = 0;
    for (let m = 0; m <= 59; m++) {
        const ms = String(m).padStart(2, '0');
        if ((m0 === '?' || m0 === ms[0]) && (m1 === '?' || m1 === ms[1])) minuteCount++;
    }
    return hourCount * minuteCount;
}

function findMaxK(nums) {
    let maxK = -1; // initialize maxK as -1
    let numSet = new Set(); // create a set to store the numbers in the array
    for (let num of nums) { // iterate over the array
        numSet.add(num); // add each number to the set
    }
    for (let num of nums) { // iterate over the array again
        // check if the negative of the current number exists in the set
        if (numSet.has(-num) && num > 0) {
            // update maxK if the current number is larger than maxK
            maxK = Math.max(maxK, num);
        }
    }
    return maxK; // return the largest positive integer k
}

function countDistinctIntegers(nums) {
    let distinctNumbers = new Set(); // store unique numbers
    for (let num of nums) { 
        // add original number to set
        distinctNumbers.add(num);
        // reverse the number and add it to the set
        let reversedNum = parseInt(num.toString().split('').reverse().join('')); 
        distinctNumbers.add(reversedNum);
    }
    return distinctNumbers.size; // return the number of distinct integers
}

function sumOfNumberAndItsReverse(num) {
  for (let i = 0; i <= num; i++) { 
    // check if the sum of i and its reverse equals num
    if (i + parseInt(i.toString().split('').reverse().join('')) === num) return true;
  }
  return false;
}

function productQueries(n, queries) {
    let powers = [];
    // decompose n into its binary representation from the least significant
    // bit upward - each set bit becomes one entry in powers, in ascending order
    let temp = n;
    for (let i = 0; temp > 0; i++) {
        if (temp & 1) powers.push(1 << i);
        temp = temp >> 1;
    }
    let result = [];
    // calculate product for each query
    for (let query of queries) {
        let product = 1;
        for (let i = query[0]; i <= query[1]; i++) {
            product *= powers[i];
        }
        result.push(product);
    }
    return result;
}

function countSubarrays(nums, minK, maxK) {
    let result = 0;
    const n = nums.length;
    // for each start l, extend r rightward while the window stays fully
    // inside [minK, maxK], counting once both minK and maxK have appeared
    for (let l = 0; l < n; l++) {
        let hasMin = false, hasMax = false;
        for (let r = l; r < n; r++) {
            if (nums[r] < minK || nums[r] > maxK) break;
            if (nums[r] === minK) hasMin = true;
            if (nums[r] === maxK) hasMax = true;
            if (hasMin && hasMax) result++;
        }
    }
    return result;
}

function haveConflict(event1, event2) {
    // Convert time to minutes for easier comparison
    function timeToMinutes(time) {
        let parts = time.split(':');
        return parseInt(parts[0]) * 60 + parseInt(parts[1]);
    }

    let start1 = timeToMinutes(event1[0]);
    let end1 = timeToMinutes(event1[1]);
    let start2 = timeToMinutes(event2[0]);
    let end2 = timeToMinutes(event2[1]);

    // Check if the events intersect
    return !(end1 < start2 || end2 < start1);
}

function subarrayGCD(nums, k) {
    let count = 0;
    // iterate over all possible subarrays
    for (let i = 0; i < nums.length; i++) {
        let gcd = nums[i];
        for (let j = i; j < nums.length; j++) {
            // calculate the gcd of the current subarray
            gcd = getGCD(gcd, nums[j]);
            // if the gcd is equal to k, increment the count
            if (gcd === k) count++;
        }
    }
    return count;
}

function getGCD(a, b) {
    if (b === 0) return a;
    return getGCD(b, a % b);
}

function componentValue(nums, edges) {
    let n = nums.length;
    let totalSum = 0;
    for (let num of nums) {
        totalSum += num;
    }
    let possibleSums = [];
    for (let i = 1; i <= n; i++) {
        if (totalSum % i === 0) {
            possibleSums.push(totalSum / i);
        }
    }
    possibleSums.sort((a, b) => a - b);
    let graph = new Array(n).fill(0).map(() => []);
    for (let edge of edges) {
        graph[edge[0]].push(edge[1]);
        graph[edge[1]].push(edge[0]);
    }
    const maxVal = Math.max(...nums);
    let maxEdges = 0;
    // Try candidate component sums smallest-first (more components = more cut
    // edges); a component sum below the largest single node value can never
    // work since that node alone would already exceed it.
    for (let sum of possibleSums) {
        if (sum < maxVal) continue;
        let count = 0;
        const res = dfs(0, -1, sum);
        // walk the tree with a parent pointer (instead of a shared visited
        // array) so we can actually CUT a subtree off once its sum hits the
        // target, rather than always merging into one giant component
        function dfs(node, parent, target) {
            let s = nums[node];
            for (const nb of graph[node]) {
                if (nb === parent) continue;
                const childSum = dfs(nb, node, target);
                if (childSum === -1) return -1;
                s += childSum;
            }
            if (s > target) return -1;
            if (s === target) { count++; return 0; } // cut: contributes nothing to parent
            return s;
        }
        if (res === 0) {
            maxEdges = Math.max(maxEdges, totalSum / sum - 1);
        }
    }
    return maxEdges;
}

function minimizeArrayValue(nums) {
  let result = 0;
  let prefixSum = 0;
  // calculate the maximum possible value by considering the prefix sum and the current index
  for (let i = 0; i < nums.length; i++) {
    prefixSum += nums[i];
    // update the result with the maximum of the current result and the ceiling of the prefix sum divided by the current index plus one
    result = Math.max(result, Math.ceil(prefixSum / (i + 1)));
  }
  return result;
}

function minOperations(nums, target) {
    // Each operation does nums[i]+=2, nums[j]-=2 in one step, so every
    // element's own parity is invariant across any number of operations -
    // a value can only ever be matched to a target value of the SAME
    // parity. Split into odd/even groups, sort each ascending, pair
    // correspondingly, and sum only the positive (increase-side)
    // differences, halved (each op contributes one unit of increase and
    // one unit of decrease, and total increase always equals total
    // decrease since overall sum is invariant).
    function solveGroup(a, b) {
        a = a.slice().sort((x, y) => x - y);
        b = b.slice().sort((x, y) => x - y);
        let ops = 0;
        for (let i = 0; i < a.length; i++) {
            if (b[i] > a[i]) ops += (b[i] - a[i]);
        }
        return ops;
    }
    const numsOdd = nums.filter(x => x % 2 !== 0);
    const numsEven = nums.filter(x => x % 2 === 0);
    const targetOdd = target.filter(x => x % 2 !== 0);
    const targetEven = target.filter(x => x % 2 === 0);
    return (solveGroup(numsOdd, targetOdd) + solveGroup(numsEven, targetEven)) / 2;
}

function minCost(nums, cost) {
    let minCost = Infinity;
    // iterate over all possible target values
    for (let target = Math.min(...nums); target <= Math.max(...nums); target++) {
        let totalCost = 0;
        // calculate the total cost to make all elements equal to the target value
        for (let i = 0; i < nums.length; i++) {
            totalCost += Math.abs(nums[i] - target) * cost[i];
        }
        // update the minimum cost
        minCost = Math.min(minCost, totalCost);
    }
    return minCost;
}

function numberOfPaths(grid, k) {
    const MOD = 1000000007;
    const m = grid.length, n = grid[0].length;
    const dp = Array.from({length: m}, () => Array.from({length: n}, () => new Array(k).fill(0)));
    dp[0][0][grid[0][0] % k] = 1;
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            for (let r = 0; r < k; r++) {
                const cur = dp[i][j][r];
                if (!cur) continue;
                if (i + 1 < m) {
                    const nr = (r + grid[i+1][j]) % k;
                    dp[i+1][j][nr] = (dp[i+1][j][nr] + cur) % MOD;
                }
                if (j + 1 < n) {
                    const nr = (r + grid[i][j+1]) % k;
                    dp[i][j+1][nr] = (dp[i][j+1][nr] + cur) % MOD;
                }
            }
        }
    }
    return dp[m-1][n-1][0];
}

function robotWithString(s) {
    const n = s.length;
    const suffixMin = new Array(n+1).fill('{');
    for (let i = n-1; i >= 0; i--) suffixMin[i] = s[i] < suffixMin[i+1] ? s[i] : suffixMin[i+1];
    const t = [];
    const p = [];
    for (let i = 0; i < n; i++) {
        t.push(s[i]);
        while (t.length && t[t.length-1] <= suffixMin[i+1]) {
            p.push(t.pop());
        }
    }
    while (t.length) p.push(t.pop());
    return p.join('');
}

function checkDistances(s, distance) {
    // store first index of each letter, -1 means not seen yet
    const firstPos = new Array(26).fill(-1);

    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - 97; // map 'a'..'z' to 0..25

        if (firstPos[idx] === -1) {
            // first occurrence
            firstPos[idx] = i;
        } else {
            // second occurrence: verify required gap
            const requiredGap = distance[idx];
            const actualGap = i - firstPos[idx] - 1;
            if (actualGap !== requiredGap) return false;
        }
    }
    return true;
}

function oddString(words) {
    // create a hashmap to store the difference arrays as keys and their corresponding strings as values
    let differenceMap = {};
    for (let word of words) {
        let difference = [];
        // calculate the difference array for each string
        for (let i = 0; i < word.length - 1; i++) {
            difference.push(word.charCodeAt(i + 1) - word.charCodeAt(i));
        }
        // store the difference array and its corresponding string in the hashmap
        let key = difference.join(',');
        if (!differenceMap[key]) differenceMap[key] = [];
        differenceMap[key].push(word);
    }
    // find the difference array that appears only once
    for (let key in differenceMap) {
        // if the difference array appears only once, return the corresponding string
        if (differenceMap[key].length === 1) return differenceMap[key][0];
    }
}

function averageOfEvenNumbersDivisibleByThree(nums) {
  let sum = 0, count = 0; 
  // loop through each number in the array to check if it's even and divisible by 3
  for (let num of nums) {
    if (num % 2 === 0 && num % 3 === 0) {
      sum += num; 
      // increment count to keep track of numbers that meet the condition
      count++;
    }
  }
  // if no numbers meet the condition, return 0
  if (count === 0) return 0;
  // calculate the average and round down to the nearest integer
  return Math.floor(sum / count);
}

function makeIntegerBeautiful(n, target) {
    let x = 0;
    while (true) {
        let sum = 0; // calculate the sum of digits of n + x
        let temp = n + x;
        while (temp > 0) {
            sum += temp % 10; // add the last digit to the sum
            temp = Math.floor(temp / 10); // remove the last digit
        }
        if (sum <= target) // if the sum of digits is less than or equal to the target, return x
            return x;
        x++; // if not, increment x and try again
    }
}

