function mostPopularCreator(creators, ids, views) {
    let creatorPopularity = {};
    for (let i = 0; i < creators.length; i++) {
        // Calculate the total views for each creator
        if (creatorPopularity[creators[i]]) {
            creatorPopularity[creators[i]].totalViews += views[i];
            if (views[i] > creatorPopularity[creators[i]].maxViews || (views[i] === creatorPopularity[creators[i]].maxViews && ids[i] < creatorPopularity[creators[i]].maxViewId)) {
                // Update the most viewed video id for the creator
                creatorPopularity[creators[i]].maxViews = views[i];
                creatorPopularity[creators[i]].maxViewId = ids[i];
            }
        } else {
            creatorPopularity[creators[i]] = { totalViews: views[i], maxViews: views[i], maxViewId: ids[i] };
        }
    }

    let maxPopularity = 0;
    for (let creator in creatorPopularity) {
        // Find the maximum popularity
        maxPopularity = Math.max(maxPopularity, creatorPopularity[creator].totalViews);
    }

    let result = [];
    for (let creator in creatorPopularity) {
        // Add creators with the highest popularity to the result
        if (creatorPopularity[creator].totalViews === maxPopularity) {
            result.push([creator, creatorPopularity[creator].maxViewId]);
        }
    }
    return result;
}

function secondGreaterElement(nums) {
    const n = nums.length;
    const result = new Array(n).fill(-1);
    // for each i, scan forward for the FIRST index whose value exceeds
    // nums[i], keep scanning past it for the SECOND such index
    for (let i = 0; i < n; i++) {
        let foundFirst = false;
        for (let j = i + 1; j < n; j++) {
            if (nums[j] > nums[i]) {
                if (!foundFirst) {
                    foundFirst = true;
                } else {
                    result[i] = nums[j];
                    break;
                }
            }
        }
    }
    return result;
}

function twoEditWords(queries, dictionary) {
    function editsBetween(word1, word2) {
        let edits = 0;
        for (let i = 0; i < word1.length; i++) {
            // count the number of different characters
            if (word1[i] !== word2[i]) edits++;
            if (edits > 2) return edits;
        }
        return edits;
    }

    let result = [];
    for (let query of queries) {
        for (let dictWord of dictionary) {
            // check if the query word can be transformed into the dictionary word with 2 edits
            if (editsBetween(query, dictWord) <= 2) {
                result.push(query);
                break; // stop checking other dictionary words for this query
            }
        }
    }
    return result;
}

function maximumSum(nums, k) {
    let maxSum = 0;
    // iterate over the array with a sliding window of size k
    for (let i = 0; i <= nums.length - k; i++) {
        let currentSum = 0;
        let uniqueElements = new Set();
        // calculate the sum of the current window and check for unique elements
        for (let j = i; j < i + k; j++) {
            currentSum += nums[j];
            uniqueElements.add(nums[j]);
        }
        // if all elements in the window are unique, update maxSum
        if (uniqueElements.size === k) maxSum = Math.max(maxSum, currentSum);
    }
    return maxSum;
}

function applyOperations(nums) {
    // iterate over the array and apply operations
    for (let i = 0; i < nums.length - 1; i++) {
        if (nums[i] === nums[i + 1]) {
            nums[i] *= 2; // multiply the current element by 2 if it's equal to the next one
            nums[i + 1] = 0; // set the next element to 0
        }
    }
    // use two pointers to shift all the 0's to the end of the array
    let left = 0, right = 0;
    while (right < nums.length) {
        if (nums[right] !== 0) {
            let temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp; // swap non-zero elements to the front
            left++;
        }
        right++;
    }
    return nums;
}

function destroyTargets(nums, space) {
    let countMap = {};
    for (let num of nums) {
        // calculate the remainder of num divided by space to group targets that can be destroyed together
        let remainder = num % space;
        if (!countMap[remainder]) countMap[remainder] = [];
        countMap[remainder].push(num);
    }
    let maxCount = 0;
    let minSeed = Infinity;
    for (let remainder in countMap) {
        // find the group with the maximum count of targets
        let count = countMap[remainder].length;
        if (count > maxCount) {
            maxCount = count;
            // find the minimum seed value in the group with the maximum count
            minSeed = Math.min(...countMap[remainder]);
        } else if (count === maxCount) {
            // if there are multiple groups with the same maximum count, find the one with the minimum seed value
            minSeed = Math.min(minSeed, Math.min(...countMap[remainder]));
        }
    }
    return minSeed;
}

function heightOfTreeAfterSubtreeRemovalQueries(root, queries) {
    function getHeight(node) {
        if (!node) return -1;
        let leftHeight = getHeight(node.left);
        let rightHeight = getHeight(node.right);
        return Math.max(leftHeight, rightHeight) + 1;
    }
    function removeSubtree(node, value) {
        if (!node) return null;
        if (node.val === value) return null;
        node.left = removeSubtree(node.left, value);
        node.right = removeSubtree(node.right, value);
        return node;
    }
    let answer = [];
    for (let query of queries) {
        let tempRoot = JSON.parse(JSON.stringify(root));
        tempRoot = removeSubtree(tempRoot, query);
        answer.push(getHeight(tempRoot));
    }
    return answer;
}

function minimumTotalDistance(robot, factory) {
    robot.sort((a, b) => a - b);
    factory.sort((a, b) => a[0] - b[0]);
    let totalDistance = 0;
    let robotIndex = 0;
    for (let i = 0; i < factory.length; i++) {
        let factoryPosition = factory[i][0];
        let limit = factory[i][1];
        // calculate the median distance for the robots assigned to the current factory
        let distances = [];
        while (robotIndex < robot.length && limit > 0) {
            distances.push(Math.abs(robot[robotIndex] - factoryPosition));
            robotIndex++;
            limit--;
        }
        distances.sort((a, b) => a - b);
        // add the median distance to the total distance
        totalDistance += distances.reduce((acc, curr) => acc + curr, 0);
    }
    return totalDistance;
}

function convertTemperature(celsius) {
  // calculate Kelvin by adding 273.15 to Celsius
  var kelvin = celsius + 273.15;
  // calculate Fahrenheit by multiplying Celsius by 9/5 and adding 32
  var fahrenheit = celsius * 9 / 5 + 32;
  return [kelvin, fahrenheit];
}

function findOriginalArray(pref) {
    const n = pref.length;
    const arr = new Array(n);
    if (n === 0) return arr;

    arr[0] = pref[0];                     // first element is unchanged
    for (let i = 1; i < n; i++) {
        arr[i] = pref[i] ^ pref[i - 1];   // xor with previous prefix to get original value
    }
    return arr;
}

function longestTaskEmployee(n, logs) {
    let previousLeave = 0;          // start time of the current task
    let maxDuration = 0;            // longest duration seen so far
    let employeeId = 0;             // employee with the longest task (smallest id on tie)

    for (let i = 0; i < logs.length; i++) {
        const [id, leaveTime] = logs[i];
        const duration = leaveTime - previousLeave;   // duration of this task

        // update if we found a longer task or same length with smaller id
        if (duration > maxDuration || (duration === maxDuration && id < employeeId)) {
            maxDuration = duration;
            employeeId = id;
        }

        previousLeave = leaveTime;   // next task starts when this one ends
    }

    return employeeId;
}

function findPivotInteger(n) {
  let totalSum = (n * (n + 1)) / 2; // calculate the total sum of numbers from 1 to n
  let leftSum = 0; // initialize the sum of numbers to the left of the pivot
  for (let x = 1; x <= n; x++) { 
    // check if the sum of numbers to the left of x equals the sum of numbers to the right of x
    if (leftSum === totalSum - leftSum - x) return x; 
    leftSum += x; // update the sum of numbers to the left of x
  }
  return -1; // return -1 if no pivot integer is found
}

var mostProfitablePath = function(edges, bob, amount) {
    const n = amount.length;
    const adj = Array.from({length:n}, () => []);
    for (const [a,b] of edges) { adj[a].push(b); adj[b].push(a); }
    const parent = new Array(n).fill(-1);
    const depth = new Array(n).fill(0);
    const stack = [0];
    parent[0] = -2;
    while (stack.length) {
        const v = stack.pop();
        for (const nb of adj[v]) {
            if (nb === parent[v]) continue;
            parent[nb] = v;
            depth[nb] = depth[v] + 1;
            stack.push(nb);
        }
    }
    const INF = 1e9;
    const bobTime = new Array(n).fill(INF);
    let node = bob, t = 0;
    while (true) {
        bobTime[node] = t;
        if (node === 0) break;
        node = parent[node];
        t++;
    }
    let ans = -1e18;
    function dfs(v, p, curSum) {
        if (depth[v] < bobTime[v]) curSum += amount[v];
        else if (depth[v] === bobTime[v]) curSum += Math.floor(amount[v]/2);
        const isLeaf = (v !== 0 && adj[v].length === 1) || (v === 0 && adj[v].length === 0);
        if (isLeaf) ans = Math.max(ans, curSum);
        for (const nb of adj[v]) {
            if (nb === p) continue;
            dfs(nb, v, curSum);
        }
    }
    dfs(0, -1, 0);
    return ans;
};

function countSubarraysWithMedianK(nums, k) {
    let count = 0;
    // iterate over all possible subarrays
    for (let i = 0; i < nums.length; i++) {
        for (let j = i; j < nums.length; j++) {
            let subarray = nums.slice(i, j + 1);
            // sort the subarray to find the median
            subarray.sort((a, b) => a - b);
            // for this problem the median of an even-length subarray is
            // defined as the SMALLER of the two middle elements - only one
            // specific position counts, not either of the two
            let medianIndex = Math.floor((subarray.length - 1) / 2);
            if (subarray[medianIndex] === k) count++;
        }
    }
    return count;
}

/**
 * Removes every node that has a greater value somewhere to its right.
 * @param {ListNode|null} head - Head of the singly linked list.
 * @return {ListNode|null} - Head of the modified list.
 */
function removeNodes(head) {
    // ---------- reverse the original list ----------
    let prev = null;
    let cur = head;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    // 'prev' is now the head of the reversed list
    let revHead = prev;

    // ---------- keep nodes that are >= max seen so far ----------
    let maxSeen = -Infinity;
    const dummy = new ListNode(0); // temporary start of filtered list
    let tail = dummy;
    cur = revHead;
    while (cur) {
        if (cur.val >= maxSeen) {          // keep this node
            maxSeen = cur.val;
            tail.next = cur;
            tail = cur;
        }
        cur = cur.next;
    }
    tail.next = null; // cut off any trailing nodes that were skipped

    // ---------- reverse the filtered list back ----------
    prev = null;
    cur = dummy.next;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev; // new head
}

function minAppendToMakeSubsequence(s, t) {
    let i = 0;               // index in s
    let j = 0;               // index in t

    // match the longest prefix of t as a subsequence in s
    while (i < s.length && j < t.length) {
        if (s[i] === t[j]) {
            j++;
        }
        i++;
    }

    // characters of t that couldn't be matched must be appended
    return t.length - j;
}

function countGoodStrings(low, high, zero, one) {
    const MOD = 1000000007;
    const dp = new Array(high + 1).fill(0);
    dp[0] = 1;                     // empty string

    // DP transition: dp[i] = dp[i-zero] + dp[i-one]
    for (let i = 1; i <= high; i++) {
        let ways = 0;
        if (i >= zero) ways = (ways + dp[i - zero]) % MOD;
        if (i >= one)  ways = (ways + dp[i - one]) % MOD;
        dp[i] = ways;
    }

    let ans = 0;
    for (let i = low; i <= high; i++) {
        ans = (ans + dp[i]) % MOD;
    }
    return ans;
}

function subarrayLCM(nums, k) {
    function gcd(a, b) {
        if (b === 0) return a;
        return gcd(b, a % b);
    }
    function lcm(a, b) {
        return (a * b) / gcd(a, b);
    }
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        let currentLcm = nums[i];
        // Calculate the LCM of the subarray starting at index i
        for (let j = i; j < nums.length; j++) {
            currentLcm = lcm(currentLcm, nums[j]);
            // Check if the LCM of the subarray is equal to k
            if (currentLcm === k) count++;
            // If the LCM exceeds k, break the inner loop
            if (currentLcm > k) break;
        }
    }
    return count;
}

function distinctAverages(nums) {
    // sort to pair smallest with largest easily
    nums.sort((a, b) => a - b);

    const averages = new Set();
    let left = 0;
    let right = nums.length - 1;

    while (left < right) {
        const avg = (nums[left] + nums[right]) / 2; // compute current average
        averages.add(avg);                           // store distinct value
        left++;
        right--;
    }

    return averages.size;
}

function minCuts(n) {
    // special case: a single slice needs no cut
    if (n === 1) return 0;

    // even number of slices → each diameter creates two slices
    if (n % 2 === 0) return n / 2;   // main logic

    // odd number of slices → need one cut per slice
    return n;                        // main logic
}

function minimumPenalty(customers) {
    let minPenalty = Infinity;
    let minTime = Infinity;
    for (let i = 0; i <= customers.length; i++) {
        let penalty = 0;
        for (let j = 0; j < customers.length; j++) {
            if (j < i) {
                // shop is open at hour j but no customer came - wasted hour
                if (customers[j] === 'N') penalty++;
            } else {
                // shop is closed at hour j but a customer came - missed customer
                if (customers[j] === 'Y') penalty++;
            }
        }
        if (penalty < minPenalty) {
            minPenalty = penalty;
            minTime = i;
        } else if (penalty === minPenalty) {
            minTime = Math.min(minTime, i);
        }
    }
    return minTime;
}

function magnificentSets(n, edges) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const visited = new Array(n + 1).fill(false);
    const color = new Array(n + 1).fill(-1);
    let totalGroups = 0;

    for (let i = 1; i <= n; i++) {
        if (visited[i]) continue;

        // Gather component nodes and check bipartiteness
        const comp = [];
        const queue = [i];
        visited[i] = true;
        color[i] = 0;
        comp.push(i);
        let bipartite = true;
        for (let qIdx = 0; qIdx < queue.length; qIdx++) {
            const u = queue[qIdx];
            for (const v of adj[u]) {
                if (!visited[v]) {
                    visited[v] = true;
                    color[v] = color[u] ^ 1;
                    queue.push(v);
                    comp.push(v);
                } else if (color[v] === color[u]) {
                    bipartite = false;
                }
            }
        }
        if (!bipartite) return -1;

        // Compute diameter of this component
        let diameter = 0;
        for (const start of comp) {
            const dist = new Array(n + 1).fill(-1);
            const q = [start];
            dist[start] = 0;
            for (let idx = 0; idx < q.length; idx++) {
                const u = q[idx];
                for (const v of adj[u]) {
                    if (dist[v] === -1) {
                        dist[v] = dist[u] + 1;
                        q.push(v);
                    }
                }
            }
            for (const node of comp) {
                if (dist[node] > diameter) diameter = dist[node];
            }
        }

        totalGroups += diameter + 1;
    }

    return totalGroups;
}
// TIME: O(n*(n+m)) SPACE: O(n+m)

function dividePlayers(skill) {
    // sort to enable pairing smallest with largest
    skill.sort((a, b) => a - b);

    const target = skill[0] + skill[skill.length - 1]; // desired team skill sum
    let totalChemistry = 0;
    let left = 0,
        right = skill.length - 1;

    // pair smallest with largest, check sum, accumulate product
    while (left < right) {
        if (skill[left] + skill[right] !== target) return -1;
        totalChemistry += skill[left] * skill[right];
        left++;
        right--;
    }
    return totalChemistry;
}

function longestSquareStreak(nums) {
    const s = new Set(nums);
    let best = -1;
    for (const x of s) {
        let cur = x, len = 1;
        while (s.has(cur*cur) && cur*cur <= 1e5*1e5) { cur = cur*cur; len++; }
        if (len >= 2) best = Math.max(best, len);
    }
    return best;
}

function totalCost(costs, k, candidates) {
    const n = costs.length;
    const alive = costs.slice();
    // frontEnd = rightmost index currently offered from the left pool;
    // backStart = leftmost index currently offered from the right pool.
    // The two pools never overlap; whichever side a hire comes from grows
    // by one index toward the middle to keep offering `candidates` workers.
    let frontEnd = Math.min(candidates, n) - 1;
    let backStart = Math.max(n - candidates, frontEnd + 1);
    let total = 0;
    for (let count = 0; count < k; count++) {
        let minFrontCost = Infinity, minFrontIdx = -1;
        for (let i = 0; i <= frontEnd; i++) {
            if (alive[i] < minFrontCost) { minFrontCost = alive[i]; minFrontIdx = i; }
        }
        let minBackCost = Infinity, minBackIdx = -1;
        for (let i = backStart; i < n; i++) {
            if (alive[i] < minBackCost) { minBackCost = alive[i]; minBackIdx = i; }
        }
        let chosenIdx, chosenCost;
        if (minFrontIdx !== -1 && (minBackIdx === -1 || minFrontCost <= minBackCost)) {
            chosenIdx = minFrontIdx; chosenCost = minFrontCost;
        } else {
            chosenIdx = minBackIdx; chosenCost = minBackCost;
        }
        total += chosenCost;
        alive[chosenIdx] = Infinity;
        if (chosenIdx <= frontEnd) {
            if (frontEnd + 1 < backStart) frontEnd++;
        } else {
            if (backStart - 1 > frontEnd) backStart--;
        }
    }
    return total;
}

function minScore(n, roads) {
    // Build adjacency list
    const adj = Array.from({ length: n + 1 }, () => []);
    for (const [u, v, w] of roads) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const visited = new Array(n + 1).fill(false);
    const stack = [1];
    visited[1] = true;
    let minScore = Infinity;

    // Traverse the component containing city 1
    while (stack.length) {
        const node = stack.pop();
        for (const [nbr, w] of adj[node]) {
            if (w < minScore) minScore = w;          // keep the smallest edge weight seen
            if (!visited[nbr]) {
                visited[nbr] = true;
                stack.push(nbr);
            }
        }
    }
    return minScore;
}

var minimumTotalCost = function(nums1, nums2) {
    const n = nums1.length;
    let ans = 0n;
    let same = 0;
    const cnt = new Map();
    for (let i = 0; i < n; i++) {
        if (nums1[i] === nums2[i]) {
            ans += BigInt(i);
            same++;
            cnt.set(nums1[i], (cnt.get(nums1[i]) || 0) + 1);
        }
    }
    let m = 0, lead = -1;
    for (const [val, c] of cnt.entries()) {
        const t = c * 2 - same;
        if (t > m) { m = t; lead = val; }
    }
    for (let i = 0; i < n && m > 0; i++) {
        if (nums1[i] !== nums2[i] && nums1[i] !== lead && nums2[i] !== lead) {
            ans += BigInt(i);
            m--;
        }
    }
    return m > 0 ? -1 : Number(ans);
};

function minCost(stones) {
    const n = stones.length;
    if (n <= 2) return stones[n-1] - stones[0];
    let maxGap = 0;
    for (let i = 0; i < n - 2; i++) {
        const gap = stones[i + 2] - stones[i];
        if (gap > maxGap) maxGap = gap;
    }
    return maxGap;
}

function deleteGreatestValue(grid) {
    // sort each row so that the greatest values are at the end
    for (let i = 0; i < grid.length; i++) {
        grid[i].sort((a, b) => a - b);
    }

    const cols = grid[0].length;
    let answer = 0;

    // for each column (from left to right after sorting) add the maximum element among rows
    for (let c = 0; c < cols; c++) {
        let colMax = 0;
        for (let r = 0; r < grid.length; r++) {
            if (grid[r][c] > colMax) colMax = grid[r][c];
        }
        answer += colMax;
    }

    return answer;
}

function maxValue(strs) {
    let max = 0;                                   // track the highest value found
    for (let s of strs) {
        let onlyDigits = true;                     // assume the string is all digits
        for (let i = 0; i < s.length; i++) {
            const ch = s.charCodeAt(i);
            if (ch < 48 || ch > 57) {              // not '0'‑'9'
                onlyDigits = false;
                break;
            }
        }
        const value = onlyDigits ? Number(s) : s.length; // numeric value or length
        if (value > max) max = value;              // update maximum if needed
    }
    return max;
}

function MemoryAllocator(n) {
    const free = [{ start: 0, end: n - 1 }];
    const allocations = new Map(); // mID -> list of {start, size}

    function freeInterval(start, size) {
        let newStart = start;
        let newEnd = start + size - 1;
        let i = 0;
        while (i < free.length && free[i].end < newStart - 1) i++;
        if (i > 0 && free[i - 1].end + 1 >= newStart) {
            newStart = free[i - 1].start;
            newEnd = Math.max(newEnd, free[i - 1].end);
            free.splice(i - 1, 1);
            i--;
        }
        while (i < free.length && free[i].start <= newEnd + 1) {
            newStart = Math.min(newStart, free[i].start);
            newEnd = Math.max(newEnd, free[i].end);
            free.splice(i, 1);
        }
        free.splice(i, 0, { start: newStart, end: newEnd });
    }

    return {
        allocate: function (size, mID) {
            for (let i = 0; i < free.length; i++) {
                const interval = free[i];
                const length = interval.end - interval.start + 1;
                if (length >= size) {
                    const allocStart = interval.start;
                    if (length === size) free.splice(i, 1);
                    else interval.start += size;
                    if (!allocations.has(mID)) allocations.set(mID, []);
                    allocations.get(mID).push({ start: allocStart, size });
                    return allocStart;
                }
            }
            return -1;
        },

        freeMemory: function (mID) {
            const blocks = allocations.get(mID);
            if (!blocks) return 0;
            let freed = 0;
            for (const b of blocks) { freeInterval(b.start, b.size); freed += b.size; }
            allocations.delete(mID);
            return freed;
        }
    };
}

function isPossible(n, edges) {
    const adj = Array.from({length:n+1}, () => new Set());
    for (const [u,v] of edges) { adj[u].add(v); adj[v].add(u); }
    const odd = [];
    for (let i = 1; i <= n; i++) if (adj[i].size % 2 === 1) odd.push(i);
    if (odd.length === 0) return true;
    if (odd.length === 2) {
        const [a,b] = odd;
        if (!adj[a].has(b)) return true;
        for (let c = 1; c <= n; c++) if (c!==a && c!==b && !adj[c].has(a) && !adj[c].has(b)) return true;
        return false;
    }
    if (odd.length === 4) {
        const [a,b,c,d] = odd;
        return (!adj[a].has(b) && !adj[c].has(d)) || (!adj[a].has(c) && !adj[b].has(d)) || (!adj[a].has(d) && !adj[b].has(c));
    }
    return false;
}

function countSimilarPairs(words) {
    const freq = new Map();               // map mask -> how many words have this character set

    for (const w of words) {
        let mask = 0;
        for (const ch of w) {
            mask |= 1 << (ch.charCodeAt(0) - 97);   // set bit for each character
        }
        freq.set(mask, (freq.get(mask) || 0) + 1);   // count this mask
    }

    let pairs = 0;
    for (const cnt of freq.values()) {
        pairs += cnt * (cnt - 1) / 2;                // nC2 for each group
    }
    return pairs;
}

function smallestValue(n) {
  while (true) {
    let sum = 0, num = n, d = 2;
    while (d * d <= num) {
      while (num % d === 0) { sum += d; num /= d; }
      d++;
    }
    if (num > 1) sum += num;
    if (sum === n) return n;
    n = sum;
  }
}

function captureForts(forts) {
    let maxCaptured = 0;
    let prevIdx = -1; // index of the last seen non-zero fort (1 = yours, -1 = empty)

    for (let i = 0; i < forts.length; i++) {
        const cur = forts[i];
        // boundary markers are your fort (1) or an empty slot (-1); an
        // enemy fort (0) is what gets captured, never a boundary
        if (cur !== 0) {
            // opposite non-zero values (1 and -1 sum to 0) mean everything
            // strictly between them is guaranteed to be enemy forts (0),
            // since we only stop the scan at non-zero positions
            if (prevIdx !== -1 && cur + forts[prevIdx] === 0) {
                const captured = i - prevIdx - 1;
                if (captured > maxCaptured) maxCaptured = captured;
            }
            prevIdx = i;
        }
    }
    return maxCaptured;
}

function topStudents(positive_feedback, negative_feedback, report, student_id, k) {
    // build quick lookup sets for feedback words
    const posSet = new Set(positive_feedback);
    const negSet = new Set(negative_feedback);

    // map student id -> accumulated points
    const points = new Map();

    // process each report
    for (let i = 0; i < report.length; i++) {
        const id = student_id[i];
        const words = report[i].split(' ');
        let score = 0;
        for (const w of words) {
            if (posSet.has(w)) score += 3;      // positive word
            else if (negSet.has(w)) score -= 1; // negative word
        }
        points.set(id, (points.get(id) || 0) + score);
    }

    // collect all students into an array for sorting
    const students = [];
    for (const [id, pt] of points.entries()) {
        students.push({ id, pt });
    }

    // sort by points descending, then id ascending
    students.sort((a, b) => {
        if (b.pt !== a.pt) return b.pt - a.pt;
        return a.id - b.id;
    });

    // take top k ids
    const result = [];
    for (let i = 0; i < k && i < students.length; i++) {
        result.push(students[i].id);
    }
    return result;
}

function maximumTastiness(price, k) {
    // sort prices to work with ordered differences
    price.sort((a, b) => a - b);

    // greedy check: can we pick k candies with at least 'dist' between them?
    function canPlace(dist) {
        let count = 1;               // first candy always taken
        let last = price[0];
        for (let i = 1; i < price.length; i++) {
            if (price[i] - last >= dist) {
                count++;
                last = price[i];
                if (count === k) return true; // enough candies selected
            }
        }
        return false;
    }

    let low = 0;
    let high = price[price.length - 1] - price[0]; // maximal possible difference

    // binary search on the answer
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2); // upper mid
        if (canPlace(mid)) {
            low = mid;               // try larger distance
        } else {
            high = mid - 1;          // distance too large
        }
    }
    return low;
}

function takeCharacters(s, k) {
    const n = s.length;
    const totalA = (s.match(/a/g)||[]).length;
    const totalB = (s.match(/b/g)||[]).length;
    const totalC = (s.match(/c/g)||[]).length;
    if (totalA < k || totalB < k || totalC < k) return -1;
    const allowedA = totalA - k, allowedB = totalB - k, allowedC = totalC - k;
    let left = 0, cntA = 0, cntB = 0, cntC = 0, maxLen = 0;
    for (let right = 0; right < n; right++) {
        const ch = s[right];
        if (ch === 'a') cntA++; else if (ch === 'b') cntB++; else cntC++;
        while (cntA > allowedA || cntB > allowedB || cntC > allowedC) {
            const chLeft = s[left];
            if (chLeft === 'a') cntA--; else if (chLeft === 'b') cntB--; else cntC--;
            left++;
        }
        const curLen = right - left + 1;
        if (curLen > maxLen) maxLen = curLen;
    }
    return n - maxLen;
}

var countAnagrams = function(s) {
    const MOD = 1000000007;
    const words = s.split(' ');
    const maxLen = Math.max(...words.map(w=>w.length));
    const fact = new Array(maxLen+1).fill(1);
    for (let i=1;i<=maxLen;i++) fact[i] = fact[i-1]*i % MOD;
    function modpow(base, exp, mod) {
        let b = BigInt(base) % BigInt(mod);
        let e = BigInt(exp);
        const m = BigInt(mod);
        let result = 1n;
        while (e > 0n) {
            if (e & 1n) result = (result*b) % m;
            e >>= 1n;
            b = (b*b) % m;
        }
        return Number(result);
    }
    const invFact = new Array(maxLen+1).fill(1);
    invFact[maxLen] = modpow(fact[maxLen], MOD-2, MOD);
    for (let i=maxLen;i>=1;i--) invFact[i-1] = invFact[i]*i % MOD;
    const M = BigInt(MOD);
    let ans = 1n;
    for (const w of words) {
        let ways = BigInt(fact[w.length]);
        const freq = {};
        for (const ch of w) freq[ch] = (freq[ch]||0)+1;
        for (const c of Object.values(freq)) ways = (ways * BigInt(invFact[c])) % M;
        ans = (ans * ways) % M;
    }
    return Number(ans);
};

function distinctPrimeFactors(nums) {
    const primeSet = new Set();               // store distinct primes

    for (let value of nums) {
        let n = value;
        if (n < 2) continue;                  // 0 and 1 have no prime factors

        // extract factor 2
        while (n % 2 === 0) {
            primeSet.add(2);
            n /= 2;
        }

        // extract odd factors up to sqrt(n)
        for (let f = 3; f * f <= n; f += 2) {
            while (n % f === 0) {
                primeSet.add(f);
                n /= f;
            }
        }

        // if remainder > 1, it is a prime itself
        if (n > 1) primeSet.add(n);
    }

    return primeSet.size;
}

function countDigitsDividingNumber(num) {
    var count = 0;
    var numStr = num.toString(); // turn the number into a string to examine each digit
    for (var i = 0; i < numStr.length; i++) {
        var digit = numStr.charCodeAt(i) - 48; // numeric value of current digit
        if (digit !== 0 && num % digit === 0) {
            count++;
        }
    }
    return count;
}

function shortestDistance(words, target, startIndex) {
    const n = words.length;
    let minDist = Infinity;
    for (let i = 0; i < n; i++) {
        if (words[i] !== target) continue;               // check only target positions
        // distance clockwise and counter‑clockwise in a circular array
        const clockwise = (i - startIndex + n) % n;
        const counter   = (startIndex - i + n) % n;
        const dist = Math.min(clockwise, counter);
        if (dist < minDist) minDist = dist;
    }
    return minDist === Infinity ? -1 : minDist;
}

function minPartitions(s, k) {
    // impossible if a single digit exceeds k
    for (let i = 0; i < s.length; i++) {
        const d = s.charCodeAt(i) - 48; // digit value
        if (d > k) return -1;
    }

    let parts = 0;   // number of completed substrings
    let cur = 0;     // value of the substring we are building

    for (let i = 0; i < s.length; i++) {
        const d = s.charCodeAt(i) - 48;
        const next = cur * 10 + d;   // try to extend the current substring

        // main logic: cut when the extended value would exceed k
        if (next > k) {
            parts++;      // finish the previous substring
            cur = d;      // start a new one with the current digit
        } else {
            cur = next;   // keep extending
        }
    }

    // add the last (non‑empty) substring
    return s.length === 0 ? 0 : parts + 1;
}

function minimizeTheMaximumOfTwoArrays(divisor1, divisor2, uniqueCnt1, uniqueCnt2) {
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const lcm = (a, b) => Math.floor(a / gcd(a, b)) * b;
    const l = lcm(divisor1, divisor2);

    const feasible = (m) => {
        const a = Math.floor(m / divisor1);
        const b = Math.floor(m / divisor2);
        const c = Math.floor(m / l);

        const exclusive1 = b - c;
        const exclusive2 = a - c;
        const overlap = m - (a + b - c);

        const need1 = Math.max(0, uniqueCnt1 - exclusive1);
        const need2 = Math.max(0, uniqueCnt2 - exclusive2);

        return need1 + need2 <= overlap;
    };

    let hi = 1;
    while (!feasible(hi)) hi <<= 1;

    let lo = 1;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (feasible(mid)) hi = mid; else lo = mid + 1;
    }
    return lo;
}

function numberOfGreatPartitions(nums, k) {
    const MOD = 1000000007;
    const total = nums.reduce((a, b) => a + b, 0);

    // if total sum is too small, no great partition exists
    if (total < 2 * k) return 0;

    const dp = new Array(total + 1).fill(0);
    dp[0] = 1;                       // empty subset

    // DP: count subsets for each possible sum
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        for (let s = total; s >= x; s--) {
            dp[s] = (dp[s] + dp[s - x]) % MOD;
        }
    }

    // sum counts for sums inside [k, total - k]
    let ans = 0;
    for (let s = k; s <= total - k; s++) {
        ans = (ans + dp[s]) % MOD;
    }
    return ans;
}

function xorBeauty(nums) {
    let result = 0;
    // XOR all elements; each bit appears in the final answer iff it appears an odd number of times
    for (let v of nums) {
        result ^= v;
    }
    return result;
}

function maxPower(stations, r, k) {
  const n = stations.length;
