      const lo = Math.max(0, i - r), hi = Math.min(n - 1, i + r);
      diff[lo] += stations[i];
      diff[hi + 1] -= stations[i];
    }
    let cur = 0;
    for (let i = 0; i < n; i++) { cur += diff[i]; power[i] = cur; }
    return power;
  }
  const basePower = initialPower();
  function feasible(target) {
    const power = basePower.slice();
    const added = new Array(n + 1).fill(0);
