    for (let i = 0; i < n; i++) {
      curAdd += added[i];
      const cur = power[i] + curAdd;
      if (cur < target) {
        const need = target - cur;
        used += need;
        if (used > k) return false;
        curAdd += need;
        const hi = Math.min(n - 1, i + r);
        added[hi + 1] -= need;
      }
    }
