  let lo = Math.min(...basePower), hi = Math.min(...basePower) + k + basePower.reduce((a,b)=>a+b,0);
  hi = Math.max(...basePower) + k; // safe upper bound
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (feasible(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}

function DataStream() {
    // keep track of the value of the most recent run and its length
    let lastValue = null;
    let runLength = 0;

    return {
        // add a new integer from the stream
        next: function (val) {
            // if the new value continues the current run, extend it;
            // otherwise start a new run with length 1
            if (val === lastValue) {
                runLength++;
            } else {
                lastValue = val;
                runLength = 1;
            }
        },

        // check whether the last k integers are all equal to `value`
        consecutive: function (k, value) {
            // true only when the current run matches the queried value
            // and its length is at least k
            return value === lastValue && runLength >= k;
        }
    };
}

function closestPrimes(left, right) {
    const sieve = new Array(right+1).fill(true);
    sieve[0] = sieve[1] = false;
    for (let i = 2; i*i <= right; i++) if (sieve[i]) for (let j = i*i; j <= right; j += i) sieve[j] = false;
    const primes = [];
    for (let i = Math.max(2,left); i <= right; i++) if (sieve[i]) primes.push(i);
    let best = [-1,-1], bestGap = Infinity;
    for (let i = 1; i < primes.length; i++) {
        const gap = primes[i] - primes[i-1];
        if (gap < bestGap) { bestGap = gap; best = [primes[i-1], primes[i]]; }
    }
    return best;
}

function categorizeBox(length, width, height, mass) {
    // Determine if the box is bulky (any dimension ≥ 10⁴ or volume ≥ 10⁹)
    const isBulky = length >= 1e4 || width >= 1e4 || height >= 1e4 ||
                    length * width * height >= 1e9;
    // Determine if the box is heavy (mass ≥ 100)
    const isHeavy = mass >= 100;

    if (isBulky && isHeavy) return "Both";
    if (isBulky) return "Bulky";
    if (isHeavy) return "Heavy";
    return "Neither";
}

function maxCount(nums) {
    const n = nums.length;

    // binary search for first index where value >= 0
    let lo = 0, hi = n;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (nums[mid] < 0) lo = mid + 1;
        else hi = mid;
    }
    const firstNonNeg = lo;               // negatives are all before this index

    // binary search for first index where value > 0
    lo = 0; hi = n;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (nums[mid] <= 0) lo = mid + 1;
        else hi = mid;
    }
    const firstPos = lo;                  // positives start from this index

    const negCount = firstNonNeg;
    const posCount = n - firstPos;
    return Math.max(negCount, posCount);
}

function maxScore(nums, k) {
    // build a max‑heap from the initial numbers
    const heap = [];
    for (const v of nums) heapPush(heap, v);

    let score = 0;
    for (let i = 0; i < k; i++) {
        const cur = heapPop(heap);          // take the current maximum
        score += cur;                       // add it to the total score
        heapPush(heap, Math.ceil(cur / 3)); // push the reduced value back
    }
    return score;
}

/* ---------- max‑heap helpers (max‑heap of numbers) ---------- */
function heapPush(arr, val) {
    arr.push(val);
    let i = arr.length - 1;
    while (i > 0) {
        const p = (i - 1) >> 1;
        if (arr[p] >= arr[i]) break;
        [arr[p], arr[i]] = [arr[i], arr[p]];
        i = p;
    }
}
function heapPop(arr) {
    if (arr.length === 0) return undefined;
    const top = arr[0];
    const last = arr.pop();
    if (arr.length) {
        arr[0] = last;
        let i = 0;
        while (true) {
            let l = i * 2 + 1,
                r = i * 2 + 2,
                largest = i;
            if (l < arr.length && arr[l] > arr[largest]) largest = l;
            if (r < arr.length && arr[r] > arr[largest]) largest = r;
            if (largest === i) break;
            [arr[i], arr[largest]] = [arr[largest], arr[i]];
            i = largest;
        }
    }
    return top;
}

function makeNumberOfDistinctCharactersEqual(word1, word2) {
    const freq1 = new Array(26).fill(0);
    const freq2 = new Array(26).fill(0);
    for (const ch of word1) { const idx = ch.charCodeAt(0) - 97; if (idx >= 0 && idx < 26) freq1[idx]++; }
    for (const ch of word2) { const idx = ch.charCodeAt(0) - 97; if (idx >= 0 && idx < 26) freq2[idx]++; }

    const d1 = freq1.filter(v => v > 0).length;
    const d2 = freq2.filter(v => v > 0).length;

    if (d1 === d2) return true;

    for (let a = 0; a < 26; a++) {
        if (!freq1[a]) continue;
        for (let b = 0; b < 26; b++) {
            if (!freq2[b]) continue;
            const delta1 = (freq1[b] === 0 ? 1 : 0) - (freq1[a] === 1 ? 1 : 0);
            const delta2 = (freq2[a] === 0 ? 1 : 0) - (freq2[b] === 1 ? 1 : 0);
            if (d1 + delta1 === d2 + delta2) return true;
        }
    }
    return false;
}

function timeToCrossBridge(n, k, time) {
    class Heap {
        constructor(cmp) { this.a = []; this.cmp = cmp; }
        get size() { return this.a.length; }
        peek() { return this.a[0]; }
        push(x) {
            const a = this.a; a.push(x);
            let i = a.length - 1;
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.cmp(a[p], a[i]) <= 0) break;
                [a[p], a[i]] = [a[i], a[p]];
                i = p;
            }
        }
        pop() {
            const a = this.a;
            const top = a[0];
            const last = a.pop();
            if (a.length) {
                a[0] = last;
                let i = 0;
                while (true) {
                    let l = 2*i+1, r = 2*i+2, s = i;
                    if (l < a.length && this.cmp(a[l], a[s]) < 0) s = l;
                    if (r < a.length && this.cmp(a[r], a[s]) < 0) s = r;
                    if (s === i) break;
                    [a[s], a[i]] = [a[i], a[s]];
                    i = s;
                }
            }
            return top;
        }
    }

    const right = time.map(t => t[0]);
    const pick = time.map(t => t[1]);
    const left = time.map(t => t[2]);
    const put = time.map(t => t[3]);
    const crossSum = time.map((t, i) => right[i] + left[i]);

    // "least efficient first" = highest crossSum, tie -> highest index
    const effCmp = (a, b) => {
        // a, b are worker indices
        if (crossSum[a] !== crossSum[b]) return crossSum[b] - crossSum[a]; // higher crossSum first
        return b - a; // higher index first
    };

    const waitingLeft = new Heap(effCmp);
    const waitingRight = new Heap(effCmp);
    for (let i = 0; i < k; i++) waitingLeft.push(i);

    const workingRight = new Heap((a, b) => a[0] - b[0]); // [finishTime, idx] picking on right
    const workingLeft = new Heap((a, b) => a[0] - b[0]);  // [finishTime, idx] putting on left

    let currentTime = 0;
    let boxesLeftToPick = n;
    let boxesPut = 0;

    function releaseUpTo(t) {
        while (workingRight.size && workingRight.peek()[0] <= t) {
            const [, idx] = workingRight.pop();
            waitingRight.push(idx);
        }
        while (workingLeft.size && workingLeft.peek()[0] <= t) {
            const [, idx] = workingLeft.pop();
            waitingLeft.push(idx);
        }
    }

    while (boxesPut < n) {
        releaseUpTo(currentTime);

        if (waitingRight.size > 0) {
            const idx = waitingRight.pop();
            currentTime += left[idx];
            boxesPut++;
            if (boxesPut === n) return currentTime;
            workingLeft.push([currentTime + put[idx], idx]);
        } else if (waitingLeft.size > 0 && boxesLeftToPick > 0) {
            const idx = waitingLeft.pop();
            boxesLeftToPick--;
            currentTime += right[idx];
            workingRight.push([currentTime + pick[idx], idx]);
        } else {
            // bridge idle - jump to next event
            let next = Infinity;
            if (workingRight.size) next = Math.min(next, workingRight.peek()[0]);
            if (workingLeft.size) next = Math.min(next, workingLeft.peek()[0]);
            currentTime = next;
        }
    }
    return currentTime;
}

function differenceOfSum(nums) {
    let elementSum = 0;
    let digitSum = 0;

    for (let i = 0; i < nums.length; i++) {
        const val = nums[i];
        elementSum += val;                     // add whole number to element sum

        // add each digit of the current number to digit sum
        let temp = val;
        while (temp > 0) {
            digitSum += temp % 10;
            temp = Math.floor(temp / 10);
        }
    }

    return Math.abs(elementSum - digitSum);
}

function countGoodSubarrays(nums, k) {
    const n = nums.length;
    if (k === 0) return (n * (n + 1)) / 2;          // all subarrays are good

    const freq = new Map();                         // frequency of each value in the window
    let left = 0;
    let pairs = 0;                                  // current number of equal‑value pairs
    let answer = 0;

    for (let right = 0; right < n; right++) {
        const val = nums[right];
        const cnt = freq.get(val) || 0;
        pairs += cnt;                               // new element forms `cnt` new pairs
        freq.set(val, cnt + 1);

        // shrink left while we already have enough pairs
        while (pairs >= k) {
            answer += n - right;                    // all extensions of this window are also good
            const leftVal = nums[left];
            const leftCnt = freq.get(leftVal);
            pairs -= leftCnt - 1;                    // removing left element loses those pairs
            freq.set(leftVal, leftCnt - 1);
            left++;
        }
    }
    return answer;
}

function isCircularSentence(sentence) {
    // Split the sentence into words
    var words = sentence.split(' ');
    // Check if the last character of each word is equal to the first character of the next word
    for (var i = 0; i < words.length - 1; i++) {
        if (words[i].charAt(words[i].length - 1) !== words[i + 1].charAt(0)) {
            return false;
        }
    }
    // Check if the last character of the last word is equal to the first character of the first word
    if (words[words.length - 1].charAt(words[words.length - 1].length - 1) !== words[0].charAt(0)) {
        return false;
    }
    return true;
}

function closestNodes(root, queries) {
    // perform in-order traversal to get the sorted array of node values
    let sortedValues = [];
    function inOrder(node) {
        if (node) {
            inOrder(node.left);
            sortedValues.push(node.val);
            inOrder(node.right);
        }
    }
    inOrder(root);

    let result = [];
    for (let query of queries) {
        // find the largest number that is smaller or equal to the query
        let mini = -1;
        for (let i = sortedValues.length - 1; i >= 0; i--) {
            if (sortedValues[i] <= query) {
                mini = sortedValues[i];
                break;
            }
        }
        // find the smallest number that is greater or equal to the query
        let maxi = -1;
        for (let i = 0; i < sortedValues.length; i++) {
            if (sortedValues[i] >= query) {
                maxi = sortedValues[i];
                break;
            }
        }
        result.push([mini, maxi]);
    }
    return result;
}

function unequalTriplets(nums) {
  let count = 0;
  // iterate over all possible triplets in the array
  for (let i = 0; i < nums.length; i++) {
    for (let j = 0; j < nums.length; j++) {
      for (let k = 0; k < nums.length; k++) {
        // check if the indices are distinct and in ascending order
        if (i < j && j < k) {
          // check if the values at the indices are distinct
          if (nums[i] !== nums[j] && nums[j] !== nums[k] && nums[i] !== nums[k]) {
            count++;
          }
        }
      }
    }
  }
  return count;
}

function maxNonOverlappingPalindromeSubstrings(s, k) {
    let count = 0;
    let left = 0;
    // loop through the string to find all possible substrings
    while (left < s.length) {
        let found = false;
        // try to find a palindrome substring of length at least k starting from the left pointer
        for (let right = left + k; right <= s.length; right++) {
            let substring = s.substring(left, right);
            // check if the substring is a palindrome
            if (isPalindrome(substring)) {
                // if it is, increment the count and move the left pointer to the right of the found substring
                count++;
                left = right;
                found = true;
                break;
            }
        }
        // if no palindrome substring is found, move the left pointer to the right
        if (!found) {
            left++;
        }
    }
    return count;
}

// helper function to check if a string is a palindrome
function isPalindrome(s) {
    let left = 0;
    let right = s.length - 1;
    while (left < right) {
        if (s[left] !== s[right]) {
            return false;
        }
        left++;
        right--;
    }
    return true;
}

function minimumFuelCost(roads, seats) {
    let graph = {};
    graph[0] = []; // the capital (node 0) must exist in the graph even with zero roads
    for (let i = 0; i < roads.length; i++) {
        if (!graph[roads[i][0]]) graph[roads[i][0]] = [];
        if (!graph[roads[i][1]]) graph[roads[i][1]] = [];
        graph[roads[i][0]].push(roads[i][1]);
        graph[roads[i][1]].push(roads[i][0]);
    }
    let res = 0;
    function dfs(node, parent) {
        let representatives = 1;
        for (let child of (graph[node] || [])) {
            if (child !== parent) {
                representatives += dfs(child, node);
            }
        }
        if (node !== 0) {
            res += Math.ceil(representatives / seats);
        }
        return representatives;
    }
    dfs(0, -1);
    return res;
}

function countPalindromicSubsequence(s) {
    const MOD = 1e9 + 7;
    const n = s.length;
    let count = 0;
    // generate all possible subsequences of length 5
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            for (let k = j + 1; k < n; k++) {
                for (let l = k + 1; l < n; l++) {
                    for (let m = l + 1; m < n; m++) {
                        let subsequence = s[i] + s[j] + s[k] + s[l] + s[m];
                        // check if the subsequence is a palindrome
                        let isPalindrome = true;
                        for (let p = 0; p < 2; p++) {
                            if (subsequence[p] !== subsequence[4 - p]) {
                                isPalindrome = false;
                                break;
                            }
                        }
                        if (isPalindrome) {
                            count = (count + 1) % MOD;
                        }
                    }
                }
            }
        }
    }
    return count;
}

function splitMessage(message, limit) {
    const n = message.length;
    function digits(x) { return String(x).length; }

    // find the smallest totalParts b such that the message actually fits,
    // accounting for the suffix "<i/b>" growing as i and b grow more digits
    let totalParts = -1;
    for (let b = 1; b <= n; b++) {
        let capacity = 0;
        let feasible = true;
        for (let i = 1; i <= b; i++) {
            const suffixLen = 3 + digits(i) + digits(b); // "<" + i + "/" + b + ">"
            const avail = limit - suffixLen;
            if (avail <= 0) { feasible = false; break; }
            capacity += avail;
            if (capacity >= n) break;
        }
        if (!feasible) continue;
        if (capacity >= n) { totalParts = b; break; }
    }
    if (totalParts === -1) return [];

    const result = [];
    let idx = 0;
    for (let i = 1; i <= totalParts; i++) {
        const suffix = `<${i}/${totalParts}>`;
        const partLen = Math.min(limit - suffix.length, n - idx);
        result.push(message.substring(idx, idx + partLen) + suffix);
        idx += partLen;
    }
    return result;
}

function maxPoints(grid, queries) {
    const m = grid.length;
    const n = grid[0].length;
    const directions = [[-1, 0], [1, 0], [0, -1], [0, 1]];
    const answer = [];

    for (let query of queries) {
        let count = 0;
        const visited = Array.from({ length: m }, () => Array(n).fill(false));
        const queue = [[0, 0]];
        // the points earned are the NUMBER OF CELLS reachable through a path
        // of values strictly LESS THAN query, starting from the top-left
        if (grid[0][0] < query) {
            visited[0][0] = true;
            let head = 0;
            while (head < queue.length) {
                const [row, col] = queue[head++];
                count++;
                for (const [dr, dc] of directions) {
                    const nr = row + dr;
                    const nc = col + dc;
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] && grid[nr][nc] < query) {
                        visited[nr][nc] = true;
                        queue.push([nr, nc]);
                    }
                }
            }
        }
        answer.push(count);
    }
    return answer;
}

function minimumOperations(root) {
    let result = 0;
    let queue = [root];
    while (queue.length > 0) {
        let levelSize = queue.length;
        let levelValues = [];
        for (let i = 0; i < levelSize; i++) {
            let node = queue.shift();
            levelValues.push(node.val);
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        let sortedLevelValues = levelValues.slice().sort((a, b) => a - b);
        // Create a mapping of original index to sorted index for each value
        let indexMapping = {};
        for (let i = 0; i < levelValues.length; i++) {
            indexMapping[levelValues[i]] = i;
        }
        let visited = new Array(levelSize).fill(false);
        for (let i = 0; i < levelSize; i++) {
            if (visited[i] || levelValues[i] === sortedLevelValues[i]) continue;
            let cycleSize = 0;
            let j = i;
            while (!visited[j]) {
                visited[j] = true;
                j = indexMapping[sortedLevelValues[j]];
                cycleSize++;
            }
            // Each cycle requires (cycleSize - 1) operations to sort
            result += (cycleSize - 1);
        }
    }
    return result;
}

function beautifulPartitions(s, k, minLength) {
    const MOD = 1000000007;
    const n = s.length;
    const isPrimeDigit = d => d === '2' || d === '3' || d === '5' || d === '7';
    const dp = Array(n + 1).fill(0).map(() => Array(k + 1).fill(0));
    dp[0][0] = 1;
    // a beautiful substring must START with a prime digit (2,3,5,7) and
    // END with a non-prime digit - this has nothing to do with whether the
    // substring read as a whole NUMBER is prime
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= k; j++) {
            for (let len = minLength; len <= i; len++) {
                const prev = i - len;
                if (isPrimeDigit(s[prev]) && !isPrimeDigit(s[i - 1])) {
                    dp[i][j] = (dp[i][j] + dp[prev][j - 1]) % MOD;
                }
            }
        }
    }
    return dp[n][k];
}

function cycleLengthQueries(n, queries) {
    function findDepth(node) {
        // depth of the root (node 1) is 1, not 0
        return Math.floor(Math.log2(node)) + 1;
    }

    function findLCA(a, b) {
        let depthA = findDepth(a);
        let depthB = findDepth(b);
        while (depthA > depthB) {
            // parent of node x in this 1-indexed complete binary tree is
            // floor(x/2), NOT floor((x-1)/2)+1 (that formula gives the
            // wrong ancestor, e.g. it maps node 5 to 3 instead of 2)
            a = Math.floor(a / 2);
            depthA--;
        }
        while (depthB > depthA) {
            b = Math.floor(b / 2);
            depthB--;
        }
        while (a !== b) {
            a = Math.floor(a / 2);
            b = Math.floor(b / 2);
        }
        return a;
    }

    let answer = [];
    for (let i = 0; i < queries.length; i++) {
        let a = queries[i][0];
        let b = queries[i][1];
        let lca = findLCA(a, b);
        let cycleLength = findDepth(a) + findDepth(b) - 2 * findDepth(lca) + 1;
        answer.push(cycleLength);
    }
    return answer;
}

function maxStarSum(vals, edges, k) {
    // Create an adjacency list for the graph
    const graph = Array(vals.length).fill(0).map(() => []);
    for (const [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }

    let maxSum = -Infinity;
    for (let i = 0; i < vals.length; i++) {
        // Sort the neighbors of the current node in descending order of their values
        const sortedNeighbors = graph[i].sort((a, b) => vals[b] - vals[a]);
        let sum = vals[i];
        // Add the values of the top k neighbors to the sum
        for (let j = 0; j < Math.min(k, sortedNeighbors.length); j++) {
            sum += vals[sortedNeighbors[j]];
        }
        // Update the maximum sum
        maxSum = Math.max(maxSum, sum);
    }
    return maxSum;
}

// TIME: O(n * m * log(m)) SPACE: O(n + m)

function minimumCommonValue(nums1, nums2) {
    let i = 0;               // pointer for nums1
    let j = 0;               // pointer for nums2

    // traverse both arrays until one pointer reaches the end
    while (i < nums1.length && j < nums2.length) {
        if (nums1[i] === nums2[j]) {
            // first match is the smallest common value because arrays are sorted
            return nums1[i];
        }
        if (nums1[i] < nums2[j]) {
            i++;               // advance the smaller element
        } else {
            j++;               // advance the smaller element
        }
    }
    return -1;               // no common element found
}

var minOperations = function(nums1, nums2, k) {
    if (k === 0) {
        return nums1.every((v,i)=>v===nums2[i]) ? 0 : -1;
    }
    const sum = arr => arr.reduce((a,b)=>a+b,0);
    if (sum(nums1) !== sum(nums2)) return -1;
    let positiveSum = 0;
    for (let i=0;i<nums1.length;i++) {
        const diff = nums1[i]-nums2[i];
        if (diff % k !== 0) return -1;
        if (diff > 0) positiveSum += diff;
    }
    return Math.floor(positiveSum/k);
};

function maxDifferenceBetweenMaxAndMinPriceSum(n, edges, price) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    function dfs(start) {
        const dist = new Array(n).fill(0);
        const parent = new Array(n).fill(-1);
        const stack = [start];
        dist[start] = price[start];
        while (stack.length) {
            const u = stack.pop();
            for (const v of adj[u]) {
                if (v === parent[u]) continue;
                parent[v] = u;
                dist[v] = dist[u] + price[v];
                stack.push(v);
            }
        }
        return { dist, parent };
    }

    // Find one endpoint of the diameter
    const first = dfs(0);
    let A = 0;
    for (let i = 0; i < n; i++) {
        if (first.dist[i] > first.dist[A]) A = i;
    }

    // Find the opposite endpoint
    const fromA = dfs(A);
    let B = A;
    for (let i = 0; i < n; i++) {
        if (fromA.dist[i] > fromA.dist[B]) B = i;
    }

    // Distances from both diameter ends
    const fromB = dfs(B);

    let answer = 0;
    for (let i = 0; i < n; i++) {
        const maxPath = Math.max(fromA.dist[i], fromB.dist[i]);
        const cost = maxPath - price[i];
        if (cost > answer) answer = cost;
    }
    return answer;
}

function sortTheStudents(score, k) {
