function alternatingDigitSum(n) {
  let sum = 0;
  let sign = 1; // starting sign is positive
  while (n > 0) {
    // extract the last digit and update the sign for the next iteration
    let digit = n % 10;
    sum += sign * digit;
    sign *= -1; // alternate the sign
    n = Math.floor(n / 10); // remove the last digit
  }
  return sum;
}

function distinctNumbers(n) {
  let distinctNums = new Set();
  let queue = [n];
  distinctNums.add(n);
  while (queue.length > 0) {
    let num = queue.shift();
    // for each number, check all its divisors
    for (let i = 2; i <= num; i++) {
      if (num % i === 1) {
        // if the divisor is not in the set, add it to the set and the queue
        if (!distinctNums.has(i)) {
          distinctNums.add(i);
          queue.push(i);
        }
      }
    }
  }
  return distinctNums.size;
}

