function countCollisions(n) {
    const MOD = 1000000007n;
    function powMod(base, exp, mod) {
        base %= mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    }
    // The only two collision-free configurations are: every monkey moves
    // clockwise, or every monkey moves counter-clockwise - exactly 2 ways,
    // regardless of whether n is even or odd.
    const total = powMod(2n, BigInt(n), MOD);
    let result = (total - 2n) % MOD;
    if (result < 0n) result += MOD;
    return Number(result);
}

