function incrementSubmatrices(n, queries) {
    // create (n+1)×(n+1) diff matrix filled with 0
    const diff = Array.from({ length: n + 1 }, () => Array(n + 1).fill(0));

    // apply each query to diff (difference array technique)
    for (const q of queries) {
        const [r1, c1, r2, c2] = q;
        diff[r1][c1] += 1;                     // top‑left corner
        diff[r1][c2 + 1] -= 1;                 // right side (if inside)
        diff[r2 + 1][c1] -= 1;                 // bottom side (if inside)
        diff[r2 + 1][c2 + 1] += 1;             // bottom‑right corner (if inside)
    }

    // build the final matrix by converting diff to its 2‑D prefix sum
    const result = Array.from({ length: n }, () => Array(n).fill(0));
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            // accumulate from top, left and subtract overlap
            let val = diff[i][j];
            if (i > 0) val += result[i - 1][j];
            if (j > 0) val += result[i][j - 1];
            if (i > 0 && j > 0) val -= result[i - 1][j - 1];
            result[i][j] = val;
        }
    }
    return result;
}

