function handleSumQueries(nums1, nums2, queries) {
    const n = nums1.length;
    const tree = new Array(4 * n).fill(0);   // segment tree storing count of 1s
    const lazy = new Array(4 * n).fill(false); // pending flip flags

    // build segment tree from nums1
    function build(idx, l, r) {
        if (l === r) {
            tree[idx] = nums1[l];
            return;
        }
        const mid = (l + r) >> 1;
        build(idx << 1, l, mid);
        build(idx << 1 | 1, mid + 1, r);
        tree[idx] = tree[idx << 1] + tree[idx << 1 | 1];
    }

    // apply flip to a node
    function applyFlip(idx, l, r) {
        tree[idx] = (r - l + 1) - tree[idx]; // 0↔1
        lazy[idx] = !lazy[idx];
    }

    // propagate pending flip to children
    function push(idx, l, r) {
        if (!lazy[idx]) return;
        const mid = (l + r) >> 1;
        applyFlip(idx << 1, l, mid);
        applyFlip(idx << 1 | 1, mid + 1, r);
        lazy[idx] = false;
    }

    // flip values in [ql, qr]
    function flipRange(idx, l, r, ql, qr) {
        if (qr < l || r < ql) return;
        if (ql <= l && r <= qr) {
            applyFlip(idx, l, r);
            return;
        }
        push(idx, l, r);
        const mid = (l + r) >> 1;
        flipRange(idx << 1, l, mid, ql, qr);
        flipRange(idx << 1 | 1, mid + 1, r, ql, qr);
        tree[idx] = tree[idx << 1] + tree[idx << 1 | 1];
    }

    build(1, 0, n - 1);

    let sumNums2 = nums2.reduce((a, b) => a + b, 0);
    const answer = [];

    for (const q of queries) {
        const type = q[0];
        if (type === 1) {
            const left = q[1];
            const right = q[2];
            flipRange(1, 0, n - 1, left, right); // range flip on nums1
        } else if (type === 2) {
            const val = q[1];
            sumNums2 += val * tree[1]; // total ones in nums1 = tree[1]
        } else if (type === 3) {
            answer.push(sumNums2);
        }
    }

    return answer;
}

