    while (n > 0) {
        if (n % 2 === 1) {                     // n is odd
            // decide whether to add or subtract a power of two
            if (n % 4 === 3 && n !== 3) {
                n += 1;                        // add 2^0 (effectively add 1)
            } else {
                n -= 1;                        // subtract 2^0 (effectively subtract 1)
            }
            ops++;                             // one operation performed
        }
        n = Math.floor(n / 2);                 // shift right: divide by 2
    }
    return ops;
