function countWays(ranges) {
    const MOD = 1000000007;

    // sort by start, then by end
    ranges.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

    let components = 0;
    let curMaxEnd = -Infinity;

    for (let i = 0; i < ranges.length; i++) {
        const [s, e] = ranges[i];
        if (s > curMaxEnd) {          // start of a new component
            components++;
            curMaxEnd = e;
        } else {                      // still inside current component
            if (e > curMaxEnd) curMaxEnd = e;
        }
    }

    // fast exponentiation: 2^components mod MOD
    let result = 1;
    let base = 2;
    let exp = components;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1;
    }
    return result;
}

function findTheString(lcp) {
    const n = lcp.length;
    const group = new Array(n).fill(-1);
    let numGroups = 0;
    for (let i = 0; i < n; i++) {
        if (group[i] !== -1) continue;
        group[i] = numGroups;
        for (let j = i+1; j < n; j++) {
            if (lcp[i][j] > 0 && group[j] === -1) group[j] = numGroups;
        }
        numGroups++;
    }
    if (numGroups > 26) return "";
    const word = new Array(n);
    for (let i = 0; i < n; i++) word[i] = String.fromCharCode(97 + group[i]);
    // verify: check consistency
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < n; j++) {
            if (word[i] !== word[j] && lcp[i][j] !== 0) return "";
        }
    }
    // recompute actual lcp from word and compare
    const actual = Array.from({length:n}, () => new Array(n).fill(0));
    for (let i = n-1; i >= 0; i--) {
        for (let j = n-1; j >= 0; j--) {
            if (word[i] === word[j]) {
                actual[i][j] = (i+1<n && j+1<n) ? actual[i+1][j+1]+1 : 1;
            }
        }
    }
    for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) if (actual[i][j] !== lcp[i][j]) return "";
    return word.join('');
}

function countNumberOfPossibleRootNodes(edges, guesses, k) {
    const n = edges.length + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [a, b] of edges) { adj[a].push(b); adj[b].push(a); }

    const guessSet = new Set(guesses.map(([u, v]) => u + ',' + v));

    const parent = new Array(n).fill(-1);
    let stack = [[0, -1]];
    let initialCorrect = 0;
    while (stack.length) {
        const [node, par] = stack.pop();
        parent[node] = par;
        for (const nb of adj[node]) {
            if (nb === par) continue;
            stack.push([nb, node]);
            if (guessSet.has(node + ',' + nb)) initialCorrect++;
        }
    }

    let answer = 0;
    stack = [[0, -1, initialCorrect]];
    while (stack.length) {
        const [node, par, correct] = stack.pop();
        if (correct >= k) answer++;
        for (const nb of adj[node]) {
            if (nb === par) continue;
            let newCorrect = correct;
            if (guessSet.has(node + ',' + nb)) newCorrect--;
            if (guessSet.has(nb + ',' + node)) newCorrect++;
            stack.push([nb, node, newCorrect]);
        }
    }
    return answer;
}

