var findMinimumTime = function(tasks) {
    if (!tasks.length) return 0;
    tasks = tasks.slice().sort((a,b)=>a[1]-b[1]);
    const maxTime = Math.max(...tasks.map(t=>t[1]));
    const selected = new Array(maxTime+1).fill(false);
    class Fenwick {
        constructor(n) { this.n=n; this.bit = new Array(n+1).fill(0); }
        add(idx, delta=1) { while (idx<=this.n) { this.bit[idx]+=delta; idx += idx & (-idx); } }
        sum(idx) { let s=0; while (idx>0) { s+=this.bit[idx]; idx -= idx & (-idx); } return s; }
    }
    const ft = new Fenwick(maxTime);
    let totalOn = 0;
    for (const [start, end, dur] of tasks) {
        const already = ft.sum(end) - ft.sum(start-1);
        let need = dur - already;
        if (need <= 0) continue;
        let t = end;
        while (need > 0 && t >= start) {
            if (!selected[t]) {
                selected[t] = true;
                ft.add(t, 1);
                totalOn++;
                need--;
            }
            t--;
        }
    }
    return totalOn;
};

