    // iterate through the specified range
    for (let i = left; i <= right; i++) {
        const word = words[i];
        // check first and last characters are vowels
        if (word && vowels.includes(word[0]) && vowels.includes(word[word.length - 1])) {
            count++;
        }
    }

    return count;
}

function countBeautifulSubarrays(nums) {
    const freq = new Map();
    freq.set(0, 1);
    let prefix = 0;
    let result = 0;
    for (let i = 0; i < nums.length; i++) {
        prefix ^= nums[i];
        const cnt = freq.get(prefix) || 0;
        result += cnt;
        freq.set(prefix, cnt + 1);
    }
    return result;
}

function maxScore(nums) {
    // sort numbers from largest to smallest to keep the running sum as high as possible early
    nums.sort((a, b) => b - a);

    let prefixSum = 0;
    let positiveCount = 0;

    for (let i = 0; i < nums.length; i++) {
        prefixSum += nums[i];
        if (prefixSum > 0) {
            positiveCount++;          // this prefix is positive
        } else {
            break;                    // once non‑positive, it can never become positive again
        }
    }
    return positiveCount;
}

function distributeMoney(money, children) {
    if (money < children) return -1;
    let maxEight = Math.min(children, Math.floor(money / 8));
    for (let cand = maxEight; cand >= 0; cand--) {
        const remMoney = money - cand * 8;
        const remChildren = children - cand;
        if (remChildren === 0) {
            // every dollar must be given out - leftover money with no
            // children left to receive it makes this candidate invalid
            if (remMoney === 0) return cand;
            continue;
        }
        if (remMoney < remChildren) continue; // can't give every remaining child at least $1
        if (remChildren === 1 && remMoney === 4) continue; // the last child would be forced to get exactly $4
        return cand;
    }
    return -1;
}

function minRepairTime(ranks, cars) {
    // lower bound (0 minutes) and upper bound (fastest mechanic alone)
    let low = 0;
    let minRank = Math.min(...ranks);
    let high = minRank * cars * cars;   // worst‑case time

    while (low < high) {
        const mid = Math.floor((low + high) / 2);

        // MAIN LOGIC: count how many cars can be repaired within 'mid' minutes
        let repaired = 0;
        for (let i = 0; i < ranks.length; i++) {
            repaired += Math.floor(Math.sqrt(mid / ranks[i]));
            if (repaired >= cars) break;   // early exit when enough cars are counted
        }

        if (repaired >= cars) {
            high = mid;                     // 'mid' minutes are sufficient
        } else {
            low = mid + 1;                  // need more time
        }
    }
    return low;
}

function numberOfEvenOddBits(n) {
    let evenCount = 0;
    let oddCount = 0;
    let index = 0;               // bit position, starting from LSB (0)

    while (n > 0) {
        if (n & 1) {             // current LSB is 1
            if (index % 2 === 0) {
                evenCount++;     // even index
            } else {
                oddCount++;      // odd index
            }
        }
        n >>= 1;                 // shift right to process next bit
        index++;                 // move to next position
    }

    return [evenCount, oddCount];
}

function findScore(nums) {
    const n = nums.length;
    // indices sorted by (value, index)
    const idx = Array.from({ length: n }, (_, i) => i);
    idx.sort((a, b) => {
        if (nums[a] !== nums[b]) return nums[a] - nums[b];
        return a - b;                     // left‑most tie‑breaker
    });

    const marked = new Array(n).fill(false);
    let score = 0;

    // MAIN LOGIC: walk through indices from smallest to largest
    for (const i of idx) {
        if (!marked[i]) {
            score += nums[i];
            marked[i] = true;                     // mark itself
            if (i - 1 >= 0) marked[i - 1] = true; // left neighbour
            if (i + 1 < n) marked[i + 1] = true;  // right neighbour
        }
    }
    return score;
}

function maxGreatness(nums) {
    const n = nums.length;
    const a = [...nums].sort((x, y) => x - y); // original values, sorted
    const b = [...nums].sort((x, y) => x - y); // pool of values, sorted

    let i = 0, j = 0, count = 0;

    // main greedy loop: match smallest possible larger element
    while (i < n && j < n) {
        if (b[j] > a[i]) {
            count++;
            i++;
            j++;
        } else {
            j++;
        }
    }
    return count;
}

function beautifulSubsets(nums, k) {
    // sort the whole array to group equal values together
    nums.sort((a, b) => a - b);

    // count how many times each value appears
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);

    // distinct values in increasing order
    const values = Array.from(cnt.keys()).sort((a, b) => a - b);
    const m = values.length;

    let totalWays = 1;          // product of ways of all independent chains
    let i = 0;

    while (i < m) {
        // start a new chain
        // dpPrevPrev = dp[i‑2], dpPrev = dp[i‑1] (for the previous value in the chain)
        let dpPrevPrev = 1;                     // dp[-1] = 1 (empty before chain)
        const w0 = Math.pow(2, cnt.get(values[i])) - 1;
        let dpPrev = 1 + w0;                    // dp[0] = 1 + w(v0)
        i++;

        // extend the chain while the next value differs exactly by k
        while (i < m && values[i] - values[i - 1] === k) {
            const w = Math.pow(2, cnt.get(values[i])) - 1;
            const cur = dpPrev + dpPrevPrev * w;   // dp[i] = dp[i‑1] + dp[i‑2] * w(vi)
            dpPrevPrev = dpPrev;
            dpPrev = cur;
            i++;
        }

        totalWays *= dpPrev;   // include the empty choice of this chain
    }

    return totalWays - 1;      // exclude the completely empty subset
}

function smallestMissingNonNegativeIntegerAfterOperations(nums, value) {
    const cnt = new Array(value).fill(0);
    for (const num of nums) {
        const m = ((num % value) + value) % value;
        cnt[m]++;
    }
    let mex = 0;
    while (cnt[mex % value]) {
        cnt[mex % value]--;
        mex++;
    }
    return mex;
}

function passThePillow(n, time) {
    // Edge case: only one person
    if (n === 1) return 1;

    const cycle = 2 * (n - 1);          // length of one back‑and‑forth cycle
    const r = time % cycle;             // position within the current cycle

    // If still moving forward, position increases; otherwise it moves backward
    if (r <= n - 1) {
        return 1 + r;
    } else {
        return n - (r - (n - 1));
    }
}

function kthLargestLevelSum(root, k) {
    if (!root) return -1;

    const queue = [root];
    let head = 0;
    const levelSums = [];

    // BFS to compute sum of each level
    while (head < queue.length) {
        const levelSize = queue.length - head;
        let sum = 0;
        for (let i = 0; i < levelSize; i++) {
            const node = queue[head++];
            sum += node.val;
            if (node.left) queue.push(node.left);
            if (node.right) queue.push(node.right);
        }
        levelSums.push(sum);
    }

    // sort sums descending and pick kth largest
    levelSums.sort((a, b) => b - a);
    return k <= levelSums.length ? levelSums[k - 1] : -1;
}

function primeSubOperation(nums) {
    const MAXV = 1000;
    const isComposite = new Array(MAXV + 1).fill(false);
    for (let i = 2; i * i <= MAXV; i++) {
        if (!isComposite[i]) for (let j = i * i; j <= MAXV; j += i) isComposite[j] = true;
    }
    const primes = [];
    for (let i = 2; i <= MAXV; i++) if (!isComposite[i]) primes.push(i);

    let prev = 0;
    // Process left to right, making each element as small as possible
    // (while staying strictly greater than the previous element) so later
    // elements have the most room to also satisfy the constraint.
    for (let i = 0; i < nums.length; i++) {
        const cur = nums[i];
        const maxAllowedSubtract = cur - prev - 1;
        let bestSubtract = 0; // "no operation" is always a valid option
        if (maxAllowedSubtract >= 2) {
            let lo = 0, hi = primes.length - 1, idx = -1;
            while (lo <= hi) {
                const mid = (lo + hi) >> 1;
                if (primes[mid] <= maxAllowedSubtract) { idx = mid; lo = mid + 1; }
                else hi = mid - 1;
            }
            if (idx !== -1) bestSubtract = Math.max(bestSubtract, primes[idx]);
        }
        const result = cur - bestSubtract;
        if (result <= prev) return false;
        prev = result;
    }
    return true;
}

function checkValidGrid(grid) {
    const n = grid.length;
    if (grid[0][0] !== 0) return false;
    const pos = new Array(n*n);
    for (let r = 0; r < n; r++) for (let c = 0; c < n; c++) pos[grid[r][c]] = [r,c];
    for (let i = 1; i < n*n; i++) {
        const [pr,pc] = pos[i-1];
        const [cr,cc] = pos[i];
        const dr = Math.abs(cr-pr), dc = Math.abs(cc-pc);
        if (!((dr===1&&dc===2)||(dr===2&&dc===1))) return false;
    }
    return true;
}

function smallestNumber(nums1, nums2) {
    // 1. look for the SMALLEST common digit (not just the first one
    //    encountered while scanning nums2) - if several digits are shared,
    //    picking the smallest one is what actually minimizes the result
    const set1 = new Set(nums1);
    let bestCommon = Infinity;
    for (const d of nums2) {
        if (set1.has(d) && d < bestCommon) bestCommon = d;
    }
    if (bestCommon < Infinity) return bestCommon; // return a number, not a string

    // 2. no common digit -> need a two-digit number
    let min1 = 10, min2 = 10;
    for (const d of nums1) if (d < min1) min1 = d;
    for (const d of nums2) if (d < min2) min2 = d;

    const cand1 = min1 * 10 + min2;
    const cand2 = min2 * 10 + min1;
    return Math.min(cand1, cand2);
}

function minOperations(nums, queries) {
    const n = nums.length;
    // sort the array to enable binary search
    const sorted = nums.slice().sort((a, b) => a - b);

    // build prefix sums: pref[i] = sum of first i elements
    const pref = new Array(n + 1);
    pref[0] = 0;
    for (let i = 0; i < n; i++) {
        pref[i + 1] = pref[i] + sorted[i];
    }
    const totalSum = pref[n];

    const answers = [];

    for (const q of queries) {
        // find first index > q (upper bound)
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (sorted[mid] <= q) lo = mid + 1;
            else hi = mid;
        }
        const k = lo; // count of elements <= q

        // left side cost: make all <= q become q
        const leftCost = q * k - pref[k];
        // right side cost: make all > q become q
        const rightCost = (totalSum - pref[k]) - q * (n - k);

        answers.push(leftCost + rightCost);
    }

    return answers;
}

function maximumCostSubstring(s, chars, vals) {
    // build map of special character values
    const valueMap = {};
    for (let i = 0; i < chars.length; i++) {
        valueMap[chars[i]] = vals[i];
    }

    let current = 0;   // current subarray sum
    let best = 0;      // best sum seen so far

    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        const v = valueMap.hasOwnProperty(ch) ? valueMap[ch] : 1; // value of character
        current = Math.max(0, current + v); // reset if sum becomes negative
        best = Math.max(best, current);     // update answer
    }

    return best; // empty substring yields 0, already handled
}

function collectCoinsInTree(coins, edges) {
    const n = coins.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }
    const degree = new Int32Array(n);
    for (let i = 0; i < n; i++) degree[i] = adj[i].length;
    const removed = new Uint8Array(n);
    const queue = [];
    for (let i = 0; i < n; i++) {
        if (degree[i] === 1 && coins[i] === 0) queue.push(i);
    }
    let qIdx = 0;
    while (qIdx < queue.length) {
        const u = queue[qIdx++];
        if (removed[u]) continue;
        removed[u] = 1;
        for (const v of adj[u]) {
            if (removed[v]) continue;
            degree[v]--;
            if (degree[v] === 1 && coins[v] === 0) queue.push(v);
        }
    }
    let leaves = [];
    for (let i = 0; i < n; i++) {
        if (!removed[i] && degree[i] === 1) leaves.push(i);
    }
    for (let round = 0; round < 2; round++) {
        const next = [];
        for (const u of leaves) {
            if (removed[u]) continue;
            removed[u] = 1;
            for (const v of adj[u]) {
                if (removed[v]) continue;
                degree[v]--;
                if (degree[v] === 1) next.push(v);
            }
        }
        leaves = next;
    }
    let remainingEdges = 0;
    // a removed node's own degree entry is stale - only its NEIGHBORS get
    // decremented when it's removed, never the node itself - so including
    // removed nodes in this sum drastically overcounts remaining edges
    for (let i = 0; i < n; i++) {
        if (!removed[i]) remainingEdges += degree[i];
    }
    remainingEdges = Math.floor(remainingEdges / 2);
    return Math.max(0, remainingEdges) * 2;
}

function findMatrix(nums) {
    const freq = new Map();
    let maxFreq = 0;

    for (const v of nums) {
        const cnt = (freq.get(v) || 0) + 1;
        freq.set(v, cnt);
        if (cnt > maxFreq) maxFreq = cnt;
    }

    // order distinct values by frequency descending, then by value
    // descending - iterating the Map in raw insertion order instead
    // produces a differently-ordered (though still technically valid)
    // layout that doesn't match the expected row contents
    const entries = [...freq.entries()].sort((a, b) => b[1] - a[1] || b[0] - a[0]);

    const rows = Array.from({ length: maxFreq }, () => []);
    for (const [num, count] of entries) {
        for (let i = 0; i < count; i++) {
            rows[i].push(num);
        }
    }

    return rows;
}

function makeKSubarraySumsEqual(arr, k) {
    const n = arr.length;
    if (n === 0) return 0;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);
    const g = gcd(n, k);
    const cycleLen = n / g;
    let totalOps = 0;

    for (let start = 0; start < g; start++) {
        const vals = [];
        let idx = start;
        for (let i = 0; i < cycleLen; i++) {
            vals.push(arr[idx]);
            idx = (idx + k) % n;
        }
        vals.sort((a, b) => a - b);
        const median = vals[Math.floor(cycleLen / 2)];
        for (const v of vals) totalOps += Math.abs(v - median);
    }
    return totalOps;
}

function longestBalancedSubstring(s) {
    let maxLen = 0;
    let prevRunChar = '';
    let prevRunLen = 0;
    let curRunLen = 0;

    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        if (i === 0 || c === s[i - 1]) {
            curRunLen++;                     // extend current run
        } else {
            // run changed: evaluate zero→one transition
            if (prevRunChar === '0' && c === '1') {
                const candidate = 2 * Math.min(prevRunLen, curRunLen);
                if (candidate > maxLen) maxLen = candidate; // update answer
            }
            // shift runs
            prevRunChar = s[i - 1];
            prevRunLen = curRunLen;
            curRunLen = 1;                    // start new run with c
        }
    }

    // handle the final transition if the string ends with a '1' run
    if (prevRunChar === '0' && s[s.length - 1] === '1') {
        const candidate = 2 * Math.min(prevRunLen, curRunLen);
        if (candidate > maxLen) maxLen = candidate;
    }

    return maxLen;
}

function minimumReverseOperations(n, p, banned, k) {
    const answer = new Array(n).fill(-1);
    const nxt = new Int32Array(n + 2);
    for (let i = 0; i <= n + 1; i++) nxt[i] = i;

    function find(i) {
        if (i >= n) return n;
        if (nxt[i] === i) return i;
        return nxt[i] = find(nxt[i]);
    }

    function remove(i) {
        nxt[i] = find(i + 2);
    }

    // mark banned positions as removed
    for (const b of banned) {
        remove(b);
    }

    // start position
    answer[p] = 0;
    remove(p);
    const queue = [p];
    let head = 0;

    while (head < queue.length) {
        const x = queue[head++];
        const dMin = Math.max(0, x - (n - k));
        const dMax = Math.min(k - 1, x);
        let L = x + (k - 1) - 2 * dMax;
        let R = x + (k - 1) - 2 * dMin;
        if (L < 0) L = 0;
        if (R >= n) R = n - 1;
        if (L > R) continue;

        let cur = find(L);
        while (cur <= R) {
            answer[cur] = answer[x] + 1;
            queue.push(cur);
            const next = find(cur + 2);
            nxt[cur] = next;
            cur = next;
        }
    }

    return answer;
}

var findShortestCycle = function(n, edges) {
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
    const INF = 1e9;
    let best = INF;
    for (let s=0;s<n;s++) {
        const dist = new Array(n).fill(-1);
        const parent = new Array(n).fill(-1);
        const q = [s];
        dist[s] = 0;
        let head = 0;
        while (head < q.length) {
            const u = q[head++];
            for (const v of adj[u]) {
                if (dist[v] === -1) {
                    dist[v] = dist[u]+1;
                    parent[v] = u;
                    q.push(v);
                } else if (parent[u] !== v) {
                    const cycleLen = dist[u]+dist[v]+1;
                    if (cycleLen < best) best = cycleLen;
                }
            }
        }
        if (best === 3) break;
    }
    return best === INF ? -1 : best;
};

function maxSum(numOnes, numZeros, numNegOnes, k) {
    // Pick as many 1's as possible
    const onesPicked = Math.min(numOnes, k);
    let remaining = k - onesPicked;

    // Then pick 0's (they don't change the sum)
    const zerosPicked = Math.min(numZeros, remaining);
    remaining -= zerosPicked;

    // Whatever is still needed must be -1's, each decreasing the sum by 1
    const negOnesPicked = Math.min(numNegOnes, remaining);
    const sum = onesPicked - negOnesPicked; // zeros contribute 0

    return sum;
}

function minimumNumberOfVisitedCellsInAGrid(grid) {
    const m = grid.length, n = grid[0].length;
    if (m === 1 && n === 1) return 1;

    const rowParent = Array.from({length: m}, () => Array.from({length: n + 1}, (_, i) => i));
    const colParent = Array.from({length: n}, () => Array.from({length: m + 1}, (_, i) => i));

    const findRow = (r, c) => {
        while (rowParent[r][c] !== c) {
            rowParent[r][c] = rowParent[r][rowParent[r][c]];
            c = rowParent[r][c];
        }
        return c;
    };
    const findCol = (c, r) => {
        while (colParent[c][r] !== r) {
            colParent[c][r] = colParent[c][colParent[c][r]];
            r = colParent[c][r];
        }
        return r;
    };

    const q = [[0, 0, 1]];
    let head = 0;
    rowParent[0][0] = 1;
    colParent[0][0] = 1;

    while (head < q.length) {
        const [i, j, dist] = q[head++];
        if (i === m - 1 && j === n - 1) return dist;
        const jump = grid[i][j];
        if (jump === 0) continue;

        let limit = Math.min(n - 1, j + jump);
        let col = findRow(i, j + 1);
        while (col <= limit) {
            q.push([i, col, dist + 1]);
            rowParent[i][col] = col + 1;
            colParent[col][i] = i + 1;
            col = findRow(i, col + 1);
        }

        limit = Math.min(m - 1, i + jump);
        let row = findCol(j, i + 1);
        while (row <= limit) {
            q.push([row, j, dist + 1]);
            rowParent[row][j] = j + 1;
            colParent[j][row] = row + 1;
            row = findCol(j, row + 1);
        }
    }
    return -1;
}

function maxPoints(reward1, reward2, k) {
    const n = reward1.length;
    // baseline: second mouse eats everything
    let total = 0;
    const diffs = new Array(n);
    for (let i = 0; i < n; i++) {
        total += reward2[i];
        diffs[i] = reward1[i] - reward2[i];   // gain if first mouse takes this cheese
    }
    // pick k cheeses with largest gain for the first mouse
    diffs.sort((a, b) => b - a);               // descending order
    for (let i = 0; i < k; i++) {
        total += diffs[i];
    }
    return total;
}

function primeInDiagonal(nums) {
    // handle empty matrix
    if (!nums.length) return 0;
    const rows = nums.length;
    const cols = nums[0].length;
    let maxPrime = 0;

    // iterate over each possible row index for a diagonal element
    for (let i = 0; i < rows; i++) {
        // ----- main diagonal (i,i) -----
        if (i < cols) {
            const val = nums[i][i];
            if (isPrime(val) && val > maxPrime) maxPrime = val;
        }

        // ----- anti‑diagonal (i, cols‑1‑i) -----
        const antiCol = cols - 1 - i;
        if (antiCol >= 0 && antiCol < cols) {
            // avoid double‑counting the centre cell of an odd‑sized square
            if (i !== antiCol) {
                const val = nums[i][antiCol];
                if (isPrime(val) && val > maxPrime) maxPrime = val;
            }
        }
    }
    return maxPrime;
}

// primality test using trial division up to sqrt(n)
function isPrime(n) {
    if (n < 2) return false;
    if (n % 2 === 0) return n === 2;
    for (let d = 3; d * d <= n; d += 2) {
        if (n % d === 0) return false;
    }
    return true;
}


// TIME: O(min(rows, cols) * √V)  SPACE: O(1)

function minimizeMaxDifference(nums, p) {
    const n = nums.length;
    if (p === 0) return 0;                     // no pairs needed

    const a = nums.slice().sort((x, y) => x - y); // sort to enable greedy pairing

    // binary search on the answer
    let low = 0;
    let high = a[n - 1] - a[0];                 // maximal possible difference

    // check if we can create at least p pairs with max diff <= limit
    function canForm(limit) {
        let cnt = 0;
        for (let i = 0; i < n - 1; ) {
            if (a[i + 1] - a[i] <= limit) {    // greedy pair
                cnt++;
                i += 2;                         // skip both indices
            } else {
                i += 1;                         // try next element as left partner
            }
        }
        return cnt;
    }

    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        if (canForm(mid) >= p) {
            high = mid;                         // feasible, try smaller limit
        } else {
            low = mid + 1;                      // not enough pairs, increase limit
        }
    }
    return low;
}

function checkIfInstanceOf(value, cls) {
    if (typeof cls !== 'function') return false;
    if (value === null || value === undefined) return false;
    // box primitives (numbers, strings, booleans) so they get a real prototype chain
    const obj = Object(value);
    let proto = Object.getPrototypeOf(obj);
    while (proto !== null) {
        if (proto === cls.prototype) return true;
        proto = Object.getPrototypeOf(proto);
    }
    return false;
}

function TimeLimitedCache() {
  const map = new Map();               // key → {value, expire, timer}
  let active = 0;                      // number of un‑expired keys

  function set(key, value, duration) {
    const now = Date.now();
    const existing = map.get(key);
    const stillValid = existing && existing.expire > now;

    if (stillValid) clearTimeout(existing.timer);   // cancel old expiration

    // schedule removal after `duration` ms
    const timer = setTimeout(() => {
      map.delete(key);
      active--;
    }, duration);

    map.set(key, { value, expire: now + duration, timer });

    if (!stillValid) active++;          // new un‑expired entry
    return !!stillValid;                // true if overwritten un‑expired key
  }

  function get(key) {
    const now = Date.now();
    const entry = map.get(key);
    if (entry && entry.expire > now) {
      return entry.value;                // still valid
    }
    if (entry) {                         // expired but timer not fired yet
      clearTimeout(entry.timer);
      map.delete(key);
      active--;
    }
    return -1;
  }

  function count() {
    return active;                       // current number of un‑expired keys
  }

  return { set, get, count };
}

function sumOfDistances(nums) {
    const n = nums.length;
    const ans = new Array(n).fill(0);
    const groups = new Map();               // map value → list of indices

    // collect indices for each distinct value
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        if (!groups.has(v)) groups.set(v, []);
        groups.get(v).push(i);
    }

    // process each group independently
    for (const idxList of groups.values()) {
        const m = idxList.length;
        if (m <= 1) continue;               // no other equal element

        // prefix sums of indices
        const pref = new Array(m);
        pref[0] = idxList[0];
        for (let k = 1; k < m; k++) pref[k] = pref[k - 1] + idxList[k];
        const totalSum = pref[m - 1];

        // compute answer for each position in the group
        for (let p = 0; p < m; p++) {
            const i = idxList[p];
            const leftCount = p;
            const leftSum = p > 0 ? pref[p - 1] : 0;
            const rightCount = m - p - 1;
            const rightSum = totalSum - leftSum - i;

            // sum of distances to all other equal elements
            ans[i] = i * leftCount - leftSum + rightSum - i * rightCount;
        }
    }

    return ans;
}

function counter(n) {
    let current = n;                     // store the next value to return
    return function() {
        const result = current;          // capture current value
        current += 1;                    // prepare next value
        return result;
    };
}

function memoize(fn) {
    const cache = new Map();          // stores results for each unique argument list
    let callCount = 0;                // counts how many times fn is really executed

    function memoized(...args) {
        const key = args.join('|');   // create a simple key from the arguments
        if (cache.has(key)) {         // MAIN LOGIC: return cached value if we have seen this input
            return cache.get(key);
        }
        const result = fn(...args);   // otherwise compute, cache and count the call
        cache.set(key, result);
        callCount++;
        return result;
    }

    // expose a way to query the real call count
    memoized.getCallCount = function () {
        return callCount;
    };

    return memoized;
}

// TIME: O(k) per call (k = number of arguments) SPACE: O(m) where m = number of distinct argument sets stored in the cache.

function snail(nums, rowsCount, colsCount) {
    // invalid dimensions or mismatched size
    if (
        !Number.isInteger(rowsCount) ||
        !Number.isInteger(colsCount) ||
        rowsCount <= 0 ||
        colsCount <= 0 ||
        rowsCount * colsCount !== nums.length
    ) {
        return [];
    }

    const result = Array.from({ length: rowsCount }, () => Array(colsCount));
    let idx = 0;

    // fill column by column, alternating direction
    for (let col = 0; col < colsCount; col++) {
        if (col % 2 === 0) {
            // top -> bottom
            for (let row = 0; row < rowsCount; row++) {
                result[row][col] = nums[idx++];
            }
        } else {
            // bottom -> top
            for (let row = rowsCount - 1; row >= 0; row--) {
                result[row][col] = nums[idx++];
            }
        }
    }

    return result;
}

function debounce(fn, wait) {
    let timerId = null;                     // holds the pending timeout

    return function (...args) {
        // cancel previous scheduled call if it hasn't run yet
        if (timerId !== null) clearTimeout(timerId);

        // schedule fn to run after `wait` ms with the latest arguments
        timerId = setTimeout(() => {
            fn.apply(this, args);
        }, wait);
    };
}

// TIME: O(1) per call, O(n) total SPACE: O(1)

function flattenDepth(arr, n) {
    const result = [];

    // recursively traverse and flatten when current depth is less than n
    function dfs(subArr, depth) {
        for (let i = 0; i < subArr.length; i++) {
            const elem = subArr[i];
            if (Array.isArray(elem) && depth < n) {
                dfs(elem, depth + 1);
            } else {
                result.push(elem);
            }
        }
    }

    dfs(arr, 0);
    return result;
}

function sleep(millis) {
    // Resolve the promise after the specified delay
    return new Promise(resolve => setTimeout(resolve, millis));
}

function last(arr) {
    // return last element or -1 if the array is empty
    return arr.length ? arr[arr.length - 1] : -1;
}

function arrayReduceTransform(nums, fn, init) {
    // start with the initial accumulator value
    let accumulator = init;

    // process each element sequentially
    for (let i = 0; i < nums.length; i++) {
        accumulator = fn(accumulator, nums[i]);
    }

    return accumulator;
}

// Add a groupBy method to all arrays
Array.prototype.groupBy = function (fn) {
  const groups = {};                     // result object

  // MAIN LOGIC: iterate through the array and collect items by their key
  for (let i = 0; i < this.length; i++) {
    const item = this[i];
    const key = fn(item);                // compute grouping key
    if (!groups.hasOwnProperty(key)) {
      groups[key] = [];                  // create bucket if it doesn't exist
    }
    groups[key].push(item);              // preserve original order
  }

  return groups;
};

function memoize(fn) {
  const root = new Map();                 // root of the nested map cache
  const RESULT = Symbol('result');        // unique key for stored result

  return function(...args) {
    let node = root;
    // traverse/create a path for each argument using === equality
    for (const arg of args) {
      if (!node.has(arg)) node.set(arg, new Map());
      node = node.get(arg);
    }
    // if result already cached, return it
    if (node.has(RESULT)) return node.get(RESULT);
    // otherwise compute, cache, and return
    const value = fn(...args);
    node.set(RESULT, value);
    return value;
  };
}

function compose(functions) {
    // Return a function that applies the given functions from right to left
    return function(x) {
        let result = x;
        // Iterate over the array backwards, feeding the result into each function
        for (let i = functions.length - 1; i >= 0; i--) {
            result = functions[i](result);
        }
        return result;
    };
}

function timeLimit(fn, t) {
    return function (...args) {
        return new Promise((resolve, reject) => {
            const timeoutId = setTimeout(() => {
                reject("Time Limit Exceeded");   // reject if limit reached
            }, t);

            fn(...args)                           // run the original async function
                .then((value) => {
                    clearTimeout(timeoutId);     // cancel timer on success
                    resolve(value);
                })
                .catch((err) => {
                    clearTimeout(timeoutId);     // cancel timer on error
                    reject(err);
                });
        });
    };
}

function filter(arr, fn) {
  const result = [];                     // store elements that pass the test
  for (let i = 0; i < arr.length; i++) {
    // evaluate predicate with element and its index
    if (fn(arr[i], i)) {
      result.push(arr[i]);                // keep the element
    }
  }
  return result;
}

function map(arr, fn) {
    var result = new Array(arr.length);
    for (var i = 0; i < arr.length; i++) {
        // apply the mapping function to the current element and its index
        result[i] = fn(arr[i], i);
    }
    return result;
}

function Graph(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) adj[u].push([v, w]);

    const heap = [];
    function heapPush(item) {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p][0] <= heap[i][0]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    }
    function heapPop() {
        const top = heap[0];
        const last = heap.pop();
        if (heap.length) {
            heap[0] = last;
            let i = 0;
            while (true) {
                let l = i * 2 + 1, r = i * 2 + 2, smallest = i;
                if (l < heap.length && heap[l][0] < heap[smallest][0]) smallest = l;
                if (r < heap.length && heap[r][0] < heap[smallest][0]) smallest = r;
                if (smallest === i) break;
                [heap[i], heap[smallest]] = [heap[smallest], heap[i]];
                i = smallest;
            }
        }
        return top;
    }

    function addEdge(edge) {
        const [u, v, w] = edge;
        adj[u].push([v, w]);
    }

    function shortestPath(src, dst) {
        if (src === dst) return 0;
        const dist = new Array(n).fill(Infinity);
        dist[src] = 0;
        heap.length = 0;
        heapPush([0, src]);
        while (heap.length) {
            const [d, u] = heapPop();
            if (d !== dist[u]) continue;
            if (u === dst) return d;
            for (const [v, w] of adj[u]) {
                const nd = d + w;
                if (nd < dist[v]) { dist[v] = nd; heapPush([nd, v]); }
            }
        }
        return -1;
    }

    return { addEdge, shortestPath };
}

function columnWidths(grid) {
    const rows = grid.length;
    const cols = grid[0].length;
    const ans = new Array(cols).fill(0);

    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const len = grid[i][j].toString().length; // length of current element
            if (len > ans[j]) ans[j] = len;            // keep the maximum for this column
        }
    }
    return ans;
}

function replaceValueInTree(root) {
    if (!root) return null;
    let queue = [[root, null]];
    while (queue.length) {
        const level = queue;
        queue = [];
        const levelSum = level.reduce((s, [node]) => s + node.val, 0);
        const parentSum = new Map();
        for (const [node, parent] of level) {
            parentSum.set(parent, (parentSum.get(parent) || 0) + node.val);
        }
        for (const [node, parent] of level) {
            node.val = levelSum - parentSum.get(parent);
        }
        for (const [node] of level) {
            if (node.left) queue.push([node.left, node]);
            if (node.right) queue.push([node.right, node]);
        }
    }
    return root;
}

function maxDivScore(nums, divisors) {
    let bestDivisor = divisors[0];
    let bestScore   = 0;

    // iterate over each divisor
    for (let i = 0; i < divisors.length; i++) {
        const d = divisors[i];
        let cnt = 0;

        // count how many nums are divisible by d
        for (let j = 0; j < nums.length; j++) {
            if (nums[j] % d === 0) cnt++;
        }

        // update best result (higher score or same score with smaller divisor)
        if (cnt > bestScore || (cnt === bestScore && d < bestDivisor)) {
            bestScore   = cnt;
            bestDivisor = d;
        }
    }

    return bestDivisor;
}

function minimumTotalPrice(n, edges, price, trips) {
    const adj = Array.from({length:n}, () => []);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
    const count = new Array(n).fill(0);
    function findPath(start, end) {
        const parent = new Array(n).fill(-1);
        const vis = new Array(n).fill(false);
        const stack = [start]; vis[start]=true;
        while (stack.length) {
            const u = stack.pop();
            if (u === end) break;
            for (const v of adj[u]) if (!vis[v]) { vis[v]=true; parent[v]=u; stack.push(v); }
        }
        let cur = end;
        while (cur !== -1) { count[cur]++; cur = parent[cur]; }
    }
    for (const [s,e] of trips) findPath(s,e);
    const memo = new Map();
    function dfs(u, parent, halved) {
        const key = u*2 + (halved?1:0) + parent*1000000;
        if (memo.has(key)) return memo.get(key);
        let res = halved ? Math.floor(price[u]*count[u]/2) : price[u]*count[u];
        for (const v of adj[u]) {
            if (v === parent) continue;
            if (halved) res += dfs(v, u, false);
            else res += Math.min(dfs(v, u, true), dfs(v, u, false));
        }
        memo.set(key, res);
        return res;
    }
    return Math.min(dfs(0,-1,true), dfs(0,-1,false));
}

function findArrayConcatenationValue(nums) {
    let concatenationValue = 0;
    while (nums.length > 0) {
        // Check if there is more than one element in the array
        if (nums.length > 1) {
            // Concatenate the first and last elements and add to the concatenation value
            concatenationValue += parseInt(nums.shift() + '' + nums.pop());
        } else {
            // If there is only one element, add it to the concatenation value
            concatenationValue += nums.shift();
        }
    }
    return concatenationValue;
}

function maximumNumbers(banned, n, maxSum) {
    let sum = 0, count = 0;
    let set = new Set(banned);
    // iterate over the range and check if each number is banned
    for (let i = 1; i <= n; i++) {
        // if the number is not banned and adding it to the sum doesn't exceed maxSum
        if (!set.has(i) && sum + i <= maxSum) {
            sum += i; // add the number to the sum
            count++; // increment the count
        }
    }
    return count;
}

function minCapability(nums, k) {
    let left = Math.min(...nums);
    let right = Math.max(...nums);
    // perform binary search to find the minimum capability
    while (left < right) {
        let mid = Math.floor((left + right) / 2);
        let count = 0;
        let prev = -2;
        // count the number of houses that can be robbed with the current capability
        for (let i = 0; i < nums.length; i++) {
            if (nums[i] <= mid && i - prev >= 2) {
                count++;
                prev = i;
            }
        }
        // if the number of houses that can be robbed is less than k, increase the capability
        if (count < k) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

function findValidSplit(nums) {
    function gcd(a, b) {
        if (b === 0n) return a;
        return gcd(b, a % b);
    }

    let totalProduct = 1n;
    for (let num of nums) totalProduct *= BigInt(num);

    let leftProduct = 1n;
    // i must leave at least one element on the right side, so the last
    // valid split index is nums.length - 2
    for (let i = 0; i < nums.length - 1; i++) {
        // include nums[i] in the left partition BEFORE checking - a split
        // at index i means left = nums[0..i], right = nums[i+1..]
        leftProduct *= BigInt(nums[i]);
        let rightProduct = totalProduct / leftProduct;
        if (gcd(leftProduct, rightProduct) === 1n) return i;
    }
    return -1;
}

function minimumScore(s, t) {
    const n = s.length, m = t.length;
    const INF = n + 1;
    // suf[j] = smallest s-index such that t[j:] is a subsequence of s[suf[j]:]
    // suf[m] = n (empty suffix, trivially satisfied); INF = infeasible
    const suf = new Array(m + 1).fill(INF);
    suf[m] = n;
    let si = n - 1;
    for (let tj = m - 1; tj >= 0; tj--) {
        while (si >= 0 && s[si] !== t[tj]) si--;
        if (si < 0) break; // remaining suf[0..tj] stay infeasible
        suf[tj] = si;
        si--;
    }

    // greedily match a growing PREFIX of t from the left of s (using the
    // earliest possible s positions, to leave maximum room for a suffix),
    // and for each prefix length find the best already-computed suffix
    // that starts after the prefix's last used s position
    let best = m; // fallback: remove all of t
    let sPos = -1; // last s-index used to match the kept prefix of t
    let j = 0;
    for (let i = 0; i <= m; i++) {
        if (j < i) j = i; // suffix can't start before the prefix ends
        while (j <= m && (suf[j] === INF || suf[j] <= sPos)) j++;
        if (j <= m) best = Math.min(best, j - i);
        if (i < m) {
            let p = sPos + 1;
            while (p < n && s[p] !== t[i]) p++;
            if (p >= n) break;
            sPos = p;
        }
    }
    return best;
}

function maxDiff(num) {
    let numStr = num.toString();
    let maxNum = num;
    let minNum = num;
    // iterate through each digit to find the maximum possible value
    for (let i = 0; i < 10; i++) {
        for (let j = 0; j < 10; j++) {
            if (i === j) continue;
            let tempNum = numStr;
            // replace all occurrences of digit i with digit j
            tempNum = tempNum.split(i.toString()).join(j.toString());
            let tempNumInt = parseInt(tempNum);
            // update maxNum if the current number is larger
            if (tempNumInt > maxNum) maxNum = tempNumInt;
            // update minNum if the current number is smaller
            if (tempNumInt < minNum) minNum = tempNumInt;
        }
    }
    // return the difference between the maximum and minimum values
    return maxNum - minNum;
}

function substringXorQueries(s, queries) {
    const n = s.length;
    const ans = new Array(queries.length).fill(null).map(() => [-1, -1]);
    for (let i = 0; i < queries.length; i++) {
        const target = queries[i][0] ^ queries[i][1];
        let found = false;
        // iterate by LENGTH first (shortest to longest), then by start
        // index, so the first match found is the shortest one, and ties
        // on length resolve to the smallest start index
        for (let len = 1; len <= n && !found; len++) {
            for (let j = 0; j + len <= n && !found; j++) {
                let val = 0;
                for (let k = j; k < j + len; k++) {
                    val = (val << 1) | (s[k] === '1' ? 1 : 0);
                }
                if (val === target) {
                    ans[i] = [j, j + len - 1];
                    found = true;
                }
            }
        }
    }
    return ans;
}

function minCost(basket1, basket2) {
    // net (freq1 - freq2) per value across the WHOLE combined input
    const cnt = {};
    for (const x of basket1) cnt[x] = (cnt[x] || 0) + 1;
    for (const x of basket2) cnt[x] = (cnt[x] || 0) - 1;

    let globalMin = Infinity;
    for (const x of basket1) if (x < globalMin) globalMin = x;
    for (const x of basket2) if (x < globalMin) globalMin = x;

    // for each value with a net imbalance, half of the imbalance must
    // change baskets; collect all such "excess" items into one pool
    const excess = [];
    for (const key in cnt) {
        const c = cnt[key];
        if (c % 2 !== 0) return -1; // combined count for this value must be even
        const v = Number(key);
        for (let i = 0; i < Math.abs(c) / 2; i++) excess.push(v);
    }
    excess.sort((a, b) => a - b);

    // only the cheaper HALF of the excess pool actually needs to move (each
    // swap resolves one excess unit from each side simultaneously); for
    // each, either swap the two mismatched items directly, or route
    // through the globally cheapest item twice (swap it in, then out),
    // whichever is cheaper
    let total = 0;
    const half = excess.length / 2;
    for (let i = 0; i < half; i++) {
        total += Math.min(excess[i], 2 * globalMin);
    }
    return total;
}

function maximizeWin(prizePositions, k) {
    let maxPrizes = 0;
    // Calculate the total number of prizes for each possible segment
    for (let i = 0; i < prizePositions.length; i++) {
        let leftSegmentCount = 0;
        // Count the number of prizes in the left segment
        for (let j = 0; j < prizePositions.length; j++) {
            if (prizePositions[j] >= prizePositions[i] && prizePositions[j] <= prizePositions[i] + k) {
                leftSegmentCount++;
            }
        }
        for (let j = 0; j < prizePositions.length; j++) {
            let rightSegmentCount = 0;
            // Count the number of prizes in the right segment
            for (let m = 0; m < prizePositions.length; m++) {
                if (prizePositions[m] >= prizePositions[j] && prizePositions[m] <= prizePositions[j] + k) {
                    rightSegmentCount++;
                }
            }
            // Update the maximum number of prizes
            maxPrizes = Math.max(maxPrizes, leftSegmentCount + rightSegmentCount - 
            // Count the number of prizes that are in both segments
            countOverlappingPrizes(prizePositions, prizePositions[i], prizePositions[i] + k, prizePositions[j], prizePositions[j] + k));
        }
    }
    return maxPrizes;
}

function countOverlappingPrizes(prizePositions, leftStart, leftEnd, rightStart, rightEnd) {
    let overlappingCount = 0;
    for (let i = 0; i < prizePositions.length; i++) {
        if (prizePositions[i] >= Math.max(leftStart, rightStart) && prizePositions[i] <= Math.min(leftEnd, rightEnd)) {
            overlappingCount++;
        }
    }
    return overlappingCount;
}

function countFairPairs(nums, lower, upper) {
    nums.sort((a, b) => a - b);
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        // only search among j > i (positions AFTER i in the sorted array)
        // to count each unordered index pair exactly once
        let left = binarySearch(nums, i + 1, lower - nums[i]);
        let right = binarySearch(nums, i + 1, upper - nums[i] + 1);
        count += right - left;
    }
    return count;
}

function binarySearch(nums, from, target) {
    let left = from;
    let right = nums.length;
    while (left < right) {
        let mid = Math.floor((left + right) / 2);
        if (nums[mid] < target) {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    return left;
}

function minCost(nums, k) {
    let n = nums.length;
    let dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        let count = {};
        let uniqueCount = 0;
        for (let j = i - 1; j >= 0; j--) {
            // calculate the importance value of the current subarray
            if (count[nums[j]] === undefined) {
                count[nums[j]] = 1;
                uniqueCount++;
            } else if (count[nums[j]] === 1) {
                count[nums[j]]++;
                uniqueCount--;
            } else {
                count[nums[j]]++;
            }
            // update dp array with the minimum cost
            dp[i] = Math.min(dp[i], dp[j] + k + (i - j - uniqueCount));
        }
    }
    return dp[n];
}

function countVowelStrings(words, queries) {
    var vowels = 'aeiou';
    var vowelCount = new Array(words.length).fill(0);
    for (var i = 0; i < words.length; i++) {
        // check if the word starts and ends with a vowel
        if (vowels.includes(words[i][0]) && vowels.includes(words[i][words[i].length - 1])) {
            vowelCount[i] = 1;
        }
    }
    // calculate prefix sum
    for (var i = 1; i < vowelCount.length; i++) {
        vowelCount[i] += vowelCount[i - 1];
    }
    var ans = new Array(queries.length).fill(0);
    for (var i = 0; i < queries.length; i++) {
        var li = queries[i][0];
        var ri = queries[i][1];
        // calculate the sum of vowel counts in the range [li, ri]
        ans[i] = (ri >= 0 && ri < vowelCount.length) ? vowelCount[ri] : 0;
        ans[i] -= (li - 1 >= 0 && li - 1 < vowelCount.length) ? vowelCount[li - 1] : 0;
    }
    return ans;
}

function putMarblesInBags(weights, k) {
    const n = weights.length;
    if (k === 1 || k === n) return 0;
    // The score is a sum of (first+last) per contiguous bag. Splitting the
    // array into k contiguous bags is equivalent to choosing k-1 "cut"
    // points among the n-1 adjacent gaps; each cut at gap i contributes
    // weights[i]+weights[i+1] to the total score (the array's own first
    // and last elements contribute identically to both max and min, so
    // they cancel out of the difference and can be ignored entirely).
    const pairSums = [];
    for (let i = 0; i < n - 1; i++) pairSums.push(weights[i] + weights[i + 1]);
    pairSums.sort((a, b) => a - b);

    let minScore = 0, maxScore = 0;
    for (let i = 0; i < k - 1; i++) minScore += pairSums[i];
    for (let i = 0; i < k - 1; i++) maxScore += pairSums[pairSums.length - 1 - i];

    return maxScore - minScore;
}

function makeEqual(s, target) {
    // check if the number of 1s in s and target are equal
    let countS = 0, countTarget = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '1') countS++;
        if (target[i] === '1') countTarget++;
    }
    if (countS !== countTarget) return false;

    // check if we can make s equal to target
    let visited = new Array(s.length).fill(false);
    for (let i = 0; i < s.length; i++) {
        if (s[i] !== target[i]) {
            // find an index j such that s[j] is equal to target[i]
            let found = false;
            for (let j = 0; j < s.length; j++) {
                if (!visited[j] && s[j] === target[i]) {
                    // perform the operation on s[i] and s[j]
                    s = s.substring(0, i) + (s[i] === '1' || s[j] === '1' ? '1' : '0') + s.substring(i + 1);
                    s = s.substring(0, j) + (s[i] === '0' && s[j] === '1' || s[i] === '1' && s[j] === '0' ? '1' : '0') + s.substring(j + 1);
                    visited[j] = true;
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
    }
    return true;
}

function maximumSumWithKElements(nums, k) {
    // Each operation picks the CURRENT maximum and increments it by 1, so
    // the optimal strategy always re-picks the same (growing) maximum: the
    // values added are max, max+1, max+2, ..., max+k-1.
    const maxVal = Math.max(...nums);
    return k * maxVal + (k * (k - 1)) / 2;
}

function calculateDelayedArrivalTime(arrivalTime, delayedTime) {
  // calculate the total hours including the delay
  let totalHours = arrivalTime + delayedTime;
  // adjust for 24-hour format by taking the modulus of total hours with 24
  return totalHours % 24;
}

function sumMultiples(n) {
  let totalSum = 0;
  for (let i = 1; i <= n; i++) // loop through all numbers in the range [1, n]
    if (i % 3 === 0 || i % 5 === 0 || i % 7 === 0) // check if the number is divisible by 3, 5, or 7
      totalSum += i; // add the number to the total sum if it's divisible
  return totalSum;
}

function countOperationsToEmptyArray(nums) {
    const n = nums.length;
    const indices = Array.from({length: n}, (_, i) => i);
    indices.sort((a, b) => nums[a] - nums[b]);
    let ans = n; // each element needs at least one operation to be removed
    for (let i = 1; i < n; i++) {
        // if the next-smallest element sits BEFORE the current one in the
        // original array, we must "wrap around" past every remaining
        // not-yet-removed element to reach it, costing one extra
        // operation per remaining element
        if (indices[i] < indices[i - 1]) {
            ans += n - i;
        }
    }
    return ans;
}

function findPrefixCommonArray(A, B) {
    let n = A.length;
    let prefixCommonArray = new Array(n).fill(0);
    let aSet = new Set();
    let bSet = new Set();
    for (let i = 0; i < n; i++) {
        aSet.add(A[i]); // add current element of A to the set
        bSet.add(B[i]); // add current element of B to the set
        let intersectionCount = 0;
        for (let j = 1; j <= n; j++) {
            if (aSet.has(j) && bSet.has(j)) {
                intersectionCount++; // count common elements
            }
        }
        prefixCommonArray[i] = intersectionCount; // store the count of common elements
    }
    return prefixCommonArray;
}

function maxNumberofFish(grid) {
    if (!grid.length) return 0;
    let maxFish = 0;
    let rows = grid.length, cols = grid[0].length;
    let visited = Array(rows).fill().map(() => Array(cols).fill(false));
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            // start DFS from WATER cells (fish count > 0) - grid[i][j]===0
            // means land, not an empty-but-traversable water cell
            if (grid[i][j] > 0 && !visited[i][j]) {
                maxFish = Math.max(maxFish, dfs(grid, i, j, visited));
            }
        }
    }
    return maxFish;
}

function dfs(grid, i, j, visited) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[0].length || visited[i][j] || grid[i][j] === 0) return 0;
    visited[i][j] = true;
    // return (not just locally increment) the accumulated count, since
    // primitives are passed by value and any local increment inside a
    // recursive call is invisible to the caller otherwise
    let fishCount = grid[i][j];
    fishCount += dfs(grid, i + 1, j, visited);
    fishCount += dfs(grid, i - 1, j, visited);
    fishCount += dfs(grid, i, j + 1, visited);
    fishCount += dfs(grid, i, j - 1, visited);
    return fishCount;
}

function firstCompletelyPaintedRowOrColumn(arr, mat) {
    let m = mat.length;
    let n = mat[0].length;
    let rows = new Array(m).fill(0);
    let cols = new Array(n).fill(0);
    // iterate over arr and update rows and cols
    for (let i = 0; i < arr.length; i++) {
        for (let j = 0; j < m; j++) {
            for (let k = 0; k < n; k++) {
                if (mat[j][k] === arr[i]) {
                    rows[j]++;
                    cols[k]++;
                    // check if a row or column is completely painted
                    if (rows[j] === n || cols[k] === m) {
                        return i;
                    }
                }
            }
        }
    }
    return -1;
}

function getSubarrayBeauty(nums, k, x) {
    let result = [];
    for (let i = 0; i <= nums.length - k; i++) {
        let subarray = nums.slice(i, i + k); // get the current subarray
        let negatives = subarray.filter(num => num < 0); // filter out non-negative numbers
        if (negatives.length < x) { // if there are fewer than x negative integers
            result.push(0); // the beauty is 0
        } else {
            let sortedNegatives = negatives.sort((a, b) => a - b); // sort the negative numbers
            result.push(sortedNegatives[x - 1]); // the beauty is the xth smallest negative integer
        }
    }
    return result;
}

// TIME: O(n * k * log(k)) SPACE: O(k)

function minOperations(nums) {
    function gcd(a, b) {
        if (b === 0) return a;
        return gcd(b, a % b);
    }
    const n = nums.length;
    const ones = nums.filter(x => x === 1).length;
    // if any 1 already exists, each other element needs exactly one
    // operation to become 1 (propagating outward one step at a time)
    if (ones > 0) return n - ones;

    // otherwise, find the shortest subarray whose gcd is 1 - creating a
    // single 1 there costs (length-1) operations, then propagating that 1
    // to the rest of the array costs another (n-1) operations
    let minLen = Infinity;
    for (let i = 0; i < n; i++) {
        let g = nums[i];
        for (let j = i + 1; j < n; j++) {
            g = gcd(g, nums[j]);
            if (g === 1) { minLen = Math.min(minLen, j - i + 1); break; }
        }
    }
    if (minLen === Infinity) return -1; // overall gcd isn't 1, impossible
    return (minLen - 1) + (n - 1);
}

function cancellable(generator) {
    let cancelled = false;
    let resolve, reject;
    let promise = new Promise((res, rej) => { resolve = res; reject = rej; });
    let cancel = () => { cancelled = true; };
    function step(result) {
        if (cancelled) {
            try {
                generator.throw(new Error("Cancelled"));
            } catch (error) {
                reject(error);
            }
            return;
        }
        try {
            if (result.done) {
                resolve(result.value);
            } else {
                Promise.resolve(result.value).then(value => {
                    step(generator.next(value));
                }).catch(error => {
                    try {
                        step(generator.throw(error));
                    } catch (e) {
                        reject(e);
                    }
                });
            }
        } catch (error) {
            reject(error);
        }
    }
    step(generator.next());
    return [cancel, promise];
}

function determineWinner(player1, player2) {
    function calculateScore(player) {
        let score = 0;
        for (let i = 0; i < player.length; i++) {
            let roll = player[i];
            // the roll's value is doubled if either of the PREVIOUS TWO
            // rolls was a 10 - this is a simple per-roll bonus rule, not
            // classic ten-pin frame/strike/spare scoring
            if ((i >= 1 && player[i - 1] === 10) || (i >= 2 && player[i - 2] === 10)) {
                roll *= 2;
            }
            score += roll;
        }
        return score;
    }
    const score1 = calculateScore(player1);
    const score2 = calculateScore(player2);
    if (score1 > score2) return 1;
    else if (score1 < score2) return 2;
    else return 0;
}

function minimumCost(start, target, specialRoads) {
    let points = [start, target];
    for (let road of specialRoads) {
        points.push([road[0], road[1]]);
        points.push([road[2], road[3]]);
    }
    // use a consistent "x,y" string key everywhere instead of relying on
    // the default array-to-string conversion mixed with JSON.parse (which
    // fails since "x,y" isn't valid JSON)
    const key = (p) => p[0] + ',' + p[1];
    const uniqueMap = new Map();
    for (const p of points) uniqueMap.set(key(p), p);
    points = [...uniqueMap.values()];

    let graph = {};
    for (let point of points) graph[key(point)] = {};
    for (let road of specialRoads) {
        const a = key([road[0], road[1]]);
        const b = key([road[2], road[3]]);
        if (!(b in graph[a]) || graph[a][b] > road[4]) graph[a][b] = road[4];
    }
    for (let i = 0; i < points.length; i++) {
        for (let j = 0; j < points.length; j++) {
            if (i !== j) {
                let cost = Math.abs(points[i][0] - points[j][0]) + Math.abs(points[i][1] - points[j][1]);
                const a = key(points[i]), b = key(points[j]);
                if (!(b in graph[a]) || graph[a][b] > cost) graph[a][b] = cost;
            }
        }
    }

    let distances = {};
    let queue = [[start, 0]];
    while (queue.length > 0) {
        queue.sort((a, b) => a[1] - b[1]);
        let [point, distance] = queue.shift();
        const pk = key(point);
        if (pk in distances && distances[pk] <= distance) continue;
        distances[pk] = distance;
        for (let neighbor in graph[pk]) {
            let newDistance = distance + graph[pk][neighbor];
            if (!(neighbor in distances) || newDistance < distances[neighbor]) {
                const [nx, ny] = neighbor.split(',').map(Number);
                queue.push([[nx, ny], newDistance]);
            }
        }
    }

    return distances[key(target)];
}

function smallestBeautifulString(s, k) {
    const arr = s.split('');
    const n = arr.length;
    let idx = n - 1;
    arr[idx] = String.fromCharCode(arr[idx].charCodeAt(0) + 1);
    while (idx < n) {
        if (arr[idx].charCodeAt(0) - 97 >= k) {
            if (idx === 0) return "";
            arr[idx] = 'a';
            idx--;
            arr[idx] = String.fromCharCode(arr[idx].charCodeAt(0) + 1);
            continue;
        }
        if (idx > 0 && arr[idx] === arr[idx - 1]) {
            arr[idx] = String.fromCharCode(arr[idx].charCodeAt(0) + 1);
            continue;
        }
        if (idx > 1 && arr[idx] === arr[idx - 2]) {
            arr[idx] = String.fromCharCode(arr[idx].charCodeAt(0) + 1);
            continue;
        }
        idx++;
        if (idx < n) arr[idx] = 'a';
    }
    return arr.join('');
}

function findPrefixScores(nums) {
    const n = nums.length;
    const ans = new Array(n);
    let runningMax = -Infinity;
    let prefixSum = 0;
    for (let i = 0; i < n; i++) {
        // each element is first "converted" by adding the running max of
        // the prefix seen so far, THEN summed - not simply doubled
        runningMax = Math.max(runningMax, nums[i]);
        const converted = nums[i] + runningMax;
        prefixSum += converted;
        ans[i] = prefixSum;
    }
    return ans;
}

function addMinimum(word) {
  const pattern = 'abc';
  let count = 0, pos = 0;
  for (const ch of word) {
    if (ch === pattern[pos]) { pos = (pos+1) % 3; }
    else {
      // need to insert to complete current cycle up to ch
      while (ch !== pattern[pos]) { count++; pos = (pos+1) % 3; }
      pos = (pos+1) % 3;
    }
  }
  // complete the last partial cycle
  if (pos !== 0) count += 3 - pos;
  return count;
}

function createHelloWorld() {
  // the returned function will always return 'Hello World' regardless of the input arguments
  return function() {
    // the function ignores all arguments and returns 'Hello World'
    return 'Hello World';
  }
}

function once(fn) {
  let called = false; // track if the function has been called
  let result; // store the result of the function call
  return function(...args) {
    // if the function has not been called, call it and store the result
    if (!called) {
      result = fn(...args); // call the original function with the provided arguments
      called = true; // mark the function as called
    }
    // return the result if the function has been called, otherwise return undefined
    return called ? result : undefined;
  }
}

function createCounter(init) {
    let currentValue = init; // initialize the current value with the given init
    return {
        increment: function() { // increment the current value and return it
            return ++currentValue;
        },
        decrement: function() { // decrement the current value and return it
            return --currentValue;
        },
        reset: function() { // reset the current value to the initial value and return it
            return currentValue = init;
        }
    };
}

function distinctDifferenceArray(nums) {
    let result = [];
    for (let i = 0; i < nums.length; i++) {
        // calculate the number of distinct elements in the prefix
        let prefixSet = new Set(nums.slice(0, i + 1));
        let prefixCount = prefixSet.size;
        // calculate the number of distinct elements in the suffix
        let suffixSet = new Set(nums.slice(i + 1));
        let suffixCount = suffixSet.size;
        // calculate the difference and add it to the result
        result.push(prefixCount - suffixCount);
    }
    return result;
}

function minIncrements(n, cost) {
    const c = cost.slice();
    let increments = 0;
    // process every internal node bottom-up (0-indexed, children 2i+1,2i+2)
    for (let i = Math.floor((n - 2) / 2); i >= 0; i--) {
        const left = 2 * i + 1, right = 2 * i + 2;
        if (left >= n) continue; // leaf, nothing to equalize
        if (right >= n) {
            // only one child - nothing to equalize against
            c[i] += c[left];
            continue;
        }
        if (c[left] !== c[right]) {
            increments += Math.abs(c[left] - c[right]);
            if (c[left] < c[right]) c[left] = c[right];
            else c[right] = c[left];
        }
        // propagate the now-equalized child cost up into the parent
        c[i] += c[left];
    }
    return increments;
}

function numberOfAdjacentElementsWithTheSameColor(n, queries) {
    let colors = new Array(n).fill(0);
    let answer = new Array(queries.length).fill(0);
    for (let i = 0; i < queries.length; i++) {
        let index = queries[i][0];
        let color = queries[i][1];
        colors[index] = color;
        let count = 0;
        // count adjacent elements with the same color
        for (let j = 0; j < n - 1; j++) {
            if (colors[j] === colors[j + 1] && colors[j] !== 0) {
                count++;
            }
        }
        answer[i] = count;
    }
    return answer;
}

function FrequencyTracker() {
    this.freqCount = {};
    this.count = {};
}

function add(thisObj, num) {
    if (thisObj.freqCount[num] !== undefined) {
        thisObj.count[thisObj.freqCount[num]]--;
        if (thisObj.count[thisObj.freqCount[num]] === 0) {
            delete thisObj.count[thisObj.freqCount[num]];
        }
    }
    thisObj.freqCount[num] = (thisObj.freqCount[num] || 0) + 1;
    thisObj.count[thisObj.freqCount[num]] = (thisObj.count[thisObj.freqCount[num]] || 0) + 1;
}

function remove(thisObj, num) {
    if (thisObj.freqCount[num] === undefined) return;
    thisObj.count[thisObj.freqCount[num]]--;
    if (thisObj.count[thisObj.freqCount[num]] === 0) {
        delete thisObj.count[thisObj.freqCount[num]];
    }
    thisObj.freqCount[num]--;
    if (thisObj.freqCount[num] === 0) {
        delete thisObj.freqCount[num];
    } else {
        thisObj.count[thisObj.freqCount[num]] = (thisObj.count[thisObj.freqCount[num]] || 0) + 1;
    }
}

function query(thisObj, num) {
    // FIXED: original checked `freqCount[num] !== undefined`, which asks "has the
    // NUMBER `num` ever been added" - but query's argument is a FREQUENCY, and the
    // question is "does any tracked number currently have exactly this frequency".
