function chunkArray(arr, size) {
  var result = []; // initialize an empty array to store the result
  for (var i = 0; i < arr.length; i += size) { // loop through the array with a step of size
    result.push(arr.slice(i, i + size)); // push a slice of the array into the result
  }
  return result; // return the result
}

function* fibGenerator() {
    let a = 0, b = 1;
    while (true) {
        // output current Fibonacci number
        yield a;
        // advance to next number
        const next = a + b;
        a = b;
        b = next;
    }
}

// TIME: O(1) per iteration SPACE: O(1)

function nestedGenerator(arr) {
    function* flatten(subArr) {
        for (const el of subArr) {
            if (Array.isArray(el)) {
                yield* flatten(el);
            } else {
                yield el;
            }
        }
    }
    return [...flatten(arr)];
}

function rowWithMaximumOnes(mat) {
    let maxCount = -1;          // track highest number of ones found
    let bestRow = -1;           // index of the row with that count

    for (let i = 0; i < mat.length; i++) {
        // count ones in the current row
        let count = 0;
        for (let j = 0; j < mat[i].length; j++) {
            if (mat[i][j] === 1) count++;
        }

        // update best row if this row has more ones (or same count but smaller index)
        if (count > maxCount) {
            maxCount = count;
            bestRow = i;
        }
    }

    return [bestRow, maxCount];
}

function maximumOr(nums, k) {
    let maxOr = 0;
    // Generate all possible combinations of operations on nums
    for (let i = 0; i < (1 << (k * nums.length)); i++) {
        let temp = nums.slice();
        let operations = 0;
        // Apply operations according to the current combination
        for (let j = 0; j < nums.length; j++) {
            for (let bit = 0; bit < k; bit++) {
                if (((i >> (j * k + bit)) & 1) === 1) {
                    temp[j] *= 2;
                    operations++;
                }
            }
            // Check if we have exceeded the allowed number of operations
            if (operations > k) break;
        }
        // If we have exceeded the allowed number of operations, skip this combination
        if (operations > k) continue;
        // Calculate the bitwise or of the current combination
        let or = 0;
        for (let num of temp) {
            or |= num;
        }
        // Update the maximum bitwise or
        maxOr = Math.max(maxOr, or);
    }
    return maxOr;
}

// TIME: O(2^(k*n) * n) SPACE: O(n)

function powerOfHeroes(nums) {
    const MOD = 1000000007n;
    const sorted = nums.slice().sort((a, b) => a - b).map(BigInt);
    const n = sorted.length;
    let g = 0n; // g(i) = sum_{j<i} nums[j] * 2^(i-1-j)
    let result = 0n;
    for (let i = 0; i < n; i++) {
        // sumOfMins = contribution from subsets where nums[i] is the max
        // and some earlier element is the min (everything strictly
        // between them free to include/exclude), plus nums[i] itself (the
        // singleton subset where nums[i] is both min and max)
        const sumOfMins = (g + sorted[i]) % MOD;
        const contribution = (((sorted[i] * sorted[i]) % MOD) * sumOfMins) % MOD;
        result = (result + contribution) % MOD;
        g = (2n * g + sorted[i]) % MOD;
    }
    return Number(result);
}

function doesValidArrayExist(derived) {
    let n = derived.length;
    let original = new Array(n).fill(0);
    original[0] = 0;
    original[1] = derived[0];
    for (let i = 2; i < n; i++) {
        // calculate original[i] based on the previously calculated values
        original[i] = derived[i-1] ^ original[i-1];
    }
    for (let i = 0; i < n; i++) {
        // check if the calculated original array satisfies the condition
        if (derived[i] !== (original[i] ^ original[(i+1)%n])) {
            return false;
        }
    }
    return true;
}

function countCompleteComponents(n, edges) {
    // Create an adjacency list representation of the graph
    let graph = Array.from({length: n}, () => []);
    for (let [a, b] of edges) {
        graph[a].push(b);
        graph[b].push(a);
    }

    let visited = new Array(n).fill(false);
    let count = 0;

    // Iterate over all vertices
    for (let i = 0; i < n; i++) {
        if (!visited[i]) {
            // Perform DFS to find all vertices in the current connected component
            let component = [];
            dfs(graph, visited, i, component);

            // Check if the current connected component is complete
            if (isComplete(graph, component)) {
                count++;
            }
        }
    }

    return count;
}

// Helper function to perform DFS
function dfs(graph, visited, vertex, component) {
    visited[vertex] = true;
    component.push(vertex);
    for (let neighbor of graph[vertex]) {
        if (!visited[neighbor]) {
            dfs(graph, visited, neighbor, component);
        }
    }
}

// Helper function to check if a connected component is complete
function isComplete(graph, component) {
    for (let i = 0; i < component.length; i++) {
        for (let j = i + 1; j < component.length; j++) {
            // If there is no edge between two vertices in the component, it is not complete
            if (!graph[component[i]].includes(component[j])) {
                return false;
            }
        }
    }
    return true;
}

function findLosers(n, k) {
    const visited = new Array(n + 1).fill(false);
    let current = 1;
    let i = 1;
    // the i-th pass moves the ball i*k steps forward (increasing each
    // time), not a constant k steps every pass
    while (!visited[current]) {
        visited[current] = true;
        current = ((current - 1 + i * k) % n) + 1;
        i++;
    }
    const losers = [];
    for (let f = 1; f <= n; f++) if (!visited[f]) losers.push(f);
    return losers;
}

function maximumMoves(grid) {
    const rows = grid.length, cols = grid[0].length;
    const reachable = Array.from({length: rows}, () => Array(cols).fill(false));
    for (let i = 0; i < rows; i++) reachable[i][0] = true;
    let maxCol = 0;
    for (let j = 1; j < cols; j++) {
        for (let i = 0; i < rows; i++) {
            // can only arrive from the IMMEDIATELY PREVIOUS column, and
            // only from an adjacent row (row-1, row, or row+1) - not from
            // any arbitrary earlier column/row
            for (const di of [-1, 0, 1]) {
                const pi = i + di;
                if (pi >= 0 && pi < rows && reachable[pi][j - 1] && grid[pi][j - 1] < grid[i][j]) {
                    reachable[i][j] = true;
                    maxCol = Math.max(maxCol, j);
                    break;
                }
            }
        }
    }
    return maxCol;
}

function callPolyfill(obj, ...args) {
  // Create a temporary function to hold the original function
  let temp = this;
  // Set the original function as a property of the given object
  obj.temp = temp;
  // Call the original function with the given arguments and the object as the context
  let result = obj.temp(...args);
  // Remove the temporary function from the object
  delete obj.temp;
  // Return the result of the function call
  return result;
}

function countSeniorCitizens(details) {
    let seniorCount = 0;                         // count of passengers > 60
