function argumentsLength(args) {
  // the harness calls this with a single array argument - return the
  // LENGTH OF THAT ARRAY, not arguments.length (which is always 1 here,
  // since exactly one argument - the array itself - was passed in)
  return args.length;
}

function expect(val) {
