}

function calculateLeftoverMoney(prices, money) {
    prices.sort((a, b) => a - b); // sort the prices array in ascending order
    if (prices.length < 2) return money; // if there are less than 2 chocolates, return the initial money
    if (prices[0] + prices[1] <= money) return money - prices[0] - prices[1]; // if buying the two cheapest chocolates doesn't exceed the money, return the leftover money
    return money; // if buying the two cheapest chocolates exceeds the money, return the initial money
}

function compactObject(obj) {
  if (Array.isArray(obj)) {
    // Filter out falsy values and recursively compact nested objects
    return obj.filter(val => val).map(val => typeof val === 'object' ? compactObject(val) : val);
  } else if (typeof obj === 'object') {
    // Create a new object with only truthy values and recursively compact nested objects
    const result = {};
    for (const key in obj) {
      if (obj[key]) {
        // Recursively compact nested objects
        result[key] = typeof obj[key] === 'object' ? compactObject(obj[key]) : obj[key];
      }
    }
    return result;
  } else {
    // If obj is not an object or array, return it as is
    return obj;
  }
}

function punishmentNumber(n) {
    let result = 0;
    for (let i = 1; i <= n; i++) {
        const square = i * i;
        if (canPartition(square.toString(), i)) result += square;
    }
    return result;
}

function canPartition(s, target) {
    // try every way to split the DIGIT STRING of the square into
    // contiguous pieces, summing each piece as a number, and check if
    // some split sums exactly to target
    function helper(start, currentSum) {
        if (start === s.length) return currentSum === target;
        if (currentSum > target) return false;
        let num = 0;
        for (let end = start; end < s.length; end++) {
            num = num * 10 + (s.charCodeAt(end) - 48);
            if (helper(end + 1, currentSum + num)) return true;
        }
        return false;
    }
    return helper(0, 0);
}

function minExtraCharacters(s, dictionary) {
    let dp = new Array(s.length + 1).fill(0);
    // initialize dp array to store the minimum number of extra characters for each substring
    for (let i = 1; i <= s.length; i++) {
        dp[i] = dp[i - 1] + 1;
        // for each substring, try to find a word in the dictionary that matches the substring
        for (let word of dictionary) {
            if (i >= word.length && s.slice(i - word.length, i) === word) {
                // if a match is found, update the dp array with the minimum number of extra characters
                dp[i] = Math.min(dp[i], dp[i - word.length]);
            }
        }
    }
    // return the minimum number of extra characters for the entire string
    return dp[s.length];
}

function removeTrailingZeros(num) {
  let trailingZerosRemoved = false;
  while (num.length > 0 && num[num.length - 1] === '0') // keep removing the last character if it's '0'
    num = num.slice(0, -1);
  return num;
}

function maximumStrength(nums) {
    let maxStrength = -Infinity;
    for (let mask = 0; mask < (1 << nums.length); mask++) {
        let currentStrength = 1;
        for (let i = 0; i < nums.length; i++) {
            if ((mask & (1 << i)) !== 0) {
                currentStrength *= nums[i]; // calculate the strength of the current group
            }
        }
        maxStrength = Math.max(maxStrength, currentStrength); // update the maximum strength
    }
    return maxStrength;
}

function modifyGraphEdgeWeights(n, edges, source, destination, target) {
  const INF = 2000000000;

  function dijkstra(edgeList) {
    const g = Array.from({ length: n }, () => Array(n).fill(Infinity));
    for (const [a, b, w] of edgeList) {
      if (w === -1) continue;
      if (w < g[a][b]) { g[a][b] = w; g[b][a] = w; }
    }
    const dist = Array(n).fill(Infinity);
    dist[source] = 0;
    const vis = Array(n).fill(false);
    for (let iter = 0; iter < n; iter++) {
      let k = -1;
      for (let j = 0; j < n; j++) {
        if (!vis[j] && (k === -1 || dist[j] < dist[k])) k = j;
      }
      vis[k] = true;
      for (let j = 0; j < n; j++) {
        if (dist[k] + g[k][j] < dist[j]) dist[j] = dist[k] + g[k][j];
      }
    }
    return dist[destination];
  }

  let d = dijkstra(edges);
  if (d < target) return [];
  if (d === target) {
    for (const e of edges) if (e[2] === -1) e[2] = INF;
    return edges;
  }

  let ok = false;
  for (const e of edges) {
    if (e[2] !== -1) continue;
    if (ok) { e[2] = INF; continue; }
    e[2] = 1;
    d = dijkstra(edges);
    if (d <= target) {
      ok = true;
      e[2] += (target - d);
    }
  }
  return ok ? edges : [];
}

function gcdTraversal(nums) {
    function find(parent, i) {
        // if the current node is the parent, return it
        if (parent[i] === i) return i;
        // otherwise, recursively find the parent
        return parent[i] = find(parent, parent[i]);
    }

    function union(parent, rank, x, y) {
        // find the parents of x and y
        let rootX = find(parent, x);
        let rootY = find(parent, y);
        // if they are already in the same set, return
        if (rootX === rootY) return;
        // otherwise, merge the sets
        if (rank[rootX] < rank[rootY]) {
            parent[rootX] = rootY;
        } else if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }

    let n = nums.length;
    let parent = new Array(n).fill(0).map((_, i) => i);
    let rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            // if the gcd of nums[i] and nums[j] is greater than 1, union them
            if (gcd(nums[i], nums[j]) > 1) union(parent, rank, i, j);
        }
    }
    // if all indices are in the same set, return true
    let root = find(parent, 0);
    for (let i = 1; i < n; i++) {
        if (find(parent, i) !== root) return false;
    }
    return true;
}

function gcd(a, b) {
    if (b === 0) return a;
    return gcd(b, a % b);
}

function differenceOfNumberOnDiagonals(grid) {
    const m = grid.length;
    const n = grid[0].length;
    const answer = Array(m).fill(0).map(() => Array(n).fill(0));
    const diagonalCounts = {};

    // Calculate diagonal values for each cell
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const diagonalKey = r - c;
            const antiDiagonalKey = r + c;
            // Count distinct values on the diagonal
            if (!diagonalCounts[diagonalKey]) diagonalCounts[diagonalKey] = new Set();
            if (!diagonalCounts[antiDiagonalKey]) diagonalCounts[antiDiagonalKey] = new Set();
            diagonalCounts[diagonalKey].add(grid[r][c]);
            diagonalCounts[antiDiagonalKey].add(grid[r][c]);
        }
    }

    // Calculate answer for each cell
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const diagonalKey = r - c;
            const antiDiagonalKey = r + c;
            // Calculate difference of distinct values on diagonals
            answer[r][c] = Math.abs(diagonalCounts[diagonalKey].size - diagonalCounts[antiDiagonalKey].size);
        }
    }

    return answer;
}

function eventEmitter(actions, values) {
    const results = [];
    const listeners = new Map(); // event name -> array of callbacks

    for (let i = 0; i < actions.length; i++) {
        const act = actions[i];
        const val = values[i];

        if (act === "EventEmitter") {
            // constructor – nothing to initialise beyond the map above
            results.push([]);
        } else if (act === "subscribe") {
            const [eventName, fnStr] = val;
            // turn the string representation into a real function
            const fn = eval('(' + fnStr + ')');
            if (!listeners.has(eventName)) listeners.set(eventName, []);
            listeners.get(eventName).push(fn);          // store in order
            results.push(["subscribed"]);
        } else if (act === "emit") {
            const [eventName, args = []] = val;
            const callbacks = listeners.get(eventName) || [];
            const emittedValues = [];
            for (const cb of callbacks) {
                emittedValues.push(cb.apply(null, args)); // invoke with supplied args
            }
            results.push(["emitted", emittedValues]);
        }
    }
    return results;
}

function sumInMatrix(nums) {
    const rows = nums.length;
    const cols = nums[0].length;
    let total = 0;

    for (let c = 0; c < cols; c++) {
        let maxInCol = -Infinity;               // find maximum of current column
        for (let r = 0; r < rows; r++) {
            if (nums[r][c] > maxInCol) {
                maxInCol = nums[r][c];
            }
        }
        total += maxInCol;                       // add column maximum to score
    }

    return total;
}

function minimizeStringLength(s) {
    // the reachable minimum is exactly the number of distinct characters:
    // any group of equal chars collapses to one survivor via the swap operations
    return new Set(s).size;
}

function cancellable(fn, args, t) {
    let timeoutId = setTimeout(function() { // delay the execution of fn by t milliseconds
        fn(...args);
    }, t);
    return function cancelFn() { // return a cancel function
        clearTimeout(timeoutId); // cancel the delayed execution of fn if cancelFn is invoked
    }
}

function minSwaps(nums) {
    const n = nums.length;
    const pos1 = nums.indexOf(1);
    const posn = nums.indexOf(n);
    // adjacent swaps needed to walk 1 to front and n to back; subtract 1 if their paths would cross
    let ans = pos1 + (n - 1 - posn);
    if (pos1 > posn) ans -= 1;
    return ans;
}

var maxIncreasingCells = function(mat) {
    const m = mat.length, n = m ? mat[0].length : 0;
    const cells = [];
    for (let i=0;i<m;i++) for (let j=0;j<n;j++) cells.push([mat[i][j], i, j]);
    cells.sort((a,b)=>a[0]-b[0]);
    const rowBest = new Array(m).fill(0);
    const colBest = new Array(n).fill(0);
    const dp = Array.from({length:m}, () => new Array(n).fill(0));
    let ans = 0;
    let idx = 0;
    while (idx < cells.length) {
        const curVal = cells[idx][0];
        const group = [];
        while (idx < cells.length && cells[idx][0] === curVal) {
            group.push([cells[idx][1], cells[idx][2]]);
            idx++;
        }
        for (const [i,j] of group) {
            dp[i][j] = 1 + Math.max(rowBest[i], colBest[j]);
            ans = Math.max(ans, dp[i][j]);
        }
        for (const [i,j] of group) {
            if (dp[i][j] > rowBest[i]) rowBest[i] = dp[i][j];
            if (dp[i][j] > colBest[j]) colBest[j] = dp[i][j];
        }
    }
    return ans;
};

function addTwoPromises(promise1, promise2) {
  // Use Promise.all to wait for both promises to resolve
  return Promise.all([promise1, promise2]).then(values => {
    // Add the resolved values of the two promises
    return values[0] + values[1];
  });
}

function sumOfMatrixAfterQueries(n, queries) {
    // process in reverse: the first query (in reverse, i.e. the LAST original query)
    // to touch a given row/column is the one whose value actually survives
    const rowDone = new Array(n).fill(false);
    const colDone = new Array(n).fill(false);
    let rowsDoneCount = 0, colsDoneCount = 0;
    let total = 0;
    for (let i = queries.length - 1; i >= 0; i--) {
        const [type, index, val] = queries[i];
        if (type === 0) {
            if (!rowDone[index]) {
                rowDone[index] = true; rowsDoneCount++;
                total += val * (n - colsDoneCount); // only cells whose column isn't already fixed count
            }
        } else {
            if (!colDone[index]) {
                colDone[index] = true; colsDoneCount++;
                total += val * (n - rowsDoneCount);
            }
        }
    }
    return total;
}

function countGoodIntegers(num1, num2, min_sum, max_sum) {
    let result = 0;
    let mod = 1000000007;
    for (let i = parseInt(num1); i <= parseInt(num2); i++) {
        // calculate the sum of digits of current integer
        let sum = 0, temp = i;
        while (temp > 0) {
            sum += temp % 10;
            temp = Math.floor(temp / 10);
        }
        // check if the sum of digits is within the given range
        if (sum >= min_sum && sum <= max_sum) {
            result = (result + 1) % mod;
        }
    }
    return result;
}

function sortBy(arr, fn) {
  // Use the built-in sort function and provide a compare function that uses fn to determine the sort order
  return arr.sort((a, b) => fn(a) - fn(b));
}

function promiseAll(functions) {
    return new Promise((resolve, reject) => {
        // Initialize an array to store the results of each promise
        const results = new Array(functions.length);
        // Initialize a counter to keep track of the number of resolved promises
        let resolvedCount = 0;
        // Initialize a variable to store the time at which the first promise resolves or rejects
        let startTime = Date.now();

        // Iterate over each function in the array
        functions.forEach((func, index) => {
            // Execute the function and handle the promise it returns
            func().then((result) => {
                // Store the result in the results array
                results[index] = result;
                // Increment the resolved count
                resolvedCount++;
                // If all promises have resolved, resolve the main promise with the results
                if (resolvedCount === functions.length) {
                    // Calculate the time taken for all promises to resolve
                    const timeTaken = Date.now() - startTime;
                    resolve({ t: timeTaken, resolved: results });
                }
            }).catch((error) => {
                // If any promise rejects, reject the main promise with the error
                const timeTaken = Date.now() - startTime;
                reject({ t: timeTaken, rejected: error });
            });
        });
    });
}

function calculate(actions, values) {
    let result = values[0];
    let index = 1;
    for (let i = 1; i < actions.length - 1; i++) {
        // Perform the corresponding mathematical operation based on the action
        if (actions[i] === 'add') result += values[index];
        else if (actions[i] === 'subtract') result -= values[index];
        else if (actions[i] === 'multiply') result *= values[index];
        else if (actions[i] === 'divide') result /= values[index];
        else if (actions[i] === 'power') result = Math.pow(result, values[index]);
        index++;
    }
    return result;
}

function isFascinating(n) {
    let concatenated = '' + n + (2 * n) + (3 * n); // concatenate the numbers
    let digitCount = {}; // hash table to store the count of each digit
    for (let i = 0; i < concatenated.length; i++) {
        let digit = concatenated[i]; // get the current digit
        if (digit === '0') return false; // if the digit is 0, return false
        if (digitCount[digit]) return false; // if the digit is already in the hash table, return false
        digitCount[digit] = true; // add the digit to the hash table
    }
    return Object.keys(digitCount).length === 9; // check if the hash table has 9 unique digits
}

function findMiddleNumber(nums) {
  // sort the array to easily find the minimum and maximum values
  nums.sort((a, b) => a - b);
  // if the array has only two elements, return -1
  if (nums.length === 2) return -1;
  // return the middle element (or any element that is not the first or last)
  return nums[1];
}

function robotMovement(nums, s, d) {
    const MOD = 1e9 + 7;
    const n = nums.length;
    let positions = nums.slice();
    let directions = s.split('').map(c => c === 'L' ? -1 : 1);
    // update positions based on the direction of movement for d seconds
    for (let i = 0; i < d; i++) {
        for (let j = 0; j < n; j++) {
            positions[j] += directions[j];
        }
        // check for collisions and update directions
        for (let j = 0; j < n - 1; j++) {
            for (let k = j + 1; k < n; k++) {
                if (positions[j] === positions[k]) {
                    // if two robots collide, they will start moving in opposite directions
                    directions[j] *= -1;
                    directions[k] *= -1;
                }
            }
        }
    }
    // calculate the sum of distances between all pairs of robots
    let sum = 0;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            sum = (sum + Math.abs(positions[i] - positions[j])) % MOD;
        }
    }
    return sum;
}

function longestSemiRepetitiveSubstring(s) {
    let maxLength = 0;
    let left = 0;
    let repeatedCount = 0;
    for (let right = 0; right < s.length; right++) {
        // if current character is the same as the previous one, increment repeated count
        if (right > 0 && s[right] === s[right - 1]) repeatedCount++;
        // if repeated count is greater than 1, move the left pointer to the right until repeated count is 1 or less
        while (repeatedCount > 1) {
            // if the character at the left pointer is the same as the one to its right, decrement repeated count
            if (s[left] === s[left + 1]) repeatedCount--;
            left++;
        }
        // update max length
        maxLength = Math.max(maxLength, right - left + 1);
    }
    return maxLength;
}

function lexicographicallySmallestString(s) {
    const arr = s.split('');
    const n = arr.length;
    let i = 0;
    while (i < n && arr[i] === 'a') i++;
    if (i === n) {
        arr[n - 1] = 'z';
        return arr.join('');
    }
    while (i < n && arr[i] !== 'a') {
        arr[i] = String.fromCharCode(arr[i].charCodeAt(0) - 1);
        i++;
    }
    return arr.join('');
}

function minimumCost(nums, x) {
    const n = nums.length;
    let best = Infinity;
    const minSoFar = nums.slice();
    // for a fixed total number of rotations k, the cost to collect type i is the
    // minimum price it's ever offered at across rotations 0..k; total cost = sum + k*x
    for (let k = 0; k < n; k++) {
        if (k > 0) {
            for (let i = 0; i < n; i++) minSoFar[i] = Math.min(minSoFar[i], nums[(i + k) % n]);
        }
        const sum = minSoFar.reduce((a, b) => a + b, 0) + k * x;
        best = Math.min(best, sum);
    }
    return best;
}

function maxSum(nums1, nums2, queries) {
    let answer = [];
    // iterate over each query and find the maximum sum
    for (let i = 0; i < queries.length; i++) {
        let max = -1;
        // iterate over each index in nums1 and nums2
        for (let j = 0; j < nums1.length; j++) {
            // check if the current index satisfies the constraints
            if (nums1[j] >= queries[i][0] && nums2[j] >= queries[i][1]) {
                // update the maximum sum if the current sum is larger
                max = Math.max(max, nums1[j] + nums2[j]);
            }
        }
        // add the maximum sum for the current query to the answer array
        answer.push(max);
    }
    return answer;
}

function totalDistanceTraveled(mainTank, additionalTank) {
    let totalDistance = 0;
    let fuelConsumed = 0;
    while (mainTank > 0) {
        // calculate the distance that can be traveled with the current fuel in the main tank
        let distance = mainTank * 10;
        // calculate the fuel that will be consumed to travel this distance
        fuelConsumed = distance / 10;
        // if the fuel consumed is greater than the fuel available in the main tank, 
        // calculate the distance that can be traveled with the available fuel
        if (fuelConsumed > mainTank) {
            distance = mainTank * 10;
            fuelConsumed = mainTank;
        }
        // calculate the number of times 5 liters of fuel will be consumed
        let injections = Math.floor(fuelConsumed / 5);
        // calculate the total fuel that will be injected from the additional tank
        let injectedFuel = Math.min(injections, additionalTank);
        // update the main tank fuel and the additional tank fuel
        mainTank -= fuelConsumed - injectedFuel;
        additionalTank -= injectedFuel;
        // update the total distance traveled
        totalDistance += distance;
    }
    return totalDistance;
}

function minimumPartitionValue(nums) {
    nums.sort((a, b) => a - b); // sort the array in ascending order
    let minDiff = Infinity; // initialize minimum difference as infinity
    for (let i = 0; i < nums.length; i++) { // iterate over all possible partitions
        let maxLeft = nums[i]; // maximum element in the left partition
        let minRight = nums[i + 1]; // minimum element in the right partition
        if (i + 1 < nums.length) { // if the right partition is not empty
            minDiff = Math.min(minDiff, Math.abs(maxLeft - minRight)); // update minimum difference
        }
    }
    return minDiff; // return the minimum difference
}

function countSpecialPermutations(nums) {
    const MOD = 1000000007;
    const n = nums.length;
    const dp = Array.from({ length: 1 << n }, () => new Array(n).fill(-1));
    function solve(mask, last) {
        if (mask === (1 << n) - 1) return 1;
        if (dp[mask][last] !== -1) return dp[mask][last];
        let ways = 0;
        for (let next = 0; next < n; next++) {
            if (mask & (1 << next)) continue;
            // 'special' means every adjacent pair divides one another
            if (nums[last] % nums[next] === 0 || nums[next] % nums[last] === 0) {
                ways = (ways + solve(mask | (1 << next), next)) % MOD;
            }
        }
        return dp[mask][last] = ways;
    }
    let total = 0;
    for (let i = 0; i < n; i++) total = (total + solve(1 << i, i)) % MOD;
    return total;
}

function minCost(cost, time) {
    const n = cost.length;
    const INF = Infinity;
    const memo = new Map();

    function solve(i, remaining) {
        // remaining = number of walls still needing coverage (clamped at 0)
        if (remaining <= 0) return 0;
        if (i === n) return INF;
        const key = i * (n + 1) + remaining;
        if (memo.has(key)) return memo.get(key);

        // Option 1: skip wall i for the paid painter (it'll be covered by free painter later,
        // accounted for implicitly since 'remaining' only decreases via paid choices below)
        let best = solve(i + 1, remaining);

        // Option 2: assign wall i to the paid painter: covers itself + gives free painter `time[i]` walls
        const covered = 1 + time[i];
        const nextRemaining = Math.max(0, remaining - covered);
        const withPaint = cost[i] + solve(i + 1, nextRemaining);
        if (withPaint < best) best = withPaint;

        memo.set(key, best);
        return best;
    }

    return solve(0, n);
}

function minStringLength(s) {
    const stack = [];
    for (let i = 0; i < s.length; i++) {
        stack.push(s[i]);
        // if the last two chars form "AB" or "CD", remove them
        while (stack.length >= 2) {
            const n = stack.length;
            const a = stack[n - 2];
            const b = stack[n - 1];
            if ((a === 'A' && b === 'B') || (a === 'C' && b === 'D')) {
                stack.pop();
                stack.pop();
            } else {
                break;
            }
        }
    }
    return stack.length;
}

function smallestPalindrome(s) {
    const arr = s.split('');               // mutable copy
    let i = 0, j = arr.length - 1;
    while (i < j) {
        if (arr[i] !== arr[j]) {
            // use the smaller character for both sides (minimal ops + lexicographically smallest)
            const smaller = arr[i] < arr[j] ? arr[i] : arr[j];
            arr[i] = arr[j] = smaller;
        }
        i++;
        j--;
    }
    return arr.join('');
}

function minimumCostToMakeAllEqual(s) {
    const n = s.length;
    let total = 0;
    for (let i = 0; i < n - 1; i++) {
        if (s[i] !== s[i + 1]) total += Math.min(i + 1, n - i - 1);
    }
    return total;
}

function ArrayWrapper(arr, op) {
    if (op === 'Add') {
        let sum = 0;
        for (const sub of arr) for (const v of sub) sum += v;
        return sum;
    }
    if (op === 'String') {
        return '[' + arr[0].join(',') + ']';
    }
    throw new Error('Unsupported operation: ' + op);
}

function isEmpty(obj) {
    // Determine whether the input is an array or a plain object
    if (Array.isArray(obj)) {
        // For arrays, check the length property
        return obj.length === 0;
    }
    // For objects, count own enumerable keys
    return Object.keys(obj).length === 0;
}

function longestEvenOddSubarrayWithThreshold(nums, threshold) {
    let best = 0, curLen = 0, prevParity = null;
    for (const x of nums) {
        if (x > threshold) { curLen = 0; prevParity = null; continue; }
        const parity = x & 1;
        if (curLen === 0) {
            if (parity === 0) { curLen = 1; prevParity = 0; best = Math.max(best, curLen); }
            else { curLen = 0; prevParity = null; }
        } else {
            if (parity !== prevParity) { curLen++; prevParity = parity; best = Math.max(best, curLen); }
            else {
                if (parity === 0) { curLen = 1; prevParity = 0; best = Math.max(best, curLen); }
                else { curLen = 0; prevParity = null; }
            }
        }
    }
    return best;
}

function relocateMarbles(nums, moveFrom, moveTo) {
    // build a map position → number of marbles there
    const posCount = new Map();
    for (const p of nums) {
        posCount.set(p, (posCount.get(p) || 0) + 1);
    }

    // simulate each move: move all marbles from moveFrom[i] to moveTo[i]
    for (let i = 0; i < moveFrom.length; i++) {
        const from = moveFrom[i];
        const to = moveTo[i];
        const cnt = posCount.get(from);
        if (cnt !== undefined) {               // there are marbles at 'from'
            posCount.set(to, (posCount.get(to) || 0) + cnt);
            posCount.delete(from);
        }
    }

    // collect occupied positions and sort them
    const result = Array.from(posCount.keys());
    result.sort((a, b) => a - b);
    return result;
}

function countContinuousSubarrays(nums) {
    const n = nums.length;
    let total = 0;
    for (let i = 0; i < n; i++) {
        let curMin = nums[i], curMax = nums[i];
        for (let j = i; j < n; j++) {
            curMin = Math.min(curMin, nums[j]);
            curMax = Math.max(curMax, nums[j]);
            if (curMax - curMin > 2) break; // window can only get worse from here, so stop early
            total++;
        }
    }
    return total;
}

function longestAlternatingSubarray(nums) {
    let maxLen = -1;          // best length found
    let curLen = 1;           // length of current alternating subarray
    let prevDiff = 0;         // sign of previous valid difference (+1 / -1)

    for (let i = 1; i < nums.length; i++) {
        const diff = nums[i] - nums[i - 1];

        // main logic: decide whether we can extend, restart, or reset
        if (Math.abs(diff) === 1 && (prevDiff === 0 || diff * prevDiff === -1)) {
            curLen++;                     // keep extending
        } else if (Math.abs(diff) === 1) {
            curLen = 2;                   // start new subarray from i‑1
        } else {
            curLen = 1;                   // no alternating pair here
        }

        prevDiff = Math.abs(diff) === 1 ? diff : 0; // keep sign only if diff is valid
        if (curLen > maxLen) maxLen = curLen;       // update answer
    }

    return maxLen >= 2 ? maxLen : -1; // length 2 is the smallest valid subarray
}

function maximumAchievableNumber(num, t) {
    return num + 2 * t;
}

function primePairs(n) {
    // ---------- build sieve ----------
    const isPrime = new Array(n + 1).fill(true);
    isPrime[0] = isPrime[1] = false;
    for (let i = 2; i * i <= n; i++) {
        if (isPrime[i]) {
            for (let j = i * i; j <= n; j += i) {
                isPrime[j] = false;
            }
        }
    }

    const result = [];

    // ---------- find prime pairs ----------
    for (let x = 2; x <= Math.floor(n / 2); x++) {
        const y = n - x;
        if (isPrime[x] && isPrime[y]) {
            result.push([x, y]);   // keep x ≤ y, list stays sorted by x
        }
    }

    return result;
}

function minimumLength(words) {
    // dp maps 'firstChar+lastChar' of the current concatenated string -> minimum achievable length
    let dp = new Map();
    const w0 = words[0];
    dp.set(w0[0] + w0[w0.length - 1], w0.length);
    for (let i = 1; i < words.length; i++) {
        const w = words[i], wf = w[0], wl = w[w.length - 1], wlen = w.length;
        const newDp = new Map();
        for (const [key, len] of dp) {
            const f = key[0], l = key[1];
            // join(current, w): new first char stays f, new last char becomes wl
            const len1 = len + wlen - (l === wf ? 1 : 0);
            const k1 = f + wl;
            if (!newDp.has(k1) || newDp.get(k1) > len1) newDp.set(k1, len1);
            // join(w, current): new first char becomes wf, new last char stays l
            const len2 = len + wlen - (wl === f ? 1 : 0);
            const k2 = wf + l;
            if (!newDp.has(k2) || newDp.get(k2) > len2) newDp.set(k2, len2);
        }
        dp = newDp;
    }
    return Math.min(...dp.values());
}

function minBeautifulSubstrings(s) {
    const n = s.length;
    const powers = [];
    let val = 1;
    while (true) {
        const bin = val.toString(2);
        if (bin.length > n) break;
        powers.push(bin);
        val *= 5;
    }
    const INF = Number.MAX_SAFE_INTEGER;
    const dp = new Array(n + 1).fill(INF);
    dp[0] = 0;
    for (let i = 1; i <= n; i++) {
        for (const b of powers) {
            const len = b.length;
            if (len <= i && s.slice(i - len, i) === b) {
                dp[i] = Math.min(dp[i], dp[i - len] + 1);
            }
        }
    }
    return dp[n] === INF ? -1 : dp[n];
}

function maxJumps(nums, target) {
    const n = nums.length;
    if (n === 0) return -1;
    if (n === 1) return 0;               // already at the last index

    const dp = new Array(n).fill(-Infinity);
    dp[0] = 0;                            // start position needs no jump

    // compute dp[i] using all earlier positions j
    for (let i = 1; i < n; i++) {
        for (let j = 0; j < i; j++) {
            // main logic: check reachability and update dp[i]
            if (Math.abs(nums[j] - nums[i]) <= target && dp[j] !== -Infinity) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }

    return dp[n - 1] === -Infinity ? -1 : dp[n - 1];
}

var sumImbalanceNumbers = function(nums) {
    const n = nums.length;
    const maxVal = n+2;
    let total = 0;
    for (let start=0; start<n; start++) {
        const freq = new Array(maxVal+3).fill(0);
        let components = 0;
        for (let end=start; end<n; end++) {
            const x = nums[end];
            if (freq[x] === 0) {
                const left = (freq[x-1]||0) > 0;
                const right = (freq[x+1]||0) > 0;
                if (!left && !right) components++;
                else if (left && right) components--;
                freq[x] = 1;
            }
            const imbalance = components > 0 ? components-1 : 0;
            total += imbalance;
        }
    }
    return total;
};

function applyOperationsToMakeAllArrayElementsEqualToZero(nums, k) {
    const n = nums.length;
    if (k <= 0 || k > n) return nums.every(x => x === 0);
    const diff = new Array(n + 1).fill(0);
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur += diff[i];
        const need = nums[i] - cur;
        if (need < 0) return false;
        if (need) {
            if (i + k > n) return false;
            cur += need;
            diff[i + k] -= need;
        }
    }
    return true;
}

function numberOfBlackBlocks(m, n, coordinates) {
    // answer array for 0..4 black cells
    const ans = Array(5).fill(0);
    // map from block top‑left corner "i,j" to its black‑cell count
    const blockCount = new Map();

    // enumerate every black cell
    for (const [x, y] of coordinates) {
        // each black cell can belong to up to 4 blocks
        for (let dx = -1; dx <= 0; dx++) {
            for (let dy = -1; dy <= 0; dy++) {
                const i = x + dx;          // possible top‑left row
                const j = y + dy;          // possible top‑left column
                // skip blocks that would go out of the grid
                if (i < 0 || j < 0 || i >= m - 1 || j >= n - 1) continue;
                const key = i + ',' + j;
                blockCount.set(key, (blockCount.get(key) || 0) + 1);
            }
        }
    }

    // count how many blocks have 1..4 black cells
    for (const cnt of blockCount.values()) {
        ans[cnt]++;               // cnt is guaranteed to be 1..4
    }

    // blocks with zero black cells
    const totalBlocks = Math.max(0, (m - 1) * (n - 1));
    const nonZero = ans[1] + ans[2] + ans[3] + ans[4];
    ans[0] = totalBlocks - nonZero;

    return ans;
}

function longestNonDecreasingSubarrayFromTwoArrays(nums1, nums2) {
    const n = nums1.length;
    if (n === 0) return 0;
    let len1 = 1, len2 = 1, ans = 1;
    for (let i = 1; i < n; i++) {
        let cur1 = 1, cur2 = 1;
        if (nums1[i - 1] <= nums1[i]) cur1 = Math.max(cur1, len1 + 1);
        if (nums2[i - 1] <= nums1[i]) cur1 = Math.max(cur1, len2 + 1);
        if (nums1[i - 1] <= nums2[i]) cur2 = Math.max(cur2, len1 + 1);
        if (nums2[i - 1] <= nums2[i]) cur2 = Math.max(cur2, len2 + 1);
        len1 = cur1; len2 = cur2;
        if (len1 > ans) ans = len1;
        if (len2 > ans) ans = len2;
    }
    return ans;
}

function maximumBeauty(nums, k) {
  nums.sort((a,b)=>a-b);
  let left = 0, best = 1;
  for (let right = 0; right < nums.length; right++) {
    while (nums[right] - nums[left] > 2*k) left++;
    best = Math.max(best, right - left + 1);
  }
  return best;
}

function sumOfSquaresSpecial(nums) {
    const n = nums.length;
    let sum = 0;
    // iterate over each possible index (1‑based)
    for (let i = 1; i <= n; i++) {
        // check if i divides the length of the array
        if (n % i === 0) {
            const val = nums[i - 1];   // convert to 0‑based index
            sum += val * val;          // add square of the special element
        }
    }
    return sum;
}

function isGoodArray(nums) {
    // find candidate n (maximum element)
    let n = -Infinity;
    for (let v of nums) {
        if (v > n) n = v;
    }
    if (n < 1) return false;                // n must be positive
    if (nums.length !== n + 1) return false; // length must match base[n]

    // count occurrences
    const freq = Object.create(null);
    for (let v of nums) {
        if (v > n) return false;            // value larger than n cannot appear
        freq[v] = (freq[v] || 0) + 1;
    }

    // verify required frequencies
    for (let i = 1; i < n; i++) {
        if (freq[i] !== 1) return false;    // each 1..n-1 appears exactly once
    }
    return freq[n] === 2;                    // n appears twice
}

function minimumValidSplit(nums) {
    const n = nums.length;
    // ---- find candidate for dominant element (Boyer‑Moore) ----
    let candidate = null;
    let count = 0;
    for (let i = 0; i < n; i++) {
        if (count === 0) {
            candidate = nums[i];
            count = 1;
        } else if (nums[i] === candidate) {
            count++;
        } else {
            count--;
        }
    }
    const dom = candidate;               // guaranteed to be the dominant element

    // ---- total occurrences of dom ----
    let totalDom = 0;
    for (let v of nums) if (v === dom) totalDom++;

    // ---- scan prefixes, looking for the first valid split ----
    let leftCount = 0;
    for (let i = 0; i < n - 1; i++) {    // split must leave both sides non‑empty
        if (nums[i] === dom) leftCount++;

        const leftLen = i + 1;
        const rightLen = n - leftLen;
        const rightCount = totalDom - leftCount;

        // both sides must have dom as dominant
        if (leftCount * 2 > leftLen && rightCount * 2 > rightLen) {
            return i;                     // smallest index found
        }
    }
    return -1;                           // no valid split
}

function longestValidSubstring(word, forbidden) {
    const forbiddenSet = new Set(forbidden);
    const maxLen = Math.max(...forbidden.map(f => f.length));
    const n = word.length;
    let left = 0, best = 0;
    for (let right = 0; right < n; right++) {
        for (let start = right; start >= left && start > right - maxLen; start--) {
            const sub = word.slice(start, right+1);
            if (forbiddenSet.has(sub)) { left = start + 1; break; }
        }
        best = Math.max(best, right - left + 1);
    }
    return best;
}

function maxScore(nums, x) {
    const n = nums.length;
    const best = [-Infinity, -Infinity];
    best[nums[0]%2] = nums[0];
    for (let i = 1; i < n; i++) {
        const p = nums[i]%2;
        const cand = Math.max(best[p], best[1-p] - x) + nums[i];
        best[p] = Math.max(best[p], cand);
    }
    return Math.max(best[0], best[1]);
}

function maxPossibleElement(nums) {
    let stack = [];
    let max = 0;
    for (let i = nums.length - 1; i >= 0; i--) {
        let cur = nums[i];
        while (stack.length && cur <= stack[stack.length - 1]) {
            cur += stack.pop();
        }
        stack.push(cur);
        if (cur > max) max = cur;
    }
    return max;
}

function splitStringsBySeparator(words, separator) {
    const result = [];

    for (let i = 0; i < words.length; i++) {          // iterate over each word
        const parts = words[i].split(separator);      // split by the given separator
        for (let j = 0; j < parts.length; j++) {      // process each piece
            if (parts[j] !== '') {                     // exclude empty strings
                result.push(parts[j]);
            }
        }
    }

    return result;
}

function sortVowels(s) {
    const isVowel = c => 'aeiouAEIOU'.includes(c);

    // collect all vowels
    const vowels = [];
    for (let i = 0; i < s.length; i++) {
        if (isVowel(s[i])) vowels.push(s[i]);
    }

    // sort vowels by their ASCII/Unicode code points
    vowels.sort();

    // rebuild the string, inserting sorted vowels in original vowel positions
    let vi = 0;
    let result = '';
    for (let i = 0; i < s.length; i++) {
        if (isVowel(s[i])) {
            result += vowels[vi++];
        } else {
            result += s[i];
        }
    }
    return result;
}

function countPathsThatCanFormAPalindromeInATree(parent, s) {
    const n = parent.length;
    const children = Array.from({length: n}, () => []);
    for (let i = 1; i < n; i++) children[parent[i]].push(i);

    const masks = new Array(n).fill(0);
    masks[0] = 1 << (s.charCodeAt(0) - 97);
    let stack = [0];
    while (stack.length) {
        const node = stack.pop();
        for (const child of children[node]) {
            const bit = 1 << (s.charCodeAt(child) - 97);
            masks[child] = masks[node] ^ bit;
            stack.push(child);
        }
    }

    const freq = new Map();
    let ans = 0;
    const bitMasks = Array.from({length: 26}, (_, i) => 1 << i);
    for (const m of masks) {
        ans += freq.get(m) || 0;
        for (const b of bitMasks) ans += freq.get(m ^ b) || 0;
        freq.set(m, (freq.get(m) || 0) + 1);
    }
    return ans;
}

function countWays(n, x) {
    const MOD = 1000000007;
    // collect all usable powers i^x (i >= 1)
    const powers = [];
    for (let i = 1; ; ++i) {
        const v = Math.pow(i, x);
        if (v > n) break;
        powers.push(v);
    }

    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;                     // empty set gives sum 0

    // main DP: add each power once, updating sums backwards
    for (const v of powers) {
        for (let s = n; s >= v; --s) {
            dp[s] = (dp[s] + dp[s - v]) % MOD;
        }
    }
    return dp[n];
}

var maxIncreasingGroups = function(usageLimits) {
    const n = usageLimits.length;
    let low = 0, high = n;
    while (low < high) {
        const mid = Math.floor((low+high+1)/2);
        let sum = 0;
        for (const v of usageLimits) sum += Math.min(v, mid);
        const need = mid*(mid+1)/2;
        if (sum >= need) low = mid; else high = mid-1;
    }
    return low;
};

function countCompleteSubarrays(nums) {
    const total = new Set(nums).size;
    const n = nums.length;
    let count = 0;
    for (let i = 0; i < n; i++) {
        const seen = new Set();
        for (let j = i; j < n; j++) {
            seen.add(nums[j]);
            if (seen.size === total) count++;
        }
    }
    return count;
}

function countEmployeesMeetingTarget(hours, target) {
    let metCount = 0;                         // initialize counter
    for (let i = 0; i < hours.length; i++) {  // iterate through all employees
        if (hours[i] >= target) {              // check if employee meets the target
            metCount++;                        // increment counter
        }
    }
    return metCount;                          // result
}

function minimumString(a, b, c) {
  function contains(x, y) { return x.includes(y); }
  function merge(x, y) {
    if (contains(x, y)) return x;
    if (contains(y, x)) return y;
    // find max overlap where suffix of x matches prefix of y
    for (let len = Math.min(x.length, y.length); len > 0; len--) {
      if (x.slice(x.length - len) === y.slice(0, len)) return x + y.slice(len);
    }
    return x + y;
  }
  function mergeAll(order) {
    let [x, y, z] = order;
    return merge(merge(x, y), z);
  }
  const perms = [
    [a,b,c],[a,c,b],[b,a,c],[b,c,a],[c,a,b],[c,b,a]
  ];
  let best = null;
  for (const p of perms) {
    const cand = mergeAll(p);
    if (best === null || cand.length < best.length || (cand.length === best.length && cand < best)) best = cand;
  }
  return best;
}

function insertGreatestCommonDivisors(head) {
    // helper: Euclidean algorithm for GCD
    function gcd(a, b) {
        while (b !== 0) {
            const temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    let cur = head;
    while (cur && cur.next) {
        // compute GCD of the current pair
        const g = gcd(cur.val, cur.next.val);
        // create node with the GCD value and insert it
        const newNode = { val: g, next: cur.next };
        cur.next = newNode;
        // advance to the original next node (skip the inserted one)
        cur = newNode.next;
    }
    return head;
}

function countSteppingNumbers(low, high) {
  const MOD = 1000000007n;

  function decStr(s) {
    const a = s.split('');
    let i = a.length - 1;
    while (i >= 0 && a[i] === '0') { a[i] = '9'; i--; }
    if (i >= 0) a[i] = String(Number(a[i]) - 1);
    while (a.length > 1 && a[0] === '0') a.shift();
    return a.join('');
  }

  function count(bound) {
    const n = bound.length;
    const memo = new Map();

    function dfs(pos, prev, tight, started) {
      if (pos === n) return started ? 1n : 0n;
      const key = pos + ',' + prev + ',' + (tight?1:0) + ',' + (started?1:0);
      if (!tight) {
        const cached = memo.get(key);
        if (cached !== undefined) return cached;
      }
      const limit = tight ? bound.charCodeAt(pos) - 48 : 9;
      let res = 0n;
      for (let d = 0; d <= limit; d++) {
        if (!started) {
          if (d === 0) {
            res += dfs(pos+1, -1, tight && d===limit, false);
          } else {
            res += dfs(pos+1, d, tight && d===limit, true);
          }
        } else {
          if (Math.abs(d - prev) === 1) {
            res += dfs(pos+1, d, tight && d===limit, true);
          }
        }
      }
      res %= MOD;
      if (!tight) memo.set(key, res);
      return res;
    }
    return dfs(0, -1, true, false);
  }

  const lowMinus1 = (low === '0') ? null : decStr(low);
  let cHigh = count(high);
  let cLowMinus1 = (lowMinus1 === null || lowMinus1 === '0' && low==='1') ? 0n : count(lowMinus1);
  if (low === '0') cLowMinus1 = 0n; // shouldn't happen per constraints (low>=1)
  let ans = (cHigh - cLowMinus1) % MOD;
  if (ans < 0n) ans += MOD;
  return Number(ans);
}

function accountBalance(purchaseAmount) {
    // round the purchase amount to the nearest multiple of 10
    const roundedAmount = Math.round(purchaseAmount / 10) * 10;
    return 100 - roundedAmount;
}

function minimumTime(nums1, nums2, x) {
    const n = nums1.length;
    let sum1 = 0, sum2 = 0;
    for (let i = 0; i < n; i++) { sum1 += nums1[i]; sum2 += nums2[i]; }

    const idx = Array.from({ length: n }, (_, i) => i);
    idx.sort((a, b) => nums2[a] - nums2[b]);

    // dp[j] = max total "value saved" achievable using exactly j zero-operations,
    // where zeroing element i at operation-slot j (1-indexed, processed in nums2-ascending
    // order) saves nums1[i] + j*nums2[i] from the eventual sum.
    const dp = new Array(n + 1).fill(0);
    for (const i of idx) {
        for (let j = n; j >= 1; j--) {
            const cand = dp[j - 1] + nums1[i] + j * nums2[i];
            if (cand > dp[j]) dp[j] = cand;
        }
    }

    for (let t = 0; t <= n; t++) {
        const total = sum1 + t * sum2 - dp[t];
        if (total <= x) return t;
    }
    return -1;
}

function findMaximumElegance(items, k) {
    items.sort((a,b) => b[0] - a[0]);
    const n = items.length;
    const seen = new Set();
    const dupStack = [];
    let totalProfit = 0, distinct = 0;
    for (let i = 0; i < k; i++) {
        const [profit, cat] = items[i];
        totalProfit += profit;
        if (seen.has(cat)) dupStack.push(profit);
        else { seen.add(cat); distinct++; }
    }
    let best = totalProfit + distinct*distinct;
    for (let i = k; i < n; i++) {
        const [profit, cat] = items[i];
        if (!seen.has(cat) && dupStack.length) {
            const worst = dupStack.pop();
            totalProfit -= worst;
            totalProfit += profit;
            seen.add(cat);
            distinct++;
            best = Math.max(best, totalProfit + distinct*distinct);
        }
    }
    return best;
}

function minimumSecondsToEqualizeACircularArray(nums) {
    const n = nums.length;
    if (n <= 1) return 0;
    const info = new Map();
    for (let i = 0; i < n; i++) {
        const v = nums[i];
        if (!info.has(v)) info.set(v, [i, i, 0]);
        else {
            const [first, prev, maxGap] = info.get(v);
            const gap = i - prev - 1;
            info.set(v, [first, i, Math.max(maxGap, gap)]);
        }
    }

    let answer = Infinity;
    for (const [first, prev, maxGap0] of info.values()) {
        let maxGap = maxGap0;
        let wrapGap;
        if (maxGap === n - 1) wrapGap = n - 1;
        else wrapGap = ((first + n - prev - 1) % n + n) % n;
        if (wrapGap > maxGap) maxGap = wrapGap;
        if (maxGap === n - 1 && info.size === 1) return 0;
        const seconds = Math.floor((maxGap + 1) / 2);
        if (seconds < answer) answer = seconds;
    }
    return answer;
}

function canSplitArray(nums, m) {
    const n = nums.length;
    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefix[i + 1] = prefix[i] + nums[i];
    }
    const sum = (l, r) => prefix[r + 1] - prefix[l];
    const dp = Array.from({ length: n }, () => Array(n).fill(false));
    for (let i = 0; i < n; i++) dp[i][i] = true;
    for (let len = 2; len <= n; len++) {
        for (let l = 0; l + len - 1 < n; l++) {
            const r = l + len - 1;
            if (sum(l, r) < m) continue;
            for (let k = l; k < r; k++) {
                if (dp[l][k] && dp[k + 1][r]) {
                    dp[l][r] = true;
                    break;
                }
            }
        }
    }
    return dp[0][n - 1];
}

function faultyKeyboard(s) {
    const result = [];          // store characters in a deque-like array
    let reversed = false;       // current orientation of the screen

    for (const ch of s) {
        if (ch === 'i') {
            reversed = !reversed;               // toggle orientation
        } else {
            if (!reversed) {
                result.push(ch);                 // add to the right end
            } else {
                result.unshift(ch);              // add to the left end
            }
        }
    }

    if (reversed) {
        result.reverse();        // final orientation is reversed
    }
    return result.join('');
}

function doubleLinkedList(head) {
    let prev = null;
    let cur = head;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    let node = prev;
    let carry = 0;
    while (node) {
        const sum = node.val * 2 + carry;
        node.val = sum % 10;
        carry = Math.floor(sum / 10);
        if (!node.next) {
            if (carry) node.next = { val: carry, next: null };
            break;
        }
        node = node.next;
    }
    cur = prev;
    prev = null;
    while (cur) {
        const nxt = cur.next;
        cur.next = prev;
        prev = cur;
        cur = nxt;
    }
    return prev;
}

function minimumAbsoluteDifference(nums, x) {
    // ---------- treap node ----------
    function Node(key) {
        this.key = key;                     // stored value
        this.pri = Math.random();           // random priority
        this.cnt = 1;                       // multiplicity
        this.left = null;
        this.right = null;
    }

    // ---------- rotations ----------
    function rotateRight(p) {
        const q = p.left;
        p.left = q.right;
        q.right = p;
        return q;
    }
    function rotateLeft(p) {
        const q = p.right;
        p.right = q.left;
        q.left = p;
        return q;
    }

    // ---------- insert ----------
    function insert(node, key) {
        if (!node) return new Node(key);
        if (key === node.key) {
            node.cnt++;                     // duplicate
        } else if (key < node.key) {
            node.left = insert(node.left, key);
            if (node.left.pri < node.pri) node = rotateRight(node);
        } else {
            node.right = insert(node.right, key);
            if (node.right.pri < node.pri) node = rotateLeft(node);
        }
        return node;
    }

    // ---------- lower bound (smallest ≥ key) ----------
    function lowerBound(node, key) {
        if (!node) return null;
        if (node.key >= key) {
            const left = lowerBound(node.left, key);
            return left ? left : node;
        }
        return lowerBound(node.right, key);
    }

    // ---------- predecessor (largest < key) ----------
    function predecessor(node, key) {
        if (!node) return null;
        if (node.key < key) {
            const right = predecessor(node.right, key);
            return right ? right : node;
        }
        return predecessor(node.left, key);
    }

    let root = null;
    let best = Infinity;

    for (let i = 0; i < nums.length; i++) {
        // make the element i‑x available for future queries
        if (i - x >= 0) root = insert(root, nums[i - x]);

        // query the closest value among already inserted elements
        const lb = lowerBound(root, nums[i]);
        if (lb) best = Math.min(best, Math.abs(lb.key - nums[i]));
        const pred = predecessor(root, nums[i]);
        if (pred) best = Math.min(best, Math.abs(pred.key - nums[i]));
    }

    // if no pair satisfies the distance condition (should not happen)
    return best === Infinity ? 0 : best;
}

function maxScore(nums, k) {
    const n = nums.length;
    const MOD = 1000000007n;

    const primeScore = (x) => {
        let count = 0;
        let v = x;
        for (let p = 2; p * p <= v; p++) {
            if (v % p === 0) {
                count++;
                while (v % p === 0) v = Math.floor(v / p);
            }
        }
        if (v > 1) count++;
        return count;
    };

    const scores = nums.map(primeScore);

    const left = new Array(n).fill(-1);
    const right = new Array(n).fill(n);
    let stack = [];
    for (let i = 0; i < n; i++) {
        while (stack.length && scores[stack[stack.length - 1]] < scores[i]) {
            stack.pop();
        }
        left[i] = stack.length ? stack[stack.length - 1] : -1;
        stack.push(i);
    }
    stack = [];
    for (let i = n - 1; i >= 0; i--) {
        while (stack.length && scores[stack[stack.length - 1]] <= scores[i]) {
            stack.pop();
        }
        right[i] = stack.length ? stack[stack.length - 1] : n;
        stack.push(i);
    }

    const count = new Array(n);
    for (let i = 0; i < n; i++) {
        count[i] = BigInt(i - left[i]) * BigInt(right[i] - i);
    }

    const order = Array.from({length: n}, (_, i) => i).sort((a, b) => nums[b] - nums[a]);

    const modpow = (base, exp, mod) => {
        base = base % mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    };

    let remaining = BigInt(k);
    let ans = 1n;
    for (const i of order) {
        if (remaining <= 0n) break;
        const take = count[i] < remaining ? count[i] : remaining;
        ans = (ans * modpow(BigInt(nums[i]), take, MOD)) % MOD;
        remaining -= take;
    }
    return Number(ans);
}

function maxPairSum(nums) {
    // arrays that store the two largest numbers for each possible largest digit
    const first = new Array(10).fill(-1);
    const second = new Array(10).fill(-1);

    for (let i = 0; i < nums.length; i++) {
        let n = nums[i];
        // compute the largest digit of n
        let maxDigit = 0;
        if (n === 0) {
            maxDigit = 0;
        } else {
            while (n > 0) {
                const d = n % 10;
                if (d > maxDigit) maxDigit = d;
                n = Math.floor(n / 10);
            }
        }

        // keep the two biggest numbers for this maxDigit
        if (nums[i] > first[maxDigit]) {
            second[maxDigit] = first[maxDigit];
            first[maxDigit] = nums[i];
        } else if (nums[i] > second[maxDigit]) {
            second[maxDigit] = nums[i];
        }
    }

    // find the best sum among all digit groups
    let best = -1;
    for (let d = 0; d < 10; d++) {
        if (second[d] !== -1) {
            const sum = first[d] + second[d];
            if (sum > best) best = sum;
        }
    }
    return best;
}

function findTheSafestPathInAGrid(grid) {
    if (!grid.length || !grid[0].length) return 0;
    const rows = grid.length, cols = grid[0].length;
    const dist = Array.from({length: rows}, () => new Array(cols).fill(-1));
    const q = [];
    for (let r = 0; r < rows; r++) for (let c = 0; c < cols; c++) if (grid[r][c] === 1) { dist[r][c] = 0; q.push([r, c]); }

    let head = 0;
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (head < q.length) {
        const [r, c] = q[head++];
        const nd = dist[r][c] + 1;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && dist[nr][nc] === -1) {
                dist[nr][nc] = nd;
                q.push([nr, nc]);
            }
        }
    }

    const best = Array.from({length: rows}, () => new Array(cols).fill(-1));
    const startSafety = dist[0][0];
    best[0][0] = startSafety;

    const heap = [[-startSafety, 0, 0]];
    const less = (a, b) => a[0] !== b[0] ? a[0] < b[0] : (a[1] !== b[1] ? a[1] < b[1] : a[2] < b[2]);
    const push = (item) => {
        heap.push(item);
        let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1; if (less(heap[i], heap[p])) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; } else break; }
    };
    const pop = () => {
        const top = heap[0]; const last = heap.pop();
        if (heap.length) {
            heap[0] = last; let i = 0;
            while (true) { let l = 2*i+1, r = 2*i+2, s = i; if (l < heap.length && less(heap[l], heap[s])) s = l; if (r < heap.length && less(heap[r], heap[s])) s = r; if (s === i) break; [heap[i], heap[s]] = [heap[s], heap[i]]; i = s; }
        }
        return top;
    };

    while (heap.length) {
        const [negSafety, r, c] = pop();
        const safety = -negSafety;
        if (r === rows - 1 && c === cols - 1) return safety;
        if (safety < best[r][c]) continue;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                const newSafety = Math.min(safety, dist[nr][nc]);
                if (newSafety > best[nr][nc]) {
                    best[nr][nc] = newSafety;
                    push([-newSafety, nr, nc]);
                }
            }
        }
    }
    return 0;
}

function makeStringSubsequence(str1, str2) {
    const n = str1.length, m = str2.length;
    let i = 0, j = 0;

    // try to match each character of str2 with the earliest possible position in str1
    while (i < n && j < m) {
        const cur = str1[i];
        const next = cur === 'z' ? 'a' : String.fromCharCode(cur.charCodeAt(0) + 1);
        if (cur === str2[j] || next === str2[j]) {
            j++;               // character matched, move to next of str2
        }
        i++;                   // always move forward in str1
    }
    return j === m;            // all characters of str2 were matched
}

function minOperations(nums) {
    // dp1 = longest subsequence consisting only of 1's seen so far
    // dp2 = longest subsequence of 1's followed by 2's
    // dp3 = longest subsequence of 1's, then 2's, then 3's
    let dp1 = 0, dp2 = 0, dp3 = 0;

    for (let v of nums) {
        if (v === 1) {
            // keep this 1 in the all‑1s part
            dp1 = dp1 + 1;
        } else if (v === 2) {
            // either extend an existing 1‑then‑2 subsequence or start a new one from dp1
            dp2 = Math.max(dp1, dp2) + 1;
        } else { // v === 3
            // either extend an existing 1‑2‑3 subsequence or start a new one from dp2
            dp3 = Math.max(dp2, dp3) + 1;
        }
    }

    const longest = Math.max(dp1, dp2, dp3);
    return nums.length - longest; // removals needed
}

function isAcronym(words, s) {
    // quick length check: acronym must have same length as words array
    if (s.length !== words.length) return false;

    // compare each character of s with the first letter of the corresponding word
    for (let i = 0; i < words.length; i++) {
        if (words[i].charAt(0) !== s.charAt(i)) return false;
    }
    return true;
}

function maxProfit(n, offers) {
    // sort offers by their ending house index
    offers.sort((a, b) => a[1] - b[1]);

    const m = offers.length;
    const ends = new Array(m);
    const dp = new Array(m);

    for (let i = 0; i < m; i++) ends[i] = offers[i][1];

    for (let i = 0; i < m; i++) {
        const start = offers[i][0];
        const gold  = offers[i][2];

        // binary search the rightmost offer whose end < start
        let lo = 0, hi = i - 1, prev = -1;
        while (lo <= hi) {
            const mid = (lo + hi) >> 1;
            if (ends[mid] < start) {
                prev = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        const take = gold + (prev >= 0 ? dp[prev] : 0); // profit if we accept this offer
        const skip = i > 0 ? dp[i - 1] : 0;              // profit if we ignore it
        dp[i] = take > skip ? take : skip;               // best profit up to i
    }

    return m > 0 ? dp[m - 1] : 0;
}

function countPairsLessThanTarget(nums, target) {
    // sort the array to enable two‑pointer counting
    nums.sort((a, b) => a - b);
    let left = 0;
    let right = nums.length - 1;
    let count = 0;

    while (left < right) {
        // if the smallest + largest is already < target,
        // then all elements between left and right form valid pairs with left
        if (nums[left] + nums[right] < target) {
            count += right - left;   // add all pairs (left, left+1 … right)
            left++;                  // move to next smallest element
        } else {
            right--;                 // need a smaller sum, move the larger pointer leftward
        }
    }
    return count;
}

function minimumKAvoidingSum(n, k) {
    const chosen = new Set();   // stores numbers already taken
    let sum = 0;
    let i = 1;
    while (chosen.size < n) {
        // if the complement of i is already chosen, we cannot take i
        if (chosen.has(k - i)) {
            i++;
            continue;
        }
        chosen.add(i);
        sum += i;
        i++;
    }
    return sum;
}

// Number of Beautiful Integers in the Range (LC 2827) — digit DP
function numberOfBeautifulIntegers(low, high, k) {
    function countUpTo(limit) {
        if (limit < 1) return 0;
        const s = String(limit);
        const L = s.length;
        const memo = new Map();
        function dp(pos, tight, started, evenMinusOdd, mod) {
            if (pos === L) return (started && evenMinusOdd === 0 && mod === 0) ? 1 : 0;
            const key = `${pos}|${tight?1:0}|${started?1:0}|${evenMinusOdd}|${mod}`;
            if (memo.has(key)) return memo.get(key);
            const maxDigit = tight ? Number(s[pos]) : 9;
            let total = 0;
            for (let d = 0; d <= maxDigit; d++) {
                const nTight = tight && d === maxDigit;
                const nStarted = started || d > 0;
                let nBal = evenMinusOdd;
                if (nStarted) nBal += (d % 2 === 0 ? 1 : -1);
                const nMod = nStarted ? (mod * 10 + d) % k : 0;
                total += dp(pos+1, nTight, nStarted, nBal, nMod);
            }
            memo.set(key, total);
            return total;
        }
        return dp(0, true, false, 0, 0);
    }
    return countUpTo(high) - countUpTo(low - 1);
}

function findTheLongestEqualSubarray(nums, k) {
    const n = nums.length;
    if (n === 0) return 0;
    const freq = new Map();
    const freqCount = new Array(n + 1).fill(0);
    let left = 0, maxFreq = 0, ans = 0;

    for (let right = 0; right < n; right++) {
        const val = nums[right];
        const old = freq.get(val) || 0;
        freq.set(val, old + 1);
        if (old > 0) freqCount[old]--;
        freqCount[old + 1]++;
        if (old + 1 > maxFreq) maxFreq = old + 1;

        while ((right - left + 1) - maxFreq > k) {
            const leftVal = nums[left];
            const oldLeft = freq.get(leftVal);
            freq.set(leftVal, oldLeft - 1);
            freqCount[oldLeft]--;
            if (oldLeft - 1 > 0) freqCount[oldLeft - 1]++;
            left++;
            while (maxFreq > 0 && freqCount[maxFreq] === 0) maxFreq--;
        }
        if (maxFreq > ans) ans = maxFreq;
    }
    return ans;
}

function furthestDistanceFromOrigin(moves) {
    let plus=0, minus=0, wild=0;
    for (const c of moves) { if (c==='L') minus++; else if (c==='R') plus++; else wild++; }
    return Math.abs(plus-minus) + wild;
}

function minimumBeautifulArraySum(n, target) {
    const MOD = 1000000007n;
    const N = BigInt(n);
    const T = BigInt(target);
    const A = T / 2n; // floor(target/2)
    const countUpToTarget = A + 1n;

    let sum;
    if (N <= A) {
        sum = N * (N + 1n) / 2n;
    } else if (N === countUpToTarget) {
        sum = A * (A + 1n) / 2n + T;
    } else {
        const extra = N - countUpToTarget;
        sum = A * (A + 1n) / 2n + T + extra * T + extra * (extra + 1n) / 2n;
    }

    return Number((sum % MOD + MOD) % MOD);
}

function maxScore(receiver, k) {
  const n = receiver.length;
  let best = 0;
  const totalTerms = k + 1;
  for (let start = 0; start < n; start++) {
    let cur = start;
    let steps = 0;
    let sum = 0;
    const visited = new Map();
    const path = [];
    while (steps < totalTerms) {
      if (visited.has(cur)) break;
      visited.set(cur, steps);
      path.push(cur);
      sum += cur;
      steps++;
      cur = receiver[cur];
    }
    if (steps === totalTerms) {
      if (sum > best) best = sum;
      continue;
    }
    const cycleStartIdx = visited.get(cur);
    const cycleLen = steps - cycleStartIdx;
    let cycleSum = 0;
    for (let i = cycleStartIdx; i < steps; i++) cycleSum += path[i];
    let remaining = totalTerms - steps;
    const fullCycles = Math.floor(remaining / cycleLen);
    sum += fullCycles * cycleSum;
    remaining %= cycleLen;
    for (let i = 0; i < remaining; i++) sum += path[cycleStartIdx + i];
    if (sum > best) best = sum;
  }
  return best;
}

function canMakeEqual(s1, s2) {
    if (s1.length !== s2.length) return false;
    const n = s1.length;
    // the allowed swap only exchanges two indices of the same parity, so - exactly as
    // in 'Check if Strings Can be Made Equal With Operations I' - characters can only be
    // freely permuted within the even-index positions and within the odd-index positions
    const s1e = [], s1o = [], s2e = [], s2o = [];
    for (let i = 0; i < n; i++) {
        if (i % 2 === 0) { s1e.push(s1[i]); s2e.push(s2[i]); }
        else { s1o.push(s1[i]); s2o.push(s2[i]); }
    }
    s1e.sort(); s2e.sort(); s1o.sort(); s2o.sort();
    return s1e.join('') === s2e.join('') && s1o.join('') === s2o.join('');
}

function maxSumAlmostUnique(nums, m, k) {
    if (k > nums.length) return 0;

    const freq = new Map();          // element → count in current window
    let distinctCount = 0;           // number of keys with count > 0
    let windowSum = 0;
    let best = 0;

    for (let i = 0; i < nums.length; i++) {
        // add rightmost element
        const right = nums[i];
        windowSum += right;
        const rightFreq = (freq.get(right) || 0) + 1;
        freq.set(right, rightFreq);
        if (rightFreq === 1) distinctCount++;   // new distinct element

        // remove leftmost element when window exceeds size k
        if (i >= k) {
            const left = nums[i - k];
            windowSum -= left;
            const leftFreq = freq.get(left) - 1;
            if (leftFreq === 0) {
                freq.delete(left);
                distinctCount--;                // lost a distinct element
            } else {
                freq.set(left, leftFreq);
            }
        }

        // evaluate window when it has exactly k elements
        if (i >= k - 1) {
            if (distinctCount >= m) {
                if (windowSum > best) best = windowSum;
            }
        }
    }

    return best;
}

function minOperations(nums, target) {
    const MAX_BITS = 31; // up to 2^30
    const cnt = new Array(MAX_BITS).fill(0);
    for (let v of nums) {
        let e = 0;
        while (v > 1) {
            v >>= 1;
            e++;
        }
        cnt[e]++;
    }
    let ops = 0;
    for (let i = 0; i < MAX_BITS; i++) {
        // if current bit of target is needed
        if ((target >> i) & 1) {
            // try to use an existing piece of size 2^i
            if (cnt[i] > 0) {
                cnt[i]--;
            } else {
                // find a larger piece to split
                let j = i + 1;
                while (j < MAX_BITS && cnt[j] === 0) j++;
                if (j === MAX_BITS) return -1; // cannot satisfy this bit
                // split down from j to i
                while (j > i) {
                    cnt[j]--;
                    cnt[j - 1] += 2;
                    ops++;
                    j--;
                }
                // now we have at least one piece of size 2^i
                cnt[i]--;
            }
        }
        // combine leftover pieces of size 2^i into larger pieces for future bits
        if (i + 1 < MAX_BITS) {
            cnt[i + 1] += Math.floor(cnt[i] / 2);
        }
    }
    return ops;
}

function canBeEqual(s1, s2) {
    // count characters at even indices
    const evenCount = Array(26).fill(0);
    const oddCount = Array(26).fill(0);
    for (let i = 0; i < s1.length; i++) {
        const idx1 = s1.charCodeAt(i) - 97;
        const idx2 = s2.charCodeAt(i) - 97;
        if (i % 2 === 0) {
            evenCount[idx1]++;   // s1 even position
            evenCount[idx2]--;   // s2 even position
        } else {
            oddCount[idx1]++;    // s1 odd position
            oddCount[idx2]--;    // s2 odd position
        }
    }
    // MAIN LOGIC: verify that both even and odd character multisets match
    for (let i = 0; i < 26; i++) {
        if (evenCount[i] !== 0 || oddCount[i] !== 0) return false;
    }
    return true;
}

function minOperations(num) {
    const n = num.length;
    let answer = n; // worst case: delete everything, leaving "0"
    const targets = ["00", "25", "50", "75"];
    for (const t of targets) {
        let i = n - 1;
        while (i >= 0 && num[i] !== t[1]) i--;
        if (i < 0) continue;
        let j = i - 1;
        while (j >= 0 && num[j] !== t[0]) j--;
        if (j < 0) continue;
        const deletions = (n - 1 - i) + (i - 1 - j);
        if (deletions < answer) answer = deletions;
    }
    // a lone '0' is itself divisible by 25: keep any single zero digit, delete the rest
    for (let i = n - 1; i >= 0; i--) {
        if (num[i] === '0') { answer = Math.min(answer, n - 1); break; }
    }
    return answer;
}

function minOperationsQueries(n, edges, queries) {
    const LOG = Math.ceil(Math.log2(n+1))+1;
    const adj = Array.from({length:n}, () => []);
    for (const [u,v,w] of edges) { adj[u].push([v,w]); adj[v].push([u,w]); }
    const depth = new Array(n).fill(0);
    const up = Array.from({length:LOG}, () => new Array(n).fill(-1));
    // cnt[node][w] = count of weight w edges from root to node (w in 1..26)
    const cnt = Array.from({length:n}, () => new Array(27).fill(0));
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const u = stack.pop();
        for (const [v,w] of adj[u]) {
            if (visited[v]) continue;
            visited[v] = true;
            depth[v] = depth[u]+1;
            up[0][v] = u;
            for (let x = 1; x <= 26; x++) cnt[v][x] = cnt[u][x];
            cnt[v][w]++;
            stack.push(v);
        }
    }
    for (let k = 1; k < LOG; k++) {
        for (let i = 0; i < n; i++) {
            up[k][i] = up[k-1][i] === -1 ? -1 : up[k-1][up[k-1][i]];
        }
    }
    function lca(u, v) {
        if (depth[u] < depth[v]) [u,v] = [v,u];
        let diff = depth[u]-depth[v];
        for (let k = 0; k < LOG; k++) if ((diff>>k)&1) u = up[k][u];
        if (u === v) return u;
        for (let k = LOG-1; k >= 0; k--) {
            if (up[k][u] !== up[k][v]) { u = up[k][u]; v = up[k][v]; }
        }
        return up[0][u];
    }
    const ans = [];
    for (const [a,b] of queries) {
        const l = lca(a,b);
        const pathLen = depth[a] + depth[b] - 2*depth[l];
        let maxCnt = 0;
        for (let x = 1; x <= 26; x++) {
            const c = cnt[a][x] + cnt[b][x] - 2*cnt[l][x];
            if (c > maxCnt) maxCnt = c;
        }
        ans.push(pathLen - maxCnt);
    }
    return ans;
}

function countSymmetricIntegers(low, high) {
    let answer = 0;
    for (let x = low; x <= high; x++) {
        const str = x.toString();                 // convert number to string
        if (str.length % 2 !== 0) continue;       // odd length → never symmetric
        const half = str.length / 2;
        let leftSum = 0, rightSum = 0;
        // sum digits of the first half
        for (let i = 0; i < half; i++) leftSum += str.charCodeAt(i) - 48;
        // sum digits of the second half
        for (let i = half; i < str.length; i++) rightSum += str.charCodeAt(i) - 48;
        if (leftSum === rightSum) answer++;        // symmetric integer found
    }
    return answer;
}

function isReachable(sx, sy, fx, fy, t) {
    // compute the minimum number of moves (Chebyshev distance)
    const minSteps = Math.max(Math.abs(fx - sx), Math.abs(fy - sy));
    // we can always waste extra moves, so reachable iff t is at least minSteps
    return t >= minSteps;
}

function countKSubsequencesOfAStringWithMaximumBeauty(s, k) {
    const MOD = 1000000007n;
    const freq = new Array(26).fill(0);
    for (const ch of s) freq[ch.charCodeAt(0) - 97]++;

    const freqs = freq.filter(c => c);
    const distinct = freqs.length;
    if (k > distinct) return 0;
    if (k === 0) return 1;

    freqs.sort((a, b) => b - a);
    const threshold = freqs[k - 1];

    const higher = freqs.filter(f => f > threshold).length;
    const cntTotal = freqs.filter(f => f === threshold).length;
    const cntNeeded = k - higher;

    const modpow = (base, exp, mod) => {
        base %= mod;
        let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };

    let prod = 1n;
    for (const f of freqs) if (f > threshold) prod = (prod * BigInt(f)) % MOD;
    prod = (prod * modpow(BigInt(threshold), BigInt(cntNeeded), MOD)) % MOD;

    const comb = (n, r) => {
        if (r < 0 || r > n) return 0n;
        let num = 1n, den = 1n;
        for (let i = 0; i < r; i++) { num = (num * BigInt(n - i)) % MOD; den = (den * BigInt(i + 1)) % MOD; }
        return (num * modpow(den, MOD - 2n, MOD)) % MOD;
    };

    const combVal = comb(cntTotal, cntNeeded);
    return Number((prod * combVal) % MOD);
}

function minimumMoves(grid) {
    const sources = [], sinks = [];
    for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) {
        let c = grid[i][j];
        while (c > 1) { sources.push([i,j]); c--; }
        while (c < 1) { sinks.push([i,j]); c++; }
    }
    let best = Infinity;
    function permute(arr, l) {
        if (l === arr.length) {
            let cost = 0;
            for (let i = 0; i < sources.length; i++) cost += Math.abs(sources[i][0]-arr[i][0]) + Math.abs(sources[i][1]-arr[i][1]);
            best = Math.min(best, cost);
            return;
        }
        for (let i = l; i < arr.length; i++) {
            [arr[l], arr[i]] = [arr[i], arr[l]];
            permute(arr, l+1);
            [arr[l], arr[i]] = [arr[i], arr[l]];
        }
    }
    if (sources.length === 0) return 0;
    permute(sinks.slice(), 0);
    return best;
}

function numberOfWays(s, t, k) {
    const MOD = 1000000007n;
    const n = s.length;

    function matMul(a, b) {
        const r = [[0n,0n],[0n,0n]];
        for (let i=0;i<2;i++) for (let j=0;j<2;j++){
            let sum=0n;
            for (let x=0;x<2;x++) sum = (sum + a[i][x]*b[x][j]) % MOD;
            r[i][j]=sum;
        }
        return r;
    }
    function matPow(m, e) {
        let result = [[1n,0n],[0n,1n]];
        let base = m;
        let exp = BigInt(e);
        while (exp>0n) {
            if (exp & 1n) result = matMul(result, base);
            base = matMul(base, base);
            exp >>= 1n;
        }
        return result;
    }
    const trans = [[0n,1n],[BigInt(n-1), BigInt(n-2)]];
    const p = matPow(trans, k);
    const dp0 = p[0][0], dp1 = p[0][1];

    // Z-algorithm on s+t+t
    const combined = s + t + t;
    const m = combined.length;
    const z = new Array(m).fill(0);
    let left=0, right=0;
    for (let i=1;i<m;i++){
        let zi = 0;
        if (i<=right && z[i-left] <= right-i) {
            zi = z[i-left];
        } else {
            zi = Math.max(0, right-i+1);
            while (i+zi<m && combined[i+zi]===combined[zi]) zi++;
        }
        z[i]=zi;
        if (i+zi-1>right){ left=i; right=i+zi-1; }
    }

    let result = 0n;
    for (let i=n;i<2*n;i++){
        if (z[i]>=n) {
            const rot = i-n;
            result = (result + (rot===0?dp0:dp1)) % MOD;
        }
    }
    return Number(result);
}

function numberOfPoints(nums) {
  const covered = new Set();
  for (const [s,e] of nums) for (let i = s; i <= e; i++) covered.add(i);
  return covered.size;
}

function minRightShifts(nums) {
    const n = nums.length;
    let breakIdx = -1;                     // index where order breaks

    for (let i = 0; i < n; i++) {
        const next = (i + 1) % n;
        if (nums[i] > nums[next]) {        // found a decreasing point
            if (breakIdx !== -1) return -1; // more than one break → impossible
            breakIdx = i;
        }
    }

    if (breakIdx === -1) return 0;         // already sorted

    // (breakIdx + 1) is the position of the smallest element;
    // right shifting it to index 0 needs (n - (breakIdx + 1)) shifts
    return (n - (breakIdx + 1)) % n;
}

function countPairs(coordinates, k) {
    // build frequency map of all points
    const freq = new Map();
    for (const [x, y] of coordinates) {
        const key = x + ',' + y;
        freq.set(key, (freq.get(key) || 0) + 1);
    }

    let ans = 0;

    for (const [x, y] of coordinates) {
        const curKey = x + ',' + y;
        // remove current point so we don't pair it with itself or double‑count later
        freq.set(curKey, freq.get(curKey) - 1);

        // MAIN LOGIC: try every possible split a + b = k
        for (let a = 0; a <= k; ++a) {
            const b = k - a;
            const nx = x ^ a;          // needed x‑coordinate of partner
            const ny = y ^ b;          // needed y‑coordinate of partner
            const partnerKey = nx + ',' + ny;
            const cnt = freq.get(partnerKey);
            if (cnt !== undefined) ans += cnt;
        }
    }

    return ans;
}

var countInterestingSubarrays = function(nums, modulo, k) {
    let prefix = 0;
    const remainderCounts = new Map();
    remainderCounts.set(0, 1);
    let result = 0;
    for (const num of nums) {
        const good = (num % modulo === k) ? 1 : 0;
        prefix += good;
        const target = ((prefix - k) % modulo + modulo) % modulo;
        result += remainderCounts.get(target) || 0;
        const key = prefix % modulo;
        remainderCounts.set(key, (remainderCounts.get(key)||0)+1);
    }
    return result;
};

function minArrayLength(nums) {
    const n = nums.length;
    const freq = {};
    let maxFreq = 0;
    for (const x of nums) { freq[x] = (freq[x] || 0) + 1; if (freq[x] > maxFreq) maxFreq = freq[x]; }
    // if one value dominates (appears more than half the time) it can never be fully
    // paired away with anything else; otherwise everything can be paired down to 0 or 1
    if (2 * maxFreq > n) return 2 * maxFreq - n;
    return n % 2;
}

function sumIndicesWithKSetBits(nums, k) {
    let sum = 0;
    for (let i = 0; i < nums.length; i++) {
        // count set bits of the current index
        let bits = 0;
        let x = i;
        while (x) {
            bits += x & 1;
            x >>>= 1;               // unsigned right shift
        }
        if (bits === k) {          // index matches the required popcount
            sum += nums[i];
        }
    }
    return sum;
}

function maximumSum(nums) {
    const n = nums.length;
    function squareFree(x) {
        let result = 1;
        for (let p = 2; p*p <= x; p++) {
            let cnt = 0;
            while (x % p === 0) { x /= p; cnt++; }
            if (cnt % 2 === 1) result *= p;
        }
        if (x > 1) result *= x;
        return result;
    }
    const groups = new Map();
    for (let i = 1; i <= n; i++) {
        const key = squareFree(i);
        groups.set(key, (groups.get(key)||0) + nums[i-1]);
    }
    return Math.max(...groups.values());
}

function maxNumberOfAlloys(n, k, budget, composition, stock, cost) {
  function feasibleWithMachine(machine, x) {
    let total = 0;
    for (let j = 0; j < n; j++) {
      const need = machine[j] * x - stock[j];
      if (need > 0) total += need * cost[j];
    }
    return total <= budget;
  }
  let lo = 0, hi = 2 * 100000000; // generous upper bound
  // tighten hi via binary search feasibility loop below; find max X such that some machine feasible
  function feasible(x) {
    for (const machine of composition) if (feasibleWithMachine(machine, x)) return true;
    return false;
  }
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    if (feasible(mid)) lo = mid; else hi = mid - 1;
  }
  return lo;
}

function countWays(nums) {
    const n = nums.length;
    const freq = new Array(n + 1).fill(0);
    for (const v of nums) freq[v]++;

    let ans = 0;
    let pref = 0;
    for (let k = 0; k < n; k++) {
        if (pref === k && freq[k] === 0) ans++;
        pref += freq[k];
    }
    ans++;
    return ans;
}

function maxOddBinaryNumber(s) {
    // count how many '1's are present
    let ones = 0;
    for (let i = 0; i < s.length; i++) {
        if (s[i] === '1') ones++;
    }

    // place all but one '1' at the front, then zeros, then the final '1'
    const leadingOnes = '1'.repeat(ones - 1);
    const zeros = '0'.repeat(s.length - ones);
    return leadingOnes + zeros + '1';
}

function maximumSumOfHeights(maxHeights) {
    function oneSidePass(arr) {
        const m = arr.length;
        const stack = []; // [value, count]
        const res = new Array(m).fill(0n);
        for (let i = 0; i < m; i++) {
            let count = 1n;
            while (stack.length && stack[stack.length-1][0] >= arr[i]) {
                const [v, c] = stack.pop();
                count += c;
            }
            stack.push([arr[i], count]);
            const sum = BigInt(arr[i]) * count;
            res[i] = i > 0 ? res[i-1] : 0n; // placeholder, will fix below with prefix tracking
        }
        return stack;
    }

    // redo cleanly: maintain running total sum alongside stack
    function pass(arr) {
        const m = arr.length;
        const stack = []; // [value, count, totalSumForThisSegment]
        const res = new Array(m).fill(0n);
        for (let i = 0; i < m; i++) {
            let count = 1n;
            let segSum = BigInt(arr[i]);
            while (stack.length && stack[stack.length-1][0] >= arr[i]) {
                const [v, c] = stack.pop();
                count += c;
            }
            segSum = BigInt(arr[i]) * count;
            stack.push([arr[i], count]);
            const prevTotal = i - Number(count) >= 0 ? res[i - Number(count)] : 0n;
            res[i] = prevTotal + segSum;
        }
        return res;
    }

    const n = maxHeights.length;
    const left = pass(maxHeights);
    const rightArr = maxHeights.slice().reverse();
    const rightRes = pass(rightArr);
    const right = rightRes.slice().reverse();

    let best = 0n;
    for (let i = 0; i < n; i++) {
        const total = left[i] + right[i] - BigInt(maxHeights[i]);
        if (total > best) best = total;
    }
    return Number(best);
}

function minimumOperations(nums) {
    // count frequencies of each number
    const freq = new Map();
    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        freq.set(v, (freq.get(v) || 0) + 1);
    }

    let totalOps = 0;

    // evaluate each frequency independently
    for (const f of freq.values()) {
        if (f === 1) return -1;                     // impossible case
        if (f % 3 === 0) {
            totalOps += f / 3;                      // all groups of 3
        } else {
            // remainder 1 or 2 -> need one extra group
            totalOps += Math.floor(f / 3) + 1;
        }
    }

    return totalOps;
}

function beautifulTowersI(heights) {
    const n = heights.length;
    const left = new Array(n).fill(0);
    let stack = [];
    for (let i = 0; i < n; i++) {
        const h = heights[i];
        while (stack.length && heights[stack[stack.length - 1]] >= h) stack.pop();
        if (stack.length) {
            const prev = stack[stack.length - 1];
            left[i] = left[prev] + h * (i - prev);
        } else {
            left[i] = h * (i + 1);
        }
        stack.push(i);
    }

    const right = new Array(n).fill(0);
    stack = [];
    for (let i = n - 1; i >= 0; i--) {
        const h = heights[i];
        while (stack.length && heights[stack[stack.length - 1]] >= h) stack.pop();
        if (stack.length) {
            const nxt = stack[stack.length - 1];
            right[i] = right[nxt] + h * (nxt - i);
        } else {
            right[i] = h * (n - i);
        }
        stack.push(i);
    }

    let best = 0;
    for (let i = 0; i < n; i++) {
        const total = left[i] + right[i] - heights[i];
        if (total > best) best = total;
    }
    return best;
}

function countValidPaths(n, edges) {
  // Sieve for primes up to n
  const isPrime = new Uint8Array(n + 1);
  if (n >= 2) {
    isPrime.fill(1, 2);
    for (let i = 2; i * i <= n; i++) {
      if (isPrime[i]) {
        for (let j = i * i; j <= n; j += i) {
          isPrime[j] = 0;
        }
      }
    }
  }

  // Build adjacency list
  const adj = Array.from({ length: n + 1 }, () => []);
  for (const [u, v] of edges) {
    adj[u].push(v);
    adj[v].push(u);
  }

  // Find connected components consisting only of non‑prime nodes
  const compId = new Int32Array(n + 1);
  const compSize = [];
  let compCnt = 0;
  const stack = [];
  for (let i = 1; i <= n; i++) {
    if (isPrime[i] || compId[i]) continue;
    compCnt++;
    let size = 0;
    stack.push(i);
    compId[i] = compCnt;
    while (stack.length) {
      const node = stack.pop();
      size++;
      for (const nb of adj[node]) {
        if (!isPrime[nb] && !compId[nb]) {
          compId[nb] = compCnt;
          stack.push(nb);
        }
      }
    }
    compSize[compCnt] = size;
  }

  // Count contributions for each prime node
  let answer = 0;
  for (let p = 1; p <= n; p++) {
    if (!isPrime[p]) continue;
    let total = 0;
    let sumSq = 0;
    for (const nb of adj[p]) {
      if (isPrime[nb]) continue;
      const sz = compSize[compId[nb]];
      total += sz;
      sumSq += sz * sz;
    }
    if (total === 0) continue;
    const contribution = total + (total * total - sumSq) / 2;
    answer += contribution;
  }
  return answer;
}

function maxKDivisibleComponents(n, edges, values, k) {
    // build adjacency list
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    // depth‑first search returning {modSum, compCnt}
    function dfs(u, parent) {
        let sumMod = values[u] % k;          // current subtree sum modulo k
        let comps = 0;                       // components formed inside subtree

        for (const v of adj[u]) {
            if (v === parent) continue;
            const child = dfs(v, u);

            // if child's subtree sum is divisible, cut the edge and count it
            if (child.modSum === 0) {
                comps += child.compCnt + 1;   // +1 for the new component
            } else {
                comps += child.compCnt;       // cannot cut, keep its sum
                sumMod = (sumMod + child.modSum) % k;
            }
        }
        return { modSum: sumMod, compCnt: comps };
    }

    const root = dfs(0, -1);
    // root itself may become a component if its sum is divisible
    return root.compCnt + (root.modSum === 0 ? 1 : 0);
}

function maximumTripletValue(nums) {
    let best = 0;
    let maxI = -Infinity, maxDiff = -Infinity;
    for (const v of nums) {
        if (maxDiff !== -Infinity) best = Math.max(best, maxDiff * v);
        if (maxI !== -Infinity) maxDiff = Math.max(maxDiff, maxI - v);
        maxI = Math.max(maxI, v);
    }
    return best;
}

function minOperations(nums, k) {
    // count of required numbers still missing
    let missing = k;
    // boolean array for numbers 1..k
    const seen = new Array(k + 1).fill(false);

    let ops = 0;
    for (let i = nums.length - 1; i >= 0; i--) {
        ops++;                                   // one more pop operation
        const v = nums[i];
        if (v <= k && !seen[v]) {                // v is a needed number not yet seen
            seen[v] = true;
            missing--;
        }
        if (missing === 0) break;                // all numbers 1..k collected
    }
    return ops;
}

function maxSubarrays(nums) {
  let totalAnd = -1 >>> 0;
  for (const x of nums) totalAnd &= x;
  if (totalAnd !== 0) return 1;
  let count = 0;
  let curAnd = -1 >>> 0;
  for (const x of nums) {
    curAnd &= x;
    if (curAnd === 0) { count++; curAnd = -1 >>> 0; }
  }
  return Math.max(count, 1);
}

function maximumTripletValue(nums) {
    let best = 0n;
    let maxI = -Infinity, maxDiff = -Infinity;
    for (const v of nums) {
        if (maxDiff !== -Infinity) { const c = BigInt(maxDiff)*BigInt(v); if (c > best) best = c; }
        if (maxI !== -Infinity) maxDiff = Math.max(maxDiff, maxI - v);
        maxI = Math.max(maxI, v);
    }
    return Number(best);
}

function countVisitedNodes(edges) {
    const n = edges.length;
    const answer = new Array(n);
    const state = new Array(n).fill(0);

    function dfs(u) {
        if (state[u] === 2) return answer[u];
        if (state[u] === 1) {
            let cur = u, size = 0;
            do {
                size++;
                cur = edges[cur];
            } while (cur !== u);
            cur = u;
            do {
                answer[cur] = size;
                state[cur] = 2;
                cur = edges[cur];
            } while (cur !== u);
            return answer[u];
        }
        state[u] = 1;
        const v = edges[u];
        const childAns = dfs(v);
        if (state[u] === 2) return answer[u]; // u was finalized as part of a cycle during the recursive call
        answer[u] = childAns + 1;
        state[u] = 2;
        return answer[u];
    }

    for (let i = 0; i < n; i++) {
        if (state[i] === 0) dfs(i);
    }
    return answer;
}

function minimumSizeSubarrayInInfiniteArray(nums, target) {
    const n = nums.length;
    const prefix = new Array(n + 1);
    prefix[0] = 0;
    const map = new Map(); // sum -> index
    map.set(0, 0);
    for (let i = 1; i <= n; i++) {
        prefix[i] = prefix[i - 1] + nums[i - 1];
        map.set(prefix[i], i);
    }
    const totalSum = prefix[n];
    let answer = Infinity;

