            const v = nums[addIdx];
            if (v > maxVal) { maxVal = v; maxIdx = addIdx; } // update max
            if (v < minVal) { minVal = v; minIdx = addIdx; } // update min
        }

        // check current i against the best candidates from the eligible set
        if (maxIdx !== -1 && Math.abs(nums[i] - maxVal) >= valueDifference) {
            return [i, maxIdx];
        }
        if (minIdx !== -1 && Math.abs(nums[i] - minVal) >= valueDifference) {
            return [i, minIdx];
        }
    }
    return [-1, -1];
}

function minimumSumOfMountainTripletsII(nums) {
    const n = nums.length;
    if (n < 3) return -1;
    const INF = Infinity;

    const leftMin = new Array(n).fill(INF);
    let cur = INF;
    for (let i = 1; i < n; i++) {
        cur = Math.min(cur, nums[i - 1]);
        leftMin[i] = cur;
    }

    const rightMin = new Array(n).fill(INF);
    cur = INF;
    for (let i = n - 2; i >= 0; i--) {
        cur = Math.min(cur, nums[i + 1]);
        rightMin[i] = cur;
    }

    let ans = INF;
    for (let j = 1; j < n - 1; j++) {
        if (leftMin[j] < nums[j] && rightMin[j] < nums[j]) {
            const total = leftMin[j] + nums[j] + rightMin[j];
            if (total < ans) ans = total;
        }
    }
    return ans === INF ? -1 : ans;
}

function minGroupsForValidAssignment(balls) {
  const counts = new Map();
  for (const b of balls) counts.set(b, (counts.get(b)||0)+1);
  const freqs = [...counts.values()];
  const minCount = Math.min(...freqs);
  for (let k = minCount; k >= 1; k--) {
    let total = 0, feasible = true;
    for (const c of freqs) {
      const g = Math.ceil(c / (k+1));
      if (g * k > c) { feasible = false; break; }
      total += g;
    }
    if (feasible) return total;
  }
  return balls.length; // fallback (k=1 always works actually handled in loop)
}

function findChampion(n, edges) {
    // Create an adjacency list to represent the graph
    let graph = Array(n).fill().map(() => []);
    let inDegree = Array(n).fill(0);

    // Populate the adjacency list and calculate the in-degree of each node
    for (let [u, v] of edges) {
        graph[u].push(v);
        inDegree[v]++;
    }

    // Find all nodes with in-degree 0, which are the potential champions
    let champions = [];
    for (let i = 0; i < n; i++) {
        if (inDegree[i] === 0) {
            champions.push(i);
        }
    }

    // If there is only one champion, return it; otherwise, return -1
    return champions.length === 1 ? champions[0] : -1;
}

function findChampion(grid) {
  let champion = 0;
  // iterate over each team to compare with the current champion
  for (let i = 1; i < grid.length; i++) {
    // check if the current team is stronger than the champion
    let isStronger = true;
    for (let j = 0; j < grid.length; j++) {
      // if the current team is not stronger than any team, it's not the champion
      if (grid[champion][j] && !grid[i][j]) {
        isStronger = false;
        break;
      }
    }
    // if the current team is stronger than the champion, update the champion
    if (isStronger) champion = i;
  }
  return champion;
}

function makeArrayBeautiful(nums, k) {
    let operations = 0;
    for (let i = 0; i < nums.length - 2; i++) {
        // check if the current subarray has a max element less than k
        if (Math.max(...nums.slice(i, i + 3)) < k) {
            // calculate the difference between k and the current max element
            let diff = k - Math.max(...nums.slice(i, i + 3));
            // increment the operations count by the difference
            operations += diff;
            // increment the current max element by the difference
            nums[nums.indexOf(Math.max(...nums.slice(i, i + 3)), i)] += diff;
        }
    }
    return operations;
}

function minimumSum(nums1, nums2) {
    let sum1 = 0, sum2 = 0, zeros1 = 0, zeros2 = 0;
    for (const v of nums1) { if (v === 0) zeros1++; else sum1 += v; }
    for (const v of nums2) { if (v === 0) zeros2++; else sum2 += v; }
    // an array with no zeros has a FIXED sum - it cannot be raised or lowered at all
    if (zeros1 === 0 && zeros2 === 0) return sum1 === sum2 ? sum1 : -1;
    if (zeros1 === 0) return sum1 >= sum2 + zeros2 ? sum1 : -1;
    if (zeros2 === 0) return sum2 >= sum1 + zeros1 ? sum2 : -1;
    // both arrays have zeros: the answer is whichever array's minimum-possible sum is larger
    return Math.max(sum1 + zeros1, sum2 + zeros2);
}

function maxScore(edges, values) {
    const n = values.length;
    const graph = Array.from({ length: n }, () => []);
    for (const [a, b] of edges) { graph[a].push(b); graph[b].push(a); }
    let total = 0;
    for (const v of values) total += v;
    // dp(node) = minimum total value that must stay unzeroed within this subtree so every
    // leaf-path through it keeps a nonzero sum: either keep just this node (covers every
    // path through it), or delegate coverage to each child's own minimal solution
    function dfs(node, parent) {
        let sumChildren = 0, childrenCount = 0;
        for (const child of graph[node]) {
            if (child !== parent) { sumChildren += dfs(child, node); childrenCount++; }
        }
        if (childrenCount === 0) return values[node]; // leaf: nothing to delegate to, must keep itself
        return Math.min(values[node], sumChildren);
    }
    const minKeep = dfs(0, -1);
    return total - minKeep;
}

function maxPoints(edges, coins, k) {
    const n = coins.length;
    const tree = Array.from({length:n},()=>[]);
    for (const [u,v] of edges) { tree[u].push(v); tree[v].push(u); }
    const CAP = 14;
    const memo = Array.from({length:n},()=>new Array(CAP+1).fill(-1));

    function dfs(node, parent, halvings) {
        const h = Math.min(halvings, CAP);
        if (memo[node][h] !== -1) return memo[node][h];

        const baseVal = coins[node] >> h;
        let way1 = baseVal - k;
        let way2 = Math.floor(baseVal / 2);
        for (const child of tree[node]) {
            if (child === parent) continue;
            way1 += dfs(child, node, h);
            way2 += dfs(child, node, Math.min(h + 1, CAP));
        }
        const result = Math.max(way1, way2);
        memo[node][h] = result;
        return result;
    }

    return dfs(0, -1, 0);
}

function distributeCandies(n, limit) {
  let totalWays = 0;
  // iterate over all possible combinations of candies for the first child
  for (let a = 0; a <= Math.min(n, limit); a++) {
    // iterate over all possible combinations of candies for the second child
    for (let b = 0; b <= Math.min(n - a, limit); b++) {
      // calculate the number of candies for the third child
      let c = n - a - b;
      // check if the third child gets more than the limit candies
      if (c <= limit && c >= 0) {
        // increment the total number of ways
        totalWays++;
      }
    }
  }
  return totalWays;
}

