function maximumLength(nums, k) {
    const n = nums.length;
    const dp = Array.from({length:k}, () => new Array(k).fill(0));
    let best = 0;
    for (let i = 0; i < n; i++) {
        const v = ((nums[i] % k) + k) % k;
        for (let r = 0; r < k; r++) {
            const prevV = ((r - v) % k + k) % k;
            const cand = dp[prevV][r] + 1;
            if (cand > dp[v][r]) dp[v][r] = cand;
            best = Math.max(best, dp[v][r]);
        }
    }
    return best;
}

function findMinDiameter(edges1, edges2) {
    // helper: compute diameter and radius of a tree given its edges
    function getDiameterAndRadius(edges) {
        const n = edges.length + 1;
        const adj = Array.from({ length: n }, () => []);
        for (const [u, v] of edges) {
            adj[u].push(v);
            adj[v].push(u);
        }

        // BFS returns farthest node and distance array from start
        function bfs(start) {
            const dist = new Int32Array(n).fill(-1);
            const q = new Array(n);
            let head = 0, tail = 0;
            q[tail++] = start;
            dist[start] = 0;
            let far = start;

            while (head < tail) {
                const cur = q[head++];
                for (const nb of adj[cur]) {
                    if (dist[nb] === -1) {
                        dist[nb] = dist[cur] + 1;
                        q[tail++] = nb;
                        if (dist[nb] > dist[far]) far = nb; // keep farthest
                    }
                }
            }
            return { far, dist };
        }

        // first BFS to find one endpoint of the diameter
        const first = bfs(0);
        // second BFS from that endpoint to get the true diameter
        const second = bfs(first.far);
        const diameter = second.dist[second.far];
        const radius = Math.ceil(diameter / 2);
        return { diameter, radius };
    }

    const t1 = getDiameterAndRadius(edges1);
    const t2 = getDiameterAndRadius(edges2);

    // main logic: the best we can do is connect the centers of both trees
    const candidate = t1.radius + 1 + t2.radius;
    return Math.max(t1.diameter, t2.diameter, candidate);
}

function countSubarrays(nums, k) {
    let answer = 0;
    let prev = [];                     // list of [andValue, count] for subarrays ending at previous index

    for (let x of nums) {
        // start with subarray consisting only of the current element
        let cur = [[x, 1]];

        // extend all subarrays that ended at the previous position
        for (let [val, cnt] of prev) {
            const newVal = val & x;
            const last = cur[cur.length - 1];
            if (newVal === last[0]) {          // merge identical AND results
                last[1] += cnt;
            } else {
                cur.push([newVal, cnt]);
            }
        }

        // count those whose AND equals k
        for (let [val, cnt] of cur) {
            if (val === k) answer += cnt;
        }

        prev = cur;                     // prepare for next iteration
    }

    return answer;
}



