function generateBinaryStrings(n) {
    const result = [];

    // backtrack builds the string character by character
    function dfs(pos, prevZero, cur) {
        if (pos === n) {
            result.push(cur);
            return;
        }
        // always can place '1'
        dfs(pos + 1, false, cur + '1');
        // can place '0' only if previous char wasn't '0'
        if (!prevZero) {
            dfs(pos + 1, true, cur + '0');
        }
    }

    dfs(0, false, '');
    return result;
}

