      s[i][j][1] = s[i-1][j][1] + s[i][j-1][1] - s[i-1][j-1][1] + (grid[i-1][j-1] === 'Y' ? 1 : 0);
      if (s[i][j][0] > 0 && s[i][j][0] === s[i][j][1]) ans++;
