function countAlternatingGroups(colors) {
    const n = colors.length;
    if (n < 3) return 0;                 // not enough tiles for a group

    let groups = 0;
    for (let i = 0; i < n; i++) {
        const left = (i - 1 + n) % n;    // index of left neighbor (circular)
        const right = (i + 1) % n;       // index of right neighbor (circular)

        // main logic: middle tile differs from both neighbors, which are equal
        if (colors[i] !== colors[left] && colors[left] === colors[right]) {
            groups++;
        }
    }
    return groups;
}

function alternatingGroupsII(colors, k) {
    const n = colors.length;
    if (n === 0 || k > n) return 0;
    if (k === 1) return n;
    const need = k - 1;
    let good = 0;
    for (let i = 0; i < need; i++) if (colors[i] !== colors[i + 1]) good++;
    let ans = good === need ? 1 : 0;
    for (let start = 1; start < n; start++) {
        if (colors[start - 1] !== colors[start]) good--;
        const idx = (start + need - 1) % n;
        const nxt = (idx + 1) % n;
        if (colors[idx] !== colors[nxt]) good++;
        if (good === need) ans++;
    }
    return ans;
}

