function constructString(target, words, costs) {
    const n = target.length;
    const dp = new Array(n + 1).fill(Infinity);
    dp[0] = 0;                                   // base: empty prefix costs 0

    for (let i = 0; i < n; i++) {
        if (dp[i] === Infinity) continue;       // unreachable prefix
        for (let w = 0; w < words.length; w++) {
            const word = words[w];
            const len = word.length;
            if (i + len > n) continue;           // word would exceed target length
            // check if word matches target at position i
            if (target.substr(i, len) === word) {
                const newCost = dp[i] + costs[w];
                if (newCost < dp[i + len]) {
                    dp[i + len] = newCost;       // improve cost for longer prefix
                }
            }
        }
    }

    return dp[n] === Infinity ? -1 : dp[n];
}

function minCost(m, n, horizontalCut, verticalCut) {
    // sort cuts in descending order to apply the most expensive cuts first
    horizontalCut.sort((a, b) => b - a);
    verticalCut.sort((a, b) => b - a);

    let i = 0, j = 0;                 // indices for horizontal and vertical cuts
    let horizPieces = 1, vertPieces = 1; // current number of pieces in each direction
    let total = 0;

    // greedy selection of the next cut
    while (i < horizontalCut.length && j < verticalCut.length) {
        if (horizontalCut[i] > verticalCut[j]) {
            total += horizontalCut[i] * vertPieces; // cost multiplied by existing vertical pieces
            horizPieces++;                           // a new horizontal piece is created
            i++;
        } else {
            total += verticalCut[j] * horizPieces; // cost multiplied by existing horizontal pieces
            vertPieces++;                           // a new vertical piece is created
            j++;
        }
    }

    // consume any remaining horizontal cuts
    while (i < horizontalCut.length) {
        total += horizontalCut[i] * vertPieces;
        i++;
    }

    // consume any remaining vertical cuts
    while (j < verticalCut.length) {
        total += verticalCut[j] * horizPieces;
        j++;
    }

    return total;
}

function minimumCost(m, n, horizontalCut, verticalCut) {
    // sort costs descending
    horizontalCut.sort((a, b) => b - a);
    verticalCut.sort((a, b) => b - a);

    let hPieces = 1;          // number of horizontal strips created so far
    let vPieces = 1;          // number of vertical strips created so far
    let i = 0, j = 0;
    let total = 0;

    // greedy selection of the most expensive remaining cut
    while (i < horizontalCut.length || j < verticalCut.length) {
        if (j === verticalCut.length ||
            (i < horizontalCut.length && horizontalCut[i] > verticalCut[j])) {
            // take a horizontal cut
            total += horizontalCut[i] * vPieces;
            hPieces++;
            i++;
        } else {
            // take a vertical cut
            total += verticalCut[j] * hPieces;
            vPieces++;
            j++;
        }
    }

    return total;
}

var getSmallestString = function(s) {
