function deleteNodes(nums, head) {
    // Build a set of values to delete for O(1) look‑ups
    const toDelete = new Set(nums);

    // Dummy node simplifies removal of head nodes
    const dummy = { val: 0, next: head };
    let prev = dummy;
    let curr = head;

    // Traverse the list and unlink nodes whose value is in the set
    while (curr !== null) {
        if (toDelete.has(curr.val)) {
            prev.next = curr.next;          // skip the current node
        } else {
            prev = curr;                    // keep the node, move prev forward
        }
        curr = curr.next;                  // always advance current
    }

    return dummy.next;                     // new head (may be null)
}

function minimumLengthAfterOperations(s) {
