    // each distinct character contributes 1 if its count is odd, else 2
    // (the actual operation lets you delete the two CLOSEST occurrences of a repeated
    // character regardless of adjacency, not just literally-adjacent duplicates)
    for (const k in freq) total += (freq[k] % 2 === 1) ? 1 : 2;
    return total;
}

function minChanges(nums, k) {
  const n = nums.length;
  const pairCount = n / 2;
  const diff = new Array(k + 2).fill(0);
  const exact = new Array(k + 1).fill(0);

  for (let i = 0, j = n - 1; i < j; i++, j--) {
    const a = nums[i], b = nums[j];
    const M = Math.max(a, k - a, b, k - b);
    diff[0] -= 1;
    diff[M + 1] += 1;
    exact[Math.abs(a - b)]++;
  }

  let best = Infinity;
  let cur = 0;
  for (let X = 0; X <= k; X++) {
    cur += diff[X];
    const changes = 2 * pairCount + cur - exact[X];
    if (changes < best) best = changes;
  }
  return best;
}

function numberOfBitChanges(n, k) {
    // If k has a 1 where n has a 0, it can never be reached
    if ((n & k) !== k) return -1;

    // Bits that differ are exactly the ones we need to turn off
    let diff = n ^ k;
    let changes = 0;
    // Count set bits in diff (popcount)
    while (diff) {
        diff &= diff - 1; // remove lowest set bit
        changes++;
    }
    return changes;
}

