function maxScoreFromGridOperations(grid) {
    const n = grid.length;
    const colPrefix = Array.from({ length: n }, () => new Array(n + 1).fill(0));
    for (let j = 0; j < n; j++) {
        for (let i = 0; i < n; i++) colPrefix[j][i + 1] = colPrefix[j][i] + grid[i][j];
    }
    const rangeSum = (j, lo, hi) => (hi <= lo ? 0 : colPrefix[j][hi] - colPrefix[j][lo]);

    // dp[hPrev][hCur]: hPrev = height of column (c-1), hCur = height of column c,
    // value = best total credit for columns 0..c-2 (fully finalized: their neighbors
    // on both sides are already known when they were finalized)
    // start: c = 0 -> virtual h[-1] = 0 fixed, h[0] = hCur free, nothing finalized yet
    let dp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(-Infinity));
    for (let hCur = 0; hCur <= n; hCur++) dp[0][hCur] = 0;

    for (let c = 1; c < n; c++) {
        // moving to include column c: choose hNext = h[c]; finalize column c-1's
        // credit using (hPrev = h[c-2], hCur = h[c-1], hNext = h[c])
        const ndp = Array.from({ length: n + 1 }, () => new Array(n + 1).fill(-Infinity));
        for (let hPrev = 0; hPrev <= n; hPrev++) {
            for (let hCur = 0; hCur <= n; hCur++) {
                if (dp[hPrev][hCur] === -Infinity) continue;
                for (let hNext = 0; hNext <= n; hNext++) {
                    const boundary = Math.max(hPrev, hNext);
                    const credit = rangeSum(c - 1, hCur, boundary);
                    const val = dp[hPrev][hCur] + credit;
                    if (val > ndp[hCur][hNext]) ndp[hCur][hNext] = val;
                }
            }
        }
        dp = ndp;
    }

    // finalize the LAST column (n-1) using virtual right neighbor h[n] = 0
    let best = -Infinity;
    for (let hPrev = 0; hPrev <= n; hPrev++) {
        for (let hCur = 0; hCur <= n; hCur++) {
            if (dp[hPrev][hCur] === -Infinity) continue;
            const boundary = hPrev; // right virtual neighbor = 0, so max(hPrev, 0) = hPrev
            const credit = rangeSum(n - 1, hCur, boundary);
            const val = dp[hPrev][hCur] + credit;
            if (val > best) best = val;
        }
    }
    return best;
}

function findWinningPlayer(x, y) {
    // how many full turns can be played with the available coins
    const maxTurns = Math.min(x, Math.floor(y / 4));

    // odd number of turns → Alice takes the last one, otherwise Bob does
    return (maxTurns % 2 === 1) ? "Alice" : "Bob";
}

function countNotSpecial(l, r) {
    // total numbers in the interval
    const total = r - l + 1;

    // bounds for possible prime square roots
    const low = Math.ceil(Math.sqrt(l));
    const high = Math.floor(Math.sqrt(r));
    if (low > high) return total;               // no squares possible

    // sieve of Eratosthenes up to 'high'
    const isPrime = new Array(high + 1).fill(true);
    isPrime[0] = isPrime[1] = false;
    const limit = Math.floor(Math.sqrt(high));
    for (let i = 2; i <= limit; i++) {
        if (isPrime[i]) {
            for (let j = i * i; j <= high; j += i) {
                isPrime[j] = false;
            }
        }
    }

    // count primes whose square lies in [l, r]
    let primeSquareCount = 0;
    for (let p = low; p <= high; p++) {
        if (isPrime[p]) primeSquareCount++;
    }

    return total - primeSquareCount;
}

