function canAliceWin(s) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    let cnt = 0;
    for (const ch of s) if (vowels.has(ch)) cnt++;
    // Alice wins iff there's at least one vowel present at all, regardless of parity
    // (a well-known result for this exact game: an odd number of vowels lets her win
    // outright with a substring-of-just-vowels move, and an even count >0 still lets
    // her win by instead removing a substring containing an odd number of consonants,
    // which is always possible when a vowel exists, flipping control back in her favor)
    return cnt > 0;
}

function canAliceWin(nums) {
    let total = 0;
    let singleSum = 0;
    let doubleSum = 0;

    for (let i = 0; i < nums.length; i++) {
        const v = nums[i];
        total += v;                         // accumulate total sum
        if (v < 10) {                       // single‑digit numbers
            singleSum += v;
        } else if (v < 100) {               // double‑digit numbers
            doubleSum += v;
        }
    }

    // Alice wins if either her chosen group outweighs the rest
    return singleSum > total - singleSum || doubleSum > total - doubleSum;
