function isPathPossible(xCorner, yCorner, circles) {
    const n = circles.length;
    const leftIdx = n, rightIdx = n+1, bottomIdx = n+2, topIdx = n+3;
    const parent = [...Array(n+4).keys()];
    const rank = new Array(n+4).fill(0);
    function find(v) { while (parent[v] !== v) { parent[v] = parent[parent[v]]; v = parent[v]; } return v; }
    function unite(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) rank[ra]++;
    }
    function touchesSide(x, y, r, side) {
        let dx, dy;
        if (side === 'left') {
            dx = x; dy = 0;
            if (y < 0) dy = -y; else if (y > yCorner) dy = y - yCorner;
        } else if (side === 'right') {
            dx = x - xCorner; dy = 0;
            if (y < 0) dy = -y; else if (y > yCorner) dy = y - yCorner;
        } else if (side === 'bottom') {
            dy = y; dx = 0;
            if (x < 0) dx = -x; else if (x > xCorner) dx = x - xCorner;
        } else {
            dy = y - yCorner; dx = 0;
            if (x < 0) dx = -x; else if (x > xCorner) dx = x - xCorner;
        }
        return dx*dx + dy*dy <= r*r;
    }
    for (let i = 0; i < n; i++) {
        const [x, y, r] = circles[i];
        if (touchesSide(x, y, r, 'left')) unite(i, leftIdx);
        if (touchesSide(x, y, r, 'right')) unite(i, rightIdx);
        if (touchesSide(x, y, r, 'bottom')) unite(i, bottomIdx);
        if (touchesSide(x, y, r, 'top')) unite(i, topIdx);
    }
    for (let i = 0; i < n; i++) {
        const [xi, yi, ri] = circles[i];
        for (let j = i+1; j < n; j++) {
            const [xj, yj, rj] = circles[j];
            const dx = xi - xj, dy = yi - yj;
            if (dx*dx + dy*dy <= (ri+rj)*(ri+rj)) unite(i, j);
        }
