function timeTaken(edges) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    const result = new Array(n).fill(0);

    for (let src = 0; src < n; src++) {
        const dist = new Array(n).fill(-1);
        dist[src] = 0;
        const stack = [src];
        let maxDist = 0;
        while (stack.length) {
            const cur = stack.pop();
            for (const nb of adj[cur]) {
                if (dist[nb] === -1) {
                    const w = (nb % 2 === 0) ? 2 : 1;
                    dist[nb] = dist[cur] + w;
                    if (dist[nb] > maxDist) maxDist = dist[nb];
                    stack.push(nb);
                }
            }
        }
        result[src] = maxDist;
    }
    return result;
}

// Minimum Number of Flips to Make Binary Grid Palindromic II (LC 3240)
function minFlips(grid) {
    const m = grid.length, n = grid[0].length;
    let ops = 0;
    // handle quadruples
    for (let i = 0; i < Math.floor(m/2); i++) {
        for (let j = 0; j < Math.floor(n/2); j++) {
            const vals = [grid[i][j], grid[i][n-1-j], grid[m-1-i][j], grid[m-1-i][n-1-j]];
            const ones = vals.reduce((a,b)=>a+b,0);
            ops += Math.min(ones, 4 - ones);
        }
    }
    // middle row / middle column pairs
    let onesPairs = 0, diffPairs = 0;
    if (m % 2 === 1 && n % 2 === 1) ops += grid[Math.floor(m/2)][Math.floor(n/2)];
    if (m % 2 === 1) {
        const r = Math.floor(m/2);
        for (let j = 0; j < Math.floor(n/2); j++) {
            const a = grid[r][j], b = grid[r][n-1-j];
            if (a !== b) diffPairs++;
            else if (a === 1) onesPairs += 2;
        }
    }
    if (n % 2 === 1) {
        const c = Math.floor(n/2);
        for (let i = 0; i < Math.floor(m/2); i++) {
            const a = grid[i][c], b = grid[m-1-i][c];
            if (a !== b) diffPairs++;
            else if (a === 1) onesPairs += 2;
        }
    }
    if (diffPairs > 0) {
        ops += diffPairs; // each mismatched pair costs 1 flip and can be set to 0 or 1 freely
        if (onesPairs % 4 !== 0 && diffPairs === 0) ops += 2;
    } else {
        if (onesPairs % 4 !== 0) ops += 2;
    }
    return ops;
}

