function snakePosition(n, commands) {
    let row = 0, col = 0;                     // start at cell 0 (0,0)

    for (let i = 0; i < commands.length; i++) {   // process each command
        const cmd = commands[i];
        if (cmd === "UP") row--;                  // move up
        else if (cmd === "DOWN") row++;           // move down
        else if (cmd === "LEFT") col--;           // move left
        else if (cmd === "RIGHT") col++;          // move right
    }

    return row * n + col;                         // convert (row,col) to index
