function countGoodNodes(edges) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);

    // build adjacency list
    for (const [a, b] of edges) {
        adj[a].push(b);
        adj[b].push(a);
    }

    let good = 0; // answer

    function dfs(u, parent) {
        const childSizes = [];

        // explore children
        for (const v of adj[u]) {
            if (v === parent) continue;
            const sz = dfs(v, u);
            childSizes.push(sz);
        }

        // main logic: check if u is good
        let isGood = true;
        if (childSizes.length > 0) {
            const first = childSizes[0];
            for (let i = 1; i < childSizes.length; i++) {
                if (childSizes[i] !== first) {
                    isGood = false;
                    break;
                }
            }
        }
        if (isGood) good++;

        // size of u's subtree
        let total = 1;
        for (const s of childSizes) total += s;
        return total;
    }

    dfs(0, -1);
    return good;
}

function findSmallestMissingInteger(nums) {
    let longestPrefixSum = 0;
    let longestPrefixLength = 0;
    for (let i = 0; i < nums.length; i++) {
        let currentPrefixSum = 0;
        let currentPrefixLength = 0;
        for (let j = i; j < nums.length; j++) {
            // check if the current prefix is sequential
            if (j === i || nums[j] === nums[j - 1] + 1) {
                currentPrefixSum += nums[j];
                currentPrefixLength++;
            } else {
                break;
            }
        }
        // update the longest prefix if the current prefix is longer
        if (currentPrefixLength > longestPrefixLength) {
            longestPrefixLength = currentPrefixLength;
            longestPrefixSum = currentPrefixSum;
        }
    }
    let numSet = new Set(nums);
    let smallestMissingInteger = longestPrefixSum;
    while (numSet.has(smallestMissingInteger)) {
        // increment the smallest missing integer until we find one that's not in the set
        smallestMissingInteger++;
    }
    return smallestMissingInteger;
}

