function countMonotonicPairs(nums) {
  const MOD = 1000000007;
  const MAX = 50;
  let dp = new Array(MAX + 1).fill(0);
  for (let v = 0; v <= nums[0]; v++) dp[v] = 1;
  for (let i = 0; i < nums.length - 1; i++) {
    const diff = nums[i + 1] - nums[i];
    const need = diff > 0 ? diff : 0;
    const pref = new Array(MAX + 1).fill(0);
    pref[0] = dp[0];
    for (let v = 1; v <= MAX; v++) {
      pref[v] = (pref[v - 1] + dp[v]) % MOD;
    }
    const next = new Array(MAX + 1).fill(0);
    for (let v = 0; v <= nums[i + 1]; v++) {
      const limit = v - need;
      if (limit >= 0) next[v] = pref[limit];
    }
    dp = next;
  }
  let ans = 0;
  const last = nums[nums.length - 1];
  for (let v = 0; v <= last; v++) {
    ans = (ans + dp[v]) % MOD;
  }
  return ans;
}

function countDominantOnes(s) {
    const n = s.length;
    const prefOnes = new Array(n + 1).fill(0);
    const prefZeros = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefOnes[i + 1] = prefOnes[i] + (s[i] === '1' ? 1 : 0);
        prefZeros[i + 1] = prefZeros[i] + (s[i] === '0' ? 1 : 0);
    }
    const maxZeros = Math.floor(Math.sqrt(n));
    let ans = 0;
    for (let r = 0; r < n; r++) {
        for (let l = r; l >= 0; l--) {
            const zeros = prefZeros[r + 1] - prefZeros[l];
            if (zeros > maxZeros) break;
            const ones = prefOnes[r + 1] - prefOnes[l];
            if (ones >= zeros * zeros) ans++;
        }
    }
    return ans;
}
