function alternatingGroups(colors, queries) {
    const n = colors.length;
    const diff = new Array(n);
    for (let i = 0; i < n; i++) {
        diff[i] = colors[i] !== colors[(i + 1) % n] ? 1 : 0;
    }
    const result = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const k = q[1];
            const L = k - 1; // need L consecutive diff==1
            let ans = 0;
            let cur = 0;
            for (let i = 0; i < 2 * n; i++) {
                const idx = i % n;
                if (diff[idx] === 1) {
                    cur++;
                } else {
                    cur = 0;
                }
                if (cur >= L) {
                    const start = i - (L - 1);
                    if (start < n) ans++;
                }
            }
            result.push(ans);
        } else {
            const i = q[1];
            const v = q[2];
            if (colors[i] === v) continue;
            colors[i] = v;
            const left = (i - 1 + n) % n;
            diff[left] = colors[left] !== colors[i] ? 1 : 0;
            diff[i] = colors[i] !== colors[(i + 1) % n] ? 1 : 0;
        }
    }
    return result;
}

