function powerOfKSizeSubarrays(nums, k) {
    const n = nums.length;
    const inc = new Array(n).fill(0);
    for (let i = 1; i < n; i++) {
        inc[i] = nums[i] > nums[i - 1] ? 1 : 0;
    }
    let sumInc = 0;
    for (let i = 1; i < k; i++) {
        sumInc += inc[i];
    }
    const results = [];
    const target = k - 1;
    for (let start = 0; start <= n - k; start++) {
        if (sumInc === target) {
            results.push(nums[start + k - 1]);
        } else {
            results.push(-1);
        }
        if (start < n - k) {
            const removeIdx = start + 1;
            const addIdx = start + k;
            sumInc = sumInc - inc[removeIdx] + inc[addIdx];
        }
    }
    return results;
}

function countKConstraintSubstrings(s, k, queries) {
    const n = s.length;
    const r0 = new Array(n);
    const r1 = new Array(n);
    // compute r0: farthest right where zeros <= k
    let right = -1;
    let zeros = 0;
    for (let left = 0; left < n; left++) {
        while (right + 1 < n && zeros + (s.charAt(right + 1) === '0' ? 1 : 0) <= k) {
            right++;
            if (s.charAt(right) === '0') zeros++;
        }
        r0[left] = right;
        if (right >= left) {
            if (s.charAt(left) === '0') zeros--;
        } else {
            right = left - 1;
        }
    }
    // compute r1: farthest right where ones <= k
    right = -1;
    let ones = 0;
    for (let left = 0; left < n; left++) {
        while (right + 1 < n && ones + (s.charAt(right + 1) === '1' ? 1 : 0) <= k) {
            right++;
            if (s.charAt(right) === '1') ones++;
        }
        r1[left] = right;
        if (right >= left) {
            if (s.charAt(left) === '1') ones--;
        } else {
            right = left - 1;
        }
    }
    const maxGood = new Array(n);
    for (let i = 0; i < n; i++) {
        maxGood[i] = Math.max(r0[i], r1[i]);
    }
    // Fenwick Trees
    class Fenwick {
        constructor(size) {
            this.n = size;
            this.bit = new Array(size + 1).fill(0);
        }
        add(idx, delta) {
            for (let i = idx; i <= this.n; i += i & -i) {
                this.bit[i] += delta;
            }
        }
        sum(idx) {
            let res = 0;
            for (let i = idx; i > 0; i -= i & -i) {
                res += this.bit[i];
            }
            return res;
        }
        rangeSum(l, r) { // inclusive, 0‑based
            return this.sum(r + 1) - this.sum(l);
        }
    }
    const bitCnt = new Fenwick(n);
    const bitSum = new Fenwick(n);
    const qObjs = queries.map((qr, idx) => ({ l: qr[0], r: qr[1], idx }));
    qObjs.sort((a, b) => a.r - b.r);
    const ans = new Array(queries.length);
    let pos = 0;
    for (const q of qObjs) {
        while (pos < n && maxGood[pos] <= q.r) {
            bitCnt.add(pos + 1, 1);
            bitSum.add(pos + 1, maxGood[pos]);
            pos++;
        }
        const len = q.r - q.l + 1;
        const cntLe = bitCnt.rangeSum(q.l, q.r);
        const sumLe = bitSum.rangeSum(q.l, q.r);
        const cntGt = len - cntLe;
        const sumMin = sumLe + q.r * cntGt;
        const sumI = (q.l + q.r) * len / 2;
        ans[q.idx] = sumMin + len - sumI;
    }
    return ans;
}
