function finalArrayState(nums, k, multiplier) {
    const n = nums.length;
    if (n === 0) return [];

    // ---------- heap helpers ----------
    const heap = [];

    function swap(i, j) {
        const tmp = heap[i];
        heap[i] = heap[j];
        heap[j] = tmp;
    }

    function less(a, b) {
        // compare by value, break ties by index
        if (a.value !== b.value) return a.value < b.value;
        return a.index < b.index;
    }

    function heapifyUp(pos) {
        while (pos > 0) {
            const parent = (pos - 1) >> 1;
            if (less(heap[pos], heap[parent])) {
                swap(pos, parent);
                pos = parent;
            } else break;
        }
    }

    function heapifyDown(pos) {
        const size = heap.length;
        while (true) {
            let left = pos * 2 + 1;
            let right = left + 1;
            let smallest = pos;

            if (left < size && less(heap[left], heap[smallest])) smallest = left;
            if (right < size && less(heap[right], heap[smallest])) smallest = right;

            if (smallest !== pos) {
                swap(pos, smallest);
                pos = smallest;
            } else break;
        }
    }

    // ---------- build heap ----------
    for (let i = 0; i < n; ++i) {
        heap.push({ value: nums[i], index: i });
        heapifyUp(heap.length - 1);
    }

    // ---------- main logic ----------
    for (let op = 0; op < k; ++op) {
        const node = heap[0];                 // smallest element
        node.value *= multiplier;              // multiply it
        nums[node.index] = node.value;         // store back to result array
        heapifyDown(0);                        // restore heap order
    }

    return nums;
}

