function maxEnergyBoost(energyDrinkA, energyDrinkB) {
    const n = energyDrinkA.length;
    if (n === 0) return 0;

    // initialise states for hour 0
    let a = energyDrinkA[0];   // drink A now
    let b = energyDrinkB[0];   // drink B now
    let s = 0;                 // skip now

    for (let i = 1; i < n; i++) {
        const prevA = a, prevB = b, prevS = s;

        // drink A this hour: continue A or come from a skip
        a = Math.max(prevA, prevS) + energyDrinkA[i];

        // drink B this hour: continue B or come from a skip
        b = Math.max(prevB, prevS) + energyDrinkB[i];

        // skip this hour: can follow any previous state
        s = Math.max(prevA, prevB, prevS);
    }

    // best total after the last hour
    return Math.max(a, b, s);
}

function findTheLargestPalindromeDivisibleByK(n, k) {
    if (k === 0 || n === 0) return "";
    const m = Math.floor((n + 1) / 2);
    const pow10Mod = new Array(n).fill(0);
    pow10Mod[0] = 1 % k;
    for (let i = 1; i < n; i++) pow10Mod[i] = (pow10Mod[i - 1] * 10) % k;

    const weight = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        const j = n - 1 - i;
        if (i === j) weight[i] = pow10Mod[i] % k;
        else weight[i] = (pow10Mod[i] + pow10Mod[j]) % k;
    }

    const reachable = Array.from({length: m + 1}, () => new Uint8Array(k));
    reachable[m][0] = 1;
    for (let i = m - 1; i >= 0; i--) {
        const w = weight[i];
        const cur = reachable[i];
        const nxt = reachable[i + 1];
        for (let r = 0; r < k; r++) {
            if (!nxt[r]) continue;
            for (let d = 0; d <= 9; d++) {
                if (i === 0 && d === 0) continue;
                const nr = (d * w + r) % k;
                cur[nr] = 1;
            }
        }
    }
    if (!reachable[0][0]) return "";

    const firstHalf = new Array(m).fill('');
    let need = 0;
    for (let i = 0; i < m; i++) {
        const w = weight[i];
        for (let d = 9; d >= 0; d--) {
            if (i === 0 && d === 0) continue;
            const contrib = (d * w) % k;
            const suffix = ((need - contrib) % k + k) % k;
            if (reachable[i + 1][suffix]) {
                firstHalf[i] = String(d);
                need = suffix;
                break;
            }
        }
    }
    const res = [...firstHalf];
    const start = n % 2 === 0 ? m - 1 : m - 2;
    for (let i = start; i >= 0; i--) res.push(firstHalf[i]);
    return res.join('');
}

function findKey(num1, num2, num3) {
