    for (let i = 0; i < 4; i++) {               // examine each digit position
        const d1 = s1.charCodeAt(i) - 48;       // convert char to numeric digit
        const d2 = s2.charCodeAt(i) - 48;
        const d3 = s3.charCodeAt(i) - 48;
        const minDigit = Math.min(d1, d2, d3);  // smallest digit at this position
        keyStr += String(minDigit);
    }
    return Number(keyStr); // removes leading zeros automatically
}

function countAlmostEqualPairs(nums) {
    function canSwapToEqual(s, target) {
        const len = s.length;
        for (let i = 0; i < len; i++) {
            for (let j = i + 1; j < len; j++) {
                if (s[i] === s[j]) continue;
                const arr = s.split('');
                const tmp = arr[i];
                arr[i] = arr[j];
                arr[j] = tmp;
                const val = parseInt(arr.join(''), 10);
                if (val === target) return true;
            }
        }
        return false;
    }

    function almostEqual(a, b) {
        if (a === b) return true;
        const sa = a.toString();
        const sb = b.toString();
        return canSwapToEqual(sa, b) || canSwapToEqual(sb, a);
    }

    let count = 0;
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            if (almostEqual(nums[i], nums[j])) count++;
        }
    }
    return count;
}

var countPairs = function(nums) {
    function generate(num) {
        const s = String(num);
        const L = s.length;
        const result = new Set([num]);
        const arr = s.split('');
        for (let i=0;i<L;i++) {
            for (let j=i+1;j<L;j++) {
                const t = arr[i]; arr[i]=arr[j]; arr[j]=t;
                let swapped = arr.join('').replace(/^0+/, '');
                const val = swapped === '' ? 0 : parseInt(swapped, 10);
                result.add(val);
                const t2 = arr[i]; arr[i]=arr[j]; arr[j]=t2;
            }
        }
        return result;
    }
    const n = nums.length;
    const reachable = nums.map(x => generate(x));
    const valueMap = new Map();
    for (let i=0;i<n;i++) {
        for (const v of reachable[i]) {
            if (!valueMap.has(v)) valueMap.set(v, []);
            valueMap.get(v).push(i);
        }
    }
    const seenPairs = new Set();
    let ans = 0;
    for (const idxList of valueMap.values()) {
        const m = idxList.length;
        for (let a=0;a<m;a++) {
            const i = idxList[a];
            for (let b=a+1;b<m;b++) {
                const j = idxList[b];
                const code = i*n+j;
                if (!seenPairs.has(code)) { seenPairs.add(code); ans++; }
            }
        }
    }
    return ans;
};

function finalArrayStateAfterKMultiplicationOperationsII(nums, k, multiplier) {
    const MOD = 1000000007n;
    const n = nums.length;
    const modf = (x) => ((x % Number(MOD)) + Number(MOD)) % Number(MOD);

    if (k === 0 || multiplier === 1) return nums.map(x => modf(x));

    if (multiplier === 0) {
        const key = (val) => {
            if (val === 0) return -Infinity;
            const mag = Math.log(Math.abs(val));
            return val < 0 ? -mag : mag;
        };
        let best = 0;
        for (let i = 1; i < n; i++) if (key(nums[i]) < key(nums[best])) best = i;
        return nums.map((v, i) => i === best ? 0 : modf(v));
    }

    const logM = Math.log(Math.abs(multiplier));
    const cnt = new Array(n).fill(0);

    const heap = [];
    const less = (a, b) => a[0] !== b[0] ? a[0] < b[0] : a[1] < b[1];
    const push = (item) => { heap.push(item); let i = heap.length - 1; while (i > 0) { const p = (i - 1) >> 1; if (less(heap[i], heap[p])) { [heap[i], heap[p]] = [heap[p], heap[i]]; i = p; } else break; } };
    const pop = () => { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let l = 2*i+1, r = 2*i+2, s = i; if (l < heap.length && less(heap[l], heap[s])) s = l; if (r < heap.length && less(heap[r], heap[s])) s = r; if (s === i) break; [heap[i], heap[s]] = [heap[s], heap[i]]; i = s; } } return top; };

    for (let i = 0; i < n; i++) {
        const v = nums[i];
        let kVal;
        if (v === 0) kVal = -Infinity;
        else { const mag = Math.log(Math.abs(v)); kVal = v < 0 ? -mag : mag; }
        push([kVal, i]);
    }

    for (let step = 0; step < k; step++) {
        const [, i] = pop();
        cnt[i]++;
        let newKey;
        if (nums[i] === 0) newKey = -Infinity;
        else { const mag = Math.log(Math.abs(nums[i])) + cnt[i] * logM; newKey = nums[i] < 0 ? -mag : mag; }
        push([newKey, i]);
    }

    const modpow = (base, exp, mod) => {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };

    const result = [];
    for (let i = 0; i < n; i++) {
        const base = BigInt(modf(nums[i]));
        const mult = modpow(BigInt(multiplier), BigInt(cnt[i]), MOD);
        result.push(Number((base * mult) % MOD));
    }
    return result;
}

function haveSameColor(coordinate1, coordinate2) {
    // convert column letter to 1‑8
    const col1 = coordinate1.charCodeAt(0) - 'a'.charCodeAt(0) + 1;
    const col2 = coordinate2.charCodeAt(0) - 'a'.charCodeAt(0) + 1;

    // convert row character to number
    const row1 = parseInt(coordinate1[1], 10);
    const row2 = parseInt(coordinate2[1], 10);

    // squares have same color when (col + row) parity matches
    return (col1 + row1) % 2 === (col2 + row2) % 2;
}

function kthNearestObstacle(queries, k) {
    const heap = [];               // max‑heap storing at most k smallest distances
    const results = [];

    // ----- heap helpers (max‑heap) -----
    const swap = (i, j) => { const t = heap[i]; heap[i] = heap[j]; heap[j] = t; };
    const bubbleUp = (idx) => {
        while (idx > 0) {
            const p = (idx - 1) >> 1;
            if (heap[p] >= heap[idx]) break;
            swap(p, idx);
            idx = p;
        }
    };
    const bubbleDown = (idx) => {
        const n = heap.length;
        while (true) {
            let largest = idx;
            const l = idx * 2 + 1;
            const r = idx * 2 + 2;
            if (l < n && heap[l] > heap[largest]) largest = l;
            if (r < n && heap[r] > heap[largest]) largest = r;
            if (largest === idx) break;
            swap(idx, largest);
            idx = largest;
        }
    };
    const push = (val) => { heap.push(val); bubbleUp(heap.length - 1); };
    const popMax = () => {
        const max = heap[0];
        const end = heap.pop();
        if (heap.length) { heap[0] = end; bubbleDown(0); }
        return max;
    };
    const peek = () => heap[0];
    // -----------------------------------

    for (const [x, y] of queries) {
        const dist = Math.abs(x) + Math.abs(y);   // distance from origin

        if (heap.length < k) {
            push(dist);                            // fill heap until size k
        } else if (dist < peek()) {
            popMax();                              // replace larger element
            push(dist);
        }

        results.push(heap.length === k ? peek() : -1);
    }

    return results;
}

function hashDividedString(s, k) {
    const n = s.length;
    let result = '';

    // Process each k‑length block and compute its hash character
    for (let i = 0; i < n; i += k) {
        let sum = 0;
        // Sum alphabet indices (a→0, b→1, …) of characters in the block
        for (let j = i; j < i + k; j++) {
            sum += s.charCodeAt(j) - 97;
        }
        const hashedChar = String.fromCharCode((sum % 26) + 97);
        result += hashedChar;
    }
    return result;
}

function maxScore(grid) {
    const m = grid.length;
    const valueRows = new Map();
    for (let r = 0; r < m; r++) {
        for (const v of grid[r]) {
            if (!valueRows.has(v)) valueRows.set(v, new Set());
            valueRows.get(v).add(r);
        }
    }
    let dp = new Array(1<<m).fill(0);
    for (const [v, rows] of valueRows) {
        const newDp = dp.slice();
        for (let mask = 0; mask < (1<<m); mask++) {
            for (const r of rows) {
                if ((mask>>r)&1) continue;
                const nm = mask | (1<<r);
                if (dp[mask]+v > newDp[nm]) newDp[nm] = dp[mask]+v;
            }
        }
        dp = newDp;
    }
    return Math.max(...dp);
}

function maximumSubarrayXor(nums, queries) {
    const n = nums.length;
    const score = Array.from({ length: n }, () => new Array(n).fill(0));
    const best = Array.from({ length: n }, () => new Array(n).fill(0));
    for (let i = 0; i < n; i++) { score[i][i] = nums[i]; best[i][i] = nums[i]; }
    for (let len = 2; len <= n; len++) {
        for (let i = 0; i + len - 1 < n; i++) {
            const j = i + len - 1;
            score[i][j] = score[i][j - 1] ^ score[i + 1][j];
            best[i][j] = Math.max(score[i][j], best[i][j - 1], best[i + 1][j]);
        }
    }
    return queries.map(([l, r]) => best[l][r]);
}

function countGoodIntegers(n, k) {
    const fact = new Array(n + 1);
    fact[0] = 1;
    for (let i = 1; i <= n; i++) fact[i] = fact[i - 1] * i;

    const halfLen = Math.ceil(n / 2);
    const lo = Math.pow(10, halfLen - 1);
    const hi = Math.pow(10, halfLen) - 1;
    const seen = new Set();

    for (let half = lo; half <= hi; half++) {
        const halfStr = String(half);
        const mirrorPart = (n % 2 === 0) ? halfStr : halfStr.slice(0, -1);
        const rev = mirrorPart.split('').reverse().join('');
        const fullStr = halfStr + rev;
        const fullNum = Number(fullStr);
        if (fullNum % k !== 0) continue;
        const counts = new Array(10).fill(0);
        for (const ch of fullStr) counts[ch.charCodeAt(0) - 48]++;
        seen.add(counts.join(','));
    }

    let total = 0;
    for (const key of seen) {
        const counts = key.split(',').map(Number);
        let allPerm = fact[n];
        for (const c of counts) allPerm /= fact[c];
        let leadZeroPerm = 0;
        if (counts[0] > 0) {
            leadZeroPerm = fact[n - 1] / fact[counts[0] - 1];
            for (let d = 1; d <= 9; d++) leadZeroPerm /= fact[counts[d]];
        }
        total += (allPerm - leadZeroPerm);
    }
    return total;
}

function maxMoves(kx, ky, positions) {
  const allPos = [[kx,ky], ...positions];
  const m = allPos.length;
  const dist = Array.from({length:m}, () => new Array(m).fill(-1));
  const knightMoves = [[1,2],[2,1],[-1,2],[-2,1],[1,-2],[2,-1],[-1,-2],[-2,-1]];
  for (let s = 0; s < m; s++) {
    const [sx, sy] = allPos[s];
    const d = Array.from({length:50}, () => new Array(50).fill(-1));
    d[sx][sy] = 0;
    const queue = [[sx,sy]];
    let idx = 0;
    while (idx < queue.length) {
      const [x,y] = queue[idx++];
      for (const [dx,dy] of knightMoves) {
        const nx=x+dx, ny=y+dy;
        if (nx>=0&&nx<50&&ny>=0&&ny<50&&d[nx][ny]===-1) { d[nx][ny]=d[x][y]+1; queue.push([nx,ny]); }
      }
    }
    for (let t = 0; t < m; t++) dist[s][t] = d[allPos[t][0]][allPos[t][1]];
  }
  const numPawns = positions.length;
  const memo = new Map();
  function dp(mask, cur, aliceTurn) {
    if (mask === 0) return 0;
    const key = mask+','+cur+','+(aliceTurn?1:0);
    if (memo.has(key)) return memo.get(key);
    let best = aliceTurn ? -Infinity : Infinity;
    for (let p = 0; p < numPawns; p++) {
      if (!(mask & (1<<p))) continue;
      const val = dist[cur][p+1] + dp(mask ^ (1<<p), p+1, !aliceTurn);
      if (aliceTurn) best = Math.max(best, val); else best = Math.min(best, val);
    }
    memo.set(key, best);
    return best;
  }
  const fullMask = (1 << numPawns) - 1;
  return dp(fullMask, 0, true);
}

function countMonotonicPairs(nums) {
    const MOD = 1000000007n;
    const n = nums.length;
    const m = Math.max(...nums);

    let f = new Array(m + 1).fill(0n);
    for (let j = 0; j <= nums[0]; j++) f[j] = 1n;

    for (let i = 1; i < n; i++) {
        const next = new Array(m + 1).fill(0n);
        for (let j = 0; j <= nums[i]; j++) {
            const k = Math.min(j, j + nums[i - 1] - nums[i]);
            let sum = 0n;
            for (let jp = 0; jp <= k; jp++) {
                sum = (sum + f[jp]) % MOD;
            }
            next[j] = sum;
        }
        f = next;
    }

    let ans = 0n;
    for (let j = 0; j <= nums[n - 1]; j++) ans = (ans + f[j]) % MOD;
    return Number(ans);
}

function maximizeScoreOfNumbersInRanges(start, d) {
    const n = start.length;
    if (n <= 1) return 0;
    const intervals = start.map(s => [s, s + d]).sort((a, b) => a[0] - b[0]);
    const minL = intervals[0][0];
    const maxR = intervals[n - 1][1];
    let lo = 0, hi = maxR - minL + 1;

    const feasible = (dist) => {
        let prev = intervals[0][0];
        for (let i = 1; i < n; i++) {
            const need = prev + dist;
            const [loI, hiI] = intervals[i];
            prev = loI > need ? loI : need;
            if (prev > hiI) return false;
        }
        return true;
    };

    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (feasible(mid)) lo = mid + 1; else hi = mid;
    }
    return lo - 1;
}

function convertDateToBinary(date) {
