function maxRemovableQueries(nums, queries) {
    class Heap {
        constructor(cmp) { this.arr = []; this.cmp = cmp; }
        size() { return this.arr.length; }
        peek() { return this.arr[0]; }
        push(val) {
            const a = this.arr; a.push(val);
            let i = a.length - 1;
            while (i > 0) { const p = (i - 1) >> 1; if (this.cmp(a[p], a[i]) <= 0) break; [a[p], a[i]] = [a[i], a[p]]; i = p; }
        }
        pop() {
            const a = this.arr;
            if (a.length === 0) return undefined;
            const root = a[0]; const last = a.pop();
            if (a.length > 0) {
                a[0] = last; let i = 0;
                while (true) {
                    const l = i * 2 + 1, r = l + 1; let s = i;
                    if (l < a.length && this.cmp(a[l], a[s]) < 0) s = l;
                    if (r < a.length && this.cmp(a[r], a[s]) < 0) s = r;
                    if (s === i) break;
                    [a[i], a[s]] = [a[s], a[i]]; i = s;
                }
            }
            return root;
        }
    }
    const n = nums.length, q = queries.length;
    const startAt = Array.from({ length: n }, () => []);
    for (let i = 0; i < q; i++) { const [l, r] = queries[i]; startAt[l].push(r); }
    const startHeap = new Heap((a, b) => b - a);
    const selectedHeap = new Heap((a, b) => a - b);
    let active = 0, used = 0;
    for (let i = 0; i < n; i++) {
        for (const r of startAt[i]) startHeap.push(r);
        while (selectedHeap.size() && selectedHeap.peek() < i) { selectedHeap.pop(); active--; }
        while (active < nums[i]) {
            while (startHeap.size() && startHeap.peek() < i) startHeap.pop();
            if (!startHeap.size()) return -1;
            const r = startHeap.pop();
            selectedHeap.push(r);
            active++; used++;
        }
    }
    return q - used;
}

function largestOutlier(nums) {
    const total = nums.reduce((s, v) => s + v, 0);   // sum of all elements

    // build frequency table
    const freq = Object.create(null);
    for (const v of nums) {
        freq[v] = (freq[v] || 0) + 1;
    }

    let best = -Infinity;

    for (let i = 0; i < nums.length; i++) {
        const sumCandidate = nums[i];                     // element that could be the sum
        const outlier = total - 2 * sumCandidate;        // derived outlier value

        const count = freq[outlier];
        if (count === undefined) continue;               // outlier value not present

        // need distinct indices; if values coincide we need at least two occurrences
        if (outlier === sumCandidate && count < 2) continue;

        if (outlier > best) best = outlier;              // keep the largest possible outlier
    }

    return best;
}

function maxRemainingWeight(edges, k) {
    const n = edges.length + 1;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const dpFull = new Array(n).fill(0);
    const dpReserved = new Array(n).fill(0);

    // iterative post-order DFS
    const parent = new Array(n).fill(-1);
    const order = [];
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const [v] of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                parent[v] = u;
                stack.push(v);
            }
        }
    }

    for (let idx = order.length - 1; idx >= 0; idx--) {
        const u = order[idx];
        let baseSum = 0;
        const gains = [];
        for (const [v, w] of adj[u]) {
            if (v === parent[u]) continue;
            baseSum += dpFull[v];
            const gain = (w + dpReserved[v]) - dpFull[v];
            if (gain > 0) gains.push(gain);
        }
        gains.sort((a, b) => b - a);

        const mFull = k; // if this node's edge to ITS parent is NOT kept, it can use full k for children
        const mReserved = Math.max(0, k - 1); // if edge to parent IS kept, one slot reserved

        let sumFull = 0;
        for (let i = 0; i < Math.min(mFull, gains.length); i++) sumFull += gains[i];
        let sumReserved = 0;
        for (let i = 0; i < Math.min(mReserved, gains.length); i++) sumReserved += gains[i];

        dpFull[u] = baseSum + sumFull;
        dpReserved[u] = baseSum + sumReserved;
    }

    return dpFull[0];
}

function maximizeTargetNodes(edges1, edges2, k) {
    const n = edges1.length + 1;
    const m = edges2.length + 1;

    function buildAdj(num, edges) {
        const adj = Array.from({ length: num }, () => []);
        for (const [a, b] of edges) {
            adj[a].push(b);
            adj[b].push(a);
        }
        return adj;
    }

    const adj1 = buildAdj(n, edges1);
    const adj2 = buildAdj(m, edges2);

    function allPairsDist(num, adj) {
        const dist = Array.from({ length: num }, () => new Int16Array(num));
        for (let s = 0; s < num; s++) {
            const d = dist[s];
            d.fill(-1);
            const queue = new Int16Array(num);
            let head = 0, tail = 0;
            d[s] = 0;
            queue[tail++] = s;
            while (head < tail) {
                const u = queue[head++];
                const du = d[u];
                for (const v of adj[u]) {
                    if (d[v] === -1) {
                        d[v] = du + 1;
                        queue[tail++] = v;
                    }
                }
            }
        }
        return dist;
    }

    const dist1 = allPairsDist(n, adj1);
    const dist2 = allPairsDist(m, adj2);

    // count nodes within k in first tree for each i
    const countFirst = new Int16Array(n);
    for (let i = 0; i < n; i++) {
        let cnt = 0;
        const drow = dist1[i];
        for (let j = 0; j < n; j++) {
            if (drow[j] !== -1 && drow[j] <= k) cnt++;
        }
        countFirst[i] = cnt;
    }

    // bestSecond[r] = maximum number of nodes in second tree within distance r from some center
    const bestSecond = new Int16Array(k + 1);
    for (let v = 0; v < m; v++) {
        const cnt = new Int16Array(k + 1);
        const drow = dist2[v];
        for (let w = 0; w < m; w++) {
            const d = drow[w];
            if (d !== -1 && d <= k) cnt[d]++;
        }
        for (let r = 1; r <= k; r++) cnt[r] += cnt[r - 1];
        for (let r = 0; r <= k; r++) {
            if (cnt[r] > bestSecond[r]) bestSecond[r] = cnt[r];
        }
    }

    const answer = new Int16Array(n);
    for (let i = 0; i < n; i++) {
        let maxAdd = 0;
        const drow = dist1[i];
        for (let u = 0; u < n; u++) {
            const d = drow[u];
            const R = k - d - 1;
            if (R >= 0) {
                const add = bestSecond[R];
                if (add > maxAdd) maxAdd = add;
            }
        }
        answer[i] = countFirst[i] + maxAdd;
    }

    return Array.from(answer);
}
