function smallestAllSetBits(n) {
    // work with BigInt to avoid overflow
    let num = BigInt(n);

    // count how many bits are needed to represent num
    let len = 0n;
    let tmp = num;
    while (tmp > 0n) {
        tmp >>= 1n;
        len += 1n;
    }

    // smallest all‑set‑bits number with exactly 'len' bits
    let candidate = (1n << len) - 1n;

    // if it already satisfies the condition, return it
    if (candidate >= num) {
        return Number(candidate);
    }

    // otherwise the answer needs one more bit
    return Number((1n << (len + 1n)) - 1n);
}

function minimumOperationsToMakeArrayValuesEqualToK(nums, k) {
    const distinct = new Set();
    for (const v of nums) {
        if (v < k) return -1;
        if (v > k) distinct.add(v);
    }
    return distinct.size;
}

function minimumTransformationCost(n, m) {
  function isPrime(x) {
    if (x <= 1) return false;
    if (x === 2) return true;
    if (x % 2 === 0) return false;
    const r = Math.floor(Math.sqrt(x));
    for (let i = 3; i <= r; i += 2) {
      if (x % i === 0) return false;
    }
    return true;
  }

  const lenN = n.toString().length;
  const lenM = m.toString().length;
  if (lenN !== lenM) return -1;
  const d = lenN;

  if (isPrime(n) || isPrime(m)) return -1;
  if (n === m) return n;

  const maxVal = Math.pow(10, d) - 1;
  const dist = new Array(maxVal + 1).fill(Infinity);
  const visited = new Array(maxVal + 1).fill(false);

  // simple binary min-heap
  class MinHeap {
    constructor() {
      this.heap = [];
    }
    push(item) {
      this.heap.push(item);
      this._siftUp(this.heap.length - 1);
    }
    _siftUp(idx) {
      while (idx > 0) {
        const parent = (idx - 1) >> 1;
        if (this.heap[parent][0] <= this.heap[idx][0]) break;
        [this.heap[parent], this.heap[idx]] = [this.heap[idx], this.heap[parent]];
        idx = parent;
      }
    }
    pop() {
      if (this.heap.length === 0) return null;
      const top = this.heap[0];
      const end = this.heap.pop();
      if (this.heap.length > 0) {
        this.heap[0] = end;
        this._siftDown(0);
      }
      return top;
    }
    _siftDown(idx) {
      const n = this.heap.length;
      while (true) {
        let left = idx * 2 + 1;
        let right = left + 1;
        let smallest = idx;
        if (left < n && this.heap[left][0] < this.heap[smallest][0]) smallest = left;
        if (right < n && this.heap[right][0] < this.heap[smallest][0]) smallest = right;
        if (smallest === idx) break;
        [this.heap[smallest], this.heap[idx]] = [this.heap[idx], this.heap[smallest]];
        idx = smallest;
      }
    }
    isEmpty() {
      return this.heap.length === 0;
    }
  }

  const heap = new MinHeap();
  dist[n] = n;
  heap.push([n, n]);

  while (!heap.isEmpty()) {
    const [curDist, u] = heap.pop();
    if (visited[u]) continue;
    visited[u] = true;
    if (u === m) return curDist;

    const s = u.toString().padStart(d, '0');
    for (let i = 0; i < d; i++) {
      const digit = s.charCodeAt(i) - 48;
      // decrease
      if (digit > 0) {
        if (i === 0 && digit === 1) {
          // would make leading zero, skip
        } else {
          const v = parseInt(s.slice(0, i) + (digit - 1) + s.slice(i + 1), 10);
          if (!isPrime(v) && curDist + v < dist[v]) {
            dist[v] = curDist + v;
            heap.push([dist[v], v]);
          }
        }
      }
      // increase
      if (digit < 9) {
        const v = parseInt(s.slice(0, i) + (digit + 1) + s.slice(i + 1), 10);
        if (!isPrime(v) && curDist + v < dist[v]) {
          dist[v] = curDist + v;
          heap.push([dist[v], v]);
        }
      }
    }
  }

  return -1;
}

var countComponents = function(nums, threshold) {
    const n = nums.length;
    const parent = Array.from({length:n}, (_,i)=>i);
    const rnk = new Array(n).fill(0);
    function find(x) { while (parent[x]!==x) { parent[x]=parent[parent[x]]; x=parent[x]; } return x; }
    function unite(a,b) {
        let ra=find(a), rb=find(b);
        if (ra===rb) return;
        if (rnk[ra]<rnk[rb]) { const t=ra; ra=rb; rb=t; }
        parent[rb]=ra;
        if (rnk[ra]===rnk[rb]) rnk[ra]++;
    }
    const rep = new Array(threshold+1).fill(-1);
    for (let i=0;i<n;i++) {
        const val = nums[i];
        if (val > threshold) continue;
        let mult = val;
        while (mult <= threshold) {
            if (rep[mult] === -1) rep[mult] = i;
            else unite(i, rep[mult]);
            mult += val;
        }
    }
    const comps = new Set();
    for (let i=0;i<n;i++) comps.add(find(i));
    return comps.size;
};

function transformedArray(nums) {
    const n = nums.length;
    const result = new Array(n);
    for (let i = 0; i < n; i++) {
        let idx = (i + nums[i]) % n;
        if (idx < 0) idx += n;
        result[i] = nums[idx];
    }
    return result;
}

function maxTargetNodes(edges1, edges2) {
    function colorTree(edges) {
        const n = edges.length + 1;
        const adj = Array.from({length:n}, () => []);
        for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
        const color = new Array(n).fill(-1);
        color[0] = 0;
        const stack = [0];
        while (stack.length) {
            const u = stack.pop();
            for (const v of adj[u]) if (color[v] === -1) { color[v] = 1-color[u]; stack.push(v); }
        }
        return color;
    }
    const color1 = colorTree(edges1);
    const color2 = colorTree(edges2);
    const n = color1.length;
    const cnt1 = [0,0];
    for (const c of color1) cnt1[c]++;
    const cnt2 = [0,0];
    for (const c of color2) cnt2[c]++;
    const bestFromTree2 = Math.max(cnt2[0], cnt2[1]);
    const answer = new Array(n);
    for (let i = 0; i < n; i++) answer[i] = cnt1[color1[i]] + bestFromTree2;
    return answer;
}

function findMinimumTime(strength, k) {
    // Find the maximum required strength among all locks
    let maxStrength = 0;
    for (let i = 0; i < strength.length; i++) {
        if (strength[i] > maxStrength) maxStrength = strength[i];
    }
    // Minimum minutes needed to process all locks given the per‑minute limit k
    const minutesForLocks = Math.ceil(strength.length / k);
    // The overall minimum time is the larger of the two constraints
    return Math.max(maxStrength, minutesForLocks);
}

function maxSubarraySumDivisibleByK(nums, k) {
    let prefix = 0;
    let answer = -Infinity;
    const minPrefix = new Array(k).fill(Infinity);
    minPrefix[0] = 0;                     // empty prefix (index 0)

    for (let i = 0; i < nums.length; i++) {
        prefix += nums[i];                // current prefix sum
        const r = (i + 1) % k;            // remainder of index+1

        // best subarray ending at i with length % k == 0
        answer = Math.max(answer, prefix - minPrefix[r]);

        // keep smallest prefix for this remainder
        if (prefix < minPrefix[r]) minPrefix[r] = prefix;
    }
    return answer;
}

function maxAreaRectangle(points) {
  const n = points.length;
  const pointSet = new Set();
  for (const p of points) {
    pointSet.add(p[0] + ',' + p[1]);
  }
  let best = -1;
  for (let i = 0; i < n; i++) {
    const [x1, y1] = points[i];
    for (let j = i + 1; j < n; j++) {
      const [x2, y2] = points[j];
      if (x1 === x2 || y1 === y2) continue;
      const c1 = x1 + ',' + y2;
      const c2 = x2 + ',' + y1;
      if (!pointSet.has(c1) || !pointSet.has(c2)) continue;
      const minX = Math.min(x1, x2);
      const maxX = Math.max(x1, x2);
