    const MAX_DIFF = 300; // maximum possible absolute difference (nums[i] <= 300)
    const dp = Array.from({ length: n }, () => new Uint16Array(MAX_DIFF + 1));
    const suffix = Array.from({ length: n }, () => new Uint16Array(MAX_DIFF + 1));
    let answer = 1; // at least one element

    for (let i = 0; i < n; i++) {
        for (let j = 0; j < i; j++) {
            const d = Math.abs(nums[i] - nums[j]);
            let best = 2; // subsequence consisting of nums[j] and nums[i]
            const prev = suffix[j][d];
            if (prev > 0) {
                const cand = prev + 1;
                if (cand > best) best = cand;
            }
            if (best > dp[i][d]) {
                dp[i][d] = best;
                if (best > answer) answer = best;
            }
        }
        // build suffix max for position i
        let curMax = 0;
        for (let d = MAX_DIFF; d >= 0; d--) {
            if (dp[i][d] > curMax) curMax = dp[i][d];
            suffix[i][d] = curMax;
        }
    }
    return answer;
}

function findMirrorScoreOfAString(s) {
    const stacks = Array.from({length: 26}, () => []);
    let score = 0;
    const aOrd = 'a'.charCodeAt(0);
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - aOrd;
        const mirIdx = 25 - idx;
        if (stacks[mirIdx].length) {
            const pos = stacks[mirIdx].pop();
            score += i - pos;
        } else {
            stacks[idx].push(i);
        }
    }
    return score;
}

function maximumWeight(intervals) {
    const n = intervals.length;
    const idx = intervals.map((v,i)=>i).sort((a,b)=>intervals[a][1]-intervals[b][1]);
    const sorted = idx.map(i => [...intervals[i], i]);
    const ends = sorted.map(v=>v[1]);
    function prevCompatible(i) {
        const start = sorted[i][0];
        let lo=0, hi=i-1, res=-1;
        while (lo<=hi) { const mid=(lo+hi)>>1; if (ends[mid] < start) { res=mid; lo=mid+1; } else hi=mid-1; }
        return res;
    }
    const dp = Array.from({length:n+1}, () => Array.from({length:5}, () => ({w:0n, list:[]})));
    function better(a, b) {
        if (a.w !== b.w) return a.w > b.w ? a : b;
        const la = a.list, lb = b.list;
        for (let i = 0; i < Math.min(la.length, lb.length); i++) {
            if (la[i] !== lb[i]) return la[i] < lb[i] ? a : b;
        }
        return la.length <= lb.length ? a : b;
    }
    for (let i = 1; i <= n; i++) {
        const p = prevCompatible(i-1);
        for (let j = 0; j <= 4; j++) {
            let best = dp[i-1][j];
            if (j > 0) {
                const prevState = dp[p+1][j-1];
                const cand = { w: prevState.w + BigInt(sorted[i-1][2]), list: [...prevState.list, sorted[i-1][3]].sort((a,b)=>a-b) };
                best = better(best, cand);
            }
            dp[i][j] = best;
        }
    }
    let ans = dp[n][0];
    for (let j = 1; j <= 4; j++) ans = better(ans, dp[n][j]);
    return ans.list;
}

function minMaxWeight(n, edges, threshold) {
  const outEdges = Array.from({length: n}, () => []);
  for (const [u, v, w] of edges) outEdges[u].push([v, w]);
  for (let u = 0; u < n; u++) {
    outEdges[u].sort((a, b) => a[1] - b[1]);
    if (outEdges[u].length > threshold) outEdges[u].length = threshold;
  }
  const revAdj = Array.from({length: n}, () => []);
  let maxW = 0;
  for (let u = 0; u < n; u++) {
    for (const [v, w] of outEdges[u]) {
      revAdj[v].push([u, w]);
      if (w > maxW) maxW = w;
    }
  }

  function reachableCount(m) {
    const visited = new Array(n).fill(false);
    visited[0] = true;
    const stack = [0];
    let cnt = 1;
    while (stack.length) {
      const u = stack.pop();
      for (const [v, w] of revAdj[u]) {
        if (w <= m && !visited[v]) {
          visited[v] = true;
          cnt++;
          stack.push(v);
        }
      }
    }
    return cnt;
  }

  if (reachableCount(maxW) < n) return -1;
  let lo = 1, hi = maxW;
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    if (reachableCount(mid) === n) hi = mid; else lo = mid + 1;
  }
  return lo;
}

function zigzagGridTraversal(grid) {
    const rows = grid.length, cols = grid[0].length;
    const flat = [];
    // row-by-row boustrophedon (snake) order: even rows left-to-right, odd rows right-to-left
    for (let r = 0; r < rows; r++) {
        if (r % 2 === 0) { for (let c = 0; c < cols; c++) flat.push(grid[r][c]); }
        else { for (let c = cols - 1; c >= 0; c--) flat.push(grid[r][c]); }
    }
    const result = [];
    for (let i = 0; i < flat.length; i += 2) result.push(flat[i]); // keep every alternate cell
    return result;
}

function countNonDecreasingSubarrays(nums, k) {
    const n = nums.length;
    let answer = 0;
    for (let i = 0; i < n; i++) {
        let curMax = nums[i];
        let cost = 0;
        answer++; // subarray of length 1 is always non‑decreasing
        for (let j = i + 1; j < n; j++) {
            if (nums[j] >= curMax) {
                curMax = nums[j];
            } else {
                cost += curMax - nums[j];
                if (cost > k) break;
            }
            if (cost <= k) answer++;
        }
    }
    return answer;
}

function minimumCostToMakeArraysIdentical(arr, brr, k) {
    let total = 0;
    for (let i = 0; i < arr.length; i++) {
        const a = arr[i];
        const b = brr[i];
        const withoutFlip = Math.abs(a - b);
        const withFlip = k + Math.abs(a + b);
        total += withoutFlip < withFlip ? withoutFlip : withFlip;
    }
    return total;
}

function maximumAmount(coins) {
  const m = coins.length, n = coins[0].length;
  const NEG = -Infinity;
  const dp = Array.from({length:m}, () => Array.from({length:n}, () => [NEG,NEG,NEG]));
  dp[0][0][0] = coins[0][0];
  dp[0][0][1] = Math.max(coins[0][0], 0);
  dp[0][0][2] = Math.max(coins[0][0], 0);
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) continue;
      for (let k = 0; k < 3; k++) {
        let best = NEG;
        if (i > 0) best = Math.max(best, dp[i-1][j][k] + coins[i][j]);
        if (j > 0) best = Math.max(best, dp[i][j-1][k] + coins[i][j]);
        if (k > 0) {
          if (i > 0) best = Math.max(best, dp[i-1][j][k-1]);
          if (j > 0) best = Math.max(best, dp[i][j-1][k-1]);
        }
        dp[i][j][k] = best;
      }
    }
  }
  return dp[m-1][n-1][2];
}

function maxCircularAdjacentDiff(nums) {
    const n = nums.length;
    if (n < 2) return 0;               // no adjacent pair

    let maxDiff = 0;
    for (let i = 0; i < n; i++) {
        const next = (i + 1) % n;
        const diff = Math.abs(nums[i] - nums[next]); // main logic: compare adjacent pair
        if (diff > maxDiff) maxDiff = diff;
    }
    return maxDiff;
}

function sumMaxMinSubseq(nums, k) {
  const MOD = 1000000007n;
  const n = nums.length;
  const sorted = nums.slice().sort((a, b) => a - b);
  const fact = new Array(n + 1);
  const invFact = new Array(n + 1);
  fact[0] = 1n;
  for (let i = 1; i <= n; i++) {
    fact[i] = (fact[i - 1] * BigInt(i)) % MOD;
  }
  const modPow = (base, exp) => {
    let res = 1n;
    let b = base % MOD;
    let e = exp;
    while (e > 0n) {
      if (e & 1n) res = (res * b) % MOD;
      b = (b * b) % MOD;
      e >>= 1n;
    }
    return res;
  };
  const modInv = (x) => modPow(x, MOD - 2n);
  invFact[n] = modInv(fact[n]);
  for (let i = n - 1; i >= 0; i--) {
    invFact[i] = (invFact[i + 1] * BigInt(i + 1)) % MOD;
  }
  const comb = (m, r) => {
    if (r < 0 || r > m) return 0n;
    return (((fact[m] * invFact[r]) % MOD) * invFact[m - r]) % MOD;
  };
  let ans = 0n;
  const maxChoose = k - 1;
  for (let i = 0; i < n; i++) {
    const left = i;
    const right = n - 1 - i;
    let waysMax = 0n;
    const upMax = Math.min(maxChoose, left);
    for (let t = 0; t <= upMax; t++) {
      waysMax = (waysMax + comb(left, t)) % MOD;
    }
    let waysMin = 0n;
    const upMin = Math.min(maxChoose, right);
    for (let t = 0; t <= upMin; t++) {
      waysMin = (waysMin + comb(right, t)) % MOD;
    }
    const val = BigInt(sorted[i]) % MOD;
    const contrib = (val * ((waysMax + waysMin) % MOD)) % MOD;
    ans = (ans + contrib) % MOD;
  }
  return Number(ans);
}

function longestSpecialPath(edges, nums) {
    const n = nums.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const prefix = [];
    let bestLen = 0;
    let bestNodes = Infinity;
    const lastSeen = new Map();

    function dfs(node, parent, depth, left) {
        const val = nums[node];
        const prevDepth = lastSeen.has(val) ? lastSeen.get(val) : -1;
        const newLeft = Math.max(left, prevDepth + 1);

        const curPref = depth === 0 ? 0 : prefix[depth];
        const leftPref = prefix[newLeft];
        const pathLen = curPref - leftPref;
        const nodeCnt = depth - newLeft + 1;

        if (pathLen > bestLen) {
            bestLen = pathLen;
            bestNodes = nodeCnt;
        } else if (pathLen === bestLen && nodeCnt < bestNodes) {
            bestNodes = nodeCnt;
        }

        const saved = lastSeen.has(val) ? lastSeen.get(val) : undefined;
        lastSeen.set(val, depth);

        for (const [nbr, w] of adj[node]) {
            if (nbr === parent) continue;
            prefix[depth + 1] = curPref + w;
            dfs(nbr, node, depth + 1, newLeft);
        }

        if (saved === undefined) lastSeen.delete(val);
        else lastSeen.set(val, saved);
    }

    prefix[0] = 0;
    dfs(0, -1, 0, 0);
    return [bestLen, bestNodes];
}

function manhattanDistancesOfAllArrangementsOfPieces(m, n, k) {
    const MOD = 1000000007n;
    const modpow = (base, exp, mod) => {
        base %= mod; let result = 1n;
        while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
        return result;
    };
    const INV6 = modpow(6n, MOD - 2n, MOD);

    if (k < 2) return 0;
    const totalCells = m * n;
    if (k > totalCells) return 0;

    const N = totalCells - 2;
    let r = k - 2;
    if (r > N) return 0;
    r = Math.min(r, N - r);

    let arrangements;
    if (r === 0) {
        arrangements = 1n;
    } else {
        const inv = new Array(r + 1).fill(0n);
        inv[1] = 1n;
        for (let i = 2; i <= r; i++) {
            inv[i] = (MOD - (MOD / BigInt(i)) * inv[Number(MOD % BigInt(i))] % MOD) % MOD;
        }
        arrangements = 1n;
        const start = N - r;
        for (let i = 1; i <= r; i++) {
            arrangements = (arrangements * BigInt(start + i)) % MOD;
            arrangements = (arrangements * inv[i]) % MOD;
        }
    }

    const mMod = BigInt(m) % MOD;
    const nMod = BigInt(n) % MOD;
    const m3 = (mMod * mMod % MOD) * mMod % MOD;
    const n3 = (nMod * nMod % MOD) * nMod % MOD;

    const rowPart = (nMod * nMod % MOD) * (((m3 - mMod) % MOD + MOD) % MOD) % MOD;
    const colPart = (mMod * mMod % MOD) * (((n3 - nMod) % MOD + MOD) % MOD) % MOD;

    let sumDist = (rowPart + colPart) % MOD;
    sumDist = (sumDist * INV6) % MOD;

    return Number((arrangements * sumDist) % MOD);
}

function countPartitions(nums) {
    const n = nums.length;
    if (n < 2) return 0;                     // no possible split

    let total = 0;
    for (let v of nums) total += v;          // compute total sum

    // if total sum is odd, no partition can give an even difference
    if (total % 2 !== 0) return 0;

    // total is even → every split yields an even difference
    return n - 1;
}

function sumSubarrayMins(nums) {
    let total = 0;
    const n = nums.length;
    for (let i = 0; i < n; i++) {
        const cur = [];
        for (let j = i; j < n; j++) {
            // insert nums[j] into cur, keeping it sorted
            let lo = 0, hi = cur.length;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (cur[mid] < nums[j]) lo = mid + 1; else hi = mid;
            }
            cur.splice(lo, 0, nums[j]);
            const median = cur[Math.floor((cur.length - 1) / 2)];
            total += median;
        }
    }
    return total;
}

function minCost(n, cost) {
    const half = n / 2;
    const INF = Infinity;
    // dp[l][r] = min cost for pair 0 with left color l, right color r (l!=r)
    let dp = [];
    for (let l = 0; l < 3; l++) {
        dp.push(new Array(3).fill(INF));
        for (let r = 0; r < 3; r++) {
            if (l === r) continue;
            dp[l][r] = cost[0][l] + cost[n-1][r];
        }
    }
    for (let i = 1; i < half; i++) {
        const ndp = [];
        for (let l = 0; l < 3; l++) ndp.push(new Array(3).fill(INF));
        for (let l = 0; l < 3; l++) {
            for (let r = 0; r < 3; r++) {
                if (l === r) continue;
                let best = INF;
                for (let pl = 0; pl < 3; pl++) {
                    if (pl === l) continue;
                    for (let pr = 0; pr < 3; pr++) {
                        if (pr === r || pr === pl) continue;
                        if (dp[pl][pr] < best) best = dp[pl][pr];
                    }
                }
                ndp[l][r] = best + cost[i][l] + cost[n-1-i][r];
            }
        }
        dp = ndp;
    }
    let ans = INF;
    for (let l = 0; l < 3; l++) for (let r = 0; r < 3; r++) if (l !== r) ans = Math.min(ans, dp[l][r]);
    return ans;
}

function maxMinSumAtMostK(nums, k) {
  const n = nums.length;
  const leftGreater = new Array(n);
  const rightGreater = new Array(n);
  const leftSmaller = new Array(n);
  const rightSmaller = new Array(n);
  let stack = [];

  // previous greater (strict)
  for (let i = 0; i < n; i++) {
    while (stack.length && nums[stack[stack.length - 1]] <= nums[i]) stack.pop();
    leftGreater[i] = stack.length ? stack[stack.length - 1] : -1;
    stack.push(i);
  }

  // next greater or equal
  stack = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length && nums[stack[stack.length - 1]] < nums[i]) stack.pop();
    rightGreater[i] = stack.length ? stack[stack.length - 1] : n;
    stack.push(i);
  }

  // previous smaller (strict)
  stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length && nums[stack[stack.length - 1]] >= nums[i]) stack.pop();
    leftSmaller[i] = stack.length ? stack[stack.length - 1] : -1;
    stack.push(i);
  }

  // next smaller or equal
  stack = [];
  for (let i = n - 1; i >= 0; i--) {
    while (stack.length && nums[stack[stack.length - 1]] > nums[i]) stack.pop();
    rightSmaller[i] = stack.length ? stack[stack.length - 1] : n;
    stack.push(i);
  }

  const S = k + 1;

  function countPairs(L, R) {
    // count of (l,r) with 1<=l<=L,1<=r<=R, l+r <= S
    let limit = S - R;
    let a = 0;
    if (limit > 0) a = Math.min(L, limit);
    let cnt = a * R;
    const start = a + 1;
    const end = Math.min(L, S - 1);
    if (start <= end) {
      const num = end - start + 1;
      const sum = num * S - (start + end) * num / 2;
      cnt += sum;
    }
    return cnt;
  }

  let ans = 0;
  for (let i = 0; i < n; i++) {
    const Lmax = i - leftGreater[i];
    const Rmax = rightGreater[i] - i;
    const pairsMax = countPairs(Lmax, Rmax);
    ans += nums[i] * pairsMax;

    const Lmin = i - leftSmaller[i];
    const Rmin = rightSmaller[i] - i;
    const pairsMin = countPairs(Lmin, Rmin);
    ans += nums[i] * pairsMin;
  }
  return ans;
}

function maxFreeTime(eventTime, k, startTime, endTime) {
    const n = startTime.length;
    const m = n + 1;
    const gaps = new Array(m);
    gaps[0] = startTime[0];
    for (let i = 1; i < n; i++) {
        gaps[i] = startTime[i] - endTime[i - 1];
    }
    gaps[m - 1] = eventTime - endTime[n - 1];
    let totalFree = 0;
    for (let g of gaps) totalFree += g;
    if (k >= m - 1) return totalFree;
    const sorted = gaps.map((v, idx) => [v, idx]);
    sorted.sort((a, b) => b[0] - a[0]);
    const prefix = new Array(m + 1);
    prefix[0] = 0;
    for (let i = 0; i < m; i++) {
        prefix[i + 1] = prefix[i] + sorted[i][0];
    }
    const rank = new Array(m);
    for (let i = 0; i < m; i++) {
        rank[sorted[i][1]] = i;
    }
    let answer = 0;
    for (let i = 0; i < m; i++) {
        let sumTopK;
        if (rank[i] < k) {
            sumTopK = prefix[k + 1] - gaps[i];
        } else {
            sumTopK = prefix[k];
        }
        const candidate = gaps[i] + sumTopK;
        if (candidate > answer) answer = candidate;
    }
    return answer;
}

function countMentions(numberOfUsers, events) {
    const indexed = events.map((e, i) => ({e, i}));
    indexed.sort((a, b) => {
        const tsA = parseInt(a.e[1]), tsB = parseInt(b.e[1]);
        if (tsA !== tsB) return tsA - tsB;
        const prioA = a.e[0] === 'OFFLINE' ? 0 : 1;
        const prioB = b.e[0] === 'OFFLINE' ? 0 : 1;
        if (prioA !== prioB) return prioA - prioB;
        return a.i - b.i;
    });
    const sorted = indexed.map(x => x.e);
    const mentions = new Array(numberOfUsers).fill(0);
    const offlineUntil = new Array(numberOfUsers).fill(-1);

    for (const [etype, t, content] of sorted) {
        const ts = parseInt(t);
        if (etype === 'OFFLINE') {
            const uid = parseInt(content);
            offlineUntil[uid] = ts + 60;
        } else {
            if (content === 'ALL') {
                for (let i = 0; i < numberOfUsers; i++) mentions[i] += 1;
            } else if (content === 'HERE') {
                for (let i = 0; i < numberOfUsers; i++) {
                    if (offlineUntil[i] <= ts) mentions[i] += 1;
                }
            } else {
                for (const part of content.split(' ')) {
                    const uid = parseInt(part.slice(2));
                    mentions[uid] += 1;
                }
            }
        }
    }
    return mentions;
}

function maxFrequencyAfterSubarrayOperation(nums, k) {
    const n = nums.length;
    let originalCount = 0;
    const deltaSet = new Set();
    deltaSet.add(0);
    for (let i = 0; i < n; i++) {
        if (nums[i] === k) originalCount++;
        deltaSet.add(k - nums[i]);
    }
    let answer = originalCount;
    for (const delta of deltaSet) {
        if (delta === 0) continue; // no change
        let cur = 0;
        let best = 0;
        const target = k - delta;
        for (let i = 0; i < n; i++) {
            if (nums[i] === k) {
                cur -= 1;
            } else if (nums[i] === target) {
                cur += 1;
            }
            if (cur < 0) cur = 0;
            if (cur > best) best = cur;
        }
        const candidate = originalCount + best;
        if (candidate > answer) answer = candidate;
    }
    return answer;
}

function getShortestSupersequenceFrequencies(words) {
    const letterSet = new Set();
    for (const w of words) { letterSet.add(w[0]); letterSet.add(w[1]); }
    const letters = [...letterSet].sort();
    const n = letters.length;
    const idx = {};
    letters.forEach((c, i) => { idx[c] = i; });

    const adj = Array.from({length: n}, () => []);
    const edgeSet = new Set();
    for (const w of words) {
        const key = w[0] + w[1];
        if (edgeSet.has(key)) continue;
        edgeSet.add(key);
        adj[idx[w[0]]].push(idx[w[1]]);
    }

    function isAcyclicAfterRemoving(removedMask) {
        const color = new Array(n).fill(0);
        function dfs(u) {
            if (color[u] === 1) return true;
            if (color[u] === 2) return false;
            color[u] = 1;
            if (!((removedMask >> u) & 1)) {
                for (const v of adj[u]) {
                    if ((removedMask >> v) & 1) continue;
                    if (dfs(v)) return true;
                }
            }
            color[u] = 2;
            return false;
        }
        for (let i = 0; i < n; i++) {
            if (color[i] === 0 && dfs(i)) return false;
        }
        return true;
    }

    let bestMasks = [];
    for (let size = 0; size <= n; size++) {
        const found = [];
        for (let mask = 0; mask < (1 << n); mask++) {
            let popcount = 0, m = mask;
            while (m) { popcount += m & 1; m >>= 1; }
            if (popcount !== size) continue;
            if (isAcyclicAfterRemoving(mask)) found.push(mask);
        }
        if (found.length > 0) { bestMasks = found; break; }
    }

    const results = [];
    for (const mask of bestMasks) {
        const freq = new Array(26).fill(0);
        for (let i = 0; i < n; i++) {
            const code = letters[i].charCodeAt(0) - 97;
            freq[code] = ((mask >> i) & 1) ? 2 : 1;
        }
        results.push(freq);
    }
    return results;
}

function minimumCostGoodCaption(s) {
    const n = s.length;
    if (n === 2 && s[0] !== s[1]) return "";
    const freq = new Map();
    for (const ch of s) freq.set(ch, (freq.get(ch) || 0) + 1);
    const maxFreq = Math.max(...freq.values());
    const candidates = [...freq.keys()].filter(ch => freq.get(ch) === maxFreq);
    const chosen = candidates.sort()[0];
    return chosen.repeat(n);
}

function maxDiffEvenOdd(s) {
    // 1. count frequencies of each character
    const freq = new Array(26).fill(0);
    for (let i = 0; i < s.length; ++i) {
        const idx = s.charCodeAt(i) - 97; // 'a' -> 0
        freq[idx] += 1;
    }

    // 2. find the largest odd frequency and the smallest even frequency
    let maxOdd = -1;          // -1 means "not found yet"
    let minEven = Infinity;  // Infinity means "not found yet"
    for (let i = 0; i < 26; ++i) {
        const f = freq[i];
        if (f === 0) continue;               // ignore letters that do not appear
        if (f % 2 === 1) {                    // odd frequency
            if (f > maxOdd) maxOdd = f;
        } else {                               // even frequency
            if (f < minEven) minEven = f;
        }
    }

    // 3. compute answer (0 if a required group is missing)
    if (maxOdd === -1 || minEven === Infinity) return 0;
    return maxOdd - minEven;
}

function findValidPair(s) {
    // count occurrences of each digit (0‑9)
    const freq = new Array(10).fill(0);
    for (let i = 0; i < s.length; i++) {
        freq[s.charCodeAt(i) - 48]++;          // '0'.charCodeAt(0) == 48
    }

    // look for the first adjacent pair that satisfies the condition
    for (let i = 0; i < s.length - 1; i++) {
        const d1 = s[i];
        const d2 = s[i + 1];
        // main logic: both digits must be distinct and each must appear
        // exactly as many times as its numeric value
        if (d1 !== d2 &&
            freq[d1.charCodeAt(0) - 48] === Number(d1) &&
            freq[d2.charCodeAt(0) - 48] === Number(d2)) {
            return d1 + d2;
        }
    }
    return "";
}

function maxManhattanDistanceAfterKChanges(s, k) {
    let x = 0, y = 0;
    let inward = 0;
    let answer = 0;
    for (let i = 0; i < s.length; i++) {
        const c = s[i];
        let outward;
        if (c === 'N') outward = (y >= 0);
        else if (c === 'S') outward = (y <= 0);
        else if (c === 'E') outward = (x >= 0);
        else outward = (x <= 0); // 'W'
        if (!outward) inward++;
        if (c === 'N') y++;
        else if (c === 'S') y--;
        else if (c === 'E') x++;
        else x--;
        const dist = Math.abs(x) + Math.abs(y);
        const best = dist + 2 * Math.min(k, inward);
        if (best > answer) answer = best;
    }
    return answer;
}

function minimumIncrementsForTargetMultiplesInAnArray(nums, target) {
    const m = target.length;
    if (m === 0) return 0;
    const fullMask = (1 << m) - 1;
    const INF = 1e18;
    const gcd = (a, b) => b === 0 ? a : gcd(b, a % b);

    const lcmMask = new Array(1 << m).fill(1);
    for (let mask = 1; mask <= fullMask; mask++) {
        const bit = 31 - Math.clz32(mask & -mask);
        const prev = mask ^ (1 << bit);
        const prevL = lcmMask[prev];
        const t = target[bit];
        const g = gcd(prevL, t);
        lcmMask[mask] = Math.floor(prevL / g) * t;
    }

    let dp = new Array(1 << m).fill(INF);
    dp[0] = 0;

    for (const cur of nums) {
        const costMask = new Array(1 << m).fill(0);
        for (let mask = 1; mask <= fullMask; mask++) {
            const L = lcmMask[mask];
            const mult = Math.ceil(cur / L);
            const nxt = mult * L;
            costMask[mask] = nxt - cur;
        }

        const ndp = [...dp];
        for (let sub = 1; sub <= fullMask; sub++) {
            const add = costMask[sub];
            const comp = fullMask ^ sub;
            let mask = comp;
            while (true) {
                const newmask = mask | sub;
                const cand = dp[mask] + add;
                if (cand < ndp[newmask]) ndp[newmask] = cand;
                if (mask === 0) break;
                mask = (mask - 1) & comp;
            }
        }
        dp = ndp;
    }

    return dp[fullMask];
}

var maxFreeTime = function(eventTime, startTime, endTime) {
    const n = startTime.length;
    const leftGaps = new Array(n).fill(0);
    leftGaps[0] = startTime[0];
    for (let i = 1; i < n; i++) {
        leftGaps[i] = Math.max(leftGaps[i-1], startTime[i] - endTime[i-1]);
    }
    const rightGaps = new Array(n).fill(0);
    rightGaps[n-1] = eventTime - endTime[n-1];
    for (let i = n-2; i >= 0; i--) {
        rightGaps[i] = Math.max(rightGaps[i+1], startTime[i+1] - endTime[i]);
    }
    let res = 0;
    for (let i = 0; i < n; i++) {
        const leftGap = i === 0 ? leftGaps[0] : startTime[i] - endTime[i-1];
        const rightGap = i === n-1 ? rightGaps[n-1] : startTime[i+1] - endTime[i];
        const duration = endTime[i] - startTime[i];
        let interval = 0;
        const canUseLeft = i !== 0 && leftGaps[i-1] >= duration;
        const canUseRight = i !== n-1 && rightGaps[i+1] >= duration;
        if (canUseLeft || canUseRight) interval = duration;
        res = Math.max(res, leftGap + interval + rightGap);
    }
    return res;
};

function sortMatrix(grid) {
    const n = grid.length;
    for (let i = 0; i < n; i++) {
        const diag = [];
        for (let r = i, c = 0; r < n; r++, c++) diag.push(grid[r][c]);
        diag.sort((a,b) => b-a);
        let k=0;
        for (let r = i, c = 0; r < n; r++, c++) grid[r][c] = diag[k++];
    }
    for (let j = 1; j < n; j++) {
        const diag = [];
        for (let r = 0, c = j; c < n; r++, c++) diag.push(grid[r][c]);
        diag.sort((a,b) => a-b);
        let k=0;
        for (let r = 0, c = j; c < n; r++, c++) grid[r][c] = diag[k++];
    }
    return grid;
}

function assignElements(groups, elements) {
  const result = [];
  for (const g of groups) {
    let found = -1;
    for (let i = 0; i < elements.length; i++) {
      if (elements[i] !== 0 && g % elements[i] === 0) { found = i; break; }
    }
    result.push(found);
  }
  return result;
}

function maxDifferenceEvenOdd(s, k) {
    const n = s.length;
    const INF = Number.MAX_SAFE_INTEGER;
    let ans = -Infinity;
    for (let a = 0; a <= 4; a++) {
        for (let b = 0; b <= 4; b++) {
            if (a === b) continue;
            const aChar = String(a), bChar = String(b);
            let curA = 0, curB = 0, preA = 0, preB = 0;
            const t = [[INF, INF],[INF, INF]];
            let l = -1;
            for (let r = 0; r < n; r++) {
                if (s[r] === aChar) curA++;
                if (s[r] === bChar) curB++;
                while (r - l >= k && curB - preB >= 2) {
                    const pa = preA & 1, pb = preB & 1;
                    if (preA - preB < t[pa][pb]) t[pa][pb] = preA - preB;
                    l++;
                    if (s[l] === aChar) preA++;
                    if (s[l] === bChar) preB++;
                }
                const idxA = (curA & 1) ^ 1;
                const idxB = curB & 1;
                const cand = curA - curB - t[idxA][idxB];
                if (cand > ans) ans = cand;
            }
        }
    }
    return ans;
}

function maximizeTheMinimumGameScore(points, m) {
    const maxP = points.length ? Math.max(...points) : 0;
    let low = 0, high = maxP * m;
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        let need = 0;
        for (const v of points) {
            need += Math.ceil(mid / v);
            if (need > m) break;
        }
        if (need <= m) low = mid; else high = mid - 1;
    }
    return low;
}

function countSubstrings(s) {
    const n = s.length;
    let count = 0;
    for (let i = 0; i < n; i++) {
        const rem = new Array(10).fill(0);
        for (let j = i; j < n; j++) {
            const digit = s.charCodeAt(j) - 48;
            for (let d = 1; d <= 9; d++) {
                rem[d] = (rem[d] * 10 + digit) % d;
            }
            if (digit !== 0 && rem[digit] === 0) count++;
        }
    }
    return count;
}

function sumGoodNumbers(nums, k) {
    const n = nums.length;
    let total = 0;

    // iterate through each element and test the good condition
    for (let i = 0; i < n; i++) {
        let good = true;

        // compare with left neighbor if it exists
        const left = i - k;
        if (left >= 0 && !(nums[i] > nums[left])) {
            good = false;
        }

        // compare with right neighbor if it exists
        const right = i + k;
        if (right < n && !(nums[i] > nums[right])) {
            good = false;
        }

        // add to sum if still good
        if (good) {
            total += nums[i];
        }
    }

    return total;
}

function separateSquares(squares) {
    let lo = 0, hi = 2e9;
    function areaAbove(y) {
        let above = 0, below = 0;
        for (const [x, sy, l] of squares) {
            const top = sy + l;
            if (y <= sy) above += l*l;
            else if (y >= top) below += l*l;
            else { above += (top - y)*l; below += (y - sy)*l; }
        }
        return above - below;
    }
    for (let iter = 0; iter < 100; iter++) {
        const mid = (lo + hi) / 2;
        if (areaAbove(mid) > 0) lo = mid; else hi = mid;
    }
    return lo;
}

function findSpecialSubstring(s, k) {
    if (k <= 0) return false;               // invalid length
    let consecutive = 1;                    // count of current run
    for (let i = 1; i < s.length; i++) {
        // reset or extend the run of identical characters
        if (s[i] === s[i - 1]) {
            consecutive++;
        } else {
            consecutive = 1;
        }
        if (consecutive >= k) return true; // found a run long enough
    }
    return false;
}

function shortestMatchingSubstring(s, p) {
    // split pattern into three fixed parts
    const parts = p.split('*');          // ["A","B","C"]
    const A = parts[0];
    const B = parts[1];
    const C = parts[2];
    const n = s.length;

    // find every index where a given sub‑string occurs (empty sub matches everywhere)
    function findMatches(sub) {
        const res = [];
        if (sub.length === 0) {
            for (let i = 0; i <= n; i++) res.push(i);
            return res;
        }
        for (let i = 0; i + sub.length <= n; i++) {
            if (s.substr(i, sub.length) === sub) res.push(i);
        }
        return res;
    }

    const startsA = findMatches(A);
    const startsB = findMatches(B);
    const startsC = findMatches(C);

    // nextB[pos] = smallest start index of B that is >= pos (‑1 if none)
    const nextB = new Array(n + 1).fill(-1);
    let idxB = 0;
    for (let pos = 0; pos <= n; pos++) {
        while (idxB < startsB.length && startsB[idxB] < pos) idxB++;
        if (idxB < startsB.length) nextB[pos] = startsB[idxB];
    }

    // nextC[pos] = smallest start index of C that is >= pos (‑1 if none)
    const nextC = new Array(n + 1).fill(-1);
    let idxC = 0;
    for (let pos = 0; pos <= n; pos++) {
        while (idxC < startsC.length && startsC[idxC] < pos) idxC++;
        if (idxC < startsC.length) nextC[pos] = startsC[idxC];
    }

    let best = Infinity;

    // try every possible start of A and greedily take the earliest B and C after it
    for (const i of startsA) {
        const posB = i + A.length;
        const j = nextB[posB];
        if (j === -1) continue;               // no B after this A
        const posC = j + B.length;
        const k = nextC[posC];
        if (k === -1) continue;               // no C after this B
        const len = (k + C.length) - i;       // length of substring covering A‑B‑C
        if (len < best) best = len;
    }

    return best === Infinity ? -1 : best;
}

// TIME: O(n * (|A|+|B|+|C|))  SPACE: O(n)

function separateSquaresII(squares) {
  function lowerBound(arr, target) {
    let l = 0, r = arr.length;
    while (l < r) {
      const m = (l + r) >> 1;
      if (arr[m] < target) l = m + 1;
      else r = m;
    }
    return l;
  }

  function unionArea(rects) {
    if (rects.length === 0) return 0;
    const events = [];
    const yVals = [];
    for (const [x1, x2, y1, y2] of rects) {
      events.push({ x: x1, type: 1, y1, y2 });
      events.push({ x: x2, type: -1, y1, y2 });
      yVals.push(y1, y2);
    }
    events.sort((a, b) => a.x - b.x);
    yVals.sort((a, b) => a - b);
    const uniqY = [];
    for (let i = 0; i < yVals.length; i++) {
      if (i === 0 || yVals[i] !== yVals[i - 1]) uniqY.push(yVals[i]);
    }
    const m = uniqY.length - 1; // number of elementary y-intervals
    if (m <= 0) return 0;
    const cnt = new Int32Array((m + 2) * 4);
    const len = new Float64Array((m + 2) * 4);

    function update(node, l, r, ql, qr, delta) {
      if (ql > r || qr < l) return;
      if (ql <= l && r <= qr) {
        cnt[node] += delta;
      } else {
        const mid = (l + r) >> 1;
        update(node * 2, l, mid, ql, qr, delta);
        update(node * 2 + 1, mid + 1, r, ql, qr, delta);
      }
      if (cnt[node] > 0) {
        len[node] = uniqY[r + 1] - uniqY[l];
      } else if (l === r) {
        len[node] = 0;
      } else {
        len[node] = len[node * 2] + len[node * 2 + 1];
      }
    }

    let area = 0;
    let prevX = events[0].x;
    for (let i = 0; i < events.length; i++) {
      const e = events[i];
      const dx = e.x - prevX;
      if (dx !== 0) area += len[1] * dx;
      const y1Idx = lowerBound(uniqY, e.y1);
      const y2Idx = lowerBound(uniqY, e.y2) - 1;
      if (y1Idx <= y2Idx) update(1, 0, m - 1, y1Idx, y2Idx, e.type);
      prevX = e.x;
    }
    return area;
  }

  // total union area of full squares
  const fullRects = squares.map(s => {
    const [x, y, l] = s;
    return [x, x + l, y, y + l];
  });
  const totalArea = unionArea(fullRects);
  const halfArea = totalArea / 2;

  // binary search on Y
  let low = Infinity, high = -Infinity;
  for (const [x, y, l] of squares) {
    if (y < low) low = y;
    if (y + l > high) high = y + l;
  }

  for (let iter = 0; iter < 60; iter++) {
    const mid = (low + high) / 2;
    const rects = [];
    for (const [x, y, l] of squares) {
      const y2 = Math.min(y + l, mid);
      if (y2 > y) rects.push([x, x + l, y, y2]);
    }
    const areaBelow = unionArea(rects);
    if (areaBelow >= halfArea) high = mid;
    else low = mid;
  }
  return high;
}
// TIME: O(N log N * log(precision)) SPACE: O(N)

function maxSumWithAtMostK(grid, limits, k) {
    const candidates = [];

    // ----- row‑wise greedy selection -----
    for (let i = 0; i < grid.length; ++i) {
        const row = grid[i];
        // sort descending to bring the biggest numbers to the front
        const sorted = row.slice().sort((a, b) => b - a);
        const take = Math.min(limits[i] ?? 0, sorted.length);
        for (let j = 0; j < take; ++j) {
            candidates.push(sorted[j]);
        }
    }

    // ----- global greedy selection -----
    candidates.sort((a, b) => b - a);          // biggest first
    const limit = Math.min(k, candidates.length);
    let sum = 0;
    for (let i = 0; i < limit; ++i) {
        sum += candidates[i];
    }
    return sum;
}

function eatPizzas(pizzas) {
    const a = [...pizzas].sort((x, y) => x - y);
    const n = a.length;
    const days = Math.floor(n / 4);
    const odd = Math.floor((days + 1) / 2);
    const even = days - odd;
    let total = 0;
    for (let i = 0; i < odd; i++) total += a[n - 1 - i];
    let idx = n - odd - 2;
    for (let i = 0; i < even; i++) {
        total += a[idx];
        idx -= 2;
    }
    return total;
}

