function selectKDisjointSpecialSubstrings(s, k) {
    // count frequency of each character
    const freq = {};
    for (let i = 0; i < s.length; i++) {
        const ch = s[i];
        freq[ch] = (freq[ch] || 0) + 1;
    }

    // count characters that appear exactly once
    let uniqueCount = 0;
    for (const ch in freq) {
        if (freq[ch] === 1) uniqueCount++;
    }

    // we can take each unique character as a length‑1 substring
    return uniqueCount >= k;
}

var lenOfVDiagonal = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dirs = [1,1,-1,-1,1];
    const memo = new Array(m);
    for (let i=0;i<m;i++){
        memo[i]=new Array(n);
        for (let j=0;j<n;j++){
            memo[i][j]=[[null,null],[null,null],[null,null],[null,null]];
        }
    }
    function dfs(i,j,k,cnt){
        if (memo[i][j][k][cnt]!==null) return memo[i][j][k][cnt];
        const target = grid[i][j]===2?0:2;
        let best=0;
        const x=i+dirs[k], y=j+dirs[k+1];
        if (x>=0&&x<m&&y>=0&&y<n&&grid[x][y]===target){
            best = dfs(x,y,k,cnt)+1;
        }
        if (cnt===0){
            const k2=(k+1)%4;
            const x2=i+dirs[k2], y2=j+dirs[k2+1];
            if (x2>=0&&x2<m&&y2>=0&&y2<n&&grid[x2][y2]===target){
                best = Math.max(best, dfs(x2,y2,k2,1)+1);
            }
        }
        memo[i][j][k][cnt]=best;
        return best;
    }
    let ans=0;
    for (let i=0;i<m;i++){
        for (let j=0;j<n;j++){
            if (grid[i][j]===1){
                for (let k=0;k<4;k++){
                    ans = Math.max(ans, dfs(i,j,k,0)+1);
                }
            }
        }
    }
    return ans;
};

function areDigitsEqual(s) {
  // convert string to array of numbers
  let digits = s.split('').map(ch => Number(ch));

  // repeatedly replace with sums modulo 10 until only two digits remain
  while (digits.length > 2) {
    const next = new Array(digits.length - 1);
    for (let i = 0; i < next.length; i++) {
      next[i] = (digits[i] + digits[i + 1]) % 10;
    }
    digits = next;
  }

  // check if the final two digits are equal
  return digits[0] === digits[1];
}

function maxMinManhattanDistance(side, points, k) {
    const P = 4 * side;
    const s = [];
    for (const [x, y] of points) {
        let pos;
        if (y === 0) {
            pos = x; // bottom side
        } else if (x === side) {
            pos = side + y; // right side
        } else if (y === side) {
            pos = 3 * side - x; // top side
        } else { // x === 0
            pos = 4 * side - y; // left side
        }
        s.push(pos);
    }
    s.sort((a, b) => a - b);
    const N = s.length;
    const dup = s.concat(s.map(v => v + P));

    function lowerBound(arr, target, start) {
        let l = start, r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] < target) l = m + 1;
            else r = m;
        }
        return l;
    }

    function feasible(d) {
        for (let i = 0; i < N; i++) {
            let cnt = 1;
            let lastPos = dup[i];
            let idx = i;
            while (cnt < k) {
                const target = lastPos + d;
                const j = lowerBound(dup, target, idx + 1);
                if (j >= i + N) break; // cannot wrap more than one full circle
                cnt++;
                lastPos = dup[j];
                idx = j;
            }
            if (cnt === k) {
                const span = lastPos - dup[i];
                if (span <= P - d) return true;
            }
        }
        return false;
    }

    let low = 0, high = Math.floor(P / 2);
    while (low < high) {
        const mid = Math.floor((low + high + 1) / 2);
        if (feasible(mid)) low = mid;
        else high = mid - 1;
    }
    return low;
}

function transformArrayByParity(nums) {
    var n = nums.length;
    var result = new Array(n);
    var zeroCount = 0;

    // count how many numbers are even (parity 0)
    for (var i = 0; i < n; i++) {
        if (nums[i] % 2 === 0) zeroCount++;
    }

    // first place all zeros, then the ones
    for (var i = 0; i < n; i++) {
        result[i] = i < zeroCount ? 0 : 1;
    }

    return result;
}

function countArrays(original, bounds) {
  let lo = -Infinity, hi = Infinity;
  for (let i = 0; i < original.length; i++) {
    const dLo = bounds[i][0] - original[i];
    const dHi = bounds[i][1] - original[i];
    lo = Math.max(lo, dLo);
    hi = Math.min(hi, dHi);
  }
  return Math.max(0, hi - lo + 1);
}

function checkDigitsEqual(s) {
    // convert string to array of numeric digits
    let digits = Array.from(s, ch => ch.charCodeAt(0) - 48);

    // repeatedly apply the operation until only two digits remain
    while (digits.length > 2) {
        const next = new Array(digits.length - 1);
        // MAIN LOGIC: each new digit is (a_i + a_{i+1}) mod 10
        for (let i = 0; i < digits.length - 1; i++) {
            next[i] = (digits[i] + digits[i + 1]) % 10;
        }
        digits = next;
    }

    // final comparison of the two remaining digits
    return digits[0] === digits[1];
}

function smallestGeneratedString(str1, str2) {
    const n = str1.length;
    const m = str2.length;
    const L = n + m - 1;
    const word = new Array(L).fill(null);
    // Apply 'T' constraints
    for (let i = 0; i < n; i++) {
        if (str1[i] === 'T') {
            for (let j = 0; j < m; j++) {
                const pos = i + j;
                const c = str2[j];
                if (word[pos] === null) {
                    word[pos] = c;
                } else if (word[pos] !== c) {
                    return "";
                }
            }
        }
    }
    // Satisfy 'F' constraints
    for (let i = 0; i < n; i++) {
        if (str1[i] === 'F') {
            let alreadyDiff = false;
            for (let j = 0; j < m; j++) {
                const pos = i + j;
                const c = str2[j];
                if (word[pos] !== null && word[pos] !== c) {
                    alreadyDiff = true;
                    break;
                }
            }
            if (alreadyDiff) continue;
            // Need to introduce a difference
            let changed = false;
            for (let j = m - 1; j >= 0; j--) {
                const pos = i + j;
                if (word[pos] === null) {
                    const c = str2[j];
                    word[pos] = c === 'a' ? 'b' : 'a';
                    changed = true;
                    break;
                }
            }
            if (!changed) return "";
        }
    }
    // Fill remaining positions with the smallest possible character
    for (let i = 0; i < L; i++) {
        if (word[i] === null) word[i] = 'a';
    }
    return word.join('');
}

function minimumRemovalCost(nums) {
  const n = nums.length;
  const maxPos = Array.from({ length: n }, () => Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    maxPos[i][i] = i;
    for (let j = i + 1; j < n; j++) {
      const prev = maxPos[i][j - 1];
      maxPos[i][j] = nums[j] > nums[prev] ? j : prev;
    }
  }

  const dp = Array.from({ length: n }, () => Array(n).fill(0));
  for (let len = 1; len <= n; len++) {
    for (let l = 0; l + len - 1 < n; l++) {
      const r = l + len - 1;
      if (l === r) {
        dp[l][r] = nums[l];
      } else {
        const m = maxPos[l][r];
        const left = m > l ? dp[l][m - 1] : 0;
        const right = m < r ? dp[m + 1][r] : 0;
        dp[l][r] = nums[m] + Math.min(left, right);
      }
    }
  }
  return dp[0][n - 1];
}

function permute(n, k) {
  k = BigInt(k);
  const fact = [1n];
  for (let i = 1; i <= n; i++) fact.push(fact[i-1] * BigInt(i));

  let oddCount = Math.ceil(n/2), evenCount = Math.floor(n/2);
  // total valid perms overall (for early exit if k too large)
  function totalCount() {
    if (n === 0) return 1n;
    if (n === 1) return 1n; // single element, trivially valid (no adjacent pair)
    if (Math.abs(oddCount - evenCount) > 1) return 0n;
    if (oddCount === evenCount) return 2n * fact[oddCount] * fact[evenCount];
    return fact[oddCount] * fact[evenCount];
  }
  if (k > totalCount()) return [];

  const used = new Array(n+1).fill(false);
  const result = [];
  let remOdd = oddCount, remEven = evenCount;
  let prevParity = null; // 0 = even, 1 = odd

  for (let pos = 0; pos < n; pos++) {
    let placed = false;
    for (let v = 1; v <= n; v++) {
      if (used[v]) continue;
      const parity = v % 2; // 1 odd, 0 even
      if (prevParity !== null && parity === prevParity) continue;
      const newRemOdd = remOdd - (parity === 1 ? 1 : 0);
      const newRemEven = remEven - (parity === 0 ? 1 : 0);
      const L = newRemOdd + newRemEven;
      let cnt;
      if (L === 0) {
        cnt = 1n;
      } else {
        const nextParityOdd = (parity === 0); // if current is even, next must be odd
        const neededOdd = nextParityOdd ? Math.ceil(L/2) : Math.floor(L/2);
        const neededEven = L - neededOdd;
        if (newRemOdd === neededOdd && newRemEven === neededEven) {
          cnt = fact[newRemOdd] * fact[newRemEven];
        } else {
          cnt = 0n;
        }
      }
      if (k <= cnt) {
        used[v] = true;
        result.push(v);
        remOdd = newRemOdd; remEven = newRemEven; prevParity = parity;
        placed = true;
        break;
      } else {
        k -= cnt;
      }
    }
    if (!placed) return []; // shouldn't happen if totalCount check passed
  }
  return result;
}

function longestPalindromicSubsequence(s, k) {
    const n = s.length;
    const memo = new Map();
    function cost(a, b) {
        const d = Math.abs(a.charCodeAt(0) - b.charCodeAt(0));
        return Math.min(d, 26 - d);
    }
    function dfs(i, j, budget) {
        if (i > j) return 0;
        if (i === j) return 1;
        const key = i + ',' + j + ',' + budget;
        if (memo.has(key)) return memo.get(key);
        let best = Math.max(dfs(i+1, j, budget), dfs(i, j-1, budget));
        const c = cost(s[i], s[j]);
        if (c <= budget) {
            best = Math.max(best, 2 + dfs(i+1, j-1, budget - c));
        }
        memo.set(key, best);
        return best;
    }
    return dfs(0, n-1, k);
}

function maxSumKSubarrays(nums, k, m) {
    const n = nums.length;
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) pref[i + 1] = pref[i] + nums[i];

    // dpPrev[i] = best sum using (j‑1) subarrays in first i elements
    let dpPrev = new Array(n + 1).fill(-Infinity);
    dpPrev[0] = 0; // zero subarrays give sum 0

    for (let sub = 1; sub <= k; sub++) {
        const dpCurr = new Array(n + 1).fill(-Infinity);
        let best = -Infinity; // best value of dpPrev[t] - pref[t] for t ≤ i‑m

        for (let i = m; i <= n; i++) {
            // incorporate position t = i‑m into best
            best = Math.max(best, dpPrev[i - m] - pref[i - m]);

            // either keep previous best without ending a subarray at i‑1,
            // or take a subarray that ends at i‑1 (length ≥ m)
            dpCurr[i] = Math.max(dpCurr[i - 1], best + pref[i]);
        }
        dpPrev = dpCurr; // move to next subarray count
    }
    return dpPrev[n];
}

function largestInteger(nums, k) {
  const n = nums.length;
  const values = [...new Set(nums)];
  let best = -1;
  for (const x of values) {
    let windowCount = 0;
    for (let s = 0; s + k <= n; s++) {
      let found = false;
      for (let i = s; i < s + k; i++) if (nums[i] === x) { found = true; break; }
      if (found) windowCount++;
      if (windowCount > 1) break;
    }
    if (windowCount === 1 && x > best) best = x;
  }
  return best;
}

function fruitsIntoBasketsII(fruits, baskets) {
    const fruitsSorted = [...fruits].sort((a, b) => a - b);
    const basketsSorted = [...baskets].sort((a, b) => a - b);
    let i = 0, j = 0, placed = 0;
    while (i < fruitsSorted.length && j < basketsSorted.length) {
        if (basketsSorted[j] > fruitsSorted[i]) { placed++; i++; j++; }
        else j++;
    }
    return fruits.length - placed;
}

function countUnplacedFruits(fruits, baskets) {
    const n = fruits.length;
    if (n === 0) return 0;
    const tree = new Array(4 * n).fill(0);
    function build(node, l, r) {
        if (l === r) { tree[node] = baskets[l]; return; }
        const mid = (l + r) >> 1;
        build(node * 2, l, mid); build(node * 2 + 1, mid + 1, r);
        tree[node] = Math.max(tree[node * 2], tree[node * 2 + 1]);
    }
    function update(node, l, r, idx) {
        if (l === r) { tree[node] = -1; return; }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx); else update(node * 2 + 1, mid + 1, r, idx);
        tree[node] = Math.max(tree[node * 2], tree[node * 2 + 1]);
    }
    function query(node, l, r, need) {
        if (tree[node] < need) return -1;
        if (l === r) return l;
        const mid = (l + r) >> 1;
        const left = query(node * 2, l, mid, need);
        if (left !== -1) return left;
        return query(node * 2 + 1, mid + 1, r, need);
    }
    build(1, 0, n - 1);
    let unplaced = 0;
    for (let i = 0; i < n; i++) {
        const idx = query(1, 0, n - 1, fruits[i]);
        if (idx === -1) unplaced++;
        else update(1, 0, n - 1, idx);
    }
    return unplaced;
}

function chooseKElementsWithMaximumSum(nums1, nums2, k) {
    const n = nums1.length;
    if (n === 0 || k <= 0) return new Array(n).fill(0);
    const order = Array.from({length: n}, (_, i) => i).sort((a, b) => nums1[a] - nums1[b]);
    const answer = new Array(n).fill(0);

    class MinHeap {
        constructor() { this.a = []; }
        push(v) { this.a.push(v); let i = this.a.length - 1; while (i > 0) { const p = (i-1)>>1; if (this.a[p] > this.a[i]) { [this.a[p],this.a[i]]=[this.a[i],this.a[p]]; i=p; } else break; } }
        replace(v) { this.a[0] = v; let i = 0; while (true) { let l=2*i+1,r=2*i+2,s=i; if (l<this.a.length && this.a[l]<this.a[s]) s=l; if (r<this.a.length && this.a[r]<this.a[s]) s=r; if (s===i) break; [this.a[i],this.a[s]]=[this.a[s],this.a[i]]; i=s; } }
        get length() { return this.a.length; }
        get top() { return this.a[0]; }
    }
    const heap = new MinHeap();
    let curSum = 0;
    let i = 0;
    while (i < n) {
        let j = i;
        const curVal = nums1[order[i]];
        while (j < n && nums1[order[j]] === curVal) j++;
        for (let p = i; p < j; p++) answer[order[p]] = curSum;
        for (let p = i; p < j; p++) {
            const v = nums2[order[p]];
            if (heap.length < k) { heap.push(v); curSum += v; }
            else if (v > heap.top) { curSum += v - heap.top; heap.replace(v); }
        }
        i = j;
    }
    return answer;
}

/**
 * @param {number} n
 * @param {number[][]} conflictingPairs
 * @return {number}
 */
function maxSubarrays(n, conflictingPairs) {
    // Helper to compute valid subarrays count given a set of pairs (array of [a,b])
    function countValid(pairs) {
        const ending = Array.from({ length: n + 1 }, () => []);
        for (let [x, y] of pairs) {
            let a = x, b = y;
            if (a > b) { const tmp = a; a = b; b = tmp; }
            // store left endpoint for each right endpoint
            ending[b].push(a);
        }
        let left = 1;
        let total = 0;
        for (let r = 1; r <= n; r++) {
            const list = ending[r];
            for (let i = 0; i < list.length; i++) {
                const a = list[i];
                if (a + 1 > left) left = a + 1;
            }
            if (left <= r) {
                total += r - left + 1;
            }
        }
        return total;
    }

    let best = 0;
    const m = conflictingPairs.length;

    // Brute-force: try removing each pair one by one
    for (let removeIdx = 0; removeIdx < m; removeIdx++) {
        const remaining = [];
        for (let i = 0; i < m; i++) {
            if (i !== removeIdx) remaining.push(conflictingPairs[i]);
        }
        const cur = countValid(remaining);
        if (cur > best) best = cur;
    }

    return best;
}
// TIME: O(m * (n + m)) SPACE: O(n + m)

var longestSpecialPath = function(edges, nums) {
    const n = nums.length;
    const adj = Array.from({length:n}, () => []);
    for (const [u,v,w] of edges) { adj[u].push([v,w]); adj[v].push([u,w]); }
    const maxVal = Math.max(...nums);
    const last = new Array(maxVal+1).fill(-1);
    const path = [];
    const pref = [0];
    let left = 0;
    let bestSum = 0, bestLen = 0;
    const stack = [[0,-1,0,0,-1,0]];
    while (stack.length) {
        const top = stack.pop();
        const node=top[0], parent=top[1], weight=top[2], state=top[3], prevLastIn=top[4], prevLeftIn=top[5];
        if (state === 0) {
            const val = nums[node];
            const prevLast = last[val];
            const prevLeft = left;
            const idx = path.length;
            path.push(node);
            pref.push(pref[pref.length-1] + weight);
            left = Math.max(left, prevLast+1);
            last[val] = idx;
            const curSum = pref[pref.length-1] - (left>0 ? pref[left] : 0);
            const curLen = idx - left + 1;
            if (curSum > bestSum || (curSum === bestSum && curLen > bestLen)) {
                bestSum = curSum; bestLen = curLen;
            }
            stack.push([node, parent, weight, 1, prevLast, prevLeft]);
            for (const [nei, w] of adj[node]) {
                if (nei === parent) continue;
                stack.push([nei, node, w, 0, -1, 0]);
            }
        } else {
            const val = nums[node];
            last[val] = prevLastIn;
            left = prevLeftIn;
            path.pop();
            pref.pop();
        }
    }
    return [bestSum, bestLen];
};

function countEvenNumbers(digits) {
    const seen = new Set();                 // store distinct numbers
    const n = digits.length;

    for (let i = 0; i < n; i++) {           // choose hundreds digit
        if (digits[i] === 0) continue;      // no leading zero

        for (let j = 0; j < n; j++) {       // choose tens digit
            if (j === i) continue;

            for (let k = 0; k < n; k++) {   // choose units digit
                if (k === i || k === j) continue;
                if (digits[k] % 2 !== 0) continue; // must be even

                const num = digits[i] * 100 + digits[j] * 10 + digits[k];
                seen.add(num);               // deduplicate automatically
            }
        }
    }

    return seen.size;
}

class Spreadsheet {
    constructor(rows) {
        this.rows = rows;
        this.cells = new Map();
    }
    setCell(cell, value) { this.cells.set(cell, value); }
    resetCell(cell) { this.cells.delete(cell); }
    getValue(formula) {
        if (formula[0] === '=') {
            const parts = formula.slice(1).split('+');
            let total = 0;
            for (const p of parts) {
                if (/^[A-Z][0-9]+$/.test(p)) total += this.cells.get(p) || 0;
                else total += parseInt(p, 10);
            }
            return total;
        }
        return this.cells.get(formula) || 0;
    }
}

function solveQueries(nums, queries) {
    const n = nums.length;
    const positions = new Map();
    for (let i = 0; i < n; i++) {
        if (!positions.has(nums[i])) positions.set(nums[i], []);
        positions.get(nums[i]).push(i);
    }
    return queries.map(q => {
        const arr = positions.get(nums[q]);
        if (arr.length <= 1) return -1;
        let best = Infinity;
        for (const p of arr) {
            if (p === q) continue;
            const d = Math.abs(p - q);
            best = Math.min(best, Math.min(d, n - d));
        }
        return best;
    });
}

function minimumQueriesToZeroArray(nums, queries) {
    const n = nums.length;
    const cur = nums.slice();
    const allZero = () => cur.every(v => v === 0);
    if (allZero()) return 0;
    for (let i = 0; i < queries.length; i++) {
        const [l, r, val] = queries[i];
        for (let j = l; j <= r; j++) {
            cur[j] = Math.max(0, cur[j] - val);
        }
        if (allZero()) return i + 1;
    }
    return -1;
}

function longestCommonPrefix(words, k) {
    const n = words.length;
    if (n - 1 < k) {
        return new Array(n).fill(0);
    }

    // Build trie
    const nodes = [{ next: new Array(26).fill(-1), cnt: 0, depth: 0 }]; // root at index 0
    let maxWordLen = 0;

    for (const w of words) {
        let cur = 0;
        let d = 0;
        for (const ch of w) {
            const idx = ch.charCodeAt(0) - 97;
            if (nodes[cur].next[idx] === -1) {
                nodes.push({ next: new Array(26).fill(-1), cnt: 0, depth: d + 1 });
                nodes[cur].next[idx] = nodes.length - 1;
            }
            cur = nodes[cur].next[idx];
            d++;
            nodes[cur].cnt++; // this node represents a prefix of length d
        }
        if (w.length > maxWordLen) maxWordLen = w.length;
    }

    // goodCount[depth] = number of nodes at that depth with cnt >= k
    const goodCount = new Array(maxWordLen + 1).fill(0);
    let globalMaxDepth = 0;
    for (let i = 1; i < nodes.length; i++) { // skip root (depth 0)
        const node = nodes[i];
        if (node.cnt >= k) {
            goodCount[node.depth]++;
            if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
        }
    }

    const answer = new Array(n).fill(0);

    // Helper to possibly decrease globalMaxDepth
    const shrinkMaxDepth = () => {
        while (globalMaxDepth > 0 && goodCount[globalMaxDepth] === 0) {
            globalMaxDepth--;
        }
    };

    for (let i = 0; i < n; i++) {
        const w = words[i];
        // Decrement counts along the path of words[i]
        let cur = 0;
        for (const ch of w) {
            const idx = ch.charCodeAt(0) - 97;
            cur = nodes[cur].next[idx];
            const node = nodes[cur];
            if (node.cnt === k) { // will drop below k
                goodCount[node.depth]--;
                if (node.depth === globalMaxDepth && goodCount[node.depth] === 0) {
                    shrinkMaxDepth();
                }
            }
            node.cnt--;
        }

        // After removal, answer is current globalMaxDepth
        answer[i] = globalMaxDepth;

        // Restore counts
        cur = 0;
        for (const ch of w) {
            const idx = ch.charCodeAt(0) - 97;
            cur = nodes[cur].next[idx];
            const node = nodes[cur];
            node.cnt++;
            if (node.cnt === k) { // just reached k again
                goodCount[node.depth]++;
                if (node.depth > globalMaxDepth) globalMaxDepth = node.depth;
            }
        }
    }

    return answer;
}

function numberOfBeautifulIntegers(l, r) {
  let count = 0;
  for (let x = l; x <= r; x++) {
    let prod = 1, sum = 0, t = x;
    while (t > 0) { const d = t % 10; prod *= d; sum += d; t = Math.floor(t / 10); }
    if (prod % sum === 0) count++;
  }
  return count;
}

function minBrewTime(skill, mana) {
    const n = skill.length;
    const m = mana.length;
    let done = new Array(n).fill(0);

    for (let j = 0; j < m; j++) {
        const idealStart = new Array(n).fill(0);
        for (let i = 1; i < n; i++) {
            idealStart[i] = idealStart[i - 1] + skill[i - 1] * mana[j];
        }
        let shift = 0;
        for (let i = 0; i < n; i++) {
            shift = Math.max(shift, done[i] - idealStart[i]);
        }
        const finish = new Array(n);
        for (let i = 0; i < n; i++) {
            const start = idealStart[i] + shift;
            finish[i] = start + skill[i] * mana[j];
        }
        done = finish;
    }
    return done[n - 1];
}

function maxUniqueSubarraySum(nums) {
    let left = 0;
    let curSum = 0;
    let best = -Infinity;
    const freq = new Map(); // value -> count inside window

    for (let right = 0; right < nums.length; right++) {
        const v = nums[right];

        // MAIN LOGIC: shrink window while v already appears → keep uniqueness
        while (freq.get(v) > 0) {
            const leftVal = nums[left];
            freq.set(leftVal, freq.get(leftVal) - 1);
            curSum -= leftVal;
            left++;
        }

        freq.set(v, (freq.get(v) || 0) + 1);
        curSum += v;
        if (curSum > best) best = curSum;
    }

    return best;
}

function calculateReverseDegree(s) {
    let total = 0;
    for (let i = 0; i < s.length; i++) {
        const revValue = 122 - s.charCodeAt(i) + 1; // 'z' = 122
        total += (i + 1) * revValue;
    }
    return total;
}

function maxContainers(n, w, maxWeight) {
    // maximum containers limited by deck size and weight capacity
    const deckCapacity = n * n;
    const weightLimit = Math.floor(maxWeight / w);
    return Math.min(deckCapacity, weightLimit);
}

function numberOfComponents(properties, k) {
    const n = properties.length;
    if (n === 0) return 0;
    const sets = properties.map(p => new Set(p));
    const parent = Array.from({length: n}, (_, i) => i);
    const rank = new Array(n).fill(0);

    function find(x) {
        while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; }
        return x;
    }
    function unite(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra;
        if (rank[ra] === rank[rb]) rank[ra]++;
    }

    for (let i = 0; i < n; i++) {
        for (let j = i+1; j < n; j++) {
            let a = sets[i], b = sets[j];
            let small, large;
            if (a.size > b.size) { small = b; large = a; } else { small = a; large = b; }
            let common = 0;
            for (const val of small) {
                if (large.has(val)) {
                    common++;
                    if (common >= k) break;
                }
            }
            if (common >= k) unite(i, j);
        }
    }
    const roots = new Set();
    for (let i = 0; i < n; i++) roots.add(find(i));
    return roots.size;
}

function minimumOperations(queries) {
    let total = 0;
    for (let i = 0; i < queries.length; i++) {
        const [l, r] = queries[i];
        total += r - l;               // each query contributes (r - l) operations
    }
    return total;
}

function maxActiveSectionsSub(s) {
    const n = s.length;
    let totalOnes = 0;
    let pre = -Infinity;
    let mx = 0;
    let i = 0;
    while (i < n) {
        let j = i + 1;
        while (j < n && s[j] === s[i]) j++;
        const cur = j - i;
        if (s[i] === '1') {
            totalOnes += cur;
        } else {
            mx = Math.max(mx, pre + cur);
            pre = cur;
        }
        i = j;
    }
    return totalOnes + mx;
}

function maxActiveSectionQueries(s, queries) {
    const answer = [];
    for (const [l, r] of queries) {
        const sub = s.slice(l, r + 1);
        answer.push(maxActiveSectionsSub(sub));
    }
    return answer;
}

