    for (let i = 0; i <= n; i++) {
        for (let j = i; j <= n; j++) {
            const subS = s.slice(i, j);
            for (let p = 0; p <= m; p++) {
                for (let q = p; q <= m; q++) {
                    const subT = t.slice(p, q);
                    const combined = subS + subT;
                    if (combined.length > maxLen && isPal(combined)) {
