    for (let i = 1; i < n; i++) ans[i] = Math.min(ans[i-1], cost[i]);
    return ans;
}

function minOperations(nums, x, k) {
    const n = nums.length;
    const cost = new Array(n - x + 1).fill(0);
    for (let i = 0; i <= n - x; i++) {
        const window = nums.slice(i, i+x).slice().sort((a,b) => a-b);
        const median = window[Math.floor(window.length/2)];
        cost[i] = window.reduce((s,v) => s + Math.abs(v - median), 0);
    }
    const INF = Infinity;
    const m = n - x + 1;
    const dp = Array.from({length: n+1}, () => new Array(k+1).fill(INF));
    dp[0][0] = 0;
    for (let pos = 0; pos < n; pos++) {
        for (let t = 0; t <= k; t++) {
            if (dp[pos][t] === INF) continue;
            if (dp[pos][t] < dp[pos+1][t]) dp[pos+1][t] = dp[pos][t];
            if (pos < m && t < k) {
                const npos = pos + x;
                const ncost = dp[pos][t] + cost[pos];
                if (ncost < dp[npos][t+1]) dp[npos][t+1] = ncost;
            }
        }
    }
    return dp[n][k];
}

function minimumCost(nums, cost, k) {
    const n = nums.length;
    const prefixNums = new Array(n + 1).fill(0);
    const prefixCost = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) {
        prefixNums[i + 1] = prefixNums[i] + nums[i];
        prefixCost[i + 1] = prefixCost[i] + cost[i];
    }
    // dp[i] = min cost to divide nums[i..n-1] into subarrays
    const dp = new Array(n + 1).fill(Infinity);
    dp[n] = 0;
    for (let i = n - 1; i >= 0; i--) {
        for (let j = i; j < n; j++) {
            // k*(subarray index) summed across all subarrays telescopes into k times the
            // remaining total cost-sum whenever a new subarray starts, avoiding explicit index tracking
            const val = prefixNums[j + 1] * (prefixCost[j + 1] - prefixCost[i]) +
                        k * (prefixCost[n] - prefixCost[i]) + dp[j + 1];
            dp[i] = Math.min(dp[i], val);
        }
    }
    return dp[0];
}

function maximumProductOfSubsequencesWithAnAlternatingSumEqualToK(nums, k, limit) {
    let dpEven = new Map([[0, 1]]);
    let dpOdd = new Map();

    for (const val of nums) {
        const nextEven = new Map(dpEven);
        const nextOdd = new Map(dpOdd);

        if (Math.abs(val) <= limit) {
            if (!nextOdd.has(val) || val > nextOdd.get(val)) nextOdd.set(val, val);
        }

        for (const [s, prod] of dpEven) {
            if (val === 0) {
                const newSum = s;
                if (!nextOdd.has(newSum) || 0 > nextOdd.get(newSum)) nextOdd.set(newSum, 0);
                continue;
            }
            if (Math.abs(prod) > Math.floor(limit / Math.abs(val))) continue;
            const newProd = prod * val;
            const newSum = s + val;
            if (!nextOdd.has(newSum) || newProd > nextOdd.get(newSum)) nextOdd.set(newSum, newProd);
        }

        for (const [s, prod] of dpOdd) {
            if (val === 0) {
                const newSum = s;
                if (!nextEven.has(newSum) || 0 > nextEven.get(newSum)) nextEven.set(newSum, 0);
                continue;
            }
            if (Math.abs(prod) > Math.floor(limit / Math.abs(val))) continue;
            const newProd = prod * val;
            const newSum = s - val;
            if (!nextEven.has(newSum) || newProd > nextEven.get(newSum)) nextEven.set(newSum, newProd);
        }

        dpEven = nextEven; dpOdd = nextOdd;
    }

    let ans = -1;
    if (dpEven.has(k)) ans = Math.max(ans, dpEven.get(k));
    if (dpOdd.has(k)) ans = Math.max(ans, dpOdd.get(k));
    return ans;
}

function minOperations(nums) {
    if (nums.length === 0) return 0;

    const tails = [];                     // stores minimal possible tails

    for (let x of nums) {
        // binary search: first index with tails[idx] > x
        let lo = 0, hi = tails.length;
        while (lo < hi) {
            const mid = (lo + hi) >>> 1;
            if (tails[mid] <= x) lo = mid + 1;
            else hi = mid;
        }
        if (lo === tails.length) {
            tails.push(x);                 // extend longest subsequence
        } else {
            tails[lo] = x;                 // improve existing tail
        }
    }
    return nums.length - tails.length;    // deletions needed
}

