function Router(memoryLimit) {
    const limit = memoryLimit;
    const queue = [];
    let head = 0;
    const packetSet = new Set(); // stores "src,dst,ts"
    const destMap = new Map(); // dst -> {arr: [], head: 0}
    function evictOldest() {
        if (queue.length - head === 0) return;
        const pkt = queue[head];
        head++;
        const key = `${pkt.src},${pkt.dst},${pkt.ts}`;
        packetSet.delete(key);
        const entry = destMap.get(pkt.dst);
        if (entry) {
            entry.head++;
            if (entry.head >= entry.arr.length) {
                destMap.delete(pkt.dst);
            }
        }
    }
    function addPacket(source, destination, timestamp) {
        const key = `${source},${destination},${timestamp}`;
        if (packetSet.has(key)) return false;
        if (queue.length - head >= limit) {
            evictOldest();
        }
        queue.push({ src: source, dst: destination, ts: timestamp });
        packetSet.add(key);
        let entry = destMap.get(destination);
        if (!entry) {
            entry = { arr: [], head: 0 };
            destMap.set(destination, entry);
        }
        entry.arr.push(timestamp);
        return true;
    }
    function forwardPacket() {
        if (queue.length - head === 0) return [];
        const pkt = queue[head];
        evictOldest();
        return [pkt.src, pkt.dst, pkt.ts];
    }
    function getCount(destination, startTime, endTime) {
        const entry = destMap.get(destination);
        if (!entry) return 0;
        const arr = entry.arr;
        const h = entry.head;
        // first index >= startTime
        let l = h, r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] < startTime) l = m + 1;
            else r = m;
        }
        const leftIdx = l;
        // first index > endTime
        l = h; r = arr.length;
        while (l < r) {
            const m = (l + r) >> 1;
            if (arr[m] <= endTime) l = m + 1;
            else r = m;
        }
        const rightIdx = l;
        return rightIdx - leftIdx;
    }
    return { addPacket, forwardPacket, getCount };
}
// TIME: addPacket O(1) amortized, forwardPacket O(1), getCount O(log k) where k is packets for destination
// SPACE: O(N) where N is current number of stored packets.

var uniqueXorTriplets = function(nums) {
    const LIMIT = 2048;
    const present = new Array(LIMIT).fill(0);
    for (const x of nums) if (x>=0 && x<LIMIT) present[x]=1;
    const pairXor = new Array(LIMIT).fill(0);
    for (let a=0;a<LIMIT;a++) {
        if (present[a]) {
            for (let b=0;b<LIMIT;b++) {
                if (present[b]) pairXor[a^b] = 1;
            }
        }
    }
    const result = new Array(LIMIT).fill(0);
    for (let v=0;v<LIMIT;v++) if (present[v]) result[v]=1;
    for (let p=0;p<LIMIT;p++) {
        if (pairXor[p]) {
            for (let c=0;c<LIMIT;c++) {
                if (present[c]) result[p^c]=1;
            }
        }
    }
    return result.reduce((a,b)=>a+b,0);
};

function smallestPalindromicPermutation(s) {
    // 1. frequency table (ASCII range is enough for typical inputs)
    const freq = new Array(256).fill(0);
    for (let i = 0; i < s.length; ++i) {
        freq[s.charCodeAt(i)]++;
    }

    let leftHalf = '';
    let middle = '';

    // 2. build the left half in lexicographic order
    for (let code = 0; code < 256; ++code) {
        const count = freq[code];
        if (count === 0) continue;

        const half = count >> 1;                 // floor(count / 2)
        if (half > 0) leftHalf += String.fromCharCode(code).repeat(half);

        if (count & 1) middle = String.fromCharCode(code); // odd count → middle
    }

    // 3. right half is the reverse of the left half
    const rightHalf = leftHalf.split('').reverse().join('');

    // 4. combine parts
    return leftHalf + middle + rightHalf;
}

function minOperations(nums, k) {
    let total = 0;
    for (let i = 0; i < nums.length; i++) { total += nums[i]; }
    return total % k; // the only allowed operation decreases an element by 1, so we can only round DOWN to the nearest multiple of k
