function findClosestPerson(x, y, z) {
    const dist1 = Math.abs(x - z);   // distance from Person 1 to Person 3
    const dist2 = Math.abs(y - z);   // distance from Person 2 to Person 3

    // compare distances to decide who reaches Person 3 first
    if (dist1 < dist2) return 1;
    if (dist2 < dist1) return 2;
    return 0; // equal distance
}

class Fenwick {
    constructor(n) { this.n = n; this.bit = new Array(n+2).fill(0); }
    add(idx, val) { let i = idx; while (i <= this.n) { this.bit[i] += val; i += i & (-i); } }
    rangeAdd(l, r, val) { this.add(l, val); this.add(r+1, -val); }
    pointQuery(idx) { let res = 0, i = idx; while (i > 0) { res += this.bit[i]; i -= i & (-i); } return res; }
}

function shortestPathQueries(n, edges, queries) {
    const adj = Array.from({length: n+1}, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }
    const parent = new Array(n+1).fill(0);
    const tin = new Array(n+1).fill(0);
    const tout = new Array(n+1).fill(0);
    const dist = new Array(n+1).fill(0);
    const edgeWeight = new Array(n+1).fill(0);

    let timer = 0;
    const stack = [[1, 0]];
    parent[1] = 0;
    while (stack.length) {
        const [v, state] = stack.pop();
        if (state === 0) {
            timer += 1;
            tin[v] = timer;
            stack.push([v, 1]);
            for (const [to, w] of adj[v]) {
                if (to === parent[v]) continue;
                parent[to] = v;
                edgeWeight[to] = w;
                dist[to] = dist[v] + w;
                stack.push([to, 0]);
            }
        } else {
            tout[v] = timer;
        }
    }

    const fenwick = new Fenwick(n);
    const answer = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const u = q[1], v = q[2], wnew = q[3];
            const child = parent[u] === v ? u : v;
            const delta = wnew - edgeWeight[child];
            edgeWeight[child] = wnew;
            fenwick.rangeAdd(tin[child], tout[child], delta);
        } else {
            const x = q[1];
            const cur = dist[x] + fenwick.pointQuery(tin[x]);
            answer.push(cur);
        }
    }
    return answer;
}

function smallestPalindromicRearrangementII(s, k) {
    const INF = 2000000000000000000n;
    const combCapped = (n, kk) => {
        if (kk < 0 || kk > n) return 0n;
        if (kk > n - kk) kk = n - kk;
        let res = 1n;
        for (let i = 1; i <= kk; i++) {
            res = res * BigInt(n - kk + i) / BigInt(i);
            if (res >= INF) return INF;
        }
        return res;
    };
    const mulCapped = (a, b) => {
        if (a >= INF || b >= INF) return INF;
        if (b !== 0n && a > INF / b) return INF;
        return a * b;
    };

    let kBig = BigInt(k);
    if (kBig <= 0n) return "";
    const freq = new Array(26).fill(0);
    for (const ch of s) freq[ch.charCodeAt(0) - 97]++;

    const middle = [];
    const halfCnt = new Array(26).fill(0);
    for (let i = 0; i < 26; i++) {
        if (freq[i] % 2 === 1) middle.push(String.fromCharCode(97 + i));
        halfCnt[i] = Math.floor(freq[i] / 2);
    }

    const halfLen = halfCnt.reduce((a, b) => a + b, 0);

    let totalPerms = 1n;
    let remaining = halfLen;
    for (const c of halfCnt) {
        if (c) {
            totalPerms = mulCapped(totalPerms, combCapped(remaining, c));
            if (totalPerms >= INF) { totalPerms = INF; break; }
            remaining -= c;
        }
    }

    if (kBig > totalPerms) return "";

    const left = [];
    for (let pos = 0; pos < halfLen; pos++) {
        const N = halfLen - pos;
        for (let i = 0; i < 26; i++) {
            const cntI = halfCnt[i];
            if (cntI === 0) continue;
            const cntPerm = totalPerms * BigInt(cntI) / BigInt(N);
            if (kBig > cntPerm) { kBig -= cntPerm; continue; }
            left.push(String.fromCharCode(97 + i));
            halfCnt[i]--;
            totalPerms = cntPerm;
            break;
        }
    }

    const right = [...left].reverse();
    return left.join('') + middle.join('') + right.join('');
}

function maxSizeNonDecreasing(nums) {
    const stack = [];
