function resultArray(nums, k, queries) {
    const n = nums.length;
    const size = 4 * n;
    // Each segment tree node stores:
    //  cnt[v] = number of nonempty prefix positions within the segment whose PURE
    //           product (assuming the segment starts fresh with a running product of 1)
    //           equals v (mod k).
    //  full   = product of the entire segment, mod k.
    const cntTree = new Array(size);
    const fullTree = new Array(size);

    function mergeInto(node, left, right) {
        const lc = cntTree[left], rc = cntTree[right];
        const lf = fullTree[left];
        const merged = lc.slice();
        for (let w = 0; w < k; w++) {
            if (rc[w] === 0) continue;
            const x = (lf * w) % k;
            merged[x] += rc[w];
        }
        cntTree[node] = merged;
        fullTree[node] = (lf * fullTree[right]) % k;
    }

    function build(node, l, r) {
        if (l === r) {
            const val = ((nums[l] % k) + k) % k;
            const arr = new Array(k).fill(0);
            arr[val] = 1;
            cntTree[node] = arr;
            fullTree[node] = val;
        } else {
            const mid = (l + r) >> 1;
            build(node * 2, l, mid);
            build(node * 2 + 1, mid + 1, r);
            mergeInto(node, node * 2, node * 2 + 1);
        }
    }

    function update(node, l, r, idx, newVal) {
        if (l === r) {
            const arr = new Array(k).fill(0);
            arr[newVal] = 1;
            cntTree[node] = arr;
            fullTree[node] = newVal;
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx, newVal);
        else update(node * 2 + 1, mid + 1, r, idx, newVal);
        mergeInto(node, node * 2, node * 2 + 1);
    }

    // Returns {cnt, full} for the query range [ql, qr], combining left-to-right.
    function query(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) return { cnt: cntTree[node], full: fullTree[node] };
        const mid = (l + r) >> 1;
        if (qr <= mid) return query(node * 2, l, mid, ql, qr);
        if (ql > mid) return query(node * 2 + 1, mid + 1, r, ql, qr);
        const leftRes = query(node * 2, l, mid, ql, qr);
        const rightRes = query(node * 2 + 1, mid + 1, r, ql, qr);
        const merged = leftRes.cnt.slice();
        for (let w = 0; w < k; w++) {
            if (rightRes.cnt[w] === 0) continue;
            const x = (leftRes.full * w) % k;
            merged[x] += rightRes.cnt[w];
        }
        return { cnt: merged, full: (leftRes.full * rightRes.full) % k };
    }

    build(1, 0, n - 1);

    const results = [];
    for (const [index, value, start, x] of queries) {
        const v = ((value % k) + k) % k;
        update(1, 0, n - 1, index, v);
        const res = query(1, 0, n - 1, start, n - 1);
        results.push(res.cnt[x]);
    }
    return results;
}

const MOD = 1000000007;

function decimalToBase(s, b) {
    if (s === "0") return [0];
    let cur = s;
    const rev = [];
    while (!(cur.length === 1 && cur[0] === '0')) {
        let nextChars = [];
        let carry = 0;
        for (const ch of cur) {
            const num = carry * 10 + (ch.charCodeAt(0) - 48);
            const q = Math.floor(num / b);
            carry = num % b;
            if (nextChars.length || q !== 0) nextChars.push(String.fromCharCode(48 + q));
        }
        rev.push(carry);
        cur = nextChars.length ? nextChars.join('') : "0";
    }
    rev.reverse();
    return rev;
}

function decrementString(s) {
    const res = s.split('');
    let i = res.length - 1;
    while (i >= 0 && res[i] === '0') { res[i] = '9'; i--; }
    if (i >= 0) res[i] = String.fromCharCode(res[i].charCodeAt(0) - 1);
    let pos = 0;
    while (pos < res.length && res[pos] === '0') pos++;
    if (pos === res.length) return "0";
    return res.slice(pos).join('');
}

function countUpTo(digits, b) {
    const n = digits.length;
    const memo = Array.from({length: n}, () => Array.from({length: b}, () => [-1, -1]));
    function dfs(idx, prev, tight, started) {
        if (idx === n) return 1;
        const st = started ? 1 : 0;
        if (!tight && memo[idx][prev][st] !== -1) return memo[idx][prev][st];
        const limit = tight ? digits[idx] : b - 1;
        let res = 0;
        for (let d = 0; d <= limit; d++) {
            const nstarted = started || d !== 0;
            const ntight = tight && (d === limit);
            if (!nstarted) {
                res += dfs(idx + 1, 0, ntight, false);
            } else {
                if (!started) {
                    res += dfs(idx + 1, d, ntight, true);
                } else {
                    if (d >= prev) res += dfs(idx + 1, d, ntight, true);
                }
            }
            if (res >= MOD) res -= MOD;
        }
        if (!tight) memo[idx][prev][st] = res % MOD;
        return res % MOD;
    }
    return dfs(0, 0, true, false) % MOD;
}

function countNumbersNonDecreasing(l, r, b) {
    const rDigits = decimalToBase(r, b);
