    if (l !== "0") {
        const lMinus = decrementString(l);
        const lDigits = decimalToBase(lMinus, b);
        cntLMinus = countUpTo(lDigits, b);
    }
    let ans = (cntR - cntLMinus) % MOD;
    if (ans < 0) ans += MOD;
    return ans;
}

