        let length = 0, i = 1;
        while (i < nP) {
            if (pat[i] === pat[length]) { length++; lps[i] = length; i++; }
            else { if (length !== 0) length = lps[length - 1]; else { lps[i] = 0; i++; } }
        }
        const res = [];
        i = 0; let j = 0;
        while (i < nT) {
            if (text[i] === pat[j]) {
                i++; j++;
                if (j === nP) { res.push(i - j); j = lps[j - 1]; }
            } else {
                if (j !== 0) j = lps[j - 1]; else i++;
            }
        }
        return res;
    };

    const rowOcc = kmpOccurrences(rowStr, pattern);
    const colOcc = kmpOccurrences(colStr, pattern);

    const diffHor = new Array(M + 1).fill(0);
    for (const p of rowOcc) if (p + L <= M) { diffHor[p]++; diffHor[p + L]--; }
    const diffVer = new Array(M + 1).fill(0);
    for (const q of colOcc) if (q + L <= M) { diffVer[q]++; diffVer[q + L]--; }

    const horCov = new Array(M).fill(false);
    let cur = 0;
    for (let i = 0; i < M; i++) { cur += diffHor[i]; horCov[i] = cur > 0; }
    const verCov = new Array(M).fill(false);
    cur = 0;
    for (let i = 0; i < M; i++) { cur += diffVer[i]; verCov[i] = cur > 0; }

    let count = 0;
    for (let i = 0; i < m; i++) {
        const baseRow = i * n;
        for (let j = 0; j < n; j++) {
            const idxRow = baseRow + j;
            const idxCol = j * m + i;
            if (horCov[idxRow] && verCov[idxCol]) count++;
        }
    }
    return count;
}

function calculateScore(instructions, values) {
    const n = instructions.length;
    const visited = new Array(n).fill(false);
    let i = 0, score = 0;
    while (i >= 0 && i < n && !visited[i]) {
        visited[i] = true;
        if (instructions[i] === 'add') { score += values[i]; i++; }
        else { i += values[i]; }
    }
    return score;
}

function findXValue(nums, k) {
    // result[x] = number of sub‑arrays with product % k == x
    const result = new Array(k).fill(0);

    // dp[r] = number of sub‑arrays ending at previous index with remainder r
    let dp = new Array(k).fill(0);

    for (let idx = 0; idx < nums.length; idx++) {
        const v = nums[idx];
        const newDp = new Array(k).fill(0);

        // start a new sub‑array consisting only of v
        const singleRem = v % k;
        newDp[singleRem] += 1;

        // extend all sub‑arrays that ended at the previous position
        for (let r = 0; r < k; r++) {
            const cnt = dp[r];
            if (cnt === 0) continue;               // skip empty entries
            const newRem = (r * v) % k;
            newDp[newRem] += cnt;
        }

        // add the newly formed sub‑arrays to the global answer
        for (let r = 0; r < k; r++) {
            if (newDp[r] !== 0) result[r] += newDp[r];
        }

        dp = newDp; // prepare for the next iteration
    }

    return result;
}

function pathExistenceQueries(n, nums, maxDiff, queries) {
    // ---------- Union‑Find ----------
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }

    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return;
        if (rank[ra] < rank[rb]) parent[ra] = rb;
        else if (rank[ra] > rank[rb]) parent[rb] = ra;
        else {
            parent[rb] = ra;
            rank[ra]++;
        }
    }

    // main logic: connect consecutive nodes whose value difference ≤ maxDiff
    for (let i = 1; i < n; i++) {
        if (nums[i] - nums[i - 1] <= maxDiff) {
            union(i, i - 1);
        }
    }

    const answer = new Array(queries.length);
    // main logic: answer each query by component comparison
    for (let i = 0; i < queries.length; i++) {
        const [u, v] = queries[i];
        answer[i] = find(u) === find(v);
    }
    return answer;
}

function mostCommonResponse(responses) {
    const countMap = new Map();               // map: response -> total occurrences

    for (const day of responses) {
        const unique = new Set(day);           // remove duplicates within the same day
        for (const resp of unique) {
            countMap.set(resp, (countMap.get(resp) || 0) + 1);
        }
    }

    let best = "";
    let bestCount = -1;
    for (const [resp, cnt] of countMap) {
        if (cnt > bestCount || (cnt === bestCount && resp < best)) {
            best = resp;
            bestCount = cnt;
        }
    }
    return best;
}

function smallestDivisiblePermutation(nums, k) {
    const n = nums.length;
    const fullMask = (1 << n) - 1;
    const lengths = new Array(n).fill(0);
    const pow10mod = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        let l = 0, tmp = nums[i];
        while (tmp > 0) { l++; tmp = Math.floor(tmp / 10); }
        lengths[i] = l;
        let p = 1 % k;
        for (let j = 0; j < l; j++) p = (p * 10) % k;
        pow10mod[i] = p;
    }
    const memo = Array.from({length: 1 << n}, () => new Array(k).fill(-1));
    function can(mask, rem) {
        if (mask === fullMask) return rem === 0 ? 1 : 0;
        if (memo[mask][rem] !== -1) return memo[mask][rem];
        let res = 0;
        for (let i = 0; i < n; i++) {
            if (mask & (1 << i)) continue;
            const newRem = ((rem * pow10mod[i]) % k + nums[i] % k) % k;
            if (can(mask | (1 << i), newRem)) { res = 1; break; }
        }
        memo[mask][rem] = res;
        return res;
    }
    if (!can(0, 0)) return [];
    const order = [...Array(n).keys()].sort((a, b2) => nums[a] - nums[b2]);
    const answer = [];
    let mask = 0, rem = 0;
    for (let step = 0; step < n; step++) {
        for (const idx of order) {
            if (mask & (1 << idx)) continue;
            const newRem = ((rem * pow10mod[idx]) % k + nums[idx] % k) % k;
            if (can(mask | (1 << idx), newRem)) {
                answer.push(nums[idx]);
                mask |= (1 << idx);
                rem = newRem;
                break;
            }
        }
    }
    return answer;
}

function baseUnitConversion(conversions) {
    const MOD2 = 1000000007;
    if (!conversions.length) return [];
    let maxIdx = 0;
    for (const [src, tgt] of conversions) {
        if (src > maxIdx) maxIdx = src;
        if (tgt > maxIdx) maxIdx = tgt;
    }
    const n = maxIdx + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [src, tgt, factor] of conversions) adj[src].push([tgt, factor]);
    const result = new Array(n).fill(0);
    result[0] = 1;
    const stack = [0];
    while (stack.length) {
        const u = stack.pop();
        for (const [v, factor] of adj[u]) {
            result[v] = (result[u] * factor) % MOD2;
            stack.push(v);
        }
    }
    return result;
}

function maxProfit(n, edges, score) {
    // build predecessor mask for each node
    const preMask = new Array(n).fill(0);
    for (const [u, v] of edges) {
        preMask[v] |= 1 << u;
    }

    const totalMask = (1 << n) - 1;
    const dp = new Array(1 << n).fill(-Infinity);
    dp[0] = 0;

    // iterate over all subsets of placed nodes
    for (let mask = 0; mask <= totalMask; ++mask) {
        const placed = dp[mask];
        if (placed === -Infinity) continue;               // unreachable state
        const pos = bitCount(mask) + 1;                    // position for the next node

        // try to place any node whose predecessors are already in mask
        for (let v = 0; v < n; ++v) {
            if (mask & (1 << v)) continue;                // already placed
            if ((preMask[v] & ~mask) !== 0) continue;     // some predecessor not placed yet
            const nextMask = mask | (1 << v);
            const profit = placed + score[v] * pos;
            if (profit > dp[nextMask]) dp[nextMask] = profit; // update best profit for nextMask
        }
    }
    return dp[totalMask];
}

// helper: count set bits in an integer (popcount)
function bitCount(x) {
    let cnt = 0;
    while (x) {
        x &= x - 1;
        ++cnt;
    }
    return cnt;
}

function fillSpecialGrid(n) {
    const size = 1 << n;                 // 2ⁿ
    const grid = Array.from({ length: size }, () => Array(size));

    // recursive helper: (row, col) top‑left corner, current sub‑grid size, start value
    function fill(r, c, sz, start) {
        if (sz === 1) {                  // base case: single cell
            grid[r][c] = start;
            return;
        }
        const half = sz >> 1;            // sz / 2
        const quad = half * half;        // cells in one quadrant

        // fill quadrants in the required order
        fill(r, c + half, half, start + 0 * quad); // top‑right
        fill(r + half, c + half, half, start + 1 * quad); // bottom‑right
        fill(r + half, c, half, start + 2 * quad); // bottom‑left
        fill(r, c, half, start + 3 * quad); // top‑left
    }

    fill(0, 0, size, 0);
    return grid;
}

function countCoveredBuildings(n, buildings) {
    const rowMin = new Map(), rowMax = new Map();
    const colMin = new Map(), colMax = new Map();
    const set = new Set();
    for (const [x,y] of buildings) {
        set.add(x+','+y);
        if (!rowMin.has(y) || x < rowMin.get(y)) rowMin.set(y, x);
        if (!rowMax.has(y) || x > rowMax.get(y)) rowMax.set(y, x);
        if (!colMin.has(x) || y < colMin.get(x)) colMin.set(x, y);
        if (!colMax.has(x) || y > colMax.get(x)) colMax.set(x, y);
    }
    let count = 0;
    for (const [x,y] of buildings) {
        if (x > rowMin.get(y) && x < rowMax.get(y) && y > colMin.get(x) && y < colMax.get(x)) count++;
    }
    return count;
}

var minTravelTime = function(l, n, k, position, time) {
    const INF = Infinity;
    const prefix = new Array(n).fill(0);
    for (let i = 0; i < n - 1; i++) prefix[i + 1] = prefix[i] + time[i];
    const dp = Array.from({length: n + 1}, () => Array.from({length: n}, () => new Array(k + 1).fill(INF)));
    dp[0][0][0] = 0;
    for (let c = 0; c < n - 1; c++) {
        for (let pidx = 0; pidx <= n; pidx++) {
            for (let m = 0; m <= k; m++) {
                const cost0 = dp[pidx][c][m];
                if (cost0 === INF) continue;
                const p = pidx - 1;
                const rate = prefix[c + 1] - prefix[p + 1];
                for (let i2 = c + 1; i2 < n; i2++) {
                    const mergesAdd = i2 - c - 1;
                    const m2 = m + mergesAdd;
                    if (m2 > k) continue;
                    const newcost = cost0 + rate * (position[i2] - position[c]);
                    if (newcost < dp[c + 1][i2][m2]) dp[c + 1][i2][m2] = newcost;
                }
            }
        }
    }
    let ans = INF;
    for (let pidx = 0; pidx <= n; pidx++) ans = Math.min(ans, dp[pidx][n - 1][k]);
    return ans;
};

function shortestPathLengths(n, nums, maxDiff, queries) {
    // sort indices by nums value
    const idx = new Array(n);
    for (let i = 0; i < n; i++) idx[i] = i;
    idx.sort((a, b) => {
        const diff = nums[a] - nums[b];
        return diff !== 0 ? diff : a - b;
    });
    const sortedVals = new Array(n);
    const pos = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        sortedVals[i] = nums[idx[i]];
        pos[idx[i]] = i;
    }
    // compute far[i]: farthest index reachable from i (inclusive)
    const far = new Int32Array(n);
    let r = 0;
    for (let i = 0; i < n; i++) {
        if (r < i) r = i;
        while (r + 1 < n && sortedVals[r + 1] - sortedVals[i] <= maxDiff) {
            r++;
        }
        far[i] = r;
    }
    // binary lifting table
    const LOG = Math.ceil(Math.log2(n)) + 1;
    const up = Array.from({ length: LOG }, () => new Int32Array(n));
    for (let i = 0; i < n; i++) up[0][i] = far[i];
    for (let k = 1; k < LOG; k++) {
        const prev = up[k - 1];
        const cur = up[k];
        for (let i = 0; i < n; i++) {
            cur[i] = prev[prev[i]];
        }
    }
    const answers = new Array(queries.length);
    for (let qi = 0; qi < queries.length; qi++) {
        let [u, v] = queries[qi];
        if (u === v) {
            answers[qi] = 0;
            continue;
        }
        let pu = pos[u];
        let pv = pos[v];
        if (pu > pv) {
            const tmp = pu;
            pu = pv;
            pv = tmp;
        }
        let cur = pu;
        let steps = 0;
        for (let k = LOG - 1; k >= 0; k--) {
            const nxt = up[k][cur];
            if (nxt < pv) {
                cur = nxt;
                steps += 1 << k;
            }
        }
        if (far[cur] >= pv) {
            answers[qi] = steps + 1;
        } else {
            answers[qi] = -1;
        }
    }
    return answers;
}
// TIME: O((n+q) log n) SPACE: O(n log n)

function maxProductTwoDigits(n) {
    // Convert the number to a string to iterate over its digits
    const s = n.toString();
    // Frequency array for digits 0‑9
    const freq = new Array(10).fill(0);
    for (let i = 0; i < s.length; i++) {
        freq[s.charCodeAt(i) - 48]++;   // count each digit
    }

    // Find the largest digit that appears at least once
    let first = -1;
    for (let d = 9; d >= 0; d--) {
        if (freq[d] > 0) { first = d; break; }
    }
    if (first === -1) return 0; // no digits (should not happen)

    // If the largest digit occurs twice, its square is the maximum product
    if (freq[first] >= 2) return first * first;

    // Otherwise find the next largest digit
    let second = -1;
    for (let d = first - 1; d >= 0; d--) {
        if (freq[d] > 0) { second = d; break; }
    }
    if (second === -1) return 0; // only one distinct digit present once
    return first * second;
}

function minOperations(nums) {
    let ops = 0;
    const stack = [];

    for (let h of nums) {
        while (stack.length && stack[stack.length - 1] > h) {
            stack.pop();                     // close higher segments
        }
        if (h > 0 && (!stack.length || stack[stack.length - 1] < h)) {
            stack.push(h);                   // start a new segment
            ops += 1;
        }
    }
    return ops;
}

function minDeletions(s, k) {
    // count frequency of each letter
    const freq = new Array(26).fill(0);
    for (let ch of s) {
        freq[ch.charCodeAt(0) - 97]++;
    }

    // collect frequencies of characters that actually appear
    const present = freq.filter(v => v > 0);
    const distinct = present.length;

    if (distinct <= k) return 0;               // already satisfies the condition

    // MAIN LOGIC: delete characters from the least frequent distinct letters
    present.sort((a, b) => a - b);             // ascending order of frequencies
    let deletions = 0;
    const toRemove = distinct - k;              // how many distinct letters must disappear
    for (let i = 0; i < toRemove; i++) {
        deletions += present[i];                // delete all occurrences of this letter
    }
    return deletions;
}

var maxSum = function(edges, nums, k) {
    const n = nums.length;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

    const parent = new Array(n).fill(-1);
    const order = [];
    const visited = new Array(n).fill(false);
    const stack = [0];
    visited[0] = true;
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const v of adj[u]) {
            if (!visited[v]) { visited[v] = true; parent[v] = u; stack.push(v); }
        }
    }

    const dp = new Array(n);
    for (let idx = order.length - 1; idx >= 0; idx--) {
        const v = order[idx];
        const children = adj[v].filter(c => c !== parent[v]);
        const table = [];
        for (let dist = 0; dist <= k; dist++) {
            const row = [0, 0];
            for (let sidx = 0; sidx < 2; sidx++) {
                const sign = sidx === 0 ? 1 : -1;
                let noInvert = sign * nums[v];
                const cdist = Math.min(dist+1, k);
                for (const c of children) noInvert += dp[c][cdist][sidx];
                let best = noInvert;
                if (dist >= k) {
                    let invert = -sign * nums[v];
                    for (const c of children) invert += dp[c][1][1-sidx];
                    best = Math.max(best, invert);
                }
                row[sidx] = best;
            }
            table.push(row);
        }
        dp[v] = table;
    }
    return dp[0][k][0];
};

function magicalSum(m, k, nums) {
  const MOD = 1000000007n;
  const n = nums.length;
  const C = Array.from({length: m + 1}, () => Array(m + 1).fill(0n));
  for (let i = 0; i <= m; i++) {
    C[i][0] = 1n;
    for (let j = 1; j <= i; j++) C[i][j] = (C[i-1][j-1] + (j <= i-1 ? C[i-1][j] : 0n)) % MOD;
  }
  function modpow(base, exp, mod) {
    base %= mod; let result = 1n;
    while (exp > 0n) { if (exp & 1n) result = (result * base) % mod; base = (base * base) % mod; exp >>= 1n; }
    return result;
  }
  const memo = new Map();
  function dfs(i, j, kk, carry) {
    if (kk < 0 || (i === n && j > 0)) return 0n;
    const key = i + ',' + j + ',' + kk + ',' + carry;
    if (memo.has(key)) return memo.get(key);
    if (i === n) {
      let c = carry, kRem = kk;
      while (c) { kRem -= c & 1; c >>= 1; }
      const res = kRem === 0 ? 1n : 0n;
      memo.set(key, res); return res;
    }
    let res = 0n;
    for (let t = 0; t <= j; t++) {
      const nt = t + carry;
      const p = modpow(BigInt(nums[i]), BigInt(t), MOD);
      const nk = kk - (nt & 1);
      res = (res + C[j][t] * p % MOD * dfs(i + 1, j - t, nk, nt >> 1)) % MOD;
    }
    memo.set(key, res); return res;
  }
  return Number(dfs(0, m, k, 0) % MOD);
}

function mostFrequentVowelConsonant(s) {
    const vowelSet = new Set(['a', 'e', 'i', 'o', 'u']);
    const freq = Array(26).fill(0);               // frequency of each letter

    // count occurrences of each character
    for (let i = 0; i < s.length; i++) {
        const idx = s.charCodeAt(i) - 97;          // 'a' -> 0, 'b' -> 1, ...
        freq[idx]++;
    }

    let maxVowel = 0, maxConsonant = 0;

    // find the maximum frequency among vowels and among consonants
    for (let i = 0; i < 26; i++) {
        const count = freq[i];
        const ch = String.fromCharCode(i + 97);
        if (vowelSet.has(ch)) {
            if (count > maxVowel) maxVowel = count;
        } else {
            if (count > maxConsonant) maxConsonant = count;
        }
    }

    return maxVowel + maxConsonant;
}

function smallestIndex(nums) {
    // iterate over each index
    for (let i = 0; i < nums.length; i++) {
        let value = Math.abs(nums[i]); // work with non‑negative value
        let digitSum = 0;
        // compute sum of digits
        while (value > 0) {
            digitSum += value % 10;
            value = Math.floor(value / 10);
        }
        if (digitSum === i) return i; // found the smallest matching index
    }
    return -1; // no index satisfies the condition
}

function maxWeight(n, edges, k, t) {
    const adj = Array.from({length:n}, () => []);
    for (const [u,v,w] of edges) adj[u].push([v,w]);
    let best = -1;
    const dp = Array.from({length:n}, () => Array.from({length:k+1}, () => new Set()));
    for (let i = 0; i < n; i++) dp[i][0].add(0);
    for (let e = 0; e < k; e++) {
        for (let u = 0; u < n; u++) {
            for (const s of dp[u][e]) {
                for (const [v,w] of adj[u]) {
                    const ns = s + w;
                    if (ns < t) dp[v][e+1].add(ns);
                }
            }
        }
    }
    for (let u = 0; u < n; u++) for (const s of dp[u][k]) best = Math.max(best, s);
    return best;
}

function equalSumGridPartition(grid) {
    const m = grid.length;
    const n = grid[0].length;

    const rowSums = new Array(m).fill(0);
    const colSums = new Array(n).fill(0);
    let total = 0;

    // compute total sum, row sums and column sums
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            const v = grid[i][j];
            total += v;
            rowSums[i] += v;
            colSums[j] += v;
        }
    }

    // try every possible horizontal cut
    let prefix = 0;
    for (let i = 0; i < m - 1; i++) {          // cut between row i and i+1
        prefix += rowSums[i];
        if (prefix * 2 === total) return true; // left part equals right part
    }

    // try every possible vertical cut
    prefix = 0;
    for (let j = 0; j < n - 1; j++) {          // cut between column j and j+1
        prefix += colSums[j];
        if (prefix * 2 === total) return true; // left part equals right part
    }

    return false;
}

function minimumWeightedSubgraphWithTheRequiredPathsII(edges, queries) {
    const n = edges.length + 1;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, w] of edges) { adj[u].push([v, w]); adj[v].push([u, w]); }

    const LOG = Math.max(1, Math.ceil(Math.log2(n + 1)));
    const parent = Array.from({length: LOG}, () => new Array(n).fill(-1));
    const depth = new Array(n).fill(0);
    const dist = new Array(n).fill(0);

    const stack = [[0, -1]];
    const visited = new Array(n).fill(false);
    while (stack.length) {
        const [u, p] = stack.pop();
        if (visited[u]) continue;
        visited[u] = true;
        for (const [v, w] of adj[u]) {
            if (v === p) continue;
            parent[0][v] = u;
            depth[v] = depth[u] + 1;
            dist[v] = dist[u] + w;
            stack.push([v, u]);
        }
    }

    for (let kk = 1; kk < LOG; kk++) {
        for (let v = 0; v < n; v++) {
            const anc = parent[kk - 1][v];
            parent[kk][v] = anc === -1 ? -1 : parent[kk - 1][anc];
        }
    }

    const lca = (u, v) => {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        let diff = depth[u] - depth[v];
        let bit = 0;
        while (diff) { if (diff & 1) u = parent[bit][u]; diff >>= 1; bit++; }
        if (u === v) return u;
        for (let kk = LOG - 1; kk >= 0; kk--) {
            if (parent[kk][u] !== parent[kk][v]) { u = parent[kk][u]; v = parent[kk][v]; }
        }
        return parent[0][u];
    };

    const distance = (u, v) => {
        const w = lca(u, v);
        return dist[u] + dist[v] - 2 * dist[w];
    };

    const res = [];
    for (const [a, b, c] of queries) {
        const x = lca(a, b), y = lca(a, c), z = lca(b, c);
        let m = x;
        if (depth[y] > depth[m]) m = y;
        if (depth[z] > depth[m]) m = z;
        const total = distance(a, m) + distance(b, m) + distance(c, m);
        res.push(total);
    }
    return res;
}

function maximumEdgeSum(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const order = [];
    if (n === 1) {
        order.push(0);
    } else {
        let start = -1;
        for (let i = 0; i < n; i++) {
            if (adj[i].length === 1) {
                start = i;
                break;
            }
        }
        if (start === -1) {
            // cycle
            start = 0;
            let prev = -1;
            let cur = start;
            for (let i = 0; i < n; i++) {
                order.push(cur);
                let next = adj[cur][0];
                if (next === prev && adj[cur].length > 1) next = adj[cur][1];
                prev = cur;
                cur = next;
            }
        } else {
            // path
            let prev = -1;
            let cur = start;
            while (true) {
                order.push(cur);
                let next = undefined;
                for (const nb of adj[cur]) {
                    if (nb !== prev) {
                        next = nb;
                        break;
                    }
                }
                if (next === undefined) break;
                prev = cur;
                cur = next;
            }
        }
    }

    // Build the zigzag value sequence: sort n..1 descending, insert alternately
    // right/left into a deque so the largest values end up clustered together
    // (this maximizes the sum of adjacent products along the path/cycle order).
    const seq = [n];
    let appendRight = true;
    for (let v = n - 1; v >= 1; v--) {
        if (appendRight) seq.push(v);
        else seq.unshift(v);
        appendRight = !appendRight;
    }

    const value = new Array(n);
    for (let i = 0; i < n; i++) {
        value[order[i]] = seq[i];
    }
    let sum = 0;
    for (const [u, v] of edges) {
        sum += value[u] * value[v];
    }
    return sum;
}

function equalSumGridPartition(grid) {
  const m = grid.length, n = grid[0].length;

  function check(mat) {
    const rows = mat.length, cols = mat[0].length;
    const rowSum = mat.map(row => row.reduce((a,b)=>a+b,0));
    const total = rowSum.reduce((a,b)=>a+b,0);
    let topSum = 0;
    const topFreq = new Map();
    const fullFreq = new Map();
    for (const row of mat) for (const v of row) fullFreq.set(v, (fullFreq.get(v)||0)+1);
    const botFreq = new Map(fullFreq);

    for (let r = 0; r < rows - 1; r++) {
      topSum += rowSum[r];
      for (const v of mat[r]) {
        topFreq.set(v, (topFreq.get(v)||0)+1);
        botFreq.set(v, botFreq.get(v)-1);
        if (botFreq.get(v) === 0) botFreq.delete(v);
      }
      const botSum = total - topSum;
      const topRows = r + 1, botRows = rows - topRows;

      if (topSum === botSum) return true;
      const diff = Math.abs(topSum - botSum);
      if (topSum > botSum) {
        if (topFreq.has(diff)) {
          if (topRows >= 2 && cols >= 2) return true;
          if (topRows === 1) {
            if (mat[0][0] === diff || mat[0][cols-1] === diff) return true;
          } else if (cols === 1) {
            if (mat[0][0] === diff || mat[topRows-1][0] === diff) return true;
          }
        }
      } else {
        if (botFreq.has(diff)) {
          if (botRows >= 2 && cols >= 2) return true;
          if (botRows === 1) {
            if (mat[r+1][0] === diff || mat[r+1][cols-1] === diff) return true;
          } else if (cols === 1) {
            if (mat[r+1][0] === diff || mat[rows-1][0] === diff) return true;
          }
        }
      }
    }
    return false;
  }

  if (check(grid)) return true;
  const t = Array.from({length: n}, (_, j) => Array.from({length: m}, (_, i) => grid[i][j]));
  if (check(t)) return true;
  return false;
}

function sumLargestPrimes(s) {
    const n = s.length;
    const primeSet = new Set();

    // MAIN LOGIC: generate every substring, convert to integer (ignoring leading zeros), test for primality, store unique primes
    for (let i = 0; i < n; i++) {
        let numStr = '';
        for (let j = i; j < n; j++) {
            numStr += s[j];
            const num = parseInt(numStr, 10);          // leading zeros are ignored by parseInt
            if (num >= 2 && isPrime(num)) {
                primeSet.add(num);
            }
        }
    }

    // sort primes descending and sum the three largest (or fewer)
    const primes = Array.from(primeSet).sort((a, b) => b - a);
    let sum = 0;
    for (let k = 0; k < Math.min(3, primes.length); k++) {
        sum += primes[k];
    }
    return sum;
}

// trial‑division primality test
function isPrime(num) {
    if (num < 2) return false;
    if (num % 2 === 0) return num === 2;
    const limit = Math.floor(Math.sqrt(num));
    for (let d = 3; d <= limit; d += 2) {
        if (num % d === 0) return false;
    }
    return true;
}

function findMaximumNumberOfNonIntersectingSubstrings(word) {
    const n = word.length;
    const pos = new Map();
    for (let i = 0; i < n; i++) {
        const ch = word[i];
        if (!pos.has(ch)) pos.set(ch, []);
        pos.get(ch).push(i);
    }

    const bisectLeft = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < val) lo = mid + 1; else hi = mid; }
        return lo;
    };

    const intervals = [];
    for (let i = 0; i < n; i++) {
        const ch = word[i];
        const lst = pos.get(ch);
        const jIdx = bisectLeft(lst, i + 3);
        if (jIdx < lst.length) intervals.push([i, lst[jIdx]]);
    }

    intervals.sort((a, b) => a[1] - b[1]);

    let count = 0, lastEnd = -1;
    for (const [l, r] of intervals) {
        if (l > lastEnd) { count++; lastEnd = r; }
    }
    return count;
}

function minSwaps(nums) {
  // helper to compute digit sum
  function digitSum(n) {
    let sum = 0;
    while (n > 0) {
      sum += n % 10;
      n = Math.floor(n / 10);
    }
    return sum;
  }

  // build array with sorting keys
  const withKeys = nums.map((v, i) => ({
    value: v,
    digitSum: digitSum(v),
    originalIdx: i
  }));

  // sort by digit sum then by value
  withKeys.sort((a, b) => {
    if (a.digitSum !== b.digitSum) return a.digitSum - b.digitSum;
    return a.value - b.value;
  });

  // map each value to its target index after sorting
  const targetPos = new Map();
  withKeys.forEach((obj, idx) => targetPos.set(obj.value, idx));

  const visited = new Array(nums.length).fill(false);
  let swaps = 0;

  // count swaps via cycle decomposition
  for (let i = 0; i < nums.length; i++) {
    if (visited[i]) continue;
    let cycleLen = 0;
    let j = i;
    while (!visited[j]) {
      visited[j] = true;
      const nextValue = nums[j];
      j = targetPos.get(nextValue); // move to the position where this value should go
      cycleLen++;
    }
    if (cycleLen > 1) swaps += cycleLen - 1; // each cycle needs (len-1) swaps
  }

  return swaps;
}

var resultingString = function(s) {
