    for (const ch of s) {
        if (stack.length && consecutive(stack[stack.length-1], ch)) stack.pop();
        else stack.push(ch);
    }
    return stack.join('');
};

function minMoves(matrix) {
    const m = matrix.length, n = matrix[0].length;
    const portalCells = new Map();
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        const c = matrix[i][j];
        if (c >= 'A' && c <= 'Z') {
            if (!portalCells.has(c)) portalCells.set(c, []);
            portalCells.get(c).push([i,j]);
        }
    }
    const dist = Array.from({length:m}, () => new Array(n).fill(Infinity));
    dist[0][0] = 0;
    const deque = [[0,0]];
    const usedPortal = new Set();
    const dirs = [[-1,0],[1,0],[0,-1],[0,1]];
    while (deque.length) {
        const [i,j] = deque.shift();
        const d = dist[i][j];
        const c = matrix[i][j];
        if (c >= 'A' && c <= 'Z' && !usedPortal.has(c)) {
            usedPortal.add(c);
            for (const [ni,nj] of portalCells.get(c)) {
                if (d < dist[ni][nj]) { dist[ni][nj] = d; deque.unshift([ni,nj]); }
            }
        }
        for (const [di,dj] of dirs) {
            const ni=i+di, nj=j+dj;
            if (ni>=0&&ni<m&&nj>=0&&nj<n&&matrix[ni][nj] !== '#') {
                if (d+1 < dist[ni][nj]) { dist[ni][nj]=d+1; deque.push([ni,nj]); }
            }
        }
    }
    return dist[m-1][n-1] === Infinity ? -1 : dist[m-1][n-1];
}

function assignEdgeWeights(edges) {
  const MOD = 1000000007n;
  const n = edges.length + 1;
  const adj = Array.from({length:n+1}, () => []);
  for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }
  const depth = new Array(n+1).fill(-1);
  depth[1] = 0;
  const queue = [1];
  let idx = 0, maxDepth = 0;
  while (idx < queue.length) {
    const u = queue[idx++];
    for (const v of adj[u]) if (depth[v] === -1) { depth[v] = depth[u]+1; maxDepth = Math.max(maxDepth, depth[v]); queue.push(v); }
  }
  if (maxDepth === 0) return 0;
  function modpow(b,e,m){ b%=m; let r=1n; while(e>0n){ if(e&1n) r=r*b%m; b=b*b%m; e>>=1n; } return r; }
  return Number(modpow(2n, BigInt(maxDepth-1), MOD));
}

function numberOfWaysEdgeWeights(edges, queries) {
    const MOD2 = 1000000007n;
    const n = edges.length + 1;
    const adj = Array.from({length: n+1}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }
    const LOG = Math.max(1, Math.ceil(Math.log2(n+1)) + 1);
    const parent = Array.from({length: LOG}, () => new Array(n+1).fill(0));
    const depth = new Array(n+1).fill(0);
    const visited = new Array(n+1).fill(false);
    const stack = [1];
    visited[1] = true;
    depth[1] = 0;
    parent[0][1] = 0;
    while (stack.length) {
        const u = stack.pop();
        for (const v of adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                depth[v] = depth[u] + 1;
                parent[0][v] = u;
                stack.push(v);
            }
        }
    }
    for (let k = 1; k < LOG; k++) {
        for (let v = 1; v <= n; v++) {
            const anc = parent[k-1][v];
            parent[k][v] = anc ? parent[k-1][anc] : 0;
        }
    }
    function lca(u, v) {
        if (depth[u] < depth[v]) [u, v] = [v, u];
        let diff = depth[u] - depth[v];
        let bit = 0;
        while (diff) {
            if (diff & 1) u = parent[bit][u];
            diff >>= 1;
            bit++;
        }
        if (u === v) return u;
        for (let k = LOG - 1; k >= 0; k--) {
            if (parent[k][u] !== parent[k][v]) { u = parent[k][u]; v = parent[k][v]; }
        }
        return parent[0][u];
    }
    function modpow(base, exp, mod) {
        base %= mod; let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    }
    const res = [];
    for (const [u, v] of queries) {
        const w = lca(u, v);
        const length = depth[u] + depth[v] - 2 * depth[w];
        if (length === 0) res.push(0);
        else res.push(Number(modpow(2n, BigInt(length - 1), MOD2)));
    }
    return res;
}

function findMinimumLogTransportationCost(n, m, k) {
