}

function minAbsDiffInSlidingSubmatrix(grid, k) {
    const m = grid.length;
    const n = grid[0].length;
    const rows = m - k + 1;
    const cols = n - k + 1;
    const ans = Array.from({ length: rows }, () => Array(cols).fill(0));
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const values = [];
            for (let x = i; x < i + k; x++) { for (let y = j; y < j + k; y++) { values.push(grid[x][y]); } }
            // the problem wants the min diff between DISTINCT values - dedupe first so
            // two cells sharing the same value don't produce a spurious diff of 0
            const uniq = Array.from(new Set(values)).sort((a, b) => a - b);
            let minDiff = Infinity;
            for (let p = 1; p < uniq.length; p++) {
                const diff = uniq[p] - uniq[p - 1];
                if (diff < minDiff) minDiff = diff;
            }
            ans[i][j] = uniq.length < 2 ? 0 : minDiff;
        }
    }
    return ans;
}

function maxProfitFromStocks(n, present, future, hierarchy, budget) {
  const tree = Array.from({ length: n }, () => []);
  for (const [u, v] of hierarchy) tree[u - 1].push(v - 1);

  function merge(a, b) {
    const res = Array(budget + 1).fill(0);
    for (let i = 0; i <= budget; i++) {
      let best = 0;
      for (let j = 0; j <= i; j++) {
        const v = a[i - j] + b[j];
        if (v > best) best = v;
      }
      res[i] = best;
    }
    return res;
  }

  function dfs(u) {
    let noBuyMerged = Array(budget + 1).fill(0);
    let buyMerged = Array(budget + 1).fill(0);
    for (const v of tree[u]) {
      const [childDp0, childDp1] = dfs(v);
      noBuyMerged = merge(noBuyMerged, childDp0);
      buyMerged = merge(buyMerged, childDp1);
    }

    const dp0 = noBuyMerged.slice();
    const dp1 = noBuyMerged.slice();

    const costFull = present[u];
    if (costFull <= budget) {
      for (let b = costFull; b <= budget; b++) {
        const candidate = (future[u] - costFull) + buyMerged[b - costFull];
        if (candidate > dp0[b]) dp0[b] = candidate;
      }
    }
    const costDisc = Math.floor(present[u] / 2);
    if (costDisc <= budget) {
      for (let b = costDisc; b <= budget; b++) {
        const candidate = (future[u] - costDisc) + buyMerged[b - costDisc];
        if (candidate > dp1[b]) dp1[b] = candidate;
      }
    }
    return [dp0, dp1];
  }

  const [dp0] = dfs(0);
  return dp0[budget];
}

function smallestStringAfterRemovals(s) {
  const n = s.length;
  if (n === 0) return "";
  const isConsecutive = (a, b) => {
    const diff = Math.abs(a.charCodeAt(0) - b.charCodeAt(0));
    return diff === 1 || diff === 25;
  };
  const can = Array.from({ length: n }, () => Array(n).fill(false));
  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      for (let k = i + 1; k <= j; k++) {
        if (
          isConsecutive(s[i], s[k]) &&
          (i + 1 > k - 1 || can[i + 1][k - 1]) &&
          (k + 1 > j || can[k + 1][j])
        ) {
          can[i][j] = true;
          break;
        }
      }
    }
  }
  const best = Array.from({ length: n }, () => Array(n).fill(""));
  for (let i = 0; i < n; i++) best[i][i] = s[i];
  for (let len = 2; len <= n; len++) {
    for (let i = 0; i + len - 1 < n; i++) {
      const j = i + len - 1;
      if (can[i][j]) {
        best[i][j] = "";
        continue;
      }
      let cur = s.slice(i, j + 1);
      for (let m = i; m < j; m++) {
        const cand = best[i][m] + best[m + 1][j];
        if (cand < cur) cur = cand;
      }
      best[i][j] = cur;
    }
  }
  return best[0][n - 1];
}

function checkEqualPartitions(nums, target) {
