                const l = first + 1, r = last;
                diff[l] += 1;
                diff[r + 1] -= 1;
            }
        }
        let bestOverlap = 0, cur = 0;
        for (let p = 1; p < n; p++) {
            cur += diff[p];
            bestOverlap = Math.max(bestOverlap, cur);
        }
        ans.push(totalDistinct + bestOverlap);
    }
    return ans;
}

