function maxGCDScore(nums, k) {
    const n = nums.length;
    let best = 0;
    for (let i = 0; i < n; i++) {
        let g = 0;
        for (let j = i; j < n; j++) {
            g = gcd(g, nums[j]);
            const len = j - i + 1;
            let minV = Infinity, cntMin = 0;
            for (let t = i; t <= j; t++) {
                let v = 0, x = nums[t];
                while (x % 2 === 0) { x /= 2; v++; }
                if (v < minV) { minV = v; cntMin = 1; }
                else if (v === minV) cntMin++;
            }
            let score = len * g;
            if (cntMin <= k) score = Math.max(score, len * g * 2);
            best = Math.max(best, score);
        }
    }
    return best;
}

function canMakeEqual(nums, k) {
    // the operation flips BOTH nums[i] and nums[i+1] together, not one element freely,
    // so a simple 'count the minority value' model doesn't capture the real constraint
    function check(target) {
        const n = nums.length;
        const copy = nums.slice();
        let ops = 0;
        for (let i = 0; i < n - 1; i++) {
            if (copy[i] !== target) {
                copy[i] *= -1;
                copy[i + 1] *= -1;
                ops++;
            }
        }
        return copy[n - 1] === target && ops <= k;
    }
    if (nums.length === 1) return true;
    return check(1) || check(-1);
}

function maxYSum(x, y) {
    // 1. keep the maximum y for each distinct x
    const best = new Map();               // x -> max y
    for (let i = 0; i < x.length; i++) {
        const curX = x[i];
        const curY = y[i];
        if (!best.has(curX) || curY > best.get(curX)) {
            best.set(curX, curY);
        }
    }

    // 2. find the three largest values among the stored maxima
    let first = -Infinity, second = -Infinity, third = -Infinity;
    for (const val of best.values()) {
        if (val > first) {                 // shift down
            third = second;
            second = first;
            first = val;
        } else if (val > second) {
            third = second;
            second = val;
        } else if (val > third) {
            third = val;
        }
    }

    // 3. if we have three distinct x‑values return their sum, else -1
    return third === -Infinity ? -1 : first + second + third;
}

function maximumProfit(prices, k) {
    const n = prices.length;
    const NEG = -Infinity;
    let f = Array.from({length: k+1}, () => [NEG, NEG, NEG]);
    f[0][0] = 0;
    for (let j = 1; j <= k; j++) {
        f[j][0] = 0;
        f[j][1] = -prices[0];
        f[j][2] = prices[0];
    }
    for (let i = 1; i < n; i++) {
        const nf = Array.from({length: k+1}, () => [NEG, NEG, NEG]);
        nf[0][0] = 0;
        for (let j = 1; j <= k; j++) {
            let best0 = f[j][0];
            if (f[j][1] > NEG) best0 = Math.max(best0, f[j][1] + prices[i]);
            if (f[j][2] > NEG) best0 = Math.max(best0, f[j][2] - prices[i]);
            nf[j][0] = best0;

            let best1 = f[j][1];
            if (f[j-1][0] > NEG) best1 = Math.max(best1, f[j-1][0] - prices[i]);
            nf[j][1] = best1;

            let best2 = f[j][2];
            if (f[j-1][0] > NEG) best2 = Math.max(best2, f[j-1][0] + prices[i]);
            nf[j][2] = best2;
        }
        f = nf;
    }
    return f[k][0];
}

