function countPartitionsWithMaxMinDifferenceAtMostK(nums, k) {
    const MOD = 1000000007;
    const n = nums.length;
    if (n === 0) return 1;
    const pref = new Array(n + 1).fill(0);
    pref[0] = 1;
    const maxdq = [];
    const mindq = [];
    let left = 0, dp = 0;

    for (let idx = 1; idx <= n; idx++) {
        const val = nums[idx - 1];
        while (maxdq.length && nums[maxdq[maxdq.length - 1]] <= val) maxdq.pop();
        maxdq.push(idx - 1);
        while (mindq.length && nums[mindq[mindq.length - 1]] >= val) mindq.pop();
        mindq.push(idx - 1);
        while (nums[maxdq[0]] - nums[mindq[0]] > k) {
            if (maxdq[0] === left) maxdq.shift();
            if (mindq[0] === left) mindq.shift();
            left++;
        }
        if (left === 0) dp = pref[idx - 1];
        else dp = pref[idx - 1] - pref[left - 1];
        dp = ((dp % MOD) + MOD) % MOD;
        pref[idx] = (pref[idx - 1] + dp) % MOD;
    }
    return dp % MOD;
}

