}

var minOperations = function(word1, word2) {
    const n = word1.length;
    function calc(l, r, rev) {
        const cnt = Array.from({length: 26}, () => new Array(26).fill(0));
        let res = 0;
        for (let i = l; i <= r; i++) {
            const j = rev ? r - (i - l) : i;
            const a = word1.charCodeAt(j) - 97;
            const b = word2.charCodeAt(i) - 97;
            if (a !== b) {
                if (cnt[b][a] > 0) cnt[b][a]--;
                else { cnt[a][b]++; res++; }
            }
        }
        return res;
    }
    const f = new Array(n + 1).fill(Infinity);
    f[0] = 0;
    for (let i = 1; i <= n; i++) {
        for (let j = 0; j < i; j++) {
            if (f[j] === Infinity) continue;
            const a = calc(j, i - 1, false);
            const b = 1 + calc(j, i - 1, true);
            const t = Math.min(a, b);
            f[i] = Math.min(f[i], f[j] + t);
        }
    }
    return f[n];
};

function weightedMedianNode(n, edges, queries) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
    }

    const LOG = Math.ceil(Math.log2(n)) + 1;
    const parent = Array.from({ length: LOG }, () => new Array(n).fill(-1));
    const upDist = Array.from({ length: LOG }, () => new Array(n).fill(0));
    const depth = new Array(n).fill(0);
    const dist = new Array(n).fill(0);

    const stack = [0];
    const visited = new Array(n).fill(false);
    visited[0] = true;
    while (stack.length) {
        const node = stack.pop();
        for (const [nei, w] of adj[node]) {
            if (!visited[nei]) {
                visited[nei] = true;
                parent[0][nei] = node;
                upDist[0][nei] = w;
                depth[nei] = depth[node] + 1;
                dist[nei] = dist[node] + w;
                stack.push(nei);
            }
        }
    }

    for (let k = 1; k < LOG; k++) {
        for (let v = 0; v < n; v++) {
            const mid = parent[k - 1][v];
            if (mid !== -1) {
                parent[k][v] = parent[k - 1][mid];
                upDist[k][v] = upDist[k - 1][v] + upDist[k - 1][mid];
            }
        }
    }

    function lca(a, b) {
        if (depth[a] < depth[b]) [a, b] = [b, a];
        let diff = depth[a] - depth[b];
        for (let k = LOG - 1; k >= 0; k--) {
            if ((diff >> k) & 1) a = parent[k][a];
        }
        if (a === b) return a;
        for (let k = LOG - 1; k >= 0; k--) {
            if (parent[k][a] !== -1 && parent[k][a] !== parent[k][b]) {
                a = parent[k][a];
                b = parent[k][b];
            }
        }
        return parent[0][a];
    }

    function climbExact(node, need) {
        for (let k = LOG - 1; k >= 0; k--) {
            if (parent[k][node] !== -1 && upDist[k][node] <= need) {
                need -= upDist[k][node];
                node = parent[k][node];
            }
        }
        return node;
    }

    const ans = [];
    for (const [u, v] of queries) {
        const w = lca(u, v);
        const total = dist[u] + dist[v] - 2 * dist[w];
        const target = Math.floor((total + 1) / 2); // ceil(total/2)
        const du = dist[u] - dist[w];
        if (target <= du) {
            let cur = u;
            let need = target;
            for (let k = LOG - 1; k >= 0; k--) {
                if (parent[k][cur] !== -1 && upDist[k][cur] < need) {
                    need -= upDist[k][cur];
                    cur = parent[k][cur];
                }
            }
            ans.push(parent[0][cur]);
        } else {
            const upNeeded = total - target; // distance to move up from v
            const node = climbExact(v, upNeeded);
            ans.push(node);
        }
    }
    return ans;
}
// TIME: O((n + q) log n) SPACE: O(n log n)

function specialTriplets(nums) {
    const MOD = 1000000007n;
    const right = new Map();
    const left = new Map();
    for (const x of nums) right.set(x, (right.get(x) || 0) + 1);
    let ans = 0n;
    for (const x of nums) {
        right.set(x, right.get(x) - 1);
        const t = x * 2;
        const l = BigInt(left.get(t) || 0);
        const r = BigInt(right.get(t) || 0);
