}

function minSwaps(nums) {
    const n = nums.length;
    const evenPos = [];
    const oddPos = [];

    // collect original indices of each parity
    for (let i = 0; i < n; i++) {
        if (nums[i] % 2 === 0) evenPos.push(i);
        else oddPos.push(i);
    }

    const evenCnt = evenPos.length;
    const oddCnt = oddPos.length;

    // impossible if counts differ by more than 1
    if (Math.abs(evenCnt - oddCnt) > 1) return -1;

    const patterns = [];
    if (evenCnt >= oddCnt) patterns.push('evenFirst'); // start with even at index 0
    if (oddCnt >= evenCnt) patterns.push('oddFirst');   // start with odd at index 0

    let answer = Infinity;

    for (const pat of patterns) {
        const targetEven = [];

        // build target positions for evens according to the pattern
        if (pat === 'evenFirst') {
            for (let i = 0; i < n; i += 2) targetEven.push(i);
        } else {
            for (let i = 1; i < n; i += 2) targetEven.push(i);
        }

        // sum of distances each even element must travel (minimal adjacent swaps)
        let swaps = 0;
        for (let i = 0; i < evenCnt; i++) {
            swaps += Math.abs(evenPos[i] - targetEven[i]);
        }

        answer = Math.min(answer, swaps);
    }

    return answer;
}

function findMaximumAreaOfATriangle(points) {
    if (!points.length) return -1;
    const xMinY = new Map(), xMaxY = new Map();
    const yMinX = new Map(), yMaxX = new Map();

    let minX = points[0][0], maxX = points[0][0];
    let minY = points[0][1], maxY = points[0][1];

    for (const [x, y] of points) {
        if (x < minX) minX = x; else if (x > maxX) maxX = x;
        if (y < minY) minY = y; else if (y > maxY) maxY = y;

        if (xMinY.has(x)) {
            if (y < xMinY.get(x)) xMinY.set(x, y);
            if (y > xMaxY.get(x)) xMaxY.set(x, y);
        } else { xMinY.set(x, y); xMaxY.set(x, y); }

        if (yMinX.has(y)) {
            if (x < yMinX.get(y)) yMinX.set(y, x);
            if (x > yMaxX.get(y)) yMaxX.set(y, x);
        } else { yMinX.set(y, x); yMaxX.set(y, x); }
    }

    let best = 0;
    for (const [x, miny] of xMinY) {
        const maxy = xMaxY.get(x);
        if (maxy > miny) {
            const base = maxy - miny;
            const height = Math.max(Math.abs(x - minX), Math.abs(x - maxX));
            const area2 = base * height;
            if (area2 > best) best = area2;
        }
    }
    for (const [y, minx] of yMinX) {
        const maxx = yMaxX.get(y);
        if (maxx > minx) {
            const base = maxx - minx;
            const height = Math.max(Math.abs(y - minY), Math.abs(y - maxY));
            const area2 = base * height;
            if (area2 > best) best = area2;
        }
    }
    return best > 0 ? best : -1;
}

var maxProduct = function(nums, m) {
