    for (let j=0;j<n;j++) {
        const idx = j-(m-1);
        if (idx >= 0) {
            const val = nums[idx];
            if (val > bestMax) bestMax = val;
            if (val < bestMin) bestMin = val;
            const cur = nums[j];
            const prod1 = bestMax*cur;
            const prod2 = bestMin*cur;
            answer = Math.max(answer, Math.max(prod1, prod2));
        }
    }
    return answer;
};

function kthSmallestPathXor(par, vals, queries) {
    const n = vals.length;
    const adj = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        const p = par[i];
        adj[p].push(i);
    }
    const pathXor = new Int32Array(n);
    const tin = new Int32Array(n);
    const tout = new Int32Array(n);
    const euler = new Int32Array(n);
    let timer = 0;
    const stack = [[0, 0]]; // [node, state] state 0 = enter, 1 = exit
    while (stack.length) {
        const [node, state] = stack.pop();
        if (state === 0) {
            // enter
            tin[node] = timer;
            euler[timer] = node;
            timer++;
            // compute path xor
            if (par[node] === -1) pathXor[node] = vals[node];
            else pathXor[node] = pathXor[par[node]] ^ vals[node];
            // push exit marker
            stack.push([node, 1]);
            // push children
            const children = adj[node];
            for (let i = children.length - 1; i >= 0; i--) {
                stack.push([children[i], 0]);
            }
        } else {
            // exit
            tout[node] = timer - 1;
        }
    }
    const q = queries.length;
    const blockSize = Math.floor(Math.sqrt(n)) || 1;
    const qObjs = new Array(q);
    for (let i = 0; i < q; i++) {
        const [u, k] = queries[i];
        qObjs[i] = {
            l: tin[u],
            r: tout[u],
            k: k,
            idx: i
        };
    }
    qObjs.sort((a, b) => {
        const blockA = Math.floor(a.l / blockSize);
        const blockB = Math.floor(b.l / blockSize);
        if (blockA !== blockB) return blockA - blockB;
        if (blockA % 2 === 0) return a.r - b.r;
        return b.r - a.r;
    });
    const MAX_VAL = 1 << 17; // 131072, covers possible XOR values (0..131071)
    const bitSize = MAX_VAL + 2;
    const bit = new Int32Array(bitSize);
    const freq = new Int32Array(MAX_VAL);
    let distinctCount = 0;
    function bitAdd(i, delta) {
        while (i < bitSize) {
            bit[i] += delta;
            i += i & -i;
        }
    }
    function bitFindKth(k) {
        let idx = 0;
        let mask = 1;
        while (mask < bitSize) mask <<= 1;
        for (mask >>= 1; mask > 0; mask >>= 1) {
            const next = idx + mask;
            if (next < bitSize && bit[next] < k) {
                idx = next;
                k -= bit[next];
            }
        }
        return idx + 1; // 1‑based index
    }
    function addPos(pos) {
        const node = euler[pos];
        const v = pathXor[node];
        if (freq[v] === 0) {
            bitAdd(v + 1, 1);
            distinctCount++;
        }
        freq[v]++;
    }
    function removePos(pos) {
        const node = euler[pos];
        const v = pathXor[node];
        freq[v]--;
        if (freq[v] === 0) {
            bitAdd(v + 1, -1);
            distinctCount--;
        }
    }
    const ans = new Array(q);
    let curL = 0, curR = -1;
    for (const qq of qObjs) {
        while (curL > qq.l) addPos(--curL);
        while (curR < qq.r) addPos(++curR);
        while (curL < qq.l) removePos(curL++);
        while (curR > qq.r) removePos(curR--);
        if (qq.k > distinctCount) {
            ans[qq.idx] = -1;
        } else {
            const idx = bitFindKth(qq.k);
            ans[qq.idx] = idx - 1;
        }
    }
    return ans;
}
// TIME: O((n+q)·√n·log M) SPACE: O(n+M)

class MinHeap {
    constructor() { this.data = []; }
    push(item) {
        this.data.push(item);
        let i = this.data.length - 1;
        while (i > 0) {
            const p = (i-1)>>1;
            if (this.data[p][0] <= this.data[i][0]) break;
            [this.data[p], this.data[i]] = [this.data[i], this.data[p]];
            i = p;
        }
    }
    pop() {
        const top = this.data[0];
        const last = this.data.pop();
        if (this.data.length > 0) {
            this.data[0] = last;
            let i = 0;
            while (true) {
                let l = 2*i+1, r = 2*i+2, smallest = i;
                if (l < this.data.length && this.data[l][0] < this.data[smallest][0]) smallest = l;
                if (r < this.data.length && this.data[r][0] < this.data[smallest][0]) smallest = r;
                if (smallest === i) break;
                [this.data[i], this.data[smallest]] = [this.data[smallest], this.data[i]];
                i = smallest;
            }
        }
        return top;
    }
    get size() { return this.data.length; }
}

function combinations(arr, k) {
    const result = [];
    function backtrack(start, cur) {
        if (cur.length === k) { result.push(cur.slice()); return; }
        for (let i = start; i < arr.length; i++) {
            cur.push(arr[i]);
            backtrack(i+1, cur);
            cur.pop();
        }
    }
    backtrack(0, []);
    return result;
}

var minTime = function(n, k, m, time, mul) {
    const FULL = (1 << n) - 1;
    const dist = [];
    for (let mask = 0; mask <= FULL; mask++) {
        dist.push([new Array(m).fill(Infinity), new Array(m).fill(Infinity)]);
    }
    dist[FULL][0][0] = 0.0;
    const pq = new MinHeap();
    pq.push([0.0, FULL, 0, 0]);
    const EPS = 1e-9;
    while (pq.size > 0) {
        const [cost, remaining, direction, stage] = pq.pop();
        if (cost > dist[remaining][direction][stage] + EPS) continue;
        if (direction === 1 && remaining === 0) return cost;
        if (direction === 0) {
            const people = [];
            for (let i = 0; i < n; i++) if (remaining & (1<<i)) people.push(i);
            for (let sz = 1; sz <= Math.min(k, people.length); sz++) {
                for (const group of combinations(people, sz)) {
                    let gtime = 0;
                    for (const i of group) gtime = Math.max(gtime, time[i]);
                    gtime *= mul[stage];
                    let newRemaining = remaining;
                    for (const i of group) newRemaining &= ~(1<<i);
                    const newStage = (stage + Math.floor(gtime)) % m;
                    const newCost = cost + gtime;
                    if (newCost < dist[newRemaining][1][newStage] - EPS) {
                        dist[newRemaining][1][newStage] = newCost;
                        pq.push([newCost, newRemaining, 1, newStage]);
                    }
                }
            }
        } else {
            for (let i = 0; i < n; i++) {
                if (!(remaining & (1<<i))) {
                    const rtime = time[i] * mul[stage];
                    const newRemaining = remaining | (1<<i);
                    const newStage = (stage + Math.floor(rtime)) % m;
                    const newCost = cost + rtime;
                    if (newCost < dist[newRemaining][0][newStage] - EPS) {
                        dist[newRemaining][0][newStage] = newCost;
                        pq.push([newCost, newRemaining, 0, newStage]);
                    }
                }
            }
        }
    }
    return -1.0;
};

function hasPrimeFrequency(nums) {
    const freq = new Map();
    for (const v of nums) {
        freq.set(v, (freq.get(v) || 0) + 1);
    }

    // iterate over each distinct element's count and test for primality
    for (const count of freq.values()) {
        if (isPrime(count)) return true;
    }
    return false;
}

function isPrime(num) {
    if (num <= 1) return false;
    if (num === 2) return true;
    if (num % 2 === 0) return false;
    const limit = Math.floor(Math.sqrt(num));
    for (let i = 3; i <= limit; i += 2) {
        if (num % i === 0) return false;
    }
    return true;
}

