function findCoins(numWays) {
    const n = numWays.length;
    const dp = new Array(n+1).fill(0);
    dp[0] = 1;
    const coins = [];
    for (let amount = 1; amount <= n; amount++) {
        if (dp[amount] === numWays[amount-1]) continue;
        if (dp[amount] + 1 !== numWays[amount-1]) return [];
        coins.push(amount);
        for (let a = amount; a <= n; a++) dp[a] += dp[a-amount];
    }
    for (let amount = 1; amount <= n; amount++) if (dp[amount] !== numWays[amount-1]) return [];
    return coins;
}

function minNodesToIncrease(n, edges, cost) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
