    const children = Array.from({ length: n }, () => []);
    const parent = new Array(n).fill(-1);
    const order = [];

    const stack = [0];
    parent[0] = 0;
    while (stack.length) {
        const node = stack.pop();
        order.push(node);
        for (const nb of adj[node]) {
            if (nb === parent[node]) continue;
            parent[nb] = node;
            children[node].push(nb);
            stack.push(nb);
        }
    }

    const maxSum = new Array(n).fill(0);
    const touches = new Array(n).fill(0);

    for (let i = order.length - 1; i >= 0; i--) {
        const node = order[i];
        const childs = children[node];
        if (childs.length === 0) {
            maxSum[node] = cost[node];
            touches[node] = 0;
        } else {
            let maxChildSum = -Infinity;
            for (const ch of childs) {
                if (maxSum[ch] > maxChildSum) maxChildSum = maxSum[ch];
            }
            let total = 0;
            for (const ch of childs) {
                total += touches[ch];
                if (maxSum[ch] < maxChildSum) total += 1;
            }
            maxSum[node] = cost[node] + maxChildSum;
            touches[node] = total;
        }
    }

    return touches[0];
}

function partitionString(s) {
    const used = new Set();
    const result = [];
    const n = s.length;
    let i = 0;
    while (i < n) {
        let found = false;
        // try to make the shortest possible unique segment starting at i
        for (let j = i; j < n; j++) {
            const seg = s.slice(i, j + 1);
            if (!used.has(seg)) {
                used.add(seg);
                result.push(seg);
                i = j + 1;
                found = true;
                break;
            }
        }
        // if no unique segment can be formed, stop processing
        if (!found) break;
    }
    return result;
}

function longestCommonPrefixBetweenAdjacentStringsAfterRemovals(words) {
    const n = words.length;
    if (n === 1) return [0];

    const lcpLen = (a, b) => {
        const m = Math.min(a.length, b.length);
        let i = 0;
        while (i < m && a[i] === b[i]) i++;
        return i;
    };

    const lcp = new Array(n - 1).fill(0);
    for (let i = 0; i < n - 1; i++) lcp[i] = lcpLen(words[i], words[i + 1]);

    const prefMax = new Array(n - 1).fill(0);
    let cur = 0;
    for (let i = 0; i < n - 1; i++) { cur = Math.max(cur, lcp[i]); prefMax[i] = cur; }

    const suffMax = new Array(n - 1).fill(0);
    cur = 0;
    for (let i = n - 2; i >= 0; i--) { cur = Math.max(cur, lcp[i]); suffMax[i] = cur; }

    const ans = new Array(n).fill(0);
    for (let i = 0; i < n; i++) {
        let maxExcl = 0;
        const leftPair = i - 1;
        const rightPair = i;
        if (leftPair - 1 >= 0) maxExcl = Math.max(maxExcl, prefMax[leftPair - 1]);
        if (rightPair + 1 <= n - 2) maxExcl = Math.max(maxExcl, suffMax[rightPair + 1]);

        let newPair = 0;
        if (i - 1 >= 0 && i + 1 < n) newPair = lcpLen(words[i - 1], words[i + 1]);

        ans[i] = Math.max(maxExcl, newPair);
    }
    return ans;
}

function maxStability(n, edges, k) {
  class DSU {
    constructor(n) { this.p = Array.from({length:n},(_,i)=>i); this.r = new Array(n).fill(0); }
    find(x) { while (this.p[x]!==x) { this.p[x]=this.p[this.p[x]]; x=this.p[x]; } return x; }
    union(a,b) { a=this.find(a); b=this.find(b); if (a===b) return false; if (this.r[a]<this.r[b]) [a,b]=[b,a]; this.p[b]=a; if (this.r[a]===this.r[b]) this.r[a]++; return true; }
  }

  // Step 1: check mandatory edges alone don't form a cycle / are consistent
  const mandatory = edges.filter(e => e[3] === 1);
  const eligible = edges.filter(e => e[3] === 0);
  {
    const dsu = new DSU(n);
    for (const [u,v] of mandatory) {
      if (!dsu.union(u,v)) return -1; // cycle among mandatory edges -> impossible
    }
  }

  let maxStrength = 0;
  for (const e of edges) maxStrength = Math.max(maxStrength, e[2]);

  function feasible(X) {
    const dsu = new DSU(n);
    let components = n;
    // mandatory edges must all individually satisfy strength >= X (can't upgrade)
    for (const [u,v,s] of mandatory) {
      if (s < X) return false;
      if (dsu.union(u,v)) components--;
    }
    // free eligible edges (strength already >= X)
    for (const [u,v,s] of eligible) {
      if (s >= X) {
        if (dsu.union(u,v)) components--;
      }
    }
    if (components === 1) return true;
    // need upgrades: eligible edges with s < X but 2*s >= X
    let used = 0;
    for (const [u,v,s] of eligible) {
      if (s < X && 2*s >= X) {
        if (dsu.find(u) !== dsu.find(v)) {
          if (used >= k) continue;
          if (dsu.union(u,v)) { components--; used++; }
        }
      }
      if (components === 1) break;
    }
    return components === 1;
  }

  // quick connectivity check ignoring X constraint (using ALL edges, upgraded or not) to see if -1 needed
  {
    const dsu = new DSU(n);
    let components = n;
    for (const [u,v] of edges) { if (dsu.union(u,v)) components--; }
    if (components > 1) return -1;
  }

  let lo = 1, hi = 2 * maxStrength;
  let ans = -1;
  while (lo <= hi) {
    const mid = Math.floor((lo+hi)/2);
    if (feasible(mid)) { ans = mid; lo = mid + 1; } else hi = mid - 1;
  }
  return ans;
}

var minXor = function(nums, k) {
    const n = nums.length;
    const pref = new Array(n+1).fill(0);
    for (let i=0;i<n;i++) pref[i+1] = pref[i] ^ nums[i];
    function can(limit) {
        const dp = Array.from({length:n+1}, () => new Set());
        dp[0].add(0);
        for (let i=1;i<=n;i++) {
            const reachable = new Set();
            for (let j=0;j<i;j++) {
                const subXor = pref[i]^pref[j];
                if (subXor <= limit) {
                    for (const cnt of dp[j]) reachable.add(cnt+1);
                }
            }
            dp[i] = reachable;
        }
        return dp[n].has(k);
    }
    let low=0, high=(2**31)-1;
    while (low < high) {
        const mid = Math.floor((low+high)/2);
        if (can(mid)) high = mid;
        else low = mid+1;
    }
    return low;
};

function minCost(m, n, waitCost) {
    const entry = (i, j) => (i + 1) * (j + 1);
    const wait = (i, j) => (i === 0 && j === 0) ? 0 : waitCost[i][j];
    let prev = new Array(n).fill(0);
    let cur = new Array(n).fill(0);
    prev[0] = entry(0, 0);
    for (let j = 1; j < n; j++) prev[j] = prev[j - 1] + wait(0, j - 1) + entry(0, j);
    for (let i = 1; i < m; i++) {
        cur[0] = prev[0] + wait(i - 1, 0) + entry(i, 0);
        for (let j = 1; j < n; j++) {
            const fromLeft = cur[j - 1] + wait(i, j - 1);
            const fromUp = prev[j] + wait(i - 1, j);
            cur[j] = Math.min(fromLeft, fromUp) + entry(i, j);
        }
        [prev, cur] = [cur, prev];
    }
    return prev[n - 1];
}

function convert(n) {
    // compute the required powers
    const square = n * n;
    const cube = square * n;

    // convert each result to the appropriate base and make letters uppercase
    const hex = square.toString(16).toUpperCase();   // base‑16
    const base36 = cube.toString(36).toUpperCase(); // base‑36

    // concatenate the two strings
    return hex + base36;
}

function minimumTimeToReachDestinationInDirectedGraph(n, edges) {
    if (n === 1) return 0;
    const adj = Array.from({length: n}, () => []);
    for (const [u, v, start, end] of edges) adj[u].push([v, start, end]);
    const INF = 1e18;
    const dist = new Array(n).fill(INF);
    dist[0] = 0;
    const target = n - 1;

    const heap = [[0, 0]];
    const push = (item) => { heap.push(item); let i = heap.length - 1; while (i > 0) { const p = (i-1)>>1; if (heap[i][0] < heap[p][0]) { [heap[i],heap[p]]=[heap[p],heap[i]]; i=p; } else break; } };
    const pop = () => { const top = heap[0]; const last = heap.pop(); if (heap.length) { heap[0] = last; let i = 0; while (true) { let l=2*i+1,r=2*i+2,s=i; if (l<heap.length && heap[l][0]<heap[s][0]) s=l; if (r<heap.length && heap[r][0]<heap[s][0]) s=r; if (s===i) break; [heap[i],heap[s]]=[heap[s],heap[i]]; i=s; } } return top; };

    while (heap.length) {
        const [curTime, u] = pop();
        if (curTime !== dist[u]) continue;
        if (u === target) return curTime;
        for (const [v, start, end] of adj[u]) {
            if (curTime > end) continue;
            const depart = curTime < start ? start : curTime;
            const nextTime = depart + 1;
            if (nextTime < dist[v]) { dist[v] = nextTime; push([nextTime, v]); }
        }
    }
    return -1;
}

function validateCoupons(code, businessLine, isActive) {
    const order = {electronics:0, grocery:1, pharmacy:2, restaurant:3};
    const valid = [];
    const codeRe = /^[A-Za-z0-9_]+$/;
    for (let i = 0; i < code.length; i++) {
        if (!code[i] || !codeRe.test(code[i])) continue;
        if (!(businessLine[i] in order)) continue;
        if (!isActive[i]) continue;
        valid.push([code[i], businessLine[i]]);
    }
    valid.sort((a,b) => {
        const oa = order[a[1]], ob = order[b[1]];
        if (oa !== ob) return oa - ob;
        return a[0] < b[0] ? -1 : (a[0] > b[0] ? 1 : 0);
    });
    return valid.map(x => x[0]);
}

var minStable = function(nums, maxC) {
    function gcd(a,b) { while (b!==0) { const t=a%b; a=b; b=t; } return a; }
    function bitLength(x) { let len=0; while (x>0) { x = Math.floor(x/2); len++; } return len; }
    const n = nums.length;
    if (maxC >= n) return 0;
    const log = bitLength(n);
    const st = [nums.slice()];
    for (let k=1;k<log;k++) {
        const span = 1<<(k-1);
        const limit = n - (1<<k) + 1;
        const prev = st[k-1];
        const row = new Array(n).fill(0);
        for (let i=0;i<limit;i++) row[i] = gcd(prev[i], prev[i+span]);
        st.push(row);
    }
    function rangeGcd(l, r) {
        const length = r-l+1;
        const k = bitLength(length)-1;
        return gcd(st[k][l], st[k][r-(1<<k)+1]);
    }
    function feasible(L) {
        let needed = 0, lastSelected = -1;
        for (let i=0; i<n-L; i++) {
            if (rangeGcd(i, i+L) >= 2) {
                if (i > lastSelected) {
                    needed++;
                    if (needed > maxC) return false;
                    lastSelected = i+L;
                }
            }
        }
        return true;
    }
    let low=0, high=n;
    while (low < high) {
        const mid = Math.floor((low+high)/2);
        if (feasible(mid)) high=mid; else low=mid+1;
    }
    return low;
};

function minimumTime(n, edges, k) {
    const parent = [...Array(n).keys()];
    const size = new Array(n).fill(1);
    function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return false;
        if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra; size[ra] += size[rb];
        return true;
    }
    const sorted = edges.slice().sort((a, b) => b[2] - a[2]);
    let comps = n;
    for (const [u, v, t] of sorted) {
        if (union(u, v)) {
            comps -= 1;
            if (comps < k) return t;
        }
    }
    return 0;
}

function minMovesGrid(sx, sy, tx, ty) {
    if (sx === tx && sy === ty) return 0;
    const queue = [];
    const visited = new Set();
    queue.push([sx, sy, 0]);
    visited.add(sx + ',' + sy);
    while (queue.length) {
        const [x, y, d] = queue.shift();
        const m = Math.max(x, y);
        const candidates = [
            [x + m, y],
            [x, y + m]
        ];
        for (const [nx, ny] of candidates) {
            if (nx > tx || ny > ty) continue;
            if (nx === tx && ny === ty) return d + 1;
            const key = nx + ',' + ny;
            if (!visited.has(key)) {
                visited.add(key);
                queue.push([nx, ny, d + 1]);
            }
        }
    }
    return -1;
}

function powerGridMaintenance(c, connections, queries) {
  const parent = new Int32Array(c + 1);
  const rank = new Int32Array(c + 1);
  for (let i = 1; i <= c; i++) parent[i] = i;
  function find(x) {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];
      x = parent[x];
    }
    return x;
  }
  function union(a, b) {
    let ra = find(a), rb = find(b);
    if (ra === rb) return;
    if (rank[ra] < rank[rb]) {
      parent[ra] = rb;
    } else if (rank[ra] > rank[rb]) {
      parent[rb] = ra;
    } else {
      parent[rb] = ra;
      rank[ra]++;
    }
  }
  for (const [u, v] of connections) union(u, v);
  const compNodes = new Array(c + 1);
  for (let i = 1; i <= c; i++) {
    const r = find(i);
    if (!compNodes[r]) compNodes[r] = [];
    compNodes[r].push(i);
  }
  const ptr = new Int32Array(c + 1);
  const online = new Uint8Array(c + 1);
  online.fill(1);
  const ans = [];
  for (const [type, x] of queries) {
    if (type === 2) {
      online[x] = 0;
    } else {
      // A station that is itself online always resolves its own check.
      if (online[x]) {
        ans.push(x);
        continue;
      }
      const r = find(x);
      const arr = compNodes[r];
      let i = ptr[r];
      while (i < arr.length && online[arr[i]] === 0) i++;
      ptr[r] = i;
      if (i === arr.length) ans.push(-1);
      else ans.push(arr[i]);
    }
  }
  return ans;
}

function processStr(s) {
    let result = "";
    for (const c of s) {
        if (c === '*') result = result.slice(0,-1);
        else if (c === '#') result = result + result;
        else if (c === '%') result = result.split('').reverse().join('');
        else result += c;
    }
    return result;
}

function getKthChar(s, k) {
    const n = s.length;
    const len = new Array(n + 1);
    len[0] = 0;
    for (let i = 1; i <= n; i++) {
        const ch = s[i - 1];
        const prev = len[i - 1];
        if (ch >= 'a' && ch <= 'z') {
            len[i] = prev + 1;
        } else if (ch === '*') {
            len[i] = prev > 0 ? prev - 1 : 0;
        } else if (ch === '#') {
            len[i] = prev * 2;
        } else if (ch === '%') {
            len[i] = prev;
        }
    }
    if (k >= len[n]) return '.';
    for (let i = n; i > 0; i--) {
        const ch = s[i - 1];
        const prev = len[i - 1];
        if (ch >= 'a' && ch <= 'z') {
            if (k === prev) return ch;
            // else k stays the same, continue
        } else if (ch === '*') {
            // deletion removes last character, positions unchanged
            // nothing to do
        } else if (ch === '#') {
            if (k >= prev) k = k - prev;
        } else if (ch === '%') {
            k = prev - 1 - k;
        }
    }
    return '.';
}

function minimizeMaximumComponentCost(n, edges, k) {
    if (k >= n) return 0;
    const parent = [...Array(n).keys()];
    const size = new Array(n).fill(1);
    function find(x) { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; }
    function union(a, b) {
        let ra = find(a), rb = find(b);
        if (ra === rb) return false;
        if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
        parent[rb] = ra; size[ra] += size[rb];
        return true;
    }
    const sorted = edges.slice().sort((a, b) => a[2] - b[2]);
    let components = n, answer = 0;
    for (const [u, v, w] of sorted) {
        if (union(u, v)) {
            answer = w;
            components -= 1;
            if (components === k) break;
        }
    }
    return answer;
}

function longestPalindromicPathInGraph(n, edges, label) {
    const adj = Array.from({length: n}, () => []);
    for (const [u, v] of edges) { adj[u].push(v); adj[v].push(u); }

    const maxMask = 1 << n;
    const pairsByMask = Array.from({length: maxMask}, () => new Set());

    for (let i = 0; i < n; i++) pairsByMask[1 << i].add(i + ',' + i);

    for (const [u, v] of edges) {
        if (label[u] === label[v]) {
            const m = (1 << u) | (1 << v);
            pairsByMask[m].add(u + ',' + v);
            pairsByMask[m].add(v + ',' + u);
        }
    }

    const popcount = (x) => { let c = 0; while (x) { c += x & 1; x >>>= 1; } return c; };

    let ans = 1;
    for (let mask = 0; mask < maxMask; mask++) {
        for (const pairStr of pairsByMask[mask]) {
            const [i, j] = pairStr.split(',').map(Number);
            const bits = popcount(mask);
            if (bits > ans) ans = bits;
            for (const u of adj[i]) {
                if ((mask >> u) & 1) continue;
                for (const v of adj[j]) {
                    if ((mask >> v) & 1) continue;
                    if (u === v) continue;
                    if (label[u] !== label[v]) continue;
                    const newMask = mask | (1 << u) | (1 << v);
                    pairsByMask[newMask].add(u + ',' + v);
                }
            }
        }
    }
    return ans;
}

function countIslands(grid, k) {
    const rows = grid.length;
    if (rows === 0) return 0;
    const cols = grid[0].length;
    const visited = Array.from({ length: rows }, () => Array(cols).fill(false));
    let islandCount = 0;
    const dirs = [
        [1, 0],
        [-1, 0],
        [0, 1],
        [0, -1],
    ];

    for (let r = 0; r < rows; r++) {
        for (let c = 0; c < cols; c++) {
            if (grid[r][c] > 0 && !visited[r][c]) {
                // explore one island and compute its total value
                let sum = 0;
                const stack = [[r, c]];
                visited[r][c] = true;

                while (stack.length) {
                    const [cr, cc] = stack.pop();
                    sum += grid[cr][cc];

                    for (const [dr, dc] of dirs) {
                        const nr = cr + dr;
                        const nc = cc + dc;
                        if (
                            nr >= 0 && nr < rows &&
                            nc >= 0 && nc < cols &&
                            grid[nr][nc] > 0 && !visited[nr][nc]
                        ) {
                            visited[nr][nc] = true;
                            stack.push([nr, nc]);
                        }
                    }
                }

                if (sum % k === 0) islandCount++;
            }
        }
    }

    return islandCount;
}

function maxScore(edges, online, k, n) {
  n = n || online.length;
  const adj = Array.from({length: n}, () => []);
  const indeg = new Array(n).fill(0);
  for (const [u, v, c] of edges) {
    adj[u].push([v, c]);
    indeg[v]++;
  }
  // topo order (Kahn's)
  const topo = [];
  const indegCopy = indeg.slice();
  const queue = [];
  for (let i = 0; i < n; i++) if (indegCopy[i] === 0) queue.push(i);
  let head = 0;
  while (head < queue.length) {
    const u = queue[head++];
    topo.push(u);
    for (const [v] of adj[u]) {
      indegCopy[v]--;
      if (indegCopy[v] === 0) queue.push(v);
    }
  }

  let maxCost = 0;
  for (const [,,c] of edges) maxCost = Math.max(maxCost, c);

  function feasible(X) {
    const INF = Infinity;
    const dist = new Array(n).fill(INF);
    dist[0] = 0;
    for (const u of topo) {
      if (dist[u] === INF) continue;
      if (!online[u] && u !== 0 && u !== n - 1) continue;
      for (const [v, c] of adj[u]) {
        if (c < X) continue;
        if (!online[v]) continue;
        const nd = dist[u] + c;
        if (nd < dist[v]) dist[v] = nd;
      }
    }
    return dist[n-1] !== INF && dist[n-1] <= k;
  }

  if (!feasible(0)) return -1;
  let lo = 0, hi = maxCost, ans = 0;
  while (lo <= hi) {
    const mid = Math.floor((lo+hi)/2);
    if (feasible(mid)) { ans = mid; lo = mid + 1; } else hi = mid - 1;
  }
  return ans;
}

function popcountDepth(n, k) {
    function depth(x) {
        let d = 0;
        while (x !== 1) {
            let c = 0, y = x;
            while (y > 0) { if (y & 1) c++; y >>>= 1; }
            x = c;
            d++;
        }
        return d;
    }
    let count = 0;
    for (let x = 1; x <= n; x++) if (depth(x) === k) count++;
    return count;
}

function isDivisibleBySumAndProduct(n) {
    let sum = 0;
    let product = 1;
    let temp = n;
    while (temp > 0) {
        const digit = temp % 10;
        sum += digit;
        product *= digit;
        temp = Math.floor(temp / 10);
    }
    const total = sum + product; // combine sum and product of digits
    return n % total === 0;
}

function splitArrayByPrimeIndices(nums) {
  const n = nums.length;
  // Sieve to find prime indices up to n‑1
  const isPrime = new Array(n).fill(false);
  if (n > 2) {
    const primeFlag = new Array(n).fill(true);
    primeFlag[0] = primeFlag[1] = false;
    for (let i = 2; i * i < n; i++) {
      if (primeFlag[i]) {
        for (let j = i * i; j < n; j += i) {
          primeFlag[j] = false;
        }
      }
    }
    for (let i = 2; i < n; i++) {
      if (primeFlag[i]) isPrime[i] = true;
    }
  }

  let sumPrime = 0;
  let sumNonPrime = 0;
  // Accumulate sums based on whether the index is prime
  for (let i = 0; i < n; i++) {
    if (isPrime[i]) sumPrime += nums[i];
    else sumNonPrime += nums[i];
  }

  return Math.abs(sumPrime - sumNonPrime);
}

function countNumberOfTrapezoidsI(points) {
    const MOD = 1000000007n;
    const INV2 = (MOD + 1n) / 2n;

    const yCounts = new Map();
    for (const [, y] of points) yCounts.set(y, (yCounts.get(y) || 0) + 1);

    let sumA = 0n, sumASq = 0n;
    for (const c of yCounts.values()) {
        if (c > 1) {
            const a = BigInt(c) * BigInt(c - 1) / 2n;
            const aMod = a % MOD;
            sumA = (sumA + aMod) % MOD;
            sumASq = (sumASq + aMod * aMod) % MOD;
        }
    }

    let ans = ((sumA * sumA - sumASq) % MOD + MOD) % MOD;
    ans = (ans * INV2) % MOD;
    return Number(ans);
}

function numberOfIntegersWithPopcountDepthEqualToKII(nums, queries) {
    class Fenwick {
        constructor(n) { this.n = n; this.bit = new Array(n + 1).fill(0); }
        add(idx, delta) { let i = idx + 1; while (i <= this.n) { this.bit[i] += delta; i += i & -i; } }
        sum(idx) { let i = idx + 1, res = 0; while (i) { res += this.bit[i]; i -= i & -i; } return res; }
        rangeSum(l, r) { if (l > r) return 0; return this.sum(r) - (l ? this.sum(l - 1) : 0); }
    }

    const popcountDepth = (x) => {
        const popcount = (v) => { let c = 0; while (v) { c += v & 1; v >>>= 1; } return c; };
        let d = 0;
        while (x !== 1) { x = popcount(x); d++; }
        return d;
    };

    const n = nums.length;
    const maxDepth = 5;
    const fenwicks = Array.from({length: maxDepth + 1}, () => new Fenwick(n));

    const depths = nums.map(v => popcountDepth(v));
    depths.forEach((d, i) => fenwicks[d].add(i, 1));

    const ans = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const [, l, r, k] = q;
            if (k >= 0 && k <= maxDepth) ans.push(fenwicks[k].rangeSum(l, r));
            else ans.push(0);
        } else {
            const [, idx, val] = q;
            const oldD = depths[idx];
            const newD = popcountDepth(val);
            if (oldD !== newD) {
                fenwicks[oldD].add(idx, -1);
                fenwicks[newD].add(idx, 1);
                depths[idx] = newD;
            }
            nums[idx] = val;
        }
    }
    return ans;
}

function countNumberOfTrapezoids(points) {
    const n = points.length;
    const slopeMap = new Map(); // slopeKey -> {total, pointDeg: Map, lineMap: Map}
    const midMap = new Map(); // midpointKey -> count

    function gcd(a, b) {
        while (b !== 0) {
            const t = a % b;
            a = b;
            b = t;
        }
        return a;
    }

    for (let i = 0; i < n; i++) {
        const [xi, yi] = points[i];
        for (let j = i + 1; j < n; j++) {
            const [xj, yj] = points[j];
            let dx = xj - xi;
            let dy = yj - yi;
            const g = gcd(Math.abs(dx), Math.abs(dy));
            dx /= g;
            dy /= g;
            // normalize sign
            if (dx < 0) {
                dx = -dx;
                dy = -dy;
            } else if (dx === 0 && dy < 0) {
                dy = -dy;
            }
            const slopeKey = dy + '/' + dx;

            // line identifier using dy*x - dx*y = c
            const c = dy * xi - dx * yi;
            const lineKey = slopeKey + '/' + c;

            // midpoint for parallelogram counting
            const midKey = (xi + xj) + ',' + (yi + yj);
            midMap.set(midKey, (midMap.get(midKey) || 0) + 1);

            // update slope map
            let slopeEntry = slopeMap.get(slopeKey);
            if (!slopeEntry) {
                slopeEntry = {
                    total: 0,
                    pointDeg: new Map(),
                    lineMap: new Map()
                };
                slopeMap.set(slopeKey, slopeEntry);
            }
            slopeEntry.total++;

            // point degrees for this slope
            slopeEntry.pointDeg.set(i, (slopeEntry.pointDeg.get(i) || 0) + 1);
            slopeEntry.pointDeg.set(j, (slopeEntry.pointDeg.get(j) || 0) + 1);

            // line map within this slope
            let lineEntry = slopeEntry.lineMap.get(lineKey);
            if (!lineEntry) {
                lineEntry = {
                    count: 0,
                    pointDegLine: new Map()
                };
                slopeEntry.lineMap.set(lineKey, lineEntry);
            }
            lineEntry.count++;
            lineEntry.pointDegLine.set(i, (lineEntry.pointDegLine.get(i) || 0) + 1);
            lineEntry.pointDegLine.set(j, (lineEntry.pointDegLine.get(j) || 0) + 1);
        }
    }

    // count trapezoids based on parallel side pairs
    let trapezoidPairs = 0;
    for (const slopeEntry of slopeMap.values()) {
        const m = slopeEntry.total;
        const totalPairs = m * (m - 1) / 2;

        // pairs sharing a point
        let sharePoint = 0;
        for (const deg of slopeEntry.pointDeg.values()) {
            sharePoint += deg * (deg - 1) / 2;
        }

        // pairs on the same line
        let sameLinePairs = 0;
        let sameLineSharePoint = 0;
        for (const lineEntry of slopeEntry.lineMap.values()) {
            const t = lineEntry.count;
            sameLinePairs += t * (t - 1) / 2;
            for (const degL of lineEntry.pointDegLine.values()) {
                sameLineSharePoint += degL * (degL - 1) / 2;
            }
        }

        const valid = totalPairs - sharePoint - sameLinePairs + sameLineSharePoint;
        trapezoidPairs += valid;
    }

    // count parallelograms (each counted twice above)
    let parallelogramCount = 0;
    for (const cnt of midMap.values()) {
        if (cnt > 1) {
            parallelogramCount += cnt * (cnt - 1) / 2;
        }
    }

    const result = trapezoidPairs - parallelogramCount;
    return result;
}

function maxMedianSum(nums) {
    // sort to arrange numbers so that larger medians can be chosen
    nums.sort((a, b) => a - b);

    const n = nums.length;
    const groups = n / 3;          // number of triples
    let sum = 0;

    // pick the median of each triple: start from the second‑largest element,
    // then skip one element each time (the largest of the current triple)
    for (let i = n - 2; i >= groups; i -= 2) {
        sum += nums[i];
    }
    return sum;
}

function maxLCT(s) {
    const n = s.length;
    const prefixL = new Array(n + 1).fill(0);   // L count before each position
    const prefixLC = new Array(n + 1).fill(0);  // LC subsequences before each position
    const suffixT = new Array(n + 1).fill(0);   // T count after each position
    const suffixCT = new Array(n + 1).fill(0);  // CT pairs after each position

    // build prefix arrays
    let cntL = 0, cntLC = 0;
    for (let i = 0; i < n; i++) {
        prefixL[i] = cntL;
        prefixLC[i] = cntLC;
        const ch = s[i];
        if (ch === 'L') cntL++;
        else if (ch === 'C') cntLC += cntL;   // each earlier L forms an LC pair
    }
    prefixL[n] = cntL;
    prefixLC[n] = cntLC;

    // build suffix arrays
    let cntT = 0, cntCT = 0;
    for (let i = n - 1; i >= 0; i--) {
        suffixT[i + 1] = cntT;
        suffixCT[i + 1] = cntCT;
        const ch = s[i];
        if (ch === 'T') cntT++;
        else if (ch === 'C') cntCT += cntT;   // each later T forms a CT pair
    }
    suffixT[0] = cntT;
    suffixCT[0] = cntCT;

    // original number of "LCT" subsequences
    let original = 0;
    for (let i = 0; i < n; i++) {
        if (s[i] === 'C') original += prefixL[i] * suffixT[i + 1];
    }

    // evaluate best insertion
    let bestInc = 0;
    for (let i = 0; i <= n; i++) {
        const incL = suffixCT[i];                     // insert 'L' at i
        if (incL > bestInc) bestInc = incL;
        const incT = prefixLC[i];                     // insert 'T' at i
        if (incT > bestInc) bestInc = incT;
        const incC = prefixL[i] * suffixT[i];         // insert 'C' at i
        if (incC > bestInc) bestInc = incC;
    }

    return original + bestInc;
}

var minJumps = function(nums) {
    const n = nums.length;
    if (n <= 1) return 0;
    const maxVal = Math.max(...nums);
    const spf = new Array(maxVal+1).fill(0);
    for (let i=2;i<=maxVal;i++) {
        if (spf[i] === 0) {
            spf[i] = i;
            if (i*i <= maxVal) {
                for (let j=i*i;j<=maxVal;j+=i) {
                    if (spf[j]===0) spf[j]=i;
                }
            }
        }
    }
    const primeToIndices = new Map();
    for (let idx=0; idx<n; idx++) {
        let x = nums[idx];
        const facsSet = new Set();
        while (x > 1) {
            const p = spf[x] !== 0 ? spf[x] : x;
            facsSet.add(p);
            while (x % p === 0) x = Math.floor(x/p);
        }
        for (const p of facsSet) {
            if (!primeToIndices.has(p)) primeToIndices.set(p, []);
            primeToIndices.get(p).push(idx);
        }
    }
    function isPrime(v) { return v > 1 && spf[v] === v; }
    const dist = new Array(n).fill(-1);
    const q = [0];
    dist[0] = 0;
    let head = 0;
    while (head < q.length) {
        const cur = q[head++];
        const curDist = dist[cur];
        if (cur === n-1) return curDist;
        for (const nxt of [cur-1, cur+1]) {
            if (nxt>=0 && nxt<n && dist[nxt]===-1) {
                dist[nxt] = curDist+1;
                q.push(nxt);
            }
        }
        if (isPrime(nums[cur])) {
            const p = nums[cur];
            const lst = primeToIndices.get(p) || [];
            for (const nxt of lst) {
                if (dist[nxt] === -1) {
                    dist[nxt] = curDist+1;
                    q.push(nxt);
                }
            }
            primeToIndices.set(p, []);
        }
    }
    return -1;
};

function maxXorAndPartition(nums) {
    const n = nums.length;
    const full = 1 << n;
    const BITS = 30;

    // basis[mask] = Int32Array(BITS) linear basis (echelon form) of elements at set-bit positions of mask
    const basis = new Array(full);
    const totalXor = new Int32Array(full);
    const andVal = new Int32Array(full); // AND of elements in mask (mask!=0); andVal[0] unused (empty => sentinel)
    basis[0] = new Int32Array(BITS);
    totalXor[0] = 0;
    andVal[0] = -1; // all bits set, identity for AND, empty set sentinel

    for (let mask = 1; mask < full; mask++) {
        const low = mask & (-mask);
        const idx = Math.log2(low) | 0;
        const prev = mask ^ low;
        totalXor[mask] = totalXor[prev] ^ nums[idx];
        andVal[mask] = andVal[prev] & nums[idx];
        // copy basis from prev, then insert nums[idx]
        const b = basis[prev].slice();
        let v = nums[idx];
        for (let bit = BITS - 1; bit >= 0 && v; bit--) {
            if (!((v >> bit) & 1)) continue;
            if (b[bit] === 0) { b[bit] = v; break; }
            v ^= b[bit];
        }
        basis[mask] = b;
    }

    function bestXorSum(mask) {
        if (mask === 0) return 0; // both A and C empty
        const X = totalXor[mask];
        const b = basis[mask];
        let a = 0;
        for (let bit = BITS - 1; bit >= 0; bit--) {
            if (b[bit] === 0) continue;
            const isXBitZero = ((X >> bit) & 1) === 0;
            if (isXBitZero && !((a >> bit) & 1)) {
                a ^= b[bit];
            }
        }
        return a + (a ^ X);
    }

    let answer = 0;
    for (let B = 0; B < full; B++) {
        const S = (full - 1) ^ B;
        const andB = (B === 0) ? 0 : andVal[B];
        const cand = andB + bestXorSum(S);
        if (cand > answer) answer = cand;
    }
    return answer;
}

function minRemovals(nums, k) {
    // sort to bring potential balanced elements together
    nums.sort((a, b) => a - b);
    const n = nums.length;
    let left = 0;
    let best = 0;

    // slide a window where max <= k * min
    for (let right = 0; right < n; right++) {
        while (nums[right] > k * nums[left]) {
            left++;                     // shrink from the left until condition holds
        }
        const windowSize = right - left + 1;
        if (windowSize > best) best = windowSize;
    }

    // elements to delete = total - size of largest balanced subset
    return n - best;
}

function earliestFinishTimeForLandAndWaterRidesII(landStartTime, landDuration, waterStartTime, waterDuration) {
    const INF = 1e18;

    const bisectLeft = (arr, val) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo + hi) >> 1; if (arr[mid] < val) lo = mid + 1; else hi = mid; }
        return lo;
    };

    const helper = (firstStarts, firstDurs, secondStarts, secondDurs) => {
        if (!firstStarts.length || !secondStarts.length) return INF;

        const paired = secondStarts.map((s, i) => [s, secondDurs[i]]).sort((a, b) => a[0] - b[0]);
        const secStarts = paired.map(p => p[0]);
        const secEnds = paired.map(p => p[0] + p[1]);
        const secDurs = paired.map(p => p[1]);
        const n = secStarts.length;

        const suffixMinEnd = new Array(n).fill(INF);
        let cur = INF;
        for (let i = n - 1; i >= 0; i--) { cur = Math.min(cur, secEnds[i]); suffixMinEnd[i] = cur; }

        const prefixMinDur = new Array(n).fill(INF);
        cur = INF;
        for (let i = 0; i < n; i++) { cur = Math.min(cur, secDurs[i]); prefixMinDur[i] = cur; }

        let best = INF;
        for (let i = 0; i < firstStarts.length; i++) {
            const s = firstStarts[i], d = firstDurs[i];
            const finishFirst = s + d;
            const idx = bisectLeft(secStarts, finishFirst);
            if (idx < n) best = Math.min(best, suffixMinEnd[idx]);
            if (idx > 0) best = Math.min(best, finishFirst + prefixMinDur[idx - 1]);
        }
        return best;
    };

    const ans = Math.min(
        helper(landStartTime, landDuration, waterStartTime, waterDuration),
        helper(waterStartTime, waterDuration, landStartTime, landDuration)
    );
    return ans === INF ? -1 : ans;
}

function earliestFinishTime(landStartTime, landDuration, waterStartTime, waterDuration) {
    let best = Infinity;
    for (let i = 0; i < landStartTime.length; i++) {
        const endLand = landStartTime[i] + landDuration[i];
        for (let j = 0; j < waterStartTime.length; j++) {
            best = Math.min(best, Math.max(endLand, waterStartTime[j]) + waterDuration[j]);
        }
    }
    for (let j = 0; j < waterStartTime.length; j++) {
        const endW = waterStartTime[j] + waterDuration[j];
        for (let i = 0; i < landStartTime.length; i++) {
            best = Math.min(best, Math.max(endW, landStartTime[i]) + landDuration[i]);
        }
    }
    return best;
}

function isTrionicArray(nums) {
  const n = nums.length;
  if (n < 3) return false;
  const incPrefix = new Array(n).fill(false);
  incPrefix[0] = true;
  for (let i = 1; i < n; i++) { incPrefix[i] = incPrefix[i - 1] && nums[i - 1] < nums[i]; }
  const incSuffix = new Array(n).fill(false);
  incSuffix[n - 1] = true;
  for (let i = n - 2; i >= 0; i--) { incSuffix[i] = incSuffix[i + 1] && nums[i] < nums[i + 1]; }
  // p must be > 0: the definition requires 0 < p < q < n-1, i.e. a genuine rising
  // segment before the peak, not just a single trivial starting element
  for (let p = 1; p <= n - 3; p++) {
    if (!incPrefix[p]) continue;
    let decreasing = true;
    for (let q = p + 1; q <= n - 2; q++) {
      if (q === p + 1) { decreasing = true; } else { if (nums[q - 1] <= nums[q]) decreasing = false; }
      if (!decreasing) break;
      if (incSuffix[q + 1]) return true;
    }
  }
  return false;
}

function thresholdMajorityQueries(nums, queries) {
    const n = nums.length;
    const pos = new Map();
    nums.forEach((v, i) => { if (!pos.has(v)) pos.set(v, []); pos.get(v).push(i); });

    let size = 1;
    while (size < n) size <<= 1;
    let tree = new Array(2 * size).fill(null).map(() => [0, 0]);

    function combine(a, b) {
        if (a[0] === b[0]) return [a[0], a[1] + b[1]];
        if (a[1] > b[1]) return [a[0], a[1] - b[1]];
        return [b[0], b[1] - a[1]];
    }
    for (let i = 0; i < n; i++) tree[size + i] = [nums[i], 1];
    for (let i = size - 1; i >= 1; i--) tree[i] = combine(tree[i << 1], tree[(i << 1) | 1]);

    function query(l, r) {
        l += size; r += size + 1;
        let leftRes = [0, 0], rightRes = [0, 0];
        while (l < r) {
            if (l & 1) { leftRes = combine(leftRes, tree[l]); l++; }
            if (r & 1) { r--; rightRes = combine(tree[r], rightRes); }
            l >>= 1; r >>= 1;
        }
        return combine(leftRes, rightRes);
    }
    function bisectLeft(arr, x) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (arr[mid] < x) lo = mid+1; else hi = mid; }
        return lo;
    }
    function bisectRight(arr, x) {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const mid = (lo+hi)>>1; if (arr[mid] <= x) lo = mid+1; else hi = mid; }
        return lo;
    }

    const ans = [];
    for (const [l, r, threshold] of queries) {
        const [cand] = query(l, r);
        if (!pos.has(cand)) { ans.push(-1); continue; }
        const lst = pos.get(cand);
        const cnt = bisectRight(lst, r) - bisectLeft(lst, l);
        ans.push(cnt >= threshold ? cand : -1);
    }
    return ans;
}

function maxSumTrionic(nums) {
    const n = nums.length;
    let i = 0;
    let ans = -Infinity;
    while (i < n) {
        const l = i;
        i += 1;
        while (i < n && nums[i - 1] < nums[i]) i += 1; // find maximal increasing run
        if (i === l + 1) continue; // no real increase, need at least 2 elements
        const p = i - 1; // peak
        let s = nums[p - 1] + nums[p]; // minimal valid increasing prefix ending at p
        while (i < n && nums[i - 1] > nums[i]) { s += nums[i]; i += 1; } // decreasing run
        if (i === p + 1 || i === n || nums[i - 1] === nums[i]) continue;
        const q = i - 1; // valley
        s += nums[i];
        i += 1;
        // extend third (increasing) part as far as beneficial
        let mx = 0, t = 0;
        while (i < n && nums[i - 1] < nums[i]) { t += nums[i]; i += 1; mx = Math.max(mx, t); }
        s += mx;
        // extend first part backward from p-2 as far as beneficial
        mx = 0; t = 0;
        let j = p - 2;
        while (j >= l) { t += nums[j]; mx = Math.max(mx, t); j -= 1; }
        s += mx;
        ans = Math.max(ans, s);
        i = q; // restart scan from q (allows overlapping trionic patterns)
    }
    return ans;
}

function minimumTimeToActivateString(s, order, k) {
    const n = s.length;
    const totalSubstrings = n * (n + 1) / 2;
    if (k <= 0) return 0;
    if (k > totalSubstrings) return -1;

    const times = new Array(n).fill(n);
    order.forEach((idx, t) => { times[idx] = t; });

    const goodSubstrings = (t) => {
        let bad = 0, cur = 0;
        for (let i = 0; i < n; i++) {
            if (times[i] > t) cur++;
            else { if (cur) { bad += cur * (cur + 1) / 2; cur = 0; } }
        }
        if (cur) bad += cur * (cur + 1) / 2;
        return totalSubstrings - bad;
    };

    let lo = 0, hi = n - 1, ans = -1;
    while (lo <= hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (goodSubstrings(mid) >= k) { ans = mid; hi = mid - 1; }
        else lo = mid + 1;
    }
    return ans;
}

function maxBalancedShipments(weight) {
    const n = weight.length;
    let i = 0;
    let shipments = 0;

    while (i < n) {
        let maxSoFar = weight[i];
        let j = i + 1;

        // find the earliest j where weight[j] is smaller than a previous max
        while (j < n) {
            if (weight[j] > maxSoFar) {
                maxSoFar = weight[j];
            } else if (weight[j] < maxSoFar) {
                shipments++;          // a balanced shipment ends at j
                break;
            }
            j++;
        }

        if (j === n) break;          // no further balanced shipment possible
        i = j + 1;                    // start next segment after the closed shipment
    }

    return shipments;
}

function maxTotal(value, limit) {
    const n = value.length;
    const arr = value.map((v, i) => [v, limit[i]]);
    arr.sort((a, b) => a[1] - b[1] || b[0] - a[0]);
    const status = new Array(n).fill(0);
    let i = 0, j = 0, active = 0, ans = 0;
    while (j < n) {
        const [val, lmt] = arr[j];
        if (active < lmt) {
            status[j] = 1;
            ans += val;
            active += 1;
            if (active === lmt) {
                while (j < n && arr[j][1] === active) j++;
            } else {
                j++;
            }
        } else {
            j++;
        }
        while (i < j && arr[i][1] <= active) {
            active -= status[i];
            i++;
        }
    }
    return ans;
}

/**
 * Flips a square submatrix of size k located at (row, col) vertically in place.
 *
 * @param {number[][]} matrix - The original n x n matrix.
 * @param {number} row      - Top‑left row index of the submatrix.
 * @param {number} col      - Top‑left column index of the submatrix.
 * @param {number} k        - Size of the square submatrix.
 */
function flipSquareSubmatrixVertically(matrix, row, col, k) {
    // swap rows within the submatrix
    for (let i = 0; i < Math.floor(k / 2); i++) {
        const top = row + i;
        const bottom = row + k - 1 - i;
        for (let j = 0; j < k; j++) {
            const leftIdx = col + j;
            // exchange the two cells
            const temp = matrix[top][leftIdx];
            matrix[top][leftIdx] = matrix[bottom][leftIdx];
            matrix[bottom][leftIdx] = temp;
        }
    }
}

function maxKToSortPermutation(nums) {
    let ans = -1;
    for (let i = 0; i < nums.length; i++) {
        if (nums[i] !== i) {
            ans &= nums[i];
        }
    }
    return Math.max(ans, 0);
}

function minimumSensors(n, m, k) {
    const side = 2 * k + 1;
    const sensorsRow = Math.ceil(n / side);
    const sensorsCol = Math.ceil(m / side);
    return sensorsRow * sensorsCol;
}

function allMultisets() {
    const evenDigits = [2,4,6,8];
    const oddChoices = [null,1,3,5,7,9];
    const result = [];
    const n = evenDigits.length;
    for (let mask = 0; mask < (1<<n); mask++) {
        const combo = [];
        for (let i = 0; i < n; i++) if (mask & (1<<i)) combo.push(evenDigits[i]);
        for (const odd of oddChoices) {
            const digits = combo.slice();
            if (odd) digits.push(odd);
            if (digits.length === 0) continue;
            const counts = {};
            let total = 0;
            for (const d of digits) { counts[d] = d; total += d; }
            result.push({len: total, counts});
        }
    }
    return result;
}

function halfMultiset(counts) {
    const half = {};
    let middle = null;
    for (const d in counts) {
        const c = counts[d];
        if (c % 2 === 1) middle = d;
        half[d] = Math.floor(c/2);
    }
    return {half, middle};
}

function minArrangement(counts) {
    const {half, middle} = halfMultiset(counts);
    let halfDigits = [];
    for (const d of Object.keys(half).sort((a,b)=>a-b)) {
        for (let i=0;i<half[d];i++) halfDigits.push(d);
    }
    halfDigits.sort();
    const prefix = halfDigits.join('');
    const mid = middle !== null ? String(middle) : '';
    return prefix + mid + prefix.split('').reverse().join('');
}

function distinctPermutations(items) {
    // items: array of chars, generate distinct permutations
    items = items.slice().sort();
    const results = [];
    const used = new Array(items.length).fill(false);
    const path = [];
    function backtrack() {
        if (path.length === items.length) {
            results.push(path.join(''));
            return;
        }
        for (let i = 0; i < items.length; i++) {
            if (used[i]) continue;
            if (i > 0 && items[i] === items[i-1] && !used[i-1]) continue;
            used[i] = true;
            path.push(items[i]);
            backtrack();
            path.pop();
            used[i] = false;
        }
    }
    backtrack();
    return results;
}

function bestGreaterArrangement(counts, nStr) {
    const L = Object.values(counts).reduce((a,b)=>a+b,0);
    const {half, middle} = halfMultiset(counts);
    let halfItems = [];
    for (const d of Object.keys(half).sort((a,b)=>a-b)) {
        for (let i=0;i<half[d];i++) halfItems.push(d);
    }
    const perms = halfItems.length > 0 ? distinctPermutations(halfItems) : [''];
    let best = null;
    for (const prefix of perms) {
        const mid = middle !== null ? String(middle) : '';
        const full = prefix + mid + prefix.split('').reverse().join('');
        if (full.length !== L) continue;
        if (full > nStr) {
            if (best === null || full < best) best = full;
        }
    }
    return best;
}

function nextSpecial(n) {
    const nStr = String(n);
    const L0 = nStr.length;
    const multisets = allMultisets();
    const byLen = {};
    for (const {len, counts} of multisets) {
        if (!byLen[len]) byLen[len] = [];
        byLen[len].push(counts);
    }
    if (byLen[L0]) {
        let best = null;
        for (const counts of byLen[L0]) {
            const res = bestGreaterArrangement(counts, nStr);
            if (res !== null && (best === null || res < best)) best = res;
        }
        if (best !== null) return best; // return as string (BigInt-safe)
    }
    const lens = Object.keys(byLen).map(Number).sort((a,b)=>a-b);
    for (const l of lens) {
        if (l <= L0) continue;
        let best = null;
        for (const counts of byLen[l]) {
            const arr = minArrangement(counts);
            if (best === null || arr < best) best = arr;
        }
        return best;
    }
    return null;
}

var nextSpecialPalindrome = function(n) {
