};

var minCost = function(grid, k) {
    const m = grid.length, n = grid[0].length;
    const INF = Infinity;
    const f = Array.from({length: k + 1}, () => Array.from({length: m}, () => new Array(n).fill(INF)));
    f[0][0][0] = 0;
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        if (i > 0) f[0][i][j] = Math.min(f[0][i][j], f[0][i-1][j] + grid[i][j]);
        if (j > 0) f[0][i][j] = Math.min(f[0][i][j], f[0][i][j-1] + grid[i][j]);
    }
    const g = new Map();
    for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
        const v = grid[i][j];
        if (!g.has(v)) g.set(v, []);
        g.get(v).push([i, j]);
    }
    const keys = [...g.keys()].sort((a, b) => b - a);
    for (let t = 1; t <= k; t++) {
        let mn = INF;
        for (const key of keys) {
            const pos = g.get(key);
            for (const [i, j] of pos) mn = Math.min(mn, f[t-1][i][j]);
            for (const [i, j] of pos) f[t][i][j] = mn;
        }
        for (let i = 0; i < m; i++) for (let j = 0; j < n; j++) {
            if (i > 0) f[t][i][j] = Math.min(f[t][i][j], f[t][i-1][j] + grid[i][j]);
            if (j > 0) f[t][i][j] = Math.min(f[t][i][j], f[t][i][j-1] + grid[i][j]);
        }
    }
    let ans = INF;
    for (let t = 0; t <= k; t++) ans = Math.min(ans, f[t][m-1][n-1]);
    return ans;
};

function numberOfPerfectPairs(nums) {
    // brute-force O(n^2): directly check the real "perfect pair" condition
    const n = nums.length;
    let count = 0;
    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const a = nums[i], b = nums[j];
            const mn = Math.min(Math.abs(a - b), Math.abs(a + b));
            const mx = Math.max(Math.abs(a - b), Math.abs(a + b));
            if (mn <= Math.min(Math.abs(a), Math.abs(b)) && mx >= Math.max(Math.abs(a), Math.abs(b))) {
                count++;
            }
        }
    }
    return count;
}

function maxProfit(prices, strategy, k) {
    const n = prices.length;
    const h = Math.floor(k / 2);

    let pOriginal = 0;
    for (let i = 0; i < n; i++) pOriginal += strategy[i] * prices[i];

    let newSeg = 0;
    for (let i = h; i < k; i++) newSeg += prices[i];
    let oldSeg = 0;
    for (let i = 0; i < k; i++) oldSeg += strategy[i] * prices[i];
    let maxDelta = Math.max(0, newSeg - oldSeg);

    for (let j = 1; j <= n - k; j++) {
        oldSeg += -strategy[j-1]*prices[j-1] + strategy[j+k-1]*prices[j+k-1];
        newSeg += -prices[j-1+h] + prices[j+k-1];
        maxDelta = Math.max(maxDelta, newSeg - oldSeg);
    }

    return pOriginal + maxDelta;
}

