function minCostReversal(n, edges) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);       // forward: cost w
        adj[v].push([u, 2 * w]);   // reversed: cost 2*w
    }
    const INF = Infinity;
    const dist = new Array(n).fill(INF);
    dist[0] = 0;
    // simple array-based min-priority queue (fine for correctness-testing scale)
    const pq = [[0, 0]];
    while (pq.length) {
        pq.sort((a, b) => a[0] - b[0]);
        const [d, u] = pq.shift();
        if (d !== dist[u]) continue;
        if (u === n - 1) break;
        for (const [v, w] of adj[u]) {
            const nd = d + w;
            if (nd < dist[v]) {
                dist[v] = nd;
                pq.push([nd, v]);
            }
        }
    }
    return dist[n - 1] === INF ? -1 : dist[n - 1];
}

var xorAfterQueries = function(nums, queries) {
    const MOD = 1000000007n;
    const arr = nums.map(x => BigInt(x));
    for (const [l, r, k, v] of queries) {
        const vv = BigInt(v);
        for (let idx = l; idx <= r; idx += k) {
            arr[idx] = arr[idx] * vv % MOD;
        }
    }
    let x = 0n;
    for (const n of arr) x ^= n;
    return Number(x);
};

function minimumSumAfterDivisibleSumDeletions(nums, k) {
    const totalSum = nums.reduce((a, b) => a + b, 0);
    let pref = 0;
    let dpPrev = 0;
    const best = new Map([[0, 0]]);
    const NEG_INF = -1e30;
    for (const x of nums) {
        pref += x;
        const r = ((pref % k) + k) % k;
        const cand = pref + (best.has(r) ? best.get(r) : NEG_INF);
        let dpCurr = dpPrev;
        if (cand > dpCurr) dpCurr = cand;
        const val = dpCurr - pref;
        if (!best.has(r) || val > best.get(r)) {
            best.set(r, val);
        }
        dpPrev = dpCurr;
    }
    const maxDeleted = dpPrev;
    return totalSum - maxDeleted;
}

function xorAfterQueries(nums, queries) {
    const MOD = 1000000007n;
    const arr = nums.map(BigInt);
    for (const [l, r, k, v] of queries) {
        const bv = BigInt(v);
        for (let idx = l; idx <= r; idx += k) {
            arr[idx] = (arr[idx] * bv) % MOD;
        }
    }
    let ans = 0n;
    for (const x of arr) ans ^= x;
    return Number(ans);
}

function gcdOfOddEvenSums(n) {
    const sumOdd = n * n;
    const sumEven = n * (n + 1);
    let a = sumOdd, b = sumEven;
    while (b !== 0) {
        const temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}

function maxValue(nums) {
    const n = nums.length;
    const ans = new Array(n).fill(0);
    const preMax = new Array(n).fill(0);
    preMax[0] = nums[0];
    for (let i = 1; i < n; i++) preMax[i] = Math.max(preMax[i-1], nums[i]);
    let sufMin = Infinity;
    for (let i = n - 1; i >= 0; i--) {
        ans[i] = preMax[i] > sufMin ? ans[i+1] : preMax[i];
        sufMin = Math.min(sufMin, nums[i]);
    }
    return ans;
}

function maximumWallsDestroyed(robots, distance, walls) {
    const n = robots.length;
    const arr = robots.map((pos, i) => [pos, distance[i]]).sort((a, b) => a[0] - b[0]);
    walls = walls.slice().sort((a, b) => a - b);

    function bisectLeft(arr, target) {
        let lo = 0, hi = arr.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    const memo = new Map();
    function dp(i, j) {
        if (i < 0) return 0;
        const key = i * 2 + j;
        if (memo.has(key)) return memo.get(key);
        const [pos, dist] = arr[i];

        let left = pos - dist;
        if (i > 0) left = Math.max(left, arr[i - 1][0] + 1);
        let l = bisectLeft(walls, left);
        let r = bisectLeft(walls, pos + 1);
        const optLeft = dp(i - 1, 0) + (r - l);

        let right = pos + dist;
        if (i + 1 < n) {
            const [npos, ndist] = arr[i + 1];
            if (j === 0) right = Math.min(right, npos - ndist - 1);
            else right = Math.min(right, npos - 1);
        }
        l = bisectLeft(walls, pos);
        r = bisectLeft(walls, right + 1);
        const optRight = dp(i - 1, 1) + (r - l);

        const res = Math.max(optLeft, optRight);
        memo.set(key, res);
        return res;
    }

    return dp(n - 1, 1);
}

function uniquePaths(grid) {
  const MOD = 1000000007n;
  const n = grid.length, m = grid[0].length;
  const memo = new Map();

  function dp(i, j, direction) {
    // direction: 0 = came from moving down (dx=1,dy=0), 1 = came from moving right (dx=0,dy=1)
    while (i >= 0 && i < n && j >= 0 && j < m && grid[i][j] === 1) {
      direction = 1 - direction;
      if (direction === 0) { i += 1; } else { j += 1; }
    }
    if (i < 0 || i >= n || j < 0 || j >= m) return 0n;
    if (i === n - 1 && j === m - 1) return 1n;
    if (grid[i][j] === 0) {
      const key = i + ',' + j;
      if (memo.has(key)) return memo.get(key);
      const res = (dp(i + 1, j, 0) + dp(i, j + 1, 1)) % MOD;
      memo.set(key, res);
      return res;
    }
    return 0n; // unreachable due to while loop above
  }

  return Number(dp(0, 0, 0) % MOD);
}

function canPartitionKDistinct(arr, k) {
    const n = arr.length;
    if (k <= 0 || n % k !== 0) return false;          // invalid group size or leftover elements

    const groups = n / k;
    const freq = new Map();

    // count occurrences of each value
    for (let i = 0; i < n; i++) {
        const val = arr[i];
        freq.set(val, (freq.get(val) || 0) + 1);
    }

    // check the most frequent element
    let maxFreq = 0;
    for (const count of freq.values()) {
        if (count > maxFreq) maxFreq = count;
    }

    return maxFreq <= groups;                         // each occurrence must fit into a different group
}

function maxScore(cards, x) {
    const P = new Map(), Q = new Map();
    let Z = 0;
    for (const c of cards) {
        if (!c.includes(x)) continue;
        const a = c[0], b = c[1];
        if (a === x && b === x) Z++;
        else if (a === x) P.set(b, (P.get(b) || 0) + 1);
        else if (b === x) Q.set(a, (Q.get(a) || 0) + 1);
    }
    const totalP = [...P.values()].reduce((s, v) => s + v, 0);
    const totalQ = [...Q.values()].reduce((s, v) => s + v, 0);
    const maxP = P.size ? Math.max(...P.values()) : 0;
    const maxQ = Q.size ? Math.max(...Q.values()) : 0;
    const total = totalP + totalQ + Z;
    const bottleneck = Math.max(maxP + maxQ, Z);
    return Math.min(Math.floor(total / 2), total - bottleneck);
}

function findLeastFrequentDigit(num) {
    // Convert the number to a string to iterate over its digits
    const str = String(num);
    const freq = Array(10).fill(0);          // frequency of each digit 0‑9

    // Count occurrences of each digit
    for (let i = 0; i < str.length; i++) {
        const d = str.charCodeAt(i) - 48;    // faster than parseInt for a single digit
        freq[d]++;
    }

    // Find the smallest digit with the minimal non‑zero frequency
    let minCount = Infinity;
    let answer = -1;
    for (let d = 0; d < 10; d++) {
        if (freq[d] > 0 && freq[d] < minCount) {
            minCount = freq[d];
            answer = d;
        }
    }
    return answer;
}

function minOperations(s, k) {
    const n = s.length;
    let cnt0 = 0;
    for (const c of s) if (c === '0') cnt0++;
    const visited = new Array(n + 1).fill(false);
    visited[cnt0] = true;
    let queue = [cnt0];
    let ans = 0;
    while (queue.length > 0) {
        const next = [];
        for (const cur of queue) {
            if (cur === 0) return ans;
            const l = cur + k - 2 * Math.min(cur, k);
            const r = cur + k - 2 * Math.max(k - n + cur, 0);
            for (let v = l; v <= r; v += 2) {
                if (v < 0 || v > n) continue;
                if (!visited[v]) { visited[v] = true; next.push(v); }
            }
        }
        queue = next;
        ans++;
    }
    return -1;
}

function maximumProductOfTwoIntegersWithNoCommonBits(nums) {
    const n = nums.length;
    if (n < 2) return 0;

    const maxVal = Math.max(...nums);
    let B = maxVal === 0 ? 1 : (32 - Math.clz32(maxVal));
    if (B === 0) B = 1;
    const size = 1 << B;
    const allMask = size - 1;

    const best = new Array(size).fill(0);
    const cnt = new Array(size).fill(0);
    for (const x of nums) {
        const m = x;
        if (x > best[m]) best[m] = x;
        cnt[m] = (cnt[m] || 0) + 1;
    }

    const maxSubset = best.slice();
    for (let i = 0; i < B; i++) {
        for (let mask = 0; mask < size; mask++) {
            if (mask & (1 << i)) {
                const sub = mask ^ (1 << i);
                if (maxSubset[sub] > maxSubset[mask]) maxSubset[mask] = maxSubset[sub];
            }
        }
    }

    let answer = 0;
    for (const x of nums) {
        const m = x;
        const complement = allMask ^ m;
        let partner = maxSubset[complement];

        if (partner === x && cnt[m] < 2) continue;

        if (partner > 0) {
            const product = x * partner;
            if (product > answer) answer = product;
        }
    }

    return answer;
}

// LC 3671 - brute-force reference (algo variant): O(2^n) subset enumeration, correct but only for small n
function sumOfBeautifulSubsequencesBrute(nums) {
  const MOD = 1000000007n;
  const n = nums.length;
  function gcdAll(arr) {
    let g = arr[0];
    for (let i = 1; i < arr.length; i++) { let a = g, b = arr[i]; while (b) { [a, b] = [b, a % b]; } g = a; }
    return g;
  }
  const beauty = new Map();
  for (let mask = 1; mask < (1 << n); mask++) {
    const sub = [];
    for (let i = 0; i < n; i++) if (mask & (1 << i)) sub.push(nums[i]);
    let increasing = true;
    for (let i = 1; i < sub.length; i++) if (sub[i] <= sub[i - 1]) { increasing = false; break; }
    if (!increasing) continue;
    const g = gcdAll(sub);
    beauty.set(g, (beauty.get(g) || 0n) + 1n);
  }
  let total = 0n;
  for (const [g, c] of beauty) total = (total + BigInt(g) * c) % MOD;
  return Number(total);
}

