var numberOfRoutes = function(grid, d) {
    const MOD = 1000000007n;
    const n = grid.length, m = grid[0].length;
    let wUp = (d*d - 1 >= 0) ? Math.floor(Math.sqrt(d*d - 1)) : -1;
    const wStay = d;

    let dpUp = new Array(m).fill(0n);
    for (let c = 0; c < m; c++) if (grid[n-1][c] === '.') dpUp[c] = 1n;
    let dpStay = new Array(m).fill(0n);

    for (let r = n-1; r > 0; r--) {
        const preUp = new Array(m+1).fill(0n);
        for (let c = 0; c < m; c++) preUp[c+1] = (preUp[c] + dpUp[c]) % MOD;
        const newStay = new Array(m).fill(0n);
        for (let c = 0; c < m; c++) {
            if (grid[r][c] !== '.') continue;
            const lo = Math.max(0, c-wStay), hi = Math.min(m-1, c+wStay);
            let total = (preUp[hi+1] - preUp[lo] + MOD) % MOD;
            total = (total - dpUp[c] + MOD) % MOD;
            newStay[c] = total;
        }
        dpStay = newStay;

        const combined = new Array(m);
        for (let c = 0; c < m; c++) combined[c] = (dpUp[c] + dpStay[c]) % MOD;
        const preComb = new Array(m+1).fill(0n);
        for (let c = 0; c < m; c++) preComb[c+1] = (preComb[c] + combined[c]) % MOD;

        const newUp = new Array(m).fill(0n);
        for (let c = 0; c < m; c++) {
            if (grid[r-1][c] !== '.' || wUp < 0) continue;
            const lo = Math.max(0, c-wUp), hi = Math.min(m-1, c+wUp);
            newUp[c] = (preComb[hi+1] - preComb[lo]) % MOD;
        }
        dpUp = newUp;
        dpStay = new Array(m).fill(0n);
    }

    const preUp0 = new Array(m+1).fill(0n);
    for (let c = 0; c < m; c++) preUp0[c+1] = (preUp0[c] + dpUp[c]) % MOD;
    const dpStay0 = new Array(m).fill(0n);
    for (let c = 0; c < m; c++) {
        if (grid[0][c] !== '.') continue;
        const lo = Math.max(0, c-wStay), hi = Math.min(m-1, c+wStay);
        let total = (preUp0[hi+1] - preUp0[lo] + MOD) % MOD;
        dpStay0[c] = (total - dpUp[c] + MOD) % MOD;
    }

    let ans = 0n;
    for (let c = 0; c < m; c++) ans = (ans + dpUp[c] + dpStay0[c]) % MOD;
    return Number(ans);
};

