function minSubarrayLength(arr, K) {
    let left = 0;
    let distinctSum = 0;                 // sum of values that appear at least once in the window
    const freq = new Map();              // value → count inside current window
    let best = Infinity;

    for (let right = 0; right < arr.length; right++) {
        const val = arr[right];
        const cnt = freq.get(val) || 0;
        freq.set(val, cnt + 1);
        if (cnt === 0) distinctSum += val;   // first occurrence adds to distinct sum

        // shrink while we already satisfy the requirement
        while (distinctSum >= K) {
            best = Math.min(best, right - left + 1);
            const leftVal = arr[left];
            const leftCnt = freq.get(leftVal);
            if (leftCnt === 1) distinctSum -= leftVal; // removing last occurrence
            if (leftCnt === 1) freq.delete(leftVal);
