    for (let i = 1; i < n; i++) a[i] = Math.min(a[i], a[i-1] + diff[i-1]);
    for (let i = n-2; i >= 0; i--) a[i] = Math.min(a[i], a[i+1] + diff[i]);
    return Math.max(...a);
}

var minCost = function(lists) {
    const n = lists.length;
    const full = 1 << n;
    const sortedArr = new Array(full);
    sortedArr[0] = [];
    for (let mask = 1; mask < full; mask++) {
        const low = mask & (-mask);
        const idx = Math.log2(low);
        const a = sortedArr[mask ^ low];
        const b = lists[idx];
        const merged = [];
        let i = 0, j = 0;
        while (i < a.length && j < b.length) {
            if (a[i] <= b[j]) merged.push(a[i++]);
            else merged.push(b[j++]);
        }
        while (i < a.length) merged.push(a[i++]);
        while (j < b.length) merged.push(b[j++]);
        sortedArr[mask] = merged;
    }
    const INF = Infinity;
    const dp = new Array(full).fill(0);
    for (let mask = 1; mask < full; mask++) {
        if ((mask & (mask - 1)) === 0) { dp[mask] = 0; continue; }
        let best = INF;
        for (let sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
            const comp = mask ^ sub;
            if (comp === 0) continue;
            const A = sortedArr[sub], B = sortedArr[comp];
            const medA = A[Math.floor((A.length - 1) / 2)];
            const medB = B[Math.floor((B.length - 1) / 2)];
            const cost = dp[sub] + dp[comp] + A.length + B.length + Math.abs(medA - medB);
            if (cost < best) best = cost;
        }
