function maxCapacity(costs, capacity, budget) {
    const n = costs.length;
    const arr = [];
    for (let i = 0; i < n; i++) if (costs[i] < budget) arr.push([costs[i], capacity[i]]);
    if (arr.length === 0) return 0;
    arr.sort((a, b) => a[0] - b[0]);
    const m = arr.length;
    let ans = Math.max(...arr.map(x => x[1]));
    const LOG = Math.max(1, Math.ceil(Math.log2(m + 1)));
    const sparse = Array.from({length: LOG}, () => new Array(m).fill(0));
    for (let i = 0; i < m; i++) sparse[0][i] = arr[i][1];
    for (let j = 1; (1 << j) <= m; j++) {
        const half = 1 << (j - 1);
        for (let i = 0; i + (1 << j) <= m; i++) sparse[j][i] = Math.max(sparse[j-1][i], sparse[j-1][i+half]);
    }
    function query(l, r) {
        if (l > r) return -Infinity;
        const length = r - l + 1;
        const k = Math.floor(Math.log2(length));
        return Math.max(sparse[k][l], sparse[k][r - (1 << k) + 1]);
    }
    let hi = m - 1;
    for (let i = 0; i < m; i++) {
        if (hi < i) hi = i;
        while (hi > i && arr[i][0] + arr[hi][0] >= budget) hi--;
        if (hi > i) {
            const bp = query(i + 1, hi);
            if (bp !== -Infinity) ans = Math.max(ans, arr[i][1] + bp);
        }
    }
    return ans;
}

