  function rec(start, partsLeft, acc) {
    if (partsLeft === 0) {
      if (start === n) best = Math.min(best, acc);
      return;
    }
    if (start >= n) return;
    let sum = 0;
    for (let end = start; end < n; end++) {
      sum += nums[end];
      // remaining elements must be enough for partsLeft-1 more parts
      if (n - (end+1) < partsLeft - 1) continue;
      rec(end+1, partsLeft-1, acc + value(sum));
    }
  }
  rec(0, k, 0);
  return best;
}

