function gcd(a, b) { while (b) { [a, b] = [b, a % b]; } return a; }
function check(nums, p) {
    const n = nums.length;
    const filtered = [];
    for (let i = 0; i < n; i++) if (nums[i] % p === 0) filtered.push(nums[i] / p);
    if (filtered.length === 0) return false;
    if (filtered.length < n) {
        let g = 0;
        for (const v of filtered) g = gcd(g, v);
        return g === 1;
    } else {
        const vals = filtered;
        const pre = new Array(n + 1).fill(0);
        for (let i = 0; i < n; i++) pre[i + 1] = gcd(pre[i], vals[i]);
        const suf = new Array(n + 1).fill(0);
        for (let i = n - 1; i >= 0; i--) suf[i] = gcd(suf[i + 1], vals[i]);
        for (let i = 0; i < n; i++) if (gcd(pre[i], suf[i + 1]) === 1) return true;
        return false;
    }
}
function goodSubsequences(nums, p, queries) {
    nums = nums.slice();
    let ans = 0;
    for (const [idx, val] of queries) {
        nums[idx] = val;
        if (check(nums, p)) ans++;
    }
    return ans;
}

function trafficSignal(timer) {
    if (timer === 0) return "Green";
    if (timer === 30) return "Orange";
    if (timer > 30 && timer <= 90) return "Red";
    return "Invalid";
}

function maxValue(nums1, nums0) {
    const n = nums1.length;
    const blocks = [];
    for (let i = 0; i < n; i++) blocks.push('1'.repeat(nums1[i]) + '0'.repeat(nums0[i]));
    blocks.sort((a, b) => {
        const ab = a + b, ba = b + a;
        if (ab > ba) return -1;
        if (ab < ba) return 1;
        return 0;
    });
    const MOD = 1000000007n;
    let val = 0n;
    for (const block of blocks) {
        for (const c of block) {
            val = (val * 2n + BigInt(c === '1' ? 1 : 0)) % MOD;
        }
    }
    return Number(val);
}

function findVertexDegrees(adjMatrix) {
    const n = adjMatrix.length;
    const degrees = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        let degree = 0;
        for (let j = 0; j < n; j++) {
            degree += adjMatrix[i][j];          // count edges from i to j
        }
        // a self‑loop contributes two to the degree
        if (adjMatrix[i][i] === 1) degree += 1;
        degrees[i] = degree;
    }

    return degrees;
}

function triangleAngles(sides) {
    if (sides.length !== 3) return [];
    const s = sides.slice().sort((x, y) => x - y);
    const [a, b, c] = s;
    if (a <= 0 || a + b <= c) return [];
    const clamp = v => Math.max(-1, Math.min(1, v));
    const toDeg = r => r * 180 / Math.PI;
    const angleOpp = (opp, s1, s2) => Math.round(toDeg(Math.acos(clamp((s1*s1 + s2*s2 - opp*opp) / (2*s1*s2)))) * 10000) / 10000;
    return [angleOpp(a, b, c), angleOpp(b, a, c), angleOpp(c, a, b)];
}

function longestBalancedAfterOneSwap(s) {
    let open = 0, close = 0;
    for (let ch of s) {
        if (ch === '0') open++;
        else if (ch === '1') close++;
    }
    return 2 * Math.min(open, close);
}

function multiSourceFloodFill(rows, cols, sources) {
    const result = Array.from({ length: rows }, () => new Array(cols).fill(0));
    const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));
    // min-heap keyed by [dist, -value] using a simple binary heap
    const heap = [];
    function push(item) { heap.push(item); let i = heap.length - 1;
        while (i > 0) { const p = (i - 1) >> 1;
            if (heap[p][0] > heap[i][0] || (heap[p][0] === heap[i][0] && heap[p][1] > heap[i][1])) { [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; } else break; } }
    function pop() { const top = heap[0]; const last = heap.pop();
        if (heap.length) { heap[0] = last; let i = 0;
            while (true) { let l = 2*i+1, r = 2*i+2, s = i;
                if (l < heap.length && (heap[l][0] < heap[s][0] || (heap[l][0]===heap[s][0]&&heap[l][1]<heap[s][1]))) s = l;
                if (r < heap.length && (heap[r][0] < heap[s][0] || (heap[r][0]===heap[s][0]&&heap[r][1]<heap[s][1]))) s = r;
                if (s === i) break; [heap[s], heap[i]] = [heap[i], heap[s]]; i = s; } }
        return top; }
    for (const [r, c, v] of sources) push([0, -v, r, c]);
    const dirs = [[1,0],[-1,0],[0,1],[0,-1]];
    while (heap.length) {
        const [dist, negV, r, c] = pop();
        if (visited[r][c]) continue;
        visited[r][c] = true;
        result[r][c] = -negV;
        for (const [dr, dc] of dirs) {
            const nr = r + dr, nc = c + dc;
            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc]) push([dist + 1, negV, nr, nc]);
        }
    }
    return result;
}

function firstStableIndex(nums, k) {
    const n = nums.length;
    const right = new Array(n).fill(nums[n - 1]);
    for (let i = n - 2; i >= 0; i--) right[i] = Math.min(right[i + 1], nums[i]);
    let left = -Infinity;
    for (let i = 0; i < n; i++) {
        left = Math.max(left, nums[i]);
        if (left - right[i] <= k) return i;
    }
    return -1;
}

function smallestStableIndex(nums, k) {
    const n = nums.length;
    const prefixMax = new Array(n);
    prefixMax[0] = nums[0];
    for (let i = 1; i < n; i++) prefixMax[i] = Math.max(prefixMax[i - 1], nums[i]);
    const suffixMin = new Array(n);
    suffixMin[n - 1] = nums[n - 1];
    for (let i = n - 2; i >= 0; i--) suffixMin[i] = Math.min(suffixMin[i + 1], nums[i]);
    for (let i = 0; i < n; i++) if (prefixMax[i] - suffixMin[i] <= k) return i;
    return -1;
}

/**
 * Counts the connected subgraphs whose node values sum to an even number.
 *
 * @param {number[]} values - values[i] is the value of vertex i (0‑based)
 * @param {number[][]} edges - each edge is a two‑element array [u, v]
 * @return {number} number of connected subgraphs with even node sum
 */
function countEvenConnectedSubgraphs(values, edges) {
    const n = values.length;
    // build adjacency list
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }

    // pre‑compute sum for every mask using DP: sum[mask] = sum[mask without LSB] + value[lsb]
    const sum = new Uint32Array(1 << n);
    for (let mask = 1; mask < (1 << n); ++mask) {
        const lsb = mask & -mask;                     // lowest set bit
        const idx = Math.clz32(lsb) ^ 31;             // index of that bit (0‑based)
        sum[mask] = sum[mask ^ lsb] + values[idx];
    }

    let answer = 0;
    const visited = new Uint8Array(n);                // reused for every BFS

    // enumerate all non‑empty subsets
    for (let mask = 1; mask < (1 << n); ++mask) {
        if ((sum[mask] & 1) === 1) continue;          // MAIN LOGIC: skip odd sums

        // find any vertex inside the mask to start BFS
        let start = 0;
        while (((mask >> start) & 1) === 0) ++start;

        // BFS limited to vertices present in mask
        const queue = [start];
        visited.fill(0);
        visited[start] = 1;
        let visitedCount = 0;

        while (queue.length) {
            const v = queue.pop();
            ++visitedCount;
            for (const nb of adj[v]) {
                if (visited[nb]) continue;
                if ((mask >> nb) & 1) {               // only walk inside the subset
                    visited[nb] = 1;
                    queue.push(nb);
                }
            }
        }

        // MAIN LOGIC: if all vertices of the mask were reached, the subset is connected
        if (visitedCount === popcount(mask)) ++answer;
    }

    return answer;
}

/* helper: count set bits of a mask */
function popcount(x) {
    // Kernighan's method
    let cnt = 0;
    while (x) {
        x &= x - 1;
        ++cnt;
    }
    return cnt;
}



