function minGenerations(points, target) {
    const targetKey = target.join(',');
    let pointSet = new Set(points.map(p => p.join(',')));
    if (pointSet.has(targetKey)) return 0;
    for (let gen = 1; gen <= 40; gen++) {
        const pts = Array.from(pointSet).map(s => s.split(',').map(Number));
        const newPoints = new Set();
        const n = pts.length;
        for (let i = 0; i < n; i++) {
            for (let j = i + 1; j < n; j++) {
                const a = pts[i], b = pts[j];
                const avg = a.map((v, k) => Math.floor((v + b[k]) / 2));
                newPoints.add(avg.join(','));
            }
        }
        let addedNew = false;
        for (const p of newPoints) if (!pointSet.has(p)) { pointSet.add(p); addedNew = true; }
        if (pointSet.has(targetKey)) return gen;
        if (!addedNew) break;
    }
    return -1;
}

var countWordOccurrences = function(chunks, queries) {
    const s = chunks.join("");
    const n = s.length;
    const cnt = new Map();
    let i = 0;
    while (i < n) {
        const c = s[i];
        if (c === ' ' || c === '-') { i++; continue; }
        let j = i;
        while (j < n) {
            const cj = s[j];
            if (cj === ' ') break;
            if (cj === '-') {
                const isLower = ch => ch >= 'a' && ch <= 'z';
                const joiner = (j > i) && isLower(s[j-1]) && (j+1 < n) && isLower(s[j+1]);
                if (!joiner) break;
            }
            j++;
        }
        const word = s.substring(i, j);
        cnt.set(word, (cnt.get(word) || 0) + 1);
        i = j;
    }
    return queries.map(q => cnt.get(q) || 0);
};

function minimumThresholdPath(n, edges, s, t, K) {
    const adj = Array.from({ length: n }, () => []);
    const weights = new Set();
    for (const [u, v, w] of edges) {
        adj[u].push([v, w]);
        adj[v].push([u, w]);
        weights.add(w);
    }
    let uniq = Array.from(weights).sort((a, b) => a - b);
    if (uniq.length === 0 || uniq[0] > 0) uniq = [0, ...uniq];
    function feasible(limit) {
        const dist = new Array(n).fill(Infinity);
        const deque = [];
        dist[s] = 0;
        deque.push(s);
        while (deque.length) {
            const u = deque.shift();
            for (const [v, w] of adj[u]) {
                const cost = w > limit ? 1 : 0;
                const nd = dist[u] + cost;
                if (nd < dist[v] && nd <= K) {
                    dist[v] = nd;
                    if (cost === 0) deque.unshift(v);
                    else deque.push(v);
                }
            }
        }
        return dist[t] <= K;
    }
    let lo = 0, hi = uniq.length - 1, ans = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        const thr = uniq[mid];
        if (feasible(thr)) { ans = thr; hi = mid - 1; }
        else lo = mid + 1;
    }
    return ans;
}

function minimizeArraySum(arr) {
    const n = arr.length;
    if (n === 0) return 0;

    // find the maximum value to size auxiliary arrays
    const maxVal = Math.max(...arr);

    // mark which numbers actually appear in the array
    const exists = new Uint8Array(maxVal + 1);
    for (const v of arr) exists[v] = 1;

    // sentinel must fit in Int32Array; maxVal + 1 is larger than any real divisor
    const INF = maxVal + 1;
    const minDiv = new Int32Array(maxVal + 1).fill(INF);

    // MAIN LOGIC: for each present value d, update all its multiples
    for (let d = 1; d <= maxVal; d++) {
        if (!exists[d]) continue;
        for (let m = d; m <= maxVal; m += d) {
            if (exists[m] && d < minDiv[m]) {
                minDiv[m] = d;
            }
        }
    }

    let total = 0;
    for (const v of arr) total += minDiv[v];
    return total;
}

function concatenateArrayWithReverse(arr) {
    const n = arr.length;
    const result = new Array(n * 2);
    for (let i = 0; i < n; i++) {
        result[i] = arr[i];               // copy original elements
    }
    // append the elements in reverse order
    for (let i = 0; i < n; i++) {
        result[n + i] = arr[n - 1 - i];
    }
    return result;
}

function minCostToBuyApples(N, cost, weight) {
    const m = cost.length;
    const maxW = Math.max(...weight);
    const limit = N + maxW;
    const dp = new Array(limit + 1).fill(Infinity);
    dp[0] = 0;
    for (let i = 0; i < limit; i++) {
        if (dp[i] === Infinity) continue;
        for (let j = 0; j < m; j++) {
            const next = Math.min(limit, i + weight[j]);
            if (dp[i] + cost[j] < dp[next]) dp[next] = dp[i] + cost[j];
        }
    }
    let ans = Infinity;
    for (let i = N; i <= limit; i++) ans = Math.min(ans, dp[i]);
    return ans === Infinity ? -1 : ans;
}

