}

function smallestUniqueSubarray(nums) {
    const n = nums.length;
    if (n === 0) return -1;
    const MOD1 = 1000000007n, MOD2 = 1000000009n, BASE = 91138233n, OFFSET = 1000000007n;
    const pow1 = new Array(n + 1).fill(1n), pow2 = new Array(n + 1).fill(1n);
    for (let i = 1; i <= n; i++) { pow1[i] = (pow1[i-1]*BASE)%MOD1; pow2[i] = (pow2[i-1]*BASE)%MOD2; }
    const pref1 = new Array(n + 1).fill(0n), pref2 = new Array(n + 1).fill(0n);
    for (let i = 0; i < n; i++) {
        const val = BigInt(nums[i]) + OFFSET;
        pref1[i+1] = (pref1[i]*BASE + val) % MOD1;
        pref2[i+1] = (pref2[i]*BASE + val) % MOD2;
    }
    function hasUnique(L) {
        const cnt = new Map();
        for (let i = 0; i + L <= n; i++) {
            let h1 = (pref1[i+L] - pref1[i]*pow1[L]) % MOD1; if (h1 < 0n) h1 += MOD1;
            let h2 = (pref2[i+L] - pref2[i]*pow2[L]) % MOD2; if (h2 < 0n) h2 += MOD2;
            const key = h1 + ',' + h2;
            cnt.set(key, (cnt.get(key) || 0) + 1);
        }
        for (const c of cnt.values()) if (c === 1) return true;
        return false;
    }
    let lo = 1, hi = n, answer = -1;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (hasUnique(mid)) { answer = mid; hi = mid - 1; }
        else lo = mid + 1;
    }
    return answer;
}

function countNonAdjacentSubsets(parent, nums, k) {
    const MOD = 1000000007n;
    const n = parent.length;
    const children = Array.from({length: n}, () => []);
    for (let i = 0; i < n; i++) if (parent[i] !== -1) children[parent[i]].push(i);

    // iterative post-order to avoid deep recursion
    const order = [];
    const stack = [0];
    while (stack.length) {
        const u = stack.pop();
        order.push(u);
        for (const v of children[u]) stack.push(v);
    }
    const dpNot = new Array(n), dpSel = new Array(n);
    for (let i = order.length - 1; i >= 0; i--) {
        const u = order[i];
        let dn = new Array(k).fill(0n); dn[0] = 1n;
        let ds = new Array(k).fill(0n); ds[nums[u] % k] = 1n;
        for (const v of children[u]) {
            const cn = dpNot[v], cs = dpSel[v];
            const comb = new Array(k);
            for (let j = 0; j < k; j++) comb[j] = (cn[j] + cs[j]) % MOD;
            const newNot = new Array(k).fill(0n);
            for (let a = 0; a < k; a++) {
                if (dn[a] === 0n) continue;
                for (let b = 0; b < k; b++) {
                    if (comb[b] === 0n) continue;
                    const idx = (a + b) % k;
                    newNot[idx] = (newNot[idx] + dn[a] * comb[b]) % MOD;
                }
            }
            const newSel = new Array(k).fill(0n);
            for (let a = 0; a < k; a++) {
                if (ds[a] === 0n) continue;
                for (let b = 0; b < k; b++) {
                    if (cn[b] === 0n) continue;
                    const idx = (a + b) % k;
                    newSel[idx] = (newSel[idx] + ds[a] * cn[b]) % MOD;
                }
            }
            dn = newNot; ds = newSel;
        }
        dpNot[u] = dn; dpSel[u] = ds;
    }
    return Number((dpNot[0][0] + dpSel[0][0] - 1n + MOD) % MOD);
}

var maxIntersectionSum = function(grid) {
    const m = grid.length, n = grid[0].length;
    let dp = new Map();
    const key = (a, b) => a * 1000 + b;
    for (let r1 = 0; r1 < m; r1++) {
        for (let r2 = 0; r2 < m; r2++) {
            const lo = Math.max(0, r2), hi = Math.min(r1, m - 1);
            let contrib = 0;
            for (let r = lo; r <= hi; r++) contrib += grid[r][0];
            const k = key(r1, r2);
            if (!dp.has(k) || dp.get(k) < contrib) dp.set(k, contrib);
        }
    }
    for (let c = 1; c < n; c++) {
        const ndp = new Map();
        for (const [k, val] of dp) {
            const pr1 = Math.floor(k / 1000), pr2 = k % 1000;
            for (let r1 = pr1; r1 < m; r1++) {
                for (let r2 = 0; r2 <= pr2; r2++) {
                    const lo = Math.max(pr1, r2), hi = Math.min(r1, pr2);
                    let contrib = 0;
                    for (let r = lo; r <= hi; r++) contrib += grid[r][c];
                    const nk = key(r1, r2);
                    const nv = val + contrib;
                    if (!ndp.has(nk) || ndp.get(nk) < nv) ndp.set(nk, nv);
                }
            }
        }
        dp = ndp;
    }
    const finalKey = key(m - 1, 0);
    return dp.has(finalKey) ? dp.get(finalKey) : 0;
};

function countLocalMaximums(matrix) {
    const n = matrix.length, m = matrix[0].length;
    let count = 0;
    for (let r = 0; r < n; r++) {
        for (let c = 0; c < m; c++) {
            const x = matrix[r][c];
            if (x === 0) continue;
            let isMax = true;
            // the cell's own value x is the neighbourhood radius
            for (let dr = -x; dr <= x && isMax; dr++) {
                for (let dc = -x; dc <= x; dc++) {
                    if (Math.abs(dr) === x && Math.abs(dc) === x) continue; // corner exclusion
                    const rr = r + dr, cc = c + dc;
                    if (rr < 0 || rr >= n || cc < 0 || cc >= m) continue;
                    if (matrix[rr][cc] > x) { isMax = false; break; }
                }
            }
            if (isMax) count++;
        }
    }
    return count;
}

