function minOperations(nums, k) {
    const n = nums.length;
    const residues = nums.map(v => ((v % k) + k) % k);
    let best = Infinity;
    for (let x = 0; x < k; x++) {
        for (let y = 0; y < k; y++) {
            if (x === y) continue;
            let cost = 0;
            for (let i = 0; i < n; i++) {
                const target = (i % 2 === 0) ? x : y;
                const diff = Math.abs(residues[i] - target);
                cost += Math.min(diff, k - diff);
            }
            if (cost < best) best = cost;
        }
    }
    return best;
}

function limitOccurrences(nums, k) {
