    }
    return nums.slice(0, write);
}

function minOperations(nums) {
    const n = nums.length;
    if (n <= 1) return 0;
    const p0 = nums.indexOf(0);
    let sourceIsRot = true;
    for (let i = 0; i < n; i++) if (nums[(p0 + i) % n] !== i) { sourceIsRot = false; break; }
    const rev = nums.slice().reverse();
    const p0r = rev.indexOf(0);
    let revIsRot = true;
    for (let i = 0; i < n; i++) if (rev[(p0r + i) % n] !== i) { revIsRot = false; break; }
    if (!sourceIsRot && !revIsRot) return -1;
    const dist = [new Array(n).fill(-1), new Array(n).fill(-1)];
    dist[0][0] = 0;
    const queue = [[0, 0]];
    let head = 0;
    while (head < queue.length) {
        const [f, s] = queue[head++];
        const d = dist[f][s];
        const ns = (s + 1) % n;
        if (dist[f][ns] === -1) { dist[f][ns] = d + 1; queue.push([f, ns]); }
        const nf = 1 - f, ns2 = (n - s) % n;
        if (dist[nf][ns2] === -1) { dist[nf][ns2] = d + 1; queue.push([nf, ns2]); }
    }
    let best = Infinity;
    if (sourceIsRot && dist[0][p0] !== -1) best = Math.min(best, dist[0][p0]);
    if (revIsRot && dist[1][p0r] !== -1) best = Math.min(best, dist[1][p0r]);
    return best === Infinity ? -1 : best;
}

function passwordStrength(password) {
    const seen = new Set(password);
