        else if (c >= 'A' && c <= 'Z') ans += 2;
        else if (c >= '0' && c <= '9') ans += 3;
        else if ("!@#$".includes(c)) ans += 5;
    }
    return ans;
}

function maximumSaleItems(items, budget) {
    const f = new Array(budget + 1).fill(0);
    let mn = Infinity;
    for (const [factor, price] of items) {
        mn = Math.min(mn, price);
        let cnt = 0;
        for (const [factor_j] of items) if (factor_j % factor === 0) cnt++;
        for (let j = budget; j >= price; j--) {
            f[j] = Math.max(f[j], f[j - price] + cnt);
        }
    }
    let ans = 0;
    for (let i = 0; i <= budget; i++) {
        ans = Math.max(ans, f[i] + Math.floor((budget - i) / mn));
    }
    return ans;
}

