function digitFrequencyScore(num) {
    // Convert the input to a string to iterate over each digit
    const str = String(num);
    // Frequency array for digits 0‑9
    const freq = Array(10).fill(0);

    // Count how many times each digit appears
    for (let i = 0; i < str.length; i++) {
        const d = str.charCodeAt(i) - 48; // '0' → 48
        if (d >= 0 && d <= 9) freq[d]++;   // ignore non‑digit characters
    }

    // Compute the score: sum of digit * its frequency
    let score = 0;
    for (let d = 0; d < 10; d++) {
        score += d * freq[d];
    }
    return score;
}

function maximumSaleItems(items, budget) {
    const maxF = Math.max(...items.map(x => x[0]));
    const freq = new Array(maxF + 1).fill(0);
    for (const [f] of items) freq[f]++;
    const S = new Array(maxF + 1).fill(0);
    for (let f = 1; f <= maxF; f++) {
        let total = 0;
        for (let m = f; m <= maxF; m += f) total += freq[m];
        S[f] = total;
    }
    const minPrice = Math.min(...items.map(x => x[1]));
    const attractive = [];
    for (const [f, p] of items) {
        const D = S[f] - 1;
        if (p <= 2 * minPrice) attractive.push([p, D]);
    }
    attractive.sort((a, b) => a[0] - b[0]);

    let totalItems = 0;
    let remaining = budget;
    for (const [price, D] of attractive) {
        if (D <= 0 || remaining < price) continue;
        const buy = Math.min(D, Math.floor(remaining / price));
        totalItems += buy * 2;
        remaining -= buy * price;
    }
    totalItems += Math.floor(remaining / minPrice);
    return totalItems;
}

function isPalindrome(num) {
    // negative numbers cannot be palindromes
    if (num < 0) return false;

    let original = num;
    let reversed = 0;

    // reverse the digits of the number
    while (num > 0) {
        reversed = reversed * 10 + (num % 10);
        num = Math.floor(num / 10);
    }

    return reversed === original;
}

function bruteForce(nums) {
  // try all ways to partition (small n) via DP: dp[i] = best (lexicographically max) array for suffix starting at i
  const n = nums.length;
  function mexOf(arr) {
    const s = new Set(arr);
    let m = 0;
    while (s.has(m)) m++;
    return m;
  }
  const memo = new Map();
  function solve(i) {
    if (i === n) return [];
    if (memo.has(i)) return memo.get(i);
    let best = null;
    for (let k = 1; k <= n - i; k++) {
      const m = mexOf(nums.slice(i, i+k));
      const rest = solve(i+k);
      const candidate = [m, ...rest];
      if (best === null || isGreater(candidate, best)) best = candidate;
    }
    memo.set(i, best);
    return best;
  }
  function isGreater(a, b) {
    const len = Math.min(a.length, b.length);
    for (let idx = 0; idx < len; idx++) {
      if (a[idx] !== b[idx]) return a[idx] > b[idx];
    }
    return a.length > b.length;
  }
  return solve(0);
}

function countDigits(num) {
