function isArmstrong(num) {
    if (num < 0) return false;               // negative numbers cannot be Armstrong

    // count digits
    let temp = num;
    let digitCount = 0;
    do {
        digitCount++;
        temp = Math.floor(temp / 10);
    } while (temp > 0);

    // compute the sum of each digit raised to digitCount
    temp = num;
    let sum = 0;
    while (temp > 0) {
        const digit = temp % 10;
        sum += Math.pow(digit, digitCount);
        temp = Math.floor(temp / 10);
    }

    // handle the case num == 0 (loop above never runs)
    if (num === 0) sum = Math.pow(0, digitCount);

    return sum === num;
}

