function maxConsecutiveOnes(nums) {
    let maxStreak = 0;      // longest streak found so far
    let currentStreak = 0;  // streak of consecutive 1's while iterating

    for (let i = 0; i < nums.length; i++) {
        if (nums[i] === 1) {
            currentStreak++;                     // extend current streak
        } else {
            // end of a streak, possibly update max and reset
            if (currentStreak > maxStreak) {
                maxStreak = currentStreak;
            }
            currentStreak = 0;
        }
    }

    // final check in case the array ends with a streak of 1's
    if (currentStreak > maxStreak) {
        maxStreak = currentStreak;
