function longestSubarrayWithSumK(nums, k) {
    let left = 0;          // start of the sliding window
    let currentSum = 0;    // sum of elements inside the window
    let maxLen = 0;        // longest length found

    for (let right = 0; right < nums.length; right++) {
        currentSum += nums[right];               // expand window to the right

        // shrink window while sum exceeds k
        while (currentSum > k && left <= right) {
            currentSum -= nums[left];
            left++;
        }

        // update answer when exact sum is found
        if (currentSum === k) {
            const windowLen = right - left + 1;
            if (windowLen > maxLen) maxLen = windowLen;
        }
    }

    return maxLen;
}

function findMissingNumber(nums) {
