}

function sortColors(nums) {
    let low = 0;               // boundary for 0's
    let mid = 0;               // current element
    let high = nums.length - 1; // boundary for 2's

    // three-way partition (Dutch National Flag)
    while (mid <= high) {
        if (nums[mid] === 0) {
            // swap nums[low] and nums[mid], expand 0 region
            [nums[low], nums[mid]] = [nums[mid], nums[low]];
            low++;
            mid++;
        } else if (nums[mid] === 1) {
            // 1 is in correct place
            mid++;
        } else { // nums[mid] === 2
            // swap nums[mid] and nums[high], shrink 2 region
            [nums[mid], nums[high]] = [nums[high], nums[mid]];
            high--;
        }
    }
}

function majorityElement(nums) {
    let candidate = null;
    let count = 0;
    for (let i = 0; i < nums.length; i++) {
        // Boyer‑Moore voting: pick or adjust the candidate
        if (count === 0) {
            candidate = nums[i];
            count = 1;
        } else if (nums[i] === candidate) {
            count++;
        } else {
            count--;
        }
    }
    return candidate;
}

function areAnagrams(str1, str2) {
    // quick reject if lengths differ
    if (str1.length !== str2.length) return false;

    const charCount = {};

    // count characters in first string
    for (let i = 0; i < str1.length; i++) {
        const ch = str1[i];
        charCount[ch] = (charCount[ch] || 0) + 1;
    }

    // subtract counts using second string
    for (let i = 0; i < str2.length; i++) {
        const ch = str2[i];
        if (!charCount[ch]) return false; // missing or excess
        charCount[ch]--;
    }

    // all counts should be zero; no need to check explicitly
    return true;
}

function middleNode(head) {
    let slow = head;
    let fast = head;
    // advance fast by two steps and slow by one step until fast reaches the end
    while (fast && fast.next) {
        slow = slow.next;
        fast = fast.next.next;
    }
    return slow;
}

function hasCycle(head) {
    // Use two pointers moving at different speeds
    let slow = head;
    let fast = head;

    while (fast !== null && fast.next !== null) {
        slow = slow.next;          // move one step
        fast = fast.next.next;     // move two steps

        if (slow === fast) {
            return true;           // pointers met → cycle exists
        }
    }

    return false;                  // fast reached the end → no cycle
}

function removeNthFromEnd(head, n) {
    var dummy = { next: head };
    var first = dummy;
    var second = dummy;

    // move first n+1 steps ahead to keep a gap of n between first and second
    for (var i = 0; i <= n; i++) {
        first = first.next;
    }

    // advance both pointers until first reaches the end
    while (first) {
        first = first.next;
        second = second.next;
    }

    // remove the nth node from the end
    second.next = second.next.next;

    return dummy.next;
}

function twoSum(nums, target) {
    const indexMap = new Map();               // store value -> index

    for (let i = 0; i < nums.length; i++) {
        const complement = target - nums[i];  // value needed to reach target
        if (indexMap.has(complement)) {       // check if complement already seen
            return [indexMap.get(complement), i];
        }
        indexMap.set(nums[i], i);             // store current value and index
    }
    return []; // no solution found
}

function myPow(x, n) {
    if (n === 0) return 1;                     // base case
    if (n < 0) {                               // handle negative exponent
        x = 1 / x;
        n = -n;
    }
    const half = myPow(x, Math.floor(n / 2));  // compute x^(n/2) recursively
    if (n % 2 === 0) {
        return half * half;                    // even exponent
    } else {
        return half * half * x;                // odd exponent
    }
}

function kthSmallest(matrix, k) {
    const n = matrix.length;
    let low = matrix[0][0];
    let high = matrix[n - 1][n - 1];

    // binary search on the value range
    while (low < high) {
        const mid = Math.floor((low + high) / 2);
        let count = 0;
        // count how many elements are <= mid
        for (let row = 0; row < n; row++) {
            let col = n - 1;
            while (col >= 0 && matrix[row][col] > mid) col--;
            count += col + 1;
        }
        if (count < k) {
            low = mid + 1;   // kth element is larger
        } else {
            high = mid;      // kth element is <= mid
        }
    }
    return low;
}

// TIME: O(n log(max-min)) SPACE: O(1)

function preorderTraversal(root) {
    const result = [];
    if (!root) return result;

    const stack = [root];                 // start with the root node
    while (stack.length) {                // process nodes while stack not empty
        const node = stack.pop();          // visit the top node
        result.push(node.val);             // record its value

        // push right first so left is processed next
        if (node.right) stack.push(node.right);
        if (node.left)  stack.push(node.left);
    }
    return result;
}

function kthSmallest(root, k) {
    const stack = [];
    let node = root;

    // Perform iterative inorder traversal until the k‑th element is reached
    while (stack.length > 0 || node !== null) {
        // Go as far left as possible
        while (node !== null) {
            stack.push(node);
            node = node.left;
        }

        node = stack.pop();   // Visit node
        k--;                  // One more smallest element found
        if (k === 0) return node.val; // Return when the k‑th smallest is reached

        node = node.right;    // Move to right subtree
    }

    return null; // k is out of bounds
}

function inorderTraversal(root) {
    const result = [];

    // Recursive inorder traversal
    function traverse(node) {
        if (!node) return;
        traverse(node.left);   // left subtree
        result.push(node.val); // visit node
        traverse(node.right);  // right subtree
    }

    traverse(root);
    return result;
}

function Trie() {
    const root = { children: {}, isEnd: false };   // root of the trie

    return {
        insert(word) {
            let node = root;
            for (const ch of word) {
                // create a new node if the path does not exist
                if (!node.children[ch]) {
                    node.children[ch] = { children: {}, isEnd: false };
                }
                node = node.children[ch];
            }
            node.isEnd = true;                       // mark end of word
        },

        search(word) {
            let node = root;
            for (const ch of word) {
                // if any character is missing, word is not present
                if (!node.children[ch]) return false;
                node = node.children[ch];
            }
            return node.isEnd;                       // true only if exact word ends here
        },

        startsWith(prefix) {
            let node = root;
            for (const ch of prefix) {
                // missing path means no word with given prefix
                if (!node.children[ch]) return false;
                node = node.children[ch];
            }
            return true;                             // all prefix characters found
        }
    };
}

function lowestCommonAncestor(root, p, q) {
    let node = root;
    while (node) {
        // Both targets are in the left subtree
        if (p.val < node.val && q.val < node.val) {
            node = node.left;
        // Both targets are in the right subtree
        } else if (p.val > node.val && q.val > node.val) {
            node = node.right;
        // Split point found – this node is the LCA
        } else {
            return node;
        }
    }
    return null;
}

function isValidBST(root) {
    // helper function checks subtree with value bounds
    function validate(node, lowerBound, upperBound) {
        if (node === null) return true;                     // empty subtree is valid
        if (node.val <= lowerBound || node.val >= upperBound) return false; // BST violation
        // recurse left with updated upper bound, and right with updated lower bound
        return validate(node.left, lowerBound, node.val) && validate(node.right, node.val, upperBound);
    }
    return validate(root, Number.NEGATIVE_INFINITY, Number.POSITIVE_INFINITY);
}

function kthLargestElement(nums, k) {
    // min‑heap implementation
    const heap = [];

    const parent = i => (i - 1) >> 1;
    const left = i => i * 2 + 1;
    const right = i => i * 2 + 2;

    const swap = (i, j) => {
        const tmp = heap[i];
        heap[i] = heap[j];
        heap[j] = tmp;
    };

    const heapifyUp = i => {
        while (i > 0 && heap[parent(i)] > heap[i]) {
            swap(i, parent(i));
            i = parent(i);
        }
    };

    const heapifyDown = i => {
        while (true) {
            let smallest = i;
            const l = left(i), r = right(i);
            if (l < heap.length && heap[l] < heap[smallest]) smallest = l;
            if (r < heap.length && heap[r] < heap[smallest]) smallest = r;
            if (smallest === i) break;
            swap(i, smallest);
            i = smallest;
        }
    };

    const push = val => {
        heap.push(val);
        heapifyUp(heap.length - 1);
    };

    const pop = () => {
        if (heap.length === 1) return heap.pop();
        const top = heap[0];
        heap[0] = heap.pop();
        heapifyDown(0);
        return top;
    };

    const peek = () => heap[0];

    // maintain a min‑heap of size k
    for (let i = 0; i < nums.length; i++) {
        push(nums[i]);
        if (heap.length > k) pop(); // discard smallest when size exceeds k
    }

    return peek(); // kth largest element
}

function countComponents(n, edges) {
    // initialize DSU
    const parent = new Array(n);
    const rank = new Array(n).fill(0);
    for (let i = 0; i < n; i++) parent[i] = i;

    function find(x) {
        // path compression
        if (parent[x] !== x) parent[x] = find(parent[x]);
        return parent[x];
    }

    function union(a, b) {
        const rootA = find(a);
        const rootB = find(b);
        if (rootA === rootB) return false; // already connected
        // union by rank
        if (rank[rootA] < rank[rootB]) {
            parent[rootA] = rootB;
        } else if (rank[rootA] > rank[rootB]) {
            parent[rootB] = rootA;
        } else {
            parent[rootB] = rootA;
            rank[rootA]++;
        }
        return true;
    }

    let components = n;               // start with n isolated nodes
    for (const [u, v] of edges) {     // union each edge and reduce count
        if (union(u, v)) components--;
    }
    return components;
}

// TIME: O(n + m · α(n)) SPACE: O(n)

function rangeSumQuery(nums, queries) {
    const n = nums.length;
    const tree = new Array(4 * n).fill(0);

    // build segment tree
    function build(node, l, r) {
        if (l === r) {
            tree[node] = nums[l];
            return;
        }
        const mid = (l + r) >> 1;
        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    // point update
    function update(node, l, r, idx, val) {
        if (l === r) {
            tree[node] = val;
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx, val);
        else update(node * 2 + 1, mid + 1, r, idx, val);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    // range sum query
    function query(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) return tree[node];
        if (r < ql || l > qr) return 0;
        const mid = (l + r) >> 1;
        return query(node * 2, l, mid, ql, qr) +
               query(node * 2 + 1, mid + 1, r, ql, qr);
    }

    build(1, 0, n - 1);

    const answers = [];
    for (const q of queries) {
        if (q[0] === 'update') {
            const idx = q[1];
            const val = q[2];
            update(1, 0, n - 1, idx, val);
        } else { // 'sum'
            const left = q[1];
            const right = q[2];
            answers.push(query(1, 0, n - 1, left, right));
        }
    }
    return answers;
}

// TIME: O(log n) per update/query  SPACE: O(n)

function bestTimeToBuySellCooldown(prices) {
    if (!prices || prices.length === 0) return 0;

    // cash: max profit when not holding a stock today
    // hold: max profit when holding a stock today
    // prevCash: cash value from two days ago (needed for cooldown)
    let cash = 0;
    let hold = -prices[0];
    let prevCash = 0;

    for (let i = 1; i < prices.length; i++) {
        // transition: sell today or stay idle
        const newCash = Math.max(cash, hold + prices[i]);
        // transition: buy today (after cooldown) or keep holding
        const newHold = Math.max(hold, prevCash - prices[i]);

        prevCash = cash;   // shift window for cooldown
        cash = newCash;
        hold = newHold;
    }
    return cash; // best profit ends with no stock held
}

function findStableMountains(height, threshold) {
    var stableMountains = [];
    for (var i = 1; i < height.length; i++) // iterate through the array starting from the second mountain
        if (height[i - 1] > threshold) // check if the previous mountain's height is greater than the threshold
            stableMountains.push(i); // if it is, add the current mountain's index to the result array
    return stableMountains;
}

function countHouses(n, x, y) {
    const adj = Array.from({ length: n + 1 }, () => []);
    for (let i = 1; i < n; i++) {
        adj[i].push(i + 1);
        adj[i + 1].push(i);
    }
    if (x !== y) {
        adj[x].push(y);
        adj[y].push(x);
    }

    const result = new Array(n).fill(0); // index 0..n-2 => distance 1..n-1

    for (let src = 1; src <= n; src++) {
        const dist = new Array(n + 1).fill(-1);
        dist[src] = 0;
        const queue = [src];
        let head = 0;
        while (head < queue.length) {
            const cur = queue[head++];
            for (const nxt of adj[cur]) {
                if (dist[nxt] === -1) {
                    dist[nxt] = dist[cur] + 1;
                    queue.push(nxt);
                }
            }
        }
        for (let dest = 1; dest <= n; dest++) {
            if (dest === src) continue;
            const d = dist[dest];
            if (d >= 1 && d <= n - 1) result[d - 1]++;
        }
    }
    return result;
}

function minCost(nums) {
    let n = nums.length;
    let minCost = Infinity;
    // iterate over all possible first subarray endings
    for (let i = 0; i < n - 2; i++) {
        // iterate over all possible second subarray endings
        for (let j = i + 1; j < n - 1; j++) {
            // calculate the cost of the current subarray division
            let cost = nums[0] + nums[i + 1] + nums[j + 1];
            // update the minimum cost if the current cost is smaller
            minCost = Math.min(minCost, cost);
        }
    }
    return minCost;
}

function minOperations(nums, k) {
    let xor = 0;
    for (const num of nums) xor ^= num;
    let diff = xor ^ k;
    let count = 0;
    while (diff) { count += diff & 1; diff >>>= 1; }
    return count;
}

var maximumSubarraySum = function(nums, k) {
    let maxSum = -Infinity;
    const n = nums.length;
    const prefixSum = new Array(n+1).fill(0);
    for (let i=0;i<n;i++) prefixSum[i+1] = prefixSum[i]+nums[i];
    for (let i=0;i<n;i++) {
        for (let j=i;j<n;j++) {
            if (Math.abs(nums[i]-nums[j])===k) {
                const cur = prefixSum[j+1]-prefixSum[i];
                if (cur > maxSum) maxSum = cur;
            }
        }
    }
    return maxSum === -Infinity ? 0 : maxSum;
};

function powerfulIntegers(start, finish, limit, s) {
  for (const ch of s) {
    if (Number(ch) > limit) return 0;
  }
  function countUpTo(x) {
    if (x < 0) return 0;
    const t = String(x);
    if (t.length < s.length) return 0;
    const memo = new Map();
    function dfs(pos, lim) {
      if (t.length - pos === s.length) {
        if (lim) return (s <= t.slice(pos)) ? 1 : 0;
        return 1;
      }
      if (!lim && memo.has(pos)) return memo.get(pos);
      let up = lim ? (t.charCodeAt(pos) - 48) : 9;
      up = Math.min(up, limit);
      let ans = 0;
      for (let d = 0; d <= up; d++) {
        ans += dfs(pos + 1, lim && d === (t.charCodeAt(pos) - 48));
      }
      if (!lim) memo.set(pos, ans);
      return ans;
    }
    return dfs(0, true);
  }
  return countUpTo(finish) - countUpTo(start - 1);
}

function minimumKeypresses(word) {
    let frequency = {};
    for (let char of word) { if (!frequency[char]) frequency[char] = 0; frequency[char]++; }
    let sortedFrequencies = Object.values(frequency).sort((a, b) => b - a);
    let result = 0;
    // only 8 keys are usable (2-9), so groups of 8, not 9
    for (let i = 0; i < sortedFrequencies.length; i++) {
        if (i < 8) { result += sortedFrequencies[i]; }
        else if (i < 16) { result += sortedFrequencies[i] * 2; }
        else { result += sortedFrequencies[i] * 3; }
    }
    return result;
}

function beautifulIndices(s, a, b, k) {
    let beautiful = [];
    for (let i = 0; i <= s.length - a.length; i++) // check every substring of s that has the same length as a
        if (s.substring(i, i + a.length) === a) 
            for (let j = 0; j <= s.length - b.length; j++) // check every substring of s that has the same length as b
                if (s.substring(j, j + b.length) === b && Math.abs(i - j) <= k) { // check if the current index i is beautiful
                    beautiful.push(i);
                    break; // break the inner loop to avoid duplicate indices
                }
    return [...new Set(beautiful)].sort((a, b) => a - b); // remove duplicates and sort the indices
}

function maximumSizeAfterRemovals(nums1, nums2) {
    const half = nums1.length / 2;
    const count1 = {}, count2 = {};
    for (const v of nums1) count1[v] = (count1[v] || 0) + 1;
    for (const v of nums2) count2[v] = (count2[v] || 0) + 1;

    const keys1 = Object.keys(count1);
    const keys2 = Object.keys(count2);
    let common = 0;
    for (const k of keys1) if (count2[k] !== undefined) common++;
    const only1 = keys1.length - common;
    const only2 = keys2.length - common;

    const take1 = Math.min(half, only1);
    const take2 = Math.min(half, only2);
    const remainingCap = (half - take1) + (half - take2);
    const takeCommon = Math.min(common, remainingCap);

    return take1 + take2 + takeCommon;
}

function minCost(nums, k, dist) {
    const n = nums.length;
    let best = Infinity;

    function rec(subIdx, start, currentCost, starts) {
        // subIdx: which subarray number (1-indexed) we're about to create, 'start' = its start index
        if (subIdx > 1) starts = starts.concat([start]);
        if (subIdx === k) {
            const cost = currentCost + nums[start];
            if (starts[starts.length - 1] - starts[0] <= dist) {
                best = Math.min(best, cost);
            }
            return;
        }
        for (let end = start; end < n - (k - subIdx); end++) {
            rec(subIdx + 1, end + 1, currentCost + nums[start], starts);
        }
    }
    rec(1, 0, 0, []);
    return best;
}

function minimumDamage(power, damage, health) {
  const n = damage.length;
  const enemies = [];
  for (let i = 0; i < n; i++) {
    const t = Math.ceil(health[i] / power);
    enemies.push([t, damage[i]]);
  }
  // sort by t_i / damage_i ascending -> compare via cross multiplication
  enemies.sort((a, b) => a[0] * b[1] - b[0] * a[1]);
  let total = 0;
  let elapsed = 0;
  for (const [t, dmg] of enemies) {
    elapsed += t;
    total += elapsed * dmg;
  }
  return total;
}

function canSortArray(nums) {
    // Create a copy of the array and sort it
    let sortedNums = nums.slice().sort((a, b) => a - b);

    // Initialize a variable to store the count of set bits for each number
    let setBitsCount = new Array(nums.length);

    // Calculate the count of set bits for each number in the original array
    for (let i = 0; i < nums.length; i++) {
        // Count the number of set bits in the binary representation of the number
        setBitsCount[i] = countSetBits(nums[i]);
    }

    // Initialize a variable to store the count of set bits for each number in the sorted array
    let sortedSetBitsCount = new Array(nums.length);

    // Calculate the count of set bits for each number in the sorted array
    for (let i = 0; i < nums.length; i++) {
        // Count the number of set bits in the binary representation of the number
        sortedSetBitsCount[i] = countSetBits(sortedNums[i]);
    }

    // Check if the array can be sorted by comparing the count of set bits for each number
    for (let i = 0; i < nums.length; i++) {
        // If the count of set bits for the current number in the original array is different from the count of set bits for the current number in the sorted array, return false
        if (setBitsCount[i] !== sortedSetBitsCount[i]) {
            return false;
        }
    }

    // If the function has not returned false, return true
    return true;
}

// Helper function to count the number of set bits in the binary representation of a number
function countSetBits(num) {
    let count = 0;
    while (num) {
        // If the least significant bit is 1, increment the count
        count += num & 1;
        // Right shift the number by 1 bit
        num >>= 1;
    }
    return count;
}

// LC 3066. Minimum Operations to Exceed Threshold Value II
// Fills BOTH js_algo_missing and js_optimal_missing (same slug appears in both lists).
// Verified against both official examples in this repo's handoff notes.

// algo: sorted-array simulation, re-sorting after every merge (O(n^2 log n)).
function minOperationsAlgo(nums, k) {
  const arr = [...nums].sort((a, b) => a - b);
  let ops = 0;
  while (arr.length > 1 && arr[0] < k) {
    const x = arr.shift(), y = arr.shift();
    const merged = Math.min(x, y) * 2 + Math.max(x, y);
    // Re-insert in sorted position.
    let i = 0;
    while (i < arr.length && arr[i] < merged) i++;
    arr.splice(i, 0, merged);
    ops++;
  }
  return ops;
}

// optimal: binary min-heap, O(n log n).
function minOperationsOptimal(nums, k) {
  const heap = [...nums];
  const less = (a, b) => heap[a] < heap[b];
  const swap = (a, b) => { const t = heap[a]; heap[a] = heap[b]; heap[b] = t; };
  const siftDown = (i) => {
    const n = heap.length;
    while (true) {
      let smallest = i, l = 2 * i + 1, r = 2 * i + 2;
      if (l < n && less(l, smallest)) smallest = l;
      if (r < n && less(r, smallest)) smallest = r;
      if (smallest === i) break;
      swap(i, smallest); i = smallest;
    }
  };
  const siftUp = (i) => {
    while (i > 0) { const p = (i - 1) >> 1; if (!less(i, p)) break; swap(i, p); i = p; }
  };
  for (let i = (heap.length >> 1) - 1; i >= 0; i--) siftDown(i);
  const pop = () => { const top = heap[0]; heap[0] = heap[heap.length - 1]; heap.pop(); siftDown(0); return top; };
  const push = (v) => { heap.push(v); siftUp(heap.length - 1); };

  let ops = 0;
  while (heap.length > 1 && heap[0] < k) {
    const x = pop(), y = pop();
    push(Math.min(x, y) * 2 + Math.max(x, y));
    ops++;
  }
  return ops;
}

module.exports = { minOperationsAlgo, minOperationsOptimal };

// LC 3354. Make Array Elements Equal to Zero (Easy, n <= 100)
// Fills js_algo_missing.
function countValidSelections(nums) {
  const n = nums.length;
  let count = 0;
  // Try every zero as a starting position, in both directions.
  for (let start = 0; start < n; start++) {
    if (nums[start] !== 0) continue;
    for (const dir of [1, -1]) {
      const arr = nums.slice();
      let curr = start, direction = dir;
      while (curr >= 0 && curr < n) {
        if (arr[curr] === 0) curr += direction;
        else { arr[curr]--; direction = -direction; curr += direction; }
      }
      if (arr.every((v) => v === 0)) count++;
    }
  }
  return count;
}
module.exports = { countValidSelections };

// LC 3499. Maximize Active Section with Trade I (Medium, O(n))
// Fills js_algo_missing.
function maxActiveSectionsAfterTrade(s) {
  const n = s.length;
  let totalOnes = 0, index = 0, prevZero = -Infinity, maxGain = 0;
  // Walk the string by runs of the same character.
  while (index < n) {
    let end = index + 1;
    while (end < n && s[end] === s[index]) end++;
    const len = end - index;
    if (s[index] === '1') totalOnes += len;
    else { maxGain = Math.max(maxGain, prevZero + len); prevZero = len; }
    index = end;
  }
  return totalOnes + maxGain;
}
